INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(1, 1, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', '1:1'),
(2, 1, 2, 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '1:2'),
(3, 1, 3, 'ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', '1:3'),
(4, 1, 4, 'مَـٰلِكِ يَوْمِ ٱلدِّينِ', '1:4'),
(5, 1, 5, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', '1:5'),
(6, 1, 6, 'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', '1:6'),
(7, 1, 7, 'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', '1:7'),
(8, 2, 1, ' الٓمٓ', '2:1'),
(9, 2, 2, 'ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ', '2:2'),
(10, 2, 3, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '2:3'),
(11, 2, 4, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '2:4'),
(12, 2, 5, 'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '2:5'),
(13, 2, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '2:6'),
(14, 2, 7, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', '2:7'),
(15, 2, 8, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ', '2:8'),
(16, 2, 9, 'يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', '2:9'),
(17, 2, 10, 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', '2:10'),
(18, 2, 11, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', '2:11'),
(19, 2, 12, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ', '2:12'),
(20, 2, 13, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ', '2:13'),
(21, 2, 14, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَـٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', '2:14'),
(22, 2, 15, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', '2:15'),
(23, 2, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', '2:16'),
(24, 2, 17, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَـٰتٍ لَّا يُبْصِرُونَ', '2:17'),
(25, 2, 18, 'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ', '2:18'),
(26, 2, 19, 'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ', '2:19'),
(27, 2, 20, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:20'),
(28, 2, 21, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '2:21'),
(29, 2, 22, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', '2:22'),
(30, 2, 23, 'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ', '2:23'),
(31, 2, 24, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَـٰفِرِينَ', '2:24'),
(32, 2, 25, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَـٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَـٰلِدُونَ', '2:25'),
(33, 2, 26, '۞ إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ', '2:26'),
(34, 2, 27, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '2:27'),
(35, 2, 28, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَـٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '2:28'),
(36, 2, 29, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَـٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '2:29'),
(37, 2, 30, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', '2:30'),
(38, 2, 31, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمْ صَـٰدِقِينَ', '2:31'),
(39, 2, 32, 'قَالُوا۟ سُبْحَـٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '2:32'),
(40, 2, 33, 'قَالَ يَـٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', '2:33'),
(41, 2, 34, 'وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ', '2:34'),
(42, 2, 35, 'وَقُلْنَا يَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ', '2:35'),
(43, 2, 36, 'فَأَزَلَّهُمَا ٱلشَّيْطَـٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ', '2:36'),
(44, 2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '2:37'),
(45, 2, 38, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:38'),
(46, 2, 39, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:39'),
(47, 2, 40, 'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّـٰىَ فَٱرْهَبُونِ', '2:40'),
(48, 2, 41, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا وَإِيَّـٰىَ فَٱتَّقُونِ', '2:41'),
(49, 2, 42, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '2:42'),
(50, 2, 43, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', '2:43'),
(51, 2, 44, '۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَـٰبَ ۚ أَفَلَا تَعْقِلُونَ', '2:44'),
(52, 2, 45, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَـٰشِعِينَ', '2:45'),
(53, 2, 46, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', '2:46'),
(54, 2, 47, 'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ', '2:47'),
(55, 2, 48, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَـٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', '2:48'),
(56, 2, 49, 'وَإِذْ نَجَّيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', '2:49'),
(57, 2, 50, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَـٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', '2:50'),
(58, 2, 51, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ', '2:51'),
(59, 2, 52, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', '2:52'),
(60, 2, 53, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', '2:53'),
(61, 2, 54, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '2:54'),
(62, 2, 55, 'وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', '2:55'),
(63, 2, 56, 'ثُمَّ بَعَثْنَـٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '2:56'),
(64, 2, 57, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '2:57'),
(65, 2, 58, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', '2:58'),
(66, 2, 59, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', '2:59'),
(67, 2, 60, '۞ وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '2:60'),
(68, 2, 61, 'وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', '2:61'),
(69, 2, 62, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:62'),
(70, 2, 63, 'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', '2:63'),
(71, 2, 64, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَـٰسِرِينَ', '2:64'),
(72, 2, 65, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ', '2:65'),
(73, 2, 66, 'فَجَعَلْنَـٰهَا نَكَـٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', '2:66'),
(74, 2, 67, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَـٰهِلِينَ', '2:67'),
(75, 2, 68, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', '2:68'),
(76, 2, 69, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّـٰظِرِينَ', '2:69'),
(77, 2, 70, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَـٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', '2:70'),
(78, 2, 71, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٔـٰنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', '2:71'),
(79, 2, 72, 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', '2:72'),
(80, 2, 73, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '2:73'),
(81, 2, 74, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَـٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '2:74'),
(82, 2, 75, '۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', '2:75'),
(83, 2, 76, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ', '2:76'),
(84, 2, 77, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', '2:77'),
(85, 2, 78, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَـٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', '2:78'),
(86, 2, 79, 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَـٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَـٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', '2:79'),
(87, 2, 80, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '2:80'),
(88, 2, 81, 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَـٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:81'),
(89, 2, 82, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:82'),
(90, 2, 83, 'وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', '2:83'),
(91, 2, 84, 'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَـٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', '2:84'),
(92, 2, 85, 'ثُمَّ أَنتُمْ هَـٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَـٰرِهِمْ تَظَـٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَـٰرَىٰ تُفَـٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَـٰبِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '2:85'),
(93, 2, 86, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', '2:86'),
(94, 2, 87, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', '2:87'),
(95, 2, 88, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', '2:88'),
(96, 2, 89, 'وَلَمَّا جَآءَهُمْ كِتَـٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَـٰفِرِينَ', '2:89'),
(97, 2, 90, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ', '2:90'),
(98, 2, 91, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', '2:91'),
(99, 2, 92, '۞ وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَـٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ', '2:92'),
(100, 2, 93, 'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَـٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', '2:93'),
(101, 2, 94, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ', '2:94'),
(102, 2, 95, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', '2:95'),
(103, 2, 96, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '2:96'),
(104, 2, 97, 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', '2:97'),
(105, 2, 98, 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَـٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَـٰفِرِينَ', '2:98'),
(106, 2, 99, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَـٰسِقُونَ', '2:99'),
(107, 2, 100, 'أَوَكُلَّمَا عَـٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', '2:100'),
(108, 2, 101, 'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', '2:101'),
(109, 2, 102, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَـٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَـٰنَ ۖ وَمَا كَفَرَ سُلَيْمَـٰنُ وَلَـٰكِنَّ ٱلشَّيَـٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', '2:102'),
(110, 2, 103, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ', '2:103'),
(111, 2, 104, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ', '2:104'),
(112, 2, 105, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '2:105'),
(113, 2, 106, '۞ مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:106'),
(114, 2, 107, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '2:107'),
(115, 2, 108, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', '2:108'),
(116, 2, 109, 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَـٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:109'),
(117, 2, 110, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '2:110'),
(118, 2, 111, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَـٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ', '2:111'),
(119, 2, 112, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:112'),
(120, 2, 113, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَـٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '2:113'),
(121, 2, 114, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَـٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '2:114'),
(122, 2, 115, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ', '2:115'),
(123, 2, 116, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّ لَّهُۥ قَـٰنِتُونَ', '2:116'),
(124, 2, 117, 'بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '2:117'),
(125, 2, 118, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَـٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْـَٔايَـٰتِ لِقَوْمٍ يُوقِنُونَ', '2:118'),
(126, 2, 119, 'إِنَّآ أَرْسَلْنَـٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَـٰبِ ٱلْجَحِيمِ', '2:119'),
(127, 2, 120, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '2:120'),
(128, 2, 121, 'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '2:121'),
(129, 2, 122, 'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ', '2:122'),
(130, 2, 123, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَـٰعَةٌ وَلَا هُمْ يُنصَرُونَ', '2:123'),
(131, 2, 124, '۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَـٰتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّـٰلِمِينَ', '2:124'),
(132, 2, 125, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَـٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', '2:125'),
(133, 2, 126, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَـٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ', '2:126'),
(134, 2, 127, 'وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَـٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '2:127'),
(135, 2, 128, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '2:128'),
(136, 2, 129, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '2:129'),
(137, 2, 130, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَـٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ', '2:130'),
(138, 2, 131, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَـٰلَمِينَ', '2:131'),
(139, 2, 132, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَـٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '2:132'),
(140, 2, 133, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ إِلَـٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ', '2:133'),
(141, 2, 134, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '2:134'),
(142, 2, 135, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَـٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '2:135'),
(143, 2, 136, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '2:136'),
(144, 2, 137, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '2:137'),
(145, 2, 138, 'صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً ۖ وَنَحْنُ لَهُۥ عَـٰبِدُونَ', '2:138'),
(146, 2, 139, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', '2:139'),
(147, 2, 140, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَـٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '2:140'),
(148, 2, 141, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '2:141'),
(149, 2, 142, '۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا ۚ قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '2:142'),
(150, 2, 143, 'وَكَذَٰلِكَ جَعَلْنَـٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَـٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '2:143'),
(151, 2, 144, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ', '2:144'),
(152, 2, 145, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ ۚ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ ۙ إِنَّكَ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ', '2:145'),
(153, 2, 146, 'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', '2:146'),
(154, 2, 147, 'ٱلْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', '2:147'),
(155, 2, 148, 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:148'),
(156, 2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '2:149'),
(157, 2, 150, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', '2:150'),
(158, 2, 151, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', '2:151'),
(159, 2, 152, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', '2:152'),
(160, 2, 153, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ', '2:153'),
(161, 2, 154, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌ وَلَـٰكِن لَّا تَشْعُرُونَ', '2:154'),
(162, 2, 155, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ', '2:155'),
(163, 2, 156, 'ٱلَّذِينَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', '2:156'),
(164, 2, 157, 'أُو۟لَـٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', '2:157'),
(165, 2, 158, '۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', '2:158'),
(166, 2, 159, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَـٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِى ٱلْكِتَـٰبِ ۙ أُو۟لَـٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّـٰعِنُونَ', '2:159'),
(167, 2, 160, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَـٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', '2:160'),
(168, 2, 161, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَـٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', '2:161'),
(169, 2, 162, 'خَـٰلِدِينَ فِيهَا ۖ لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '2:162'),
(170, 2, 163, 'وَإِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۖ لَّآ إِلَـٰهَ إِلَّا هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ', '2:163'),
(171, 2, 164, 'إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَـٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '2:164'),
(172, 2, 165, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', '2:165'),
(173, 2, 166, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', '2:166'),
(174, 2, 167, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَـٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَـٰرِجِينَ مِنَ ٱلنَّارِ', '2:167'),
(175, 2, 168, 'يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَـٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '2:168'),
(176, 2, 169, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '2:169'),
(177, 2, 170, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', '2:170'),
(178, 2, 171, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً ۚ صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ', '2:171'),
(179, 2, 172, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', '2:172'),
(180, 2, 173, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '2:173'),
(181, 2, 174, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَـٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا ۙ أُو۟لَـٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '2:174'),
(182, 2, 175, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', '2:175'),
(183, 2, 176, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَـٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَـٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ', '2:176'),
(184, 2, 177, '۞ لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَـٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَـٰٓئِكَةِ وَٱلْكِتَـٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَـٰهَدُوا۟ ۖ وَٱلصَّـٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', '2:177'),
(185, 2, 178, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ۖ ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ ۚ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَـٰنٍ ۗ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ ۗ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', '2:178'),
(186, 2, 179, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تَتَّقُونَ', '2:179'),
(187, 2, 180, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', '2:180'),
(188, 2, 181, 'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '2:181'),
(189, 2, 182, 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '2:182'),
(190, 2, 183, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '2:183'),
(191, 2, 184, 'أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', '2:184'),
(192, 2, 185, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَـٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', '2:185'),
(193, 2, 186, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', '2:186'),
(194, 2, 187, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', '2:187'),
(195, 2, 188, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَـٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', '2:188'),
(196, 2, 189, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَـٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '2:189'),
(197, 2, 190, 'وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَـٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '2:190'),
(198, 2, 191, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ ۚ وَلَا تُقَـٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَـٰتِلُوكُمْ فِيهِ ۖ فَإِن قَـٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَـٰفِرِينَ', '2:191'),
(199, 2, 192, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '2:192'),
(200, 2, 193, 'وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ ۖ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ', '2:193'),
(201, 2, 194, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَـٰتُ قِصَاصٌ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '2:194'),
(202, 2, 195, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '2:195'),
(203, 2, 196, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۖ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ۚ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌ كَامِلَةٌ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '2:196'),
(204, 2, 197, 'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَـٰتٌ ۚ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ ۚ وَٱتَّقُونِ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ', '2:197'),
(205, 2, 198, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ ۚ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَـٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ ۖ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', '2:198'),
(206, 2, 199, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '2:199'),
(207, 2, 200, 'فَإِذَا قَضَيْتُم مَّنَـٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ', '2:200'),
(208, 2, 201, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ', '2:201'),
(209, 2, 202, 'أُو۟لَـٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ ۚ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', '2:202'),
(210, 2, 203, '۞ وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ ۚ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ ۚ لِمَنِ ٱتَّقَىٰ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', '2:203'),
(211, 2, 204, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', '2:204'),
(212, 2, 205, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', '2:205'),
(213, 2, 206, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ', '2:206'),
(214, 2, 207, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', '2:207'),
(215, 2, 208, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '2:208'),
(216, 2, 209, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَـٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '2:209'),
(217, 2, 210, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَـٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '2:210'),
(218, 2, 211, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَـٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ ۗ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '2:211'),
(219, 2, 212, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ ۘ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '2:212'),
(220, 2, 213, 'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '2:213'),
(221, 2, 214, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ', '2:214'),
(222, 2, 215, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '2:215'),
(223, 2, 216, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '2:216'),
(224, 2, 217, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ ۖ قُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ ۚ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَـٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَـٰعُوا۟ ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:217'),
(225, 2, 218, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَـٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '2:218'),
(226, 2, 219, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ۖ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَـٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', '2:219'),
(227, 2, 220, 'فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۗ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَـٰمَىٰ ۖ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ ۚ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ ۚ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '2:220'),
(228, 2, 221, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَـٰتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ ۚ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ ۗ أُو۟لَـٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ ۖ وَيُبَيِّنُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '2:221'),
(229, 2, 222, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', '2:222'),
(230, 2, 223, 'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا۟ لِأَنفُسِكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَـٰقُوهُ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '2:223'),
(231, 2, 224, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَـٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '2:224'),
(232, 2, 225, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ', '2:225'),
(233, 2, 226, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '2:226'),
(234, 2, 227, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَـٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '2:227'),
(235, 2, 228, 'وَٱلْمُطَلَّقَـٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَـٰثَةَ قُرُوٓءٍ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَـٰحًا ۚ وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '2:228'),
(236, 2, 229, 'ٱلطَّلَـٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَـٰنٍ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '2:229'),
(237, 2, 230, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ ۗ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', '2:230'),
(238, 2, 231, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ وَلَا تَتَّخِذُوٓا۟ ءَايَـٰتِ ٱللَّهِ هُزُوًا ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَـٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '2:231'),
(239, 2, 232, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '2:232'),
(240, 2, 233, '۞ وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَـٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ ۚ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ ۚ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَـٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '2:233'),
(241, 2, 234, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2:234'),
(242, 2, 235, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ ۚ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَـٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَـٰبُ أَجَلَهُۥ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', '2:235'),
(243, 2, 236, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَـٰعًۢا بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُحْسِنِينَ', '2:236'),
(244, 2, 237, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ ۚ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ ۚ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '2:237'),
(245, 2, 238, 'حَـٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَـٰنِتِينَ', '2:238'),
(246, 2, 239, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا ۖ فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', '2:239'),
(247, 2, 240, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَـٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ ۚ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '2:240'),
(248, 2, 241, 'وَلِلْمُطَلَّقَـٰتِ مَتَـٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', '2:241'),
(249, 2, 242, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '2:242'),
(250, 2, 243, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَـٰهُمْ ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '2:243'),
(251, 2, 244, 'وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '2:244'),
(252, 2, 245, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً ۚ وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', '2:245'),
(253, 2, 246, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَـٰتِلُوا۟ ۖ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَـٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَـٰرِنَا وَأَبْنَآئِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', '2:246'),
(254, 2, 247, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا ۚ قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ ۚ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ ۖ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '2:247'),
(255, 2, 248, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَـٰرُونَ تَحْمِلُهُ ٱلْمَلَـٰٓئِكَةُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '2:248'),
(256, 2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ ۚ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ ۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ ۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ', '2:249'),
(257, 2, 250, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', '2:250'),
(258, 2, 251, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَـٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَـٰلَمِينَ', '2:251'),
(259, 2, 252, 'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۚ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', '2:252'),
(260, 2, 253, '۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَـٰتٍ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ وَلَـٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَـٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '2:253'),
(261, 2, 254, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَـٰعَةٌ ۗ وَٱلْكَـٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ', '2:254'),
(262, 2, 255, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', '2:255'),
(263, 2, 256, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّـٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '2:256'),
(264, 2, 257, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَـٰتِ ۗ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:257'),
(265, 2, 258, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ ۖ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '2:258'),
(266, 2, 259, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَـٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ ۖ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ ۖ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ ۖ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ ۖ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا ۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:259'),
(267, 2, 260, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَـٰكِن لِّيَطْمَئِنَّ قَلْبِى ۖ قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا ۚ وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '2:260'),
(268, 2, 261, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ ۗ وَٱللَّهُ يُضَـٰعِفُ لِمَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '2:261'),
(269, 2, 262, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:262'),
(270, 2, 263, '۞ قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌ', '2:263'),
(271, 2, 264, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَـٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ', '2:264'),
(272, 2, 265, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '2:265'),
(273, 2, 266, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', '2:266'),
(274, 2, 267, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَـٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ ۖ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', '2:267'),
(275, 2, 268, 'ٱلشَّيْطَـٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ ۖ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '2:268'),
(276, 2, 269, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '2:269'),
(277, 2, 270, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ ۗ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ', '2:270'),
(278, 2, 271, 'إِن تُبْدُوا۟ ٱلصَّدَقَـٰتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2:271'),
(279, 2, 272, '۞ لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَـٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ ۚ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ ۚ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', '2:272'),
(280, 2, 273, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَـٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '2:273'),
(281, 2, 274, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:274'),
(282, 2, 275, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَـٰنُ مِنَ ٱلْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ ۗ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ ۚ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ ۖ وَمَنْ عَادَ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '2:275'),
(283, 2, 276, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَـٰتِ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', '2:276'),
(284, 2, 277, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2:277'),
(285, 2, 278, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '2:278'),
(286, 2, 279, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', '2:279'),
(287, 2, 280, 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ ۚ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', '2:280'),
(288, 2, 281, 'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '2:281'),
(289, 2, 282, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا ۚ فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ ۚ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ ۚ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَـٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ ۖ إِلَّآ أَن تَكُونَ تِجَـٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ ۚ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ ۖ وَيُعَلِّمُكُمُ ٱللَّهُ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '2:282'),
(290, 2, 283, '۞ وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَـٰنٌ مَّقْبُوضَةٌ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَـٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ ۗ وَلَا تَكْتُمُوا۟ ٱلشَّهَـٰدَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', '2:283'),
(291, 2, 284, 'لِّلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '2:284'),
(292, 2, 285, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', '2:285'),
(293, 2, 286, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', '2:286'),
(294, 3, 1, ' الٓمٓ', '3:1'),
(295, 3, 2, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', '3:2'),
(296, 3, 3, 'نَزَّلَ عَلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', '3:3'),
(297, 3, 4, 'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', '3:4'),
(298, 3, 5, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', '3:5'),
(299, 3, 6, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '3:6'),
(300, 3, 7, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَـٰبَ مِنْهُ ءَايَـٰتٌ مُّحْكَمَـٰتٌ هُنَّ أُمُّ ٱلْكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتٌ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَـٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '3:7'),
(301, 3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ', '3:8'),
(302, 3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '3:9'),
(303, 3, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', '3:10'),
(304, 3, 11, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', '3:11'),
(305, 3, 12, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ', '3:12'),
(306, 3, 13, 'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌ تُقَـٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَـٰرِ', '3:13'),
(307, 3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَـٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَـٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', '3:14'),
(308, 3, 15, '۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '3:15'),
(309, 3, 16, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', '3:16'),
(310, 3, 17, 'ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلْقَـٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', '3:17'),
(311, 3, 18, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا هُوَ وَٱلْمَلَـٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '3:18'),
(312, 3, 19, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَـٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '3:19'),
(313, 3, 20, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '3:20'),
(314, 3, 21, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '3:21'),
(315, 3, 22, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ', '3:22'),
(316, 3, 23, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يُدْعَوْنَ إِلَىٰ كِتَـٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', '3:23'),
(317, 3, 24, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', '3:24'),
(318, 3, 25, 'فَكَيْفَ إِذَا جَمَعْنَـٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '3:25'),
(319, 3, 26, 'قُلِ ٱللَّهُمَّ مَـٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3:26'),
(320, 3, 27, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ', '3:27'),
(321, 3, 28, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', '3:28'),
(322, 3, 29, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3:29'),
(323, 3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', '3:30'),
(324, 3, 31, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '3:31'),
(325, 3, 32, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَـٰفِرِينَ', '3:32'),
(326, 3, 33, '۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَـٰلَمِينَ', '3:33'),
(327, 3, 34, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '3:34'),
(328, 3, 35, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '3:35'),
(329, 3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَـٰنِ ٱلرَّجِيمِ', '3:36'),
(330, 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا ۖ قَالَ يَـٰمَرْيَمُ أَنَّىٰ لَكِ هَـٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '3:37'),
(331, 3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', '3:38'),
(332, 3, 39, 'فَنَادَتْهُ ٱلْمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّـٰلِحِينَ', '3:39'),
(333, 3, 40, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', '3:40'),
(334, 3, 41, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَةَ أَيَّامٍ إِلَّا رَمْزًا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَـٰرِ', '3:41'),
(335, 3, 42, 'وَإِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَـٰلَمِينَ', '3:42'),
(336, 3, 43, 'يَـٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', '3:43'),
(337, 3, 44, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَـٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', '3:44'),
(338, 3, 45, 'إِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', '3:45'),
(339, 3, 46, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّـٰلِحِينَ', '3:46'),
(340, 3, 47, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '3:47'),
(341, 3, 48, 'وَيُعَلِّمُهُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', '3:48'),
(342, 3, 49, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '3:49'),
(343, 3, 50, 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '3:50'),
(344, 3, 51, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '3:51'),
(345, 3, 52, '۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', '3:52'),
(346, 3, 53, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ', '3:53'),
(347, 3, 54, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ', '3:54'),
(348, 3, 55, 'إِذْ قَالَ ٱللَّهُ يَـٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '3:55'),
(349, 3, 56, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ', '3:56'),
(350, 3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ', '3:57'),
(351, 3, 58, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَـٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', '3:58'),
(352, 3, 59, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', '3:59'),
(353, 3, 60, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', '3:60'),
(354, 3, 61, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَـٰذِبِينَ', '3:61'),
(355, 3, 62, 'إِنَّ هَـٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَـٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '3:62'),
(356, 3, 63, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', '3:63'),
(357, 3, 64, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', '3:64'),
(358, 3, 65, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', '3:65'),
(359, 3, 66, 'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ حَـٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '3:66'),
(360, 3, 67, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَـٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '3:67'),
(361, 3, 68, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَـٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', '3:68'),
(362, 3, 69, 'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', '3:69'),
(363, 3, 70, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', '3:70'),
(364, 3, 71, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '3:71'),
(365, 3, 72, 'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', '3:72'),
(366, 3, 73, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '3:73'),
(367, 3, 74, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '3:74'),
(368, 3, 75, '۞ وَمِنْ أَهْلِ ٱلْكِتَـٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', '3:75'),
(369, 3, 76, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', '3:76'),
(370, 3, 77, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَـٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَـٰٓئِكَ لَا خَلَـٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '3:77'),
(371, 3, 78, 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَـٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَـٰبِ وَمَا هُوَ مِنَ ٱلْكِتَـٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', '3:78'),
(372, 3, 79, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَـٰكِن كُونُوا۟ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَـٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', '3:79'),
(373, 3, 80, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', '3:80'),
(374, 3, 81, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَـٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ', '3:81'),
(375, 3, 82, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', '3:82'),
(376, 3, 83, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', '3:83'),
(377, 3, 84, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '3:84'),
(378, 3, 85, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَـٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ', '3:85'),
(379, 3, 86, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '3:86'),
(380, 3, 87, 'أُو۟لَـٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', '3:87'),
(381, 3, 88, 'خَـٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '3:88'),
(382, 3, 89, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '3:89'),
(383, 3, 90, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ', '3:90'),
(384, 3, 91, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّـٰصِرِينَ', '3:91'),
(385, 3, 92, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '3:92'),
(386, 3, 93, '۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَـٰدِقِينَ', '3:93'),
(387, 3, 94, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '3:94'),
(388, 3, 95, 'قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '3:95'),
(389, 3, 96, 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَـٰلَمِينَ', '3:96'),
(390, 3, 97, 'فِيهِ ءَايَـٰتٌۢ بَيِّنَـٰتٌ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَـٰلَمِينَ', '3:97'),
(391, 3, 98, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', '3:98'),
(392, 3, 99, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '3:99'),
(393, 3, 100, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ يَرُدُّوكُم بَعْدَ إِيمَـٰنِكُمْ كَـٰفِرِينَ', '3:100'),
(394, 3, 101, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '3:101'),
(395, 3, 102, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '3:102'),
(396, 3, 103, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', '3:103'),
(397, 3, 104, 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '3:104'),
(398, 3, 105, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَأُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', '3:105'),
(399, 3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَـٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '3:106'),
(400, 3, 107, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَـٰلِدُونَ', '3:107'),
(401, 3, 108, 'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَـٰلَمِينَ', '3:108'),
(402, 3, 109, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '3:109'),
(403, 3, 110, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَـٰبِ لَكَانَ خَيْرًا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَـٰسِقُونَ', '3:110'),
(404, 3, 111, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًى ۖ وَإِن يُقَـٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', '3:111'),
(405, 3, 112, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', '3:112'),
(406, 3, 113, '۞ لَيْسُوا۟ سَوَآءً ۗ مِّنْ أَهْلِ ٱلْكِتَـٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَـٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', '3:113'),
(407, 3, 114, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَـٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ', '3:114'),
(408, 3, 115, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '3:115'),
(409, 3, 116, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَـٰلِدُونَ', '3:116'),
(410, 3, 117, 'مَثَلُ مَا يُنفِقُونَ فِى هَـٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', '3:117'),
(411, 3, 118, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ', '3:118'),
(412, 3, 119, 'هَـٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَـٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '3:119'),
(413, 3, 120, 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', '3:120'),
(414, 3, 121, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَـٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '3:121'),
(415, 3, 122, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '3:122'),
(416, 3, 123, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', '3:123'),
(417, 3, 124, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَـٰثَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُنزَلِينَ', '3:124'),
(418, 3, 125, 'بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَـٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُسَوِّمِينَ', '3:125'),
(419, 3, 126, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '3:126'),
(420, 3, 127, 'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', '3:127'),
(421, 3, 128, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَـٰلِمُونَ', '3:128'),
(422, 3, 129, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '3:129'),
(423, 3, 130, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَـٰفًا مُّضَـٰعَفَةً ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '3:130'),
(424, 3, 131, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَـٰفِرِينَ', '3:131'),
(425, 3, 132, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '3:132'),
(426, 3, 133, '۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', '3:133'),
(427, 3, 134, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَـٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '3:134'),
(428, 3, 135, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَـٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', '3:135'),
(429, 3, 136, 'أُو۟لَـٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَـٰمِلِينَ', '3:136'),
(430, 3, 137, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ', '3:137'),
(431, 3, 138, 'هَـٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', '3:138'),
(432, 3, 139, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', '3:139'),
(433, 3, 140, 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ', '3:140'),
(434, 3, 141, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَـٰفِرِينَ', '3:141'),
(435, 3, 142, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّـٰبِرِينَ', '3:142'),
(436, 3, 143, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', '3:143'),
(437, 3, 144, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّـٰكِرِينَ', '3:144'),
(438, 3, 145, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَـٰبًا مُّؤَجَّلًا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّـٰكِرِينَ', '3:145'),
(439, 3, 146, 'وَكَأَيِّن مِّن نَّبِىٍّ قَـٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ', '3:146'),
(440, 3, 147, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', '3:147'),
(441, 3, 148, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '3:148'),
(442, 3, 149, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ', '3:149'),
(443, 3, 150, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّـٰصِرِينَ', '3:150'),
(444, 3, 151, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّـٰلِمِينَ', '3:151'),
(445, 3, 152, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', '3:152'),
(446, 3, 153, '۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَـٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَـٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '3:153'),
(447, 3, 154, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ ۖ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَـٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَـٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '3:154'),
(448, 3, 155, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَـٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', '3:155'),
(449, 3, 156, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '3:156'),
(450, 3, 157, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', '3:157'),
(451, 3, 158, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', '3:158'),
(452, 3, 159, 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', '3:159'),
(453, 3, 160, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '3:160'),
(454, 3, 161, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَـٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '3:161'),
(455, 3, 162, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ', '3:162'),
(456, 3, 163, 'هُمْ دَرَجَـٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '3:163'),
(457, 3, 164, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ', '3:164'),
(458, 3, 165, 'أَوَلَمَّآ أَصَـٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَـٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3:165'),
(459, 3, 166, 'وَمَآ أَصَـٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', '3:166'),
(460, 3, 167, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَـٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَـٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', '3:167'),
(461, 3, 168, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ', '3:168'),
(462, 3, 169, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', '3:169'),
(463, 3, 170, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '3:170'),
(464, 3, 171, '۞ يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', '3:171'),
(465, 3, 172, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', '3:172'),
(466, 3, 173, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَـٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', '3:173'),
(467, 3, 174, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', '3:174'),
(468, 3, 175, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَـٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', '3:175'),
(469, 3, 176, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', '3:176'),
(470, 3, 177, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ', '3:177'),
(471, 3, 178, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا ۚ وَلَهُمْ عَذَابٌ مُّهِينٌ', '3:178'),
(472, 3, 179, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَـٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ', '3:179'),
(473, 3, 180, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم ۖ بَلْ هُوَ شَرٌّ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '3:180'),
(474, 3, 181, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '3:181'),
(475, 3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', '3:182'),
(476, 3, 183, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَـٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَـٰدِقِينَ', '3:183'),
(477, 3, 184, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَـٰتِ وَٱلزُّبُرِ وَٱلْكِتَـٰبِ ٱلْمُنِيرِ', '3:184'),
(478, 3, 185, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ', '3:185'),
(479, 3, 186, '۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '3:186'),
(480, 3, 187, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَبِئْسَ مَا يَشْتَرُونَ', '3:187'),
(481, 3, 188, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ', '3:188'),
(482, 3, 189, 'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3:189'),
(483, 3, 190, 'إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلْأَلْبَـٰبِ', '3:190'),
(484, 3, 191, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَـٰطِلًا سُبْحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', '3:191'),
(485, 3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ', '3:192'),
(486, 3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَـٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', '3:193'),
(487, 3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', '3:194'),
(488, 3, 195, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَـٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَـٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', '3:195'),
(489, 3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَـٰدِ', '3:196'),
(490, 3, 197, 'مَتَـٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ', '3:197'),
(491, 3, 198, 'لَـٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ', '3:198'),
(492, 3, 199, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَـٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا ۗ أُو۟لَـٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '3:199'),
(493, 3, 200, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '3:200'),
(494, 4, 1, ' يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا', '4:1'),
(495, 4, 2, 'وَءَاتُوا۟ ٱلْيَتَـٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا', '4:2'),
(496, 4, 3, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَـٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَـٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', '4:3'),
(497, 4, 4, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَـٰتِهِنَّ نِحْلَةً ۚ فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا', '4:4'),
(498, 4, 5, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَـٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', '4:5'),
(499, 4, 6, 'وَٱبْتَلُوا۟ ٱلْيَتَـٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ ۖ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ ۚ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ ۖ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ ۚ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', '4:6'),
(500, 4, 7, 'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ ۚ نَصِيبًا مَّفْرُوضًا', '4:7'),
(501, 4, 8, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', '4:8'),
(502, 4, 9, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَـٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا', '4:9'),
(503, 4, 10, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَـٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا ۖ وَسَيَصْلَوْنَ سَعِيرًا', '4:10'),
(504, 4, 11, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَـٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '4:11'),
(505, 4, 12, '۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ ۚ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ ۗ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَـٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ ۚ وَصِيَّةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌ', '4:12'),
(506, 4, 13, 'تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '4:13'),
(507, 4, 14, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَـٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ', '4:14'),
(508, 4, 15, 'وَٱلَّـٰتِى يَأْتِينَ ٱلْفَـٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ ۖ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا', '4:15'),
(509, 4, 16, 'وَٱلَّذَانِ يَأْتِيَـٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا ۖ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا', '4:16'),
(510, 4, 17, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَـٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '4:17'),
(511, 4, 18, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٔـٰنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَـٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '4:18'),
(512, 4, 19, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا ۖ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ ۚ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا', '4:19'),
(513, 4, 20, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا ۚ أَتَأْخُذُونَهُۥ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا', '4:20'),
(514, 4, 21, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَـٰقًا غَلِيظًا', '4:21'),
(515, 4, 22, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ۚ إِنَّهُۥ كَانَ فَـٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا', '4:22'),
(516, 4, 23, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَـٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّـٰتُكُمْ وَخَـٰلَـٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَـٰتُكُمُ ٱلَّـٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَـٰعَةِ وَأُمَّهَـٰتُ نِسَآئِكُمْ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَـٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَـٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ ۗ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '4:23'),
(517, 4, 24, '۞ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَـٰنُكُمْ ۖ كِتَـٰبَ ٱللَّهِ عَلَيْكُمْ ۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ ۚ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '4:24'),
(518, 4, 25, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَـٰتِ ٱلْمُؤْمِنَـٰتِ فَمِن مَّا مَلَكَتْ أَيْمَـٰنُكُم مِّن فَتَيَـٰتِكُمُ ٱلْمُؤْمِنَـٰتِ ۚ وَٱللَّهُ أَعْلَمُ بِإِيمَـٰنِكُم ۚ بَعْضُكُم مِّنۢ بَعْضٍ ۚ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَـٰتٍ غَيْرَ مُسَـٰفِحَـٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ ۚ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَـٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَـٰتِ مِنَ ٱلْعَذَابِ ۚ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ ۚ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '4:25'),
(519, 4, 26, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '4:26'),
(520, 4, 27, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا', '4:27'),
(521, 4, 28, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَـٰنُ ضَعِيفًا', '4:28'),
(522, 4, 29, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَـٰطِلِ إِلَّآ أَن تَكُونَ تِجَـٰرَةً عَن تَرَاضٍ مِّنكُمْ ۚ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ ۚ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا', '4:29'),
(523, 4, 30, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '4:30'),
(524, 4, 31, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', '4:31'),
(525, 4, 32, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ ۚ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ ۖ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ ۚ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', '4:32'),
(526, 4, 33, 'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ ۚ وَٱلَّذِينَ عَقَدَتْ أَيْمَـٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '4:33'),
(527, 4, 34, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ ۚ فَٱلصَّـٰلِحَـٰتُ قَـٰنِتَـٰتٌ حَـٰفِظَـٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ ۚ وَٱلَّـٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا', '4:34'),
(528, 4, 35, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَـٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا', '4:35'),
(529, 4, 36, '۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَـٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', '4:36'),
(530, 4, 37, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا', '4:37'),
(531, 4, 38, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ ۗ وَمَن يَكُنِ ٱلشَّيْطَـٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا', '4:38'),
(532, 4, 39, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ ۚ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', '4:39'),
(533, 4, 40, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ ۖ وَإِن تَكُ حَسَنَةً يُضَـٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', '4:40'),
(534, 4, 41, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدًا', '4:41'),
(535, 4, 42, 'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا', '4:42'),
(536, 4, 43, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَـٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ ۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', '4:43'),
(537, 4, 44, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يَشْتَرُونَ ٱلضَّلَـٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', '4:44'),
(538, 4, 45, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ ۚ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا', '4:45'),
(539, 4, 46, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ ۚ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَـٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '4:46'),
(540, 4, 47, 'يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَـٰبَ ٱلسَّبْتِ ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '4:47'),
(541, 4, 48, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', '4:48'),
(542, 4, 49, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم ۚ بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', '4:49'),
(543, 4, 50, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا', '4:50'),
(544, 4, 51, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَـٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', '4:51'),
(545, 4, 52, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ ۖ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', '4:52'),
(546, 4, 53, 'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', '4:53'),
(547, 4, 54, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۖ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَـٰهُم مُّلْكًا عَظِيمًا', '4:54'),
(548, 4, 55, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ ۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', '4:55'),
(549, 4, 56, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَـٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ ۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا', '4:56'),
(550, 4, 57, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', '4:57'),
(551, 4, 58, '۞ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَـٰنَـٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ ۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا', '4:58'),
(552, 4, 59, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ ۖ فَإِن تَنَـٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '4:59'),
(553, 4, 60, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّـٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَـٰنُ أَن يُضِلَّهُمْ ضَلَـٰلًۢا بَعِيدًا', '4:60'),
(554, 4, 61, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَـٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', '4:61'),
(555, 4, 62, 'فَكَيْفَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَـٰنًا وَتَوْفِيقًا', '4:62'),
(556, 4, 63, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا', '4:63'),
(557, 4, 64, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ ۚ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا', '4:64'),
(558, 4, 65, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا', '4:65'),
(559, 4, 66, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَـٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ ۖ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', '4:66'),
(560, 4, 67, 'وَإِذًا لَّـَٔاتَيْنَـٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا', '4:67'),
(561, 4, 68, 'وَلَهَدَيْنَـٰهُمْ صِرَٰطًا مُّسْتَقِيمًا', '4:68'),
(562, 4, 69, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَ ۚ وَحَسُنَ أُو۟لَـٰٓئِكَ رَفِيقًا', '4:69'),
(563, 4, 70, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًا', '4:70'),
(564, 4, 71, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا', '4:71'),
(565, 4, 72, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَـٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', '4:72'),
(566, 4, 73, 'وَلَئِنْ أَصَـٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَـٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', '4:73'),
(567, 4, 74, '۞ فَلْيُقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۚ وَمَن يُقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', '4:74'),
(568, 4, 75, 'وَمَا لَكُمْ لَا تُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَـٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', '4:75'),
(569, 4, 76, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ وَٱلَّذِينَ كَفَرُوا۟ يُقَـٰتِلُونَ فِى سَبِيلِ ٱلطَّـٰغُوتِ فَقَـٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَـٰنِ ۖ إِنَّ كَيْدَ ٱلشَّيْطَـٰنِ كَانَ ضَعِيفًا', '4:76'),
(570, 4, 77, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً ۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ ۗ قُلْ مَتَـٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْـَٔاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', '4:77'),
(571, 4, 78, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ ۗ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَـٰذِهِۦ مِنْ عِندِ ٱللَّهِ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَـٰذِهِۦ مِنْ عِندِكَ ۚ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ ۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', '4:78'),
(572, 4, 79, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ ۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ ۚ وَأَرْسَلْنَـٰكَ لِلنَّاسِ رَسُولًا ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '4:79'),
(573, 4, 80, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ ۖ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا', '4:80'),
(574, 4, 81, 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ ۖ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ ۖ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '4:81'),
(575, 4, 82, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ ۚ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَـٰفًا كَثِيرًا', '4:82'),
(576, 4, 83, 'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ ۖ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَـٰنَ إِلَّا قَلِيلًا', '4:83'),
(577, 4, 84, 'فَقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ۚ وَحَرِّضِ ٱلْمُؤْمِنِينَ ۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', '4:84'),
(578, 4, 85, 'مَّن يَشْفَعْ شَفَـٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا ۖ وَمَن يَشْفَعْ شَفَـٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا', '4:85'),
(579, 4, 86, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', '4:86'),
(580, 4, 87, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۗ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا', '4:87'),
(581, 4, 88, '۞ فَمَا لَكُمْ فِى ٱلْمُنَـٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', '4:88'),
(582, 4, 89, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً ۖ فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ ۖ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', '4:89'),
(583, 4, 90, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَـٰتِلُوكُمْ أَوْ يُقَـٰتِلُوا۟ قَوْمَهُمْ ۚ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَـٰتَلُوكُمْ ۚ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَـٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', '4:90'),
(584, 4, 91, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا ۚ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ۚ وَأُو۟لَـٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَـٰنًا مُّبِينًا', '4:91'),
(585, 4, 92, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا ۚ وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ ۚ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '4:92'),
(586, 4, 93, 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَـٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا', '4:93'),
(587, 4, 94, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَـٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '4:94'),
(588, 4, 95, 'لَّا يَسْتَوِى ٱلْقَـٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ فَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَـٰعِدِينَ دَرَجَةً ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَفَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ عَلَى ٱلْقَـٰعِدِينَ أَجْرًا عَظِيمًا', '4:95'),
(589, 4, 96, 'دَرَجَـٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '4:96'),
(590, 4, 97, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ ۖ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ ۚ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا ۚ فَأُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ ۖ وَسَآءَتْ مَصِيرًا', '4:97'),
(591, 4, 98, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', '4:98'),
(592, 4, 99, 'فَأُو۟لَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا', '4:99'),
(593, 4, 100, '۞ وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً ۚ وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '4:100'),
(594, 4, 101, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ ۚ إِنَّ ٱلْكَـٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا', '4:101'),
(595, 4, 102, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ ۖ وَخُذُوا۟ حِذْرَكُمْ ۗ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا', '4:102'),
(596, 4, 103, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَـٰبًا مَّوْقُوتًا', '4:103'),
(597, 4, 104, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ ۖ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ ۖ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '4:104'),
(598, 4, 105, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ ۚ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا', '4:105'),
(599, 4, 106, 'وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '4:106'),
(600, 4, 107, 'وَلَا تُجَـٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', '4:107'),
(601, 4, 108, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', '4:108'),
(602, 4, 109, 'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ جَـٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَـٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَـٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', '4:109'),
(603, 4, 110, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا', '4:110'),
(604, 4, 111, 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '4:111'),
(605, 4, 112, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا', '4:112'),
(606, 4, 113, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِن شَىْءٍ ۚ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ ۚ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا', '4:113'),
(607, 4, 114, '۞ لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَـٰحٍۭ بَيْنَ ٱلنَّاسِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', '4:114'),
(608, 4, 115, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا', '4:115'),
(609, 4, 116, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا', '4:116'),
(610, 4, 117, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَـٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَـٰنًا مَّرِيدًا', '4:117'),
(611, 4, 118, 'لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', '4:118'),
(612, 4, 119, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَـٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ ۚ وَمَن يَتَّخِذِ ٱلشَّيْطَـٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', '4:119'),
(613, 4, 120, 'يَعِدُهُمْ وَيُمَنِّيهِمْ ۖ وَمَا يَعِدُهُمُ ٱلشَّيْطَـٰنُ إِلَّا غُرُورًا', '4:120'),
(614, 4, 121, 'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', '4:121'),
(615, 4, 122, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا', '4:122'),
(616, 4, 123, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَـٰبِ ۗ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', '4:123'),
(617, 4, 124, 'وَمَن يَعْمَلْ مِنَ ٱلصَّـٰلِحَـٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', '4:124'),
(618, 4, 125, 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا', '4:125'),
(619, 4, 126, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا', '4:126'),
(620, 4, 127, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ ۖ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ فِى يَتَـٰمَى ٱلنِّسَآءِ ٱلَّـٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَـٰمَىٰ بِٱلْقِسْطِ ۚ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا', '4:127'),
(621, 4, 128, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا ۚ وَٱلصُّلْحُ خَيْرٌ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '4:128'),
(622, 4, 129, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ ۖ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ ۚ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '4:129'),
(623, 4, 130, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ ۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا', '4:130'),
(624, 4, 131, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا', '4:131'),
(625, 4, 132, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '4:132'),
(626, 4, 133, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ ۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', '4:133'),
(627, 4, 134, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا', '4:134'),
(628, 4, 135, '۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '4:135'),
(629, 4, 136, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا', '4:136'),
(630, 4, 137, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', '4:137'),
(631, 4, 138, 'بَشِّرِ ٱلْمُنَـٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', '4:138'),
(632, 4, 139, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا', '4:139'),
(633, 4, 140, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَـٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ ۚ إِنَّكُمْ إِذًا مِّثْلُهُمْ ۗ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَـٰفِقِينَ وَٱلْكَـٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', '4:140'),
(634, 4, 141, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَـٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَـٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', '4:141'),
(635, 4, 142, 'إِنَّ ٱلْمُنَـٰفِقِينَ يُخَـٰدِعُونَ ٱللَّهَ وَهُوَ خَـٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا', '4:142'),
(636, 4, 143, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', '4:143'),
(637, 4, 144, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَـٰنًا مُّبِينًا', '4:144'),
(638, 4, 145, 'إِنَّ ٱلْمُنَـٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', '4:145'),
(639, 4, 146, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَـٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا', '4:146'),
(640, 4, 147, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ ۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا', '4:147'),
(641, 4, 148, '۞ لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', '4:148'),
(642, 4, 149, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا', '4:149'),
(643, 4, 150, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', '4:150'),
(644, 4, 151, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ حَقًّا ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا', '4:151'),
(645, 4, 152, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَـٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '4:152'),
(646, 4, 153, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَـٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَـٰبًا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّـٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَـٰنًا مُّبِينًا', '4:153'),
(647, 4, 154, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَـٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَـٰقًا غَلِيظًا', '4:154'),
(648, 4, 155, 'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ وَكُفْرِهِم بِـَٔايَـٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ ۚ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '4:155'),
(649, 4, 156, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَـٰنًا عَظِيمًا', '4:156'),
(650, 4, 157, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا', '4:157'),
(651, 4, 158, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '4:158'),
(652, 4, 159, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَـٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', '4:159'),
(653, 4, 160, 'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَـٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا', '4:160'),
(654, 4, 161, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَـٰطِلِ ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', '4:161'),
(655, 4, 162, 'لَّـٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ ۚ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ ۚ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَـٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', '4:162'),
(656, 4, 163, '۞ إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَـٰرُونَ وَسُلَيْمَـٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', '4:163'),
(657, 4, 164, 'وَرُسُلًا قَدْ قَصَصْنَـٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا', '4:164'),
(658, 4, 165, 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '4:165'),
(659, 4, 166, 'لَّـٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ ۖ أَنزَلَهُۥ بِعِلْمِهِۦ ۖ وَٱلْمَلَـٰٓئِكَةُ يَشْهَدُونَ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '4:166'),
(660, 4, 167, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَـٰلًۢا بَعِيدًا', '4:167'),
(661, 4, 168, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', '4:168'),
(662, 4, 169, 'إِلَّا طَرِيقَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '4:169'),
(663, 4, 170, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '4:170'),
(664, 4, 171, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '4:171'),
(665, 4, 172, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَـٰٓئِكَةُ ٱلْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', '4:172'),
(666, 4, 173, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۖ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', '4:173'),
(667, 4, 174, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَـٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا', '4:174'),
(668, 4, 175, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا', '4:175'),
(669, 4, 176, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَـٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '4:176'),
(670, 5, 1, ' يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَـٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', '5:1'),
(671, 5, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '5:2'),
(672, 5, 3, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَـٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَـٰمَ دِينًا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ ۙ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5:3'),
(673, 5, 4, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '5:4'),
(674, 5, 5, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ ۖ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلْمُؤْمِنَـٰتِ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَـٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ', '5:5'),
(675, 5, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَـٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '5:6'),
(676, 5, 7, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَـٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '5:7'),
(677, 5, 8, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '5:8'),
(678, 5, 9, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۙ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '5:9'),
(679, 5, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', '5:10'),
(680, 5, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '5:11'),
(681, 5, 12, '۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', '5:12'),
(682, 5, 13, 'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ لَعَنَّـٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَـٰسِيَةً ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '5:13'),
(683, 5, 14, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰٓ أَخَذْنَا مِيثَـٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', '5:14'),
(684, 5, 15, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَـٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَـٰبٌ مُّبِينٌ', '5:15'),
(685, 5, 16, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '5:16'),
(686, 5, 17, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5:17'),
(687, 5, 18, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَـٰرَىٰ نَحْنُ أَبْنَـٰٓؤُا۟ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', '5:18'),
(688, 5, 19, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ ۖ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5:19'),
(689, 5, 20, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ', '5:20'),
(690, 5, 21, 'يَـٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ', '5:21'),
(691, 5, 22, 'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', '5:22'),
(692, 5, 23, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَـٰلِبُونَ ۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '5:23'),
(693, 5, 24, 'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا ۖ فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَـٰتِلَآ إِنَّا هَـٰهُنَا قَـٰعِدُونَ', '5:24'),
(694, 5, 25, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى ۖ فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَـٰسِقِينَ', '5:25'),
(695, 5, 26, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةً ۛ يَتِيهُونَ فِى ٱلْأَرْضِ ۚ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَـٰسِقِينَ', '5:26'),
(696, 5, 27, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ ۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', '5:27'),
(697, 5, 28, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ', '5:28'),
(698, 5, 29, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَـٰبِ ٱلنَّارِ ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ', '5:29'),
(699, 5, 30, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَـٰسِرِينَ', '5:30'),
(700, 5, 31, 'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ ۚ قَالَ يَـٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَـٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى ۖ فَأَصْبَحَ مِنَ ٱلنَّـٰدِمِينَ', '5:31'),
(701, 5, 32, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَـٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', '5:32'),
(702, 5, 33, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَـٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '5:33'),
(703, 5, 34, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ ۖ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5:34'),
(704, 5, 35, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَـٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', '5:35'),
(705, 5, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَـٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ', '5:36'),
(706, 5, 37, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَـٰرِجِينَ مِنْهَا ۖ وَلَهُمْ عَذَابٌ مُّقِيمٌ', '5:37'),
(707, 5, 38, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَـٰلًا مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '5:38'),
(708, 5, 39, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5:39'),
(709, 5, 40, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5:40'),
(710, 5, 41, '۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّـٰعُونَ لِلْكَذِبِ سَمَّـٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَـٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '5:41'),
(711, 5, 42, 'سَمَّـٰعُونَ لِلْكَذِبِ أَكَّـٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '5:42'),
(712, 5, 43, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَـٰٓئِكَ بِٱلْمُؤْمِنِينَ', '5:43'),
(713, 5, 44, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ', '5:44'),
(714, 5, 45, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ ۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '5:45'),
(715, 5, 46, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', '5:46'),
(716, 5, 47, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', '5:47'),
(717, 5, 48, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَـٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '5:48'),
(718, 5, 49, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ ۖ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَـٰسِقُونَ', '5:49'),
(719, 5, 50, 'أَفَحُكْمَ ٱلْجَـٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', '5:50'),
(720, 5, 51, '۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَـٰرَىٰٓ أَوْلِيَآءَ ۘ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '5:51'),
(721, 5, 52, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَـٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَـٰدِمِينَ', '5:52'),
(722, 5, 53, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَـٰلُهُمْ فَأَصْبَحُوا۟ خَـٰسِرِينَ', '5:53'),
(723, 5, 54, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَـٰفِرِينَ يُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '5:54'),
(724, 5, 55, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', '5:55'),
(725, 5, 56, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَـٰلِبُونَ', '5:56'),
(726, 5, 57, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ ۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '5:57'),
(727, 5, 58, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '5:58'),
(728, 5, 59, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَـٰسِقُونَ', '5:59'),
(729, 5, 60, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ ۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَ ۚ أُو۟لَـٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', '5:60'),
(730, 5, 61, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ ۚ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', '5:61'),
(731, 5, 62, 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَـٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', '5:62'),
(732, 5, 63, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', '5:63'),
(733, 5, 64, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ ۘ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ ۚ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۚ وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ ۚ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا ۚ وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '5:64'),
(734, 5, 65, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَـٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَـٰهُمْ جَنَّـٰتِ ٱلنَّعِيمِ', '5:65'),
(735, 5, 66, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ ۖ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', '5:66'),
(736, 5, 67, '۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ', '5:67'),
(737, 5, 68, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ ۗ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۖ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', '5:68'),
(738, 5, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَـٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '5:69'),
(739, 5, 70, 'لَقَدْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا ۖ كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ', '5:70'),
(740, 5, 71, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '5:71'),
(741, 5, 72, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ', '5:72'),
(742, 5, 73, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةٍ ۘ وَمَا مِنْ إِلَـٰهٍ إِلَّآ إِلَـٰهٌ وَٰحِدٌ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '5:73'),
(743, 5, 74, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '5:74'),
(744, 5, 75, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَـٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', '5:75'),
(745, 5, 76, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا ۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '5:76'),
(746, 5, 77, 'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', '5:77'),
(747, 5, 78, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', '5:78'),
(748, 5, 79, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', '5:79'),
(749, 5, 80, 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ ۚ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَـٰلِدُونَ', '5:80'),
(750, 5, 81, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَـٰكِنَّ كَثِيرًا مِّنْهُمْ فَـٰسِقُونَ', '5:81'),
(751, 5, 82, '۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', '5:82'),
(752, 5, 83, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ ۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ', '5:83'),
(753, 5, 84, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّـٰلِحِينَ', '5:84'),
(754, 5, 85, 'فَأَثَـٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '5:85'),
(755, 5, 86, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', '5:86'),
(756, 5, 87, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَـٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '5:87'),
(757, 5, 88, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '5:88'),
(758, 5, 89, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَـٰنَ ۖ فَكَفَّـٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَـٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ ۚ ذَٰلِكَ كَفَّـٰرَةُ أَيْمَـٰنِكُمْ إِذَا حَلَفْتُمْ ۚ وَٱحْفَظُوٓا۟ أَيْمَـٰنَكُمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', '5:89'),
(759, 5, 90, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَـٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَـٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', '5:90'),
(760, 5, 91, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَـٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ', '5:91'),
(761, 5, 92, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '5:92'),
(762, 5, 93, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '5:93'),
(763, 5, 94, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ ۚ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', '5:94'),
(764, 5, 95, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ ۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَـٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّـٰرَةٌ طَعَامُ مَسَـٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ ۗ عَفَا ٱللَّهُ عَمَّا سَلَفَ ۚ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', '5:95'),
(765, 5, 96, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَـٰعًا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا ۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '5:96'),
(766, 5, 97, '۞ جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَـٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَـٰٓئِدَ ۚ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '5:97'),
(767, 5, 98, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5:98'),
(768, 5, 99, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', '5:99'),
(769, 5, 100, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ ۚ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تُفْلِحُونَ', '5:100'),
(770, 5, 101, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ', '5:101'),
(771, 5, 102, 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَـٰفِرِينَ', '5:102'),
(772, 5, 103, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ ۙ وَلَـٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', '5:103'),
(773, 5, 104, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', '5:104'),
(774, 5, 105, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ ۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '5:105'),
(775, 5, 106, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَـٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَـٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ ۚ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ ۙ وَلَا نَكْتُمُ شَهَـٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ', '5:106'),
(776, 5, 107, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَـٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَـٰدَتُنَآ أَحَقُّ مِن شَهَـٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ', '5:107'),
(777, 5, 108, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَـٰنٌۢ بَعْدَ أَيْمَـٰنِهِمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', '5:108'),
(778, 5, 109, '۞ يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ ۖ قَالُوا۟ لَا عِلْمَ لَنَآ ۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ', '5:109'),
(779, 5, 110, 'إِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا ۖ وَإِذْ عَلَّمْتُكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ۖ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى ۖ وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى ۖ وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى ۖ وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَـٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '5:110'),
(780, 5, 111, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', '5:111'),
(781, 5, 112, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَـٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '5:112'),
(782, 5, 113, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّـٰهِدِينَ', '5:113'),
(783, 5, 114, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', '5:114'),
(784, 5, 115, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ ۖ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ', '5:115'),
(785, 5, 116, 'وَإِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَـٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَـٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ', '5:116'),
(786, 5, 117, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '5:117'),
(787, 5, 118, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '5:118'),
(788, 5, 119, 'قَالَ ٱللَّهُ هَـٰذَا يَوْمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدْقُهُمْ ۚ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '5:119'),
(789, 5, 120, 'لِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ', '5:120'),
(790, 6, 1, ' ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', '6:1'),
(791, 6, 2, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا ۖ وَأَجَلٌ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ', '6:2'),
(792, 6, 3, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', '6:3'),
(793, 6, 4, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '6:4'),
(794, 6, 5, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '6:5'),
(795, 6, 6, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَـٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '6:6'),
(796, 6, 7, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَـٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '6:7'),
(797, 6, 8, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ ۖ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', '6:8'),
(798, 6, 9, 'وَلَوْ جَعَلْنَـٰهُ مَلَكًا لَّجَعَلْنَـٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', '6:9'),
(799, 6, 10, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '6:10'),
(800, 6, 11, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ', '6:11'),
(801, 6, 12, 'قُل لِّمَن مَّا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', '6:12'),
(802, 6, 13, '۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '6:13'),
(803, 6, 14, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '6:14'),
(804, 6, 15, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', '6:15'),
(805, 6, 16, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', '6:16'),
(806, 6, 17, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '6:17'),
(807, 6, 18, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '6:18'),
(808, 6, 19, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَـٰدَةً ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَـٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', '6:19'),
(809, 6, 20, 'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', '6:20'),
(810, 6, 21, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ', '6:21'),
(811, 6, 22, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '6:22'),
(812, 6, 23, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', '6:23'),
(813, 6, 24, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '6:24'),
(814, 6, 25, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَـٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '6:25'),
(815, 6, 26, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', '6:26'),
(816, 6, 27, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَـٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '6:27'),
(817, 6, 28, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَـٰذِبُونَ', '6:28'),
(818, 6, 29, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '6:29'),
(819, 6, 30, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '6:30'),
(820, 6, 31, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَـٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ', '6:31'),
(821, 6, 32, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ ۖ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', '6:32'),
(822, 6, 33, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ', '6:33'),
(823, 6, 34, 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', '6:34'),
(824, 6, 35, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَـٰهِلِينَ', '6:35'),
(825, 6, 36, '۞ إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', '6:36'),
(826, 6, 37, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '6:37'),
(827, 6, 38, 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَـٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَـٰبِ مِن شَىْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', '6:38'),
(828, 6, 39, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَـٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '6:39'),
(829, 6, 40, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَـٰدِقِينَ', '6:40'),
(830, 6, 41, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', '6:41'),
(831, 6, 42, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَـٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', '6:42'),
(832, 6, 43, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ مَا كَانُوا۟ يَعْمَلُونَ', '6:43'),
(833, 6, 44, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَـٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', '6:44'),
(834, 6, 45, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '6:45'),
(835, 6, 46, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَـٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ ثُمَّ هُمْ يَصْدِفُونَ', '6:46'),
(836, 6, 47, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّـٰلِمُونَ', '6:47'),
(837, 6, 48, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '6:48'),
(838, 6, 49, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', '6:49'),
(839, 6, 50, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ', '6:50'),
(840, 6, 51, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', '6:51'),
(841, 6, 52, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ', '6:52'),
(842, 6, 53, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّـٰكِرِينَ', '6:53'),
(843, 6, 54, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَـٰتِنَا فَقُلْ سَلَـٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَـٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ', '6:54'),
(844, 6, 55, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', '6:55'),
(845, 6, 56, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', '6:56'),
(846, 6, 57, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَـٰصِلِينَ', '6:57'),
(847, 6, 58, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّـٰلِمِينَ', '6:58'),
(848, 6, 59, '۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَـٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ', '6:59'),
(849, 6, 60, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '6:60'),
(850, 6, 61, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', '6:61'),
(851, 6, 62, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَـٰسِبِينَ', '6:62'),
(852, 6, 63, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', '6:63'),
(853, 6, 64, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', '6:64'),
(854, 6, 65, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَفْقَهُونَ', '6:65'),
(855, 6, 66, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', '6:66'),
(856, 6, 67, 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ ۚ وَسَوْفَ تَعْلَمُونَ', '6:67'),
(857, 6, 68, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَـٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَـٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '6:68'),
(858, 6, 69, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَـٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', '6:69'),
(859, 6, 70, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', '6:70'),
(860, 6, 71, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَـٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَـٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَـٰلَمِينَ', '6:71'),
(861, 6, 72, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '6:72'),
(862, 6, 73, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '6:73'),
(863, 6, 74, '۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَـٰلٍ مُّبِينٍ', '6:74'),
(864, 6, 75, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', '6:75'),
(865, 6, 76, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا ۖ قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ', '6:76'),
(866, 6, 77, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', '6:77'),
(867, 6, 78, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَـٰذَا رَبِّى هَـٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَـٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', '6:78'),
(868, 6, 79, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '6:79'),
(869, 6, 80, 'وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَـٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ', '6:80'),
(870, 6, 81, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَـٰنًا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ', '6:81'),
(871, 6, 82, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَـٰنَهُم بِظُلْمٍ أُو۟لَـٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', '6:82'),
(872, 6, 83, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَـٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '6:83'),
(873, 6, 84, 'وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَـٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَـٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '6:84'),
(874, 6, 85, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّ مِّنَ ٱلصَّـٰلِحِينَ', '6:85'),
(875, 6, 86, 'وَإِسْمَـٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا ۚ وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَـٰلَمِينَ', '6:86'),
(876, 6, 87, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّـٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَـٰهُمْ وَهَدَيْنَـٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '6:87'),
(877, 6, 88, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', '6:88'),
(878, 6, 89, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَـٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَـٰفِرِينَ', '6:89'),
(879, 6, 90, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَـٰلَمِينَ', '6:90'),
(880, 6, 91, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَـٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', '6:91'),
(881, 6, 92, 'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', '6:92'),
(882, 6, 93, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَـٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَـٰتِهِۦ تَسْتَكْبِرُونَ', '6:93'),
(883, 6, 94, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَـٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَـٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَـٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', '6:94'),
(884, 6, 95, '۞ إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ', '6:95'),
(885, 6, 96, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', '6:96'),
(886, 6, 97, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', '6:97'),
(887, 6, 98, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَفْقَهُونَ', '6:98'),
(888, 6, 99, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّـٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '6:99'),
(889, 6, 100, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَـٰتٍۭ بِغَيْرِ عِلْمٍ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يَصِفُونَ', '6:100'),
(890, 6, 101, 'بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَـٰحِبَةٌ ۖ وَخَلَقَ كُلَّ شَىْءٍ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '6:101'),
(891, 6, 102, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ خَـٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '6:102'),
(892, 6, 103, 'لَّا تُدْرِكُهُ ٱلْأَبْصَـٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَـٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', '6:103'),
(893, 6, 104, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '6:104'),
(894, 6, 105, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ', '6:105'),
(895, 6, 106, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', '6:106'),
(896, 6, 107, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '6:107'),
(897, 6, 108, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '6:108'),
(898, 6, 109, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْـَٔايَـٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', '6:109'),
(899, 6, 110, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَـٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', '6:110'),
(900, 6, 111, '۞ وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَـٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', '6:111'),
(901, 6, 112, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَـٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', '6:112'),
(902, 6, 113, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', '6:113'),
(903, 6, 114, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَـٰبَ مُفَصَّلًا ۚ وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', '6:114'),
(904, 6, 115, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا ۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '6:115'),
(905, 6, 116, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', '6:116'),
(906, 6, 117, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '6:117'),
(907, 6, 118, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَـٰتِهِۦ مُؤْمِنِينَ', '6:118'),
(908, 6, 119, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', '6:119'),
(909, 6, 120, 'وَذَرُوا۟ ظَـٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', '6:120'),
(910, 6, 121, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ ۗ وَإِنَّ ٱلشَّيَـٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَـٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', '6:121'),
(911, 6, 122, 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَـٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَـٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَـٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', '6:122'),
(912, 6, 123, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَـٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', '6:123'),
(913, 6, 124, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', '6:124'),
(914, 6, 125, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَـٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', '6:125'),
(915, 6, 126, 'وَهَـٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَذَّكَّرُونَ', '6:126'),
(916, 6, 127, '۞ لَهُمْ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '6:127'),
(917, 6, 128, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَـٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَـٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '6:128'),
(918, 6, 129, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّـٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', '6:129'),
(919, 6, 130, 'يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ', '6:130'),
(920, 6, 131, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَـٰفِلُونَ', '6:131'),
(921, 6, 132, 'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ', '6:132'),
(922, 6, 133, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', '6:133'),
(923, 6, 134, 'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', '6:134'),
(924, 6, 135, 'قُلْ يَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ', '6:135'),
(925, 6, 136, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَـٰمِ نَصِيبًا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَـٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ', '6:136'),
(926, 6, 137, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَـٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', '6:137'),
(927, 6, 138, 'وَقَالُوا۟ هَـٰذِهِۦٓ أَنْعَـٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَـٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَـٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', '6:138'),
(928, 6, 139, 'وَقَالُوا۟ مَا فِى بُطُونِ هَـٰذِهِ ٱلْأَنْعَـٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', '6:139'),
(929, 6, 140, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَـٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', '6:140'),
(930, 6, 141, '۞ وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّـٰتٍ مَّعْرُوشَـٰتٍ وَغَيْرَ مَعْرُوشَـٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', '6:141'),
(931, 6, 142, 'وَمِنَ ٱلْأَنْعَـٰمِ حَمُولَةً وَفَرْشًا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '6:142'),
(932, 6, 143, 'ثَمَـٰنِيَةَ أَزْوَٰجٍ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ', '6:143'),
(933, 6, 144, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '6:144'),
(934, 6, 145, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', '6:145'),
(935, 6, 146, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ۚ ذَٰلِكَ جَزَيْنَـٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَـٰدِقُونَ', '6:146'),
(936, 6, 147, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '6:147'),
(937, 6, 148, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', '6:148'),
(938, 6, 149, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَـٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '6:149'),
(939, 6, 150, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', '6:150'),
(940, 6, 151, '۞ قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُم مِّنْ إِمْلَـٰقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '6:151'),
(941, 6, 152, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', '6:152'),
(942, 6, 153, 'وَأَنَّ هَـٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', '6:153'),
(943, 6, 154, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', '6:154'),
(944, 6, 155, 'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '6:155'),
(945, 6, 156, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَـٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَـٰفِلِينَ', '6:156'),
(946, 6, 157, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَـٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَـٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَـٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', '6:157'),
(947, 6, 158, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَـٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَـٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَـٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَـٰنِهَا خَيْرًا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '6:158'),
(948, 6, 159, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', '6:159'),
(949, 6, 160, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', '6:160'),
(950, 6, 161, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '6:161'),
(951, 6, 162, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '6:162'),
(952, 6, 163, 'لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', '6:163'),
(953, 6, 164, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '6:164'),
(954, 6, 165, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَـٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَـٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ', '6:165'),
(955, 7, 1, ' الٓمٓصٓ', '7:1'),
(956, 7, 2, 'كِتَـٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', '7:2'),
(957, 7, 3, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًا مَّا تَذَكَّرُونَ', '7:3'),
(958, 7, 4, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَا فَجَآءَهَا بَأْسُنَا بَيَـٰتًا أَوْ هُمْ قَآئِلُونَ', '7:4'),
(959, 7, 5, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَـٰلِمِينَ', '7:5'),
(960, 7, 6, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', '7:6'),
(961, 7, 7, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ ۖ وَمَا كُنَّا غَآئِبِينَ', '7:7'),
(962, 7, 8, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '7:8'),
(963, 7, 9, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَظْلِمُونَ', '7:9'),
(964, 7, 10, 'وَلَقَدْ مَكَّنَّـٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ ۗ قَلِيلًا مَّا تَشْكُرُونَ', '7:10'),
(965, 7, 11, 'وَلَقَدْ خَلَقْنَـٰكُمْ ثُمَّ صَوَّرْنَـٰكُمْ ثُمَّ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّـٰجِدِينَ', '7:11'),
(966, 7, 12, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', '7:12'),
(967, 7, 13, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ', '7:13'),
(968, 7, 14, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '7:14'),
(969, 7, 15, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', '7:15'),
(970, 7, 16, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', '7:16'),
(971, 7, 17, 'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَـٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَـٰكِرِينَ', '7:17'),
(972, 7, 18, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', '7:18'),
(973, 7, 19, 'وَيَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ', '7:19'),
(974, 7, 20, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَـٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَـٰلِدِينَ', '7:20'),
(975, 7, 21, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ', '7:21'),
(976, 7, 22, 'فَدَلَّىٰهُمَا بِغُرُورٍ ۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَـٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ', '7:22'),
(977, 7, 23, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ', '7:23'),
(978, 7, 24, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ', '7:24'),
(979, 7, 25, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', '7:25'),
(980, 7, 26, 'يَـٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', '7:26'),
(981, 7, 27, 'يَـٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَـٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَـٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', '7:27'),
(982, 7, 28, 'وَإِذَا فَعَلُوا۟ فَـٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '7:28'),
(983, 7, 29, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ ۖ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۚ كَمَا بَدَأَكُمْ تَعُودُونَ', '7:29'),
(984, 7, 30, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَـٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَـٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '7:30'),
(985, 7, 31, '۞ يَـٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', '7:31'),
(986, 7, 32, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَـٰتِ مِنَ ٱلرِّزْقِ ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَـٰمَةِ ۗ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', '7:32'),
(987, 7, 33, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '7:33'),
(988, 7, 34, 'وَلِكُلِّ أُمَّةٍ أَجَلٌ ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ', '7:34'),
(989, 7, 35, 'يَـٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى ۙ فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '7:35'),
(990, 7, 36, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '7:36'),
(991, 7, 37, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ أُو۟لَـٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَـٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ', '7:37'),
(992, 7, 38, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ ۖ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا ۖ حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ ۖ قَالَ لِكُلٍّ ضِعْفٌ وَلَـٰكِن لَّا تَعْلَمُونَ', '7:38'),
(993, 7, 39, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', '7:39'),
(994, 7, 40, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', '7:40'),
(995, 7, 41, 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ ۚ وَكَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ', '7:41'),
(996, 7, 42, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '7:42'),
(997, 7, 43, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ ۖ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَـٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ ۖ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ ۖ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', '7:43'),
(998, 7, 44, 'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْجَنَّةِ أَصْحَـٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا ۖ قَالُوا۟ نَعَمْ ۚ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ', '7:44'),
(999, 7, 45, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَـٰفِرُونَ', '7:45'),
(1000, 7, 46, 'وَبَيْنَهُمَا حِجَابٌ ۚ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ ۚ وَنَادَوْا۟ أَصْحَـٰبَ ٱلْجَنَّةِ أَن سَلَـٰمٌ عَلَيْكُمْ ۚ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', '7:46');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(1001, 7, 47, '۞ وَإِذَا صُرِفَتْ أَبْصَـٰرُهُمْ تِلْقَآءَ أَصْحَـٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '7:47'),
(1002, 7, 48, 'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', '7:48'),
(1003, 7, 49, 'أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ۚ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', '7:49'),
(1004, 7, 50, 'وَنَادَىٰٓ أَصْحَـٰبُ ٱلنَّارِ أَصْحَـٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ ۚ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَـٰفِرِينَ', '7:50'),
(1005, 7, 51, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَـٰذَا وَمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ', '7:51'),
(1006, 7, 52, 'وَلَقَدْ جِئْنَـٰهُم بِكِتَـٰبٍ فَصَّلْنَـٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '7:52'),
(1007, 7, 53, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ ۚ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '7:53'),
(1008, 7, 54, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ', '7:54'),
(1009, 7, 55, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '7:55'),
(1010, 7, 56, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ', '7:56'),
(1011, 7, 57, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَـٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', '7:57'),
(1012, 7, 58, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ ۖ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا ۚ كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَشْكُرُونَ', '7:58'),
(1013, 7, 59, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', '7:59'),
(1014, 7, 60, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَـٰلٍ مُّبِينٍ', '7:60'),
(1015, 7, 61, 'قَالَ يَـٰقَوْمِ لَيْسَ بِى ضَلَـٰلَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', '7:61'),
(1016, 7, 62, 'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '7:62'),
(1017, 7, 63, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', '7:63'),
(1018, 7, 64, 'فَكَذَّبُوهُ فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', '7:64'),
(1019, 7, 65, '۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ', '7:65'),
(1020, 7, 66, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَـٰذِبِينَ', '7:66'),
(1021, 7, 67, 'قَالَ يَـٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', '7:67'),
(1022, 7, 68, 'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', '7:68'),
(1023, 7, 69, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ ۚ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', '7:69'),
(1024, 7, 70, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا ۖ فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '7:70'),
(1025, 7, 71, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ ۖ أَتُجَـٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '7:71'),
(1026, 7, 72, 'فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ', '7:72'),
(1027, 7, 73, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', '7:73'),
(1028, 7, 74, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '7:74'),
(1029, 7, 75, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَـٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ ۚ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', '7:75'),
(1030, 7, 76, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَـٰفِرُونَ', '7:76'),
(1031, 7, 77, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَـٰصَـٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', '7:77'),
(1032, 7, 78, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ', '7:78'),
(1033, 7, 79, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَـٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ', '7:79'),
(1034, 7, 80, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَـٰلَمِينَ', '7:80'),
(1035, 7, 81, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '7:81'),
(1036, 7, 82, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', '7:82'),
(1037, 7, 83, 'فَأَنجَيْنَـٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَـٰبِرِينَ', '7:83'),
(1038, 7, 84, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُجْرِمِينَ', '7:84'),
(1039, 7, 85, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '7:85'),
(1040, 7, 86, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا ۚ وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ ۖ وَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ', '7:86'),
(1041, 7, 87, 'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ', '7:87'),
(1042, 7, 88, '۞ قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَـٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۚ قَالَ أَوَلَوْ كُنَّا كَـٰرِهِينَ', '7:88'),
(1043, 7, 89, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا ۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا ۚ عَلَى ٱللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَـٰتِحِينَ', '7:89'),
(1044, 7, 90, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَـٰسِرُونَ', '7:90'),
(1045, 7, 91, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ', '7:91'),
(1046, 7, 92, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ۚ ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَـٰسِرِينَ', '7:92'),
(1047, 7, 93, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَـٰلَـٰتِ رَبِّى وَنَصَحْتُ لَكُمْ ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَـٰفِرِينَ', '7:93'),
(1048, 7, 94, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', '7:94'),
(1049, 7, 95, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَـٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '7:95'),
(1050, 7, 96, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَـٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَـٰكِن كَذَّبُوا۟ فَأَخَذْنَـٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', '7:96'),
(1051, 7, 97, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَـٰتًا وَهُمْ نَآئِمُونَ', '7:97'),
(1052, 7, 98, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', '7:98'),
(1053, 7, 99, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَـٰسِرُونَ', '7:99'),
(1054, 7, 100, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَـٰهُم بِذُنُوبِهِمْ ۚ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', '7:100'),
(1055, 7, 101, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَـٰفِرِينَ', '7:101'),
(1056, 7, 102, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ ۖ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَـٰسِقِينَ', '7:102'),
(1057, 7, 103, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَـٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ', '7:103'),
(1058, 7, 104, 'وَقَالَ مُوسَىٰ يَـٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', '7:104'),
(1059, 7, 105, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', '7:105'),
(1060, 7, 106, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '7:106'),
(1061, 7, 107, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', '7:107'),
(1062, 7, 108, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّـٰظِرِينَ', '7:108'),
(1063, 7, 109, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِيمٌ', '7:109'),
(1064, 7, 110, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ ۖ فَمَاذَا تَأْمُرُونَ', '7:110'),
(1065, 7, 111, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ', '7:111'),
(1066, 7, 112, 'يَأْتُوكَ بِكُلِّ سَـٰحِرٍ عَلِيمٍ', '7:112'),
(1067, 7, 113, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَـٰلِبِينَ', '7:113'),
(1068, 7, 114, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', '7:114'),
(1069, 7, 115, 'قَالُوا۟ يَـٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', '7:115'),
(1070, 7, 116, 'قَالَ أَلْقُوا۟ ۖ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ', '7:116'),
(1071, 7, 117, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', '7:117'),
(1072, 7, 118, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', '7:118'),
(1073, 7, 119, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَـٰغِرِينَ', '7:119'),
(1074, 7, 120, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَـٰجِدِينَ', '7:120'),
(1075, 7, 121, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَـٰلَمِينَ', '7:121'),
(1076, 7, 122, 'رَبِّ مُوسَىٰ وَهَـٰرُونَ', '7:122'),
(1077, 7, 123, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّ هَـٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا ۖ فَسَوْفَ تَعْلَمُونَ', '7:123'),
(1078, 7, 124, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '7:124'),
(1079, 7, 125, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', '7:125'),
(1080, 7, 126, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَـٰتِ رَبِّنَا لَمَّا جَآءَتْنَا ۚ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', '7:126'),
(1081, 7, 127, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَـٰهِرُونَ', '7:127'),
(1082, 7, 128, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ ۖ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَٱلْعَـٰقِبَةُ لِلْمُتَّقِينَ', '7:128'),
(1083, 7, 129, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا ۚ قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', '7:129'),
(1084, 7, 130, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', '7:130'),
(1085, 7, 131, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَـٰذِهِۦ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ ۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '7:131'),
(1086, 7, 132, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', '7:132'),
(1087, 7, 133, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَـٰتٍ مُّفَصَّلَـٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', '7:133'),
(1088, 7, 134, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَـٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ ۖ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', '7:134'),
(1089, 7, 135, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَـٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', '7:135'),
(1090, 7, 136, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَـٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ', '7:136'),
(1091, 7, 137, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَـٰرِقَ ٱلْأَرْضِ وَمَغَـٰرِبَهَا ٱلَّتِى بَـٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', '7:137'),
(1092, 7, 138, 'وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ ۚ قَالُوا۟ يَـٰمُوسَى ٱجْعَل لَّنَآ إِلَـٰهًا كَمَا لَهُمْ ءَالِهَةٌ ۚ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', '7:138'),
(1093, 7, 139, 'إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', '7:139'),
(1094, 7, 140, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَـٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَـٰلَمِينَ', '7:140'),
(1095, 7, 141, 'وَإِذْ أَنجَيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ ۖ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', '7:141'),
(1096, 7, 142, '۞ وَوَٰعَدْنَا مُوسَىٰ ثَلَـٰثِينَ لَيْلَةً وَأَتْمَمْنَـٰهَا بِعَشْرٍ فَتَمَّ مِيقَـٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً ۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَـٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', '7:142'),
(1097, 7, 143, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَـٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَـٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَـٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', '7:143'),
(1098, 7, 144, 'قَالَ يَـٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَـٰلَـٰتِى وَبِكَلَـٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ', '7:144'),
(1099, 7, 145, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا ۚ سَأُو۟رِيكُمْ دَارَ ٱلْفَـٰسِقِينَ', '7:145'),
(1100, 7, 146, 'سَأَصْرِفُ عَنْ ءَايَـٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ', '7:146'),
(1101, 7, 147, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَـٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', '7:147'),
(1102, 7, 148, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ ۚ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَـٰلِمِينَ', '7:148'),
(1103, 7, 149, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ', '7:149'),
(1104, 7, 150, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَـٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ ۖ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ ۖ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ ۚ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '7:150'),
(1105, 7, 151, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ ۖ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', '7:151'),
(1106, 7, 152, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', '7:152'),
(1107, 7, 153, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '7:153'),
(1108, 7, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ ۖ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', '7:154'),
(1109, 7, 155, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَـٰتِنَا ۖ فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّـٰىَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ ۖ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ ۖ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا ۖ وَأَنتَ خَيْرُ ٱلْغَـٰفِرِينَ', '7:155'),
(1110, 7, 156, '۞ وَٱكْتُبْ لَنَا فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَـٰتِنَا يُؤْمِنُونَ', '7:156'),
(1111, 7, 157, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَـٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَـٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَـٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '7:157'),
(1112, 7, 158, 'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَـٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', '7:158'),
(1113, 7, 159, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', '7:159'),
(1114, 7, 160, 'وَقَطَّعْنَـٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا ۚ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۚ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَـٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '7:160'),
(1115, 7, 161, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٔـٰتِكُمْ ۚ سَنَزِيدُ ٱلْمُحْسِنِينَ', '7:161'),
(1116, 7, 162, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', '7:162'),
(1117, 7, 163, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', '7:163'),
(1118, 7, 164, 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا ۖ قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', '7:164'),
(1119, 7, 165, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', '7:165'),
(1120, 7, 166, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ', '7:166'),
(1121, 7, 167, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ', '7:167'),
(1122, 7, 168, 'وَقَطَّعْنَـٰهُمْ فِى ٱلْأَرْضِ أُمَمًا ۖ مِّنْهُمُ ٱلصَّـٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ ۖ وَبَلَوْنَـٰهُم بِٱلْحَسَنَـٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', '7:168'),
(1123, 7, 169, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَـٰبَ يَأْخُذُونَ عَرَضَ هَـٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ ۚ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَـٰقُ ٱلْكِتَـٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ ۗ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', '7:169'),
(1124, 7, 170, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَـٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', '7:170'),
(1125, 7, 171, '۞ وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', '7:171'),
(1126, 7, 172, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ إِنَّا كُنَّا عَنْ هَـٰذَا غَـٰفِلِينَ', '7:172'),
(1127, 7, 173, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', '7:173'),
(1128, 7, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', '7:174'),
(1129, 7, 175, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَـٰهُ ءَايَـٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَـٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', '7:175'),
(1130, 7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَـٰهُ بِهَا وَلَـٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', '7:176'),
(1131, 7, 177, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', '7:177'),
(1132, 7, 178, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى ۖ وَمَن يُضْلِلْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '7:178'),
(1133, 7, 179, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ ۚ أُو۟لَـٰٓئِكَ كَٱلْأَنْعَـٰمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْغَـٰفِلُونَ', '7:179'),
(1134, 7, 180, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَـٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', '7:180'),
(1135, 7, 181, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', '7:181'),
(1136, 7, 182, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', '7:182'),
(1137, 7, 183, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', '7:183'),
(1138, 7, 184, 'أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', '7:184'),
(1139, 7, 185, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', '7:185'),
(1140, 7, 186, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ ۚ وَيَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', '7:186'),
(1141, 7, 187, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '7:187'),
(1142, 7, 188, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ ۚ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', '7:188'),
(1143, 7, 189, '۞ هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا ۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ ۖ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَـٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', '7:189'),
(1144, 7, 190, 'فَلَمَّآ ءَاتَىٰهُمَا صَـٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا ۚ فَتَعَـٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', '7:190'),
(1145, 7, 191, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '7:191'),
(1146, 7, 192, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '7:192'),
(1147, 7, 193, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ ۚ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَـٰمِتُونَ', '7:193'),
(1148, 7, 194, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ ۖ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَـٰدِقِينَ', '7:194'),
(1149, 7, 195, 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ ۖ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ ۖ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ ۖ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا ۗ قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', '7:195'),
(1150, 7, 196, 'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَـٰبَ ۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ', '7:196'),
(1151, 7, 197, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '7:197'),
(1152, 7, 198, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', '7:198'),
(1153, 7, 199, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَـٰهِلِينَ', '7:199'),
(1154, 7, 200, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَـٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ ۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', '7:200'),
(1155, 7, 201, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَـٰٓئِفٌ مِّنَ ٱلشَّيْطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', '7:201'),
(1156, 7, 202, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', '7:202'),
(1157, 7, 203, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا ۚ قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى ۚ هَـٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', '7:203'),
(1158, 7, 204, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '7:204'),
(1159, 7, 205, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَـٰفِلِينَ', '7:205'),
(1160, 7, 206, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ ۩', '7:206'),
(1161, 8, 1, ' يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', '8:1'),
(1162, 8, 2, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَـٰتُهُۥ زَادَتْهُمْ إِيمَـٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '8:2'),
(1163, 8, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '8:3'),
(1164, 8, 4, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُمْ دَرَجَـٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '8:4'),
(1165, 8, 5, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَـٰرِهُونَ', '8:5'),
(1166, 8, 6, 'يُجَـٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', '8:6'),
(1167, 8, 7, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَـٰفِرِينَ', '8:7'),
(1168, 8, 8, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَـٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', '8:8'),
(1169, 8, 9, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُرْدِفِينَ', '8:9'),
(1170, 8, 10, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '8:10'),
(1171, 8, 11, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَـٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', '8:11'),
(1172, 8, 12, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَـٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ', '8:12'),
(1173, 8, 13, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '8:13'),
(1174, 8, 14, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَـٰفِرِينَ عَذَابَ ٱلنَّارِ', '8:14'),
(1175, 8, 15, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', '8:15'),
(1176, 8, 16, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', '8:16'),
(1177, 8, 17, 'فَلَمْ تَقْتُلُوهُمْ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '8:17'),
(1178, 8, 18, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَـٰفِرِينَ', '8:18'),
(1179, 8, 19, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', '8:19'),
(1180, 8, 20, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', '8:20'),
(1181, 8, 21, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', '8:21'),
(1182, 8, 22, '۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', '8:22'),
(1183, 8, 23, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', '8:23'),
(1184, 8, 24, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', '8:24'),
(1185, 8, 25, 'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '8:25'),
(1186, 8, 26, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ لَعَلَّكُمْ تَشْكُرُونَ', '8:26'),
(1187, 8, 27, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَـٰنَـٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', '8:27'),
(1188, 8, 28, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', '8:28'),
(1189, 8, 29, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '8:29'),
(1190, 8, 30, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ', '8:30'),
(1191, 8, 31, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَـٰذَآ ۙ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '8:31'),
(1192, 8, 32, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَـٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ', '8:32'),
(1193, 8, 33, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ ۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', '8:33'),
(1194, 8, 34, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ ۚ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '8:34'),
(1195, 8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً ۚ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '8:35'),
(1196, 8, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ ۗ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', '8:36'),
(1197, 8, 37, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '8:37'),
(1198, 8, 38, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', '8:38'),
(1199, 8, 39, 'وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', '8:39'),
(1200, 8, 40, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ ۚ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', '8:40'),
(1201, 8, 41, '۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '8:41'),
(1202, 8, 42, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ ۚ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَـٰدِ ۙ وَلَـٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ ۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', '8:42'),
(1203, 8, 43, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا ۖ وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَـٰكِنَّ ٱللَّهَ سَلَّمَ ۗ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '8:43'),
(1204, 8, 44, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '8:44'),
(1205, 8, 45, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', '8:45'),
(1206, 8, 46, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَـٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ', '8:46'),
(1207, 8, 47, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۚ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', '8:47'),
(1208, 8, 48, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ ۖ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ ۚ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', '8:48'),
(1209, 8, 49, 'إِذْ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمْ ۗ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '8:49'),
(1210, 8, 50, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ۙ ٱلْمَلَـٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '8:50'),
(1211, 8, 51, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّـٰمٍ لِّلْعَبِيدِ', '8:51'),
(1212, 8, 52, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '8:52'),
(1213, 8, 53, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '8:53'),
(1214, 8, 54, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ ۚ وَكُلٌّ كَانُوا۟ ظَـٰلِمِينَ', '8:54'),
(1215, 8, 55, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', '8:55'),
(1216, 8, 56, 'ٱلَّذِينَ عَـٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', '8:56'),
(1217, 8, 57, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', '8:57'),
(1218, 8, 58, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', '8:58'),
(1219, 8, 59, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ ۚ إِنَّهُمْ لَا يُعْجِزُونَ', '8:59'),
(1220, 8, 60, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', '8:60'),
(1221, 8, 61, '۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '8:61'),
(1222, 8, 62, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ ۚ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', '8:62'),
(1223, 8, 63, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَـٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُۥ عَزِيزٌ حَكِيمٌ', '8:63'),
(1224, 8, 64, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', '8:64'),
(1225, 8, 65, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ ۚ إِن يَكُن مِّنكُمْ عِشْرُونَ صَـٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', '8:65'),
(1226, 8, 66, 'ٱلْـَٔـٰنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا ۚ فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ', '8:66'),
(1227, 8, 67, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ ۚ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '8:67'),
(1228, 8, 68, 'لَّوْلَا كِتَـٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ', '8:68'),
(1229, 8, 69, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '8:69'),
(1230, 8, 70, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '8:70'),
(1231, 8, 71, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '8:71'),
(1232, 8, 72, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَـٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ ۚ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '8:72'),
(1233, 8, 73, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ', '8:73'),
(1234, 8, 74, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '8:74'),
(1235, 8, 75, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ مَعَكُمْ فَأُو۟لَـٰٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَـٰبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '8:75'),
(1236, 9, 1, 'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', '9:1'),
(1237, 9, 2, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَـٰفِرِينَ', '9:2'),
(1238, 9, 3, 'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', '9:3'),
(1239, 9, 4, 'إِلَّا ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَـٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', '9:4'),
(1240, 9, 5, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '9:5'),
(1241, 9, 6, 'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ', '9:6'),
(1242, 9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَـٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَـٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', '9:7'),
(1243, 9, 8, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَـٰسِقُونَ', '9:8'),
(1244, 9, 9, 'ٱشْتَرَوْا۟ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '9:9'),
(1245, 9, 10, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', '9:10'),
(1246, 9, 11, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', '9:11'),
(1247, 9, 12, 'وَإِن نَّكَثُوٓا۟ أَيْمَـٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَـٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَـٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', '9:12'),
(1248, 9, 13, 'أَلَا تُقَـٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَـٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', '9:13'),
(1249, 9, 14, 'قَـٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ', '9:14'),
(1250, 9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '9:15'),
(1251, 9, 16, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '9:16'),
(1252, 9, 17, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَـٰجِدَ ٱللَّهِ شَـٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ ۚ أُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَـٰلِدُونَ', '9:17'),
(1253, 9, 18, 'إِنَّمَا يَعْمُرُ مَسَـٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ ۖ فَعَسَىٰٓ أُو۟لَـٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', '9:18'),
(1254, 9, 19, '۞ أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَـٰهَدَ فِى سَبِيلِ ٱللَّهِ ۚ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '9:19'),
(1255, 9, 20, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', '9:20'),
(1256, 9, 21, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّـٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', '9:21'),
(1257, 9, 22, 'خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', '9:22'),
(1258, 9, 23, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَـٰنِ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '9:23'),
(1259, 9, 24, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَـٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَـٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', '9:24'),
(1260, 9, 25, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', '9:25'),
(1261, 9, 26, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَذَٰلِكَ جَزَآءُ ٱلْكَـٰفِرِينَ', '9:26'),
(1262, 9, 27, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '9:27'),
(1263, 9, 28, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَـٰذَا ۚ وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ ۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ', '9:28'),
(1264, 9, 29, 'قَـٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَـٰغِرُونَ', '9:29'),
(1265, 9, 30, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَـٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ۖ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ ۖ يُضَـٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۚ أَنَّىٰ يُؤْفَكُونَ', '9:30'),
(1266, 9, 31, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَـٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَـٰهًا وَٰحِدًا ۖ لَّآ إِلَـٰهَ إِلَّا هُوَ ۚ سُبْحَـٰنَهُۥ عَمَّا يُشْرِكُونَ', '9:31'),
(1267, 9, 32, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', '9:32'),
(1268, 9, 33, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '9:33'),
(1269, 9, 34, '۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَـٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۗ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '9:34'),
(1270, 9, 35, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ ۖ هَـٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', '9:35'),
(1271, 9, 36, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَـٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَـٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَـٰتِلُونَكُمْ كَآفَّةً ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '9:36'),
(1272, 9, 37, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ ۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ ۚ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَـٰلِهِمْ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ', '9:37'),
(1273, 9, 38, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ ۚ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ ۚ فَمَا مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ', '9:38'),
(1274, 9, 39, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '9:39'),
(1275, 9, 40, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَـٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '9:40'),
(1276, 9, 41, 'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَـٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '9:41'),
(1277, 9, 42, 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَـٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ ۚ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَـٰذِبُونَ', '9:42'),
(1278, 9, 43, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَـٰذِبِينَ', '9:43'),
(1279, 9, 44, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَـٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '9:44'),
(1280, 9, 45, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', '9:45'),
(1281, 9, 46, '۞ وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَـٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَـٰعِدِينَ', '9:46'),
(1282, 9, 47, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَـٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّـٰعُونَ لَهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', '9:47'),
(1283, 9, 48, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَـٰرِهُونَ', '9:48'),
(1284, 9, 49, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ ۚ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ ۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَـٰفِرِينَ', '9:49'),
(1285, 9, 50, 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ ۖ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', '9:50'),
(1286, 9, 51, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '9:51'),
(1287, 9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ ۖ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا ۖ فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', '9:52'),
(1288, 9, 53, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ ۖ إِنَّكُمْ كُنتُمْ قَوْمًا فَـٰسِقِينَ', '9:53'),
(1289, 9, 54, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَـٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَـٰرِهُونَ', '9:54'),
(1290, 9, 55, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَـٰفِرُونَ', '9:55'),
(1291, 9, 56, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَـٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', '9:56'),
(1292, 9, 57, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَـٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', '9:57'),
(1293, 9, 58, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَـٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', '9:58'),
(1294, 9, 59, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', '9:59'),
(1295, 9, 60, '۞ إِنَّمَا ٱلصَّدَقَـٰتُ لِلْفُقَرَآءِ وَٱلْمَسَـٰكِينِ وَٱلْعَـٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَـٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '9:60'),
(1296, 9, 61, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ ۚ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ ۚ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', '9:61'),
(1297, 9, 62, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', '9:62'),
(1298, 9, 63, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدًا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', '9:63'),
(1299, 9, 64, 'يَحْذَرُ ٱلْمُنَـٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ ۚ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', '9:64'),
(1300, 9, 65, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ ۚ قُلْ أَبِٱللَّهِ وَءَايَـٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', '9:65'),
(1301, 9, 66, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَـٰنِكُمْ ۚ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', '9:66'),
(1302, 9, 67, 'ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ بَعْضُهُم مِّنۢ بَعْضٍ ۚ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ ۚ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ ۗ إِنَّ ٱلْمُنَـٰفِقِينَ هُمُ ٱلْفَـٰسِقُونَ', '9:67'),
(1303, 9, 68, 'وَعَدَ ٱللَّهُ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۚ هِىَ حَسْبُهُمْ ۚ وَلَعَنَهُمُ ٱللَّهُ ۖ وَلَهُمْ عَذَابٌ مُّقِيمٌ', '9:68'),
(1304, 9, 69, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَـٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَـٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَـٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَـٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ ۚ أُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '9:69'),
(1305, 9, 70, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَـٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَـٰتِ ۚ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '9:70'),
(1306, 9, 71, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَـٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '9:71'),
(1307, 9, 72, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9:72'),
(1308, 9, 73, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', '9:73'),
(1309, 9, 74, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَـٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ ۚ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ ۚ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ ۖ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '9:74'),
(1310, 9, 75, '۞ وَمِنْهُم مَّنْ عَـٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ', '9:75'),
(1311, 9, 76, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', '9:76'),
(1312, 9, 77, 'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', '9:77'),
(1313, 9, 78, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلْغُيُوبِ', '9:78'),
(1314, 9, 79, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَـٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ ۙ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '9:79'),
(1315, 9, 80, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', '9:80'),
(1316, 9, 81, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَـٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَـٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ ۗ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا ۚ لَّوْ كَانُوا۟ يَفْقَهُونَ', '9:81'),
(1317, 9, 82, 'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', '9:82'),
(1318, 9, 83, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَـٰتِلُوا۟ مَعِىَ عَدُوًّا ۖ إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَـٰلِفِينَ', '9:83'),
(1319, 9, 84, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ ۖ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَـٰسِقُونَ', '9:84'),
(1320, 9, 85, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَـٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَـٰفِرُونَ', '9:85'),
(1321, 9, 86, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَـٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَـٰعِدِينَ', '9:86'),
(1322, 9, 87, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', '9:87'),
(1323, 9, 88, 'لَـٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ وَأُو۟لَـٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '9:88'),
(1324, 9, 89, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9:89'),
(1325, 9, 90, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '9:90'),
(1326, 9, 91, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ ۚ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '9:91'),
(1327, 9, 92, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', '9:92'),
(1328, 9, 93, '۞ إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ ۚ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', '9:93'),
(1329, 9, 94, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ ۚ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ ۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '9:94'),
(1330, 9, 95, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ ۖ فَأَعْرِضُوا۟ عَنْهُمْ ۖ إِنَّهُمْ رِجْسٌ ۖ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', '9:95'),
(1331, 9, 96, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ ۖ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَـٰسِقِينَ', '9:96'),
(1332, 9, 97, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '9:97'),
(1333, 9, 98, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '9:98'),
(1334, 9, 99, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَـٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ ۚ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ ۚ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ ۗ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '9:99'),
(1335, 9, 100, 'وَٱلسَّـٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَـٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَـٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّـٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9:100'),
(1336, 9, 101, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَـٰفِقُونَ ۖ وَمِنْ أَهْلِ ٱلْمَدِينَةِ ۖ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ ۖ نَحْنُ نَعْلَمُهُمْ ۚ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', '9:101'),
(1337, 9, 102, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَـٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '9:102'),
(1338, 9, 103, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '9:103'),
(1339, 9, 104, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَـٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '9:104'),
(1340, 9, 105, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ ۖ وَسَتُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '9:105'),
(1341, 9, 106, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '9:106'),
(1342, 9, 107, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ ۚ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ ۖ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ', '9:107'),
(1343, 9, 108, 'لَا تَقُمْ فِيهِ أَبَدًا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', '9:108'),
(1344, 9, 109, 'أَفَمَنْ أَسَّسَ بُنْيَـٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَـٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '9:109'),
(1345, 9, 110, 'لَا يَزَالُ بُنْيَـٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '9:110'),
(1346, 9, 111, '۞ إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ ۚ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ ۚ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9:111'),
(1347, 9, 112, 'ٱلتَّـٰٓئِبُونَ ٱلْعَـٰبِدُونَ ٱلْحَـٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَـٰفِظُونَ لِحُدُودِ ٱللَّهِ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '9:112'),
(1348, 9, 113, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَـٰبُ ٱلْجَحِيمِ', '9:113'),
(1349, 9, 114, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ ۚ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ', '9:114'),
(1350, 9, 115, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '9:115'),
(1351, 9, 116, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '9:116'),
(1352, 9, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَـٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ ۚ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ', '9:117'),
(1353, 9, 118, 'وَعَلَى ٱلثَّلَـٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '9:118'),
(1354, 9, 119, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّـٰدِقِينَ', '9:119'),
(1355, 9, 120, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ۚ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَـٰلِحٌ ۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '9:120'),
(1356, 9, 121, 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', '9:121'),
(1357, 9, 122, '۞ وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', '9:122'),
(1358, 9, 123, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَـٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '9:123'),
(1359, 9, 124, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَـٰذِهِۦٓ إِيمَـٰنًا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَـٰنًا وَهُمْ يَسْتَبْشِرُونَ', '9:124'),
(1360, 9, 125, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَـٰفِرُونَ', '9:125'),
(1361, 9, 126, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', '9:126'),
(1362, 9, 127, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', '9:127'),
(1363, 9, 128, 'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', '9:128'),
(1364, 9, 129, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', '9:129'),
(1365, 10, 1, ' الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ', '10:1'),
(1366, 10, 2, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرٌ مُّبِينٌ', '10:2'),
(1367, 10, 3, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ', '10:3'),
(1368, 10, 4, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', '10:4'),
(1369, 10, 5, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', '10:5'),
(1370, 10, 6, 'إِنَّ فِى ٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَّقُونَ', '10:6'),
(1371, 10, 7, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَـٰتِنَا غَـٰفِلُونَ', '10:7'),
(1372, 10, 8, 'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', '10:8'),
(1373, 10, 9, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَـٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ فِى جَنَّـٰتِ ٱلنَّعِيمِ', '10:9'),
(1374, 10, 10, 'دَعْوَىٰهُمْ فِيهَا سُبْحَـٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '10:10'),
(1375, 10, 11, '۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', '10:11'),
(1376, 10, 12, 'وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', '10:12'),
(1377, 10, 13, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '10:13'),
(1378, 10, 14, 'ثُمَّ جَعَلْنَـٰكُمْ خَلَـٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', '10:14'),
(1379, 10, 15, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَـٰتٍ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَـٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', '10:15'),
(1380, 10, 16, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', '10:16'),
(1381, 10, 17, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', '10:17'),
(1382, 10, 18, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '10:18'),
(1383, 10, 19, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', '10:19'),
(1384, 10, 20, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '10:20'),
(1385, 10, 21, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا ۚ قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا ۚ إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', '10:21'),
(1386, 10, 22, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', '10:22'),
(1387, 10, 23, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم ۖ مَّتَـٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '10:23'),
(1388, 10, 24, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَـٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَـٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَـٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَـٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَتَفَكَّرُونَ', '10:24'),
(1389, 10, 25, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَـٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '10:25'),
(1390, 10, 26, '۞ لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ ۖ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '10:26'),
(1391, 10, 27, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '10:27'),
(1392, 10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ ۚ فَزَيَّلْنَا بَيْنَهُمْ ۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', '10:28'),
(1393, 10, 29, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَـٰفِلِينَ', '10:29'),
(1394, 10, 30, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '10:30'),
(1395, 10, 31, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ', '10:31'),
(1396, 10, 32, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ ۖ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَـٰلُ ۖ فَأَنَّىٰ تُصْرَفُونَ', '10:32'),
(1397, 10, 33, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', '10:33'),
(1398, 10, 34, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۚ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۖ فَأَنَّىٰ تُؤْفَكُونَ', '10:34'),
(1399, 10, 35, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ ۚ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ ۗ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', '10:35'),
(1400, 10, 36, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا ۚ إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', '10:36'),
(1401, 10, 37, 'وَمَا كَانَ هَـٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَـٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَـٰلَمِينَ', '10:37'),
(1402, 10, 38, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ', '10:38'),
(1403, 10, 39, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِينَ', '10:39'),
(1404, 10, 40, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ ۚ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', '10:40'),
(1405, 10, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', '10:41'),
(1406, 10, 42, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ ۚ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', '10:42'),
(1407, 10, 43, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', '10:43'),
(1408, 10, 44, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَـٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', '10:44'),
(1409, 10, 45, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ ۚ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', '10:45'),
(1410, 10, 46, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', '10:46'),
(1411, 10, 47, 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', '10:47'),
(1412, 10, 48, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '10:48'),
(1413, 10, 49, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ ۗ لِكُلِّ أُمَّةٍ أَجَلٌ ۚ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ', '10:49'),
(1414, 10, 50, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَـٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', '10:50'),
(1415, 10, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ۚ ءَآلْـَٔـٰنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', '10:51'),
(1416, 10, 52, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', '10:52'),
(1417, 10, 53, '۞ وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ ۖ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', '10:53'),
(1418, 10, 54, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ ۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ ۖ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ ۚ وَهُمْ لَا يُظْلَمُونَ', '10:54'),
(1419, 10, 55, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '10:55'),
(1420, 10, 56, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', '10:56'),
(1421, 10, 57, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '10:57'),
(1422, 10, 58, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '10:58'),
(1423, 10, 59, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَـٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ ۖ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', '10:59'),
(1424, 10, 60, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '10:60'),
(1425, 10, 61, 'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ', '10:61'),
(1426, 10, 62, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '10:62'),
(1427, 10, 63, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '10:63'),
(1428, 10, 64, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۚ لَا تَبْدِيلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '10:64'),
(1429, 10, 65, 'وَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا ۚ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '10:65'),
(1430, 10, 66, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ ۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', '10:66'),
(1431, 10, 67, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَسْمَعُونَ', '10:67'),
(1432, 10, 68, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ هُوَ ٱلْغَنِىُّ ۖ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ إِنْ عِندَكُم مِّن سُلْطَـٰنٍۭ بِهَـٰذَآ ۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '10:68'),
(1433, 10, 69, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '10:69'),
(1434, 10, 70, 'مَتَـٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', '10:70'),
(1435, 10, 71, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَـٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَـٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', '10:71'),
(1436, 10, 72, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '10:72'),
(1437, 10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَـٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَـٰهُمْ خَلَـٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُنذَرِينَ', '10:73'),
(1438, 10, 74, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ ۚ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', '10:74'),
(1439, 10, 75, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَـٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَـٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', '10:75'),
(1440, 10, 76, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَـٰذَا لَسِحْرٌ مُّبِينٌ', '10:76'),
(1441, 10, 77, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَـٰذَا وَلَا يُفْلِحُ ٱلسَّـٰحِرُونَ', '10:77'),
(1442, 10, 78, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', '10:78'),
(1443, 10, 79, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَـٰحِرٍ عَلِيمٍ', '10:79'),
(1444, 10, 80, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', '10:80'),
(1445, 10, 81, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ ۖ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ ۖ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', '10:81'),
(1446, 10, 82, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', '10:82'),
(1447, 10, 83, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ ۚ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', '10:83'),
(1448, 10, 84, 'وَقَالَ مُوسَىٰ يَـٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', '10:84'),
(1449, 10, 85, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّـٰلِمِينَ', '10:85'),
(1450, 10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', '10:86'),
(1451, 10, 87, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '10:87'),
(1452, 10, 88, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ ۖ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '10:88'),
(1453, 10, 89, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', '10:89'),
(1454, 10, 90, '۞ وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا ۖ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', '10:90'),
(1455, 10, 91, 'ءَآلْـَٔـٰنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', '10:91'),
(1456, 10, 92, 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً ۚ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَـٰتِنَا لَغَـٰفِلُونَ', '10:92'),
(1457, 10, 93, 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '10:93'),
(1458, 10, 94, 'فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَـٰبَ مِن قَبْلِكَ ۚ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', '10:94'),
(1459, 10, 95, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَـٰسِرِينَ', '10:95'),
(1460, 10, 96, 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', '10:96'),
(1461, 10, 97, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '10:97'),
(1462, 10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَـٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَـٰهُمْ إِلَىٰ حِينٍ', '10:98'),
(1463, 10, 99, 'وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', '10:99'),
(1464, 10, 100, 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', '10:100'),
(1465, 10, 101, 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَا تُغْنِى ٱلْـَٔايَـٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ', '10:101'),
(1466, 10, 102, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ ۚ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '10:102'),
(1467, 10, 103, 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', '10:103'),
(1468, 10, 104, 'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَـٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '10:104'),
(1469, 10, 105, 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '10:105'),
(1470, 10, 106, 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ ۖ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّـٰلِمِينَ', '10:106'),
(1471, 10, 107, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '10:107'),
(1472, 10, 108, 'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ', '10:108'),
(1473, 10, 109, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ', '10:109'),
(1474, 11, 1, ' الٓر ۚ كِتَـٰبٌ أُحْكِمَتْ ءَايَـٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', '11:1'),
(1475, 11, 2, 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۚ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ', '11:2'),
(1476, 11, 3, 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَـٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ ۖ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ', '11:3'),
(1477, 11, 4, 'إِلَى ٱللَّهِ مَرْجِعُكُمْ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '11:4'),
(1478, 11, 5, 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '11:5'),
(1479, 11, 6, '۞ وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّ فِى كِتَـٰبٍ مُّبِينٍ', '11:6'),
(1480, 11, 7, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۗ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '11:7'),
(1481, 11, 8, 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '11:8'),
(1482, 11, 9, 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَـٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَـٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ', '11:9'),
(1483, 11, 10, 'وَلَئِنْ أَذَقْنَـٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌ فَخُورٌ', '11:10'),
(1484, 11, 11, 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '11:11'),
(1485, 11, 12, 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ ۚ إِنَّمَآ أَنتَ نَذِيرٌ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '11:12'),
(1486, 11, 13, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَـٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ', '11:13'),
(1487, 11, 14, 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَـٰهَ إِلَّا هُوَ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', '11:14'),
(1488, 11, 15, 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَـٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', '11:15'),
(1489, 11, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', '11:16'),
(1490, 11, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۚ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ ۚ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ ۚ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', '11:17'),
(1491, 11, 18, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَـٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَـٰدُ هَـٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ', '11:18'),
(1492, 11, 19, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ', '11:19'),
(1493, 11, 20, 'أُو۟لَـٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ۘ يُضَـٰعَفُ لَهُمُ ٱلْعَذَابُ ۚ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', '11:20'),
(1494, 11, 21, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '11:21'),
(1495, 11, 22, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '11:22'),
(1496, 11, 23, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '11:23'),
(1497, 11, 24, '۞ مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ ۚ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ أَفَلَا تَذَكَّرُونَ', '11:24'),
(1498, 11, 25, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', '11:25'),
(1499, 11, 26, 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ', '11:26'),
(1500, 11, 27, 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَـٰذِبِينَ', '11:27'),
(1501, 11, 28, 'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَـٰرِهُونَ', '11:28'),
(1502, 11, 29, 'وَيَـٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ ۚ إِنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَلَـٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', '11:29'),
(1503, 11, 30, 'وَيَـٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ ۚ أَفَلَا تَذَكَّرُونَ', '11:30'),
(1504, 11, 31, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ۖ ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ ۖ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ', '11:31'),
(1505, 11, 32, 'قَالُوا۟ يَـٰنُوحُ قَدْ جَـٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '11:32'),
(1506, 11, 33, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', '11:33'),
(1507, 11, 34, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', '11:34'),
(1508, 11, 35, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ', '11:35'),
(1509, 11, 36, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', '11:36'),
(1510, 11, 37, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَـٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۚ إِنَّهُم مُّغْرَقُونَ', '11:37'),
(1511, 11, 38, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ ۚ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', '11:38'),
(1512, 11, 39, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '11:39'),
(1513, 11, 40, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ ۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ', '11:40'),
(1514, 11, 41, '۞ وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ ۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ', '11:41'),
(1515, 11, 42, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَـٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَـٰفِرِينَ', '11:42'),
(1516, 11, 43, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ ۚ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ ۚ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', '11:43'),
(1517, 11, 44, 'وَقِيلَ يَـٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَـٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ ۖ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّـٰلِمِينَ', '11:44'),
(1518, 11, 45, 'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَـٰكِمِينَ', '11:45'),
(1519, 11, 46, 'قَالَ يَـٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ ۖ إِنَّهُۥ عَمَلٌ غَيْرُ صَـٰلِحٍ ۖ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۖ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَـٰهِلِينَ', '11:46'),
(1520, 11, 47, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ ۖ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَـٰسِرِينَ', '11:47'),
(1521, 11, 48, 'قِيلَ يَـٰنُوحُ ٱهْبِطْ بِسَلَـٰمٍ مِّنَّا وَبَرَكَـٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ ۚ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', '11:48'),
(1522, 11, 49, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ ۖ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَـٰذَا ۖ فَٱصْبِرْ ۖ إِنَّ ٱلْعَـٰقِبَةَ لِلْمُتَّقِينَ', '11:49'),
(1523, 11, 50, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۖ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', '11:50'),
(1524, 11, 51, 'يَـٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ ۚ أَفَلَا تَعْقِلُونَ', '11:51'),
(1525, 11, 52, 'وَيَـٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', '11:52'),
(1526, 11, 53, 'قَالُوا۟ يَـٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', '11:53'),
(1527, 11, 54, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ ۗ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', '11:54'),
(1528, 11, 55, 'مِن دُونِهِۦ ۖ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ', '11:55'),
(1529, 11, 56, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم ۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ ۚ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '11:56'),
(1530, 11, 57, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ ۚ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا ۚ إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', '11:57'),
(1531, 11, 58, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَـٰهُم مِّنْ عَذَابٍ غَلِيظٍ', '11:58'),
(1532, 11, 59, 'وَتِلْكَ عَادٌ ۖ جَحَدُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', '11:59'),
(1533, 11, 60, 'وَأُتْبِعُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَـٰمَةِ ۗ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', '11:60'),
(1534, 11, 61, '۞ وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ', '11:61'),
(1535, 11, 62, 'قَالُوا۟ يَـٰصَـٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَـٰذَآ ۖ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ', '11:62'),
(1536, 11, 63, 'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ ۖ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ', '11:63'),
(1537, 11, 64, 'وَيَـٰقَوْمِ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', '11:64'),
(1538, 11, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَـٰثَةَ أَيَّامٍ ۖ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', '11:65'),
(1539, 11, 66, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَـٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ ۗ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', '11:66'),
(1540, 11, 67, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَـٰرِهِمْ جَـٰثِمِينَ', '11:67'),
(1541, 11, 68, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًا لِّثَمُودَ', '11:68'),
(1542, 11, 69, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَـٰمًا ۖ قَالَ سَلَـٰمٌ ۖ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ', '11:69'),
(1543, 11, 70, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً ۚ قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ', '11:70'),
(1544, 11, 71, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَـٰهَا بِإِسْحَـٰقَ وَمِن وَرَآءِ إِسْحَـٰقَ يَعْقُوبَ', '11:71'),
(1545, 11, 72, 'قَالَتْ يَـٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَـٰذَا بَعْلِى شَيْخًا ۖ إِنَّ هَـٰذَا لَشَىْءٌ عَجِيبٌ', '11:72'),
(1546, 11, 73, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ ۖ رَحْمَتُ ٱللَّهِ وَبَرَكَـٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ ۚ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ', '11:73'),
(1547, 11, 74, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَـٰدِلُنَا فِى قَوْمِ لُوطٍ', '11:74'),
(1548, 11, 75, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ', '11:75'),
(1549, 11, 76, 'يَـٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَـٰذَآ ۖ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ ۖ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', '11:76'),
(1550, 11, 77, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَـٰذَا يَوْمٌ عَصِيبٌ', '11:77'),
(1551, 11, 78, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ ۚ قَالَ يَـٰقَوْمِ هَـٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ ۖ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', '11:78'),
(1552, 11, 79, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', '11:79'),
(1553, 11, 80, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ', '11:80'),
(1554, 11, 81, 'قَالُوا۟ يَـٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ ۖ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ ۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ ۚ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ ۚ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ', '11:81'),
(1555, 11, 82, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَـٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', '11:82'),
(1556, 11, 83, 'مُّسَوَّمَةً عِندَ رَبِّكَ ۖ وَمَا هِىَ مِنَ ٱلظَّـٰلِمِينَ بِبَعِيدٍ', '11:83'),
(1557, 11, 84, '۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ ۚ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', '11:84'),
(1558, 11, 85, 'وَيَـٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '11:85'),
(1559, 11, 86, 'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '11:86'),
(1560, 11, 87, 'قَالُوا۟ يَـٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَـٰٓؤُا۟ ۖ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', '11:87'),
(1561, 11, 88, 'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَـٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '11:88'),
(1562, 11, 89, 'وَيَـٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَـٰلِحٍ ۚ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', '11:89'),
(1563, 11, 90, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ', '11:90'),
(1564, 11, 91, 'قَالُوا۟ يَـٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا ۖ وَلَوْلَا رَهْطُكَ لَرَجَمْنَـٰكَ ۖ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ', '11:91'),
(1565, 11, 92, 'قَالَ يَـٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا ۖ إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ', '11:92'),
(1566, 11, 93, 'وَيَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَـٰمِلٌ ۖ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَـٰذِبٌ ۖ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ', '11:93'),
(1567, 11, 94, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَـٰرِهِمْ جَـٰثِمِينَ', '11:94'),
(1568, 11, 95, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', '11:95'),
(1569, 11, 96, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَا وَسُلْطَـٰنٍ مُّبِينٍ', '11:96'),
(1570, 11, 97, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ ۖ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', '11:97'),
(1571, 11, 98, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَـٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ ۖ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', '11:98'),
(1572, 11, 99, 'وَأُتْبِعُوا۟ فِى هَـٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَـٰمَةِ ۚ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', '11:99'),
(1573, 11, 100, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ ۖ مِنْهَا قَآئِمٌ وَحَصِيدٌ', '11:100'),
(1574, 11, 101, 'وَمَا ظَلَمْنَـٰهُمْ وَلَـٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ ۖ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ ۖ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', '11:101'),
(1575, 11, 102, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَـٰلِمَةٌ ۚ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ', '11:102'),
(1576, 11, 103, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ۚ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', '11:103'),
(1577, 11, 104, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ', '11:104'),
(1578, 11, 105, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ ۚ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ', '11:105'),
(1579, 11, 106, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', '11:106'),
(1580, 11, 107, 'خَـٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۚ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', '11:107'),
(1581, 11, 108, '۞ وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَـٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۖ عَطَآءً غَيْرَ مَجْذُوذٍ', '11:108'),
(1582, 11, 109, 'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَـٰٓؤُلَآءِ ۚ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ ۚ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', '11:109'),
(1583, 11, 110, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ فَٱخْتُلِفَ فِيهِ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '11:110'),
(1584, 11, 111, 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَـٰلَهُمْ ۚ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ', '11:111'),
(1585, 11, 112, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ ۚ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '11:112'),
(1586, 11, 113, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', '11:113'),
(1587, 11, 114, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ ۚ إِنَّ ٱلْحَسَنَـٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ۚ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', '11:114'),
(1588, 11, 115, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '11:115'),
(1589, 11, 116, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ ۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', '11:116'),
(1590, 11, 117, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', '11:117'),
(1591, 11, 118, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ', '11:118'),
(1592, 11, 119, 'إِلَّا مَن رَّحِمَ رَبُّكَ ۚ وَلِذَٰلِكَ خَلَقَهُمْ ۗ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', '11:119'),
(1593, 11, 120, 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ ۚ وَجَآءَكَ فِى هَـٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', '11:120'),
(1594, 11, 121, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَـٰمِلُونَ', '11:121'),
(1595, 11, 122, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '11:122'),
(1596, 11, 123, 'وَلِلَّهِ غَيْبُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '11:123'),
(1597, 12, 1, ' الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', '12:1'),
(1598, 12, 2, 'إِنَّآ أَنزَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '12:2'),
(1599, 12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَـٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَـٰفِلِينَ', '12:3'),
(1600, 12, 4, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَـٰجِدِينَ', '12:4'),
(1601, 12, 5, 'قَالَ يَـٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَـٰنَ لِلْإِنسَـٰنِ عَدُوٌّ مُّبِينٌ', '12:5'),
(1602, 12, 6, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَـٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ', '12:6'),
(1603, 12, 7, '۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَـٰتٌ لِّلسَّآئِلِينَ', '12:7'),
(1604, 12, 8, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَـٰلٍ مُّبِينٍ', '12:8'),
(1605, 12, 9, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَـٰلِحِينَ', '12:9'),
(1606, 12, 10, 'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَـٰعِلِينَ', '12:10'),
(1607, 12, 11, 'قَالُوا۟ يَـٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ', '12:11'),
(1608, 12, 12, 'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ', '12:12'),
(1609, 12, 13, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَـٰفِلُونَ', '12:13'),
(1610, 12, 14, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَـٰسِرُونَ', '12:14'),
(1611, 12, 15, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَـٰذَا وَهُمْ لَا يَشْعُرُونَ', '12:15'),
(1612, 12, 16, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ', '12:16'),
(1613, 12, 17, 'قَالُوا۟ يَـٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَـٰدِقِينَ', '12:17'),
(1614, 12, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '12:18'),
(1615, 12, 19, 'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَـٰبُشْرَىٰ هَـٰذَا غُلَـٰمٌ ۚ وَأَسَرُّوهُ بِضَـٰعَةً ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', '12:19'),
(1616, 12, 20, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', '12:20'),
(1617, 12, 21, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا ۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '12:21'),
(1618, 12, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '12:22'),
(1619, 12, 23, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ ۚ قَالَ مَعَاذَ ٱللَّهِ ۖ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ', '12:23'),
(1620, 12, 24, 'وَلَقَدْ هَمَّتْ بِهِۦ ۖ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَـٰنَ رَبِّهِۦ ۚ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ ۚ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', '12:24'),
(1621, 12, 25, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', '12:25'),
(1622, 12, 26, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى ۚ وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَـٰذِبِينَ', '12:26'),
(1623, 12, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ', '12:27'),
(1624, 12, 28, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌ', '12:28'),
(1625, 12, 29, 'يُوسُفُ أَعْرِضْ عَنْ هَـٰذَا ۚ وَٱسْتَغْفِرِى لِذَنۢبِكِ ۖ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', '12:29'),
(1626, 12, 30, '۞ وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ ۖ قَدْ شَغَفَهَا حُبًّا ۖ إِنَّا لَنَرَىٰهَا فِى ضَلَـٰلٍ مُّبِينٍ', '12:30'),
(1627, 12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ ۖ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَـٰشَ لِلَّهِ مَا هَـٰذَا بَشَرًا إِنْ هَـٰذَآ إِلَّا مَلَكٌ كَرِيمٌ', '12:31'),
(1628, 12, 32, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ ۖ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ ۖ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّـٰغِرِينَ', '12:32'),
(1629, 12, 33, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَـٰهِلِينَ', '12:33'),
(1630, 12, 34, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '12:34'),
(1631, 12, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَـٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ', '12:35'),
(1632, 12, 36, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ ۖ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا ۖ وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ ۖ نَبِّئْنَا بِتَأْوِيلِهِۦٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', '12:36'),
(1633, 12, 37, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ ۚ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ', '12:37'),
(1634, 12, 38, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَـٰقَ وَيَعْقُوبَ ۚ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ۚ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '12:38'),
(1635, 12, 39, 'يَـٰصَـٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', '12:39'),
(1636, 12, 40, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۚ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '12:40'),
(1637, 12, 41, 'يَـٰصَـٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا ۖ وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ ۚ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', '12:41'),
(1638, 12, 42, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَـٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', '12:42'),
(1639, 12, 43, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ ۖ يَـٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَـٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', '12:43'),
(1640, 12, 44, 'قَالُوٓا۟ أَضْغَـٰثُ أَحْلَـٰمٍ ۖ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَـٰمِ بِعَـٰلِمِينَ', '12:44'),
(1641, 12, 45, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', '12:45'),
(1642, 12, 46, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', '12:46'),
(1643, 12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', '12:47'),
(1644, 12, 48, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', '12:48'),
(1645, 12, 49, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', '12:49'),
(1646, 12, 50, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ ۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّـٰتِى قَطَّعْنَ أَيْدِيَهُنَّ ۚ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ', '12:50'),
(1647, 12, 51, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ ۚ قُلْنَ حَـٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ ۚ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٔـٰنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ', '12:51'),
(1648, 12, 52, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', '12:52'),
(1649, 12, 53, '۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ', '12:53'),
(1650, 12, 54, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى ۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', '12:54'),
(1651, 12, 55, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌ', '12:55'),
(1652, 12, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ ۚ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ ۖ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '12:56'),
(1653, 12, 57, 'وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '12:57'),
(1654, 12, 58, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', '12:58'),
(1655, 12, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ ۚ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', '12:59'),
(1656, 12, 60, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', '12:60'),
(1657, 12, 61, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَـٰعِلُونَ', '12:61'),
(1658, 12, 62, 'وَقَالَ لِفِتْيَـٰنِهِ ٱجْعَلُوا۟ بِضَـٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', '12:62'),
(1659, 12, 63, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ', '12:63'),
(1660, 12, 64, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ ۖ فَٱللَّهُ خَيْرٌ حَـٰفِظًا ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '12:64'),
(1661, 12, 65, 'وَلَمَّا فَتَحُوا۟ مَتَـٰعَهُمْ وَجَدُوا۟ بِضَـٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَـٰٓأَبَانَا مَا نَبْغِى ۖ هَـٰذِهِۦ بِضَـٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ۖ ذَٰلِكَ كَيْلٌ يَسِيرٌ', '12:65'),
(1662, 12, 66, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ ۖ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', '12:66'),
(1663, 12, 67, 'وَقَالَ يَـٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ ۖ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ ۖ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '12:67'),
(1664, 12, 68, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا ۚ وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَـٰهُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '12:68'),
(1665, 12, 69, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', '12:69'),
(1666, 12, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَـٰرِقُونَ', '12:70'),
(1667, 12, 71, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', '12:71'),
(1668, 12, 72, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ', '12:72'),
(1669, 12, 73, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَـٰرِقِينَ', '12:73'),
(1670, 12, 74, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَـٰذِبِينَ', '12:74'),
(1671, 12, 75, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ', '12:75'),
(1672, 12, 76, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ ۚ كَذَٰلِكَ كِدْنَا لِيُوسُفَ ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ', '12:76'),
(1673, 12, 77, '۞ قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ ۚ قَالَ أَنتُمْ شَرٌّ مَّكَانًا ۖ وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', '12:77'),
(1674, 12, 78, 'قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', '12:78'),
(1675, 12, 79, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَـٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَـٰلِمُونَ', '12:79'),
(1676, 12, 80, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا ۖ قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ ۖ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى ۖ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ', '12:80'),
(1677, 12, 81, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَـٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَـٰفِظِينَ', '12:81'),
(1678, 12, 82, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا ۖ وَإِنَّا لَصَـٰدِقُونَ', '12:82'),
(1679, 12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '12:83'),
(1680, 12, 84, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ', '12:84'),
(1681, 12, 85, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَـٰلِكِينَ', '12:85'),
(1682, 12, 86, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '12:86'),
(1683, 12, 87, 'يَـٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَـٰفِرُونَ', '12:87'),
(1684, 12, 88, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَـٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ ۖ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', '12:88'),
(1685, 12, 89, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَـٰهِلُونَ', '12:89'),
(1686, 12, 90, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ ۖ قَالَ أَنَا۠ يُوسُفُ وَهَـٰذَآ أَخِى ۖ قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ ۖ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '12:90'),
(1687, 12, 91, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَـٰطِـِٔينَ', '12:91'),
(1688, 12, 92, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '12:92'),
(1689, 12, 93, 'ٱذْهَبُوا۟ بِقَمِيصِى هَـٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', '12:93'),
(1690, 12, 94, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ ۖ لَوْلَآ أَن تُفَنِّدُونِ', '12:94'),
(1691, 12, 95, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَـٰلِكَ ٱلْقَدِيمِ', '12:95'),
(1692, 12, 96, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا ۖ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '12:96'),
(1693, 12, 97, 'قَالُوا۟ يَـٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَـٰطِـِٔينَ', '12:97'),
(1694, 12, 98, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '12:98'),
(1695, 12, 99, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', '12:99'),
(1696, 12, 100, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا ۖ وَقَالَ يَـٰٓأَبَتِ هَـٰذَا تَأْوِيلُ رُءْيَـٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا ۖ وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَـٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ ۚ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '12:100'),
(1697, 12, 101, '۞ رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ فَاطِرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّـٰلِحِينَ', '12:101'),
(1698, 12, 102, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۖ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', '12:102'),
(1699, 12, 103, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', '12:103'),
(1700, 12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', '12:104'),
(1701, 12, 105, 'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', '12:105'),
(1702, 12, 106, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', '12:106'),
(1703, 12, 107, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَـٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '12:107'),
(1704, 12, 108, 'قُلْ هَـٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَـٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '12:108'),
(1705, 12, 109, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ ۗ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۗ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ ۗ أَفَلَا تَعْقِلُونَ', '12:109'),
(1706, 12, 110, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '12:110'),
(1707, 12, 111, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَـٰبِ ۗ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '12:111'),
(1708, 13, 1, ' الٓمٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ۗ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', '13:1'),
(1709, 13, 2, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَـٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۚ يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْـَٔايَـٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', '13:2'),
(1710, 13, 3, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَـٰرًا ۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ ۖ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '13:3'),
(1711, 13, 4, 'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَـٰوِرَٰتٌ وَجَنَّـٰتٌ مِّنْ أَعْنَـٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '13:4'),
(1712, 13, 5, '۞ وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ ٱلْأَغْلَـٰلُ فِىٓ أَعْنَاقِهِمْ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '13:5'),
(1713, 13, 6, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَـٰتُ ۗ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ ۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', '13:6'),
(1714, 13, 7, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ ۗ إِنَّمَآ أَنتَ مُنذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ', '13:7'),
(1715, 13, 8, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', '13:8'),
(1716, 13, 9, 'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', '13:9'),
(1717, 13, 10, 'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', '13:10'),
(1718, 13, 11, 'لَهُۥ مُعَقِّبَـٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', '13:11'),
(1719, 13, 12, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', '13:12'),
(1720, 13, 13, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَـٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَـٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', '13:13'),
(1721, 13, 14, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَـٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَـٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَـٰفِرِينَ إِلَّا فِى ضَلَـٰلٍ', '13:14'),
(1722, 13, 15, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَـٰلُهُم بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ ۩', '13:15'),
(1723, 13, 16, 'قُلْ مَن رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ ۚ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَـٰتُ وَٱلنُّورُ ۗ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَـٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ ۚ قُلِ ٱللَّهُ خَـٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّـٰرُ', '13:16'),
(1724, 13, 17, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا ۚ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَـٰعٍ زَبَدٌ مِّثْلُهُۥ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَـٰطِلَ ۚ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً ۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', '13:17'),
(1725, 13, 18, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ ۚ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ ۚ أُو۟لَـٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمِهَادُ', '13:18'),
(1726, 13, 19, '۞ أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '13:19'),
(1727, 13, 20, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَـٰقَ', '13:20'),
(1728, 13, 21, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', '13:21'),
(1729, 13, 22, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَـٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَـٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', '13:22'),
(1730, 13, 23, 'جَنَّـٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّـٰتِهِمْ ۖ وَٱلْمَلَـٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', '13:23'),
(1731, 13, 24, 'سَلَـٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ ۚ فَنِعْمَ عُقْبَى ٱلدَّارِ', '13:24'),
(1732, 13, 25, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۙ أُو۟لَـٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '13:25'),
(1733, 13, 26, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا مَتَـٰعٌ', '13:26'),
(1734, 13, 27, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۗ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', '13:27'),
(1735, 13, 28, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', '13:28'),
(1736, 13, 29, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ', '13:29'),
(1737, 13, 30, 'كَذَٰلِكَ أَرْسَلْنَـٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَـٰنِ ۚ قُلْ هُوَ رَبِّى لَآ إِلَـٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', '13:30'),
(1738, 13, 31, 'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ ۗ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا ۗ أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا ۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '13:31'),
(1739, 13, 32, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', '13:32'),
(1740, 13, 33, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ ۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ ۚ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَـٰهِرٍ مِّنَ ٱلْقَوْلِ ۗ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '13:33'),
(1741, 13, 34, 'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَقُّ ۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '13:34'),
(1742, 13, 35, '۞ مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ أُكُلُهَا دَآئِمٌ وَظِلُّهَا ۚ تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ ۖ وَّعُقْبَى ٱلْكَـٰفِرِينَ ٱلنَّارُ', '13:35'),
(1743, 13, 36, 'وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ ۖ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ ۚ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ ۚ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', '13:36'),
(1744, 13, 37, 'وَكَذَٰلِكَ أَنزَلْنَـٰهُ حُكْمًا عَرَبِيًّا ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ', '13:37'),
(1745, 13, 38, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً ۚ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ لِكُلِّ أَجَلٍ كِتَابٌ', '13:38'),
(1746, 13, 39, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ ۖ وَعِندَهُۥٓ أُمُّ ٱلْكِتَـٰبِ', '13:39'),
(1747, 13, 40, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ وَعَلَيْنَا ٱلْحِسَابُ', '13:40'),
(1748, 13, 41, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا ۚ وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ ۚ وَهُوَ سَرِيعُ ٱلْحِسَابِ', '13:41'),
(1749, 13, 42, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا ۖ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ ۗ وَسَيَعْلَمُ ٱلْكُفَّـٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', '13:42'),
(1750, 13, 43, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا ۚ قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَـٰبِ', '13:43'),
(1751, 14, 1, ' الٓر ۚ كِتَـٰبٌ أَنزَلْنَـٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', '14:1'),
(1752, 14, 2, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَوَيْلٌ لِّلْكَـٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ', '14:2'),
(1753, 14, 3, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍۭ بَعِيدٍ', '14:3'),
(1754, 14, 4, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '14:4'),
(1755, 14, 5, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '14:5'),
(1756, 14, 6, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', '14:6'),
(1757, 14, 7, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', '14:7'),
(1758, 14, 8, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', '14:8'),
(1759, 14, 9, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ ۛ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۛ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ ۚ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ', '14:9'),
(1760, 14, 10, '۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَـٰنٍ مُّبِينٍ', '14:10'),
(1761, 14, 11, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَـٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَـٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '14:11'),
(1762, 14, 12, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا ۚ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '14:12'),
(1763, 14, 13, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّـٰلِمِينَ', '14:13'),
(1764, 14, 14, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ۚ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', '14:14'),
(1765, 14, 15, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ', '14:15'),
(1766, 14, 16, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ', '14:16'),
(1767, 14, 17, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ ۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ', '14:17'),
(1768, 14, 18, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ أَعْمَـٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ ۖ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ۚ ذَٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلْبَعِيدُ', '14:18'),
(1769, 14, 19, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', '14:19'),
(1770, 14, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', '14:20'),
(1771, 14, 21, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَـٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ ۚ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَـٰكُمْ ۖ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', '14:21'),
(1772, 14, 22, 'وَقَالَ ٱلشَّيْطَـٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ ۖ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَـٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى ۖ فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم ۖ مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ ۖ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ ۗ إِنَّ ٱلظَّـٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '14:22'),
(1773, 14, 23, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ ۖ تَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ', '14:23'),
(1774, 14, 24, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ', '14:24'),
(1775, 14, 25, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا ۗ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '14:25'),
(1776, 14, 26, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ', '14:26'),
(1777, 14, 27, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَ ۚ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', '14:27'),
(1778, 14, 28, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', '14:28'),
(1779, 14, 29, 'جَهَنَّمَ يَصْلَوْنَهَا ۖ وَبِئْسَ ٱلْقَرَارُ', '14:29'),
(1780, 14, 30, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ ۗ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', '14:30'),
(1781, 14, 31, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَـٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَـٰلٌ', '14:31'),
(1782, 14, 32, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ ۖ وَسَخَّرَ لَكُمُ ٱلْأَنْهَـٰرَ', '14:32'),
(1783, 14, 33, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ ۖ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', '14:33'),
(1784, 14, 34, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ ۚ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱلْإِنسَـٰنَ لَظَلُومٌ كَفَّارٌ', '14:34'),
(1785, 14, 35, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَـٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', '14:35'),
(1786, 14, 36, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ ۖ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى ۖ وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ', '14:36'),
(1787, 14, 37, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', '14:37'),
(1788, 14, 38, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', '14:38'),
(1789, 14, 39, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَـٰعِيلَ وَإِسْحَـٰقَ ۚ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', '14:39'),
(1790, 14, 40, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ', '14:40'),
(1791, 14, 41, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', '14:41'),
(1792, 14, 42, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَـٰفِلًا عَمَّا يَعْمَلُ ٱلظَّـٰلِمُونَ ۚ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَـٰرُ', '14:42'),
(1793, 14, 43, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ ۖ وَأَفْـِٔدَتُهُمْ هَوَآءٌ', '14:43'),
(1794, 14, 44, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ ۗ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', '14:44'),
(1795, 14, 45, 'وَسَكَنتُمْ فِى مَسَـٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', '14:45'),
(1796, 14, 46, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', '14:46'),
(1797, 14, 47, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ ۗ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ', '14:47'),
(1798, 14, 48, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَـٰوَٰتُ ۖ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', '14:48'),
(1799, 14, 49, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', '14:49'),
(1800, 14, 50, 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', '14:50'),
(1801, 14, 51, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '14:51'),
(1802, 14, 52, 'هَـٰذَا بَلَـٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '14:52'),
(1803, 15, 1, ' الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ وَقُرْءَانٍ مُّبِينٍ', '15:1'),
(1804, 15, 2, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', '15:2'),
(1805, 15, 3, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ', '15:3'),
(1806, 15, 4, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ', '15:4'),
(1807, 15, 5, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '15:5'),
(1808, 15, 6, 'وَقَالُوا۟ يَـٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ', '15:6'),
(1809, 15, 7, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '15:7'),
(1810, 15, 8, 'مَا نُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ', '15:8'),
(1811, 15, 9, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ', '15:9'),
(1812, 15, 10, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', '15:10'),
(1813, 15, 11, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '15:11'),
(1814, 15, 12, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', '15:12'),
(1815, 15, 13, 'لَا يُؤْمِنُونَ بِهِۦ ۖ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', '15:13'),
(1816, 15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', '15:14'),
(1817, 15, 15, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَـٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ', '15:15'),
(1818, 15, 16, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ', '15:16'),
(1819, 15, 17, 'وَحَفِظْنَـٰهَا مِن كُلِّ شَيْطَـٰنٍ رَّجِيمٍ', '15:17'),
(1820, 15, 18, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ', '15:18'),
(1821, 15, 19, 'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ', '15:19'),
(1822, 15, 20, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', '15:20'),
(1823, 15, 21, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ', '15:21'),
(1824, 15, 22, 'وَأَرْسَلْنَا ٱلرِّيَـٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَـٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَـٰزِنِينَ', '15:22'),
(1825, 15, 23, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', '15:23'),
(1826, 15, 24, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', '15:24'),
(1827, 15, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', '15:25'),
(1828, 15, 26, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ مِن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '15:26'),
(1829, 15, 27, 'وَٱلْجَآنَّ خَلَقْنَـٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', '15:27'),
(1830, 15, 28, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌۢ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '15:28'),
(1831, 15, 29, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَـٰجِدِينَ', '15:29'),
(1832, 15, 30, 'فَسَجَدَ ٱلْمَلَـٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '15:30'),
(1833, 15, 31, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّـٰجِدِينَ', '15:31'),
(1834, 15, 32, 'قَالَ يَـٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِينَ', '15:32'),
(1835, 15, 33, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '15:33'),
(1836, 15, 34, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '15:34'),
(1837, 15, 35, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', '15:35'),
(1838, 15, 36, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '15:36'),
(1839, 15, 37, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '15:37'),
(1840, 15, 38, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', '15:38'),
(1841, 15, 39, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', '15:39'),
(1842, 15, 40, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '15:40'),
(1843, 15, 41, 'قَالَ هَـٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', '15:41'),
(1844, 15, 42, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَـٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', '15:42'),
(1845, 15, 43, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', '15:43'),
(1846, 15, 44, 'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', '15:44'),
(1847, 15, 45, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَعُيُونٍ', '15:45'),
(1848, 15, 46, 'ٱدْخُلُوهَا بِسَلَـٰمٍ ءَامِنِينَ', '15:46'),
(1849, 15, 47, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَـٰبِلِينَ', '15:47'),
(1850, 15, 48, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', '15:48'),
(1851, 15, 49, '۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', '15:49'),
(1852, 15, 50, 'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ', '15:50'),
(1853, 15, 51, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', '15:51'),
(1854, 15, 52, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَـٰمًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', '15:52'),
(1855, 15, 53, 'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ عَلِيمٍ', '15:53'),
(1856, 15, 54, 'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ', '15:54'),
(1857, 15, 55, 'قَالُوا۟ بَشَّرْنَـٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَـٰنِطِينَ', '15:55'),
(1858, 15, 56, 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', '15:56'),
(1859, 15, 57, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', '15:57'),
(1860, 15, 58, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', '15:58'),
(1861, 15, 59, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', '15:59'),
(1862, 15, 60, 'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ ۙ إِنَّهَا لَمِنَ ٱلْغَـٰبِرِينَ', '15:60'),
(1863, 15, 61, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ', '15:61'),
(1864, 15, 62, 'قَالَ إِنَّكُمْ قَوْمٌ مُّنكَرُونَ', '15:62'),
(1865, 15, 63, 'قَالُوا۟ بَلْ جِئْنَـٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ', '15:63'),
(1866, 15, 64, 'وَأَتَيْنَـٰكَ بِٱلْحَقِّ وَإِنَّا لَصَـٰدِقُونَ', '15:64'),
(1867, 15, 65, 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَـٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ', '15:65'),
(1868, 15, 66, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَـٰٓؤُلَآءِ مَقْطُوعٌ مُّصْبِحِينَ', '15:66'),
(1869, 15, 67, 'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ', '15:67'),
(1870, 15, 68, 'قَالَ إِنَّ هَـٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ', '15:68'),
(1871, 15, 69, 'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ', '15:69'),
(1872, 15, 70, 'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَـٰلَمِينَ', '15:70'),
(1873, 15, 71, 'قَالَ هَـٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَـٰعِلِينَ', '15:71'),
(1874, 15, 72, 'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ', '15:72'),
(1875, 15, 73, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ', '15:73'),
(1876, 15, 74, 'فَجَعَلْنَا عَـٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِّن سِجِّيلٍ', '15:74'),
(1877, 15, 75, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّلْمُتَوَسِّمِينَ', '15:75'),
(1878, 15, 76, 'وَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ', '15:76'),
(1879, 15, 77, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', '15:77'),
(1880, 15, 78, 'وَإِن كَانَ أَصْحَـٰبُ ٱلْأَيْكَةِ لَظَـٰلِمِينَ', '15:78'),
(1881, 15, 79, 'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ', '15:79'),
(1882, 15, 80, 'وَلَقَدْ كَذَّبَ أَصْحَـٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ', '15:80'),
(1883, 15, 81, 'وَءَاتَيْنَـٰهُمْ ءَايَـٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ', '15:81'),
(1884, 15, 82, 'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ', '15:82'),
(1885, 15, 83, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ', '15:83'),
(1886, 15, 84, 'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', '15:84'),
(1887, 15, 85, 'وَمَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ ۗ وَإِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ ۖ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ', '15:85'),
(1888, 15, 86, 'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّـٰقُ ٱلْعَلِيمُ', '15:86'),
(1889, 15, 87, 'وَلَقَدْ ءَاتَيْنَـٰكَ سَبْعًا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ', '15:87'),
(1890, 15, 88, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', '15:88'),
(1891, 15, 89, 'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ', '15:89'),
(1892, 15, 90, 'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ', '15:90'),
(1893, 15, 91, 'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ', '15:91'),
(1894, 15, 92, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ', '15:92'),
(1895, 15, 93, 'عَمَّا كَانُوا۟ يَعْمَلُونَ', '15:93'),
(1896, 15, 94, 'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', '15:94'),
(1897, 15, 95, 'إِنَّا كَفَيْنَـٰكَ ٱلْمُسْتَهْزِءِينَ', '15:95'),
(1898, 15, 96, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ ۚ فَسَوْفَ يَعْلَمُونَ', '15:96'),
(1899, 15, 97, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', '15:97'),
(1900, 15, 98, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِينَ', '15:98'),
(1901, 15, 99, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', '15:99'),
(1902, 16, 1, ' أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '16:1'),
(1903, 16, 2, 'يُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', '16:2'),
(1904, 16, 3, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '16:3'),
(1905, 16, 4, 'خَلَقَ ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', '16:4'),
(1906, 16, 5, 'وَٱلْأَنْعَـٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌ وَمَنَـٰفِعُ وَمِنْهَا تَأْكُلُونَ', '16:5'),
(1907, 16, 6, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', '16:6'),
(1908, 16, 7, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَـٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ ۚ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', '16:7'),
(1909, 16, 8, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ', '16:8'),
(1910, 16, 9, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '16:9'),
(1911, 16, 10, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً ۖ لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ', '16:10'),
(1912, 16, 11, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَـٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', '16:11'),
(1913, 16, 12, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '16:12'),
(1914, 16, 13, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَذَّكَّرُونَ', '16:13'),
(1915, 16, 14, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '16:14'),
(1916, 16, 15, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَـٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '16:15'),
(1917, 16, 16, 'وَعَلَـٰمَـٰتٍ ۚ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', '16:16'),
(1918, 16, 17, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ', '16:17'),
(1919, 16, 18, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ', '16:18'),
(1920, 16, 19, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', '16:19'),
(1921, 16, 20, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '16:20'),
(1922, 16, 21, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ ۖ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', '16:21'),
(1923, 16, 22, 'إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۚ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', '16:22'),
(1924, 16, 23, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', '16:23'),
(1925, 16, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ ۙ قَالُوٓا۟ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '16:24'),
(1926, 16, 25, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَـٰمَةِ ۙ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ ۗ أَلَا سَآءَ مَا يَزِرُونَ', '16:25'),
(1927, 16, 26, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَـٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '16:26'),
(1928, 16, 27, 'ثُمَّ يَوْمَ ٱلْقِيَـٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَـٰٓقُّونَ فِيهِمْ ۚ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَـٰفِرِينَ', '16:27'),
(1929, 16, 28, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ ۖ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ ۚ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', '16:28'),
(1930, 16, 29, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۖ فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', '16:29'),
(1931, 16, 30, '۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ ۚ قَالُوا۟ خَيْرًا ۗ لِّلَّذِينَ أَحْسَنُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةٌ ۚ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ ۚ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', '16:30'),
(1932, 16, 31, 'جَنَّـٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ لَهُمْ فِيهَا مَا يَشَآءُونَ ۚ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', '16:31'),
(1933, 16, 32, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ طَيِّبِينَ ۙ يَقُولُونَ سَلَـٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', '16:32'),
(1934, 16, 33, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '16:33'),
(1935, 16, 34, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '16:34'),
(1936, 16, 35, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '16:35'),
(1937, 16, 36, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّـٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَـٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ', '16:36'),
(1938, 16, 37, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ ۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ', '16:37'),
(1939, 16, 38, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ ۙ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ ۚ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '16:38'),
(1940, 16, 39, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَـٰذِبِينَ', '16:39'),
(1941, 16, 40, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَـٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', '16:40'),
(1942, 16, 41, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً ۖ وَلَأَجْرُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', '16:41'),
(1943, 16, 42, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '16:42'),
(1944, 16, 43, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ ۚ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', '16:43'),
(1945, 16, 44, 'بِٱلْبَيِّنَـٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', '16:44'),
(1946, 16, 45, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '16:45'),
(1947, 16, 46, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', '16:46'),
(1948, 16, 47, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', '16:47'),
(1949, 16, 48, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَـٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ', '16:48'),
(1950, 16, 49, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَـٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', '16:49'),
(1951, 16, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩', '16:50'),
(1952, 16, 51, '۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَـٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ ۖ فَإِيَّـٰىَ فَٱرْهَبُونِ', '16:51'),
(1953, 16, 52, 'وَلَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا ۚ أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', '16:52'),
(1954, 16, 53, 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', '16:53'),
(1955, 16, 54, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', '16:54'),
(1956, 16, 55, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَـٰهُمْ ۚ فَتَمَتَّعُوا۟ ۖ فَسَوْفَ تَعْلَمُونَ', '16:55'),
(1957, 16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَـٰهُمْ ۗ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', '16:56'),
(1958, 16, 57, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَـٰتِ سُبْحَـٰنَهُۥ ۙ وَلَهُم مَّا يَشْتَهُونَ', '16:57'),
(1959, 16, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', '16:58'),
(1960, 16, 59, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ ۚ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ ۗ أَلَا سَآءَ مَا يَحْكُمُونَ', '16:59'),
(1961, 16, 60, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ مَثَلُ ٱلسَّوْءِ ۖ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '16:60'),
(1962, 16, 61, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَـٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ', '16:61'),
(1963, 16, 62, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ ۖ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', '16:62'),
(1964, 16, 63, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', '16:63'),
(1965, 16, 64, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَـٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ ۙ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '16:64'),
(1966, 16, 65, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَسْمَعُونَ', '16:65'),
(1967, 16, 66, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَـٰمِ لَعِبْرَةً ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّـٰرِبِينَ', '16:66'),
(1968, 16, 67, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَـٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْقِلُونَ', '16:67'),
(1969, 16, 68, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', '16:68'),
(1970, 16, 69, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', '16:69'),
(1971, 16, 70, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ ۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ', '16:70'),
(1972, 16, 71, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ ۚ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ ۚ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', '16:71'),
(1973, 16, 72, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ ۚ أَفَبِٱلْبَـٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', '16:72'),
(1974, 16, 73, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ', '16:73'),
(1975, 16, 74, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ ۚ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '16:74'),
(1976, 16, 75, '۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَـٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا ۖ هَلْ يَسْتَوُۥنَ ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '16:75'),
(1977, 16, 76, 'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ ۖ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ ۙ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '16:76'),
(1978, 16, 77, 'وَلِلَّهِ غَيْبُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '16:77'),
(1979, 16, 78, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَـٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۙ لَعَلَّكُمْ تَشْكُرُونَ', '16:78'),
(1980, 16, 79, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '16:79'),
(1981, 16, 80, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَـٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَـٰثًا وَمَتَـٰعًا إِلَىٰ حِينٍ', '16:80'),
(1982, 16, 81, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَـٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَـٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ ۚ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', '16:81'),
(1983, 16, 82, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ٱلْمُبِينُ', '16:82'),
(1984, 16, 83, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَـٰفِرُونَ', '16:83'),
(1985, 16, 84, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', '16:84'),
(1986, 16, 85, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', '16:85'),
(1987, 16, 86, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَـٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ ۖ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَـٰذِبُونَ', '16:86'),
(1988, 16, 87, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '16:87'),
(1989, 16, 88, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَـٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', '16:88'),
(1990, 16, 89, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِ ۚ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَـٰبَ تِبْيَـٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', '16:89'),
(1991, 16, 90, '۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَـٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', '16:90'),
(1992, 16, 91, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَـٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَـٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا ۚ إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', '16:91'),
(1993, 16, 92, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَـٰثًا تَتَّخِذُونَ أَيْمَـٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ ۚ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ ۚ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '16:92'),
(1994, 16, 93, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', '16:93'),
(1995, 16, 94, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَـٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ ۖ وَلَكُمْ عَذَابٌ عَظِيمٌ', '16:94'),
(1996, 16, 95, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا ۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '16:95'),
(1997, 16, 96, 'مَا عِندَكُمْ يَنفَدُ ۖ وَمَا عِندَ ٱللَّهِ بَاقٍ ۗ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', '16:96'),
(1998, 16, 97, 'مَنْ عَمِلَ صَـٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', '16:97'),
(1999, 16, 98, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَـٰنِ ٱلرَّجِيمِ', '16:98'),
(2000, 16, 99, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَـٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '16:99');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(2001, 16, 100, 'إِنَّمَا سُلْطَـٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', '16:100'),
(2002, 16, 101, 'وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ ۙ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '16:101'),
(2003, 16, 102, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', '16:102'),
(2004, 16, 103, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌ ۗ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّ وَهَـٰذَا لِسَانٌ عَرَبِىٌّ مُّبِينٌ', '16:103'),
(2005, 16, 104, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَـٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', '16:104'),
(2006, 16, 105, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَـٰتِ ٱللَّهِ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰذِبُونَ', '16:105'),
(2007, 16, 106, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَـٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَـٰنِ وَلَـٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '16:106'),
(2008, 16, 107, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ', '16:107'),
(2009, 16, 108, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْغَـٰفِلُونَ', '16:108'),
(2010, 16, 109, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْخَـٰسِرُونَ', '16:109'),
(2011, 16, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَـٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '16:110'),
(2012, 16, 111, '۞ يَوْمَ تَأْتِى كُلُّ نَفْسٍ تُجَـٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', '16:111'),
(2013, 16, 112, 'وَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', '16:112'),
(2014, 16, 113, 'وَلَقَدْ جَآءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَـٰلِمُونَ', '16:113'),
(2015, 16, 114, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلًا طَيِّبًا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', '16:114'),
(2016, 16, 115, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '16:115'),
(2017, 16, 116, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَـٰذَا حَلَـٰلٌ وَهَـٰذَا حَرَامٌ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ ۚ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '16:116'),
(2018, 16, 117, 'مَتَـٰعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', '16:117'),
(2019, 16, 118, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ ۖ وَمَا ظَلَمْنَـٰهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '16:118'),
(2020, 16, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَـٰلَةٍ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '16:119'),
(2021, 16, 120, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', '16:120'),
(2022, 16, 121, 'شَاكِرًا لِّأَنْعُمِهِ ۚ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '16:121'),
(2023, 16, 122, 'وَءَاتَيْنَـٰهُ فِى ٱلدُّنْيَا حَسَنَةً ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ', '16:122'),
(2024, 16, 123, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '16:123'),
(2025, 16, 124, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ ۚ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '16:124'),
(2026, 16, 125, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَـٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '16:125'),
(2027, 16, 126, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ ۖ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّـٰبِرِينَ', '16:126'),
(2028, 16, 127, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '16:127'),
(2029, 16, 128, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', '16:128'),
(2030, 17, 1, ' سُبْحَـٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَـٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَـٰتِنَآ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '17:1'),
(2031, 17, 2, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَجَعَلْنَـٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًا', '17:2'),
(2032, 17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ ۚ إِنَّهُۥ كَانَ عَبْدًا شَكُورًا', '17:3'),
(2033, 17, 4, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَـٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا', '17:4'),
(2034, 17, 5, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَآ أُو۟لِى بَأْسٍ شَدِيدٍ فَجَاسُوا۟ خِلَـٰلَ ٱلدِّيَارِ ۚ وَكَانَ وَعْدًا مَّفْعُولًا', '17:5'),
(2035, 17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَـٰكُم بِأَمْوَٰلٍ وَبَنِينَ وَجَعَلْنَـٰكُمْ أَكْثَرَ نَفِيرًا', '17:6'),
(2036, 17, 7, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ ۖ وَإِنْ أَسَأْتُمْ فَلَهَا ۚ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ لِيَسُـۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', '17:7'),
(2037, 17, 8, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ ۚ وَإِنْ عُدتُّمْ عُدْنَا ۘ وَجَعَلْنَا جَهَنَّمَ لِلْكَـٰفِرِينَ حَصِيرًا', '17:8'),
(2038, 17, 9, 'إِنَّ هَـٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ أَجْرًا كَبِيرًا', '17:9'),
(2039, 17, 10, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '17:10'),
(2040, 17, 11, 'وَيَدْعُ ٱلْإِنسَـٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ ۖ وَكَانَ ٱلْإِنسَـٰنُ عَجُولًا', '17:11'),
(2041, 17, 12, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ ۖ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةً لِّتَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ وَكُلَّ شَىْءٍ فَصَّلْنَـٰهُ تَفْصِيلًا', '17:12'),
(2042, 17, 13, 'وَكُلَّ إِنسَـٰنٍ أَلْزَمْنَـٰهُ طَـٰٓئِرَهُۥ فِى عُنُقِهِۦ ۖ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَـٰمَةِ كِتَـٰبًا يَلْقَىٰهُ مَنشُورًا', '17:13'),
(2043, 17, 14, 'ٱقْرَأْ كِتَـٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًا', '17:14'),
(2044, 17, 15, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا', '17:15'),
(2045, 17, 16, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَـٰهَا تَدْمِيرًا', '17:16'),
(2046, 17, 17, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍ ۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًا', '17:17'),
(2047, 17, 18, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًا مَّدْحُورًا', '17:18'),
(2048, 17, 19, 'وَمَنْ أَرَادَ ٱلْـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًا', '17:19'),
(2049, 17, 20, 'كُلًّا نُّمِدُّ هَـٰٓؤُلَآءِ وَهَـٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ ۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', '17:20'),
(2050, 17, 21, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ ۚ وَلَلْـَٔاخِرَةُ أَكْبَرُ دَرَجَـٰتٍ وَأَكْبَرُ تَفْضِيلًا', '17:21'),
(2051, 17, 22, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', '17:22'),
(2052, 17, 23, '۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', '17:23'),
(2053, 17, 24, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا', '17:24'),
(2054, 17, 25, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ ۚ إِن تَكُونُوا۟ صَـٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًا', '17:25'),
(2055, 17, 26, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', '17:26'),
(2056, 17, 27, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَـٰطِينِ ۖ وَكَانَ ٱلشَّيْطَـٰنُ لِرَبِّهِۦ كَفُورًا', '17:27'),
(2057, 17, 28, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', '17:28'),
(2058, 17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', '17:29'),
(2059, 17, 30, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', '17:30'),
(2060, 17, 31, 'وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُمْ خَشْيَةَ إِمْلَـٰقٍ ۖ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ ۚ إِنَّ قَتْلَهُمْ كَانَ خِطْـًٔا كَبِيرًا', '17:31'),
(2061, 17, 32, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ ۖ إِنَّهُۥ كَانَ فَـٰحِشَةً وَسَآءَ سَبِيلًا', '17:32'),
(2062, 17, 33, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۗ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَـٰنًا فَلَا يُسْرِف فِّى ٱلْقَتْلِ ۖ إِنَّهُۥ كَانَ مَنصُورًا', '17:33'),
(2063, 17, 34, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۚ وَأَوْفُوا۟ بِٱلْعَهْدِ ۖ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًا', '17:34'),
(2064, 17, 35, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '17:35'),
(2065, 17, 36, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۚ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَـٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا', '17:36'),
(2066, 17, 37, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًا', '17:37'),
(2067, 17, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًا', '17:38'),
(2068, 17, 39, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ ۗ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًا مَّدْحُورًا', '17:39'),
(2069, 17, 40, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَـٰٓئِكَةِ إِنَـٰثًا ۚ إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', '17:40'),
(2070, 17, 41, 'وَلَقَدْ صَرَّفْنَا فِى هَـٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', '17:41'),
(2071, 17, 42, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌ كَمَا يَقُولُونَ إِذًا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًا', '17:42'),
(2072, 17, 43, 'سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', '17:43'),
(2073, 17, 44, 'تُسَبِّحُ لَهُ ٱلسَّمَـٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَـٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ ۗ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', '17:44'),
(2074, 17, 45, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ حِجَابًا مَّسْتُورًا', '17:45'),
(2075, 17, 46, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۚ وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَـٰرِهِمْ نُفُورًا', '17:46'),
(2076, 17, 47, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', '17:47'),
(2077, 17, 48, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', '17:48'),
(2078, 17, 49, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَـٰمًا وَرُفَـٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', '17:49'),
(2079, 17, 50, '۞ قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', '17:50'),
(2080, 17, 51, 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ ۚ فَسَيَقُولُونَ مَن يُعِيدُنَا ۖ قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍ ۚ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ ۖ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًا', '17:51'),
(2081, 17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', '17:52'),
(2082, 17, 53, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ ٱلشَّيْطَـٰنَ يَنزَغُ بَيْنَهُمْ ۚ إِنَّ ٱلشَّيْطَـٰنَ كَانَ لِلْإِنسَـٰنِ عَدُوًّا مُّبِينًا', '17:53'),
(2083, 17, 54, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ ۖ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ ۚ وَمَآ أَرْسَلْنَـٰكَ عَلَيْهِمْ وَكِيلًا', '17:54'),
(2084, 17, 55, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعْضٍ ۖ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', '17:55'),
(2085, 17, 56, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', '17:56'),
(2086, 17, 57, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ ۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', '17:57'),
(2087, 17, 58, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَـٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَـٰبِ مَسْطُورًا', '17:58'),
(2088, 17, 59, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْـَٔايَـٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ ۚ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةً فَظَلَمُوا۟ بِهَا ۚ وَمَا نُرْسِلُ بِٱلْـَٔايَـٰتِ إِلَّا تَخْوِيفًا', '17:59'),
(2089, 17, 60, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ ۚ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَـٰكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ ۚ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَـٰنًا كَبِيرًا', '17:60'),
(2090, 17, 61, 'وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', '17:61'),
(2091, 17, 62, 'قَالَ أَرَءَيْتَكَ هَـٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًا', '17:62'),
(2092, 17, 63, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءً مَّوْفُورًا', '17:63'),
(2093, 17, 64, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَـٰدِ وَعِدْهُمْ ۚ وَمَا يَعِدُهُمُ ٱلشَّيْطَـٰنُ إِلَّا غُرُورًا', '17:64'),
(2094, 17, 65, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَـٰنٌ ۚ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', '17:65'),
(2095, 17, 66, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ ۚ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًا', '17:66'),
(2096, 17, 67, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ ۖ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ ۚ وَكَانَ ٱلْإِنسَـٰنُ كَفُورًا', '17:67'),
(2097, 17, 68, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', '17:68'),
(2098, 17, 69, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ۙ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًا', '17:69'),
(2099, 17, 70, '۞ وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَـٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ وَفَضَّلْنَـٰهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', '17:70'),
(2100, 17, 71, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَـٰمِهِمْ ۖ فَمَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَـٰٓئِكَ يَقْرَءُونَ كِتَـٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', '17:71'),
(2101, 17, 72, 'وَمَن كَانَ فِى هَـٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْـَٔاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', '17:72'),
(2102, 17, 73, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ ۖ وَإِذًا لَّٱتَّخَذُوكَ خَلِيلًا', '17:73'),
(2103, 17, 74, 'وَلَوْلَآ أَن ثَبَّتْنَـٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًٔا قَلِيلًا', '17:74'),
(2104, 17, 75, 'إِذًا لَّأَذَقْنَـٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', '17:75'),
(2105, 17, 76, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا ۖ وَإِذًا لَّا يَلْبَثُونَ خِلَـٰفَكَ إِلَّا قَلِيلًا', '17:76'),
(2106, 17, 77, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا ۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', '17:77'),
(2107, 17, 78, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ ۖ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًا', '17:78'),
(2108, 17, 79, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', '17:79'),
(2109, 17, 80, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَـٰنًا نَّصِيرًا', '17:80'),
(2110, 17, 81, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَـٰطِلُ ۚ إِنَّ ٱلْبَـٰطِلَ كَانَ زَهُوقًا', '17:81'),
(2111, 17, 82, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ ۙ وَلَا يَزِيدُ ٱلظَّـٰلِمِينَ إِلَّا خَسَارًا', '17:82'),
(2112, 17, 83, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَـٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ ۖ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًا', '17:83'),
(2113, 17, 84, 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', '17:84'),
(2114, 17, 85, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ ۖ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًا', '17:85'),
(2115, 17, 86, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', '17:86'),
(2116, 17, 87, 'إِلَّا رَحْمَةً مِّن رَّبِّكَ ۚ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًا', '17:87'),
(2117, 17, 88, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَـٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', '17:88'),
(2118, 17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَـٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', '17:89'),
(2119, 17, 90, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', '17:90'),
(2120, 17, 91, 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ ٱلْأَنْهَـٰرَ خِلَـٰلَهَا تَفْجِيرًا', '17:91'),
(2121, 17, 92, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ قَبِيلًا', '17:92'),
(2122, 17, 93, 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَـٰبًا نَّقْرَؤُهُۥ ۗ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', '17:93'),
(2123, 17, 94, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًا رَّسُولًا', '17:94'),
(2124, 17, 95, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَـٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا', '17:95'),
(2125, 17, 96, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', '17:96'),
(2126, 17, 97, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ ۖ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَـٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا ۖ مَّأْوَىٰهُمْ جَهَنَّمُ ۖ كُلَّمَا خَبَتْ زِدْنَـٰهُمْ سَعِيرًا', '17:97'),
(2127, 17, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَـٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَـٰمًا وَرُفَـٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', '17:98'),
(2128, 17, 99, '۞ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورًا', '17:99'),
(2129, 17, 100, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ ۚ وَكَانَ ٱلْإِنسَـٰنُ قَتُورًا', '17:100'),
(2130, 17, 101, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۖ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَـٰمُوسَىٰ مَسْحُورًا', '17:101'),
(2131, 17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَـٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَـٰفِرْعَوْنُ مَثْبُورًا', '17:102'),
(2132, 17, 103, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَـٰهُ وَمَن مَّعَهُۥ جَمِيعًا', '17:103'),
(2133, 17, 104, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', '17:104'),
(2134, 17, 105, 'وَبِٱلْحَقِّ أَنزَلْنَـٰهُ وَبِٱلْحَقِّ نَزَلَ ۗ وَمَآ أَرْسَلْنَـٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '17:105'),
(2135, 17, 106, 'وَقُرْءَانًا فَرَقْنَـٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَـٰهُ تَنزِيلًا', '17:106'),
(2136, 17, 107, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ ۚ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', '17:107'),
(2137, 17, 108, 'وَيَقُولُونَ سُبْحَـٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', '17:108'),
(2138, 17, 109, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا ۩', '17:109'),
(2139, 17, 110, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَـٰنَ ۖ أَيًّا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', '17:110'),
(2140, 17, 111, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّ مِّنَ ٱلذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًۢا', '17:111'),
(2141, 18, 1, ' ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَـٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ۜ', '18:1'),
(2142, 18, 2, 'قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا', '18:2'),
(2143, 18, 3, 'مَّـٰكِثِينَ فِيهِ أَبَدًا', '18:3'),
(2144, 18, 4, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا', '18:4'),
(2145, 18, 5, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍ وَلَا لِـَٔابَآئِهِمْ ۚ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَٰهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًا', '18:5'),
(2146, 18, 6, 'فَلَعَلَّكَ بَـٰخِعٌ نَّفْسَكَ عَلَىٰٓ ءَاثَـٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَـٰذَا ٱلْحَدِيثِ أَسَفًا', '18:6'),
(2147, 18, 7, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا', '18:7'),
(2148, 18, 8, 'وَإِنَّا لَجَـٰعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا', '18:8'),
(2149, 18, 9, 'أَمْ حَسِبْتَ أَنَّ أَصْحَـٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَـٰتِنَا عَجَبًا', '18:9'),
(2150, 18, 10, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', '18:10'),
(2151, 18, 11, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًا', '18:11'),
(2152, 18, 12, 'ثُمَّ بَعَثْنَـٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًا', '18:12'),
(2153, 18, 13, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَـٰهُمْ هُدًى', '18:13'),
(2154, 18, 14, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَـٰهًا ۖ لَّقَدْ قُلْنَآ إِذًا شَطَطًا', '18:14'),
(2155, 18, 15, 'هَـٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً ۖ لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَـٰنٍۭ بَيِّنٍ ۖ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا', '18:15'),
(2156, 18, 16, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا', '18:16'),
(2157, 18, 17, '۞ وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ ۗ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا', '18:17'),
(2158, 18, 18, 'وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ ۚ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ ۖ وَكَلْبُهُم بَـٰسِطٌ ذِرَاعَيْهِ بِٱلْوَصِيدِ ۚ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا', '18:18'),
(2159, 18, 19, 'وَكَذَٰلِكَ بَعَثْنَـٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ ۚ قَالَ قَآئِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ ۖ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ ۚ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَـٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', '18:19'),
(2160, 18, 20, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًا', '18:20'),
(2161, 18, 21, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَـٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ ۖ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَـٰنًا ۖ رَّبُّهُمْ أَعْلَمُ بِهِمْ ۚ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', '18:21'),
(2162, 18, 22, 'سَيَقُولُونَ ثَلَـٰثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ ۖ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ ۚ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ ۗ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءً ظَـٰهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', '18:22'),
(2163, 18, 23, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا', '18:23'),
(2164, 18, 24, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَـٰذَا رَشَدًا', '18:24'),
(2165, 18, 25, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَـٰثَ مِا۟ئَةٍ سِنِينَ وَٱزْدَادُوا۟ تِسْعًا', '18:25'),
(2166, 18, 26, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ ۖ لَهُۥ غَيْبُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ أَبْصِرْ بِهِۦ وَأَسْمِعْ ۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًا', '18:26'),
(2167, 18, 27, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ ۖ لَا مُبَدِّلَ لِكَلِمَـٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '18:27'),
(2168, 18, 28, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًا', '18:28'),
(2169, 18, 29, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ ۚ إِنَّآ أَعْتَدْنَا لِلظَّـٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا ۚ وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ ۚ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', '18:29'),
(2170, 18, 30, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', '18:30'),
(2171, 18, 31, 'أُو۟لَـٰٓئِكَ لَهُمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۚ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', '18:31'),
(2172, 18, 32, '۞ وَٱضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَـٰبٍ وَحَفَفْنَـٰهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', '18:32'),
(2173, 18, 33, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًٔا ۚ وَفَجَّرْنَا خِلَـٰلَهُمَا نَهَرًا', '18:33'),
(2174, 18, 34, 'وَكَانَ لَهُۥ ثَمَرٌ فَقَالَ لِصَـٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', '18:34'),
(2175, 18, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَـٰذِهِۦٓ أَبَدًا', '18:35'),
(2176, 18, 36, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', '18:36'),
(2177, 18, 37, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّىٰكَ رَجُلًا', '18:37'),
(2178, 18, 38, 'لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًا', '18:38'),
(2179, 18, 39, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ ۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًا وَوَلَدًا', '18:39'),
(2180, 18, 40, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', '18:40'),
(2181, 18, 41, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًا', '18:41'),
(2182, 18, 42, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَـٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًا', '18:42'),
(2183, 18, 43, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', '18:43'),
(2184, 18, 44, 'هُنَالِكَ ٱلْوَلَـٰيَةُ لِلَّهِ ٱلْحَقِّ ۚ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', '18:44'),
(2185, 18, 45, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَـٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَـٰحُ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا', '18:45'),
(2186, 18, 46, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱلْبَـٰقِيَـٰتُ ٱلصَّـٰلِحَـٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', '18:46'),
(2187, 18, 47, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةً وَحَشَرْنَـٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', '18:47'),
(2188, 18, 48, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَـٰكُمْ أَوَّلَ مَرَّةٍۭ ۚ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', '18:48'),
(2189, 18, 49, 'وَوُضِعَ ٱلْكِتَـٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَـٰوَيْلَتَنَا مَالِ هَـٰذَا ٱلْكِتَـٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا ۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا ۗ وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', '18:49'),
(2190, 18, 50, 'وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ ۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ ۚ بِئْسَ لِلظَّـٰلِمِينَ بَدَلًا', '18:50'),
(2191, 18, 51, '۞ مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًا', '18:51'),
(2192, 18, 52, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', '18:52'),
(2193, 18, 53, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًا', '18:53'),
(2194, 18, 54, 'وَلَقَدْ صَرَّفْنَا فِى هَـٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍ ۚ وَكَانَ ٱلْإِنسَـٰنُ أَكْثَرَ شَىْءٍ جَدَلًا', '18:54'),
(2195, 18, 55, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًا', '18:55'),
(2196, 18, 56, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۚ وَيُجَـٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَـٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ ۖ وَٱتَّخَذُوٓا۟ ءَايَـٰتِى وَمَآ أُنذِرُوا۟ هُزُوًا', '18:56'),
(2197, 18, 57, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَـٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ ۚ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۖ وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًا', '18:57'),
(2198, 18, 58, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ ۖ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ ۚ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًا', '18:58'),
(2199, 18, 59, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَـٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', '18:59'),
(2200, 18, 60, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا', '18:60'),
(2201, 18, 61, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًا', '18:61'),
(2202, 18, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَـٰذَا نَصَبًا', '18:62'),
(2203, 18, 63, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَـٰنُ أَنْ أَذْكُرَهُۥ ۚ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًا', '18:63'),
(2204, 18, 64, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ ۚ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًا', '18:64'),
(2205, 18, 65, 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَآ ءَاتَيْنَـٰهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَـٰهُ مِن لَّدُنَّا عِلْمًا', '18:65'),
(2206, 18, 66, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', '18:66'),
(2207, 18, 67, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '18:67'),
(2208, 18, 68, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًا', '18:68'),
(2209, 18, 69, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًا وَلَآ أَعْصِى لَكَ أَمْرًا', '18:69'),
(2210, 18, 70, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', '18:70'),
(2211, 18, 71, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا ۖ قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًا', '18:71'),
(2212, 18, 72, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '18:72'),
(2213, 18, 73, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًا', '18:73'),
(2214, 18, 74, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَـٰمًا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةًۢ بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْـًٔا نُّكْرًا', '18:74'),
(2215, 18, 75, '۞ قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '18:75'),
(2216, 18, 76, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَـٰحِبْنِى ۖ قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًا', '18:76'),
(2217, 18, 77, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ ۖ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًا', '18:77'),
(2218, 18, 78, 'قَالَ هَـٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ ۚ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', '18:78'),
(2219, 18, 79, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَـٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', '18:79'),
(2220, 18, 80, 'وَأَمَّا ٱلْغُلَـٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَـٰنًا وَكُفْرًا', '18:80'),
(2221, 18, 81, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَوٰةً وَأَقْرَبَ رُحْمًا', '18:81'),
(2222, 18, 82, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَـٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَـٰلِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ ۚ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ۚ ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', '18:82'),
(2223, 18, 83, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ ۖ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', '18:83'),
(2224, 18, 84, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَـٰهُ مِن كُلِّ شَىْءٍ سَبَبًا', '18:84'),
(2225, 18, 85, 'فَأَتْبَعَ سَبَبًا', '18:85'),
(2226, 18, 86, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا ۗ قُلْنَا يَـٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًا', '18:86'),
(2227, 18, 87, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًا نُّكْرًا', '18:87'),
(2228, 18, 88, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَـٰلِحًا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ ۖ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًا', '18:88'),
(2229, 18, 89, 'ثُمَّ أَتْبَعَ سَبَبًا', '18:89'),
(2230, 18, 90, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', '18:90'),
(2231, 18, 91, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', '18:91'),
(2232, 18, 92, 'ثُمَّ أَتْبَعَ سَبَبًا', '18:92'),
(2233, 18, 93, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', '18:93'),
(2234, 18, 94, 'قَالُوا۟ يَـٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', '18:94'),
(2235, 18, 95, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', '18:95'),
(2236, 18, 96, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ ۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ ۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًا', '18:96'),
(2237, 18, 97, 'فَمَا ٱسْطَـٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَـٰعُوا۟ لَهُۥ نَقْبًا', '18:97'),
(2238, 18, 98, 'قَالَ هَـٰذَا رَحْمَةٌ مِّن رَّبِّى ۖ فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ ۖ وَكَانَ وَعْدُ رَبِّى حَقًّا', '18:98'),
(2239, 18, 99, '۞ وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِى بَعْضٍ ۖ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَـٰهُمْ جَمْعًا', '18:99'),
(2240, 18, 100, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَـٰفِرِينَ عَرْضًا', '18:100'),
(2241, 18, 101, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', '18:101'),
(2242, 18, 102, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ ۚ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَـٰفِرِينَ نُزُلًا', '18:102'),
(2243, 18, 103, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَـٰلًا', '18:103'),
(2244, 18, 104, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', '18:104'),
(2245, 18, 105, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَـٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ وَزْنًا', '18:105'),
(2246, 18, 106, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَـٰتِى وَرُسُلِى هُزُوًا', '18:106'),
(2247, 18, 107, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَانَتْ لَهُمْ جَنَّـٰتُ ٱلْفِرْدَوْسِ نُزُلًا', '18:107'),
(2248, 18, 108, 'خَـٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', '18:108'),
(2249, 18, 109, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًا لِّكَلِمَـٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَـٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًا', '18:109'),
(2250, 18, 110, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۖ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًا صَـٰلِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', '18:110'),
(2251, 19, 1, ' كٓهيعٓصٓ', '19:1'),
(2252, 19, 2, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', '19:2'),
(2253, 19, 3, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا', '19:3'),
(2254, 19, 4, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا', '19:4'),
(2255, 19, 5, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا', '19:5'),
(2256, 19, 6, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ ۖ وَٱجْعَلْهُ رَبِّ رَضِيًّا', '19:6'),
(2257, 19, 7, 'يَـٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا', '19:7'),
(2258, 19, 8, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا', '19:8'),
(2259, 19, 9, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا', '19:9'),
(2260, 19, 10, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً ۚ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَ لَيَالٍ سَوِيًّا', '19:10'),
(2261, 19, 11, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا', '19:11'),
(2262, 19, 12, 'يَـٰيَحْيَىٰ خُذِ ٱلْكِتَـٰبَ بِقُوَّةٍ ۖ وَءَاتَيْنَـٰهُ ٱلْحُكْمَ صَبِيًّا', '19:12'),
(2263, 19, 13, 'وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً ۖ وَكَانَ تَقِيًّا', '19:13'),
(2264, 19, 14, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا', '19:14'),
(2265, 19, 15, 'وَسَلَـٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا', '19:15'),
(2266, 19, 16, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا', '19:16'),
(2267, 19, 17, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا', '19:17'),
(2268, 19, 18, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَـٰنِ مِنكَ إِن كُنتَ تَقِيًّا', '19:18'),
(2269, 19, 19, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَـٰمًا زَكِيًّا', '19:19'),
(2270, 19, 20, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا', '19:20'),
(2271, 19, 21, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ ۖ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا ۚ وَكَانَ أَمْرًا مَّقْضِيًّا', '19:21'),
(2272, 19, 22, '۞ فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا', '19:22'),
(2273, 19, 23, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَـٰلَيْتَنِى مِتُّ قَبْلَ هَـٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', '19:23'),
(2274, 19, 24, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', '19:24'),
(2275, 19, 25, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَـٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', '19:25'),
(2276, 19, 26, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا ۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَـٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا', '19:26'),
(2277, 19, 27, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ ۖ قَالُوا۟ يَـٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا', '19:27'),
(2278, 19, 28, 'يَـٰٓأُخْتَ هَـٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', '19:28'),
(2279, 19, 29, 'فَأَشَارَتْ إِلَيْهِ ۖ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا', '19:29'),
(2280, 19, 30, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَـٰبَ وَجَعَلَنِى نَبِيًّا', '19:30'),
(2281, 19, 31, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَـٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا', '19:31'),
(2282, 19, 32, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا', '19:32'),
(2283, 19, 33, 'وَٱلسَّلَـٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', '19:33'),
(2284, 19, 34, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ ۚ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', '19:34'),
(2285, 19, 35, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ ۖ سُبْحَـٰنَهُۥٓ ۚ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '19:35'),
(2286, 19, 36, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '19:36'),
(2287, 19, 37, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', '19:37'),
(2288, 19, 38, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا ۖ لَـٰكِنِ ٱلظَّـٰلِمُونَ ٱلْيَوْمَ فِى ضَلَـٰلٍ مُّبِينٍ', '19:38'),
(2289, 19, 39, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', '19:39'),
(2290, 19, 40, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', '19:40'),
(2291, 19, 41, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ إِبْرَٰهِيمَ ۚ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '19:41'),
(2292, 19, 42, 'إِذْ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا', '19:42'),
(2293, 19, 43, 'يَـٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا', '19:43'),
(2294, 19, 44, 'يَـٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَـٰنَ ۖ إِنَّ ٱلشَّيْطَـٰنَ كَانَ لِلرَّحْمَـٰنِ عَصِيًّا', '19:44'),
(2295, 19, 45, 'يَـٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَـٰنِ فَتَكُونَ لِلشَّيْطَـٰنِ وَلِيًّا', '19:45'),
(2296, 19, 46, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَـٰٓإِبْرَٰهِيمُ ۖ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ ۖ وَٱهْجُرْنِى مَلِيًّا', '19:46'),
(2297, 19, 47, 'قَالَ سَلَـٰمٌ عَلَيْكَ ۖ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ ۖ إِنَّهُۥ كَانَ بِى حَفِيًّا', '19:47'),
(2298, 19, 48, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا', '19:48'),
(2299, 19, 49, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ ۖ وَكُلًّا جَعَلْنَا نَبِيًّا', '19:49'),
(2300, 19, 50, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', '19:50'),
(2301, 19, 51, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ مُوسَىٰٓ ۚ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', '19:51'),
(2302, 19, 52, 'وَنَـٰدَيْنَـٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَـٰهُ نَجِيًّا', '19:52'),
(2303, 19, 53, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَـٰرُونَ نَبِيًّا', '19:53'),
(2304, 19, 54, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ إِسْمَـٰعِيلَ ۚ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', '19:54'),
(2305, 19, 55, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا', '19:55'),
(2306, 19, 56, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ إِدْرِيسَ ۚ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '19:56'),
(2307, 19, 57, 'وَرَفَعْنَـٰهُ مَكَانًا عَلِيًّا', '19:57'),
(2308, 19, 58, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ ۚ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُ ٱلرَّحْمَـٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا ۩', '19:58'),
(2309, 19, 59, '۞ فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ ۖ فَسَوْفَ يَلْقَوْنَ غَيًّا', '19:59'),
(2310, 19, 60, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحًا فَأُو۟لَـٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا', '19:60'),
(2311, 19, 61, 'جَنَّـٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَـٰنُ عِبَادَهُۥ بِٱلْغَيْبِ ۚ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا', '19:61'),
(2312, 19, 62, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَـٰمًا ۖ وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', '19:62'),
(2313, 19, 63, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', '19:63'),
(2314, 19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ ۖ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ ۚ وَمَا كَانَ رَبُّكَ نَسِيًّا', '19:64'),
(2315, 19, 65, 'رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَـٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا', '19:65'),
(2316, 19, 66, 'وَيَقُولُ ٱلْإِنسَـٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', '19:66'),
(2317, 19, 67, 'أَوَلَا يَذْكُرُ ٱلْإِنسَـٰنُ أَنَّا خَلَقْنَـٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا', '19:67'),
(2318, 19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَـٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', '19:68'),
(2319, 19, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَـٰنِ عِتِيًّا', '19:69'),
(2320, 19, 70, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', '19:70'),
(2321, 19, 71, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا ۚ كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', '19:71'),
(2322, 19, 72, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّـٰلِمِينَ فِيهَا جِثِيًّا', '19:72'),
(2323, 19, 73, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', '19:73'),
(2324, 19, 74, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَـٰثًا وَرِءْيًا', '19:74'),
(2325, 19, 75, 'قُلْ مَن كَانَ فِى ٱلضَّلَـٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَـٰنُ مَدًّا ۚ حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', '19:75'),
(2326, 19, 76, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى ۗ وَٱلْبَـٰقِيَـٰتُ ٱلصَّـٰلِحَـٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', '19:76'),
(2327, 19, 77, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَـٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', '19:77'),
(2328, 19, 78, 'أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَـٰنِ عَهْدًا', '19:78'),
(2329, 19, 79, 'كَلَّا ۚ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّا', '19:79'),
(2330, 19, 80, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًا', '19:80'),
(2331, 19, 81, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لِّيَكُونُوا۟ لَهُمْ عِزًّا', '19:81'),
(2332, 19, 82, 'كَلَّا ۚ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', '19:82'),
(2333, 19, 83, 'أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَـٰطِينَ عَلَى ٱلْكَـٰفِرِينَ تَؤُزُّهُمْ أَزًّا', '19:83'),
(2334, 19, 84, 'فَلَا تَعْجَلْ عَلَيْهِمْ ۖ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', '19:84'),
(2335, 19, 85, 'يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَـٰنِ وَفْدًا', '19:85'),
(2336, 19, 86, 'وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًا', '19:86'),
(2337, 19, 87, 'لَّا يَمْلِكُونَ ٱلشَّفَـٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَـٰنِ عَهْدًا', '19:87'),
(2338, 19, 88, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَـٰنُ وَلَدًا', '19:88'),
(2339, 19, 89, 'لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّا', '19:89'),
(2340, 19, 90, 'تَكَادُ ٱلسَّمَـٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا', '19:90'),
(2341, 19, 91, 'أَن دَعَوْا۟ لِلرَّحْمَـٰنِ وَلَدًا', '19:91'),
(2342, 19, 92, 'وَمَا يَنۢبَغِى لِلرَّحْمَـٰنِ أَن يَتَّخِذَ وَلَدًا', '19:92'),
(2343, 19, 93, 'إِن كُلُّ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَـٰنِ عَبْدًا', '19:93'),
(2344, 19, 94, 'لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّا', '19:94'),
(2345, 19, 95, 'وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَـٰمَةِ فَرْدًا', '19:95'),
(2346, 19, 96, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَـٰنُ وُدًّا', '19:96'),
(2347, 19, 97, 'فَإِنَّمَا يَسَّرْنَـٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًا لُّدًّا', '19:97'),
(2348, 19, 98, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا', '19:98'),
(2349, 20, 1, ' طه', '20:1'),
(2350, 20, 2, 'مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ', '20:2'),
(2351, 20, 3, 'إِلَّا تَذْكِرَةً لِّمَن يَخْشَىٰ', '20:3'),
(2352, 20, 4, 'تَنزِيلًا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَـٰوَٰتِ ٱلْعُلَى', '20:4'),
(2353, 20, 5, 'ٱلرَّحْمَـٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ', '20:5'),
(2354, 20, 6, 'لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ', '20:6'),
(2355, 20, 7, 'وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى', '20:7'),
(2356, 20, 8, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ', '20:8'),
(2357, 20, 9, 'وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', '20:9'),
(2358, 20, 10, 'إِذْ رَءَا نَارًا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًى', '20:10'),
(2359, 20, 11, 'فَلَمَّآ أَتَىٰهَا نُودِىَ يَـٰمُوسَىٰٓ', '20:11'),
(2360, 20, 12, 'إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', '20:12'),
(2361, 20, 13, 'وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ', '20:13'),
(2362, 20, 14, 'إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ', '20:14'),
(2363, 20, 15, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ', '20:15'),
(2364, 20, 16, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ', '20:16'),
(2365, 20, 17, 'وَمَا تِلْكَ بِيَمِينِكَ يَـٰمُوسَىٰ', '20:17'),
(2366, 20, 18, 'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ', '20:18'),
(2367, 20, 19, 'قَالَ أَلْقِهَا يَـٰمُوسَىٰ', '20:19'),
(2368, 20, 20, 'فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌ تَسْعَىٰ', '20:20'),
(2369, 20, 21, 'قَالَ خُذْهَا وَلَا تَخَفْ ۖ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ', '20:21'),
(2370, 20, 22, 'وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ', '20:22'),
(2371, 20, 23, 'لِنُرِيَكَ مِنْ ءَايَـٰتِنَا ٱلْكُبْرَى', '20:23'),
(2372, 20, 24, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', '20:24'),
(2373, 20, 25, 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', '20:25'),
(2374, 20, 26, 'وَيَسِّرْ لِىٓ أَمْرِى', '20:26'),
(2375, 20, 27, 'وَٱحْلُلْ عُقْدَةً مِّن لِّسَانِى', '20:27'),
(2376, 20, 28, 'يَفْقَهُوا۟ قَوْلِى', '20:28'),
(2377, 20, 29, 'وَٱجْعَل لِّى وَزِيرًا مِّنْ أَهْلِى', '20:29'),
(2378, 20, 30, 'هَـٰرُونَ أَخِى', '20:30'),
(2379, 20, 31, 'ٱشْدُدْ بِهِۦٓ أَزْرِى', '20:31'),
(2380, 20, 32, 'وَأَشْرِكْهُ فِىٓ أَمْرِى', '20:32'),
(2381, 20, 33, 'كَىْ نُسَبِّحَكَ كَثِيرًا', '20:33'),
(2382, 20, 34, 'وَنَذْكُرَكَ كَثِيرًا', '20:34'),
(2383, 20, 35, 'إِنَّكَ كُنتَ بِنَا بَصِيرًا', '20:35'),
(2384, 20, 36, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَـٰمُوسَىٰ', '20:36'),
(2385, 20, 37, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', '20:37'),
(2386, 20, 38, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', '20:38'),
(2387, 20, 39, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ ۚ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', '20:39'),
(2388, 20, 40, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ ۖ فَرَجَعْنَـٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ ۚ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَـٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّـٰكَ فُتُونًا ۚ فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَـٰمُوسَىٰ', '20:40'),
(2389, 20, 41, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', '20:41'),
(2390, 20, 42, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَـٰتِى وَلَا تَنِيَا فِى ذِكْرِى', '20:42'),
(2391, 20, 43, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', '20:43'),
(2392, 20, 44, 'فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', '20:44'),
(2393, 20, 45, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', '20:45'),
(2394, 20, 46, 'قَالَ لَا تَخَافَآ ۖ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', '20:46'),
(2395, 20, 47, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ ۖ قَدْ جِئْنَـٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ ۖ وَٱلسَّلَـٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', '20:47'),
(2396, 20, 48, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', '20:48'),
(2397, 20, 49, 'قَالَ فَمَن رَّبُّكُمَا يَـٰمُوسَىٰ', '20:49'),
(2398, 20, 50, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', '20:50'),
(2399, 20, 51, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', '20:51'),
(2400, 20, 52, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَـٰبٍ ۖ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', '20:52'),
(2401, 20, 53, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ', '20:53'),
(2402, 20, 54, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَـٰمَكُمْ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '20:54'),
(2403, 20, 55, '۞ مِنْهَا خَلَقْنَـٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', '20:55'),
(2404, 20, 56, 'وَلَقَدْ أَرَيْنَـٰهُ ءَايَـٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', '20:56'),
(2405, 20, 57, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَـٰمُوسَىٰ', '20:57'),
(2406, 20, 58, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى', '20:58'),
(2407, 20, 59, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى', '20:59'),
(2408, 20, 60, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', '20:60'),
(2409, 20, 61, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ ۖ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', '20:61'),
(2410, 20, 62, 'فَتَنَـٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', '20:62'),
(2411, 20, 63, 'قَالُوٓا۟ إِنْ هَـٰذَٰنِ لَسَـٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', '20:63'),
(2412, 20, 64, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا ۚ وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', '20:64'),
(2413, 20, 65, 'قَالُوا۟ يَـٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', '20:65'),
(2414, 20, 66, 'قَالَ بَلْ أَلْقُوا۟ ۖ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', '20:66'),
(2415, 20, 67, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ', '20:67'),
(2416, 20, 68, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', '20:68'),
(2417, 20, 69, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ ۖ إِنَّمَا صَنَعُوا۟ كَيْدُ سَـٰحِرٍ ۖ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', '20:69'),
(2418, 20, 70, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَـٰرُونَ وَمُوسَىٰ', '20:70'),
(2419, 20, 71, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ ۖ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ', '20:71'),
(2420, 20, 72, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَـٰتِ وَٱلَّذِى فَطَرَنَا ۖ فَٱقْضِ مَآ أَنتَ قَاضٍ ۖ إِنَّمَا تَقْضِى هَـٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', '20:72'),
(2421, 20, 73, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَـٰيَـٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ ۗ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ', '20:73'),
(2422, 20, 74, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', '20:74'),
(2423, 20, 75, 'وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّـٰلِحَـٰتِ فَأُو۟لَـٰٓئِكَ لَهُمُ ٱلدَّرَجَـٰتُ ٱلْعُلَىٰ', '20:75'),
(2424, 20, 76, 'جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', '20:76'),
(2425, 20, 77, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَـٰفُ دَرَكًا وَلَا تَخْشَىٰ', '20:77'),
(2426, 20, 78, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', '20:78'),
(2427, 20, 79, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', '20:79'),
(2428, 20, 80, 'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَـٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَـٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', '20:80'),
(2429, 20, 81, 'كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى ۖ وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', '20:81'),
(2430, 20, 82, 'وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحًا ثُمَّ ٱهْتَدَىٰ', '20:82'),
(2431, 20, 83, '۞ وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَـٰمُوسَىٰ', '20:83'),
(2432, 20, 84, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', '20:84'),
(2433, 20, 85, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', '20:85'),
(2434, 20, 86, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَـٰنَ أَسِفًا ۚ قَالَ يَـٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا ۚ أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', '20:86'),
(2435, 20, 87, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَـٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَـٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', '20:87'),
(2436, 20, 88, 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَـٰذَآ إِلَـٰهُكُمْ وَإِلَـٰهُ مُوسَىٰ فَنَسِىَ', '20:88'),
(2437, 20, 89, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', '20:89'),
(2438, 20, 90, 'وَلَقَدْ قَالَ لَهُمْ هَـٰرُونُ مِن قَبْلُ يَـٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ ۖ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَـٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', '20:90'),
(2439, 20, 91, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَـٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', '20:91'),
(2440, 20, 92, 'قَالَ يَـٰهَـٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', '20:92'),
(2441, 20, 93, 'أَلَّا تَتَّبِعَنِ ۖ أَفَعَصَيْتَ أَمْرِى', '20:93'),
(2442, 20, 94, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ ۖ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', '20:94'),
(2443, 20, 95, 'قَالَ فَمَا خَطْبُكَ يَـٰسَـٰمِرِىُّ', '20:95'),
(2444, 20, 96, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', '20:96'),
(2445, 20, 97, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ ۖ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ ۖ وَٱنظُرْ إِلَىٰٓ إِلَـٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا ۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', '20:97'),
(2446, 20, 98, 'إِنَّمَآ إِلَـٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ۚ وَسِعَ كُلَّ شَىْءٍ عِلْمًا', '20:98'),
(2447, 20, 99, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ ۚ وَقَدْ ءَاتَيْنَـٰكَ مِن لَّدُنَّا ذِكْرًا', '20:99'),
(2448, 20, 100, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَـٰمَةِ وِزْرًا', '20:100'),
(2449, 20, 101, 'خَـٰلِدِينَ فِيهِ ۖ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ حِمْلًا', '20:101'),
(2450, 20, 102, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', '20:102'),
(2451, 20, 103, 'يَتَخَـٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', '20:103'),
(2452, 20, 104, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', '20:104'),
(2453, 20, 105, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا', '20:105'),
(2454, 20, 106, 'فَيَذَرُهَا قَاعًا صَفْصَفًا', '20:106'),
(2455, 20, 107, 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا', '20:107'),
(2456, 20, 108, 'يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ ۖ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَـٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', '20:108'),
(2457, 20, 109, 'يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَـٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَرَضِىَ لَهُۥ قَوْلًا', '20:109'),
(2458, 20, 110, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا', '20:110'),
(2459, 20, 111, '۞ وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ ۖ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', '20:111'),
(2460, 20, 112, 'وَمَن يَعْمَلْ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', '20:112'),
(2461, 20, 113, 'وَكَذَٰلِكَ أَنزَلْنَـٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', '20:113'),
(2462, 20, 114, 'فَتَعَـٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۗ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ ۖ وَقُل رَّبِّ زِدْنِى عِلْمًا', '20:114'),
(2463, 20, 115, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا', '20:115'),
(2464, 20, 116, 'وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', '20:116'),
(2465, 20, 117, 'فَقُلْنَا يَـٰٓـَٔادَمُ إِنَّ هَـٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', '20:117'),
(2466, 20, 118, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', '20:118'),
(2467, 20, 119, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', '20:119'),
(2468, 20, 120, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَـٰنُ قَالَ يَـٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', '20:120'),
(2469, 20, 121, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', '20:121'),
(2470, 20, 122, 'ثُمَّ ٱجْتَبَـٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', '20:122'),
(2471, 20, 123, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا ۖ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', '20:123'),
(2472, 20, 124, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَـٰمَةِ أَعْمَىٰ', '20:124'),
(2473, 20, 125, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', '20:125'),
(2474, 20, 126, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَـٰتُنَا فَنَسِيتَهَا ۖ وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', '20:126'),
(2475, 20, 127, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَـٰتِ رَبِّهِۦ ۚ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', '20:127'),
(2476, 20, 128, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَـٰكِنِهِمْ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '20:128'),
(2477, 20, 129, 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', '20:129'),
(2478, 20, 130, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا ۖ وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', '20:130'),
(2479, 20, 131, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ ۚ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', '20:131'),
(2480, 20, 132, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا ۖ لَا نَسْـَٔلُكَ رِزْقًا ۖ نَّحْنُ نَرْزُقُكَ ۗ وَٱلْعَـٰقِبَةُ لِلتَّقْوَىٰ', '20:132'),
(2481, 20, 133, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ ۚ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', '20:133'),
(2482, 20, 134, 'وَلَوْ أَنَّآ أَهْلَكْنَـٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَـٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', '20:134'),
(2483, 20, 135, 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ ۖ فَسَتَعْلَمُونَ مَنْ أَصْحَـٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', '20:135'),
(2484, 21, 1, ' ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ', '21:1'),
(2485, 21, 2, 'مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', '21:2'),
(2486, 21, 3, 'لَاهِيَةً قُلُوبُهُمْ ۗ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَـٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ ۖ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', '21:3'),
(2487, 21, 4, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '21:4'),
(2488, 21, 5, 'بَلْ قَالُوٓا۟ أَضْغَـٰثُ أَحْلَـٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', '21:5'),
(2489, 21, 6, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَآ ۖ أَفَهُمْ يُؤْمِنُونَ', '21:6'),
(2490, 21, 7, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ ۖ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', '21:7'),
(2491, 21, 8, 'وَمَا جَعَلْنَـٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَـٰلِدِينَ', '21:8'),
(2492, 21, 9, 'ثُمَّ صَدَقْنَـٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَـٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', '21:9'),
(2493, 21, 10, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَـٰبًا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ', '21:10'),
(2494, 21, 11, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', '21:11'),
(2495, 21, 12, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', '21:12'),
(2496, 21, 13, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَـٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', '21:13'),
(2497, 21, 14, 'قَالُوا۟ يَـٰوَيْلَنَآ إِنَّا كُنَّا ظَـٰلِمِينَ', '21:14'),
(2498, 21, 15, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَـٰهُمْ حَصِيدًا خَـٰمِدِينَ', '21:15'),
(2499, 21, 16, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَـٰعِبِينَ', '21:16'),
(2500, 21, 17, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَـٰهُ مِن لَّدُنَّآ إِن كُنَّا فَـٰعِلِينَ', '21:17'),
(2501, 21, 18, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَـٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ ۚ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', '21:18'),
(2502, 21, 19, 'وَلَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', '21:19'),
(2503, 21, 20, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', '21:20'),
(2504, 21, 21, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', '21:21'),
(2505, 21, 22, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', '21:22'),
(2506, 21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', '21:23'),
(2507, 21, 24, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً ۖ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ ۖ هَـٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى ۗ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ ۖ فَهُم مُّعْرِضُونَ', '21:24'),
(2508, 21, 25, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', '21:25'),
(2509, 21, 26, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَـٰنُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۚ بَلْ عِبَادٌ مُّكْرَمُونَ', '21:26'),
(2510, 21, 27, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', '21:27'),
(2511, 21, 28, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', '21:28'),
(2512, 21, 29, '۞ وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَـٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ', '21:29'),
(2513, 21, 30, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَـٰهُمَا ۖ وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ ۖ أَفَلَا يُؤْمِنُونَ', '21:30'),
(2514, 21, 31, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', '21:31'),
(2515, 21, 32, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا ۖ وَهُمْ عَنْ ءَايَـٰتِهَا مُعْرِضُونَ', '21:32'),
(2516, 21, 33, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ', '21:33'),
(2517, 21, 34, 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ ۖ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَـٰلِدُونَ', '21:34'),
(2518, 21, 35, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً ۖ وَإِلَيْنَا تُرْجَعُونَ', '21:35'),
(2519, 21, 36, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَـٰنِ هُمْ كَـٰفِرُونَ', '21:36'),
(2520, 21, 37, 'خُلِقَ ٱلْإِنسَـٰنُ مِنْ عَجَلٍ ۚ سَأُو۟رِيكُمْ ءَايَـٰتِى فَلَا تَسْتَعْجِلُونِ', '21:37'),
(2521, 21, 38, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '21:38'),
(2522, 21, 39, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', '21:39'),
(2523, 21, 40, 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', '21:40'),
(2524, 21, 41, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '21:41'),
(2525, 21, 42, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَـٰنِ ۗ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', '21:42'),
(2526, 21, 43, 'أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا ۚ لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', '21:43'),
(2527, 21, 44, 'بَلْ مَتَّعْنَا هَـٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ ۗ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ ۚ أَفَهُمُ ٱلْغَـٰلِبُونَ', '21:44'),
(2528, 21, 45, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ ۚ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', '21:45'),
(2529, 21, 46, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَـٰوَيْلَنَآ إِنَّا كُنَّا ظَـٰلِمِينَ', '21:46'),
(2530, 21, 47, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَـٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَـٰسِبِينَ', '21:47'),
(2531, 21, 48, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَـٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ', '21:48'),
(2532, 21, 49, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', '21:49'),
(2533, 21, 50, 'وَهَـٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَـٰهُ ۚ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', '21:50'),
(2534, 21, 51, '۞ وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَـٰلِمِينَ', '21:51'),
(2535, 21, 52, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَـٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَـٰكِفُونَ', '21:52'),
(2536, 21, 53, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَـٰبِدِينَ', '21:53'),
(2537, 21, 54, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَـٰلٍ مُّبِينٍ', '21:54'),
(2538, 21, 55, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّـٰعِبِينَ', '21:55'),
(2539, 21, 56, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّـٰهِدِينَ', '21:56'),
(2540, 21, 57, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَـٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', '21:57'),
(2541, 21, 58, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', '21:58'),
(2542, 21, 59, 'قَالُوا۟ مَن فَعَلَ هَـٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِينَ', '21:59'),
(2543, 21, 60, 'قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', '21:60'),
(2544, 21, 61, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', '21:61'),
(2545, 21, 62, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَـٰذَا بِـَٔالِهَتِنَا يَـٰٓإِبْرَٰهِيمُ', '21:62'),
(2546, 21, 63, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَـٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', '21:63'),
(2547, 21, 64, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّـٰلِمُونَ', '21:64'),
(2548, 21, 65, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَـٰٓؤُلَآءِ يَنطِقُونَ', '21:65'),
(2549, 21, 66, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ', '21:66'),
(2550, 21, 67, 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ ۖ أَفَلَا تَعْقِلُونَ', '21:67'),
(2551, 21, 68, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَـٰعِلِينَ', '21:68'),
(2552, 21, 69, 'قُلْنَا يَـٰنَارُ كُونِى بَرْدًا وَسَلَـٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', '21:69'),
(2553, 21, 70, 'وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَـٰهُمُ ٱلْأَخْسَرِينَ', '21:70'),
(2554, 21, 71, 'وَنَجَّيْنَـٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَـٰرَكْنَا فِيهَا لِلْعَـٰلَمِينَ', '21:71'),
(2555, 21, 72, 'وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ نَافِلَةً ۖ وَكُلًّا جَعَلْنَا صَـٰلِحِينَ', '21:72'),
(2556, 21, 73, 'وَجَعَلْنَـٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ ۖ وَكَانُوا۟ لَنَا عَـٰبِدِينَ', '21:73'),
(2557, 21, 74, 'وَلُوطًا ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَـٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَـٰٓئِثَ ۗ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَـٰسِقِينَ', '21:74'),
(2558, 21, 75, 'وَأَدْخَلْنَـٰهُ فِى رَحْمَتِنَآ ۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِينَ', '21:75'),
(2559, 21, 76, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَـٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', '21:76'),
(2560, 21, 77, 'وَنَصَرْنَـٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَـٰهُمْ أَجْمَعِينَ', '21:77'),
(2561, 21, 78, 'وَدَاوُۥدَ وَسُلَيْمَـٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَـٰهِدِينَ', '21:78'),
(2562, 21, 79, 'فَفَهَّمْنَـٰهَا سُلَيْمَـٰنَ ۚ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا ۚ وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ ۚ وَكُنَّا فَـٰعِلِينَ', '21:79'),
(2563, 21, 80, 'وَعَلَّمْنَـٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ ۖ فَهَلْ أَنتُمْ شَـٰكِرُونَ', '21:80'),
(2564, 21, 81, 'وَلِسُلَيْمَـٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَـٰرَكْنَا فِيهَا ۚ وَكُنَّا بِكُلِّ شَىْءٍ عَـٰلِمِينَ', '21:81'),
(2565, 21, 82, 'وَمِنَ ٱلشَّيَـٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ ۖ وَكُنَّا لَهُمْ حَـٰفِظِينَ', '21:82'),
(2566, 21, 83, '۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', '21:83'),
(2567, 21, 84, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ ۖ وَءَاتَيْنَـٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَـٰبِدِينَ', '21:84'),
(2568, 21, 85, 'وَإِسْمَـٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ ۖ كُلٌّ مِّنَ ٱلصَّـٰبِرِينَ', '21:85'),
(2569, 21, 86, 'وَأَدْخَلْنَـٰهُمْ فِى رَحْمَتِنَآ ۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِينَ', '21:86'),
(2570, 21, 87, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَـٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَـٰتِ أَن لَّآ إِلَـٰهَ إِلَّآ أَنتَ سُبْحَـٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّـٰلِمِينَ', '21:87'),
(2571, 21, 88, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَـٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُـۨجِى ٱلْمُؤْمِنِينَ', '21:88'),
(2572, 21, 89, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', '21:89'),
(2573, 21, 90, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ ۚ إِنَّهُمْ كَانُوا۟ يُسَـٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا ۖ وَكَانُوا۟ لَنَا خَـٰشِعِينَ', '21:90'),
(2574, 21, 91, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَـٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَـٰلَمِينَ', '21:91'),
(2575, 21, 92, 'إِنَّ هَـٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', '21:92'),
(2576, 21, 93, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ ۖ كُلٌّ إِلَيْنَا رَٰجِعُونَ', '21:93'),
(2577, 21, 94, 'فَمَن يَعْمَلْ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَـٰتِبُونَ', '21:94'),
(2578, 21, 95, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَـٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', '21:95'),
(2579, 21, 96, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', '21:96'),
(2580, 21, 97, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَـٰخِصَةٌ أَبْصَـٰرُ ٱلَّذِينَ كَفَرُوا۟ يَـٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَـٰذَا بَلْ كُنَّا ظَـٰلِمِينَ', '21:97'),
(2581, 21, 98, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', '21:98'),
(2582, 21, 99, 'لَوْ كَانَ هَـٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا ۖ وَكُلٌّ فِيهَا خَـٰلِدُونَ', '21:99'),
(2583, 21, 100, 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', '21:100'),
(2584, 21, 101, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَـٰٓئِكَ عَنْهَا مُبْعَدُونَ', '21:101'),
(2585, 21, 102, 'لَا يَسْمَعُونَ حَسِيسَهَا ۖ وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَـٰلِدُونَ', '21:102'),
(2586, 21, 103, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ هَـٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', '21:103'),
(2587, 21, 104, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ ۚ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ ۚ وَعْدًا عَلَيْنَآ ۚ إِنَّا كُنَّا فَـٰعِلِينَ', '21:104'),
(2588, 21, 105, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّـٰلِحُونَ', '21:105'),
(2589, 21, 106, 'إِنَّ فِى هَـٰذَا لَبَلَـٰغًا لِّقَوْمٍ عَـٰبِدِينَ', '21:106'),
(2590, 21, 107, 'وَمَآ أَرْسَلْنَـٰكَ إِلَّا رَحْمَةً لِّلْعَـٰلَمِينَ', '21:107'),
(2591, 21, 108, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', '21:108'),
(2592, 21, 109, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ ۖ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', '21:109'),
(2593, 21, 110, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', '21:110'),
(2594, 21, 111, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَـٰعٌ إِلَىٰ حِينٍ', '21:111'),
(2595, 21, 112, 'قَـٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ ۗ وَرَبُّنَا ٱلرَّحْمَـٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '21:112'),
(2596, 22, 1, ' يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ', '22:1'),
(2597, 22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَـٰرَىٰ وَمَا هُم بِسُكَـٰرَىٰ وَلَـٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ', '22:2'),
(2598, 22, 3, 'وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَـٰنٍ مَّرِيدٍ', '22:3'),
(2599, 22, 4, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', '22:4'),
(2600, 22, 5, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَـٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ ۚ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا ۚ وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ', '22:5'),
(2601, 22, 6, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '22:6'),
(2602, 22, 7, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', '22:7'),
(2603, 22, 8, 'وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَـٰبٍ مُّنِيرٍ', '22:8'),
(2604, 22, 9, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ ۖ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَـٰمَةِ عَذَابَ ٱلْحَرِيقِ', '22:9'),
(2605, 22, 10, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّـٰمٍ لِّلْعَبِيدِ', '22:10'),
(2606, 22, 11, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍ ۖ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْـَٔاخِرَةَ ۚ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '22:11'),
(2607, 22, 12, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ۚ ذَٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلْبَعِيدُ', '22:12'),
(2608, 22, 13, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ ۚ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', '22:13'),
(2609, 22, 14, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '22:14'),
(2610, 22, 15, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', '22:15'),
(2611, 22, 16, 'وَكَذَٰلِكَ أَنزَلْنَـٰهُ ءَايَـٰتٍۭ بَيِّنَـٰتٍ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', '22:16'),
(2612, 22, 17, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّـٰبِـِٔينَ وَٱلنَّصَـٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '22:17'),
(2613, 22, 18, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌ مِّنَ ٱلنَّاسِ ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ ۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ ۩', '22:18'),
(2614, 22, 19, '۞ هَـٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ ۖ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', '22:19'),
(2615, 22, 20, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', '22:20'),
(2616, 22, 21, 'وَلَهُم مَّقَـٰمِعُ مِنْ حَدِيدٍ', '22:21'),
(2617, 22, 22, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '22:22'),
(2618, 22, 23, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا ۖ وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', '22:23'),
(2619, 22, 24, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', '22:24'),
(2620, 22, 25, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَـٰهُ لِلنَّاسِ سَوَآءً ٱلْعَـٰكِفُ فِيهِ وَٱلْبَادِ ۚ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', '22:25'),
(2621, 22, 26, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', '22:26'),
(2622, 22, 27, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', '22:27'),
(2623, 22, 28, 'لِّيَشْهَدُوا۟ مَنَـٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَـٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَـٰمِ ۖ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', '22:28'),
(2624, 22, 29, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', '22:29'),
(2625, 22, 30, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَـٰتِ ٱللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ ۗ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَـٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ ۖ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَـٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', '22:30'),
(2626, 22, 31, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍ سَحِيقٍ', '22:31'),
(2627, 22, 32, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَـٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', '22:32'),
(2628, 22, 33, 'لَكُمْ فِيهَا مَنَـٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', '22:33'),
(2629, 22, 34, 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَـٰمِ ۗ فَإِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا۟ ۗ وَبَشِّرِ ٱلْمُخْبِتِينَ', '22:34'),
(2630, 22, 35, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّـٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '22:35'),
(2631, 22, 36, 'وَٱلْبُدْنَ جَعَلْنَـٰهَا لَكُم مِّن شَعَـٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌ ۖ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ ۖ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ ۚ كَذَٰلِكَ سَخَّرْنَـٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '22:36'),
(2632, 22, 37, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَـٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ ۚ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ ۗ وَبَشِّرِ ٱلْمُحْسِنِينَ', '22:37'),
(2633, 22, 38, '۞ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', '22:38'),
(2634, 22, 39, 'أُذِنَ لِلَّذِينَ يُقَـٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', '22:39'),
(2635, 22, 40, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَـٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَـٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًا ۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', '22:40'),
(2636, 22, 41, 'ٱلَّذِينَ إِن مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ ۗ وَلِلَّهِ عَـٰقِبَةُ ٱلْأُمُورِ', '22:41'),
(2637, 22, 42, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', '22:42'),
(2638, 22, 43, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ', '22:43'),
(2639, 22, 44, 'وَأَصْحَـٰبُ مَدْيَنَ ۖ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَـٰفِرِينَ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ نَكِيرِ', '22:44'),
(2640, 22, 45, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَـٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', '22:45'),
(2641, 22, 46, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَـٰرُ وَلَـٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', '22:46'),
(2642, 22, 47, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ ۚ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', '22:47'),
(2643, 22, 48, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', '22:48'),
(2644, 22, 49, 'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ', '22:49'),
(2645, 22, 50, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '22:50'),
(2646, 22, 51, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَـٰتِنَا مُعَـٰجِزِينَ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', '22:51'),
(2647, 22, 52, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَـٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَـٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَـٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '22:52'),
(2648, 22, 53, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَـٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْقَاسِيَةِ قُلُوبُهُمْ ۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍ', '22:53'),
(2649, 22, 54, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ ۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '22:54'),
(2650, 22, 55, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', '22:55'),
(2651, 22, 56, 'ٱلْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِى جَنَّـٰتِ ٱلنَّعِيمِ', '22:56'),
(2652, 22, 57, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا فَأُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', '22:57'),
(2653, 22, 58, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًا ۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', '22:58'),
(2654, 22, 59, 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ ۗ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌ', '22:59'),
(2655, 22, 60, '۞ ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '22:60'),
(2656, 22, 61, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '22:61'),
(2657, 22, 62, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '22:62'),
(2658, 22, 63, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً ۗ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', '22:63'),
(2659, 22, 64, 'لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '22:64'),
(2660, 22, 65, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ ۗ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '22:65'),
(2661, 22, 66, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۗ إِنَّ ٱلْإِنسَـٰنَ لَكَفُورٌ', '22:66'),
(2662, 22, 67, 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ ۖ فَلَا يُنَـٰزِعُنَّكَ فِى ٱلْأَمْرِ ۚ وَٱدْعُ إِلَىٰ رَبِّكَ ۖ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', '22:67'),
(2663, 22, 68, 'وَإِن جَـٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', '22:68'),
(2664, 22, 69, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '22:69'),
(2665, 22, 70, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَـٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '22:70'),
(2666, 22, 71, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ ۗ وَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٍ', '22:71'),
(2667, 22, 72, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ ۖ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَـٰتِنَا ۗ قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ ۗ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ ۖ وَبِئْسَ ٱلْمَصِيرُ', '22:72'),
(2668, 22, 73, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ ۚ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ ۖ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ۚ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', '22:73'),
(2669, 22, 74, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', '22:74'),
(2670, 22, 75, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَـٰٓئِكَةِ رُسُلًا وَمِنَ ٱلنَّاسِ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '22:75'),
(2671, 22, 76, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '22:76'),
(2672, 22, 77, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ ۩', '22:77'),
(2673, 22, 78, 'وَجَـٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ ۚ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍ ۚ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ ۚ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَـٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ ۚ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ ۖ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', '22:78'),
(2674, 23, 1, ' قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', '23:1'),
(2675, 23, 2, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَـٰشِعُونَ', '23:2'),
(2676, 23, 3, 'وَٱلَّذِينَ هُمْ عَنِ ٱللَّغْوِ مُعْرِضُونَ', '23:3'),
(2677, 23, 4, 'وَٱلَّذِينَ هُمْ لِلزَّكَوٰةِ فَـٰعِلُونَ', '23:4'),
(2678, 23, 5, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَـٰفِظُونَ', '23:5'),
(2679, 23, 6, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', '23:6'),
(2680, 23, 7, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْعَادُونَ', '23:7'),
(2681, 23, 8, 'وَٱلَّذِينَ هُمْ لِأَمَـٰنَـٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', '23:8'),
(2682, 23, 9, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', '23:9'),
(2683, 23, 10, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْوَٰرِثُونَ', '23:10'),
(2684, 23, 11, 'ٱلَّذِينَ يَرِثُونَ ٱلْفِرْدَوْسَ هُمْ فِيهَا خَـٰلِدُونَ', '23:11'),
(2685, 23, 12, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ مِن سُلَـٰلَةٍ مِّن طِينٍ', '23:12'),
(2686, 23, 13, 'ثُمَّ جَعَلْنَـٰهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ', '23:13'),
(2687, 23, 14, 'ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةً فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةً فَخَلَقْنَا ٱلْمُضْغَةَ عِظَـٰمًا فَكَسَوْنَا ٱلْعِظَـٰمَ لَحْمًا ثُمَّ أَنشَأْنَـٰهُ خَلْقًا ءَاخَرَ ۚ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَـٰلِقِينَ', '23:14'),
(2688, 23, 15, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', '23:15'),
(2689, 23, 16, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَـٰمَةِ تُبْعَثُونَ', '23:16'),
(2690, 23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَـٰفِلِينَ', '23:17'),
(2691, 23, 18, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَسْكَنَّـٰهُ فِى ٱلْأَرْضِ ۖ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَـٰدِرُونَ', '23:18'),
(2692, 23, 19, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّـٰتٍ مِّن نَّخِيلٍ وَأَعْنَـٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '23:19'),
(2693, 23, 20, 'وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍ لِّلْـَٔاكِلِينَ', '23:20'),
(2694, 23, 21, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَـٰمِ لَعِبْرَةً ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَـٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '23:21'),
(2695, 23, 22, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', '23:22'),
(2696, 23, 23, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', '23:23'),
(2697, 23, 24, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَـٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَـٰٓئِكَةً مَّا سَمِعْنَا بِهَـٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '23:24'),
(2698, 23, 25, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍ', '23:25'),
(2699, 23, 26, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', '23:26'),
(2700, 23, 27, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ ۙ فَٱسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ ۖ وَلَا تُخَـٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۖ إِنَّهُم مُّغْرَقُونَ', '23:27'),
(2701, 23, 28, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '23:28'),
(2702, 23, 29, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', '23:29'),
(2703, 23, 30, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ', '23:30'),
(2704, 23, 31, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '23:31'),
(2705, 23, 32, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', '23:32'),
(2706, 23, 33, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْـَٔاخِرَةِ وَأَتْرَفْنَـٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَـٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', '23:33'),
(2707, 23, 34, 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَـٰسِرُونَ', '23:34'),
(2708, 23, 35, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَـٰمًا أَنَّكُم مُّخْرَجُونَ', '23:35'),
(2709, 23, 36, '۞ هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', '23:36'),
(2710, 23, 37, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '23:37'),
(2711, 23, 38, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', '23:38'),
(2712, 23, 39, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', '23:39'),
(2713, 23, 40, 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَـٰدِمِينَ', '23:40'),
(2714, 23, 41, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَـٰهُمْ غُثَآءً ۚ فَبُعْدًا لِّلْقَوْمِ ٱلظَّـٰلِمِينَ', '23:41'),
(2715, 23, 42, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', '23:42'),
(2716, 23, 43, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '23:43'),
(2717, 23, 44, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا ۖ كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ ۚ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَـٰهُمْ أَحَادِيثَ ۚ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', '23:44'),
(2718, 23, 45, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَـٰرُونَ بِـَٔايَـٰتِنَا وَسُلْطَـٰنٍ مُّبِينٍ', '23:45'),
(2719, 23, 46, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', '23:46'),
(2720, 23, 47, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَـٰبِدُونَ', '23:47'),
(2721, 23, 48, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', '23:48'),
(2722, 23, 49, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ لَعَلَّهُمْ يَهْتَدُونَ', '23:49'),
(2723, 23, 50, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَـٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', '23:50'),
(2724, 23, 51, 'يَـٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَـٰتِ وَٱعْمَلُوا۟ صَـٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ', '23:51'),
(2725, 23, 52, 'وَإِنَّ هَـٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', '23:52'),
(2726, 23, 53, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '23:53'),
(2727, 23, 54, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', '23:54'),
(2728, 23, 55, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ', '23:55'),
(2729, 23, 56, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ ۚ بَل لَّا يَشْعُرُونَ', '23:56'),
(2730, 23, 57, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', '23:57'),
(2731, 23, 58, 'وَٱلَّذِينَ هُم بِـَٔايَـٰتِ رَبِّهِمْ يُؤْمِنُونَ', '23:58'),
(2732, 23, 59, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', '23:59'),
(2733, 23, 60, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', '23:60'),
(2734, 23, 61, 'أُو۟لَـٰٓئِكَ يُسَـٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَـٰبِقُونَ', '23:61'),
(2735, 23, 62, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَلَدَيْنَا كِتَـٰبٌ يَنطِقُ بِٱلْحَقِّ ۚ وَهُمْ لَا يُظْلَمُونَ', '23:62'),
(2736, 23, 63, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَـٰذَا وَلَهُمْ أَعْمَـٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَـٰمِلُونَ', '23:63'),
(2737, 23, 64, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', '23:64'),
(2738, 23, 65, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ ۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', '23:65'),
(2739, 23, 66, 'قَدْ كَانَتْ ءَايَـٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ تَنكِصُونَ', '23:66'),
(2740, 23, 67, 'مُسْتَكْبِرِينَ بِهِۦ سَـٰمِرًا تَهْجُرُونَ', '23:67'),
(2741, 23, 68, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', '23:68'),
(2742, 23, 69, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', '23:69'),
(2743, 23, 70, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ ۚ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَـٰرِهُونَ', '23:70'),
(2744, 23, 71, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ بَلْ أَتَيْنَـٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', '23:71'),
(2745, 23, 72, 'أَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', '23:72'),
(2746, 23, 73, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '23:73'),
(2747, 23, 74, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَـٰكِبُونَ', '23:74'),
(2748, 23, 75, '۞ وَلَوْ رَحِمْنَـٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا۟ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', '23:75'),
(2749, 23, 76, 'وَلَقَدْ أَخَذْنَـٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', '23:76'),
(2750, 23, 77, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', '23:77'),
(2751, 23, 78, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًا مَّا تَشْكُرُونَ', '23:78'),
(2752, 23, 79, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', '23:79'),
(2753, 23, 80, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَـٰفُ ٱلَّيْلِ وَٱلنَّهَارِ ۚ أَفَلَا تَعْقِلُونَ', '23:80'),
(2754, 23, 81, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', '23:81'),
(2755, 23, 82, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ', '23:82'),
(2756, 23, 83, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَـٰذَا مِن قَبْلُ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '23:83'),
(2757, 23, 84, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', '23:84'),
(2758, 23, 85, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَذَكَّرُونَ', '23:85'),
(2759, 23, 86, 'قُلْ مَن رَّبُّ ٱلسَّمَـٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', '23:86'),
(2760, 23, 87, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَتَّقُونَ', '23:87'),
(2761, 23, 88, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', '23:88'),
(2762, 23, 89, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ فَأَنَّىٰ تُسْحَرُونَ', '23:89'),
(2763, 23, 90, 'بَلْ أَتَيْنَـٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَـٰذِبُونَ', '23:90'),
(2764, 23, 91, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَـٰهٍ ۚ إِذًا لَّذَهَبَ كُلُّ إِلَـٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', '23:91'),
(2765, 23, 92, 'عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '23:92'),
(2766, 23, 93, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', '23:93'),
(2767, 23, 94, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '23:94'),
(2768, 23, 95, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَـٰدِرُونَ', '23:95'),
(2769, 23, 96, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ ۚ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', '23:96'),
(2770, 23, 97, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَـٰطِينِ', '23:97'),
(2771, 23, 98, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', '23:98'),
(2772, 23, 99, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', '23:99'),
(2773, 23, 100, 'لَعَلِّىٓ أَعْمَلُ صَـٰلِحًا فِيمَا تَرَكْتُ ۚ كَلَّآ ۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا ۖ وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', '23:100'),
(2774, 23, 101, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ', '23:101'),
(2775, 23, 102, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '23:102'),
(2776, 23, 103, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فِى جَهَنَّمَ خَـٰلِدُونَ', '23:103'),
(2777, 23, 104, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَـٰلِحُونَ', '23:104'),
(2778, 23, 105, 'أَلَمْ تَكُنْ ءَايَـٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', '23:105'),
(2779, 23, 106, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ', '23:106'),
(2780, 23, 107, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَـٰلِمُونَ', '23:107'),
(2781, 23, 108, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', '23:108'),
(2782, 23, 109, 'إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', '23:109'),
(2783, 23, 110, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', '23:110'),
(2784, 23, 111, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', '23:111'),
(2785, 23, 112, 'قَـٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', '23:112'),
(2786, 23, 113, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ ٱلْعَآدِّينَ', '23:113'),
(2787, 23, 114, 'قَـٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا ۖ لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', '23:114'),
(2788, 23, 115, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَـٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', '23:115'),
(2789, 23, 116, 'فَتَعَـٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', '23:116'),
(2790, 23, 117, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ لَا بُرْهَـٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَـٰفِرُونَ', '23:117'),
(2791, 23, 118, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', '23:118'),
(2792, 24, 1, ' سُورَةٌ أَنزَلْنَـٰهَا وَفَرَضْنَـٰهَا وَأَنزَلْنَا فِيهَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', '24:1'),
(2793, 24, 2, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍ ۖ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ ٱلْمُؤْمِنِينَ', '24:2'),
(2794, 24, 3, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ ۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', '24:3'),
(2795, 24, 4, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَـٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَـٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَـٰدَةً أَبَدًا ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', '24:4'),
(2796, 24, 5, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '24:5'),
(2797, 24, 6, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَـٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَـٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ', '24:6'),
(2798, 24, 7, 'وَٱلْخَـٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَـٰذِبِينَ', '24:7'),
(2799, 24, 8, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَـٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلْكَـٰذِبِينَ', '24:8'),
(2800, 24, 9, 'وَٱلْخَـٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّـٰدِقِينَ', '24:9'),
(2801, 24, 10, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', '24:10'),
(2802, 24, 11, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّا لَّكُم ۖ بَلْ هُوَ خَيْرٌ لَّكُمْ ۚ لِكُلِّ ٱمْرِئٍ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ ۚ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ', '24:11'),
(2803, 24, 12, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَـٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا۟ هَـٰذَآ إِفْكٌ مُّبِينٌ', '24:12'),
(2804, 24, 13, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ ۚ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَـٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَـٰذِبُونَ', '24:13'),
(2805, 24, 14, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', '24:14'),
(2806, 24, 15, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌ', '24:15'),
(2807, 24, 16, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَـٰذَا سُبْحَـٰنَكَ هَـٰذَا بُهْتَـٰنٌ عَظِيمٌ', '24:16'),
(2808, 24, 17, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', '24:17'),
(2809, 24, 18, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '24:18'),
(2810, 24, 19, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَـٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '24:19'),
(2811, 24, 20, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌ رَّحِيمٌ', '24:20'),
(2812, 24, 21, '۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَـٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۚ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَـٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '24:21'),
(2813, 24, 22, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَـٰكِينَ وَٱلْمُهَـٰجِرِينَ فِى سَبِيلِ ٱللَّهِ ۖ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '24:22'),
(2814, 24, 23, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَـٰتِ ٱلْغَـٰفِلَـٰتِ ٱلْمُؤْمِنَـٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '24:23'),
(2815, 24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '24:24'),
(2816, 24, 25, 'يَوْمَئِذٍ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', '24:25'),
(2817, 24, 26, 'ٱلْخَبِيثَـٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَـٰتِ ۖ وَٱلطَّيِّبَـٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَـٰتِ ۚ أُو۟لَـٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ ۖ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '24:26'),
(2818, 24, 27, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', '24:27'),
(2819, 24, 28, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ ۖ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ ۖ هُوَ أَزْكَىٰ لَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', '24:28'),
(2820, 24, 29, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَـٰعٌ لَّكُمْ ۚ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', '24:29'),
(2821, 24, 30, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَـٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', '24:30'),
(2822, 24, 31, 'وَقُل لِّلْمُؤْمِنَـٰتِ يَغْضُضْنَ مِنْ أَبْصَـٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا ۖ وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ ۖ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُنَّ أَوِ ٱلتَّـٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ ۖ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ ۚ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', '24:31'),
(2823, 24, 32, 'وَأَنكِحُوا۟ ٱلْأَيَـٰمَىٰ مِنكُمْ وَٱلصَّـٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ ۚ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '24:32'),
(2824, 24, 33, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَـٰبَ مِمَّا مَلَكَتْ أَيْمَـٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا ۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ ۚ وَلَا تُكْرِهُوا۟ فَتَيَـٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ', '24:33'),
(2825, 24, 34, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَـٰتٍ مُّبَيِّنَـٰتٍ وَمَثَلًا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', '24:34'),
(2826, 24, 35, '۞ ٱللَّهُ نُورُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ ۖ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَـٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ ۚ نُّورٌ عَلَىٰ نُورٍ ۗ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ ۚ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَـٰلَ لِلنَّاسِ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '24:35'),
(2827, 24, 36, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', '24:36'),
(2828, 24, 37, 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَـٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ ۙ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَـٰرُ', '24:37'),
(2829, 24, 38, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '24:38'),
(2830, 24, 39, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَـٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ ۗ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', '24:39'),
(2831, 24, 40, 'أَوْ كَظُلُمَـٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ ۚ ظُلُمَـٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا ۗ وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ', '24:40'),
(2832, 24, 41, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَـٰٓفَّـٰتٍ ۖ كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ ۗ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', '24:41'),
(2833, 24, 42, 'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', '24:42'),
(2834, 24, 43, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَـٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍ فِيهَا مِنۢ بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ ۖ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَـٰرِ', '24:43'),
(2835, 24, 44, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَـٰرِ', '24:44'),
(2836, 24, 45, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ ۖ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ ۚ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '24:45'),
(2837, 24, 46, 'لَّقَدْ أَنزَلْنَآ ءَايَـٰتٍ مُّبَيِّنَـٰتٍ ۚ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '24:46'),
(2838, 24, 47, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَـٰٓئِكَ بِٱلْمُؤْمِنِينَ', '24:47'),
(2839, 24, 48, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', '24:48'),
(2840, 24, 49, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', '24:49'),
(2841, 24, 50, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ ۚ بَلْ أُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '24:50'),
(2842, 24, 51, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '24:51'),
(2843, 24, 52, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', '24:52'),
(2844, 24, 53, '۞ وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ ۖ قُل لَّا تُقْسِمُوا۟ ۖ طَاعَةٌ مَّعْرُوفَةٌ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '24:53'),
(2845, 24, 54, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ ۖ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '24:54'),
(2846, 24, 55, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًا ۚ يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًٔا ۚ وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', '24:55'),
(2847, 24, 56, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '24:56'),
(2848, 24, 57, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ ۚ وَمَأْوَىٰهُمُ ٱلنَّارُ ۖ وَلَبِئْسَ ٱلْمَصِيرُ', '24:57'),
(2849, 24, 58, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَـٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَـٰثَ مَرَّٰتٍ ۚ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ۚ ثَلَـٰثُ عَوْرَٰتٍ لَّكُمْ ۚ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ ۚ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '24:58'),
(2850, 24, 59, 'وَإِذَا بَلَغَ ٱلْأَطْفَـٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '24:59'),
(2851, 24, 60, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّـٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَـٰتٍۭ بِزِينَةٍ ۖ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '24:60'),
(2852, 24, 61, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَـٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَـٰمِكُمْ أَوْ بُيُوتِ عَمَّـٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَـٰلَـٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ ۚ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًا ۚ فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ ٱللَّهِ مُبَـٰرَكَةً طَيِّبَةً ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '24:61'),
(2853, 24, 62, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ ۚ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَـٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ ۚ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '24:62'),
(2854, 24, 63, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا ۚ قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا ۚ فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', '24:63'),
(2855, 24, 64, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '24:64'),
(2856, 25, 1, ' تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَـٰلَمِينَ نَذِيرًا', '25:1'),
(2857, 25, 2, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا', '25:2'),
(2858, 25, 3, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا', '25:3'),
(2859, 25, 4, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ ۖ فَقَدْ جَآءُو ظُلْمًا وَزُورًا', '25:4'),
(2860, 25, 5, 'وَقَالُوٓا۟ أَسَـٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا', '25:5'),
(2861, 25, 6, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا', '25:6'),
(2862, 25, 7, 'وَقَالُوا۟ مَالِ هَـٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ ۙ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا', '25:7'),
(2863, 25, 8, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا ۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', '25:8'),
(2864, 25, 9, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَـٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', '25:9'),
(2865, 25, 10, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', '25:10'),
(2866, 25, 11, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', '25:11'),
(2867, 25, 12, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍ سَمِعُوا۟ لَهَا تَغَيُّظًا وَزَفِيرًا', '25:12'),
(2868, 25, 13, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًا', '25:13'),
(2869, 25, 14, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًا وَٰحِدًا وَٱدْعُوا۟ ثُبُورًا كَثِيرًا', '25:14'),
(2870, 25, 15, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۚ كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا', '25:15'),
(2871, 25, 16, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَـٰلِدِينَ ۚ كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسْـُٔولًا', '25:16'),
(2872, 25, 17, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَـٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', '25:17'),
(2873, 25, 18, 'قَالُوا۟ سُبْحَـٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَـٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًا', '25:18'),
(2874, 25, 19, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا ۚ وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا', '25:19'),
(2875, 25, 20, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ ۗ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ ۗ وَكَانَ رَبُّكَ بَصِيرًا', '25:20'),
(2876, 25, 21, '۞ وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَـٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا ۗ لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا', '25:21'),
(2877, 25, 22, 'يَوْمَ يَرَوْنَ ٱلْمَلَـٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', '25:22'),
(2878, 25, 23, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍ فَجَعَلْنَـٰهُ هَبَآءً مَّنثُورًا', '25:23'),
(2879, 25, 24, 'أَصْحَـٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', '25:24'),
(2880, 25, 25, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَـٰمِ وَنُزِّلَ ٱلْمَلَـٰٓئِكَةُ تَنزِيلًا', '25:25'),
(2881, 25, 26, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَـٰنِ ۚ وَكَانَ يَوْمًا عَلَى ٱلْكَـٰفِرِينَ عَسِيرًا', '25:26'),
(2882, 25, 27, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَـٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًا', '25:27'),
(2883, 25, 28, 'يَـٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', '25:28'),
(2884, 25, 29, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى ۗ وَكَانَ ٱلشَّيْطَـٰنُ لِلْإِنسَـٰنِ خَذُولًا', '25:29'),
(2885, 25, 30, 'وَقَالَ ٱلرَّسُولُ يَـٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَـٰذَا ٱلْقُرْءَانَ مَهْجُورًا', '25:30'),
(2886, 25, 31, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ ٱلْمُجْرِمِينَ ۗ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', '25:31'),
(2887, 25, 32, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةً وَٰحِدَةً ۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ ۖ وَرَتَّلْنَـٰهُ تَرْتِيلًا', '25:32'),
(2888, 25, 33, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَـٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', '25:33'),
(2889, 25, 34, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَـٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', '25:34'),
(2890, 25, 35, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَـٰرُونَ وَزِيرًا', '25:35'),
(2891, 25, 36, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا فَدَمَّرْنَـٰهُمْ تَدْمِيرًا', '25:36'),
(2892, 25, 37, 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَـٰهُمْ وَجَعَلْنَـٰهُمْ لِلنَّاسِ ءَايَةً ۖ وَأَعْتَدْنَا لِلظَّـٰلِمِينَ عَذَابًا أَلِيمًا', '25:37'),
(2893, 25, 38, 'وَعَادًا وَثَمُودَا۟ وَأَصْحَـٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًا', '25:38'),
(2894, 25, 39, 'وَكُلًّا ضَرَبْنَا لَهُ ٱلْأَمْثَـٰلَ ۖ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', '25:39'),
(2895, 25, 40, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ ۚ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا ۚ بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًا', '25:40'),
(2896, 25, 41, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', '25:41'),
(2897, 25, 42, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا ۚ وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', '25:42'),
(2898, 25, 43, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', '25:43'),
(2899, 25, 44, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ ۚ إِنْ هُمْ إِلَّا كَٱلْأَنْعَـٰمِ ۖ بَلْ هُمْ أَضَلُّ سَبِيلًا', '25:44'),
(2900, 25, 45, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًا', '25:45'),
(2901, 25, 46, 'ثُمَّ قَبَضْنَـٰهُ إِلَيْنَا قَبْضًا يَسِيرًا', '25:46'),
(2902, 25, 47, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًا وَٱلنَّوْمَ سُبَاتًا وَجَعَلَ ٱلنَّهَارَ نُشُورًا', '25:47'),
(2903, 25, 48, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا', '25:48'),
(2904, 25, 49, 'لِّنُحْـِۧىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَـٰمًا وَأَنَاسِىَّ كَثِيرًا', '25:49'),
(2905, 25, 50, 'وَلَقَدْ صَرَّفْنَـٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', '25:50'),
(2906, 25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا', '25:51'),
(2907, 25, 52, 'فَلَا تُطِعِ ٱلْكَـٰفِرِينَ وَجَـٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا', '25:52'),
(2908, 25, 53, '۞ وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَـٰذَا عَذْبٌ فُرَاتٌ وَهَـٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', '25:53'),
(2909, 25, 54, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا ۗ وَكَانَ رَبُّكَ قَدِيرًا', '25:54'),
(2910, 25, 55, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ ۗ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا', '25:55'),
(2911, 25, 56, 'وَمَآ أَرْسَلْنَـٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '25:56'),
(2912, 25, 57, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', '25:57'),
(2913, 25, 58, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ ۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', '25:58'),
(2914, 25, 59, 'ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ ٱلرَّحْمَـٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًا', '25:59'),
(2915, 25, 60, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَـٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَـٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا ۩', '25:60'),
(2916, 25, 61, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا', '25:61'),
(2917, 25, 62, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', '25:62'),
(2918, 25, 63, 'وَعِبَادُ ٱلرَّحْمَـٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ ٱلْجَـٰهِلُونَ قَالُوا۟ سَلَـٰمًا', '25:63'),
(2919, 25, 64, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَـٰمًا', '25:64'),
(2920, 25, 65, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', '25:65'),
(2921, 25, 66, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا', '25:66'),
(2922, 25, 67, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', '25:67'),
(2923, 25, 68, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ ۚ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', '25:68'),
(2924, 25, 69, 'يُضَـٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَـٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', '25:69'),
(2925, 25, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَـٰلِحًا فَأُو۟لَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَـٰتٍ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '25:70'),
(2926, 25, 71, 'وَمَن تَابَ وَعَمِلَ صَـٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًا', '25:71'),
(2927, 25, 72, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًا', '25:72'),
(2928, 25, 73, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّا وَعُمْيَانًا', '25:73'),
(2929, 25, 74, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', '25:74'),
(2930, 25, 75, 'أُو۟لَـٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَـٰمًا', '25:75'),
(2931, 25, 76, 'خَـٰلِدِينَ فِيهَا ۚ حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', '25:76'),
(2932, 25, 77, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ ۖ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', '25:77'),
(2933, 26, 1, ' طسٓمٓ', '26:1'),
(2934, 26, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', '26:2'),
(2935, 26, 3, 'لَعَلَّكَ بَـٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', '26:3'),
(2936, 26, 4, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَـٰقُهُمْ لَهَا خَـٰضِعِينَ', '26:4'),
(2937, 26, 5, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَـٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', '26:5'),
(2938, 26, 6, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '26:6'),
(2939, 26, 7, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '26:7'),
(2940, 26, 8, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:8'),
(2941, 26, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:9'),
(2942, 26, 10, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '26:10'),
(2943, 26, 11, 'قَوْمَ فِرْعَوْنَ ۚ أَلَا يَتَّقُونَ', '26:11'),
(2944, 26, 12, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', '26:12'),
(2945, 26, 13, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَـٰرُونَ', '26:13'),
(2946, 26, 14, 'وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ', '26:14'),
(2947, 26, 15, 'قَالَ كَلَّا ۖ فَٱذْهَبَا بِـَٔايَـٰتِنَآ ۖ إِنَّا مَعَكُم مُّسْتَمِعُونَ', '26:15'),
(2948, 26, 16, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَـٰلَمِينَ', '26:16'),
(2949, 26, 17, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', '26:17'),
(2950, 26, 18, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', '26:18'),
(2951, 26, 19, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَـٰفِرِينَ', '26:19'),
(2952, 26, 20, 'قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', '26:20'),
(2953, 26, 21, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', '26:21'),
(2954, 26, 22, 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', '26:22'),
(2955, 26, 23, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَـٰلَمِينَ', '26:23'),
(2956, 26, 24, 'قَالَ رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', '26:24'),
(2957, 26, 25, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', '26:25'),
(2958, 26, 26, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', '26:26'),
(2959, 26, 27, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ', '26:27'),
(2960, 26, 28, 'قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُمْ تَعْقِلُونَ', '26:28'),
(2961, 26, 29, 'قَالَ لَئِنِ ٱتَّخَذْتَ إِلَـٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ', '26:29'),
(2962, 26, 30, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍ مُّبِينٍ', '26:30'),
(2963, 26, 31, 'قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '26:31'),
(2964, 26, 32, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', '26:32'),
(2965, 26, 33, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّـٰظِرِينَ', '26:33'),
(2966, 26, 34, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِيمٌ', '26:34'),
(2967, 26, 35, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ', '26:35'),
(2968, 26, 36, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ', '26:36'),
(2969, 26, 37, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ', '26:37'),
(2970, 26, 38, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَـٰتِ يَوْمٍ مَّعْلُومٍ', '26:38'),
(2971, 26, 39, 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', '26:39'),
(2972, 26, 40, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَـٰلِبِينَ', '26:40'),
(2973, 26, 41, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَـٰلِبِينَ', '26:41'),
(2974, 26, 42, 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ ٱلْمُقَرَّبِينَ', '26:42'),
(2975, 26, 43, 'قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', '26:43'),
(2976, 26, 44, 'فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَـٰلِبُونَ', '26:44'),
(2977, 26, 45, 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', '26:45'),
(2978, 26, 46, 'فَأُلْقِىَ ٱلسَّحَرَةُ سَـٰجِدِينَ', '26:46'),
(2979, 26, 47, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَـٰلَمِينَ', '26:47'),
(2980, 26, 48, 'رَبِّ مُوسَىٰ وَهَـٰرُونَ', '26:48'),
(2981, 26, 49, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ ۚ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '26:49'),
(2982, 26, 50, 'قَالُوا۟ لَا ضَيْرَ ۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', '26:50'),
(2983, 26, 51, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَـٰيَـٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', '26:51'),
(2984, 26, 52, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', '26:52'),
(2985, 26, 53, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ', '26:53'),
(2986, 26, 54, 'إِنَّ هَـٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ', '26:54'),
(2987, 26, 55, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', '26:55'),
(2988, 26, 56, 'وَإِنَّا لَجَمِيعٌ حَـٰذِرُونَ', '26:56'),
(2989, 26, 57, 'فَأَخْرَجْنَـٰهُم مِّن جَنَّـٰتٍ وَعُيُونٍ', '26:57'),
(2990, 26, 58, 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', '26:58'),
(2991, 26, 59, 'كَذَٰلِكَ وَأَوْرَثْنَـٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', '26:59'),
(2992, 26, 60, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', '26:60'),
(2993, 26, 61, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَـٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', '26:61'),
(2994, 26, 62, 'قَالَ كَلَّآ ۖ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', '26:62'),
(2995, 26, 63, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ', '26:63'),
(2996, 26, 64, 'وَأَزْلَفْنَا ثَمَّ ٱلْـَٔاخَرِينَ', '26:64'),
(2997, 26, 65, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', '26:65'),
(2998, 26, 66, 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', '26:66'),
(2999, 26, 67, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:67'),
(3000, 26, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:68');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(3001, 26, 69, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ', '26:69'),
(3002, 26, 70, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ', '26:70'),
(3003, 26, 71, 'قَالُوا۟ نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَـٰكِفِينَ', '26:71'),
(3004, 26, 72, 'قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ', '26:72'),
(3005, 26, 73, 'أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ', '26:73'),
(3006, 26, 74, 'قَالُوا۟ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ', '26:74'),
(3007, 26, 75, 'قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ', '26:75'),
(3008, 26, 76, 'أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ', '26:76'),
(3009, 26, 77, 'فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ ٱلْعَـٰلَمِينَ', '26:77'),
(3010, 26, 78, 'ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ', '26:78'),
(3011, 26, 79, 'وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ', '26:79'),
(3012, 26, 80, 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', '26:80'),
(3013, 26, 81, 'وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ', '26:81'),
(3014, 26, 82, 'وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ', '26:82'),
(3015, 26, 83, 'رَبِّ هَبْ لِى حُكْمًا وَأَلْحِقْنِى بِٱلصَّـٰلِحِينَ', '26:83'),
(3016, 26, 84, 'وَٱجْعَل لِّى لِسَانَ صِدْقٍ فِى ٱلْـَٔاخِرِينَ', '26:84'),
(3017, 26, 85, 'وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', '26:85'),
(3018, 26, 86, 'وَٱغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', '26:86'),
(3019, 26, 87, 'وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ', '26:87'),
(3020, 26, 88, 'يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ', '26:88'),
(3021, 26, 89, 'إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍ سَلِيمٍ', '26:89'),
(3022, 26, 90, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ', '26:90'),
(3023, 26, 91, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِلْغَاوِينَ', '26:91'),
(3024, 26, 92, 'وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', '26:92'),
(3025, 26, 93, 'مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ', '26:93'),
(3026, 26, 94, 'فَكُبْكِبُوا۟ فِيهَا هُمْ وَٱلْغَاوُۥنَ', '26:94'),
(3027, 26, 95, 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ', '26:95'),
(3028, 26, 96, 'قَالُوا۟ وَهُمْ فِيهَا يَخْتَصِمُونَ', '26:96'),
(3029, 26, 97, 'تَٱللَّهِ إِن كُنَّا لَفِى ضَلَـٰلٍ مُّبِينٍ', '26:97'),
(3030, 26, 98, 'إِذْ نُسَوِّيكُم بِرَبِّ ٱلْعَـٰلَمِينَ', '26:98'),
(3031, 26, 99, 'وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', '26:99'),
(3032, 26, 100, 'فَمَا لَنَا مِن شَـٰفِعِينَ', '26:100'),
(3033, 26, 101, 'وَلَا صَدِيقٍ حَمِيمٍ', '26:101'),
(3034, 26, 102, 'فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '26:102'),
(3035, 26, 103, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:103'),
(3036, 26, 104, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:104'),
(3037, 26, 105, 'كَذَّبَتْ قَوْمُ نُوحٍ ٱلْمُرْسَلِينَ', '26:105'),
(3038, 26, 106, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ', '26:106'),
(3039, 26, 107, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '26:107'),
(3040, 26, 108, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:108'),
(3041, 26, 109, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ', '26:109'),
(3042, 26, 110, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:110'),
(3043, 26, 111, '۞ قَالُوٓا۟ أَنُؤْمِنُ لَكَ وَٱتَّبَعَكَ ٱلْأَرْذَلُونَ', '26:111'),
(3044, 26, 112, 'قَالَ وَمَا عِلْمِى بِمَا كَانُوا۟ يَعْمَلُونَ', '26:112'),
(3045, 26, 113, 'إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى ۖ لَوْ تَشْعُرُونَ', '26:113'),
(3046, 26, 114, 'وَمَآ أَنَا۠ بِطَارِدِ ٱلْمُؤْمِنِينَ', '26:114'),
(3047, 26, 115, 'إِنْ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', '26:115'),
(3048, 26, 116, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَـٰنُوحُ لَتَكُونَنَّ مِنَ ٱلْمَرْجُومِينَ', '26:116'),
(3049, 26, 117, 'قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ', '26:117'),
(3050, 26, 118, 'فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ', '26:118'),
(3051, 26, 119, 'فَأَنجَيْنَـٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', '26:119'),
(3052, 26, 120, 'ثُمَّ أَغْرَقْنَا بَعْدُ ٱلْبَاقِينَ', '26:120'),
(3053, 26, 121, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:121'),
(3054, 26, 122, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:122'),
(3055, 26, 123, 'كَذَّبَتْ عَادٌ ٱلْمُرْسَلِينَ', '26:123'),
(3056, 26, 124, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ', '26:124'),
(3057, 26, 125, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '26:125'),
(3058, 26, 126, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:126'),
(3059, 26, 127, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ', '26:127'),
(3060, 26, 128, 'أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ', '26:128'),
(3061, 26, 129, 'وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ', '26:129'),
(3062, 26, 130, 'وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ', '26:130'),
(3063, 26, 131, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:131'),
(3064, 26, 132, 'وَٱتَّقُوا۟ ٱلَّذِىٓ أَمَدَّكُم بِمَا تَعْلَمُونَ', '26:132'),
(3065, 26, 133, 'أَمَدَّكُم بِأَنْعَـٰمٍ وَبَنِينَ', '26:133'),
(3066, 26, 134, 'وَجَنَّـٰتٍ وَعُيُونٍ', '26:134'),
(3067, 26, 135, 'إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', '26:135'),
(3068, 26, 136, 'قَالُوا۟ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ ٱلْوَٰعِظِينَ', '26:136'),
(3069, 26, 137, 'إِنْ هَـٰذَآ إِلَّا خُلُقُ ٱلْأَوَّلِينَ', '26:137'),
(3070, 26, 138, 'وَمَا نَحْنُ بِمُعَذَّبِينَ', '26:138'),
(3071, 26, 139, 'فَكَذَّبُوهُ فَأَهْلَكْنَـٰهُمْ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:139'),
(3072, 26, 140, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:140'),
(3073, 26, 141, 'كَذَّبَتْ ثَمُودُ ٱلْمُرْسَلِينَ', '26:141'),
(3074, 26, 142, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ صَـٰلِحٌ أَلَا تَتَّقُونَ', '26:142'),
(3075, 26, 143, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '26:143'),
(3076, 26, 144, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:144'),
(3077, 26, 145, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ', '26:145'),
(3078, 26, 146, 'أَتُتْرَكُونَ فِى مَا هَـٰهُنَآ ءَامِنِينَ', '26:146'),
(3079, 26, 147, 'فِى جَنَّـٰتٍ وَعُيُونٍ', '26:147'),
(3080, 26, 148, 'وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ', '26:148'),
(3081, 26, 149, 'وَتَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا فَـٰرِهِينَ', '26:149'),
(3082, 26, 150, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:150'),
(3083, 26, 151, 'وَلَا تُطِيعُوٓا۟ أَمْرَ ٱلْمُسْرِفِينَ', '26:151'),
(3084, 26, 152, 'ٱلَّذِينَ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', '26:152'),
(3085, 26, 153, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', '26:153'),
(3086, 26, 154, 'مَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '26:154'),
(3087, 26, 155, 'قَالَ هَـٰذِهِۦ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ', '26:155'),
(3088, 26, 156, 'وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ', '26:156'),
(3089, 26, 157, 'فَعَقَرُوهَا فَأَصْبَحُوا۟ نَـٰدِمِينَ', '26:157'),
(3090, 26, 158, 'فَأَخَذَهُمُ ٱلْعَذَابُ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:158'),
(3091, 26, 159, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:159'),
(3092, 26, 160, 'كَذَّبَتْ قَوْمُ لُوطٍ ٱلْمُرْسَلِينَ', '26:160'),
(3093, 26, 161, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ', '26:161'),
(3094, 26, 162, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '26:162'),
(3095, 26, 163, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:163'),
(3096, 26, 164, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ', '26:164'),
(3097, 26, 165, 'أَتَأْتُونَ ٱلذُّكْرَانَ مِنَ ٱلْعَـٰلَمِينَ', '26:165'),
(3098, 26, 166, 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَٰجِكُم ۚ بَلْ أَنتُمْ قَوْمٌ عَادُونَ', '26:166'),
(3099, 26, 167, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَـٰلُوطُ لَتَكُونَنَّ مِنَ ٱلْمُخْرَجِينَ', '26:167'),
(3100, 26, 168, 'قَالَ إِنِّى لِعَمَلِكُم مِّنَ ٱلْقَالِينَ', '26:168'),
(3101, 26, 169, 'رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ', '26:169'),
(3102, 26, 170, 'فَنَجَّيْنَـٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', '26:170'),
(3103, 26, 171, 'إِلَّا عَجُوزًا فِى ٱلْغَـٰبِرِينَ', '26:171'),
(3104, 26, 172, 'ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ', '26:172'),
(3105, 26, 173, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', '26:173'),
(3106, 26, 174, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:174'),
(3107, 26, 175, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:175'),
(3108, 26, 176, 'كَذَّبَ أَصْحَـٰبُ لْـَٔيْكَةِ ٱلْمُرْسَلِينَ', '26:176'),
(3109, 26, 177, 'إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ', '26:177'),
(3110, 26, 178, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '26:178'),
(3111, 26, 179, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '26:179'),
(3112, 26, 180, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ', '26:180'),
(3113, 26, 181, '۞ أَوْفُوا۟ ٱلْكَيْلَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُخْسِرِينَ', '26:181'),
(3114, 26, 182, 'وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ', '26:182'),
(3115, 26, 183, 'وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '26:183'),
(3116, 26, 184, 'وَٱتَّقُوا۟ ٱلَّذِى خَلَقَكُمْ وَٱلْجِبِلَّةَ ٱلْأَوَّلِينَ', '26:184'),
(3117, 26, 185, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', '26:185'),
(3118, 26, 186, 'وَمَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلْكَـٰذِبِينَ', '26:186'),
(3119, 26, 187, 'فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '26:187'),
(3120, 26, 188, 'قَالَ رَبِّىٓ أَعْلَمُ بِمَا تَعْمَلُونَ', '26:188'),
(3121, 26, 189, 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ ۚ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ', '26:189'),
(3122, 26, 190, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '26:190'),
(3123, 26, 191, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '26:191'),
(3124, 26, 192, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلْعَـٰلَمِينَ', '26:192'),
(3125, 26, 193, 'نَزَلَ بِهِ ٱلرُّوحُ ٱلْأَمِينُ', '26:193'),
(3126, 26, 194, 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ٱلْمُنذِرِينَ', '26:194'),
(3127, 26, 195, 'بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ', '26:195'),
(3128, 26, 196, 'وَإِنَّهُۥ لَفِى زُبُرِ ٱلْأَوَّلِينَ', '26:196'),
(3129, 26, 197, 'أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَـٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ', '26:197'),
(3130, 26, 198, 'وَلَوْ نَزَّلْنَـٰهُ عَلَىٰ بَعْضِ ٱلْأَعْجَمِينَ', '26:198'),
(3131, 26, 199, 'فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ', '26:199'),
(3132, 26, 200, 'كَذَٰلِكَ سَلَكْنَـٰهُ فِى قُلُوبِ ٱلْمُجْرِمِينَ', '26:200'),
(3133, 26, 201, 'لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '26:201'),
(3134, 26, 202, 'فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '26:202'),
(3135, 26, 203, 'فَيَقُولُوا۟ هَلْ نَحْنُ مُنظَرُونَ', '26:203'),
(3136, 26, 204, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', '26:204'),
(3137, 26, 205, 'أَفَرَءَيْتَ إِن مَّتَّعْنَـٰهُمْ سِنِينَ', '26:205'),
(3138, 26, 206, 'ثُمَّ جَآءَهُم مَّا كَانُوا۟ يُوعَدُونَ', '26:206'),
(3139, 26, 207, 'مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يُمَتَّعُونَ', '26:207'),
(3140, 26, 208, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ', '26:208'),
(3141, 26, 209, 'ذِكْرَىٰ وَمَا كُنَّا ظَـٰلِمِينَ', '26:209'),
(3142, 26, 210, 'وَمَا تَنَزَّلَتْ بِهِ ٱلشَّيَـٰطِينُ', '26:210'),
(3143, 26, 211, 'وَمَا يَنۢبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ', '26:211'),
(3144, 26, 212, 'إِنَّهُمْ عَنِ ٱلسَّمْعِ لَمَعْزُولُونَ', '26:212'),
(3145, 26, 213, 'فَلَا تَدْعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلْمُعَذَّبِينَ', '26:213'),
(3146, 26, 214, 'وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', '26:214'),
(3147, 26, 215, 'وَٱخْفِضْ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', '26:215'),
(3148, 26, 216, 'فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', '26:216'),
(3149, 26, 217, 'وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ', '26:217'),
(3150, 26, 218, 'ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ', '26:218'),
(3151, 26, 219, 'وَتَقَلُّبَكَ فِى ٱلسَّـٰجِدِينَ', '26:219'),
(3152, 26, 220, 'إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '26:220'),
(3153, 26, 221, 'هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَـٰطِينُ', '26:221'),
(3154, 26, 222, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ', '26:222'),
(3155, 26, 223, 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَـٰذِبُونَ', '26:223'),
(3156, 26, 224, 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', '26:224'),
(3157, 26, 225, 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ', '26:225'),
(3158, 26, 226, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', '26:226'),
(3159, 26, 227, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ ۗ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ', '26:227'),
(3160, 27, 1, ' طسٓ ۚ تِلْكَ ءَايَـٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ', '27:1'),
(3161, 27, 2, 'هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', '27:2'),
(3162, 27, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '27:3'),
(3163, 27, 4, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَـٰلَهُمْ فَهُمْ يَعْمَهُونَ', '27:4'),
(3164, 27, 5, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '27:5'),
(3165, 27, 6, 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', '27:6'),
(3166, 27, 7, 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ', '27:7'),
(3167, 27, 8, 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '27:8'),
(3168, 27, 9, 'يَـٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', '27:9'),
(3169, 27, 10, 'وَأَلْقِ عَصَاكَ ۚ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ ۚ يَـٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', '27:10'),
(3170, 27, 11, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ', '27:11'),
(3171, 27, 12, 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ۖ فِى تِسْعِ ءَايَـٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ', '27:12'),
(3172, 27, 13, 'فَلَمَّا جَآءَتْهُمْ ءَايَـٰتُنَا مُبْصِرَةً قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ', '27:13'),
(3173, 27, 14, 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا ۚ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ', '27:14'),
(3174, 27, 15, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَـٰنَ عِلْمًا ۖ وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', '27:15'),
(3175, 27, 16, 'وَوَرِثَ سُلَيْمَـٰنُ دَاوُۥدَ ۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَـٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', '27:16'),
(3176, 27, 17, 'وَحُشِرَ لِسُلَيْمَـٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', '27:17'),
(3177, 27, 18, 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَـٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَـٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَـٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', '27:18'),
(3178, 27, 19, 'فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّـٰلِحِينَ', '27:19'),
(3179, 27, 20, 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', '27:20'),
(3180, 27, 21, 'لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَـٰنٍ مُّبِينٍ', '27:21'),
(3181, 27, 22, 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ', '27:22'),
(3182, 27, 23, 'إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', '27:23'),
(3183, 27, 24, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', '27:24'),
(3184, 27, 25, 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', '27:25'),
(3185, 27, 26, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ ۩', '27:26'),
(3186, 27, 27, '۞ قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَـٰذِبِينَ', '27:27'),
(3187, 27, 28, 'ٱذْهَب بِّكِتَـٰبِى هَـٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', '27:28'),
(3188, 27, 29, 'قَالَتْ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَـٰبٌ كَرِيمٌ', '27:29'),
(3189, 27, 30, 'إِنَّهُۥ مِن سُلَيْمَـٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', '27:30'),
(3190, 27, 31, 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', '27:31'),
(3191, 27, 32, 'قَالَتْ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', '27:32'),
(3192, 27, 33, 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', '27:33'),
(3193, 27, 34, 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً ۖ وَكَذَٰلِكَ يَفْعَلُونَ', '27:34'),
(3194, 27, 35, 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', '27:35'),
(3195, 27, 36, 'فَلَمَّا جَآءَ سُلَيْمَـٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', '27:36'),
(3196, 27, 37, 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَـٰغِرُونَ', '27:37'),
(3197, 27, 38, 'قَالَ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', '27:38'),
(3198, 27, 39, 'قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ ۖ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ', '27:39'),
(3199, 27, 40, 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَـٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ ۚ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَـٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ ۖ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ', '27:40'),
(3200, 27, 41, 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', '27:41'),
(3201, 27, 42, 'فَلَمَّا جَآءَتْ قِيلَ أَهَـٰكَذَا عَرْشُكِ ۖ قَالَتْ كَأَنَّهُۥ هُوَ ۚ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', '27:42'),
(3202, 27, 43, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ ۖ إِنَّهَا كَانَتْ مِن قَوْمٍ كَـٰفِرِينَ', '27:43'),
(3203, 27, 44, 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ ۖ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا ۚ قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ ۗ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَـٰنَ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '27:44'),
(3204, 27, 45, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', '27:45'),
(3205, 27, 46, 'قَالَ يَـٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ ۖ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', '27:46'),
(3206, 27, 47, 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ ۚ قَالَ طَـٰٓئِرُكُمْ عِندَ ٱللَّهِ ۖ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', '27:47'),
(3207, 27, 48, 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', '27:48'),
(3208, 27, 49, 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَـٰدِقُونَ', '27:49'),
(3209, 27, 50, 'وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', '27:50'),
(3210, 27, 51, 'فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَـٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', '27:51'),
(3211, 27, 52, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْلَمُونَ', '27:52'),
(3212, 27, 53, 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '27:53'),
(3213, 27, 54, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَـٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', '27:54'),
(3214, 27, 55, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', '27:55'),
(3215, 27, 56, '۞ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', '27:56'),
(3216, 27, 57, 'فَأَنجَيْنَـٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَـٰهَا مِنَ ٱلْغَـٰبِرِينَ', '27:57'),
(3217, 27, 58, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', '27:58'),
(3218, 27, 59, 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَـٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ۗ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', '27:59'),
(3219, 27, 60, 'أَمَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', '27:60'),
(3220, 27, 61, 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَـٰلَهَآ أَنْهَـٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '27:61'),
(3221, 27, 62, 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ قَلِيلًا مَّا تَذَكَّرُونَ', '27:62'),
(3222, 27, 63, 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ تَعَـٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', '27:63'),
(3223, 27, 64, 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ', '27:64'),
(3224, 27, 65, 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ ۚ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', '27:65'),
(3225, 27, 66, 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْـَٔاخِرَةِ ۚ بَلْ هُمْ فِى شَكٍّ مِّنْهَا ۖ بَلْ هُم مِّنْهَا عَمُونَ', '27:66'),
(3226, 27, 67, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', '27:67'),
(3227, 27, 68, 'لَقَدْ وُعِدْنَا هَـٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '27:68'),
(3228, 27, 69, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُجْرِمِينَ', '27:69'),
(3229, 27, 70, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '27:70'),
(3230, 27, 71, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '27:71'),
(3231, 27, 72, 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', '27:72'),
(3232, 27, 73, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '27:73'),
(3233, 27, 74, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', '27:74'),
(3234, 27, 75, 'وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ', '27:75'),
(3235, 27, 76, 'إِنَّ هَـٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', '27:76'),
(3236, 27, 77, 'وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '27:77'),
(3237, 27, 78, 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', '27:78'),
(3238, 27, 79, 'فَتَوَكَّلْ عَلَى ٱللَّهِ ۖ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', '27:79'),
(3239, 27, 80, 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', '27:80'),
(3240, 27, 81, 'وَمَآ أَنتَ بِهَـٰدِى ٱلْعُمْىِ عَن ضَلَـٰلَتِهِمْ ۖ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَـٰتِنَا فَهُم مُّسْلِمُونَ', '27:81'),
(3241, 27, 82, '۞ وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَـٰتِنَا لَا يُوقِنُونَ', '27:82'),
(3242, 27, 83, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَـٰتِنَا فَهُمْ يُوزَعُونَ', '27:83'),
(3243, 27, 84, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَـٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', '27:84'),
(3244, 27, 85, 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', '27:85'),
(3245, 27, 86, 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '27:86'),
(3246, 27, 87, 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۚ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', '27:87'),
(3247, 27, 88, 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ ۚ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ ۚ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', '27:88'),
(3248, 27, 89, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ', '27:89'),
(3249, 27, 90, 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', '27:90'),
(3250, 27, 91, 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَـٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '27:91'),
(3251, 27, 92, 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', '27:92'),
(3252, 27, 93, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَـٰتِهِۦ فَتَعْرِفُونَهَا ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ', '27:93'),
(3253, 28, 1, ' طسٓمٓ', '28:1'),
(3254, 28, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', '28:2'),
(3255, 28, 3, 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', '28:3'),
(3256, 28, 4, 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ ۚ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', '28:4'),
(3257, 28, 5, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', '28:5'),
(3258, 28, 6, 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', '28:6'),
(3259, 28, 7, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ ۖ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', '28:7'),
(3260, 28, 8, 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا ۗ إِنَّ فِرْعَوْنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا كَانُوا۟ خَـٰطِـِٔينَ', '28:8'),
(3261, 28, 9, 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ ۖ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ', '28:9'),
(3262, 28, 10, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَـٰرِغًا ۖ إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '28:10'),
(3263, 28, 11, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ ۖ فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ', '28:11'),
(3264, 28, 12, '۞ وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَـٰصِحُونَ', '28:12'),
(3265, 28, 13, 'فَرَدَدْنَـٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '28:13'),
(3266, 28, 14, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '28:14'),
(3267, 28, 15, 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَـٰذَا مِن شِيعَتِهِۦ وَهَـٰذَا مِنْ عَدُوِّهِۦ ۖ فَٱسْتَغَـٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ ۖ قَالَ هَـٰذَا مِنْ عَمَلِ ٱلشَّيْطَـٰنِ ۖ إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ', '28:15'),
(3268, 28, 16, 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '28:16'),
(3269, 28, 17, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ', '28:17'),
(3270, 28, 18, 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ ۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ', '28:18'),
(3271, 28, 19, 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَـٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ ۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', '28:19'),
(3272, 28, 20, 'وَجَآءَ رَجُلٌ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَـٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّـٰصِحِينَ', '28:20'),
(3273, 28, 21, 'فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ ۖ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '28:21'),
(3274, 28, 22, 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', '28:22'),
(3275, 28, 23, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ ۖ قَالَ مَا خَطْبُكُمَا ۖ قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ ۖ وَأَبُونَا شَيْخٌ كَبِيرٌ', '28:23'),
(3276, 28, 24, 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ', '28:24'),
(3277, 28, 25, 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا ۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ ۖ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '28:25'),
(3278, 28, 26, 'قَالَتْ إِحْدَىٰهُمَا يَـٰٓأَبَتِ ٱسْتَـْٔجِرْهُ ۖ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', '28:26'),
(3279, 28, 27, 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَـٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَـٰنِىَ حِجَجٍ ۖ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ ۖ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ ۚ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِينَ', '28:27'),
(3280, 28, 28, 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ ۖ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ ۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', '28:28'),
(3281, 28, 29, '۞ فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', '28:29'),
(3282, 28, 30, 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَـٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَـٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَـٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ', '28:30'),
(3283, 28, 31, 'وَأَنْ أَلْقِ عَصَاكَ ۖ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ ۚ يَـٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ ۖ إِنَّكَ مِنَ ٱلْـَٔامِنِينَ', '28:31'),
(3284, 28, 32, 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ ۖ فَذَٰنِكَ بُرْهَـٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ', '28:32'),
(3285, 28, 33, 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', '28:33'),
(3286, 28, 34, 'وَأَخِى هَـٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ ۖ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', '28:34'),
(3287, 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَـٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا ۚ بِـَٔايَـٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَـٰلِبُونَ', '28:35'),
(3288, 28, 36, 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَـٰتِنَا بَيِّنَـٰتٍ قَالُوا۟ مَا هَـٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَـٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '28:36'),
(3289, 28, 37, 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ', '28:37'),
(3290, 28, 38, 'وَقَالَ فِرْعَوْنُ يَـٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَـٰهٍ غَيْرِى فَأَوْقِدْ لِى يَـٰهَـٰمَـٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَـٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَـٰذِبِينَ', '28:38'),
(3291, 28, 39, 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', '28:39'),
(3292, 28, 40, 'فَأَخَذْنَـٰهُ وَجُنُودَهُۥ فَنَبَذْنَـٰهُمْ فِى ٱلْيَمِّ ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِينَ', '28:40'),
(3293, 28, 41, 'وَجَعَلْنَـٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ لَا يُنصَرُونَ', '28:41'),
(3294, 28, 42, 'وَأَتْبَعْنَـٰهُمْ فِى هَـٰذِهِ ٱلدُّنْيَا لَعْنَةً ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', '28:42'),
(3295, 28, 43, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', '28:43'),
(3296, 28, 44, 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِينَ', '28:44'),
(3297, 28, 45, 'وَلَـٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ ۚ وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِنَا وَلَـٰكِنَّا كُنَّا مُرْسِلِينَ', '28:45'),
(3298, 28, 46, 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَـٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', '28:46'),
(3299, 28, 47, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَـٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '28:47'),
(3300, 28, 48, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ ۚ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ ۖ قَالُوا۟ سِحْرَانِ تَظَـٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّ كَـٰفِرُونَ', '28:48'),
(3301, 28, 49, 'قُلْ فَأْتُوا۟ بِكِتَـٰبٍ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَـٰدِقِينَ', '28:49'),
(3302, 28, 50, 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ ۚ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '28:50'),
(3303, 28, 51, '۞ وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', '28:51'),
(3304, 28, 52, 'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', '28:52'),
(3305, 28, 53, 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', '28:53'),
(3306, 28, 54, 'أُو۟لَـٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '28:54'),
(3307, 28, 55, 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ سَلَـٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَـٰهِلِينَ', '28:55'),
(3308, 28, 56, 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَـٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۚ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '28:56'),
(3309, 28, 57, 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ ۚ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '28:57'),
(3310, 28, 58, 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا ۖ فَتِلْكَ مَسَـٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًا ۖ وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', '28:58'),
(3311, 28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِنَا ۚ وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَـٰلِمُونَ', '28:59'),
(3312, 28, 60, 'وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا ۚ وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰٓ ۚ أَفَلَا تَعْقِلُونَ', '28:60'),
(3313, 28, 61, 'أَفَمَن وَعَدْنَـٰهُ وَعْدًا حَسَنًا فَهُوَ لَـٰقِيهِ كَمَن مَّتَّعْنَـٰهُ مَتَـٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَـٰمَةِ مِنَ ٱلْمُحْضَرِينَ', '28:61'),
(3314, 28, 62, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '28:62'),
(3315, 28, 63, 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَـٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَـٰهُمْ كَمَا غَوَيْنَا ۖ تَبَرَّأْنَآ إِلَيْكَ ۖ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', '28:63'),
(3316, 28, 64, 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ ۚ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', '28:64'),
(3317, 28, 65, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', '28:65'),
(3318, 28, 66, 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ', '28:66'),
(3319, 28, 67, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', '28:67'),
(3320, 28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ ۗ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ ۚ سُبْحَـٰنَ ٱللَّهِ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '28:68'),
(3321, 28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', '28:69'),
(3322, 28, 70, 'وَهُوَ ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْـَٔاخِرَةِ ۖ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '28:70'),
(3323, 28, 71, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ مَنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ ۖ أَفَلَا تَسْمَعُونَ', '28:71'),
(3324, 28, 72, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ مَنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ ۖ أَفَلَا تُبْصِرُونَ', '28:72'),
(3325, 28, 73, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '28:73'),
(3326, 28, 74, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '28:74'),
(3327, 28, 75, 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا۟ بُرْهَـٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '28:75'),
(3328, 28, 76, '۞ إِنَّ قَـٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ ۖ وَءَاتَيْنَـٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', '28:76'),
(3329, 28, 77, 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْـَٔاخِرَةَ ۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا ۖ وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ ۖ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '28:77'),
(3330, 28, 78, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ ۚ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا ۚ وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', '28:78'),
(3331, 28, 79, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ ۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَـٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَـٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ', '28:79'),
(3332, 28, 80, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَـٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّـٰبِرُونَ', '28:80'),
(3333, 28, 81, 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', '28:81'),
(3334, 28, 82, 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ ۖ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا ۖ وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَـٰفِرُونَ', '28:82'),
(3335, 28, 83, 'تِلْكَ ٱلدَّارُ ٱلْـَٔاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى ٱلْأَرْضِ وَلَا فَسَادًا ۚ وَٱلْعَـٰقِبَةُ لِلْمُتَّقِينَ', '28:83'),
(3336, 28, 84, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', '28:84'),
(3337, 28, 85, 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ ۚ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَـٰلٍ مُّبِينٍ', '28:85'),
(3338, 28, 86, 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَـٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ ۖ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَـٰفِرِينَ', '28:86'),
(3339, 28, 87, 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَـٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ ۖ وَٱدْعُ إِلَىٰ رَبِّكَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '28:87'),
(3340, 28, 88, 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ ۘ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ ۚ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '28:88'),
(3341, 29, 1, ' الٓمٓ', '29:1'),
(3342, 29, 2, 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', '29:2'),
(3343, 29, 3, 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَـٰذِبِينَ', '29:3'),
(3344, 29, 4, 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا ۚ سَآءَ مَا يَحْكُمُونَ', '29:4'),
(3345, 29, 5, 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتٍ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '29:5'),
(3346, 29, 6, 'وَمَن جَـٰهَدَ فَإِنَّمَا يُجَـٰهِدُ لِنَفْسِهِۦٓ ۚ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَـٰلَمِينَ', '29:6'),
(3347, 29, 7, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '29:7'),
(3348, 29, 8, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ حُسْنًا ۖ وَإِن جَـٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ ۚ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '29:8'),
(3349, 29, 9, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّـٰلِحِينَ', '29:9'),
(3350, 29, 10, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ ۚ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَـٰلَمِينَ', '29:10'),
(3351, 29, 11, 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَـٰفِقِينَ', '29:11'),
(3352, 29, 12, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَـٰيَـٰكُمْ وَمَا هُم بِحَـٰمِلِينَ مِنْ خَطَـٰيَـٰهُم مِّن شَىْءٍ ۖ إِنَّهُمْ لَكَـٰذِبُونَ', '29:12'),
(3353, 29, 13, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ ۖ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَـٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', '29:13'),
(3354, 29, 14, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَـٰلِمُونَ', '29:14'),
(3355, 29, 15, 'فَأَنجَيْنَـٰهُ وَأَصْحَـٰبَ ٱلسَّفِينَةِ وَجَعَلْنَـٰهَآ ءَايَةً لِّلْعَـٰلَمِينَ', '29:15'),
(3356, 29, 16, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ۖ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '29:16'),
(3357, 29, 17, 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَـٰنًا وَتَخْلُقُونَ إِفْكًا ۚ إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ ۖ إِلَيْهِ تُرْجَعُونَ', '29:17'),
(3358, 29, 18, 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ ۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '29:18'),
(3359, 29, 19, 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '29:19'),
(3360, 29, 20, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْـَٔاخِرَةَ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '29:20'),
(3361, 29, 21, 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ ۖ وَإِلَيْهِ تُقْلَبُونَ', '29:21'),
(3362, 29, 22, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '29:22'),
(3363, 29, 23, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَـٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', '29:23'),
(3364, 29, 24, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '29:24'),
(3365, 29, 25, 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَـٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ يَوْمَ ٱلْقِيَـٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ', '29:25'),
(3366, 29, 26, '۞ فَـَٔامَنَ لَهُۥ لُوطٌ ۘ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '29:26'),
(3367, 29, 27, 'وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَـٰبَ وَءَاتَيْنَـٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ', '29:27'),
(3368, 29, 28, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَـٰلَمِينَ', '29:28'),
(3369, 29, 29, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ ۖ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '29:29'),
(3370, 29, 30, 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', '29:30'),
(3371, 29, 31, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَـٰذِهِ ٱلْقَرْيَةِ ۖ إِنَّ أَهْلَهَا كَانُوا۟ ظَـٰلِمِينَ', '29:31'),
(3372, 29, 32, 'قَالَ إِنَّ فِيهَا لُوطًا ۚ قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا ۖ لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَـٰبِرِينَ', '29:32'),
(3373, 29, 33, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ ۖ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَـٰبِرِينَ', '29:33'),
(3374, 29, 34, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَـٰذِهِ ٱلْقَرْيَةِ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', '29:34'),
(3375, 29, 35, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', '29:35'),
(3376, 29, 36, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْـَٔاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '29:36'),
(3377, 29, 37, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ', '29:37'),
(3378, 29, 38, 'وَعَادًا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَـٰكِنِهِمْ ۖ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', '29:38'),
(3379, 29, 39, 'وَقَـٰرُونَ وَفِرْعَوْنَ وَهَـٰمَـٰنَ ۖ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَـٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَـٰبِقِينَ', '29:39'),
(3380, 29, 40, 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ ۖ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا ۚ وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '29:40'),
(3381, 29, 41, 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًا ۖ وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ ۖ لَوْ كَانُوا۟ يَعْلَمُونَ', '29:41'),
(3382, 29, 42, 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '29:42'),
(3383, 29, 43, 'وَتِلْكَ ٱلْأَمْثَـٰلُ نَضْرِبُهَا لِلنَّاسِ ۖ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَـٰلِمُونَ', '29:43'),
(3384, 29, 44, 'خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', '29:44'),
(3385, 29, 45, 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَـٰبِ وَأَقِمِ ٱلصَّلَوٰةَ ۖ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۗ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ ۗ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', '29:45'),
(3386, 29, 46, '۞ وَلَا تُجَـٰدِلُوٓا۟ أَهْلَ ٱلْكِتَـٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ ۖ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَـٰهُنَا وَإِلَـٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '29:46'),
(3387, 29, 47, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ ۚ فَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يُؤْمِنُونَ بِهِۦ ۖ وَمِنْ هَـٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ ۚ وَمَا يَجْحَدُ بِـَٔايَـٰتِنَآ إِلَّا ٱلْكَـٰفِرُونَ', '29:47'),
(3388, 29, 48, 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَـٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ ۖ إِذًا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', '29:48'),
(3389, 29, 49, 'بَلْ هُوَ ءَايَـٰتٌۢ بَيِّنَـٰتٌ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ۚ وَمَا يَجْحَدُ بِـَٔايَـٰتِنَآ إِلَّا ٱلظَّـٰلِمُونَ', '29:49'),
(3390, 29, 50, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَـٰتٌ مِّن رَّبِّهِۦ ۖ قُلْ إِنَّمَا ٱلْـَٔايَـٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', '29:50'),
(3391, 29, 51, 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَـٰبَ يُتْلَىٰ عَلَيْهِمْ ۚ إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', '29:51'),
(3392, 29, 52, 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا ۖ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَـٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '29:52'),
(3393, 29, 53, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ ۚ وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '29:53'),
(3394, 29, 54, 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَـٰفِرِينَ', '29:54'),
(3395, 29, 55, 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', '29:55'),
(3396, 29, 56, 'يَـٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّـٰىَ فَٱعْبُدُونِ', '29:56'),
(3397, 29, 57, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۖ ثُمَّ إِلَيْنَا تُرْجَعُونَ', '29:57'),
(3398, 29, 58, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ نِعْمَ أَجْرُ ٱلْعَـٰمِلِينَ', '29:58'),
(3399, 29, 59, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '29:59'),
(3400, 29, 60, 'وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '29:60'),
(3401, 29, 61, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ', '29:61'),
(3402, 29, 62, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '29:62'),
(3403, 29, 63, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ ۚ قُلِ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', '29:63'),
(3404, 29, 64, 'وَمَا هَـٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ ۚ وَإِنَّ ٱلدَّارَ ٱلْـَٔاخِرَةَ لَهِىَ ٱلْحَيَوَانُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', '29:64'),
(3405, 29, 65, 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', '29:65'),
(3406, 29, 66, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَـٰهُمْ وَلِيَتَمَتَّعُوا۟ ۖ فَسَوْفَ يَعْلَمُونَ', '29:66'),
(3407, 29, 67, 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ ۚ أَفَبِٱلْبَـٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', '29:67'),
(3408, 29, 68, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَـٰفِرِينَ', '29:68'),
(3409, 29, 69, 'وَٱلَّذِينَ جَـٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', '29:69'),
(3410, 30, 1, ' الٓمٓ', '30:1'),
(3411, 30, 2, 'غُلِبَتِ ٱلرُّومُ', '30:2'),
(3412, 30, 3, 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', '30:3'),
(3413, 30, 4, 'فِى بِضْعِ سِنِينَ ۗ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ ۚ وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ', '30:4'),
(3414, 30, 5, 'بِنَصْرِ ٱللَّهِ ۚ يَنصُرُ مَن يَشَآءُ ۖ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '30:5'),
(3415, 30, 6, 'وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '30:6'),
(3416, 30, 7, 'يَعْلَمُونَ ظَـٰهِرًا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْـَٔاخِرَةِ هُمْ غَـٰفِلُونَ', '30:7'),
(3417, 30, 8, 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم ۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى ۗ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَـٰفِرُونَ', '30:8'),
(3418, 30, 9, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '30:9'),
(3419, 30, 10, 'ثُمَّ كَانَ عَـٰقِبَةَ ٱلَّذِينَ أَسَـٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', '30:10'),
(3420, 30, 11, 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '30:11'),
(3421, 30, 12, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', '30:12'),
(3422, 30, 13, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَـٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَـٰفِرِينَ', '30:13'),
(3423, 30, 14, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', '30:14'),
(3424, 30, 15, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ', '30:15'),
(3425, 30, 16, 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا وَلِقَآئِ ٱلْـَٔاخِرَةِ فَأُو۟لَـٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '30:16'),
(3426, 30, 17, 'فَسُبْحَـٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', '30:17'),
(3427, 30, 18, 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ', '30:18'),
(3428, 30, 19, 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ وَكَذَٰلِكَ تُخْرَجُونَ', '30:19'),
(3429, 30, 20, 'وَمِنْ ءَايَـٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ', '30:20'),
(3430, 30, 21, 'وَمِنْ ءَايَـٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '30:21'),
(3431, 30, 22, 'وَمِنْ ءَايَـٰتِهِۦ خَلْقُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّلْعَـٰلِمِينَ', '30:22'),
(3432, 30, 23, 'وَمِنْ ءَايَـٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَسْمَعُونَ', '30:23'),
(3433, 30, 24, 'وَمِنْ ءَايَـٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءً فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '30:24'),
(3434, 30, 25, 'وَمِنْ ءَايَـٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ۚ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', '30:25'),
(3435, 30, 26, 'وَلَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّ لَّهُۥ قَـٰنِتُونَ', '30:26'),
(3436, 30, 27, 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ ۚ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '30:27'),
(3437, 30, 28, 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ ۖ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَـٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَـٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْقِلُونَ', '30:28'),
(3438, 30, 29, 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍ ۖ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ', '30:29'),
(3439, 30, 30, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا ۚ فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا ۚ لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '30:30'),
(3440, 30, 31, '۞ مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', '30:31'),
(3441, 30, 32, 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '30:32'),
(3442, 30, 33, 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', '30:33'),
(3443, 30, 34, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَـٰهُمْ ۚ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', '30:34'),
(3444, 30, 35, 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَـٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', '30:35'),
(3445, 30, 36, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً فَرِحُوا۟ بِهَا ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', '30:36'),
(3446, 30, 37, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '30:37'),
(3447, 30, 38, 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ۚ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '30:38'),
(3448, 30, 39, 'وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ ۖ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', '30:39'),
(3449, 30, 40, 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۖ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '30:40'),
(3450, 30, 41, 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', '30:41'),
(3451, 30, 42, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ ۚ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', '30:42'),
(3452, 30, 43, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ ۖ يَوْمَئِذٍ يَصَّدَّعُونَ', '30:43'),
(3453, 30, 44, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ ۖ وَمَنْ عَمِلَ صَـٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', '30:44'),
(3454, 30, 45, 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِن فَضْلِهِۦٓ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْكَـٰفِرِينَ', '30:45'),
(3455, 30, 46, 'وَمِنْ ءَايَـٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '30:46'),
(3456, 30, 47, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَـٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ ۖ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', '30:47'),
(3457, 30, 48, 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَـٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَـٰلِهِۦ ۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '30:48'),
(3458, 30, 49, 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', '30:49'),
(3459, 30, 50, 'فَٱنظُرْ إِلَىٰٓ ءَاثَـٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '30:50'),
(3460, 30, 51, 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', '30:51'),
(3461, 30, 52, 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', '30:52'),
(3462, 30, 53, 'وَمَآ أَنتَ بِهَـٰدِ ٱلْعُمْىِ عَن ضَلَـٰلَتِهِمْ ۖ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَـٰتِنَا فَهُم مُّسْلِمُونَ', '30:53'),
(3463, 30, 54, '۞ ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً ۚ يَخْلُقُ مَا يَشَآءُ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', '30:54'),
(3464, 30, 55, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍ ۚ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', '30:55'),
(3465, 30, 56, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَـٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَـٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ ۖ فَهَـٰذَا يَوْمُ ٱلْبَعْثِ وَلَـٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', '30:56'),
(3466, 30, 57, 'فَيَوْمَئِذٍ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', '30:57'),
(3467, 30, 58, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَـٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ ۚ وَلَئِن جِئْتَهُم بِـَٔايَةٍ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', '30:58'),
(3468, 30, 59, 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', '30:59'),
(3469, 30, 60, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۖ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', '30:60'),
(3470, 31, 1, ' الٓمٓ', '31:1'),
(3471, 31, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ', '31:2'),
(3472, 31, 3, 'هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', '31:3'),
(3473, 31, 4, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '31:4'),
(3474, 31, 5, 'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '31:5'),
(3475, 31, 6, 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', '31:6'),
(3476, 31, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '31:7'),
(3477, 31, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتُ ٱلنَّعِيمِ', '31:8'),
(3478, 31, 9, 'خَـٰلِدِينَ فِيهَا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '31:9'),
(3479, 31, 10, 'خَلَقَ ٱلسَّمَـٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '31:10'),
(3480, 31, 11, 'هَـٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ ۚ بَلِ ٱلظَّـٰلِمُونَ فِى ضَلَـٰلٍ مُّبِينٍ', '31:11'),
(3481, 31, 12, 'وَلَقَدْ ءَاتَيْنَا لُقْمَـٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ ۚ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', '31:12'),
(3482, 31, 13, 'وَإِذْ قَالَ لُقْمَـٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَـٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ ۖ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ', '31:13'),
(3483, 31, 14, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَـٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', '31:14'),
(3484, 31, 15, 'وَإِن جَـٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا ۖ وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ۚ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '31:15'),
(3485, 31, 16, 'يَـٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَـٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ ۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', '31:16'),
(3486, 31, 17, 'يَـٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '31:17'),
(3487, 31, 18, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '31:18'),
(3488, 31, 19, 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ ۚ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', '31:19'),
(3489, 31, 20, 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَـٰهِرَةً وَبَاطِنَةً ۗ وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَـٰبٍ مُّنِيرٍ', '31:20'),
(3490, 31, 21, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ٱلشَّيْطَـٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', '31:21'),
(3491, 31, 22, '۞ وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ ۗ وَإِلَى ٱللَّهِ عَـٰقِبَةُ ٱلْأُمُورِ', '31:22'),
(3492, 31, 23, 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ ۚ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '31:23'),
(3493, 31, 24, 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', '31:24'),
(3494, 31, 25, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ ۚ قُلِ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '31:25'),
(3495, 31, 26, 'لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '31:26'),
(3496, 31, 27, 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَـٰمٌ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَـٰتُ ٱللَّهِ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '31:27'),
(3497, 31, 28, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ ۗ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '31:28'),
(3498, 31, 29, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', '31:29'),
(3499, 31, 30, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '31:30'),
(3500, 31, 31, 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَـٰتِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '31:31'),
(3501, 31, 32, 'وَإِذَا غَشِيَهُم مَّوْجٌ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌ ۚ وَمَا يَجْحَدُ بِـَٔايَـٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', '31:32'),
(3502, 31, 33, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا ۚ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', '31:33'),
(3503, 31, 34, 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ ۖ وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا ۖ وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍ تَمُوتُ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', '31:34'),
(3504, 32, 1, ' الٓمٓ', '32:1'),
(3505, 32, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَـٰلَمِينَ', '32:2'),
(3506, 32, 3, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۚ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', '32:3'),
(3507, 32, 4, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ ۚ أَفَلَا تَتَذَكَّرُونَ', '32:4'),
(3508, 32, 5, 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ', '32:5'),
(3509, 32, 6, 'ذَٰلِكَ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', '32:6'),
(3510, 32, 7, 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ ۖ وَبَدَأَ خَلْقَ ٱلْإِنسَـٰنِ مِن طِينٍ', '32:7'),
(3511, 32, 8, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَـٰلَةٍ مِّن مَّآءٍ مَّهِينٍ', '32:8'),
(3512, 32, 9, 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ ۖ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًا مَّا تَشْكُرُونَ', '32:9'),
(3513, 32, 10, 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍۭ ۚ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَـٰفِرُونَ', '32:10'),
(3514, 32, 11, '۞ قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', '32:11'),
(3515, 32, 12, 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَـٰلِحًا إِنَّا مُوقِنُونَ', '32:12'),
(3516, 32, 13, 'وَلَوْ شِئْنَا لَـَٔاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَـٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', '32:13'),
(3517, 32, 14, 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَآ إِنَّا نَسِينَـٰكُمْ ۖ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', '32:14'),
(3518, 32, 15, 'إِنَّمَا يُؤْمِنُ بِـَٔايَـٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ ۩', '32:15'),
(3519, 32, 16, 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '32:16'),
(3520, 32, 17, 'فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '32:17'),
(3521, 32, 18, 'أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا ۚ لَّا يَسْتَوُۥنَ', '32:18'),
(3522, 32, 19, 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ جَنَّـٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', '32:19'),
(3523, 32, 20, 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ ۖ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', '32:20'),
(3524, 32, 21, 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', '32:21'),
(3525, 32, 22, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَـٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ ۚ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', '32:22'),
(3526, 32, 23, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ ۖ وَجَعَلْنَـٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ', '32:23'),
(3527, 32, 24, 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ ۖ وَكَانُوا۟ بِـَٔايَـٰتِنَا يُوقِنُونَ', '32:24'),
(3528, 32, 25, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '32:25'),
(3529, 32, 26, 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَـٰكِنِهِمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ ۖ أَفَلَا يَسْمَعُونَ', '32:26'),
(3530, 32, 27, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَـٰمُهُمْ وَأَنفُسُهُمْ ۖ أَفَلَا يُبْصِرُونَ', '32:27'),
(3531, 32, 28, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَـٰدِقِينَ', '32:28'),
(3532, 32, 29, 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَـٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', '32:29'),
(3533, 32, 30, 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', '32:30'),
(3534, 33, 1, ' يَـٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَـٰفِرِينَ وَٱلْمُنَـٰفِقِينَ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '33:1'),
(3535, 33, 2, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '33:2'),
(3536, 33, 3, 'وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '33:3'),
(3537, 33, 4, 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ ۚ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّـٰٓـِٔى تُظَـٰهِرُونَ مِنْهُنَّ أُمَّهَـٰتِكُمْ ۚ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ۚ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ ۖ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', '33:4'),
(3538, 33, 5, 'ٱدْعُوهُمْ لِـَٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ ۚ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ ۚ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَـٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '33:5'),
(3539, 33, 6, 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ ۖ وَأَزْوَٰجُهُۥٓ أُمَّهَـٰتُهُمْ ۗ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَـٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَـٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَـٰبِ مَسْطُورًا', '33:6'),
(3540, 33, 7, 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَـٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَـٰقًا غَلِيظًا', '33:7'),
(3541, 33, 8, 'لِّيَسْـَٔلَ ٱلصَّـٰدِقِينَ عَن صِدْقِهِمْ ۚ وَأَعَدَّ لِلْكَـٰفِرِينَ عَذَابًا أَلِيمًا', '33:8'),
(3542, 33, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '33:9'),
(3543, 33, 10, 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَـٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', '33:10'),
(3544, 33, 11, 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا', '33:11'),
(3545, 33, 12, 'وَإِذْ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا', '33:12'),
(3546, 33, 13, 'وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَـٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ ۚ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ ۖ إِن يُرِيدُونَ إِلَّا فِرَارًا', '33:13'),
(3547, 33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَـَٔاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا', '33:14'),
(3548, 33, 15, 'وَلَقَدْ كَانُوا۟ عَـٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَـٰرَ ۚ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا', '33:15'),
(3549, 33, 16, 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا', '33:16'),
(3550, 33, 17, 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً ۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', '33:17'),
(3551, 33, 18, '۞ قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا ۖ وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', '33:18'),
(3552, 33, 19, 'أَشِحَّةً عَلَيْكُمْ ۖ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ ۚ أُو۟لَـٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَـٰلَهُمْ ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '33:19'),
(3553, 33, 20, 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ ۖ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ ۖ وَلَوْ كَانُوا۟ فِيكُم مَّا قَـٰتَلُوٓا۟ إِلَّا قَلِيلًا', '33:20'),
(3554, 33, 21, 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا', '33:21'),
(3555, 33, 22, 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَـٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ ۚ وَمَا زَادَهُمْ إِلَّآ إِيمَـٰنًا وَتَسْلِيمًا', '33:22'),
(3556, 33, 23, 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَـٰهَدُوا۟ ٱللَّهَ عَلَيْهِ ۖ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ ۖ وَمَا بَدَّلُوا۟ تَبْدِيلًا', '33:23'),
(3557, 33, 24, 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّـٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَـٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '33:24'),
(3558, 33, 25, 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا ۚ وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ ۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا', '33:25'),
(3559, 33, 26, 'وَأَنزَلَ ٱلَّذِينَ ظَـٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَـٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', '33:26'),
(3560, 33, 27, 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَـٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '33:27'),
(3561, 33, 28, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', '33:28'),
(3562, 33, 29, 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَـٰتِ مِنكُنَّ أَجْرًا عَظِيمًا', '33:29'),
(3563, 33, 30, 'يَـٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ يُضَـٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '33:30'),
(3564, 33, 31, '۞ وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَـٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', '33:31'),
(3565, 33, 32, 'يَـٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ ۚ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', '33:32'),
(3566, 33, 33, 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَـٰهِلِيَّةِ ٱلْأُولَىٰ ۖ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', '33:33'),
(3567, 33, 34, 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَـٰتِ ٱللَّهِ وَٱلْحِكْمَةِ ۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', '33:34'),
(3568, 33, 35, 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَـٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَٱلْقَـٰنِتِينَ وَٱلْقَـٰنِتَـٰتِ وَٱلصَّـٰدِقِينَ وَٱلصَّـٰدِقَـٰتِ وَٱلصَّـٰبِرِينَ وَٱلصَّـٰبِرَٰتِ وَٱلْخَـٰشِعِينَ وَٱلْخَـٰشِعَـٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَـٰتِ وَٱلصَّـٰٓئِمِينَ وَٱلصَّـٰٓئِمَـٰتِ وَٱلْحَـٰفِظِينَ فُرُوجَهُمْ وَٱلْحَـٰفِظَـٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', '33:35'),
(3569, 33, 36, 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ ۗ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَـٰلًا مُّبِينًا', '33:36'),
(3570, 33, 37, 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ ۖ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَـٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '33:37'),
(3571, 33, 38, 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ ۖ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۚ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا', '33:38'),
(3572, 33, 39, 'ٱلَّذِينَ يُبَلِّغُونَ رِسَـٰلَـٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ ۗ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', '33:39'),
(3573, 33, 40, 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَـٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَ ۗ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '33:40'),
(3574, 33, 41, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا', '33:41'),
(3575, 33, 42, 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '33:42'),
(3576, 33, 43, 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَـٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا', '33:43'),
(3577, 33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَـٰمٌ ۚ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', '33:44'),
(3578, 33, 45, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَـٰكَ شَـٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', '33:45'),
(3579, 33, 46, 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا', '33:46'),
(3580, 33, 47, 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا', '33:47'),
(3581, 33, 48, 'وَلَا تُطِعِ ٱلْكَـٰفِرِينَ وَٱلْمُنَـٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '33:48'),
(3582, 33, 49, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَـٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا ۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', '33:49'),
(3583, 33, 50, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّـٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَـٰلَـٰتِكَ ٱلَّـٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ ۗ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَـٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '33:50'),
(3584, 33, 51, '۞ تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ ۖ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ۚ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ ۚ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا', '33:51'),
(3585, 33, 52, 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا', '33:52'),
(3586, 33, 53, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَـٰظِرِينَ إِنَىٰهُ وَلَـٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ ۚ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ ۖ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ ۚ وَإِذَا سَأَلْتُمُوهُنَّ مَتَـٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ۚ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ۚ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا ۚ إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', '33:53'),
(3587, 33, 54, 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', '33:54'),
(3588, 33, 55, 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَـٰنُهُنَّ ۗ وَٱتَّقِينَ ٱللَّهَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '33:55'),
(3589, 33, 56, 'إِنَّ ٱللَّهَ وَمَلَـٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ ۚ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', '33:56'),
(3590, 33, 57, 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', '33:57'),
(3591, 33, 58, 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا', '33:58'),
(3592, 33, 59, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَـٰبِيبِهِنَّ ۚ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '33:59'),
(3593, 33, 60, '۞ لَّئِن لَّمْ يَنتَهِ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا', '33:60'),
(3594, 33, 61, 'مَّلْعُونِينَ ۖ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا', '33:61'),
(3595, 33, 62, 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', '33:62'),
(3596, 33, 63, 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ ۚ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', '33:63'),
(3597, 33, 64, 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَـٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', '33:64'),
(3598, 33, 65, 'خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', '33:65'),
(3599, 33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَـٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', '33:66'),
(3600, 33, 67, 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', '33:67'),
(3601, 33, 68, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا', '33:68'),
(3602, 33, 69, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ ۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا', '33:69'),
(3603, 33, 70, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا', '33:70'),
(3604, 33, 71, 'يُصْلِحْ لَكُمْ أَعْمَـٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', '33:71'),
(3605, 33, 72, 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَـٰنُ ۖ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا', '33:72'),
(3606, 33, 73, 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَـٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا', '33:73'),
(3607, 34, 1, ' ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْـَٔاخِرَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '34:1'),
(3608, 34, 2, 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۚ وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', '34:2'),
(3609, 34, 3, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ ۖ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَـٰلِمِ ٱلْغَيْبِ ۖ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ', '34:3'),
(3610, 34, 4, 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۚ أُو۟لَـٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '34:4'),
(3611, 34, 5, 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَـٰتِنَا مُعَـٰجِزِينَ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', '34:5'),
(3612, 34, 6, 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', '34:6'),
(3613, 34, 7, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ', '34:7'),
(3614, 34, 8, 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ ۗ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَـٰلِ ٱلْبَعِيدِ', '34:8'),
(3615, 34, 9, 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ', '34:9'),
(3616, 34, 10, '۞ وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا ۖ يَـٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ ۖ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', '34:10'),
(3617, 34, 11, 'أَنِ ٱعْمَلْ سَـٰبِغَـٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ ۖ وَٱعْمَلُوا۟ صَـٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ', '34:11'),
(3618, 34, 12, 'وَلِسُلَيْمَـٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ ۖ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ ۖ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ ۖ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', '34:12'),
(3619, 34, 13, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَـٰرِيبَ وَتَمَـٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَـٰتٍ ۚ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا ۚ وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ', '34:13'),
(3620, 34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ ۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', '34:14'),
(3621, 34, 15, 'لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ ۖ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ ۖ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ ۚ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', '34:15'),
(3622, 34, 16, 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَـٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ', '34:16'),
(3623, 34, 17, 'ذَٰلِكَ جَزَيْنَـٰهُم بِمَا كَفَرُوا۟ ۖ وَهَلْ نُجَـٰزِىٓ إِلَّا ٱلْكَفُورَ', '34:17'),
(3624, 34, 18, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَـٰرَكْنَا فِيهَا قُرًى ظَـٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ ۖ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', '34:18'),
(3625, 34, 19, 'فَقَالُوا۟ رَبَّنَا بَـٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَـٰهُمْ أَحَادِيثَ وَمَزَّقْنَـٰهُمْ كُلَّ مُمَزَّقٍ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '34:19'),
(3626, 34, 20, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ', '34:20'),
(3627, 34, 21, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَـٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْـَٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ ۗ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', '34:21'),
(3628, 34, 22, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ ۖ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ', '34:22'),
(3629, 34, 23, 'وَلَا تَنفَعُ ٱلشَّفَـٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ ۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ ۖ قَالُوا۟ ٱلْحَقَّ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '34:23'),
(3630, 34, 24, '۞ قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُلِ ٱللَّهُ ۖ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَـٰلٍ مُّبِينٍ', '34:24'),
(3631, 34, 25, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', '34:25'),
(3632, 34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', '34:26'),
(3633, 34, 27, 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ ۖ كَلَّا ۚ بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', '34:27'),
(3634, 34, 28, 'وَمَآ أَرْسَلْنَـٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '34:28'),
(3635, 34, 29, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '34:29'),
(3636, 34, 30, 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', '34:30'),
(3637, 34, 31, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَـٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', '34:31'),
(3638, 34, 32, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَـٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم ۖ بَلْ كُنتُم مُّجْرِمِينَ', '34:32'),
(3639, 34, 33, 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا ۚ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَـٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', '34:33'),
(3640, 34, 34, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَـٰفِرُونَ', '34:34'),
(3641, 34, 35, 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَـٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ', '34:35'),
(3642, 34, 36, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '34:36'),
(3643, 34, 37, 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَـٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَـٰلِحًا فَأُو۟لَـٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَـٰتِ ءَامِنُونَ', '34:37'),
(3644, 34, 38, 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَـٰتِنَا مُعَـٰجِزِينَ أُو۟لَـٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '34:38'),
(3645, 34, 39, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ ۚ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', '34:39'),
(3646, 34, 40, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَـٰٓئِكَةِ أَهَـٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', '34:40'),
(3647, 34, 41, 'قَالُوا۟ سُبْحَـٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم ۖ بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ ۖ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', '34:41'),
(3648, 34, 42, 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', '34:42'),
(3649, 34, 43, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ قَالُوا۟ مَا هَـٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَـٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى ۚ وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '34:43'),
(3650, 34, 44, 'وَمَآ ءَاتَيْنَـٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا ۖ وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', '34:44'),
(3651, 34, 45, 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَـٰهُمْ فَكَذَّبُوا۟ رُسُلِى ۖ فَكَيْفَ كَانَ نَكِيرِ', '34:45'),
(3652, 34, 46, '۞ قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ ۖ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ ۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ', '34:46'),
(3653, 34, 47, 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '34:47'),
(3654, 34, 48, 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّـٰمُ ٱلْغُيُوبِ', '34:48'),
(3655, 34, 49, 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَـٰطِلُ وَمَا يُعِيدُ', '34:49'),
(3656, 34, 50, 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى ۖ وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ ۚ إِنَّهُۥ سَمِيعٌ قَرِيبٌ', '34:50'),
(3657, 34, 51, 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ', '34:51'),
(3658, 34, 52, 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ', '34:52'),
(3659, 34, 53, 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ ۖ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ', '34:53'),
(3660, 34, 54, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ ۚ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ', '34:54'),
(3661, 35, 1, ' ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَـٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '35:1'),
(3662, 35, 2, 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا ۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '35:2'),
(3663, 35, 3, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ ۚ هَلْ مِنْ خَـٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', '35:3'),
(3664, 35, 4, 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '35:4'),
(3665, 35, 5, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۖ وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', '35:5'),
(3666, 35, 6, 'إِنَّ ٱلشَّيْطَـٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا ۚ إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَـٰبِ ٱلسَّعِيرِ', '35:6'),
(3667, 35, 7, 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ ۖ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '35:7'),
(3668, 35, 8, 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا ۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۖ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', '35:8'),
(3669, 35, 9, 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَـٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَـٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ كَذَٰلِكَ ٱلنُّشُورُ', '35:9'),
(3670, 35, 10, 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا ۚ إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّـٰلِحُ يَرْفَعُهُۥ ۚ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ ۖ وَمَكْرُ أُو۟لَـٰٓئِكَ هُوَ يَبُورُ', '35:10'),
(3671, 35, 11, 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا ۚ وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَـٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '35:11'),
(3672, 35, 12, 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَـٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَـٰذَا مِلْحٌ أُجَاجٌ ۖ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا ۖ وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '35:12'),
(3673, 35, 13, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۚ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', '35:13'),
(3674, 35, 14, 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ ۚ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ', '35:14'),
(3675, 35, 15, '۞ يَـٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '35:15'),
(3676, 35, 16, 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', '35:16'),
(3677, 35, 17, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', '35:17'),
(3678, 35, 18, 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ ۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ ۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ ۚ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', '35:18'),
(3679, 35, 19, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', '35:19'),
(3680, 35, 20, 'وَلَا ٱلظُّلُمَـٰتُ وَلَا ٱلنُّورُ', '35:20'),
(3681, 35, 21, 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', '35:21'),
(3682, 35, 22, 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ ۚ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ ۖ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ', '35:22'),
(3683, 35, 23, 'إِنْ أَنتَ إِلَّا نَذِيرٌ', '35:23'),
(3684, 35, 24, 'إِنَّآ أَرْسَلْنَـٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا ۚ وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', '35:24'),
(3685, 35, 25, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَـٰبِ ٱلْمُنِيرِ', '35:25'),
(3686, 35, 26, 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ ۖ فَكَيْفَ كَانَ نَكِيرِ', '35:26'),
(3687, 35, 27, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا ۚ وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ', '35:27'),
(3688, 35, 28, 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَـٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ ۗ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَـٰٓؤُا۟ ۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', '35:28'),
(3689, 35, 29, 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَـٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَـٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَـٰرَةً لَّن تَبُورَ', '35:29'),
(3690, 35, 30, 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ ۚ إِنَّهُۥ غَفُورٌ شَكُورٌ', '35:30'),
(3691, 35, 31, 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَـٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ ۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ', '35:31'),
(3692, 35, 32, 'ثُمَّ أَوْرَثْنَا ٱلْكِتَـٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا ۖ فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '35:32'),
(3693, 35, 33, 'جَنَّـٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا ۖ وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', '35:33'),
(3694, 35, 34, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ ۖ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', '35:34'),
(3695, 35, 35, 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', '35:35'),
(3696, 35, 36, 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا ۚ كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ', '35:36'),
(3697, 35, 37, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَـٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ ۖ فَذُوقُوا۟ فَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٍ', '35:37'),
(3698, 35, 38, 'إِنَّ ٱللَّهَ عَـٰلِمُ غَيْبِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '35:38'),
(3699, 35, 39, 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَـٰٓئِفَ فِى ٱلْأَرْضِ ۚ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ ۖ وَلَا يَزِيدُ ٱلْكَـٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا ۖ وَلَا يَزِيدُ ٱلْكَـٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', '35:39'),
(3700, 35, 40, 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَـٰوَٰتِ أَمْ ءَاتَيْنَـٰهُمْ كِتَـٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ ۚ بَلْ إِن يَعِدُ ٱلظَّـٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', '35:40'),
(3701, 35, 41, '۞ إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا ۚ وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ ۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', '35:41'),
(3702, 35, 42, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ ۖ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', '35:42'),
(3703, 35, 43, 'ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ ۚ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ ۚ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ ۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا ۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', '35:43'),
(3704, 35, 44, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً ۚ وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا', '35:44'),
(3705, 35, 45, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَـٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۖ فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', '35:45'),
(3706, 36, 1, ' يسٓ', '36:1'),
(3707, 36, 2, 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', '36:2'),
(3708, 36, 3, 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', '36:3'),
(3709, 36, 4, 'عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '36:4'),
(3710, 36, 5, 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', '36:5'),
(3711, 36, 6, 'لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَـٰفِلُونَ', '36:6'),
(3712, 36, 7, 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', '36:7'),
(3713, 36, 8, 'إِنَّا جَعَلْنَا فِىٓ أَعْنَـٰقِهِمْ أَغْلَـٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', '36:8'),
(3714, 36, 9, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَـٰهُمْ فَهُمْ لَا يُبْصِرُونَ', '36:9'),
(3715, 36, 10, 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '36:10'),
(3716, 36, 11, 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَـٰنَ بِٱلْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ', '36:11'),
(3717, 36, 12, 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَـٰرَهُمْ ۚ وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ فِىٓ إِمَامٍ مُّبِينٍ', '36:12'),
(3718, 36, 13, 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَـٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', '36:13'),
(3719, 36, 14, 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', '36:14'),
(3720, 36, 15, 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَـٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', '36:15'),
(3721, 36, 16, 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', '36:16'),
(3722, 36, 17, 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '36:17'),
(3723, 36, 18, 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ', '36:18'),
(3724, 36, 19, 'قَالُوا۟ طَـٰٓئِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '36:19'),
(3725, 36, 20, 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَـٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', '36:20'),
(3726, 36, 21, 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', '36:21'),
(3727, 36, 22, 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', '36:22'),
(3728, 36, 23, 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَـٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَـٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ', '36:23'),
(3729, 36, 24, 'إِنِّىٓ إِذًا لَّفِى ضَلَـٰلٍ مُّبِينٍ', '36:24'),
(3730, 36, 25, 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', '36:25'),
(3731, 36, 26, 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ ۖ قَالَ يَـٰلَيْتَ قَوْمِى يَعْلَمُونَ', '36:26'),
(3732, 36, 27, 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', '36:27'),
(3733, 36, 28, '۞ وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', '36:28'),
(3734, 36, 29, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَـٰمِدُونَ', '36:29'),
(3735, 36, 30, 'يَـٰحَسْرَةً عَلَى ٱلْعِبَادِ ۚ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '36:30'),
(3736, 36, 31, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', '36:31'),
(3737, 36, 32, 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '36:32'),
(3738, 36, 33, 'وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَـٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', '36:33'),
(3739, 36, 34, 'وَجَعَلْنَا فِيهَا جَنَّـٰتٍ مِّن نَّخِيلٍ وَأَعْنَـٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', '36:34'),
(3740, 36, 35, 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ ۖ أَفَلَا يَشْكُرُونَ', '36:35'),
(3741, 36, 36, 'سُبْحَـٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', '36:36'),
(3742, 36, 37, 'وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', '36:37'),
(3743, 36, 38, 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', '36:38'),
(3744, 36, 39, 'وَٱلْقَمَرَ قَدَّرْنَـٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', '36:39'),
(3745, 36, 40, 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ ۚ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ', '36:40'),
(3746, 36, 41, 'وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', '36:41'),
(3747, 36, 42, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', '36:42'),
(3748, 36, 43, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', '36:43'),
(3749, 36, 44, 'إِلَّا رَحْمَةً مِّنَّا وَمَتَـٰعًا إِلَىٰ حِينٍ', '36:44'),
(3750, 36, 45, 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', '36:45'),
(3751, 36, 46, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '36:46'),
(3752, 36, 47, 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ مُّبِينٍ', '36:47'),
(3753, 36, 48, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '36:48'),
(3754, 36, 49, 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', '36:49'),
(3755, 36, 50, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', '36:50'),
(3756, 36, 51, 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', '36:51'),
(3757, 36, 52, 'قَالُوا۟ يَـٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا ۜ ۗ هَـٰذَا مَا وَعَدَ ٱلرَّحْمَـٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', '36:52'),
(3758, 36, 53, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '36:53'),
(3759, 36, 54, 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', '36:54'),
(3760, 36, 55, 'إِنَّ أَصْحَـٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَـٰكِهُونَ', '36:55'),
(3761, 36, 56, 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَـٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', '36:56'),
(3762, 36, 57, 'لَهُمْ فِيهَا فَـٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', '36:57'),
(3763, 36, 58, 'سَلَـٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', '36:58'),
(3764, 36, 59, 'وَٱمْتَـٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', '36:59'),
(3765, 36, 60, '۞ أَلَمْ أَعْهَدْ إِلَيْكُمْ يَـٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَـٰنَ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '36:60'),
(3766, 36, 61, 'وَأَنِ ٱعْبُدُونِى ۚ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '36:61'),
(3767, 36, 62, 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا ۖ أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', '36:62'),
(3768, 36, 63, 'هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', '36:63'),
(3769, 36, 64, 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', '36:64'),
(3770, 36, 65, 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', '36:65'),
(3771, 36, 66, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', '36:66'),
(3772, 36, 67, 'وَلَوْ نَشَآءُ لَمَسَخْنَـٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَـٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ', '36:67'),
(3773, 36, 68, 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ', '36:68'),
(3774, 36, 69, 'وَمَا عَلَّمْنَـٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ', '36:69'),
(3775, 36, 70, 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَـٰفِرِينَ', '36:70'),
(3776, 36, 71, 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَـٰمًا فَهُمْ لَهَا مَـٰلِكُونَ', '36:71'),
(3777, 36, 72, 'وَذَلَّلْنَـٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', '36:72'),
(3778, 36, 73, 'وَلَهُمْ فِيهَا مَنَـٰفِعُ وَمَشَارِبُ ۖ أَفَلَا يَشْكُرُونَ', '36:73'),
(3779, 36, 74, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ', '36:74'),
(3780, 36, 75, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', '36:75'),
(3781, 36, 76, 'فَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', '36:76'),
(3782, 36, 77, 'أَوَلَمْ يَرَ ٱلْإِنسَـٰنُ أَنَّا خَلَقْنَـٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', '36:77'),
(3783, 36, 78, 'وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ ۖ قَالَ مَن يُحْىِ ٱلْعِظَـٰمَ وَهِىَ رَمِيمٌ', '36:78'),
(3784, 36, 79, 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', '36:79'),
(3785, 36, 80, 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', '36:80'),
(3786, 36, 81, 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِقَـٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم ۚ بَلَىٰ وَهُوَ ٱلْخَلَّـٰقُ ٱلْعَلِيمُ', '36:81'),
(3787, 36, 82, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', '36:82'),
(3788, 36, 83, 'فَسُبْحَـٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ', '36:83'),
(3789, 37, 1, ' وَٱلصَّـٰٓفَّـٰتِ صَفًّا', '37:1'),
(3790, 37, 2, 'فَٱلزَّٰجِرَٰتِ زَجْرًا', '37:2'),
(3791, 37, 3, 'فَٱلتَّـٰلِيَـٰتِ ذِكْرًا', '37:3'),
(3792, 37, 4, 'إِنَّ إِلَـٰهَكُمْ لَوَٰحِدٌ', '37:4'),
(3793, 37, 5, 'رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَـٰرِقِ', '37:5'),
(3794, 37, 6, 'إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ', '37:6'),
(3795, 37, 7, 'وَحِفْظًا مِّن كُلِّ شَيْطَـٰنٍ مَّارِدٍ', '37:7'),
(3796, 37, 8, 'لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ', '37:8'),
(3797, 37, 9, 'دُحُورًا ۖ وَلَهُمْ عَذَابٌ وَاصِبٌ', '37:9'),
(3798, 37, 10, 'إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ', '37:10'),
(3799, 37, 11, 'فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ ۚ إِنَّا خَلَقْنَـٰهُم مِّن طِينٍ لَّازِبٍۭ', '37:11'),
(3800, 37, 12, 'بَلْ عَجِبْتَ وَيَسْخَرُونَ', '37:12'),
(3801, 37, 13, 'وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ', '37:13'),
(3802, 37, 14, 'وَإِذَا رَأَوْا۟ ءَايَةً يَسْتَسْخِرُونَ', '37:14'),
(3803, 37, 15, 'وَقَالُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '37:15'),
(3804, 37, 16, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ', '37:16'),
(3805, 37, 17, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', '37:17'),
(3806, 37, 18, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ', '37:18'),
(3807, 37, 19, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ', '37:19'),
(3808, 37, 20, 'وَقَالُوا۟ يَـٰوَيْلَنَا هَـٰذَا يَوْمُ ٱلدِّينِ', '37:20'),
(3809, 37, 21, 'هَـٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', '37:21'),
(3810, 37, 22, '۞ ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ', '37:22'),
(3811, 37, 23, 'مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ', '37:23'),
(3812, 37, 24, 'وَقِفُوهُمْ ۖ إِنَّهُم مَّسْـُٔولُونَ', '37:24'),
(3813, 37, 25, 'مَا لَكُمْ لَا تَنَاصَرُونَ', '37:25'),
(3814, 37, 26, 'بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ', '37:26'),
(3815, 37, 27, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', '37:27'),
(3816, 37, 28, 'قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ', '37:28'),
(3817, 37, 29, 'قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ', '37:29'),
(3818, 37, 30, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَـٰنٍۭ ۖ بَلْ كُنتُمْ قَوْمًا طَـٰغِينَ', '37:30'),
(3819, 37, 31, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ ۖ إِنَّا لَذَآئِقُونَ', '37:31'),
(3820, 37, 32, 'فَأَغْوَيْنَـٰكُمْ إِنَّا كُنَّا غَـٰوِينَ', '37:32'),
(3821, 37, 33, 'فَإِنَّهُمْ يَوْمَئِذٍ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', '37:33'),
(3822, 37, 34, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', '37:34'),
(3823, 37, 35, 'إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَـٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ', '37:35'),
(3824, 37, 36, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍ مَّجْنُونٍۭ', '37:36'),
(3825, 37, 37, 'بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ', '37:37'),
(3826, 37, 38, 'إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ', '37:38'),
(3827, 37, 39, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', '37:39'),
(3828, 37, 40, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', '37:40'),
(3829, 37, 41, 'أُو۟لَـٰٓئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ', '37:41'),
(3830, 37, 42, 'فَوَٰكِهُ ۖ وَهُم مُّكْرَمُونَ', '37:42'),
(3831, 37, 43, 'فِى جَنَّـٰتِ ٱلنَّعِيمِ', '37:43'),
(3832, 37, 44, 'عَلَىٰ سُرُرٍ مُّتَقَـٰبِلِينَ', '37:44'),
(3833, 37, 45, 'يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍۭ', '37:45'),
(3834, 37, 46, 'بَيْضَآءَ لَذَّةٍ لِّلشَّـٰرِبِينَ', '37:46'),
(3835, 37, 47, 'لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ', '37:47'),
(3836, 37, 48, 'وَعِندَهُمْ قَـٰصِرَٰتُ ٱلطَّرْفِ عِينٌ', '37:48'),
(3837, 37, 49, 'كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ', '37:49'),
(3838, 37, 50, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', '37:50'),
(3839, 37, 51, 'قَالَ قَآئِلٌ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌ', '37:51'),
(3840, 37, 52, 'يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ', '37:52'),
(3841, 37, 53, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَدِينُونَ', '37:53'),
(3842, 37, 54, 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', '37:54'),
(3843, 37, 55, 'فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ', '37:55'),
(3844, 37, 56, 'قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ', '37:56'),
(3845, 37, 57, 'وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ', '37:57'),
(3846, 37, 58, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', '37:58'),
(3847, 37, 59, 'إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', '37:59'),
(3848, 37, 60, 'إِنَّ هَـٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '37:60'),
(3849, 37, 61, 'لِمِثْلِ هَـٰذَا فَلْيَعْمَلِ ٱلْعَـٰمِلُونَ', '37:61'),
(3850, 37, 62, 'أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ', '37:62'),
(3851, 37, 63, 'إِنَّا جَعَلْنَـٰهَا فِتْنَةً لِّلظَّـٰلِمِينَ', '37:63'),
(3852, 37, 64, 'إِنَّهَا شَجَرَةٌ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ', '37:64'),
(3853, 37, 65, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَـٰطِينِ', '37:65'),
(3854, 37, 66, 'فَإِنَّهُمْ لَـَٔاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', '37:66'),
(3855, 37, 67, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ', '37:67'),
(3856, 37, 68, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ', '37:68'),
(3857, 37, 69, 'إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ', '37:69'),
(3858, 37, 70, 'فَهُمْ عَلَىٰٓ ءَاثَـٰرِهِمْ يُهْرَعُونَ', '37:70'),
(3859, 37, 71, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ', '37:71'),
(3860, 37, 72, 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', '37:72'),
(3861, 37, 73, 'فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُنذَرِينَ', '37:73'),
(3862, 37, 74, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', '37:74'),
(3863, 37, 75, 'وَلَقَدْ نَادَىٰنَا نُوحٌ فَلَنِعْمَ ٱلْمُجِيبُونَ', '37:75'),
(3864, 37, 76, 'وَنَجَّيْنَـٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', '37:76'),
(3865, 37, 77, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ', '37:77'),
(3866, 37, 78, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', '37:78'),
(3867, 37, 79, 'سَلَـٰمٌ عَلَىٰ نُوحٍ فِى ٱلْعَـٰلَمِينَ', '37:79'),
(3868, 37, 80, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '37:80'),
(3869, 37, 81, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', '37:81'),
(3870, 37, 82, 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', '37:82'),
(3871, 37, 83, '۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', '37:83'),
(3872, 37, 84, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍ سَلِيمٍ', '37:84'),
(3873, 37, 85, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ', '37:85'),
(3874, 37, 86, 'أَئِفْكًا ءَالِهَةً دُونَ ٱللَّهِ تُرِيدُونَ', '37:86'),
(3875, 37, 87, 'فَمَا ظَنُّكُم بِرَبِّ ٱلْعَـٰلَمِينَ', '37:87'),
(3876, 37, 88, 'فَنَظَرَ نَظْرَةً فِى ٱلنُّجُومِ', '37:88'),
(3877, 37, 89, 'فَقَالَ إِنِّى سَقِيمٌ', '37:89'),
(3878, 37, 90, 'فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ', '37:90'),
(3879, 37, 91, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', '37:91'),
(3880, 37, 92, 'مَا لَكُمْ لَا تَنطِقُونَ', '37:92'),
(3881, 37, 93, 'فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ', '37:93'),
(3882, 37, 94, 'فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ', '37:94'),
(3883, 37, 95, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', '37:95'),
(3884, 37, 96, 'وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', '37:96'),
(3885, 37, 97, 'قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَـٰنًا فَأَلْقُوهُ فِى ٱلْجَحِيمِ', '37:97'),
(3886, 37, 98, 'فَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَـٰهُمُ ٱلْأَسْفَلِينَ', '37:98'),
(3887, 37, 99, 'وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ', '37:99'),
(3888, 37, 100, 'رَبِّ هَبْ لِى مِنَ ٱلصَّـٰلِحِينَ', '37:100'),
(3889, 37, 101, 'فَبَشَّرْنَـٰهُ بِغُلَـٰمٍ حَلِيمٍ', '37:101'),
(3890, 37, 102, 'فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَـٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَـٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰبِرِينَ', '37:102'),
(3891, 37, 103, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', '37:103'),
(3892, 37, 104, 'وَنَـٰدَيْنَـٰهُ أَن يَـٰٓإِبْرَٰهِيمُ', '37:104'),
(3893, 37, 105, 'قَدْ صَدَّقْتَ ٱلرُّءْيَآ ۚ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '37:105'),
(3894, 37, 106, 'إِنَّ هَـٰذَا لَهُوَ ٱلْبَلَـٰٓؤُا۟ ٱلْمُبِينُ', '37:106'),
(3895, 37, 107, 'وَفَدَيْنَـٰهُ بِذِبْحٍ عَظِيمٍ', '37:107'),
(3896, 37, 108, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', '37:108'),
(3897, 37, 109, 'سَلَـٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ', '37:109'),
(3898, 37, 110, 'كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '37:110'),
(3899, 37, 111, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', '37:111'),
(3900, 37, 112, 'وَبَشَّرْنَـٰهُ بِإِسْحَـٰقَ نَبِيًّا مِّنَ ٱلصَّـٰلِحِينَ', '37:112'),
(3901, 37, 113, 'وَبَـٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَـٰقَ ۚ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِۦ مُبِينٌ', '37:113'),
(3902, 37, 114, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَـٰرُونَ', '37:114'),
(3903, 37, 115, 'وَنَجَّيْنَـٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', '37:115'),
(3904, 37, 116, 'وَنَصَرْنَـٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَـٰلِبِينَ', '37:116'),
(3905, 37, 117, 'وَءَاتَيْنَـٰهُمَا ٱلْكِتَـٰبَ ٱلْمُسْتَبِينَ', '37:117'),
(3906, 37, 118, 'وَهَدَيْنَـٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', '37:118'),
(3907, 37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْـَٔاخِرِينَ', '37:119'),
(3908, 37, 120, 'سَلَـٰمٌ عَلَىٰ مُوسَىٰ وَهَـٰرُونَ', '37:120'),
(3909, 37, 121, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '37:121'),
(3910, 37, 122, 'إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', '37:122'),
(3911, 37, 123, 'وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ', '37:123'),
(3912, 37, 124, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', '37:124'),
(3913, 37, 125, 'أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ ٱلْخَـٰلِقِينَ', '37:125'),
(3914, 37, 126, 'ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', '37:126'),
(3915, 37, 127, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', '37:127'),
(3916, 37, 128, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', '37:128'),
(3917, 37, 129, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', '37:129'),
(3918, 37, 130, 'سَلَـٰمٌ عَلَىٰٓ إِلْ يَاسِينَ', '37:130'),
(3919, 37, 131, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '37:131'),
(3920, 37, 132, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', '37:132'),
(3921, 37, 133, 'وَإِنَّ لُوطًا لَّمِنَ ٱلْمُرْسَلِينَ', '37:133'),
(3922, 37, 134, 'إِذْ نَجَّيْنَـٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', '37:134'),
(3923, 37, 135, 'إِلَّا عَجُوزًا فِى ٱلْغَـٰبِرِينَ', '37:135'),
(3924, 37, 136, 'ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ', '37:136'),
(3925, 37, 137, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', '37:137'),
(3926, 37, 138, 'وَبِٱلَّيْلِ ۗ أَفَلَا تَعْقِلُونَ', '37:138'),
(3927, 37, 139, 'وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ', '37:139'),
(3928, 37, 140, 'إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ', '37:140'),
(3929, 37, 141, 'فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ', '37:141'),
(3930, 37, 142, 'فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌ', '37:142'),
(3931, 37, 143, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ', '37:143'),
(3932, 37, 144, 'لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '37:144'),
(3933, 37, 145, '۞ فَنَبَذْنَـٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌ', '37:145'),
(3934, 37, 146, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ', '37:146'),
(3935, 37, 147, 'وَأَرْسَلْنَـٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ', '37:147'),
(3936, 37, 148, 'فَـَٔامَنُوا۟ فَمَتَّعْنَـٰهُمْ إِلَىٰ حِينٍ', '37:148'),
(3937, 37, 149, 'فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ', '37:149'),
(3938, 37, 150, 'أَمْ خَلَقْنَا ٱلْمَلَـٰٓئِكَةَ إِنَـٰثًا وَهُمْ شَـٰهِدُونَ', '37:150'),
(3939, 37, 151, 'أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', '37:151'),
(3940, 37, 152, 'وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَـٰذِبُونَ', '37:152'),
(3941, 37, 153, 'أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ', '37:153'),
(3942, 37, 154, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', '37:154'),
(3943, 37, 155, 'أَفَلَا تَذَكَّرُونَ', '37:155'),
(3944, 37, 156, 'أَمْ لَكُمْ سُلْطَـٰنٌ مُّبِينٌ', '37:156'),
(3945, 37, 157, 'فَأْتُوا۟ بِكِتَـٰبِكُمْ إِن كُنتُمْ صَـٰدِقِينَ', '37:157'),
(3946, 37, 158, 'وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًا ۚ وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', '37:158'),
(3947, 37, 159, 'سُبْحَـٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', '37:159'),
(3948, 37, 160, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', '37:160'),
(3949, 37, 161, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', '37:161'),
(3950, 37, 162, 'مَآ أَنتُمْ عَلَيْهِ بِفَـٰتِنِينَ', '37:162'),
(3951, 37, 163, 'إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ', '37:163'),
(3952, 37, 164, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌ مَّعْلُومٌ', '37:164'),
(3953, 37, 165, 'وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ', '37:165'),
(3954, 37, 166, 'وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ', '37:166'),
(3955, 37, 167, 'وَإِن كَانُوا۟ لَيَقُولُونَ', '37:167'),
(3956, 37, 168, 'لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ ٱلْأَوَّلِينَ', '37:168'),
(3957, 37, 169, 'لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', '37:169'),
(3958, 37, 170, 'فَكَفَرُوا۟ بِهِۦ ۖ فَسَوْفَ يَعْلَمُونَ', '37:170'),
(3959, 37, 171, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ', '37:171'),
(3960, 37, 172, 'إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ', '37:172'),
(3961, 37, 173, 'وَإِنَّ جُندَنَا لَهُمُ ٱلْغَـٰلِبُونَ', '37:173'),
(3962, 37, 174, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', '37:174'),
(3963, 37, 175, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', '37:175'),
(3964, 37, 176, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', '37:176'),
(3965, 37, 177, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ', '37:177'),
(3966, 37, 178, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', '37:178'),
(3967, 37, 179, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', '37:179'),
(3968, 37, 180, 'سُبْحَـٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', '37:180'),
(3969, 37, 181, 'وَسَلَـٰمٌ عَلَى ٱلْمُرْسَلِينَ', '37:181'),
(3970, 37, 182, 'وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '37:182'),
(3971, 38, 1, ' صٓ ۚ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ', '38:1'),
(3972, 38, 2, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍ وَشِقَاقٍ', '38:2'),
(3973, 38, 3, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ', '38:3'),
(3974, 38, 4, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ ۖ وَقَالَ ٱلْكَـٰفِرُونَ هَـٰذَا سَـٰحِرٌ كَذَّابٌ', '38:4'),
(3975, 38, 5, 'أَجَعَلَ ٱلْـَٔالِهَةَ إِلَـٰهًا وَٰحِدًا ۖ إِنَّ هَـٰذَا لَشَىْءٌ عُجَابٌ', '38:5'),
(3976, 38, 6, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ ۖ إِنَّ هَـٰذَا لَشَىْءٌ يُرَادُ', '38:6'),
(3977, 38, 7, 'مَا سَمِعْنَا بِهَـٰذَا فِى ٱلْمِلَّةِ ٱلْـَٔاخِرَةِ إِنْ هَـٰذَآ إِلَّا ٱخْتِلَـٰقٌ', '38:7'),
(3978, 38, 8, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا ۚ بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى ۖ بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', '38:8'),
(3979, 38, 9, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', '38:9'),
(3980, 38, 10, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَـٰبِ', '38:10'),
(3981, 38, 11, 'جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ', '38:11'),
(3982, 38, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', '38:12'),
(3983, 38, 13, 'وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَـٰبُ لْـَٔيْكَةِ ۚ أُو۟لَـٰٓئِكَ ٱلْأَحْزَابُ', '38:13'),
(3984, 38, 14, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', '38:14'),
(3985, 38, 15, 'وَمَا يَنظُرُ هَـٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ', '38:15'),
(3986, 38, 16, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', '38:16'),
(3987, 38, 17, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ ۖ إِنَّهُۥٓ أَوَّابٌ', '38:17'),
(3988, 38, 18, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', '38:18'),
(3989, 38, 19, 'وَٱلطَّيْرَ مَحْشُورَةً ۖ كُلٌّ لَّهُۥٓ أَوَّابٌ', '38:19'),
(3990, 38, 20, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَـٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', '38:20'),
(3991, 38, 21, '۞ وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', '38:21'),
(3992, 38, 22, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ ۖ قَالُوا۟ لَا تَخَفْ ۖ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', '38:22'),
(3993, 38, 23, 'إِنَّ هَـٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', '38:23'),
(3994, 38, 24, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ ۖ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَقَلِيلٌ مَّا هُمْ ۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ ۩', '38:24'),
(3995, 38, 25, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ ۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '38:25'),
(3996, 38, 26, 'يَـٰدَاوُۥدُ إِنَّا جَعَلْنَـٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', '38:26'),
(3997, 38, 27, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَـٰطِلًا ۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ ۚ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', '38:27'),
(3998, 38, 28, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', '38:28'),
(3999, 38, 29, 'كِتَـٰبٌ أَنزَلْنَـٰهُ إِلَيْكَ مُبَـٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَـٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '38:29'),
(4000, 38, 30, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَـٰنَ ۚ نِعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌ', '38:30');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(4001, 38, 31, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّـٰفِنَـٰتُ ٱلْجِيَادُ', '38:31'),
(4002, 38, 32, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', '38:32'),
(4003, 38, 33, 'رُدُّوهَا عَلَىَّ ۖ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', '38:33'),
(4004, 38, 34, 'وَلَقَدْ فَتَنَّا سُلَيْمَـٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ', '38:34'),
(4005, 38, 35, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ ۖ إِنَّكَ أَنتَ ٱلْوَهَّابُ', '38:35'),
(4006, 38, 36, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', '38:36'),
(4007, 38, 37, 'وَٱلشَّيَـٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ', '38:37'),
(4008, 38, 38, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', '38:38'),
(4009, 38, 39, 'هَـٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', '38:39'),
(4010, 38, 40, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '38:40'),
(4011, 38, 41, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَـٰنُ بِنُصْبٍ وَعَذَابٍ', '38:41'),
(4012, 38, 42, 'ٱرْكُضْ بِرِجْلِكَ ۖ هَـٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ', '38:42'),
(4013, 38, 43, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَـٰبِ', '38:43'),
(4014, 38, 44, 'وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ ۗ إِنَّا وَجَدْنَـٰهُ صَابِرًا ۚ نِّعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌ', '38:44'),
(4015, 38, 45, 'وَٱذْكُرْ عِبَـٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَـٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَـٰرِ', '38:45'),
(4016, 38, 46, 'إِنَّآ أَخْلَصْنَـٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ', '38:46'),
(4017, 38, 47, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', '38:47'),
(4018, 38, 48, 'وَٱذْكُرْ إِسْمَـٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ ۖ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ', '38:48'),
(4019, 38, 49, 'هَـٰذَا ذِكْرٌ ۚ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ', '38:49'),
(4020, 38, 50, 'جَنَّـٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ', '38:50'),
(4021, 38, 51, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَـٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', '38:51'),
(4022, 38, 52, '۞ وَعِندَهُمْ قَـٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', '38:52'),
(4023, 38, 53, 'هَـٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', '38:53'),
(4024, 38, 54, 'إِنَّ هَـٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', '38:54'),
(4025, 38, 55, 'هَـٰذَا ۚ وَإِنَّ لِلطَّـٰغِينَ لَشَرَّ مَـَٔابٍ', '38:55'),
(4026, 38, 56, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', '38:56'),
(4027, 38, 57, 'هَـٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', '38:57'),
(4028, 38, 58, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', '38:58'),
(4029, 38, 59, 'هَـٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ ۖ لَا مَرْحَبًۢا بِهِمْ ۚ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', '38:59'),
(4030, 38, 60, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ ۖ أَنتُمْ قَدَّمْتُمُوهُ لَنَا ۖ فَبِئْسَ ٱلْقَرَارُ', '38:60'),
(4031, 38, 61, 'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَـٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى ٱلنَّارِ', '38:61'),
(4032, 38, 62, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', '38:62'),
(4033, 38, 63, 'أَتَّخَذْنَـٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَـٰرُ', '38:63'),
(4034, 38, 64, 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ', '38:64'),
(4035, 38, 65, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ ۖ وَمَا مِنْ إِلَـٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', '38:65'),
(4036, 38, 66, 'رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّـٰرُ', '38:66'),
(4037, 38, 67, 'قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ', '38:67'),
(4038, 38, 68, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', '38:68'),
(4039, 38, 69, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', '38:69'),
(4040, 38, 70, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', '38:70'),
(4041, 38, 71, 'إِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌۢ بَشَرًا مِّن طِينٍ', '38:71'),
(4042, 38, 72, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَـٰجِدِينَ', '38:72'),
(4043, 38, 73, 'فَسَجَدَ ٱلْمَلَـٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '38:73'),
(4044, 38, 74, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ', '38:74'),
(4045, 38, 75, 'قَالَ يَـٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ ۖ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', '38:75'),
(4046, 38, 76, 'قَالَ أَنَا۠ خَيْرٌ مِّنْهُ ۖ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', '38:76'),
(4047, 38, 77, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '38:77'),
(4048, 38, 78, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', '38:78'),
(4049, 38, 79, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '38:79'),
(4050, 38, 80, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '38:80'),
(4051, 38, 81, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', '38:81'),
(4052, 38, 82, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', '38:82'),
(4053, 38, 83, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '38:83'),
(4054, 38, 84, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', '38:84'),
(4055, 38, 85, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', '38:85'),
(4056, 38, 86, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', '38:86'),
(4057, 38, 87, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', '38:87'),
(4058, 38, 88, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', '38:88'),
(4059, 39, 1, ' تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '39:1'),
(4060, 39, 2, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '39:2'),
(4061, 39, 3, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَـٰذِبٌ كَفَّارٌ', '39:3'),
(4062, 39, 4, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ ۚ سُبْحَـٰنَهُۥ ۖ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', '39:4'),
(4063, 39, 5, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۗ أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّـٰرُ', '39:5'),
(4064, 39, 6, 'خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَـٰمِ ثَمَـٰنِيَةَ أَزْوَٰجٍ ۚ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَـٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَـٰتٍ ثَلَـٰثٍ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُصْرَفُونَ', '39:6'),
(4065, 39, 7, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ ۖ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ ۖ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ ۗ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۗ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '39:7'),
(4066, 39, 8, '۞ وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ ۚ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا ۖ إِنَّكَ مِنْ أَصْحَـٰبِ ٱلنَّارِ', '39:8'),
(4067, 39, 9, 'أَمَّنْ هُوَ قَـٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْـَٔاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ ۗ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '39:9'),
(4068, 39, 10, 'قُلْ يَـٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ ۚ لِلَّذِينَ أَحْسَنُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةٌ ۗ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ ۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ', '39:10'),
(4069, 39, 11, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '39:11'),
(4070, 39, 12, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', '39:12'),
(4071, 39, 13, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', '39:13'),
(4072, 39, 14, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى', '39:14'),
(4073, 39, 15, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ ۗ قُلْ إِنَّ ٱلْخَـٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '39:15'),
(4074, 39, 16, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ ۚ يَـٰعِبَادِ فَٱتَّقُونِ', '39:16'),
(4075, 39, 17, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّـٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ ۚ فَبَشِّرْ عِبَادِ', '39:17'),
(4076, 39, 18, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَـٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', '39:18'),
(4077, 39, 19, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', '39:19'),
(4078, 39, 20, 'لَـٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', '39:20'),
(4079, 39, 21, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَـٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَـٰمًا ۚ إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَـٰبِ', '39:21'),
(4080, 39, 22, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَـٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ ۚ فَوَيْلٌ لِّلْقَـٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍ مُّبِينٍ', '39:22'),
(4081, 39, 23, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَـٰبًا مُّتَشَـٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '39:23'),
(4082, 39, 24, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَـٰمَةِ ۚ وَقِيلَ لِلظَّـٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', '39:24'),
(4083, 39, 25, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '39:25'),
(4084, 39, 26, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', '39:26'),
(4085, 39, 27, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَـٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', '39:27'),
(4086, 39, 28, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', '39:28'),
(4087, 39, 29, 'ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَـٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '39:29'),
(4088, 39, 30, 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', '39:30'),
(4089, 39, 31, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَـٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', '39:31'),
(4090, 39, 32, '۞ فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَـٰفِرِينَ', '39:32'),
(4091, 39, 33, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ ۙ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', '39:33'),
(4092, 39, 34, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '39:34'),
(4093, 39, 35, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '39:35'),
(4094, 39, 36, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ ۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '39:36'),
(4095, 39, 37, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ ۗ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ', '39:37'),
(4096, 39, 38, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ ۚ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَـٰشِفَـٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَـٰتُ رَحْمَتِهِۦ ۚ قُلْ حَسْبِىَ ٱللَّهُ ۖ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', '39:38'),
(4097, 39, 39, 'قُلْ يَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَـٰمِلٌ ۖ فَسَوْفَ تَعْلَمُونَ', '39:39'),
(4098, 39, 40, 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '39:40'),
(4099, 39, 41, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَـٰبَ لِلنَّاسِ بِٱلْحَقِّ ۖ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '39:41'),
(4100, 39, 42, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا ۖ فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '39:42'),
(4101, 39, 43, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ ۚ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ', '39:43'),
(4102, 39, 44, 'قُل لِّلَّهِ ٱلشَّفَـٰعَةُ جَمِيعًا ۖ لَّهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '39:44'),
(4103, 39, 45, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ ۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '39:45'),
(4104, 39, 46, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ عَـٰلِمَ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '39:46'),
(4105, 39, 47, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَـٰمَةِ ۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', '39:47'),
(4106, 39, 48, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '39:48'),
(4107, 39, 49, 'فَإِذَا مَسَّ ٱلْإِنسَـٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَـٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ ۚ بَلْ هِىَ فِتْنَةٌ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '39:49'),
(4108, 39, 50, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', '39:50'),
(4109, 39, 51, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ ۚ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَـٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', '39:51'),
(4110, 39, 52, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '39:52'),
(4111, 39, 53, '۞ قُلْ يَـٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '39:53'),
(4112, 39, 54, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', '39:54'),
(4113, 39, 55, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', '39:55'),
(4114, 39, 56, 'أَن تَقُولَ نَفْسٌ يَـٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِينَ', '39:56'),
(4115, 39, 57, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', '39:57'),
(4116, 39, 58, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', '39:58'),
(4117, 39, 59, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَـٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَـٰفِرِينَ', '39:59'),
(4118, 39, 60, 'وَيَوْمَ ٱلْقِيَـٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', '39:60'),
(4119, 39, 61, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', '39:61'),
(4120, 39, 62, 'ٱللَّهُ خَـٰلِقُ كُلِّ شَىْءٍ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '39:62'),
(4121, 39, 63, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '39:63'),
(4122, 39, 64, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَـٰهِلُونَ', '39:64'),
(4123, 39, 65, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ', '39:65'),
(4124, 39, 66, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّـٰكِرِينَ', '39:66'),
(4125, 39, 67, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَـٰمَةِ وَٱلسَّمَـٰوَٰتُ مَطْوِيَّـٰتٌۢ بِيَمِينِهِۦ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', '39:67'),
(4126, 39, 68, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۖ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', '39:68'),
(4127, 39, 69, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَـٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', '39:69'),
(4128, 39, 70, 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', '39:70'),
(4129, 39, 71, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَـٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ بَلَىٰ وَلَـٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَـٰفِرِينَ', '39:71'),
(4130, 39, 72, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', '39:72'),
(4131, 39, 73, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَـٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَـٰلِدِينَ', '39:73'),
(4132, 39, 74, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ ۖ فَنِعْمَ أَجْرُ ٱلْعَـٰمِلِينَ', '39:74'),
(4133, 39, 75, 'وَتَرَى ٱلْمَلَـٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ ۖ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '39:75'),
(4134, 40, 1, ' حمٓ', '40:1'),
(4135, 40, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', '40:2'),
(4136, 40, 3, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ إِلَيْهِ ٱلْمَصِيرُ', '40:3'),
(4137, 40, 4, 'مَا يُجَـٰدِلُ فِىٓ ءَايَـٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَـٰدِ', '40:4'),
(4138, 40, 5, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ ۖ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ ۖ وَجَـٰدَلُوا۟ بِٱلْبَـٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', '40:5'),
(4139, 40, 6, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَـٰبُ ٱلنَّارِ', '40:6'),
(4140, 40, 7, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', '40:7'),
(4141, 40, 8, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّـٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّـٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '40:8'),
(4142, 40, 9, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ ۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '40:9'),
(4143, 40, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَـٰنِ فَتَكْفُرُونَ', '40:10'),
(4144, 40, 11, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ', '40:11'),
(4145, 40, 12, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ ۖ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ ۚ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', '40:12'),
(4146, 40, 13, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَـٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا ۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', '40:13'),
(4147, 40, 14, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', '40:14'),
(4148, 40, 15, 'رَفِيعُ ٱلدَّرَجَـٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', '40:15'),
(4149, 40, 16, 'يَوْمَ هُم بَـٰرِزُونَ ۖ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ ۚ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ ۖ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', '40:16'),
(4150, 40, 17, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ ۚ لَا ظُلْمَ ٱلْيَوْمَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '40:17'),
(4151, 40, 18, 'وَأَنذِرْهُمْ يَوْمَ ٱلْـَٔازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَـٰظِمِينَ ۚ مَا لِلظَّـٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ', '40:18'),
(4152, 40, 19, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', '40:19'),
(4153, 40, 20, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ ۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '40:20'),
(4154, 40, 21, '۞ أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ ۚ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '40:21'),
(4155, 40, 22, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ ۚ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '40:22'),
(4156, 40, 23, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَا وَسُلْطَـٰنٍ مُّبِينٍ', '40:23'),
(4157, 40, 24, 'إِلَىٰ فِرْعَوْنَ وَهَـٰمَـٰنَ وَقَـٰرُونَ فَقَالُوا۟ سَـٰحِرٌ كَذَّابٌ', '40:24'),
(4158, 40, 25, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ ۚ وَمَا كَيْدُ ٱلْكَـٰفِرِينَ إِلَّا فِى ضَلَـٰلٍ', '40:25'),
(4159, 40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ ۖ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', '40:26'),
(4160, 40, 27, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', '40:27'),
(4161, 40, 28, 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَـٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَـٰتِ مِن رَّبِّكُمْ ۖ وَإِن يَكُ كَـٰذِبًا فَعَلَيْهِ كَذِبُهُۥ ۖ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', '40:28'),
(4162, 40, 29, 'يَـٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَـٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا ۚ قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', '40:29'),
(4163, 40, 30, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَـٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', '40:30'),
(4164, 40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۚ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', '40:31'),
(4165, 40, 32, 'وَيَـٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', '40:32'),
(4166, 40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '40:33'),
(4167, 40, 34, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَـٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ ۖ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', '40:34'),
(4168, 40, 35, 'ٱلَّذِينَ يُجَـٰدِلُونَ فِىٓ ءَايَـٰتِ ٱللَّهِ بِغَيْرِ سُلْطَـٰنٍ أَتَىٰهُمْ ۖ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', '40:35'),
(4169, 40, 36, 'وَقَالَ فِرْعَوْنُ يَـٰهَـٰمَـٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَـٰبَ', '40:36'),
(4170, 40, 37, 'أَسْبَـٰبَ ٱلسَّمَـٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَـٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَـٰذِبًا ۚ وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ ۚ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ', '40:37'),
(4171, 40, 38, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَـٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', '40:38'),
(4172, 40, 39, 'يَـٰقَوْمِ إِنَّمَا هَـٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَـٰعٌ وَإِنَّ ٱلْـَٔاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', '40:39'),
(4173, 40, 40, 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا ۖ وَمَنْ عَمِلَ صَـٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', '40:40'),
(4174, 40, 41, '۞ وَيَـٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', '40:41'),
(4175, 40, 42, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّـٰرِ', '40:42'),
(4176, 40, 43, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْـَٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَـٰبُ ٱلنَّارِ', '40:43'),
(4177, 40, 44, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ ۚ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', '40:44'),
(4178, 40, 45, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ ۖ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', '40:45'),
(4179, 40, 46, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا ۖ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', '40:46'),
(4180, 40, 47, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَـٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ', '40:47'),
(4181, 40, 48, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', '40:48'),
(4182, 40, 49, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ', '40:49'),
(4183, 40, 50, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَـٰتِ ۖ قَالُوا۟ بَلَىٰ ۚ قَالُوا۟ فَٱدْعُوا۟ ۗ وَمَا دُعَـٰٓؤُا۟ ٱلْكَـٰفِرِينَ إِلَّا فِى ضَلَـٰلٍ', '40:50'),
(4184, 40, 51, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَـٰدُ', '40:51'),
(4185, 40, 52, 'يَوْمَ لَا يَنفَعُ ٱلظَّـٰلِمِينَ مَعْذِرَتُهُمْ ۖ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '40:52'),
(4186, 40, 53, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَـٰبَ', '40:53'),
(4187, 40, 54, 'هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَـٰبِ', '40:54'),
(4188, 40, 55, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَـٰرِ', '40:55'),
(4189, 40, 56, 'إِنَّ ٱلَّذِينَ يُجَـٰدِلُونَ فِىٓ ءَايَـٰتِ ٱللَّهِ بِغَيْرِ سُلْطَـٰنٍ أَتَىٰهُمْ ۙ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَـٰلِغِيهِ ۚ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '40:56'),
(4190, 40, 57, 'لَخَلْقُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '40:57'),
(4191, 40, 58, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَلَا ٱلْمُسِىٓءُ ۚ قَلِيلًا مَّا تَتَذَكَّرُونَ', '40:58'),
(4192, 40, 59, 'إِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', '40:59'),
(4193, 40, 60, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ ۚ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', '40:60'),
(4194, 40, 61, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '40:61'),
(4195, 40, 62, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَـٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', '40:62'),
(4196, 40, 63, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ', '40:63'),
(4197, 40, 64, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ', '40:64'),
(4198, 40, 65, 'هُوَ ٱلْحَىُّ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۗ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', '40:65'),
(4199, 40, 66, '۞ قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَـٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَـٰلَمِينَ', '40:66'),
(4200, 40, 67, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا ۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ ۖ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', '40:67'),
(4201, 40, 68, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ ۖ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '40:68'),
(4202, 40, 69, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَـٰدِلُونَ فِىٓ ءَايَـٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', '40:69'),
(4203, 40, 70, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَـٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا ۖ فَسَوْفَ يَعْلَمُونَ', '40:70'),
(4204, 40, 71, 'إِذِ ٱلْأَغْلَـٰلُ فِىٓ أَعْنَـٰقِهِمْ وَٱلسَّلَـٰسِلُ يُسْحَبُونَ', '40:71'),
(4205, 40, 72, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', '40:72'),
(4206, 40, 73, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', '40:73'),
(4207, 40, 74, 'مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَـٰفِرِينَ', '40:74'),
(4208, 40, 75, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', '40:75'),
(4209, 40, 76, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', '40:76'),
(4210, 40, 77, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۚ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', '40:77'),
(4211, 40, 78, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', '40:78'),
(4212, 40, 79, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَـٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', '40:79'),
(4213, 40, 80, 'وَلَكُمْ فِيهَا مَنَـٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', '40:80'),
(4214, 40, 81, 'وَيُرِيكُمْ ءَايَـٰتِهِۦ فَأَىَّ ءَايَـٰتِ ٱللَّهِ تُنكِرُونَ', '40:81'),
(4215, 40, 82, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', '40:82'),
(4216, 40, 83, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '40:83'),
(4217, 40, 84, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', '40:84'),
(4218, 40, 85, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَـٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا ۖ سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ ۖ وَخَسِرَ هُنَالِكَ ٱلْكَـٰفِرُونَ', '40:85'),
(4219, 41, 1, ' حمٓ', '41:1'),
(4220, 41, 2, 'تَنزِيلٌ مِّنَ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', '41:2'),
(4221, 41, 3, 'كِتَـٰبٌ فُصِّلَتْ ءَايَـٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', '41:3'),
(4222, 41, 4, 'بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', '41:4'),
(4223, 41, 5, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَـٰمِلُونَ', '41:5'),
(4224, 41, 6, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ ۗ وَوَيْلٌ لِّلْمُشْرِكِينَ', '41:6'),
(4225, 41, 7, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ', '41:7'),
(4226, 41, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', '41:8'),
(4227, 41, 9, '۞ قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ۚ ذَٰلِكَ رَبُّ ٱلْعَـٰلَمِينَ', '41:9'),
(4228, 41, 10, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَـٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ', '41:10'),
(4229, 41, 11, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ', '41:11'),
(4230, 41, 12, 'فَقَضَىٰهُنَّ سَبْعَ سَمَـٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا ۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَحِفْظًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', '41:12'),
(4231, 41, 13, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَـٰعِقَةً مِّثْلَ صَـٰعِقَةِ عَادٍ وَثَمُودَ', '41:13'),
(4232, 41, 14, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَـٰفِرُونَ', '41:14'),
(4233, 41, 15, 'فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً ۖ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً ۖ وَكَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ', '41:15'),
(4234, 41, 16, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَخْزَىٰ ۖ وَهُمْ لَا يُنصَرُونَ', '41:16'),
(4235, 41, 17, 'وَأَمَّا ثَمُودُ فَهَدَيْنَـٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَـٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', '41:17'),
(4236, 41, 18, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '41:18'),
(4237, 41, 19, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', '41:19'),
(4238, 41, 20, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَـٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '41:20'),
(4239, 41, 21, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا ۖ قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', '41:21'),
(4240, 41, 22, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَـٰرُكُمْ وَلَا جُلُودُكُمْ وَلَـٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', '41:22'),
(4241, 41, 23, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَـٰسِرِينَ', '41:23'),
(4242, 41, 24, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ ۖ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', '41:24'),
(4243, 41, 25, '۞ وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَـٰسِرِينَ', '41:25'),
(4244, 41, 26, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَـٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', '41:26'),
(4245, 41, 27, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '41:27'),
(4246, 41, 28, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ ۖ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ ۖ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ', '41:28'),
(4247, 41, 29, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', '41:29'),
(4248, 41, 30, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَـٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَـٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', '41:30'),
(4249, 41, 31, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۖ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', '41:31'),
(4250, 41, 32, 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', '41:32'),
(4251, 41, 33, 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَـٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', '41:33'),
(4252, 41, 34, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', '41:34'),
(4253, 41, 35, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ', '41:35'),
(4254, 41, 36, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَـٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '41:36'),
(4255, 41, 37, 'وَمِنْ ءَايَـٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ ۚ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', '41:37'),
(4256, 41, 38, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ ۩', '41:38'),
(4257, 41, 39, 'وَمِنْ ءَايَـٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَـٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ ۚ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ ۚ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '41:39'),
(4258, 41, 40, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَـٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ ۗ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَـٰمَةِ ۚ ٱعْمَلُوا۟ مَا شِئْتُمْ ۖ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '41:40'),
(4259, 41, 41, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ ۖ وَإِنَّهُۥ لَكِتَـٰبٌ عَزِيزٌ', '41:41'),
(4260, 41, 42, 'لَّا يَأْتِيهِ ٱلْبَـٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ ۖ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', '41:42'),
(4261, 41, 43, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ ۚ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', '41:43'),
(4262, 41, 44, 'وَلَوْ جَعَلْنَـٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَـٰتُهُۥٓ ۖ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ ۗ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ ۖ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى ۚ أُو۟لَـٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ', '41:44'),
(4263, 41, 45, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ فَٱخْتُلِفَ فِيهِ ۗ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '41:45'),
(4264, 41, 46, 'مَّنْ عَمِلَ صَـٰلِحًا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۗ وَمَا رَبُّكَ بِظَلَّـٰمٍ لِّلْعَبِيدِ', '41:46'),
(4265, 41, 47, '۞ إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ ۚ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّـٰكَ مَا مِنَّا مِن شَهِيدٍ', '41:47'),
(4266, 41, 48, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ ۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ', '41:48'),
(4267, 41, 49, 'لَّا يَسْـَٔمُ ٱلْإِنسَـٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ', '41:49'),
(4268, 41, 50, 'وَلَئِنْ أَذَقْنَـٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَـٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ ۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', '41:50'),
(4269, 41, 51, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَـٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ', '41:51'),
(4270, 41, 52, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ', '41:52'),
(4271, 41, 53, 'سَنُرِيهِمْ ءَايَـٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '41:53'),
(4272, 41, 54, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ ۗ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ', '41:54'),
(4273, 42, 1, ' حمٓ', '42:1'),
(4274, 42, 2, 'عٓسٓقٓ', '42:2'),
(4275, 42, 3, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', '42:3'),
(4276, 42, 4, 'لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', '42:4'),
(4277, 42, 5, 'تَكَادُ ٱلسَّمَـٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ ۚ وَٱلْمَلَـٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ ۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '42:5'),
(4278, 42, 6, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '42:6'),
(4279, 42, 7, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ ۚ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ', '42:7'),
(4280, 42, 8, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ', '42:8'),
(4281, 42, 9, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۖ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '42:9'),
(4282, 42, 10, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '42:10'),
(4283, 42, 11, 'فَاطِرُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَـٰمِ أَزْوَٰجًا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '42:11'),
(4284, 42, 12, 'لَهُۥ مَقَالِيدُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ', '42:12'),
(4285, 42, 13, '۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', '42:13'),
(4286, 42, 14, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ ۚ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَـٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '42:14'),
(4287, 42, 15, 'فَلِذَٰلِكَ فَٱدْعُ ۖ وَٱسْتَقِمْ كَمَآ أُمِرْتَ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ ۖ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَـٰبٍ ۖ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ ۖ لَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ ۖ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ۖ ٱللَّهُ يَجْمَعُ بَيْنَنَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', '42:15'),
(4288, 42, 16, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ', '42:16'),
(4289, 42, 17, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَـٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ ۗ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ', '42:17'),
(4290, 42, 18, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا ۖ وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ ۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَـٰلٍۭ بَعِيدٍ', '42:18'),
(4291, 42, 19, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', '42:19'),
(4292, 42, 20, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْـَٔاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ ۖ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِن نَّصِيبٍ', '42:20'),
(4293, 42, 21, 'أَمْ لَهُمْ شُرَكَـٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ ۚ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ ۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '42:21'),
(4294, 42, 22, 'تَرَى ٱلظَّـٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ ۗ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ ۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '42:22'),
(4295, 42, 23, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ ۗ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا ۚ إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ', '42:23'),
(4296, 42, 24, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۖ فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ ۗ وَيَمْحُ ٱللَّهُ ٱلْبَـٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَـٰتِهِۦٓ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '42:24'),
(4297, 42, 25, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', '42:25'),
(4298, 42, 26, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۚ وَٱلْكَـٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', '42:26'),
(4299, 42, 27, '۞ وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَـٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ ۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ', '42:27'),
(4300, 42, 28, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ ۚ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', '42:28'),
(4301, 42, 29, 'وَمِنْ ءَايَـٰتِهِۦ خَلْقُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ ۚ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ', '42:29'),
(4302, 42, 30, 'وَمَآ أَصَـٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ', '42:30'),
(4303, 42, 31, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '42:31'),
(4304, 42, 32, 'وَمِنْ ءَايَـٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَـٰمِ', '42:32'),
(4305, 42, 33, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '42:33'),
(4306, 42, 34, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ', '42:34'),
(4307, 42, 35, 'وَيَعْلَمَ ٱلَّذِينَ يُجَـٰدِلُونَ فِىٓ ءَايَـٰتِنَا مَا لَهُم مِّن مَّحِيصٍ', '42:35'),
(4308, 42, 36, 'فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '42:36'),
(4309, 42, 37, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَـٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', '42:37'),
(4310, 42, 38, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', '42:38'),
(4311, 42, 39, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', '42:39'),
(4312, 42, 40, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا ۖ فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّـٰلِمِينَ', '42:40'),
(4313, 42, 41, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَـٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', '42:41'),
(4314, 42, 42, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', '42:42'),
(4315, 42, 43, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', '42:43'),
(4316, 42, 44, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ ۗ وَتَرَى ٱلظَّـٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', '42:44'),
(4317, 42, 45, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَـٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ ۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَـٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ أَلَآ إِنَّ ٱلظَّـٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ', '42:45'),
(4318, 42, 46, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', '42:46'),
(4319, 42, 47, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ ۚ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', '42:47'),
(4320, 42, 48, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا ۖ إِنْ عَلَيْكَ إِلَّا ٱلْبَلَـٰغُ ۗ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَـٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَـٰنَ كَفُورٌ', '42:48'),
(4321, 42, 49, 'لِّلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ يَخْلُقُ مَا يَشَآءُ ۚ يَهَبُ لِمَن يَشَآءُ إِنَـٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', '42:49'),
(4322, 42, 50, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَـٰثًا ۖ وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا ۚ إِنَّهُۥ عَلِيمٌ قَدِيرٌ', '42:50'),
(4323, 42, 51, '۞ وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ ۚ إِنَّهُۥ عَلِىٌّ حَكِيمٌ', '42:51'),
(4324, 42, 52, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا ۚ مَا كُنتَ تَدْرِى مَا ٱلْكِتَـٰبُ وَلَا ٱلْإِيمَـٰنُ وَلَـٰكِن جَعَلْنَـٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا ۚ وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '42:52'),
(4325, 42, 53, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', '42:53'),
(4326, 43, 1, ' حمٓ', '43:1'),
(4327, 43, 2, 'وَٱلْكِتَـٰبِ ٱلْمُبِينِ', '43:2'),
(4328, 43, 3, 'إِنَّا جَعَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '43:3'),
(4329, 43, 4, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَـٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', '43:4'),
(4330, 43, 5, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ', '43:5'),
(4331, 43, 6, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ', '43:6'),
(4332, 43, 7, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '43:7'),
(4333, 43, 8, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', '43:8'),
(4334, 43, 9, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', '43:9'),
(4335, 43, 10, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '43:10'),
(4336, 43, 11, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا ۚ كَذَٰلِكَ تُخْرَجُونَ', '43:11'),
(4337, 43, 12, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَـٰمِ مَا تَرْكَبُونَ', '43:12'),
(4338, 43, 13, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَـٰنَ ٱلَّذِى سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', '43:13'),
(4339, 43, 14, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', '43:14'),
(4340, 43, 15, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا ۚ إِنَّ ٱلْإِنسَـٰنَ لَكَفُورٌ مُّبِينٌ', '43:15'),
(4341, 43, 16, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ', '43:16'),
(4342, 43, 17, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَـٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', '43:17'),
(4343, 43, 18, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ', '43:18'),
(4344, 43, 19, 'وَجَعَلُوا۟ ٱلْمَلَـٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَـٰدُ ٱلرَّحْمَـٰنِ إِنَـٰثًا ۚ أَشَهِدُوا۟ خَلْقَهُمْ ۚ سَتُكْتَبُ شَهَـٰدَتُهُمْ وَيُسْـَٔلُونَ', '43:19'),
(4345, 43, 20, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَـٰنُ مَا عَبَدْنَـٰهُم ۗ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَخْرُصُونَ', '43:20'),
(4346, 43, 21, 'أَمْ ءَاتَيْنَـٰهُمْ كِتَـٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', '43:21'),
(4347, 43, 22, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَـٰرِهِم مُّهْتَدُونَ', '43:22'),
(4348, 43, 23, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَـٰرِهِم مُّقْتَدُونَ', '43:23'),
(4349, 43, 24, '۞ قَـٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ ۖ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَـٰفِرُونَ', '43:24'),
(4350, 43, 25, 'فَٱنتَقَمْنَا مِنْهُمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ', '43:25'),
(4351, 43, 26, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ', '43:26'),
(4352, 43, 27, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', '43:27'),
(4353, 43, 28, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', '43:28'),
(4354, 43, 29, 'بَلْ مَتَّعْتُ هَـٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ', '43:29'),
(4355, 43, 30, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَـٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَـٰفِرُونَ', '43:30'),
(4356, 43, 31, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَـٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', '43:31'),
(4357, 43, 32, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ ۚ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَـٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا ۗ وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '43:32'),
(4358, 43, 33, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَـٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', '43:33'),
(4359, 43, 34, 'وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', '43:34'),
(4360, 43, 35, 'وَزُخْرُفًا ۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَٱلْـَٔاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', '43:35'),
(4361, 43, 36, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَـٰنِ نُقَيِّضْ لَهُۥ شَيْطَـٰنًا فَهُوَ لَهُۥ قَرِينٌ', '43:36'),
(4362, 43, 37, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '43:37'),
(4363, 43, 38, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَـٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', '43:38'),
(4364, 43, 39, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', '43:39'),
(4365, 43, 40, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَـٰلٍ مُّبِينٍ', '43:40'),
(4366, 43, 41, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', '43:41'),
(4367, 43, 42, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَـٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', '43:42'),
(4368, 43, 43, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ ۖ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '43:43'),
(4369, 43, 44, 'وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ ۖ وَسَوْفَ تُسْـَٔلُونَ', '43:44'),
(4370, 43, 45, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَـٰنِ ءَالِهَةً يُعْبَدُونَ', '43:45'),
(4371, 43, 46, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَـٰلَمِينَ', '43:46'),
(4372, 43, 47, 'فَلَمَّا جَآءَهُم بِـَٔايَـٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', '43:47'),
(4373, 43, 48, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا ۖ وَأَخَذْنَـٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', '43:48'),
(4374, 43, 49, 'وَقَالُوا۟ يَـٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', '43:49'),
(4375, 43, 50, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', '43:50'),
(4376, 43, 51, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَـٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَـٰذِهِ ٱلْأَنْهَـٰرُ تَجْرِى مِن تَحْتِىٓ ۖ أَفَلَا تُبْصِرُونَ', '43:51'),
(4377, 43, 52, 'أَمْ أَنَا۠ خَيْرٌ مِّنْ هَـٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', '43:52'),
(4378, 43, 53, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَـٰٓئِكَةُ مُقْتَرِنِينَ', '43:53'),
(4379, 43, 54, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ', '43:54'),
(4380, 43, 55, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَـٰهُمْ أَجْمَعِينَ', '43:55'),
(4381, 43, 56, 'فَجَعَلْنَـٰهُمْ سَلَفًا وَمَثَلًا لِّلْـَٔاخِرِينَ', '43:56'),
(4382, 43, 57, '۞ وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', '43:57'),
(4383, 43, 58, 'وَقَالُوٓا۟ ءَأَـٰلِهَتُنَا خَيْرٌ أَمْ هُوَ ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا ۚ بَلْ هُمْ قَوْمٌ خَصِمُونَ', '43:58'),
(4384, 43, 59, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَـٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ', '43:59'),
(4385, 43, 60, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَـٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ', '43:60'),
(4386, 43, 61, 'وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ ۚ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '43:61'),
(4387, 43, 62, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَـٰنُ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '43:62'),
(4388, 43, 63, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَـٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', '43:63'),
(4389, 43, 64, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '43:64'),
(4390, 43, 65, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', '43:65'),
(4391, 43, 66, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '43:66'),
(4392, 43, 67, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', '43:67'),
(4393, 43, 68, 'يَـٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', '43:68'),
(4394, 43, 69, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', '43:69'),
(4395, 43, 70, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', '43:70'),
(4396, 43, 71, 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ ۖ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ ۖ وَأَنتُمْ فِيهَا خَـٰلِدُونَ', '43:71'),
(4397, 43, 72, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', '43:72'),
(4398, 43, 73, 'لَكُمْ فِيهَا فَـٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', '43:73'),
(4399, 43, 74, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَـٰلِدُونَ', '43:74'),
(4400, 43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', '43:75'),
(4401, 43, 76, 'وَمَا ظَلَمْنَـٰهُمْ وَلَـٰكِن كَانُوا۟ هُمُ ٱلظَّـٰلِمِينَ', '43:76'),
(4402, 43, 77, 'وَنَادَوْا۟ يَـٰمَـٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ ۖ قَالَ إِنَّكُم مَّـٰكِثُونَ', '43:77'),
(4403, 43, 78, 'لَقَدْ جِئْنَـٰكُم بِٱلْحَقِّ وَلَـٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَـٰرِهُونَ', '43:78'),
(4404, 43, 79, 'أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ', '43:79'),
(4405, 43, 80, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم ۚ بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', '43:80'),
(4406, 43, 81, 'قُلْ إِن كَانَ لِلرَّحْمَـٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَـٰبِدِينَ', '43:81'),
(4407, 43, 82, 'سُبْحَـٰنَ رَبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', '43:82'),
(4408, 43, 83, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', '43:83'),
(4409, 43, 84, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَـٰهٌ وَفِى ٱلْأَرْضِ إِلَـٰهٌ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', '43:84'),
(4410, 43, 85, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', '43:85'),
(4411, 43, 86, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَـٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', '43:86'),
(4412, 43, 87, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ', '43:87'),
(4413, 43, 88, 'وَقِيلِهِۦ يَـٰرَبِّ إِنَّ هَـٰٓؤُلَآءِ قَوْمٌ لَّا يُؤْمِنُونَ', '43:88'),
(4414, 43, 89, 'فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَـٰمٌ ۚ فَسَوْفَ يَعْلَمُونَ', '43:89'),
(4415, 44, 1, ' حمٓ', '44:1'),
(4416, 44, 2, 'وَٱلْكِتَـٰبِ ٱلْمُبِينِ', '44:2'),
(4417, 44, 3, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةٍ مُّبَـٰرَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ', '44:3'),
(4418, 44, 4, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', '44:4'),
(4419, 44, 5, 'أَمْرًا مِّنْ عِندِنَآ ۚ إِنَّا كُنَّا مُرْسِلِينَ', '44:5'),
(4420, 44, 6, 'رَحْمَةً مِّن رَّبِّكَ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '44:6'),
(4421, 44, 7, 'رَبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', '44:7'),
(4422, 44, 8, 'لَآ إِلَـٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', '44:8'),
(4423, 44, 9, 'بَلْ هُمْ فِى شَكٍّ يَلْعَبُونَ', '44:9'),
(4424, 44, 10, 'فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍ مُّبِينٍ', '44:10'),
(4425, 44, 11, 'يَغْشَى ٱلنَّاسَ ۖ هَـٰذَا عَذَابٌ أَلِيمٌ', '44:11'),
(4426, 44, 12, 'رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ', '44:12'),
(4427, 44, 13, 'أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌ مُّبِينٌ', '44:13'),
(4428, 44, 14, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ', '44:14'),
(4429, 44, 15, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا ۚ إِنَّكُمْ عَآئِدُونَ', '44:15'),
(4430, 44, 16, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', '44:16'),
(4431, 44, 17, '۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ', '44:17'),
(4432, 44, 18, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ ۖ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '44:18'),
(4433, 44, 19, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ ۖ إِنِّىٓ ءَاتِيكُم بِسُلْطَـٰنٍ مُّبِينٍ', '44:19'),
(4434, 44, 20, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', '44:20'),
(4435, 44, 21, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', '44:21'),
(4436, 44, 22, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَـٰٓؤُلَآءِ قَوْمٌ مُّجْرِمُونَ', '44:22'),
(4437, 44, 23, 'فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ', '44:23'),
(4438, 44, 24, 'وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا ۖ إِنَّهُمْ جُندٌ مُّغْرَقُونَ', '44:24'),
(4439, 44, 25, 'كَمْ تَرَكُوا۟ مِن جَنَّـٰتٍ وَعُيُونٍ', '44:25'),
(4440, 44, 26, 'وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ', '44:26'),
(4441, 44, 27, 'وَنَعْمَةٍ كَانُوا۟ فِيهَا فَـٰكِهِينَ', '44:27'),
(4442, 44, 28, 'كَذَٰلِكَ ۖ وَأَوْرَثْنَـٰهَا قَوْمًا ءَاخَرِينَ', '44:28'),
(4443, 44, 29, 'فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ', '44:29'),
(4444, 44, 30, 'وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ', '44:30'),
(4445, 44, 31, 'مِن فِرْعَوْنَ ۚ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ', '44:31'),
(4446, 44, 32, 'وَلَقَدِ ٱخْتَرْنَـٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَـٰلَمِينَ', '44:32'),
(4447, 44, 33, 'وَءَاتَيْنَـٰهُم مِّنَ ٱلْـَٔايَـٰتِ مَا فِيهِ بَلَـٰٓؤٌا۟ مُّبِينٌ', '44:33'),
(4448, 44, 34, 'إِنَّ هَـٰٓؤُلَآءِ لَيَقُولُونَ', '44:34'),
(4449, 44, 35, 'إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', '44:35'),
(4450, 44, 36, 'فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَـٰدِقِينَ', '44:36'),
(4451, 44, 37, 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ أَهْلَكْنَـٰهُمْ ۖ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ', '44:37'),
(4452, 44, 38, 'وَمَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَـٰعِبِينَ', '44:38'),
(4453, 44, 39, 'مَا خَلَقْنَـٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '44:39'),
(4454, 44, 40, 'إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَـٰتُهُمْ أَجْمَعِينَ', '44:40'),
(4455, 44, 41, 'يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًى شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', '44:41'),
(4456, 44, 42, 'إِلَّا مَن رَّحِمَ ٱللَّهُ ۚ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '44:42'),
(4457, 44, 43, 'إِنَّ شَجَرَتَ ٱلزَّقُّومِ', '44:43'),
(4458, 44, 44, 'طَعَامُ ٱلْأَثِيمِ', '44:44'),
(4459, 44, 45, 'كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ', '44:45'),
(4460, 44, 46, 'كَغَلْىِ ٱلْحَمِيمِ', '44:46'),
(4461, 44, 47, 'خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ', '44:47'),
(4462, 44, 48, 'ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ', '44:48'),
(4463, 44, 49, 'ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ', '44:49'),
(4464, 44, 50, 'إِنَّ هَـٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ', '44:50'),
(4465, 44, 51, 'إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍ', '44:51'),
(4466, 44, 52, 'فِى جَنَّـٰتٍ وَعُيُونٍ', '44:52'),
(4467, 44, 53, 'يَلْبَسُونَ مِن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَقَـٰبِلِينَ', '44:53'),
(4468, 44, 54, 'كَذَٰلِكَ وَزَوَّجْنَـٰهُم بِحُورٍ عِينٍ', '44:54'),
(4469, 44, 55, 'يَدْعُونَ فِيهَا بِكُلِّ فَـٰكِهَةٍ ءَامِنِينَ', '44:55'),
(4470, 44, 56, 'لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ ۖ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ', '44:56'),
(4471, 44, 57, 'فَضْلًا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '44:57'),
(4472, 44, 58, 'فَإِنَّمَا يَسَّرْنَـٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', '44:58'),
(4473, 44, 59, 'فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', '44:59'),
(4474, 45, 1, ' حمٓ', '45:1'),
(4475, 45, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '45:2'),
(4476, 45, 3, 'إِنَّ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّلْمُؤْمِنِينَ', '45:3'),
(4477, 45, 4, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَـٰتٌ لِّقَوْمٍ يُوقِنُونَ', '45:4'),
(4478, 45, 5, 'وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَـٰحِ ءَايَـٰتٌ لِّقَوْمٍ يَعْقِلُونَ', '45:5'),
(4479, 45, 6, 'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَـٰتِهِۦ يُؤْمِنُونَ', '45:6'),
(4480, 45, 7, 'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ', '45:7'),
(4481, 45, 8, 'يَسْمَعُ ءَايَـٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '45:8'),
(4482, 45, 9, 'وَإِذَا عَلِمَ مِنْ ءَايَـٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', '45:9'),
(4483, 45, 10, 'مِّن وَرَآئِهِمْ جَهَنَّمُ ۖ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', '45:10'),
(4484, 45, 11, 'هَـٰذَا هُدًى ۖ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', '45:11'),
(4485, 45, 12, '۞ ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '45:12'),
(4486, 45, 13, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '45:13'),
(4487, 45, 14, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', '45:14'),
(4488, 45, 15, 'مَنْ عَمِلَ صَـٰلِحًا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۖ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', '45:15'),
(4489, 45, 16, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ وَفَضَّلْنَـٰهُمْ عَلَى ٱلْعَـٰلَمِينَ', '45:16'),
(4490, 45, 17, 'وَءَاتَيْنَـٰهُم بَيِّنَـٰتٍ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '45:17'),
(4491, 45, 18, 'ثُمَّ جَعَلْنَـٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', '45:18'),
(4492, 45, 19, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا ۚ وَإِنَّ ٱلظَّـٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۖ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', '45:19'),
(4493, 45, 20, 'هَـٰذَا بَصَـٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ', '45:20'),
(4494, 45, 21, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَآءَ مَا يَحْكُمُونَ', '45:21'),
(4495, 45, 22, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '45:22'),
(4496, 45, 23, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَـٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ ۚ أَفَلَا تَذَكَّرُونَ', '45:23'),
(4497, 45, 24, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ', '45:24'),
(4498, 45, 25, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَـٰدِقِينَ', '45:25'),
(4499, 45, 26, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '45:26'),
(4500, 45, 27, 'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ', '45:27'),
(4501, 45, 28, 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً ۚ كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَـٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', '45:28'),
(4502, 45, 29, 'هَـٰذَا كِتَـٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ ۚ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', '45:29'),
(4503, 45, 30, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', '45:30'),
(4504, 45, 31, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَـٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', '45:31'),
(4505, 45, 32, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', '45:32'),
(4506, 45, 33, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '45:33'),
(4507, 45, 34, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ', '45:34'),
(4508, 45, 35, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَـٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', '45:35'),
(4509, 45, 36, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَـٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَـٰلَمِينَ', '45:36'),
(4510, 45, 37, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '45:37'),
(4511, 46, 1, ' حمٓ', '46:1'),
(4512, 46, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '46:2'),
(4513, 46, 3, 'مَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى ۚ وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', '46:3'),
(4514, 46, 4, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَـٰوَٰتِ ۖ ٱئْتُونِى بِكِتَـٰبٍ مِّن قَبْلِ هَـٰذَآ أَوْ أَثَـٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ', '46:4'),
(4515, 46, 5, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـٰفِلُونَ', '46:5'),
(4516, 46, 6, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَـٰفِرِينَ', '46:6'),
(4517, 46, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَـٰذَا سِحْرٌ مُّبِينٌ', '46:7'),
(4518, 46, 8, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ ۖ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۖ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '46:8'),
(4519, 46, 9, 'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', '46:9'),
(4520, 46, 10, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '46:10'),
(4521, 46, 11, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَـٰذَآ إِفْكٌ قَدِيمٌ', '46:11'),
(4522, 46, 12, 'وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ وَهَـٰذَا كِتَـٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', '46:12'),
(4523, 46, 13, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَـٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '46:13'),
(4524, 46, 14, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ خَـٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '46:14'),
(4525, 46, 15, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ إِحْسَـٰنًا ۖ حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا ۖ وَحَمْلُهُۥ وَفِصَـٰلُهُۥ ثَلَـٰثُونَ شَهْرًا ۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', '46:15'),
(4526, 46, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَـٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', '46:16'),
(4527, 46, 17, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '46:17'),
(4528, 46, 18, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَـٰسِرِينَ', '46:18'),
(4529, 46, 19, 'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۖ وَلِيُوَفِّيَهُمْ أَعْمَـٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', '46:19'),
(4530, 46, 20, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَـٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', '46:20'),
(4531, 46, 21, '۞ وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', '46:21'),
(4532, 46, 22, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', '46:22'),
(4533, 46, 23, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَـٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', '46:23'),
(4534, 46, 24, 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَـٰذَا عَارِضٌ مُّمْطِرُنَا ۚ بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ ۖ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', '46:24'),
(4535, 46, 25, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَـٰكِنُهُمْ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '46:25'),
(4536, 46, 26, 'وَلَقَدْ مَكَّنَّـٰهُمْ فِيمَآ إِن مَّكَّنَّـٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَـٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَـٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَـٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '46:26'),
(4537, 46, 27, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَرْجِعُونَ', '46:27'),
(4538, 46, 28, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ ۖ بَلْ ضَلُّوا۟ عَنْهُمْ ۚ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', '46:28'),
(4539, 46, 29, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ ۖ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', '46:29'),
(4540, 46, 30, 'قَالُوا۟ يَـٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَـٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', '46:30'),
(4541, 46, 31, 'يَـٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', '46:31'),
(4542, 46, 32, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍ مُّبِينٍ', '46:32'),
(4543, 46, 33, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ ۚ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '46:33'),
(4544, 46, 34, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۖ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '46:34'),
(4545, 46, 35, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ ۚ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ ۚ بَلَـٰغٌ ۚ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَـٰسِقُونَ', '46:35'),
(4546, 47, 1, ' ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَـٰلَهُمْ', '47:1'),
(4547, 47, 2, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', '47:2'),
(4548, 47, 3, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَـٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَـٰلَهُمْ', '47:3'),
(4549, 47, 4, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَـٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ ۗ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَـٰلَهُمْ', '47:4'),
(4550, 47, 5, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', '47:5'),
(4551, 47, 6, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', '47:6'),
(4552, 47, 7, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', '47:7'),
(4553, 47, 8, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَـٰلَهُمْ', '47:8'),
(4554, 47, 9, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَـٰلَهُمْ', '47:9'),
(4555, 47, 10, '۞ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ دَمَّرَ ٱللَّهُ عَلَيْهِمْ ۖ وَلِلْكَـٰفِرِينَ أَمْثَـٰلُهَا', '47:10'),
(4556, 47, 11, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَـٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', '47:11'),
(4557, 47, 12, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَـٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ', '47:12'),
(4558, 47, 13, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَـٰهُمْ فَلَا نَاصِرَ لَهُمْ', '47:13'),
(4559, 47, 14, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', '47:14'),
(4560, 47, 15, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ فِيهَآ أَنْهَـٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَـٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَـٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّـٰرِبِينَ وَأَنْهَـٰرٌ مِّنْ عَسَلٍ مُّصَفًّى ۖ وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ ۖ كَمَنْ هُوَ خَـٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ', '47:15'),
(4561, 47, 16, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', '47:16'),
(4562, 47, 17, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', '47:17'),
(4563, 47, 18, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً ۖ فَقَدْ جَآءَ أَشْرَاطُهَا ۚ فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', '47:18'),
(4564, 47, 19, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', '47:19'),
(4565, 47, 20, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ ۖ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ ۙ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَأَوْلَىٰ لَهُمْ', '47:20'),
(4566, 47, 21, 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ ۚ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ', '47:21'),
(4567, 47, 22, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', '47:22'),
(4568, 47, 23, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَـٰرَهُمْ', '47:23'),
(4569, 47, 24, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', '47:24'),
(4570, 47, 25, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَـٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ۙ ٱلشَّيْطَـٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', '47:25'),
(4571, 47, 26, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ ۖ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', '47:26'),
(4572, 47, 27, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَـٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـٰرَهُمْ', '47:27'),
(4573, 47, 28, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَـٰلَهُمْ', '47:28'),
(4574, 47, 29, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَـٰنَهُمْ', '47:29'),
(4575, 47, 30, 'وَلَوْ نَشَآءُ لَأَرَيْنَـٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَـٰهُمْ ۚ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ ۚ وَٱللَّهُ يَعْلَمُ أَعْمَـٰلَكُمْ', '47:30'),
(4576, 47, 31, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَـٰهِدِينَ مِنكُمْ وَٱلصَّـٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', '47:31'),
(4577, 47, 32, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَـٰلَهُمْ', '47:32'),
(4578, 47, 33, '۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَـٰلَكُمْ', '47:33'),
(4579, 47, 34, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', '47:34'),
(4580, 47, 35, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَـٰلَكُمْ', '47:35'),
(4581, 47, 36, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', '47:36'),
(4582, 47, 37, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَـٰنَكُمْ', '47:37'),
(4583, 47, 38, 'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ ۖ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ ۚ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ ۚ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَـٰلَكُم', '47:38'),
(4584, 48, 1, ' إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', '48:1'),
(4585, 48, 2, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا', '48:2'),
(4586, 48, 3, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', '48:3'),
(4587, 48, 4, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَـٰنًا مَّعَ إِيمَـٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '48:4'),
(4588, 48, 5, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ ۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا', '48:5'),
(4589, 48, 6, 'وَيُعَذِّبَ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَـٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۖ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا', '48:6'),
(4590, 48, 7, 'وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '48:7'),
(4591, 48, 8, 'إِنَّآ أَرْسَلْنَـٰكَ شَـٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', '48:8'),
(4592, 48, 9, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '48:9'),
(4593, 48, 10, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ ۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ ۖ وَمَنْ أَوْفَىٰ بِمَا عَـٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا', '48:10'),
(4594, 48, 11, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا ۚ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۚ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا ۚ بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', '48:11'),
(4595, 48, 12, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا', '48:12'),
(4596, 48, 13, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَعِيرًا', '48:13'),
(4597, 48, 14, 'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '48:14'),
(4598, 48, 15, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ ۖ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَـٰمَ ٱللَّهِ ۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا ۚ بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا', '48:15'),
(4599, 48, 16, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَـٰتِلُونَهُمْ أَوْ يُسْلِمُونَ ۖ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا ۖ وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا', '48:16'),
(4600, 48, 17, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا', '48:17'),
(4601, 48, 18, '۞ لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَـٰبَهُمْ فَتْحًا قَرِيبًا', '48:18'),
(4602, 48, 19, 'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا ۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '48:19'),
(4603, 48, 20, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَـٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا', '48:20'),
(4604, 48, 21, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '48:21'),
(4605, 48, 22, 'وَلَوْ قَـٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَـٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', '48:22'),
(4606, 48, 23, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', '48:23'),
(4607, 48, 24, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '48:24'),
(4608, 48, 25, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ ۚ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَـٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ ۖ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ ۚ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', '48:25'),
(4609, 48, 26, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَـٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '48:26'),
(4610, 48, 27, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ ۖ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ ۖ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', '48:27'),
(4611, 48, 28, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '48:28'),
(4612, 48, 29, 'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ ۖ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا ۖ سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ۚ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ ۚ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ ۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا', '48:29'),
(4613, 49, 1, ' يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '49:1'),
(4614, 49, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَـٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', '49:2'),
(4615, 49, 3, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ ۚ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '49:3'),
(4616, 49, 4, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', '49:4'),
(4617, 49, 5, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '49:5'),
(4618, 49, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَـٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَـٰدِمِينَ', '49:6'),
(4619, 49, 7, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ ۚ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَـٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَـٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', '49:7'),
(4620, 49, 8, 'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '49:8'),
(4621, 49, 9, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَـٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '49:9'),
(4622, 49, 10, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', '49:10'),
(4623, 49, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَـٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَـٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '49:11'),
(4624, 49, 12, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ', '49:12'),
(4625, 49, 13, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَـٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَـٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ', '49:13'),
(4626, 49, 14, '۞ قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا ۖ قُل لَّمْ تُؤْمِنُوا۟ وَلَـٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَـٰنُ فِى قُلُوبِكُمْ ۖ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَـٰلِكُمْ شَيْـًٔا ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '49:14'),
(4627, 49, 15, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ', '49:15'),
(4628, 49, 16, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '49:16'),
(4629, 49, 17, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ ۖ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَـٰمَكُم ۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَـٰنِ إِن كُنتُمْ صَـٰدِقِينَ', '49:17'),
(4630, 49, 18, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', '49:18'),
(4631, 50, 1, ' قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', '50:1'),
(4632, 50, 2, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَـٰفِرُونَ هَـٰذَا شَىْءٌ عَجِيبٌ', '50:2'),
(4633, 50, 3, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ۖ ذَٰلِكَ رَجْعٌۢ بَعِيدٌ', '50:3'),
(4634, 50, 4, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ ۖ وَعِندَنَا كِتَـٰبٌ حَفِيظٌۢ', '50:4'),
(4635, 50, 5, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ', '50:5'),
(4636, 50, 6, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَـٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٍ', '50:6'),
(4637, 50, 7, 'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ', '50:7'),
(4638, 50, 8, 'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ', '50:8'),
(4639, 50, 9, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَـٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّـٰتٍ وَحَبَّ ٱلْحَصِيدِ', '50:9'),
(4640, 50, 10, 'وَٱلنَّخْلَ بَاسِقَـٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ', '50:10'),
(4641, 50, 11, 'رِّزْقًا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا ۚ كَذَٰلِكَ ٱلْخُرُوجُ', '50:11'),
(4642, 50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَـٰبُ ٱلرَّسِّ وَثَمُودُ', '50:12'),
(4643, 50, 13, 'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ', '50:13'),
(4644, 50, 14, 'وَأَصْحَـٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ ۚ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', '50:14'),
(4645, 50, 15, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ', '50:15'),
(4646, 50, 16, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', '50:16'),
(4647, 50, 17, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ', '50:17'),
(4648, 50, 18, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ', '50:18'),
(4649, 50, 19, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', '50:19'),
(4650, 50, 20, 'وَنُفِخَ فِى ٱلصُّورِ ۚ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', '50:20'),
(4651, 50, 21, 'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ', '50:21'),
(4652, 50, 22, 'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَـٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ', '50:22'),
(4653, 50, 23, 'وَقَالَ قَرِينُهُۥ هَـٰذَا مَا لَدَىَّ عَتِيدٌ', '50:23'),
(4654, 50, 24, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', '50:24'),
(4655, 50, 25, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', '50:25'),
(4656, 50, 26, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', '50:26'),
(4657, 50, 27, '۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَـٰكِن كَانَ فِى ضَلَـٰلٍۭ بَعِيدٍ', '50:27'),
(4658, 50, 28, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', '50:28'),
(4659, 50, 29, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّـٰمٍ لِّلْعَبِيدِ', '50:29'),
(4660, 50, 30, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', '50:30'),
(4661, 50, 31, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', '50:31'),
(4662, 50, 32, 'هَـٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', '50:32'),
(4663, 50, 33, 'مَّنْ خَشِىَ ٱلرَّحْمَـٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍ مُّنِيبٍ', '50:33'),
(4664, 50, 34, 'ٱدْخُلُوهَا بِسَلَـٰمٍ ۖ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', '50:34'),
(4665, 50, 35, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', '50:35'),
(4666, 50, 36, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا۟ فِى ٱلْبِلَـٰدِ هَلْ مِن مَّحِيصٍ', '50:36'),
(4667, 50, 37, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌ', '50:37'),
(4668, 50, 38, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', '50:38'),
(4669, 50, 39, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', '50:39'),
(4670, 50, 40, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَأَدْبَـٰرَ ٱلسُّجُودِ', '50:40'),
(4671, 50, 41, 'وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍ قَرِيبٍ', '50:41'),
(4672, 50, 42, 'يَوْمَ يَسْمَعُونَ ٱلصَّيْحَةَ بِٱلْحَقِّ ۚ ذَٰلِكَ يَوْمُ ٱلْخُرُوجِ', '50:42'),
(4673, 50, 43, 'إِنَّا نَحْنُ نُحْىِۦ وَنُمِيتُ وَإِلَيْنَا ٱلْمَصِيرُ', '50:43'),
(4674, 50, 44, 'يَوْمَ تَشَقَّقُ ٱلْأَرْضُ عَنْهُمْ سِرَاعًا ۚ ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ', '50:44'),
(4675, 50, 45, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ ۖ وَمَآ أَنتَ عَلَيْهِم بِجَبَّارٍ ۖ فَذَكِّرْ بِٱلْقُرْءَانِ مَن يَخَافُ وَعِيدِ', '50:45'),
(4676, 51, 1, ' وَٱلذَّٰرِيَـٰتِ ذَرْوًا', '51:1'),
(4677, 51, 2, 'فَٱلْحَـٰمِلَـٰتِ وِقْرًا', '51:2'),
(4678, 51, 3, 'فَٱلْجَـٰرِيَـٰتِ يُسْرًا', '51:3'),
(4679, 51, 4, 'فَٱلْمُقَسِّمَـٰتِ أَمْرًا', '51:4'),
(4680, 51, 5, 'إِنَّمَا تُوعَدُونَ لَصَادِقٌ', '51:5'),
(4681, 51, 6, 'وَإِنَّ ٱلدِّينَ لَوَٰقِعٌ', '51:6'),
(4682, 51, 7, 'وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ', '51:7'),
(4683, 51, 8, 'إِنَّكُمْ لَفِى قَوْلٍ مُّخْتَلِفٍ', '51:8'),
(4684, 51, 9, 'يُؤْفَكُ عَنْهُ مَنْ أُفِكَ', '51:9'),
(4685, 51, 10, 'قُتِلَ ٱلْخَرَّٰصُونَ', '51:10'),
(4686, 51, 11, 'ٱلَّذِينَ هُمْ فِى غَمْرَةٍ سَاهُونَ', '51:11'),
(4687, 51, 12, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ', '51:12'),
(4688, 51, 13, 'يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ', '51:13'),
(4689, 51, 14, 'ذُوقُوا۟ فِتْنَتَكُمْ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ', '51:14'),
(4690, 51, 15, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَعُيُونٍ', '51:15'),
(4691, 51, 16, 'ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ', '51:16'),
(4692, 51, 17, 'كَانُوا۟ قَلِيلًا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ', '51:17'),
(4693, 51, 18, 'وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ', '51:18'),
(4694, 51, 19, 'وَفِىٓ أَمْوَٰلِهِمْ حَقٌّ لِّلسَّآئِلِ وَٱلْمَحْرُومِ', '51:19'),
(4695, 51, 20, 'وَفِى ٱلْأَرْضِ ءَايَـٰتٌ لِّلْمُوقِنِينَ', '51:20'),
(4696, 51, 21, 'وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', '51:21'),
(4697, 51, 22, 'وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', '51:22'),
(4698, 51, 23, 'فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ', '51:23'),
(4699, 51, 24, 'هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ', '51:24'),
(4700, 51, 25, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَـٰمًا ۖ قَالَ سَلَـٰمٌ قَوْمٌ مُّنكَرُونَ', '51:25'),
(4701, 51, 26, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍ سَمِينٍ', '51:26'),
(4702, 51, 27, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', '51:27'),
(4703, 51, 28, 'فَأَوْجَسَ مِنْهُمْ خِيفَةً ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَـٰمٍ عَلِيمٍ', '51:28'),
(4704, 51, 29, 'فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌ', '51:29'),
(4705, 51, 30, 'قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ ۖ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', '51:30'),
(4706, 51, 31, '۞ قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', '51:31'),
(4707, 51, 32, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', '51:32'),
(4708, 51, 33, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةً مِّن طِينٍ', '51:33'),
(4709, 51, 34, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', '51:34'),
(4710, 51, 35, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ', '51:35'),
(4711, 51, 36, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍ مِّنَ ٱلْمُسْلِمِينَ', '51:36'),
(4712, 51, 37, 'وَتَرَكْنَا فِيهَآ ءَايَةً لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ', '51:37'),
(4713, 51, 38, 'وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَـٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَـٰنٍ مُّبِينٍ', '51:38'),
(4714, 51, 39, 'فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَـٰحِرٌ أَوْ مَجْنُونٌ', '51:39'),
(4715, 51, 40, 'فَأَخَذْنَـٰهُ وَجُنُودَهُۥ فَنَبَذْنَـٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌ', '51:40'),
(4716, 51, 41, 'وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ', '51:41'),
(4717, 51, 42, 'مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ', '51:42'),
(4718, 51, 43, 'وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍ', '51:43'),
(4719, 51, 44, 'فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّـٰعِقَةُ وَهُمْ يَنظُرُونَ', '51:44'),
(4720, 51, 45, 'فَمَا ٱسْتَطَـٰعُوا۟ مِن قِيَامٍ وَمَا كَانُوا۟ مُنتَصِرِينَ', '51:45'),
(4721, 51, 46, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ', '51:46'),
(4722, 51, 47, 'وَٱلسَّمَآءَ بَنَيْنَـٰهَا بِأَيْي۟دٍ وَإِنَّا لَمُوسِعُونَ', '51:47'),
(4723, 51, 48, 'وَٱلْأَرْضَ فَرَشْنَـٰهَا فَنِعْمَ ٱلْمَـٰهِدُونَ', '51:48'),
(4724, 51, 49, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', '51:49'),
(4725, 51, 50, 'فَفِرُّوٓا۟ إِلَى ٱللَّهِ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', '51:50'),
(4726, 51, 51, 'وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', '51:51'),
(4727, 51, 52, 'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ', '51:52'),
(4728, 51, 53, 'أَتَوَاصَوْا۟ بِهِۦ ۚ بَلْ هُمْ قَوْمٌ طَاغُونَ', '51:53'),
(4729, 51, 54, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍ', '51:54'),
(4730, 51, 55, 'وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ', '51:55'),
(4731, 51, 56, 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', '51:56'),
(4732, 51, 57, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍ وَمَآ أُرِيدُ أَن يُطْعِمُونِ', '51:57'),
(4733, 51, 58, 'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ', '51:58'),
(4734, 51, 59, 'فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًا مِّثْلَ ذَنُوبِ أَصْحَـٰبِهِمْ فَلَا يَسْتَعْجِلُونِ', '51:59'),
(4735, 51, 60, 'فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ', '51:60'),
(4736, 52, 1, ' وَٱلطُّورِ', '52:1'),
(4737, 52, 2, 'وَكِتَـٰبٍ مَّسْطُورٍ', '52:2'),
(4738, 52, 3, 'فِى رَقٍّ مَّنشُورٍ', '52:3'),
(4739, 52, 4, 'وَٱلْبَيْتِ ٱلْمَعْمُورِ', '52:4'),
(4740, 52, 5, 'وَٱلسَّقْفِ ٱلْمَرْفُوعِ', '52:5'),
(4741, 52, 6, 'وَٱلْبَحْرِ ٱلْمَسْجُورِ', '52:6'),
(4742, 52, 7, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌ', '52:7'),
(4743, 52, 8, 'مَّا لَهُۥ مِن دَافِعٍ', '52:8'),
(4744, 52, 9, 'يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًا', '52:9'),
(4745, 52, 10, 'وَتَسِيرُ ٱلْجِبَالُ سَيْرًا', '52:10'),
(4746, 52, 11, 'فَوَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '52:11'),
(4747, 52, 12, 'ٱلَّذِينَ هُمْ فِى خَوْضٍ يَلْعَبُونَ', '52:12'),
(4748, 52, 13, 'يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', '52:13'),
(4749, 52, 14, 'هَـٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', '52:14'),
(4750, 52, 15, 'أَفَسِحْرٌ هَـٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ', '52:15'),
(4751, 52, 16, 'ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', '52:16'),
(4752, 52, 17, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَنَعِيمٍ', '52:17'),
(4753, 52, 18, 'فَـٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ', '52:18'),
(4754, 52, 19, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', '52:19'),
(4755, 52, 20, 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٍ مَّصْفُوفَةٍ ۖ وَزَوَّجْنَـٰهُم بِحُورٍ عِينٍ', '52:20'),
(4756, 52, 21, 'وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَـٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَـٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍ ۚ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌ', '52:21'),
(4757, 52, 22, 'وَأَمْدَدْنَـٰهُم بِفَـٰكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ', '52:22'),
(4758, 52, 23, 'يَتَنَـٰزَعُونَ فِيهَا كَأْسًا لَّا لَغْوٌ فِيهَا وَلَا تَأْثِيمٌ', '52:23'),
(4759, 52, 24, '۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ', '52:24'),
(4760, 52, 25, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', '52:25'),
(4761, 52, 26, 'قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ', '52:26'),
(4762, 52, 27, 'فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', '52:27'),
(4763, 52, 28, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ ۖ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ', '52:28'),
(4764, 52, 29, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ', '52:29'),
(4765, 52, 30, 'أَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ', '52:30'),
(4766, 52, 31, 'قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ', '52:31'),
(4767, 52, 32, 'أَمْ تَأْمُرُهُمْ أَحْلَـٰمُهُم بِهَـٰذَآ ۚ أَمْ هُمْ قَوْمٌ طَاغُونَ', '52:32'),
(4768, 52, 33, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ ۚ بَل لَّا يُؤْمِنُونَ', '52:33'),
(4769, 52, 34, 'فَلْيَأْتُوا۟ بِحَدِيثٍ مِّثْلِهِۦٓ إِن كَانُوا۟ صَـٰدِقِينَ', '52:34'),
(4770, 52, 35, 'أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَـٰلِقُونَ', '52:35'),
(4771, 52, 36, 'أَمْ خَلَقُوا۟ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ', '52:36'),
(4772, 52, 37, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ', '52:37'),
(4773, 52, 38, 'أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ ۖ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَـٰنٍ مُّبِينٍ', '52:38'),
(4774, 52, 39, 'أَمْ لَهُ ٱلْبَنَـٰتُ وَلَكُمُ ٱلْبَنُونَ', '52:39'),
(4775, 52, 40, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', '52:40'),
(4776, 52, 41, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', '52:41'),
(4777, 52, 42, 'أَمْ يُرِيدُونَ كَيْدًا ۖ فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ', '52:42'),
(4778, 52, 43, 'أَمْ لَهُمْ إِلَـٰهٌ غَيْرُ ٱللَّهِ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', '52:43'),
(4779, 52, 44, 'وَإِن يَرَوْا۟ كِسْفًا مِّنَ ٱلسَّمَآءِ سَاقِطًا يَقُولُوا۟ سَحَابٌ مَّرْكُومٌ', '52:44'),
(4780, 52, 45, 'فَذَرْهُمْ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ', '52:45'),
(4781, 52, 46, 'يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', '52:46'),
(4782, 52, 47, 'وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًا دُونَ ذَٰلِكَ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '52:47'),
(4783, 52, 48, 'وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا ۖ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', '52:48'),
(4784, 52, 49, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَـٰرَ ٱلنُّجُومِ', '52:49'),
(4785, 53, 1, ' وَٱلنَّجْمِ إِذَا هَوَىٰ', '53:1'),
(4786, 53, 2, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ', '53:2'),
(4787, 53, 3, 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', '53:3'),
(4788, 53, 4, 'إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ', '53:4'),
(4789, 53, 5, 'عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ', '53:5'),
(4790, 53, 6, 'ذُو مِرَّةٍ فَٱسْتَوَىٰ', '53:6'),
(4791, 53, 7, 'وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ', '53:7'),
(4792, 53, 8, 'ثُمَّ دَنَا فَتَدَلَّىٰ', '53:8'),
(4793, 53, 9, 'فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ', '53:9'),
(4794, 53, 10, 'فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ', '53:10'),
(4795, 53, 11, 'مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ', '53:11'),
(4796, 53, 12, 'أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ', '53:12'),
(4797, 53, 13, 'وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ', '53:13'),
(4798, 53, 14, 'عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ', '53:14'),
(4799, 53, 15, 'عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ', '53:15'),
(4800, 53, 16, 'إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ', '53:16'),
(4801, 53, 17, 'مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ', '53:17'),
(4802, 53, 18, 'لَقَدْ رَأَىٰ مِنْ ءَايَـٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ', '53:18'),
(4803, 53, 19, 'أَفَرَءَيْتُمُ ٱللَّـٰتَ وَٱلْعُزَّىٰ', '53:19'),
(4804, 53, 20, 'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ', '53:20'),
(4805, 53, 21, 'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ', '53:21'),
(4806, 53, 22, 'تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰٓ', '53:22'),
(4807, 53, 23, 'إِنْ هِىَ إِلَّآ أَسْمَآءٌ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', '53:23'),
(4808, 53, 24, 'أَمْ لِلْإِنسَـٰنِ مَا تَمَنَّىٰ', '53:24'),
(4809, 53, 25, 'فَلِلَّهِ ٱلْـَٔاخِرَةُ وَٱلْأُولَىٰ', '53:25'),
(4810, 53, 26, '۞ وَكَم مِّن مَّلَكٍ فِى ٱلسَّمَـٰوَٰتِ لَا تُغْنِى شَفَـٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ', '53:26'),
(4811, 53, 27, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَـٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', '53:27'),
(4812, 53, 28, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا', '53:28'),
(4813, 53, 29, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', '53:29'),
(4814, 53, 30, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', '53:30'),
(4815, 53, 31, 'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَـٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', '53:31'),
(4816, 53, 32, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَـٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَـٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', '53:32'),
(4817, 53, 33, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', '53:33'),
(4818, 53, 34, 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ', '53:34'),
(4819, 53, 35, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', '53:35'),
(4820, 53, 36, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', '53:36'),
(4821, 53, 37, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', '53:37'),
(4822, 53, 38, 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', '53:38'),
(4823, 53, 39, 'وَأَن لَّيْسَ لِلْإِنسَـٰنِ إِلَّا مَا سَعَىٰ', '53:39'),
(4824, 53, 40, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', '53:40'),
(4825, 53, 41, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', '53:41'),
(4826, 53, 42, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', '53:42'),
(4827, 53, 43, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', '53:43'),
(4828, 53, 44, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', '53:44'),
(4829, 53, 45, 'وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ', '53:45'),
(4830, 53, 46, 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', '53:46'),
(4831, 53, 47, 'وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ', '53:47'),
(4832, 53, 48, 'وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ', '53:48'),
(4833, 53, 49, 'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ', '53:49'),
(4834, 53, 50, 'وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ', '53:50'),
(4835, 53, 51, 'وَثَمُودَا۟ فَمَآ أَبْقَىٰ', '53:51'),
(4836, 53, 52, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ', '53:52'),
(4837, 53, 53, 'وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ', '53:53'),
(4838, 53, 54, 'فَغَشَّىٰهَا مَا غَشَّىٰ', '53:54'),
(4839, 53, 55, 'فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ', '53:55'),
(4840, 53, 56, 'هَـٰذَا نَذِيرٌ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ', '53:56'),
(4841, 53, 57, 'أَزِفَتِ ٱلْـَٔازِفَةُ', '53:57'),
(4842, 53, 58, 'لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ', '53:58'),
(4843, 53, 59, 'أَفَمِنْ هَـٰذَا ٱلْحَدِيثِ تَعْجَبُونَ', '53:59'),
(4844, 53, 60, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', '53:60'),
(4845, 53, 61, 'وَأَنتُمْ سَـٰمِدُونَ', '53:61'),
(4846, 53, 62, 'فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟ ۩', '53:62'),
(4847, 54, 1, ' ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ', '54:1'),
(4848, 54, 2, 'وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ', '54:2'),
(4849, 54, 3, 'وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ ۚ وَكُلُّ أَمْرٍ مُّسْتَقِرٌّ', '54:3'),
(4850, 54, 4, 'وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ', '54:4'),
(4851, 54, 5, 'حِكْمَةٌۢ بَـٰلِغَةٌ ۖ فَمَا تُغْنِ ٱلنُّذُرُ', '54:5'),
(4852, 54, 6, 'فَتَوَلَّ عَنْهُمْ ۘ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍ نُّكُرٍ', '54:6'),
(4853, 54, 7, 'خُشَّعًا أَبْصَـٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ', '54:7'),
(4854, 54, 8, 'مُّهْطِعِينَ إِلَى ٱلدَّاعِ ۖ يَقُولُ ٱلْكَـٰفِرُونَ هَـٰذَا يَوْمٌ عَسِرٌ', '54:8'),
(4855, 54, 9, '۞ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌ وَٱزْدُجِرَ', '54:9'),
(4856, 54, 10, 'فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌ فَٱنتَصِرْ', '54:10'),
(4857, 54, 11, 'فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍ مُّنْهَمِرٍ', '54:11'),
(4858, 54, 12, 'وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍ قَدْ قُدِرَ', '54:12'),
(4859, 54, 13, 'وَحَمَلْنَـٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍ وَدُسُرٍ', '54:13'),
(4860, 54, 14, 'تَجْرِى بِأَعْيُنِنَا جَزَآءً لِّمَن كَانَ كُفِرَ', '54:14'),
(4861, 54, 15, 'وَلَقَد تَّرَكْنَـٰهَآ ءَايَةً فَهَلْ مِن مُّدَّكِرٍ', '54:15'),
(4862, 54, 16, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', '54:16'),
(4863, 54, 17, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', '54:17'),
(4864, 54, 18, 'كَذَّبَتْ عَادٌ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', '54:18'),
(4865, 54, 19, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ', '54:19'),
(4866, 54, 20, 'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ', '54:20'),
(4867, 54, 21, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', '54:21'),
(4868, 54, 22, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', '54:22'),
(4869, 54, 23, 'كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ', '54:23'),
(4870, 54, 24, 'فَقَالُوٓا۟ أَبَشَرًا مِّنَّا وَٰحِدًا نَّتَّبِعُهُۥٓ إِنَّآ إِذًا لَّفِى ضَلَـٰلٍ وَسُعُرٍ', '54:24'),
(4871, 54, 25, 'أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ', '54:25'),
(4872, 54, 26, 'سَيَعْلَمُونَ غَدًا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ', '54:26'),
(4873, 54, 27, 'إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةً لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ', '54:27'),
(4874, 54, 28, 'وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ ۖ كُلُّ شِرْبٍ مُّحْتَضَرٌ', '54:28'),
(4875, 54, 29, 'فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', '54:29'),
(4876, 54, 30, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', '54:30'),
(4877, 54, 31, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَٰحِدَةً فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ', '54:31'),
(4878, 54, 32, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', '54:32'),
(4879, 54, 33, 'كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ', '54:33'),
(4880, 54, 34, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍ ۖ نَّجَّيْنَـٰهُم بِسَحَرٍ', '54:34'),
(4881, 54, 35, 'نِّعْمَةً مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ', '54:35'),
(4882, 54, 36, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ', '54:36'),
(4883, 54, 37, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ', '54:37'),
(4884, 54, 38, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ', '54:38'),
(4885, 54, 39, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ', '54:39'),
(4886, 54, 40, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', '54:40'),
(4887, 54, 41, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ', '54:41'),
(4888, 54, 42, 'كَذَّبُوا۟ بِـَٔايَـٰتِنَا كُلِّهَا فَأَخَذْنَـٰهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ', '54:42'),
(4889, 54, 43, 'أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُو۟لَـٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌ فِى ٱلزُّبُرِ', '54:43'),
(4890, 54, 44, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ', '54:44'),
(4891, 54, 45, 'سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ', '54:45'),
(4892, 54, 46, 'بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', '54:46'),
(4893, 54, 47, 'إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَـٰلٍ وَسُعُرٍ', '54:47'),
(4894, 54, 48, 'يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ', '54:48'),
(4895, 54, 49, 'إِنَّا كُلَّ شَىْءٍ خَلَقْنَـٰهُ بِقَدَرٍ', '54:49'),
(4896, 54, 50, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌ كَلَمْحٍۭ بِٱلْبَصَرِ', '54:50'),
(4897, 54, 51, 'وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ', '54:51'),
(4898, 54, 52, 'وَكُلُّ شَىْءٍ فَعَلُوهُ فِى ٱلزُّبُرِ', '54:52'),
(4899, 54, 53, 'وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ', '54:53'),
(4900, 54, 54, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَنَهَرٍ', '54:54'),
(4901, 54, 55, 'فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍۭ', '54:55'),
(4902, 55, 1, ' ٱلرَّحْمَـٰنُ', '55:1'),
(4903, 55, 2, 'عَلَّمَ ٱلْقُرْءَانَ', '55:2'),
(4904, 55, 3, 'خَلَقَ ٱلْإِنسَـٰنَ', '55:3'),
(4905, 55, 4, 'عَلَّمَهُ ٱلْبَيَانَ', '55:4'),
(4906, 55, 5, 'ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍ', '55:5'),
(4907, 55, 6, 'وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ', '55:6'),
(4908, 55, 7, 'وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ', '55:7'),
(4909, 55, 8, 'أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ', '55:8'),
(4910, 55, 9, 'وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ', '55:9'),
(4911, 55, 10, 'وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', '55:10'),
(4912, 55, 11, 'فِيهَا فَـٰكِهَةٌ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ', '55:11'),
(4913, 55, 12, 'وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ', '55:12'),
(4914, 55, 13, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:13'),
(4915, 55, 14, 'خَلَقَ ٱلْإِنسَـٰنَ مِن صَلْصَـٰلٍ كَٱلْفَخَّارِ', '55:14'),
(4916, 55, 15, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍ مِّن نَّارٍ', '55:15'),
(4917, 55, 16, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:16'),
(4918, 55, 17, 'رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ', '55:17'),
(4919, 55, 18, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:18'),
(4920, 55, 19, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', '55:19'),
(4921, 55, 20, 'بَيْنَهُمَا بَرْزَخٌ لَّا يَبْغِيَانِ', '55:20'),
(4922, 55, 21, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:21'),
(4923, 55, 22, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', '55:22'),
(4924, 55, 23, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:23'),
(4925, 55, 24, 'وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَـٰمِ', '55:24'),
(4926, 55, 25, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:25'),
(4927, 55, 26, 'كُلُّ مَنْ عَلَيْهَا فَانٍ', '55:26'),
(4928, 55, 27, 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَـٰلِ وَٱلْإِكْرَامِ', '55:27'),
(4929, 55, 28, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:28'),
(4930, 55, 29, 'يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍ', '55:29'),
(4931, 55, 30, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:30'),
(4932, 55, 31, 'سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ', '55:31'),
(4933, 55, 32, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:32'),
(4934, 55, 33, 'يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَـٰنٍ', '55:33'),
(4935, 55, 34, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:34'),
(4936, 55, 35, 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ', '55:35'),
(4937, 55, 36, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:36'),
(4938, 55, 37, 'فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةً كَٱلدِّهَانِ', '55:37'),
(4939, 55, 38, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:38'),
(4940, 55, 39, 'فَيَوْمَئِذٍ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٌ وَلَا جَآنٌّ', '55:39'),
(4941, 55, 40, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:40'),
(4942, 55, 41, 'يُعْرَفُ ٱلْمُجْرِمُونَ بِسِيمَـٰهُمْ فَيُؤْخَذُ بِٱلنَّوَٰصِى وَٱلْأَقْدَامِ', '55:41'),
(4943, 55, 42, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:42'),
(4944, 55, 43, 'هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِى يُكَذِّبُ بِهَا ٱلْمُجْرِمُونَ', '55:43'),
(4945, 55, 44, 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍ', '55:44'),
(4946, 55, 45, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:45'),
(4947, 55, 46, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ', '55:46'),
(4948, 55, 47, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:47'),
(4949, 55, 48, 'ذَوَاتَآ أَفْنَانٍ', '55:48'),
(4950, 55, 49, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:49'),
(4951, 55, 50, 'فِيهِمَا عَيْنَانِ تَجْرِيَانِ', '55:50'),
(4952, 55, 51, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:51'),
(4953, 55, 52, 'فِيهِمَا مِن كُلِّ فَـٰكِهَةٍ زَوْجَانِ', '55:52'),
(4954, 55, 53, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:53'),
(4955, 55, 54, 'مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍ ۚ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍ', '55:54'),
(4956, 55, 55, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:55'),
(4957, 55, 56, 'فِيهِنَّ قَـٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', '55:56'),
(4958, 55, 57, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:57'),
(4959, 55, 58, 'كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ', '55:58'),
(4960, 55, 59, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:59'),
(4961, 55, 60, 'هَلْ جَزَآءُ ٱلْإِحْسَـٰنِ إِلَّا ٱلْإِحْسَـٰنُ', '55:60'),
(4962, 55, 61, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:61'),
(4963, 55, 62, 'وَمِن دُونِهِمَا جَنَّتَانِ', '55:62'),
(4964, 55, 63, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:63'),
(4965, 55, 64, 'مُدْهَآمَّتَانِ', '55:64'),
(4966, 55, 65, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:65'),
(4967, 55, 66, 'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', '55:66'),
(4968, 55, 67, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:67'),
(4969, 55, 68, 'فِيهِمَا فَـٰكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', '55:68'),
(4970, 55, 69, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:69'),
(4971, 55, 70, 'فِيهِنَّ خَيْرَٰتٌ حِسَانٌ', '55:70'),
(4972, 55, 71, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:71'),
(4973, 55, 72, 'حُورٌ مَّقْصُورَٰتٌ فِى ٱلْخِيَامِ', '55:72'),
(4974, 55, 73, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:73'),
(4975, 55, 74, 'لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', '55:74'),
(4976, 55, 75, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:75'),
(4977, 55, 76, 'مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِىٍّ حِسَانٍ', '55:76'),
(4978, 55, 77, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', '55:77'),
(4979, 55, 78, 'تَبَـٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَـٰلِ وَٱلْإِكْرَامِ', '55:78'),
(4980, 56, 1, ' إِذَا وَقَعَتِ ٱلْوَاقِعَةُ', '56:1'),
(4981, 56, 2, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ', '56:2'),
(4982, 56, 3, 'خَافِضَةٌ رَّافِعَةٌ', '56:3'),
(4983, 56, 4, 'إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّا', '56:4'),
(4984, 56, 5, 'وَبُسَّتِ ٱلْجِبَالُ بَسًّا', '56:5'),
(4985, 56, 6, 'فَكَانَتْ هَبَآءً مُّنۢبَثًّا', '56:6'),
(4986, 56, 7, 'وَكُنتُمْ أَزْوَٰجًا ثَلَـٰثَةً', '56:7'),
(4987, 56, 8, 'فَأَصْحَـٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', '56:8'),
(4988, 56, 9, 'وَأَصْحَـٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', '56:9'),
(4989, 56, 10, 'وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ', '56:10'),
(4990, 56, 11, 'أُو۟لَـٰٓئِكَ ٱلْمُقَرَّبُونَ', '56:11'),
(4991, 56, 12, 'فِى جَنَّـٰتِ ٱلنَّعِيمِ', '56:12'),
(4992, 56, 13, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', '56:13'),
(4993, 56, 14, 'وَقَلِيلٌ مِّنَ ٱلْـَٔاخِرِينَ', '56:14'),
(4994, 56, 15, 'عَلَىٰ سُرُرٍ مَّوْضُونَةٍ', '56:15'),
(4995, 56, 16, 'مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَـٰبِلِينَ', '56:16'),
(4996, 56, 17, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ', '56:17'),
(4997, 56, 18, 'بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ', '56:18'),
(4998, 56, 19, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ', '56:19'),
(4999, 56, 20, 'وَفَـٰكِهَةٍ مِّمَّا يَتَخَيَّرُونَ', '56:20'),
(5000, 56, 21, 'وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ', '56:21');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(5001, 56, 22, 'وَحُورٌ عِينٌ', '56:22'),
(5002, 56, 23, 'كَأَمْثَـٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ', '56:23'),
(5003, 56, 24, 'جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '56:24'),
(5004, 56, 25, 'لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا', '56:25'),
(5005, 56, 26, 'إِلَّا قِيلًا سَلَـٰمًا سَلَـٰمًا', '56:26'),
(5006, 56, 27, 'وَأَصْحَـٰبُ ٱلْيَمِينِ مَآ أَصْحَـٰبُ ٱلْيَمِينِ', '56:27'),
(5007, 56, 28, 'فِى سِدْرٍ مَّخْضُودٍ', '56:28'),
(5008, 56, 29, 'وَطَلْحٍ مَّنضُودٍ', '56:29'),
(5009, 56, 30, 'وَظِلٍّ مَّمْدُودٍ', '56:30'),
(5010, 56, 31, 'وَمَآءٍ مَّسْكُوبٍ', '56:31'),
(5011, 56, 32, 'وَفَـٰكِهَةٍ كَثِيرَةٍ', '56:32'),
(5012, 56, 33, 'لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ', '56:33'),
(5013, 56, 34, 'وَفُرُشٍ مَّرْفُوعَةٍ', '56:34'),
(5014, 56, 35, 'إِنَّآ أَنشَأْنَـٰهُنَّ إِنشَآءً', '56:35'),
(5015, 56, 36, 'فَجَعَلْنَـٰهُنَّ أَبْكَارًا', '56:36'),
(5016, 56, 37, 'عُرُبًا أَتْرَابًا', '56:37'),
(5017, 56, 38, 'لِّأَصْحَـٰبِ ٱلْيَمِينِ', '56:38'),
(5018, 56, 39, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', '56:39'),
(5019, 56, 40, 'وَثُلَّةٌ مِّنَ ٱلْـَٔاخِرِينَ', '56:40'),
(5020, 56, 41, 'وَأَصْحَـٰبُ ٱلشِّمَالِ مَآ أَصْحَـٰبُ ٱلشِّمَالِ', '56:41'),
(5021, 56, 42, 'فِى سَمُومٍ وَحَمِيمٍ', '56:42'),
(5022, 56, 43, 'وَظِلٍّ مِّن يَحْمُومٍ', '56:43'),
(5023, 56, 44, 'لَّا بَارِدٍ وَلَا كَرِيمٍ', '56:44'),
(5024, 56, 45, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', '56:45'),
(5025, 56, 46, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', '56:46'),
(5026, 56, 47, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ', '56:47'),
(5027, 56, 48, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', '56:48'),
(5028, 56, 49, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْـَٔاخِرِينَ', '56:49'),
(5029, 56, 50, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَـٰتِ يَوْمٍ مَّعْلُومٍ', '56:50'),
(5030, 56, 51, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', '56:51'),
(5031, 56, 52, 'لَـَٔاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ', '56:52'),
(5032, 56, 53, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', '56:53'),
(5033, 56, 54, 'فَشَـٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', '56:54'),
(5034, 56, 55, 'فَشَـٰرِبُونَ شُرْبَ ٱلْهِيمِ', '56:55'),
(5035, 56, 56, 'هَـٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', '56:56'),
(5036, 56, 57, 'نَحْنُ خَلَقْنَـٰكُمْ فَلَوْلَا تُصَدِّقُونَ', '56:57'),
(5037, 56, 58, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', '56:58'),
(5038, 56, 59, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَـٰلِقُونَ', '56:59'),
(5039, 56, 60, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', '56:60'),
(5040, 56, 61, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَـٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', '56:61'),
(5041, 56, 62, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', '56:62'),
(5042, 56, 63, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', '56:63'),
(5043, 56, 64, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', '56:64'),
(5044, 56, 65, 'لَوْ نَشَآءُ لَجَعَلْنَـٰهُ حُطَـٰمًا فَظَلْتُمْ تَفَكَّهُونَ', '56:65'),
(5045, 56, 66, 'إِنَّا لَمُغْرَمُونَ', '56:66'),
(5046, 56, 67, 'بَلْ نَحْنُ مَحْرُومُونَ', '56:67'),
(5047, 56, 68, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', '56:68'),
(5048, 56, 69, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', '56:69'),
(5049, 56, 70, 'لَوْ نَشَآءُ جَعَلْنَـٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ', '56:70'),
(5050, 56, 71, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', '56:71'),
(5051, 56, 72, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', '56:72'),
(5052, 56, 73, 'نَحْنُ جَعَلْنَـٰهَا تَذْكِرَةً وَمَتَـٰعًا لِّلْمُقْوِينَ', '56:73'),
(5053, 56, 74, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', '56:74'),
(5054, 56, 75, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', '56:75'),
(5055, 56, 76, 'وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ', '56:76'),
(5056, 56, 77, 'إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ', '56:77'),
(5057, 56, 78, 'فِى كِتَـٰبٍ مَّكْنُونٍ', '56:78'),
(5058, 56, 79, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', '56:79'),
(5059, 56, 80, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', '56:80'),
(5060, 56, 81, 'أَفَبِهَـٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', '56:81'),
(5061, 56, 82, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', '56:82'),
(5062, 56, 83, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', '56:83'),
(5063, 56, 84, 'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ', '56:84'),
(5064, 56, 85, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَـٰكِن لَّا تُبْصِرُونَ', '56:85'),
(5065, 56, 86, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', '56:86'),
(5066, 56, 87, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَـٰدِقِينَ', '56:87'),
(5067, 56, 88, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', '56:88'),
(5068, 56, 89, 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ', '56:89'),
(5069, 56, 90, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ', '56:90'),
(5070, 56, 91, 'فَسَلَـٰمٌ لَّكَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ', '56:91'),
(5071, 56, 92, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', '56:92'),
(5072, 56, 93, 'فَنُزُلٌ مِّنْ حَمِيمٍ', '56:93'),
(5073, 56, 94, 'وَتَصْلِيَةُ جَحِيمٍ', '56:94'),
(5074, 56, 95, 'إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', '56:95'),
(5075, 56, 96, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', '56:96'),
(5076, 57, 1, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '57:1'),
(5077, 57, 2, 'لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '57:2'),
(5078, 57, 3, 'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '57:3'),
(5079, 57, 4, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '57:4'),
(5080, 57, 5, 'لَّهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '57:5'),
(5081, 57, 6, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '57:6'),
(5082, 57, 7, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', '57:7'),
(5083, 57, 8, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَـٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', '57:8'),
(5084, 57, 9, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', '57:9'),
(5085, 57, 10, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَـٰتَلَ ۚ أُو۟لَـٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَـٰتَلُوا۟ ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '57:10'),
(5086, 57, 11, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', '57:11'),
(5087, 57, 12, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '57:12'),
(5088, 57, 13, 'يَوْمَ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', '57:13'),
(5089, 57, 14, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', '57:14'),
(5090, 57, 15, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ', '57:15'),
(5091, 57, 16, '۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', '57:16'),
(5092, 57, 17, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '57:17'),
(5093, 57, 18, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَـٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', '57:18'),
(5094, 57, 19, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', '57:19'),
(5095, 57, 20, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَـٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَـٰمًا ۖ وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ', '57:20'),
(5096, 57, 21, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '57:21'),
(5097, 57, 22, 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَـٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '57:22'),
(5098, 57, 23, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '57:23'),
(5099, 57, 24, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ ۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '57:24'),
(5100, 57, 25, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَـٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَـٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ ۖ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَـٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '57:25'),
(5101, 57, 26, 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَـٰبَ ۖ فَمِنْهُم مُّهْتَدٍ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', '57:26'),
(5102, 57, 27, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَـٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۖ فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', '57:27'),
(5103, 57, 28, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '57:28'),
(5104, 57, 29, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَـٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ ۙ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '57:29'),
(5105, 58, 1, ' قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَـٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '58:1'),
(5106, 58, 2, 'ٱلَّذِينَ يُظَـٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَـٰتِهِمْ ۖ إِنْ أُمَّهَـٰتُهُمْ إِلَّا ٱلَّـٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '58:2'),
(5107, 58, 3, 'وَٱلَّذِينَ يُظَـٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '58:3'),
(5108, 58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ', '58:4'),
(5109, 58, 5, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ', '58:5'),
(5110, 58, 6, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '58:6'),
(5111, 58, 7, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '58:7'),
(5112, 58, 8, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَـٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ', '58:8'),
(5113, 58, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَـٰجَيْتُمْ فَلَا تَتَنَـٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَـٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '58:9'),
(5114, 58, 10, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَـٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '58:10'),
(5115, 58, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَـٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَـٰتٍ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '58:11'),
(5116, 58, 12, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَـٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ۚ ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '58:12'),
(5117, 58, 13, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَـٰتٍ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '58:13'),
(5118, 58, 14, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', '58:14'),
(5119, 58, 15, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '58:15'),
(5120, 58, 16, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', '58:16'),
(5121, 58, 17, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', '58:17'),
(5122, 58, 18, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَـٰذِبُونَ', '58:18'),
(5123, 58, 19, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَـٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱلشَّيْطَـٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَـٰنِ هُمُ ٱلْخَـٰسِرُونَ', '58:19'),
(5124, 58, 20, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَـٰٓئِكَ فِى ٱلْأَذَلِّينَ', '58:20'),
(5125, 58, 21, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '58:21'),
(5126, 58, 22, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُو۟لَـٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَـٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱللَّهِ ۚ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', '58:22'),
(5127, 59, 1, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '59:1'),
(5128, 59, 2, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ مِن دِيَـٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَـٰٓأُو۟لِى ٱلْأَبْصَـٰرِ', '59:2'),
(5129, 59, 3, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ', '59:3'),
(5130, 59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '59:4'),
(5131, 59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَـٰسِقِينَ', '59:5'),
(5132, 59, 6, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَـٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '59:6'),
(5133, 59, 7, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '59:7'),
(5134, 59, 8, 'لِلْفُقَرَآءِ ٱلْمُهَـٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ', '59:8'),
(5135, 59, 9, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَـٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '59:9'),
(5136, 59, 10, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَـٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', '59:10'),
(5137, 59, 11, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ', '59:11'),
(5138, 59, 12, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَـٰرَ ثُمَّ لَا يُنصَرُونَ', '59:12'),
(5139, 59, 13, 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', '59:13'),
(5140, 59, 14, 'لَا يُقَـٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ ۚ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '59:14'),
(5141, 59, 15, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '59:15'),
(5142, 59, 16, 'كَمَثَلِ ٱلشَّيْطَـٰنِ إِذْ قَالَ لِلْإِنسَـٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ', '59:16'),
(5143, 59, 17, 'فَكَانَ عَـٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَـٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ', '59:17'),
(5144, 59, 18, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '59:18'),
(5145, 59, 19, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', '59:19'),
(5146, 59, 20, 'لَا يَسْتَوِىٓ أَصْحَـٰبُ ٱلنَّارِ وَأَصْحَـٰبُ ٱلْجَنَّةِ ۚ أَصْحَـٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', '59:20'),
(5147, 59, 21, 'لَوْ أَنزَلْنَا هَـٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَـٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ ۚ وَتِلْكَ ٱلْأَمْثَـٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', '59:21'),
(5148, 59, 22, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ۖ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۖ هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ', '59:22'),
(5149, 59, 23, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَـٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', '59:23'),
(5150, 59, 24, 'هُوَ ٱللَّهُ ٱلْخَـٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '59:24'),
(5151, 60, 1, ' يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَـٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', '60:1'),
(5152, 60, 2, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', '60:2'),
(5153, 60, 3, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَـٰدُكُمْ ۚ يَوْمَ ٱلْقِيَـٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '60:3'),
(5154, 60, 4, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', '60:4'),
(5155, 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '60:5'),
(5156, 60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '60:6'),
(5157, 60, 7, '۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً ۚ وَٱللَّهُ قَدِيرٌ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '60:7'),
(5158, 60, 8, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَـٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَـٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '60:8'),
(5159, 60, 9, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَـٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَـٰرِكُمْ وَظَـٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '60:9'),
(5160, 60, 10, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَـٰتُ مُهَـٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَـٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَـٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '60:10'),
(5161, 60, 11, 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '60:11'),
(5162, 60, 12, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَـٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَـٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَـٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '60:12'),
(5163, 60, 13, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَـٰبِ ٱلْقُبُورِ', '60:13'),
(5164, 61, 1, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '61:1'),
(5165, 61, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', '61:2'),
(5166, 61, 3, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', '61:3'),
(5167, 61, 4, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَـٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَـٰنٌ مَّرْصُوصٌ', '61:4'),
(5168, 61, 5, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', '61:5'),
(5169, 61, 6, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ', '61:6'),
(5170, 61, 7, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَـٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '61:7'),
(5171, 61, 8, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', '61:8'),
(5172, 61, 9, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '61:9'),
(5173, 61, 10, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَـٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', '61:10'),
(5174, 61, 11, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '61:11'),
(5175, 61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '61:12'),
(5176, 61, 13, 'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '61:13'),
(5177, 61, 14, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَـٰهِرِينَ', '61:14'),
(5178, 62, 1, ' يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '62:1'),
(5179, 62, 2, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ', '62:2'),
(5180, 62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '62:3'),
(5181, 62, 4, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '62:4'),
(5182, 62, 5, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', '62:5'),
(5183, 62, 6, 'قُلْ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ', '62:6'),
(5184, 62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', '62:7'),
(5185, 62, 8, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَـٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '62:8'),
(5186, 62, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '62:9'),
(5187, 62, 10, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', '62:10'),
(5188, 62, 11, 'وَإِذَا رَأَوْا۟ تِجَـٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَـٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', '62:11'),
(5189, 63, 1, ' إِذَا جَآءَكَ ٱلْمُنَـٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَـٰفِقِينَ لَكَـٰذِبُونَ', '63:1'),
(5190, 63, 2, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '63:2'),
(5191, 63, 3, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', '63:3'),
(5192, 63, 4, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', '63:4'),
(5193, 63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', '63:5'),
(5194, 63, 6, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', '63:6'),
(5195, 63, 7, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَفْقَهُونَ', '63:7'),
(5196, 63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَعْلَمُونَ', '63:8'),
(5197, 63, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَـٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', '63:9'),
(5198, 63, 10, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ', '63:10'),
(5199, 63, 11, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '63:11'),
(5200, 64, 1, ' يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '64:1'),
(5201, 64, 2, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '64:2'),
(5202, 64, 3, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', '64:3'),
(5203, 64, 4, 'يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '64:4'),
(5204, 64, 5, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '64:5'),
(5205, 64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', '64:6'),
(5206, 64, 7, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '64:7'),
(5207, 64, 8, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '64:8'),
(5208, 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '64:9'),
(5209, 64, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ خَـٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', '64:10'),
(5210, 64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '64:11'),
(5211, 64, 12, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ', '64:12'),
(5212, 64, 13, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '64:13'),
(5213, 64, 14, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَـٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '64:14'),
(5214, 64, 15, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', '64:15'),
(5215, 64, 16, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '64:16'),
(5216, 64, 17, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', '64:17'),
(5217, 64, 18, 'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', '64:18'),
(5218, 65, 1, ' يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', '65:1'),
(5219, 65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', '65:2'),
(5220, 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', '65:3'),
(5221, 65, 4, 'وَٱلَّـٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشْهُرٍ وَٱلَّـٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَـٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', '65:4'),
(5222, 65, 5, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', '65:5'),
(5223, 65, 6, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', '65:6'),
(5224, 65, 7, 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', '65:7'),
(5225, 65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَـٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَـٰهَا عَذَابًا نُّكْرًا', '65:8'),
(5226, 65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَـٰقِبَةُ أَمْرِهَا خُسْرًا', '65:9'),
(5227, 65, 10, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', '65:10'),
(5228, 65, 11, 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِ ٱللَّهِ مُبَيِّنَـٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', '65:11'),
(5229, 65, 12, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', '65:12'),
(5230, 66, 1, ' يَـٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '66:1'),
(5231, 66, 2, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَـٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '66:2'),
(5232, 66, 3, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَـٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', '66:3'),
(5233, 66, 4, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَـٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَـٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَـٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', '66:4'),
(5234, 66, 5, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَـٰتٍ مُّؤْمِنَـٰتٍ قَـٰنِتَـٰتٍ تَـٰٓئِبَـٰتٍ عَـٰبِدَٰتٍ سَـٰٓئِحَـٰتٍ ثَيِّبَـٰتٍ وَأَبْكَارًا', '66:5'),
(5235, 66, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَـٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', '66:6'),
(5236, 66, 7, 'يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', '66:7'),
(5237, 66, 8, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '66:8'),
(5238, 66, 9, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', '66:9'),
(5239, 66, 10, 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَـٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', '66:10'),
(5240, 66, 11, 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', '66:11'),
(5241, 66, 12, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَـٰنِتِينَ', '66:12'),
(5242, 67, 1, ' تَبَـٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '67:1'),
(5243, 67, 2, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', '67:2'),
(5244, 67, 3, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَـٰنِ مِن تَفَـٰوُتٍ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', '67:3'),
(5245, 67, 4, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', '67:4'),
(5246, 67, 5, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَجَعَلْنَـٰهَا رُجُومًا لِّلشَّيَـٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', '67:5'),
(5247, 67, 6, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', '67:6'),
(5248, 67, 7, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', '67:7'),
(5249, 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', '67:8'),
(5250, 67, 9, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ كَبِيرٍ', '67:9'),
(5251, 67, 10, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَـٰبِ ٱلسَّعِيرِ', '67:10'),
(5252, 67, 11, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَـٰبِ ٱلسَّعِيرِ', '67:11'),
(5253, 67, 12, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '67:12'),
(5254, 67, 13, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '67:13'),
(5255, 67, 14, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', '67:14'),
(5256, 67, 15, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', '67:15'),
(5257, 67, 16, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', '67:16'),
(5258, 67, 17, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', '67:17'),
(5259, 67, 18, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', '67:18'),
(5260, 67, 19, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَـٰٓفَّـٰتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَـٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', '67:19'),
(5261, 67, 20, 'أَمَّنْ هَـٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَـٰنِ ۚ إِنِ ٱلْكَـٰفِرُونَ إِلَّا فِى غُرُورٍ', '67:20'),
(5262, 67, 21, 'أَمَّنْ هَـٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', '67:21'),
(5263, 67, 22, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '67:22'),
(5264, 67, 23, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ', '67:23'),
(5265, 67, 24, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', '67:24'),
(5266, 67, 25, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', '67:25'),
(5267, 67, 26, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', '67:26'),
(5268, 67, 27, 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', '67:27'),
(5269, 67, 28, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَـٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', '67:28'),
(5270, 67, 29, 'قُلْ هُوَ ٱلرَّحْمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَـٰلٍ مُّبِينٍ', '67:29'),
(5271, 67, 30, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ', '67:30'),
(5272, 68, 1, ' نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', '68:1'),
(5273, 68, 2, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ', '68:2'),
(5274, 68, 3, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ', '68:3'),
(5275, 68, 4, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', '68:4'),
(5276, 68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', '68:5'),
(5277, 68, 6, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', '68:6'),
(5278, 68, 7, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '68:7'),
(5279, 68, 8, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', '68:8'),
(5280, 68, 9, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', '68:9'),
(5281, 68, 10, 'وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ', '68:10'),
(5282, 68, 11, 'هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ', '68:11'),
(5283, 68, 12, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', '68:12'),
(5284, 68, 13, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', '68:13'),
(5285, 68, 14, 'أَن كَانَ ذَا مَالٍ وَبَنِينَ', '68:14'),
(5286, 68, 15, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '68:15'),
(5287, 68, 16, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', '68:16'),
(5288, 68, 17, 'إِنَّا بَلَوْنَـٰهُمْ كَمَا بَلَوْنَآ أَصْحَـٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', '68:17'),
(5289, 68, 18, 'وَلَا يَسْتَثْنُونَ', '68:18'),
(5290, 68, 19, 'فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', '68:19'),
(5291, 68, 20, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', '68:20'),
(5292, 68, 21, 'فَتَنَادَوْا۟ مُصْبِحِينَ', '68:21'),
(5293, 68, 22, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَـٰرِمِينَ', '68:22'),
(5294, 68, 23, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَـٰفَتُونَ', '68:23'),
(5295, 68, 24, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ', '68:24'),
(5296, 68, 25, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَـٰدِرِينَ', '68:25'),
(5297, 68, 26, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', '68:26'),
(5298, 68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ', '68:27'),
(5299, 68, 28, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', '68:28'),
(5300, 68, 29, 'قَالُوا۟ سُبْحَـٰنَ رَبِّنَآ إِنَّا كُنَّا ظَـٰلِمِينَ', '68:29'),
(5301, 68, 30, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَـٰوَمُونَ', '68:30'),
(5302, 68, 31, 'قَالُوا۟ يَـٰوَيْلَنَآ إِنَّا كُنَّا طَـٰغِينَ', '68:31'),
(5303, 68, 32, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', '68:32'),
(5304, 68, 33, 'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', '68:33'),
(5305, 68, 34, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّـٰتِ ٱلنَّعِيمِ', '68:34'),
(5306, 68, 35, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', '68:35'),
(5307, 68, 36, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', '68:36'),
(5308, 68, 37, 'أَمْ لَكُمْ كِتَـٰبٌ فِيهِ تَدْرُسُونَ', '68:37'),
(5309, 68, 38, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', '68:38'),
(5310, 68, 39, 'أَمْ لَكُمْ أَيْمَـٰنٌ عَلَيْنَا بَـٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', '68:39'),
(5311, 68, 40, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', '68:40'),
(5312, 68, 41, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَـٰدِقِينَ', '68:41'),
(5313, 68, 42, 'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', '68:42'),
(5314, 68, 43, 'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَـٰلِمُونَ', '68:43'),
(5315, 68, 44, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَـٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', '68:44'),
(5316, 68, 45, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', '68:45'),
(5317, 68, 46, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', '68:46'),
(5318, 68, 47, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', '68:47'),
(5319, 68, 48, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ', '68:48'),
(5320, 68, 49, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ', '68:49'),
(5321, 68, 50, 'فَٱجْتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ', '68:50'),
(5322, 68, 51, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَـٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ', '68:51'),
(5323, 68, 52, 'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', '68:52'),
(5324, 69, 1, ' ٱلْحَآقَّةُ', '69:1'),
(5325, 69, 2, 'مَا ٱلْحَآقَّةُ', '69:2'),
(5326, 69, 3, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', '69:3'),
(5327, 69, 4, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', '69:4'),
(5328, 69, 5, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', '69:5'),
(5329, 69, 6, 'وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ', '69:6'),
(5330, 69, 7, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَـٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ', '69:7'),
(5331, 69, 8, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ', '69:8'),
(5332, 69, 9, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَـٰتُ بِٱلْخَاطِئَةِ', '69:9'),
(5333, 69, 10, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً', '69:10'),
(5334, 69, 11, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَـٰكُمْ فِى ٱلْجَارِيَةِ', '69:11'),
(5335, 69, 12, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ', '69:12'),
(5336, 69, 13, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ', '69:13'),
(5337, 69, 14, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً', '69:14'),
(5338, 69, 15, 'فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ', '69:15'),
(5339, 69, 16, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ', '69:16'),
(5340, 69, 17, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَـٰنِيَةٌ', '69:17'),
(5341, 69, 18, 'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ', '69:18'),
(5342, 69, 19, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَـٰبِيَهْ', '69:19'),
(5343, 69, 20, 'إِنِّى ظَنَنتُ أَنِّى مُلَـٰقٍ حِسَابِيَهْ', '69:20'),
(5344, 69, 21, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', '69:21'),
(5345, 69, 22, 'فِى جَنَّةٍ عَالِيَةٍ', '69:22'),
(5346, 69, 23, 'قُطُوفُهَا دَانِيَةٌ', '69:23'),
(5347, 69, 24, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', '69:24'),
(5348, 69, 25, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَـٰلَيْتَنِى لَمْ أُوتَ كِتَـٰبِيَهْ', '69:25'),
(5349, 69, 26, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', '69:26'),
(5350, 69, 27, 'يَـٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', '69:27'),
(5351, 69, 28, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ', '69:28'),
(5352, 69, 29, 'هَلَكَ عَنِّى سُلْطَـٰنِيَهْ', '69:29'),
(5353, 69, 30, 'خُذُوهُ فَغُلُّوهُ', '69:30'),
(5354, 69, 31, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', '69:31'),
(5355, 69, 32, 'ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ', '69:32'),
(5356, 69, 33, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', '69:33'),
(5357, 69, 34, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', '69:34'),
(5358, 69, 35, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَـٰهُنَا حَمِيمٌ', '69:35'),
(5359, 69, 36, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ', '69:36'),
(5360, 69, 37, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَـٰطِـُٔونَ', '69:37'),
(5361, 69, 38, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', '69:38'),
(5362, 69, 39, 'وَمَا لَا تُبْصِرُونَ', '69:39'),
(5363, 69, 40, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', '69:40'),
(5364, 69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍ ۚ قَلِيلًا مَّا تُؤْمِنُونَ', '69:41'),
(5365, 69, 42, 'وَلَا بِقَوْلِ كَاهِنٍ ۚ قَلِيلًا مَّا تَذَكَّرُونَ', '69:42'),
(5366, 69, 43, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', '69:43'),
(5367, 69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', '69:44'),
(5368, 69, 45, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', '69:45'),
(5369, 69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', '69:46'),
(5370, 69, 47, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَـٰجِزِينَ', '69:47'),
(5371, 69, 48, 'وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ', '69:48'),
(5372, 69, 49, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', '69:49'),
(5373, 69, 50, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَـٰفِرِينَ', '69:50'),
(5374, 69, 51, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', '69:51'),
(5375, 69, 52, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', '69:52'),
(5376, 70, 1, ' سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ', '70:1'),
(5377, 70, 2, 'لِّلْكَـٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ', '70:2'),
(5378, 70, 3, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', '70:3'),
(5379, 70, 4, 'تَعْرُجُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ', '70:4'),
(5380, 70, 5, 'فَٱصْبِرْ صَبْرًا جَمِيلًا', '70:5'),
(5381, 70, 6, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا', '70:6'),
(5382, 70, 7, 'وَنَرَىٰهُ قَرِيبًا', '70:7'),
(5383, 70, 8, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', '70:8'),
(5384, 70, 9, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', '70:9'),
(5385, 70, 10, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا', '70:10'),
(5386, 70, 11, 'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', '70:11'),
(5387, 70, 12, 'وَصَـٰحِبَتِهِۦ وَأَخِيهِ', '70:12'),
(5388, 70, 13, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', '70:13'),
(5389, 70, 14, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ', '70:14'),
(5390, 70, 15, 'كَلَّآ ۖ إِنَّهَا لَظَىٰ', '70:15'),
(5391, 70, 16, 'نَزَّاعَةً لِّلشَّوَىٰ', '70:16'),
(5392, 70, 17, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', '70:17'),
(5393, 70, 18, 'وَجَمَعَ فَأَوْعَىٰٓ', '70:18'),
(5394, 70, 19, '۞ إِنَّ ٱلْإِنسَـٰنَ خُلِقَ هَلُوعًا', '70:19'),
(5395, 70, 20, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا', '70:20'),
(5396, 70, 21, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', '70:21'),
(5397, 70, 22, 'إِلَّا ٱلْمُصَلِّينَ', '70:22'),
(5398, 70, 23, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', '70:23'),
(5399, 70, 24, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ', '70:24'),
(5400, 70, 25, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', '70:25'),
(5401, 70, 26, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', '70:26'),
(5402, 70, 27, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', '70:27'),
(5403, 70, 28, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ', '70:28'),
(5404, 70, 29, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَـٰفِظُونَ', '70:29'),
(5405, 70, 30, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', '70:30'),
(5406, 70, 31, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْعَادُونَ', '70:31'),
(5407, 70, 32, 'وَٱلَّذِينَ هُمْ لِأَمَـٰنَـٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', '70:32'),
(5408, 70, 33, 'وَٱلَّذِينَ هُم بِشَهَـٰدَٰتِهِمْ قَآئِمُونَ', '70:33'),
(5409, 70, 34, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', '70:34'),
(5410, 70, 35, 'أُو۟لَـٰٓئِكَ فِى جَنَّـٰتٍ مُّكْرَمُونَ', '70:35'),
(5411, 70, 36, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', '70:36'),
(5412, 70, 37, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', '70:37'),
(5413, 70, 38, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ', '70:38'),
(5414, 70, 39, 'كَلَّآ ۖ إِنَّا خَلَقْنَـٰهُم مِّمَّا يَعْلَمُونَ', '70:39'),
(5415, 70, 40, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَـٰرِقِ وَٱلْمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ', '70:40'),
(5416, 70, 41, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', '70:41'),
(5417, 70, 42, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', '70:42'),
(5418, 70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ', '70:43'),
(5419, 70, 44, 'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', '70:44'),
(5420, 71, 1, ' إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', '71:1'),
(5421, 71, 2, 'قَالَ يَـٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', '71:2'),
(5422, 71, 3, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', '71:3'),
(5423, 71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ', '71:4'),
(5424, 71, 5, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', '71:5'),
(5425, 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', '71:6'),
(5426, 71, 7, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', '71:7'),
(5427, 71, 8, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', '71:8'),
(5428, 71, 9, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', '71:9'),
(5429, 71, 10, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا', '71:10'),
(5430, 71, 11, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا', '71:11'),
(5431, 71, 12, 'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا', '71:12'),
(5432, 71, 13, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا', '71:13'),
(5433, 71, 14, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', '71:14'),
(5434, 71, 15, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا', '71:15'),
(5435, 71, 16, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا', '71:16'),
(5436, 71, 17, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا', '71:17'),
(5437, 71, 18, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا', '71:18'),
(5438, 71, 19, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', '71:19'),
(5439, 71, 20, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', '71:20'),
(5440, 71, 21, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', '71:21'),
(5441, 71, 22, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', '71:22'),
(5442, 71, 23, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', '71:23'),
(5443, 71, 24, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا ۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَـٰلًا', '71:24'),
(5444, 71, 25, 'مِّمَّا خَطِيٓـَٔـٰتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', '71:25'),
(5445, 71, 26, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَـٰفِرِينَ دَيَّارًا', '71:26'),
(5446, 71, 27, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', '71:27'),
(5447, 71, 28, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارًۢا', '71:28'),
(5448, 72, 1, ' قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', '72:1'),
(5449, 72, 2, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', '72:2'),
(5450, 72, 3, 'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةً وَلَا وَلَدًا', '72:3'),
(5451, 72, 4, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', '72:4'),
(5452, 72, 5, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', '72:5'),
(5453, 72, 6, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', '72:6'),
(5454, 72, 7, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', '72:7'),
(5455, 72, 8, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَـٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', '72:8'),
(5456, 72, 9, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَـٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', '72:9'),
(5457, 72, 10, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', '72:10'),
(5458, 72, 11, 'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًا', '72:11'),
(5459, 72, 12, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', '72:12'),
(5460, 72, 13, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', '72:13'),
(5461, 72, 14, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَـٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَـٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', '72:14'),
(5462, 72, 15, 'وَأَمَّا ٱلْقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', '72:15'),
(5463, 72, 16, 'وَأَلَّوِ ٱسْتَقَـٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَـٰهُم مَّآءً غَدَقًا', '72:16'),
(5464, 72, 17, 'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', '72:17'),
(5465, 72, 18, 'وَأَنَّ ٱلْمَسَـٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', '72:18'),
(5466, 72, 19, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', '72:19'),
(5467, 72, 20, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', '72:20'),
(5468, 72, 21, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', '72:21'),
(5469, 72, 22, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '72:22'),
(5470, 72, 23, 'إِلَّا بَلَـٰغًا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا', '72:23'),
(5471, 72, 24, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', '72:24'),
(5472, 72, 25, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', '72:25'),
(5473, 72, 26, 'عَـٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', '72:26'),
(5474, 72, 27, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', '72:27'),
(5475, 72, 28, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', '72:28'),
(5476, 73, 1, ' يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ', '73:1'),
(5477, 73, 2, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا', '73:2'),
(5478, 73, 3, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', '73:3'),
(5479, 73, 4, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', '73:4'),
(5480, 73, 5, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', '73:5'),
(5481, 73, 6, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', '73:6'),
(5482, 73, 7, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', '73:7'),
(5483, 73, 8, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', '73:8'),
(5484, 73, 9, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا', '73:9'),
(5485, 73, 10, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا', '73:10'),
(5486, 73, 11, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', '73:11'),
(5487, 73, 12, 'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا', '73:12'),
(5488, 73, 13, 'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا', '73:13'),
(5489, 73, 14, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا', '73:14'),
(5490, 73, 15, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا', '73:15'),
(5491, 73, 16, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَـٰهُ أَخْذًا وَبِيلًا', '73:16'),
(5492, 73, 17, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', '73:17'),
(5493, 73, 18, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا', '73:18'),
(5494, 73, 19, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', '73:19'),
(5495, 73, 20, '۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ', '73:20'),
(5496, 74, 1, ' يَـٰٓأَيُّهَا ٱلْمُدَّثِّرُ', '74:1'),
(5497, 74, 2, 'قُمْ فَأَنذِرْ', '74:2'),
(5498, 74, 3, 'وَرَبَّكَ فَكَبِّرْ', '74:3'),
(5499, 74, 4, 'وَثِيَابَكَ فَطَهِّرْ', '74:4'),
(5500, 74, 5, 'وَٱلرُّجْزَ فَٱهْجُرْ', '74:5'),
(5501, 74, 6, 'وَلَا تَمْنُن تَسْتَكْثِرُ', '74:6'),
(5502, 74, 7, 'وَلِرَبِّكَ فَٱصْبِرْ', '74:7'),
(5503, 74, 8, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', '74:8'),
(5504, 74, 9, 'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ', '74:9'),
(5505, 74, 10, 'عَلَى ٱلْكَـٰفِرِينَ غَيْرُ يَسِيرٍ', '74:10'),
(5506, 74, 11, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا', '74:11'),
(5507, 74, 12, 'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا', '74:12'),
(5508, 74, 13, 'وَبَنِينَ شُهُودًا', '74:13'),
(5509, 74, 14, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا', '74:14'),
(5510, 74, 15, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', '74:15'),
(5511, 74, 16, 'كَلَّآ ۖ إِنَّهُۥ كَانَ لِـَٔايَـٰتِنَا عَنِيدًا', '74:16'),
(5512, 74, 17, 'سَأُرْهِقُهُۥ صَعُودًا', '74:17'),
(5513, 74, 18, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', '74:18'),
(5514, 74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَ', '74:19'),
(5515, 74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', '74:20'),
(5516, 74, 21, 'ثُمَّ نَظَرَ', '74:21'),
(5517, 74, 22, 'ثُمَّ عَبَسَ وَبَسَرَ', '74:22'),
(5518, 74, 23, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', '74:23'),
(5519, 74, 24, 'فَقَالَ إِنْ هَـٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ', '74:24'),
(5520, 74, 25, 'إِنْ هَـٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', '74:25'),
(5521, 74, 26, 'سَأُصْلِيهِ سَقَرَ', '74:26'),
(5522, 74, 27, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', '74:27'),
(5523, 74, 28, 'لَا تُبْقِى وَلَا تَذَرُ', '74:28'),
(5524, 74, 29, 'لَوَّاحَةٌ لِّلْبَشَرِ', '74:29'),
(5525, 74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَ', '74:30'),
(5526, 74, 31, 'وَمَا جَعَلْنَآ أَصْحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةً ۙ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَـٰنًا ۙ وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْمُؤْمِنُونَ ۙ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَـٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', '74:31'),
(5527, 74, 32, 'كَلَّا وَٱلْقَمَرِ', '74:32'),
(5528, 74, 33, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', '74:33'),
(5529, 74, 34, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', '74:34'),
(5530, 74, 35, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', '74:35'),
(5531, 74, 36, 'نَذِيرًا لِّلْبَشَرِ', '74:36'),
(5532, 74, 37, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', '74:37'),
(5533, 74, 38, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', '74:38'),
(5534, 74, 39, 'إِلَّآ أَصْحَـٰبَ ٱلْيَمِينِ', '74:39'),
(5535, 74, 40, 'فِى جَنَّـٰتٍ يَتَسَآءَلُونَ', '74:40'),
(5536, 74, 41, 'عَنِ ٱلْمُجْرِمِينَ', '74:41'),
(5537, 74, 42, 'مَا سَلَكَكُمْ فِى سَقَرَ', '74:42'),
(5538, 74, 43, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', '74:43'),
(5539, 74, 44, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', '74:44'),
(5540, 74, 45, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', '74:45'),
(5541, 74, 46, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', '74:46'),
(5542, 74, 47, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', '74:47'),
(5543, 74, 48, 'فَمَا تَنفَعُهُمْ شَفَـٰعَةُ ٱلشَّـٰفِعِينَ', '74:48'),
(5544, 74, 49, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', '74:49'),
(5545, 74, 50, 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', '74:50'),
(5546, 74, 51, 'فَرَّتْ مِن قَسْوَرَةٍۭ', '74:51'),
(5547, 74, 52, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', '74:52'),
(5548, 74, 53, 'كَلَّا ۖ بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ', '74:53'),
(5549, 74, 54, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ', '74:54'),
(5550, 74, 55, 'فَمَن شَآءَ ذَكَرَهُۥ', '74:55'),
(5551, 74, 56, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', '74:56'),
(5552, 75, 1, ' لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَـٰمَةِ', '75:1'),
(5553, 75, 2, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', '75:2'),
(5554, 75, 3, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', '75:3'),
(5555, 75, 4, 'بَلَىٰ قَـٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', '75:4'),
(5556, 75, 5, 'بَلْ يُرِيدُ ٱلْإِنسَـٰنُ لِيَفْجُرَ أَمَامَهُۥ', '75:5'),
(5557, 75, 6, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَـٰمَةِ', '75:6'),
(5558, 75, 7, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', '75:7'),
(5559, 75, 8, 'وَخَسَفَ ٱلْقَمَرُ', '75:8'),
(5560, 75, 9, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', '75:9'),
(5561, 75, 10, 'يَقُولُ ٱلْإِنسَـٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', '75:10'),
(5562, 75, 11, 'كَلَّا لَا وَزَرَ', '75:11'),
(5563, 75, 12, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', '75:12'),
(5564, 75, 13, 'يُنَبَّؤُا۟ ٱلْإِنسَـٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', '75:13'),
(5565, 75, 14, 'بَلِ ٱلْإِنسَـٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ', '75:14'),
(5566, 75, 15, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', '75:15'),
(5567, 75, 16, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', '75:16'),
(5568, 75, 17, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', '75:17'),
(5569, 75, 18, 'فَإِذَا قَرَأْنَـٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', '75:18'),
(5570, 75, 19, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', '75:19'),
(5571, 75, 20, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', '75:20'),
(5572, 75, 21, 'وَتَذَرُونَ ٱلْـَٔاخِرَةَ', '75:21'),
(5573, 75, 22, 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', '75:22'),
(5574, 75, 23, 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', '75:23'),
(5575, 75, 24, 'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ', '75:24'),
(5576, 75, 25, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', '75:25'),
(5577, 75, 26, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', '75:26'),
(5578, 75, 27, 'وَقِيلَ مَنْ ۜ رَاقٍ', '75:27'),
(5579, 75, 28, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', '75:28'),
(5580, 75, 29, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', '75:29'),
(5581, 75, 30, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', '75:30'),
(5582, 75, 31, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', '75:31'),
(5583, 75, 32, 'وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ', '75:32'),
(5584, 75, 33, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', '75:33'),
(5585, 75, 34, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', '75:34'),
(5586, 75, 35, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', '75:35'),
(5587, 75, 36, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَن يُتْرَكَ سُدًى', '75:36'),
(5588, 75, 37, 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ', '75:37'),
(5589, 75, 38, 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', '75:38'),
(5590, 75, 39, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', '75:39'),
(5591, 75, 40, 'أَلَيْسَ ذَٰلِكَ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ', '75:40'),
(5592, 76, 1, ' هَلْ أَتَىٰ عَلَى ٱلْإِنسَـٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا', '76:1'),
(5593, 76, 2, 'إِنَّا خَلَقْنَا ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـٰهُ سَمِيعًۢا بَصِيرًا', '76:2'),
(5594, 76, 3, 'إِنَّا هَدَيْنَـٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', '76:3'),
(5595, 76, 4, 'إِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَلَـٰسِلَا۟ وَأَغْلَـٰلًا وَسَعِيرًا', '76:4'),
(5596, 76, 5, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', '76:5'),
(5597, 76, 6, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', '76:6'),
(5598, 76, 7, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', '76:7'),
(5599, 76, 8, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', '76:8'),
(5600, 76, 9, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', '76:9'),
(5601, 76, 10, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', '76:10'),
(5602, 76, 11, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', '76:11'),
(5603, 76, 12, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', '76:12'),
(5604, 76, 13, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', '76:13'),
(5605, 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَـٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', '76:14'),
(5606, 76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', '76:15'),
(5607, 76, 16, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', '76:16'),
(5608, 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', '76:17'),
(5609, 76, 18, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', '76:18'),
(5610, 76, 19, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', '76:19'),
(5611, 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', '76:20'),
(5612, 76, 21, 'عَـٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ ۖ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', '76:21'),
(5613, 76, 22, 'إِنَّ هَـٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', '76:22'),
(5614, 76, 23, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا', '76:23'),
(5615, 76, 24, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا', '76:24'),
(5616, 76, 25, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', '76:25'),
(5617, 76, 26, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا', '76:26'),
(5618, 76, 27, 'إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا', '76:27'),
(5619, 76, 28, 'نَّحْنُ خَلَقْنَـٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَـٰلَهُمْ تَبْدِيلًا', '76:28'),
(5620, 76, 29, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', '76:29'),
(5621, 76, 30, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '76:30'),
(5622, 76, 31, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', '76:31'),
(5623, 77, 1, ' وَٱلْمُرْسَلَـٰتِ عُرْفًا', '77:1'),
(5624, 77, 2, 'فَٱلْعَـٰصِفَـٰتِ عَصْفًا', '77:2'),
(5625, 77, 3, 'وَٱلنَّـٰشِرَٰتِ نَشْرًا', '77:3'),
(5626, 77, 4, 'فَٱلْفَـٰرِقَـٰتِ فَرْقًا', '77:4'),
(5627, 77, 5, 'فَٱلْمُلْقِيَـٰتِ ذِكْرًا', '77:5'),
(5628, 77, 6, 'عُذْرًا أَوْ نُذْرًا', '77:6'),
(5629, 77, 7, 'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ', '77:7'),
(5630, 77, 8, 'فَإِذَا ٱلنُّجُومُ طُمِسَتْ', '77:8'),
(5631, 77, 9, 'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ', '77:9'),
(5632, 77, 10, 'وَإِذَا ٱلْجِبَالُ نُسِفَتْ', '77:10'),
(5633, 77, 11, 'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ', '77:11'),
(5634, 77, 12, 'لِأَىِّ يَوْمٍ أُجِّلَتْ', '77:12'),
(5635, 77, 13, 'لِيَوْمِ ٱلْفَصْلِ', '77:13'),
(5636, 77, 14, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ', '77:14'),
(5637, 77, 15, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:15'),
(5638, 77, 16, 'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ', '77:16'),
(5639, 77, 17, 'ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ', '77:17'),
(5640, 77, 18, 'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', '77:18'),
(5641, 77, 19, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:19'),
(5642, 77, 20, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ', '77:20'),
(5643, 77, 21, 'فَجَعَلْنَـٰهُ فِى قَرَارٍ مَّكِينٍ', '77:21'),
(5644, 77, 22, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', '77:22'),
(5645, 77, 23, 'فَقَدَرْنَا فَنِعْمَ ٱلْقَـٰدِرُونَ', '77:23'),
(5646, 77, 24, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:24'),
(5647, 77, 25, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا', '77:25'),
(5648, 77, 26, 'أَحْيَآءً وَأَمْوَٰتًا', '77:26'),
(5649, 77, 27, 'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَـٰمِخَـٰتٍ وَأَسْقَيْنَـٰكُم مَّآءً فُرَاتًا', '77:27'),
(5650, 77, 28, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:28'),
(5651, 77, 29, 'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', '77:29'),
(5652, 77, 30, 'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَـٰثِ شُعَبٍ', '77:30'),
(5653, 77, 31, 'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ', '77:31'),
(5654, 77, 32, 'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ', '77:32'),
(5655, 77, 33, 'كَأَنَّهُۥ جِمَـٰلَتٌ صُفْرٌ', '77:33'),
(5656, 77, 34, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:34'),
(5657, 77, 35, 'هَـٰذَا يَوْمُ لَا يَنطِقُونَ', '77:35'),
(5658, 77, 36, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', '77:36'),
(5659, 77, 37, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:37'),
(5660, 77, 38, 'هَـٰذَا يَوْمُ ٱلْفَصْلِ ۖ جَمَعْنَـٰكُمْ وَٱلْأَوَّلِينَ', '77:38'),
(5661, 77, 39, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', '77:39'),
(5662, 77, 40, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:40'),
(5663, 77, 41, 'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَـٰلٍ وَعُيُونٍ', '77:41'),
(5664, 77, 42, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ', '77:42'),
(5665, 77, 43, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', '77:43'),
(5666, 77, 44, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '77:44'),
(5667, 77, 45, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:45'),
(5668, 77, 46, 'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ', '77:46'),
(5669, 77, 47, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:47'),
(5670, 77, 48, 'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ', '77:48'),
(5671, 77, 49, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '77:49'),
(5672, 77, 50, 'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', '77:50'),
(5673, 78, 1, ' عَمَّ يَتَسَآءَلُونَ', '78:1'),
(5674, 78, 2, 'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ', '78:2'),
(5675, 78, 3, 'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ', '78:3'),
(5676, 78, 4, 'كَلَّا سَيَعْلَمُونَ', '78:4'),
(5677, 78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', '78:5'),
(5678, 78, 6, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًا', '78:6'),
(5679, 78, 7, 'وَٱلْجِبَالَ أَوْتَادًا', '78:7'),
(5680, 78, 8, 'وَخَلَقْنَـٰكُمْ أَزْوَٰجًا', '78:8'),
(5681, 78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', '78:9'),
(5682, 78, 10, 'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا', '78:10'),
(5683, 78, 11, 'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا', '78:11'),
(5684, 78, 12, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', '78:12'),
(5685, 78, 13, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', '78:13'),
(5686, 78, 14, 'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا', '78:14'),
(5687, 78, 15, 'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا', '78:15'),
(5688, 78, 16, 'وَجَنَّـٰتٍ أَلْفَافًا', '78:16'),
(5689, 78, 17, 'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًا', '78:17'),
(5690, 78, 18, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا', '78:18'),
(5691, 78, 19, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا', '78:19'),
(5692, 78, 20, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', '78:20'),
(5693, 78, 21, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', '78:21'),
(5694, 78, 22, 'لِّلطَّـٰغِينَ مَـَٔابًا', '78:22'),
(5695, 78, 23, 'لَّـٰبِثِينَ فِيهَآ أَحْقَابًا', '78:23'),
(5696, 78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', '78:24'),
(5697, 78, 25, 'إِلَّا حَمِيمًا وَغَسَّاقًا', '78:25'),
(5698, 78, 26, 'جَزَآءً وِفَاقًا', '78:26'),
(5699, 78, 27, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا', '78:27'),
(5700, 78, 28, 'وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا كِذَّابًا', '78:28'),
(5701, 78, 29, 'وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ كِتَـٰبًا', '78:29'),
(5702, 78, 30, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', '78:30'),
(5703, 78, 31, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', '78:31'),
(5704, 78, 32, 'حَدَآئِقَ وَأَعْنَـٰبًا', '78:32'),
(5705, 78, 33, 'وَكَوَاعِبَ أَتْرَابًا', '78:33'),
(5706, 78, 34, 'وَكَأْسًا دِهَاقًا', '78:34'),
(5707, 78, 35, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا', '78:35'),
(5708, 78, 36, 'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا', '78:36'),
(5709, 78, 37, 'رَّبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَـٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', '78:37'),
(5710, 78, 38, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَـٰٓئِكَةُ صَفًّا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَابًا', '78:38'),
(5711, 78, 39, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', '78:39'),
(5712, 78, 40, 'إِنَّآ أَنذَرْنَـٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَـٰلَيْتَنِى كُنتُ تُرَٰبًۢا', '78:40'),
(5713, 79, 1, ' وَٱلنَّـٰزِعَـٰتِ غَرْقًا', '79:1'),
(5714, 79, 2, 'وَٱلنَّـٰشِطَـٰتِ نَشْطًا', '79:2'),
(5715, 79, 3, 'وَٱلسَّـٰبِحَـٰتِ سَبْحًا', '79:3'),
(5716, 79, 4, 'فَٱلسَّـٰبِقَـٰتِ سَبْقًا', '79:4'),
(5717, 79, 5, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا', '79:5'),
(5718, 79, 6, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', '79:6'),
(5719, 79, 7, 'تَتْبَعُهَا ٱلرَّادِفَةُ', '79:7'),
(5720, 79, 8, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ', '79:8'),
(5721, 79, 9, 'أَبْصَـٰرُهَا خَـٰشِعَةٌ', '79:9'),
(5722, 79, 10, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', '79:10'),
(5723, 79, 11, 'أَءِذَا كُنَّا عِظَـٰمًا نَّخِرَةً', '79:11'),
(5724, 79, 12, 'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ', '79:12'),
(5725, 79, 13, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ', '79:13'),
(5726, 79, 14, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', '79:14'),
(5727, 79, 15, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', '79:15'),
(5728, 79, 16, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', '79:16'),
(5729, 79, 17, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', '79:17'),
(5730, 79, 18, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', '79:18'),
(5731, 79, 19, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', '79:19'),
(5732, 79, 20, 'فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ', '79:20'),
(5733, 79, 21, 'فَكَذَّبَ وَعَصَىٰ', '79:21'),
(5734, 79, 22, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', '79:22'),
(5735, 79, 23, 'فَحَشَرَ فَنَادَىٰ', '79:23'),
(5736, 79, 24, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', '79:24'),
(5737, 79, 25, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ', '79:25'),
(5738, 79, 26, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ', '79:26'),
(5739, 79, 27, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا', '79:27'),
(5740, 79, 28, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', '79:28'),
(5741, 79, 29, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', '79:29'),
(5742, 79, 30, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', '79:30'),
(5743, 79, 31, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', '79:31'),
(5744, 79, 32, 'وَٱلْجِبَالَ أَرْسَىٰهَا', '79:32'),
(5745, 79, 33, 'مَتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ', '79:33'),
(5746, 79, 34, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', '79:34'),
(5747, 79, 35, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَـٰنُ مَا سَعَىٰ', '79:35'),
(5748, 79, 36, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', '79:36'),
(5749, 79, 37, 'فَأَمَّا مَن طَغَىٰ', '79:37'),
(5750, 79, 38, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', '79:38'),
(5751, 79, 39, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', '79:39'),
(5752, 79, 40, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', '79:40'),
(5753, 79, 41, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', '79:41'),
(5754, 79, 42, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', '79:42'),
(5755, 79, 43, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', '79:43'),
(5756, 79, 44, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', '79:44'),
(5757, 79, 45, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', '79:45'),
(5758, 79, 46, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', '79:46'),
(5759, 80, 1, ' عَبَسَ وَتَوَلَّىٰٓ', '80:1'),
(5760, 80, 2, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', '80:2'),
(5761, 80, 3, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', '80:3'),
(5762, 80, 4, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', '80:4'),
(5763, 80, 5, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', '80:5'),
(5764, 80, 6, 'فَأَنتَ لَهُۥ تَصَدَّىٰ', '80:6'),
(5765, 80, 7, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', '80:7'),
(5766, 80, 8, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', '80:8'),
(5767, 80, 9, 'وَهُوَ يَخْشَىٰ', '80:9'),
(5768, 80, 10, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', '80:10'),
(5769, 80, 11, 'كَلَّآ إِنَّهَا تَذْكِرَةٌ', '80:11'),
(5770, 80, 12, 'فَمَن شَآءَ ذَكَرَهُۥ', '80:12'),
(5771, 80, 13, 'فِى صُحُفٍ مُّكَرَّمَةٍ', '80:13'),
(5772, 80, 14, 'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ', '80:14'),
(5773, 80, 15, 'بِأَيْدِى سَفَرَةٍ', '80:15'),
(5774, 80, 16, 'كِرَامٍۭ بَرَرَةٍ', '80:16'),
(5775, 80, 17, 'قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ', '80:17'),
(5776, 80, 18, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', '80:18'),
(5777, 80, 19, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', '80:19'),
(5778, 80, 20, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', '80:20'),
(5779, 80, 21, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', '80:21'),
(5780, 80, 22, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', '80:22'),
(5781, 80, 23, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', '80:23'),
(5782, 80, 24, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ', '80:24'),
(5783, 80, 25, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا', '80:25'),
(5784, 80, 26, 'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا', '80:26'),
(5785, 80, 27, 'فَأَنۢبَتْنَا فِيهَا حَبًّا', '80:27'),
(5786, 80, 28, 'وَعِنَبًا وَقَضْبًا', '80:28'),
(5787, 80, 29, 'وَزَيْتُونًا وَنَخْلًا', '80:29'),
(5788, 80, 30, 'وَحَدَآئِقَ غُلْبًا', '80:30'),
(5789, 80, 31, 'وَفَـٰكِهَةً وَأَبًّا', '80:31'),
(5790, 80, 32, 'مَّتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ', '80:32'),
(5791, 80, 33, 'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ', '80:33'),
(5792, 80, 34, 'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ', '80:34'),
(5793, 80, 35, 'وَأُمِّهِۦ وَأَبِيهِ', '80:35'),
(5794, 80, 36, 'وَصَـٰحِبَتِهِۦ وَبَنِيهِ', '80:36'),
(5795, 80, 37, 'لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ', '80:37'),
(5796, 80, 38, 'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ', '80:38'),
(5797, 80, 39, 'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ', '80:39'),
(5798, 80, 40, 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ', '80:40'),
(5799, 80, 41, 'تَرْهَقُهَا قَتَرَةٌ', '80:41'),
(5800, 80, 42, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ', '80:42'),
(5801, 81, 1, ' إِذَا ٱلشَّمْسُ كُوِّرَتْ', '81:1'),
(5802, 81, 2, 'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ', '81:2'),
(5803, 81, 3, 'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ', '81:3'),
(5804, 81, 4, 'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ', '81:4'),
(5805, 81, 5, 'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ', '81:5'),
(5806, 81, 6, 'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ', '81:6'),
(5807, 81, 7, 'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ', '81:7'),
(5808, 81, 8, 'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ', '81:8'),
(5809, 81, 9, 'بِأَىِّ ذَنۢبٍ قُتِلَتْ', '81:9'),
(5810, 81, 10, 'وَإِذَا ٱلصُّحُفُ نُشِرَتْ', '81:10'),
(5811, 81, 11, 'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ', '81:11'),
(5812, 81, 12, 'وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ', '81:12'),
(5813, 81, 13, 'وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ', '81:13'),
(5814, 81, 14, 'عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ', '81:14'),
(5815, 81, 15, 'فَلَآ أُقْسِمُ بِٱلْخُنَّسِ', '81:15'),
(5816, 81, 16, 'ٱلْجَوَارِ ٱلْكُنَّسِ', '81:16'),
(5817, 81, 17, 'وَٱلَّيْلِ إِذَا عَسْعَسَ', '81:17'),
(5818, 81, 18, 'وَٱلصُّبْحِ إِذَا تَنَفَّسَ', '81:18'),
(5819, 81, 19, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', '81:19'),
(5820, 81, 20, 'ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍ', '81:20'),
(5821, 81, 21, 'مُّطَاعٍ ثَمَّ أَمِينٍ', '81:21'),
(5822, 81, 22, 'وَمَا صَاحِبُكُم بِمَجْنُونٍ', '81:22'),
(5823, 81, 23, 'وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ', '81:23'),
(5824, 81, 24, 'وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ', '81:24'),
(5825, 81, 25, 'وَمَا هُوَ بِقَوْلِ شَيْطَـٰنٍ رَّجِيمٍ', '81:25'),
(5826, 81, 26, 'فَأَيْنَ تَذْهَبُونَ', '81:26'),
(5827, 81, 27, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', '81:27'),
(5828, 81, 28, 'لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ', '81:28'),
(5829, 81, 29, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ', '81:29'),
(5830, 82, 1, ' إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', '82:1'),
(5831, 82, 2, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', '82:2'),
(5832, 82, 3, 'وَإِذَا ٱلْبِحَارُ فُجِّرَتْ', '82:3'),
(5833, 82, 4, 'وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ', '82:4'),
(5834, 82, 5, 'عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ', '82:5'),
(5835, 82, 6, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ', '82:6'),
(5836, 82, 7, 'ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ', '82:7'),
(5837, 82, 8, 'فِىٓ أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ', '82:8'),
(5838, 82, 9, 'كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ', '82:9'),
(5839, 82, 10, 'وَإِنَّ عَلَيْكُمْ لَحَـٰفِظِينَ', '82:10'),
(5840, 82, 11, 'كِرَامًا كَـٰتِبِينَ', '82:11'),
(5841, 82, 12, 'يَعْلَمُونَ مَا تَفْعَلُونَ', '82:12'),
(5842, 82, 13, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', '82:13'),
(5843, 82, 14, 'وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍ', '82:14'),
(5844, 82, 15, 'يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ', '82:15'),
(5845, 82, 16, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ', '82:16'),
(5846, 82, 17, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', '82:17'),
(5847, 82, 18, 'ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', '82:18'),
(5848, 82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍ لِّلَّهِ', '82:19'),
(5849, 83, 1, ' وَيْلٌ لِّلْمُطَفِّفِينَ', '83:1'),
(5850, 83, 2, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', '83:2'),
(5851, 83, 3, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', '83:3'),
(5852, 83, 4, 'أَلَا يَظُنُّ أُو۟لَـٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', '83:4'),
(5853, 83, 5, 'لِيَوْمٍ عَظِيمٍ', '83:5'),
(5854, 83, 6, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَـٰلَمِينَ', '83:6'),
(5855, 83, 7, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍ', '83:7'),
(5856, 83, 8, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌ', '83:8'),
(5857, 83, 9, 'كِتَـٰبٌ مَّرْقُومٌ', '83:9'),
(5858, 83, 10, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', '83:10'),
(5859, 83, 11, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', '83:11'),
(5860, 83, 12, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', '83:12'),
(5861, 83, 13, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', '83:13'),
(5862, 83, 14, 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', '83:14'),
(5863, 83, 15, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ', '83:15'),
(5864, 83, 16, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', '83:16'),
(5865, 83, 17, 'ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', '83:17'),
(5866, 83, 18, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', '83:18'),
(5867, 83, 19, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', '83:19'),
(5868, 83, 20, 'كِتَـٰبٌ مَّرْقُومٌ', '83:20'),
(5869, 83, 21, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', '83:21'),
(5870, 83, 22, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', '83:22'),
(5871, 83, 23, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', '83:23'),
(5872, 83, 24, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', '83:24'),
(5873, 83, 25, 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', '83:25'),
(5874, 83, 26, 'خِتَـٰمُهُۥ مِسْكٌ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَـٰفِسُونَ', '83:26'),
(5875, 83, 27, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', '83:27'),
(5876, 83, 28, 'عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', '83:28'),
(5877, 83, 29, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', '83:29'),
(5878, 83, 30, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', '83:30'),
(5879, 83, 31, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', '83:31'),
(5880, 83, 32, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ', '83:32'),
(5881, 83, 33, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَـٰفِظِينَ', '83:33'),
(5882, 83, 34, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', '83:34'),
(5883, 83, 35, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', '83:35'),
(5884, 83, 36, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', '83:36'),
(5885, 84, 1, ' إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', '84:1'),
(5886, 84, 2, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', '84:2'),
(5887, 84, 3, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', '84:3'),
(5888, 84, 4, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', '84:4'),
(5889, 84, 5, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', '84:5'),
(5890, 84, 6, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَـٰقِيهِ', '84:6'),
(5891, 84, 7, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ', '84:7'),
(5892, 84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', '84:8'),
(5893, 84, 9, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا', '84:9'),
(5894, 84, 10, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', '84:10'),
(5895, 84, 11, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًا', '84:11'),
(5896, 84, 12, 'وَيَصْلَىٰ سَعِيرًا', '84:12'),
(5897, 84, 13, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', '84:13'),
(5898, 84, 14, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', '84:14'),
(5899, 84, 15, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا', '84:15'),
(5900, 84, 16, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', '84:16'),
(5901, 84, 17, 'وَٱلَّيْلِ وَمَا وَسَقَ', '84:17'),
(5902, 84, 18, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', '84:18'),
(5903, 84, 19, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', '84:19'),
(5904, 84, 20, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', '84:20'),
(5905, 84, 21, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', '84:21'),
(5906, 84, 22, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', '84:22'),
(5907, 84, 23, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', '84:23'),
(5908, 84, 24, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '84:24'),
(5909, 84, 25, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', '84:25'),
(5910, 85, 1, ' وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', '85:1'),
(5911, 85, 2, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', '85:2'),
(5912, 85, 3, 'وَشَاهِدٍ وَمَشْهُودٍ', '85:3'),
(5913, 85, 4, 'قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ', '85:4'),
(5914, 85, 5, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', '85:5'),
(5915, 85, 6, 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', '85:6'),
(5916, 85, 7, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ', '85:7'),
(5917, 85, 8, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', '85:8'),
(5918, 85, 9, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '85:9'),
(5919, 85, 10, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', '85:10'),
(5920, 85, 11, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', '85:11'),
(5921, 85, 12, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', '85:12'),
(5922, 85, 13, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', '85:13'),
(5923, 85, 14, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', '85:14'),
(5924, 85, 15, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', '85:15'),
(5925, 85, 16, 'فَعَّالٌ لِّمَا يُرِيدُ', '85:16'),
(5926, 85, 17, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', '85:17'),
(5927, 85, 18, 'فِرْعَوْنَ وَثَمُودَ', '85:18'),
(5928, 85, 19, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ', '85:19'),
(5929, 85, 20, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', '85:20'),
(5930, 85, 21, 'بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ', '85:21'),
(5931, 85, 22, 'فِى لَوْحٍ مَّحْفُوظٍۭ', '85:22'),
(5932, 86, 1, ' وَٱلسَّمَآءِ وَٱلطَّارِقِ', '86:1'),
(5933, 86, 2, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', '86:2'),
(5934, 86, 3, 'ٱلنَّجْمُ ٱلثَّاقِبُ', '86:3'),
(5935, 86, 4, 'إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ', '86:4'),
(5936, 86, 5, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ', '86:5'),
(5937, 86, 6, 'خُلِقَ مِن مَّآءٍ دَافِقٍ', '86:6'),
(5938, 86, 7, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', '86:7'),
(5939, 86, 8, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ', '86:8'),
(5940, 86, 9, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', '86:9'),
(5941, 86, 10, 'فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ', '86:10'),
(5942, 86, 11, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', '86:11'),
(5943, 86, 12, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', '86:12'),
(5944, 86, 13, 'إِنَّهُۥ لَقَوْلٌ فَصْلٌ', '86:13'),
(5945, 86, 14, 'وَمَا هُوَ بِٱلْهَزْلِ', '86:14'),
(5946, 86, 15, 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', '86:15'),
(5947, 86, 16, 'وَأَكِيدُ كَيْدًا', '86:16'),
(5948, 86, 17, 'فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', '86:17'),
(5949, 87, 1, ' سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', '87:1'),
(5950, 87, 2, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', '87:2'),
(5951, 87, 3, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', '87:3'),
(5952, 87, 4, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', '87:4'),
(5953, 87, 5, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', '87:5'),
(5954, 87, 6, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', '87:6'),
(5955, 87, 7, 'إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', '87:7'),
(5956, 87, 8, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', '87:8'),
(5957, 87, 9, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', '87:9'),
(5958, 87, 10, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', '87:10'),
(5959, 87, 11, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', '87:11'),
(5960, 87, 12, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', '87:12'),
(5961, 87, 13, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', '87:13'),
(5962, 87, 14, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', '87:14'),
(5963, 87, 15, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', '87:15'),
(5964, 87, 16, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', '87:16'),
(5965, 87, 17, 'وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ', '87:17'),
(5966, 87, 18, 'إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', '87:18'),
(5967, 87, 19, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', '87:19'),
(5968, 88, 1, ' هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ', '88:1'),
(5969, 88, 2, 'وُجُوهٌ يَوْمَئِذٍ خَـٰشِعَةٌ', '88:2'),
(5970, 88, 3, 'عَامِلَةٌ نَّاصِبَةٌ', '88:3'),
(5971, 88, 4, 'تَصْلَىٰ نَارًا حَامِيَةً', '88:4'),
(5972, 88, 5, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ', '88:5'),
(5973, 88, 6, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ', '88:6'),
(5974, 88, 7, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ', '88:7'),
(5975, 88, 8, 'وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ', '88:8'),
(5976, 88, 9, 'لِّسَعْيِهَا رَاضِيَةٌ', '88:9'),
(5977, 88, 10, 'فِى جَنَّةٍ عَالِيَةٍ', '88:10'),
(5978, 88, 11, 'لَّا تَسْمَعُ فِيهَا لَـٰغِيَةً', '88:11'),
(5979, 88, 12, 'فِيهَا عَيْنٌ جَارِيَةٌ', '88:12'),
(5980, 88, 13, 'فِيهَا سُرُرٌ مَّرْفُوعَةٌ', '88:13'),
(5981, 88, 14, 'وَأَكْوَابٌ مَّوْضُوعَةٌ', '88:14'),
(5982, 88, 15, 'وَنَمَارِقُ مَصْفُوفَةٌ', '88:15'),
(5983, 88, 16, 'وَزَرَابِىُّ مَبْثُوثَةٌ', '88:16'),
(5984, 88, 17, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', '88:17'),
(5985, 88, 18, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', '88:18'),
(5986, 88, 19, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', '88:19'),
(5987, 88, 20, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', '88:20'),
(5988, 88, 21, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ', '88:21'),
(5989, 88, 22, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', '88:22'),
(5990, 88, 23, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', '88:23'),
(5991, 88, 24, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', '88:24'),
(5992, 88, 25, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', '88:25'),
(5993, 88, 26, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', '88:26'),
(5994, 89, 1, ' وَٱلْفَجْرِ', '89:1'),
(5995, 89, 2, 'وَلَيَالٍ عَشْرٍ', '89:2'),
(5996, 89, 3, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', '89:3'),
(5997, 89, 4, 'وَٱلَّيْلِ إِذَا يَسْرِ', '89:4'),
(5998, 89, 5, 'هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ', '89:5'),
(5999, 89, 6, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', '89:6'),
(6000, 89, 7, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', '89:7');
INSERT INTO `ayahs` (`id`, `surah_number`, `verse_number`, `text_uthmani`, `verse_key`) VALUES
(6001, 89, 8, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ', '89:8'),
(6002, 89, 9, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', '89:9'),
(6003, 89, 10, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', '89:10'),
(6004, 89, 11, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ', '89:11'),
(6005, 89, 12, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', '89:12'),
(6006, 89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', '89:13'),
(6007, 89, 14, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', '89:14'),
(6008, 89, 15, 'فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', '89:15'),
(6009, 89, 16, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ', '89:16'),
(6010, 89, 17, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', '89:17'),
(6011, 89, 18, 'وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', '89:18'),
(6012, 89, 19, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا', '89:19'),
(6013, 89, 20, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا', '89:20'),
(6014, 89, 21, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', '89:21'),
(6015, 89, 22, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا', '89:22'),
(6016, 89, 23, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', '89:23'),
(6017, 89, 24, 'يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', '89:24'),
(6018, 89, 25, 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ', '89:25'),
(6019, 89, 26, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ', '89:26'),
(6020, 89, 27, 'يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', '89:27'),
(6021, 89, 28, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', '89:28'),
(6022, 89, 29, 'فَٱدْخُلِى فِى عِبَـٰدِى', '89:29'),
(6023, 89, 30, 'وَٱدْخُلِى جَنَّتِى', '89:30'),
(6024, 90, 1, ' لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ', '90:1'),
(6025, 90, 2, 'وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ', '90:2'),
(6026, 90, 3, 'وَوَالِدٍ وَمَا وَلَدَ', '90:3'),
(6027, 90, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ', '90:4'),
(6028, 90, 5, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', '90:5'),
(6029, 90, 6, 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', '90:6'),
(6030, 90, 7, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', '90:7'),
(6031, 90, 8, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', '90:8'),
(6032, 90, 9, 'وَلِسَانًا وَشَفَتَيْنِ', '90:9'),
(6033, 90, 10, 'وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ', '90:10'),
(6034, 90, 11, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', '90:11'),
(6035, 90, 12, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', '90:12'),
(6036, 90, 13, 'فَكُّ رَقَبَةٍ', '90:13'),
(6037, 90, 14, 'أَوْ إِطْعَـٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ', '90:14'),
(6038, 90, 15, 'يَتِيمًا ذَا مَقْرَبَةٍ', '90:15'),
(6039, 90, 16, 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', '90:16'),
(6040, 90, 17, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', '90:17'),
(6041, 90, 18, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', '90:18'),
(6042, 90, 19, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', '90:19'),
(6043, 90, 20, 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ', '90:20'),
(6044, 91, 1, ' وَٱلشَّمْسِ وَضُحَىٰهَا', '91:1'),
(6045, 91, 2, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', '91:2'),
(6046, 91, 3, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', '91:3'),
(6047, 91, 4, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', '91:4'),
(6048, 91, 5, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', '91:5'),
(6049, 91, 6, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', '91:6'),
(6050, 91, 7, 'وَنَفْسٍ وَمَا سَوَّىٰهَا', '91:7'),
(6051, 91, 8, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', '91:8'),
(6052, 91, 9, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', '91:9'),
(6053, 91, 10, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', '91:10'),
(6054, 91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', '91:11'),
(6055, 91, 12, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', '91:12'),
(6056, 91, 13, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا', '91:13'),
(6057, 91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', '91:14'),
(6058, 91, 15, 'وَلَا يَخَافُ عُقْبَـٰهَا', '91:15'),
(6059, 92, 1, ' وَٱلَّيْلِ إِذَا يَغْشَىٰ', '92:1'),
(6060, 92, 2, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', '92:2'),
(6061, 92, 3, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', '92:3'),
(6062, 92, 4, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', '92:4'),
(6063, 92, 5, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', '92:5'),
(6064, 92, 6, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', '92:6'),
(6065, 92, 7, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', '92:7'),
(6066, 92, 8, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', '92:8'),
(6067, 92, 9, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', '92:9'),
(6068, 92, 10, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', '92:10'),
(6069, 92, 11, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', '92:11'),
(6070, 92, 12, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', '92:12'),
(6071, 92, 13, 'وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ', '92:13'),
(6072, 92, 14, 'فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', '92:14'),
(6073, 92, 15, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', '92:15'),
(6074, 92, 16, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', '92:16'),
(6075, 92, 17, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', '92:17'),
(6076, 92, 18, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', '92:18'),
(6077, 92, 19, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ', '92:19'),
(6078, 92, 20, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', '92:20'),
(6079, 92, 21, 'وَلَسَوْفَ يَرْضَىٰ', '92:21'),
(6080, 93, 1, ' وَٱلضُّحَىٰ', '93:1'),
(6081, 93, 2, 'وَٱلَّيْلِ إِذَا سَجَىٰ', '93:2'),
(6082, 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', '93:3'),
(6083, 93, 4, 'وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ', '93:4'),
(6084, 93, 5, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', '93:5'),
(6085, 93, 6, 'أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ', '93:6'),
(6086, 93, 7, 'وَوَجَدَكَ ضَآلًّا فَهَدَىٰ', '93:7'),
(6087, 93, 8, 'وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ', '93:8'),
(6088, 93, 9, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', '93:9'),
(6089, 93, 10, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', '93:10'),
(6090, 93, 11, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', '93:11'),
(6091, 94, 1, ' أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', '94:1'),
(6092, 94, 2, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', '94:2'),
(6093, 94, 3, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', '94:3'),
(6094, 94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', '94:4'),
(6095, 94, 5, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', '94:5'),
(6096, 94, 6, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', '94:6'),
(6097, 94, 7, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', '94:7'),
(6098, 94, 8, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', '94:8'),
(6099, 95, 1, 'وَٱلتِّينِ وَٱلزَّيْتُونِ', '95:1'),
(6100, 95, 2, 'وَطُورِ سِينِينَ', '95:2'),
(6101, 95, 3, 'وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', '95:3'),
(6102, 95, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ', '95:4'),
(6103, 95, 5, 'ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ', '95:5'),
(6104, 95, 6, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', '95:6'),
(6105, 95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', '95:7'),
(6106, 95, 8, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ', '95:8'),
(6107, 96, 1, ' ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', '96:1'),
(6108, 96, 2, 'خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ', '96:2'),
(6109, 96, 3, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', '96:3'),
(6110, 96, 4, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', '96:4'),
(6111, 96, 5, 'عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ', '96:5'),
(6112, 96, 6, 'كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ', '96:6'),
(6113, 96, 7, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', '96:7'),
(6114, 96, 8, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', '96:8'),
(6115, 96, 9, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', '96:9'),
(6116, 96, 10, 'عَبْدًا إِذَا صَلَّىٰٓ', '96:10'),
(6117, 96, 11, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', '96:11'),
(6118, 96, 12, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', '96:12'),
(6119, 96, 13, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', '96:13'),
(6120, 96, 14, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', '96:14'),
(6121, 96, 15, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', '96:15'),
(6122, 96, 16, 'نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ', '96:16'),
(6123, 96, 17, 'فَلْيَدْعُ نَادِيَهُۥ', '96:17'),
(6124, 96, 18, 'سَنَدْعُ ٱلزَّبَانِيَةَ', '96:18'),
(6125, 96, 19, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', '96:19'),
(6126, 97, 1, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', '97:1'),
(6127, 97, 2, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', '97:2'),
(6128, 97, 3, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', '97:3'),
(6129, 97, 4, 'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', '97:4'),
(6130, 97, 5, 'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', '97:5'),
(6131, 98, 1, ' لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', '98:1'),
(6132, 98, 2, 'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً', '98:2'),
(6133, 98, 3, 'فِيهَا كُتُبٌ قَيِّمَةٌ', '98:3'),
(6134, 98, 4, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', '98:4'),
(6135, 98, 5, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', '98:5'),
(6136, 98, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', '98:6'),
(6137, 98, 7, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', '98:7'),
(6138, 98, 8, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', '98:8'),
(6139, 99, 1, ' إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', '99:1'),
(6140, 99, 2, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', '99:2'),
(6141, 99, 3, 'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا', '99:3'),
(6142, 99, 4, 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', '99:4'),
(6143, 99, 5, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', '99:5'),
(6144, 99, 6, 'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ', '99:6'),
(6145, 99, 7, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ', '99:7'),
(6146, 99, 8, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ', '99:8'),
(6147, 100, 1, ' وَٱلْعَـٰدِيَـٰتِ ضَبْحًا', '100:1'),
(6148, 100, 2, 'فَٱلْمُورِيَـٰتِ قَدْحًا', '100:2'),
(6149, 100, 3, 'فَٱلْمُغِيرَٰتِ صُبْحًا', '100:3'),
(6150, 100, 4, 'فَأَثَرْنَ بِهِۦ نَقْعًا', '100:4'),
(6151, 100, 5, 'فَوَسَطْنَ بِهِۦ جَمْعًا', '100:5'),
(6152, 100, 6, 'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌ', '100:6'),
(6153, 100, 7, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', '100:7'),
(6154, 100, 8, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', '100:8'),
(6155, 100, 9, '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', '100:9'),
(6156, 100, 10, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', '100:10'),
(6157, 100, 11, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ', '100:11'),
(6158, 101, 1, ' ٱلْقَارِعَةُ', '101:1'),
(6159, 101, 2, 'مَا ٱلْقَارِعَةُ', '101:2'),
(6160, 101, 3, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', '101:3'),
(6161, 101, 4, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', '101:4'),
(6162, 101, 5, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', '101:5'),
(6163, 101, 6, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', '101:6'),
(6164, 101, 7, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', '101:7'),
(6165, 101, 8, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', '101:8'),
(6166, 101, 9, 'فَأُمُّهُۥ هَاوِيَةٌ', '101:9'),
(6167, 101, 10, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', '101:10'),
(6168, 101, 11, 'نَارٌ حَامِيَةٌۢ', '101:11'),
(6169, 102, 1, ' أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', '102:1'),
(6170, 102, 2, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', '102:2'),
(6171, 102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَ', '102:3'),
(6172, 102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', '102:4'),
(6173, 102, 5, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', '102:5'),
(6174, 102, 6, 'لَتَرَوُنَّ ٱلْجَحِيمَ', '102:6'),
(6175, 102, 7, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', '102:7'),
(6176, 102, 8, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', '102:8'),
(6177, 103, 1, ' وَٱلْعَصْرِ', '103:1'),
(6178, 103, 2, 'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ', '103:2'),
(6179, 103, 3, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', '103:3'),
(6180, 104, 1, ' وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ', '104:1'),
(6181, 104, 2, 'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ', '104:2'),
(6182, 104, 3, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', '104:3'),
(6183, 104, 4, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', '104:4'),
(6184, 104, 5, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', '104:5'),
(6185, 104, 6, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', '104:6'),
(6186, 104, 7, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', '104:7'),
(6187, 104, 8, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ', '104:8'),
(6188, 104, 9, 'فِى عَمَدٍ مُّمَدَّدَةٍۭ', '104:9'),
(6189, 105, 1, ' أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ', '105:1'),
(6190, 105, 2, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ', '105:2'),
(6191, 105, 3, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', '105:3'),
(6192, 105, 4, 'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ', '105:4'),
(6193, 105, 5, 'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ', '105:5'),
(6194, 106, 1, ' لِإِيلَـٰفِ قُرَيْشٍ', '106:1'),
(6195, 106, 2, 'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', '106:2'),
(6196, 106, 3, 'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ', '106:3'),
(6197, 106, 4, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ', '106:4'),
(6198, 107, 1, ' أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', '107:1'),
(6199, 107, 2, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', '107:2'),
(6200, 107, 3, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', '107:3'),
(6201, 107, 4, 'فَوَيْلٌ لِّلْمُصَلِّينَ', '107:4'),
(6202, 107, 5, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', '107:5'),
(6203, 107, 6, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', '107:6'),
(6204, 107, 7, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', '107:7'),
(6205, 108, 1, ' إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ', '108:1'),
(6206, 108, 2, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', '108:2'),
(6207, 108, 3, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', '108:3'),
(6208, 109, 1, ' قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ', '109:1'),
(6209, 109, 2, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', '109:2'),
(6210, 109, 3, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', '109:3'),
(6211, 109, 4, 'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ', '109:4'),
(6212, 109, 5, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', '109:5'),
(6213, 109, 6, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', '109:6'),
(6214, 110, 1, ' إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', '110:1'),
(6215, 110, 2, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا', '110:2'),
(6216, 110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', '110:3'),
(6217, 111, 1, ' تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ', '111:1'),
(6218, 111, 2, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', '111:2'),
(6219, 111, 3, 'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', '111:3'),
(6220, 111, 4, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', '111:4'),
(6221, 111, 5, 'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ', '111:5'),
(6222, 112, 1, ' قُلْ هُوَ ٱللَّهُ أَحَدٌ', '112:1'),
(6223, 112, 2, 'ٱللَّهُ ٱلصَّمَدُ', '112:2'),
(6224, 112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', '112:3'),
(6225, 112, 4, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', '112:4'),
(6226, 113, 1, ' قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', '113:1'),
(6227, 113, 2, 'مِن شَرِّ مَا خَلَقَ', '113:2'),
(6228, 113, 3, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', '113:3'),
(6229, 113, 4, 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ', '113:4'),
(6230, 113, 5, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', '113:5'),
(6231, 114, 1, ' قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', '114:1'),
(6232, 114, 2, 'مَلِكِ ٱلنَّاسِ', '114:2'),
(6233, 114, 3, 'إِلَـٰهِ ٱلنَّاسِ', '114:3'),
(6234, 114, 4, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', '114:4'),
(6235, 114, 5, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', '114:5'),
(6236, 114, 6, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', '114:6');
INSERT INTO `translations` (`id`, `name`, `language_name`, `author_name`) VALUES
(87, 'Sadiq and Sani', 'amharic', 'Sadiq and Sani');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('1:1', 87, 'በአላህ ስም እጅግ በጣም ሩኅሩህ በጣም አዛኝ በኾነው፡፡'),
('1:2', 87, 'ምስጋና ለአላህ ይገባው የዓለማት ጌታ ለኾነው፤'),
('1:3', 87, 'እጅግ በጣም ርኅሩህ በጣም አዛኝ'),
('1:4', 87, 'የፍርዱ ቀን ባለቤት ለኾነው፡፡'),
('1:5', 87, 'አንተን ብቻ እንግገዛለን፤ አንተንም ብቻ እርዳታን እንለምናለን፡፡'),
('1:6', 87, 'ቀጥተኛውን መንገድ ምራን፡፡'),
('1:7', 87, 'የእነዚያን በነርሱ ላይ በጎ የዋልክላቸውን በነሱ ላይ ያልተቆጣህባቸውንና ያልተሳሳቱትንም ሰዎች መንገድ (ምራን፤ በሉ)፡፡'),
('2:1', 87, 'አ.ለ.መ'),
('2:2', 87, 'ይህ መጽሐፍ (ከአላህ ለመኾኑ) ጥርጥር የለበትም፤ ለፈራህያን መሪ ነው፡፡'),
('2:3', 87, 'ለነዚያ በሩቁ ነገር የሚያምኑ ሶላትንም ደንቡን ጠብቀው የሚሰግዱ ከሰጠናቸውም ሲሳይ የሚቸሩ ለኾኑት፤'),
('2:4', 87, 'ለእነዚያም ወደ አንተ በተወረደውና ከአንተ በፊትም በተወረደው የሚያምኑ በመጨረሻይቱም (ዓለም) እነርሱ የሚያረጋግጡ ለኾኑት (መሪ ነው)፡፡'),
('2:5', 87, 'እነዚያ ከጌታቸው በመመራት ላይ ናቸው፤ እነዚያም እነሱ ፍላጎታቸውን ያገኙ ናቸው፡፡'),
('2:6', 87, 'እነዚያ የካዱት (ሰዎች) ብታስፈራራቸውም ባታስፈራራቸውም በነርሱ ላይ እኩል ነው፤ አያምኑም፡፡'),
('2:7', 87, 'አላህ በልቦቻቸው ላይ በመስሚያቸውም ላይ አትሞባቸዋል፤ በዓይኖቻቸውም ላይ መሸፈኛ አልለ፤ ለነሱም ታላቅ ቅጣት አላቸው፡፡'),
('2:8', 87, 'ከሰዎችም «በአላህና በመጨረሻው ቀን አምነናል» የሚሉ አልሉ፤ እነርሱም አማኞች አይደሉም፡፡'),
('2:9', 87, 'አላህንና እነዚያን ያመኑትን (ሰዎች) ያታልላሉ፤ የማያውቁ ሲኾኑ ነፍሶቻቸውን እንጅ ሌላን አያታልሉም፡፡'),
('2:10', 87, 'በልቦቻቸው ውስጥ (የንፍቅና) በሽታ አለባቸው፡፡ አላህም በሽታን ጨመረባቸው፡፡ ለነርሱም ይዋሹ በነበሩት ምክንያት አሳማሚ ቅጣት አላቸው፡፡'),
('2:11', 87, 'ለነርሱም «በምድር ላይ አታበላሹ» በተባሉ ጊዜ «እኛ አሳማሪዎች ብቻ ነን» ይላሉ፡፡'),
('2:12', 87, 'ንቁ እነርሱ አጥፊዎቹ እነሱው ናቸው፤ ግን አያውቁም፡፡'),
('2:13', 87, 'ለነሱም «ሰዎቹ እንዳመኑ እመኑ» በተባሉ ጊዜ «ቂሎቹ እንዳመኑ እናምናለን?» ይላሉ፡፡ አዋጅ ንቁ እነርሱ ቂሎቹ እነርሱው ናቸው፤ ግን አያውቁም፡፡'),
('2:14', 87, 'እነዚያንም ያመኑትን በተገናኙ ጊዜ «አምነናል» ይላሉ፡፡ ወደ ሰይጣኖቻቸውም ባገለሉ ጊዜ «እኛ ከናንተ ጋር ነን፤ እኛ (በነሱ) ተሳላቂዎች ብቻ ነን» ይላሉ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('2:15', 87, 'አላህ በነሱ ይሳለቅባቸዋል፤ በጥመታቸውም ውስጥ የሚዋልሉ ሲኾኑ ያዘገያቸዋል፡፡'),
('2:16', 87, 'እነዚህ እነዚያ ስህተትን በቅንነት የገዙ ናቸው፡፡ ንግዳቸውም አላተረፈችም፤ ቀጥተኞችም አልኾኑም፡፡'),
('2:17', 87, '(በንፍቅና) ምሳሌያቸው እንደዚያ እሳትን እንዳነደደ ሰው በዙሪያው ያለውን ሁሉ ባበራች ጊዜም አላህ ብርሃናቸውን እንደወሰደባቸው በጨለማዎችም ውስጥ የማያዩ ኾነው እንደተዋቸው (ሰዎች) ብጤ ነው፡፡'),
('2:18', 87, '(እነሱ) ደንቆሮዎች፣ ዲዳዎች፣ ዕውሮች ናቸው፤ ስለዚህ እነርሱ አይመለሱም፡፡'),
('2:19', 87, 'ወይም (ምሳሌያቸው) ከሰማይ እንደ ወረደ ዝናም (ባለቤቶች) ነው፤ በርሱ (በደመናው) ውስጥ ጨለማዎች፣ ነጎድጓድም፣ ብልጭታም ያሉበት ሲኾን ከመብረቆቹ ሞትን ለመፍራት ጣቶቻቸውን በጆሮቻቸው ውስጥ እንደሚያደርጉ ብጤ ነው፡፡ አላህም ከሓዲዎችን ከባቢ ነው፡፡'),
('2:20', 87, 'ብልጭታው ዓይኖቻቸውን ሊነጥቅ ይቀርባል፡፡ ለነርሱ ባበራላቸው ቁጥር በርሱ ውስጥ ይኼዳሉ፡፡ በነሱም ላይ ባጨለመ ጊዜ ይቆማሉ፡፡ አላህም በሻ ኖሮ መስሚያቸውንና ማያዎቻቸውን በወሰደ ነበር፤ አላህ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('2:21', 87, 'እናንተ ሰዎች ሆይ! የፈጠራችሁን እነዚያንም ከናንተ በፊት የነበሩትን (የፈጠረውን) ጌታችሁን ተገዙ፤ (ቅጣትን) ልትጠነቀቁ ይከጀላልና፡፡'),
('2:22', 87, '(እርሱ) ያ ለናንተ ምድርን ምንጣፍ ሰማይንም ጣራ ያደረገ ነው፤ ከሰማይም (ከደመና) ውሃን ያወረደ በርሱም ከፍሬዎች ለናንተ ሲሳይን ያወጣ ነው፡፡ እናንተም (ፈጣሪነቱን) የምታውቁ ስትኾኑ ለአላህ ባላንጣዎችን አታድርጉ፡፡'),
('2:23', 87, 'በባሪያችንም ላይ ካወረድነው በመጠራጠር ውስጥ ብትኾኑ ከብጤው አንዲትን ምዕራፍ አምጡ፡፡ እውነተኞችም እንደኾናችሁ ከአላህ ሌላ መስካሪዎቻችሁን ጥሩ፡፡'),
('2:24', 87, '(ይህንን) ባትሠሩ ፈጽሞም አትሠሩትምና ያችን መቀጣጠያዋ ሰዎችና ድንጋዮች የኾነችውን እሳት ተጠበቁ፤ ለከሓዲዎች ተደግሳለች፡፡'),
('2:25', 87, 'እነዚያን ያመኑትንና መልካሞችንም የሠሩትን ለነርሱ ከሥሮቻቸው ወንዞች የሚፈሱባቸው ገነቶች ያሏቸው መኾኑን አብስራቸው፡፡ ከርሷ ከፍሬ (ዓይነት) ሲሳይን በተመገቡ ቁጥር (ፍሬዎችዋ ስለሚመሳሰሉ) «ይህ ያ ከአሁን በፊት የተገመብነው ነው» ይላሉ፡፡ እርሱንም ተመሳሳይ ኾኖ ተሰጡት፡፡ ለነሱም በውስጧ ንጹህ የተደረጉ ሚስቶች አሏቸው፡፡ እነሱም በውስጧ ዘውታሪዎች ናቸው፡፡'),
('2:26', 87, 'አላህ ማንኛውንም ነገር ትንኝንም ኾነ (በትንሽነት ወይም በትልቅነት) ከበላይዋ የኾነንም ምሳሌ ለማድረግ አያፍርም፡፡ እነዚያ ያመኑትማ፤ እርሱ (ምሳሌው) ከጌታቸው (የተገኘ) እውነት መኾኑን ያውቃሉ፡፡ እነዚያም የካዱትማ «አላህ በዚህ ምንን ምሳሌ ሻ» ይላሉ፡፡ በርሱ (በምሳሌው) ብዙዎችን ያሳስታል በርሱም ብዙዎችን ያቀናል፡፡ በርሱም አመፀኞችን እንጅ ሌላን አያሳስትም፡፡'),
('2:27', 87, 'እነዚያ የአላህን ቃል ኪዳን ከአጠበቀባቸው በኋላ የሚያፈርሱ እንዲቀጠልም በርሱ ያዘዘውን ነገር የሚቆርጡ በምድርም ላይ የሚያበላሹ እነዚያ እነርሱ ከሳሪዎቹ ናቸው፡፡'),
('2:28', 87, 'ሙታን የነበራችሁ ስትኾኑ ሕያው ያደረጋችሁ ከዚያም የሚገድላችሁ ከዚያም ሕያው የሚያደርጋችሁ ሲኾን ከዚያም ወደርሱ የምትመለሱ ስትኾኑ በአላህ እንዴት ትክዳለችሁ!'),
('2:29', 87, 'እርሱ ያ በምድር ያለውን ሁሉ ለእናንተ የፈጠረ ነው፡፡ ከዚያም ወደ ሰማይ አሰበ፤ ሰባት ሰማያትም አደረጋቸው፡፡ እርሱም በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('2:30', 87, '(ሙሐመድ ሆይ) ጌታህ ለመላእክት፡- «እኔ በምድር ላይ ምትክን አድራጊ ነኝ፤» ባለ ጊዜ (የኾነውን አስታውስ፤ እነርሱም) «እኛ ከማመስገን ጋር የምናጠራህ ላንተም የምንቀድስ ስንኾን በርሷ ውስጥ የሚያጠፋንና ደሞችንም የሚያፈስን ታደርጋለህን?» አሉ፡፡ (አላህ) «እኔ የማታውቁትን ነገር አውቃለሁ» አላቸው፡፡'),
('2:31', 87, 'አደምንም ስሞችን ሁሏንም አስተማረው፡፡ ከዚያም በመላእክት ላይ (ተጠሪዎቹን) አቀረባቸው፡፡ «እውነተኞችም እንደኾናችሁ የነዚህን (ተጠሪዎች) ስሞች ንገሩኝ» አላቸው፡፡'),
('2:32', 87, '«ጥራት ይገባህ፤ ከአስተማርከን ነገር በስተቀር ለኛ ዕውቀት የለንም፡፡ አንተ ዐዋቂው ጥበበኛው አንተ ብቻ ነህና» (አሉ)፡፡'),
('2:33', 87, '፡-«አደም ሆይ ስሞቻቸውን ንገራቸው» አለው፡፡ ስሞቻቸውን በነገራቸውም ጊዜ «እኔ የሰማያትንና የምድርን ሩቅ ምስጢር ዐውቃለሁ፤ የምትገልጹትንና ያንንም ትደብቁት የነበራችሁትን ዐውቃለሁ አላልኳችሁምን?» አላቸው፡፡'),
('2:34', 87, 'ለመላእክትም «ለአደም ስገዱ» ባልን ጊዜ (አስታውስ) ፡፡ ሁሉም ወዲያውኑ ሰገዱ፤ ኢብሊስ (ዲያብሎስ) ብቻ ሲቀር እምቢ አለ፤ ኮራም ከከሓዲዎቹም ኾነ፡፡'),
('2:35', 87, '«አደም ሆይ! አንተ ከነሚስትህ በገነት ተቀመጥ፤ ከርሷም በፈለጋችሁት ስፍራ በሰፊው ተመገቡ፤ ግን ይህችን ዛፍ አትቅረቡ፤ ከበደለኞች ትኾናላችሁና» አልንም፡፡'),
('2:36', 87, 'ከርሷም ሰይጣን አዳለጣቸው በውስጡም ከነበሩበት (ድሎት) አወጣቸው፡፡ «ከፊላችሁም ለከፊሉ ጠላት ሲኾን ውረዱ፤ ለናንተም በምድር ላይ እስከ ጊዜ (ሞታችሁ) ድረስ መርጊያና መጣቀሚያ አላችሁ» አልናቸው፡፡'),
('2:37', 87, 'አደምም ከጌታው ቃላትን ተቀበለ፡፡ በርሱ ላይም (ጌታው ጸጸትን በመቀበል) ተመለሰለት፤ እነሆ እርሱ ጸጸትን ተቀባይ አዛኝ ነውና፡፡'),
('2:38', 87, '«ሁላችሁም ኾናችሁ ከርሷ ውረዱ፡፡ ከኔም የኾነ መመሪያ ቢመጣላችሁ ወዲያውኑ መመሪያዬን የተከተለ ሰው በነሱ ላይ ፍርሃት የለባቸውም፤ እነሱም አያዝኑም» አልናቸው፡፡'),
('2:39', 87, 'እነዚያም (በመልክተኞቻችን) የካዱ በአንቀጾቻችንም ያስተባበሉ እነዚያ የእሳት ጓዶች ናቸው፡፡ እነርሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('2:40', 87, 'የእስራኤል ልጆች ሆይ! ያችን በናንተ ላይ የለገስኳትን ጸጋዬን አስታውሱ፡፡ በቃል ኪዳኔም ሙሉ፤ በቃል ኪዳናችሁ እሞላለሁና፤ እኔንም ብቻ ፍሩ፡፡'),
('2:41', 87, 'ከናንተ ጋር ያለውን (መጽሐፍ) የሚያረጋግጥ ሆኖ ባወረድኩትም (ቁርኣን) እመኑ፡፡ በርሱም የመጀመሪያ ከሓዲ አትሁኑ፡፡ በአንቀጾቼም ጥቂትን ዋጋ አትለውጡ፡፡ እኔንም ብቻ ተጠንቀቁ፡'),
('2:42', 87, 'እውነቱንም በውሸት አትቀላቅሉ፡፡ እናንተም የምታውቁ ስትሆኑ እውነትን አትደብቁ፡፡'),
('2:43', 87, 'ሶላትንም ደንቡን ጠብቃችሁ ስገዱ፡፡ ዘካንም (ግዴታ ምጽዋትን) ስጡ፡፡ (ለጌታችሁ) ከአጎንባሾች ጋርም አጎንብሱ፡፡'),
('2:44', 87, 'እናንተ መጽሐፉን የምታነቡ ሆናችሁ ሰዎችን በበጎ ሥራ ታዛላችሁን? ነፍሶቻችሁንም ትረሳላችሁን? (የሥራችሁን መጥፎነት) አታውቁምን?'),
('2:45', 87, 'በመታገስና በሶላትም ተረዱ፡፡ እርሷም (ሶላት) በፈሪዎች ላይ እንጅ በሌላው ላይ በእርግጥ ከባድ ናት፡፡'),
('2:46', 87, 'እነዚያ እነርሱ ጌታቸውን የሚገናኙ እነሱም ወደእርሱ ተመላሾች መኾናቸውን የሚያረጋግጡ በኾኑት (ላይ እንጅ ከባድ ናት)፡፡'),
('2:47', 87, 'የእስራኤል ልጆች ሆይ! ያችን በናንተ ላይ የለገስኳትን ጸጋዬንና እኔም በዓለማት ላይ ያበለጥኳችሁ (አባቶቻችሁን በጊዜያቸው ከነበሩት ዓለማት ያበለጥኩዋቸው) መኾኔን አስታውሱ፡፡'),
('2:48', 87, '(ማንኛዋ) ነፍስም ከ(ሌላዋ) ነፍስ ምንንም የማትመነዳበትን፣ ከርሷም ምልጃን የማይቀበሉባትን፣ ከርሷም ቤዛ የማይያዝበትን፣ እነርሱም የማይረዱበትን ቀን ተጠንቀቁ፡፡'),
('2:49', 87, 'ከፈርዖንም ቤተሰቦች (ከጎሶቹና ከሰራዊቱ) ብርቱን ቅጣት የሚያቀምሱዋችሁ ወንዶች ልጆቻችሁን የሚያርዱ ሴቶቻችሁንም የሚተው ሲኾኑ ባዳንናችሁ ጊዜ (የኾነውን አስታውሱ)፡፡ በዚሃችሁም ከጌታችሁ ታላቅ ፈተና አለበት፡፡'),
('2:50', 87, 'በናንተም ምክንያት ባሕሩን በከፈልን ጊዜ (አስታውሱ)፡፡ ወዲያውም አዳንናችሁ፡፡ የፈርዖንንም ቤተሰቦች እናንተ የምትመለከቱ ኾናችሁ አሰጠምናቸው፡፡'),
('2:51', 87, 'ሙሳንም አርባን ሌሊት በቀጠርነው ጊዜ (የኾነውን አስታውሱ)፡፡ ከዚያም ከርሱ (መኼድ) በኋላ እናንተ በዳዮች ስትኾኑ ወይፈንን (አምላክ አድርጋችሁ) ያዛችሁ፡፡'),
('2:52', 87, 'ከዚያም ከዚህ በኋላ እናንተ ታመሰግኑ ዘንድ ከናንተ ምሕረት አደረግን፡፡'),
('2:53', 87, 'ሙሳንም መጽሐፍንና (እውነትና ውሸትን) መለያንም ትመሩ ዘንድ በሰጠነው ጊዜ (አስታውሱ)፡፡'),
('2:54', 87, 'ሙሳም ለሕዝቦቹ፡- «ሕዝቦቼ ሆይ! እናንተ ወይፈንን (አምላክ አድርጋችሁ) በመያዛችሁ ነፍሶቻችሁን በደላችሁ፡፡ ወደ ፈጣሪያችሁም ተመለሱ፤ ነፍሶቻችሁንም ግደሉ፤ ይሃችሁ በፈጣሪያችሁ ዘንድ ለናንተ በላጭ ነው» ባለ ጊዜ (አስታውስ)፡፡ በእናንተም ላይ ጸጸትን በመቀበል ተመለሰላችሁ፡፡ እነሆ እርሱ ጸጸትን ተቀባይ አዛኝ ነውና፡፡'),
('2:55', 87, '«ሙሳ ሆይ! አላህን በግልጽ እስከምናይ ድረስ ላንተ በፍጹም አናምንልህም» በላችሁም ጊዜ (አስታውሱ)፡፡ እናንተም እየተመለከታችሁ መብረቅ ያዘቻችሁ፡፡'),
('2:56', 87, 'ከዚያም ታመሰግኑ ዘንድ ከሞታችሁ በኋላ አስነሳናችሁ፡፡'),
('2:57', 87, 'በናንተም ላይ ደመናን አጠለልን፡፡ በናተም ላይ (እንደ ነጭ ማር ያለ) መንናን እና ድርጭትን አወረድን፡፡ ከሰጠናችሁም ጣፋጮች «ብሉ (አልን)፡፡» አልበደሉንምም ግን ነፍሶቻቸውን ይበድሉ ነበር፡፡'),
('2:58', 87, '«ይህችንም ከተማ ግቡ፡፡ ከርሷም በሻችሁት ስፍራ ሰፊን (ምግብ) ተመገቡ፡፡ በሩንም ያጎነበሳችሁ ኾናችሁ ግቡ፤ (ጥያቄያችን የኃጢአታችን መርገፍ ነው) በሉም፡፡ ኃጢአቶቻችሁን ለናንተ እንምራለንና፡፡ በጎ ሠሪዎችንም (ምንዳን) እንጨምርላቸዋለን» ባልን ጊዜ (አስታውሱ)፡፡'),
('2:59', 87, 'እነዚያም የበደሉት ሰዎች ከዚያ ለነሱ ከተባሉት ሌላ ቃልን ለወጡ፡፡ በነዚያም በበደሉት ላይ ያመጹ በመሆናቸው ምክንያት መቅሠፍትን አወረድንባቸው፡፡'),
('2:60', 87, 'ሙሳም ለሕዝቦቹ መጠጥን በፈለገ ጊዜ (የኾነውን አስታውሱ)፡፡ «ድንጋዩንም በበትርህ ምታ» አልነው፡፡ (መታውም) ከርሱም ዐሥራሁለት ምንጮች ፈለቁ፡፡ ሰዎቹ ሁሉ መጠጫቸውን በእርግጥ ዐወቁ፡፡ «ከአላህ ሲሳይ ብሉ፤ ጠጡም፤ አመጠኞችም ኾናችሁ በምድር ላይ አታበላሹ» (አልናቸው)፡፡'),
('2:61', 87, 'ሙሳ ሆይ፡- «በአንድ (ዓይነት) ምግብ ላይ በፍጹም አንታገሥም፤ ስለዚህ ጌታህን ከዚያ ምድር ከምታበቅለው ሁሉ ከቅጠላቅጠል ከዱባዋም ከስንዴዋም ከምስርዋም ከሽንኩርቷም ለኛ ያወጣ ዘንድ ለኛ ለምንልን» ባላችሁም ጊዜ (የኾነውን አስታውሱ፡፡ ሙሳም፡- «ያንን እርሱ ዝቅተኛ የኾነውን በዚያ እርሱ በላጭ በኾነው ነገር ለውጥን ትፈልጋላችሁን? ወደ ከተማ ውረዱ፤ ለናንተም የጠየቃችሁት ነገር አላችሁ» አላቸው፡፡ በነርሱም ላይ ውርደትና ድኽነት ተመታባቸው፡፡ ከአላህም በኾነ ቁጣ ተመለሱ፡፡ ይህ እነርሱ በአላህ ታምራቶች ይክዱና ነቢያትንም ያለ ሕግ ይገድሉ ስለነበሩ ነው፡፡ ይህ በማመጻቸውና ወሰን የሚያልፉ በመኾናቸው ነው፡፡'),
('2:62', 87, 'እነዚያ ያመኑ እነዚያም ይሁዳውያን የኾኑ፣ ክርስቲያኖችም፣ ሳቢያኖችም (ከእነርሱ) በአላህና በመጨረሻው ቀን ያመነ መልካምንም ሥራ የሠራ ለነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፡፡ በነርሱም ላይ ፍርሃት የለባቸውም፤ እነሱም አያዝኑም፡፡'),
('2:63', 87, 'ከበላያችሁም የጡርን ተራራ ያነሳን ኾነን የጠበቀ ቃልኪዳናችሁን በያዝን ጊዜ (የኾነውን አስታውሱ)፡፡ «ያንን የሰጠናችሁን በኀይል ያዙ፤ በውስጡ ያለውንም ነገር (ከእሳት) ትጠበቁ ዘንድ አስታውሱ» (አልን)፡፡'),
('2:64', 87, 'ከዚያም ከዚህ በኋላ (ኪዳኑን) ተዋችሁ፡፡ በናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ በእርግጥ ከጠፊዎቹ በኾናችሁ ነበር፡፡'),
('2:65', 87, 'እነዚያንም ከእናንተ ውስጥ በቅዳሜ ቀን (ዐሣን በማጥመድ) ወሰን ያለፉትንና ለነሱ «ወራዳዎች ስትኾኑ ዝንጀሮዎች ኹኑ» ያልናቸውን በእርግጥ ዐወቃችሁ፡፡'),
('2:66', 87, '(ቅጣቲቱንም) ለነዚያ በስተፊትዋ ለነበሩትና ለነዚያም ከበኋላዋ ላሉት (ሕዝቦች) መቀጣጫ ለፈራህያንም መገሰጫ አደረግናት፡፡'),
('2:67', 87, 'ሙሳም ለሕዝቦቹ፡- «አላህ ላምን እንድታርዱ ያዛችኋል» ባለ ጊዜ (አስታወሱ)፡፡«መሳለቂያ አድርገህ ትይዘናለህን?» አሉት፡፡ «ከተሳላቂዎች ከመኾን በአላህ እጠበቃለሁ» አላቸው፡፡'),
('2:68', 87, '«ለኛ ጌታህን ጠይቅልን፤ እርሷ ምን እንደኾነች (ዕድሜዋን) ያብራራልን» አሉ፡፡ «እርሱ እርሷ ያላረጀች ጥጃም ያልኾነች በዚህ መካከል ልከኛ የኾነች ጊደር ናት ይላችኋል፤ የታዘዛችሁትንም ሥሩ» አላቸው፡፡'),
('2:69', 87, '«ለኛ ጌታህን ጠይቅልን፤ መልኳ ምን እንደኾነ ለኛ ይግለጽልን» አሉ፡፡ «እርሱ እርሷ መልኳ ደማቅ ተመልካቾችን የምታስደስት ዳለቻ ላም ናት ይላችኋል» አላቸው፡፡'),
('2:70', 87, '«ለኛ ጌታህን ጠይቅልን፤ እርሷ ምን እንደኾነች ይግለጽልን፤ ከብቶች በኛ ላይ ተመሳሰሉብን፡፡ እኛም አላህ የሻ እንደኾነ በእርግጥ ተመሪዎች ነን» አሉ፡፡'),
('2:71', 87, '«እርሱ እርሷ ያልተገራች ምድርን (በማረስ) የማታስነሳ እርሻንም የማታጠጣ (ከነውር) የተጠበቀች ልዩ ምልክት የሌለባት ናት ይላችኋል» አላቸው፡፡ «አሁን በትክክል መጣህ» አሉ፤ ሊሠሩ ያልተቃረቡም ሲኾኑ አረዷት ፡፡'),
('2:72', 87, 'ነፍስነም በገደላችሁና በርሷም (ገዳይ) በተከራከራችሁ ጊዜ (አስታውሱ)፡፡ አላህም ትደብቁት የነበራችሁትን ሁሉ ገላጭ ነው፡፡'),
('2:73', 87, '«(በድኑን) በከፊሏም ምቱት» አልን፤ እንደዚሁ አላህ ሙታንን ያስነሳል፤ ታውቁም ዘንድ ታምራቶችን ያሳያችኋል፡፡'),
('2:74', 87, 'ከዚያም ከዚህ በኋላ ልቦቻችሁ ደረቁ፤ እርሷም እንደ ድንጋዮች ወይም በድርቅና ይበልጥ የበረታች ናት፡፡ ከድንጋዮችም ከርሱ ጂረቶች የሚፈሱለት አልለ፡፡ ከነርሱም በእርግጥ የሚሰነጠቅና ከርሱ ውሃ (ምንጭ) የሚወጣው አልለ፡፡ ከነርሱም አላህን ከመፍራት የተነሳ ወደ ታች የሚወርድ አልለ፡፡ አላህም ከምትሠሩት ነገር ዘንጊ አይደለም፡፡'),
('2:75', 87, '(አይሁዶች) ከነሱ የኾኑ ጭፍሮች የአላህን ቃል የሚሰሙና ከዚያም ከተረዱት በኋላ እነርሱ እያወቁ የሚለውጡት ሲኾኑ ለናንተ ማመናቸውን ትከጅላላችሁን?'),
('2:76', 87, 'እነዚያንም ያመኑትን ባገኙ ጊዜ «አምነናል» ይላሉ፡፡ ከፊላቸውም ወደ ከፊሉ ባገለለ «ጊዜ አላህ በናንተ ላይ በገለጸላቸሁ ነገር እጌታችሁ ዘንድ በርሱ እንዲከራከሩዋችሁ ትነግሩዋቸዋላችሁን? አታውቁምን?» ይላሉ፡፡'),
('2:77', 87, 'አላህ የሚደብቁትንና የሚገልጹትን የሚያውቅ መኾኑን አያውቁምን?'),
('2:78', 87, 'ከነሱም መጽሐፉን የማያውቁ መሃይማናን አሉ፡፡ ግን ከንቱ ምኞቶችን (ይመኛሉ)፤ እነርሱም የሚጠራጠሩ እንጂ ሌላ አይደሉም፡፡'),
('2:79', 87, 'ለነዚያም መጽሐፉን በእጆቻቸው ለሚጽፉና ከዚያም በርሱ ጥቂትን ዋጋ ሊገዙበት «ይህ ከአላህ ዘንድ ነው» ለሚሉ ወዮላቸው፡፡ ለነርሱም ከዚያ እጆቻቸው ከጻፉት ወዮላቸው፡፡ ለነሱም ከዚያ ከሚያፈሩት (ኃጢኣት) ወዮላቸው፡፡'),
('2:80', 87, '«እሳትም የተቆጠሩን ቀኖች እንጂ አትነካንም» አሉ፡፡ «አላህ ዘንድ ቃል ኪዳን ይዛችኋልን? (ይህ ከኾነ) አላህም ኪዳኑን አያፈርስም፤ በእውነቱ በአላህ ላይ የማታውቁትን ትናገራላችሁ» በላቸው፡፡'),
('2:81', 87, 'አይደለም (ትነካችኋለች)፤ መጥፎን (ክሕደትን) የሠራ በርሱም ኃጠኣቱ የከበበችው ሰው እነዚያ የእሳት ጓዶች ናቸው፡፡ እነርሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('2:82', 87, 'እነዚያም ያመኑት በጎ ሥራዎችንም የሠሩት እነዚያ የገነት ጓዶች ናቸው፡፡ እነርሱ በውስጧ ዘላለም ዘውታሪዎች ናቸው፡፡'),
('2:83', 87, 'የእስራኤል ልጆችንም ጥብቅ ኪዳን አላህን እንጂ ሌላን አታምልኩ፤ በወላጆችም በጎን ሥራ (አድርጉ)፤ በዝምድና ባለቤቶችም፣ በየቲሞችም (አባት የሌላቸው ልጆች) በምስኪኖችም (በጎ ዋሉ)፤ ለሰዎችም መልካምን ተናገሩ፤ ሶላትንም ደንቡን ጠብቃችሁ ስገዱ፤ ዘካንም ስጡ በማለት በያዝንባቸው ጊዜ (አስታውሱ)፡፡ ከዚያም ከናንተ ጥቂቶች ሲቀሩ ሸሻችሁ እናንተም (ኪዳንን) የምትተዉ ናችሁ፡፡'),
('2:84', 87, 'ደሞቻችሁን አታፍስሱ ነፍሶቻችሁንም (ከፊላችሁን) ከአገሮቻችሁ አታውጡ የምንል ስንኾን የጠበቀ ቃል ኪዳናችሁን በያዝንባችሁ ጊዜ (አስታውሱ)፡፡ ከዚያም (በኪዳኑ) አረጋገጣችሁ፤ እናንተም ትመሰክራላችሁ፡፡'),
('2:85', 87, 'ከዚያም እናንተ እነዚያ ነፍሶቻችሁን የምትገድሉ ከናንተም የኾኑ ጭፍሮችን በኃጢአትና በመበደል በነርሱ ላይ የምትረዳዱ ስትኾኑ ከአገሮቻቸው የምታወጡ ምርኮኞችም ኾነው ቢመጡዋችሁ የምትበዡ ናችሁ፡፡ እርሱ (ነገሩ) እነርሱን ማውጣት በእናንተ ላይ የተከለከለ ነው፡፡ በመጽሐፉ ከፊል ታምናላችሁን? በከፊሉም ትክዳላችሁን? ከእናንተም ይህንን የሚሠራ ሰው ቅጣት በቅርቢቱ ሕይወት ውርደት እንጂ ሌላ አይደለም፡፡ በትንሣኤ ቀንም ወደ ብርቱ ቅጣት ይመለሳሉ፡፡ አላህም ከምትሠሩት ሥራ ሁሉ ዘንጊ አይደለም፡፡'),
('2:86', 87, 'እነዚህ እነዚያ ቅርቢቱን ሕይወት በመጨረሻይቱ አገር የገዙ ናቸው፡፡ ከነሱም ቅጣቱ አይቀልላቸውም፤ እነሱም አይርረዱም፡፡'),
('2:87', 87, 'ሙሳንም መጽሐፍን በእርግጥ ሰጠነው፡፡ ከበኋላውም መልክትኞችን አስከታተልን፡፡ የመርየምን ልጅ ዒሳንም ግልጽ ታምራቶችን ሰጠነው፡፡ በቅዱሱ መንፈስም አበረታነው፡፡ ነፍሶቻችሁ በማትወደው ነገር መልክተኛ በመጣላችሁ ቁጥር (ከመከተል) ትኮራላችሁን? ከፊሉን አስተባበላችሁ፤ ከፊሉንም ትገድላላችሁ፡፡'),
('2:88', 87, '«ልቦቻችንም ሽፍኖች ናቸው» አሉ፤ አይደለም አላህ በክሕደታቸው ምክንያት ረገማቸው ጥቂትንም ብቻ ያምናሉ፡፡'),
('2:89', 87, 'ከነሱም ጋር ያለውን (መጽሐፍ) አረጋጋጭ የኾነ መጽሐፍ ከአላህ ዘንድ በመጣላቸው ጊዜ (ከመምጣቱ) በፊት በነዚያ በካዱት ላይ ይረዱበት የነበሩ ሲኾኑ ያወቁት ነገር በመጣላቸው ጊዜ በርሱ ካዱ፡፡ የአላህም ርግማን በከሓዲዎች ላይ ይኹን፡፡'),
('2:90', 87, 'ነፍሶቻቸውን በርሱ የሸጡበት ነገር ከፋ! (እርሱም) አላህ ከባሮቹ በሚሻው ሰው ላይ ከችሮታው (ራእይን) ማውረዱን በመመቅኘት አላህ ባወረደው ነገር መካዳቸው ነው፡፡ በቁጣ ላይም ቁጣ (የተረጋገጠባቸው ሲኾኑ) ተመለሱ፡፡ ለከሓዲዎችም አዋራጅ ቅጣት አላቸው፡፡'),
('2:91', 87, 'አላህም ባወረደው (ሁሉ) ለእነርሱ «እመኑ» በተባሉ ጊዜ «በኛ ላይ በተወረደው (መጽሐፍ ብቻ) እናምናለን» ይላሉ፡፡ ከርሱ ኋላ ባለው (ቁርአን) እርሱ ከነሱ ጋር ላለው (መጽሐፍ) አረጋጋጭ እውተኛ ሲኾን ይክዳሉ፡፡ «አማኞች ከኾናችሁ ከአሁን በፊት የአላህን ነቢያት ለምን ገደላችሁ?» በላቸው፡፡'),
('2:92', 87, 'ሙሳም በታምራቶች በእርግጥ መጣላችሁ፡፡ ከዚያም ከበኋላው እናንተ በዳዮች ስትኾኑ ወይፈንን (አምላክ አድርጋችሁ) ያዛችሁ፡፡'),
('2:93', 87, 'የጡርንም ጋራ ከበላያችሁ ያነሳን ስንኾን (በኦሪት ሕግ እንድትሠሩ) ኪዳናችሁን በያዝን ጊዜ (አስታውሱ)፡፡ «የሰጠናችሁን በኀይል ያዙ፤ ስሙም፤» (አልን)፡፡«ሰማን አመጽንም» አሉ፡፡ የወይፈኑንም ውዴታ በክሕደታቸው ምክንያት በልቦቻቸው ውስጥ ተጠጡ፡፡ «አማኞች እንደኾናችሁ እምነታችሁ በርሱ የሚያዛችሁ ነገር ከፋ!» በላቸው፡፡'),
('2:94', 87, '«የመጨረሻይቱ አገር (ገነት) አላህ ዘንድ ከሰው ሁሉ ሌላ የተለየች ስትኾን ለእናንተ ብቻ እንደኾነች እውነተኞች ከኾናችሁ ሞትን ተመኙ» በላቸው፡፡'),
('2:95', 87, 'እጆቻቸውም ባሳለፉት (በሠሩት) ምክንያት ምን ጊዜም ፈጽሞ አይመኙትም፤ አላህም በዳዮችን ዐዋቂ ነው፡፡'),
('2:96', 87, 'ከሰዎችም ሁሉ ከእነዚያም (ጣዖትን) ከአጋሩት ይበልጥ በሕይወት ላይ የሚጓጉ ኾነው በእርግጥ ታገኛቸዋለህ፡፡ አንዳቸው ሺሕ ዓመት ዕድሜ ቢሰጥ ይወዳል፡፡ እርሱም ዕድሜ መሰጠቱ ከቅጣት የሚያርቀው አይደለም፡፡ አላህም የሚሠሩትን ሁሉ ተመልካች ነው፡፡'),
('2:97', 87, 'ለጂብሪል (ለገብርኤል) ጠላት የኾነ ሰው (በቁጭት ይሙት) በላቸው፡፡ እርሱ (ቁርኣኑን) ከበፊቱ ለነበሩት (መጻሕፍት) አረጋጋጭ ለምእመናን መሪና ብስራት ሲኾን በአላህ ፈቃድ በልብህ ላይ አውርዶታልና፡፡'),
('2:98', 87, 'ለአላህና ለመላእክቱ ለመልክተኞቹም ለጂብሪልም ለሚካልም (ሚካኤል) ጠላት የኾነ ሰው አላህ ለ(እነዚህ) ከሓዲዎች ጠላት ነው፡፡'),
('2:99', 87, 'ወዳንተም ግልጽ የኾኑትን አንቀጾች በእርግጥ አውርደናል፡፡ በርሷም አመጸኞች እንጂ ሌላው አይክድም፤'),
('2:100', 87, 'ቃል ኪዳንንም ቃል በገቡ ቁጥር ከእነርሱ ከፊሉ ይጥለዋልን? (ያፈርሰዋልን?)፤ ይልቁንም አብዛኞቻቸው አያምኑም፡፡'),
('2:101', 87, 'እነርሱ ጋርም ላለው (መጽሐፍ) አረጋጋጭ የኾነ መልክተኛ ከአላህ ዘንድ በመጣላቸው ጊዜ ከነዚያ መጽሐፍን ከተሰጡት ከፊሉ እነርሱ እንደማያውቁ ኾነው የአላህን መጽሐፍ ከጀርባዎቻቸው ኋላ ጣሉ፡፡'),
('2:102', 87, 'ሰይጣናትም በሱለይማን (ሰሎሞን) ዘመነ መንግስት የሚያነቡትን (ድግምት) ተከተሉ፡፡ ሱለይማንም አልካደም፤ (ድግምተኛ አልነበረም)፤ ግን ሰይጣናት ሰዎችን ድግምትን የሚያስተምሩ ሲኾኑ ካዱ፡፡ ያንንም በባቢል በሁለቱ መላእክት በሃሩትና ማሩት ላይ የተወረደውን ነገር (ያስተምሩዋቸዋል)፡፡ «እኛ መፈተኛ ነንና አትካድ» እስከሚሉም ድረስ አንድንም አያስተምሩም፡፡ ከእነሱም በሰውየውና በሚስቱ መካከል በርሱ የሚለዩበትን ነገር ይማራሉ፡፡ እነርሱም በአላህ ፈቃድ ካልኾነ በርሱ አንድንም ጎጂዎች አይደሉም፡፡ የሚጎዳቸውንና የማይጠቅማቸውንም ይማራሉ፡፡ የገዛውም ሰው ለርሱ በመጨረሻይቱ አገር ምንም እድል የሌለው መኾኑን በእርግጥ ዐወቁ፡፡ ነፍሶቻቸውንም በርሱ የሸጡበት ዋጋ ከፋ! የሚያውቁ በኾኑ ኖሮ (ባልሠሩት ነበር)፡፡'),
('2:103', 87, 'እነርሱም (አይሁዶች) ባመኑና በተጠነቀቁ ኖሮ (በተመነዱ ነበር)፡፡ የሚያውቁ ቢኾኑ ከአላህ ዘንድ የኾነው ምንዳ (ነፍሶቻቸውን ከሚሸጡበት) በላጭ ነው፡፤'),
('2:104', 87, 'እናንተ ያመናችሁ ሆይ! (ለነቢዩ) ራዒና አትበሉ፡፡ ተመለከትን በሉም፡፡ ስሙም፤ ለከሓዲዎችም አሳማሚ ቅጣት አላቸው፡፡'),
('2:105', 87, 'እነዚያ ከመጽሐፉ ባለቤቶችና ከአጋሪዎቹም የካዱት በናንተ ላይ ከጌታችሁ የኾነ መልካም ነገር መወረዱን አይወዱም፡፡ አላህም በችሮታው (በነቢይነት) የሚሻውን ይመርጣል፡፡ አላህም የታላቅ ችሮታ ባለቤት ነው፡፡'),
('2:106', 87, 'ከአንቀጽ ብንለውጥ ወይም እርሷን ብናስረሳህ ከርሷ የሚበልጥን ወይም ብጤዋን እናመጣለን፤ አላህ በነገሩ ሁሉ ላይ ከሃሊ (ቻይ) መኾኑን አታውቅምን?'),
('2:107', 87, 'አላህ የሰማያትና የምድር ንግሥና ለርሱ ብቻ መኾኑን አታውቅምን? ለእናንተም ከአላህ ሌላ ዘመድና ረዳት ምንም የላችሁም፡፡'),
('2:108', 87, 'በእውነቱ ከአሁን በፊት ሙሳ እንደተጠየቀ ብጤ መልክተኛችሁን ልትጠይቁ ትፈልጋላችሁን? በእምነትም ክህደትን የሚለውጥ ሰው ትክክለኛውን መንገድ በእርግጥ ተሳሳተ፡፡'),
('2:109', 87, 'ከመጽሐፉ ባለቤቶች ብዙዎች እውነቱ ከተገለጸላቸው በኋላ ከነፍሶቻቸው በኾነው ምቀኝነት ከእምነታችሁ በኋላ ከሓዲዎች አድርገው ሊመልሱዋችሁ ተመኙ፡፡ አላህም ትዕዛዙን እስከሚያመጣ ድረስ ይቅርታ አድርጉ፤ እለፏቸውም፡፡ አላህ በነገሩ ሁሉ ላይ ከሃሊ ነውና፡፡'),
('2:110', 87, 'ሶላትንም አስተካክላችሁ ስገዱ፡፡ ዘካንም ስጡ፡፡ ለነፍሶቻችሁም ከበጎ ሥራ የምታስቀድሙትን አላህ ዘንድ ታገኙታላችሁ፡፡ አላህ የምትሠሩትን ሁሉ ተመልካች ነውና፡፡'),
('2:111', 87, '«ገነትንም አይሁድን ወይም ክርስቲያኖችን የኾነ ሰው እንጂ ሌላ አይገባትም» አሉ፡፡ ይህቺ (ከንቱ) ምኞታቸው ናት፡፡ «እውነተኞች እንደኾናችሁ አስረጃችሁን አምጡ» በላቸው፡፡'),
('2:112', 87, 'አይደለም (ሌላውም ይገባታል) እርሱ በጎ ሠሪ ኾኖ ፊቱን ለአላህ የሰጠ ሰው ለርሱ በጌታው ዘንድ ምንዳው አለው፡፡ በነሱም ላይ ፍርሃት የለባቸውም፤ እነሱም አያዝኑም፡፡'),
('2:113', 87, 'እነርሱ መጽሐፉን የሚያነቡ ሲኾኑ አይሁዶች፡- ክርስቲያኖች በምንም ላይ አይደሉም አሉ፡፡ ክርስቲያኖችም፡- አይሁዶች በምንም ላይ አይደሉም አሉ፡፡ እንደዚሁ እነዚያ የማያውቁት (አጋሪዎች) የንግግራቸውን ብጤ አሉ፡፡ አላህም በዚያ በርሱ ይለያዩበት በነበሩት ነገር በትንሣኤ ቀን በመካከላቸው ይፈርዳል፡፡'),
('2:114', 87, 'የአላህንም መስጊዶች በውስጣቸው ስሙ እንዳይወሳ ከከለከለና እርሷንም በማበላሸት ከሮጠ ሰው ይበልጥ በዳይ ማነው? እነዚያ ፈሪዎች ኾነው እንጂ ለእነርሱ በቅርቢቱ ዓለም ውርደት አላቸው፡፡ ለነርሱም በመጨረሻይቱ አገር ታላቅ ቅጣት አላቸው፡፡'),
('2:115', 87, 'ምሥራቁም ምዕራቡም የአላህ ነው (ፊቶቻችሁን) ወደ የትም ብታዞሩ የአላህ ፊት እዚያ ነው፡፡ አላህ ችሮታው ሰፊ ዐዋቂ ነውና፡፡'),
('2:116', 87, 'አላህም ልጅ አለው አሉ፡፡ (ከሚሉት) ጥራት ተገባው፡፡ አይደለም በሰማያትና በምድር ያለው ሁሉ የርሱ ነው፡፡ ሁሉም ለርሱ ታዛዦች ናቸው፡፡'),
('2:117', 87, 'ሰማያትንና ምድርን ያለብጤ ፈጣሪ ነው፤ ነገርንም (ማስገኘት) በሻ ጊዜ ለርሱ የሚለው፡- «ኹን ነው፤» ወዲያውም ይኾናል፡፡'),
('2:118', 87, 'እነዚያም የማያውቁት (አንተ መልክተኛ ስለመኾንህ) አላህ አያናግረንም ኖሮአልን? ወይም (ለእውነተኛነትህ) ታምር አትመጣልንም ኖሮአልን? አሉ፡፡ እንደዚሁ እነዚያ ከነሱ በፊት የነበሩት እንደ ንግግራቸው ብጤ ብለዋል፡፡ ልቦቻቸው (በክሕደት) ተመሳሰሉ፡፡ ለሚያረጋግጡ ሕዝቦች አንቀጾችን በእርግጥ አብራርተናል፡፡'),
('2:119', 87, 'እኛ አብሳሪና አስፈራሪ ኾነህ በውነት ላክንህ፡፡ ከእሳትም ጓዶች አትጠየቅም፡፡'),
('2:120', 87, 'አይሁዶችና ክርስቲያኖችም ሃይማኖታቸውን እስከምትከተል ድረስ ካንተ ፈጽሞ አይወዱም፡፡ «የአላህ መምራት (ትክክለኛው) መምራት እርሱ ብቻ ነው» በላቸው፡፡ ከዚያም እውቀቱ ከመጣልህ በኋላ ዝንባሌያቸውን ብትከተል ለአንተ ከአላህ (የሚከለክልልህ) ዘመድና ረዳት ምንም የለህም፡፡'),
('2:121', 87, 'እነዚያ መጽሐፉን የሰጠናቸው ተገቢ ንባቡን ያነቡታል፡፡ እነዚያ በርሱ ያምናሉ፤ በርሱም የሚክዱ እነዚያ እነርሱ ከሳሪዎቹ ናቸው፡፡'),
('2:122', 87, 'የእስራኤል ልጆች ሆይ! ያችን በናንተ ላይ የለገስኳትን ጸጋዬንና እኔም በዓለማት ላይ ያበለጥኳችሁ መኾኔን አስታውሱ፡፡'),
('2:123', 87, '(አማኝ) ነፍስም ከ(ከሓዲ) ነፍስ ምንንም የማትጠቅምበትን፣ ከርሷም ቤዛ የማይወሰድበትን፣ ምልጃም ለርሷ የማትጠቅምበትን፣ እነርሱም የማይረዱበትን ቀን ተጠንቀቁ፡፡'),
('2:124', 87, 'ኢብራሂምንም ጌታው በቃላት (በሕግጋት) በፈተነውና በፈጸማቸው ጊዜ (አስታውስ)፤ «እኔ ለሰዎች መሪ አድራጊህ ነኝ» አለው፡፡ «ከዘሮቼም (አድርግ)» አለ፡፡ ቃል ኪዳኔ በዳዮቹን አያገኝም አለው፡፡'),
('2:125', 87, 'ቤቱንም ለሰዎች መመለሻና ጸጥተኛ ባደረግን ጊዜ (አስታውስ)፡፡ ከኢብራሂምም መቆሚያ መስገጃን አድርጉ፡፡ ወደ ኢብራሂምና ወደ ኢስማዒልም ቤቴን ለዘዋሪዎቹና ለተቀማጮቹም ለአጎንባሾች ሰጋጆቹም አጥሩ ስንል ቃል ኪዳን ያዝን፡፡'),
('2:126', 87, 'ኢብራሂም ባለ ጊዜ (አስታውስ)፡፡ ጌታዬ ሆይ! ይህንን ጸጥተኛ አገር አድርግ፡፡ ቤተሰቦቹንም ከነሱ በአላህና በመጨረሻው ቀን ያመነውን ሰው ከፍሬዎች ስጠው፡፡ (አላህም) የካደውንም ሰው፤ (እሰጠዋለሁ)፡፡ ጥቂትም እጠቅመዋለሁ፤ ከዚያም ወደ እሳት ቅጣት አስጠጋዋለሁ፤ ምን ትከፋም መመለሻ! (አለ)፡፡'),
('2:127', 87, 'ኢብራሂምና ኢስማኢልም «ጌታችን ሆይ! ከእኛ ተቀበል፡፡ አንተ ሰሚውና ዐዋቂው አንተ ነህና» የሚሉ ሲኾኑ ከቤቱ መሠረቶቹን ከፍ ባደረጉ ጊዜ (አስታውስ)፡፡'),
('2:128', 87, '«ጌታችን ሆይ! ላነተ ታዛዦችም አድርገን፡፡ ከዘሮቻችንም ላንተ ታዛዦች ሕዝቦችን (አድርግ)፡፡ ሕግጋታችንንም አሳየን፤ (አሳውቀን)፡፡ በኛም ላይ ተመለስን፤ አንተ ጸጸትን ተቀባዩ ሩኅሩኅ አንተ ብቻ ነህና፡፡»'),
('2:129', 87, '«ጌታችን ሆይ! በውስጣቸውም ከነሱው የኾነን መልክተኛ በነርሱ ላይ አንቀጾችህን የሚያነብላቸውን መጽሐፍንና ጥበብንም የሚያስተምራቸውን (ከክህደት) የሚያጠራቸውንም ላክ፤ አንተ አሸናፊው ጥበበኛው አንተ ብቻ ነህና» (የሚሉም ሲኾኑ)፡፡'),
('2:130', 87, 'ከኢብራሂምም ሕግጋት ነፍሱን ያቄለ ሰው ካልኾነ በስተቀር የሚያፈገፍግ ማነው? (የለም)፤ በቅርቢቱም ዓለም በእርግጥ መረጥነው፡፡ በመጨረሻይቱም ዓለም እርሱ ከመልካሞቹ ነው፡፡'),
('2:131', 87, 'ጌታው ለርሱ ታዘዝ ባለው ጊዜ (መረጠው)፡፡ ለዓለማት ጌታ ታዘዝኩ አለ፡፡'),
('2:132', 87, 'በርሷም (በሕግጋቲቱ) ኢብራሂም ልጆቹን አዘዘ፡፡ ያዕቁብም (እንደዚሁ ልጆቹን አዘዘ)፡፡ «ልጆቼ ሆይ! አላህ ለናንተ ሃይማኖትን መረጠ፤ ስለዚህ እናንተ ሙስሊሞች ኾናችሁ እንጂ አትሙቱ» (አላቸው)፡፡'),
('2:133', 87, 'ያዕቁብን ሞት በመጣበት ጊዜ ለልጆቹ ከኔ በኋላ ማንን ትገዛላችሁ ባለ ጊዜ ቀራቢዎች ነበራችሁን? (እነርሱም) አምላክህንና የአባቶችህን የኢብራሂምን የኢስማዒልንና የኢስሐቅንም አምላክ አንድ የኾነውን አምላክ እኛ ለርሱ ፍፁም ታዛዦች ኾነን እናመልካለን አሉ፡፡'),
('2:134', 87, 'ይህች (የተወሳችው) በእርግጥ ያለፈች ሕዝብ ናት፡፡ ለርሷ የሠራችው (ምንዳ) አላት፡፡ ለናንተም የሠራችሁት (ምንዳ) አላችሁ፡፡ ይሠሩትም ከነበሩት አትጠየቁም፡፡'),
('2:135', 87, '«አይሁድን ወይም ክርስቲያኖችን ኹኑ፤ (ቅኑን መንገድ) ትመራላችሁና» አሉም፡፡ «አይደለም የኢብራሂምን ሃይማኖት ቀጥተኛ ሲኾን እንከተላለን፤ ከአጋሪዎችም አልነበረም» በላቸው፡፡'),
('2:136', 87, '«በአላህና ወደኛ በተወረደው (ቁርኣን) ወደ ኢብራሂምም ወደ ኢስማዒልና ወደ ኢስሐቅም ወደ ያዕቁብና ወደ ነገዶቹም በተወረደው በዚያም ሙሳና ዒሳ በተሰጡት በዚያም ነቢያት ሁሉ ከጌታቸው በተሰጡት ከነርሱ በአንድም መካከል የማንለይ ስንኾን አመንን፤ እኛም ለርሱ (ለአላህ) ታዛዦች ነን» በሉ፡፡'),
('2:137', 87, 'በርሱ ባመናችሁበት ብጤ ቢያምኑ በእርግጥ ተመሩ፡፡ ቢዞሩም እነርሱ በጭቅጭቅ ውስጥ ብቻ ናቸው፡፡ እነርሱንም አላህ ይበቃሃል፤ እርሱም ሰሚው ዐዋቂው ነው፡፡'),
('2:138', 87, 'የአላህን (የተፈጥሮ) መንክር (እምነት) ያዙ፡፡ በመንከርም ከአላህ ይበልጥ ያማረ ማነው? (ማንም የለም) እኛም ለርሱ ብቻ ተገዢዎች ነን (በሉ)፡፡'),
('2:139', 87, 'እርሱ (አላህ) ጌታችንና ጌታችሁ ሲኾን ለኛም ሥራችን ያለን ስንኾን ለናንተም ሥራችሁ ያላችሁ ስትኾኑ እኛም ለርሱ ፍጹም ታዛዦች ስንኾን በአላህ (ሃይማኖት) ትከራከሩናላችሁን? በላቸው፡፡'),
('2:140', 87, 'ወይም ኢብራሂም ኢስማዒልም ኢስሐቅም ያዕቁብም ነገዶቹም አይሁዶች ወይም ክርስቲያኖች ነበሩ ትላላችሁን? «እናንተ ታውቃላችሁን? ወይንስ አላህ?» በላቸው፡፡ እርሱም ዘንድ ከአላህ የኾነችን ምስክርነት ከደበቀ ሰው ይበልጥ በዳይ ማነው? አላህም ከምትሠሩት ሁሉ ዘንጊ አይደለም፡፡'),
('2:141', 87, 'ይህቺ በእርግጥ ያለፈች ሕዝብ ናት፤ ለእርሷ የሠራችው አላት፤ ለናንተም የሠራችሁት አላችሁ፤ ይሠሩትም ከነበሩት አትጠየቁም፡፡'),
('2:142', 87, 'ከሰዎቹ ቂሎቹ «ከዚያች በርሷ ላይ ከነበሩባት ቂብላቸው ምን አዞራቸው?» ይላሉ፤ «ምሥራቁም ምዕራቡም የአላህ ነው፤ የሻውን ሰው ወደ ቀጥተኛው መንገድ ይመራል» በላቸው፡፡'),
('2:143', 87, 'እንደዚሁም (እንደመራናችሁ) በሰዎች ላይ መስካሪዎች ልትሆኑና መልክተኛውም በናንተ ላይ መስካሪ ይሆን ዘንድ ምርጥ ሕዝቦች አደረግናችሁ፡፡ ያችንም በርሷ ላይ የነበርክባትን አቅጣጫ መልክተኛውን የሚከተለውን ሰው ወደ ክህደት ከሚመለሰው ሰው ልናውቅ (ልንገልጽ) እንጅ ቂብላ አላደረግናትም፡፡ እርሷም በነዚያ አላህ በመራቸው ሰዎች ላይ በስተቀር በእርግጥ ከባድ ናት፡፡ አላህም እምነታችሁን (ስግደታችሁን) የሚያጠፋ አይደለም፤ አላህ ለሰዎች በጣም ርኅሩኅ አዛኝ ነውና፡፡'),
('2:144', 87, 'የፊትህን ወደ ሰማይ መገላበጥ በእርግጥ እናያለን፡፡ ወደምትወዳትም ቂብላ እናዞርሃለን፡፡ ስለዚህ ፊትህን ወደ ተከበረው መስጊድ (ወደ ካዕባ) አግጣጫ አዙር፡፡ የትም ስፍራ ብትኾኑም (ስትሰግዱ) ፊቶቻችሁን ወደርሱ አግጣጫ አዙሩ፡፡ እነዚያም መጽሐፉን የተሰጡት እርሱ ከጌታቸው ሲኾን እውነት መሆኑን ያውቃሉ፡፡ አላህም ከምትሠሩት ሥራ ዘንጊ አይደለም፡፡'),
('2:145', 87, 'እነዚያንም መጽሐፍን የተሰጡትን በአስረጅ ሁሉ ብትመጣቸው ቂብላህን አይከተሉም፡፡ አንተም ቂብላቸውን ተከታይ አይደለህም፡፡ ከፊላቸውም የከፊሉን ቂብላ ተከታይ አይደሉም፡፡ ከዕውቀትም (ከራዕይ) ከመጣልህ በኋላ ዝንባሌያቸውን ብትከተል አንተ ያን ጊዜ ከበዳዮች ነህ፡፡'),
('2:146', 87, 'እነዚያ መጽሐፍን የሰጠናቸው ወንዶች ልጆቻቸውን እንደሚያውቁ (ሙሐመድን) ያውቁታል፡፡ ከነሱም የተለዩ ክፍሎች እነርሱ የሚያወቁ ሲኾኑ እውነቱን በእርግጥ ይደብቃሉ፡፡'),
('2:147', 87, '(ይህ) ከጌታህ የኾነ እውነት ነው፤ ከተጠራጣሪዎቹም አትሁን፡፡'),
('2:148', 87, 'ለሁሉም እርሱ (በስግደት ፊቱን) የሚያዞርባት አግጣጫ አለችው፡፡ ወደ መልካም ሥራዎችም ተሽቀዳደሙ፡፡ የትም ስፍራ ብትኾኑ አላህ እናንተን የተሰበሰባችሁ ኾናችሁ ያመጣችኋል፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('2:149', 87, 'ከየትም (ለጉዞ) ከወጣህበት ስፍራ ፊትሀን ወደ ተከበረው መስጊድ አግጣጫ አዙር፡፡ እርሱም ከጌታህ የኾነ እርግጠኛ እውነት ነው፡፡ አላህም ከምትሠሩት ሥራ ዘንጊ አይደለም፡፡'),
('2:150', 87, 'ከየትም ከወጣህበት ስፍራ ፊትህን ወደ ተከለለው መስጊድ አግጣጫ አዙር፡፡ በየትም ስፍራ ብትኾኑ ለሰዎቹ እነዚያ ከነሱ የበደሉት ሲቀሩ (ሃይማኖታችንን ይክዳሉ ቂብላችንን ይከተላሉ በማለት) በናንተ ላይ መከራከሪያ እንዳይኖራቸው ፊቶቻችሁን ወደ አግጣጫው አዙሩ፡፡ አትፍሩዋቸውም፤ ፍሩኝም፤ (በዚህም ያዘዝኳችሁ መከራከሪያ እንዳይኖራቸው) በናንተም ላይ ጸጋየን እንድሞላላችሁና (ወደ እውነትም) እንድትመሩ ነው፡፡'),
('2:151', 87, 'በውስጣችሁ ከናንተው የኾነን በናንተ ላይ አንቀጾቻችንን የሚያነብላችሁና የሚያጠራችሁ፣ መጽሐፍንና ጥበብንም የሚያስተምራችሁ፣ ታውቁት ያልነበራችሁትንም ነገር የሚያሳውቃችሁ የኾነን መልክተኛ እንደላክን (ጸጋን ሞላንላችሁ)፡፡'),
('2:152', 87, 'አስታውሱኝም፤ አስታውሳችኋለሁና ለኔም አመስግኑ፤ አትካዱኝም፡፡'),
('2:153', 87, 'እናንተ ያመናችሁ ሆይ! በመታገስና በሶላት ተረዱ፡፡ አላህ (በእርዳታው) ከታጋሾች ጋር ነውና፡፡'),
('2:154', 87, 'በአላህ መንገድ (ለሃይማኖቱ) የሚገደሉትን ሰዎችም «ሙታን ናቸው» አትበሉ፡፡ በእውነቱ ሕያዋን ናቸው፤ ግን አታውቁም፡፡'),
('2:155', 87, 'ከፍርሃትና ከረኃብም በጥቂት ነገር፣ ከገንዘቦችና ከነፍሶችም፣ ከፍራፍሬዎችም በመቀነስ በእርግጥ እንሞክራችኋለን፡፡ ታጋሾችንም (በገነት) አብስር፡፡'),
('2:156', 87, 'እነዚያን መከራ፤ በነካቻቸው ጊዜ «እኛ ለአላህ፤ ነን እኛም ወደርሱ ተመላሾች» ነን የሚሉትን (አብስር)፡፡'),
('2:157', 87, 'እነዚያ በእነርሱ ላይ ከጌታቸው የኾኑ ምሕረቶች ችሮታም አልሉ፡፡ እነርሱም (ወደ እውነት) ተመሪዎቹ እነርሱ ናቸው፡፡'),
('2:158', 87, 'ሶፋና መርዋ ከአላህ (ትዕዛዝ መፈጸሚያ) ምልክቶች ናቸው፡፡ ቤቱን (ካዕባን) በሐጅ ወይም በዑምራህ ሥራ የጎበኘ ሰው በሁለቱ (መካከል) በመመላለሱ በርሱ ላይ ኃጢአት የለበትም፡፡ መልካምንም ሥራ በፈቃደኛነት የሠራ ሰው (አላህ ይመነዳዋል)፤ አላህ አመስጋኝ ዐዋቂ ነውና፡፡'),
('2:159', 87, 'እነዚያ ከአንቀጾችና ከቅን መምሪያ ያወረድነውን ለሰዎች በመጽሐፉ ከገለጽነው በኋላ የሚደብቁ፤ እነዚያ አላህ ይረግማቸዋል፤ ረጋሚዎችም ሁሉ ይረግሟቸዋል፡፡'),
('2:160', 87, 'እነዚያ (ከመደበቅ) የተጸጸቱና (ሥራቸውን) ያሳመሩም (የደበቁትን) የገለጹም ብቻ ሲቀሩ፡፡ እነዚህም በነሱ ላይ (ጸጸታቸውን) እቀበላለሁ፤ እኔም ጸጸትን በጣም ተቀባይ አዛኙ ነኝ፡፡'),
('2:161', 87, 'እነዚያ የካዱ እነርሱ ከሐዲዎች ኾነውም የሞቱ እነዚያ በነርሱ ላይ የአላህና የመላእክት የሰዎችም ሁሉ እርግማን አለባቸው፡፡'),
('2:162', 87, 'በውስጧ (በርግማንዋ ውስጥ) ሁልጊዜ ዘውታሪዎች ሲኾኑ ቅጣቱ ከነሱ አይቀለልም እነርሱም አይቅቆዩም (ጊዜ አይስሰጡም)፡፡'),
('2:163', 87, 'አምላካችሁም አንድ አምላክ ብቻ ነው፤ ከርሱ በቀር ሌላ አምላክ የለም፡፡ (እርሱ) እጅግ በጣም ርኅሩህ አዛኝ ነው፡፡'),
('2:164', 87, 'ሰማያትንና ምድርን በመፍጠር ሌሊትንና ቀንንም በማተካካት፣ በዚያቸም ሰዎችን በሚጠቅም ነገር (ተጭና) በባህር ላይ በምትንሻለለው ታንኳ፣ አላህም ከሰማይ ባወረደው ውሃና በርሱም ምድርን ከሞተች በኋላ ሕያው በማድረጉ፣ በርሷም ውስጥ ከተንቀሳቃሽ ሁሉ በመበተኑ፣ ነፋሶችንም (በየአግጣጫው) በማገለባበጥ፣ በሰማይና በምድር መካከል በሚነዳውም ደመና ለሚያውቁ ሕዝቦች እርግጠኛ ምልክቶች አሉ፡፡'),
('2:165', 87, 'ከሰዎችም ከአላህ ሌላ ባለንጣዎችን (ጣዖታትን) አላህን እንደሚወዱ የሚወዷቸው ኾነው የሚይዙ አልሉ፡፡ እነዚያ ያመኑትም አላህን በመውደድ (ከነርሱ) ይበልጥ የበረቱ ናቸው፡፡ እነዚያም የበደሉት ሰዎች ቅጣትን (በትንሣኤ ቀን) ባዩ ጊዜ ኀይል ሁሉ ለአላህ ብቻ መኾኑንና አላህም ቅጣቱ ብርቱ መኾኑን (በአዱኛ ዓለም) ቢያውቁ ኖሮ (ባላንጣዎችን በመያዛቸው በተጸጸቱ ነበር)፡፡'),
('2:166', 87, 'እነዚያ አስከታዮቹ ቅጣትን ያዩ ሲኾኑ ከእነዚያ ከተከታዮች በተጥራሩና በእነርሱም (መካከል) ምክንያቶች በተቆረጡ ጊዜ (የሚኾኑትን ባወቁ ኖሮ በተጸጸቱ ነበር)፡፡'),
('2:167', 87, 'እነዚያም የተከተሉት «ለእኛ (ወደ ቅርቢቱ ዓለም) አንዲት ጊዜ መመለስ በኖረችንና ከእኛ እንደተጥራሩ ከእነርሱ በተጥራራን እንመኛለን» ይላሉ፡፡ እንደዚሁ አላህ ሥራዎቻቸውን በነርሱ ላይ ጸጸቶች አድርጎ ያሳያቸዋል፡፡ እነርሱም ከእሳት ወጪዎች አይደሉም፡፡'),
('2:168', 87, 'እናንተ ሰዎች ሆይ! በምድር ካለው ነገር የተፈቀደ ጣፋጭ ሲኾን ብሉ፡፡ የሰይጣንንም እርምጃዎች አትከታተሉ፡፡ እርሱ ለእናንተ ግልጽ ጠላት ነውና፡፡'),
('2:169', 87, '(እርሱ) የሚያዛችሁ በኃጢኣትና በጸያፍ ነገር በአላህም ላይ የማታውቁትን እንድትናገሩ ብቻ ነው፡፡'),
('2:170', 87, 'ለእነርሱም «አላህ ያወረደውን ተከተሉ» በተባሉ ጊዜ «አይደለም አባቶቻችንን በርሱ ላይ ያገኘንበትን ነገር እንከተላለን» ይላሉ፡፡ አባቶቻቸው ምንም የማያውቁና (ወደ እውነት) የማይመሩም ቢኾኑ (ይከተሉዋቸዋልን?)'),
('2:171', 87, 'የነዚያም የካዱት (እና ወደ ቅን መንገድ የሚጠራቸው ሰው) ምሳሌ እንደዚያ ድምጽንና ጥሪን በስተቀር ሌላን በማይሰማ (እንስሳ) ላይ እንደሚጮህ ብጤ ነው፡፡ (እነርሱ) ደንቆሮዎች፣ ዲዳዎች፣ ዕውሮች ናቸው፤ ስለዚህ እነርሱ አያውቁም፡፡'),
('2:172', 87, 'እናንተ ያመናችሁ ሆይ! ከነዚያ ከሰጠናችሁ ጣፋጮች ብሉ፡፡ ለአላህም እርሱን ብቻ የምትገዙ እንደኾናችሁ አመስግኑ፡፡'),
('2:173', 87, 'በናንተ ላይ እርም ያደረገው በክትንና ደምን፣ የእሪያ ሥጋንም፣ በእርሱም (ማረድ) ከአላህ ስም ሌላ የተነሳበትን ነገር ብቻ ነው፡፡ ሽፍታና ወሰን አላፊ ሳይኾን (ለመብላት) የተገደደ ሰውም በርሱ ላይ ኃጢኣት የለበትም አላህ መሓሪ አዛኝ ነውና፡፡'),
('2:174', 87, 'እነዚያ አላህ ከመጽሐፍ ያወረደውን የሚደብቁ በርሱም (በመደበቃቸው) ጥቂትን ዋጋ የሚገዙ እነዚያ በሆዶቻቸው ውስጥ እሳትን እንጂ አይበሉም፡፡ አላህም በትንሣኤ ቀን አያናግራቸውም፤ (ከኃጢኣት) አያጠራቸውምም፡፡ ለነርሱም አሳማሚ ቅጣት አላቸው፡፡'),
('2:175', 87, 'እነዚያ ጥመትን በቅንነት ቅጣትንም በምሕረት የገዙ ናቸው፡፡ በእሳት ላይም ምን ታጋሽ አደረጋቸው!'),
('2:176', 87, 'ይህ (ቅጣት) አላህ መጽሐፍን በእውነት ያወረደ በመኾኑ ምክንያት (እና በርሱ በመካዳቸው) ነው፡፡ እነዚያም በመጽሐፉ የተለያዩት (ከእውነት) በራቀ ጭቅጭቅ ውስጥ ናቸው፡፡'),
('2:177', 87, 'መልካም ሥራ ፊቶቻችሁን ወደ ምሥራቅና ምዕራብ አቅጣጫ ማዞር አይደለም፡፡ ግን መልካም ሥራ በአላህና በመጨረሻው ቀን፣ በመላእክትም፣ በመጻሕፍትም፣ በነቢያትም፣ ያመነ ሰው ገንዘብንም ከመውደዱ ጋር ለዝምድና ባለቤቶችና ለየቲሞች ለምስኪኖችም፣ ለመንገደኞችም፣ ለለማኞችም፣ ለጫንቃዎችም (ማስለቀቅ) የሰጠ ሰውና ሶላትንም ደንቡን ጠብቆ የሰገደ፣ ዘካንም የሰጠ፣ ቃል ኪዳንም በገቡ ጊዜ በኪዳናቸው የሞሉ (ሰዎች ሥራ) ነው፡፡ በችግር በበሽታና በጦር ጊዜም ታጋሾችን (እናወድሳለን)፡፡ እነዚህ እነዚያ እውነትን የያዙ ናቸው፡፡ እነዚያም ተጠንቃቂዎቹ እነርሱ ናቸው፡፡'),
('2:178', 87, 'እናንተ ያመናችሁ ሆይ! በተገደሉ ሰዎች ማመሳሰል በናንተ ላይ ተጻፈ፡፡ ነጻ በነጻ ባሪያም በባሪያ ሴትም በሴት (ይገደላሉ)፡፡ ለእርሱም (ለገዳዩ) ከወንድሙ (ደም) ትንሽ ነገር ምሕረት የተደረገለት ሰው (በመሓሪው ላይ ጉማውን) በመልካም መከታተል ወደርሱም (ወደ መሓሪው) ገዳዩ በመልካም አኳኋን መክፈል አለባቸው፡፡ ይህ ከጌታችሁ የኾነ ማቃለልና እዝነት ነው፡፡ ከዚህም በኋላ ሕግን የተላለፈ ሰው ለርሱ አሳማሚ ቅጣት አለው፡፡'),
('2:179', 87, 'ለእናንተም ባለ አእምሮዎች ሆይ! በማመሳሰል (ሕግ) ውስጥ ሕይወት አላችሁ፡፡ ትጠነቀቁ ዘንድ (ገዳይን መግደል ተደነገገላችሁ)፡፡'),
('2:180', 87, 'አንዳችሁን ሞት በመጣበት ጊዜ ሀብትን ቢተው ለወላጆችና ለቅርብ ዘመዶች በበጎ መናዘዝ በናንተ ላይ ተጻፈ፡፡ (ይህ) በጥንቁቆቹ ላይ እርግጠኛ ድንጋጌ ተደነገገ፡፡'),
('2:181', 87, '(ኑዛዜውን) ከሰማውም በኋላ የለወጠው ሰው ኃጢአቱ በነዚያ በሚለውጡት ላይ ብቻ ነው፡፡ አላህ ሰሚ ዐዋቂ ነውና፡፡'),
('2:182', 87, 'ከተናዛዢም በኩል (ከውነት) መዘንበልን ወይም (ከሢሶ በመጨመር) ኃጢኣትን ያወቀና በመካከላቸው ያስታረቀ ሰው በእርሱ ላይ ኃጢኣት የለበትም፡፡ አላህ በጣም መሓሪ አዛኝ ነውና፡፡'),
('2:183', 87, 'እናንተ ያመናችሁ ሆይ ጾም በነዚያ ከናንተ በፊት በነበሩት (ሕዝቦች) ላይ እንደ ተጻፈ በናንተም ላይ ተጻፈ (ተደነባ) ልትጠነቀቁ ይከጀላልና፡፡'),
('2:184', 87, 'የተቆጠሩን ቀኖች (ጹሙ)፡፡ ከእናንተም ውሰጥ በሽተኛ ወይም በጉዞ ላይ የኾነ ሰው ከሌሎች ቀኖች ቁጥሮችን መጾም አለበት፡፡ በእነዚያም ጾምን በማይችሉት ላይ ቤዛ ድኻን ማብላት አለባቸው፡፡ (ቤዛን በመጨመር) መልካምንም ሥራ የፈቀደ ሰው እርሱ (ፈቅዶ መጨመሩ) ለርሱ በላጭ ነው፡፡ መጾማችሁም ለናንተ የበለጠ ነው፤ የምታውቁ ብትኾኑ (ትመርጡታላችሁ)፡፡'),
('2:185', 87, '(እንድትጾሙ የተጻፈባችሁ) ያ በርሱ ውስጥ ለሰዎች መሪ ከቅን መንገድና (እውነትን ከውሸት) ከሚለዩም ገላጮች (አንቀጾች) ሲኾን ቁርኣን የተወረደበት የረመዳን ወር ነው፡፡ ከእናንተም ወሩን ያገኘ ሰው ይጹመው፡፡ በሽተኛ ወይም በጉዞ ላይ የኾነም ሰው ከሌሎች ቀኖች ቁጥሮችን (በልኩ) መጾም አለበት፡፡ አላህ በእናንተ ገሩን (ነገር) ይሻል፡፡ በእናንተም ችግሩን አይሻም፡፡ ቁጥሮችንም ልትሞሉ አላህንም ቅኑን መንገድ ስለመራችሁ ታከብሩትና ታመሰግኑት ዘንድ (ይህን ደነገግንላችሁ)፡፡'),
('2:186', 87, 'ባሮቼም ከእኔ በጠየቁህ ጊዜ (እንዲህ በላቸው)፡- እኔ ቅርብ ነኝ፡፡ የለማኝን ጸሎት በለመነኝ ጊዜ እቀበለዋለሁ፡፡ ስለዚህ ለኔ ይታዘዙ፤ በኔም ይመኑ፤ እነሱ ሊመሩ ይከጀላልና፡፡'),
('2:187', 87, 'በጾም ሌሊት ወደ ሴቶቻችሁ መድረስ ለናንተ ተፈቀደላችሁ፡፡ እነርሱ ለናንተ ልብሶች ናቸው፤ እናንተም ለነርሱ ልብሶች ናችሁ፡፡ አላህ እናንተ ነፍሶቻችሁን የምትበድሉ መኾናችሁን ዐወቀ፡፡ በእናንተም ላይ ተመለሰላችሁ፡፡ ከእናንተም ይቅርታ አደረገ፡፡ አሁን ተገናኙዋቸው፡፡ አላህም ለናንተ የጻፈላችሁን ነገር (ልጅን) ፈልጉ፡፡ ከጎህ የኾነው ነጩ ክርም ከጥቁሩ ክር (ከሌሊት ጨለማ) ለእናንተ እስከሚገልጽላችሁ ድረስ ብሉ፤ ጠጡም፡፡ ከዚያም ጾምን እስከ ሌሊቱ ድረስ ሙሉ፡፡ እናንተም በመስጊዶች ተቀማጮች ስትኾኑ አትገናኙዋቸው፡፡ ይህች የአላህ ሕግጋት ናትና (ለመተላለፍ) አትቅረቧት፡፡ እንደዚሁ አላህ አንቀጾቹን ለሰዎች ያብራራል፡፡ እነርሱ (የተከለከሉትን) ሊጠነቀቁ ይከጀላልና፡፡'),
('2:188', 87, 'ገንዘቦቻችሁንም በመካከላችሁ በከንቱ (ያለ አግባብ) አትብሉ፡፡ እናንተም የምታውቁ ስትኾኑ ከሰዎች ገንዘቦች ከፊልን በኃጢኣት ትበሉ ዘንድ ወደ ዳኞች አትጣሏት፡፡'),
('2:189', 87, '(ሙሐመድ ሆይ!) ከለጋ ጨረቃዎች (መለዋወጥ) ይጠየቁሃል፡፡ እነርሱ ለሰዎች ጥቅም ለሐጅም (ማወቂያ) ጊዜያቶች (ምልክቶች) ናቸው በላቸው፡፡ መልካም ሥራም ቤቶችን ከጀርባዎቻቸው በመምጣታችሁ አይደለም፡፡ ግን የመልካም ሥራ ባለቤት የተጠነቀቀ ሰው ነው፡፡ ቤቶችንም ከደጃፎቻቸው በኩል ግቡ፤ አላህንም ፍሩ ልትድኑ ይከጀላልና (በላቸው)፡፡'),
('2:190', 87, 'እነዚያንም የሚጋደሉዋችሁን (ከሓዲዎች) በአላህ መንገድ ተጋደሉ፡፡ ወሰንንም አትለፉ፤ አላህ ወሰን አላፊዎን አይወድምና፡፡'),
('2:191', 87, 'ባገኛችኋቸውም ስፍራ ሁሉ ግደሉዋቸው፡፡ ከአወጧችሁም ስፍራ አውጧቸው፡፡ መከራም ከመግደል ይበልጥ የበረታች ናት፡፡ በተከበረው መስጊድም ዘንድ በርሱ ውስጥ እስከሚጋደሉዋችሁ ድረስ አትጋደሉዋቸው፡፡ ቢጋደሉዋችሁም ግደሉዋቸው፤ የከሓዲዎች ቅጣት እንደዚህ ነው፡፡'),
('2:192', 87, 'ቢከለከሉም አላህ መሓሪ አዛኝ ነው፡፡'),
('2:193', 87, 'ሁከት እስከማይገኝና ሃይማኖት ለአላህ ብቻ እስከሚኾን ድረስ ተጋደሉዋቸው፡፡ ቢከለክሉም ወሰንን ማለፍ፤ በበዳዮች ላይ እንጂ የለም (ወሰን አትለፉባቸው)፡፡'),
('2:194', 87, 'የተከበረው ወር በተከበረው ወር አንጻር ነው፡፡ ክብሮችም ሁሉ ተመሳሳዮች ናቸው፡፡ በእናንተም ላይ (በተከበረው ወር) ወሰን ያለፈባችሁን ሰው በናንተ ላይ ወሰን ባለፈው ብጤ በርሱ ላይ ወሰን እለፉበት፡፡ አላህንም ፍሩ አላህ ከሚፈሩት ጋር መኾኑንም ዕወቁ፡፡'),
('2:195', 87, 'በአላህም መንገድ ለግሱ፡፡ በእጆቻችሁም (ነፍሶቻችሁን) ወደ ጥፋት አትጣሉ፡፡ በጎ ሥራንም ሥሩ፤ አላህ በጎ ሠሪዎችን ይወዳልና፡፡'),
('2:196', 87, 'ሐጅንና ዑምራንም ለአላህ ሙሉ፡፡ ብትታገዱም ከሀድይ (ከመሥዋእት) የተገራውን (መሰዋት) አለባችሁ፡፡ ሀድዩም እስፍራው እስከሚደርስ ድረስ ራሶቻችሁን አትላጩ፡፡ ከናንተም ውስጥ በሽተኛ ወይም በራሱ ሁከት ያለበት የኾነ ሰው (ቢላጭ) ከጾም ወይም ከምጽዋት ወይም ከመሥዋዕት ቤዛ አለበት፡፡ ጸጥታም ባገኛችሁ ጊዜ እስከ ሐጅ በዑምራ የተጣቀመ ሰው ከሀድይ የተገራውን (መሠዋት) አለበት፡፡ ያላገኘም ሰው ሶስትን ቀኖች በሐጅ ወራት፤ ሰባትም በተመለሳችሁ ጊዜ መጾም አለበት፡፡ ይህች ሙሉ ዐሥር (ቀናት) ናት፡፡ ይህም (ሕግ) ቤተሰቦቹ ከቅዱሱ መስጊድ አቅራቢያ ላልኾኑ ነው፡፡ አላህንም ፍሩ፤ አላህም ቅጣተ ብርቱ መኾኑን እወቁ፡፡'),
('2:197', 87, 'ሐጅ (ጊዜያቱ) የታወቁ ወሮች ናቸው፡፡ በእነርሱም ውስጥ ሐጅን (እንዲሠራ) ነፍሱን ያስገደደ ሰው በሐጅ ውስጥ ሴትን መገናኘት ማመጽም ክርክርም የለም፡፡ ከበጎም ሥራ የምትሠሩትን ሁሉ አላህ ያውቀዋል፡፡ ተሰነቁም፤ ከስንቅም ሁሉ በላጩ ጥንቃቄ (አላህን መፍራት) ነው፡፡ የአእምሮዎችም ባለቤቶች ሆይ! ፍሩኝ፡፡'),
('2:198', 87, '(በሐጅ ጊዜ በንግድ ሥራ) ከጌታችሁ ትርፍን በመፈለጋችሁ በናንተ ላይ ኃጢኣት የለባችሁም፡፡ ከዐረፋትም በጎረፋችሁ ጊዜ መሸዐረልሐራም ዘንድ አላህን አውሱ፡፡ (ለሐጅ) ስለመራችሁም አውሱት፡፡ ከመምራቱ በፊትም በእርግጥ ከተሳሳቾች ነበራችሁ፡፡'),
('2:199', 87, 'ከዚያም (ቁረይሾች ሆይ!) ሰዎቹ ከጎረፉበት ስፍራ ጉረፉ፤ (ተመለሱ)፡፡ አላህንም ምሕረትን ለምኑ፤ አላህ እጅግ መሓሪ አዛኝ ነውና፡፡'),
('2:200', 87, 'የሐጅ ሥራዎቻችሁንም በፈጸማችሁ ጊዜ አባቶቻችሁን እንደምታወሱ ወይም ይበልጥ የበረታን ማውሳት አላህን አውሱ፡፡ ከሰዎችም ውስጥ፡- «ጌታችን ሆይ! በምድረዓለም መልካም ዕድልን ስጠን» የሚል ሰው አለ፡፡ ለርሱም በመጨረሻይቱ አገር ከዕድል ምንም የለውም፡፡'),
('2:201', 87, 'ከእነርሱም ውስጥ፡- «ጌታችን ሆይ! በምድረ ዓለም ደግን ነገር (ጸጋን) በመጨረሻይቱም አገር ደግን ነገር (ገነትን) ስጠን፤ የእሳትንም ቅጣት ጠብቀን» የሚሉ ሰዎች አልሉ፡፡'),
('2:202', 87, 'እነዚያከሠሩት በጎ ሥራ ለነርሱ እድል አላቸው፡፡ አላህም ምርመራው ፈጣን ነው፡፡'),
('2:203', 87, 'በተቆጠሩ ቀኖችም ውስጥ (በሚና ጠጠሮችን ስትወረውሩ) አላህን አውሱ፡፡ በሁለት ቀኖችም ውስጥ (በመኼድ) የተቻኮለ ሰው በርሱ ላይ ኃጢኣት የለበትም፡፡ የቆየም ሰው በርሱ ላይ ኃጢኣት የለበትም፡፡ (ይህም) አላህን ለፈራ ሰው ነው፡፡ አላህንም ፍሩ፡፡ እናንተ ወደርሱ የምትሰበሰቡ መኾናችሁንም ዕወቁ፡፡'),
('2:204', 87, 'ከሰዎችም ውስጥ እርሱ ክርክረ ብርቱ ሲኾን በቅርቢቱ ሕይወት ንግግሩ የሚደንቅህና በልቡ ውስጥ ባለው ነገር ላይ አላህን የሚያስመሰክር ሰው አልለ፡፡'),
('2:205', 87, '(ካንተ) በዞረም ጊዜ በምድር ላይ በውስጧ ሊያበላሽና አዝመራንና እንስሳዎችን ሊያጠፋ ይሮጣል፡፡ አላህም ማበላሸትን አይወድም፡፡'),
('2:206', 87, 'ለእርሱ «አላህን ፍራ» በተባለም ጊዜ፤ ትዕቢቱ በኃጢኣት (ሥራ) ላይ ትገፈፋዋለች፡፡ ገሀነምም በቂው ናት፤ (እርሷም) በእርግጥ የከፋች ምንጣፍ ናት፡፡'),
('2:207', 87, 'ከሰዎችም ውስጥ የአላህን ውዴታ ለመፈለግ ነፍሱን የሚሸጥ ሰው አልለ፡፡ አላህም ለባሮቹ በጣም ርኅሩህ ነው፡፡'),
('2:208', 87, 'እናንተ ያመናችሁ ሆይ! ሁላችሁም በመታዘዝ ውስጥ ግቡ፡፡ የሰይጣንንም እርምጃዎች አትከተሉ፤ እርሱ ለእናንተ ግልጽ ጠላት ነውና፡፡'),
('2:209', 87, 'ግልጽ ማስረጃዎችም ከመጡላችሁ በኋላ ብትዘነበሉ አላህ አሸናፊ ጥበበኛ መኾኑን እወቁ፡፡'),
('2:210', 87, 'አላህ (ቅጣቱ)ና መላእክቱ ከደመና በኾኑ ጥላዎች ውስጥ ሊመጡዋቸው እንጂ አይጠባበቁም፡፡ ነገሩም ተፈጸመ፤ ነገሮችም ሁሉ ወደ አላህ ይመለሳሉ፡፡'),
('2:211', 87, 'የእስራኤልን ልጆች ከግልጽ ተዓምር ስንትን እደሰጠናቸው ጠይቃቸው፡፡ የአላህንም ጸጋ ከመጣችለት በኋላ የሚለውጥ ሰው አላህ ቅጣተ ብርቱ ነው፡፡'),
('2:212', 87, 'ለእነዚያ ለካዱት ከእነዚያ ካመኑት የሚሳለቁ ሲኾኑ ቅርቢቱ ሕይወት ተሸለመችላችው፡፡ እነዚያም የተጠነቀቁት በትንሣኤ ቀን ከበላያቸው ናቸው፡፡ አላህም ለሚሻው ሰው ያለ ግምት ይሰጣል፡፡'),
('2:213', 87, 'ሰዎቹ ሁሉ አንድ ሕዝብ ነበሩ፤ (ተለያዩ)፡፡ አላህም ነቢያትን አብሳሪዎችና አስፈራሪዎች አድርጎ ላከ፡፡ ከእነርሱም ጋር መጻሕፍትን በሰዎቹ መካከል በዚያ በርሱ በተለያዩበት ነገር ይፈርድ ዘንድ በእውነት አወረደ፡፡ በእርሱም (በሃይማኖት) ግልጽ አስረጂዎች ከመጡላቸው በኋላ በመካከላቸው ለኾነው ምቀኝነት እነዚያው የተሰጡት እንጂ አልተለያዩበትም፡፡ አላህም እነዚያን ያመኑትን ሰዎች ለእዚያ ከእውነት በርሱ ለተለያዩበት በፍቃዱ መራቸው፡፡ አላህም የሚሻውን ሰው ወደ ቀጥተኛው መንገድ ይመራል፡፡'),
('2:214', 87, 'በእውነቱ የእነዚያ ከበፊታችሁ ያለፉት (ምእምናን መከራ) ብጤ ሳይመጣችሁ ገነትን ልትገቡ ታስባላችሁን? መልክተኛውና እነዚያ ከርሱ ጋር ያመኑት «የአላህ እርዳታ መቼ ነው?» እስከሚሉ ድረስ መከራና ጉዳት ነካቻቸው፤ ተርበደበዱም፡፡ ንቁ! የአላህ እርዳታ በእርግጥ ቅርብ ነው (ተባሉም)፡፡'),
('2:215', 87, 'ምንን (ለማንም) እንደሚለግሱ ይጠይቁሃል፡፡ ከመልካም ነገር የምትለግሱት፤ ለወላጆችና ለቅርብ ዘመዶች፣ ለየቲሞችም፣ ለድሆችም፣ ለመንገደኞችም ነው፡፡ ከበጎ ነገርም ማንኛውንም ብትሠሩ አላህ እርሱን ዐዋቂ ነው በላቸው፡፡'),
('2:216', 87, 'መጋደል እርሱ ለእናንተ የተጠላ ሲሆን በእናንተ ላይ ተጻፈ፡፡ አንዳች ነገርን እርሱ ለናንተ የበለጠ ሲሆን የምትጠሉት መኾናችሁ ተረጋገጠ፡፡ አንዳችንም ነገር እርሱ ለናንተ መጥፎ ሲሆን የምትወዱት መሆናችሁ ተረጋገጠ፡፡ አላህም (የሚሻላችሁን) ያውቃል ግን እናንተ አታውቁም፡፡'),
('2:217', 87, 'ከተከበረው ወር (ከረጀብ) በርሱ ውስጥ ከመጋደል ይጠይቁሃል፡፡ በላቸው «በርሱ ውስጥ መጋደል ታላቅ (ኀጢአት) ነው፡፡ ግን ከአላህ መንገድ (ሰዎችን) መከላከል፣ በርሱም መካድ፣ ከተከበረውም መስጊድ (ማገድ) ባለቤቶቹንም ከርሱ ማውጣት አላህ ዘንድ ይበልጥ ታላቅ (ወንጀል) ነው፡፡ ፈተናም (ማጋራት) ከመግደል ይበልጥ ከባድ ነው፡፡ (ከሐዲዎች) ቢችሉ ከሃይማኖታችሁ እስከሚመልሳችሁ ድረስ የሚዋጉዋችሁ ከመሆን አይቦዝኑም፡፡ ከእናንተ ውስጥም ከሃይማኖቱ የሚመለስና እርሱም ከሐዲ ሆኖ የሚሞት ሰው እነዚያ (በጎ) ሥራቸው በቅርቢቱም በመጨረሻይቱም አገር ተበላሸች፡፡ እነዚያ የእሳት ጓዶች ናቸው፡፡ እነርሱ በርሷ ውስጥ ዘውታሪዎች ናቸው፡፡»'),
('2:218', 87, 'እነዚያ ያመኑትና እነዚያም (ከአገራቸው) የተሰደዱት በአላህም መንገድ ላይ የተጋደሉት እነዚያ የአላህን እዝነት ይከጅላሉ፡፡ አላህም እጅግ መሓሪ አዛኝ ነው፡፡'),
('2:219', 87, 'አእምሮን ከሚቃወም መጠጥና ከቁማር ይጠይቁሃል፡፡ «በሁለቱም ውስጥ ታላቅ ኃጢኣትና ለሰዎች ጥቅሞች አሉባቸው፡፡ ግን ኃጢኣታቸው ከጥቅማቸው በጣም ትልቅ ነው» በላቸው፡፡ ምንን እንደሚመጸውቱም (መጠኑን) ይጠይቁሃል፡፡ «ትርፍን (መጽውቱ)» በላቸው፡፡ እንደዚሁ ታስተነትኑ ዘንድ አላህ ለናንተ አንቀጾችን ይገልጽላችኋል፡፡'),
('2:220', 87, 'በቅርቢቱ ዓለምና በመጨረሻይቱ ታስተነትኑ ዘንድ (ይገለጽላችኋል)፡፡ ከየቲሞችም ይጠይቁሃል፡፡ «ለእነርሱ (ገንዘባቸውን በማራባት) ማሳመር በላጭ ነው፡፡ ብትቀላቀሏቸውም ወንድሞቻችሁ ናቸው፡፡ አላህም የሚያጠፋውን ከሚያበጀው (ለይቶ) ያውቃል፡፡ አላህም በሻ ኖሮ ባስቸገራችሁ ነበር፤ አላህ አሸናፊ ጥበበኛ ነውና» በላቸው፡፡'),
('2:221', 87, '(በአላህ) አጋሪ የሆኑ ሴቶች እስከሚያምኑ ድረስ አታግቡዋቸው፡፡ ከአጋሪይቱ ምንም ብትደንቃችሁም እንኳ ያመነችው ባሪያ በእርግጥ በላጭ ናት፡፡ ለአጋሪዎቹም እስከሚያምኑ ድረስ አትዳሩላቸው፡፡ ከአጋሪው (ጌታ) ምንም ቢደንቃችሁ ምእምኑ ባሪያ በላጭ ነው፡፡ እነዚያ (አጋሪዎች) ወደ እሳት ይጣራሉ፡፡ አላህም በፈቃዱ ወደ ገነትና ወደ ምሕረት ይጠራል፡፡ ሕግጋቱንም ለሰዎች ይገልጻል እነርሱ ሊገሰጹ ይከጀላልና፡፡'),
('2:222', 87, 'ከወር አበባም ይጠይቁሃል፡፡ እርሱ አስጠያፊ ነው፡፡ ሴቶችንም በወር አበባ ጊዜ ራቋቸው፡፡ ንጹሕ እስከሚኾኑም ድረስ አትቅረቡዋቸው፡፡ ንጹሕ በኾኑም ጊዜ አላህ ካዘዛችሁ ስፍራ ተገናኙዋቸው፡፡ አላህ (ከኃጢኣት) ተመላሾችን ይወዳል፤ ተጥራሪዎችንም ይወዳል በላቸው፡፡'),
('2:223', 87, 'ሴቶቻችሁ ለናንተ እርሻ ናቸው፡፡ እርሻችሁንም በፈለጋችሁት ኹነታ ድረሱ፡፡ ለነፍሶቻችሁም (መልካም ሥራን) አስቀድሙ፡፡ አላህንም ፍሩ፡፡ እናንተም ተገናኝዎቹ መኾናችሁን ዕወቁ፡፡ ምእመናንንም (በገነት) አብስር፡፡'),
('2:224', 87, 'መልካም እንዳትሠሩ፣ አላህንም እንዳትፈሩ፣ በሰዎችም መካከል እንዳታስታርቁ አላህን ለመሐላዎቻችሁ ግርዶ አታድርጉ፡፡ አላህም ሰሚ አዋቂ ነው፡፡'),
('2:225', 87, 'በመሐላዎቻችሁ በውድቁ (ሳታስቡ በምትምሉት) አላህ አይዛችሁም፡፡ ግን ልቦቻችሁ ባሰቡት ይይዛችኋል፡፡ አላህም በጣም መሐሪ ታጋሽ ነው፡፡'),
('2:226', 87, 'ለእነዚያ ከሴቶቻቸው (ላይቀርቡ) ለሚምሉት አራትን ወሮች መጠበቅ አለባቸው፡፡ (ከመሐላቸው) ቢመለሱም አላህ መሓሪ አዛኝ ነው፡፡'),
('2:227', 87, 'መፍታትንም ቁርጥ አሳብ ቢያደርጉ (ይፍቱ)፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('2:228', 87, 'የተፈቱ ሴቶችም ነፍሶቻቸውን (ከማግባት) ሦስትን ቁርእ ይጠብቁ፡፡ በአላህና በመጨረሻውም ቀን የሚያምኑ ቢኾኑ አላህ በማሕፀኖቻቸው ውስጥ የፈጠረውን ሊደብቁ ለነርሱ አይፈቀድላቸውም፡፡ ባሎቻቸውም በዚህ ውስጥ እርቅን ቢፈልጉ በመማለሳቸው ተገቢዎች ናቸው፡፡ ለእነርሱም (ለሴቶች) የዚያ በእነርሱ ላይ ያለባቸው (ግዳጅ) ብጤ በመልካም አኑዋኑዋር (በባሎቻቸው ላይ መብት) አላቸው፡፡ ለወንዶችም (ጣጣቸውን ስለሚሸከሙ) በእነሱ ላይ ብልጫ አላቸው፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('2:229', 87, 'ፍች ሁለት ጊዜ ነው፤ (ከዚህ በኋላ) በመልካም መያዝ ወይም በበጎ አኳኋን ማሰናበት ነው፡፡ የአላህንም ሕግጋት አለመጠበቃቸውን ካላወቁ በስተቀር ከሰጣችኃቸው ነገር ምንንም ልትወስዱ ለእናንተ (ለባሎች) አይፈቀድላችሁም፡፡ የአላህንም ሕግጋት አለመጠበቃቸውን ብታውቁ በእርሱ (ነፍሷን) በተበዠችበት ነገር በሁለቱም ላይ ኃጢኣት የለም፡፡ ይህች የአላህ ሕግጋት ናት፤ አትተላለፏትም፡፡ የአላህንም ሕግጋት የሚተላለፉ እነዚያ እነርሱ በዳዮች ናቸው፡፡'),
('2:230', 87, '(ሦስተኛ) ቢፈታትም ከዚህ በኋላ ሌላን ባል እስከምታገባ ድረስ ለርሱ አትፈቀድለትም፡፡ (ሁለተኛው ባል) ቢፈታትም የአላህን ሕግጋት መጠበቃቸውን ቢያውቁ በመማለሳቸው በሁለቱም ላይ ኃጢኣት የለባቸውም፡፡ ይህችም የአላህ ሕግጋት ናት ለሚያውቁ ሕዝቦች ያብራራታል፡፡'),
('2:231', 87, 'ሴቶችን በፈታችሁና (የዒዳ) ጊዜያቸውን በደረሱ ጊዜ በመልካም ያዙዋቸው፤ (ተማለሷቸው) ወይም በመልካም ኹኔታ አሰናብቱዋቸው፡፡ ለመጉዳትም ወሰን ታልፋባቸው ዘንድ አትያዙዋቸው፤ ይህንንም የሚሠራ ሰው ነፍሱን በእርግጥ በደለ፡፡ የአላህንም አንቀጾች ማላገጫ አድርጋችሁ አትያዙ፡፡ የአላህንም ጸጋ በናንተ ላይ ያደረገውን ከመጽሐፍና ከጥበብም በርሱ የሚገስጻችሁ ሲኾን በናንተ ላይ ያወረደውን አስታውሱ፡፡ አላህንም ፍሩ፤ አላህም ነገሩን ሁሉ ዐዋቂ መኾኑን ዕወቁ፡፡'),
('2:232', 87, 'ሴቶችንም በፈታችሁና ጊዜያቸውን በደረሱ ጊዜ በመካከላቸው በሕግ በተዋደዱ ጊዜ ባሎቻቸውን ከማግባት አታስተጓጉሏቸው፡፡ ይህ (መከልከል) ከእናንተ በአላህና በመጨረሻው ቀን የሚያምን ሰው በርሱ ይገሰጽበታል፡፡ ይህ ሁኔታችሁ ለእናንተ በላጭ ነው፤ (ከመጠርጠር) አጥሪም ነው፡፡ አላህም ያውቃል፤ እናንተ ግን አታውቁም፡፡'),
('2:233', 87, 'እናቶችም ልጆቻቸውን ሙሉ የኾኑን ሁለት ዓመታት ያጥቡ፡፡ (ይህም) ማጥባትን መሙላት ለሻ ሰው ነው፡፡ ለእርሱም በተወለደለት (አባት) ላይ ምግባቸውና ልብሳቸው በችሎታው ልክ አለበት፡፡ ነፍስ ችሎታዋን እንጂ አትገደድም፡፡ ወላጂት (እናት) በልጅዋ ምክንያት ለርሱ የተወለደለትም (አባት) በልጁ ምክንያት አይጎዳዱ፡፡ በወራሽም ላይ እንደዚሁ ብጤ አለበት፡፡ (ወላጆቹ) ከሁለቱም በኾነ መዋደድና መመካከር (ልጁን ከጡት) መነጠልን ቢፈልጉ በሁለቱም ላይ ኃጢኣት የለባቸውም፡፡ ልጆቻችሁንም ለሌሎች አጥቢዎች ማስጠባትን ብትፈልጉ ልትሰጡ የሻችሁትን በመልካም ኹኔታ በሰጣችሁ ጊዜ (በማስጠባታችሁ) በእናንተ ላይ ኃጢኣት የለባችሁም፡፡ አላህንም ፍሩ፤ አላህም የምትሠሩትን ሁሉ ተመልካች መኾኑን ዕወቁ፡፡'),
('2:234', 87, 'እነዚያም ከናንተ ውስጥ የሚሞቱና ሚስቶችን የሚተዉ (ሚስቶቻቸው) በነፍሶቻቸው አራት ወሮች ከዐስር (ቀናት ከጋብቻ) ይታገሱ፡፡ ጊዜያቸውንም በጨረሱ ጊዜ በነፍሶቻቸው በታወቀ ሕግ በሠሩት ነገር በእናንተ ላይ ኃጢአት የለባችሁም፡፡ አላህም በምትሠሩት ሁሉ ውስጥ ዐዋቂ ነው፡፡'),
('2:235', 87, 'ሴቶችንም ከማጨት በርሱ ባሸሞራችሁበት ወይም በነፍሶቻችሁ ውስጥ (ለማግባት) በደበቃችሁት በናንተ ላይ ኃጢኣት የለባችሁም፡፡ አላህ እናንተ በእርግጥ የምታስታውሷቸው መኾናችሁን ዐወቀ፡፡ (ስለዚህ ማሸሞርንና ማሰብን ፈቀደላችሁ፡፡) ግን በሕግ የታወቀን ንግግር የምትነጋገሩ ካልኾናችሁ በስተቀር፤ ምስጢርን (ጋብቻን) አትቃጠሩዋቸው፡፡ የተጻፈውም (ዒዳህ) ጊዜውን እስከሚደርስ ድረስ ጋብቻን ለመዋዋል ቁርጥ ሐሳብ አታድርጉ፡፡ አላህም በነፍሶቻችሁ ያለውን ነገር የሚያውቅ መኾኑን ዕወቁ፤ ተጠንቀቁትም፡፡ አላህም መሓሪ ታጋሽ መኾኑን ዕወቁ፡፡'),
('2:236', 87, 'ሴቶችን ሳትነኳቸው (ሳትገናኙ)፤ ወይም ለነሱ መህርን ሳትወስኑላቸው ብትፈቷቸው በናንተ ላይ ኃጢኣት የለባችሁም፡፡ (ዳረጎት በመስጠት መፍታት ትችላላችሁ፡፡) ጥቀሟቸውም፡፡ በሀብታም ላይ ችሎታው በድኀም ላይ ችሎታው (አቅሙ የሚፈቅደውን መስጠት) አለበት፡፡ መልካም የኾነን መጥቀም በበጎ ሠሪዎች ላይ የተረጋገጠን፤ (ጥቀሟቸው)፡፡'),
('2:237', 87, 'ለእነርሱም መወሰንን በእርግጥ የወሰናችሁላቸው ስትኾኑ ሳትነኳቸው በፊት ብተፈቷቸው ካልማሩዋችሁ ወይም ያ የጋብቻው ውል በእጁ የኾነው (ባልየው) ካልማረ በስተቀር የወሰናችሁት ግማሹ አላቸው፡፡ ምሕረትም ማድረጋችሁ ወደ አላህ ፍራቻ በጣም የቀረበ ነው፡፡ በመካከላችሁም ችሮታን አትርሱ፤ አላህ የምትሠሩትን ሁሉ ተመልካች ነውና፡፡'),
('2:238', 87, 'በሶላቶች (በተለይ) በመካከለኛይቱም ሶላት ላይ ተጠባበቁ፡፡ ታዛዦች ኾናችሁም ለአላህ ቁሙ፡፡'),
('2:239', 87, 'ብትፈሩም እግረኞች ወይም ጋላቢዎች ኾናችሁ (ስገዱ)፡፡ ጸጥተኞችም በኾናችሁ ጊዜ ታውቁት ያልነበራችሁትን እንደ አሳወቃችሁ አላህን አውሱ (ስገዱ)፡፡'),
('2:240', 87, 'እነዚያ ከናንተ ውስጥ የሚሞቱ ሚስቶችንም የሚተዉ፤ ለሚስቶቻቸው (ከቤታቸው) የማይወጡ ሲኾኑ ዓመት ድረስ መጠቀምን ኑዛዜን (ይናዘዙ)፡፡ በፈቃዳቸው ቢወጡም በሕግ ከታወቀው ነገር በነፍሶቻቸው በሠሩት በእናንተ (በሟቹ ዘመዶች) ላይ ኃጢኣት የለባችሁም አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('2:241', 87, 'ለተፈቱ ሴቶችም በችሎታ መጠን ዳረጎት አላቸው፡፡ አላህን በሚፈሩ ላይ ተደንግጓል፡፡'),
('2:242', 87, 'እንደዚሁ አላህ አንቀጾቹን ታውቁ ዘንድ ለናንተ ያብራራላችኋል፡፡'),
('2:243', 87, 'ወደ እነዚያ እነርሱ ብዙ ሺሕ ኾነው ሞትን ለመፍራት ከሀገሮቻቸው ወደ ወጡት ሰዎች ዕውቀትህ አልደረሰምን? አላህም ለነርሱ «ሙቱ» አላቸው፤ (ሞቱም)፡፡ ከዚያም ሕያው አደረጋቸው፡፡ አላህም በሰዎች ላይ ባለችሮታ ነው፤ ግን አብዛኛዎቹ ሰዎች አያመሰግኑም፡፡'),
('2:244', 87, 'በአላህም መንገድ (ሃይማኖት) ተጋደሉ፡፡ አላህም ሰሚ ዐዋቂ መኾኑን ዕወቁ፡፡'),
('2:245', 87, 'ያ ለአላህ መልካም ብድርን የሚያበድርና ለእርሱ (አላህ) ብዙ እጥፎች አድርጎ የሚያነባብርለት ማነው? አላህም ይጨብጣል፤ ይዘረጋልም፤ ወደ እርሱም ትመለሳላችሁ፡፡'),
('2:246', 87, 'ከእስራኤል ልጆች ከሙሳ በኋላ ወደ ነበሩት ጭፍሮች ለነቢያቸው (ለሳሙኤል)፡- «ለእኛ ንጉሥን አስነሳልን በአላህ መንገድ እንዋጋለን፤» ባሉ ጊዜ አላየህምን? (አላወቅህምን?)፡-«መዋጋት ቢጻፍባችሁ አትዋጉም ይኾናል» አላቸው፡፡ «ከሀገሮቻችንና ከልጆቻችን የተባረርን ስንኾን በአላህ መንገድ የማንዋጋ ለእኛ ምን አለን?» አሉ፡፡ በእነርሱ ላይ መዋጋት በተጻፈባቸውም ጊዜ ከእነርሱ ጥቂቶች ሲቀሩ አፈገፈጉ፡፡ አላህም በዳዮቹን ዐዋቂ ነው፡፡'),
('2:247', 87, 'ነቢያቸውም ለእነርሱ፡- «አላህ ጧሉትን (ሳኦልን) ንጉሥ አድርጎ በእርግጥ ላከላችሁ» አላቸው፡፡ (እነርሱም)፡- «እኛ ከእርሱ ይልቅ በንግሥና ተገቢዎች ስንኾን ከሀብትም ስፋትን ያልተሰጠ ሲኾን ለእርሱ በኛ ላይ እንዴት ንግሥና ይኖረዋል?» አሉ፡፡ (ነቢያቸውም)፡-«አላህ በእናንተ ላይ መረጠው፡፡ በዕውቀትና በአካልም ስፋትን ጨመረለት፡፡ አላህም ንግሥናውን ለሚሻው ሰው ይሰጣል፡፡ አላህም ችሮታው ሰፊ ዐዋቂ ነው» አላቸው፡፡'),
('2:248', 87, 'ነቢያቸውም ለእነርሱ፡- «የንግሥናው ምልክት ከጌታችሁ የኾነ እርጋታ የሙሳ ቤተሰብና የሃሩን ቤተሰብ ከተውትም ቅርስ በውስጡ ያለበት መላእክት የሚሸከሙት ኾኖ ሳጥኑ ሊመጣላችሁ ነው፡፡ አማኞች ብትኾኑ በዚህ ለእናንተ እርግጠኛ ምልክት አልለ» አላቸው፡፡'),
('2:249', 87, 'ጧሉትም በሠራዊቱ (ታጅቦ) በወጣ ጊዜ፡- «አላህ በወንዝ (ውሃ) ፈታኛችሁ ነው ከርሱም የጠጣ ሰው ከእኔ አይደለም፡፡ ያልቀመሰውም ሰው በእጁ መዝገንን የዘገነ ሰው ብቻ ሲቀር እርሱ ከኔ ነው» አለ፡፡ ከእነርሱም ጥቂቶች ሲቀሩ ከርሱ ጠጡ፡፡ እርሱና እነዚያም ከእርሱ ጋር ያመኑት (ወንዙን) ባለፉት ጊዜ፡- «ጃሎትንና ሠራዊቱን በመዋጋት ለኛ ዛሬ ችሎታ የለንም» አሉት፡፡ እነዚያ እነርሱ አላህን ተገናኝዎች መኾናቸው የሚያረጋግጡት፡- «ከጥቂት ጭፍራ በአላህ ፈቃድ ብዙን ጭፍራ ያሸነፈች ብዙ ናት፤ አላህም ከታጋሾች ጋር ነው» አሉ፡፡'),
('2:250', 87, 'ለጃሎትና ለሠራዊቱ በተሰለፉም ጊዜ፡- «ጌታችን ሆይ! በእኛ ላይ ትዕግስትን አንቧቧ፤ ጫማዎቻችንንም አደላድል፤ በከሓዲያን ሕዝቦችም ላይ እርዳን» አሉ፡፡'),
('2:251', 87, 'በአላህም ፈቃድ ድል መቷቸው፡፡ ዳውድም ጃሉትን (ዳዊት ጎልያድን) ገደለ፡፡ ንግሥናንና ጥበብንም (ነቢይነትን) አላህ ሰጠው፡፡ ከሚሻውም ነገር ሁሉ አሳወቀው፡፡ አላህም ሰዎችን ከፊላቸውን በከፊሉ መመለሱ ባልነበረ ኖሮ ምድር በተበላሸች ነበር፤ ግን አላህ በዓለማት ላይ የችሮታ ባለቤት ነው፡፡'),
('2:252', 87, 'እነዚህ (አንቀጾች) በውነት በአንተ ላይ የምናነባቸው ሲኾኑ የአላህ አንቀጾች ናቸው፤ አንተም በእርግጥ ከመልክተኞቹ ነህ፡፡'),
('2:253', 87, 'እነዚህን መልክተኞች ከፊላቸውን በከፊሉ ላይ አበለጥን፡፡ ከእነርሱ ውስጥ አላህ ያነጋገረው አልለ፡፡ ከፊሎቻቸውንም በደረጃዎች ከፍ አደረገ፡፡ የመርየምን ልጅ ዒሳንም ግልጽ ታምራቶችን ሰጠነው፡፡ በቅዱሱ መንፈስም አበረታነው፡፡ አላህም በሻ ኖሮ እነዚያ ከእነርሱ (ከመልክተኞቹ) በኋላ የነበሩት ግልጽ ታምራቶች ከመጡላቸው በኋላ ባልተጋደሉ ነበር፡፡ ግን ተለያዩ፡፡ ከእነርሱም ውስጥ ያመነ ሰው አልለ፡፡ ከነርሱም ውስጥ የካደ ሰው አልለ፡፡ አላህም በሻ ኖሮ ባልተዋጉ (ባልተለያዩ) ነበር፡፡ ግን አላህ የሚሻውን ይሠራል፡፡'),
('2:254', 87, 'እናንተ ያመናችሁ ሆይ! በርሱ ውስጥ ሽያጭ (መበዠት)፣ ወዳጅነትም፣ ምልጃም የሌለበት ቀን ከመምጣቱ በፊት ከሰጠናችሁ ነገር ለግሱ፡፡ ከሓዲዎችም በዳዮቹ እነርሱ ናቸው፡፡'),
('2:255', 87, 'አላህ ከእርሱ በቀር ሌላ አምላክ የለም፡፡ ሕያው ራሱን ቻይ ነው፡፡ ማንገላጀትም እንቅልፍም አትይዘውም፡፡ በሰማያት ውስጥና በምድር ውስጥ ያለው ሁሉ የርሱ ብቻ ነው፡፡ ያ እርሱ ዘንድ በፈቃዱ ቢኾን እንጅ የሚያማልድ ማነው? (ከፍጡሮች) በፊታቸው ያለውንና ከኋላቸው ያለውን ሁሉ ያውቃል፡፡ በሻውም ነገር እንጂ ከዕውቀቱ በምንም ነገር አያካብቡም (አያውቁም)፡፡ መንበሩ ሰማያትንና ምድርን ሰፋ፡፡ ጥበቃቸውም አያቅተውም፡፡ እርሱም የሁሉ በላይ ታላቅ ነው፡፡'),
('2:256', 87, 'በሃይማኖት ማስገደድ የለም፡፡ ቅኑ መንገድ ከጠማማው በእርግጥ ተገለጠ፡፡ በጣዖትም የሚክድና በአላህ የሚያምን ሰው ለርሷ መበጠስ የሌላትን ጠንካራ ዘለበት በእርግጥ ጨበጠ፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('2:257', 87, 'አላህ የእነዚያ ያመኑት ሰዎች ረዳት ነው፡፡ ከጨለማዎች ወደ ብርሃን ያወጣቸዋል፡፡ እነዚያም የካዱት ረዳቶቻቸው ጣዖታት ናቸው፡፡ ከብርሃን ወደ ጨለማዎች ያወጧቸዋል፡፡ እነዚያ የእሳት ጓዶች ናቸው፤ እነርሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('2:258', 87, 'ወደዚያ አላህ ንግሥናን ስለሰጠው ኢብራሂምን በጌታው ነገር ወደ ተከራከረው ሰው አላየህምን ኢብራሂም «ጌታዬ ያ ሕያው የሚያደርግና የሚገድል ነው» ባለ ጊዜ «እኔ ሕያው አደርጋለሁ እገድላለሁም» አለ፡፡ ኢብራሂም፡- «አላህ ፀሐይን ከምሥራቅ በኩል ያመጣል (አንተ) ከምዕራብ በኩል አምጣት» አለው፡፡ ያም የካደው ሰው ዋለለ፤ (መልስ አጣ) አላህም በዳዮች ሕዝቦችን አይመራም፡፡'),
('2:259', 87, 'ወይም ያንን በከተማ ላይ እርሷ በጣራዎችዋ ላይ የወደቀች ስትኾን ያለፈውን ሰው ብጤ (አላየህምን)፡- «ይህችን (ከተማ) ከሞተች በኋላ አላህ እንዴት ሕያው ያደርጋታል» አለ፡፡ አላህም ገደለው መቶ ዓመትን (አቆየውም)፡፡ ከዚያም አስነሳው፡- «ምን ያህል ቆየህ» አለው፡፡ «አንድ ቀን ወይም የቀንን ከፊል ቆየሁ» አለ፡፡ «አይደለም መቶን ዓመት ቆየህ፡፡ ወደ ምግብህና ወደ መጠጥህም ያልተለወጠ ሲኾን ተመልከት፡፡ ወደ አህያህም ተመልከት፡፡ ለሰዎችም አስረጅ እናደርግህ ዘንድ (ይህንን ሠሰራን)፡፡ ወደ ዐፅሞቹም እንዴት እንደምናስነሳት ከዚያም ሥጋን እንደምናለብሳት ተመልከት» አለው፡፡ ለርሱም (በማየት) በተገለጸለት ጊዜ፡- «አላህ በነገሩ ሁሉ ላይ ቻይ መኾኑን ዐውቃለሁ» አለ፡፡'),
('2:260', 87, 'ኢብራሂምም «ጌታዬ ሆይ! ሙታንን እንዴት ሕያው እንደምታደርግ አሳየኝ» ባለ ጊዜ (አስታውስ፡፡) አላህ ፡- «አላመንክምን» አለው፡፡ «አይደለም (አምኛለሁ)፤ ግን ልቤ እንዲረጋ» ነው አለ፡፡ (አላህም)፡- «ከበራሪዎች (ከወፎች) አራትን ያዝ፡፡ ወደ አንተም ሰብስባቸው፡፡ (ቆራርጣቸውም)፤ ከዚያም በየኮረብታው ሁሉ ላይ ከነርሱ ቁራጭን አድርግ፡፡ ከዚያም ጥራቸው፤ ፈጥነው ይመጡሃልና፡፡ አላህም አሸናፊ ጥበበኛ መኾኑን ዕወቅ» አለው፡፡'),
('2:261', 87, 'የእነዚያ ገንዘቦቻቸውን በአላህ መንገድ የሚለግሱ ሰዎች (ልግስና) ምሳሌ በየዘለላው ሁሉ መቶ ቅንጣት ያለባቸውን ሰባት ዘለላዎች እንደ አበቀለች አንዲት ቅንጣት ብጤ ነው፡፡ አላህም ለሚሻው ሰው (ከዚህ በላይ) ያነባብራል፡፡ አላህም ችሮታው ሰፊ ዐዋቂ ነው፡፡'),
('2:262', 87, 'እነዚያ ገንዘቦቻቸውን በአላህ መንገድ የሚለግሱ ከዚያም የሰጡትን ነገር መመጻደቅንና ማስከፋትን የማያስከትሉ ለእነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፡፡ በእነርሱም ላይ ፍርሃት የለባቸውም፤ እነርሱም አያዝኑም፡፡'),
('2:263', 87, 'መልካም ንግግርና ምሕረት ማድረግ ማስከፋት ከሚከተላት ምጽዋት በላጭ ነው፡፡ አላህም ተብቃቂ ታጋሽ ነው፡፡'),
('2:264', 87, 'እናንተ ያመናችሁ ሆይ! እንደዚያ ገንዘቡን ለሰዎች ማሳየት ሲል እንደሚሰጠውና በአላህና በመጨረሻውም ቀን እንደማያምነው ሰው ምጽዋቶቻችሁን በመመጻደቅና በማስከፋት አታበላሹ፡፡ ምሳሌውም በላዩ ዐፈር እንዳለበት ለንጣ ድንጋይ ኃይለኛም ዝናብ እንዳገኘውና ምልጥ አድርጎ እንደተወው ብጤ ነው፡፡ ከሠሩት ነገር በምንም ላይ (ሊጠቀሙ) አይችሉም፡፡ አላህም ከሓዲያንን ሕዝቦች አይመራም፡፡'),
('2:265', 87, 'የእነዚያም የአላህን ውዴታ ለመፈለግና ለነፍሶቻቸው (እምነትን) ለማረጋገጥ ገንዘቦቻቸውን የሚለግሱ ሰዎች ምሳሌ በተስተካከለች ከፍተኛ ስፍራ ላይ እንዳለች አትክልት፣ ብዙ ዝናብ እንደነካት ፍሬዋንም እጥፍ ኾኖ እንደሰጠች፣ ዝናብም ባይነካት ካፊያ እንደሚበቃት ብጤ ነው፡፡ አላህም የምትሠሩትን ሁሉ ተመልካች ነው፡፡'),
('2:266', 87, '(ከእናንተ) አንዳችሁ ለርሱ ከዘምባባና ከወይኖች በስርዋ ወንዞች የሚፈሱባት አትክልት ልትኖረው፣ በውስጧም ለርሱ ከየፍሬው ሁሉ ሊኖረው እርጅናም ሊነካውና ለርሱ ደካማዎች ዝርያዎች ያሉት ሲኾን በውስጡ እሳት ያለበት ውርጭ ሊያገኛትና ልትቃጠል ይወዳልን እንደዚሁ አላህ አንቀጾችን ለእናንተ ያብራራል፤ ልታስተነትኑ ይከጀላልና፡፡'),
('2:267', 87, 'እናንተ ያመናችሁ ሆይ! ካፈራችሁትና ከዚያም ለእናንተ ከምድር ካወጣንላችሁ ከመልካሙ ለግሱ፡፡ መጥፎውንም (ለመስጠት) አታስቡ፡፡ በእርሱ ዓይኖቻችሁን ጨፍናችሁ እንጂ የማትወስዱት ስትኾኑ ከእርሱ (ከመጥፎው) ትሰጣላችሁን አላህም ተብቃቂ ምስጉን መኾኑን ዕወቁ፡፡'),
('2:268', 87, 'ሰይጣን (እንዳትለግሱ) ድኽነትን ያስፈራራችኋል፡፡ በመጥፎም ያዛችኋል፡፡ አላህም ከርሱ የኾነን ምሕረትና ችሮታን ይቀጥራችኋል፡፡ አላህም ችሮታው ሰፊ ዐዋቂ ነው፡፡'),
('2:269', 87, 'ለሚሻው ሰው ጥበብን ይሰጣል፤ ጥበብንም የሚስሰጥ ሰው ብዙን መልካም ነገር በእርግጥ ተሰጠ፡፡ የአእምሮዎች ባለቤቶች እንጂ (ሌላው) አይገሰጽም፡፡'),
('2:270', 87, 'ከምጽዋትም ማንኛውንም የለገሳችሁትን ወይም ከስለት የተሳላችሁትን አላህ ያውቀዋል፡፡ ለበዳዮችም ከረዳቶች ምንም የላቸውም፡፡'),
('2:271', 87, 'ምጽዋቶችን ብትገልጹ እርሷ ምንኛ መልካም ናት፡፡ ብትደብቋትና ለድኾች ብትሰጧትም እርሱ ለናንተ በላጭ ነው፡፡ ከኃጢአቶቻችሁም ከእናንተ ያብሳል፡፡ አላህም በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('2:272', 87, 'እነርሱን ማቅናት በአንተ ላይ የለብህም፡፡ ግን አላህ የሚሻውን ሰው ያቀናል፡፡ ከገንዘብም የምትለግሱት (ምንዳው) ለነፍሶቻችሁ ነው፡፡ የአላህንም ፊት (ውዴታውን) ለመፈለግ እንጂ አትለግሱም፡፡ ከገንዘብም የምትለግሱት ሁሉ (ምንዳው) ወደናንተ ይሞላል፡፡ እናንተም አትበደሉም፡፡'),
('2:273', 87, '(የምትመጸውቱት) ለእነዚያ በአላህ መንገድ (ለመታገል ሲሉ) ለታገዱት ድኾች ነው፡፡ በምድር መኼድን አይችሉም፡፡ (ልመናን) ከመጥጠበቃቸው (የተነሳ) የማያውቅ ሰው ሀብታሞች ናቸው ብሎ ይጠረጥራቸዋል፡፡ በምልክታቸው ታውቃቸዋለህ፡፡ ሰዎችን በችክታ አይለምኑም፡፡ ከገንዘብም የምትለግሱት አላህ እርሱን ዐዋቂ ነው፡፡'),
('2:274', 87, 'እነዚያ ገንዘቦቻቸውን በሌሊትና በቀን በድብቅም በግልጽም የሚለግሱ ለእነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፡፡ በእነርሱም ላይ ፍርሃት የለባቸውም እነርሱም አያዝኑም፡፡'),
('2:275', 87, 'እነዚያ አራጣን የሚበሉ ያ ሰይጣን ከመንካቱ የተነሳ የሚጥለው ሰው (ከአውድቁ) እንደሚነሳ ብጤ እንጅ (ከመቃብራቸው) አይነሱም፡፡ ይህ እነርሱ መሸጥ የአራጣ ብጤ ብቻ ነው በማለታቸው ነው፡፡ ግን መሸጥን አላህ ፈቅዷል፡፡ አራጣንም እርም አድርጓል፡፡ ከጌታውም ግሳጼ የመጣለትና የተከለከለ ሰው ለርሱ (ከመከልከሉ በፊት) ያለፈው አለው፡፡ ነገሩም ወደ አላህ ነው፤ (አራጣን ወደ መብላት) የተመለሰም ሰው እነዚያ የእሳት ጓዶች ናቸው፡፡ እነርሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('2:276', 87, 'አላህ አራጣን (በረከቱን) ያጠፋል፡፡ ምጽዋቶችንም ያፋፋል፡፡ አላህም ኃጠኢተኛ ከሓዲን ሁሉ አይወድም፡፡'),
('2:277', 87, 'እነዚያ ያመኑ፡፡ መልካም ሥራዎችንም የሠሩ፡፡ ሶላትንም ያስተካከሉ፡፡ ዘካንም የሰጡ ለነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፡፡ በእነርሱም ላይ ፍርሃት የለባቸውም እነርሱም አያዝኑም፡፡'),
('2:278', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ፍሩ፡፡ ከአራጣም የቀረውን ተዉ፡፡ አማኞች እንደኾናችሁ (ተጠንቀቁ)፡፡'),
('2:279', 87, '(የታዘዛችሁትን) ባትሠሩም ከአላህና ከመልክተኛው በኾነች ጦር (መወጋታችሁን) ዕወቁ፡፡ ብትጸጸቱም ለእናንተ የገንዘቦቻችሁ ዋናዎች አሏችሁ፡፡ አትበድሉም አትበደሉምም፡፡'),
('2:280', 87, 'የድኽነት ባለቤት የኾነም (ባለዕዳ) ሰው ቢኖር እማግኘት ድረስ ማቆየት ነው፡፡ (በመማር) መመጽወታችሁም ለእናንተ በላጭ ነው፡፡ የምታውቁ ብትኾኑ (ትሠሩታላችሁ)፡፡'),
('2:281', 87, 'በእርሱም ውስጥ ወደ አላህ የምትመለሱበትንና ከዚያም እነርሱ የማይበደሉ ሲሆኑ ነፍስ ሁሉ የሠራችውን ሥራ የምትሞላበትን ቀን ተጠንቀቁ፡፡'),
('2:282', 87, 'እናንተ ያመናችሁ ሆይ! እስከ ተወሰነ ጊዜ ድረስ በዕዳ በተዋዋላችሁ ጊዜ ጻፉት፡፡ ጸሐፊም በመካከላችሁ በትክክል ይጻፍ፡፡ ጸሐፊም አላህ እንደ አሳወቀው መጻፍን እንቢ አይበል፡፡ ይጻፍም፡፡ ያም በርሱ ላይ ዕዳው ያለበት ሰው በቃሉ ያስጽፍ፡፡ አላህንም ጌታውን ይፍራ፡፡ ከእርሱም (ካለበት ዕዳ) ምንንም አያጉድል፡፡ ያም በርሱ ላይ ዕዳው ያለበት ቂል፣ ወይም ደካማ፣ ወይም በቃሉ ማስጻፍን የማይችል ቢኾን ዋቢው በትክክል ያስጽፍለት፡፡ ከወንዶቻችሁም ሁለትን ምስክሮች አስመስክሩ፡፡ ሁለትም ወንዶች ባይኾኑ ከምስክሮች ሲኾኑ ከምትወዱዋቸው የኾኑን አንድ ወንድና አንደኛዋ ስትረሳ አንደኛይቱ ሌላዋን ታስታውሳት ዘንድ ሁለት ሴቶች (ይመስክሩ)፡፡ ምስክሮችም በተጠሩ ጊዜ እንቢ አይበሉ፡፡ (ዕዳው) ትንሽ ወይም ትልቅ ቢኾንም እስከ ጊዜው ድረስ የምትጽፉት ከመኾን አትሰልቹ፡፡ እንዲህ ማድረጋችሁ አላህ ዘንድ በጣም ትክክል ለምስክርነትም አረጋጋጭ ላለመጠራጠራችሁም በጣም ቅርብ ነው፡፡ ግን በመካከላችሁ እጅ በጅ የምትቀባበሏት ንግድ ብትኾን ባትጽፉዋት በናንተ ላይ ኃጢኣት የለባችሁም፡፡ በተሻሻጣችሁም ጊዜ አስመስክሩ፡፡ ጸሐፊም ምስክርም (ባለ ጉዳዩ ጋር) አይጎዳዱ፡፡ (ይህንን) ብትሠሩም እርሱ በእናንተ (የሚጠጋ) አመጽ ነው፡፡ አላህንም ፍሩ፡፡ አላህም ያሳውቃችኋል፡፡ አላህም ነገሩን ሁሉ ዐዋቂ ነው፡፡'),
('2:283', 87, 'በጉዞም ላይ ብትኾኑና ጸሐፊን ባታገኙ የተጨበጡ መተማመኛዎችን ያዙ፡፡ ከፊላችሁም ከፊሉን ቢያምን ያ የታመነው ሰው አደራውን ያድርስ፡፡ አላህንም ጌታውን ይፍራ፡፡ ምስክርነትንም አትደብቁ፡፡ የሚደብቃትም ሰው እርሱ ልቡ ኃጢኣተኛ ነው፡፡ አላህም የምትሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('2:284', 87, 'በሰማያት ውስጥና በምድርም ውስጥ ያለው ሁሉ የአላህ ነው፡፡ በነፍሶቻችሁ ውስጥ ያለውን ብትገልጹ ወይም ብትደብቁት አላህ በርሱ ይቆጣጠራችኋል፡፡ ለሚሻውም ሰው ይምራል፡፡ የሚሻውንም ሰው ይቀጣል፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('2:285', 87, 'መልክተኛው ከጌታው ወደ ርሱ በተወረደው አመነ፡፡ ምእምኖቹም (እንደዚሁ)፡፡ ሁሉም በአላህ፣ በመላዕክቱም፣ በመጻሕፍቱም፣ በመልክተኞቹም ከመልክተኞቹ «በአንድም መካከል አንለይም» (የሚሉ ሲኾኑ) አመኑ፡፡ «ሰማን፤ ታዘዝንም፡፡ ጌታችን ሆይ! ምሕረትህን (እንሻለን)፡፡ መመለሻም ወዳንተ ብቻ ነው» አሉም፡:'),
('2:286', 87, 'አላህ ነፍስን ከችሎታዋ በላይ አያስገድዳትም፡፡ ለርስዋ የሠራችው አላት፡፡ በርስዋም ላይ ያፈራችው (ኀጢአት) አለባት፡፡ (በሉ)፡- ጌታችን ሆይ! ብንረሳ ወይም ብንስት አትያዘን፤ (አትቅጣን)፡፡ ጌታችን ሆይ! ከባድ ሸክምን ከእኛ በፊት በነበሩት ላይ እንደጫንከው በእኛ ላይ አትጫንብን፡፡ ጌታችን ሆይ! ለኛም በርሱ ችሎታ የሌለንን ነገር አታሸክመን፡፡ ከእኛም ይቅርታ አድርግ ለእኛም ምሕረት አድርግ፡፡ እዘንልንም፤ ዋቢያችን አንተ ነህና፡፡ በከሓዲዎች ሕዝቦች ላይም እርዳን፡፡'),
('3:1', 87, 'አ.ለ.መ (አሊፍ ላም ሚም)፤'),
('3:2', 87, 'አላህ ከርሱ በስተቀር ሌላ አምላክ የለም፡፡ (እርሱ) ሕያው ሁሉን ነገር አስተናባሪ ነው፡፡'),
('3:3', 87, 'ከርሱ በፊት ያሉትን መጻሕፍት የሚያረጋግጥ ሲኾን መጽሐፉን (ቁርኣንን) ባንተ ላይ ከፋፍሎ በእውነት አወረደ፡፡ ተውራትንና ኢንጂልንም አውርዷል፡፡'),
('3:4', 87, '(ከቁርኣን) በፊት ለሰዎች መሪ አድርጎ (አወረዳቸው)፡፡ ፉርቃንንም አወረደ፡፡ እነዚያ በአላህ ተዓምራቶች የካዱ ለእነርሱ ብርቱ ቅጣት አላቸው፡፡ አላህም አሸናፊ የመበቀል ባለቤት ነው፡፡'),
('3:5', 87, 'አላህ በምድርም በሰማይም ምንም ነገር በርሱ ላይ አይሰወርም፡፡'),
('3:6', 87, 'እርሱ ያ በማሕጸኖች ውስጥ እንደሚሻ አድርጎ የሚቀርጻችሁ ነው፡፡ ከእርሱ በስተቀር ሌላ አምላክ የለም፡፡ አሸናፊው ጥበበኛው ነው፡፡'),
('3:7', 87, 'እርሱ ያ በአንተ ላይ መጽሐፉን ያወረደ ነው፡፡ ከእርሱ (ከመጽሐፉ) ግልጽ የኾኑ አንቀጾች አልሉ፡፡ እነሱ የመጽሐፉ መሠረቶች ናቸው፡፡ ሌሎችም ተመሳሳዮች አልሉ፡፡ እነዚያማ በልቦቻቸው ውስጥ ጥመት ያለባቸው ሰዎች ማሳሳትን ለመፈለግና ትችቱን ለመፈለግ ከርሱ የተመሳሰለውን ይከታተላሉ፡፡ (ትክክለኛ) ትችቱንም አላህ ብቻ እንጅ ሌላ አያውቀውም፡፡ በዕውቀትም የጠለቁት «በርሱ አምነናል፤ ሁሉም ከጌታችን ዘንድ ነው» ይላሉ፡፡ የአእምሮ ባለቤቶችም እንጅ (ሌላው) አይገሰጽም፡፡'),
('3:8', 87, '(እነሱም ይላሉ)፡- «ጌታችን ሆይ! ቅኑን መንገድ ከመራኸን በኋላ ልቦቻችንን አታዘምብልብን፡፡ ከአንተ ዘንድ የኾነን ችሮታም ለኛ ስጠን፡፡ አንተ በጣም ለጋስ ነህና፡፡»'),
('3:9', 87, '«ጌታችን ሆይ! አንተ በርሱ (ለመምጣቱ) ጥርጥር የሌለበት በኾነ ቀን ሰውን ሁሉ ሰብሳቢ ነህ፡፡ ምንጊዜም አላህ ቀጠሮውን አያፈርስምና፡፡»'),
('3:10', 87, 'እነዚያ የካዱት ሰዎች ገንዘቦቻቸውና ልጆቻቸው ከአላህ (ቅጣት) ምንም አያስጥሉዋቸውም፡፡ እነዚያም እነርሱ የእሳት ማገዶዎች ናቸው፡፡'),
('3:11', 87, '(ልማዳቸው ሁሉ) እንደፈርዖን ቤተሰብና እንደእነዚያ ከበፊታቸው እንደነበሩት ሕዝቦች ልማድ ነው፡፡ በአንቀጾቻችን አስተባበሉ፡፡ አላህም በኃጢአቶቻቸው ያዛቸው፡፡ አላህም ቅጣተብርቱ ነው፡፡'),
('3:12', 87, 'ለእነዚያ ለካዱት ሰዎች በላቸው፡- «በቅርብ ጊዜ ትሸነፉላችሁ፡፡ ወደ ገሀነምም ትሰበሰባላችሁ፡፡ ምንጣፊቱም ምን ትከፋ!»'),
('3:13', 87, '(የበድር ቀን) በተጋጠሙት ሁለት ጭፍሮች ለናንተ በእርግጥ ተዓምር አልለ፡፡ አንደኛዋ ጭፍራ በአላህ መንገድ ትጋደላለች፡፡ ሌላይቱም ከሓዲ ናት፡፡ ከሓዲዎቹ (አማኞቹን) በዓይን አስተያየት እጥፋቸውን ኾነው ያዩዋቸዋል፡፡ አላህም በርዳታው የሚሻውን ሰው ያበረታል፡፡ በዚህ ውስጥ ለማስተዋል ባለቤቶች በእርግጥ መገሰጫ አለበት፡፡'),
('3:14', 87, 'ከሴቶች፣ ከወንዶች ልጆችም፣ ከወርቅና ከብር፣ ከተካመቹ ገንዘቦችም፣ ከተሰማሩ ፈረሶችም፣ ከግመል ከከብትና ከፍየልም፣ ከአዝመራም የኾኑ ፍላጎቶችን መውደድ ለሰዎች ተሸለመ፡፡ ይህ ሁሉ የቅርቢቱ ሕይወት መጠቀሚያ ነው፡፡ አላህም እርሱ ዘንድ መልካም መመለሻ (ገነት) አለ፡፡'),
('3:15', 87, '«ከዚህ ሁሉ ነገር የሚበልጥን ልንገራችሁን» በላቸው፡፡ (እርሱም) «ለእነዚያ ለተጠነቀቁት ሰዎች በጌታቸው ዘንድ በሥራቸው ወንዞች የሚፈሱባቸው ገነቶች በውስጧ ሁልጊዜ ነዋሪዎች ሲኾኑ ንጹሕ የተደረጉ ሚስቶችም፣ ከአላህም የኾነ ውዴታ አላቸው፡፡ አላህም ባሮቹን ተመልካች ነው፡፡»'),
('3:16', 87, '(እነርሱም) እነዚያ፡- «ጌታችን ሆይ! እኛ አመንን ኀጢአቶቻችንንም ለእኛ ማር፤ የእሳትንም ቅጣት ጠብቀን» የሚሉ ናቸው፡፡'),
('3:17', 87, 'ታጋሾች እውነተኞችም ታዛዦችም ለጋሶችና በሌሊት መጨረሻዎች ምሕረትን ለማኞች ናቸው፡፡'),
('3:18', 87, 'አላህ በማስተካከል የቆመ (አስተናባሪ) ሲኾን ከእርሱ በስተቀር ሌላ አምላክ የሌለ መኾኑን መሰከረ፡፡ መላእክቶችና የዕውቀት ባለቤቶችም (እንደዚሁ መሰከሩ)፡፡ ከእርሱ በስተቀር ሌላ አምላክ የለም፡፡ አሸናፊው ጥበበኛው ነው፡፡'),
('3:19', 87, 'አላህ ዘንድ (የተወደደ) ሃይማኖት ኢስላም ብቻ ነው፡፡ እነዚያም መጽሐፉን የተሰጡት ሰዎች በመካከላቸው ላለው ምቀኝነት ዕውቀቱ ከመጣላቸው በኋላ እንጅ አልተለያዩም፡፡ በአላህም አንቀጾች የሚክድ አላህ ምርመራው ፈጣን ነው፡፡'),
('3:20', 87, 'ቢከራከሩህም፡- «ፊቴን ለአላህ ሰጠሁ፤ የተከተሉኝም ሰዎች (እንደዚሁ ለአላህ ሰጡ)» በላቸው፡፡ ለእነዚያም መጽሐፍን ለተሰጡት ሰዎችና ለመሐይሞቹ፡- «ሰለማችሁን» በላቸው፡፡ ቢሰልሙም በእርግጥ ተመሩ፡፡ እምቢ ቢሉም በአንተ ላይ ያለብህ ማድረስ ብቻ ነው፡፡ አላህም ባሮቹን ተመልካች ነው፡፡'),
('3:21', 87, 'እነዚያ በአላህ አንቀጾች የሚክዱ ነቢያትንም ያለ አግባብ የሚገድሉ ከሰዎችም ውስጥ እነዚያን በትክክለኛነት የሚያዙትን የሚገድሉ በአሳማሚ ቅጣት አብስራቸው፡፡'),
('3:22', 87, 'እነዚያ በቅርቢቱና በመጨረሻይቱ ዓለም ሥራዎቻቸው የተበላሹ ናቸው፡፡ ለእነርሱም ምንም ረዳቶች የሏቸውም፡፡'),
('3:23', 87, 'ወደ እነዚያ ከመጽሐፉ (ትምህርት) ዕድልን ወደ ተሰጡት ሰዎች አላየህምን ወደ አላህ መጽሐፍ በመካከላቸው ይፈርድ ዘንድ ይጠራሉ፡፡ ከዚያም ከእነሱ ገሚሶቹ እነርሱ (እውነቱን) የተዉ ኾነው ይሸሻሉ፡፡'),
('3:24', 87, 'ይኸ እነርሱ «እሳት የተቆጠሩ ቀኖችን እንጅ አትነካንም» በማለታቸው ነው፡፡ በሃይማኖታቸውም ይቀጣጥፉት የነበሩት ነገር አታለላቸው፡፡'),
('3:25', 87, 'በርሱ (መምጣት) ጥርጥር የሌለበት በኾነው ቀን በሰበሰብናቸውና ነፍስ ሁሉ የሠራችውን ሥራ በተሞላች ጊዜ እንዴት ይኾናሉ እነርሱም አይበደሉም፡፡'),
('3:26', 87, '(ሙሐመድ ሆይ!) በል፡- «የንግስና ባለቤት የኾንክ አላህ ሆይ! ለምትሻው ሰው ንግሥናን ትሰጣለህ፡፡ ከምትሻውም ሰው ንግሥናን ትገፍፋለህ፡፡ የምትሻውንም ሰው ታልቃለህ፡፡ የምትሻውንም ሰው ታዋርዳለህ፡፡ መልካም ነገር ሁሉ በእጅህ (በችሎታህ) ነው፤ አንተ በነገሩ ሁሉ ላይ ቻይ ነህና፡፡»'),
('3:27', 87, 'ሌሊቱን በቀን ውስጥ ታስገባለህ፡፡ ቀኑንም በሌሊቱ ውስጥ ታስገባለህ፡፡ ሕያውንም ከሙት ውስጥ ታወጣለህ፡፡ ሙትንም ከሕያው ውስጥ ታወጣለህ፡፡ ለምትሻውም ሰው ያለግምት ትሰጣለህ፡፡'),
('3:28', 87, 'ምእምናን ከሓዲዎችን ከምእምናን ሌላ ረዳቶች አድርገው አይያዙ፡፡ ይኼንንም የሚሠራ ሰው ከአላህ (ሃይማኖት) በምንም ውስጥ አይደለም፡፡ ከእነርሱ መጥጠበቅን ብትጠበቁ እንጂ፡፡ አላህም ነፍሱን (ቁጣውን) ያስጠነቅቃችኋል፡፡ መመለሻም ወደ አላህ ብቻ ነው፡፡'),
('3:29', 87, '«በደረቶቻችሁ ውስጥ ያለውን ነገር ብትደብቁ ወይም ብትገልፁት አላህ ያውቀዋል፡፡ በሰማያት ያለውንና በምድርም ያለውን ሁሉ ያውቃል፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው» (በል)፡፡'),
('3:30', 87, 'ነፍስ ሁሉ ከመልካም ነገር የሠራችውን የቀረበ ኾኖ የምታገኝበትን ቀን (አስታውስ)፡፡ ከመጥፎም የሠራችው በርስዋና በርሱ (በኀጢአትዋ) መካከል በጣም የሰፋ ርቀት ቢኖር ትመኛለች፡፡ አላህ ነፍሱን ያስጠነቅቃችኋል፡፡ አላህም ለባሮቹ ሩኅሩኅ ነው፡፡'),
('3:31', 87, 'በላቸው፡- «አላህን የምትወዱ እንደኾናችሁ ተከተሉኝ፤ አላህ ይወዳችኋልና፡፡ ኀጢኣቶቻችሁንም ለናንተ ይምራልና፡፡ አላህም መሓሪ አዛኝ ነው፡፡»'),
('3:32', 87, '«አላህንና መልክተኛውን ታዘዙ፡፡ ብትሸሹም አላህ ከሓዲዎችን አይወድም» በላቸው፡፡'),
('3:33', 87, 'አላህ አደምን፣ ኑሕንም፣ የኢብራሂምንም ቤተሰብ፣ የዒምራንንም ቤተሰብ በዓለማት ላይ መረጠ፡፡'),
('3:34', 87, 'ከፊልዋ ከከፊሉ የኾነች ዝርያ አድርጎ (መረጣት)፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('3:35', 87, 'የዒምራን ባለቤት (ሐና) «ጌታዬ ሆይ! እኔ በሆዴ ውስጥ ያለውን (ፅንስ ከሥራ) ነጻ የተደረገ ሲኾን ለአንተ ተሳልኩ፡፡ ከእኔም ተቀበል አንተ ሰሚው ዐዋቂው ነህና» ባለች ጊዜ (አስታውስ)፡፡'),
('3:36', 87, 'በወለደቻትም ጊዜ፡- «ጌታዬ ሆይ! እኔ ሴት ኾና ወለድኋት፡፡» አላህም የወለደችውን ዐዋቂ ነው፡፡ «ወንድም እንደ ሴት አይደለም፡፡ እኔም መርየም ብዬ ስም አወጣሁላት፡፡ እኔም እስዋንም ዝርያዋንም ከተረገመው ሰይጣን በአንተ እጠብቃቸዋለሁ» አለች፡፡'),
('3:37', 87, 'ጌታዋም በደህና አቀባበል ተቀበላት፡፡ በመልካም አስተዳደግም አፋፋት፡፡ ዘከሪያም አሳደጋት፤ ዘከሪያ በርሷ ላይ በምኹራቧ በገባ ቁጥር እርስዋ ዘንድ ሲሳይን አገኘ፡፡ «መርየም ሆይ! ይህ ለአንቺ ከየት ነው» አላት፡፡ «እርሱ ከአላህ ዘንድ ነው፡፡ አላህ ለሚሻው ሰው ሲሳዩን ያለ ድካም ይሰጣል» አለችው፡፡'),
('3:38', 87, 'እዚያ ዘንድ ዘከሪያ ጌታውን ለመነ፡፡ «ጌታዬ ሆይ! ከአንተ ዘንድ መልካም ዘርን ለኔ ስጠኝ አንተ ጸሎትን ሰሚነህና» አለ፡፡'),
('3:39', 87, 'እርሱም በጸሎት ማድረሻው ክፍል ቆሞ ሲጸልይ መላእክት ጠራችው፡፡ «አላህ በየሕያ ከአላህ በኾነ ቃል የሚያረጋግጥ ጌታም ድንግልም ከደጋጎቹ ነቢይም ሲኾን ያበስርሃል» በማለት (መላእክት ጠራችው)፡፡'),
('3:40', 87, '«ጌታዬ ሆይ! እኔ እርጅና በእርግጥ የደረሰብኝ ስኾን ባልተቤቴም መሐን ስትሆን ለእኔ እንዴት ልጅ ይኖረኛል አለ፡፡ (መልአኩም) እንደዚሁ አላህ የሚሻውን ነገር ይሠራል» አለው፡፡'),
('3:41', 87, '«ጌታዬ ሆይ! ለእኔ ምልክትን አድርግልኝ» አለ፡፡ «ምልክትህ ሦስት ቀን በጥቅሻ ቢኾን እንጅ ሰዎችን አለማናገርህ ነው፡፡ ጌታህንም በብዙ አውሳ፡፡ በማታና በጧትም አወድሰው» አለው፡፡'),
('3:42', 87, 'መላእክትም ያሉትን (አስታውስ)፡፡ «መርየም ሆይ! አላህ በእርግጥ መረጠሸ፡፡ አነጻሽም፡፡ በዓለማት ሴቶችም ላይ መረጠሽ፡፡»'),
('3:43', 87, '«መርየም ሆይ! ለጌታሽ ታዘዢ፡፡ ስገጂም፡፡ ከአጎንባሾቹም ጋር አጎንብሺ፡፡»'),
('3:44', 87, 'ይኸ ወደ አንተ የምናወርደው የኾነ ከሩቅ ወሬዎች ነው፡፡ መርየምንም ማን እንደሚያሳድግ ብርኦቻቸውን (ለዕጣ) በጣሉ ጊዜ እነሱ ዘንድ አልነበርክም፡፡ በሚከራከሩም ጊዜ እነሱ ዘንድ አልነበርክም፡፡'),
('3:45', 87, 'መላእክት ያሉትን (አስታውስ)፡- «መርየም ሆይ! አላህ ከርሱ በኾነው ቃል ስሙ አልመሲሕ ዒሳ የመርየም ልጅ በዚህ ዓለምና በመጨረሻውም ዓለም የተከበረ ከባለሟሎችም በኾነ (ልጅ) ያበስርሻል፡፡»'),
('3:46', 87, '«በሕፃንነቱና በከፈኒሳነቱ ሰዎቹን ያነጋግራል፡፡ ከመልካሞቹም ነው» (አላት)፡፡'),
('3:47', 87, '፡-ጌታዬ ሆይ! ሰው ያልነካኝ ስኾን ለኔ እንዴት ልጅ ይኖረኛል አለች፡፡ ነገሩ እንዳልሽው ነው፡፡ አላህ የሚሻውን ይፈጥራል፡፡ አንዳችን በሻ ጊዜ ለርሱ ኹን ይለዋል፤ ወዲውኑም ይኾናል አላት፡፡'),
('3:48', 87, 'ጽሕፈትንና ጥበብንም ተውራትንና ኢንጂልንም ያስተምረዋል፡፡'),
('3:49', 87, 'ወደ እስራኤልም ልጆች መልክተኛ ያደርገዋል፡፡ (ይላልም)፡- «እኔ ከጌታዬ ዘንድ በተዓምር ወደ እናንተ መጣሁ፡፡ እኔ ለናንተ ከጭቃ እንደ ወፍ ቅርፅ እፈጥራለሁ፡፡ በርሱም እተነፍስበታለሁ፡፡ በአላህም ፈቃድ ወፍ ይኾናል፡፡ በአላህም ፈቃድ ዕውር ኾኖ የተወለደን፣ ለምጸኛንም አድናለሁ፡፡ ሙታንንም አስነሳለሁ፡፡ የምትበሉትንና በቤታችሁ የምታደልቡትንም ሁሉ እነግራችኋለሁ፡፡ የምታምኑ እንደኾናችሁ ለእናንተ በዚህ ውስጥ በእርግጥ ተዓምር አለበት፡፡»'),
('3:50', 87, '«ከተውራትም ከእኔ በፊት ያለውን ያረጋገጥሁ ስኾን የዚያንም በእናንተ ላይ እርም የተደረገውን ከፊል ለእናንተ እፈቅድ ዘንድ (መጣኋችሁ) ከጌታችሁም በኾነ ታምር መጣሁዋችሁ፡፡ አላህንም ፍሩ፤ ታዘዙኝም፡፡»'),
('3:51', 87, '«አላህ ጌታዬና ጌታችሁ ነው፤ ስለዚህ ተገዙት፤ ይህ ቀጥተኛ መንገድ ነው» (አላቸው)፡፡'),
('3:52', 87, 'ዒሳ ከነርሱ ክህደት በተሰማውም ጊዜ፡- «ወደ አላህ (ተጨምረው) ረዳቶቼ እነማን ናቸው» አለ፤ ሐዋርያት፡- «እኛ የአላህ ረዳቶች ነን፤ በአላህ አምነናል፤ እኛም ትክክለኛ ታዛዦች መኾናችንን መስክር» አሉ፡፡'),
('3:53', 87, '«ጌታችን ሆይ! ባወረድኸው አመንን፤ መልክተኛውንም ተከተልን፤ ከመስካሪዎችም ጋር መዝግበን» (አሉ)፡፡'),
('3:54', 87, '(አይሁዶችም) አደሙ አላህም አድማቸውን መለሰባቸው፡፡ አላህም ከአድመኞች ሁሉ በላጭ ነው፡፡'),
('3:55', 87, 'አላህም ባለ ጊዜ (አስታውስ)፡፡ ዒሳ ሆይ! እኔ ወሳጂህ ወደ እኔም አንሺህ ነኝ፡፡ ከነዚያም ከካዱት ሰዎች አጥሪህ ነኝ እነዚያንም የተከተሉህን እስከ ትንሣኤ ቀን ድረስ ከነዚያ ከካዱት በላይ አድራጊ ነኝ፡፡ ከዚያም መመለሻችሁ ወደእኔ ነው፡፡ በርሱ ትለያዩበትም በነበራችሁት ነገር በመካከላችሁ እፈርዳለሁ፡፡'),
('3:56', 87, '«እነዚያማ የካዱትን ሰዎች በቅርቢቱ ዓለምና በመጨረሻይቱ ዓለም ብርቱን ቅጣት እቀጣቸዋለሁ፡፡ ለእነርሱም ምንም ረዳቶች የሏቸውም፡፡»'),
('3:57', 87, 'እነዚያም ያመኑትማ መልካም ሥራዎችንም የሠሩት ምንዳዎቻቸውን ይሞላላቸዋል፡፡ አላህም በዳዮችን አይወድም፡፡'),
('3:58', 87, 'ይህ ከተዓምራቶችና ጥበብን ከያዘው ተግሳጽ ሲኾን በአንተ ላይ እናነበዋለን፡፡'),
('3:59', 87, 'አላህ ዘንድ የዒሳ ምሳሌ እንደ አዳም ብጤ ነው፡፡ ከዐፈር ፈጠረው፡፡ ከዚያም ለርሱ (ሰው) «ኹን» አለው፤ ኾነም፡፡'),
('3:60', 87, 'ይህ ከጌታህ ዘንድ የኾነ እውነት ነው፡፡ ከተጠራጣሪዎቹም አትኹን፡፡'),
('3:61', 87, 'ዕውቀቱም ከመጣልህ በኋላ በርሱ (በዒሳ) የተከራከሩህን ሰዎች «ኑ፤ ልጆቻችንንና ልጆቻችሁን፣ ሴቶቻችንንና ሴቶቻችሁንም፣ ነፍሶቻችንንና ነፍሶቻችሁንም እንጥራ፡፡ ከዚያም አጥብቀን አላህን እንለምን፤ የአላህንም ቁጣ በውሸታሞቹ ላይ እናድርግ» በላቸው፡፡'),
('3:62', 87, 'ይህ እርሱ በእርግጥ እውነተኛ ታሪክ ነው፡፡ አምላክም ከአላህ በስተቀር ምንም የለም፡፡ አላህም እርሱ በእርግጥ አሸናፊው ጥበበኛው ነው፡፡'),
('3:63', 87, '(ከማመን) እንቢ ቢሉም አላህ አጥፊዎቹን በእርግጥ ዐዋቂ ነው፡፡'),
('3:64', 87, 'የመጽሐፉ ባለቤቶች ሆይ! በእኛና በእናንተ መካከል ትክክል ወደ ኾነች ቃል ኑ፡፡ (እርሷም) አላህን እንጅ ሌላን ላንገዛ፣ በርሱም ምንንም ላናጋራ፣ ከፊላችንም ከፊሉን ከአላህ ሌላ አማልክት አድርጎ ላይይዝ ነው፤ በላቸው፡፡ እምቢ ቢሉም፡- እኛ ሙስሊሞች መኾናችንን መስክሩ በሏቸው፡፡'),
('3:65', 87, 'እናንተ የመጽሐፉ ሰዎች ሆይ! በኢብራሂም ለምን ትከራከራላችሁ ተውራትና ኢንጂልም ከርሱ በኋላ እንጅ አልተወረዱም፡፡ ልብ አታደርጉምን በላቸው፡፡'),
('3:66', 87, 'ንቁ! እናንተ እነዚያ ለእናንተ በርሱ ዕውቀት ባላችሁ ነገር የተከራከራችሁ ናችሁ፡፡ ታዲያ ለእናንተ በርሱ ዕውቀት በሌላችሁ ነገር ለምን ትከራከራላችሁ አላህም ያውቃል፡፡ እናንተ ግን አታውቁም፡፡'),
('3:67', 87, 'ኢብራሂም ይሁዳዊም ክርስቲያንም አልነበረም፡፡ ግን ወደ ቀጥተኛው ሃይማኖት የተዘነበለ ሙስሊም ነበረ፡፡ ከአጋሪዎችም አልነበረም፡፡'),
('3:68', 87, 'ከሰው ሁሉ በኢብራሂም ተገቢዎቹ እነዚያ የተከተሉትና ይህ ነቢይ እነዚያም ያመኑት ናቸው፡፡ አላህም የምእምናን ረዳት ነው፡፡'),
('3:69', 87, 'ከመጽሐፉ ባለቤቶች የኾኑ ጭፍሮች ነፍሶቻቸውን እንጂ የማያሳስቱ ሲኾኑ ሊያሳስቱዋችሁ ተመኙ ግን አያውቁም፡፡'),
('3:70', 87, 'የመጽሐፉ ባለቤቶች ሆይ! እናንተ የምታውቁ ስትኾኑ በአላህ አንቀጾች ለምን ትክዳላችሁ'),
('3:71', 87, '«የመጽሐፉ ሰዎች ሆይ! እውነቱን በውሸት ለምን ትቀላቅላላችሁ እውነቱንም እናንተ የምታውቁ ስትኾኑ ለምን ትደብቃላችሁ»'),
('3:72', 87, 'ከመጽሐፉ ባለቤቶች የኾኑ ጭፍሮችም አሉ፡- «በነዚያ በአመኑት ላይ በተወረደው (ቁርኣን) በቀኑ መጀመሪያ ላይ እመኑበት፡፡ በመጨረሻውም ካዱት፡፡ እነርሱ ሊመለሱ ይከጀላልና፡፡»'),
('3:73', 87, 'እናንተ የተሰጣችሁትን ብጤ አንድም ሰው መሰጠቱን ወይም እጌታችሁ ዘንድ የሚከራከሩዋችሁ መኾንን ሃይማኖታችሁን ለተከተለ ሰው ቢኾን እንጂ አትመኑ (አትግለጹ አሉ)፡፡ «መምሪያው የአላህ መምሪያ ብቻ ነው» በላቸው፡፡ «ችሮታ በአላህ እጅ ነው፡፡ ለሚሻው ይሰጠዋል፡፡ አላህም ችሮታው ሰፊ ዐዋቂ ነው» በላቸው፡፡'),
('3:74', 87, 'በችሮታው (በነቢይነት) የሚሻውን ይመርጣል፡፡ አላህም የታላቅ ችሮታ ባለቤት ነው፡፡'),
('3:75', 87, 'ከመጽሐፉ ሰዎችም በብዙ ገንዘብ ብታምነው ወዳንተ የሚመልስ ሰው አልለ፡፡ ከእነሱም በአንድ ዲናር እንኳ ብታምነው፤ ሁል ጊዜ በርሱ ላይ የምትጠባበቅ ካልኾንክ በስተቀር የማይመልስ ሰው አልለ፡፡ «ይህ በመሃይምናን (በምናደርገው) በእኛ ላይ ምንም መንገድ የለብንም» ስለሚሉ ነው፡፡ እነርሱ እያወቁም በአላህ ላይ ውሸትን ይናገራሉ፡፡'),
('3:76', 87, 'አይደለም (አለባቸው እንጅ)፡፡ በቃል ኪዳኑ የሞላና የተጠነቀቀ ሰው አላህ ጥንቁቆችን ይወዳል፡፡'),
('3:77', 87, 'እነዚህ በአላህ ቃል ኪዳንና በመሐላዎቻቸው ጥቂትን ዋጋ የሚለውጡ እነዚያ በመጨረሻይቱ ዓለም ምንም ዕድል የላቸውም፡፡ በትንሣኤ ቀንም አላህ አያነጋግራቸውም፡፡ ወደ እነርሱም አይመለከትም አያነጻቸውምም፡፡ ለነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('3:78', 87, 'ከእነሱም እርሱ ከመጽሐፉ ያይደለ ሲኾን ከመጽሐፉ መኾኑን እንድታስቡ በመጽሐፉ ምላሶቻቸውን የሚያጣምሙ ክፍሎች አሉ፡፡ እርሱ ከአላህ ዘንድ ያልኾነ ሲኾን «እርሱ ከአላህ ዘንድ ነውም» ይላሉ፡፡ እነርሱ የሚያውቁ ሲኾኑም በአላህ ላይ ውሸትን ይናገራሉ፡፡'),
('3:79', 87, 'ለማንም ሰው አላህ መጽሐፍንና ጥበብን ነቢይነትንም ሊሰጠውና ከዚያም ለሰዎች «ከአላህ ሌላ ለእኔ ባሮች ኾኑ» ሊል አይገባውም፡፡ «ግን መጽሐፍን የምታስተምሩ በነበራችሁትና የምታጠኑም በነበራችሁት በዕውቀታችሁ ሠሪዎች ኹኑ» (ይላቸዋል)፡፡'),
('3:80', 87, 'መላእክትንና ነቢያትንም አማልክቶች አድርጋችሁ እንድትይዙ ሊያዛችሁ (አይገባውም)፡፡ እናንተ ሙስሊሞች ከኾናችሁ በኋላ በክህደት ያዛችኋልን'),
('3:81', 87, 'አላህ የነቢያትን ቃል ኪዳን ከመጽሐፍና ከጥበብ ሰጥቻችሁ ከዚያም «ከእናንተ ጋር ላለው (መጽሐፍ) የሚያረጋግጥ መልክተኛ ቢመጣላችሁ በርሱ በእርግጥ እንደምታምኑበት በእርግጥም እንድትረዱት ሲል በያዘ ጊዜ (አስታውስ)፡፡ አረጋገጣችሁን በዚህም ላይ ኪዳኔን ያዛችሁምን» አላቸው፡፡ «አረጋገጥን» አሉ፡፡ «እንግዲያስ መስክሩ፤ እኔም ከእናንተ ጋር ከመስካሪዎቹ ነኝ» አላቸው፡፡'),
('3:82', 87, 'ከዚህም በኋላ የሸሹ ሰዎች እነዚያ እነሱ አመጸኞቹ ናቸው፡፡'),
('3:83', 87, 'በሰማያትና በምድር ያሉ ሁሉ፤ በውድም በግድም ለርሱ የታዘዙ ወደርሱም የሚመለሱ ሲኾኑ (ከሓዲዎች) ከአላህ ሃይማኖት ሌላን ይፈልጋሉን'),
('3:84', 87, '«በአላህ አመንን፡፡ በእኛ ላይ በተወረደውም (በቁርኣን)፣ በኢብራሂምና በኢስማዒልም፣ በኢስሓቅም፣ በያዕቆብም፣ በነገዶችም ላይ በተወረደው፤ ለሙሳና ለዒሳም ለነቢያትም ሁሉ ከጌታቸው በተሰጠው (አመንን)፡፡ ከእነርሱ መካከል አንድንም አንለይም፡፡ እኛ ለእርሱ ታዛዦች ነን» በል፡፡'),
('3:85', 87, 'ከኢስላም ሌላ ሃይማኖትን የሚፈልግ ሰው ፈጽሞ ከርሱ ተቀባይ የለውም፡፡ እርሱም በመጨረሻይቱ ዓለም ከከሳሪዎቹ ነው፡፡'),
('3:86', 87, 'ከእምነታቸውና መልክተኛውም እውነት መኾኑን ከመሰከሩ የተብራሩ አንቀጾችም ከመጡላቸው በኋላ የካዱን ሕዝቦች አላህ እንዴት ያቀናል! አላህ በዳዮችንም ሕዝቦች አያቀናም፡፡'),
('3:87', 87, 'እነዚያ ቅጣታቸው የአላህና የመላእክት የሰዎችም ሁሉ ርግማን በእነሱ ላይ መኾን ነው፡፡'),
('3:88', 87, 'በውስጧ ዘውታሪዎች ሲኾኑ ቅጣቱም ከነሱ ላይ አይቃለልላቸውም፡፡ እነሱም ቀን አይስሰጡም፡፡'),
('3:89', 87, 'እነዚያ ከዚህ በኋላ ንስሓ የገቡና (ሥራቸውን) ያሳመሩ ሲቀሩ፡፡ (እነዚህንስ ይምራቸዋል)፤ አላህ መሓሪ አዛኝ ነውና፡፡'),
('3:90', 87, 'እነዚያ ከእምነታቸው በኋላ የካዱ ከዚያም ክህደትን የጨመሩ ጸጸታቸው ፈጽሞ ተቀባይ የላትም፡፡ እነዚያም የተሳሳቱ እነርሱ ናቸው፡፡'),
('3:91', 87, 'እነዚያ የካዱና እነርሱም በክህደታቸው ላይ እንዳሉ የሞቱ ከእነሱ ከአንዳቸው በምድር ሙሉ የኾነ ወርቅ (ቢኖረውና) በርሱ ቢበዥበትም እንኳ ፈጽሞ ተቀባይን አያገኝም፡፡ እነዚያ ለእነርሱ የሚያሰቃይ ቅጣት አላቸው፡፡ ለነርሱም ምንም ረዳቶች የሏቸውም፡፡'),
('3:92', 87, 'የምትወዱትን እስከምትለግሱ ድረስ በጎን ሥራ (ዋጋውን) አታገኙም፡፡ ከምንም ነገር ብትለግሱ አላህ ያውቀዋል፡፡'),
('3:93', 87, 'ተውራት ከመወረድዋ በፊት እስራኤል በራሱ ላይ እርም ካደረገው ነገር በስተቀር ምግብ ሁሉ ለእስራኤል ልጆች የተፈቀደ ነበር፡፡ እውነተኞችም እንደኾናችሁ ተውራትን አምጡ አንብቡዋትም በላቸው፡፡'),
('3:94', 87, 'ከዚህም በኋላ በአላህ ላይ ውሸትን የቀጣጠፉ ሰዎች እነዚያ እነርሱ በደለኞች ናቸው፡፡'),
('3:95', 87, '«አላህ እውነትን ተናገረ፡፡ የኢብራሂምንም መንገድ ወደ እውነት ያዘነበለ ሲኾን ተከተሉ፡፡ ከአጋሪዎቹም አልነበረም» በላቸው፡፡'),
('3:96', 87, 'ለሰዎች (መጸለያ) መጀመሪያ የተኖረው ቤት ብሩክና ለዓለማት ሁሉ መመሪያ ሲኾን ያ በበካህ (በመካ) ያለው ነው፡፡'),
('3:97', 87, 'በውስጡ ግልጽ የኾኑ ተዓምራቶች የኢብራሒምም መቆሚያ አልለ፡፡ ወደ ውስጡ የገባ ሰው ጸጥተኛ ይኾናል፡፡ ለአላህም በሰዎች ላይ ወደርሱ መኼድን በቻለ ሁሉ ላይ ቤቱን መጎብኘት ግዴታ አለባቸው፡፡ የካደም ሰው አላህ ከዓለማት ሁሉ የተብቃቃ ነው፡፡'),
('3:98', 87, '«የመጽሐፉ ባለቤቶች ሆይ! አላህ በምትሠሩት ሁሉ ላይ ዐዋቂ ሲኾን በአላህ ተዓምራት ለምን ትክዳላችሁ» በላቸው፡፡'),
('3:99', 87, '«የመጽሐፉ ሰዎች ሆይ! እናንተ መስካሪዎች ኾናችሁ ከአላህ መንገድ መጥመሟን የምትፈልጓት ስትኾኑ ያመነን ሰው ለምን ትከለክላላችሁ አላህም ከምትሰሩት ነገር ሁሉ ዘንጊ አይደለም» በላቸው፡፡'),
('3:100', 87, 'እናንተ ያመናችሁ ሆይ! ከነዚያ መጽሐፉን ከተሰጡት ሰዎች ከፊሉን ብትታዘዙ ከእምነታችሁ በኋላ ከሓዲዎች አድርገው ይመልሱዋችኋል፡፡'),
('3:101', 87, 'የአላህም አንቀጾች በእናንተ ላይ የሚነበቡ ሲኾኑ መልክተኛውም በውስጣችሁ ያለ ሲኾን እናንተ እንዴት ትክዳላችሁ በአላህም የሚጠበቅ ሰው ወደ ቀጥተኛው መንገድ በእርግጥ ተመራ፡፡'),
('3:102', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ተገቢውን መጠንቀቅ ተጠንቀቁት፡፡ እናንተም ሙስሊሞች ኾናችሁ እንጅ አትሙቱ፡፡'),
('3:103', 87, 'የአላህንም (የማመን) ገመድ ሁላችሁም ያዙ፡፡ አትለያዩም፡፡ ጠበኞችም በነበራችሁ ጊዜ በእናንተ ላይ (የዋለውን) የአላህን ጸጋ አስታውሱ፡፡ በልቦቻችሁም መካከል አስማማ፡፡ በጸጋውም ወንድማማቾች ኾናችሁ፡፡ በእሳት ጉድጓድ አፋፍም ላይ ነበራችሁ፡፡ ከእርስዋም አዳናችሁ፡፡ እንደዚሁ ትመሩ ዘንድ አላህ ለእናንተ አንቀጾቹን ያብራራል፡፡'),
('3:104', 87, 'ከናንተም ወደ በጎ ነገር የሚጠሩ በመልካም ሥራም የሚያዙ ከክፉ ነገርም የሚከለክሉ ሕዝቦች ይኑሩ፡፡ እነዚያም እነሱ የሚድኑ ናቸው፡፡'),
('3:105', 87, 'እንደነዚያም ግልጽ ተዓምራት ከመጣላቸው በኋላ እንደተለያዩትና እንደ ተጨቃጨቁት አትኹኑ፡፡ እነዚያም ለእነርሱ ታላቅ ቅጣት አላቸው፡፡'),
('3:106', 87, 'ፊቶች የሚያበሩበትን ፊቶችም የሚጠቁሩበትን ቀን (አስታውስ)፡፡ እነዚያ ፊቶቻቸው የጠቆሩትማ «ከእምነታችሁ በኋላ ካዳችሁን ትክዱት በነበራችሁት ነገር ቅጣቱን ቅመሱ» (ይባላሉ)፡፡'),
('3:107', 87, 'እነዚያም ፊቶቻቸው ያበሩትማ በአላህ ችሮታ (ገነት) ውስጥ ናቸው፡፡ እነርሱ በውስጥ ዘውታሪዎች ናቸው፡፡'),
('3:108', 87, 'ይህች በአንተ ላይ በእውነት የምናነባት ስትኾን የአላህ ተዓምራት ናት፡፡ አላህም ለዓለማት በደልን የሚሻ አይደለም፡፡'),
('3:109', 87, 'በሰማያት ያለውና በምድር ያለውም ሁሉ የአላህ ነው፡፡ ነገሮችም ሁሉ ወደ አላህ ብቻ ይመለሳሉ፡፡'),
('3:110', 87, 'ለሰዎች ከተገለጸች ሕዝብ ሁሉ በላጭ ኾናችሁ በጽድቅ ነገር ታዛላችሁ፤ ከመጥፎም ነገር ታዛላችሁ፤ በአላህም (አንድነት) ታምናላችሁ፡፡ የመጽሐፉም ሰዎች ባመኑ ኖሮ ለነርሱ የተሻለ በኾነ ነበር፡፡ ከነርሱ አማኞች አሉ፡፡ አብዛኞቻቸው ግን አመጸኞች ናቸው፡፡'),
('3:111', 87, 'ማስከፋትን እንጅ ፈጽሞ አይጎዱዋችሁም፡፡ ቢዋጉዋችሁም ጀርባዎችን ያዙሩላችኋል (ይሸሻሉ)፡፡ ከዚያም አይረዱም፡፡'),
('3:112', 87, 'የትም በተገኙበት ስፍራ ከአላህ በኾነ ቃል ኪዳን ከሰዎችም በኾነ ቃል ኪዳን (የተጠበቁ) ካልኾኑ በስተቀር በነርሱ ላይ ውርደት ተመታችባቸው፡፡ ከአላህም በኾነ ቁጣ ተመለሱ፡፡ በእነርሱም ላይ ድኽነት ተመታችባቸው፡፡ ይኸ እነርሱ በአላህ ተዓምራት ይክዱ ስለ ነበሩና ነቢያትንም ያለ ሕግ ይገድሉ ስለነበሩ ነው፡፡ ይህ በማመጻቸውና ወሰንን ይተላለፉ ስለነበሩ ነው፡፡'),
('3:113', 87, '(የመጽሐፉ ሰዎች ሁሉ) እኩል አይደሉም፡፡ ከመጽሐፉ ሰዎች ቀጥ ያሉ በሌሊት ሰዓቶች እነርሱ የሚሰግዱ ኾነው የአላህን አንቀጾች የሚያነቡ ሕዝቦች አሉ፡፡'),
('3:114', 87, 'በአላህና በመጨረሻው ቀን ያምናሉ፡፡ በጽድቅ ነገርም ያዛሉ፡፡ ከመጥፎ ነገርም ይከለክላሉ፡፡ በበጎ ሥራዎችም ይጣደፋሉ፡፡ እነዚያም ከመልካሞቹ ናቸው፡፡'),
('3:115', 87, 'ከበጎ ሥራ ማንኛውንም ቢሠሩ አይካዱትም፡፡ አላህም ጥንቁቆቹን ዐዋቂ ነው፡፡'),
('3:116', 87, 'እነዚያ የካዱት ሰዎች ገንዘቦቻቸውና ልጆቻቸው ከአላህ (ቅጣት) እነርሱን ምንንም አያድኑዋቸውም፡፡ እነዚያም የእሳት ጓዶች ናቸው፡፡ እነርሱ በእርስዋ ውስጥ ዘውታሪዎች ናቸው፡፡'),
('3:117', 87, 'የዚያ በዚህች በቅርቢቱ ሕይወት የሚለግሱት ነገር ምሳሌ በውስጧ ውርጭ ያለባት ነፋስ ነፍሶቻቸውን የበደሉን ሕዝቦች አዝመራ እንደነካችና እንዳጠፋችው ብጤ ነው፡፡ አላህም አልበደላቸውም ግን ነፍሶቻቸውን ይበድላሉ፡፡'),
('3:118', 87, 'እናንተ ያመናችሁ ሆይ! ከእናንተ ሌላ ምስጢረኛን አትያዙ፡፡ ማበላሸትን አይገቱላችሁም፡፡ ጉዳታችሁን ይወዳሉ፡፡ ጥላቻይቱ ከአፎቻቸው በእርግጥ ተገለጸች፡፡ ልቦቻቸውም የሚደብቁት ይበልጥ ትልቅ ነው፡፡ ልብ የምታደርጉ እንደኾናችሁ ለእናንተ ማብራሪያዎችን በእርግጥ ገለጽን፡፡'),
('3:119', 87, 'እነሆ እናንተ እነዚያ የምትወዱዋቸው ናችሁ፡፡ (እነሱ) ግን አይወዱዋችሁም፡፡ በመጽሐፉም በሁሉም ታምናላችሁ፡፡ ባገኙዋችሁም ጊዜ «አምነናል» ይላሉ፡፡ ባገለሉም ጊዜ ከቁጭታቸው የተነሳ በእናንተ ላይ ዐጽቆቻቸውን ይነክሳሉ፡፡ «በቁጭታችሁ ሙቱ፤ አላህ ልቦች የቋጠሩትን ዐዋቂ ነውና» በላቸው፡፡'),
('3:120', 87, 'ደግ ነገር ብትነካችሁ ታስከፋቸዋለች፡፡ መጥፎም ነገር ብታገኛችሁ በእርሷ ይደሰታሉ፡፡ ብትታገሱና ብትጠነቀቁም ተንኮላቸው ምንም አይጎዳችሁም፡፡ አላህ በሚሠሩት ሁሉ (በዕውቀቱ) ከባቢ ነውና፡፡'),
('3:121', 87, 'ለምእምኖቹም ለውጊያ ሥራዎችን የምታዘጋጅ ኾነህ ከቤተሰብህ በማለድክ ጊዜ (አስታውስ)፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('3:122', 87, 'ከእናንተ ሁለት ጭፍሮች አላህ ረዳታቸው ሲኾን ለመፍራት ባሰቡ ጊዜ (አስታውስ)፡፡ በአላህም ላይ ብቻ ምእምናኖች ይመኩ፡፡'),
('3:123', 87, 'በበድርም እናንተ ጥቂቶች ኾናችሁ ሳለ አላህ በእርግጥ ረዳችሁ፡፡ አላህንም ታመሰግኑ ዘንድ ፍሩት፡፡'),
('3:124', 87, 'ለምእምናን «ጌታችሁ በሦስት ሺህ መላእክት የተወረዱ ሲኾኑ ቢረዳችሁ አይበቃችሁምን» በምትል ጊዜ (አስታውስ)፡፡'),
('3:125', 87, '«አዎን ብትታገሱና ብትጠነቀቁ ከዚህም ፍጥነታቸው (ጠላቶቻችሁ) ቢመጡባችሁ ጌታችሁ ምልክት ባላቸው አምስት ሺህ መላእክት ይረዳችኋል፡፡»'),
('3:126', 87, 'አላህም (እርዳታውን) ለእናንተ ብስራትና ልቦቻችሁ በእርሱ እንዲረኩ እንጂ አላደረገውም፡፡ ድልም መንሳት አሸናፊ ጥበበኛ ከኾነው አላህ ዘንድ እንጅ ከሌላ አይደለም፡፡'),
('3:127', 87, '(ድልን ያጎናጸፋችሁ) ከእነዚያ ከካዱት ከፊልን ሊቆርጥ (ሊያጠፋ) ወይም ሊያዋርዳቸውና ያፈሩ ኾነው እንዲመለሱ ነው፡፡'),
('3:128', 87, '(አላህ) በእነርሱ ላይ ይቅርታ እስኪያደርግ ወይም እነርሱ በዳዮች ናቸውና እስኪቀጣቸው ድረስ ላንተ ከነገሩ ምንም የለህም፡፡'),
('3:129', 87, 'በሰማያት ያለው በምድርም ያለው ሁሉ የአላህ ነው፡፡ ለሚሻው ሰው ይምራል፤ የሚሻውንም ሰው ይቀጣል፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('3:130', 87, 'እናንተ ያመናችሁ ሆይ! አራጣን የተነባበሩ እጥፎች ሲኾኑ አትብሉ፡፡ ትድኑም ዘንድ አላህን ፍሩ፡፡'),
('3:131', 87, 'ያችንም ለከሓዲዎች የተደገሰችውን እሳት ተጠንቀቁ፡፡'),
('3:132', 87, 'ይታዘንላችሁም ዘንድ አላህንና መልክተኛውን ታዘዙ፡፡'),
('3:133', 87, 'ከጌታችሁ ወደ ኾነችም ምሕረትና ስፋትዋ እንደ ሰማያትና ምድር ወደ ኾነች ገነት አላህን ለሚፈሩ የተዘጋጀች ስትኾን ተቻኮሉ፡፡'),
('3:134', 87, 'ለእነዚያ በድሎትም ኾነ በችግር ለሚለግሱት፣ ቁጭትንም ገቺዎች ከሰዎችም ይቅርታ አድራጊዎች ለኾኑት (ተደግሳለች)፡፡ አላህም በጎ ሠሪዎችን ይወዳል፡፡'),
('3:135', 87, 'ለእነዚያም መጥፎ ሥራን በሠሩ ወይም ነፍሶቻቸውን በበደሉ ጊዜ አላህን የሚያስታውሱና ለኀጢአቶቻቸው ምሕረትን የሚለምኑ ለኾኑት ከአላህም ሌላ ኀጢአቶችን የሚምር አንድም የለ፡፡ (በስሕተት) በሠሩትም ላይ እነርሱ የሚያውቁ ሲኾኑ የማይዘወትሩ ለኾኑት (ተደግሳለች)፡፡'),
('3:136', 87, 'እነዚያ ምንዳቸው ከጌታቸው ምሕረትና በውስጣቸው ዘውታሪዎች ሲኾኑ በሥሮቻቸው ወንዞች የሚፈሱባቸው ገነቶችም ናቸው፡፡ የሠሪዎችም ምንዳ (ገነት) ምንኛ አማረች!፡፡'),
('3:137', 87, 'ከእናንተ በፊት ድርጊቶች በእርግጥ አልፈዋል፡፡ በምድርም ላይ ኺዱ፡፡ የአስተባባዮችም ፍጻሜ እንዴት እንደነበረ ተመልከቱ፡፡'),
('3:138', 87, 'ይህ ለሰዎች ገላጭ፤ ለጥንቁቆች መሪና ገሳጭ ነው፡፡'),
('3:139', 87, 'እናንተም የበላዮች ስትኾኑ ምእመናን እንደኾናችሁ አትስነፉ፤ አትዘኑም፡፡'),
('3:140', 87, 'ቁስል ቢያገኛችሁ ሰዎቹንም መሰሉ ቁስል አግኝቷቸዋል፡፡ ይኽችንም ቀናት በሰዎች መካከል እናዘዋውራታለን፡፡ (እንድትገሰጹና) አላህም እነዚያን ያመኑትን እንዲያውቅ (እንዲለይ) ከእናንተም ሰማዕታትን እንዲይዝ ነው፡፡ አላህም በዳዮችን አይወድም፡፡'),
('3:141', 87, 'አላህም እነዚያን ያመኑትን (ከኀጢአት) ሊያነጻና ከሓዲዎችንም ሊያጠፋ ነው፡፡'),
('3:142', 87, 'በእውነቱ አላህ ከናንተ እነዚያን የታገሉትን ሳያውቅ (ሳይለይ) ታጋሾቹንም ሳያውቅ ገነትን ልትገቡ አሰባችሁን'),
('3:143', 87, '(በጦርነት ላይ) መሞትንም ሳታገኙት በፊት በርግጥ የምትመኙት ነበራችሁ፡፡ እናንተም የምትመለከቱ ስትኾኑ በርግጥ አያችሁት (ታዲያ ለምን ሸሻችሁ)'),
('3:144', 87, 'ሙሐመድም ከበፊቱ መልክተኞች በእርግጥ ያለፉ የኾነ መልክተኛ እንጅ ሌላ አይደለም፡፡ ታዲያ ቢሞት ወይም ቢገደል ወደ ኋላችሁ ትገለበጣላችሁን ወደኋላው የሚገለበጥም ሰው አላህን ምንም አይጎዳም፡፡ አላህም አመስጋኞቹን በእርግጥ ይመነዳል፡፡'),
('3:145', 87, 'ለማንኛይቱም ነፍስ በአላህ ፍርድ ቢኾን እንጅ ልትሞት አይገባትም፡፡ (ጊዜውም) ተወስኖ ተጽፏል፡፡ የቅርቢቱንም ምንዳ የሚፈልግ ሰው ከእርስዋ እንሰጠዋለን፡፡ የመጨረሻይቱንም ምንዳ የሚፈልግ ሰው ከእርስዋ እንሰጠዋለን፤ አመስጋኞችንም በእርግጥ እንመነዳለን፡፡'),
('3:146', 87, 'ከነቢይም ብዙ ሊቃውንት ከርሱ ጋር ኾነው የተዋጉ ብዙ ናቸው፡፡ በአላህም መንገድ ለሚደርስባቸው ነገር አልፈሩም፤ አልደከሙምም፡፡ (ለጠላት) አልተዋረዱምም፡፡ አላህም ትዕግስተኞችን ይወዳል፡፡'),
('3:147', 87, 'ንግግራቸውም «ጌታችን ሆይ! ኃጢአቶቻችንንና በነገራችን ሁሉ ወሰን ማለፋችንን ለእኛ ማር፣ ይዞታችንንም አደላድል፣ በከሓዲዎችም ሕዝቦች ላይ እርዳን» ማለታቸው እንጅ ሌላ አልነበረም፡፡'),
('3:148', 87, 'አላህም የቅርቢቱን ምንዳና የመጨረሻይቱን መልካም ምንዳ ሰጣቸው፡፡ አላህም በጎ አድራጊዎችን ይወዳል፡፡'),
('3:149', 87, 'እናንተ ያመናችሁ ሆይ! እነዚያን የካዱትን ሰዎች ብትታዘዙ ወደ ኋላችሁ ይመልሱዋችኋል፡፡ ከሳሪዎች ኾናችሁም ትገለበጣላችሁ፡፡'),
('3:150', 87, '(አይረዷችሁም)፤ ይልቁን አላህ ብቻ ረዳታችሁ ነው፡፡ እርሱም ከረዳቶች ሁሉ በላጭ ነው፡፡'),
('3:151', 87, 'በእነዚያ በካዱት ሰዎች ልቦች ውስጥ አላህ በእርሱ አስረጅ ያላወረደበትን ነገር በአላህ በማጋራታቸው ምክንያት ፍርሃትን እንጥላለን፡፡ መኖሪያቸውም እሳት ናት፡፡ የበዳዮችም መኖሪያ ምን ትከፋ!'),
('3:152', 87, 'አላህም በፈቃዱ በምትጨፈጭፏቸው ጊዜ ኪዳኑን በእርግጥ አረጋገጠላችሁ፡፡ የምትወዱትንም ነገር ካሳያችሁ በኋላ በፈራችሁ በትዕዛዙም በተጨቃጨቃችሁና ባመጻችሁ ጊዜ (እርዳታውን ከለከላችሁ)፡፡ ከእናንተ ውስጥ ቅርቢቱን ዓለም የሚሻ አለ፡፡ ከእናንተም የመጨረሻይቱን ዓለም የሚሻ አልለ፡፡ ከዚያም ሊሞክራችሁ ከእነርሱ አዞራችሁ፡፡ በእርግጥም ከእናንተ ይቅርታ አደረገላችሁ፡፡ አላህም በምእምናን ላይ የችሮታ ባለቤት ነው፡፡'),
('3:153', 87, 'መልክተኛው ከኋላችሁ የሚጠራችሁ ሲኾን ርቃችሁ በምትሸሹና በአንድም ላይ የማትዞሩ በኾናችሁ ጊዜ (አስታውሱ)፡፡ ባመለጣችሁና በደረሰባችሁም ነገር እንድታዝኑ በሐሳብ ላይ ሐሳብን መነዳችሁ፡፡ አላህም በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('3:154', 87, 'ከዚያም ከጭንቅ በኋላ ጸጥታን ከእናንተ ከፊሎችን የሚሸፍንን እንቅልፍ በእናንተ ላይ አወረደ፡፡ ከፊሎቹም ነፍሶቻቸው በእርግጥ አሳሰቧቸው፡፡ እውነት ያልኾነውን የመሃይምነትን መጠራጠር በአላህ ይጠራጠራሉ፤ «ከነገሩ ለእኛ ምንም የለንም» ይላሉ፡፡ «ነገሩ ሁሉም ለአላህ ነው» በላቸው፡፡ ለአንተ የማይገልጹትን በነፍሶቻቸው ውስጥ ይደብቃሉ፡፡ «ከነገሩ ለእኛ አንዳች በነበረን ኖሮ እዚህ ባልተገደልን ነበር» ይላሉ፡፡ «በቤታችሁ ውስጥ በኾናችሁም ኖሮ እነዚያ በእነርሱ ላይ መገደል የተጻፈባቸው ወደ መውደቂያቸው በወጡ ነበር» በላቸው፡፡ አላህ (ፍርዱን ሊፈጽምና) በደረቶቻችሁም ውስጥ ያለውን ሊፈትን በልቦቻችሁም ውስጥ ያለውን ነገር ሊገልጽ (ይህን ሠራ)፡፡ አላህም በደረቶች ውስጥ ያለን ሁሉ ዐዋቂ ነው፡፡'),
('3:155', 87, 'እነዚያ ሁለቱ ጭፍሮች በተገናኙ ቀን ከእናንተ የሸሹት ሰዎች በዚያ በሠሩት ከፊል ምክንያት ያሳሳታቸው ሰይጣን ነው፡፡ አላህም ከነሱ በእርግጥ ይቅር አለ፡፡ አላህ መሓሪ በቅጣት የማይቸኩል ነውና፡፡'),
('3:156', 87, 'እናንተ ያመናችሁ ሆይ! እንደነዚያ እንደ ካዱትና ስለ ወንድሞቻቸው በምድር ላይ በተጓዙ ወይም ዘማቾች በኾኑ ጊዜ «እኛ ዘንድ በነበሩ ኖሮ ባልሞቱም ባልተገደሉም ነበር» እንደሚሉት አትኹኑ፡፡ አላህ ይህንን በልቦቻቸው ውስጥ ጸጸት ያደርግባቸው ዘንድ (ይህንን አሉ)፡፡ አላህም ሕያው ያደርጋል፤ ይገድላልም፡፡ አላህም የምትሠሩትን ሁሉ ተመልካች ነው፡፡'),
('3:157', 87, 'በአላህም መንገድ ብትገደሉ ወይም፤ ብትሞቱ ከአላህ የኾነው ምሕረትና እዝነት (እነርሱ) ከሚሰበስቡት ሀብት በእርግጥ በላጭ ነው፡፡'),
('3:158', 87, 'ብትሞቱም ወይም ብትገደሉ በእርግጥ ወደ አላህ ብቻ ትሰበሰባላችሁ፡፡'),
('3:159', 87, 'ከአላህም በኾነች ችሮታ ለዘብክላቸው፡፡ ዐመለ መጥፎ ልበ ደረቅም በኾንክ ኖሮ ከዙሪያህ በተበተኑ ነበር፡፡ ከእነርሱም ይቅር በል፡፡ ለእነርሱም ምሕረትን ለምንላቸው፡፡ በነገሩም ሁሉ አማክራቸው፡፡ ቁርጥ ሐሳብም ባደረግህ ጊዜ በአላህ ላይ ተመካ፡፡ አላህ በርሱ ላይ ተመኪዎችን ይወዳልና፡፡'),
('3:160', 87, 'አላህ ቢረዳችሁ ለእናንተ አሸናፊ የለም፡፡ ቢያዋርዳችሁም ያ ከርሱ (ማዋረድ) በኋላ የሚረዳችሁ ማነው በአላህም ላይ ብቻ ምእምናን ይመኩ፡፡'),
('3:161', 87, 'ለነቢይም ሰለባን መደበቅ አይገባውም፡፡ ሰለባንም የሚደብቅ ሰው በትንሣኤ ቀን በደበቀው ነገር (ተሸክሞ) ይመጣል፡፡ ከዚያም ነፍስ ሁሉ የሥራዋን ዋጋ ትሞላለች፡፡ እነርሱም አይበደሉም፡፡'),
('3:162', 87, 'የአላህን ውዴታ የተከተለ ሰው ከአላህ በኾነ ቁጣ እንደ ተመለሰና መኖሪያው ገሀነም እንደ ኾነ ሰው ነውን መመለሻውም ምን ይከፋ!'),
('3:163', 87, 'እነርሱ አላህ ዘንድ ባለ ደረጃዎች ናቸው፡፡ አላህም የሚሠሩትን ነገር ተመልካች ነው፡፡'),
('3:164', 87, 'አላህ በምእምናን ላይ ከጎሳቸው የኾነን፤ በእነርሱ ላይ አንቀጾቹን የሚያነብ፣ የሚጠራቸውም፣ መጽሐፍንና ጥበብን የሚያስተምራቸውም የኾነን መልእክተኛ በውስጣቸው በላከ ጊዜ፤ በእርግጥ ለገሰላቸው፡፡ እነርሱም ከዚያ በፊት በግልጽ ስህተት ውስጥ ነበሩ፡፡'),
('3:165', 87, 'ሁለት ብጤዎችዋን በእርግጥ ያገኛችሁ የኾነች መከራ (መጠቃት) ባገኘቻችሁ ጊዜ «ይህ ከየት ነው» አላችሁን «እርሱ ከነፍሶቻችሁ ዘንድ ነው፡፡» አላህ በነገሩ ሁሉ ላይ ቻይ ነውና በላቸው፡፡'),
('3:166', 87, 'ሁለቱ ጭፍሮችም በተጋጠሙ ቀን የደረሰባችሁ በአላህ ፈቃድ ነው፡፡ ምእምናንንም (ሊፈትንና) ሊገልጽ ነው፡፡'),
('3:167', 87, 'እነዚያንም የነፈቁትንና ለነርሱ «ኑ፤ በአላህ መንገድ ተጋደሉ፤ ወይም ተከላከሉ፤» የተባሉትን ሊገልጽ ነው፡፡ «መዋጋት (መኖሩን) ብናውቅ ኖሮ በተከተልናችሁ ነበር» አሉ፡፡ እነርሱ ያን ጊዜ ከእምነት ይልቅ ወደ ክህደት የቀረቡ ናቸው፡፡ በልቦቻቸው የሌለውን በአፎቻቸው ይናገራሉ፡፡ አላህም የሚደብቁትን ዐዋቂ ነው፡፡'),
('3:168', 87, 'እነዚያ (ከትግል) የቀሩ ሲኾኑ ለወንድሞቻቸው፡- «በታዘዙን ኖሮ ባልተገደሉ ነበር» ያሉ ናቸው፡፡ «እውነተኞች እንደኾናችሁ ከነፍሶቻችሁ ላይ ሞትን ገፍትሩ» በላቸው፡፡'),
('3:169', 87, 'እነዚያን በአላህ መንገድ የተገደሉትን ሙታን አድርገህ አትገምታቸው፡፡ በእርግጥ እነርሱ እጌታቸው ዘንድ ሕያዋን ናቸው፤ ይመገባሉ፡፡'),
('3:170', 87, 'አላህ ከችሮታው በሰጣቸው ነገር ተደሳቾች ሲኾኑ (ይመገባሉ)፡፡ በነዚያም ከኋላቸው ገና በእነርሱ ባልተከተሉት በእነርሱ ላይ ፍርሃት ባለመኖሩና እነርሱም የማያዝኑ በመኾናቸው ይደሰታሉ፡፡'),
('3:171', 87, 'ከአላህ በኾነ ጸጋና ልግስና አላህም የምእምናንን ምንዳ የማያጠፉ በመኾኑ ይደሰታሉ፡፡'),
('3:172', 87, 'እነዚያ መቁሰል ካገኛቸው በኋላ ለአላህና ለመልክተኛው የታዘዙት ከእነሱ ለነዚያ በጎ ለሠሩትና ለተጠነቀቁት ታላቅ ምንዳ አላቸው፡፡'),
('3:173', 87, 'እነዚያ ሰዎቹ ለእነርሱ፡- «ሰዎች ለእናንተ (ጦርን) አከማችተዋልና ፍሩዋቸው» ይሉዋቸውና (ይህም) እምነትን የጨመረላቸው «በቂያችንም አላህ ነው ምን ያምርም መጠጊያ!» ያሉ ናቸው፡፡'),
('3:174', 87, 'ከአላህም በኾነ ጸጋና ችሮታ ክፉ ነገር ያልነካቸው ኾነው ተመለሱ፡፡ የአላህንም ውዴታ ተከተሉ፤ አላህም የታላቅ ችሮታ ባለቤት ነው፡፡'),
('3:175', 87, 'እንዲህ የሚላችሁ ሰይጣን ብቻ ነው፡፡ ወዳጆቹን ያስፈራራችኋል፡፡ አትፍሩዋቸውም፡፡ ምእምናንም እንደኾናችሁ ፍሩኝ፡፡'),
('3:176', 87, 'እነዚያም በክህደት የሚቻኮሉት አያሳዝኑህ፡፡ ከነርሱ ፈጽሞ አላህን በምንም አይጎዱምና፡፡ አላህ በመጨረሻይቱ ዓለም ለእነሱ ዕድልን ላያደርግ ይሻል፡፡ ለእነርሱም ታላቅ ቅጣት አላቸው፡፡'),
('3:177', 87, 'እነዚያ ክህደትን በእምነት የለወጡ አላህን በምንም ነገር ፈጽሞ አይጎዱትም፡፡ ለእነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('3:178', 87, 'እነዚያ የካዱት ሰዎች እነርሱን ማዘግየታችንን ለነፍሶቻቸው ደግ ነገር ነው ብለው አያስቡ፡፡ እነርሱን የምናዘገያቸው ኃጢኣትን እንዲጨምሩ ብቻ ነው፡፡ ለነሱም አዋራጅ ስቃይ አላቸው፡፡'),
('3:179', 87, 'አላህ መጥፎውን ከመልካሙ እስከሚለይ ድረስ ምእምናንን እናንተ በርሱ ላይ ባላችሁበት (ኹኔታ) ላይ የሚተው አይደለም፡፡ አላህም ሩቁን ነገር የሚያሳውቃችሁ አይደለም፡፡ ግን አላህ ከመልክተኞቹ የሚሻውን ይመርጣል፡፡ በአላህና በመልክተኞቹም እመኑ፡፡ ብታምኑና ብትጠነቀቁም ለናንተ ታላቅ ምንዳ አላችሁ፡፡'),
('3:180', 87, 'እነዚያም አላህ ከችሮታው በሰጣቸው ገንዘብ የሚነፍጉ እርሱ ለእነሱ ደግ አይምሰላቸው፡፡ ይልቁንም፤ እርሱ ለነሱ መጥፎ ነው፡፡ ያንን በርሱ የነፈጉበትን በትንሣኤ ቀን (እባብ ኾኖ) ይጠለቃሉ፡፡ የሰማያትና የምድርም ውርስ ለአላህ ብቻ ነው፡፡ አላህም በሚሠሩት ሁሉ ውስጥ ዐዋቂ ነው፡፡'),
('3:181', 87, 'የእነዚያን «አላህ ድኻ ነው እኛ ግን ከበርቴዎች ነን» ያሉትን ሰዎች ቃል አላህ በእርግጥ ሰማ፡፡ ያንን ያሉትንና ነቢያትን ያለ ሕግ መግደላቸውን በእርግጥ እንጽፋለን፡፡ «የእሳትንም ስቃይ ቅመሱ» እንላቸዋለን፡፡'),
('3:182', 87, 'ያ (ስቃይ) እጆቻችሁ ባሳለፉት ሥራ ነው፡፡ አላህም ለባሮቹ በዳይ ባለመኾኑ ነው፡፡'),
('3:183', 87, 'እነዚያ ለማንኛውም መልክተኛ «እሳት የምትበላው የኾነን ቁርባን እስከሚያመጣልን ድረስ ላናምን አላህ ወደኛ አዟል» ያሉ ናቸው፡፡«መልክተኞች ከእኔ በፊት በተዓምራትና በዚያም ባላችሁት (ቁርባን) በእርግጥ መጥተውላችኋል፡፡ እውነተኞች ከኾናችሁ ታዲያ ለምን ገደላችኋቸው» በላቸው፡፡'),
('3:184', 87, 'ቢያስተባብሉህም ከአንተ በፊት በግልጽ ተዓምራትና በጽሑፎች፣ በብሩህ መጽሐፍም የመጡት መልክተኞች በእርግጥ ተስተባብለዋል፡፡'),
('3:185', 87, 'ነፍስ ሁሉ ሞትን ቀማሽ ናት፡፡ ምንዳዎቻችሁንም የምትሞሉት በትንሣኤ ቀን ብቻ ነው፡፡ ከእሳትም የተራቀና ገነትን የተገባ ሰው በእርግጥ ምኞቱን አገኘ፡፡ ቅርቢቱም ሕይወት የመታለያ መሳሪያ እንጅ ሌላ አይደለችም፡፡'),
('3:186', 87, 'በገንዘቦቻችሁና በነፍሶቻችሁ በእርግጥ ትፈተናላችሁ፡፡ ከእነዚያም ከእናንተ በፊት መጽሐፍን ከተሰጡትና ከእነዚያም ከአጋሩት ብዙን ማሰቃየት ትሰማላችሁ፡፡ ብትታገሱና ብትጠነቀቁ ይህ ከጥብቅ ነገሮች ነው፡፡'),
('3:187', 87, 'አላህ የነዚያን መጽሐፉን የተሰጡትን ቃል ኪዳን ለሰዎች በእርግጥ ታብራሩታላችሁ አትደብቁትምም በማለት የያዘባቸውን (አስታውሱ)፡፡ በጀርባዎቻቸውም ኋላ ጣሉት፡፡ በርሱም ጥቂትን ዋጋ ገዙ፡፡ የሚገዙትም ነገር ከፋ!'),
('3:188', 87, 'እነዚያን በሠሩት ነገር የሚደሰቱትንና ባልሠሩትም መመስገንን የሚወዱትን አታስብ፤ ከቅጣት በመዳን ላይ ናቸው ብለህ አታሰባቸው፡፡ ለእነሱ አሳማሚ ቅጣት አላቸው፡፡'),
('3:189', 87, 'የሰማያትና የምድር ንግሥና ለአላህ ብቻ ነው፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('3:190', 87, 'ሰማያትንና ምድርን በመፍጠር ሌሊትና ቀንንም በመተካካት ለባለ አእምሮዎች በእርግጥ ምልክቶች አሉ፡፡'),
('3:191', 87, '(እነርሱም) እነዚያ ቆመው፣ ተቀምጠውም፣ በጎኖቻቸው ተጋድመውም አላህን የሚያወሱ በሰማያትና በምድር አፈጣጠርም የሚያስተነትኑ፡- «ጌታችን ሆይ! ይኸን በከንቱ አልፈጠርከውም፤ ጥራት ይገባህ፤ ከእሳትም ቅጣት ጠብቀን» የሚሉ ናቸው፡፡'),
('3:192', 87, '«ጌታችን ሆይ! አንተ እሳት የምታገባውን ሰው በእርግጥ አዋረድከው፤ ለበደለኞችም ምንም ረዳቶች የሉዋቸውም፡፡»'),
('3:193', 87, '«ጌታችን ሆይ! እኛ በጌታችሁ እመኑ በማለት ወደ እምነት የሚጠራን ጠሪ ሰማን፡፡ አመንም፡፡ ጌታችን ሆይ! ኃጢአቶቻችንንም ለኛ ማር፡፡ ክፉ ሥራዎቻችንንም ከኛ አብስ፡፡ ከንጹሖቹም ሰዎች ጋር ግደለን፤»'),
('3:194', 87, '«ጌታችን ሆይ! በመልክተኞችህም ላይ ተስፋ ቃል ያደረግክልንን ስጠን፡፡ በትንሣኤ ቀንም አታዋርደን፡፡ አንተ ቀጠሮን አታፈርስምና» (የሚሉ ናቸው)፡፡'),
('3:195', 87, 'ጌታቸውም «እኔ ከእናንተ ከወንድ ወይም ከሴት የሠሪን ሥራ አላጠፋም፡፡ ከፊላችሁ ከከፊሉ ነው፤ በማለት ለነርሱ ልመናቸውን ተቀበለ፡፡ እነዚያም የተሰደዱ ከአገሮቻቸውም የተባረሩ በመንገዴም የተጠቁ የተጋደሉም የተገደሉም ክፉ ሥራዎቻቸውን ከእነርሱ በእርግጥ አብሳለሁ፡፡ በሥሮቻቸውም ወንዞች የሚፈሱባቸውን ገነቶች በእርግጥ አገባቸዋለሁ፡፡ ከአላህ ዘንድ የኾነን ምንዳ (ይመነዳሉ)፡፡ አላህም እርሱ ዘንድ መልካም ምንዳ አልለ፡፡ »'),
('3:196', 87, 'የእነዚያ የካዱት ሰዎች በአገሮች መንፈላሰስ አያታልህ፡፡'),
('3:197', 87, 'አነስተኛ ጥቅም ነው፡፡ ከዚያም መኖሪያቸው ገሀነም ናት፡፡ ምን ትከፋም ምንጣፍ!'),
('3:198', 87, 'ግን እነዚያ ጌታቸውን የፈሩ ለእነሱ ከሥሮቻቸው ወንዞች የሚፈሱባቸው ገነቶች በውስጧ ዘውታሪዎች ሲኾኑ ከአላህ ዘንድ (የተሰጡ) መስተንግዶዎች አሏቸው፡፡ አላህም ዘንድ ያለው (ምንዳ) ለበጎ ሠሪዎች በላጭ ነው፡፡'),
('3:199', 87, 'ከመጽሐፉም ባለቤቶች ለአላህ ፈሪዎች በአላህ አንቀጾችም ጥቂትን ዋጋ የማይለወጡ ሲኾኑ በአላህና በዚያ ወደ እናንተ በተወረደው በዚያም ወደእነርሱ በተወረደው የሚያምኑ ሰዎች አልሉ፡፡ እነዚያ ለእነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፡፡ አላህ ምርመራው ፈጣን ነው፡፡'),
('3:200', 87, 'እናንተ ያመናችሁ ሆይ! ታገሱ ተበራቱም፡፡ (በጦር ኬላ ላይ) ተሰለፉም፡፡ ትድኑም ዘንድ አላህን ፍሩ፡፡'),
('4:1', 87, 'እናንተ ሰዎች ሆይ! ያንን ከአንዲት ነፍስ (ከአዳም) የፈጠራችሁን ከእርስዋም መቀናጆዋን (ሔዋንን) የፈጠረውን ከእነርሱም ብዙ ወንዶችንና ሴቶች የበተነውን ጌታችሁን ፍሩ፡፡ ያንንም በርሱ የምትጠያየቁበትን አላህንና ዝምድናዎችንም (ከመቁረጥ) ተጠንቀቁ፡፡ አላህ በእናንተ ላይ ተጠባባቂ ነውና፡፡'),
('4:2', 87, 'የቲሞችንም ገንዘቦቻቸውን ስጡ፡፡ መጥፎውንም በመልካሙ አትለውጡ፡፡ ገንዘቦቻቸውንም ወደ ገንዘቦቻችሁ (በመቀላቀል) አትብሉ እርሱ ታላቅ ኃጢአት ነውና፡፡'),
('4:3', 87, 'በየቲሞችም (ማግባት) አለማስተካከላችሁን ብትፈሩ (ዝሙትንና ከተወሰነላችሁ በላይ ማግባትንም ፍሩ)፡፡ ከሴቶች ለእናንተ የተዋበላችሁን ሁለት ሁለት ሦስት ሦስትም አራት አራትም አግቡ፡፡ አለማስተካከልንም ብትፈሩ አንዲትን ብቻ ወይም እጆቻችሁ ንብረት ያደረጉትን ያዙ፡፡ ይህ ወደ አለመበደል በጣም የቀረበ ነው፡፡'),
('4:4', 87, 'ሴቶችንም መህሮቻቸውን በደስታ ስጡ፡፡ ለእናንተም ከእርሱ አንዳችን ነገር ነፍሶቻቸው ቢለግሱ መልካም ምስጉን ሲኾን ብሉት፡፡'),
('4:5', 87, 'ቂሎችንም ያችን አላህ ለእናንተ መተዳደሪያ ያደረጋትን ገንዘቦቻችውን (የያዛችሁላቸውን) አትስጡዋቸው፡፡ ከርሷም መግቡዋቸው አልብሱዋቸውም፡፡ ለእነሱም መልካምን ንግግር ተናገሩ፡፡'),
('4:6', 87, 'የቲሞችንም ጋብቻን እስከደረሱ ጊዜ ድረስ ፈትኑዋቸው፡፡ ከእነርሱም ቅንነትን ብታውቁ ገንዘቦቻቸውን ወደ እነርሱ ስጡ፡፡ በማባከንና ማደጋቸውንም በመሽቀዳደም አትብሏት፡፡ (ከዋቢዎች) ሀብታምም የኾነ ሰው ይከልከል፡፡ ድሃም የኾነ ሰው (ለድካሙ) በአግባብ ይብላ፡፡ ገንዘቦቻቸውንም ወደ እነርሱ በሰጣችሁ ጊዜ በእነርሱ ላይ አስመስክሩ፡፡ ተጠባባቂነትም በአላህ በቃ፡፡'),
('4:7', 87, 'ለወንዶች ወላጆችና የቅርብ ዘመዶች ከተዉት (ንብረት) ፋንታ (ድርሻ) አላቸው፡፡ ለሴቶችም ወላጆችና የቅርብ ዘመዶች ከተዉት ከእርሱ ካነሰው ወይም ከበዛው ፋንታ አላቸው፡፡ የተወሰነ ድርሻ (ተደርጓል)፡፡'),
('4:8', 87, 'ክፍያንም (ወራሽ ያልኾኑ) የዝምድና ባለቤቶችና የቲሞች፣ ምስኪኖችም በተገኙበት ጊዜ ከእርሱ ዳርጓቸው፡፡ መልካምንም ንግግር ተናገሩዋቸው፡፡'),
('4:9', 87, 'እነዚያም ከኋላቸው ደካሞችን ዝርያዎች ቢተው ኖሮ በእነርሱ ላይ የሚፈሩ (በየቲሞች ላይ) ይጠንቀቁ፡፡ አላህንም ይፍሩ፡፡ (ለተናዛዡ) ትክክለኛንም ቃል ይናገሩ፡፡'),
('4:10', 87, 'እነዚያ የየቲሞችን ገንዘብ በመበደል የሚበሉ በሆዶቻቸው ውስጥ የሚበሉት እሳትን ብቻ ነው፡፡ እሳትንም በእርግጥ ይገባሉ፡፡'),
('4:11', 87, 'አላህ በልጆቻችሁ (ውርስ በሚከተለው) ያዛችኋል፡፡ ለወንዱ የሁለት ሴቶች ድርሻ ብጤ አለው፡፡ (ሁለት ወይም) ከሁለት በላይም የኾኑ ሴቶች ብቻ ቢኾኑ ለእነሱ (ሟቹ) ከተወው ረጀት (ድርሻ) ከሦስት ሁለት እጁ አላቸው፡፡ አንዲትም ብትኾን ለርሷ ግማሹ አላት፡፡ ለአባትና ለእናቱም ለእርሱ ልጅ እንዳለው ከሁለቱ ለያንዳንዱ ከስድስት አንድ አላቸው፡፡ ለእርሱም ልጅ ባይኖረውና ወላጆቹ ቢወርሱት ለእናቱ ሲሶው አላት፡፡ ለእርሱም ወንድሞችና እኅቶች ቢኖሩት ለናቱ ከስድስት አንድ አላት፡፡ (ይህም የተባለው) በርሷ ከተናዘዘባት ኑዛዜ ወይም ከዕዳ በኋላ ነው፡፡ አባቶቻችሁና ልጆቻችሁ ለእናንተ በመጥቀም ማንኛቸው ይበልጥ ቅርብ እንደኾኑ አታውቁም፡፡ (ይኽም) ከአላህ የተደነገገ ነው፤ አላህ ዐዋቂ ጥበበኛ ነውና፡፡'),
('4:12', 87, 'ለእናንተም ሚስቶቻችሁ ከተዉት ንብረት ለእነርሱ ልጅ ባይኖራቸው ግማሹ አላችሁ፡፡ ለእነሱም ልጅ ቢኖራቸው ከተዉት ሀብት ከአራት አንድ አላችሁ፡፡ (ይህም) በእርሷ ከሚናዘዙባት ኑዛዜ ወይም ከዕዳ በኋላ ነው፡፡ ለናንተም ልጅ ባይኖራችሁ ከተዋችሁት ንብረት ለእነርሱ (ለሚስቶች) ከአራት አንድ አላቸው፡፡ ለእናንተም ልጅ ቢኖራችሁ ከተዋችሁት ንብረት ለእነርሱ ከስምንት አንድ አላቸው (ይህም በርሷ ከምትናዘዙባት ኑዛዜ ወይም ከዕዳ በኋላ ነው፡፡) ወላጅም ልጅም የሌለው በጎን ወራሾች የሚወርስ ወንድ ወይም ሴት ቢገኝ ለእርሱም (ለሟቹ) ወንድም ወይም እኅት (ከእናቱ በኩል ብቻ የኾነ) ቢኖር ከሁለቱ ለያንዳንዳቸው ከስድስት አንድ አላቸው፡፡ ከዚህም (ከአንድ) የበዙ ቢኾኑ እነርሱ በሲሶው ተጋሪዎች ናቸው፡፡ (ይህም ወራሾችን) የማይጎዳ ኾኖ በእርሷ ከሚናዘዙባት ኑዛዜ ወይም ከዕዳ በኋላ ነው፡፡ ከአላህም የኾነን ኑዛዜ (ያዛችኋል)፡፡ አላህም ዐዋቂ ቻይ ነው፡፡'),
('4:13', 87, 'እነዚህ የአላህ ውሳኔዎች ናቸው፡፡ አላህንና መልክተኛውንም የሚታዘዙ ሰዎች ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ ያገባቸዋል፡፡ ይህም ትልቅ ዕድል ነው፡፡'),
('4:14', 87, 'አላህንና መልክተኛውንም የሚያምጽ ወሰኖቹንም የሚተላለፍ በውስጧ ዘውታሪ ሲኾን እሳትን ያገባዋል፡፡ ለርሱም አዋራጅ ቅጣት አለው፡፡'),
('4:15', 87, 'እነዚያም ከሴቶቻችሁ መጥፎን ሥራ (ዝሙትን) የሚሠሩ በእነርሱ ላይ ከናንተ አራትን (ወንዶች) አስመስክሩባቸው፡፡ ቢመሰክሩም ሞት እስከሚደርስባቸው ወይም አላህ ለእነርሱ መንገድን እስከሚያደርግ ድረስ በቤቶች ውሰጥ ያዙዋቸው (ጠብቁዋቸው)፡፡'),
('4:16', 87, 'እነዚያንም ከእናንተ ውስጥ (ዝሙትን) የሚሠሩዋትን አሰቃዩዋቸው፡፡ ቢጸጸቱና ሥራቸውንም ቢያሳምሩ ከእነርሱ ተገቱ (አታሰቃዩዋቸው)፡፡ አላህ ጸጸትን ተቀባይ አዛኝ ነውና፡፡'),
('4:17', 87, 'ጸጸትን መቀበል በአላህ ላይ የሚገባው ለእነዚያ ኀጢአትን በስህተት ለሚሠሩና ከዚያም ከቅርብ ጊዜ ለሚጸጸቱት ብቻ ነው፡፡ እነዚያንም አላህ በእነርሱ ላይ ጸጸትን ይቀበላል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('4:18', 87, 'ጸጸትንም መቀበል ለእነዚያ ኀጢአቶችን ለሚሠሩ አንዳቸውንም ሞት በመጣበት ጊዜ «እኔ አሁን ተጸጸትኩ» ለሚልና ለነዚያም እነርሱ ከሓዲዎች ኾነው ለሚሞቱ አይደለችም፡፡ እነዚያ ለእነሱ አሳማሚን ቅጣት አዘጋጅተናል፡፡'),
('4:19', 87, 'እናንተ ያመናችሁ ሰዎች ሆይ! ሴቶችን ያስገደዳችሁ ኾናችሁ ልትወርሱና ግልጽን መጥፎ ሥራ ካልሠሩ በስተቀር ከሰጣችኋቸው ከፊሉን ልትወስዱ ልታጉላሏቸውም ለእናንተ አይፈቀድም፡፡ በመልካምም ተኗኗሩዋቸው፡፡ ብትጠሉዋቸውም (ታገሱ)፡፡ አንዳችን ነገር ብትጠሉ አላህም በእርሱ ብዙ ደግ ነገርን ሊያደርግ ይቻላልና፡፡'),
('4:20', 87, 'በሚስትም ስፍራ ሚስትን ለመለወጥ ብትፈልጉ ለአንደኛይቱ (ለምትፈታው) ብዙን ገንዘብ የሰጣችኋት ስትኾኑ ከርሱ ምንንም አትውሰዱ፡፡ በመበደልና ግልጽ በኾነ ኀጢአት ትወስዱታላችሁን'),
('4:21', 87, 'ከፊላችሁ ወደ ከፊሉ በእርግጥ የደረሰ ሲኾንና ከእናንተ ላይም (ሴቶች) የጠበቀ ኪዳንን የያዙባችሁ ሲኾኑ እንዴት ትወስዱታላችሁ!'),
('4:22', 87, 'ከሴቶችም አባቶቻችሁ ያገቡዋቸውን አታግቡ፡፡ (ትቀጡበታላችሁ)፡፡ ያለፈው ሲቀር፡፡ እርሱ መጥፎና የተጠላ ሥራ ነውና፡፡ መንገድነቱም ከፋ!'),
('4:23', 87, 'እናቶቻችሁ፣ ሴት ልጆቻችሁም፣ እኅቶቻችሁም፣ አክስቶቻችሁም፣ የሹሜዎቻችሁም፣ የወንድም ሴቶች ልጆችም፣ የእኅት ሴቶች ልጆችም፣ እነዚያም ያጠቡዋችሁ እናቶቻችሁ፣ ከመጥባት የኾኑትም እኅቶቻችሁ፣ የሚስቶቻችሁም እናቶች፣ እነዚያም በጉያዎቻችሁ ያሉት የእነዚያ በእነርሱ የገባችሁባቸው ሚስቶቻችሁ ሴቶች ልጆች፣ (ልታገቧቸው) በእናንተ ላይ እርም ተደረጉባችሁ፡፡ በእነርሱም (በሚስቶቻችሁ) ያልገባችሁባቸው ብትኾኑ (በፈታችኋቸው ጊዜ ሴቶች ልጆቻቸውን ብታገቡ) በእናንተ ላይ ኀጢአት የለባችሁም፡፡ የእነዚያ ከጀርባዎቻችሁ የኾኑት ወንዶች ልጆቻችሁ ሚስቶችም በሁለት እኅትማማቾችም መካከል መሰብሰብ (እንደዚሁ እርም ነው)፡፡ ግን ከዚህ በፊት ያለፈው ሲቀር (እርሱንስ ተምራችኋል) አላህ መሓሪ አዛኝ ነውና፡፡'),
('4:24', 87, 'ከሴቶችም (በባል) ጥብቆቹ እጆቻቸሁ (በምርኮ) የያዙዋቸው ሲቀሩ በእናንተ ላይ እርም ናቸው፡፡ (ይህን) አላህ በናንተ ላይ ጻፈ፡፡ ከዚሃችሁም (ከተከለከሉት) ወዲያ ጥብቆች ኾናችሁ ዝሙተኞች ሳትኾኑ በገንዘቦቻችሁ ልትፈልጉ ለእናንተ ተፈቀደ፡፡ ከእነሱም በርሱ (በመገናኘት) የተጠቀማችሁባቸውን ሴቶች መህሮቻቸውን ግዴታ ሲኾን ስጧቸው፡፡ ከመወሰንም በኋላ በተዋደዳችሁበት ነገር በእናንተ ላይ ኀጢአት የለም፡፡ አላህ ዐዋቂ ጥበበኛ ነውና፡፡'),
('4:25', 87, 'ከናንተም ውስጥ ጥብቆች ምእምናት የኾኑትን ለማግባት ሀብትን ያልቻለ ሰው እጆቻችሁ ንብረት ካደረጓቸው ከምእምናት ወጣቶቻችሁ (ባሪያን ያግባ)፡፡ አላህም እምነታችሁን ዐዋቂ ነው፡፡ ከፊላችሁ ከከፊሉ (የተራባ) ነው፡፡ (ባሮችን) በጌቶቻቸውም ፈቃድ አግቡዋቸው፡፡ መህሮቻቸውንም በመልካም መንገድ ስጧቸው፡፡ ጥብቆች ኾነው ዝሙተኞች ያልኾኑ የስርቆሽ ወዳጆችንም ያልያዙ ሲኾኑ (አግቧቸው)፡፡ በማግባት በተጠበቁም ጊዜ መጥፎን ሥራ ቢሠሩ በእነርሱ ላይ ከቅጣት በነጻዎቹ ላይ ያለው ግማሽ አለባቸው፡፡ ይኸ (ባሪያን ማግባት) ከናንተ ዝሙትን ለፈራ ሰው ነው፡፡'),
('4:26', 87, 'አላህ (የሃይማኖታችሁን ሕግጋት) ሊያብራራላችሁ ከእናንተ በፊትም የነበሩትን ነቢያት ደንቦች ሊመራችሁ በእናንተም ላይ ጸጸትን ሊቀበል ይሻል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('4:27', 87, 'አላህም በእናንተ ላይ ጸጸትን ሊቀበል ይሻል፡፡ እነዚያም ፍላጎታቸውን የሚከተሉት (ከውነት) ትልቅን መዘንበል እንድትዘነበሉ ይፈልጋሉ፡፡'),
('4:28', 87, 'አላህ ከእናንተ ሊያቃልልላችሁ ይሻል፡፡ ሰውም ደካማ ኾኖ ተፈጠረ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('4:29', 87, 'እናንተ ያመናችሁ ሆይ! ገንዘቦቻችሁን በመካከላችሁ ያለ አግባብ አትብሉ፡፡ ግን ከእናንተ በመዋደድ የኾነችውን ንግድ (ብሉ)፡፡ ነፍሶቻችሁንም አትግደሉ፡፡ አላህ ለእናንተ አዛኝ ነውና፡፡'),
('4:30', 87, 'ወሰን በማለፍና በመበደልም ይህንን የሠራ ሰው እሳትን እናገባዋለን፡፡ ይኸም በአላህ ላይ ገር ነው፡፡'),
('4:31', 87, 'ከእርሱ ከተከለከላችሁት ታላላቆቹን (ኀጢአቶች) ብትርቁ (ትናንሾቹን) ኀጢአቶቻችሁን ከእናንተ እናብሳለን፡፡ የተከበረንም ስፍራ (ገነትን) እናገባችኋለን፡፡'),
('4:32', 87, 'አላህም ከፊላችሁን በከፊሉ ላይ በእርሱ ያበለጠበትን ጸጋ አትመኙ፡፡ ለወንዶች ከሠሩት ሥራ እድል አላቸው፡፡ ለሴቶችም ከሠሩት ሥራ ዕድል አላቸው፡፡ አላህንም ከችሮታው ለምኑት፡፡ አላህ በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('4:33', 87, 'ለሁሉም (ለወንዶችና ለሴቶች) ወላጆችና የቅርብ ዘመዶች ከተዉት ሀብት ጠቅላይ ወራሾችን አድርገናል፡፡ እነዚያንም (ለመረዳዳትና ለመዋረስ) በመሐላዎቻችሁ የተዋዋላችኋቸውን ድርሻቸውን (ከስድስት አንድ) ስጧቸው፡፡ አላህ በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('4:34', 87, 'ወንዶች በሴቶች ላይ ቋሚዎች (አሳዳሪዎች) ናቸው፡፡ አላህ ከፊላቸውን በከፊሉ ላይ በማብለጡና (ወንዶች) ከገንዘቦቻቸው (ለሴቶች) በመስጠታቸው ነው፡፡ መልካሞቹም ሴቶች (ለባሎቻቸው) ታዛዦች አላህ ባስጠበቀው ነገር ሩቅን ጠባቂዎች ናቸው፡፡ እነዚያንም ማመጸቸውን የምትፈሩትን ገስጹዋቸው፡፡ በመኝታዎችም ተለዩዋቸው፡፡ (ሳካ ሳታደርሱ) ምቱዋቸውም፡፡ ቢታዘዟችሁም (ለመጨቆን) በእነርሱ ላይ መንገድን አትፈልጉ፤ አላህ የበላይ ታላቅ ነውና፡፡'),
('4:35', 87, '(እናንተ ዋቢዎች) የመካከላቸውንም ጭቅጭቅ ብታውቁ ከቤተሰቦቹ ሽማግሌን ከቤተሰቦችዋም ሽማግሌን ላኩ፡፡ ማስታረቅን ቢሹ አላህ በመካከላቸው ያስማማል፡፡ አላህ ግልጽን ዐዋቂ ውስጥንም ዐዋቂ ነውና፡፡'),
('4:36', 87, 'አላህንም ተገዙ፡፡ በእርሱም ምንንም አታጋሩ፡፡ በወላጆችና በቅርብ ዝምድና ባለቤትም፣ በየቲሞችም፣ በምስኪኖችም፣ በቅርብ ጎረቤትም፣ በሩቅ ጎረቤትም፣ በጎን ባልደረባም፣ በመንገደኛም፣ እጆቻችሁም ንብረት ባደረጓቸው (ባሮች)፣ መልካምን (ሥሩ)፤ አላህ ኩራተኛ ጉረኛ የኾነን ሰው አይወድም፡፡'),
('4:37', 87, 'እነዚያ የሚሰስቱ ሰዎችንም በመሰሰት የሚያዙ አላህም ከችሮታው የሰጣቸውን ጸጋ የሚደብቁ (ብርቱን ቅጣት ይቀጥጣሉ)፡፡ ለከሓዲዎችም አዋራጅን ቅጣት አዘጋጅተናል፡፡'),
('4:38', 87, 'እነዚያም ለሰዎች ይውልኝ ሲሉ ገንዘቦቻቸውን የሚሰጡ በአላህና በመጨረሻውም ቀን የማያምኑ (ይቀጥጣሉ)፡፡ ሰይጣንም ለእርሱ ጓደኛው የኾነ ሰው ጓደኛነቱ ከፋ!'),
('4:39', 87, 'በአላህና በመጨረሻውም ቀን ባመኑ አላህ ከሰጣቸውም (ሲሳይ) በለገሱ ኖሮ በነርሱ ላይ ምን (ጉዳት) ነበረ አላህም በነርሱ (ኹነታ) ዐዋቂ ነው፡፡'),
('4:40', 87, 'አላህ የብናኝን ክብደት ያህል አይበድልም፡፡ መልካም ሥራ ብትኾንም ይደራርባታል፡፡ ከእርሱም ዘንድ ታላቅን ምንዳ ይሰጣል፡፡'),
('4:41', 87, 'ከሕዝቦችም ሁሉ መስካሪን ባመጣን ጊዜ አንተንም በእነዚህ ላይ መስካሪ አድርገን በምናመጣህ ጊዜ (የከሓዲዎች ኹኔታ) እንዴት ይኾን'),
('4:42', 87, 'በዚያ ቀን እነዚያ የካዱትና መልክተኛውን ያልታዘዙት በእነሱ ምድር ብትደፋባቸው ይመኛሉ፡፡ ከአላህም ወሬን አይደብቁም፡፡'),
('4:43', 87, 'እናንተ ያመናችሁ ሆይ! እናንተ የሰከራችሁ ኾናችሁ የምትሉትን ነገር እስከምታውቁ የረከሳችሁም ስትኾኑ መንገድን አላፊዎች ካልኾናችሁ በስተቀር (አካላታችሁን) እስከምትታጠቡ ድረስ ስግደትን አትቅረቡ፡፡ በሽተኞች ወይም በጉዞ ላይ ብትኾኑም፥ ወይንም ከእናንተ አንዱ ከዓይነምድር ቢመጣ፥ ወይንም ሴቶችን ብትነካኩና ውሃን ባታገኙ፣ ንጹሕ የኾነን የምድር ገጽ አስቡ፡፡ ፊቶቻችሁንና እጆቻችሁንም (በርሱ) አብሱ፡፡ አላህ ይቅር ባይ መሓሪ ነውና፡፡'),
('4:44', 87, 'ወደነዚያ ከመጽሐፉ (ዕውቀት) ዕድልን ወደ ተሰጡት አላየህምን ጥመትን (በቅንነት) ይገዛሉ፡፡ መንገድንም እንድትሳሳቱ ይፈልጋሉ፡፡'),
('4:45', 87, 'አላህም ጠላቶቻችሁን ዐዋቂ ነው፡፡ ጠባቂነትም በአላህ በቃ፡፡ ረዳትነትም በአላህ በቃ፡፡'),
('4:46', 87, 'ከነዚያ አይሁዳውያን ከኾኑት ሰዎች ንግግሮችን ከስፍራዎቹ የሚያጣምሙ አልሉ፡፡ «ሰማንም አመጽንም የማትሰማም ስትኾን ስማ» ይላሉ፡፡ በምላሶቻቸውም ለማጣመምና ሃይማኖትንም ለመዝለፍ ራዒና ይላሉ፡፡ እነሱም «ሰማን ታዘዝንም ስማም ተመልከተንም» ባሉ ኖሮ ለነሱ መልካምና ትክክለኛ በኾነ ነበር፡፡ ግን በክህደታቸው አላህ ረገማቸው፡፡ ጥቂትንም እንጅ አያምኑም፡፡'),
('4:47', 87, 'እናንተ መጽሐፉን የተሰጣችሁ ሆይ! ፊቶችን ሳናብስና በጀርባዎች ላይ ሳንመልሳቸው ወይም የሰንበትን ባለቤቶች (ያፈረሱትን) እንደረገምን ሳንረግማቸው በፊት ከእናንተ ጋር ያለውን የሚያረጋግጥ ኾኖ ባወረድነው (ቁርኣን) እመኑ፡፡ የአላህም ትዕዛዝ ተፈጻሚ ነው፡፡'),
('4:48', 87, 'አላህ በእርሱ ማጋራትን በፍጹም አይምርም፡፡ ከዚህ ሌላ ያለውንም (ኀጢአት) ለሚሻው ሰው ይምራል፡፡ በአላህም የሚያጋራ ሰው ታላቅን ኀጢአት በእርግጥ ቀጠፈ፡፡'),
('4:49', 87, 'ወደእነዚያ ነፍሶቻቸውን ወደ ሚያጠሩት (የሚያወድሱት) አላየህምን አይደለም፤ አላህ የሚፈልገውን ያጠራል፡፡ የተምር ፍሬ ክር ያህልም አይበደሉም፡፡'),
('4:50', 87, 'በአላህ ላይ ውሸትን እንዴት እንደሚቀጣጥፉ ተመልከት፡፡ ግልጽ ወንጀልም በርሱ (በመቅጠፍ) በቃ፡፡'),
('4:51', 87, 'ወደ እነዚያ ከመጽሐፉ ዕድልን ወደ ተሰጡት አላየኸምን በድግምትና በጣዖት ያምናሉ፡፡ ለእነዚያም ለካዱት፡- እናንተ በመንገድ (በሃይማኖት) ከእነዚያ ካመኑት ይበልጥ የቀናችሁ ናችሁ ይላሉ፡፡'),
('4:52', 87, 'እነዚያ አላህ የረገማቸው ናቸው፡፡ አላህም የረገመው ሰው ለእርሱ ፈጽሞ ረዳትን አታገኝለትም፡፡'),
('4:53', 87, 'በእውነቱ ለእነሱ ከንግሥናው ፋንታ አላቸውን ያን ጊዜ ለሰዎች በተምር ፍሬ ላይ ያለችውን ነጥብ ያህል አይሰጡም ነበር፡፡'),
('4:54', 87, 'ይልቁንም ሰዎችን (ሙሐመድን) አላህ ከችሮታው በሰጣቸው ነገር ላይ ይመቀኛሉን ለኢብራሂምም ቤተሰቦች መጽሐፍንና ጥበብን በእርግጥ ሰጠን ታላቅንም ንግሥና ሰጠናቸው፡፡'),
('4:55', 87, 'ከእነሱም (ከይሁዶች) በእርሱ ያመነ አለ፡፡ ከእነርሱም ከእርሱ ያፈገፈ አለ፡፡ አቃጣይነትም በገሀነም በቃ፡፡'),
('4:56', 87, 'እነዚያን በተአምራታችን የካዱትን በእርግጥ እሳትን እናገባቸዋለን፡፡ ስቃይን እንዲቀምሱ ቆዳዎቻቸው በተቃጠሉ ቁጥር ሌሎችን ቆዳዎች እንለውጥላቸዋለን፡፡ አላህ አሸናፊ ጥበበኛ ነውና፡፡'),
('4:57', 87, 'እነዚያንም ያመኑትንና መልካም ሥራዎችን የሠሩትን ከስራቸው ወንዞች የሚፈሱባቸውን ገነቶች ዘልዓለም በውስጣቸው ዘውታሪዎች ሲኾኑ በእርግጥ እናገባቸዋለን፡፡ ለእነሱ በውስጥዋ ንጹሕ ሚስቶች አሉዋቸው፡፡ የምታስጠልልን ጥላም እናገባቸዋለን፡፡'),
('4:58', 87, 'አላህ አደራዎችን ወደ ባለቤቶቻቸው እንድታደርሱ ያዛችኋል፡፡ በሰዎችም መካከል በፈረዳችሁ ጊዜ በትክክል እንድትፈርዱ (ያዛችኋል)፡፡ አላህ በርሱ የሚገሥጻችሁ ነገር ምን ያምር! አላህ ሰሚ ተመልካች ነው፡፡'),
('4:59', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ተገዙ፡፡ መልክተኛውንና ከእናንተም የስልጣን ባለቤቶችን ታዘዙ፡፡ በማንኛውም ነገር ብትከራከሩ በአላህና በመጨረሻው ቀን የምታምኑ ብትኾኑ (የተከራከራችሁበትን ነገር) ወደ አላህና ወደ መልክተኛው መልሱት፡፡ ይህ የተሻለ መጨረሻውም ያማረ ነው፡፡'),
('4:60', 87, 'ወደ እነዚያ እነርሱ በአንተ ላይ በተወረደውና ከአንተ በፊትም በተወረደው አምነናል ወደሚሉት፤ አላየህምን በእርሱ እንዲክዱ በእርግጥ የታዘዙ ሲኾኑ ወደ ጣዖት መፋረድን ይፈልጋሉ፡፡ ሰይጣንም (ከእውነት) የራቀን መሳሳት ሊያሳስታቸው ይፈልጋል፡፡'),
('4:61', 87, 'ለእነርሱም፡- «አላህ ወደ አወረደው (ቁርኣን)ና ወደ መልክተኛው ኑ» በተባሉ ጊዜ መናፍቃን ከአንተ መሸሽን ሲሸሹ ታያቸዋለህ፡፡'),
('4:62', 87, 'እጆቻቸውም ባስቀደሙት (ጥፋት) መከራ በደረሰችባቸውና ከዚያም «ደግን ሐሳብና ማስማማትን እንጅ ሌላ አልሻንም» በማለት በአላህ የሚምሉ ኾነው በመጡህ ጊዜ እንዴት ይኾናሉ'),
('4:63', 87, 'እነዚህ እነዚያ አላህ በልቦቻቸው ውስጥ ያለውን ሁሉ የሚያውቅባቸው ናቸው፡፡ እነርሱንም ተዋቸው ገሥጻቸውም፡፡ ለእነርሱም በነፍሶቻቸው ውስጥ ስሜት ያለውን ቃል ተናገራቸው፡፡'),
('4:64', 87, 'ማንንም መልክተኛ በአላህ ፈቃድ ሊታዘዙት እንጅ አልላክንም፡፡ እነሱም ነፍሶቻቸውን በበደሉ ጊዜ ወደ አንተ ቢመጡና አላህንም ምሕረትን በለመኑ መልክተኛውም ለነርሱ ምሕረትን በለመነላቸው ኖሮ አላህን ጸጸትን ተቀባይ አዛኝ ኾኖ ባገኙት ነበር፡፡'),
('4:65', 87, 'በጌታህም እምላለሁ በመካከላቸው በተከራከሩበት ፍርድ እስከሚያስፈርዱህ ከዚያም ከፈረድከው ነገር በነፍሶቻቸው ውስጥ ጭንቀትን እስከማያገኙና ፍጹም መታዘዝንም እስከሚታዘዙ ድረስ አያምኑም፤ (ምእመን አይኾኑም)፡፡'),
('4:66', 87, 'እኛም በእነርሱ ላይ፡- «ነፍሶቻችሁን ግደሉ ወይም ከአገሮቻችሁ ውጡ» ማለትን በጻፍን ኖሮ ከነሱ ጥቂቶቹ እንጅ ባልሠሩት ነበር፡፡ እነርሱም በእርሱ የሚገሰጹበትን ነገር በሠሩ ኖሮ ለነሱ መልካምና (በእምነታቸው ላይ) ለመርጋትም በጣም የበረታ በኾነ ነበር፡፡'),
('4:67', 87, 'ያን ጊዜም ከእኛ ዘንድ ታላቅን ምንዳ በሰጠናቸው ነበር፡፡'),
('4:68', 87, 'ቀጥተኛውንም መንገድ በእርግጥ በመራናቸው ነበር፡፡'),
('4:69', 87, 'አላህንና መልክተኛውንም የሚታዘዝ ሰው እነዚያ ከእነዚያ አላህ በእነርሱ ላይ ከለገሳቸው ከነቢያት፣ ከጻድቃንም፣ ከሰማዕታትም፣ ከመልካሞቹ ጋር ይኾናሉ፡፡ የእነዚያም ጓደኝነት አማረ፡፡'),
('4:70', 87, 'ይህ ችሮታ ከአላህ ነው፡፡ አዋቂነትም በአላህ በቃ፡፡'),
('4:71', 87, 'እናንተ ያመናችሁ ሆይ! ጥንቃቄያችሁን ያዙ፡፡ ክፍልፍልም Ñድ ሆናችሁ (ለዘመቻ) ውጡ፡፡ ወይም ተሰብስባችሁ ውጡ፡፡'),
('4:72', 87, 'ከእናንተም ውስጥ በእርግጥ (ከዘመቻ) ወደ ኋላ የሚንጓደድ ሰው አልለ፡፡ አደጋም ብታገኛችሁ ከእነሱ ጋር ተጣጅ ባልኾንኩ ጊዜ አላህ በእኔ ላይ በእርግጥ ለገሰልኝ ይላል፡፡'),
('4:73', 87, 'ከአላህም የኾነ ችሮታ ቢያገኛችሁ በእናንተና በእርሱ መካከል ፍቅር እንዳልነበረች ሁሉ «ታላቅ ዕድልን አገኝ ዘንድ ከነሱ ጋር በኾንኩ ወይ ምኞቴ!» ይላል፡፡'),
('4:74', 87, 'እነዚያም ቅርቧን ሕይወት በመጨረሻይቱ ሕይወት የሚለውጡ በአላህ መንገድ ይጋደሉ፡፡ በአላህም መንገድ የሚጋደል፣ የሚገደልም ወይም የሚያሸንፍ ታላቅ ምንዳን በእርግጥ እንሰጠዋለን፡፡'),
('4:75', 87, 'በአላህ መንገድና ከወንዶች ከሴቶችና ከልጆችም የኾኑትን ደካሞች እነዚያን፡- «ጌታችን ሆይ! ከዚች ባለቤቶችዋ በዳይ ከኾኑት ከተማ አውጣን ከአንተም ዘንድ ለእኛ አሳዳሪን አድርግልን ከአንተ ዘንድም ለእኛ ረዳትን አድርግልን» የሚሉትን (ለማዳን) የማትጋደሉት ለእናንተ ምን አላችሁ'),
('4:76', 87, 'እነዚያ ያመኑት ሰዎች በአላህ መንገድ ይጋደላሉ፡፡ እነዚያ የካዱትም በጣዖት መንገድ ይጋደላሉ፡፡ የሰይጣንንም ጭፍሮች ተጋደሉ፡፡ የሰይጣን ተንኮል ደካማ ነውና፡፡'),
('4:77', 87, 'ወደእነዚያ ለእነርሱ፡- እጆቻችሁን (ከመጋደል) ሰብስቡ፣ ሶላትንም ደንቡን ጠብቃችሁ ስገዱ፣ ግዴታ ምጽዋትም ስጡ ወደ ተባሉት አላየህምን በእነርሱም ላይ መጋደል በተጻፈ ጊዜ ከእነሱ ከፊሎቹ ወዲያውኑ ሰዎችን አላህን እንደሚፈሩ ወይም የበለጠ ፍራቻን ይፈራሉ፡፡ «ጌታችን ሆይ! በእኛ ላይ መጋደልን ለምን ደነገግክ እስከ ቅርብ ጊዜ ድረስ አታቆየንም ኖሮአልን» ይላሉም፡፡ «የቅርቢቱ ሕይወት ጥቅም አነስተኛ ነው፡፡ መጨረሻይቱም ዓለም አላህን ለሚፈራ ሰው በላጭ ናት፡፡ በተምር ፍሬ ውስጥ ያለን ክር ያህል እንኳ አትበደሉም» በላቸው፡፡'),
('4:78', 87, '«የትም ስፍራ ብትኾኑ በጠነከሩ ሕንጻዎች ውስጥ ብትኾኑም እንኳ ሞት ያገኛችኋል፡፡ ደግም ነገር ብታገኛቸው ይህች ከአላህ ዘንድ ናት» ይላሉ፡፡ መከራም ብታገኛቸው «ይህቺ ከአንተ ዘንድ ናት» ይላሉ፡፡ «ሁሉም (ደጉም ክፉውም) ከአላህ ዘንድ ነው» በላቸው፡፡ ለእነዚህም ሰዎች ንግግርን ሊረዱ የማይቀርቡት ምን አላቸው'),
('4:79', 87, 'ከደግ ነገር የሚያገኝህ ከአላህ (ችሮታ) ነው፡፡ ከመከራም የሚደርስብህ ከራስህ (ጥፋት የተነሳ) ነው፡፡ ለሰዎችም ሁሉ መልክተኛ ኾነህ ላክንህ፡፡ መስካሪም በአላህ በቃ፡፡'),
('4:80', 87, 'መልክተኛውን የሚታዘዝ ሰው በእርግጥ አላህን ታዘዘ፡፡ ከትእዛዝም የሸሸ ሰው (አያሳስብህ)፡፡ በእነሱ ላይ ጠባቂ አድርገን አልላክንህምና፡፡'),
('4:81', 87, '«(ነገራችን) መታዘዝ ነው» ይላሉም፤ ከአንተም ዘንድ በወጡ ጊዜ ከነርሱ ከፊሎቹ ከዚያ (በፊትህ) ከሚሉት ሌላን (በልቦቻቸው) ያሳድራሉ፡፡ አላህም የሚያሳድሩትን ነገር ይጽፋል፡፡ ስለዚህ ተዋቸው፡፡ በአላህም ላይ ተጠጋ፡፡ መጠጊያም በአላህ በቃ፡፡'),
('4:82', 87, 'ቁርኣንን አያስተነትኑምን ከአላህ ሌላ ዘንድ በነበረ ኖሮ በርሱ ውስጥ ብዙን መለያየት ባገኙ ነበር፡፡'),
('4:83', 87, 'ከጸጥታ ወይም ከፍርሃት አንዳች (ወሬ) በመጣላቸውም ጊዜ እርሱን ያጋንናሉ፡፡ ወደ መልክተኛውና ከእነርሱ ወደ ትዕዛዙ ባለቤቶች (ወደ ዐዋቂዎቹ) በመለሱት ኖሮ እነዚያ ከእነርሱ (ነገሩን) የሚያውጣጡት ባወቁት ነበር፡፡ በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ ከጥቂቶች በስተቀር ሰይጣንን በተከተላችሁ ነበር፡፡'),
('4:84', 87, 'በአላህም መንገድ ተጋደል፡፡ ራስህን እንጅ ሌላን አትገደድም፡፡ ምእምናንንም (በመጋደል ላይ) አደፋፍር፡፡ አላህ የእነዚያን የካዱትን ኀይል ሊከለክል ይከጀላል፡፡ አላህም በኀይል በመያዙ የበረታ ቅጣቱም የጠነከረ ነው፡፡'),
('4:85', 87, 'መልካም መታደግን የሚታደግ ሰው ለእርሱ ከርስዋ ዕድል ይኖረዋል፡፡ መጥፎ መታደግንም የሚታደግ ሰው ለእርሱ ከርስዋ ድርሻ ይኖረዋል፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('4:86', 87, 'በሰላምታ በተከበራችሁም ጊዜ ከእርሷ ይበልጥ ባማረ (ሰላምታ) አክብሩ፡፡ ወይም (እርሷኑ) መልሷት፡፡ አላህ በነገሩ ሁሉ ላይ ተቆጣጣሪ ነውና፡፡'),
('4:87', 87, 'አላህ ከእርሱ በስተቀር አምላክ የለም፡፡ ወደ ትንሣኤ ቀን በርሱ ጥርጥር የሌለበት ሲኾን በእርግጥ ይሰበስባችኋል፡፡ በንግግርም ከአላህ ይበልጥ እውነተኛ ማነው'),
('4:88', 87, 'በመናፍቃንም (ነገር) አላህ በሥራዎቻቸው ወደ ክህደት የመለሳቸው ሲኾኑ ሁለት ክፍሎች የኾናችሁት ለናንተ ምን አላችሁ አላህ ያጠመመውን ሰው ልታቀኑ ታስባላችሁን አላህም ያሳሳተውን ሰው ለእርሱ መንገድን ፈጽሞ አታገኝለትም፡፡'),
('4:89', 87, '(እነርሱ) እንደ ካዱ ብትክዱና እኩል ብትኾኑ ተመኙ! በአላህም ሃይማኖት እስከሚሰደዱ ድረስ ከነሱ ወዳጆችን አትያዙ፡፡ (ከእምነት) ቢያፈገፍጉም ያዙዋቸው፤ (ማርኩዋቸው)፡፡ ባገኛችሁበትም ስፍራ ግደሉዋቸው፡፡ ከእነሱም ወዳጅንና ረዳትን አትያዙ፡፡'),
('4:90', 87, 'እነዚያ በእናንተና በእነርሱ መካከል ቃል ኪዳን ወዳላቸው ሕዝቦች የሚጠጉና ወይም እናንተን ለመጋደል ወይም ወገኖቻቸውን ለመጋደል ልቦቻቸው የተጨነቁ ኾነው የመጧዋችሁ ሲቀሩ፤ (እነዚያንስ አትጋደሉዋቸው)፡፡ አላህም በሻ ኖሮ በእናንተ ላይ ኀይል በሰጣቸውና በተጋደሉዋችሁ ነበር፡፡ ቢተዋችሁና ባይጋደሉዋችሁም ወደ እናንተም እርቅን ቢያቀርቡ አላህ ለእናንተ በነሱ ላይ (የመጋደል) መንገድን አላደረገም፡፡'),
('4:91', 87, 'ሌሎች ከእናንተ ለመዳን ከወገኖቻቸውም ለመዳን የሚፈልጉን ታገኛላችሁ፡፡ ወደ እውከት እንዲመለሱ በተጠሩ ቁጥር በርሷ ውስጥ ይመለሳሉ፡፡ ባይተውዋችሁና እርቅንም ባያቀርቡላችሁ፣ እጆቻቸውንም ባይሰበስቡ፣ ባገኛችኋቸው ስፍራ ማርኩዋቸው፡፡ ግደሉዋቸውም፡፡ እነዚያንም ለእናንተ በነሱ ላይ ግልጽ ማስረጃን አድርገናል፡፡'),
('4:92', 87, 'ለምእመንም በስሕተት ካልኾነ በቀር ምእመንን መግደል አይገባውም፡፡ ምእመንንም በስህተት የገደለ ሰው ያመነችን ጫንቃ (ባሪያ) ነጻ ማውጣትና ወደ ቤተሰቦቹም የምትሰጥ ጉማ ምሕረት ካላደረጉለት በስተቀር (መክፈል) አለበት፡፡ እርሱ (ተገዳዩ) ምእመን ሲኾን ለእናንተ ጠላት ከኾኑትም ሕዝቦች ቢኾን ያመነችን ጫንቃ ነጻ ማውጣት (ብቻ) አለበት፡፡ በእናንተና በእነሱ መካከል ቃል ኪዳን ካላቸውም ሕዝቦች ቢኾን ወደ ቤተሰቦቹ በእጅ የምትሰጥ ጉማና ያመነችን ጫንቃ ነጻ ማውጣት አለበት፡፡ ያላገኘ ሰውም ተከታታዮችን ሁለት ወሮች መጾም አለበት፡፡ አላህ መጸጸትን ለመቀበል (ደነገገላችሁ)፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('4:93', 87, 'ምእመንንም አስቦ የሚገድል ሰው ቅጣቱ በውስጧ ዘውታሪ ሲኾን ገሀነም ናት፡፡ አላህም በርሱ ላይ ተቆጣ፡፡ ረገመውም፡፡ ለእርሱም ከባድ ቅጣትን አዘጋጀ፡፡'),
('4:94', 87, 'እናንተ ያመናችሁ ሆይ! በአላህ መንገድ (ለመጋደል) በተጓዛችሁ ጊዜ አስረግጡ፡፡ ሰላምታንም ወደናንተ ላቀረበ ሰው የቅርቢቱን ሕይወት ጥቅም የምትፈልጉ ኾናችሁ ምእመን አይደለህም አትበሉ፡፡ አላህም ዘንድ ብዙ ዘረፋዎች አሉ፡፡ ከዚህ በፊት እንደዚሁ ነበራችሁ፡፡ አላህም በእናንተ ላይ ለገሰ ስለዚህ አስተውሉ፡፡ አላህ በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነውና፡፡'),
('4:95', 87, 'ከምእመናን የጉዳት ባለቤት ከኾኑት በቀር ተቀማጮቹና በአላህ መንገድ በገንዘቦቻቸውና በነፍሶቻቸው የሚታገሉት አይተካከሉም፡፡ በገንዘቦቻቸውና በነፍሶቻቸው የሚታገሉትን አላህ በተቀማጮቹ ላይ በደረጃ አበለጠ፡፡ ለሁሉም አላህ መልካሚቱን (ገነት) ተስፋ ሰጠ፡፡ ታጋዮቹንም በተቀማጮቹ ላይ አላህ በታላቅ ምንዳ አበለጠ፡፡'),
('4:96', 87, 'ከእርሱ ዘንድ በኾኑ ደረጃዎች (አበለጠ)፡፡ ምሕረትንም አደረገ፡፡ እዝነትም አዘነላቸው፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('4:97', 87, 'እነዚያ (ለእምንት ባለመሰደድ) ነፍሶቻቸውን በዳዮች ኾነው መላእክት (በበድር) የገደሉዋቸው (መላእክት ለነርሱ) «በምን ነገር ላይ ነበራችሁ» አሏቸው፡፡ «በምድር ውስጥ ደካሞች ነበርን» አሉ፡፡ «የአላህ ምድር ትሰደዱባት ዘንድ ሰፊ አልነበረችምን» አሉዋቸው፡፡ እነዚያም መኖሪያቸው ገሀነም ናት፡፡ በመመለሻነትም ከፋች!'),
('4:98', 87, 'ግን ከወንዶችና ከሴቶች ከሕፃኖችም ሲኾኑ (ለመውጣት) መላን የማይችሉና መንገድንም የማይምመሩ ደካሞች (ቅጣት የለባቸውም)'),
('4:99', 87, 'እነዚያም አላህ ከእነርሱ ይቅርታ ሊያደርግ ይሻል፡፡ አላህም ይቅር ባይ መሓሪ ነው፡፡'),
('4:100', 87, 'በአላህም መንገድ የሚሰደድ ሰው በምድር ውስጥ ብዙ መሰደጃንና ምቾትን ያገኛል፡፡ ወደ አላህና ወደ መልክተኛውም ስደተኛ ኾኖ ከቤቱ የሚወጣ ከዚያም (በመንገድ) ሞት የሚያገኘው ሰው ምንዳው በእርግጥ አላህ ዘንድ ተረጋገጠ፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('4:101', 87, 'በምድርም ላይ በተጓዛችሁ ጊዜ እነዚያ የካዱት ያውኩናል ብላችሁ ብትፈሩ ከሶላት (ባለ አራት ረከዓት የኾኑትን) ብታሳጥሩ በናንተ ላይ ኀጢአት የለም፡፡ ከሓዲዎች ለእናንተ በእርግጥ ግልጽ ጠላቶች ናቸውና፡፡'),
('4:102', 87, 'በውስጣቸውም በኾንክና ሶላትን ለእነርሱ ባስገደድካቸው ጊዜ ከእነሱ አንዲት ጭፍራ ካንተ ጋር ትቁም፡፡ መሣሪያዎቻቸውንም ይያዙ፡፡ በግንባራቸውም በተደፉ ጊዜ ከስተኋላችሁ ይኹኑ፡፡ (እነዚህ ይኺዱና) ያልሰገዱትም ሌሎቹ ጭፍሮች ይምጡ፡፡ ከአንተም ጋር ይስገዱ፡፡ ጥንቃቄያቸውንና መሣሪያዎቻቸውንም ይያዙ፡፡ እነዚያ የካዱት ከመሣሪያዎቻችሁና ከጓዞቻችሁ ብትዘነጉና በእናንተ ላይ አንዲትን መዘንበል ቢዘነበሉ ተመኙ፡፡ ከዝናብም የኾነ ችግር በእናንተ ቢኖር ወይም ሕመምተኞች ብትኾኑ መሣሪያዎቻችሁን ብታስቀምጡ በናንተ ላይ ኀጢአት የለም፡፡ ጥንቃቄያችሁንም ያዙ፡፡ አላህ ለከሓዲዎች አዋራጅን ቅጣት አዘጋጀ፡፡'),
('4:103', 87, 'ሶላትንም በፈጸማችሁ ጊዜ ቆማችሁም ተቀምጣችሁም በጎኖቻችሁም ላይ ተጋድማችሁ አላህን አውሱ፡፡ በረጋችሁም ጊዜ ሶላትን (አሟልታችሁ) ስገዱ፡፡ ሶላት በምእምናን ላይ በጊዜያት የተወሰነች ግዴታ ናትና፡፡'),
('4:104', 87, 'ሰዎቹንም በመፈለግ አትስነፉ፡፡ (ስትቆስሉ) የምትታመሙ ብትኾኑ እናንተ እንደምትታመሙ እነሱም ይታመማሉ፡፡ የማይከጅሉትንም ከአላህ ትከጅላላችሁ፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('4:105', 87, 'እኛ በሰዎች መካከል አላህ ባሳወቀህ ልትፈርድ ወደ አንተ መጽሐፉን በእውነት አወረድን፡፡ ለከዳተኞችም ተከራካሪ አትኹን፡፡'),
('4:106', 87, 'አላህንም ምሕረትን ለምን፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('4:107', 87, 'ከእነዚያም ነፍሶቻቸውን ከሚበድሉት ላይ አትከራከር፡፡ አላህ ከዳተኛ ኃጢአተኛ የኾነን ሰው አይወድምና፡፡'),
('4:108', 87, 'ከሰው ይደበቃሉ፡፡ አላህም እርሱ (በዕውቀቱ) ከእነሱ ጋር ሲኾን ከንግግር የማይወደውን ነገር (በልቦቻቸው) በሚያሳድሩ ጊዜ (ከእርሱ) አይደበቁም፡፡ አላህም በሚሠሩት ሁሉ (በዕውቀቱ) ከባቢ ነው፡፡'),
('4:109', 87, 'እነሆ እናንተ እነዚያ በቅርቢቱ ሕይወት ከነሱ የተከራከራችሁ ናችሁ፡፡ በትንሣኤ ቀን አላህን ስለእነሱ የሚከራከር ማን ነው ወይስ ለእነሱ ኃላፊና መመኪያ የሚኾን ማን ነው'),
('4:110', 87, 'መጥፎም የሚሠራ ሰው ወይም ነፍሱን የሚበድል ከዚያም (ተጸጽቶ) አላህን ምሕረት የሚለምን አላህን መሓሪ አዛኝ ኾኖ ያገኘዋል፡፡'),
('4:111', 87, 'ኀጢአትንም የሚሠራ ሰው የሚሠራው ጥፋት በራሱ ላይ ነው፡፡ አላህም ዐዋቂ ጥበበኛ ነው፤'),
('4:112', 87, 'ኀጢአትን ወይም አበሳን የሚሠራም ሰው ከዚያም በእርሱ ንጹሕን ሰው የሚሰድብ ቅጥፈትንና ግልጽ አበሳን በቁርጥ ተሸከመ፡፡'),
('4:113', 87, 'የአላህም ችሮታና እዝነቱ ባንተ ላይ ባልነበረ ኖሮ ከእነሱ የኾኑ ጭፍሮች ሊያሳስቱህ ባሰቡ ነበር፡፡ ነፍሶቻቸውንም እንጅ ሌላን አያሳስቱም፡፡ በምንም አይጐዱህም፡፡ አላህም በአንተ ላይ መጽሐፍንና ጥበብን አወረደ፡፡ የማታውቀውንም ሁሉ አስተማረህ፡፡ የአላህም ችሮታ በአንተ ላይ ታላቅ ነው፡፡'),
('4:114', 87, 'ከውይይታቸው በምጽዋት ወይም በበጎ ሥራ ወይም በሰዎች መካከል በማስታረቅ ከሚያዙ ሰዎች ውይይት በስተቀር በብዙው ውስጥ ደግ ነገር የለበትም፡፡ ይኸንንም (የተባለውን) የአላህን ውዴታ ለመፈለግ የሚሠራ ሰው ታላቅ ምንዳን እንሰጠዋለን፡፡'),
('4:115', 87, 'ቅኑም መንገድ ለእርሱ ከተገለጸ በኋላ መልክተኛውን የሚጨቃጨቅና ከምእምኖቹ መንገድ ሌላ የኾነን የሚከተል ሰው (በዚህ ዓለም) በተሾመበት (ጥመት) ላይ እንሾመዋለን፤ ገሀነምንም እናገባዋለን፡፡ መመለሻይቱም ከፋች!'),
('4:116', 87, 'አላህ በርሱ የማጋራትን (ወንጀል) አይምርም፡፡ ከዚህም ወዲያ ያለውን ለሚሻው ሰው ይምራል፡፡ በአላህም የሚያጋራ ሰው (ከእውነት) የራቀን መሳሳት በእርግጥ ተሳሳተ፡፡'),
('4:117', 87, 'ከእርሱ ሌላ እንስታትን እንጅ አይገዙም፡፡ አመጸኛ ሰይጣንንም እንጅ ሌላን አይግገዙም፡፡'),
('4:118', 87, '«አላህ የረገመውን ከባሮችህም የተወሰነን ድርሻ በእርግጥ እይዛለሁ» ያለውን (ሰይጣን እንጅ ሌላን አይከተሉም)፡፡'),
('4:119', 87, 'በእርግጥ አጠማቸዋለሁም፡፡ (ከንቱን) አስመኛቸዋለሁም፡፡ አዛቸውምና የእንስሶችን ጆሮዎች ይተለትላሉ፡፡ አዛቸውምና የአላህን ፍጥረት ይለውጣሉ፤ (ያለውን ይከተላሉ)፡፡ ከአላህም ሌላ ሰይጣንን ረዳት አድርጎ የሚይዝ ሰው ግልጽ ክስረትን በአርግጥ ከሰረ፡፡'),
('4:120', 87, '(የማይፈጸመውን) ተስፋ ይሰጣቸዋል፡፡ ያስመኛቸዋልም፡፡ ሰይጣንም ለማታለል እንጅ አይቀጥራቸውም፡፡'),
('4:121', 87, 'እነዚያ መኖሪያቸው ገሀነም ናት፡፡ ከርስዋም መሸሻን አያገኙም፡፡'),
('4:122', 87, 'እነዚያም ያመኑና በጎ ሥራዎችን የሠሩ በሥራቸው ወንዞች የሚፈሱባቸውን ገነቶች ዘላለም በውስጣቸው ዘውታሪዎች ሲኾኑ እናገባቸዋለን፡፡ አላህ እውነተኛን ተስፋ ሰጣቸው፡፡ በንግግርም ከአላህ ይበልጥ እውነተኛ ማን ነው'),
('4:123', 87, '(ነገሩ) በምኞታችሁና በመጽሐፉ ሰዎች ምኞት አይደለም፡፡ መጥፎን የሚሠራ ሰው በእርሱ ይቀጣል፡፡ ለእርሱም ከአላህ ሌላ ጠባቂንም ረዳትንም አያገኝም፡፡'),
('4:124', 87, 'ከወንድ ወይም ከሴት እርሱ አማኝ ኾኖ ከበጎ ሥራዎች አንዳችን የሚሠራም ሰው እነዚያ ገነትን ይገባሉ፡፡ በተምር ፍሬ ላይ ያለችን ነጥብ ያክል እንኳ አይበደሉም፡፡'),
('4:125', 87, 'እርሱ መልካም ሠሪ ኾኖ ፊቱን ለአላህ ከሰጠና የኢብራሂምንም መንገድ ቀጥተኛ ሲኾን ከተከተለ ሰው ይበልጥ ሃይማኖቱ ያማረ ማን ነው አላህም ኢብራሂምን ፍጹም ወዳጅ አድርጐ ያዘው፡፡'),
('4:126', 87, 'በሰማያት ያለውና በምድር ያለው ሁሉ የአላህ ነው፡፡ አላህም በነገሩ ሁሉ በዕውቀት ከባቢ ነው፡፡'),
('4:127', 87, 'በሴቶችም ነገር ያስተቹሃል፡፡ አላህ በእነርሱ ይነግራችኋል፡፡ ያም በመጽሐፉ በእናንተ ላይ የሚነበበው በእነዚያ ለእነርሱ (ከውርስ) የተጻፈላቸውን በማትሰጧቸውና ልታገቧቸው በማትፈልጉት የቲሞች ሴቶች (ይህንን እንዳታደርጉ) ከሕፃናትም ለኾኑት ደካሞች መብታቸውን እንድትሰጡ ለየቲሞችም በትክክል አንድትቆሙ (ይነግራችኋል) በላቸው፡፡ ከበጎም ሥራ ማናቸውንም ብትሠሩ አላህ እርሱን ዐዋቂ ነው፡፡'),
('4:128', 87, 'ሴትም ከባልዋ ጥላቻን ወይም ፊቱን ማዞርን ብታውቅ በመካከላቸው መስማማትን ቢስማሙ በሁለቱ ላይ ኀጢአት የለም፡፡ መታረቅም መልካም ነው፡፡ ነፍሶችም ንፍገት ተጣለባቸው፡፡ መልካምም ብትሠሩ ብትጠነቀቁም አላህ በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('4:129', 87, 'በሴቶችም መካከል ምንም እንኳ ብትጓጉ (በፍቅር) ለማስተካከል አትችሉም፡፡ እንደ ተንጠለጠለችም አድርጋችሁ ትተዋት ዘንድ (ወደምትወዷት) መዘንበልን ሁሉ አትዘንበሉ፡፡ ብታበጁም ብትጠነቀቁም አላህ መሓሪ አዛኝ ነው፡፡'),
('4:130', 87, 'ቢለያዩም አላህ ሁሉንም በችሮታው ያብቃቃቸዋል፡፡ አላህም ችሮታው ሰፊ ጥበበኛ ነው፡፡'),
('4:131', 87, 'በሰማያት ያለውና በምድርም ያለው ሁሉ የአላህ ነው፡፡ እነዚያንም ከበፊታችሁ መጽሐፍን የተሰጡትን እናንተንም አላህን ፍሩ በማለት በእርግጥ አዘዝን፡፡ ብትክዱም በሰማያትና በምድር ያለው ሁሉ የአላህ ነው፡፡ (አትጐዱትም)፡፡ አላህም ተብቃቂ ምስጉን ነው፡፡'),
('4:132', 87, 'በሰማያት ያለውና በምድርም ያለው ሁሉ የአላህ ነው፡፡ መመከያም በአላህ በቃ፡፡'),
('4:133', 87, 'ሰዎች ሆይ!(አላህ) ቢሻ ያስወግዳችኋል፡፡ ሌሎችንም ያመጣል፡፡ አላህም በዚህ ላይ ቻይ ነው፡፡'),
('4:134', 87, 'የቅርቢቱን ዓለም ምንዳ የሚፈልግ የኾነ ሰው አላህ ዘንድ የቅርቢቱና የመጨረሻይቱ ምንዳ አልለ፡፡ አላህም ሰሚ ተመልካች ነው፡፡'),
('4:135', 87, 'እናንተ ያመናችሁ ሆይ! በትክክል (ፍትሕ) ቀዋሚዎች በነፈሶቻችሁ ወይም በወላጆችና በቅርብ ዘመዶች ላይ ቢኾንም እንኳ ለአላህ መስካሪዎች ኹኑ፡፡ ሀብታም ወይም ድኻ ቢኾን አላህ በእነርሱ (ከእናንተ) ይበልጥ ተገቢ ነው፡፡ እንዳታደሉም ዝንባሌን አትከተሉ፡፡ ብታጠምሙም ወይም (መመስከርን) ብትተው አላህ በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('4:136', 87, 'እናንተ ያመናችሁ ሆይ! በአላህና በመልክተኛው በዚያም በመልክተኛው ላይ ባወረደው መጽሐፍ በዚያም ከበፊቱ ባወረደው መጽሐፍ እመኑ፡፡ በአላህና በመላእክቱም፣ በመጽሐፎቹም፣ በመልክተኞቹም፣ በመጨረሻውም ቀን፣ የካደ ሰው (ከእውነት) የራቀን መሳሳት በእርግጥ ተሳሳተ፡፡'),
('4:137', 87, 'እነዚያ (በሙሳ) ያመኑና ከዚያም (ወይፈንን በመገዛት) የካዱ ከዚያም (በእርሱ) ያመኑ ከዚያም (በዒሳ) የካዱ ከዚያም (በሙሐመድ) ክሕደትን የጨመሩ አላህ ለእነሱ የሚምራቸውና ቅኑን መንገድ የሚመራቸው አይደለም፡፡'),
('4:138', 87, 'መናፍቃንን ለእነርሱ አሳማሚ ቅጣት ያላቸው መኾኑን አብስራቸው፡፡'),
('4:139', 87, 'እነዚያ ከምእምናን ሌላ ከሓዲዎችን ወዳጆች አድርገው የሚይዙ እነሱ ዘንድ ልቅናን ይፈልጋሉን ልቅናውም ሁሉ ለአላህ ብቻ ነው፡፡'),
('4:140', 87, 'በእናንተም ላይ በመጽሐፉ ውስጥ የአላህን አንቀጾች በርሷ ሲካድባትና በርሷም ሲላገጥባት በሰማችሁ ጊዜ በሌላ ወሬ ውስጥ እስከሚገቡ ድረስ ከእነሱ ጋር አትቀመጡ፡፡ ማለትን በእርግጥ አወረደ፡፡ እናንተ ያንጊዜ ብጤያቸው ናችሁና፡፡ አላህ መናፍቃንን እና ከሓዲዎችን በሙሉ በገሀነም ውስጥ ሰብሳቢ ነውና፡፡'),
('4:141', 87, 'እነዚያ በእናንተ (የጊዜን መዘዋወር) የሚጠባበቁ ናቸው፡፡ ለእናንተም ከአላህ የኾነ አሸናፊነት «ቢኖራችሁ ከእናንተ ጋር አልነበርንምን» ይላሉ፡፡ ለከሓዲዎችም ዕድል ቢኖር «(ከአሁን በፊት) በእናንተ ላይ አልተሾምንምን (እና አልተውናችሁምን) ከምእምናንም (አደጋ) አልከለከልናችሁምን» ይላሉ፡፡ አላህም በትንሣኤ ቀን በመካከላችሁ ይፈርዳል፡፡ አላህም ለከሓዲዎች በምእምናን ላይ መንገድን በፍጹም አያደርግም፡፡'),
('4:142', 87, 'መናፍቃን አላህን ያታልላሉ፡፡ እርሱም አታላያቸው ነው፡፡ (ይቀጣቸዋል)፡፡ ወደ ሶላትም በቆሙ ጊዜ ታካቾች ስዎችን የሚያሳዩ ኾነው ይቆማሉ፡፡ አላህንም ጥቂትን እንጅ አያወሱም፡፡'),
('4:143', 87, 'በዚህ መካከል ወላዋዮች ኾነው (ያሳያሉ)፡፡ ወደእነዚህም ወደእነዚያም አይደሉም፡፡ አላህም ያሳሳተውን ሰው ለእርሱ (የቅንነት) መንገድን በፍፁም አታገኝለትም፡፡'),
('4:144', 87, 'እናንተ ያመናችሁ ሆይ! ከምእምናን ሌላ ከሓዲዎችን ወዳጆች አድርጋችሁ አትያዙ፤ ለአላህ በናንተ ላይ ግልጽ ማስረጃዎችን ልታደርጉ ትፈልጋላችሁን'),
('4:145', 87, 'መናፍቃን በእርግጥ ከእሳት በታችኛው አዘቅት ውስጥ ናቸው፡፡ ለእነሱም ረዳትን አታገኝላቸውም፡፡'),
('4:146', 87, 'እነዚያ የተመለሱ (ሥራቸውን) ያሳመሩም፤ በአላህም የተጠበቁ፤ ሃይማኖታቸውንም ለአላህ ፍጹም ያደረጉ ሲቀሩ፡፡ እነዚያስ ከምእምናን ጋር ናቸው፡፡ ለምእምናንም አላህ ታላቅን ምንዳ በእርግጥ ይሰጣል፡፡'),
('4:147', 87, 'ብታመሰግኑና ብታምኑ አላህ እናንተን በመቅጣት ምን ያደርጋል አላህም ወረታን መላሽ ዐዋቂ ነው፡፡'),
('4:148', 87, 'አላህ ከንግግር በክፉው መጮህን ከተበደለ ሰው (ጩኸት) በቀር አይወድም፡፡ አላህ ሰሚ ዐዋቂ ነው፡፡'),
('4:149', 87, 'ደግ ነገርን ብትገልጹ ወይም ብትደብቁት ወይም ከመጥፎ ነገር (ከበደል) ይቅርታ ብታደርጉ አላህ ይቅር ባይ ኃያል ነው፡፡'),
('4:150', 87, 'እነዚያ በአላህና በመልክተኞቹ የሚክዱ፣ በአላህና በመልክተኞቹም መካከል መለየትን የሚፈልጉ፣ «በከፊሉም እናምናለን በከፊሉም እንክዳለን» የሚሉ፣ በዚህም መካከል መንገድን ሊይዙ የሚፈልጉ፤'),
('4:151', 87, 'እነዚያ በውነት ከሓዲዎቹ እነርሱ ናቸው፡፡ ለከሓዲዎችም አዋራጅን ቅጣት አዘጋጅተናል፡፡'),
('4:152', 87, 'እነዚያም በአላህና በመልክተኞቹ ያመኑ ከነርሱም በአንድም መካከል ያልለዩ እነዚያ ምንዳዎቻቸውን በእርግጥ ይሰጣቸዋል፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('4:153', 87, 'የመጽሐፉ ሰዎች በነሱ ላይ ከሰማይ መጽሐፍን እንድታወርድ ይጠይቁሃል፡፡ ከዚያም የከበደን (ነገር) ሙሳን በእርግጥ ጠይቀዋል፡፡ «አላህንም በግልጽ አሳየን» ብለዋል፡፡ በበደላቸውም መብረቅ ያዘቻቸው፡፡ ከዚያም ተዓምራቶች ከመጡላቸው በኋላ ወይፈኑን (አምላክ አድርገው) ያዙ፡፡ ከዚያም ይቅር አልን፡፡ ሙሳንም ግልጽ ስልጣንን ሰጠነው፡፡'),
('4:154', 87, 'በቃል ኪዳናቸውም ምክንያት የጡርን ተራራ ከበላያቸው አነሳን፡፡ ለእነሱም «ደጃፉን አጎንባሾች ኾናችሁ ግቡ» አልን፡፡ ለእነርሱም «በሰንበት ቀን ትዕዛዝን አትተላልፉ» አልን፡፡ ከእነሱም ከባድን ቃል ኪዳን ያዝን፡፡'),
('4:155', 87, 'ቃል ኪዳናቸውንም በማፍረሳቸው፣ በአላህም አንቀጾች በመካዳቸው፣ ነቢያትንም ያለ አግባብ በመግደላቸውና «ልቦቻችን ሽፍኖች ናቸው» በማለታቸው ምክንያት (ረገምናቸው)፡፡ በእውነቱ በክህደታቸው ምክንያት አላህ በርሷ (በልቦቻቸወ) ላይ አተመ፡፡ ስለዚህ ጥቂትን እንጅ አያምኑም፡፡'),
('4:156', 87, 'በመካዳቸውም በመርየም ላይ ከባድ ቅጥፈትን በመናገራቸውም ምክንያት (ረገምናቸው)፡፡'),
('4:157', 87, '«እኛ የአላህን መልክተኛ የመርየምን ልጅ አልመሲሕ ዒሳን ገደልን» በማለታቸውም (ረገምናቸው)፡፡ አልገደሉትም አልሰቀሉትምም፡፡ ግን ለእነሱ (የተገደለው ሰው በዒሳ) ተመሰለ፡፡ እነዚያም በእርሱ ነገር የተለያዩት ከእርሱ (መገደል) በመጠራጠር ውስጥ ናቸው፡፡ ጥርጣሬን ከመከተል በስተቀር በእርሱ ነገር ምንም ዕውቀት የላቸውም፡፡ በእርግጥም አልገደሉትም፡፡'),
('4:158', 87, 'ይልቁንስ አላህ (ኢሳን) ወደርሱ አነሳው፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('4:159', 87, 'ከመጽሐፉም ሰዎች ከመሞቱ በፊት በእርሱ (በዒሳ) በእርግጥ የሚያምን እንጅ (አንድም) የለም፡፡ በትንሣኤም ቀን በነሱ ላይ መስካሪ ይኾናል፡፡'),
('4:160', 87, 'ከእነዚያ ይሁዳውያን ከኾኑትም በተገኘው በደል ሰዎችንም ከአላህ መንገድ በብዙ በመከልከላቸው ምክንያት ለእነሱ ተፈቅደው የነበሩትን ጣፋጮች ምግቦች በእነርሱ ላይ እርም አደረግንባቸው፡፡'),
('4:161', 87, 'ከእርሱ በቁርጥ የተከለከሉ ሲኾኑ አራጣንም በመያዛቸውና የሰዎችን ገንዘቦች ያለ አግባብ (በጉቦ) በመብላታቸውም ምክንያት (የተፈቀደላቸውን እርም አደረግንባቸው)፡፡ ከእነሱም ለከሓዲዎቹ አሳማሚን ቅጣት አዘጋጀን፡፡'),
('4:162', 87, 'ግን ከነርሱ ውስጥ በዕውቀት የጠለቁትና ምእምናኖቹ በአንተ ላይ በተወረደውና ከአንተም በፊት በተወረደው መጽሐፍ የሚያምኑ ሲኾኑ ሶላትንም ደንቡን ጠብቀው ሰጋጆችን (እናመሰግናለን)፡፡ ዘካንም ሰጪዎቹ በአላህና በመጨረሻዎቹም ቀን አማኞቹ እነዚያ ታላቅ ምንዳን በእርግጥ እንሰጣቸዋለን፡፡'),
('4:163', 87, 'እኛ ወደ ኑሕና ከርሱ በኋላ ወደ ነበሩት ነቢያት እንዳወረድን ወደ አንተም አወረድን፡፡ ወደ ኢብራሂምም፣ ወደ ኢስማዒልም፣ ወደ ኢስሓቅም፣ ወደ ያዕቆብም፣ ወደ ነገዶቹም፣ ወደ ዒሳም፣ ወደ አዩብም፣ ወደ ዩኑስም፣ ወደ ሃሩንና፣ ወደ ሱለይማንም አወረድን፡፡ ለዳውድም ዘቡርን ሰጠነው፡፡'),
('4:164', 87, 'ከዚህም በፊት በአንተ ላይ በእርግጥ የተረክናቸውን መልክተኞች ባንተ ላይም ያልተረክናቸውን መልክተኞች (እንደላክን ላክንህ)፡፡ አላህም ሙሳን ማነጋገርን አነጋገረው፡፡'),
('4:165', 87, 'ከመልክተኞቹ በኋላ ለሰዎች በአላህ ላይ አስረጅ እንዳይኖር አብሳሪዎችና አስፈራሪዎች የኾኑን መልክተኞች (ላክን)፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('4:166', 87, 'ግን አላህ ባንተ ላይ ባወረደው ይመሰክራል፡፡ በዕውቀቱ አወረደው፡፡ መላእክቱም ይመሰክራሉ፡፡ መስካሪም በአላህ በቃ፡፡'),
('4:167', 87, 'እነዚያ የካዱት ከአላህም መንገድ ያገዱት (ከእውነት) የራቀን መሳሳት በእርግጥ ተሳሳቱ፡፡'),
('4:168', 87, 'እነዚያ የካዱ የበደሉም አላህ የሚምራቸውና (ቅን) መንገድን የሚመራቸው አይደለም፡፡'),
('4:169', 87, 'ግን በውስጧ ዘለዓለም ዘውታሪዎች ሲኾኑ የገሀነምን መንገድ (ይመራቸዋል)፡፡ ይህም በአላህ ላይ ገር ነው፡፡'),
('4:170', 87, 'እናንተ ሰዎች ሆይ! መልክተኛው እውነትን ከጌታችሁ አመጣላችሁ፡፡ እመኑም ለናንተ የተሻለ (ይኾናል)፡፡ ብትክዱም (አትጐዱትም)፡፡ በሰማያትና በምድር ያለው ሁሉ የአላህ ነውና፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('4:171', 87, 'እናንተ የመጽሐፉ ሰዎች ሆይ! በሃይማኖታችሁ ወሰንን አትለፉ፡፡ በአላህም ላይ እውነትን እንጅ አትናገሩ፡፡ የመርየም ልጅ አልመሲሕ ዒሳ የአላህ መልክተኛ ወደ መርየም የጣላት «የኹን» ቃሉም ከእርሱ የኾነ መንፈስም ብቻ ነው፡፡ በአላህና በመልክተኞቹም እመኑ፡፡ « (አማልክት) ሦስት ናቸው» አትበሉም፡፡ ተከልከሉ፤ ለእናንተ የተሻለ ይኾናልና፡፡ አላህ አንድ አምላክ ብቻ ነው፡፡ ለእርሱ ልጅ ያለው ከመኾን የጠራ ነው፡፡ በሰማያትና በምድር ያለ ሁሉ የርሱ ነው፡፡ መመኪያም በአላህ በቃ፡፡'),
('4:172', 87, 'አልመሲሕ (ኢየሱስ) ለአላህ ባሪያ ከመኾን ፈጽሞ አይጠየፍም፡፡ ቀራቢዎች የኾኑት መላእክትም (አይጠየፉም)፡፡ እርሱን ከመገዛት የሚጠየፍና የሚኮራም ሰው (አላህ) ሁሉንም ወደ እርሱ በእርግጥ ይሰበስባቸዋል፡፡'),
('4:173', 87, 'እነዚያማ ያመኑት መልካሞችንም የሠሩት ምንዳዎቻቸውን ይሞላላቸዋል፡፡ ከችሮታውም ይጨምርላቸዋል፡፡ እነዚያን የተጠየፉትንና የኮሩትንማ አሳማሚን ቅጣት ይቀጣቸዋል፡፡ ከአላህም ሌላ ለእነሱ ዝምድንና ረዳትን አያገኙም፡፡'),
('4:174', 87, 'እናንተ ሰዎች ሆይ! ከጌታችሁ ዘንድ በእርግጥ አስረጅ መጣላችሁ፤ ወደእናንተም ገላጭ የኾነን ብርሃን (ቁርኣንን) አወረድን፡፡'),
('4:175', 87, 'እነዚያማ በአላህ ያመኑ በርሱም የተጠበቁ ከሱ በኾነው እዝነትና ችሮታ ውስጥ በእርግጥ ያስገባቸዋል፡፡ ወደእርሱም ቀጥተኛ መንገድን ይመራቸዋል፡፡'),
('4:176', 87, 'ይጠይቁሃል በላቸው፡- «ወላጅና ልጅ ሳይኖረው በሚወረስ ሰው አላህ ይነግራችኋል፡፡ ለእርሱ ልጅ የሌለው ሰው ቢሞት ለእርሱም እኅት ብትኖረው ለእርስዋ ከተወው ረጀት ግማሹ አላት፡፡ እርሱም ለርሷ ልጅ የሌላት እንደኾነች (በሙሉ) ይወርሳታል፡፡ ሁለት (እኅቶች ወይም ከሁለት በላይ) ቢኾኑም ከተወው ረጀት ከሦስት ሁለት እጁ አላቸው፡፡ ወንድሞች (ና እኅቶች) ወንዶችና ሴቶች ቢኾኑም ለወንዱ የሁለት ሴቶች ድርሻ ብጤ አለው፡፡ አላህ እንዳትሳሳቱ ለእናንተ ያብራራል፡፡ አላህም በነገሩ ሁሉ ዐዋቂ ነው፡፡»'),
('5:1', 87, 'እናንተ ያመናችሁ ሆይ! በቃል ኪዳኖች ሙሉ፡፡ በእናንተ ላይ የሚነበበው ብቻ ሲቀር፡፡ የግመል፣ የከብት፣ የበግና የፍየል እንስሳዎች እናንተ በሐጅ ሥራ ላይ ኾናችሁ ማደንን የተፈቀደ ሳታደረጉ ለእናንተ ተፈቀዱ፡፡ አላህ የሚሻውን ይፈርዳል፡፡'),
('5:2', 87, 'እናንተ ያመናችሁ ሆይ! የአላህ (ክልክል ያደረጋቸውን) ምልክቶች የተፈቀዱ አታድርጉ፡፡ የተከበረውንም ወር በመጋደል አትድፈሩ፡፡ ወደ መካ የሚነዱትን መስዋዕትና የሚታበቱባቸውንም ገመዶች ከጌታቸው ችሮታንና ውዴታን ፈልገው ወደ ተከበረው ቤት አሳቢዎችንም ሰዎች (አትንኩ)፡፡ ከሐጅም ሥራ በወጣችሁ ጊዜ ዐድኑ፡፡ ከተከበረው መስጊድ ስለከለከሉዋችሁ ሰዎችን መጥላትም (በነሱ ላይ) ወሰን እንድታልፉ አይገፋፋችሁ፡፡ በበጎ ነገርና አላህን በመፍራትም ተረዳዱ፡፡ ግን በኃጢአትና ወሰንን በማለፍ አትረዳዱ፡፡ አላህንም ፍሩ፡፡ አላህ ቅጣተ ብርቱ ነውና፡፡'),
('5:3', 87, 'በክት፣ ፈሳሽ ደምም፣ የእሪያ (አሣማ) ሥጋም፣ በርሱ ከአላህ (ስም) ሌላ የተነሳበትም፣ የታነቀችም፣ ተደብድባ የተገደለችም፣ ተንከባላ የሞተችም፣ በቀንድ ተውግታ የሞተችም፣ ከርሷ አውሬ የበላላትም (ከእነዚህ በሕይወት ደርሳችሁ) ያረዳችሁት ብቻ ሲቀር ለጣዖታትም የታረደው በአዝላምም ዕድልን መፈለጋችሁ በእናንተ ላይ እርም ተደረገ፡፡ ይህ ድርጊት አመጽ ነው፡፡ ዛሬ እነዚያ የካዱት ከሃይማኖታችሁ ተስፋ ቆረጡ፡፡ ስለዚህ አትፍሩዋቸው፡፡ ፍሩኝም፡፡ ዛሬ ሃይማኖታችሁን ለናንተ ሞላሁላችሁ፡፡ ጸጋዬንም በናንተ ላይ ፈጸምኩ፡፡ ለእናንተም ኢስላምን ከሃይማኖት በኩል ወደድኩ፡፡ በረኃብ ወቅት ወደ ኃጢአት ያዘነበለ ሳይሆን (እርም የኾኑትን ለመብላት) የተገደደ ሰውም (ይብላ)፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('5:4', 87, 'ለእነርሱ ምን እንደተፈቀደላቸው ይጠይቁሃል፡፡ በላቸው፡- «ለእናንተ መልካሞች ሁሉና እነዚያም ከአዳኞች አሰልጣኞች ኾናችሁ ያስተማራችኋቸው (ያደኑት) ተፈቀደላችሁ፡፡ አላህ ከአስተማራችሁ ዕውቀት ታስተምሯቸዋላችሁ፡፡ ለእናንተም ከያዙላችሁ ነገር ብሉ፡፡ በርሱም ላይ የአላህን ስም አውሱ፡፡ አላህንም ፍሩ አላህ ምርመራው ፈጣን ነውና፡፡»'),
('5:5', 87, 'ዛሬ መልካሞች ሁሉ ለናንተ ተፈቀዱ፡፡ የእነዚያም መጽሐፍን የተሰጡት ሰዎች ምግብ (ያረዱት) ለእናንተ የተፈቀደ ነው፡፡ ምግባችሁም ለነሱ የተፈቀደ ነው፡፡ ከምእመናት ጥብቆቹም ከእነዚያ ከእናንተ በፊት መጽሐፍን ከተሰጡት ሴቶች ጥብቆቹም፤ ዘማዊዎችና (ዝሙተኞች) የምስጢር ወዳጅ ያዢዎች ሳትኾኑ ጥብቆች ኾናችሁ መህሮቻቸውን በሰጣችኋቸው ጊዜ (ልታገቡዋቸው የተፈቀዱ ናቸው)፡፡ ከእምነትም የሚመለስ ሰው በእርግጥ ሥራው ተበላሸ፡፡ በመጨረሻም ቀን እርሱ ከከሳሪዎቹ ነው፡፡'),
('5:6', 87, 'እናንተ ያመናችሁ ሆይ! ወደ ሶላት በቆማችሁ (ለመቆም ባሰባችሁ) ጊዜ ፊቶቻችሁን፣ እጆቻችሁንም እስከ ክርኖች እጠቡ፡፡ ራሶቻችሁንም (በውሃ) አብሱ፡፡ እግሮቻችሁንም እስከ ቁርጭምጭሚቶች (እጠቡ)፡፡ (ሴት ጋር በመገናኘት ወይም በሌላ ምክንያት «ጀናባ») ብትኾኑ (ገላችሁን) ታጠቡ፡፡ በሽተኞች ወይም በጉዞ ላይ ብትኾኑም ወይም ከእናንተ አንዳችሁ ከዓይነ ምድር ቢመጣ ወይም ሴቶችን ብትነካኩና ውሃን ባታገኙ ንጹሕን የምድር ገጽ አስቡ ፡፡ ከሱም ፊቶቻችሁንና እጆቻችሁን አብሱ፡፡ አላህ በእናንተ ላይ ምንም ችግር ሊያደርግ አይሻም፡፡ ግን ታመሰግኑ ዘንድ ሊያጠራችሁና ጸጋውን በእናንተ ላይ ሊሞላ ይሻል፡፡'),
('5:7', 87, 'በእናንተም ላይ (የለገሰውን) የአላህን ጸጋ ያንንም ሰምተናል ታዘናልም ባላችሁ ጊዜ በርሱ ያጠበቀባችሁን ቃል ኪዳኑን አስታውሱ፡፡ አላህንም ፍሩ፡፡ አላህ በደረቶች ውስጥ ያለውን ሁሉ ዐዋቂ ነውና፡፡'),
('5:8', 87, 'እናንተ ያመናችሁ ሆይ! ለአላህ ቀጥተኞች በትክክል መስካሪዎች ኹኑ፡፡ ሕዝቦችንም መጥላት ባለማስተካከል ላይ አይገፋፋችሁ፡፡ አስተካክሉ፡፡ እርሱ (ማስተካከል) ለአላህ ፍራቻ በጣም የቀረበ ነው፡፡ አላህንም ፍሩ፡፡ አላህ በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('5:9', 87, 'እነዚያንም ያመኑትንና በጎ ሥራዎችን የሠሩትን አላህ (ገነትን) ተስፋ አደረገላቸው፡፡ ለእነርሱ ምሕረትና ታላቅ ምንዳ አላቸው፡፡'),
('5:10', 87, 'እነዚያም የካዱና በተአምራቶቻችን ያስተባበሉ እነዚያ የእሳት ጓዶች ናቸው፡፡'),
('5:11', 87, 'እናንተ ያመናችሁ ሆይ! ሕዝቦች እጆቻቸውን ወደ እናንተ ሊዘረጉ ባሰቡና እጆቻቸውን ከእናንተ ላይ በከለከላችሁ ጊዜ በናንተ ላይ (የዋለላችሁን) የአላህን ጸጋ አስታውሱ፡፡ አላህንም ፍሩ፡፡ ምእመናንም በአላህ ላይ ይመኩ፡፡'),
('5:12', 87, 'አላህም የእስራኤልን ልጆች የጠበቀ ቃል ኪዳን በእርግጥ ያዘባቸው፡፡ ከነርሱም ዐስራ ሁለትን አለቆች አስነሳን፡፡ አላህም አላቸው፤ «እኔ ከናንተ ጋር ነኝ፤ ሶላትን ብታስተካክሉ ግዴታ ምጽዋትንም ብትሰጡ በመልክተኞቼም ብታምኑ ብትረዱዋቸውም ለአላህም መልካም ብድርን ብታበድሩ ኀጢአቶቻችሁን ከናንተ በእርግጥ አብሳለሁ፡፡ ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶችም በእርግጥ አገባችኋለሁ፡፡ ከዚህም በኋላ ከእናንተ የካደ ሰው ቀጥተኛውን መንገድ በእርግጥ ተሳሳተ፡፡»'),
('5:13', 87, 'ቃል ኪዳናቸውንም በማፍረሳቸው ረገምናቸው፡፡ ልቦቻቸውንም ደረቆች አደረግን፡፡ ቃላትን ከቦታዎቻቸው ይለውጣሉ፡፡ በርሱም ከታዘዙበት ነገር ፈንታን ተው፡፡ ከእነሱም ጥቂቶች ሲቀሩ ከነርሱ የኾነን ክዳት የምታውቅባቸው ከመኾን አትወገድም፡፡ ከእነርሱም ይቅርታ አድርግ እለፋቸውም፡፡ አላህ መልካም ሠሪዎችን ይወዳልና፡፡'),
('5:14', 87, 'ከእነዚያም እኛ ክርስቲያኖች ነን ካሉት የጠበቀ ቃል ኪዳናቸውን ያዝን፡፡ በእርሱም ከታዘዙበት ነገር ፈንታን ተውት፡፡ ስለዚህ እስከ ትንሣኤ ቀን ድረስ በመካከላቸው ጠብንና ጥላቻን ጣልንባቸው፡፡ አላህም ይሠሩት የነበሩትን ሁሉ በእርግጥ ይነግራቸዋል፡፡'),
('5:15', 87, 'የመጽሐፉ ባለቤቶች ሆይ! ከመጽሐፉ ትሸሽጉት ከነበራችሁት ነገር ብዙውን ለእናንተ የሚገልጽ ከብዙውም የሚተው ሲኾን መልክተኛችን (ሙሐመድ) በእርግጥ መጣላችሁ፡፡ ከአላህ ዘንድ ብርሃንና ገላጭ መጽሐፍ በእርግጥ መጣላችሁ፡፡'),
('5:16', 87, 'አላህ ውዴታውን የተከተሉትን ሰዎች የሰላምን መንገዶች በእርሱ ይመራቸዋል፡፡ በፈቃዱም ከጨለማዎች ወደ ብርሃን ያወጣቸዋል፡፡ ወደ ቀጥተኛም መንገድ ይመራቸዋል፡፡'),
('5:17', 87, 'እነዚያ አላህ እርሱ የመርየም ልጅ አልመሲሕ ነው ያሉ በእርግጥ ካዱ፡፡ የመርየምን ልጅ አልመሲሕን እናቱንም በምድር ያለንም ሁሉ ለማጥፋት ቢሻ ከአላህ ማዳንን የሚችል ማነው በላቸው፡፡ የሰማያትና የምድር የመካከላቸውም ንግሥና የአላህ ብቻ ነው፡፡ የሚሻውን ይፈጥራል፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('5:18', 87, 'አይሁዶችና ክርስቲያኖችም «እኛ የአላህ ልጆችና ወዳጆቹ ነን» አሉ፡፡ «ታዲያ በኃጢአቶቻችሁ ለምን ያሰቃያችኋል አይደላችሁም እናንተ ከፈጠራቸው ሰዎች ናችሁ» በላቸው፡፡ ለሚሻው ሰው ይምራል፡፡ የሚሻውንም ሰው ይቀጣል፡፡ የሰማያትና የምድርም በመካከላቸውም ያለው ሁሉ ንግሥና የአላህ ብቻ ነው፡፡ መመለሻም ወደርሱ ብቻ ነው፡፡'),
('5:19', 87, 'እናንተ የመጽሐፉ ሰዎች ሆይ! «አብሳሪና አስፈራሪ አልመጣልንም» እንዳትሉ ከመልክተኞች በመቋረጥ ጊዜ ላይ ሲኾን (ሕጋችንን) የሚያብራራ ኾኖ መልክተኛችን በእርግጥ መጣላችሁ፡፡ አብሳሪና አስፈራሪም በእርግጥ መጣላችሁ፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('5:20', 87, 'ሙሳም ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፡- «ሕዝቦቼ ሆይ የአላህን ጸጋ በውስጣችሁ ነቢያትን ባደረገና ነገሥታትንም ባደረጋችሁ ከዓለማትም ለአንድም ያልሰጠውን ችሮታ በሰጣችሁ ጊዜ በእናንተ ላይ (ያደረገውን ጸጋ) አስታውሱ፡፡»'),
('5:21', 87, '«ሕዝቦቼ ሆይ! ያችን አላህ ለእናንተ ያደረጋትን የተቀደሰችውን መሬት ግቡ፡፡ ወደ ኋላችሁም አትመለሱ፡፡ ከሳሪዎች ኾናችሁ ትመለሳላችሁና፡፡»'),
('5:22', 87, '«ሙሳ ሆይ! በርስዋ ውስጥ ኀያላን ሕዝቦች አሉ፡፡ ከርስዋም እስከሚወጡ ድረስ እኛ ፈጽሞ አንገባትም፡፡ ከርስዋም ቢወጡ እኛ ገቢዎች ነን» አሉ፡፡'),
('5:23', 87, 'ከእነዚያ (አላህን) ከሚፈሩትና አላህ በእነርሱ ላይ ከለገሰላቸው የኾኑ ሁለት ሰዎች «በእነርሱ (በኀያሎቹ) ላይ በሩን ግቡ፡፡ በገባችሁትም ጊዜ እናንተ አሸናፊዎች ናችሁ፡፡ ምእመናንም እንደኾናችሁ በአላህ ላይ ተመኩ» አሉ፡፡'),
('5:24', 87, '«ሙሳ ሆይ! በውስጧ እስካሉ ድረስ እኛ ፈጽሞ ምን ጊዜም አንገባትም፡፡ ስለዚህ ኺድ አንተና ጌታህ ተጋደሉም እኛ እዚህ ተቀማጮች ነን» አሉ፡፡'),
('5:25', 87, '«ጌታዬ ሆይ እኔ ራሴንና ወንድሜን በቀር (ላስገድድ) አልችልም፡፡ በእኛና በአመጸኞቹም ሕዝቦች መካከል ለይ» አለ፡፡'),
('5:26', 87, 'እርስዋም (የተቀደሰችው መሬት) በእነርሱ ላይ አርባ ዓመት እርም ናት፡፡ በምድረ በዳ ይንከራተታሉ፡፡ «በአመጸኞችም ሕዝቦች ላይ አትዘን» አለው፡፡'),
('5:27', 87, 'በነርሱም ላይ የአደምን ሁለት ልጆች ወሬ ቁርባንን ባቀረቡና (አላህ) ከአንደኛቸው ተቀብሎ ከሌላው ባልተቀበለ ጊዜ (የኾነውን) በእውነት አንብብላቸው፡፡ «በእርግጥ እገድልሃለሁ» አለው፡፡ (ተገዳዩ) «አላህ የሚቀበለው እኮ ከጥንቁቆቹ ብቻ ነው» አለ፡፡'),
('5:28', 87, '«ልትገድለኝ እጅህን ወደኔ ብትዘረጋ እኔ ልገድልህ እጄን ወዳንተ የምዘረጋ አይደለሁም፡፡ እኔ የዓለማትን ጌታ አላህን እፈራለሁና» አለ፡፡'),
('5:29', 87, '«እኔ በኃጢአቴና በኃጢአትህ ልትመለስና ከእሳት ጓዶች ልትኾን እሻለሁ፤ ይኽም የበደለኞች ቅጣት ነው» (አለ)፡፡'),
('5:30', 87, 'ነፍሱም ወንድሙን መግደልን ለርሱ ሸለመችለት፤(አነሳሳችው፤)፡፡ ገደለውም፡፡ ከከሳሪዎቹም ኾነ፡፡'),
('5:31', 87, 'የወንድሙንም ሬሳ እንዴት እንደሚሸሽግ ያሳየው ዘንድ አላህ መሬትን የሚጭር ቁራን ላከለት፡፡ «ወይ እኔ የወንድሜን ሬሳ እሸሽግ ዘንድ እንደዚህ ቁራ ብጤ መኾን አቃተኝን» አለ፡፡ ከጸጸተኞችም ኾነ፡፡'),
('5:32', 87, 'በዚህ ምክንያት በእስራኤል ልጆች ላይ እነሆ ያለ ነፍስ (መግደል) ወይም በምድር ላይ ያለማጥፋት (ካልሆነ በስተቀር) ነፍስን የገደለ ሰው ሰዎቹን ሁሉ እንደገደለ ነው፤ ሕያው ያደረጋትም ሰው ሰዎቹን ሁሉ ሕያው እንዳደረገ ነው ማለትን ጻፍን፡፡ መልክተኞቻችንም በግልጽ ተዓምራት በእርግጥ መጡዋቸው፡፡ ከዚያም ከዚህ በኋላ ከእነሱ ብዙዎቹ በምድር ላይ ወሰንን አላፊዎች ናቸው፡፡'),
('5:33', 87, 'የእነዚያ አላህንና መልክተኛውን የሚዋጉ በምድርም ላይ ለማጥፋት የሚተጉ ሰዎች ቅጣት መገደል ወይም መሰቀል ወይም እጆቻቸውንና እግሮቻቸውን በማፈራረቅ መቆረጥ ወይም ከአገር መባረር ነው፡፡ ይህ በነሱ በቅርቢቱ ዓለም ውርደት ነው፡፡ በመጨረሻይቱም ለእነርሱ ከባድ ቅጣት አላቸው፡፡'),
('5:34', 87, 'እነዚያ በእነርሱ ላይ ከመቻላችሁ (ከመወሰናችሁ) በፊት የተጸጸቱ ሲቀሩ፡፡ አላህም መሓሪ አዛኝ መኾኑን እወቁ፡፡'),
('5:35', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ፍሩ፡፡ ወደርሱም መቃረቢያን (መልካም ሥራን) ፈልጉ፡፡ ትድኑ ዘንድም በእርሱ መንገድ ታገሉ፡፡'),
('5:36', 87, 'እነዚያ የካዱት ሰዎች በምድር ላይ ያለው ሁሉ ከእርሱም ጋር ብጤው ከትንሣኤ ቀን ቅጣት በእርሱ ሊበዡበት ለእነርሱ በኖራቸው ኖሮ ከእነሱ ተቀባይን ባላገኙ ነበር፡፡ ለእነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('5:37', 87, 'ከእሳት ሊወጡ ይፈልጋሉ፡፡ እነርሱም ከርስዋ ወጪዎች አይደሉም፡፡ ለእነርሱም ዘውታሪ ቅጣት አላቸው፡፡'),
('5:38', 87, 'ሰራቂውንና ሰራቂይቱንም በሠሩት ነገር ለቅጣት ከአላህ የኾነን መቀጣጫ እጆቻቸውን ቁረጡ፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('5:39', 87, 'ከበደሉም በኋላ የተጸጸተና ሥራውን ያሳመረ አላህ ጸጸቱን ከእርሱ ይቀበለዋል፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('5:40', 87, 'የሰማያትና የምድር ንግሥና የሱ (የአላህ) ብቻ መኾኑን አላወቅክምን የሚሻውን ሰው ይቀጣል፡፡ ለሚሻውም ሰው ይምራል፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('5:41', 87, 'አንተ መልክተኛ ሆይ! እነዚያ በክሕደት የሚቻኮሉት ከእነዚያ ልቦቻቸው ያላመኑ ሲኾኑ በአፎቻቸው «አመንን» ካሉትና ከእነዚያም አይሁድ ከኾኑት ሲኾኑ አያሳዝኑህ፡፡ (እነርሱ) ውሸትን አዳማጮች ናቸው፡፡ ለሌሎች ወዳንተ ላልመጡ ሕዝቦች አዳማጮች ናቸው፡፡ ንግግሮችን ከቦታቸው ሌላ ያጣምማሉ፡፡ «ይህንን (የተጣመመውን) ብትስሰጡ ያዙት፡፡ ባትስሰጡትም ተጠንቀቁ» ይላሉ፡፡ አላህም መፈተኑን የሚሻበትን ሰው ለእርሱ ከአላህ (ለመከላከል) ምንንም አትችልም፡፡ እነዚህ እነዚያ አላህ ልቦቻቸውን ማጥራትን ያልሻላቸው ናቸው፡፡ ለእነርሱ በቅርቢቱ ዓለም ውርደት አላቸው፡፡ ለእነርሱም በመጨረሻይቱ ዓለም ከባድ ቅጣት አላቸው፡፡'),
('5:42', 87, 'ውሸትን አዳማጮች እርምን በላተኞች ናቸው፡፡ ወደአንተ ቢመጣም በመካከላቸው ፍረድ፡፡ ወይም ተዋቸው፡፡ ብትተዋቸውም ምንም አይጎዱህም፡፡ ብትፈርድም በመካከላቸው በትክክል ፍረድ፡፡ አላህ በትክክል ፈራጆችን ይወዳልና፡፡'),
('5:43', 87, 'እነርሱም ዘንድ ተውራት እያለች በውስጧ የአላህ ፍርድ ያለባት ስትኾን እንዴት ያስፈርዱሃል! ከዚያም ከዚህ በኋላ እንዴት ይሸሻሉ! እነዚያም በፍጹም ምእምናን አይደሉም፡፡'),
('5:44', 87, 'እኛ ተውራትን በውስጥዋ መምሪያና ብርሃን ያለባት ስትኾን አወረድን፡፡ እነዚያ ትዕዛዝን የተቀበሉት ነቢያት በእነዚያ አይሁዳውያን በኾኑት ላይ በርሷ ይፈርዳሉ፡፡ ሊቃውንቱና ዐዋቂዎቹም ከአላህ መጽሐፍ እንዲጠብቁ በተደረጉትና በርሱም ላይ መስካሪዎች በኾኑት (ይፈርዳሉ)፡፡ ሰዎችንም አትፍሩ፡፡ ፍሩኝም፡፡ በአንቀጾቼም አነስተኛን ዋጋ አትለውጡ፡፡ አላህም ባወረደው ነገር ያልፈረደ ሰው እነዚያ ከሓዲዎቹ እነርሱ ናቸው፡፡'),
('5:45', 87, 'በእነርሱም ላይ በውስጧ «ነፍስ በነፍስ ዓይንም በዓይን አፍንጫም በአፍንጫ ጆሮም በጆሮ ጥርስም በጥርስ (ይያዛል)፡፡» ቁስሎችንም ማመሳሰል አለባቸው ማለትን ጻፍን፡፡ በእርሱም የመጸወተ (የማረ) ሰው እርሱ ለርሱ (ለሠራው ኃጢአት) ማስተሰሪያ ነው፡፡ አላህም ባወረደው ነገር የማይፈርድ ሰው፤ እነዚያ በደለኞቹ እነርሱ ናቸው፡፡'),
('5:46', 87, 'በፈለጎቻቸውም (በነቢያቶቹ ፈለግ) ላይ የመርየምን ልጅ ዒሳን ከተውራት በስተፊቱ ያለውን አረጋጋጭ ሲኾን አስከተልን፡፡ ኢንጂልንም በውስጡ ቀጥታና ብርሃን ያለበት በስተፊቱ ያለችውን ተውራትንም የሚያረጋግጥ ለጥንቁቆችም መሪና ገሳጭ ሲኾን ሰጠነው፡፡'),
('5:47', 87, 'የኢንጅልም ባለቤቶች በውስጡ አላህ ባወረደው ሕግ ይፍረዱ፡፡ አላህም ባወረደው የማይፈርድ ሰው እነዚያ አመጸኞች እነርሱ ናቸው፡፡'),
('5:48', 87, 'ወደ አንተም መጽሐፉን ከበፊቱ ያለውን መጽሐፍ አረጋጋጭና በእርሱ ላይ ተጠባባቂ ሲኾን በእውነት አወረድን፡፡ በመካከላቸውም አላህ ባወረደው ሕግ ፍረድ፡፡ እውነቱም ከመጣልህ በኋላ ዝንባሌዎቻቸውን አትከተል፡፡ ከእናንተ ለሁሉም ሕግንና መንገድን አደረግን፡፡ አላህም በሻ ኖሮ አንድ ሕዝብ ባደረጋችሁ ነበር፡፡ ግን በሰጣችሁ ሕግጋት ሊሞክራችሁ (ለያያችሁ)፡፡ በጎ ሥራዎችንም (ለመሥራት) ተሽቀዳደሙ፤ መመለሻችሁ በጠቅላላ ወደ አላህ ነው፡፡ በእርሱም ትለያዩበት የነበራችሁትን ነገር ይነግራችኋል፡፡'),
('5:49', 87, 'በመካከላቸውም አላህ ባወረደው ሕግ ፍረድ፡፡ ፍላጎቶቻቸውንም አትከተል፡፡ አላህም ወደ አንተ ካወረደው ከከፊሉ እንዳያሳስቱህ ተጠንቀቃቸው (ማለትን አወረድን)፡፡ ቢዞሩም አላህ የሚሻው በከፊሉ ኃጢአታቸው ሊቀጣቸው መኾኑን ዕወቅ፡፡ ከሰዎቹም ብዙዎቹ አመጸኞች ናቸው፡፡'),
('5:50', 87, 'የማይምንነትን ፍርድ ይፈልጋሉን ለሚያረጋግጡም ሰዎች ከአላህ ይበልጥ ፍርዱ ያማረ ማን ነው'),
('5:51', 87, 'እናንተ ያመናችሁ ሆይ! አይሁዶችንና ክርስቲያኖችን ረዳቶች አድርጋችሁ አትያዙ፡፡ ከፊላቸው ለከፊሉ ረዳቶች ናቸው፡፡ ከእናንተም ውስጥ ረዳቶች የሚያደርጋቸው ሰው እርሱ ከነርሱ ነው፡፡ አላህ አመጸኞችን ሕዝቦች አያቀናም፡፡'),
('5:52', 87, 'እነዚያንም በልቦቻቸው ውስጥ (የንፍቅና) በሽታ ያለባቸውን ሰዎች «የጊዜ መለዋወጥ እንዳያገኘን እንፈራለን የሚሉ» ሲኾኑ በእነርሱ (ለመረዳት) ሲቻኮሉ ታያቸዋለህ፡፡ አላህም ድል መንሳትን ወይም ከእርሱ ዘንድ የኾነን ነገር (ማጋለጥን) ሊያመጣ በነፍሶቻቸው ውስጥ በደበቁትም ነገር ተጸጻቾች ሲሆኑ ተረጋገጠ፡፡'),
('5:53', 87, 'እነዚያም ያመኑት ሰዎች፡- «እነዚያ እነርሱ ከእናንተ ጋር ነን ብለው የጠነከረ መሐላቸውን በአላህ የማሉት እነዚህ ናቸውን» ይላሉ፡፡ ሥራዎቻቸው ተበላሹ፡፡ ከሳሪዎችም ኾኑ፡፡'),
('5:54', 87, 'እናንተ ያመናችሁ ሆይ! ከእናንተ ውስጥ ከሃይማኖቱ የሚመለስ ሰው አላህ (በእነርሱ ስፍራ) የሚወዳቸውንና የሚወዱትን፣ በምእመናን ላይ ትሑቶች፣ በከሓዲዎች ላይ ኀያላን የኾኑን በአላህ መንገድ የሚታገሉን የወቃሽን ወቀሳ የማይፈሩን ሕዝቦች በእርግጥ ያመጣል፡፡ ይኸ የአላህ ችሮታ ነው፤ ለሚሻው ሰው ይሰጠዋል፤ አላህም ችሮታው ሰፊ ዐዋቂ ነው፡፡'),
('5:55', 87, 'ረዳታችሁ አላህና መልክተኛው እነዚያም ያመኑት ብቻ ናቸው፡፡ (እነርሱ) እነዚያ ሶላትን በደንቡ የሚሰግዱ እነርሱም ያጎነበሱ ኾነው ምጽዋትን የሚሰጡ ናቸው፡፡'),
('5:56', 87, 'አላህንና መልክተኛውን እነዚያንም ያመኑትን የሚወዳጅ ሰው (ከአላህ ጭፍሮች ይኾናል)፡፡ የአላህም ጭፍሮች እነርሱ አሸናፊዎች ናቸው፡፡'),
('5:57', 87, 'እናንተ ያመናችሁ ሆይ! ከእነዚያ ከበፊታችሁ መጽሐፍን ከተሰጡት እነዚያን ሃይማኖታችሁን ማላገጫና መጫወቻ አድርገው የያዙትን ከሓዲዎችንም ረዳቶች አድርጋችሁ አትያዙ፡፡ ምእምናንም እንደኾናችሁ አላህን ፍሩ፡፡'),
('5:58', 87, 'ወደ ሶላትም በጠራችሁ ጊዜ (ጥሪይቱን) መሳለቂያና መጫወቻ አድርገው ይይዟታል፡፡ ይህ እነርሱ የማያውቁ ሕዝቦች በመኾናቸው ነው፡፡'),
('5:59', 87, '«የመጽሐፉ ባለቤቶች ሆይ! በአላህና ወደኛ በተወረደው በፊትም በተወረደው ለማመናችን አብዛኞቻችሁም አመጸኞች ለመኾናችሁ እንጅ (ሌላን ነገር) ከኛ ትጠላላችሁን» በላቸው፡፡'),
('5:60', 87, '«አላህ ዘንድ ቅጣቱ ከዚህ የከፋ ነገር ልንገራችሁን» በላቸው፡፡ (እርሱም) «አላህ የረገመው ሰው በእርሱም ላይ ተቆጣበት፡፡ ከእነርሱም ዝንጀሮዎችንና ከርከሮዎችን ያደረገው ጣዖትንም የተገዛ ሰው (ሃይማኖት) ነው፡፡ እነዚያ በጣም በከፋ ስፍራ ናቸው፡፡» ከቀጥተኛውም መንገድ በጣም የተሳሳቱ ናቸው፡፡'),
('5:61', 87, 'በመጡዋችሁም ጊዜ (ወደእናንተ) ከክህደት ጋር በእርግጥ የገቡ እነርሱም ከርሱ ጋር በእርግጥ የወጡ ሲኾኑ «አምነናል» ይላሉ፡፡ አላህም ይደብቁት የነበሩትን ነገር በጣም ዐዋቂ ነው፡፡'),
('5:62', 87, 'ከእነርሱም ብዙዎቹን በኃጢአትና በበደል እርምንም በመብላታቸው የሚጣደፉ ሲኾኑ ታያለህ፡፡ ይሠሩት የነበሩት ነገር በጣም ከፋ!'),
('5:63', 87, 'ቀሳውስቱና ሊቃውንቱ ከኃጢአት ንግግራቸውና እርምን ከመብላታቸው አይከለክሏቸውም ኖሮአልን ይሠሩት የነበሩት ነገር በጣም ከፋ!'),
('5:64', 87, 'አይሁዶችም «የአላህ እጅ የታሰረች ናት» አሉ፡፡ እጆቻቸው ይታሰሩ ባሉትም ነገር ይረገሙ፡፡ አይደለም (የአላህ) እጆቹ የተዘረጉ ናቸው፡፡ እንደሚሻ ይለግሳል፡፡ ከጌታህም ወደ አንተ የተወረደው (ቁርኣን) ከእነሱ ብዙዎቹን ትዕቢትንና ክህደትን በእርግጥ ይጨምራቸዋል፡፡ በመካከላቸውም ጠብንና ጥላቻን እስከ ትንሣኤ ቀን ድረስ ጣልን፡፡ ለጦር እሳትን ባያያዙ (ባጫሩ) ቁጥር አላህ ያጠፋታል፡፡ በምድርም ውስጥ ለማበላሸት ይሮጣሉ፡፡ አላህም አበላሺዎችን አይወድም፡፡'),
('5:65', 87, 'የመጽሐፉም ባለቤቶች ባመኑና (ከክህደትም) በተጠነቀቁ ኖሮ ከእነሱ ኃጢኣቶቻቸውን በእርግጥ ባበስንና የመጠቀሚያ ገነቶችንም በእርግጥ ባገባናቸው ነበር፡፡'),
('5:66', 87, 'እነርሱም ተውራትንና ኢንጂልን ከጌታቸውም ወደእነሱ የተወረደውን መጽሐፍ ባቋቋሙ (በሠሩበት) ኖሮ ከበላያቸውና ከእግሮቻቸው ሥር በተመገቡ ነበር፡፡ ከእነሱ ውስጥ ትክክለኞች ሕዝቦች አልሉ፡፡ ከእነሱም ብዙዎቹ የሚሠሩት ነገር ከፋ!'),
('5:67', 87, 'አንተ መልክተኛ ሆይ! ከጌታህ ወዳንተ የተወረደውን አድርስ፡፡ ባትሠራም መልክቱን አላደረስክም፡፡ አላህም ከሰዎች ይጠብቅሃል፡፡ አላህ ከሓዲዎችን ሕዝቦች አያቀናምና፡፡'),
('5:68', 87, '«እናንተ የመጽሐፉ ባለቤቶች ሆይ! ተውራትንና ኢንጂልን ከጌታችሁም ወደእናንተ የተወረደውን እስከምታቆሙ (እስከምትሠሩባቸው) ድረስ በምንም ላይ አይደላችሁም» በላቸው፡፡ ከጌታህም ወደ አንተ የተወረደው ቁርኣን ከእነሱ ብዙዎቹን ትዕቢትንና ክህደትን በእርግጥ ይጨምርባቸዋል፡፡ በከሓዲያን ሕዝቦችም ላይ አትዘን፡፡'),
('5:69', 87, 'እነዚያ ያመኑና እነዚያም አይሁዳውያን የኾኑ፣ ሳቢያኖችም፣ ክርስቲያኖችም (ከነርሱ) በአላህና በመጨረሻው ቀን ያመነና መልካምን ሥራ የሠራ ሰው በነርሱ ላይ ፍርሃት የለባቸውም፡፡ እነርሱም አያዝኑም፡፡'),
('5:70', 87, 'የእስራኤልን ልጆች የጠበቀ ቃል ኪዳን በእርግጥ ያዝንባቸው፡፡ ወደእነሱም መልክተኞችን ላክን፡፡ ነፍሶቻቸው በማትወደው ነገር መልእክተኛ በመጣላቸው ቁጥር ከፊሉን አስተባበሉ፤ ከፊሉንም ይገድላሉ፡፡'),
('5:71', 87, 'ፈተናም አለመኖርዋን ጠረጠሩ፡፡ ታወሩም፣ ደነቆሩም፣ ከዚያም አላህ ከነርሱ ላይ ጸጸትን ተቀበለ፡፡ ከዚያም ከእነሱ ብዙዎቹ ታወሩ፣ ደነቆሩም፡፡ አላህም የሚሠሩትን ሁሉ ተመልካች ነው፡፡'),
('5:72', 87, 'እነዚያ «አላህ እርሱ የመርየም ልጅ አልመሲሕ ነው» ያሉ በእርግጥ ካዱ፡፡ አልመሲህም አለ፡- «የእስራኤል ልጆች ሆይ! ጌታዬንና ጌታችሁን አላህን ተገዙ፡፡» እነሆ! በአላህ የሚያጋራ ሰው አላህ በርሱ ላይ ገነትን በእርግጥ እርም አደረገ፡፡ መኖሪያውም እሳት ናት፡፡ ለበዳዮችም ምንም ረዳቶች የሏቸውም፡፡'),
('5:73', 87, 'እነዚያ «አላህ የሦስት ሦስተኛ ነው» ያሉ በእርግጥ ካዱ፡፡ ከአምላክም አንድ አምላክ እንጅ ሌላ የለም፡፡ ከሚሉትም ነገር ባይከለከሉ ከነሱ እነዚያን የካዱትን አሳማሚ ቅጣት በእርግጥ ይነካቸዋል፡፡'),
('5:74', 87, 'ወደ አላህ አይመለሱምና ምሕረትን አይለምኑትምን አላህም መሓሪ አዛኝ ነው፡፡'),
('5:75', 87, 'የመርየም ልጅ አልመሲሕ ከበፊቱ መልክተኞች በእርግጥ ያለፉ የኾነ መልክተኛ እንጅ ሌላ አይደለም፡፡ እናቱም በጣም እውነተኛ ናት፡፡ (ሁለቱም) ምግብን የሚበሉ ነበሩ፤ አንቀጾችን ለነርሱ (ለከሓዲዎች) እንዴት እንደምናብራራ ተመልከት ከዚያም (ከእውነት) እንዴት እንደሚመለሱ ተመልከት፡፡'),
('5:76', 87, '«ከአላህ ሌላ ለእናንተ መጉዳትንና መጥቀምን የማይችልን ትገዛላችሁን» በላቸው፡፡ አላህም እርሱ ሰሚው ዐዋቂ ነው፡፡'),
('5:77', 87, '«እናንተ የመጽሐፉ ባለቤቶች ሆይ! በሃይማኖታችሁ ከእውነት ሌላ የኾነን (ማለፍ) ወሰንን አትለፉ፡፡ በፊትም በእርግጥ የተሳሳቱትንና ከቀጥተኛው መንገድም (አሁን) የተሳሳቱን ሕዝቦች ከንቱ ዝንባሌዎች አትከተሉ» በላቸው፡፡'),
('5:78', 87, 'ከእስራኤል ልጆች እነዚያ የካዱት በዳውድና በመርየም ልጅ በዒሳ ምላስ ተረገሙ፡፡ ይህ ትእዛዝን በመጣሳቸውና ወሰንን የሚያልፉ በመኾናቸው ነው፡፡'),
('5:79', 87, 'ከሠሩት መጥፎ ነገር አይከላከሉም ነበር፡፡ ይሠሩት የነበሩት ነገር በእርግጥ ከፋ!'),
('5:80', 87, 'ከእነሱ ብዙዎቹን እነዚያን የካዱትን ሲወዳጁ ታያለህ፡፡ በእነሱ ላይ አላህ የተቆጣባቸው በመኾኑ ለእነርሱ ነፍሶቻቸው ያስቀደሙት ሥራ በጣም ከፋ፡፡ እነሱም በቅጣት ውስጥ ዘውታሪዎች ናቸው፡፡'),
('5:81', 87, 'በአላህና በነቢዩ ወደርሱም በተወረደው ቁርኣን የሚያምኑ በኾኑ ኖሮ ወዳጆች አድርገው ባልያዙዋቸው ነበር፡፡ ግን ከነርሱ ብዙዎቹ አመጠኞች ናቸው፡፡'),
('5:82', 87, 'አይሁዶችንና እነዚያን ያጋሩትን ለእነዚያ ለአመኑት በጠላትነት ከሰዎች ሁሉ ይበልጥ የበረቱ ኾነው በእርግጥ ታገኛለህ፡፡ እነዚያንም «እኛ ክርስቲያኖች ነን» ያሉትን ለእነዚያ ለአመኑት በወዳጅነት በእርግጥ ይበልጥ የቀረቧቸው ኾነው ታገኛለህ፡፡ ይህ ከእነሱ ውስጥ ቀሳውስትና መነኮሳት በመኖራቸውና እነሱም የማይኮሩ በመኾናቸው ነው፡፡'),
('5:83', 87, 'ወደ መልክተኛውም የተወረደውን (ቁርኣን) በሰሙ ጊዜ እውነቱን ከማወቃቸው የተነሳ ዓይኖቻቸው እንባን ሲያፈሱ ታያለህ፡፡ «ጌታችን ሆይ! አመንን ከመስካሪዎቹም ጋር ጻፈን » ይላሉ፡፡'),
('5:84', 87, '«በአላህና ከውነትም በመጣልን ነገር የማናምን ጌታችንም ከመልካም ሰዎች ጋር ሊያስገባን የማንከጅል ለኛ ምን አለን» (ይላሉ)፡፡'),
('5:85', 87, 'ባሉትም ምክንያት አላህ በስሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ መነዳቸው፡፡ ይህም የበጎ ሠሪዎች ዋጋ ነው፡፡'),
('5:86', 87, 'እነዚያም የካዱና በአንቀጾቻችን ያስተባበሉ እነዚያ የእሳት ጓዶች ናቸው፡፡'),
('5:87', 87, 'እናንተ ያመናችሁ ሆይ! አላህ ለናንተ የፈቀደላችሁን ጣፋጮች እርም አታድርጉ፡፡ ወሰንንም አትለፉ፡፡ አላህ ወሰን አላፊዎችን አይወድምና፡፡'),
('5:88', 87, 'አላህም ከሰጣችሁ ሲሳይ የተፈቀደ ጣፋጭ ሲኾን ብሉ፡፡ ያንንም እናንተ በርሱ አማኞች የኾናችሁበትን አላህን ፍሩ፡፡'),
('5:89', 87, 'አላህ በመሐላዎቻችሁ በውድቁ አይዛችሁም፡፡ ግን መሐላዎችን (ባሰባችሁት) ይይዛችኋል፡፡ ማስተሰሪያውም ቤተሰቦቻችሁን ከምትመግቡት ከመካከለኛው (ምግብ) ዐስርን ምስኪኖች ማብላት ወይም እነሱን ማልበስ ወይም ጫንቃን ነጻ ማውጣት ነው፤ (ከተባሉት አንዱን) ያላገኘም ሰው ሦስት ቀኖችን መጾም ነው፤ ይህ በማላችሁ ጊዜ የመሐላዎቻችሁ ማካካሻ ነው፡፡ መሐላዎቻችሁንም ጠብቁ፡፡ እንደዚሁ አላህ ለናንተ አንቀጾችን ያብራራል፡፡ እናንተ ልታመሰግኑ ይከጀላልና፡፡'),
('5:90', 87, 'እናንተ ያመናችሁ ሆይ! የሚያሰክር መጠጥ ቁማርም ጣዖታትም አዝላምም ከሰይጣን ሥራ የኾኑ እርኩስ ብቻ ናቸው፡፡ (እርኩስን) ራቁትም ልትድኑ ይከጀላልና፡፡'),
('5:91', 87, 'ሰይጣን የሚፈልገው በሚያሰክር መጠጥና በቁማር በመካከላችሁ ጠብንና ጥላቻን ሊጥል አላህን ከማውሳትና ከስግደትም ሊያግዳችሁ ብቻ ነው፡፡ ታዲያ እናንተ (ከእነዚህ) ተከልካዮች ናችሁን (ተከልከሉ)፡፡'),
('5:92', 87, 'አላህንም ተገዙ፡፡ መልክተኛውንም ታዘዙ፡፡ ተጠንቀቁም፡፡ ብትሸሹም፤ በመልክተኛችን ላይ ያለበት ግልጽ ማድረስ ብቻ መኾኑን ዕወቁ፡፡'),
('5:93', 87, 'በእነዚያ ባመኑትና በጎ ሥራዎችን በሠሩት ላይ (ክህደትን) በተጠነቀቁና ባመኑ መልካም ሥራዎችንም በሠሩ ከዚያም (የሚያሰክርንና ቁማርን) በተጠነቀቁና ባመኑ ከዚያም (ከተከለከለው ሁሉ) በተጠነቀቁና (ሥራን) ባሳመሩ ጊዜ (ከመከልከሉ በፊት) በተመገቡት ነገር ኃጢአት የለባቸውም፡፡ አላህም በጎ ሠሪዎችን ይወዳል፡፡'),
('5:94', 87, 'እናንተ ያመናችሁ ሆይ! (በሐጅ ጊዜ) እጆቻችሁና ጦሮቻችሁ በሚያገኙት ታዳኝ አውሬ አላህ ይሞክራችኋል፡፡ በሩቅ ኾኖ የሚፈራውን ሰው አላህ ሊገልጽ (ይሞክራችኋል)፡፡ ከዚያም በኋላ ወሰንን ያለፈና ያደነ ሰው ለርሱ አሳማሚ ቅጣት አለው፡፡'),
('5:95', 87, 'እናንተ ያመናችሁ ሆይ! እናንት በሐጅ ሥራ ውስጥ ስትኾኑ አውሬን አትግደሉ፡፡ ከእናንተም እያወቀ የገደለው ሰው ቅጣቱ ከእናንተ ሁለት የትክክለኛነት ባለቤቶች የሚፈርዱበት የኾነ ወደ ካዕባ ደራሽ መሥዋዕት ሲኾን ከቤት እንስሳዎች የገደለውን ነገር ብጤ መስጠት ወይም ምስኪኖችን ማብላት ወይም የዚህን ልክ መጾም ማካካሻ ነው፡፡ (ይኽም) የሥራውን ከባድ ቅጣት እንዲቀምስ ነው፡፡ (ሳይከለከል በፊት) ካለፈው ነገር አላህ ይቅርታ አደረገ፡፡ (ወደ ጥፋቱም) የተመለሰም ሰው አላህ ከርሱ ይበቀላል፡፡ አላህም አሸናፊ የመበቀል ባለቤት ነው፡፡'),
('5:96', 87, 'የባሕር ታዳኝና ምግቡ ለእናንተም ለመንገደኞችም መጠቀሚያ ይኾን ዘንድ ለናንተ ተፈቀደ፡፡ በሐጅም ላይ እስካላችሁ ድረስ የየብስ አውሬ በናንተ ላይ እርም ተደረገ፡፡ ያንንም ወደርሱ የምትሰበሰቡበትን አላህን ፍሩ፡፡'),
('5:97', 87, 'ከዕባን፣ የተከበረውን ቤት፣ ክልክል የኾነውንም ወር፣ መስዋዕቱንና ባለ ምልክቶቹንም መንጋዎች አላህ ለሰዎች መቋቋሚያ አደረገ፡፡ ይህ አላህ በሰማያት ያለውን ሁሉ በምድርም ያለውን ሁሉ የሚያውቅ መኾኑን አላህም ነገሩን ሁሉ ዐዋቂ መኾኑን እንድታውቁ ነው፡፡'),
('5:98', 87, 'አላህ ቅጣተ ብርቱ መኾኑን አላህም መሓሪ አዛኝ መኾኑን እወቁ፡፡'),
('5:99', 87, 'በመልክተኛው ላይ ማድረስ እንጅ ሌላ የለበትም፡፡ አላህም የምትገልጹትን ነገር የምትደብቁትንም ሁሉ ያውቃል፡፡'),
('5:100', 87, '«የመጥፎው (ገንዘብ) ብዛት ቢያስደንቃችሁም እንኳ መጥፎውና ጥሩው አይስተካከሉም፡፡ ባለልቦች ሆይ! አላህንም ፍሩ፤ እናንተ ልትድኑ ይከጀላልና፤» በላቸው፡፡'),
('5:101', 87, 'እናንተ ያመናችሁ ሆይ! ለእናንተ ቢገለጹ ከሚያስከፏችሁ ነገሮች አትጠይቁ፡፡ ቁርኣንም በሚወርድበት ጊዜ ከእርሷ ብትጠይቁ ለናንተ ትገለጻለች፤ ከእርሷ አላህ ይቅርታ አደረገ፡፡ አላህም መሓሪ ታጋሽ ነው፡፡'),
('5:102', 87, 'ከናንተም በፊት ሕዝቦች በእርግጥ ጠየቋት፡፡ ከዚያም በእርሷ (ምክንያት) ከሓዲዎች ኾኑ፡፡'),
('5:103', 87, 'ከበሒራ ከሳኢባም ከወሲላም ከሓምም አላህ ምንንም (ሕግ) አላደረገም፡፡ ግን እነዚያ የካዱት በአላህ ላይ ውሸትን ይቀጣጥፋሉ፡፡ አብዛኞቻቸውም አያውቁም፡፡'),
('5:104', 87, 'ለእነርሱም አላህ ወደ አወረደውና ወደ መልክተኛው ኑ በተባሉ ጊዜ «አባቶቻችንን በርሱ ላይ ያገኘንበት ነገር ይበቃናል» ይላሉ፡፡ አባቶቻቸው ምንም የማያውቁና የማይመሩ ቢኾኑም (ይኸንን ማለት ይበቃቸዋልን)'),
('5:105', 87, 'እናንተ ያመናችሁ ሆይ! ነፍሶቻችሁን (ከእሳት) ያዙ፤ (ጠብቁ)፡፡ በተመራችሁ ጊዜ የተሳሳተ ሰው አይጎዳችሁም፡፡ የሁላችሁም መመለሻ ወደ አላህ ብቻ ነው፡፡ ትሠሩትም የነበራችሁትን ሁሉ ይነግራችኋል፡፡'),
('5:106', 87, 'እናንተ ያመናችሁ ሆይ! አንዳችሁን ሞት በመጣበት ጊዜ በኑዛዜ ወቅት የመካከላችሁ ምስክርነት ከእናንተ ሁለት የትክክለኛነት ባለቤቶች የኾኑ ሰዎች ወይም በምድር ብትጓዙና የሞት አደጋ ብትነካችሁ ከሌሎቻችሁ የኾኑ ሁለት ሌሎች ሰዎች (መመስከር) ነው፡፡ ብትጠራጠሩ ከሶላት (ከዐሱር) በኋላ ታቆሟቸውና (የሚመሰክርለት ሰው) የዝምድና ባለቤት ቢኾንም እንኳ «በርሱ ዋጋን አንገዛም የአላህንም ምስክርነት አንደብቅም፤ ያን ጊዜ (ደብቀን ብንገኝ) እኛ ከኃጢአተኞች ነን» ብለው በአላህ ስም ይምላሉ፡፡'),
('5:107', 87, 'እነርሱም ኃጢአትን (በውሸት መስክረው) የተገቡ መኾናቸው ቢታወቅ ከእነዚያ (ለሟቹ) ቅርቦች በመኾን (ውርስ) ከተገባቸው የኾኑ ሁለት ሌሎች ሰዎች በስፍራቸው (በምስክሮች ስፍራ) ይቆሙና «ምስክርነታችን ከእነሱ ምስክርነት ይልቅ እውነት ነው ወሰንም አላለፍንም ያን ጊዜ እኛ ከበዳዮች ነን» ሲሉ በአላህ ይምላሉ፡፡'),
('5:108', 87, 'ይህ ምስክርነትን በተገቢዋ ላይ ለማምጣታቸው ወይም ከመሐላዎቻቸው በኋላ የመሐላዎችን (ወደ ወራሾች) መመለስን ለመፍራት በጣም የቀረበ ነው፡፡ አላህንም ፍሩ፡፡ ስሙም፡፡ አላህም አመጸኞች ሕዝቦችን አይመራም፡፡'),
('5:109', 87, 'አላህ መልክተኞቹን የሚሰበስብበትንና «ምን መልስ ተሰጣችሁ» የሚልበትን ቀን (አስታውስ)፡፡ «ለእኛ ምንም ዕውቀት የለንም አንተ ሩቆችን በጣም ዐዋቂ አንተ ብቻ ነህ» ይላሉ፡፡'),
('5:110', 87, 'አላህ በሚል ጊዜ (አስታውስ)፡- «የመርየም ልጅ ዒሳ ሆይ! በአንተና በእናትህ ላይ (የዋልኩላችሁን) ጸጋዬን አስታውስ፡፡ በሕፃንነትና በከፈኒሳነት (የበሰለ ሰው ኾነህ) ሰዎችን የምትናገር ስትኾን በቅዱስ መንፈስ (በገብሬል) ባበረታሁህ ጊዜ፤ ጽሕፈትንና ጥበብንም ተውራትንና ኢንጂልንም ባስተማርኩህ ጊዜ፣ ከጭቃም የወፍ ቅርጽ ብጤ በፈቃዴ በምትሠራና በውስጧ በምትነፋ በፈቃዴም ወፍ በምትኾን ጊዜ፣ ዕውርም ኾኖ የተወለደንና ለምጻምንም በፈቃዴ በምታሽር ጊዜ፣ ሙታንንም በፈቃዴ (ከመቃብራቸው) በምታወጣ ጊዜ፣ የእስራኤልንም ልጆች በተአምራት በመጣህባቸውና ከእነሱ እነዚያ የካዱት ይህ ግልጽ ድግምት እንጅ ሌላ አይደለም ባሉ ጊዜ፣ (ሊገድሉህ ሲያስቡህ) ከአንተ ላይ በከለከልኩልህም ጊዜ (ያደረግሁልህን ውለታ አስታውስ)፡፡»'),
('5:111', 87, 'ወደ ሐዋርያትም «በኔና በመልክተኛዬ እመኑ» በማለት ባዘዝኩ ጊዜ (አስታውስ)፡፡ «አመንን፤ እኛ ሙስሊሞች መኾናችንን መስክር» አሉ፡፡'),
('5:112', 87, 'ሐዋርያት፡- «የመርየም ልጅ ዒሳ ሆይ! ጌታህ በእኛ ላይ ከሰማይ ማእድን ሊያወርድልን ይችላልን» ባሉ ጊዜ (አስታውስ)፡፡ «ምእመናን እንደ ኾናችሁ አላህን ፍሩ» አላቸው፡፡'),
('5:113', 87, '«ከእርሷ ልንበላ ልቦቻችንም ሊረኩ እውነት ያልከንም መኾንህን ልናውቅና በእርሷም ላይ ከመስካሪዎች ልንኾን እንፈልጋለን» አሉ፡፡'),
('5:114', 87, 'የመርየም ልጅ ዒሳ አለ፡- «ጌታችን አላህ ሆይ! ለእኛ ለመጀመሪያዎቻችንና ለመጨረሻዎቻችን ባዕል (መደሰቻ) የምትኾንን ከአንተም ተአምር የኾነችን ማእድ ከሰማይ በእኛ ላይ አውርድ፡፡ ስጠንም፡፡ አንተ ከሰጪዎች ሁሉ በላጭ ነህና፡፡»'),
('5:115', 87, 'አላህ፡- «እኔ (ማእድዋን) በናንተ ላይ አውራጅዋ ነኝ፡፡ በኋላም ከእናንተ የሚክድ ሰው እኔ ከዓለማት አንድንም የማልቀጣውን ቅጣት እቀጣዋለሁ» አለ፡፡'),
('5:116', 87, 'አላህም፡- «የመርየም ልጅ ዒሳ ሆይ! አንተ ለሰዎቹ፡- እኔንና እናቴን ከአላህ ሌላ ሁለት አምላኮች አድርጋችሁ ያዙ ብላሃልን» በሚለው ጊዜ (አስታውስ)፡፡ «ጥራት ይገባህ፤ ለእኔ ተገቢዬ ያልኾነን ነገር ማለት ለኔ አይገባኝም፡፡ ብዬው እንደ ኾነም በእርግጥ ዐውቀኸዋል፡፡ በነፍሴ ውስጥ ያለውን ሁሉ ታውቃለህ፡፡ ግን አንተ ዘንድ ያለውን አላውቅም፡፡ አንተ ሩቆችን ሁሉ በጣም ዐዋቂ አንተ ብቻ ነህና» ይላል፡፡'),
('5:117', 87, '«በእርሱ ያዘዝከኝን ቃል ጌታዬንና ጌታችሁን አላህን ተገዙ ማለትን እንጂ ለነርሱ ሌላ አላልኩም፡፡ በውስጣቸውም እስካለሁ ድረስ በነርሱ ላይ ተጣባበቂ ነበርኩ፡፡ በተሞላኸኝም ጊዜ (ባነሳኸኝ ጊዜ) አንተ በነሱ ላይ ተጠባባቂ ነበርክ፡፡ አንተም በነገሩ ሁሉ ላይ ዐዋቂ ነህ፡፡»'),
('5:118', 87, '«ብትቀጣቸው እነርሱ ባሮችህ ናቸው፡፡ ለነርሱ ብትምርም አንተ አሸናፊው ጥበበኛው ነህ» (ይላል)፡፡'),
('5:119', 87, 'አላህ ይላል፡- «ይህ እውነተኞችን እውነታቸው የሚጠቅምበት ቀን ነው፡፡ ለእነርሱ በሥሮቻቸው ወንዞች የሚፈሱባቸው በውስጣቸው ሁልጊዜ ዘውታሪዎች ሲኾኑ የሚኖሩባቸው ገነቶች አሉዋቸው፡፡ አላህ ከእነሱ ወደደ፤ እነርሱም ከእርሱ ወደዱ፤ ይህ ታላቅ ዕድል ነው፡፡»'),
('5:120', 87, 'የሰማያትና የምድር በውስጣቸውም ያለው ሁሉ ንግሥና የአላህ ብቻ ነው፡፡ እሱም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('6:1', 87, 'ምስጋና ለዚያ ሰማያትንና ምድርን ለፈጠረው ጨለማዎችንና ብርሃንንም ላደረገው ለአላህ የተገባ ነው፡፡ ከዚያም እነዚያ የካዱት (ጣዖታትን በጌታቸው) ያስተካክላሉ፡፡'),
('6:2', 87, 'እርሱ ያ ከጭቃ የፈጠራችሁ ከዚያም (የሞት) ጊዜን የወሰነ ነው፡፡ እርሱም ዘንድ (ለትንሣኤ) የተወሰነ ጊዜ አልለ፡፡ ከዚያም እናንተ (በመቀስቀሳችሁ) ትጠራጠራላችሁ፡፡'),
('6:3', 87, 'እርሱም ያ በሰማያትና በምድር (ሊግገዙት የሚገባው) አላህ ነው፡፡ ምስጢራችሁን ግልጻችሁንም ያውቃል፡፡ የምትሠሩትንም ሁሉ ያውቃል፡፡'),
('6:4', 87, 'ከጌታቸውም አንቀጾች አንዲትም አንቀጽ አትመጣቸውም ከርሷ የሚሸሹ ቢኾኑ እንጅ፡፡'),
('6:5', 87, 'በእውነቱም (ቁርኣን) በመጣላቸው ጊዜ በእርግጥ አስተባበሉ፡፡ በእርሱም ይሳለቁበት የነበሩት ነገር ዜናዎች (ቅጣት) በእርግጥ ይመጣባቸዋል፡፡'),
('6:6', 87, 'ከበፊታቸው ከክፍለ ዘመናት ሕዝቦች ብዙዎችን ማጥፋታችንን አላዩምን ለእናንተ ያላስመቸነውን (ለእነርሱ) በምድር ውስጥ አስመቸናቸው፡፡ በእነርሱም ላይ ዝናምን የተከታተለ ሲኾን ላክን፡፡ ወንዞችንም በሥራቸው እንዲፈሱ አደረግን፡፡ በኃጢአቶቻቸውም አጠፋናቸው፡፡ ከኋላቸውም ሌሎችን የክፍለ ዘመን ሰዎች አስገኘን፡፡'),
('6:7', 87, 'ባንተም ላይ በወረቀት የተጻፈን መጽሐፍ ባወረድንና በእጆቻቸው በነኩት ኖሮ እነዚያ የካዱት ሰዎች «ይህ ግልጽ ድግምት እንጅ ሌላ አይደለም» ባሉ ነበር፡፡'),
('6:8', 87, '«በእርሱም (በሙሐመድ) ላይ መልአክ አይወረድለትም ኖሮአልን» አሉ፡፡ መልአክን ባወረድንም ኖሮ (ባያምኑ በጥፋታቸው) ነገሩ በተፈረደ ነበር፡፡ ከዚያም አይቆዩም ነበር፡፡'),
('6:9', 87, '(መልክተኛውን) መልአክም ባደረግነው ኖሮ ወንድ (በሰው ምስል) ባደረግነው ነበር፡፡ በእነርሱም ላይ የሚያመሳስሉትን ነገር ባመሳሰልንባቸው ነበር፡፡'),
('6:10', 87, 'ካንተ በፊትም በመልክተኞች በእርግጥ ተላግጧል፡፡ በእነዚያም ከእነሱ ባላገጡት ላይ በእርሱ ያላግጡ የነበሩት ነገር (ቅጣት) ወረደባቸው፡፡'),
('6:11', 87, '«በምድር ላይ ኺዱ የአስተባባዮችም መጨረሻ እንዴት እንደነበረ ተመልከቱ» በላቸው፡፡'),
('6:12', 87, '«በሰማያትና በምድር ያለው ሁሉ የማን ነው» በላቸው፡፡ (ሌላ መልስ የለምና) «የአላህ ነው» በል፡፡ «በነፍሱ ላይ እዝነትን ጻፈ፡፡ በትንሣኤ ቀን በእርሱ ጥርጥር የሌለበት ሲኾን በእርግጥ ይሰበስባችኋል፡፡ እነዚያ ነፍሶቻቸውን ያከሰሩ ናቸው፤ እነርሱም አያምኑም፡፡'),
('6:13', 87, 'በሌሊትና በቀንም ጸጥ ያለው ሁሉ የርሱ ብቻ ነው፡፡ እርሱም ሰሚው ዐዋቂ ነው፡፡»'),
('6:14', 87, '«ሰማያትንና ምድርን ፈጣሪ ከኾነው አላህ እርሱ የሚመግብ የማይመገብም ሲኾን ሌላን አምላክ እይዛለሁን» በላቸው፡፡ «እኔ መጀመሪያ ትእዛዝን ከተቀበለ ሰው ልኾን ታዘዝኩ፡፡ ከአጋሪዎችም ፈጽሞ አትኹን (ተብያለሁ)» በላቸው፡፡'),
('6:15', 87, '«እኔ በጌታዬ ባምጽ የታላቁን ቀን ቅጣት እፈራለሁ» በላቸው፡፡'),
('6:16', 87, 'በዚያ ቀን ከእርሱ ላይ (ቅጣት) የሚመለስለት ሰው (አላህ) በእርግጥ አዘነለት፡፡ ይህም ግልጽ ማግኘት ነው፡፡'),
('6:17', 87, 'አላህም በጉዳት ቢነካህ ለእርሱ (ለጉዳቱ) ከእርሱ በቀር ሌላ አስወጋጅ የለም፡፡ በበጎም ነገር ቢነካህ እርሱ በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('6:18', 87, 'እርሱም ከባሮቹ በላይ ሲኾን አሸናፊ ነው፡፡ እርሱም ጥበበኛው ውስጥ ዐዋቂው ነው፡፡'),
('6:19', 87, '«በምስክርነት ከነገሩ ሁሉ ይበልጥ ታላቅ ማነው» በላቸው፡፡ (ሌላ መልስ የለምና) «አላህ ነው፡፡ በእኔና በእናንተ መካከል መስካሪ ነው፡፡ ይህም ቁርኣን እናንተንና የደረሰውን ሰው ሁሉ በርሱ ላስፈራራበት ወደኔ ተወረደ፡፡ ከአላህ ጋር ሌሎች አማልክት መኖራቸውን እናንተ ትመሰክራላችሁን» በላቸው፡፡ «እኔ አልመሰክርም» በላቸው፡፡ «እርሱ አንድ አምላክ ብቻ ነው፡፡ እኔም ከምታጋሩት ነገር ንጹሕ ነኝ» በላቸው፡፡'),
('6:20', 87, 'እነዚያ መጽሐፍን የሰጠናቸው ልጆቻቸውን እንደሚያውቁ (ሙሐመድን) ያውቁታል፡፡ እነዚያ ከእነርሱ ውስጥ ነፍሶቻቸውን ያከሰሩት እነርሱ አያምኑም፡፡'),
('6:21', 87, 'በአላህም ላይ ውሸትን ከቀጣጠፈ ወይም በአንቀጾቹ ካስተባበለ ሰው ይበልጥ በደለኛ ማነው እነሆ በደለኞች አይድኑም፡፡'),
('6:22', 87, 'ሁላቸውንም የምንሰበስብበትንና ከዚያም ለእነዚያ (ጣዖታትን) ለአጋሩት እነዚያ (ለአላህ) ተጋሪዎች ናቸው ብላችሁ ታስቧቸው የነበራችሁት ተጋሪዎቻችሁ የት ናቸው የምንልበትን ቀን (አስታውስ)፡፡'),
('6:23', 87, 'ከዚያም መልሳቸው «በጌታችን በአላህ ይኹንብን አጋሪዎች አልነበርንም» ማለት እንጅ ሌላ አትኾንም፡፡'),
('6:24', 87, 'በነፍሳቸው ላይ እንዴት እንደ ዋሹና ይቀጣጥፉት የነበሩት ነገር ከእነሱ እንዴት እንደ ተሰወረ ተመልከት፡፡'),
('6:25', 87, 'ከእነርሱም ወደ አንተ የሚያዳምጥ ሰው አልለ፡፡ በልቦቻቸውም ላይ እንዳያውቁት ሺፋኖችን በጆሮዎቻቸውም ላይ ድንቁርናን አደረግን፡፡ ተዓምርንም ሁሉ ቢያዩ በርሷ አያምኑም፡፡ በመጡህም ጊዜ የሚከራከሩህ ሲኾኑ እነዚያ የካዱት «ይህ (ቁርኣን) የቀድሞዎቹ ሰዎች ጽሑፍ ተረቶች እንጅ ሌላ አይደለም» ይላሉ፡፡'),
('6:26', 87, 'እነርሱም (ሰዎችን) ከእርሱ ይከለክላሉ፡፡ ከእርሱም ይርቃሉ፡፡ ነፍሶቻቸውንም እንጂ ሌላን አያጠፉም፤ ግን አያውቁም፡፡'),
('6:27', 87, 'በእሳትም ላይ በተቆሙ ጊዜ ምነው (ወደ ምድረ ዓለም) በተመለስን በጌታችንም አንቀጾች ባላስተባበልን ከምእምናንም በኾንን ዋ ምኞታችን! ባሉ ጊዜ ብታይ ኖሮ (የሚያሰደነግጥን ነገር ባየህ ነበር)፡፡'),
('6:28', 87, 'ይልቁንም ከዚህ በፊት ይደብቁት የነበሩት ሁሉ ለእነርሱ ተገለጸ፡፡ (ወደምድረ ዓለም) በተመለሱም ኖሮ ከእርሱ ወደ ተከለከሉት ነገር በተመለሱ ነበር፡፡ እነሱም በእርግጥ ውሸታሞች ናቸው፡፡'),
('6:29', 87, 'እርሷም (ሕይወት) «የቅርቢቱ ሕይወታችን እንጅ ሌላ አይደለችም እኛም ተቀስቀቃሾች አይደለንም» አሉ፡፡'),
('6:30', 87, 'በጌታቸውም ላይ (ለምርመራ) በተቆሙ ጊዜ ብታይ ኖሮ (አስደንጋጭን ነገር ባየህ ነበር)፡፡ «ይህ እውነት አይደለምን» ይላቸዋል፡፡ «በጌታችን ይኹንብን እውነት ነው» ይላሉ፡፡ «ትክዱት በነበራችሁት ምክንያት ቅጣቱን ቅመሱ» ይላቸዋል፡፡'),
('6:31', 87, 'እነዚያ በአላህ መገናኘት ያስተባበሉ በእርግጥ ከሰሩ፡፡ ሰዓቲቱም በድንገት በመጣቻቸው ጊዜ እነሱ ኃጢኣቶቻቸውን በጀርባዎቻቸው ላይ የሚሸከሙ ሲኾኑ «በርሷ (በምድረ ዓለም) ባጓደልነው ነገር ላይ ዋ ቁጪታችን» ይላሉ፡፡ ንቁ! የሚሸከሙት ነገር ከፋ፡፡'),
('6:32', 87, 'የቅርቢቱም ሕይወት ጨዋታና ላግጣ እንጅ ሌላ አይደለችም፡፡ የመጨረሻይቱም አገር (ገነት) ለእነዚያ ለሚጠነቀቁት በጣም በላጭ ናት፡፡ አታውቁምን'),
('6:33', 87, 'እነሆ ያ የሚሉህ ነገር እንደሚያሳዝንህ በእርግጥ እናውቃለን፡፡ እነርሱም (በልቦቻቸው) አያስተባብሉህም፡፡ ግን በዳዮቹ በአላህ አንቀጾች ይክዳሉ፡፡'),
('6:34', 87, 'ከበፊትህም መልክተኞች በእርግጥ ተስተባበሉ፡፡ በተስተባበሉበትም ነገርና በተሰቃዩት ላይ እርዳታችን እስከመጣላቸው ድረስ ታገሱ፡፡ የአላህንም ንግግሮች ለዋጭ የለም፡፡ ከመልክተኞቹም ወሬ (የምትረጋጋበት) በእርግጥ መጣልህ፡፡'),
('6:35', 87, '(ኢስላምን) መተዋቸውም ባንተ ላይ ከባድ ቢኾንብህ በምድር ውስጥ ቀዳዳን ወይም በሰማይ ውስጥ መሰላልን ልትፈልግና በተአምር ልትመጣቸው ብትችል (አድርግ)፡፡ አላህም በሻ ኖሮ በቅኑ መንገድ ላይ በሰበሳባቸው ነበር፡፡ ከተሳሳቱትም ሰዎች በፍጹም አትኹን፡፡'),
('6:36', 87, 'ጥሪህን የሚቀበሉት እነዚያ የሚሰሙት ብቻ ናቸው፡፡ ሙታንንም አላህ ይቀሰቅሳቸዋል፡፡ ከዚያም ወደርሱ ብቻ ይመለሳሉ፡፡'),
('6:37', 87, '«ከጌታውም በእርሱ ላይ ለምን ተዓምር አልተወረደም» አሉ፡፡ «አላህ ተአምርን በማውረድ ላይ ቻይ ነው» በላቸው፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('6:38', 87, 'ከተንቀሳቃሽም በምድር (የሚኼድ)፤ በሁለት ክንፎቹ የሚበርም በራሪ መሰሎቻችሁ ሕዝቦች እንጅ ሌላ አይደሉም፡፡ በመጽሐፉ ውስጥ ምንንም ነገር አልተውንም ከዚያም ወደ ጌታቸው ይሰበሰባሉ፡፡'),
('6:39', 87, 'እነዚያም በአንቀጾቻችን ያስዋሹ ደንቆሮች ድዳዎችም በጨለማዎች ውስጥ ያሉ ናቸው፡፡ አላህ ማጥመሙን የሚሻውን ሰው ያጠመዋል፡፡ መምራቱን የሚሻውንም ሰው በቀጥተኛ መንገድ ላይ ያደርገዋል፡፡'),
('6:40', 87, 'የአላህ ቅጣት ቢመጣባችሁ ወይም ሰዓቲቱ (ትንሣኤ) ብትመጣባችሁ ከአላህ ሌላን ትጠራላችሁን እውነተኞች እንደ ኾናችሁ ንገሩኝ በላቸው፡፡'),
('6:41', 87, 'አይደለም እርሱን ብቻ ትጠራላችሁ፡፡ ቢሻም ወደርሱ የምትጠሩበትን ነገር ያስወግዳል፡፡ የምታጋሩትንም ነገር ትተዋላችሁ (በላቸው)፡፡'),
('6:42', 87, 'ከበፊትህም ወደ ነበሩት ሕዝቦች (መልክተኞችን) በእርግጥ ላክን፡፡ እንዲዋደቁም በድህነትና በበሽታ ያዝናቸው፡፡'),
('6:43', 87, 'ታዲያ ቅጣታችን በመጣባቸው ጊዜ አይዋደቁም ኖሯልን ግን ልቦቻቸው ደረቁ፡፡ ይሠሩት የነበሩትንም ነገር ሰይጣን ለነሱ አሳመረላቸው፡፡'),
('6:44', 87, 'በርሱም ይገሰጹበት የነበረውን ነገር በተው ጊዜ በእነሱ ላይ የነገርን ሁሉ ደጃፎች ከፈትን (አስመቸናቸው)፡፡ በተሰጡትም ነገር በተደሰቱ ጊዜ በድንገት ያዝናቸው፡፡ ወዲያውኑም እነርሱ ተስፋ ቆራጮች ኾኑ፡፡'),
('6:45', 87, 'የእነዚያም የበደሉት ሕዝቦች መጨረሻ ተቆረጠ፡፡ ምስጋናም ለዓለማት ጌታ ለአላህ ይገባው፡፡'),
('6:46', 87, 'ንገሩኝ አላህ መስሚያችሁንና ማያዎቻችሁን ቢወስድ በልቦቻችሁም ላይ ቢያትም ከአላህ ሌላ እሱን የሚያመጣላችሁ አምላክ ማነው በላቸው፡፡ አንቀጾችን እንዴት እንደምናብራራ ከዚያም እነሱ እንዴት እንደሚመለሱ ተመልከት፡፡'),
('6:47', 87, '«ንገሩኝ የአላህ ቅጣት በድንገት ወይም በግልጽ ቢመጣባችሁ አመጠኞች ሕዝቦች እንጅ ሌላ ይጠፋልን» በላቸው፡፡'),
('6:48', 87, 'መልክተኞችንም አብሳሪና አስፈራሪ አድርገን እንጅ አንልክም፡፡ ያመኑና መልካምን የሠሩ ሰዎችም በእነርሱ ላይ ፍርሃት የለባቸውም፤ እነሱም አያዝኑም፡፡'),
('6:49', 87, 'እነዚያም ባንቀጾቻችን ያስዋሹ ያምጹ በነበሩት ምክንያት ቅጣቱ ያገኛቸዋል፡፡'),
('6:50', 87, '«ለእናንተ የአላህ ግምጃ ቤቶች እኔ ዘንድ ናቸው አልልም፡፡ ሩቅንም አላውቅም፡፡ ለእናንተም እኔ መልአክ ነኝ አልልም፡፡ ወደእኔ የሚወርድልኝን እንጅ ሌላን አልከተልም» በላቸው፡፡ «ዕውርና የሚያይ ይስተካከላሉን አታስተነትኑምን» በላቸው፡፡'),
('6:51', 87, 'እነዚያንም ከእርሱ ሌላ ረዳትና አማላጅ የሌላቸው ሲኾኑ ወደ ጌታቸው መስሰብሰብን የሚፈሩትን ይጠነቀቁ ዘንድ በርሱ (በቁርኣን) አስፈራራ፡፡'),
('6:52', 87, 'እነዚያን ጌታቸውን ፊቱን (ውዴታውን) የሚሹ ኾነው በጧትና በማታ የሚጠሩትን አታባር፡፡ ታባርራቸውና ከበደለኞችም ትኾን ዘንድ እነሱን መቆጣጠር ባንተ ላይ ምንም የለብህም፡፡ አንተንም መቆጣጠር በነሱ ላይ ምንም የለባቸውም፡፡'),
('6:53', 87, 'እንደዚሁም «ከመካከላችን አላህ የለገሰላቸው እነዚህ ናቸውን» ይሉ ዘንድ ከፊላቸውን በከፊሉ ሞከርን፡፡ አላህ አመስጋኞቹን ዐዋቂ አይደለምን'),
('6:54', 87, 'እነዚያም በተአምራታችን የሚያምኑት (ወደ አንተ) በመጡ ጊዜ «ሰላም በእናንተ ላይ ይኹን፡፡ ጌታችሁ በነፍሱ ላይ እዝነትን ጻፈ፡፡ እነሆ ከእናንተ ውስጥ በስሕተት ክፉን ሥራ የሠራ ሰው ከዚያም ከእርሱ በኋላ የተጸጸተና ሥራውን ያሳመረ እርሱ (አላህ) መሓሪ አዛኝ ነው» በላቸው፡፡'),
('6:55', 87, 'እንደዚሁም (እውነቱ እንዲገለጽና) የወንጀለኞችም መንገድ ትብራራ ዘንድ አንቀጾችን እንገልጻለን፡፡'),
('6:56', 87, '«እኔ እነዚያን ከአላህ ሌላ የምትጠሩዋቸውን ከመገዛት ተከልክያለሁ» በላቸው፡፡ «ዝንባሌያችሁን አልከተልም፡፡ ያን ጊዜ በእርግጥ ተሳሳትኩ፡፡ እኔም ከተመሪዎቹ አይደለሁም» በላቸው፡፡'),
('6:57', 87, '«እኔ ከጌታዬ በኾነች ግልጽ ማስረጃ ላይ ነኝ፡፡ በእርሱም አስተባበላችሁ፡፡ በርሱ የምትቻኮሉበት ቅጣት እኔ ዘንድ አይደለም፡፡ ፍርዱ ለአላህ ብቻ ነው፡፡ እውነትን ይፈርዳል፡፡ እርሱም ከፈራጆች ሁሉ በላጭ ነው» በላቸው፡፡'),
('6:58', 87, '«በእርሱ የምትቻኮሉበት ቅጣት እኔ ዘንድ በኾነ ኖሮ በእኔና በእናንተ መካከል ነገሩ (ቅጣታችሁ) በተፈጸመ ነበር፡፡ አላህም በደለኞችን ዐዋቂ ነው» በላቸው፡፡'),
('6:59', 87, 'የሩቅ ነገርም መክፈቻዎች እርሱ ዘንድ ናቸው፡፡ ከእርሱ በቀር ማንም አያውቃቸውም፡፡ በየብስና በባሕር ያለውንም ሁሉ ያውቃል፡፡ ከቅጠልም አንዲትም አትረግፍም የሚያውቃት ቢኾን እንጅ፡፡ ከቅንጣትም በመሬት ጨለማዎች ውስጥ የለም ከእርጥብም ከደረቅም አንድም የለም ግልጽ በኾነው መጽሐፍ ውሰጥ (የተመዘገበ) ቢኾን እንጅ፡፡'),
('6:60', 87, 'እርሱም ያ በሌሊት የሚያስተኛችሁ በቀንም የሠራችሁትን ሁሉ የሚያውቅ ከዚያም የተወሰነው ጊዜ ይፈፀም ዘንድ በእርሱ (በቀን) ውስጥ የሚቀሰቅሳችሁ ነው፡፡ ከዚያም መመለሻችሁ ወደ እርሱ ነው፡፡ ከዚያም ትሠሩት የነበራችሁትን ሁሉ ይነግራችኋል፡፡'),
('6:61', 87, 'እርሱም ከባሮቹ በላይ ሲኾን ሁሉን አሸነፊ ነው፡፡ በናንተም ላይ ጠባቂዎችን (መላእክት) ይልካል፡፡ አንዳችሁንም ሞት በመጣበት ጊዜ (የሞት) መልእክተኞቻችን እነርሱ (ትእዛዛትን) የማያጓድሉ ሲኾኑ ይገድሉታል፡፡'),
('6:62', 87, 'ከዚያም እውነተኛ ወደ ኾነው ጌታቸው ወደ አላህ ይመለሳሉ፡፡ ንቁ! ፍርዱ ለእርሱ ብቻ ነው፡፡ እርሱም ከተቆጣጣሪዎች ሁሉ ይበልጥ ፈጣን ነው፡፡'),
('6:63', 87, 'ከየብስና ከባሕር ጨለማዎች በግልጽና በምስጢር የምትጠሩት ስትኾኑ «ከነዚህ ቢያድነን በእርግጥ ከአመስጋኞች እንኾናለን (ስትሉ) የሚያድናችሁ ማነው» በላቸው፡፡'),
('6:64', 87, 'አላህ ከሷና ከጭንቅም ሁሉ ያድናችኋል፡፡ ከዚያም እናንተ ታጋራላችሁ በላቸው፡፡'),
('6:65', 87, '«እርሱ (አላህ) ከበላያችሁ ወይም ከእግሮቻችሁ በታች ቅጣትን በእናንተ ላይ ሊልክ ወይም የተለያዩ ሕዝቦች ስትኾኑ ሊያደባልቃችሁና ከፊላችሁን የከፊሉን ጭካኔ ሊያቀምስ ቻይ ነው» በላቸው፡፡ ያውቁ ዘንድ አንቀጾችን እንዴት እንደምናብራራ ተመልከት፡፡'),
('6:66', 87, 'በእርሱም (በቁርኣን) እሱ እውነት ሲኾን ሕዝቦችህ አስተባበሉ፡፡ በላቸው፡- «በናንተ ላይ ጠባቂ አይደለሁም፡፡»'),
('6:67', 87, 'ለትንቢት ሁሉ (የሚደርስበት) መርጊያ አለው፡፡ ወደፊትም ታውቁታላችሁ፡፡'),
('6:68', 87, 'እነዚያንም በአንቀጾቻችን የሚገቡትን ባየህ ጊዜ ከእርሱ ሌላ በኾነ ወሬ እስከሚገቡ ድረስ ተዋቸው፡፡ ሰይጣንም (መከልከልህን) ቢያስረሳህ ከትውስታ በኋላ ከበደለኞች ሕዝቦች ጋር አትቀመጥ፡፡'),
('6:69', 87, 'በእነዚያም በሚጠነቀቁት ላይ ከሒሳባቸው ምንም የለባቸውም፡፡ ግን ይጠነቀቁ ዘንድ መገሰጽ (አለባቸው)፡፡'),
('6:70', 87, 'እነዚያንም ሃይማኖታቸውን ጨዋታና ላግጣ አድርገው የያዙትን ቅርቢቱም ሕይወት ያታለለቻቸውን ተዋቸው፡፡ በእርሱም (በቁርኣን) ነፍስ በሠራችው ሥራ እንዳትጠፋ አስታውስ፡፡ ለእርሷ ከአላህ ሌላ ረዳትና አማላጅ የላትም፡፡ በመበዢያም ሁሉ ብትበዥ ከርሷ አይወሰድም፡፡ እነዚህ እነዚያ በሠሩት ሥራ የተጠፉት ናቸው፡፡ ለነሱ ይክዱ በነበሩት ምክንያት ከፈላ ውሃ መጠጥና አሳማሚ ቅጣት አላቸው፡፡'),
('6:71', 87, '«ከአላህ ሌላ የማይጠቅመንን እና የማይጎዳንን እንገዛለን አላህም ከመራን ጊዜ በኋላ የኋሊት እንመለሳለን እንደዚያ በምድር ላይ የዋለለ ሲኾን ሰይጣናት እንዳሳሳቱት ለእርሱ ወደኛ ና እያሉ ወደ ቅን መንገድ የሚጠሩ ወዳጆች እንዳሉት (እንደማይከተላቸውም) ሰው እንኾናለን» በላቸው፡፡ «የአላህ መንገድ እርሱ ቀጥተኛው መንገድ ነው፡፡ ለዓለማት ጌታ ልንገዛም ታዘዝን» በላቸው፡፡'),
('6:72', 87, 'ሶላትንም በደንቡ ስገዱ ፍሩትም፤ (በማለት ታዘዝን)፡፡ እርሱም ያ ወደርሱ ብቻ የምትሰበሰቡበት ነው፡፡'),
('6:73', 87, 'እርሱም ያ ሰማያትንና ምድርን በእውነት የፈጠረ ነው፡፡ «ኹን» የሚልበትንና ወዲያውም የሚኾንበትን ቀን (አስታውስ)፡፡ ቃሉ እውነት ነው፡፡ በቀንዱም በሚነፋ ቀን ንግሥናው የርሱ ብቻ ነው፡፡ ሩቁንና ቅርቡን ዐዋቂ ነው፡፡ እርሱም ጥበበኛው ውስጥ ዐዋቂው ነው፡፡'),
('6:74', 87, 'ኢብራሒምም ለአባቱ ለአዘር «ጣዖታትን አማልክት አድርገህ ትይዛለህን እኔ፤ አንተንም ሕዝቦችህንም በግልጽ መሳሳት ውስጥ ኾናችሁ አያችኋለሁ» ባለ ጊዜ (አስታውስ)'),
('6:75', 87, 'እንደዚሁም ኢብራሂምን (እንዲያውቅና) ከአረጋጋጮቹም ይኾን ዘንድ የሰማያትንና የምድርን መለኮት አሳየነው፡፡'),
('6:76', 87, 'ሌሊቱም በእርሱ ላይ ባጨለመ ጊዜ ኮከብን አየ፡፡ «ይህ ጌታዬ ነው» አለ፡፡ በጠለቀም ጊዜ፡- «ጠላቂዎችን አልወድም» አለ፡፡'),
('6:77', 87, 'ጨረቃንም ወጪ ኾኖ ባየ ጊዜ፡- «ይህ ጌታዬ ነው» አለ፡፡ በገባም ጊዜ፡- «ጌታዬ (ቅኑን መንገድ) ባይመራኝ በእርግጥ ከተሳሳቱት ሕዝቦች እኾናለሁ» አለ፡፡'),
('6:78', 87, 'ፀሐይንም ጮራዋን ዘርግታ ባየ ጊዜ፡- «ይህ ጌታዬ ነው፡፡ ይህ በጣም ትልቅ ነው» አለ፡፡ በገባችም ጊዜ፡- «ወገኖቼ ሆይ! እኔ ከምታጋሩት ሁሉ ንጹሕ ነኝ» አለ፡፡'),
('6:79', 87, '«እኔ ለዚያ ሰማያትንና ምድርን ለፈጠረው (አምላክ) ቀጥተኛ ስኾን ፊቴን አዞርኩ፡፡ እኔም ከአጋሪዎቹ አይደለሁም» (አለ)፡፡'),
('6:80', 87, 'ወገኖቹም ተከራከሩት፡፡ «በአላህ (አንድነት) በእርግጥ የመራኝ ሲኾን ትከራከሩኛላችሁን በእርሱም የምታጋሩትን ነገር አልፈራም፡፡ ግን ጌታዬ ነገርን ቢሻ (ያገኘኛል)፡፡ ጌታዬም ነገሩን ሁሉ ዕውቀቱ ሰፋ፡፡ አትገነዘቡምን» አላቸው፡፡'),
('6:81', 87, '«በእናንተ ላይ በእርሱ ማስረጃን ያላወረደበትን እናንተ ማጋራታችሁን የማትፈሩ ስትኾኑ የምታጋሩትን (ጣዖታት) እንዴት እፈራለሁ! የምታውቁም ብትኾኑ ከሁለቱ ክፍሎች በጸጥታ ይበልጥ ተገቢው ማንኛው ነው» (አለ)፡፡'),
('6:82', 87, 'እነዚያ ያመኑና እምነታቸውን በበደል ያልቀላቀሉ እነዚያ ለእነርሱ ጸጥታ አላቸው፡፡ እነሱም የተመሩ ናቸው፤'),
('6:83', 87, 'ይህችም ማስረጃችን ናት፡፡ ለኢብራሂም በሕዝቦቹ ላይ (አስረጅ እንድትኾን) ሰጠናት፡፡ የምንሻውን ሰው በደረጃዎች ከፍ እናደርጋለን፡፡ ጌታህ ጥበበኛ ዐዋቂ ነውና፡፡'),
('6:84', 87, 'ለርሱም ኢስሐቅን (የልጅ ልጁን) ያዕቁብንም ሰጠነው፡፡ ሁሉንም መራን፡፡ ኑሕንም በፊት መራን፡፡ ከዘሮቹም ዳውድን፣ ሱለይማንንም፣ አዩብንም፣ ዩሱፍንም፣ ሙሳንም፣ ሃሩንንም (መራን)፡፡ እንደዚሁም በጎ ሰሪዎችን እንመነዳለን፡፡'),
('6:85', 87, 'ዘከሪያንም፣ የሕያንም፣ ዒሳንም፣ ኢልያስንም (መራን)፡፡ ሁሉም ከመልካሞቹ ናቸው፡፡'),
('6:86', 87, 'ኢስማዒልንም፣ አልየስዕንም፣ ዩኑስንም፣ ሉጥንም (መራን)፡፡ ሁሉንም በዓለማት ላይ አበለጥናቸውም፡፡'),
('6:87', 87, 'ከአባቶቻቸውም፣ ከዘሮቻቸውም፣ ከወንድሞቻቸውም (መራን)፡፡ መረጥናቸውም፤ ወደ ቀጥታውም መንገድ መራናቸው፡፡'),
('6:88', 87, 'ይህ የአላህ መምሪያ ነው፡፡ በእርሱ ከባሮቹ የሚሻውን ሰው ይመራል፡፡ ባጋሩም ኖሮ ይሠሩት የነበሩት ከነሱ በታበሰ ነበር፡፡'),
('6:89', 87, 'እነዚህ እነዚያ መጻሕፍትንና ጥበብን፣ ነቢይነትንም የሰጠናቸው ናቸው፡፡ እነዚህ (የመካ ከሓዲዎች) በእርሷ ቢክዱም በእርሷ የማይክዱን ሕዝቦች ለእርሷ በእርግጥ አዘጋጅተናል፡፡'),
('6:90', 87, 'እነዚህ (ነቢያት)፤ እነዚያ አላህ የመራቸው ናቸው፡፡ በመንገዳቸውም ተከተል፡፡ «በእርሱ (በቁርአን) ላይ ምንም ዋጋ አልጠይቃችሁም፡፡ እርሱ ለዓለማት ግሣጼ እንጅ ሌላ አይደለም» በላቸው፡፡'),
('6:91', 87, '«አላህ በሰው ላይ ምንም አላወረደም» ባሉም ጊዜ አላህን ተገቢ ክብሩን አላከበሩትም፡፡ (እንዲህ) በላቸው፡- «ያንን ብርሃንና ለሰዎች መሪ ኾኖ ሙሳ ያመጣውን መጽሐፍ ክፍልፍሎች የምታደርጉት ስትኾኑ ማን አወረደው (የወደዳችኋትን) ትገልጿታላችሁ ብዙውንም ትደብቃላችሁ፡፡ እናንተም አባቶቻችሁም ያላወቃችሁትን ተስተማራችሁ፤»'),
('6:92', 87, '«አላህ (አወረደው)» በላቸው፡፡ ከዚያም በውሸታቸው ውስጥ የሚጫወቱ ሲኾኑ ተዋቸው፡፡ ይህም ያወረድነው የኾነ ብሩክ ያንንም በፊቱ የነበረውን (መጽሐፍ) አረጋጋጭ መጽሐፍ ነው፡፡ የከተሞችን እናት (መካን) እና በዙሪያዋ ያሉትንም ሰዎች ልታስጠነቅቅበት (አወረድነው)፡፡ እነዚያም በመጨረሻይቱ ዓለም የሚያምኑት እነርሱ በሶላታቸው ላይ የሚጠባበቁ ሲኾኑ በርሱ ያምናሉ፡፡'),
('6:93', 87, 'በአላህም ላይ እብለትን ከቀጣጠፈ ወይም ወደርሱ ምንም ያልተወረደለት ሲኾን «ወደኔ ተወረደልኝ» ካለና፡-«አላህም ያወረደውን ብጤ በእርግጥ አወርዳለሁ» ካለ ሰው ይበልጥ በዳይ ማን ነው በደለኞችንም በሞት መከራዎች ውስጥ በኾኑ ጊዜ መላእክት እጆቻቸውን ዘርጊዎች ኾነው « (ለቅጥጥብ) ነፍሶቻችሁን አውጡ፤ በአላህ ላይ እውነት ያልኾነን ነገር ትናገሩ በነበራችሁትና ከአንቀጾቹም ትኮሩ በነበራችሁት ምክንያት ዛሬ የውርደትን ቅጣት ትመነዳላችሁ» (የሚሏቸው ሲኾኑ) ብታይ ኖሮ (አስደናቂን ነገር ባየህ ነበር)፡፡'),
('6:94', 87, 'መጀመሪያም ጊዜ እንደ ፈጠርናችሁ ኾናችሁ የሰጠናችሁን ሁሉ በጀርባዎቻችሁ ኋላ የተዋችሁ ስትኾኑ የሰጠናችሁን ሁሉ በጀርባዎቻችሁ ኋላ የተዋችሁ ስትኾኑ ለየብቻችሁ ኾናችሁ በእርግጥ መጣችሁን እነዚያንም እነሱ በእናንተ ውስጥ (ለአላህ) ተጋሪዎች ናቸው የምትሉዋቸውን አማላጆቻችሁን ከእናንተ ጋር አናይም፡፡ ግንኙነታችሁ በእርግጥ ተቋረጠ፡፡ ከእናንተም ያ (ያማልደናል) የምትሉት ጠፋ (ይባላሉ)፡፡'),
('6:95', 87, 'አላህ ቅንጣትንና የፍሬን አጥንት ፈልቃቂ ነው፡፡ ሕያውን ከሙት ያወጣል፤ ሙትንም ከሕያው አውጪ ነው፡፡ እርሱ አላህ ነው፤ ታዲያ (ከእምነት) እንዴት ትመለሳላችሁ (ትርቃላችሁ)'),
('6:96', 87, 'እርሱም ጎህን (ከሌሊት ጨለማ) ፈልቃቂ ሌሊትንም ማረፊያ ፀሐይንና ጨረቃንም (ለጊዜ) መቁጠሪያ አድራጊ ነው፡፡ ይህ የአሸናፊው የዐዋቂው (አላህ) ችሎታ ነው፡፡'),
('6:97', 87, 'እርሱም ያ ከዋክብትን በየብስና በባሕር ጨለማዎች ውስጥ በእርሷ ትመሩ ዘንድ ለእናንተ ያደረገ ነው፡፡ ለሚያውቁ ሕዝቦች አንቀጾችን በእርግጥ ዘረዘርን፡፡'),
('6:98', 87, 'እርሱም ያ ከአንዲት ነፍስ ያስገኛችሁ፤ ነው፡፡ (በማሕፀን) መርጊያና (በጀርባ) መቀመጫም (አላችሁ)፡፡ ለሚያወቁ ሕዝቦች አንቀጾችን በእርግጥ ዘረዘርን፡፡'),
('6:99', 87, 'እርሱም ያ ከሰማይ ውሃን ያወረደ ነው፡፡ በርሱም የነገሩን ሁሉ በቃይ አወጣን፡፡ የተደራረበንም ቅንጣት ከርሱ የምናወጣ የኾነን ለምለም (አዝመራ) ከርሱ አወጣን፡፡ ከዘንባባም ከእንቡጧ የተቀራረቡ የኾኑ ዘለላዎች አሉ፡፡ ከወይኖችም፣ ከወይራም፣ ከሩማንም (ቅጠላቸው) ተመሳሳይና (ፍሬያቸው) የማይመሳሰል ሲኾኑ አትክልቶችን (አወጣን)፡፡ ባፈራ ጊዜ ወደ ፍሬውና ወደ መብሰሉ ተመልከቱ፡፡ በእነዚህ ተዓምራት ለሚያምኑ ሕዝቦች ምልክቶች አሉ፡፡'),
('6:100', 87, 'ለአላህም አጋንንትን የፈጠራቸው ሲኾን (በመታዘዝ) ተጋሪዎች አደረጉ፡፡ ወንዶች ልጆችንና ሴቶች ልጆችንም ያለ ዕውቀት ለእርሱ ቀጠፉ፡፡ (አላህ) ጥራት የተገባው ከሚሉት ነገር የላቀ ነው፡፡'),
('6:101', 87, '(እርሱ) ሰማያትንና ምድርን ያለ ብጤ ፈጣሪ ነው፡፡ ለእርሱ ሚስት የሌለችው ሲኾን እንዴት ለእርሱ ልጅ ይኖረዋል ነገርንም ሁሉ ፈጠረ፡፡ እርሱም ነገሩን ሁሉ ዐዋቂ ነው፡፡'),
('6:102', 87, 'ይህ ጌታችሁ አላህ ነው፡፡ ከእርሱ በቀር አምላክ የለም፡፡ ነገርን ሁሉ ፈጣሪ ነው፡፡ ስለዚህ ተገዙት፡፡ እርሱም በነገሩ ሁሉ ላይ ተጠባባቂ ነው፡፡'),
('6:103', 87, 'ዓይኖች አያገኙትም፤ (አያዩትም)፡፡ እርሱም ዓይኖችን ያያል፡፡ እርሱም ርኅራኄው ረቂቁ ውስጠ ዐዋቂው ነው፡፡'),
('6:104', 87, '«ከጌታችሁ ዘንድ ብርሃኖች በእርግጥ መጡላችሁ፡፡ የተመለከተም ሰው (ጥቅሙ) ለነፍሱ ብቻ ነው፡፡ የታወረም ሰው (ጉዳቱ) በራሱ ላይ ብቻ ነው፡፡ እኔም በእናንተ ላይ ጠባቂ አይደለሁም» (በላቸው)፡፡'),
('6:105', 87, 'እንደዚሁም « (እንዲገመግሙና ያለፉትን መጻሕፍት) አጥንተሃልም» እንዲሉ ለሚያውቁ ሕዝቦችም (ቁርኣንን) እንድናብራራው አንቀጾችን እንገልጻለን፡፡'),
('6:106', 87, 'ከጌታህ ወደ አንተ የተወረደውን ተከተል፡፡ ከእርሱ በቀር አምላክ የለም፡፡ አጋሪዎችንም ተዋቸው፡፡'),
('6:107', 87, 'አላህም በሻ ኖሮ ባላጋሩ ነበር፡፡ በእነሱም ላይ ጠባቂ አላደረግንህም፡፡ አንተም በእነሱ ላይ ኃላፊ አይደለህም፡፡'),
('6:108', 87, 'እነዚያንም ከአላህ ሌላ የሚገዙዋቸውን (ጣዖታትን) አትስደቡ፡፡ ድንበርን በማለፍ ያለዕውቀት አላህን ይሰድባሉና፡፡ እንደዚሁ ለሕዝቦች ሁሉ ሥራቸውን ደግ አስመሰልንላቸው፡፡ ከዚያም መመለሻቸው ወደ ጌታቸው ነው፡፡ ይሠሩት የነበሩትንም ሁሉ ይነግራቸዋል፡፡'),
('6:109', 87, 'ተዓምርም ብትመጣላቸው በእርሷ በቁርጥ ሊያምኑ ጥብቅ መሐሎቻቸውን በአላህ ማሉ፡፡ «ተዓምራት ሁሉ አላህ ዘንድ ናት» በላቸው፡፡ እርሷ በመጣች ጊዜም አለማመናቸውን (ወይም ማመናቸውን) ምን አሳወቃችሁ'),
('6:110', 87, 'በመጀመሪያም ጊዜ በእርሱ እንዳላመኑ ሁሉ ልቦቻቸውንና ዓይኖቻቸውን እናገላብጣለን፡፡ በጥመታቸውም ውስጥ የሚዋልሉ ሲኾኑ እንተዋቸዋለን፡፡'),
('6:111', 87, 'እኛም ወደእነርሱ መላእክትን ባወረድን ሙታንም ባነጋገሩዋቸው ነገሩንም ሁሉ ጭፍራ ጭፍራ አድርገን በእነሱ ላይ በሰበሰብን ኖሮ አላህ ካልሻ በስተቀር የሚያምኑ ባልኾኑ ነበር፡፡ ግን አብዛኞቻቸው (ይህንን) ይስታሉ፡፡'),
('6:112', 87, 'እንደዚሁም ለነቢያት ሁሉ ከሰውና ከጋኔን የኾኑን ሰይጣናት ጠላት አደረግን፡፡ ከፊላቸው ወደ ከፊሉ ለማታለል ልብስብስን ቃል ይጥላሉ፡፡ ጌታህም በሻ ኖሮ ባልሠሩት ነበር፡፡ ከቅጥፈታቸውም ጋር ተዋቸው፡፡'),
('6:113', 87, '(የሚጥሉትም ሊያታልሉና) የእነዚያም በመጨረሻይቱ ሕይወት የማያምኑት ሰዎች ልቦች ወደእርሱ እንዲያዘነብሉ እንዲወዱትም እነርሱ ይቀጥፉ የነበሩትንም እንዲቀጣጥፉ ነው፡፡'),
('6:114', 87, 'እርሱ ያ መጽሐፉን የተብራራ ኾኖ ወደእናንተ ያወረደ ሲኾን «ከአላህ ሌላ ዳኛን እፈልጋለሁን» (በላቸው)፡፡ እነዚያም መጽሐፍን የሰጠናቸው እርሱ ከጌታህ ዘንድ በእውነት የተወረደ መኾኑን ያውቃሉ፡፡ ከተጠራጣሪዎቹም አትኹን፡፡'),
('6:115', 87, 'የጌታህም ቃላት እውነተኛና ትክክለኛ ስትኾን ተፈጸመች፡፡ ለቃላቱ ለዋጭ የለም፡፡ እርሱም ሰሚው ዐዋቂው ነው፡፡'),
('6:116', 87, 'በምድርም ካሉት ሰዎች አብዛኞቹን ብትከተል ከአላህ መንገድ ያሳስቱሃል፡፡ ጥርጣሬን እንጅ ሌላን አይከተሉም፡፡ እነርሱም የሚዋሹ እንጂ ሌላ አይደሉም፡፡'),
('6:117', 87, 'ጌታህ እርሱ ከመንገዱ የሚሳሳቱትን ዐዋቂ ነው፡፡ እርሱም ተመሪዎቹን ዐዋቂ ነው፡፡'),
('6:118', 87, 'በአንቀጾቹም አማኞች እንደ ኾናችሁ (ሲታረድ) የአላህ ስም በእርሱ ላይ ከተወሳበት እንስሳ ብሉ፡፡'),
('6:119', 87, 'ወደርሱም (መብላት) ከተገደዳችሁበት በስተቀር በእናንተ ላይ እርም የተደረገውን ለእናንተ (አላህ) በእርግጥ የዘረዘረ ሲኾን ከዚያ በእርሱ ላይ የአላህ ስም ከተጠራበት የማትበሉት ለናንተ ምን (ምክንያት) አላችሁ ብዙዎቹም ያለ ዕውቀት በዝንባሌዎቻቸው ያሳስታሉ፡፡ ጌታህ እርሱ ወሰን አላፊዎቹን ዐዋቂ ነው፡፡'),
('6:120', 87, 'የኃጢአትንም ግልጹንም ድብቁንም ተውዉ፡፡ እነዚያ ኃጢአትን የሚሠሩ፤ ይሠሩት በነበሩት ነገር በእርግጥ ይቀጣሉ፡፡'),
('6:121', 87, 'በእርሱም ላይ የአላህ ስም ካልተጠራበት ነገር አትብሉ፡፡ እርሱም በእርግጥ አመጽ ነው፡፡ ሰይጣናትም ወደ ወዳጆቻቸው (በክትን በመብላት) ይከራከሯችሁ ዘንድ ያሾከሹካሉ፡፡ ብትታዘዙዋቸውም እናንተ በእርግጥ አጋሪዎች ናችሁ፡፡'),
('6:122', 87, 'ሙት የነበረና ሕያው ያደረግነው ለእርሱም በሰዎች መካከል በእርሱ የሚኼድበትን ብርሃን ያደረግንለት ሰው በጨለማዎች ውስጥ ከርሷ የማይወጣ ኾኖ እንዳልለ ሰው ብጤ ነውን እንደዚሁ ለከሓዲዎች ይሠሩት የነበሩት ነገር ተጌጠላቸው፡፡'),
('6:123', 87, 'እንደዚሁም በየከተማይቱ በውስጧ ያሴሩ ዘንድ የተንኮለኞችዋን ታላላቆች አደረግን፡፡ በነፍሶቻቸውም ላይ እንጅ በሌላ ላይ አያሴሩም፤ ግን አያውቁም፡፡'),
('6:124', 87, 'ተዓምርም በመጣቻቸው ጊዜ፡- «የአላህ መልክተኞች የተሰጡትን ብጤ እስክንሰጥ ድረስ በፍጹም አናምንም» አሉ፡፡ አላህ መልክቱን የሚያደርግበትን ስፍራ ዐዋቂ ነው፡፡ እነዚያን ያመጹትን ሰዎች ይዶልቱ በነበሩት ነገር አላህ ዘንድ ውርደትና ብርቱ ቅጣት ያገኛቸዋል፡፡'),
('6:125', 87, 'አላህም ሊመራው የሚሻውን ሰው ደረቱን (ልቡን) ለኢስላም ይከፍትለታል፡፡ ሊያጠመውም የሚሻውን ሰው ደረቱን ጠባብ ቸጋራ ወደ ሰማይ ለመውጣት አንደሚታገል ያደርገዋል፡፡ እንደዚሁ አላህ በእነዚያ በማያምኑት ላይ ርክሰትን ያደርጋል፡፡'),
('6:126', 87, 'ይህም (ያለህበት) ቀጥተኛ ሲኾን የጌታህ መንገድ ነው፡፡ ለሚያስታውሱ ሕዝቦች አንቀጾችን በእርግጥ ዘርዝረናል፡፡'),
('6:127', 87, 'ለእነርሱ በጌታቸው ዘንድ የሰላም አገር አላቸው፡፡ እርሱም (ጌታህ) ይሠሩት በነበሩት ምክንያት ረዳታቸው ነው፡፡'),
('6:128', 87, 'ሁሉንም የሚሰበስብባቸውንም ቀን (አስታውስ)፡፡፡ የአጋንንት ጭፍሮች ሆይ! ከሰዎች (ጭፍራን በማጥመም) በእርግጥ አበዛችሁ (ይባላሉ)፡፡ ከሰዎችም የኾኑት ወዳጆቻቸው፡-«ጌታችን ሆይ! ከፊላችን በከፊሉ ተጠቀመ፡፡ ያንንም ለእኛ የወሰንክልንን ጊዜያችንን ደረስን» ይላሉ፡፡ እሳት አላህ የሻው ጊዜ ሲቀር በውስጧ ዘውታሪዎች ስትኾኑ መኖሪያችሁ ናት ይላቸዋል፡፡ ጌታህ ጥበበኛ ዐዋቂ ነውና፡፡'),
('6:129', 87, 'እንደዚሁም የበደለኞችን ከፊል በከፊሉ ላይ ይሠሩት በነበሩት ጥፋት ምክንያት እንሾማለን፡፡'),
('6:130', 87, 'የጋኔንና የሰዎች ጭፍሮች ሆይ!፡- «አንቀጾቼን በእናንተ ላይ የሚተርኩ የዚህንም ቀናችሁን (ቅጣት) ማግኘትን የሚያስፈራሩዋችሁ ከእናንተው የኾኑ መልክተኞች አልመጧችሁምን» (ይባላሉ)፡፡ «በነፍሶቻችን ላይ መሰከርን፤ (መጥተውልናል)» ይላሉ፡፡ የቅርቢቱም ሕይወት አታለለቻቸው፡፡ በነፍሶቻቸውም ላይ እነርሱ ከሓዲዎች የነበሩ መኾናቸውን መሰከሩ፡፡'),
('6:131', 87, 'ይህ ጌታህ ከተሞችን ባለቤቶችዋ ዘንጊዎች ኾነው ሳሉ በበደል ምክንያት አጥፊ ባለመኾኑ ነው፡፡'),
('6:132', 87, 'ለሁሉም ከሠሩት ሥራ (የተበላለጡ) ደረጃዎች አልሏቸው፡፡ ጌታህም ከሚሠሩት ሁሉ ዘንጊ አይደለም፡፡'),
('6:133', 87, 'ጌታህም ተብቃቂ የእዝነት ባለቤት ነው፡፡ ቢሻ ያስወግዳችኋል፤ (ያጠፋችኋል)፡፡ ከሌሎች ሕዝቦችም ዘሮች እንዳስገኛችሁ ከበኋላችሁ የሚሻውን ይተካል፡፡'),
('6:134', 87, 'የምትቀጠሩት ሁሉ በእርግጥ መጪ ነው፡፡ እናንተም አምላጮች አይደላችሁም፡፡'),
('6:135', 87, '«ሕዝቦቼ ሆይ! በችሎታችሁ ላይ ሥሩ፤ እኔ (በችሎታዬ ላይ) ሠሪ ነኝና፡፡ ምስጉኒቱም አገር (ገነት) ለእርሱ የምትኾንለት ሰው ማን እንደኾነ ወደ ፊት ታውቃላችሁ፡፡ እነሆ በደለኞች አይድኑም» በላቸው፡፡'),
('6:136', 87, 'ለአላህም ከፈጠረው ከአዝመራና ከግመል፣ ከከብት፣ ከፍየልም ድርሻን አደረጉ፡፡ በሐሳባቸውም «ይህ ለአላህ ነው፡፡ ይህም ለተጋሪዎቻችን ነው፡፡» ለተጋሪዎቻቸውም «(ለጣዖታት) የኾነው ነገር ወደ አላህ አይደርስም፡፡ ለአላህም የኾነው እርሱ ወደ ተጋሪዎቻቸው ይደርሳል» አሉ፡፡ የሚፈርዱት ፍርድ ከፋ!'),
('6:137', 87, 'እንደዚሁም ከአጋሪዎቹ ለብዙዎቹ፤ ተጋሪዎቻቸው ሊያጠፉዋቸው ሃይማኖ ታቸውንም በእነሱ ላይ ሊያቀላቅሉባቸው (ሊያመሳስሉባቸው) ልጆቻቸውን መግደልን አሳመሩላቸው፡፡ አላህም በሻ ኖሮ ባልሠሩት ነበር፡፡ ከቅጥፈታቸውም ጋር ተዋቸው፡፡'),
('6:138', 87, 'በሐሳባቸውም ይህች እርም የኾነች ለማዳ እንስሳና አዝመራ ናት፡፡ የምንሻው ሰው እንጂ ሌላ አይበላትም፡፡ (ይህች) ጀርቦችዋ እርም የተደረገች ለማዳ እንስሳም ናት (አትጫንም)፡፡ ይህች በርሷ ላይ የአላህን ስም (ስትታረድ) የማይጠሩባትም እንስሳ ናት አሉ፡፡ በእርሱ ላይ ለመቅጠፍ (ነገሩን ወደ አላህ አስጠጉ)፡፡ ይቀጥፉት በነበሩት ነገር በእርግጥ ይቀጣቸዋል፡፡'),
('6:139', 87, '«በነዚህም እንስሶች ሆዶች ውስጥ ያለው ለወንዶቻችን በተለይ የተፈቀደ ነው፡፡ በሚስቶቻችንም ላይ እርም የተደረገ ነው፡፡ ሙትም ቢኾን (ሙት ኾኖ ቢወለድ) እነርሱ (ወንዶቹም ሴቶቹም) በርሱ ተጋሪዎች ናቸው» አሉ፡፡ በመቅጠፋቸው አላህ በእርግጥ ይቀጣቸዋል፡፡ እርሱ ጥበበኛ ዐዋቂ ነውና፡፡'),
('6:140', 87, 'እነዚያ ያለ ዕውቀት በሞኝነት ልጆቻቸውን የገደሉና አላህም የሰጣቸውን (ሲሳይ) በአላህ ላይ በመቅጠፍ እርም ያደረጉ በእርግጥ ከሰሩ፡፡ በእርግጥ ተሳሳቱ፡፡ ተመሪዎችም አልነበሩም፡፡'),
('6:141', 87, 'እርሱም ያ ዳስ የሚደረግላቸውንና ዳስ የማይደረግላቸውን አትክልቶች የፈጠረ ነው፡፡ ዘምባባንም (የተምርን ዛፍ) አዝመራንም ፍሬዎቹ የተለያዩ ሲኾኑ ወይራንና ሩማንንም (ቅጠላቸው) ተመሳሳይና (ጣዕማቸው) የማይመሳሰል ሲኾኑ (ፈጠረ)፡፡ ባፈራ ጊዜ ከፍሬው ብሉ፡፡ በአጨዳውም ቀን ተገቢውን (ዘካ) ስጡ፡፡ አታባክኑም፡፡ እርሱ አባካኞችን አይወድምና፡፡'),
('6:142', 87, 'ከለማዳ እንስሳዎችም የሚጫኑትንና የማይጫኑትን (ፈጠረ)፡፡ አላህ ከሰጣችሁ ሲሳይ ብሉ፡፡ የሰይጣንንም እርምጃዎች አትከተሉ፡፡ እርሱ ለእናንተ ግልጽ ጠላት ነውና፡፡'),
('6:143', 87, 'ስምንትን ዓይነቶች ከበግ ሁለትን (ወንድና ሴትን) ከፍየልም ሁለትን (ፈጠረ)፡፡«ከሁለቱም ክፍሎች አላህ ወንዶቹን እርም አደረገን ወይስ ሴቶቹን ወይስ በርሱ ላይ የሁለቱ ሴቶች ማሕፀኖች ያጠቃለሉትን እውነተኞች እንደሆናችሁ በዕውቀት (በአስረጅ) ንገሩኝ» በላቸው፡፡'),
('6:144', 87, 'ከግመልም ሁለትን ከከብትም ሁለትን (ፈጠረ)፡፡«አላህ (ከሁለቱ) ወንዶቹን እርም አደረገን ወይስ ሴቶቹን ወይስ የሁለቱ ሴቶች ማሕፀኖች በእርሱ ላይ ያጠቃለሉትን በእውነቱ አላህ በዚህ ባዘዛችሁ ጊዜ የተጣዳችሁ ነበራችሁን ሰዎችንም ያለ ዕውቀት ሊያጠም በአላህ ላይ ውሸትንም ከቀጠፈ ሰው ይበልጥ በደለኛ ማን ነው አላህ በደለኞችን ሕዝቦች (ቅኑን መንገድ) አይመራም፡፡»'),
('6:145', 87, '(ሙሐመድ ሆይ!) በላቸው፡- «ወደእኔ በተወረደው ውስጥ በክት ወይም ፈሳሽ ደም ወይም የአሳማ ስጋ እርሱ ርኩስ ነውና ወይም በአመጽ ከአላህ ስም ሌላ በእርሱ ላይ የተወሳበት ካልኾነ በስተቀር በሚመገበው ተመጋቢ ላይ እርም የኾነን ነገር አላገኝም፡፡ አመጸኛና ወሰን ያለፈ ሳይኾንም የተገደደ ሰው (ከተወሱት ቢበላ ኃጢአት የለበትም)፡፡ ጌታህ መሓሪ አዛኝ ነውና፡፡»'),
('6:146', 87, 'በእነዚያም አይሁዳውያን በኾኑት ላይ ባለ ጥፍርን ሁሉ እርም አደረግን፡፡ ከከብት፣ ከፍየልና ከበግም ሞራዎቻቸውን ጀርባዎቻቸው ወይም አንጀቶቻቸው የተሸከሙት ወይም በአጥንት የተቀላቀለው (ስብ) ሲቀር በነርሱ ላይ እርም አደረግን፡፡ ይህንን በአመጻቸው ምክንያት ቀጣናቸው፡፡ እኛ እውነተኞች ነን፡፡'),
('6:147', 87, 'ቢያስተባብሉህም፡- «ጌታችሁ የሰፊ ችሮታ ባለቤት ነው፡፡ ብርቱ ቅጣቱም ከአመጸኞች ሕዝቦች ላይ አይመለስም» በላቸው፡፡'),
('6:148', 87, 'እነዚያ ያጋሩት «አላህ በሻ ኖሮ እኛም አባቶቻቸንም ባላገራን ነበር፡፡ አንዳችንም ነገር እርም ባላደረግን ነበር ይላሉ፡፡ እንደዚሁ (እነዚህን እንደዋሹ) እነዚያ ከበፊታቸው የነበሩት ብርቱ ቅጣታችንን እስከቀመሱ ድረስ አስተባባሉ፡፡ ለእኛ ታዘልቁልን ዘንድ (ማጋራታችሁን ለመውደዱ) እናንተ ዘንድ ዕውቀት አለን ጥርጣሬን እንጅ ሌላ አትከተሉም፡፡ እናንተ ዋሾዎች እንጂ ሌላ አይደላችሁም» በላቸው፡፡'),
('6:149', 87, '«የተሟላው ማስረጃ የአላህ ነው፡፡ በሻም ኖሮ ሁላችሁንም ባቀናችሁ ነበር» በላቸው፡፡'),
('6:150', 87, '«እነዚያን አላህ ይህን እርም ማድረጉን የሚመሰክሩትን ምስክሮቻችሁን አምጡ» በላቸው፡፡ ቢመሰክሩም ከእነርሱ ጋር አትመስክር፡፡ የነዚያንም በአንቀጾቻችን ያስተባበሉትን የነዚያንም እነርሱ በጌታቸው (ሌላን) የሚያስተካክሉ ሲኾኑ በመጨረሻይቱ ዓለም የማያምኑትን ሰዎች ዝንባሌዎች አትከተል፡፡'),
('6:151', 87, '«ኑ፤ ጌታችሁ በእናንተ ላይ እርም ያደርገውን ነገር (በእርሱም ያዘዛችሁን) ላንብብላችሁ» በላቸው፡፡ «በእርሱ (በአላህ) ምንንም ነገር አታጋሩ፡፡ ለወላጆችም በጎን ሥራ (ሥሩ)፡፡ ልጆቻችሁንም ከድህንት (ፍራቻ) አትግደሉ፡፡ እኛ እናንተንም እነርሱንም እንመግባችኋለንና፡፡ መጥፎ ሥራዎችንም ከእርሷ የተገለጸውንም የተደበቀውንም ሁሉ አትቅረቡ፡፡ ያችንም አላህ እርም ያደረጋትን ነፍስ በሕግ ቢኾን እንጅ አትግደሉ፡፡ ይህን ታውቁ ዘንድ (አላህ) በእርሱ አዘዛችሁ፡፡»'),
('6:152', 87, '«የየቲምንም ገንዘብ ብርታቱን (አካለ መጠን) እስኪደርስ ድረስ በዚያች እርሷ መልካም በኾነች ኹኔታ እንጅ አትቅረቡ፡፡ ስፍርንና ሚዛንንም በትክክሉ ሙሉ፡፡ ነፍስን ችሎታዋን እንጂ አናስገድድም፡፡ በተናገራችሁም ጊዜ በዘመዶቻችሁ ላይ ቢኾንም እንኳ (እውነትን በመናገር) አስተካክሉ፡፡ በአላህም ቃል ኪዳን ሙሉ፡፡ እነሆ ትገሰጹ ዘንድ በርሱ አዘዛችሁ፡፡»'),
('6:153', 87, '«ይህም ቀጥተኛ ሲኾን መንገዴ ነው፤ ተከተሉትም፡፡ (የጥመት) መንገዶችንም አትከተሉ፡፡ ከ(ቀጥተኛው) መንገዱ እናንተን ይለያዩዋችኋልና፡፡እነሆ ትጠነቀቁ ዘንድ በርሱ አዘዛችሁ፡፡»'),
('6:154', 87, 'ከዚያም ለሙሳ በዚያ መልካም በሠራው ላይ (ጸጋችንን) ለማሟላት ነገርንም ሁሉ ለመዘርዘር መጽሐፉን (ለእስራኤል ልጆች) መሪና እዝነት ይኾን ዘንድ ሰጠነው፡፡ እነርሱ በጌታቸው መገናኘት ሊያምኑ ይከጀላልና፡፡'),
('6:155', 87, 'ይህም ያወረድነው የኾነ የተባረከ መጽሐፍ ነው፡፡ ተከተሉትም፡፡ ይታዘንላችሁም ዘንድ (ከክህደት) ተጠንቀቁ፡፡'),
('6:156', 87, '«(ያወረድነውም) መጽሐፍ የተወረደው ከፊታችን በሁለቱ ጭፍሮች ላይ ብቻ ነው፡፡ እኛም ከንባባቸው ዘንጊዎች ነበርን» እንዳትሉ ነው፡፡'),
('6:157', 87, 'ወይም «እኛ መጽሐፍ በእኛ ላይ በተወረደ ኖሮ ከእነሱ ይበልጥ የተመራን እንኾን ነበር» እንዳትሉ ነው፡፡ ስለዚህ ከጌታችሁ ግልጽ ማስረጃ፣ መምሪያም፣ እዝነትም በእርግጥ መጣላችሁ፡፡ በአላህም አንቀጾች ካስተባበለና ከእርሷም ከዞረ ሰው ይበልጥ በዳይ ማን ነው እነዚያን አንቀጾቻችንን የሚተውትን ይተውት በነበሩት ምክንያት ብርቱን ቅጣት በእርግጥ እንቀጣቸዋለን፡፡'),
('6:158', 87, 'መላእክት ልትመጣላቸው ወይም ጌታህ (ቅጣቱ) ሊመጣ ወይም ከጌታህ ምልክቶች ከፊሉ ሊመጣ እንጂ ይጠባበቃሉን ከጌታህ ምልክቶች ከፊሉ በሚመጣ ቀን ከዚህ በፊት አማኝ ያልኾነችን ነፍስ እምነትዋ ወይም በእምነትዋ (ጊዜ) በጎ ያልሠራችን (ነፍስ ጸጸትዋ) አይጠቅማትም፡፡ ተጠባበቁ እኛ ተጠባባቂዎች ነንና በላቸው፡፡'),
('6:159', 87, 'እነዚያ ሃይማኖታቸውን የለያዩ አሕዛብም የኾኑ በምንም ከእነሱ አይደለህም፡፡ ነገራቸው ወደ አላህ ብቻ ነው፡፡ ከዚያም ይሠሩት የነበሩትን ሁሉ ይነገራቸዋል፡፡'),
('6:160', 87, 'በመልካም ሥራ የመጣ ሰው ለእርሱ ዐሥር ብጤዎችዋ አሉት፡፡ በክፉ ሥራም የመጣ ሰው ብጤዋን እንጅ አይመነዳም፡፡ እነርሱም አይበደሉም፡፡'),
('6:161', 87, '«እኔ ጌታዬ ወደ ቀጥተኛው መንገድ ትክክለኛን ሃይማኖት ወደ እውነት አዘንባይ ሲኾን የአብርሃምን መንገድ መራኝ፡፡ እርሱም ከአጋሪዎቹ አልነበረም» በል፡፡'),
('6:162', 87, '«ስግደቴ፣ መገዛቴም፣ ሕይወቴም፣ ሞቴም ለዓለማት ጌታ ለአላህ ነው» በል፡፡'),
('6:163', 87, '«ለእርሱ ተጋሪ የለውም፡፡ በዚህም (በማጥራት) ታዘዝኩ፡፡ እኔም የሙስሊሞች መጀመሪያ ነኝ» (በል)፡፡'),
('6:164', 87, 'በላቸው «እርሱ (አላህ) የሁሉ ጌታ ሲኾን ከአላህ በቀር ሌላን ጌታ እፈልጋለሁን ነፍስም ሁሉ በራሷ ላይ እንጅ (ክፉን) አትሠራም፡፡ ተሸካሚም (ነፍስ) የሌላይቱን ሸክም (ኃጢአት) አትሸከምም፡፡ ከዚያም መመለሻችሁ ወደ ጌታችሁ ነው፡፡ ወዲያውም በእርሱ ትለያዩበት የነበራችሁትን ሁሉ ይነገራችኋል፡፡»'),
('6:165', 87, 'እርሱም ያ በምድር ምትኮች ያደረጋችሁ በሰጣችሁም ጸጋ ሊፈትናችሁ ከፊላችሁን ከከፊሉ በላይ በደረጃዎች ከፍ ያደረገ ነው፡፡ ጌታህ ቅጣቱ ፈጣን ነው፡፡ እርሱም እጅግ መሓሪ ሩኅሩኅ ነው፡፡'),
('7:1', 87, 'አ.ለ.መ.ሰ (አሊፍ፤ ላም ፤ሚም፤ ሷድ)፡፡'),
('7:2', 87, '(ይህ) ወደ አንተ የተወረደ መጽሐፍ ነው፡፡ በደረትህም ውስጥ ከእርሱ ጭንቀት አይኑር፡፡ (የተወረደውም) በእርሱ ልታስፈራራበትና ለምእምናን መገሠጫ እንዲኾን ነው፡፡'),
('7:3', 87, 'ከጌታችሁ ወደእናንተ የተወረደውን ተከተሉ፡፡ ከአላህም ሌላ ረዳቶችን አትከተሉ፡፡ ጥቂትን ብቻ ትገሰጻላችሁ፡፡'),
('7:4', 87, 'ከከተማም ልናጠፋት የሻነው ወዲያውም ብርቱ ቅጣታችን ሌሊት ወይም ቀን እነርሱ በቀትር አርፈው ሳሉ የመጣባቸው ብዙ ናቸው፡፡'),
('7:5', 87, 'ቅጣታችንም በመጣባቸው ጊዜ «ጸሎታቸው እኛ በደለኞች ነበርን» ከማለት በቀር ሌላ አልነበረም፡፡'),
('7:6', 87, 'እነዚያንም ወደነሱ የተላከባቸውን (ሕዝቦች) በእርግጥ መልክተኞቹንም እንጠይቃለን፡፡'),
('7:7', 87, 'በእነርሱም ላይ (የነበሩበትን ሁሉ) ከዕውቀት ጋር በእርግጥ እንተርክላቸዋለን፡፡ የራቅንም አልነበርንም፡፡'),
('7:8', 87, 'ትክክለኛውም ሚዛን የዚያን ቀን ነው፡፡ ሚዛኖቻቸው የከበዱላቸው ሰዎችም እነዚያ እነርሱ የፈለጉትን ያገኙ ናቸው፡፡'),
('7:9', 87, 'ሚዛኖቻቸው የቀለሉባቸው ሰዎችም እነዚያ እነርሱ ተአምራቶቻችንን ይክዱ በነበሩት ምክንያት ነፍሶቻቸውን ያከሰሩ ናቸው፡፡'),
('7:10', 87, 'በምድርም ላይ በእርግጥ አስመቸናችሁ፡፡ በእርሷም ላይ ለናንተ መኖሪያዎችን አደረግንላችሁ፤ ምስጋናችሁ በጣም ጥቂት ነው፡፡'),
('7:11', 87, 'በእርግጥም ፈጠርናችሁ፡፡ ከዚያም ቀረጽናችሁ፡፡ ከዚያም ለመላእክቶች «ለአዳም ስገዱ» አልን፡፡ ወዲያውም ሰገዱ፡፡ ኢብሊስ (ዲያብሎስ) ሲቀር ከሰጋጆቹ አልኾነም፡፡'),
('7:12', 87, '(አላህ) «ባዘዝኩህ ጊዜ ከመስገድ ምን ከለከለህ» አለው፡፡ «እኔ ከርሱ የበለጥኩ ነኝ፡፡ ከእሳት ፈጠርከኝ፡፡ እርሱን ግን ከጭቃ ፈጠርከው» አለ፡፡'),
('7:13', 87, 'ከእርሷ ውረድ፤ በእርሷ ውስጥ ልትኮራ አይገባህምና፡፡ ውጣም አንተ ከወራዶቹ ነህና አለው፡፡'),
('7:14', 87, '«እስከሚቀሰቀሱበት ቀን ድረስ አቆየኝ» አለ፡፡'),
('7:15', 87, '፡-አንተ ከሚቆዩት ነህ አለው፡፡'),
('7:16', 87, '«ስለአጠመምከኝም ለእነርሱ በቀጥተኛው መንገድ ላይ በእርግጥ እቀመጥባቸዋለሁ» አለ፡፡'),
('7:17', 87, '«ከዚያም ከስተፊቶቻቸው ከኋላቸውም ከቀኞቻቸውም ከግራዎቻቸውም በእርግጥ እመጣባቸዋለሁ፡፡ አብዛኞቻቸውንም አመስጋኞች ኾነው አታገኛቸውም» (አለ)፡፡'),
('7:18', 87, '«የተጠላህ ብራሪ ስትኾን ከእርሷ ውጣ፡፡ ከእነርሱ የተከተለህ ከእናንተ ከመላችሁም ገሀነምን በእርግጥ እሞላታለሁ» አለው፡፡'),
('7:19', 87, '«አዳም ሆይ! አንተም ሚስትህም በገነት ተቀመጡ፡፡ ከሻችሁትም ስፍራ ብሉ፡፡ ግን ይህችን ዛፍ አትቅረቡ፡፡ (ራሳቸውን) ከሚበድሉት ትኾናላችሁና» (አላቸው)፡፡'),
('7:20', 87, 'ሰይጣንም ከሐፍረተ ገላቸው የተሸሸገውን ለእነርሱ ሊገልጽባቸው በድብቅ ንግግር ጎተጎታቸው፡፡ «ጌታችሁም መልኣኮች እንዳትኾኑ ወይም ከዘላለም ነዋሪዎች እንዳትኾኑ እንጂ ከዚህች ዛፍ አልከለከላችሁም» አላቸው፡፡'),
('7:21', 87, '«እኔ ለእናንተ በእርግጥ ከሚመክሩዋችሁ ነኝ» ሲልም አማለላቸው፡፡'),
('7:22', 87, 'በማታለልም አዋረዳቸው፡፡ ከዛፊቱም በቀመሱ ጊዜ ኀፍረተ ገላቸው ለሁለቱም ተገለጠችላቸው፡፡ ከገነት ቅጠልም በላያቸው ላይ ይደርቱ ጀመር፡፡ ጌታቸውም «ከዚህ ዛፍ አልከለከልኋችሁምን ሰይጣንም ለእናንተ ግልጽ ጠላት ነው አላልኳችሁምን» ሲል ጠራቸው፡፡'),
('7:23', 87, '«ጌታችን ሆይ! ነፍሶቻችንን በደልን፡፡ ለእኛ ባትምር ባታዝንልንም በእርግጥ ከከሳሪዎቹ እንኾናለን» አሉ፡፡'),
('7:24', 87, '(አላህ) « ከፊላችሁ ለከፊሉ ጠላት ሲኾን ውረዱ፡፡ ለእናንተም በምድር ላይ እስከ ተወሰነ ጊዜ ድረስ መርጊያና መጠቀሚያ አላችሁ» አላቸው፡፡'),
('7:25', 87, '«በእርሷ ላይ ትኖራላችሁ፡፡ በእርሷም ላይ ትሞታላችሁ፡፡ ከእርሷም ውስጥ ትወጣላችሁ» አላቸው፡፡'),
('7:26', 87, 'የአዳም ልጆች ሆይ! ኀፍረተ ገላችሁን የሚሸሽግን ልብስ ጌጥንም በእርግጥ በናንተ ላይ አወረድን፡፡ አላህን የመፍራትም ልብስ ይህ የተሻለ ነው፡፡ ይህ ከአላህ ታምራቶች ነው፡፡ ይገሠጹ ዘንድ (አወረደላቸው)፡፡'),
('7:27', 87, 'የአዳም ልጆች ሆይ! ሰይጣን አባትና እናታችሁን ኀፍረተ ገላቸውን ሊያሳያቸው ልብሶቻቸውን ከነሱ የገፈፋቸው ሲኾን ከገነት እንዳወጣቸው ሁሉ እናንተን አይሞክራችሁ፡፡ እነሆ እርሱ ከነሰራዊቱ ከማታዩዋቸው ስፍራ ያዩዋችኋልና፡፡ እኛ ሰይጣናትን ለእነዚያ ለማያምኑት ወዳጆች አድርገናል፡፡'),
('7:28', 87, 'መጥፎንም ሥራ በሠሩ ጊዜ በእርሷ ላይ አባቶቻችንን አገኘን አላህም በእርሷ አዞናል ይላሉ፡፡ «አላህ በመጥፎ ነገር አያዝም፡፡ በአላህ ላይ የማታውቁትን ትናገራላችሁን» በላቸው፡፡'),
('7:29', 87, 'ጌታዬ በማስተካከል አዘዘ፡፡ በየመስጊዱም ዘንድ ፊቶቻችሁን (እርሱን ለመገዛት) አስተካክሉ፡፡ ሃይማኖትንም ለእርሱ ፍጹም አድርጋችሁ ተገዙት፡፡ እንደጀመራችሁ ትመለሳላችሁ» በላቸው፡፡'),
('7:30', 87, 'ከፊሉን ወደ ቅን መንገድ መራ፡፡ ከፊሎቹም በእነሱ ላይ ጥመት ተረጋግጦባቸዋል፡፡ እነርሱ ሰይጣናትን ከአላህ ሌላ ረዳቶች አድርገው ይዘዋልና፡፡ እነርሱም (ቅኑን መንገድ) የተመራን ነን ብለው ያስባሉ፡፡'),
('7:31', 87, 'የአዳም ልጆች ሆይ! (ኀፍረተ ገላችሁን የሚሸፍኑትን) ጌጦቻችሁን በመስገጃው ሁሉ ዘንድ ያዙ፡፡ ብሉም፤ ጠጡም፤ አታባክኑም፡፡ እርሱ አባካኞችን አይወድምና፡፡'),
('7:32', 87, '«የአላህን ጌጥ ያችን ለባሮቹ የፈጠራትን ከሲሳይም ጥሩዎቹን እርም ያደረገ ማን ነው» በላቸው፡፡ «እርሷ በትንሣኤ ቀን ለእነዚያ ላመኑት ብቻ ስትኾን በቅርቢቱ ሕይወት ተገቢያቸው ናት» በላቸው፡፡ እንደዚሁ ለሚያውቁ ሕዝቦች አንቀጾችን እናብራራለን፡፡'),
('7:33', 87, '«ጌታዬ እርም ያደረገው መጥፎ ሥራዎችን፣ ከርሷ የተገለጸውንና የተደበቀውን ኃጢኣትንም፣ ያላግባብ መበደልንም፣ በርሱም ማስረጃ ያላወረደበትን (ጣዖት) በአላህ ማጋራታችሁን፣ በአላህም ላይ የማታውቁትን መናገራችሁን ብቻ ነው» በላቸው፡፡'),
('7:34', 87, 'ለሕዝብም ሁሉ የተወሰነ ጊዜ አላቸው፡፡ ጊዜያቸውም በመጣ ወቅት አንዲትን ሰዓት አይቆዩም፡፡ (ከጊዜያቱ) አይቀደሙምም፡፡'),
('7:35', 87, 'የአዳም ልጆች ሆይ! ከእናንተ ውስጥ በናንተ ላይ አንቀጾቼን የሚያነቡ መልከተኞች ቢመጧችሁ ከእናንተ ክሕደትን የተጠነቀቁና መልካምንም የሠሩ በነሱ ላይ ፍርሃት የለባቸውም፡፡ እነሱም አያዝኑም፡፡'),
('7:36', 87, 'እነዚያም በአንቀጾቻችን ያስተባበሉ ከእርሷም የኮሩ እነዚያ የእሳት ጓዶች ናቸው፡፡ እነሱ በርሷ ውስጥ ዘውታሪዎች ናቸው፡፡'),
('7:37', 87, 'በአላህ ላይ ውሸትን ከቀጠፈ ወይም በአንቀጾቹ ከአስዋሸ ሰው ይበልጥ በዳይ ማን ነው እነዚያ (ከተጻፈላቸው) ከመጽሐፉ ውስጥ ሲኾን ዕድላቸው ያገኛቸዋል፡፡ (የሞት) መልክተኞቻችንም የሚገድሏቸው ኾነው በመጡባቸው ጊዜ «ከአላህ ሌላ ትገዟቸው የነበራችሁት የት አሉ» ይሏቸዋል፡፡ «ከእኛ ተሰወሩን» ይላሉ፡፡ እነርሱም ከሃዲያን እንደነበሩ በነፍሶቻቸው ላይ ይመሰክራሉ፡፡'),
('7:38', 87, '«ከጋኔንም ከሰውም ከእናንተ በፊት በእርግጥ ካለፉት ሕዝቦች ጋር ኾናችሁ እሳት ውስጥ ግቡ» ይላቸዋል፡፡ አንዲቱ ሕዝብ ወደ እሳት በገባች ቁጥር (ያሳሳተቻትን) ብጤዋን ትረግማለች፡፡ መላውም በውስጧ ተሰብስበው በተገናኙም ጊዜ የኋለኛይቱ ለመጀመሪያይቱ (ተከታዮች ለአስከታዮች) «ጌታችን ሆይ! እነዚህ አሳሳቱን፡፡ ከእሳትም ስቃይ እጥፍን ስጣቸው» ትላለች፡፡ (አላህም)፡- ለሁሉም እጥፍ አለው ግን አታውቁም ይላቸዋል፡፡'),
('7:39', 87, '«መጀመሪያይቱም ለኋለኛይቱ ለእናንተ በእኛ ላይ ምንም ብልጫ አልነበራችሁም» ትላለች፡፡ «ትሠሩትም በነበራችሁት ቅጣቱን ቅመሱ» (ይላቸዋል)፡፡'),
('7:40', 87, 'እነዚያ አንቀጾቻችንን ያስተባበሉ ከእርሷም የኮሩ ለእነርሱ የሰማይ ደጃፎች አይከፈቱላቸውም፡፡ ግመል በመርፌ ቀዳዳ እስከሚገባም ድረስ ገነትን አይገቡም፡፡ እንደዚሁም አጋሪዎችን እንቀጣለን፡፡'),
('7:41', 87, 'ለእነርሱ ከገሀነም እሳት (በሥራቸው) ምንጣፍ ከበላያቸውም (የእሳት) መሸፈኛዎች አሏቸው፡፡ እንደዚሁም በደለኞችን እንቀጣለን፡፡'),
('7:42', 87, 'እነዚያም ያመኑና መልካሞችን የሠሩ ነፍስን ችሎታዋን እንጂ አናስገድድምና፤ እነዚያ የገነት ሰዎች ናቸው፡፡ እነርሱ በርሷ ውስጥ ዘውታሪዎች ናቸው፡፡'),
('7:43', 87, 'በደረቶቻቸው ውስጥ ያለውንም ጥላቻ እናስወግዳለን፡፡ ወንዞች በሥሮቻቸው ይፈሳሉ፡፡ «ለዚያም ወደዚህ (ላደረሰን ሥራ) ለመራን አላህ ምስጋና ይገባው፡፡ አላህ ባልመራንም ኖሮ አንመራም ነበር፡፡ የጌታችን መልክተኞች በእውነት ላይ ሲኾኑ በእርግጥ መጥተውልናል» ይላሉ፡፡ ይህች ገነት ትሠሩት በነበራችሁት ተሰጣችኋት በማለት ይጠራሉ፡፡'),
('7:44', 87, 'የገነትም ሰዎች የእሳትን ሰዎች «ጌታችን ቃል የገባልንን እውነት ኾኖ አገኘን፡፡ ጌታችሁ የዛተባችሁንስ እውነት ኾኖ አገኛችሁትን» ሲሉ ይጣራሉ፡፡ «አዎን አገኘን» ይላሉ፡፡ በመካከላቸውም «የአላህ ርግማን በበደለኞች ላይ ይኹን» ሲል ለፋፊ ይለፍፋል፡፡'),
('7:45', 87, '(በደለኞች) እነዚያ ከአላህ መንገድ የሚከለክሉ፣ (የአላህም መንገድ) እንድትጣመምም የሚፈልጉዋት፣ እነርሱም በመጨረሻዋ ዓለም ከሓዲዎች የኾኑ ናቸው፡፡'),
('7:46', 87, 'በመካከላቸውም ግርዶሽ አልለ፡፡ በአዕራፍም ላይ ሁሉንም በምልክታቸው የሚያውቁ ሰዎች አልሉ፡፡ የገነትንም ሰዎች ሰላም ለናንተ ይኹን በማለት ይጣራሉ፡፡ እነርሱም (የአዕራፍ ሰዎች) የሚከጅሉ ሲኾኑ ገና አልገቧትም፡፡'),
('7:47', 87, 'ዓይኖቻቸውም ወደ እሳት ሰዎች አቅጣጫ በተዞሩ ጊዜ፡- «ጌታችን ሆይ! ከበደለኞች ጋር አታድርገን» ይላሉ፡፡'),
('7:48', 87, 'የአዕራፍም ሰዎች በምልክታቸው የሚያውቁዋቸውን (ታላላቅ) ሰዎች ይጣራሉ፡፡ «ስብስባችሁና በብዛታችሁ የምትኮሩ መኾናችሁም ከእናንተ ምንም አልጠቀማችሁ» ይሏቸዋል፡፡'),
('7:49', 87, 'እነዚያ አላህ በችሮታው አያገኛቸውም ብላችሁ የማላችሁት (ደካሞች) እነዚህ ናቸውን «ገነትን ግቡ ፍርሃት የለባችሁም እናንተም አታዝኑም» (ተባሉ ይሏቸዋል)፡፡'),
('7:50', 87, 'የእሳትም ሰዎች የገነትን ሰዎች «በእኛ ላይ ከውሃ አፍስሱብን ወይም አላህ ከሰጣችሁ ሲሳይ (ጣሉልን)» ብለው ጠሩዋቸዋል፡፡ እነርሱም «አላህ በከሓዲዎች ላይ እርም አድርጓቸዋል» ይሏቸዋል፡፡'),
('7:51', 87, 'እነዚያ ሃይማኖታቸውን መሳለቂያና መጫወቻ አድርገው የያዙ የቅርቢቱም ሕይወት ያታለለቻቸው ይህንን ቀናቸውን መገናኘትን እንደረሱ በተአምራታችንም ይክዱ እንደነበሩ ዛሬ እንረሳቸዋልን፡፡'),
('7:52', 87, 'ከዕውቀት ጋርም የዘረዘርነው የኾነን መጽሐፍ ለሚያምኑ ሕዝቦች መምሪያና እዝነት ሲኾን በእርግጥ አመጣንላቸው፡፡'),
('7:53', 87, '(የዛቻውን) ፍጻሜውን እንጂ ሌላ አይጠባበቁም፡፡ ፍጻሜው በሚመጣበት ቀን እነዚያ ከመምጣቱ በፊት የረሱት ሰዎች «የጌታችን መልክተኞች በእርግጥ በውነት መጥተዋል፡፡ ለእኛ ያማልዱም ዘንድ አማላጆች አልሉን ወይስ ከዚያ እንሠራው ከነበርነው ሌላን ሥራ እንሠራ ዘንድ (ወደ ምድረ ዓለም) እንመለሳለን» ይላሉ፡፡ ነፍሶቻቸውን በእርግጥ አከሰሩ፡፡ ይቀጥፉት የነበሩትም ከእነርሱ ጠፋቸው፡፡'),
('7:54', 87, 'ጌታችሁ ያ ሰማያትንና ምድርን በስድስት ቀኖች ውስጥ የፈጠረ አላህ ነው፡፡ ከዚያም (ለክብሩ በምስማማ መልኩ) በዐርሹ ላይ ተደላደለ፡፡ (አላህ) ሌሊትን በቀን ፈጥኖ የሚፈልገው ሲኾን ይሸፍናል፡፡ ፀሐይንና ጨረቃንም ከዋክብትንም በትእዛዙ የተገሩ ሲኾኑ (ፈጠራቸው)፡፡ ንቁ! መፍጠርና ማዘዝ የእርሱ ብቻ ነው፡፡ የዓለማት ጌታ አላህ (ክብሩ) ላቀ፡፡'),
('7:55', 87, 'ጌታችሁን ተዋርዳችሁ በድብቅም ለምኑት፡፡ እርሱ ወሰን አላፊዎችን አይወድምና፡፡'),
('7:56', 87, 'በምድርም ውስጥ ከተበጀች በኋላ አታበላሹ፡፡ ፈርታችሁና ከጅላችሁም ተገዙት፡፡ የአላህ ችሮታ ከበጎ አድራጊዎች ቅርብ ነውና፡፡'),
('7:57', 87, 'እርሱም ያ ነፋሶችን ከችሮታው (ከዝናም) በፊት አብሳሪዎች አድርጎ የሚልክ ነው፡፡ ከባዳዎችንም ደመናዎች በተሸከሙ ጊዜ ሙት ወደ ኾነ አገር እንነዳዋለን፡፡ በእርሱም ውሃን እናወርዳለን፡፡ ከፍሬዎችም ሁሉ በእርሱ እናወጣለን፡፡ እንደዚሁ ትገነዘቡ ዘንድ ሙታንን (ከመቃብር) እናወጣለን፡፡'),
('7:58', 87, 'መልካሙም አገር በጌታው ፈቃድ በቃዩ (ያማረ ኾኖ) ይወጣል፡፡ ያም መጥፎ የኾነው (በቃዩ) ደካማ ኾኖ እንጂ አይወጣም፡፡ እንደዚሁ ለሚያመሰግኑ ሕዝቦች ታምራትን እናብራራለን፡፡'),
('7:59', 87, 'ኑሕን ወደ ወገኖቹ በእርግጥ ላክነው፡፡ አላቸውም፡- «ወገኖቼ ሆይ! አላህን ተገዙ፡፡ ለእናንተ ከርሱ ሌላ ምንም አምላክ የላችሁም፡፡ እኔ በእናንተ ላይ የከባድ ቀንን ቅጣት እፈራላችኋለሁ፡፡»'),
('7:60', 87, 'ከሕዝቦቹ (የካዱት) መሪዎቹ፡- «እኛ በግልጽ መሳሳት ውስጥ ኾነህ በእርግጥ እናይሃለን» አሉት፡፡'),
('7:61', 87, 'አላቸው «ወገኖቼ ሆይ! ምንም መሳሳት የለብኝም፡፡ ግን እኔ ከዓለማት ጌታ መልእክተኛ ነኝ፡፡»'),
('7:62', 87, '«የጌታዬን መልክቶች አደርስላችኋለሁ፡፡ ለእናንተም እመክራችኋለሁ፡፡ ከአላህም በኩል የማታውቁትን ዐውቃለሁ፡፡»'),
('7:63', 87, '«አላህን ልትፈሩና ይታዘንላችሁም ዘንድ ከእናንተው (ጎሳ) በኾነ ሰው ላይ እንዲያስጠነቅቃችሁ ከጌታችሁ ግሳጼ ቢመጣላችሁ ትደነቃላችሁን» (አላቸው)፡፡'),
('7:64', 87, 'ወዲያውም አስተባበሉት፡፡ እርሱንና እነዚያንም ከእርሱ ጋር ያሉትን (አማኞች) በታንኳዋ ውስጥ አዳንናቸው፡፡ እነዚያንም በአንቀጾቻችን ያስተባበሉትን አሰጠምን፡፡ እነርሱ (ልበ) ዕውራን ሕዝቦች ነበሩና፡፡'),
('7:65', 87, 'ወደ ዓድም ወንድማቸውን ሁድን ላክን፡፡ «ወገኖቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ምንም አምላክ የላችሁም፡፡ (የአላህን ቅጣት) አትፈሩምን» አላቸው፡፡'),
('7:66', 87, 'ከሕዝቦቹ እነዚያ የካዱት መሪዎች «እኛ በሞኝነት ላይ ኾነህ በእርግጥ እናይሃለን፡፡ እኛም ከውሸተኞቹ ነህ ብለን እንጠረጥርሃለን» አሉት፡፡'),
('7:67', 87, '(እርሱም) አላቸው «ወገኖቼ ሆይ! እኔ ሞኝነት የለብኝም፡፡ ግን እኔ ከዓለማት ጌታ የተላክሁ ነኝ፡፡»');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('7:68', 87, '«የጌታዬን መልክቶች አደርስላችኋለሁ፡፡ እኔም ለእናንተ ታማኝ መካሪ ነኝ፡፡»'),
('7:69', 87, '«ከጌታችሁ የኾነ ግሣጼ ከእናንተው ውስጥ ባንድ ሰው ላይ ያስጠነቀቃችሁ ዘንድ ቢመጣባችሁ ትደነቃላችሁን ከኑሕም ሕዝቦች በኋላ ምትኮች ባደረጋችሁና በፍጠረትም ግዙፍነትን በጨመረላችሁ ጊዜ አስታውሱ፡፡ የሻችሁትንም ታገኙ ዘንድ የአላህን ጸጋዎች አስታውሱ፡፡»'),
('7:70', 87, '«አላህን ብቻውን እንድንገዛ አባቶቻችንም ይገዙት የነበረውን (አማልክት) እንድንተው መጣህብን ከውነተኞች ከኾንክ የምታስፈራብንን (ቅጣት) አምጣብን» አሉ፡፡'),
('7:71', 87, '«ከጌታችሁ የኾነ ቅጣትና ቁጣ በእናንተ ላይ በእውነት ተረጋገጠ፡፡ እናንተና አባቶቻችሁም (አማልክት ብላችሁ) በጠራችኋቸው ስሞች አላህ በእርሷ ምንም ማስረጃ ያላወረደባት ስትኾን ትከራከሩኛላችሁን ተጠባባቁም እኔ ከእናንተ ጋር ከተጠባባቂዎቹ ነኝና» አለ፡፡'),
('7:72', 87, 'እርሱንና እነዚያንም አብረውት የነበሩትን ከእኛ በኾነው ችሮታ (ከቅጣት) አዳንናቸው፡፡ የእነዚያንም በተአምራታችን ያስተባበሉትንና አማኞች ያልነበሩትን መሠረት ቆረጥን፡፡'),
('7:73', 87, 'ወደ ሰሙድም ወንድማቸውን ሷሊህን ላክን፡፡ አላቸው «ወገኖቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ለእናንተ ምንም አምላክ የላችሁም፡፡ (እውነተኛ ለመኾኔ) ከጌታችሁ የኾነች ምልክት በእርግጥ መጥታላችኋለች፡፡ ይህች ለእናንተ ተዓምር ስትኾን የአላህ ግመል ናትና ተዋት፡፡ በአላህ ምድር ውስጥ ትብላ፤ (ትጠጣም)፡፡ በክፉ አትንኳትም፡፡ አሳማሚ ቅጣት ይይዛችኋልና፡፡»'),
('7:74', 87, '«ከዓድም በኋላ ምትኮች ባደረጋችሁና በምድሪቱም ላይ ባስቀመጣችሁ ጊዜ አስታውሱ፡፡ ከሜዳዎቿ (ሸክላ) ሕንጻዎችን ትገነባላችሁ፡፡ ከተራራዎችም ቤቶችን ትጠርባላችሁ፡፡ ስለዚህ የአላህን ጸጋዎች አስታውሱ፡፡ በምድርም ውስጥ አጥፊዎች ኾናችሁ አታበላሹ፡፡»'),
('7:75', 87, 'ከወገኖቹ እነዚያ የኮሩት መሪዎች ለእነዚያ ለተሸነፉት ከነሱ ላመኑት፡- «ሷሊህ ከጌታው መላኩን ታውቃላችሁን» አሏቸው፡፡ « (አዎን)፡- እኛ እርሱ በተላከበት ነገር አማኞች ነን» አሉ፡፡'),
('7:76', 87, 'እነዚያ የኮሩት፡- «እኛ በዚያ እናንተ በርሱ ባመናችሁበት ከሓዲዎች ነን» አሉ፡፡'),
('7:77', 87, 'ወዲያውም ግመሊቱን ወጓት፡፡ ከጌታቸውም ትዕዛዝ ወጡ፡፡ አሉም፡- «ሷሊህ ሆይ! ከመልክተኞቹ እንደኾንክ የምታስፈራራብንን (ቅጣት) አምጣብን፡፡»'),
('7:78', 87, 'ወዲያውም የምድር መንቀጥቀጥ (ጩኸትም) ያዘቻቸው፡፡ በቤቶቻቸውም ውስጥ ተንከፍርረው አነጉ፡፡'),
('7:79', 87, '(ሷሊህ) ከእነርሱም ዞረ፡፡ (እንዲህም) አለ «ወገኖቼ ሆይ! የጌታዬን መልክት በእርግጥ አደረስኩላችሁ፡፡ ለእናንተም መከርኳችሁ፡፡ ግን መካሪዎችን አትወዱም፡፡»'),
('7:80', 87, 'ሉጥንም ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፡፡ «አስቀያሚን ሥራ ትሠራላችሁን በእርሷ ከዓለማት አንድም አልቀደማችሁም፡፡»'),
('7:81', 87, '«እናንተ ከሴቶች ሌላ ወንዶችን በመከጀል በእርግጥ ትመጡባቸዋላችሁ፡፡ በእውነቱ እናንተ ወሰንን አላፊዎች ሕዝቦች ናችሁ፡፡»'),
('7:82', 87, 'የሕዝቦቹም መልስ « (ሎጥንና ተከታዮቹን) ከከተማችሁ አውጧቸው፡፡ እነሱ የሚጥራሩ ሰዎች ናቸውና» ማለት እንጂ ሌላ አልነበረም፡፡'),
('7:83', 87, 'እርሱንና ቤተሰቦቹንም አዳንናቸው ሚስቱ ብቻ ስትቀር፡፡ እርሷ (ለጥፋት) ከቀሩት ኾነች፡፡'),
('7:84', 87, 'በእነሱም ላይ (የእሳት) ዝናብን አዘነብንባቸው፡፡ የኃጢአተኞችም መጨረሻ እንዴት እንደነበረ ተመልከት፡፡'),
('7:85', 87, 'ወደ መድየንም (ምድያን) ወንድማቸውን ሹዓይብን (ላክን)፤ አላቸው፡- «ወገኖቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ በቀር ምንም አምላክ የላችሁም፡፡ ከጌታችሁ ዘንድ ግልጽ ማስረጃ በእርግጥ መጥታላችኋለች፡፡ ስፍርንና ሚዛንን ሙሉ፡፡ ሰዎችንም አንዳቾቻቸውን (ገንዘቦቻቸውን) አታጉድሉባቸው፡፡ በምድርም ውስጥ ከተበጀች በኋላ አታበላሹ፡፡ ይህ ምእምናን እንደኾናችሁ ለእናንተ የተሻለ ነው፡፡»'),
('7:86', 87, '« (ሰዎችን) የምታስፈራሩና ከአላህም መንገድ በእርሱ ያመኑትን የምታግዱ መጥመሟንም የምትፈልጉዋት ኾናችሁ በየመንገዱ አትቀመጡ፡፡ ጥቂቶችም በነበራችሁና ባበዛችሁ ጊዜ አስታውሱ፡፡ የአጥፊዎችም መጨረሻ እንዴት እንደነበረ ተመልከቱ፡፡»'),
('7:87', 87, '«ከእናንተም በዚያ እኔ በእርሱ በተላክሁበት ያመኑ ጭፍሮችና ያላመኑ ጭፍሮችም ቢኖሩ በመካከላችን አላህ እስከሚፈርድ ታገሱ፡፡ እርሱም ከፈራጆች ሁሉ በላጭ ነው፡፡»'),
('7:88', 87, 'ከሕዝቦቹ እነዚያ የኮሩት መሪዎች፡- «ሹዓይብ ሆይ! አንተንና እነዚያን ከአንተጋር ያመኑትን ከከተማችን በእርግጥ እናስወጣችኋለን፡፡ ወይም ወደ ሃይማኖታችን መመለስ አለባችሁ አሉ፡፡ የጠላንም ብንኾን» አላቸው፡፡'),
('7:89', 87, '«አላህ ከእርሷ ከአዳነን በኋላ ወደ ሃይማኖታችሁ ብንመለስ በአላህ ላይ በእርግጥ ውሸትን ቀጠፍን፡፡ አላህ ጌታችን ካልሻም በስተቀር ለእኛ ወደእርሷ ልንመለስ አይገባንም፡፡ ጌታችን ዕውቀቱ ሁሉን ነገር ሰፋ፡፡ በአላህ ላይ ተጠጋን፡፡ ጌታችን ሆይ! በኛና በወገኖቻችን መካከል በውነት ፍረድ፡፡ አንተም ከፈራጆቹ ሁሉ በላጭ ነህ» (አለ)'),
('7:90', 87, 'ከወገኖቹም እነዚያ የካዱት መሪዎች «ሹዓይብን ብትከተሉ እናንተ ያን ጊዜ ከሳሪዎች ናችሁ» አሉ፡፡'),
('7:91', 87, 'ወዲያውም የምድር መንቀጥቀጥ (ጩኸትም) ያዘቻቸው፡፡ በከተማቸውም ውስጥ ተንከፍርረው አነጉ፡፡'),
('7:92', 87, 'እነዚያ ሹዓይብን ያሰተባበሉት በእርሷ እንዳልነበሩባት ኾኑ፡፡ እነዚ ሹዓይብን ያስተባበሉት እነርሱ ከሳሪዎች ኾኑ፡፡'),
('7:93', 87, 'ከእነርሱም (ትቷቸው) ዞረ፡- «ወገኖቼ ሆይ! የጌታዬን መልክቶች በእርግጥ አደረስኩላችሁ፡፡ ለእናንተም መከርኩ፡፡ ታዲያ በከሓዲዎች ሰዎች ላይ እንዴት አዝናለሁ» አለም፡፡'),
('7:94', 87, 'በከተማ አንድንም ነቢይ አልላክንም ሰዎችዋን ይዋደቁ ዘንድ በድህነትና በጉዳት የያዝናቸው ብንኾን እንጂ፡፡'),
('7:95', 87, 'ከዚያም እስከበዙና «አባቶቻችንን ድህነትና በሺታ በእርግጥ ነክቷቸዋል፡፡ (ይኽም የጊዜ ልማድ ነው)» እስካሉ ድረስ በመጥፎው ስፍራ በጎውን ለወጥን፡፡ ወዲያውም እነርሱ የማያውቁ ኾነው በድንገት ያዝናቸው፡፡'),
('7:96', 87, 'የከተማዋም ሰዎች ባመኑና በተጠነቀቁ ኖሮ በእነሱ ላይ ከሰማይም ከምድርም በረከቶችን በከፈትንላቸው ነበር፡፡ ግን አስተባበሉ፡፡ ይሠሩት በነበሩትም ኃጢኣት ያዝናቸው፡፡'),
('7:97', 87, 'የከተማዋ ሰዎችም እነሱ የተኙ ኾነው ቅጣታችን ሌሊት ሊመጣባቸው አይፈሩምን'),
('7:98', 87, 'የከተማዋ ሰዎችም እነሱ የሚጫወቱ ኾነው ሳሉ ቅጣታችን ቀን በረፋድ ሊመጣባቸው አይፈሩምን'),
('7:99', 87, 'የአላህንም ማዘናጋት አይፈሩምን የአላህንም ማዘናጋት ከከሳሪዎች ሕዝቦች በስተቀር የሚተማመን የለም፡፡'),
('7:100', 87, 'ለእነዚያ ምድርን ከባለቤቶችዋ (ጥፋት) በኋላ ለሚወርሱት ብንሻ ኖሮ በኃጢኣቶቻቸው የምንቀጣቸው መኾናችን አልተገለጸላቸውምን በልቦቻቸውም ላይ እናትማለን፡፡ ስለዚህ እነርሱ አይሰሙም፡፡'),
('7:101', 87, 'እነዚህ ከተሞች (ከኑሕ እስከ ሹዓይብ ሰዎች የተነገሩት) ከወሬዎቻቸው ባንተ ላይ እንተርካለን፡፡ መልክተኞቻቸውም በግልጽ ተዓምራት በእርግጥ መጥተዋቸዋል፡፡ ከመምጣታቸው በፊት ባስተባበሉትም ነገር የሚያምኑ አልኾኑም፡፡ እንደዚሁ አላህ በከሓዲያን ልቦች ላይ ያትማል፡፡'),
('7:102', 87, 'ለብዙዎቻቸውም በቃል ኪዳናቸው መሙላትን አላገኘንም፡፡ አብዛኞቻቸውንም በእርግጥ አመጸኞች ኾነው አገኘናቸው፡፡'),
('7:103', 87, 'ከዚያም ከበኋላቸው ሙሳን ወደ ፈርዖንና ወደ መማክርቶቹ በተዓምራታችን ላክነው፡፡ በእርሷም ካዱ፡፡ ያጥፊዎችም መጨረሻ እንዴት እንደነበረ ተመልከት፡፡'),
('7:104', 87, 'ሙሳም አለ፡- «ፈርዖን ሆይ! እኔ ከዓለማት ጌታ የተላክሁ መልክተኛ ነኝ፡፡»'),
('7:105', 87, '«»በአላህ ላይ ከእውነት በቀር አለመናገር ተገቢዬ ነው፡፡ ከጌታችሁ በተዓምር በእርግጥ መጣኋችሁ፡፡ የእስራኤልንም ልጆች ከእኔ ጋር ልቀቅ፡፡'),
('7:106', 87, '(ፈርዖንም «በተዓምር የመጣህ እንደኾንክ ከውነተኞቹ ከኾንክ እርሷን አምጣት» አለው፡፡'),
('7:107', 87, 'በትሩንም ጣለ፡፡ እርስዋም ወዲያውኑ ግልጽ እባብ ኾነች፡፡'),
('7:108', 87, 'እጁንም አወጣ፡፡ እርሷም ወዲያውኑ ለተመልካቾች ነጭ ኾነች፡፡'),
('7:109', 87, 'ከፈርዖን ሰዎች መማክርቶቹ፡- «ይህ በእርግጥ ዐዋቂ ድግምተኛ ነው» አሉ፡፡'),
('7:110', 87, '«ከምድራችሁ ሊያወጣችሁ ይሻል» (አሉ)፡፡ «ታዲያ ምን ታዛላችሁ» (አለ)'),
('7:111', 87, '(እነርሱም) አሉ «እርሱንና ወንድሙን አቆይ፡፡ ወደ ከተሞቹም ሁሉ ሰብሳቢዎችን (ዘበኞች) ላክ፡፡»'),
('7:112', 87, '«ዐዋቂ ድግምተኛ የኾነን ሁሉ ያመጡልሃልና፡፡»'),
('7:113', 87, 'ድግምተኞቹም ወደ ፈርዖን መጡ፡፡ «እኛ አሸናፊዎች ብንኾን ለእኛ በእርግጥ ዋጋ አለን» አሉ፡፡'),
('7:114', 87, '«አዎን እናንተም በእርግጥ ከባለሟሎቹ ትኾናላችሁ» አላቸው፡፡'),
('7:115', 87, '«ሙሳ ሆይ (በትርህን) ወይም (በፊት) ትጥላለህ ወይም እኛ ጣዮች እንኾናለን» አሉት፡፡'),
('7:116', 87, '«ጣሉ» አላቸው፡፡ (ገመዶቻቸውን) በጣሉም ጊዜ የሰዎቹን ዓይኖች ደገሙባቸው፡፡ አስፈራሩዋቸውም፡፡ ትልቅ ድግምትንም አመጡ፡፡'),
('7:117', 87, 'ወደ ሙሳም፡- «በትርህን ጣል» ስንል ላክን፡፡ (ጣላትም) ወዲያውኑም የሚቀጣጥፉትን (ማታለያ) ትውጣለች፡፡'),
('7:118', 87, 'እውነቱም ተገለጸ፡፡ ይሠሩት የነበሩትም (ድግምት) ተበላሸ፡፡'),
('7:119', 87, 'እዚያ ዘንድ ተሸነፉም፡፡ ወራዶችም ኾነው ተመለሱ፡፡'),
('7:120', 87, 'ድግምተኞቹም ሰጋጆች ኾነው ወደቁ፡፡'),
('7:121', 87, 'አሉ፡- «በዓለማት ጌታ አመንን፡፡»'),
('7:122', 87, '«በሙሳና በሃሩን ጌታ፡፡»'),
('7:123', 87, 'ፈርዖን አለ፡- «እኔ ለእናንተ ሳልፈቅድላችሁ በፊት በእርሱ አመናችሁን ይህ በከተማይቱ ውስጥ ሰዎቿን ከእርሷ ለማውጣት በእርግጥ የተስማማችሁበት ተንኮል ነው፡፡ ወደፊትም (የሚደርስባችሁን) ታውቃላችሁ፡፡»'),
('7:124', 87, '«እጆቻችሁንና እግሮቻችሁን በማፈራረቅ በእርግጥ እቆራርጣለሁ፡፡ ከዚያም ሁላችሁንም በእርግጥ እሰቅላችኋለሁ፡፡»'),
('7:125', 87, 'አሉ፡- «እኛ ወደ ጌታችን ተመላሾች ነን፡፡»'),
('7:126', 87, '«የጌታችንም ተዓምራቶች በመጡልን ጊዜ ከማመናችን በቀር ከእኛ አትጠላም፡፡ ጌታችን ሆይ! በእኛ ላይ ትዕግስትን አፍስስ፡፡ ሙስሊሞች ኾነን ግደለን፡፡»'),
('7:127', 87, 'ከፈርዖንም ሰዎች ታላላቆቹ (ለፈርዖን) «ሙሳንና ሰዎቹን በምድር ላይ እንዲያበላሹና (ሙሳም) አንተንና አማልክቶችህን እንዲተው ትተዋቸዋለህን» አሉ፡፡ «ወንዶች ልጆቻቸውን እንገድላለን፡፡ ሴቶቻቸውንም እናስቀራለን፡፡ እኛም ከበላያቸው ነን፡፡ አሸናፊዎች (ነን)» አለ፡፡'),
('7:128', 87, 'ሙሳ ለሰዎቹ፡- «ለአላህ ተገዙ ታገሱም፡፡ ምድር ለአላህ ናትና፡፡ ከባሮቹ ለሚሻው ያወርሳታል፡፡ ምሰጉንዋም ፍጻሜ ለጥንቁቆቹ ናት» አላቸው፡፡'),
('7:129', 87, '«ከመምጣትህም በፊት ከመጣኽልንም በኋላ ተሰቃየን» አሉት፡፡ «ጌታችሁ ጠላቶቻችሁን ሊያጠፋ እንዴት እንደምትሠሩም ይመለከት ዘንድ በምድር ላይ ሊተካችሁ ይሻል» አላቸው፡፡'),
('7:130', 87, 'የፈርዖንንም ቤተሰቦች እንዲገሰጹ በድርቅ ዓመታትና ከፍሬዎችም በመቀነስ በእርግጥ ያዝናቸው፡፡'),
('7:131', 87, 'ደጊቱም ነገር (ምቾት) በመጣችላቸው ጊዜ «ይህች ለእኛ (ተገቢ) ናት» ይላሉ፡፡ ክፉትም ብታገኛቸው በሙሳና አብረውት ባሉት ገደቢስነት ያመካኛሉ፡፡ ንቁ! ገደቢስነታቸው አላህ ዘንድ ብቻ ነው፡፡ ግን አብዛኛዎቻቸው አያውቁም፡፡'),
('7:132', 87, '(ለሙሳም) «በማንኛይቱም ተዓምር በእርሷ ልትደግምብን ብትመጣብን እኛ ለአንተ የምናምንልህ አይደለንም» አሉ፡፡'),
('7:133', 87, 'ወዲያም የወሃን ማጥለቅለቅ አንበጣንም ነቀዝንም እንቁራሪቶችንም ደምንም የተለያዩ ተዓምራት ሲኾኑ በነሱ ላይ ላክን ኮሩም ተንኮለኞችም ሕዝቦች ነበሩ፡፡'),
('7:134', 87, 'በእነርሱም ላይ ቅጣቱ በወደቀባቸው ጊዜ «ሙሳ ሆይ! ጌታህን ላንተ ቃል ኪዳን በገባልህ ነገር ለእኛ ለምንልን፡፡ ከእኛ ቅጣቱን ብታነሳልን ለአንተ በእርግጥ እናምንልሃለን፡፡ የእስራኤልንም ልጆች ከአንተ ጋር በእርግጥ እንለቃለን፤» አሉ፡፡'),
('7:135', 87, 'እነርሱም ደራሾቹ እኾኑበት ጊዜ ድረስ ቅጣትን ከእነሱ ላይ ባነሳን ጊዜ ወዲያውኑ እነርሱ ቃላቸውን ያፈርሳሉ፡፡'),
('7:136', 87, 'እነርሱ በተዓምራታችን ስለአስተባበሉም ከእርሷ ዘንጊዎች ስለኾኑም፤ ከእነሱ ተበቀልን፡፡ በባሕርም ውስጥ አሰጠምናቸው፡፡'),
('7:137', 87, 'እነዚያንም ደካሞች የነበሩትን ሕዝቦች ያችን በውስጧ በረከት ያደረግንባትን ምድር ምሥራቆችዋንም ምዕራቦቿንም አወረስናቸው፡፡ የጌታህም መልካሚቱ ቃል በእስራኤል ልጆች ላይ በመታገሳቸው ተፈጸመች፡፡ ፈርዖንና ሰዎቹም ይሠሩት የነበረውን (ሕንጻ) ዳስ ያደርጉትም የነበረውን አፈረስን፡፡'),
('7:138', 87, 'የእስራኤልንም ልጆች ባሕሩን አሻገርናቸው፡፡ ለእነርሱ በኾኑ ጣዖታት (መገዛት) ላይ በሚዘወትሩ ሕዝቦች ላይ አለፉም፡፡ «ሙሳ ሆይ፡- ለእነርሱ (ለሰዎቹ) አማልክት እንዷላቸው ለእኛም አምላክን አድርግልን» አሉት፡፡ «እናንተ የምትሳሳቱ ሕዝቦች ናችሁ፤» አላቸው፡፡'),
('7:139', 87, '«እነዚህ እነርሱ በውስጡ ያሉበት ነገር ጠፊ ነው፡፡ ይሰሩት የነበሩትም ብልሹ ነው» (አላቸው)፤'),
('7:140', 87, '«ከአላህ ሌላ እርሱ ከዓለማት ያበለጣችሁ ሲኾን (የምትገዙት) አምላክን እፈልግላችኋለሁን» አለ፡፡'),
('7:141', 87, 'ከፈርዖንም ቤተሰቦች ብርቱን ቅጣት የሚያቀምሱዋችሁ ወንዶች ልጆቻችሁን የሚገድሉ ሴቶቻችሁንም የሚተዉ ሲኾኑ ባዳናችሁ ጊዜ (አስታውሱ)፡፡ በዚህም ውስጥ ከጌታችሁ ዘንድ የኾነ ከባድ ፈተና አለበት፡፡'),
('7:142', 87, 'ሙሳንም ሰላሳን ሌሊት (ሊጾምና ልናነጋግረው) ቀጠርነው፡፡ በዐስርም (ሌሊት) ሞላናት፡፡ የጌታውም ቀጠሮ አርባ ሌሊት ሲኾን ተፈጸመ፡፡ ሙሳም ለወንድሙ ሃሩን «በሕዝቦቼ ላይ ተተካኝ፡፡ አሳምርም የአጥፊዎችንም መንገድ አትከተል» አለው፡፡'),
('7:143', 87, 'ሙሳም ለቀጠሯችን በመጣና ጌታውም ባነጋገረው ጊዜ፡- «ጌታዬ ሆይ! (ነፍስህን) አሳየኝ ወደ አንተ እመለከታለሁና» አለ፡፡ (አላህም)፡- «በፍጹም አታየኝም ግን ወደ ተራራው ተመልከት፡፡ በስፍራውም ቢረጋ በእርግጥ ታየኛለህ» አለው፡፡ ጌታው ለተራራው በተገለጸ ጊዜ እንኩትኩት አደረገው፡፡ ሙሳም ጮሆ ወደቀ፡፡ በአንሰራራም ጊዜ «ጥራት ይገባህ፡፡ ወዳንተ ተመለስኩ፡፡ እኔም (በወቅቱ) የምእምናን መጀመሪያ ነኝ» አለ፡፡'),
('7:144', 87, '(አላህም) አለው፡- «ሙሳ ሆይ! እኔ በመልክቶቼና በማናገሬ በሰዎች ላይ መረጥኩህ፡፡ የሰጡህንም ያዝ፡፡ ከአመስጋኞቹም ኹን፡፡»'),
('7:145', 87, 'ለእርሱም በሰሌዳዎቹ ላይ ከነገሩ ሁሉ ግሳጼንና ለነገሩም ሁሉ ማብራራትን ጻፍንለት፡፡ (አልንም) በብርታትም ያዛት፡፡ ሕዝቦችህንም በመልካሟ እንዲይዙ እዘዛቸው፡፡ የአመጸኞቹን አገር በእርግጥ አሳያችኋለሁ፡፡'),
('7:146', 87, 'እነዚያን ያለአግባብ በምድር ላይ የሚኮሩትን ከአንቀጾቼ በእርግጥ አዞራቸዋለሁ፡፡ ተዓምርንም ሁሉ ቢያዩ በርሷ አያምኑም፡፡ ቅንንም መንገድ ቢያዩ መንገድ አድርገው አይዙትም፡፡ ግን የጥመትን መንገድ ቢያዩ መንገድ አድርገው ይይዙታል፡፡ ይህ እነርሱ በአንቀጾቻችን ስለአስተባበሉና ከእርሷም ዘንጊዎች ስለኾኑ ነው፡፡'),
('7:147', 87, 'እነዚያም በአንቀጾቻችንና መጨረሻይቱን ዓለም በመገናኘት ያስተባበሉት ሥራዎቻቸው ተበላሹ፡፡ ይሠሩት የነበረውን እንጂ ይመነዳሉን'),
('7:148', 87, 'የሙሳም ሕዝቦች ከእርሱ (መኼድ) በኋላ ከጌጦቻቸው ወይፈንን አካልን ለርሱ ማግሳት ያለውን (አምላክ አድርገው) ያዙ፡፡ እርሱ የማያናግራቸው መንገድንም የማይመራቸው መኾኑን አይመለከቱምን (አምላክ አድርገው) ያዙት፡፡ በዳዮችም ኾኑ፡፡'),
('7:149', 87, 'በተጸጸቱና እነሱም በእርግጥ የተሳሳቱ መኾናቸውን ባዩ ጊዜ፡- «ጌታችን ባያዝንልንና ባይምረን በእርግጥ ከከሳሪዎቹ እንኾናለን» አሉ፡፡'),
('7:150', 87, 'ሙሳም እየተቆጣና እያዘነ ወደ ሕዝቦቹ በተመለሰ ጊዜ «ከእኔ በኋላ በእኔ ላይ የተካችሁት ነገር ከፋ! የጌታችሁን ትእዛዝ ተቻኮላችሁን» አላቸው፡፡ ሰሌዳዎቹንም ጣላቸው፡፡ የወንድሙንም ራስ (ጸጉር) ወደርሱ የሚጎትተው ሲኾን ያዘ፡፡ (ወንድሙም)፡- «የናቴ ልጅ ሆይ! ሕዝቦቹ ናቁኝ፡፡ ሊገድሉኝም ተቃራቡ፡፡ ስለዚህ በእኔ ጠላቶችን አታስደስትብኝ፡፡ ከአመጸኞች ሕዝቦችም ጋር አታድርገኝ» አለው፡፡'),
('7:151', 87, '(ሙሳም)፡- «ጌታዬ ሆይ! ለእኔም ለወንድሜም ማር፡፡ በእዝነትህም ውስጥ አግባን፡፡ አንተም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነህ» አለ፡፡'),
('7:152', 87, 'እነዚያ ወይፈኑን (አምላክ አድርገው) የያዙ ከጌታቸው ዘንድ ቁጣ፤ በቅርቢቱም ሕይወት ውርደት በእርግጥ ያገኛቸዋል፡፡ እንዲሁም ቀጣፊዎችን እንቀጣለን፡፡'),
('7:153', 87, 'እነዚያም ኃጢአቶችን የሠሩ ከዚያም ከእርሷ በኋላ የተጸጸቱ ያመኑም ጌታህ ከእርሷ በኋላ በእርግጥ መሓሪ አዛኝ ነው፡፡'),
('7:154', 87, 'ከሙሳም ቁጣው በበረደ ጊዜ ሰሌዳዎቹን በግልባጫቸው ውስጥ ለእነዚያ እነርሱ ጌታቸውን የሚፈሩ ለኾኑት መምሪያና እዝነት ያለባቸው ሲኾኑ ያዘ፡፡'),
('7:155', 87, 'ሙሳም ከሕዝቦቹ ውስጥ ለቀጠሮዋችን ሰባን ሰዎች መረጠ፡፡ ብርቱ የምድር እንቅጥቃጤ በያዘቻቸውም ጊዜ ሙሳ አለ «ጌታዬ ሆይ! በሻህ ኖሮ ከአሁን በፊት በአጠፋሃቸው ነበር፡፡ እኔንም (ባጠፋኸኝ ነበር)፡፡ ከእኛ ቂሎቹ በሠሩት ነገር ታጠፋናለህን እርሷ (ፈተናይቱ) ያንተ ፈተና እንጂ ሌላ አይደለችም፡፡ በእርሷ የምትሻውን ታሳስታለህ፡፡ የምትሻውንም ታቀናለህ፡፡ አንተ ረዳታችን ነህና ለእኛ ምሕረት አድርግልን፡፡ እዘንልንም፡፡ አንተም ከመሓሪዎች ሁሉ በላጭ ነህ፡፡»'),
('7:156', 87, '«ለእኛም በዚች በቅርቢቱ ዓለም መልካሟን በመጨረሻይቱም (መልካሟን) ጻፍልን፡፡ እኛ ወደ አንተ ተመለስን፡፡» (ሲል ሙሳ ጸለየ፤ አላህም) አለ፡- «ቅጣቴ በእርሱ የምሻውን ሰው እቀጣበታለሁ፡፡ ችሮታየም ነገሩን ሁሉ ሰፋች፡፡ ለእነዚያም ለሚጠነቀቁ፣ ዘካንም ለሚሰጡ፣ ለእነዚያም እነሱ በአንቀጾቻችን ለሚያምኑ በእርግጥ» እጽፋታለሁ፡፡'),
('7:157', 87, 'ለእነዚያ ያንን እነሱ ዘንድ በተውራትና በኢንጂል ተጽፎ የሚያገኙትን የማይጽፍና የማያነብ ነቢይ የኾነውን መልክተኛ የሚከተሉ ለኾኑት (በእርግጥ እጽፍለታለሁ)፡፡ በበጎ ሥራ ያዛቸዋል፡፡ ከክፉም ነገር ይከለክላቸዋል፡፡ መልካም ነገሮችንም ለነርሱ ይፈቅድላቸዋል፡፡ መጥፎ ነገሮችንም በእነርሱ ላይ እርም ያደርግባቸዋል፡፡ ከእነሱም ላይ ሸክማቸውንና እነዚያንም በእነርሱ ላይ የነበሩትን እንዛዝላዎች (ከባድ ሕግጋቶች) ያነሳላቸዋል፡፡ እነዚያም በእርሱ ያመኑ ያከበሩትም የረዱትም ያንንም ከእርሱ ጋር የተወረደውን ብርሃን የተከተሉ እነዚያ እነሱ የሚያድኑ ናቸው፡፡'),
('7:158', 87, '(ሙሐመድ ሆይ!) በላቸው፡- «እናንተ ሰዎች ሆይ! እኔ ወደናንተ ወደሁላችሁም የአላህ መልክተኛ ነኝ፡፡ (እርሱም) ያ የሰማያትና የምድር ንግሥና ለእርሱ ብቻ የኾነ ነው፡፡ እርሱ እንጂ ሌላ አምላክ የለም፡፡ ሕያው ያደርጋል፡፡ ይገድላልም፡፡ በአላህ በዚያም በአላህና በቃላቶቹ በሚያምነው የማይጽፍ የማያነብ ነቢይ በኾነው መልክተኛው እመኑ፡፡ ቅንንም መንገድ ትመሩ ዘንድ ተከተሉት፡፡»'),
('7:159', 87, 'ከሙሳም ሕዝቦች በእውነት የሚመሩት በእርሱም (ፍርድን) የሚያስተካክሉ ጭፍሮች አሉ፡፡'),
('7:160', 87, 'ዐሥራ ሁለት ነገዶች ሕዝቦች አድርገንም ከፋፈልናቸው፡፡ ወደ ሙሳም ወገኖቹ መጠጣትን በፈለጉበት ጊዜ «ድንጋዩን በበትርህ ምታው» ስንል ላክን፡፡ (መታውም) ከእርሱ ዐሥራ ሁለት ምንጮችም ፈለቁ፡፡ ሰዎቹ ሁሉ መጠጫቸውን በእርግጥ ዐወቁ፡፡ በእነሱም ላይ ደመናን አጠለልን፡፡ በእነሱም ላይ መናንና ድርጭትን አወረድን፡፡ «ከሰጠናችሁም መልካም ሲሳይ ብሉ» (አልን፤ ጸጋችንን በመካዳቸው) አልበደሉንምም፡፡ ግን ነፍሶቻቸውን የሚበድሉ ነበሩ፡፡'),
('7:161', 87, 'ለእነርሱም በተባሉ ጊዜ (አስታውስ) «በዚህች ከተማ ተቀመጡ፡፡ ከእርሷም በሻችሁት ስፍራ ብሉ፡፡ (የምንፈልገው) የኃጢኣታችንን መርገፍ ነው በሉም፡፡ የከተማይቱንም በር አጎንብሳችሁ ግቡ፡፡ ኃጢኣቶቻችሁን ለእናንተ እንምራለንና፡፡ በጎ ለሠሩት በእርግጥ እንጨምራለን፡፡»'),
('7:162', 87, 'ከእነሱም ውስጥ እነዚያ (ራሳቸውን) የበደሉት ሰዎች ከዚያ ለእነርሱ ከተባለው ሌላ የኾነን ቃል ለወጡ፡፡ በእነርሱም ላይ ይበድሉ በነበሩት በደል መዐትን ከሰማይ ላክንባቸው፡፡'),
('7:163', 87, 'ከዚያችም በባህሩ ዳርቻ ከነበረችው ከተማ በቅዳሜ (ቀን) ወሰን ባለፉ ጊዜ በሰንበታቸው ቀን ዐሳዎቻቸው የተከማቹ ኾነው በሚመጡላቸው ጊዜ (የኾነውን) ጠይቃቸው፡፡ ሰንበትንም በማያከብሩበት (በሌላው) ቀን አይመጡላቸውም፡፡ እንደዚሁ ያምጹበት በነበሩት ምክንያት እንሞክራቸዋለን፡፡'),
('7:164', 87, 'ከእነሱም (ከፊሎቹ) ሕዝቦች «አላህ አጥፊያቸው ወይም በብርቱ ቅጣት ቀጪአቸው የኾኑትን ሕዝቦች ለምን ትገስፃጻላችሁ» ባሉ ጊዜ (ገሳጮቹ) «ወደ ጌታችሁ በቂ ምክንያት እንዲኾንና እነርሱም ቢከለከሉ ብለን ነው» አሉ፡፡'),
('7:165', 87, 'በእርሱም የተገሰጹበትን ነገር በተዉ ጊዜ እነዚያን ከክፉ የሚከለከሉትን አዳንን፤ እነዚያንም የበደሉትን ያምጹ በነበሩት ምክንያት በብርቱ ቅጣት ያዝናቸው፡፡'),
('7:166', 87, 'ከእርሱም ከተከለከሉት ነገር በኮሩ ጊዜ ለእነሱ «ወረዶች ዝንጀሮች ኹኑ አልን፤» (ኾኑም)፡፡'),
('7:167', 87, 'ጌታህም እስከ ትንሣኤ ቀን ክፉ ቅጣትን የሚያቀምሳቸውን ሰው በነሱ ላይ በእርግጥ የሚልክ መኾኑን ባስታወቀ ጊዜ (አስታውሳቸው)፡፡ ጌታህ በእርግጥ ቅጣተ ፈጣን ነው፡፡ እርሱም በእርግጥ እጅግ መሓሪ አዛኝ ነው፡፡'),
('7:168', 87, '(የእስራኤልን ልጆች) በምድር ላይ የተለያዩ ሕዝቦች አድርገንም ከፋፈልናቸው፡፡ ከእነሱ መልካሞች አሉ፡፡ ከእነሱም ከዚያ ሌላ አልሉ፡፡ ይመለሱ ዘንድም በተድላዎችም በመከራዎችም ሞከርናቸው፡፡'),
('7:169', 87, 'ከኋላቸውም፡- መጽሐፉን የወረሱ መጥፎ ምትኮች ተተኩ፡፡ የዚህን የቅርቡን ጠፊ ጥቅም ይይዛሉ፡፡ ብጤውም ጥቅም ቢመጣላቸው የሚይዙት ሲኾኑ « (በሠራነው)፡- ለኛ ምሕረት ይደረግልናል» ይላሉ፡፡ በአላህ ላይ ከእውነት በቀር እንዳይናገሩ በእነርሱ ላይ የመጽሐፉ ቃል ኪዳን አልተያዘባቸውምን በእርሱ ውስጥ ያለውንም አላነበቡምን የመጨረሻይቱም አገር ለእነዚያ ጌታቸውን ለሚፈሩት በላጭ ናት፡፡ አታውቁምን'),
('7:170', 87, 'እነዚያም መጽሐፉን ጠብቀው የሚይዙ ሶላትንም በደንቡ የሰገዱ እኛ የመልካም ሠሪዎችን ዋጋ አናጠፋም፡፡'),
('7:171', 87, 'የጡርን ተራራ ነቅለን ከበላያቸው እንደ ጥላ ኾኖ በአነሳነውና እርሱም በነሱ ላይ ወዳቂ መኾኑን ባረጋገጡ ጊዜ (አስታውስ)፡፡ «የሰጠናችሁን በብርታት ያዙ፡፡ ትጠነቀቁም ዘንድ በውስጡ ያለውን ተገንዘቡ» (አልን)፡፡'),
('7:172', 87, 'ጌታህም ከአደም ልጆች ከጀርቦቻቸው ዘሮቻቸውን ባወጣና «ጌታችሁ አይደለሁምን» ሲል በነፍሶቻቸው ላይ ባስመሰከራቸው ጊዜ (የኾነውን አስታውስ)፡፡ «ጌታችን ነህ መሰከርን» አሉ፡፡ «በትንሣኤ ቀን ከዚህ (ኪዳን) ዘንጊዎች ነበርን እንዳትሉ፡፡»'),
('7:173', 87, 'ወይም «(ጣዖታትን) ያጋሩት ከእኛ በፊት የነበሩት አባቶቻችን ብቻ ናቸው፡፡ እኛም ከእነሱ በኋላ የኾን ዘሮች ነበርን፡፡ አጥፊዎቹ በሠሩት ታጠፋናለህን» እንዳትሉ (አስመሰከርናችሁ)፡፡'),
('7:174', 87, 'እንደዚሁም (እንዲያስቡ) እንዲመለሱም አንቀጾችን እናብራራለን፡፡'),
('7:175', 87, 'የዚያንም ተዓምራታችንን የሰጠነውንና ከእርሷ የወጣውን ሰይጣንም ያስከተለውን ከጠማሞቹም የኾነውን ሰው ወሬ በእነርሱ ላይ አንብብላቸው፡፡'),
('7:176', 87, 'በሻንም ኖሮ በእርሷ ከፍ ባደረግነው ነበር፡፡ እርሱ ግን ወደ ምድር ተዘነበለ፡፡ ፍላጎቱንም ተከተለ፡፡ ብጤውም ብታባርረው ምላሱን አውጥቶ የሚያለከልክ ወይም ብትተወው ምላሱን አውጥቶ የሚያለከልክ እንደ ኾነ ውሻ ነው፡፡ ይህ የእነዚያ በአንቀጾቻችን ያስተባበሉት ሕዝቦች ምሳሌ ነው፡፡ ያስተነትኑም ዘንድ ታሪኮችን ተርክላቸው፡፡'),
('7:177', 87, 'የእነዚያ በአንቀጾቻችን ያስተባበሉትና ነፍሶቻቸውን ይበድሉ የነበሩት ሰዎች ምሳሌ ከፋ!'),
('7:178', 87, 'አላህ የሚያቀናው ሰው ቅን እርሱ ነው፡፡ የሚያጠመውም ሰው እነዚያ ከሳሪዎቹ እነሱ ናቸው፡፡'),
('7:179', 87, 'ከጋኔንም ከሰዎችም ብዙዎችን ለገሀነም በእርግጥ ፈጠርን፡፡ ለእነርሱ በርሳቸው የማያውቁባቸው ልቦች አሏቸው፡፡ ለእነሱም በሳቸው የማያዩባቸው ዓይኖች አሉዋቸው፡፡ ለእነሱም በሳቸው የማይሰሙባቸው ጆሮዎች አሉዋቸው፡፡ እነዚያ እንደ እንስሳዎች ናቸው፡፡ ይልቁንም እነርሱ በጣም የተሳሳቱ ናቸው፡፡ እነዚያ ዘንጊዎቹ እነርሱ ናቸው፤'),
('7:180', 87, 'ለአላህም መልካም ስሞች አሉት፡፡ (ስትጸልዩ) በእርሷም ጥሩት፡፡ እነዚያንም ስሞቹን የሚያጣምሙትን ተውዋቸው፡፡ ይሠሩት የነበሩትን ነገር በእርግጥ ይምመነዳሉ፡፡'),
('7:181', 87, 'ከፈጠርናቸውም ሰዎች በእውነት የሚመሩ በእርሱም (ፍርድን) የሚያስተካክሉ ሕዝቦች አልሉ፡፡'),
('7:182', 87, 'እነዚያንም በአንቀጾቻችን ያስተባበሉትን ከማያውቁት ስፍራ ቀስ በቀስ (ምቾትን በመጨመር) እናዘነጋቸዋለን፡፡'),
('7:183', 87, 'ለእነርሱም ጊዜ እሰጣቸዋለሁ ጥበቤ ብርቱ ነውና፡፡'),
('7:184', 87, 'በነቢያቸው (በሙሐመድ) ምንም ዕብደት የሌለበት መኾኑን አያስተውሉምን እርሱ ግልጽ አስጠንቃቂ እንጅ ሌላ አይደለም፡፡'),
('7:185', 87, 'በሰማያትና በምድር ግዛት ውስጥ ከማንኛው ነገር አላህ በፈጠረውም ሁሉ የሞት ጊዜያቸውም በእርግጥ መቅረቡ የሚፈራ መኾኑን አያስተውሉምን ከእርሱም (ከቁርኣን) ወዲያ በየትኛው ንግግር ያምናሉ፡፡'),
('7:186', 87, 'አላህ የሚያጠመው ሰው ለእርሱ ምንም አቅኝ የለውም፡፡ በጥምመታቸውም ውስጥ እየዋለሉ ይተዋቸዋል፡፡'),
('7:187', 87, 'ከሰዓቲቱ መቼ እንደምትረጋ (እንደምትመጣ) ይጠይቁሃል፡፡ «ዕውቀቷ በጌታዬ ዘንድ ነው፡፡ በጊዜዋ እርሱ እንጂ ሌላ አይገልጣትም፡፡ በሰማያትና በምድርም ከበደች፡፡ በድንገት ቢኾን እንጂ አትመጣችሁም» በላቸው፡፡ ከእርሷ አጥብቀህ እንደ ተረዳህ አድርገው ይጠይቁሃል፡፡ «ዕውቀቷ አላህ ዘንድ ብቻ ነው፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም» በላቸው፡፡'),
('7:188', 87, '«አላህ የሻውን በስተቀር ለእራሴ ጥቅምንም ጉዳትንም ማምጣት አልችልም፡፡ ሩቅንም (ምስጢር) የማውቅ በነበርኩ ኖሮ ከመልካም ነገር ባበዛሁና ክፉም ነገር ባልነካኝ ነበር፡፡ እኔ ለሚያምኑ ሕዝቦች አስፈራሪና አብሳሪ እንጂ ሌላ አይደለሁም» በላቸው፡፡'),
('7:189', 87, 'እርሱ ያ ከአንዲት ነፍስ (ከአደም) የፈጠራችሁ ከእርሷም መቀናጆዋን ወደርሷ ይረካ ዘንድ ያደረገ ነው፡፡ በተገናኛትም ጊዜ ቀላልን እርግዝና አረገዘች፡፡ እርሱንም (ፅንሱን) ይዛው ኼደች፡፡ በከበደችም ጊዜ «ደግን ልጅ ብትሰጠን በእርግጥ ከአመስጋኞቹ እንኾናለን፤» ሲሉ ጌታቸውን አላህን ለመኑ፡፡'),
('7:190', 87, 'መልካም ልጅ በሰጣቸውም ጊዜ በሰጣቸው ልጅ (ስም) ለእርሱ ተጋሪዎችን አደረጉለት፡፡ አላህም ከሚያጋሩት ሁሉ ላቀ፡፡'),
('7:191', 87, 'ምንንም የማይፈጥሩትንና እነርሱም የሚፈጠሩትን (በአላህ) ያጋራሉን'),
('7:192', 87, 'ለእነርሱም መርዳትን የማይችሉትን ነፍሶቻቸውንም የማይረዱትን (ያጋራሉን)'),
('7:193', 87, '(ጣዖቶቹን) ወደ ቅን መንገድ ብትጠሩዋቸውም አይከተሉዋችሁም፡፡ ብትጠሩዋቸው ወይም እናንተ ዝምተኞችም ብትኾኑ በእናንተ ላይ እኩል ነው፡፡'),
('7:194', 87, 'እነዚያ ከአላህ ሌላ የምትገ³ቸው ብጤዎቻችሁ ተገዢዎች ናቸው፡፡ እውነተኞችም እንደኾናችሁ ጥሩዋቸውና ለእናንተ ይመልሱላችሁ፤ (መመለስ ግን አይችሉም)፡፡'),
('7:195', 87, 'ለእነርሱ በእርሳቸው የሚኼዱባቸው እግሮች አሉዋቸውን ወይስ ለእነሱ በርሳቸው የሚጨብጡባቸው እጆች አሉዋቸውን ወይስ ለእነሱ በእርሳቸው የሚያዩባቸው ዓይኖች አሉዋቸውን ወይስ ለእነሱ በእርሳቸው የሚሰሙባቸው ጆሮዎች አሉዋቸውን «ያጋራችኋቸውን ጥሩ ከዚያም ተተናኮሉኝ፡፡ ጊዜም አትስጡኝ፤ (አልፈራችሁም)» በላቸው፡፡'),
('7:196', 87, '«የእኔ ረዳቴ ያ መጽሐፉን (ቁርኣንን) ያወረደልኝ አላህ ነውና፤ እርሱም መልካም ሠሪዎችን ይረዳል» (በላቸው)፡፡'),
('7:197', 87, 'እነዚያም ከእርሱ በቀር የምትገ³ቸው ሊረÇችሁ አይችሉም፡፡ ነፍሶቻቸውንም አይረዱም፡፡'),
('7:198', 87, '«ወደ ቅንም መንገድ (እንዲመሩዋችሁ) ብትጠሩዋቸው አይሰሙም፤» (በላቸው)፡፡ እነርሱንም የማያዩ ሲኾኑ ወደ አንተ ሲመለከቱ ታያቸዋለህ፡፡'),
('7:199', 87, 'ገርን ጠባይ ያዝ፡፡ በመልካምም እዘዝ፡፡ ባለጌዎቹንም ተዋቸው፡፡'),
('7:200', 87, 'ከሰይጣንም (በኩል) ጉትጎታ ቢያገኝህ በአላህ ተጠበቅ፡፡ እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('7:201', 87, 'እነዚያ የተጠነቀቁት ከሰይጣን የኾነ ዘዋሪ በነካቸው ጊዜ (ጌታቸውን) ይገነዘባሉ፡፡ ወዲያውም እነሱ ተመልካቾች ይኾናሉ፡፡'),
('7:202', 87, 'ወንድሞቻቸውም ጥመትን ይጨምሩላቸዋል፤ ከዚያም (እነርሱ) አይገቱም፡፡'),
('7:203', 87, 'በተዓምርም ባልመጣሃቸው ጊዜ (በራስህ) «ለምን አትፈጥራትም» ይላሉ፡፡ ከጌታዬ ወደኔ የተወረደውን ብቻ እከተላለሁ፡፡ ይህ (ቁርኣን) ከጌታችሁ ሲኾን ለሚያምኑ ሕዝቦች መረጃዎችና መምሪያ እዝነትም ነው በላቸው፡፡'),
('7:204', 87, 'ቁርኣንም በተነበበ ጊዜ እርሱን አዳምጡ፡፡ ጸጥም በሉ፡፡ ይታዘንላችኋልና፡፡'),
('7:205', 87, 'ጌታህንም በምስጢር ተዋድቀህና ፈርተህ ከጩኸት በታችም በኾነ ቃል በጧትም በማታም አውሳው፡፡ ከዘንጊዎቹም አትኹን፡፡'),
('7:206', 87, 'እነዚያ እጌታህ ዘንድ ያሉት (መላእክት) እርሱን ከመገዛት አይኮሩም፡፡ ያወድሱታልም፡፡ ለእርሱም ብቻ ይሰግዳሉ፡፡'),
('8:1', 87, 'ከጦር ዘረፋ ገንዘቦች ይጠይቁሃል፡፡ «የዘረፋ ገንዘቦች የአላህና የመልክተኛው ናቸው፡፡» ስለዚህ አላህን ፍሩ፡፡ በመካከላችሁ ያለችውንም ኹኔታ አሳምሩ፡፡ አማኞችም እንደኾናችሁ አላህንና መልክተኛውን ታዘዙ በላቸው፡፡'),
('8:2', 87, 'ፍጹም ምእምናን እነዚያ አላህ በተወሳ ጊዜ ልቦቻቸው የሚፈሩት፣ በነሱም ላይ አንቀጾቻችን በተነበቡ ጊዜ እምነትን የሚጨምሩላቸው፣ በጌታቸውም ላይ ብቻ የሚመኩት ናቸው፡፡'),
('8:3', 87, 'እነዚያ ሶላትን ደንቡን አሟልተው የሚሰግዱ ከሰጠናቸውም ሲሳይ የሚለግሱ ናቸው፡፡'),
('8:4', 87, 'እነዚያ በእውነት አማኞች እነሱ ብቻ ናቸው፡፡ ለእነሱ በጌታቸው ዘንድ ደረጃዎች ምህረትና የከበረ ሲሳይም አላቸው፡፡'),
('8:5', 87, '(ይህ በዘረፋ ክፍያ የከፊሉ ሰው መጥላት) ከምእምናን ከፊሉ የጠሉ ሲኾኑ ጌታህ ከቤትህ በእውነት ላይ ኾነህ እንዳወጣህ ነው፡፡'),
('8:6', 87, 'እነርሱ እያዩ ወደሞት እንደሚነዱ ኾነው በእውነቱ ነገር (በመጋደል ግዴታነት) ከተገለጸላቸው በኋላ ይከራከሩሃል፡፡'),
('8:7', 87, 'አላህም ከሁለቱ ጭፍሮች አንደኛዋን እርሷ ለናንተ ናት ሲል ተስፋ በሰጣችሁ ጊዜ፣ የሀይል ባለቤት ያልኾነችውም (ነጋዴይቱ) ለናንተ ልትኾን በወደዳችሁ ጊዜ፣ አላህም በተስፋ ቃላቱ እውነትን ማረጋገጡን ሊገልጽና የከሓዲዎችንም መጨረሻ ሊቆርጥ በሻ ጊዜ (የኾነውን አስታውስ)፡፡'),
('8:8', 87, '(ይህንንም ያደረገው) አጋሪዎቹ ቢጠሉም እውነቱን ሊያረጋግጥ ክህደትንም ሊያጠፋ ነው፡፡'),
('8:9', 87, 'ከጌታችሁ ርዳታን በፈለጋችሁ ጊዜ «እኔ በሺህ መላእክት ተከታታዮች ሲኾኑ እረዳችኋለሁ» ሲል ለናንተ የተቀበላችሁን (አስታውሱ)፡፡'),
('8:10', 87, 'አላህም (ይኽንን ርዳታ) ለብስራትና ልቦቻችሁ በርሱ ሊረኩበት እንጂ ለሌላ አላደረገውም፡፡ ድልም መንሳት ከአላህ ዘንድ እንጂ ከሌላ አይደለም፡፡ አላህ አሸናፊ ጥበበኛ ነውና፡፡'),
('8:11', 87, 'ከእርሱ በኾነው ጸጥታ (በጦር ግንባር) በእንቅልፍ በሸፈናችሁና ውሃውንም በእርሱ ሊያጠራችሁ፣ የሰይጣንንም ጉትጎታ ከእናንተ ሊያስወግድላችሁ፣ ልቦቻችሁንም (በትዕግስት) ሊያጠነክርላችሁ፣ በእርሱም ጫማዎችን (በአሸዋው ላይ) ሊያደላድልላችሁ በእናንተ ላይ ከሰማይ ባወረደላችሁ ጊዜ (አስታውሱ)፡፡'),
('8:12', 87, 'ጌታህ ወደ መላእክቱ «»እኔ (በእርዳታዬ) ከእናንተ ጋር ነኝና እነዚያን ያመኑትን አጽናኑ፡፡ በእነዚያ በካዱት ልቦች ውስጥ ፍርሃትን በእርግጥ እጥላለሁ፡፡ ከአንገቶችም በላይ (ራሶችን) ምቱ፡፡ ከእነሱም የቅርንጫፎችን መለያልይ ሁሉ ምቱ፡፡ ሲል ያወረደውን (አስታውስ)፡፡'),
('8:13', 87, 'ይህ እነርሱ አላህንና መልክተኛውን ስለተቃወሙ ነው፡፡ አላህንና መልክተኛውንም የሚቃወም ሁሉ አላህ ቅጣቱ ብርቱ ነው፡፡'),
('8:14', 87, 'ይህ (ቅጣታችሁ ነው) ቅመሱትም፡፡ ለከሓዲዎችም የእሳት ቅጣት በእርግጥ አለባቸው፡፡'),
('8:15', 87, 'እናንተ ያመናችሁ ሆይ! እነዚያን የካዱትን ሰዎች (ለጦር) ሲጓዙ ባገኛችኋቸው ጊዜ ጀርባዎችን አታዙሩላቸው፡፡'),
('8:16', 87, 'ያን ጊዜም ለግድያ ለመዘዋወር ወይም ወደ ሠራዊት ለመቀላቀል ሳይኾን ጀርባውን የሚያዞርላቸው ሰው ከአላህ በኾነ ቁጣ በእርግጥ ተመለሰ፡፡ መኖሪያውም ገሀነም ናት፡፡ መመለሻይቱም ከፋች፡፡'),
('8:17', 87, 'አልገደላችኋቸውም ግን አላህ ገደላቸው፡፡ (ጭብጥን ዐፈር) በወረወርክም ጊዜ አንተ አልወረወርክም፡፡ ግን አላህ ወረወረ (ወደ ዓይኖቻቸው አደረሰው)፡፡ ለአማኞችም ከርሱ የኾነን መልካም ጸጋ ለመስጠት (ይህን አደረገ)፡፡ አላህ ሰሚ ዐዋቂ ነውና፡፡'),
('8:18', 87, 'ይህ (ዕውነት ነው)፡፡ አላህም የከሓዲዎችን ተንኮል አድካሚ ነው፡፡'),
('8:19', 87, 'ፍትሕን (ፍርድን) ብትጠይቁ ፍትሑ በእርግጥ መጥቶላችኋል፡፡ (ክህደትንና መዋጋትን) ብትከለከሉም እርሱ ለእናንተ የተሻለ ነው፡፡ (ወደ መጋደል) ብትመለሱም እንመለሳለን፡፡ ሰራዊታችሁም ብትበዛም እንኳ ከናንተ ምንም አትጠቅማችሁም፡፡ አላህም ከምእምናን ጋር ነው፡፡'),
('8:20', 87, 'እናንተ ያመናችሁ ሆይ! አላህንና መልክተኛውን ታዘዙ፡፡ እናንተም የምትሰሙ ስትኾኑ ከርሱ አትሽሹ፡፡'),
('8:21', 87, 'እንደነዚያም እነሱ የማይሰሙ ሲኾኑ ሰማን እንዳሉት አትሁኑ፡፡'),
('8:22', 87, 'ከተንቀሳቃሾች ሁሉ አላህ ዘንድ መጥፎ ተንኮለኞች እነዚያ የማያውቁት፣ ደንቆሮዎቹ፣ ዲዳዎቹ ናቸው፡፡'),
('8:23', 87, 'በውስጣቸውም ደግ መኖሩን አላህ ባወቀ ኖሮ (የመረዳትን መስማት) ባሰማቸው ነበር፡፡ (ደግ የሌለባቸው መኾኑን ሲያውቅ) ባሰማቸውም ኖሮ እነሱ እውነትን የተው ኾነው በሸሹ ነበር፡፡'),
('8:24', 87, 'እናንተ ያመናችሁ ሆይ! (መልክተኛው) ሕያው ወደሚያደርጋችሁ እምነት በጠራችሁ ጊዜ ለአላህና ለመልክተኛው ታዘዙ፡፡ አላህም በሰውየውና በልቡ መካከል የሚጋርድ መኾኑን ወደርሱም የምትሰበሰቡ መኾናችሁን እወቁ፡፡'),
('8:25', 87, 'ከናንተም ውስጥ እነዚያን የበደሉትን ብቻ ለይታ የማትነካን ፈተና ተጠንቀቁ፡፡ አላህም ቅጣቱ ብርቱ መኾኑን እወቁ፡፡'),
('8:26', 87, 'እናንተም በምድር ላይ የተናቃችሁ ጥቂቶች ኾናችሁ ሳላችሁ ሰዎች ሊነጥቁዋችሁ የምትፈሩ ስትኾኑ ያስጠጋችሁን በእርዳታውም ያበረታችሁን ከመልካሞች ሲሳዮችም ታመሰግኑ ዘንድ የሰጣችሁን አስታውሱ፡፡'),
('8:27', 87, 'እናንተ ያመናችሁ ሆይ! አላህንና መልክተኛውን አትክዱ፡፡ አደራዎቻችሁንም እናንተ እያወቃችሁ አትክዱ፡፡'),
('8:28', 87, 'ገንዘቦቻችሁና ልጆቻችሁም ፈተና ብቻ መኾናቸውንና አላህም እሱ ዘንድ ታላቅ ምንዳ ያለው መኾኑን እወቁ፡፡'),
('8:29', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ብትፈሩ የእውነት መለያን ብርሃን ያደርግላችኋል፡፡ ክፉ ሥራዎቻችሁንም ከእናንተ ላይ ያብስላችኋል፡፡ ለእናንተም ይምራችኋል፡፡ አላህም የታላቅ ችሮታ ባለቤት ነው፡፡'),
('8:30', 87, 'እነዚያም የካዱት ሊያስሩህ ወይም ሊገድሉህ ወይም (ከመካ) ሊያወጡህ ባንተ ላይ በመከሩብህ ጊዜ (አስታውስ)፡፡ ይመክራሉም አላህም ተንኮላቸውን ይመልስባቸዋል፡፡ አላህም ከመካሪዎቹ ሁሉ በላይ ነው፡፡'),
('8:31', 87, 'አንቀጾቻችንም በነሱ ላይ በተነበቡ ጊዜ «በእርግጥ ሰምተናል፤ በሻን ኖሮ የዚህን ብጤ ባልን ነበር፤ ይህ የመጀመሪያዎቹ ሰዎች ጽሑፍ ተረቶች እንጂ ሌላ አይደለም» ይላሉ፡፡'),
('8:32', 87, '«ጌታችን ሆይ! ይህ እርሱ ካንተ ዘንድ (የተወረደ) እውነት እንደ ኾነ በኛ ላይ ከሰማይ ድንጋዮችን አዝንብብን ወይም አሳማሚ ቅጣትን አምጣብን» ባሉም ጊዜ (አስታውስ)'),
('8:33', 87, 'አላህም አንተ በውስጣቸው እያለህ (ድንጋይ በማዝነብና ባሳማሚ ቅጣት) የሚቀጣቸው አይደለም፡፡ አላህም እነሱ ምህረትን የሚለምኑ ሲኾኑ የሚቀጣቸው አይደለም፡፡'),
('8:34', 87, 'እነሱ ከተከበረው መስጊድ የሚከለክሉ ሲኾኑም አላህ (በሰይፍ) የማይቀጣቸው ለነሱ ምን አልላቸው (የቤቱ) ጠባቂዎችም አልነበሩም፡፡ ጠባቂዎቹ (ክሕደትን) ተጠንቃቂዎቹ እንጂ ሌሎቹ አይደሉም፡፡ ግን አብዛኛዎቻቸው አያውቁም፡፡'),
('8:35', 87, 'በቤቱ ዘንድም (በካዕባ) ስግደታቸው ማፏጨትና ማጨብጨብ እንጂ ሌላ አልነበረም፡፡ ትክዱት በነበራችሁትም ነገር ቅጣትን ቅመሱ (ይባላሉ)፡፡'),
('8:36', 87, 'እነዚያ የካዱት ከአላህ መንገድ ሊከለክሉ ገንዘቦቻቸውን ያወጣሉ፡፡ በእርግጥም ያወጡዋታል፡፡ ከዚያም በእነሱ ላይ ጸጸት ትኾንባቸዋለች፡፡ ከዚያም ይሸነፋሉ፡፡ እነዚያም የካዱት ወደ ገሀነም ይሰበሰባሉ፡፡'),
('8:37', 87, 'አላህ መጥፎውን ከመልካሙ ሊለይ መጥፎውንም ከፊሉን በከፊሉ ላይ ሊያደርግና ባንድ ላይ ሊያነባብረው በገሀነም ውስጥም ሊያደርገው (ይሰበሰባሉ)፡፡ እነዚያ እነሱ ከሳሪዎቹ ናቸው፡፡'),
('8:38', 87, 'ለነዚያ ለካዱት በላቸው፡- ቢከለከሉ ለእነሱ በእርግጥ ያለፈውን (ሥራ) ምሕረት ይደረግላቸዋል፡፡ (ወደ መጋደል) ቢመለሱም (እናጠፋቸዋለን)፡፡ የቀድሞዎቹ ሕዝቦች ልማድ በእርግጥ አልፋለችና፡፡'),
('8:39', 87, 'ሁከትም እስከማትገኝ ሃይማኖትም ሁሉ ለአላህ ብቻ እስከሚኾን ድረስ ተጋደሏቸው፡፡ ቢከለከሉም አላህ የሚሠሩትን ሁሉ ተመልካች ነው፡፡'),
('8:40', 87, '(ከእምነት) ቢዞሩም አላህ ረዳታችሁ መኾኑን ዕወቁ፡፡ (እርሱ) ምን ያምር ጠባቂ! ምን ያምርም ረዳት!'),
('8:41', 87, 'ከማንኛውም ነገር በጦር (ከከሓዲዎች) የዘረፋችሁትም አንድ አምስተኛው ለአላህና ለመልክተኛው፣ (ለነቢዩ) የዝምድና ባለቤቶችም፣ ለየቲሞችም፣ ለምስኪኖችም፣ ለመንገደኛም የተገባ መኾኑን ዕውቁ፣ በአላህና በዚያም እውነትና ውሸት በተለየበት ቀን ሁለቱ ጭፍሮች በተገናኙበት (በበድር) ቀን በባሪያችን ላይ ባወረድነው የምታምኑ እንደኾናችሁ (ይህንን ዕወቁ)፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('8:42', 87, 'እናንተ በቅርቢቱ ዳርቻ ኾናችሁ እነርሱም በሩቂቱ ዳርቻ ኾነው የነጋዴዎቹም ጭፍራ ከናንተ በታች ሲኾኑ በሰፈራችሁ ጊዜ (ያደረግንላችሁን አስታውሱ)፡፡ በተቃጠራችሁም ኖሮ በቀጠሮው በተለያያችሁ ነበር፡፡ ግን አላህ ሊሠራው የሚገባውን ነገር ሊፈጽም የሚጠፋ ሰው ከአስረጅ በኋላ እንዲጠፋ ሕያው የሚኾንም ሰው ከአስረጅ በኋላ ሕያው እንዲኾን (ያለቀጠሮ አጋጠማችሁ)፡፡ አላህም በእርግጥ ሰሚ ዐዋቂ ነው፡፡'),
('8:43', 87, 'አላህ በሕልምህ እነሱን ጥቂት አድርጎ ባሳየህ ጊዜ (አስታውስ)፡፡ እነሱን ብዙ አድርጎ ባሳየህም ኖሮ በፈራችሁና በነገሩ በተጨቃጨቃችሁ ነበር፡፡ ግን አላህ አዳናችሁ፡፡ እርሱ በደረቶች ውስጥ ያለን ሁሉ ዐዋቂ ነውና፡፡'),
('8:44', 87, 'አላህም ሊሠራው የሚገባን ነገር ይፈጽም ዘንድ በተጋጠማችሁ ጊዜ እነርሱን በዓይኖቻችሁ ጥቂት አድርጎ ያሳያችሁንና በዓይኖቻቸውም ላይ ያሳነሳችሁን (አስታውሱ)፡፡ ነገሮቹም ሁሉ ወደ አላህ ብቻ ይመለሳሉ፡፡'),
('8:45', 87, 'እናንተ ያመናችሁ ሆይ! ሰራዊትን በገጠማችሁ ጊዜ እርጉ፤ (መክቱ)፡፡ አላህንም በብዙ አውሱ፤ በእርግጥ ትድናላችሁና፡፡'),
('8:46', 87, 'አላህንና መልክተኛውንም ታዘዙ፡፡ አትጨቃጨቁም፡፡ ትፈራላችሁና ኃይላችሁም ትኼዳለችና፡፡ ታገሱም፤ አላህ ከትዕግስተኞች ጋር ነውና፡፡'),
('8:47', 87, 'እንደነዚያ ለትዕቢትና ለሰዎች ይዩልኝ ሲሉ ከአላህም መንገድ ለማገድ ከአገራቸው እንደወጡት አትኹኑ፡፡ አላህም በሚሠሩት ሁሉ (በዕውቀቱ) ከባቢ ነው፡፡'),
('8:48', 87, 'ሰይጣንም ሥራዎቻቸውን ለእነርሱ ባሳመረላቸውና «ዛሬ ለእናንተ ከሰዎች አሸናፊ የላችሁም እኔም ለእናንተ ረዳት ነኝ» ባለ ጊዜም (አስታውስ)፡፡ ሁለቱ ጭፍሮችም በተያዩ ጊዜ፤ ወደኋላው አፈገፈገ፡፡ «እኔ ከናንተ ንጹህ ነኝ፡፡ እኔ እናንተ የማታዩትን አያለሁ፡፡ እኔ አላህን እፈራለሁ፡፡ አላህም ቅጣተ ብርቱ ነው» አላቸውም፡፡'),
('8:49', 87, 'መናፍቃንና እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው «እነዚህን (ሙስሊሞች) ሃይማኖታቸው አታለላቸው» ባሉ ጊዜ (አስታውስ)፡፡ በአላህም ላይ የሚጠጋ (ያሸንፋል)፤ አላህ አሸናፊ ጥበበኛ ነውና፡፡'),
('8:50', 87, 'እነዚያንም የካዱትን መላእክት ፊቶቻቸውንና ጀርባዎቻቸውን እየመቱ «የቃጠሎንም ስቃይ ቅመሱ» (እያሉ) በሚገድሏቸው ጊዜ ብታይ ኖሮ (አስደንጋጭን ነገር ታይ ነበር)፡፡'),
('8:51', 87, 'ይህ እጆቻችሁ ባስቀደሙት ምክንያት አላህም ለባሮቹ በዳይ ባለመኾኑ ነው (ይባላሉ)፡፡'),
('8:52', 87, '(የነዚያ ልማድ) እንደ ፈርዖን ቤተሰብና እንደነዚያም ከእነሱ በፊት እንደ ነበሩት ልማድ ነው፡፡ በአላህ አንቀጾች ካዱ፤ አላህም በኃጢኣቶቻቸው ያዛቸው፤ አላህ ኀይለኛ ቅጣተ ብርቱ ነውና፡፡'),
('8:53', 87, 'ይህ (ቅጣት) አላህ በሕዝቦች ላይ የለገሰውን ጸጋ በነፍሶቻቸው ያለውን ነገር እስከሚለውጡ ድረስ የማይለውጥ በመኾኑ ምክንያት ነው፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('8:54', 87, 'እንደ ፈርዖን ቤተሰቦችና እንደእነዚያም ከእነሱ በፊት እንደ ነበሩት ልማድ (እስከሚለውጡ ድረስ አይለውጥባቸውም)፡፡ በጌታቸው ተአምራት አስተባበሉና በኃጢኣቶቻቸው አጠፋናቸው፡፡ የፈርዖንንም ቤተሰቦች አሰጠምናቸው፡፡ ሁሉም በዳዮች ነበሩም፡፡'),
('8:55', 87, 'ከሚንቀሳቀሱ እንስሳዎች ሁሉ አላህ ዘንድ ይበልጥ ክፉዎቹ እነዚያ ዘወትር የካዱት ናቸው፡፡ ስለዚህ እነሱ አያምኑም፡፡'),
('8:56', 87, 'እነዚያ ከነሱ ቃል ኪዳን የያዝክባቸው ከዚያም በየጊዜው ቃል ኪዳናቸውን የሚያፈርሱ ናቸው፡፡ እነሱም አይጠነቀቁም፡፡'),
('8:57', 87, 'በጦርም ላይ ብታገኛቸው በእነርሱ ቅጣት ምክንያት (ሌሎቹ ከሓዲዎች) ይገሰጹ ዘንድ ከኋላቸው ያሉትን በትንባቸው፡፡'),
('8:58', 87, 'ከሕዝቦችም ክዳትን ብትፈራ (የኪዳኑን መፍረስ በማወቅ) በመተካከል ላይ ኾናችሁ ኪዳናቸውን ወደነሱ ጣልላቸው፡፡ አላህ ከዳተኞችን አይወድምና፡፡'),
('8:59', 87, 'እነዚያም የካዱት ከአላህ ቅጣት ያመለጡ መኾናቸውን አያስቡ፡፡ እነሱ አያቅቱምና፡፡'),
('8:60', 87, 'ለእነሱም ከማንኛውም ኃይልና ከታጀቡ ፈረሶችም የቻላችሁትን ሁሉ በእርሱ የአላህን ጠላትና ጠላታችሁን ሌሎችንም ከእነርሱ በቀር ያሉትን የማታውቋቸውን አላህ የሚያውቃቸውን (መናፍቃን) የምታሸብሩበት ስትኾኑ አዘጋጁላቸው፡፡ ከማንኛውም ነገር በአላህ መንገድ የምትለግሱትም ምንዳው ወደናንተ በሙሉ ይሰጣል፡፡ እናንተም አትበደሉም፡፡'),
('8:61', 87, 'ወደ ዕርቅም ቢያዘነብሉ ወደ እርሷ አዘንብል፡፡ በአላህም ላይ ተጠጋ፡፡ እነሆ እርሱ ሰሚ ዐዋቂ ነውና፡፡'),
('8:62', 87, 'ሊያታልሉህም ቢፈልጉ አላህ በቂህ ነው፡፡ እርሱ ያ በእርዳታውና በምእምናን ያበረታህ ነው፡፡'),
('8:63', 87, 'በልቦቻቸውም መካከል ያስማማ ነው፡፡ በምድር ያለውን ሁሉ (ሀብት) በለገስክ ኖሮ በልቦቻቸው መካከል ባላስማማህ ነበር፡፡ ግን አላህ በመካከላቸው አስማማ፡፡ እርሱ አሸናፊ ጥበበኛ ነውና፡፡'),
('8:64', 87, 'አንተ ነቢዩ ሆይ! አላህ በቂህ ነው፡፡ ለተከተሉህም ምእምናን (አላህ በቂያቸው ነው)፡፡'),
('8:65', 87, 'አንተ ነቢዩ ሆይ! ምእምናንን በመዋጋት ላይ አደፋፍራቸው፡፡ ከእናንተ ውስጥ ሃያ ታጋሾች ኖሩ ሁለት መቶን ያሸንፋሉ፡፡ ከእናንተም መቶ ቢኖሩ ከእነዚያ ከካዱት እነሱ የማያውቁ ሕዝቦች ስለኾኑ ሺህን ያሸንፋሉ፤'),
('8:66', 87, 'አሁን አላህ ከእናንተ ላይ አቀለለላችሁ፡፡ በእናንተ ውስጥም ድክመት መኖሩን ዐወቀ፡፡ ስለዚህ ከእናንተ መቶ ታጋሾች ቢኖሩ ሁለት መቶን ያሸንፋሉ፡፡ ከእናንተም ሺህ ቢኖሩ በአላህ ፈቃድ ሁለት ሺህን ያሸንፋሉ፡፡ አላህም ከታጋሾቹ ጋር ነው፡፡'),
('8:67', 87, 'ለነቢይ በምድር ላይ እስቲያደክም ድረስ ለእርሱ ምርኮኞች ሊኖሩት አይገባም፡፡ የቅርቢቱን ዓለም ጠፊ ጥቅም ትፈልጋላችሁ፡፡ አላህም መጨረሻይቱን ይሻል፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('8:68', 87, 'ከአላህ ያለፈ ፍርድ ባልነበረ ኖሮ በወሰዳችሁት (ቤዛ) ከባድ ቅጣት በነካችሁ ነበር፡፡'),
('8:69', 87, '(ከጠላት) ከዘረፋችሁትም (ሀብት) የተፈቀደ መልካም ሲኾን ብሉ፡፡ አላህንም ፍሩ፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('8:70', 87, 'አንተ ነቢዩ ሆይ! ከምርኮኞች በእጆቻችሁ ላሉት በላቸው፡- «አላህ በልቦቻችሁ ውስጥ በጎን ነገር (እምነትን) ቢያውቅ ከእናንተ ከተወሰደባችሁ የተሻለን ይሰጣችኋል፡፡ ለእናንተም ይምራችኋል፡፡ አላህም መሓሪ አዛኝ ነው፡፡»'),
('8:71', 87, 'ሊከዱህም ቢፈልጉ ከዚህ በፊት አላህን በእርግጥ ከድተዋል፡፡ ከነሱም አስመችቶሃል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('8:72', 87, 'እነዚያ ያመኑና የተሰደዱ፡፡ በአላህም መንገድ ላይ በገንዘቦቻቸውና በነፍሶቻቸው የታገሉ፡፡ እነዚያም (ስደተኞቹን) ያስጠጉና የረዱ፡፡ እነዚያ ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው፡፡ እነዚያም ያመኑና ያልተሰደዱ እስከሚሰደዱ ድረስ ከነሱ ምንም ዝምድና የላችሁም፡፡ በሃይማኖትም እርዳታን ቢፈልጉባችሁ በእናንተና በነሱ መካከል ቃል ኪዳን ባላችሁ ሕዝቦች ላይ ካልኾነ በስተቀር በናንተ ላይ መርዳት አለባችሁ፡፡ አላህም የምትሠሩትን ሁሉ ተመልካች ነው፡፡'),
('8:73', 87, 'እነዚያም የካዱት ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው፡፡ (ከምእምናን መረዳዳትን ከከሓዲያን መቆራረጥን) ባትሠሩት በምድር ላይ ሁከትና ታላቅ ጥፋት ይኾናል፡፡'),
('8:74', 87, 'እነዚያም ያመኑና የተሰደዱ በአላህም መንገድ ላይ የታገሉ፣ እነዚያም ያስጠጉና የረዱ እነዚያ እነሱ በእውነት አማኞች ናቸው፡፡ ለእነሱም ምሕረትና የከበረ ሲሳይ አላቸው፡፡'),
('8:75', 87, 'እነዚያም በኋላ ያመኑና የተሰደዱ፣ ከእናንተም ጋር ኾነው የታገሉ እነዚያ ከናንተው ናቸው፡፡ የዝምድናዎች ባለቤቶችም በአላህ መጽሐፍ ከፊሎቻቸው በከፊሉ (መውረስ) የተገቡ ናቸው፡፡ አላህ በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('9:1', 87, '(ይህች) ከአላህና ከመልክተኛው ወደእነዚያ ቃል ኪዳን ወደ ተጋባችኋቸው አጋሪዎች የምትደርስ ንጽሕና ናት፡፡'),
('9:2', 87, 'በምድር ላይም አራት ወሮችን (ጸጥተኞች ስትኾኑ) ኺዱ፡፡ እናንተም ከአላህ (ቅጣት) የማታመልጡ መኾናችሁንና አላህም ከሓዲዎችን አዋራጅ መኾኑን ዕወቁ፤ (በሏቸው)፡፡'),
('9:3', 87, '(ይህ) ከአላህና ከመልክተኛው በታላቁ ሐጅ ቀን የወጣ አላህ ከአጋሪዎቹ ንጹሕ ነው መልክተኛውም (እንደዚሁ)፡፡ (ከክህደት) ብትጸጸቱም እርሱ ለእናንተ በላጭ ነው፡፡ (ከእምነት) ብትሸሹም እናንተ አላህን የማታቅቱት መኾናችሁን ዕወቁ በማለት ወደ ሰዎች የሚደርስ ማስታወቂያ ነው፡፡ እነዚያን የካዱትንም በአሳማሚ ቅጣት አብስራቸው፡፡'),
('9:4', 87, 'ከአጋሪዎቹ እነዚያ ቃል ኪዳን የተጋባችኋቸውና ከዚያም ምንም ያላጎደሉባችሁ በናንተ ላይም አንድንም ያልረዱባችሁ ሲቀሩ፤ (እነዚህን) ቃል ኪዳናቸውን እስከጊዜያታቸው (መጨረሻ) ሙሉላቸው፡፡ አላህ ጥንቁቆችን ይወዳልና፡፡'),
('9:5', 87, 'የተከበሩትም ወሮች ባለቁ ጊዜ አጋሪዎቹን በአገኛችሁባቸው ስፍራ ግደሉዋቸው፡፡ ያዙዋቸውም፣ ክበቡዋቸውም፣ ለእነሱም (መጠባበቅ) በየመንገዱ ተቀመጡ፡፡ ቢጸጸቱም፣ ሶላትንም በደንቡ ቢሰግዱ፣ ግዴታ ምጽዋትንም ቢሰጡ መንገዳቸውን ልቀቁላቸው፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('9:6', 87, 'ከአጋሪዎችም አንዱ ጥገኝነትን ቢጠይቅ የአላህን ቃል ይሰማ ዘንድ አስጠጋው፡፡ ከዚያም ወደ መጠበቂያው ስፍራ አድርሰው፡፡ ይህ እነሱ የማያውቁ ሕዝቦች በመኾናቸው ነው፡፡'),
('9:7', 87, 'ለአጋሪዎቹ አላህ ዘንድና እመልክተኛው ዘንድ ቃል ኪዳን እንዴት ይኖራቸዋል እነዚያ በተከበረው መስጊድ ዘንድ ቃል ኪዳን የተጋባችኋቸው ብቻ ሲቀሩ፡፡ (እነዚህ) በቃል ኪዳናቸው ለእናንተ ቀጥ እስካሉላችሁ ድረስ ለነርሱም ቀጥ በሉላቸው፡፡ አላህ ጥንቁቆችን ይወዳልና፡፡'),
('9:8', 87, 'በእናንተ ላይ ቢያይሉም በእናንተ ውስጥ ዝምድናንና ቃል ኪዳንን የማይጠብቁ ሲኾኑ እንዴት (ቃል ኪዳን ይኖራቸዋል)፡፡ በአፎቻቸው ያስወድዷችኋል፡፡ ልቦቻቸውም እንቢ ይላሉ፡፡ አብዛኞቻቸውም አመጸኞች ናቸው፡፡'),
('9:9', 87, 'በአላህ አንቀጾች ጥቂትን ዋጋ ገዙ፡፡ ከመንገዱም አገዱ፡፡ እነርሱ ይሠሩት የነበሩት ሥራ ከፋ!'),
('9:10', 87, 'በምእምን ነገር ዝምድናንም ኪዳንንም አይጠብቁም፤ እነዚያም እነሱ ወሰን አላፊዎች ናቸው፡፡'),
('9:11', 87, 'ቢጸጸቱም፣ ሶላትንም ቢሰግዱ፣ ዘካንም ቢሰጡ የሃይማኖት ወንድሞቻችሁ ናቸው፡፡ ለሚያውቁ ሕዝቦችም አንቀጾችን እናብራራለን፡፡'),
('9:12', 87, 'ከቃል ኪዳናቸው በኋላ መሓላዎቻቸውን ቢያፈርሱ፣ ሃይማኖታችሁንም ቢያነውሩ፣ የክህደት መሪዎችን (ከክህደት) ይከለከሉ ዘንድ ተዋጉዋቸው፡፡ እነርሱ ቃል ኪዳን የላቸውምና፡፡'),
('9:13', 87, 'መሓላዎቻቸውን ያፈረሱትን መልክተኛውንም ለማውጣት ያሰቡትን ሕዝቦች እነሱ ለመጀመሪያ ጊዜ የጀመሩዋችሁ ሲኾኑ ለምን አትዋጉዋቸውም ትፈሩዋቸዋላችሁን ምእምናን እንደ ኾናችሁም አላህ ይበልጥ ልትፈሩት የተገባው ነው፡፡'),
('9:14', 87, 'ተጋደሉዋቸው፡፡ አላህ በእጆቻችሁ ያሰቃያቸዋል፡፡ ያዋርዳቸዋልም፡፡ በእነሱም ላይ ይረዳችኋል፡፡ የምእምናን ሕዝቦችንም ልቦች ያሽራል፡፡'),
('9:15', 87, 'የልቦቻችሁንም ቁጭት ያስወግዳል፡፡ አላህም ከሚሻው ሰው ላይ ጸጸትን ይቀበላል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('9:16', 87, 'እነዚያን ከእናንተ ውስጥ የታገሉትንና ከአላህም ከመልክተኛውም ከምእመናንም ሌላ ምስጢረኛ ወዳጅ ያልያዙትን አላህ ሳይገልጽ ልትተው ታስባላችሁን አላህም በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('9:17', 87, 'ለከሓዲዎች በነፍሶቻቸው ላይ በክህደት የሚመሰክሩ ሲኾኑ የአላህን መስጊዶች ሊሠሩ አይገባቸውም፡፡ እነዚያ ሥራዎቻቸው ተበላሹ፡፡ እነሱም በእሳት ውስጥ ዘውታሪዎች ናቸው፡፡'),
('9:18', 87, 'የአላህን መስጊዶች የሚሠራው በአላህና በመጨረሻው ቀን ያመነ፣ ሶላትንም በደንቡ የሰገደ፣ ግዴታ ምጽዋትንም የሰጠ ከአላህም ሌላ (ማንንም) ያልፈራ ሰው ብቻ ነው፡፡ እነዚያም ከተመሩት ጭምር መኾናቸው ተረጋገጠ፡፡'),
('9:19', 87, 'ካዕባን ጎብኝዎችን ማጠጣትንና የተከበረውን መስጊድ መሥራትን በአላህና በመጨረሻው ቀን እንዳመነና በአላህ መንገድ እንደታገለ ሰው (እምነትና ትግል) አደረጋችሁን አላህ ዘንድ አይተካከሉም፡፡ አላህም በዳዮች ሕዝቦችን አይመራም፡፡'),
('9:20', 87, 'እነዚያ ያመኑት፣ ከአገራቸውም የተሰደዱት፣ በገንዘቦቻቸውና በነፍሶቻቸውም በአላህ መንገድ ላይ የታገሉት አላህ ዘንድ በደረጃ በጣም የላቁ ናቸው፡፡ እነዚያም እነሱ ፍላጎታቸውን ያገኙ ናቸው፡፡'),
('9:21', 87, 'ጌታቸው ከርሱ በኾነው እዝነትና ውዴታ በገነቶችም ለነሱ በውስጥዋ የማያቋርጥ መጠቀሚያ ያለባት ስትኾን ያበስራቸዋል፡፡'),
('9:22', 87, 'በውስጧ ዘላለም ዘውታሪዎች ሲኾኑ (ያበስራቸዋል)፡፡ አላህ እርሱ ዘንድ ታላቅ ምንዳ አለና፡፡'),
('9:23', 87, 'እናንተ ያመናችሁ ሆይ! አባቶቻችሁና ወንድሞቻችሁ ክህደትን ከእምነት አብልጠው ቢወዱ ወዳጆች አድርጋችሁ አትያዙዋቸው፡፡ ከእናንተም ውስጥ ወዳጅ የሚያደርጋቸው እነዚያ እነሱ በዳዮች ናቸው፤'),
('9:24', 87, '«አባቶቻችሁና ወንዶች ልጆቻችሁ፣ ወንድሞቻችሁም፣ ሚስቶቻችሁም፣ ዘመዶቻችሁም፣ የሰበሰባችኋቸው ሀብቶችም፣ መክሰሩዋን የምትፈሩዋት ንግድም፣ የምትወዷቸው መኖሪያዎችም እናንተ ዘንድ ከአላህና ከመልክተኛው በርሱ መንገድም ከመታገል ይበልጥ የተወደዱ እንደኾኑ አላህ ትእዛዙን እስከሚያመጣ ድረስ ተጠባበቁ» በላቸው፡፡ አላህም አመጸኞች ሕዝቦችን አይመራም፡፡'),
('9:25', 87, 'አላህም በብዙ ስፍራዎች በእርግጥ ረዳችሁ፤ የሑነይንም ቀን ብዛታችሁ በአስደነቀቻችሁና ከእናንተም ምንም ባልጠቀመቻችሁ ጊዜ ምድርም ከስፋቷ ጋር በጠበበቻችሁና ከዚያም ተሸናፊዎች ኾናችሁ በዞራችሁ ጊዜ (ረዳችሁ)፡፡'),
('9:26', 87, 'ከዚያም አላህ እርጋታውን በመልክተኛውና በምእምናኖቹ ላይ አወረደ፡፡ ያላያችኋቸውንም ሰራዊት አወረደ፡፡ እነዚያን የካዱትንም በመገደልና በመማረክ አሰቃየ፡፡ ይህም የከሓዲያን ፍዳ ነው፡፡'),
('9:27', 87, 'ከዚያም ከዚህ በኋላ አላህ በሚሻው ሰው ላይ ጸጸትን ይቀበላል፡፡ አላህም እጅግ መሓሪ አዛኝ ነው፡፡'),
('9:28', 87, 'እናንተ ያመናችሁ ሆይ! አጋሪዎች እርኩሶች ብቻ ናቸው፡፡ ከዚህም ዓመታቸው በኋላ የተከበረውን መስጊድ አይቅረቡ፡፡ ድኽነትንም ብትፈሩ አላህ ቢሻ ከችሮታው በእርግጥ ያከብራችኋል፡፡ አላህ ዐዋቂ ጥበበኛ ነውና፡፡'),
('9:29', 87, 'ከእነዚያ መጽሐፍን ከተሰጡት ሰዎች እነዚያን በአላህና በመጨረሻው ቀን የማያምኑትን፣ አላህና መልክተኛው እርም ያደረጉትንም እርም የማያደርጉትንና እውነተኛውንም ሃይማኖት የማይቀበሉትን እነርሱ የተዋረዱ ኾነው ግብርን በእጆቻቸው እስከሚሰጡ ድረስ ተዋጉዋቸው፡፡'),
('9:30', 87, 'አይሁድ ዑዘይር የአላህ ልጅ ነው አለች፡፡ ክርስቲያኖችም አልመሲሕ የአላህ ልጅ ነው አሉ፡፡ ይህ በአፎቻቸው (የሚናገሩት) ቃላቸው ነው፡፡ የእነዚያን ከነሱ በፊት የካዱትን ሰዎች ቃል ያመሳስላሉ፡፡ አላህ ያጥፋቸው፡፡ (ከእውነት) እንዴት ይመለሳሉ!'),
('9:31', 87, 'ከእርሱ በቀር ሌላ አምላክ የሌለውን አንድን አምላክ ሊገዙ እንጂ ያልታዘዙ ሲኾኑ ሊቃውንቶቻቸውንና መነኮሳታቸውን፣ የመርየምን ልጅ አልመሲሕንም ከአላህ ሌላ አማልክት አድርገው ያዙ፡፡ ከሚያጋሩት ሁሉ የጠራ ነው፡፡'),
('9:32', 87, 'የአላህን ብርሃን በአፎቻቸው ለማጥፋት ይፈልጋሉ፡፡ አላህም ከሓዲዎች ቢጠሉም እንኳ ብርሃኑን መሙላትን እንጅ ሌላን አይሻም፡፡'),
('9:33', 87, 'እርሱ ያ አጋሪዎቹ ቢጠሉም መልክተኛውን (ሙሐመድን) በቅን መንገድና በእውነተኛ ሃይማኖት ላይ ከሃይማኖት ሁሉ በላይ ይፋ ያደርገው ዘንድ የላከው ነው፡፡'),
('9:34', 87, 'እናንተ ያመናችሁ ሆይ! ከሊቃውንትና ከመነኮሳት ብዙዎቹ የሰዎችን ገንዘቦች በውሸት በእርግጥ ይበላሉ፡፡ ከአላህም መንገድ ያግዳሉ፡፡ እነዚያንም ወርቅንና ብርን የሚያደልቡትን በአላህም መንገድ ላይ የማያወጧትን በአሳማሚ ቅጣት አብስራቸው፡፡'),
('9:35', 87, 'በርሷ ላይ በገሀነም እሳት ውስጥ በሚጋልባትና ግንባሮቻቸውም፣ ጎኖቻቸውም፣ ጀርባዎቻቸውም በርሷ በሚተኮሱ ቀን (አሳማሚ በኾነ ቅጣት አብስራቸው)፡፡ ይህ ለነፍሶቻችሁ ያደለባችሁት ነው፡፡ ታደልቡት የነበራችሁትንም ቅመሱ (ይባላሉ)፡፡'),
('9:36', 87, 'የወሮች ቁጥር አላህ ዘንድ በአላህ መጽሐፍ ውስጥ ሰማያትንና ምድርን በፈጠረበት ቀን ዐሥራ ሁለት ወር ነው፡፡ ከእነሱ አራቱ የተከበሩ ናቸው፡፡ ይህ ቀጥተኛው ሃይማኖት ነው፡፡ በእነርሱ ውስጥም ነፍሶቻችሁን አትበድሉ፡፡ አጋሪዎችንም በአንድ ላይ ኾነው እንደሚዋጉዋችሁ በአንድ ላይ ኾናችሁ ተጋደሉዋቸው፡፡ አላህም ከሚፈሩት ጋር መኾኑን ዕወቁ፡፡'),
('9:37', 87, 'የአንዱን ወር ክብር ወደ ሌላው ማዘግየት በክህደት ላይ (ክህደትን) መጨመር ብቻ ነው፡፡ በእርሱ እነዚያ የካዱት ሰዎች ይሳሳቱበታል፡፡ በአንድ ዓመት የተፈቀደ ያደርጉታል፡፡ በሌላው ዓመትም ያወግዙታል፡፡ (ይህ) አላህ ያከበራቸውን ወሮች ቁጥር ሊያስተካክሉ፣ አላህም እርም ያደረገውን የተፈቀደ ሊያደርጉ ነው፡፡ የሥራዎቻቸው መጥፎው ለነርሱ ተዋበላቸው፡፡ አላህም ከሓዲያን ሕዝቦችን አይመራም፡፡'),
('9:38', 87, 'እናንተ ያመናችሁ ሆይ! በአላህ መንገድ (ለመታገል) ውጡ በተባላችሁ ጊዜ ወደ ምድር የምትወዘፉት ለእናንተ ምን አላችሁ የቅርቢቱን ሕይወት ከመጨረሻይቱ ይበልጥ ወደዳችሁን የቅርቢቱም ሕይወት ጥቅም በመጨረሻይቱ (አንጻር) ጥቂት እንጂ አይደለም፡፡'),
('9:39', 87, 'ለዘመቻ ባትወጡ (አላህ) አሳማሚን ቅጣት ይቀጣችኋል፡፡ ከእናንተ ሌላ የኾኑንም ሕዝቦች ይለውጣል፡፡ በምንም አትጎዱትምም፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('9:40', 87, '(ነቢዩን) ባትረዱት እነዚያ የካዱት ሕዝቦች የሁለት (ሰዎች) ሁለተኛ ኾኖ (ከመካ) ባወጡት ጊዜ አላህ በእርግጥ ረድቶታል፡፡ ሁለቱም በዋሻው ሳሉ ለጓደኛው አትዘን አላህ ከእኛ ጋር ነውና ባለ ጊዜ አላህም መረጋጋትን በእርሱ ላይ አወረደ፡፡ ባላያችኋቸውም ሰራዊት አበረታው፡፡ የእነዚያንም የካዱትን ሰዎች ቃል ዝቅተኛ አደረገ፡፡ የአላህም ቃል ለእርሷ ከፍተኛ ናት፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('9:41', 87, 'ቀላሎችም ከባዶችም ኾናችሁ ዝመቱ፡፡ በአላህም መንገድ በገንዘቦቻችሁ በነፍሶቻችሁም ታገሉ፡፡ ይህ የምታውቁ ብትኾኑ ለናንተ በጣም የተሻለ ነው፡፡'),
('9:42', 87, '(የጠራህባቸው ነገር) ቅርብ ጥቅምና መካከለኛ ጉዞ በኾነ ኖሮ በተከተሉህ ነበር፡፡ ግን በነሱ ላይ መንገዲቱ ራቀችባቸው፡፡ «በቻልንም ኖሮ ከእናንተ ጋር በወጣን ነበር» ሲሉ በአላህ ይምላሉ፡፡ ነፍሶቻቸውን ያጠፋሉ፡፡ አላህም እነሱ ውሸታሞች መኾናቸውን በእርግጥ ያውቃል፡፡'),
('9:43', 87, 'አላህ ከአንተ ይቅር አለ፡፡ እነዚያ እውነተኛዎቹ ላንተ እስከሚገለጹልህና ውሸታሞቹንም እስከምታውቅ ድረስ ለነርሱ (እንዲቀሩ) ለምን ፈቀድክላቸው'),
('9:44', 87, 'እነዚያ በአላህና በመጨረሻው ቀን የሚያምኑት በገንዘቦቻቸውና በነፍሶቻቸው ከመታገላቸው (ለመቅረት) ፈቃድን አይጠይቁህም፡፡ አላህም የሚፈሩትን ዐዋቂ ነው፡፡'),
('9:45', 87, 'ፈቃድን የሚጠይቁህ እነዚያ በአላህና በመጨረሻው ቀን የማያምኑት ልቦቻቸውም የተጠራጠሩት ብቻ ናቸው፡፡ እነሱም በጥርጣሬያቸው ውስጥ ይዋልላሉ፡፡'),
('9:46', 87, 'መውጣትንም ባሰቡ ኖሮ ለርሱ ዝግጅትን ባሰናዱ ነበር፡፡ ግን አላህ (ለመውጣት) እንቅስቃሴያቸውን ጠላ (አልሻውም)፡፡ አሰነፋቸውም፡፡ ከተቀማጮቹም ጋር ተቀመጡ ተባሉ፡፡'),
('9:47', 87, 'ከእናንተ ጋር በወጡ ኖሮ ጥፋትን እንጂ አይጨምሩላችሁም ነበር፡፡ ሁከትንም የሚፈልጉላችሁ ሲኾኑ በመካከላችሁ (በማሳበቅ) ይቻኮሉ ነበር፡፡ በናንተም ውስጥ ለነሱ አዳማጮች አሏቸው፡፡ አላህም በዳዮችን ዐዋቂ ነው፡፡'),
('9:48', 87, 'እነርሱ ጠይዎች ሲኾኑ እውነቱ እስከመጣና የአላህም ትዕዛዝ እስከተገለጸ ድረስ ከዚህ በፊት ሁከትን በእርግጥ ፈለጉ፡፡ ነገሮችንም ሁሉ አገላበጡልህ፡፡'),
('9:49', 87, 'ከነሱም ውስጥ «ለእኔ ፍቀድልኝ አትሞክረኝም» የሚል ሰው አልለ፡፡ ንቁ! በመከራ ውስጥ ወደቁ፡፡ ገሀነምም ከሓዲዎችን በእርግጥ ከባቢ ናት፡፡'),
('9:50', 87, 'መልካም ነገር ብታገኝህ ታስከፋቸዋለች፡፡ መከራም ብታገኝህ «ከዚህ በፊት በእርግጥ ጥንቃቄያችንን ይዘናል» ይላሉ፡፡ እነርሱም ተደሳቾች ኾነው ይሸሻሉ፡፡'),
('9:51', 87, '«አላህ ለኛ የጻፈልን (ጥቅም) እንጂ ሌላ አይነካንም፡፡ እርሱ ረዳታችን ነው፡፡ በአላህ ላይም ምእመናን ይመኩ» በላቸው፡፡'),
('9:52', 87, '«በእኛ ላይ ከሁለቱ መልካሞች አንደኛዋን እንጂ ሌላን ትጠባበቃላችሁን እኛም አላህ ከእርሱ በኾነው ቅጣት ወይም በእጆቻችን የሚያጠፋችሁ መኾኑን በናንተ ላይ እንጠባበቃለን፡፡ ተጠባበቁም እኛ ከእናንተ ጋር ተጠባባቂዎች ነንና» በላቸው፡፡'),
('9:53', 87, '«ወዳችሁም ኾነ ጠልታችሁ ለግሱ፡፡ ከእናንተ ተቀባይ የላችሁም፡፡ እናንተ አመጸኞች ሕዝቦች ናችሁና» በላቸው፡፡'),
('9:54', 87, 'ልግስናዎቻቸውን ከነሱ ተቀባይ የሚያገኙ ከመኾን እነሱ በአላህና በመልክተኛው የካዱ፣ ሶላትንም እነሱ ታካቾች ኾነው በስተቀር የማይሰግዱ፣ እነሱም ጠይዎች ኾነው በስተቀር የማይሰጡ መኾናቸው እንጂ ሌላ አልከለከላቸውም፡፡'),
('9:55', 87, 'ገንዘቦቻቸውና ልጆቻቸውም አይድነቁህ፡፡ አላህ የሚሻው በቅርቢቱ ሕይወት በነርሱ (በገንዘቦቻቸውና በልጆቻቸው) ሊቀጣቸው ነፍሶቻቸውም እነሱ ከሓዲዎች ኾነው ሊወጡ ብቻ ነው፡፡'),
('9:56', 87, 'እነሱም በእርግጥ ከእናንተ ለመኾናቸው በአላህ ይምላሉ፡፡ እነርሱም ከናንተ አይደሉም፡፡ ግን እነሱ (አጋሪዎችን ያገኘ እንዳያገኛቸው) የሚፈሩ ሕዝቦች ናቸው፡፡'),
('9:57', 87, 'መጠጊያን ወይም ዋሻዎችን ወይም መግቢያን (ቀዳዳ) ባገኙ ኖሮ እነርሱ እየገሰገሱ ወደርሱ በሸሹ ነበር፡፡'),
('9:58', 87, 'ከነሱም ውስጥ በምጽዋቶች የሚዘልፉህ ሰዎች አሉ፡፡ ከርሷም (የሚሹትን) ቢስሰጡ ይደሰታሉ፡፡ ከርሷም ባይስሰጡ እነሱ ያን ጊዜ ይጠላሉ፡፡'),
('9:59', 87, 'እነሱም አላህና መልክተኛው የሰጣቸውን በወደዱ፣ «አላህም በቂያችን ነው፤ አላህ ከችሮታው በእርግጥ ይሰጠናል፣ መልክተኛውም (ይሰጠናል)፣ እኛ ወደ አላህ ከጃዮች ነን» ባሉ ኖሮ (ለነሱ በተሻላቸው ነበር)፡፡'),
('9:60', 87, 'ግዴታ ምጽዋቶች (የሚከፈሉት) ለድኾች፣ ለምስኪኖችም፣ በርሷም ላይ ለሚሠሩ ሠራተኞች፣ ልቦቻቸውም (በእስልምና) ለሚለማመዱት፣ ጫንቃዎችንም (በባርነት ተገዢዎችን) ነጻ በማውጣት፣ በባለ ዕዳዎችም፣ በአላህ መንገድም በሚሠሩ፣ በመንገደኛም ብቻ ነው፡፡ ከአላህ የተደነገገች ግዴታ ናት፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('9:61', 87, 'ከእነሱም (ከመናፍቃን) እነዚያ ነቢዩን የሚያሰቃዩ «እርሱም ጆሮ ነው» (ወሬ ሰሚ ነው) የሚሉ አልሉ በላቸው፡፡ ለእናንተ የበጎ (ወሬ) ሰሚ ነው፡፡ በአላህ ያምናል፣ ምእምናንንም ያምናቸዋል፣ ከእናንተም ውስጥ ለነዚያ ላመኑት እዝነት ነው፡፡ እነዚያም የአላህን መልክተኛ የሚያሰቃዩ ለነሱ አሳማሚ ቅጣት አላቸው፡፡'),
('9:62', 87, 'አላህንና መልክተኛውን ሊያስወድዱ ተገቢያቸው ሲኾን እናንተን ያስወደዷችሁ ዘንድ በአላህ ይምሉላችኋል፡፡ ምእምናኖች ቢኾኑ (አላህንና መልክተኛውን ያስወድዱ)፡፡'),
('9:63', 87, 'አላህንና መልክተኛውን የሚከራከር ሰው ለእርሱ የገሀነም እሳት በውስጧ ዘውታሪ ሲኾን የተገባቺው መኾኑን አያውቁምን ይህ ታላቅ ውርደት ነው፡፡'),
('9:64', 87, 'መናፍቃን በልቦቻቸው ውስጥ ያለውን ነገር የምትነግራቸው ሱራ በእነርሱ ላይ መውረዷን ይፈራሉ፡፡ «አላግጡ አላህ የምትፈሩትን ሁሉ ገላጭ ነው» በላቸው፡፡'),
('9:65', 87, 'በእርግጥ ብትጠይቃቸው «እኛ የምንዘባርቅና የምንጫወት ብቻ ነበርን» ይላሉ፡፡ «በአላህና በአንቀጾቹ፣ በመልክተኛውም ታላግጡ ነበራችሁን» በላቸው፡፡'),
('9:66', 87, 'አታመካኙ፤ ከእምነታችሁ በኋላ በእርግጥ ካዳችሁ፡፡ ከእናንተ አንዷን ጭፍራ ብንምር (ሌላዋን) ጭፍራ እነሱ ኃጢአተኞች በመኾናቸው እንቀጣለን፡፡'),
('9:67', 87, 'መናፍቃንና መናፍቃት ከፊሎቻቸው ከከፊሉ ናቸው፡፡ በመጥፎ ነገር ያዛሉ ከደግም ነገር ይከለክላሉ፡፡ እጆቻቸውንም (ከልግስና) ይሰበስባሉ፡፡ አላህን ረሱ፡፡፤ ስለዚህ (እርሱ) ዋቸው፡፡ መናፍቃን አመጸኞቹ እነሱ ናቸው፡፡'),
('9:68', 87, 'መናፍቃንንና መናፍቃትን፣ ከሓዲዎችንም አላህ የገሀነምን እሳት በውስጧ ዘውታሪዎች ሲኾኑ ቃል ገብቶላቸዋል፡፡ እርሷ በቂያቸው ናት፡፡ አላህም ረግሟቸዋል፡፡ ለእነርሱም ዘውታሪ ቅጣት አላቸው፡፡'),
('9:69', 87, 'እንደነዚያ ከናንተ በፊት እንደ ነበሩት ናችሁ፡፡ ከእናንተ ይበልጥ በኃይል የበረቱ በገንዘቦችም በልጆችም ይበልጥ የበዙ ነበሩ፡፡ በዕድላቸውም ተጠቀሙ፡፡ እነዚያም ከእናንተ በፊት የነበሩት በዕድላቸው እንደተጠቀሙ በዕድላችሁ ተጠቀማችሁ፡፡ እንደነዚያም እንደዘባረቁት ዘባረቃችሁ፡፡ እነዚያ ሥራዎቻቸው በቅርቢቱም በመጨረሻይቱም ዓለም ተበላሹ፡፡ እነዚያም ከሳሪዎቹ እነሱ ናቸው፡፡'),
('9:70', 87, 'የእነዚያ ከእናንተ በፊት የነበሩት የኑሕ ሕዝቦች፣ የዓድና የሰሙድም፣ የኢብራሂምም ሕዝቦች የመድየን ባለቤቶችና የተገልባጮቹም ከተሞች ወሬ አልመጣላቸውምን መልክተኞቻቸው በተዓምራት መጧቸው፡፡ አላህም የሚበድላቸው አልነበረም፡፡ ግን ነፍሶቻቸውን የሚበድሉ ነበሩ፡፡'),
('9:71', 87, 'ምእምንና ምእምናትም ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው፡፡ በደግ ነገር ያዛሉ፤ ከክፉም ይከለክላሉ፡፡ ሶላትንም ይሰግዳሉ፡፡ ዘካንም ይሰጣሉ፡፡ አላህንና መልክተኛውንም ይታዘዛሉ፡፡ እነዚያን አላህ በእርግጥ ያዝንላቸዋል፡፡ አላህ አሸናፊ ጥበበኛ ነውና፡፡'),
('9:72', 87, 'አላህ ምእምናንንና ምእምናትን ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ በመኖሪያ ገነቶችም ውስጥ መልካም መኖሪያ ቤቶችን ቃል ገብቶላቸዋል፡፡ ከአላህም የኾነው ውዴታ ከሁሉ የበለጠ ነው፡፡ ይህ እርሱ ታላቅ እድል ነው፡፡'),
('9:73', 87, 'አንተ ነቢዩ ሆይ! ከሓዲዎችንና መናፍቃንን ታገል፡፡ በእነሱም ላይ ጨክን፡፡ መኖሪያቸውም ገሀነም ናት፡፡ መመለሻይቱም ከፋች፡፡'),
('9:74', 87, 'ምንም ያላሉ ለመኾናቸው በአላህ ይምላሉ፡፡ የክህደትንም ቃል በእርግጥ አሉ፡፡ ከእስልምናቸውም በኋላ ካዱ፡፡ ያላገኙትንም ነገር አሰቡ፡፡ አላህም ከችሮታው መልክተኛውም (እንደዚሁ) ያከበራቸው መኾኑን እንጂ ሌላን አልጠሉም፡፡ ቢጸጸቱም ለእነሱ የተሻለ ይኾናል፡፡ ቢሸሹም አላህ በቅርቢቱና በመጨረሻይቱ ዓለም አሳማሚን ቅጣት ይቀጣቸዋል፡፡ ለእነሱም በምድር ውስጥ ምንም ወዳጅና ረዳት የላቸውም፡፡'),
('9:75', 87, 'ከእነሱም «አላህን ከችሮታው ቢሰጠን በእርግጥ እንመጸውታለን ከመልካሞቹም በእርግጥ እንኾናለን» ሲል ቃል የተጋባ አልለ፡፡'),
('9:76', 87, 'ከችሮታውም በሰጣቸው ጊዜ በእርሱ ሰሰቱ፡፡ እነሱ (ኪዳናቸውን) የተዉ ኾነውም ዞሩ፡፡'),
('9:77', 87, 'አላህንም ቃል የገቡለትን በማፍረሳቸውና ይዋሹትም በነበሩት ምክንያት እስከሚገናኙት ቀን ድረስ ንፍቅናን አስከተላቸው፡፡'),
('9:78', 87, 'አላህ ምስጢራቸውንና ውይይታቸውን የሚያውቅ መኾኑን አላህም ሩቆችን ሁሉ በጣም ዐዋቂ መኾኑን አያውቁምን'),
('9:79', 87, 'እነዚያ ከምእምናን በምጽዋቶች ፈቃደኛ የኾኑትን፣ እነዚያንም የችሎታቸውን ያክል እንጅ የማያገኙትን ሰዎች የሚያነውሩ፣ ከእነሱም የሚስቁ አላህ ከነሱ ይሳለቅባቸዋል፤ (ይቀጣቸዋል)፡፡ ለእነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('9:80', 87, 'ለእነርሱ ምሕረትን ለምንላቸው፤ ወይም ለእነሱ ምሕረትን አትለምንላቸው (እኩል ነው)፡፡ ለእነሱ ሰባ ጊዜ ምሕረትን ብትለምንላቸው አላህ ለነሱ በፍጹም አይምርም፡፡ ይህ እነርሱ አላህና መልክተኛውን በመካዳቸው ነው፡፡ አላህም አመጸኞች ሕዝቦችን አያቀናም፡፡'),
('9:81', 87, 'እነዚያ ከዘመቻ የቀሩት ከአላህ መልክተኛ በኋላ በመቀመጣቸው ተደሰቱ፡፡ በአላህም መንገድ በገንዘቦቻቸውና በነፍሶቻቸው መታገልን ጠሉ፡፡ «በሐሩር አትኺዱ» አሉም፡፡ «የገሀነም እሳት ተኳሳነቱ በጣም የበረታ ነው» በላቸው፡፡ የሚያውቁ ቢኾኑ ኖሮ (አይቀሩም ነበር)፡፡'),
('9:82', 87, 'ጥቂትንም ይሳቁ፡፡ ይሠሩት በነበሩት ዋጋ ብዙን ያለቅሳሉ፡፡'),
('9:83', 87, 'ከእነሱም ወደ ኾነችው ጭፍራ አላህ ቢመልስህ (ከአንተ ጋር) ለመውጣትም ቢያስፈቅዱህ፡-«ከኔ ጋር በፍጹም አትወጡም፡፡ ከእኔም ጋር ጠላትን አትዋጉም፡፡ እናንተ በመጀመሪያ ጊዜ መቀመጥን ወዳችኋልና፡፡ ከተቀማጮቹ ጋርም ተቀመጡ» በላቸው፡፡'),
('9:84', 87, 'ከእነሱም በአንድም በሞተ ሰው ላይ ፈጽሞ አትስገድ፡፡ በመቃብሩም ላይ አትቁም፡፡ እነሱ አላህንና መልክተኛውን ክደዋልና፡፡ እነሱም አመጸኞች ኾነው ሞተዋልና፡፡'),
('9:85', 87, 'ገንዘቦቻቸውና ልጆቻቸውም አይድነቁህ፡፡ አላህ የሚሻው በቅርቢቱ ዓለም በነሱ ሊቀጣቸውና ከሓዲዎችም ኾነው ነፍሶቻቸው እንዲወጡ ብቻ ነው፡፡'),
('9:86', 87, 'በአላህ እመኑ፡፡ ከመልክተኛውም ጋር ኾናችሁ ታገሉ፤ በማለት ምዕራፍ በተወረደች ጊዜ ከነሱ የሰፊ ሀብት ባለቤቶች የኾኑት (ለመቅረት) ፈቃድ ይጠይቁሃል፡፡ «ከተቀማጮቹ ጋርም እንኹን ተወን» ይሉሃል፡፡'),
('9:87', 87, 'በቤት ከሚቀሩት ጋር መኾናቸውን ወደዱ፡፡ በልቦቻቸውም ላይ (ዝገት) ታተመባቸው፡፡ ስለዚህ እነሱ አያውቁም፡፡'),
('9:88', 87, 'ግን መልክተኛው እነዚያም ከርሱ ጋር ያመኑት በገንዘቦቻቸውም በነፍሶቻቸውም ታገሉ፡፡ እነዚያም መልካሞች ሁሉ ለነሱ ናቸው፡፡ እነዚያም እነሱ ምኞታቸውን ያገኙ ናቸው፡፡'),
('9:89', 87, 'ለእነሱም ገነቶችን በሥራቸው ወንዞች የሚፈሱባቸውን በውስጣቸው ዘውታሪዎች ሲኾኑ አላህ አዘጋጅቶላቸዋል፡፡ ይህ ታላቅ ማግኘት ነው፡፡'),
('9:90', 87, 'ከአዕራቦችም ይቅርታ ፈላጊዎቹ ለእነሱ እንዲፈቀድላቸው መጡ፡፡ እነዚያ አላህንና መልክተኛውን የዋሹትም ተቀመጡ፡፡ ከነሱ እነዚያን የካዱትን አሳማሚ ቅጣት በእርግጥ ይነካቸዋል፡፡'),
('9:91', 87, 'በደካሞች ላይ በበሽተኞችም ላይ በነዚያም የሚያወጡት ገንዘብ በማያገኙት ላይ ለአላህና ለመልክተኛው ፍጹም ታዛዦች ከኾኑ (ባይወጡም) ኃጢኣት የለባቸውም፡፡ በበጎ አድራጊዎች ላይ (የወቀሳ) መንገድ ምንም የለባቸውም፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('9:92', 87, 'በእነዚያም ልትጭናቸው በመጡህ ጊዜ «በርሱ ላይ የምጭናችሁ (አጋሰስ) አላገኝም፤» ያልካቸው ስትኾን የሚያወጡት ገንዘብ ባለማግኘታቸው ለማዘናቸው ዓይኖቻቸው እንባን እያፈሰሱ በዞሩት ላይ (የወቀሳ መንገድ የለባቸውም)፡፡'),
('9:93', 87, '(የወቀሳ) መንገዱ በእነዚያ እነሱ ባለጸጋዎች ኾነው ሳሉ ለመቅረት ፈቃድ በሚጠይቁህ ሰዎች ላይ ብቻ ነው፡፡ ከቀሪዎቹ ጋር መኾናቸውን ወደዱ፡፡ አላህም በልቦቻቸው ላይ አተመባቸው፤ ስለዚህ እነሱ አያውቁም፡፡'),
('9:94', 87, 'ወደእነሱ በተመለሳችሁ ጊዜ ምክንያታቸውን ያቀርቡላችኋል፡፡ አታመካኙ፤ እናንተን ፈጽሞ አናምንም፡፡ አላህ ከወሬዎቻችሁ በእርግጥ ነግሮናልና፡፡ አላህም ሥራችሁን በእርግጥ ያያል፡፡ መልክተኛውም (እንደዚሁ)፤ ከዚያም ሩቅንና ቅርብን ሁሉ ዐዋቂ ወደ ኾነው (አላህ) ትመለሳላችሁ ወዲያውም ትሠሩት የነበራችሁትን ሁሉ ይነግራችኋል በላቸው፡፡'),
('9:95', 87, 'ወደእነሱ በተመለሳችሁ ጊዜ እንድትተውዋቸው ለእናንተ በእርግጥ በአላህ ይምላሉ፡፡ እነሱንም ተዋቸው፡፡ እነሱ እርኩሶች ናቸውና፡፡ ይሠሩትም በነበሩት ዋጋ መኖሪያቸው ገሀነም ነው፡፡'),
('9:96', 87, 'ከእነሱ ትወዱላቸው ዘንድ ለናንተ ይምሉላችኋል፡፡ ከእነሱ ብትወዱም አላህ አመጸኞች ሕዝቦችን አይወድም፡፡'),
('9:97', 87, 'አዕራቦች በክህደትና በንፍቅና በጣም የበረቱ፤ አላህም በመልክተኛው ላይ ያወረደውን ሕግጋት ባለማወቅ የተገቡ ናቸው፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('9:98', 87, 'ከአዕራቦችም (በአላህ መንገድ) የሚወጣውን (ገንዘብ) ዕዳ አድርጎ የሚይዝ በእናንተም ላይ የጊዜን መገለባበጥ የሚጠባበቅ ሰው አልለ፡፡ በእነሱ ላይ ጥፋቱ ይዙርባቸው፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('9:99', 87, 'ከአዕራቦችም በአላህና በመጨረሻው ቀን የሚያምን የሚሰጣቸውንም (ምጽዋቶች) አላህ ዘንድ መቃረቢያዎችና ወደ መልክተኛው ጸሎቶች መዳረሻ አድርጎ የሚይዝ ሰው አልለ፡፡ ንቁ! እርሷ ለእነሱ በእርግጥ አቃራቢ ናት፡፡ አላህ በችሮታው ውስጥ (በገነቱ) በእርግጥ ያስገባቸዋል፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('9:100', 87, 'ከስደተኞቹና ከረዳቶቹም ሲኾኑ የመጀመሪያዎቹ ቀዳሚዎች እነዚያም በበጎ ሥራ የተከተሏቸው አላህ ከእነሱ ወዷል ከእርሱም ወደዋል፡፡ በሥሮቻቸውም ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘለዓለም ነዋሪዎች ሲኾኑ ለእነርሱ አዘጋጅቶላቸዋል፡፡ ይህ ታላቅ ዕድል ነው፡፡'),
('9:101', 87, 'በዙሪያችሁም ካሉት ከዐረብ ዘላኖች መናፍቃን አልሉ፡፡ ከመዲና ሰዎችም በንፍቅና ላይ በማመጽ የዘወተሩ አልሉ፡፡ አታውቃቸውም፡፡ እኛ እናውቃቸዋለን፡፡ ሁለት ጊዜ እንቀጣቸዋለን፡፡ ከዚያም ወደታላቅ ቅጣት ይመለሳሉ፡፡'),
('9:102', 87, 'ሌሎችም በኃጢአቶቻቸው የተናዘዙ መልካም ሥራንና ሌላን መጥፎ ሥራ የቀላቀሉ አልሉ፡፡ አላህ ከእነሱ ጸጸታቸውን ሊቀበል ይከጀላል፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('9:103', 87, 'ከገንዘቦቻቸው ስትኾን በእርሷ የምታጠራቸውና የምታፋፋቸው የኾነችን ምጽዋት ያዝ፡፡ ለነሱም ጸልይላቸው፡፡ ጸሎትህ ለእነሱ እርጋታ ነውና አላህም ሰሚ ዐዋቂ ነው፡፡'),
('9:104', 87, 'አላህ እርሱ ከባሮቹ ንስሓን የሚቀበል ምጽዋቶችንም የሚወስድ መኾኑን አላህም እርሱ ጸጸትን ተቀባይ አዛኝ መኾኑን አያውቁም'),
('9:105', 87, 'በላቸውም ሥሩ አላህ ሠራችሁን በእርግጥ ያያልና፡፡ መልክተኛውና ምእምናንም (እንደዚሁ ያያሉ)፡፡ ሩቁንና ቅርቡን ሁሉ ዐዋቂ ወደ ኾነውም (አላህ) በእርግጥ ትመለሳላችሁ፡፡ ትሠሩትም የነበራችሁትን ሁሉ ይነግራችኋል፡፡'),
('9:106', 87, 'ሌሎችም ለአላህ ትዕዛዝ የተቆዩ ሕዝቦች አልሉ፡፡ ወይ ይቀጣቸዋል ወይም ከነሱ ላይ ጸጸትን ይቀበላል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('9:107', 87, 'እነዚያም (ምእምናንን) ለመጉዳት፣ ክህደትንም ለማበርታት፣ በምእምናንም መካከል ለመለያየት፣ ከአሁን በፊት አላህንና መልክተኛውን የተዋጋውንም ሰው ለመጠባበቅ መስጊድን የሠሩት (ከነሱ ናቸው)፡፡ መልካምን ሥራ እንጂ ሌላ አልሻንም ሲሉም በእርግጥ ይምላሉ፡፡ አላህም እነሱ በእርግጥ ውሸታሞች መኾናቸውን ይመሰክራል፡፡'),
('9:108', 87, 'በእርሱ ውስጥ በፍጹም አትስገድ፡፡ ከመጀመሪያ ቀን ይዞ በአላህ ፍራቻ ላይ የተመሠረተው (የቁባ) መስጊድ በውስጡ ልትሰግድበት ይልቅ የተገባው ነው፡፡ በእሱ ውስጥ መጥራራትን የሚወዱ ወንዶች አልሉ፡፡ አላህም ተጥራሪዎችን ይወዳል፡፡'),
('9:109', 87, 'አላህን በመፍራትና ውዴታውን በመፈለግ ላይ ግንቡን የመሠረተው ሰው ይበልጣልን ወይስ ጎርፍ በሸረሸረው ለመናድ በተቃረበ ገደል አፋፍ ላይ ግንቡን የመሠረተውና በርሱ (ይዞት) በገሀነም እሳት ውስጥ የወደቀ (ይበልጣል)፡፡ አላህም በደለኞች ሕዝቦችን አይመራም፡፡'),
('9:110', 87, 'ያ የካቡት ግንባቸው ልቦቻቸው (በሞት) ካልተቆራረጡ በቀር በልቦቻቸው ውስጥ የመጠራጠር ምክንያት ከመኾን አይወገድም፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('9:111', 87, 'አላህ ከምእምናን ነፍሶቻቸውንና ገንዘቦቻቸውን ገነት ለእነሱ ብቻ ያላቸው በመኾን ገዛቸው፡፡ በአላህ መንገድ ላይ ይጋደላሉ፡፡ ይገድላሉም፤ ይገደላሉም፡፡ በተውራት በኢንጅልና በቁርኣንም (የተነገረውን) ተስፋ በእርሱ ላይ አረጋገጠ፡፡ ከአላህም የበለጠ በኪዳኑ የሚሞላ ማነው በዚያም በእርሱ በተሻሻጣችሁበት ሽያጫችሁ ተደሰቱ፡፡ ይህም እርሱ ታላቅ ዕድል ነው፡፡'),
('9:112', 87, '(እነርሱ) ተጸጻቺዎች፣ ተገዢዎች፣ አመስጋኞች፣ ጿሚዎች፣ አጎንባሾች፣ በግንባር ተደፊዎች፣ በበጎ ሥራ አዛዦች ከክፉም ከልካዮች፣ የአላህንም ሕግጋት ጠባቂዎች ናቸው ምእምናንንም አብስር፡፡'),
('9:113', 87, 'ለነቢዩና ለነዚያ ላመኑት ለአጋሪዎቹ የዝምድና ባለቤቶች ቢኾኑም እንኳ እነሱ (ከሓዲዎቹ) የእሳት ጓዶች መኾናቸው ከተገለጸላቸው በኋላ ምሕረትን ሊለምኑ የሚገባ አልነበረም፡፡'),
('9:114', 87, 'የኢብራሂምም ለአባቱ ምሕረትን መለመን ለእርሱ ገብቶለት ለነበረችው ቃል (ለመሙላት) እንጂ ለሌላ አልነበረም፡፡ እርሱም የአላህ ጠላት መኾኑ ለእርሱ በተገለጸለት ጊዜ ከርሱ ራቀ፤ (ተወው)፡፡ ኢብራሂም በእርግጥ በጣም ርኅሩኅ ታጋሽ ነውና፡፡'),
('9:115', 87, 'አላህም ሕዝቦችን ከአቀናቸው በኋላ የሚጠነቀቁትን (ሥራ) ለእነሱ እስከሚገልጸላቸው (እስከሚተውትም) ድረስ ጥፋተኛ የሚያደርግ አይደለም፡፡ አላህ በነገሩ ሁሉ ዐዋቂ ነውና፡፡'),
('9:116', 87, 'አላህ የሰማያትና የምድር ንግስና የርሱ ብቻ ነው፡፡ ሕያው ያደርጋል፤ ይገድላልም፡፡ ለእናንተም ከርሱ በቀር ጠባቂም ረዳትም የላችሁም፡፡'),
('9:117', 87, 'በነቢዩ በነዚያም በችግሪቱ ጊዜያት (በተቡክ ዘመቻ) ከእነሱ የከፊሎቹ ልቦች (ለመቅረት) ሊዘነበሉ ከተቃረቡ በኋላ በተከተሉት ስደተኞችና ረዳቶች ላይ አላህ በእርግጥ ጸጸታቸውን ተቀበለ፡፡ ከዚያም ከእነሱ ንስሓ መግባታቸውን ተቀበለ፡፡ እርሱ ለእነሱ ርኅሩኅ አዛኝ ነውና፡፡'),
('9:118', 87, 'በእነዚያም በሦስቱ ሰዎች ላይ ምድር ከስፋትዋ ጋር በእነሱ ላይ እስከ ጠበበች፣ ነፍሶቻቸውም በርሳቸው ላይ እስከተጠበቡ፣ ከአላህም ወደርሱ ቢኾን እንጂ ሌላ መጠጊያ አለመኖሩን እስከ አረጋገጡ ድረስ በተቆዩት ላይ (አላህ ጸጸትን ተቀበለ)፡፡ ከዚያም ይጸጸቱ ዘንድ ወደ ጸጸት መራቸው፡፡ አላህ እርሱ ጸጸትን ተቀባይ አዛኝ ነውና፡፡'),
('9:119', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ፍሩ፤ ከእውነተኞቹም ጋር ኹኑ፡፡'),
('9:120', 87, 'ለመዲና ሰዎችና ከአዕራብም በዙሪያቸው ላሉት ሰዎች ከአላህ መልክተኛ ወደኋላ ሊቀሩ ነፍሶቻቸውንም ከነፍሱ አብልጠው ሊወዱ አይገባቸውም ነበር፡፡ ይህ (ከመቅረት መከልከል) ለእነርሱ መልካም ሥራ የሚጻፍላቸው ቢኾን እንጅ፡፡ በአላህ መንገድ ላይ ጥምም፣ ድካምም፣ ረኃብም፣ የማይነካቸው ከሐዲዎችንም የሚያስቆጭን ስፍራ የማይረግጡ፣ ከጠላትም የሚጎዳን ነገር (መግደልን መማረክን መዝረፍን) የማያገኙ በመኾናቸው ነው፡፡ አላህ የመልካም ሠሪዎችን ምንዳ አያጠፋምና፡፡'),
('9:121', 87, 'ትንሽንም ትልቅንም ልግስና አይለግሱም ወንዝንም አያቋርጡም አላህ ይሠሩት ከነበረው የበለጠን ምንዳ ይመነዳቸው ዘንድ ለእነሱ የሚጻፍላቸው ቢሆን እንጅ፡፡'),
('9:122', 87, 'ምእምናንም (ከነቢዩ ጋር ካልኾነ) በሙሉ ሊወጡ አይገባም፡፡ ከእነሱ ውስጥ ከየክፍሉ አንዲት ጭፍራ ለምን አትወጣም፡፡ (ሌሎቹ) ሃይማኖትን እንዲማሩና ወገኖቻቸው ወደነርሱ በተመለሱ ጊዜ እንዲጠነቀቁ ይገስጹዋቸው ዘንድ (ለምን አይቀሩም)፡፡'),
('9:123', 87, 'እናንተ ያመናችሁ ሆይ! እነዚያን በአቅራቢያችሁ ያሉትን ከሓዲዎች ተዋጉ፡፡ ከእናንተም ብርታትን ያግኙ፡፡ አላህም ከሚጠነቀቁት ጋር መኾኑን ዕወቁ፡፡'),
('9:124', 87, 'ሱራም (ምዕራፍ) በተወረደች ጊዜ ከእነሱ (ከመናፍቃን) ውስጥ ማንኛችሁ ነው ይህች (ምዕራፍ) እምነትን የጨመረችለት የሚል ሰው አልለ፡፡ እነዚያ ያመኑትማ የሚደሰቱ ሲኾኑ እምነትን ጨመረችላቸው፡፡'),
('9:125', 87, 'እነዚያም በልቦቻቸው ውስጥ በሽታ ያለባቸውማ በርክሰታቸው ላይ ርክሰትን ጨመረችላቸው፡፡ እነርሱም ከሓዲዎች ኾነው ሞቱ፡፡'),
('9:126', 87, 'በየዓመቱ አንድ ወይም ሁለት ጊዜ እነርሱ የሚሞከሩ መኾናቸውን አያዩምን ከዚያም አይጸጸቱምን እነሱም አይገሰጹምን'),
('9:127', 87, '(እነሱን የምታነሳ) ምዕራፍም በተወረደች ጊዜ አንድ ሰው ያያችኋልን እያሉ ከፊሎቻቸው ወደ ከፊሉ ይመለከታሉ፡፡ ከዚያም (ተደብቀው) ይኼዳሉ፡፡ እነርሱ የማያውቁ ሕዝቦች በመኾናቸው አላህ ልቦቻቸውን አዞረ፡፡'),
('9:128', 87, 'ከጎሳችሁ የሆነ ችግራችሁ በእርሱ ላይ ጽኑ የሆነ፣ በእናንተ (እምነት) ላይ የሚጓጓ፣ በምእምናን (ላይ) ርኅሩኅ አዛኝ የኾነ መልክተኛ በእርግጥ መጣላችሁ፡፡'),
('9:129', 87, 'ቢያፈገፍጉም አላህ በቂዬ ነው፡፡ ከእርሱ ሌላ አምላክ የለም፡፡ በእርሱ ላይ ተጠጋሁ እርሱም የታላቁ ዐርሽ ጌታ ነው በላቸው፡፡'),
('10:1', 87, 'አ.ለ.ረ (አሊፍ ላም ራ) ይህቺ (ሱራ) ጥበብ ከተመላው መጽሐፍ (ከቁርኣን) አንቀጾች ናት፡፡'),
('10:2', 87, '«ሰዎችን አስፈራራ፡፡ እነዚያንም ያመኑትን ለእነሱ ከጌታቸው ዘንድ መልካም ምንዳ ያላቸው መኾኑን አብስር» በማለት ከነርሱው ወደ ኾነ አንድ ሰው ራእይን ማውረዳችን ለሰዎች ድንቅ ኾነባቸውን ከሓዲዎቹ፡- «ይህ በእርግጥ ግልጽ ድግምተኛ ነው» አሉ፡፡'),
('10:3', 87, 'ጌታችሁ ያ ሰማያትንና ምድርን በስድስት ቀኖች ውስጥ የፈጠረ አላህ ነው፡፡ ከዚያም ነገሩን ሁሉ የሚያስተናብር ሲኾን በዐርሹ ላይ (ለሱ ክብር በምስማማ መልኩ) ተደላደለ፡፡ ከእርሱ ፈቃድ በኋላ ቢኾን እንጂ አንድም አማላጅ የለም፡፡ እነሆ! አላህ ጌታችሁ ነውና ተገዙት፤ አትገሰጹምን'),
('10:4', 87, 'ሁላችሁም ኾናችሁ መመለሻችሁ ወደ እርሱ ነው፡፡ (ይህም) የተረጋገጠ የአላህ ቃል ኪዳን ነው፤ እርሱ መፍጠርን ይጀምራል፡፡ ከዚያም እነዚያን ያመኑትንና መልካም የሠሩትን በትክክል ይመነዳ ዘንድ ይመልሰዋል፡፡ እነዚያ የካዱትም ይክዱት በነበሩት ነገር ለነርሱ ከፈላ ውሃ የኾነ መጠጥና አሳማሚ ቅጣት አላቸው፡፡'),
('10:5', 87, 'እርሱ ያ ፀሐይን አንጻባራቂ ጨረቃንም አብሪ ያደረገ ነው፡፡ የዓመታትን ቁጥርና ሒሳብን ታውቁ ዘንድም ለእርሱ መስፈሪያዎችን የለካ ነው፡፡ አላህ ይህንን በእውነት እንጂ (በከንቱ) አልፈጠረውም፡፡ ለሚያውቁ ሕዝቦች አንቀጾችን ያብራራል፡፡'),
('10:6', 87, 'ሌሊትና ቀን በመተካካታቸው አላህም በሰማያትና በምድር ውስጥ በፈጠረው ሁሉ ለሚጠነቀቁ ሕዝቦች ምልክቶች አሉ፡፡'),
('10:7', 87, 'እነዚያ መገናኘታችንን የማይፈሩ ቅርቢቱንም ሕይወት የወደዱ በእሷም የረኩ እነዚያም እነሱ ከአንቀጾቻችን ዘንጊዎች የኾኑ፡፡'),
('10:8', 87, 'እነዚያ ይሠሩት በነበሩት ምክንያት መኖሪያቸው በእሳት ውስጥ ነው፡፡'),
('10:9', 87, 'እነዚያ ያመኑና መልካም ሥራዎችን የሠሩ ጌታቸው በእምነታቸው ምክንያት (የገነትን መንገድ) ይመራቸዋል፡፡ ከሥራቸው ወንዞች ይፈስሳሉ፡፡ በመጠቀሚያ ገነቶች ውስጥ ይኖራሉ፡፡'),
('10:10', 87, 'በእርሷም ውስጥ ጸሎታቸው ጌታችን ሆይ! ጥራት ይገባህ (ማለት) ነው፡፡ በእርሷ ውስጥ መከባበሪያቸውም ሰላም መባባል ነው፤ የመጨረሻ ጸሎታቸውም ምስጋና ለዓለማት ጌታ ይሁን (ማለት) ነው፡፡'),
('10:11', 87, 'አላህ ለሰዎች ደግን ነገር ለማግኘት እንደ መቻኮላቸው (አጥፋን ሲሉት) ክፉን ነገር ቢያስቸኩል ኖሮ ጊዜያቸው ወደነሱ በተፈጸመ ነበር፡፡ እነዚያንም መገናኘታችንን የማይፈሩትን በጥመታቸው ውስጥ የሚዋልሉ ሲኾኑ እንተዋቸዋለን፡፡'),
('10:12', 87, 'ሰውንም ጉዳት ባገኘው ጊዜ በጎኑ ላይ ተጋድሞ ወይም ተቀምጦ ወይም ቆሞ ይለምነናል፡፡ ጉዳቱንም ከእሱ ላይ በገለጥንለት ጊዜ ወደ አገኘው ጉዳት እንዳልጠራን ሆኖ ያልፋል፡፡ እንደዚሁ ለድንበር አላፊዎች ይሠሩት የነበሩት ሥራ ተሸለመላቸው፡፡'),
('10:13', 87, 'ከእናንተ በፊት የነበሩትንም የክፍለ ዘመናት ሰዎች መልክተኞቻቸው በማስረጃዎች የመጧቸው ሲኾኑ በበደሉና የማያምኑም በኾኑ ጊዜ በእርግጥ አጠፋናቸው፡፡ እንደዚሁ ተንኮለኞችን ሕዝቦች እንቀጣለን፡፡'),
('10:14', 87, 'ከዚያም እንዴት እንደምትሠሩ ልንመለከት ከእነሱ በኋላ በምድር ላይ ምትኮች አደረግናችሁ፡፡'),
('10:15', 87, 'አንቀጾቻችንም ግልጽ ኾነው በእነርሱ ላይ በተነበቡላቸው ጊዜ እነዚያ መገናኘታችንን የማይፈሩት ከዚህ ሌላ የሆነን ቁርኣን አምጣልን ወይም ለውጠው ይላሉ፡፡ እኔ ከራሴ በኩል ልለውጠው አይገባኝም፡፡ ወደእኔ የሚወርደውን እንጂ አልከተልም፡፡ እኔ ከጌታዬ ባምጽ የታላቁን ቀን ቅጣት እፈራለሁ በላቸው፡፡'),
('10:16', 87, 'አላህ በሻ ኖሮ በእናንተ ላይ ባለነበብኩትም (አላህ) እርሱን ባላሳወቃችሁም ነበር፡፡ በእናንተም ውስጥ ከእርሱ በፊት (ምንም ሳልል) ብዙን ዕድሜ በእርግጥ ኖሬአለሁ፤ አታውቁምን'),
('10:17', 87, 'በአላህም ላይ እብለትን ከቀጣጠፈ ወይም በአንቀጾቹ ከአስተባበለ ይበልጥ በዳይ ማን ነው እነሆ አመጸኞች አይድኑም፡፡'),
('10:18', 87, 'ከአላህም ሌላ የማይጎዳቸውን የማይጠቅማቸውንም ይግገዛሉ፡፡ «እነዚህም አላህ ዘንድ አማላጆቻችን ናቸው» ይላሉ፡፡ «አላህን በሰማያትና በምድር ውስጥ የማያውቀው ነገር ኖሮ ትነግሩታላችሁን» በላቸው፡፡ ከሚያጋሩት ሁሉ ጠራ፤ ላቀም፡፡'),
('10:19', 87, 'ሰዎችም አንድ ሕዝብ እንጂ ሌላ አልነበሩም፡፡ ተለያዩም፡፡ ከጌታህ ያለፈች ቃልም ባልነበረች ኖሮ በእርሱ በሚለያዩበት ነገር በመካከላቸው በእርግጥ (በቶሎ) በተፈረደ ነበር፡፡'),
('10:20', 87, 'በእርሱ ላይም ከጌታው የሆነች ተዓምር ለምን አትወረድለትም ይላሉ፡፡ «ሩቅ ነገርም ሁሉ የአላህ ብቻ ነው፡፡ ተጠባበቁም፤ እኔ ከናንተ ጋር ከሚጠባበቁት ነኝና» በላቸው፡፡'),
('10:21', 87, 'ሰዎችንም ካገኛቸው ጉዳት በኋላ እዝነትን (ዝናብና ምቾትን) ባቀመስናቸው ጊዜ ወዲያውኑ ለእነሱ በተዓምራቶቻችን (በማላገጥ) ተንኮል ይኖራቸዋል፡፡ አላህ ቅጣተ ፈጣን ነው፡፡ «መልክተኞቻችን የምትመክሩትን ነገር በእርግጥ ይጽፋሉ» በላቸው፡፡'),
('10:22', 87, 'እርሱ (አላህ) ያ በየብስና በባሕር የሚያስኬዳችሁ ነው፡፡ በመርከቦችም ውስጥ በሆናችሁና በእነርሱም በመልካም ነፋስ በርሷ የተደሰቱ ኾነው (መርከቦቹ) በተንሻለሉ ጊዜ ኀይለኛ ነፋስ ትመጣባታለች፡፡ ከየስፍራውም ማዕበል ይመጣባቸዋል፡፡ እነሱም (ለጥፋት) የተከበቡ መሆናቸውን ያረጋግጣሉ፡፡ (ያን ጊዜ) አላህን ከዚህች (ጭንቀት) ብታድነን በእርግጥ ከአመስጋኞቹ እንሆናለን ሲሉ ሃይማኖትን ለርሱ ብቻ ያጠሩ ሆነው ይለምኑታል፡፡'),
('10:23', 87, 'በአዳናቸውም ጊዜ እነሱ ወዲያውኑ ያለ አግባብ በምድር ላይ ወሰን ያልፋሉ፡፡ እናንተ ሰዎች ሆይ! ወሰን ማለፋችሁ (ጥፋቱ) በነፍሶቻችሁ ላይ ብቻ ነው፡፡ (እርሱም) የቅርቢቱ ሕይወት መጠቀሚያ ነው፡፡ ከዚያም መመለሻችሁ ወደኛ ነው፡፡ ትሠሩት የነበራችሁትንም ሁሉ እንነግራችኋለን፡፡'),
('10:24', 87, 'የቅርቢቱ ሕይወት ምሳሌ ከሰማይ እንዳወረድነው ውሃ፣ በእርሱም ሰውና እንስሳዎች ከሚበሉት የምድር በቃይ ተቀላቅሎበት (እንደ ፋፋ) ምድርም ውበትዋን በያዘችና ባጌጠች ጊዜ ባለቤቶችዋም በርሷ ላይ እነርሱ ቻዮች መኾናቸውን ባሰቡ ጊዜ ትእዛዛችን ሌሊት ወይም ቀን መጥቶባት ትላንት እንዳልነበረች የታጨደች እንዳደረግናት ብጤ ነው፡፡ እንደዚሁም ለሚያስተነትኑ ሕዝቦች አንቀጾችን እናብራራለን፡፡'),
('10:25', 87, 'አላህም ወደ ሰላም አገር ይጠራል፡፡ የሚሻውንም ሰው ወደ ቀጥተኛው መንገድ ይመራል፡፡'),
('10:26', 87, 'ለእነዚያ መልካም ለሠሩት መልካም ነገርና ጭማሪም አላቸው፡፡ ፊቶቻቸውንም ጥቁረትና ውርደት አይሸፍናቸውም፡፡ እነዚያ የገነት ሰዎች ናቸው፡፡ እነርሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('10:27', 87, 'ለእነዚያም ኃጢአቶችን ለሠሩት የኃጢኣቲቱ ቅጣት በብጤዋ አለቻቸው፡፡ ውርደትም ትሸፍናቸዋለች፡፡ ለእነሱ ከአላህ (ቅጣት) ጠባቂ የላቸውም፡፡ ፊቶቻቸው ከጨለመ ሌሊት ቁራጮች እንደ ተሸፈኑ ይኾናሉ፡፡ እነዚያ የእሳት ሰዎች ናቸው፡፡ እነርሱ በውስጧ ዘለዓለም ነዋሪዎች ናቸው፡፡'),
('10:28', 87, 'ሁሉንም የምንሰበስባቸውን ከዚያም ለእነዚያ ለአጋሩት እናንተም ተጋሪዎችሁም ስፍራችሁን ያዙ የምንልበትን ተጋሪዎቻቸውም እኛን ትገዙ አልነበራችሁም የሚሉዋቸው ሲኾኑ በመካከላቸው የምንለይበትን ቀን (አስታውስ)፡፡'),
('10:29', 87, '«(ጣዖታቶቹ ለእኛ) ከመገዛታችሁ በእርግጥ ዘንጊዎች ለመኾናችንም በእኛና በእናንተ መካከል የአላህ መስካሪነት በቃ» (ይሏቸዋል)፡፡'),
('10:30', 87, 'በዚያ ቀን ነፍስ ሁሉ ያሳለፈችውን ሥራ ታውቃለች፡፡ (አጋሪዎች) ወደ አላህም እውነተኛ ወደ ሆነው ጌታቸው ይመለሳሉ፡፡ ከእነሱም ይቀጣጥፉት የነበሩት ነገር ይጠፋቸዋል፡፡'),
('10:31', 87, '«ከሰማይና ከምድር ሲሳይን የሚሰጣችሁ ማን ነው መስሚያዎችንና ማያዎችንስ የፈጠረ ማን ነው ከሙትም ሕያውን የሚያወጣ ከሕያውም ሙትን የሚያወጣስ ማን ነው ነገሩን ሁሉ የሚያስተናብርስ ማን ነው» በላቸው፡፡ «በእርግጥም አላህ ነው» ይሉሃል፡፡ «ታዲያ (ለምን ታጋራላችሁ) አትፈሩትምን» በላቸው፡፡'),
('10:32', 87, 'እርሱ እውነተኛ ጌታችሁ አላህ ነው፡፡ ከእውነትም በኋላ ጥመት እንጂ ሌላ ምን አለ (ከውነት) እንዴት ትዞራላችሁ'),
('10:33', 87, 'እንደዚሁ የጌታህ ቃል በእነዚያ ባመጹት ላይ እነርሱ የማያምኑ መሆናቸው ተረጋገጠች፡፡'),
('10:34', 87, '«ከምታጋሩዋቸው (ጣዖታት) ውስጥ መፍጠርን የሚጀምር ከዚም የሚመልሰው አለን» በላቸው፡፡ «አላህ መፍጠርን ይጀምራል፤ ከዚያም ይመልሰዋል፡፡ ታዲያ (ከእምነት) እንዴት ትዞራላችሁ» በላቸው፡፡'),
('10:35', 87, '«ከምታጋሩዋቸው፤ ወደ እውነት የሚመራ አለን» በላቸው፡፡ «አላህ ወደ እውነቱ ይመራል፡፡ ወደ እውነት የሚመራው ሊከተሉት የተገባው ነውን ወይስ ካልተመራ በስተቀር የማይመራው ለእናንተም ምን (አስረጅ) አላችሁ እንዴት (በውሸት) ትፈርዳላችሁ» በላቸው፡፡'),
('10:36', 87, 'አብዛኞቻቸውም ጥርጣሬን እንጂ አይከተሉም፡፡ ጥርጣሬ ከእውነት ምንም አያብቃቃም፡፡ አላህ የሚሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('10:37', 87, 'ይህም ቁርኣን ከአላህ ሌላ (ከሆነ ፍጡር) የተቀጠፈ ሊሆን አይገባውም፡፡ ግን ያንን ከእርሱ በፊት ያለውን (መጽሐፍ) የሚያረጋግጥና በመጽሐፉ ውስጥ ያለውን የሚዘረዝር በእርሱ ጥርጣሬ የሌለበት ሲሆን ከዓለማት ጌታ (የተወረደ) ነው፡፡'),
('10:38', 87, 'በእውነትም «(ሙሐመድ) ቀጣጠፈው» ይላሉን «ይህ ከሆነ መሰሉን (አንዲት) ሱራ አምጡ፡፡ ከአላህም ሌላ የቻላችሁትን ሁሉ (ረዳት) ጥሩ፡፡ እውነተኞች እንደሆናችሁ (ተጋግዛችሁ አምጡ)» በላቸው፡፡'),
('10:39', 87, 'ይልቁንም (ከቁርኣን) እውቀቱን ባላደረሱት ፍቹም ገና ባልመጣቸው ነገር አስተባበሉ፡፡ እንደዚሁ እነዚያ ከእነሱ በፊት የነበሩት አስተባብለዋል፡፡ የበዳዮችም መጨረሻ እንዴት እንደ ነበረ ተመልከት፡፡'),
('10:40', 87, 'ከእነርሱም ውስጥ (ወደፊት) በርሱ የሚያምኑ አልሉ፡፡ ከእነርሱም በእርሱ የማያምኑ አልሉ፡፡ ጌታህም አጥፊዎቹን በጣም ዐዋቂ ነው፡፡'),
('10:41', 87, '«ቢያስተባብሉህም ለእኔ ሥራዬ አለኝ፡፡ ለእናንተም ሠራችሁ አላችሁ፡፡ እናንተ ከምሠራው ነገር ንጹሕ ናችሁ፡፡ እኔም ከምትሠሩት ነገር ንጹሕ ነኝ» በላቸው፡፡'),
('10:42', 87, 'ከእነሱም ወደ አንተ የሚያዳምጡ (እና የማያምኑ) አልሉ፡፡ አንተ ደንቆሮዎችን የማያውቁ ቢኾኑም ታሰማለህን'),
('10:43', 87, 'ከእነሱም ወደ አንተ የሚመለከቱ አልሉ፡፡ አንተ (ልበ) ዕውራንን የማያዩ ቢኾኑም ትመራለህን'),
('10:44', 87, 'አላህ ሰዎችን ምንም አይበድልም፡፡ ግን ሰዎች ነፍሶቻቸውን ይበድላሉ፡፡'),
('10:45', 87, '(ከሓዲዎችን) ከቀን አንዲትን ሰዓት እንጂ እንዳልቆዩ መስለው በመካከላቸው የሚተዋወቁ ሲሆኑ በምንሰበስባቸው ቀን (አስታውስ)፡፡ እነዚያ በአላህ መገናኘት ያስተባበሉት በእርግጥ ከሰሩ የተመሩም አልነበሩም፡፡'),
('10:46', 87, 'የዚያንም የምናስፈራራቸውን ከፊሉን (በሕይወትህ) ብናሳይህ (መልካም ነው)፡፡ ወይም (ሳናሳይህ) ብንገድልህ መመለሻቸው ወደ እኛ ነው፡፡ ከዚያም አላህ በሚሠሩት ስራ ላይ ዐዋቂ ነው፡፡'),
('10:47', 87, 'ለሕዝቦችም ሁሉ መልክተኛ አላቸው፡፡ መልክተኛውም በመጣ ጊዜ (ሲያስተባብሉ) በመካከላቸው በትክክል ይፈረዳል፡፡ እነርሱም አይበደሉም፡፡'),
('10:48', 87, '«እውነተኞችም ከሆናችሁ ይህ (የቅጣቱ) ቀጠሮ መቼ ነው» ይላሉ፡፡'),
('10:49', 87, '«ለራሴ ጉዳትንም ጥቅምንም አላህ ከሻው በስተቀር አልችልም፡፡ ለሕዝቦች ሁሉ የተወሰነ ጊዜ አልላቸው፡፡ ጊዜያቸው በመጣ ወቅት አንዲትን ሰዓት አይቆዩም፤ አይቀደሙምም» በላቸው፡፡'),
('10:50', 87, '«ቅጣቱ በሌሊት ወይም በቀን ቢመጣባችሁ፤ አጋሪዎቹ ከርሱ የሚቻኮሉበት ነገር ምንድን ነው ንገሩኝ» በላቸው፡፡'),
('10:51', 87, '«ከዚያም (ቅጣቱ) በወደቀ ጊዜ በእርሱ አመናችሁበትን በእርግጥ በእርሱ የምትቻኮሉ የነበራችሁ ስትሆኑ አሁን» (ይባላሉ)፡፡'),
('10:52', 87, 'ከዚያም ለእነዚያ ለበደሉት፡- «ዘውታሪን ቅጣት ቅመሱ ትሠሩት የነበረችሁትን ዋጋ እንጂ አትመነዱም» ይባላሉ፡፡'),
('10:53', 87, 'እርሱም «እውነት ነውን» (ሲሉ) ይጠይቁሃል፡፡ «አዎን፤ በጌታዬ እምላለሁ፤ እርሱ እውነት ነው፡፡ እናንተም አምላጮች አይደላችሁም፤» በላቸው፡፡'),
('10:54', 87, 'ለበደለችም ነፍስ ሁሉ በምድር ላይ ያለው ሁሉ ቢኖራት ኖሮ በእርግጥ በተበዠችበት ነበር፡፡ ቅጣቱንም ባዩ ጊዜ ጸጸትን ይገልጻሉ፡፡ በመካከላቸውም በትክክል ይፈረዳል፡፡ እነርሱም አይበደሉም፡፡'),
('10:55', 87, 'ንቁ! በሰማያትና በምድር ያለው ሁሉ የአላህ ነው፡፡ ንቁ! የአላህ ተስፋ ቃል እርግጥ ነው፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('10:56', 87, 'እርሱ ሕያው ያደርጋል፤ ይገድላልም ወደ እርሱም ትመለሳላችሁ፡፡'),
('10:57', 87, 'እናንተ ሰዎች ሆይ! ከጌታችሁ ግሳጼ በደረቶች ውስጥም ላለው (የመጠራጠር በሽታ) መድኃኒት ለምእምናንም ብርሃንና እዝነት በእርግጥ መጣችላችሁ፡፡'),
('10:58', 87, '«በአላህ ችሮታና በእዝነቱ (ይደሰቱ)፡፡ በዚህም ምክንያት ይደሰቱ፡፡ እርሱ ከሚሰበስቡት ሀብት በላጭ ነው» በላቸው፡፡'),
('10:59', 87, '«አላህ ከሲሳይ ለእናንተ ያወረደውን ከእርሱም እርምና የተፈቀደ ያደረጋችሁትን አያችሁን» በላቸው፡፡ «አላህ (ይህንን) ለእናንተ ፈቀደላችሁን ወይስ በአላህ ላይ ትቀጣጥፋላችሁ» በላቸው፡፡'),
('10:60', 87, 'የእነዚያም በአላህ ላይ ውሸትን የሚቀጣጥፉ (ሰዎች) በትንሣኤ ቀን (በአላህ) ጥርጣሬያቸው ምንድን ነው (አይቀጡም ይመስላቸዋልን) አላህ በሰዎች ላይ (ቅጣትን ባለማቻኮል) የልግስና ባለቤት ነው፡፡ ግን አብዛኛዎቹ አያመሰግኑም፡፡'),
('10:61', 87, '(ሙሐመድ ሆይ!) በማንኛውም ነገር ላይ አትሆንም፣ ከርሱም ከቁርኣን አታነብም፣ ማንኛውንም ሥራ (አንተም ሰዎቹም) አትሠሩም በገባችሁበት ጊዜ በናንተ ላይ ተጠባባቂዎች ብንሆን እንጂ፡፡ በምድርም ሆነ በሰማይ የብናኝ ክብደት ያክል ከጌታህ (ዕውቀት) አይርቅም፡፡ ከዚያም ያነሰ የተለቀም የለም፤ በግልጹ መጽሐፍ ውስጥ የተጻፈ ቢሆን እንጂ፡፡'),
('10:62', 87, 'ንቁ! የአላህ ወዳጆች በእነሱ ላይ ፍርሃት የለባቸውም፤ እነሱም አያዝኑም፡፡'),
('10:63', 87, '(እነሱም) እነዚያ ያመኑትና ይፈሩት የነበሩ ናቸው፡፡'),
('10:64', 87, 'ለእነሱ በቅርቢቱ ሕይወትም በመጨረሻይቱም ብስራት አላቸው፤ የአላህ ቃላት መለወጥ የላትም፤ ይህ እርሱ ታላቅ ዕድል ነው፡፡'),
('10:65', 87, 'ንግግራቸውም አያሳዝንህ፡፡ ኀይል ሁሉ በሙሉ የአላህ ብቻ ነውና፡፡ እርሱ ሰሚው ዐዋቂው ነው፡፡'),
('10:66', 87, 'ንቁ! በሰማያት ያሉትና በምድርም ያሉት ሁሉ በእርግጥ የአላህ ናቸው፤ እነዚያ ከአላህ ሌላ ተጋሪዎችን የሚጠሩ ምንን ይከተላሉ ጥርጣሬን እንጂ ሌላ አይከተሉም፡፡ እነርሱም የሚዋሹ እንጂ አይደሉም፡፡'),
('10:67', 87, 'እርሱ ያ ሌሊትን በውስጡ ልታርፉበት (ጨለማ)፤ ቀንንም (ልትሠሩበት) ብርሃን ያደረገላችሁ ነው፡፡ በዚህ ውስጥ ለሚሰሙ ሕዝቦች በእርግጥ ታምራቶች አሉ፡፡'),
('10:68', 87, '«አላህ ልጅን ያዘ (ወለደ)» አሉ፡፡ (ከሚሉት) ጥራት ተገባው፡፡ እርሱ ተብቃቂ ነው፡፡ በሰማያትና በምድር ያለው ሁሉ የርሱ ነው፡፡ እናንተ ዘንድ በዚህ (በምትሉት) ምንም አስረጅ የላችሁም፡፡ በአላህ ላይ የማታውቁትን ትናገራላችሁን'),
('10:69', 87, '«እነዚያ በአላህ ላይ ውሸትን የሚቀጣጥፉ ፈጽሞ አይድኑም፤» በላቸው፡፡'),
('10:70', 87, '(እነሱ) በቅርቢቱ ዓለም መጠቀም አላቸው፡፡ ከዚያም መመለሻቸው ወደእኛ ነው፡፡ ከዚያም ይክዱ በነበሩት ምክንያት ብርቱን ቅጣት እናቀምሳቸዋለን፡፡'),
('10:71', 87, 'የኑሕንም ወሬ በእነሱ ላይ አንብብላቸው፡፡ ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፡፡ «ሕዝቦቼ ሆይ! በእናንተ ውስጥ ብዙ ጊዜ መቆየቴ በአላህም ተዓምራት ማስታወሴ በእናንተ ላይ የከበደ ቢሆን፤ በአላህ ላይ ተጠግቻለሁ፡፡ ነገራችሁንም ከምታጋሩዋቸው (ጣዖታት) ጋር ሆናችሁ ቁረጡ፡፡ ከዚያም ነገራችሁ በእናንተ ላይ ድብቅ አይሁን (ግለጹት)፡፡ ከዚያም (የሻችሁትን) ወደእኔ አድርሱ፡፡ ጊዜም አትስጡኝ (ከምንም አልቆጥራችሁም)፡፡»'),
('10:72', 87, '«ብትሸሹም (አትጎዱኝም)፡፡ ከምንዳ ምንንም አልለምናችሁምና፡፡ ምንዳዬ በአላህ ላይ እንጂ በሌላ ላይ አይደለም፡፡ ከሙስሊሞች እንድሆንም ታዝዣለሁ፡፡»'),
('10:73', 87, 'አስተባበሉትም፡፡ እርሱንና ከእርሱ ጋር የነበሩትንም በታንኳይቱ ውስጥ አዳንናቸው፡፡ (ለጠፉት) ምትኮችም አደረግናቸው፡፡ እነዚያንም በአንቀጾቻችን ያስተባበሉትን አሰጠምን፡፡ የተስፈራሩትም ሕዝቦች መጨረሻ እንዴት እንደነበረ ተመልከት፡፡'),
('10:74', 87, 'ከዚያም ከእርሱ በኋላ መልክተኞችን ወደየሕዝቦቻቸው ላክን፡፡ በግልጽ ማስረጃዎችም መጧቸው፡፡ (ከመላካቸው) በፊት በእርሱ ባስተባበሉበትም ነገር፤ የሚያምኑ አልሆኑም፡፡ እንደዚሁ በወሰን አላፊዎች ልቦች ላይ እናትማለን፡፡'),
('10:75', 87, 'ከዚያም ከእነሱ ኋላ ሙሳንና ሃሩንን ወደ ፈርዖንና ወደ መማክርቱ በተዓምራታችን ላክን፡፡ ኮሩም ትዕቢተኞች ሕዝቦችም ነበሩ፡፡'),
('10:76', 87, 'ከእኛም ዘንድ እውነቱ በመጣላቸው ጊዜ «ይህ በእርግጥ ግልጽ ድግምት ነው» አሉ፡፡'),
('10:77', 87, 'ሙሳ አለ፡- «እውነቱን በመጣላችሁ ጊዜ ድግምተኞች የማይድኑ ሲኾኑ (እርሱ ድግምት ነው) ትላላችሁን ይህ ድግምት ነውን»'),
('10:78', 87, '(እነርሱም) አሉ፡- «አባቶቻችንን በእርሱ ላይ ካገኘንበት ሃይማኖት ልታዞረን ለእናንተም በምድር ውስጥ ኩራት (ሹመት) ልትኖራችሁ መጣህብን እኛም ለእናንተ አማኞች አይደለንም፡፡»'),
('10:79', 87, 'ፈርዖንም፡- «ዐዋቂ ድግምተኛን ሁሉ አምጡልኝ» አለ፡፡'),
('10:80', 87, 'ድግምተኞቹም በመጡ ጊዜ ሙሳ ለእነርሱ፡- «እናንተ የምትጥሉትን ነገር ጣሉ» አላቸው፡፡'),
('10:81', 87, '(ገመዶቻቸውን) በጣሉም ጊዜ ሙሳ አለ፡- «ያ በርሱ የመጣችሁበት ነገር ድግምት ነው፡፡ አላህ በእርግጥ ያፈርሰዋል፡፡ አላህ የአጥፊዎችን ሥራ ፈጽሞ አያበጅምና፡፡»'),
('10:82', 87, 'አላህም ከሓዲዎች ቢጠሉም እውነትን በቃላቱ ያረጋግጣል፡፡'),
('10:83', 87, 'ለሙሳም ከፈርዖንና ከሹማምንቶቻቸው ማሰቃየትን ከመፍራት ጋር ከወገኖቹ የኾኑ ጥቂቶች ትውልዶች እንጂ አላመኑለትም፡፡ ፈርዖንም በምድር ላይ በእርግጥ የኮራ ነበር፡፡ እርሱም በእርግጥ ወሰን ካለፉት ነበር፡፡'),
('10:84', 87, 'ሙሳም አለ፡- «ሕዝቦቼ ሆይ! በአላህ አምናችሁ እንደ ሆነ በርሱ ላይ ተጠጉ፡፡ ታዛዦች እንደ ሆናችሁ (በአላህ ላይ ትመካላችሁ)፡፡»'),
('10:85', 87, 'አሉም፡- «በአላህ ላይ ተጠጋን፡፡ ጌታችን ሆይ! ለበደለኞች ሕዝቦች መፈተኛ አታድርገን፡፡»'),
('10:86', 87, 'በእዝነትህም ከከሓዲዎች ሕዝቦች አድነን፡፡'),
('10:87', 87, 'ወደ ሙሳና ወደ ወንድሙ፡- «ለሕዝቦቻችሁ በምስር ቤቶችን ሥሩ፡፡ ቤቶቻችሁንም መስገጃ አድርጉ፡፡ ሶላትንም በደንቡ ስገዱ፡፡ (ለሙሳ) ምእምናኖቹንም አብስር» ስንል ላክን፡፡'),
('10:88', 87, 'ሙሳም አለ፡- «ጌታችን ሆይ! አንተ ለፈርዖንና ለሹሞቹ በቅርቢቱ ሕይወት ጌጥን ብዙ ገንዘቦችንም በእርግጥ ሰጠህ፡፡ ጌታችን ሆይ! ከመንገድህ ያሳስቱ ዘንድ (ሰጠሃቸው)፡፡ ጌታችን ሆይ! ገንዘቦቻቸውን አጥፋ፡፡ በልቦቻቸውም ላይ አትም፡፡ አሳማሚን ቅጣት እስከሚያዩ አያምኑምና፡፡»'),
('10:89', 87, '(አላህም) «ጸሎታችሁ በእርግጥ ተሰምታለች፡፡ ቀጥም በሉ፡፡ የእነዚያንም የማያውቁትን ሰዎች መንገድ አትከተሉ» አላቸው፡፡'),
('10:90', 87, 'የእስራኤልንም ልጆች ባሕሩን አሳለፍናቸው፡፡ ፈርዖንና ሰራዊቱም ወሰን ለማለፍና ለመበደል ተከተሏቸው፡፡ መስጠምም ባገኘው ጊዜ፡- «አመንኩ፡፡ እነሆ ከዚያ የእስራኤል ልጆች በርሱ ከአመኑበት በስተቀር ሌላ አምላክ የለም፡፡ እኔም ከታዛዦቹ ነኝ» አለ፡፡'),
('10:91', 87, 'ከአሁን በፊት በእርግጥ ያመጽክ ከአጥፊዎችም የነበርክ ስትሆን አሁን (አመንኩ ትላለህ)'),
('10:92', 87, 'ዛሬማ ከኋላህ ላሉት ተዓምር ትሆን ዘንድ በድን ሆነህ (ከባሕሩ) እናወጣሃለን (ተባለ)፡፡ ከሰዎችም ብዙዎቹ ከተዓምራታችን በእርግጥ ዘንጊዎች ናቸው፡፡'),
('10:93', 87, 'የእስራኤልንም ልጆች ምስጉንን ስፍራ በእርግጥ አሰፈርናቸው፡፡ ከመልካም ሲሳዮችም ሰጠናቸው፡፡ ዕውቀትም (ቁርኣን) እስከመጣቸው ድረስ አልተለያዩም፡፡ ጌታህ በርሱ ይለያዩበት በነበሩት ነገር በትንሣኤ ቀን በመካከላቸው ይፈርዳል፡፡'),
('10:94', 87, 'ወደ አንተም ካወረድነው በመጠራጠር ውስጥ ብትሆን እነዚያን ከአንተ በፊት መጽሐፉን የሚያነቡትን ጠይቅ፡፡ እውነቱ ከጌታህ ዘንድ በእርግጥ መጥቶልሃል፡፡ ከተጠራጣሪዎቹም አትሁን፡፡'),
('10:95', 87, 'ከእነዚያም የአላህን አንቀጾች ከአስተባበሉት አትሁን፡፡ ከከሳሪዎቹ ትሆናለህና፡፡'),
('10:96', 87, 'እነዚያ በእነርሱ ላይ የጌታህ ቃል የተረጋገጠባቸው አያምኑም፡፡'),
('10:97', 87, 'ተዓምር ሁሉ ብትመጣላቸውም አሳማሚን ቅጣት እስከሚያዩ ድረስ (አያምኑም)፡፡'),
('10:98', 87, '(ከዩኑስ በፊት ካለፉት ከተሞች) ያመነችና እምነትዋ የጠቀማት ከተማ ለምን አልኖረችም ግን የዩኑስ ሕዝቦች ባመኑ ጊዜ በቅርቢቱ ሕይወት የውርደትን ቅጣት ከእነሱ ላይ አነሳንላቸው፡፡ እስከ ጊዜም ድረስ አጣቀምናቸው፡፡'),
('10:99', 87, 'ጌታህም በሻ ኖሮ በምድር ያሉት ሰዎች ሁሉም የተሰበሰቡ ሆነው ባመኑ ነበር፡፡ ታዲያ አንተ ሰዎችን አማኞች እንዲኾኑ ታስገድዳለህን'),
('10:100', 87, 'ለማንኛዋም ነፍስ በአላህ ፈቃድ ቢሆን እንጂ ልታምን (ችሎታ) የላትም፡፡ (አላህ ለከፊሎቹ እምነትን ይሻል)፡፡ በእነዚያም በማያውቁት ላይ ርክሰትን ያደርጋል፡፡'),
('10:101', 87, '«በሰማያትና በምድር ያለውን (ተዓምር) ተመልከቱ» በላቸው፡፡ ተዓምራቶችና አስፈራሪዎችም ለማያምኑ ሕዝቦች አይጠቅሙም፡፡'),
('10:102', 87, 'የእነዚያን ከእነሱ በፊት ያለፉትን ሕዝቦች ቀኖች ብጤ እንጂ ሌላን ይጠባበቃሉን «ተጠባበቁ፤ እኔ ከናንተ ጋር ከሚጠባበቁት ነኝ» በላቸው፡፡'),
('10:103', 87, 'ከዚያም መልክተኞቻችንን እነዚያንም ያመኑትን እናድናለን፡፡ እንደዚሁም ምእምናንን (ከጭንቅ ሁሉ) እናድናለን፡፡ (ይህ) በእኛ ላይ ተረጋገጠ፡፡'),
('10:104', 87, '«እናንተ ሰዎች ሆይ! ከእኔ ሃይማኖት በመጠራጠር ውስጥ ብትሆኑ እነዚያን ከአላህ ሌላ የምትገዟቸውን አልገዛም፡፡ ግን ያንን የሚገድላችሁን አላህን እገዛለሁ፡፡ ከምእምናን እንድሆንም ታዝዣለሁ» በላቸው፡፡'),
('10:105', 87, 'ፊትህንም (ወደ ቀጥታ) ያዘነበልክ ስትሆን ለሃይማኖት ቀጥ አድርግ፡፡ ከአጋሪዎቹም አትሁን፡፡'),
('10:106', 87, '«ከአላህም በቀር የማይጠቅምንና የማይጎዳን አትገዛ፡፡ ብትሠራም አንተ ያንጊዜ ከበደለኞቹ ትሆናለህ» (ተብያለሁ በላቸው)፡፡'),
('10:107', 87, 'አላህም ጉዳትን ቢያደርስብህ ከእርሱ ሌላ ለእርሱ ገላጭ የለውም፡፡ በጎንም ነገር ቢሻልህ ለችሮታው መላሽ የለም፡፡ ከባሮቹ የሚሻውን በእርሱ ይለይበታል፡፡ እርሱም መሓሪ አዛኝ ነው፡፡'),
('10:108', 87, '«እናንተ ሰዎች ሆይ! እውነቱ ከጌታችሁ በእርግጥ መጣላችሁ፡፡ (በእርሱ) የተመራም ሰው የሚመራው ለራሱ ነው፡፡ የተሳሳተም ሰው የሚሳሳተው (ጉዳቱ) በራሱ ላይ ነው፡፡ እኔም በእናንተ ላይ ተጠባበቂ አይደለሁም» በላቸው፡፡'),
('10:109', 87, 'ወዳንተም የሚወረደውን ነገር ተከተል፡፡ አላህም (በነሱ ላይ) እስከሚፈርድ ድረስ ታገስ፡፡ እርሱም ከፈራጆቹ ሁሉ በላጭ ነው፡፡'),
('11:1', 87, 'አ.ለ.ረ (አሊፍ ላም ራ፤ ይህ ቁርኣን) አንቀጾቹ በጥንካሬ የተሰካኩ ከዚያም የተዘረዘሩ የሆነ መጽሐፍ ነው፡፡ ጥበበኛ ውስጠ ዐዋቂ ከሆነው ዘንድ (የተወረደ) ነው፡፡'),
('11:2', 87, '(እንዲህ በላቸው)፡- «አላህን እንጂ ሌላን አትገዙ፡፡ እኔ ለእናንተ ከርሱ (የተላክሁ) አስፈራሪና አብሳሪ ነኝ፡፡»'),
('11:3', 87, 'ጌታችሁንም ምሕረትን ለምኑት፡፡ ከዚያም ወደእርሱ ተመለሱ፡፡ እስከተወሰነ ጊዜ ድረስ መልካምን መጥቀም ይጠቅማችኋልና፡፡ የትሩፋትንም ባለቤት ሁሉ ችሮታውን (ምንዳውን) ይሰጠዋል፡፡ ብትሸሹም እኔ በእናንተ ላይ የታላቁን ቀን ቅጣት እፈራላችኋለሁ፡፡'),
('11:4', 87, 'መመለሻችሁ ወደ አላህ ብቻ ነው፡፡ እርሱም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('11:5', 87, 'ንቁ! እነሱ ከእርሱ (ከአላህ) ይደበቁ ዘንድ ደረቶቻቸውን ያጥፋሉ፡፡ ንቁ! ልብሶቻቸውን በሚከናነቡ ጊዜ የሚደብቁትን የሚገልጹትንም ሁሉ ያውቃል፡፡ እርሱ በደረቶች ውስጥ ያለውን ሁሉ ዐዋቂ ነውና፡፡'),
('11:6', 87, 'በምድርም ላይ ምንም ተንቀሳቃሽ የለችም ምግቧ በአላህ ላይ ያለ ቢኾን እንጂ፡፡ ማረፊያዋንም መርጊያዋንም ያውቃል፡፡ ሁሉም ግልጽ በሆነው መጽሐፍ ውስጥ ነው፡፡'),
('11:7', 87, 'እርሱም ያ ሰማያትንና ምድርን በስድስት ቀኖች ውስጥ የፈጠረ ነው፡፡ ዐርሹም በውሃ ላይ ነበር፡፡ የትኛችሁ ሥራው ያማረ መሆኑን ይፈትናችሁ ዘንድ (ፈጠራቸው)፡፡ «እናንተ ከሞት በኋላ በእርግጥ ተቀስቃሾች ናችሁ» ብትልም እነዚያ የካዱት ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም ይላሉ፡፡'),
('11:8', 87, 'ቅጣቱንም ወደ ተቆጠሩ (ጥቂት) ጊዜያቶች ከእነርሱ ብናቆይላቸው «(ከመውረድ) የሚከለክለው ምንድን ነው» ይላሉ፡፡ ንቁ! በሚመጣባቸው ቀን ከእነሱ ላይ ተመላሽ አይደለም፡፡ በእርሱ ይሳለቁበት የነበሩትም (ቅጣት) በእነርሱ ላይ ይወርድባቸዋል፡፡'),
('11:9', 87, 'ሰውንም ከእኛ ችሮታን ብናቀምሰው ከዚያም ከርሱ ብንወስዳት እርሱ በእርግጥ ተስፋ ቆራጭ ክህደተ ብርቱ ነው፡፡'),
('11:10', 87, 'ካገኘችውም ችግር በኋላ ጸጋዎችን ብናቀምሰው «ችግሮች ከኔ ላይ በእርግጥ ተወገዱ» ይላል (አያመሰግንም)፡፡ እርሱ ተደሳች ጉረኛ ነውና፡፡'),
('11:11', 87, 'ግን እነዚያ የታገሱ መልካም ሥራዎችንም የሠሩ እነዚያ ለእነሱ ምሕረትና ታላቅ ምንዳ አልላቸው፡፡'),
('11:12', 87, 'በእርሱ ላይ የገንዘብ ድልብ ለምን አልተወረደም ወይም ከርሱ ጋር መልአክ ለምን አልመጣም ማለታቸውንም በመፍራት ወደ አንተ ከሚወርደው ከፊሉን ልትተው በእርሱም ልብህ ጠባብ ሊኾን ይፈራልሃል፡፡ አንተ አስፈራሪ ብቻ ነህ፡፡ አላህም በነገሩ ሁሉ ተጠባባቂ ነው፡፡'),
('11:13', 87, 'ይልቁንም «(ቁርኣንን) ቀጣጠፈው» ይላሉን፡- «እውነተኞች እንደሆናችሁ ብጤው የሆኑን ዐስር የተቀጣጠፉ ሱራዎች አምጡ፡፡ ከአላህም ሌላ የቻላችሁትን (ረዳት) ጥሩ» በላቸው፡፡'),
('11:14', 87, 'ለእናንተም (ጥሪውን) ባይቀበሏችሁ የተወረደው በአላህ እውቀት ብቻ መሆኑንና ከእርሱ ሌላ አምላክ አለመኖሩን ዕወቁ፡፡ ታዲያ እናንተ የምትሰልሙ ናችሁን (ስለሙ በላቸው)፡፡'),
('11:15', 87, 'ቅርቢቱን ሕይወትና ጌጧን የሚሹ የሆኑትን ሰዎች ሥራዎቻቸውን (ምንዳዋን) በእርሷ ውስጥ ወደነሱ እንሞላላቸዋለን፡፡ እነሱም በርሷ ውስጥ ምንም አይጎድልባቸውም፤'),
('11:16', 87, 'እነዚያ እነርሱ በመጨረሻይቱ ዓለም ለእነርሱ ከእሳት በቀር የሌላቸው ናቸው፡፡ የሠሩትም ሥራ በርሷ ውስጥ ተበላሸ፡፡ (በቅርቢቱ ዓለም) ይሠሩት የነበሩትም በጎ ሥራ ብልሹ ነው፡፡'),
('11:17', 87, 'ከጌታው ከአስረጅ ጋር የኾነ ሰው፤ ከእርሱም (ከአላህ) የኾነ መስካሪ የሚከተለው፣ ከእርሱ በፊትም የሙሳ መጽሐፍ መሪና እዝነት ሲኾን (የመሰከረለት) የቅርቢቱን ሕይወት እንደሚሻው ሰው ነውን እነዚያ በእርሱ (በቁርኣን) ያምናሉ፡፡ ከአሕዛቦቹም በእርሱ የሚክድ ሰው እሳት መመለሻው ናት፡፡ ከእርሱም በመጠራጠር ውስጥ አትሁን፡፡ እርሱ ከጌታህ የሆነ እውነት ነው፡፡ ግን አብዛኞቹ ሰዎች አያምኑም፡፡'),
('11:18', 87, 'በአላህ ላይ እብለትን ከሚቀጣጥፍም ይበልጥ በዳይ ማነው እነዚያ በጌታቸው ላይ ይቀርባሉ፡፡ መስካሪዎቹም «እነዚህ በጌታቸው ላይ የዋሹት ናቸው» ይላሉ፡፡ ንቁ! የአላህ ርግማን በበዳዮች ላይ ይሁን፡፡'),
('11:19', 87, '(እነሱም) እነዚያ ከአላህ መንገድ የሚከለክሉ መጥመሟንም የሚፈልጓት ናቸው፡፡ እነሱም መጨረሻይቱን ዓለም እነሱ ከሓዲዎች ናቸው፡፤'),
('11:20', 87, 'እነዚያ በምድር ውስጥ (ከአላህ) የሚያመልጡ አልነበሩም፡፡ ከአላህም ሌላ ለእነርሱ ረዳቶች አልነበሯቸውም፡፡ ለእነሱ ቅጣቱ ይደራረብላቸዋል፡፡ (እውነትን) መስማትን የሚችሉ አልነበሩም የሚያዩም አልነበሩም፡፡'),
('11:21', 87, 'እነዚያ እነርሱ ነፍሶቻቸውን ያከሰሩ ከእነሱም ይቀጣጥፉት የነበሩት ነገር የጠፋቸው ናቸው፡፡'),
('11:22', 87, 'እነርሱ በመጨረሻይቱ ዓለም በጣም ከሳሪዎቹ እነሱ መሆናቸው ጥርጥር የለውም፡፡'),
('11:23', 87, 'እነዚያ ያመኑትና በጎ ሥራዎችን የሠሩት ወደ ጌታቸውም የተዋረዱት እነዚያ የገነት ሰዎች ናቸው፡፡ እነሱ በውስጧ ዘላለም ዘውታሪዎች ናቸው፡፡'),
('11:24', 87, 'የሁለቱ ክፍሎች ምሳሌ እንደ ዕውርና እንደ ደንቆሮ እንደሚያይና እንደሚሰማም ብጤ ነው፡፡ በምሳሌ ይተካከላሉን አትገሰጹምን'),
('11:25', 87, 'ኑሕንም ወደ ሕዝቦቹ በእርግጥ ላክን፡፡ (አላቸውም)፡- «እኔ ለእናንተ ግልጽ አስፈራሪ (አስጠንቃቂ) ነኝ፡፡»'),
('11:26', 87, '«አላህን እንጂ ሌላን አትገዙ፡፡ እኔ በእናንተ ላይ የአሳማሚን ቀን ቅጣት እፈራላችኋለሁና፡፡»'),
('11:27', 87, 'ከሕዝቦቹም እነዚያ የካዱት መሪዎቹ ብጤያችን ሰው ሆነህ እንጂ አናይህም፡፡ እነዚያም እነሱ ሐሳበ ጥሬዎች የሆኑት ወራዶቻችን እንጂ ሌላ ተከትሎህ አናይህም፡፡ ለእናንተም በእኛ ላይ ምንም ብልጫን አናይም፡፡ ከቶውንም ውሸታሞች መሆናችሁን እንጠረጥራችኋለን አሉ፡፡'),
('11:28', 87, '«ሕዝቦቼ ሆይ! ንገሩኝ ከጌታዬ በግልጽ ማስረጃ ላይ ብሆን ከእርሱም ዘንድ የሆነን ችሮታ (ነብይነት) ቢሰጠኝና በእናንተ ላይ ብትደበቅባችሁ እናንተ ለርቯ ጠይዎች ስትሆኑ እርቯን (በመቀበል) እናስገድዳችኋለን» አላቸው፡፡'),
('11:29', 87, '«ሕዝቦቼም ሆይ! በርሱ (በተላክሁበት ማድረስ) ላይ ገንዘብን አልጠይቃችሁም፡፡ ምንዳዬ በአላህ ላይ እንጂ በሌላ ላይ አይደለም፡፡ እኔም እነዚያን ያመኑትን አባራሪ አይደለሁም፡፡ እነርሱ ጌታቸውን የሚገናኙ ናቸውና፡፡ ግን እኔም የምትሳሳቱ ሕዝቦች ሆናችሁ አያችኋለሁ፡፡»'),
('11:30', 87, '«ሕዝቦቼም ሆይ ባባርራቸው ከአላህ (ቅጣት) የሚያድነኝ ማን ነው አትገሰጹምን»'),
('11:31', 87, '«ለእናንተም እኔ ዘንድ የአላህ ግምጃ ቤቶች አልሉ ሩቅንም ዐውቃለሁ አልላችሁም፡፡ እኔም መልአክ ነኝ አልላችሁም፡፡ ለእነዚያም ዓይኖቻችሁ ለሚያዋርዷቸው አላህ ደግ ነገርን (እምነትን) አይሰጣቸውም አልልም፡፡ አላህ በነፍሶቻቸው ውስጥ ያለውን ነገር አዋቂ ነው፡፡ እኔ ያን ጊዜ ከበደለኞች እሆናለሁና» (አላቸው)፡፡'),
('11:32', 87, '«ኑህ ሆይ! በእርግጥ ተከራከርከን፡፡ እኛን መከራከርህንም አበዛኸው፡፡ ከእውነተኞቹም እንደሆንክ የምታስፈራራብንን ቅጣት አምጣው» አሉ፡'),
('11:33', 87, '«እርሱን የሚያመጣባችሁ የሻ እንደ ሆነ አላህ ብቻ ነው፡፡ እናንተም የምታቅቱ አይደላችሁም» አላቸው፡፡'),
('11:34', 87, '«ለእናንተም ልመክራችሁ ብሻ አላህ ሊያጠማችሁ ሽቶ እንደ ኾነ ምክሬ አይጠቅማችሁም፡፡ እርሱ ጌታችሁ ነው፡፡ ወደ እርሱም ትመለሳላችሁ» (አላቸው)፡፡'),
('11:35', 87, '«ይልቁንም ቀጠፈው ይላሉን ብቀጥፈው ኃጢኣቴ (ቅጣቱ) በኔ ላይ ነው፡፡ እኔም ከምታጠፉት (ጥፋት) ንጹሕ ነኝ» በላቸው፡፡'),
('11:36', 87, 'ወደ ኑሕም እነሆ «ከሕዝቦችህ በእርግጥ ካመኑት በስተቀር (ወደፊት) አያምኑም፡፡ ይሠሩትም በነበሩት (ክህደት) አትዘን ማለት ተወረደ፡፡»'),
('11:37', 87, '(አላህም) «በጥበቃችንና በትእዛዛችንም ሆነህ መርከቢቱን ሥራ፡፡ በእነዚያም በበደሉት ሰዎች ነገር አታናግረኝ እነሱ በእርግጥ ሰማጮች ናቸውና» (አለው)፡፡'),
('11:38', 87, 'ከወገኖቹም መሪዎቹ በእርሱ አጠገብ ባለፉ ቁጥር ከእርሱ እየተሳለቁ መርከቢቱን ይሠራል፡፡ «ከእኛ ብትሳለቁ እኛም እንደተሳለቃችሁብን ከናንተ እንሳለቅባችኋለን» አላቸው፡፡'),
('11:39', 87, '«የሚያዋርደው ቅጣት የሚመጣበትን በእርሱም ላይ ዘውታሪ ቅጣት የሚሰፍርበት ሰው (ማን እንደ ሆነ) ወደፊት ታውቃላችሁ» (አላቸው)፡፡'),
('11:40', 87, 'ትእዛዛችንም በመጣና እቶኑም በገነፈለ ጊዜ «በእርሷ ውስጥ ከየዓይነቱ ሁሉ ሁለት ሁለት (ወንድና ሴት) ፤ ቤተሰቦችህንም ቃል ያለፈበት ብቻ ሲቀር ያመነንም ሰው ሁሉ ጫን» አልነው፡፡ ከእርሱም ጋር ጥቂቶች እንጂ አላመኑም፡፡'),
('11:41', 87, '«መሄዷም መቆሟም በአላህ ስም ነው እያላችሁም በውስጧ ተሳፈሩ፡፡ ጌታ መሓሪ አዛኝ ነውና» አላቸው፡፡'),
('11:42', 87, 'እርሷም እንደ ተራራዎች በሆነ ማዕበል ውስጥ በእነርሱ (ይዛቸው) የምትንሻለል ስትሆን (በአላህ ስም ተቀመጡባት)፡፡ ኑሕም ልጁን ከመርከቢቱ የራቀ ሆኖ ሳለ «ልጄ ሆይ! ከኛ ጋር ተሳፈር ከከሓዲዎቹም አትሁን» ሲል ጠራው፡፡'),
('11:43', 87, '(ልጁም) «ከውሃው ወደሚጠብቀኝ ተራራ እጠጋለሁ» አለ፡፡ (አባቱም)፡- «ዛሬ ከአላህ ትዕዛዝ ምንም ጠባቂ የለም (እርሱ) ያዘነለት ካልሆነ በቀር» አለው፡፡ ማዕበሉም በመካከላቸው ጋረደ፡፡ ከሰጣሚዎቹም ሆነ፡፡'),
('11:44', 87, 'ተባለም፡- «ምድር ሆይ! ውሃሽን ዋጪ፡፡ ሰማይም ሆይ (ዝናብሽን) ያዢ፡፡ ውሃውም ሰረገ፡፡ ቅጣቱም ተፈጸም፡፡ ጁዲይ በሚባልም ተራራ ላይ (መርከቢቱ) ተደላደለች፡፡ ለከሓዲዎችም ሰዎች ጥፋት ተገባቸው (ጠፉ)» ተባለ፡፡'),
('11:45', 87, 'ኑሕም ጌታውን ጠራ፡፡ አለም «ጌታዬ ሆይ! ልጄ ከቤተሰቤ ነው፡፡ ኪዳንህም እውነት ነው፡፡ አንተም ከፈራጆች ሁሉ ይበልጥ ዐዋቂ ነህ፡፡»'),
('11:46', 87, '(አላህም) «ኑሕ ሆይ! እርሱ ከቤተሰብህ አይደለም፤ እርሱ መልካም ያልሆነ ሥራ ነው፤ በርሱ ዕውቀት የሌለህንም ነገር አትጠይቀኝ፤ እኔ ከሚሳሳቱት ሰዎች እንዳትሆን እገስጽሀለሁ» አለ፡፡'),
('11:47', 87, '«ጌታዬ ሆይ! በእርሱ ለእኔ ዕውቀት የሌለኝን ነገር የምጠይቅህ ከመሆን እኔ ባንተ እጠበቃለሁ፡፡ ለእኔም ባትምረኝና ባታዝንልኝ ከከሳሪዎቹ እሆናለሁ» አለ፡፡'),
('11:48', 87, '«ኑሕ ሆይ! ከእኛ በሆነ ሰላም ባንተ ላይና አንተም ጋር ባሉት ሕዝቦች (ትውልድ) ላይ በሆኑ በረከቶችም የተጎናጸፍክ ሆነህ ውረድ፡፡ (ከእነሱው ዘሮች የሆኑ) ሕዝቦችም በቅርቢቱ ዓለም በእርግጥ እናስመቻቸዋለን፡፡ ከዚያም ከኛ የሆነ አሳማሚ ቅጣት ይነካቸዋል» ተባለ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('11:49', 87, 'ይህቺ ከሩቁ ወሬዎች ናት፡፡ ወደ አንተ እናወርዳታለን፡፡ አንተም ሕዝቦችህም ከዚህ በፊት የምታውቋት አልነበራችሁም፡፡ ታገስም፤ ምስጉን የሆነችው ፍጻሜ ለሚጠነቀቁት ናትና፡፡'),
('11:50', 87, 'ወደ ዓድም ወንድማቸውን ሁድን (ላክን)፡፡ አላቸው፡- «ወገኖቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ምንም አምላክ የላችሁም፡፡ እናንተም ቀጣፊዎች እንጂ ሌላ አይደላችሁም፡፡'),
('11:51', 87, '«ሕዝቦቼ ሆይ! በእርሱ (በማድረሴ) ላይ ምንዳን አልጠይቃችሁም፡፡ ምንዳዬ በዚህ በፈጠረኝ ላይ እንጂ በሌላ ላይ አይደለም፡፡ አታውቁምን'),
('11:52', 87, '«ሕዝቦቼም ሆይ! ጌታችሁን ምሕረትን ለምኑት፡፡ ከዚያም ወደርሱ ተጸጸቱ፡፡ ዝናብን በእናንተ ላይ ተከታታይ አድርጎ ይልክላችኋልና፡፡ ወደ ኃይላችሁም ኃይልን ይጨምርላችኋል፡፡ አመጸኞችም ሆናችሁ አትሽሹ፡፡»'),
('11:53', 87, 'አሉ፡- «ሁድ ሆይ! በአስረጅ አልመጣህልንም፡፡ እኛም ላንተ ንግግር ብለን አማልክቶቻችንን የምንተው አይደለንም፡፡ እኛም ለአንተ አማኞች አይደለንም፡፡'),
('11:54', 87, '«ከፊሎቹ አማልክቶቻችን በክፉ ነገር (በዕብደት) ለክፈውሃል እንጂ ሌላን አንልም» (አሉ)፡፡ «እኔ አላህን አስመሰክራለሁ፡፡ ከምታጋሩትም እኔ ንጹሕ መሆኔን መስክሩ» አላቸው፡፡'),
('11:55', 87, 'ከእርሱ ሌላ (አማልክትን ከምታጋሩት ንጹህ ነኝ)፡፡ ሁላችሁም ሆናችሁ ተንኮልን ሥሩብኝ፤ ከዚያም አታቆዩኝ፡፡'),
('11:56', 87, '«እኔ በጌታዬና በጌታችሁ በአላህ ላይ ተጠጋሁ፡፡ በምድር ላይ ምንም ተንቀሳቃሽ የለችም እርሱ አናትዋን የያዛት ብትሆን እንጂ፡፡ ጌታዬ (ቃሉም ሥራውም) በቀጥተኛው መንገድ ላይ ነው» (አላቸው)፡፡'),
('11:57', 87, '«ብትዞሩም በእርሱ ወደእናንተ የተላክሁበትን ነገር በእርግጥ አድርሼላችኋለሁ፡፡ ጌታዬ ከእናንተ ሌላ ሕዝብም ይተካል ምንም አትጎዱትምም፡፡ ጌታዬ በነገሩ ሁሉ ላይ ተጠባባቂ ነውና» (አላቸው)፡፡'),
('11:58', 87, 'ትዕዛዛችንም በመጣ ጊዜ ሁድንና እነዚያን ከእሱ ጋር ያመኑትን ከእኛ በሆነው ችሮታ አዳን፡፡ ከብርቱ ቅጣትም አዳናቸው፡፡'),
('11:59', 87, 'ይህች (ነገድ) ዓድ ናት፡፡ በጌታቸው ታምራት ካዱ፡፡ መልክተኞቹንም አመጹ፤ የኃያል ሞገደኛን ሁሉ ትዕዛዝም ተከተሉ፡፡'),
('11:60', 87, 'በዚህች በቅርቢቱ ዓለምም እርግማን እንዲከተላቸው ተደረጉ፡፡ በትንሣኤም ቀን (እንደዚሁ)፡፡ ንቁ! ዓዶች ጌታቸውን ካዱ፡፡ ንቁ! የሁድ ሕዝቦች ለሆኑት ዓዶች (ከእዝነት) መራቅ ይገባቸው፡፡'),
('11:61', 87, 'ወደ ሰሙዶችም ወንድማቸውን ሷሊህን (ላክን)፡፡ «ሕዝቦቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ለእናንተ አምላክ የላችሁም፡፡ እርሱ ከምድር ፈጠራችሁ፡፡ በውስጧ እንድታለሟትም አደረጋችሁ፡፡ ምሕረቱንም ለምኑት፡፡ ከዚህም ወደእርሱ ተመለሱ፡፡ ጌታዬ ቅርብ (ለለመነው) ተቀባይ ነውና» አላቸው፡፡'),
('11:62', 87, '«ሷሊህ ሆይ! ከዚህ በፊት በእኛ ውስጥ (መሪ ልትሆን) በእርግጥ የምትከጅል ነበርክ፡፡ አባቶቻችን የሚገዙትን ከመገዛት ትከለክለናለህን እኛም ወደርሱ ከምትጠራን ነገር በእርግጥ አወላዋይ በሆነ መጠራጠር ውስጥ ነን» አሉ፡፡'),
('11:63', 87, '«ሕዝቦቼ ሆይ! ንገሩኝ ከጌታዬ በሆነ ማስረጃ ላይ ብሆን ከእርሱም የሆነን ችሮታ (ነቢይነት) ቢሰጠኝና ባልታዘዘው ከአላህ (ቅጣት) የሚያድነኝ ማነው ከማሳሳትም በስተቀር ምንም አትጨምሩልኝም» አላቸው፡፡'),
('11:64', 87, 'ሕዝቦቼም ሆይ! ይህቺ ለእናንተ ተዓምር ስትሆን የአላህ ግመል ናት፡፡ ተውዋትም፡፡ በአላህ ምድር ውስጥ ትብላ፡፡ በክፉም አትንኳት፡፡ ቅርብ የሆነ ቅጣት ይይዛችኋልና» (አላቸው)፡፡'),
('11:65', 87, 'ወግተው ገደሏትም፡፡ (ሷሊህ) «በአገራችሁም ሶስትን ቀናት (ብቻ) ተጠቀሙ፡፡ ይህ የማይዋሽ ቀጠሮ ነው» አላቸው፡፡'),
('11:66', 87, 'ትዕዛዛችንም በመጣ ጊዜ ሷሊህንና እነዚያን ከሱ ጋር ያመኑትን ከእኛ በሆነው እዝነት አዳን፡፡ ከዚያም ቀን ውርደት (አዳንናቸው)፡፡ ጌታህ እርሱ ብርቱው አሸናፊው ነውና፡፡'),
('11:67', 87, 'እነዚያንም የበደሉትን ጩኸት ያዛቸው፡፡ በቤቶቻቸውም ውስጥ የተንበረከኩ ሆነው ሞተው አነጉ፡፡'),
('11:68', 87, 'በእሷ ውስጥ እንዳልኖሩባት ሆኑ፡፡ ንቁ! ሰሙዶች ጌታቸውን በእርግጥ ካዱ፡፡ ንቁ! ለሰሙዶች (ከአላህ እዝነት) መራቅ ተገባቸው፡፡'),
('11:69', 87, 'መልክተኞቻችንም ኢብራሂምን በ(ልጅ) ብስራት በእርግጥ መጡት፡፡ ሰላም አሉት፡፡ ሰላም አላቸው፡፡ ጥቂትም ሳይቆይ ወዲያውኑ የተጠበሰን የወይፈን ስጋ አመጣ፡፡'),
('11:70', 87, 'እጆቻቸውም ወደ እርሱ የማይደርሱ መኾነቸውን ባየ ጊዜ ሸሻቸው፡፡ ከነሱም ፍርሃት ተሰማው፡፡ «አትፍራ እኛ ወደ ሉጥ ሕዝቦች ተልከናልና» አሉት፡፡'),
('11:71', 87, 'ሚስቱም የቆመች ስትኾን (አትፍራ አሉት) ሳቀችም፡፡ በኢስሐቅም አበሰርናት፡፡ ከኢስሐቅም በኋላ (በልጁ) በያዕቁብ (አበሰርናት)፡፡'),
('11:72', 87, '(እርሷም) ዋልኝ! እኔ አሮጊት ይህም ባሌ ሽማግሌ ሆኖ ሳለ እወልዳለሁን ይህ በእርግጥ አስደናቂ ነገር ነው አለች፡፡'),
('11:73', 87, '«ከአላህ ትዕዛዝ ትደነቂያለሽን የአላህ ችሮታና በረከቶቹ በእናንተ በኢብራሂም ቤተሰቦች ላይ ይሁን እርሱ ምስጉን ለጋስ ነውና» አሉ፡፡'),
('11:74', 87, 'ከኢብራሂም ፍራቻው በሌደለትና ብስራት በመጣችለትም ጊዜ በሉጥ ሕዝቦች (ነገር) ይከራከረን ጀመር፡፡'),
('11:75', 87, 'ኢብራሂም በእርግጥ ታጋሽ አልቃሻ መላሳ ነውና፡፡'),
('11:76', 87, '«ኢብራሂም ሆይ! ከዚህ (ክርክር) ተው፡፡ እነሆ የጌታህ ትዕዛዝ በእርግጥ መጥቷል፡፡ እነሱም የማይመለስ ቅጣት የሚመጣባቸው ናቸው» (አሉት)፡፡'),
('11:77', 87, 'መልክተኞቻችንም ሉጥን በመጡት ጊዜ በነሱ (ምክንያት) አዘነ፡፡ ልቡም በነሱ ተጨነቀ፡፡ «ይህ ብርቱ ቀን ነውም» አለ፡፡'),
('11:78', 87, 'ሕዝቦቹም ወደርሱ እየተጣደፉ መጡት፡፡ ከዚህም በፊት መጥፎ ሥራዎችን ይሠሩ ነበር፡፡ «ሕዝቦቼ ሆይ! እኝህ ሴቶች ልጆቼ ናቸው፡፡ እነሱ ለእናንተ ይልቅ በጣም የጸዱ ናቸው፤ (አግቧቸው)፡፡ አላህንም ፍሩ፡፡ በእንግዶቼም አታሳፍሩኝ፡፡ ከእናንተ ውስጥ ቅን ሰው የለምን» አላቸው፡፡'),
('11:79', 87, '«ከሴቶች ልጆችህ ለእኛ ምንም ጉዳይ የለንም፡፡ አንተም የምንሻውን በእርግጥ ታውቃለህ» አሉት፡፡'),
('11:80', 87, '«በእናንተ ላይ ለኔ ኀይል በኖረኝ ወይም ወደ ብርቱ ወገን ብጠጋ ኖሮ (የምሠራውን በሠራሁ ነበር)» አላቸው፡፡'),
('11:81', 87, '«ሉጥ ሆይ! እኛ የጌታህ መልክተኞች ነን፡፡ (ሕዝቦችህ) ወደ አንተ (በክፉ) አይደርሱብህም፡፡ ቤተሰብህንም ይዘህ ከሌሊቱ በከፊሉ ውስጥ ሊድ፡፡ ከእናንተም አንድም (ወደኋላው) አይገላመጥ፡፡ ሚስትህ ብቻ ስትቀር፡፡ እነሆ እርሷን (እነሱን) የሚያገኛቸው ስቃይ ያገኛታልና፡፡ ቀጠሯቸው እንጋቱ ላይ ነው፡፡ ንጋቱ ቅርብ አይደለምን» አሉት፡፡'),
('11:82', 87, '|ትዕዛዛችንም በመጣ ጊዜ (ከተማይቱን) ላይዋን ከታችዋ አደረግን (ገለበጥናት)፡፡ ተከታታይም የሆነን የሸክላ ድንጋይ በርሷ ላይ አዘነብን፡፡'),
('11:83', 87, 'ከጌታህ ዘንድ ምልክት የተደረገባት ስትሆን (አዘነብናት)፡፡ እርሷም ከበደለኞቹ ሩቅ አይደለችም፡፡'),
('11:84', 87, 'ወደ መድየንም ወንድማቸውን ሹዐይብን (ላክን)፡፡ አላቸው «ሕዝቦቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ለናንተ አምላክ የላችሁም፡፡ ስፍርንና ሚዛንንም አታጉድሉ፤ እኔ በጸጋ ላይ ሆናችሁ አያችኋለሁ፡፡ እኔም በእናንተ ላይ የከባቢን ቀን ቅጣት እፈራለሁ፡፡'),
('11:85', 87, '«ሕዝቦቼም ሆይ! ስፍርንና ሚዛንን በትክክል ሙሉ፡፡ ሰዎችንም ምንም ነገራቸውን አታጉድሉባቸው፡፡ በምድርም ውስጥ አጥፊዎች ሆናችሁ አታበላሹ፡፡'),
('11:86', 87, 'አላህ ያስቀረላችሁ ለእናንተ የተሻለ ነው፡፡ ምእመናን እንደሆናችሁ (አላህ በሰጣችሁ ውደዱ)፡፡ እኔም (መካሪ እንጅ) በናንተ ላይ ተጠባባቂ አይደለሁም፡፡»'),
('11:87', 87, '«ሹዐይብ ሆይ! ስግደትህ አባቶቻችን የሚገዙትን ጣዖታት እንድንተው ወይም በገንዘቦቻችን የምንሻውን መሥራትን (እንድንተው) ታዝሃለችን አንተ በእርግጥ ታጋሹ ቅኑ አንተ ነህና» አሉት፡፡'),
('11:88', 87, '«ሕዝቦቼ ሆይ! ንገሩኝ፤ ከጌታዬ በሆነ አስረጅ ላይ ብሆንና ከእርሱም የሆነን መልካም ሲሳይ ቢሰጠኝ (በቅጥፈት ልቀላቅለው ይገባልን) ከእርሱ ወደ ከለከልኳችሁም ነገር ልለያችሁ አልሻም፡፡ በተቻለኝ ያክል ማበጀትን እንጂ አልሻም (ለደግ ሥራ) መገጠሜም በአላህ እንጂ በሌላ አይደለም፡፡ በእርሱ ላይ ተመካሁ፡፡ ወደእርሱም እመለሳለሁ፤» አላቸው፡፡'),
('11:89', 87, '«ወገኖቼም ሆይ! እኔን መከራከራችሁ የኑሕን ሕዝቦች ወይም የሁድን ሕዝቦች ወይም የሷሊሕን ሕዝቦች ያገኛቸው (ቅጣት) ብጤ እንዲያገኛችሁ አይገፋፋችሁ፡፡ የሉጥም ሕዝቦች ከእናንተ ሩቅ አይደሉም፡፡'),
('11:90', 87, '«ጌታችሁንም ምሕረትን ለምኑት፡፡ ከዚያም ወደርሱ ተመለሱ፡፡ ጌታዬ አዛኝ ወዳድ ነውና (አላቸው)፡፡'),
('11:91', 87, '«ሹዐይብ ሆይ! ከምትለው ነገር ብዙውን አናውቀውም፡፡ እኛም አንተን በእኛ ውስጥ ደካማ ሆነህ እናይሃለን፡፡ ጎሳዎችህም ባልኖሩ ኖሮ በወገርንህ ነበር፤ አንተም በእኛ ላይ የተከበርክ አይደለህም» አሉት፡፡'),
('11:92', 87, '«ሕዝቦቼ ሆይ! ጎሳዎቼ በእናንተ ላይ ከአላህ ይልቅ የከበሩ ናቸውን (አላህን) ከኋላችሁ ወደ ጀርባ አድርጋችሁም ያዛችሁት፡፡ ጌታዬ በምትሠሩት ሁሉ ከባቢ ነው» አላቸው፡፡'),
('11:93', 87, '«ሕዝቦቼም ሆይ! በችሎታችሁ ልክ ሥሩ፡፡ እኔ ሠሪ ነኝና፡፡ የሚያዋርደው ቅጣት የሚመጣበትና እርሱ ውሸታም የሆነው ማን እንደኾነ ወደ ፊት ታውቃላችሁ፡፡ ጠብቁም እኔ ከናንተ ጋር ተጠባባቂ ነኝና»(አላቸው)፡፡'),
('11:94', 87, 'ትዕዛዛችንም በመጣ ጊዜ ሹዐይብንና እነዚያን ከርሱ ጋር ያመኑትን ከእኛ በሆነው ችሮታ አዳን፡፡ እነዚያን የበደሉትንም (የጂብሪል) ጩኸት ያዘቻቸው፡፡ በቤቶቻቸውም ውስጥ ተንከፍርረው አደሩ፡፡'),
('11:95', 87, 'በእርሷ ውስጥ እንዳልነበሩ ሆኑ፡፡ ንቁ! ሰሙድ (ከአላህ እዝነት) እንደ ራቀች መድየንም ትራቅ፡፡'),
('11:96', 87, 'ሙሳንም በተዓምራታችንና በግልጽ ብርሃን በእርግጥ ላክነው፡፡'),
('11:97', 87, 'ወደ ፈርዖንና ወደ ሰዎቹ (ላክነው)፡፡ የፈርዖንንም ነገር (ሕዝቦቹ) ተከተሉ፡፡ የፈርዖን ነገርም ቀጥተኛ አልነበረም፡፡'),
('11:98', 87, 'በትንሣኤ ቀን ሕዝቦቹን ይቀድማል፡፡ ወደ እሳትም ያወርዳቸዋል፡፡ የሚገቡትም አገባብ ምንኛ ከፋ!'),
('11:99', 87, 'በዚችም (በቅርቢቱ ዓለም) እርግማንን አስከተልናቸው፡፡ በትንሣኤም ቀን (እንደዚሁ)፡፡ የተሰጡት ስጦታ ምንኛ ከፋ!'),
('11:100', 87, 'ይህ (የተነገረው) ከከተሞቹ ወሬዎች ነው፡፡ ባንተ ላይ እንተርከዋለን፡፡ ከእርሷ ፋናው የቀረና ሙሉ በሙሉ የተደመሰሰ አለ፡፡'),
('11:101', 87, 'እኛም አልበደልናቸውም፡፡ ግን ነፍሶቻቸውን በደሉ፡፡ የአላህም ትእዛዝ በመጣ ጊዜ እነዚያ ከአላህ ሌላ የሚገዙዋቸው አማልክቶቻቸው በምንም አላዳኗቸውም፡፡ ከማክሰርም በቀር ምንም አልጨመሩላቸውም፡፡'),
('11:102', 87, 'የጌታህም ቅጣት የከተሞችን ሰዎች እነሱ በዳዮች ሲሆኑ በቀጣቸው ጊዜ እንደዚህ ነው፡፡ ቅጣቱ በእርግጥ አሳማሚ ብርቱ ነው፡፡'),
('11:103', 87, 'በዚህ ውስጥ የመጨረሻውን ቀን ቅጣት ለሚፈሩ ሁሉ መገሰጫ አለ፡፡ ይህ (የትንሣኤ ቀን) ሰዎች በርሱ የሚሰበሰቡበት ቀን ነው፡፡ ይህም የሚጣዱት ቀን ነው፡፡'),
('11:104', 87, '(ይህንን ቀን) ለተቆጠረም ጊዜ እንጂ አናቆየውም፡፡'),
('11:105', 87, 'በሚመጣ ቀን ማንኛዋም ነፍስ በእርሱ ፈቃድ ቢሆን እንጂ አትናገርም፡፡ ከነሱም መናጢና ዕድለኛም አልለ፡፡'),
('11:106', 87, 'እነዚያ መናጢ የሆኑትማ፡ በእሳት ውስጥ ናቸው፡፡ ለእነርሱ በእርሷ ውስጥ ማናፋትና መንሰቅሰቅ አላቸው፡፡'),
('11:107', 87, 'ጌታህ ከሻው (ጭማሬ) ሌላ ሰማያትና ምድር እስከ ዘወተሩ ድረስ በውስጧ ዘውተሪዎች ሲኾኑ (በእሳት ይኖራሉ)፡፡ ጌታህ የሚሻውን ሠሪ ነውና፡፡'),
('11:108', 87, 'እነዚያም ዕድለኞቹማ ጌታህ ከሻው (ጭማሬ) ሌላ ሰማያትና ምድር እስከ ዘወተሩ ድረስ በውስጧ ዘውታሪዎች ኾነው በገነት ውስጥ ይኖራሉ፡፡ የማይቋረጥ ስጦታን ተሰጡ፡፡'),
('11:109', 87, 'እነዚህ (ከሓዲዎች) ከሚገዙት ጣዖት በመጠራጠር ውስጥ አትሁን፤ አባቶቻቸው ከዚህ በፊት እንደሚግገዙት እንጂ አይግገዙም፡፡ እኛም (እነዚህን) ፈንታቸውን የማይጓደል ሲሆን የምንሞላላቸው ነን፡፡'),
('11:110', 87, 'ለሙሳም መጽሐፍን በእርግጥ ሰጠነው፡፡ በእርሱም ተለያዩበት፡፡ ከጌታህም ያለፈች ቃል ባልነበረች ኖሮ በመካከላቸው (አሁን) ይፈረድ ነበር፡፡ እነሱም ከእርሱ (ከቁርኣን) አወላዋይ በሆነ መጠራጠር ውስጥ ናቸው፡፡'),
('11:111', 87, 'ሁሉንም ጌታህ ሥራዎቻቸውን (ምንዳቸውን) በእርግጥ ይሞላላቸዋል፡፡ እርሱ በሚሠሩት ሁሉ ውስጠ ዐዋቂ ነውና፡፡'),
('11:112', 87, 'እንደ ታዘዝከውም ቀጥ በል፡፡ ከአንተ ጋር ያመኑትም (ቀጥ ይበሉ)፡፡ ወሰንንም አትለፉ፤ እርሱ የምትሠሩትን ሁሉ ተመልካች ነውና፡፡'),
('11:113', 87, 'ወደእነዚያም ወደ በደሉት አትጠጉ፡፡ እሳት ትነካችኋለችና፡፡ ከአላህም ሌላ ጠባቂዎች የሏችሁም፡፡ ከዚያም አትረድዱም፡፡'),
('11:114', 87, 'ሶላትንም በቀን ጫፎች ከሌሊትም ክፍሎች ፈጽም፡፡ መልካም ሥራዎች ኀጢአቶችን ያስወገድዳሉና፡፡ ይህ ለተገሳጮች ግሳጼ ነው፡፡'),
('11:115', 87, 'ታገስም፤ አላህ የበጎ ሠሪዎችን ምንዳ አያጠፋምና፡፡'),
('11:116', 87, 'ከእናንተም በፊት ከነበሩት ከክፍለ ዘመናት ሰዎች ውስጥ በምድር ላይ ከማበላሸት የሚከለክሉ የመልካም ቀሪ ሥራዎች ባለቤቶች ለምን አልነበሩም ግን ከእነሱ ያዳንናቸው ጥቂቶቹ (ከለከሉና ዳኑ)፡፡ እነዚያም የበደሉት ሰዎች (አልከለከሉም)፡፡ በእርሱ የተቀማጠሉበትን ተድላ ተከተሉ፡፡ አመጸኞችም ነበሩ፡፡'),
('11:117', 87, 'ጌታህም ከተሞችን ባለቤቶቻቸው መልካም ሠሪዎች ሆነው ሳሉ በመበደል የሚያጠፋቸው አልነበረም፡፡'),
('11:118', 87, 'ጌታህም በሻ ኖሮ ሰዎችን ሁሉ አንድ ሕዝብ ባደረጋቸው ነበር፡፡ የተለያዩም ከመሆን አይወገዱም፡፡'),
('11:119', 87, 'ጌታህ ያዘነለት ብቻ ሲቀር፤ (ከመለያየት አይወገዱም)፡፡ ለዚሁም ፈጠራቸው፡፡ የጌታህም ቃል ገሀነምን ከአጋንንትና ከሰዎች ከሁሉም በእርግጥ እሞላታለሁ በማለት ተፈጸመች፡፡'),
('11:120', 87, 'ከመልክተኞቹም ዜናዎች (ተፈላጊውን) ሁሉንም ልብህን በርሱ የምናረካበትን እንተርክልሃለን፡፡ በዚህችም (ሱራ) እውነቱ ነገር ለምእምናን ግሳጼና ማስታወሻ መጥቶልሃል፡፡'),
('11:121', 87, 'ለእነዚያም ለማያምኑት ባላችሁበት ሁኔታ ላይ ሥሩ፤ እኛ ሠሪዎች ነንና በላቸው፡፡'),
('11:122', 87, 'ተጠባበቁም እኛ ተጠባባቂዎች ነንና (በላቸው)፡፡'),
('11:123', 87, 'በሰማያትና በምድርም ያለው ምስጢር ሁሉ የአላህ ነው፡፡ ነገሩ ሁሉም ወደርሱ ይመለሳል፡፡ ስለዚህ ተገዛው፡፡ በእርሱም ላይ ተጠጋ፡፡ ጌታህም ከሚሠሩት ሁሉ ዘንጊ አይደለም፡፡'),
('12:1', 87, 'አ.ለ.ረ (አሊፍ ላም ራ) እነዚህ የገላጩ መጽሐፍ አንቀጾች ናቸው፡፡'),
('12:2', 87, 'እኛ (ፍቹን) ታውቁ ዘንድ ዐረብኛ ቁርኣን ሲሆን በእርግጥ አወረድነው፡፡'),
('12:3', 87, 'እኛ ይህንን ቁርኣን ወደ አንተ በማውረዳችን በጣም መልካም ዜናዎችን በአንተ ላይ እንተርክልሃለን፡፡ እነሆ ከእርሱ በፊት (ካለፉት ሕዝቦች ታሪክ) በእርግጥ ከዘንጊዎቹ ነበርክ፡፡'),
('12:4', 87, 'ዩሱፍ ለአባቱ፡- «አባቴ ሆይ! እኔ ዐስራ አንድ ከዋክብትን ፀሐይንና ጨረቃንም (በሕልሜ) አየሁ፡፡ ለእኔ ሰጋጆች ሆነው አየኋቸው» ባለ ጊዜ (አስታውስ)፡፡'),
('12:5', 87, '(አባቱም) አለ «ልጄ ሆይ! ሕልምህን ለወንድሞችህ አታውራ፡፡ ላንተ ተንኮልን ይሰሩብሃልና፡፡ ሰይጣን ለሰው ግልጽ ጠላት ነውና፡፡»'),
('12:6', 87, '«እንደዚሁም (እንዳየኸው) ጌታህ ይመርጥሃል፡፡ ከንግግሮችም ፍች ያስተምርሃል፡፡ ጸጋውንም ከአሁን በፊት በሁለቱ አባቶችህ በኢብራሂምና በኢስሐቅ ላይ እንዳሟላት በአንተ ላይና በያዕቆብ ዘሮችም ላይ ይሞላታል፡፡ ጌታህ ዐዋቂ ጥበበኛ ነውና፡፡»'),
('12:7', 87, 'በዩሱፍና በወንድሞቹ (ታሪኮች) ውስጥ ለጠያቂዎች ሁሉ በእርግጥ አስደናቂ ምልክቶች ነበሩ፡፡'),
('12:8', 87, '(ወንድሞቹ) ባሉ ጊዜ (አስታውስ)፡፡ «እኛ ጭፍሮች ስንሆን ዩሱፍና ወንድሙ (ብንያም) ወደ አባታችን ከእኛ ይበልጥ የተወደዱ ናቸው፡፡ አባታችን በግልጽ ስህተት ውስጥ ነው፡፡'),
('12:9', 87, '«ዩሱፍን ግደሉ፡፡ ወይም በ(ሩቅ) ምድር ላይ ጣሉት፡፡ ያባታችሁ ፊት ለእናንተ የግል ይኾናልና፡፡ ከእርሱም በኋላ መልካም ሕዝቦች ትሆናላችሁና» (ተባባሉ)፡፡'),
('12:10', 87, 'ከእነሱ አንድ ተናጋሪ «ዩሱፍን አትግደሉ ግን በጉድጓድ አዘቅት ጨለማ ውስጥ ጣሉት፤ ከተጓዢዎች አንዱ ያነሳዋልና፡፡ ሠሪዎች ብትኾኑ (በዚሁ ተብቃቁ) አላቸው፡፡'),
('12:11', 87, '(እነሱም) አሉ «አባታችን ሆይ! በዩሱፍ ላይ ለምን አታምነንም እኛም ለእርሱ በእርግጥ አዛኞች ነን፡፡»'),
('12:12', 87, '«ነገ ከእኛ ጋር ላከውና ይደሰት፤ ይጫወትም፡፡ እኛም ለእርሱ ጠባቂዎች ነን፡፡»'),
('12:13', 87, '«እኔ እርሱን (ዩሱፍን) ይዛችሁ መሌዳችሁ በእርግጥ ያሳዝነኛል፡፡ እናንተም ከእርሱ ዘንጊዎች ስትሆኑ ተኩላ ይበላዋል ብዬ እፈራለሁ» አላቸው፡፡'),
('12:14', 87, '«እኛ ጭፍራዎች ሆነን ሳለን ተኩላ ቢበላውማ እኛ ያን ጊዜ በእርግጥ ከሳሪዎች ነን» አሉት፡፡'),
('12:15', 87, 'እርሱንም ይዘውት በሌዱና በጉድጓዱ ጨለማ አዘቅት ውስጥ እንዲያደርጉት በቆረጡ ጊዜ (ሐሳባቸውን ፈጸሙበት)፡፡ ወደእርሱም እነሱ የማያውቁ ሲሆኑ ይህንን ሥራቸውን በእርግጥ ትነግራቸዋለህ ስንል ላክንበት፡፡'),
('12:16', 87, 'አባታቸውንም በምሽት እያለቀሱ መጡት፡፡'),
('12:17', 87, '«አባታችን ሆይ! እኛ (ለሩጫና ለውርወራ) ልንሽቀዳደም ሌድን፡፡ ዩሱፍንም ዕቃችን ዘንድ ተውነው፡፡ ወዲያውም ተኩላ በላው፡፡ አንተም እውነተኞች ብንሆንም የምታምነን አይደለህም» አሉ፡፡'),
('12:18', 87, 'በቀሚሱም ላይ የውሸትን ደም አመጡ፡፡ (አባታቸው) «አይደለም፤ ነፍሶቻችሁ (ውሸት) ነገርን ለእናንተ ሸለሙላችሁ፡፡ ስለዚህ መልካም ትዕግስት (ማድረግ አለብኝ) በምትሉትም ነገር ላይ መታገዣው አላህ ብቻ ነው» አለ፡፡'),
('12:19', 87, 'መንገደኞችም መጡ፡፡ ውሃ ቀጂያቸውንም ላኩ፡፡ አኮሊውንም (ወደ ጉድጓዱ) ሰደደ «የምስራች! ይህ ወጣት ልጅ ነው» አለ፡፡ ሸቀጥ አድርገውም ደበቁት፡፡ አላህም የሚሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('12:20', 87, 'በርካሽ ዋጋም በሚቆጠሩ ዲርሃሞች ሸጡት፡፡ በእርሱም ከቸልተኞቹ ነበሩ፡፡'),
('12:21', 87, 'ያም ከምስር የገዛው ሰው ለሚስቱ «መኖሪያውን አክብሪ፡፡ ሊጠቅመን ወይም ልጅ አድርገን ልንይዘው ይከጀላልና» አላት፡፡ እንደዚሁም ለዩሱፍ (ገዥ ልናደርገውና) የሕልሞችንም ፍች ልናስተምረው በምድር ላይ አስመቸነው፡፡ አላህም በነገሩ ላይ አሸናፊ ነው፤ ግን አብዛኛዎቹ ሰዎች አያውቁም፡፡'),
('12:22', 87, 'ጥንካሬውንም በደረሰ ጊዜ ጥበብንና ዕውቀትን ሰጠነው፡፡ እንደዚሁም መልካም ሠሪዎችን ሁሉ እንመነዳለን፡፡'),
('12:23', 87, 'ያቺም እርሱ በቤቷ የነበረባት ሴት ከነፍሱ አባበለችው፡፡ ደጃፎቹንም ዘጋች፤ «ላንተ ተዘጋጅቼልሃለሁና ቶሎ ናም» አለችው፡፡ «በአላህ እጠበቃለሁ እርሱ (የገዛኝ) ጌታዬ ኑሮዬን ያሳመረልኝ ነውና፤ (አልከዳውም)፡፡ እነሆ! በደለኞች አይድኑም» አላት፡፡'),
('12:24', 87, 'በእርሱም በእርግጥ አሰበች፡፡ በእርሷም አሰበ፤ የጌታውን ማስረጃ ባላየ ኖሮ (የተፈጥሮ ፍላጎቱን ባረካ ነበር፤)፡፡ እንደዚሁ መጥፎ ነገርንና ኀጢአትን ከእርሱ ላይ ልንመልስለት (አስረጃችንን አሳየነው)፡፡ እርሱ ከተመረጡት ባሮቻችን ነውና፡፡'),
('12:25', 87, 'በሩንም ተሽቀዳደሙ ቀሚሱንም ከበስተኋላው ቀደደችው፡፡ ጌታዋንም (ባለቤቷን) እበሩ አጠገብ አገኙት፡፡ (ቀደም ብላ) «በባለቤትህ መጥፎን ያሰበ ሰው ቅጣቱ መታሰር ወይም አሳማሚ ስቃይ እንጂ ሌላ አይደለም» አለችው፡፡'),
('12:26', 87, '(ዩሱፍም) «እርሷ ከነፍሴ አባበለችኝ» አለ፡፡ ከቤተሰቦቿም መስካሪ (እንዲህ ሲል) መሰከረ፡፡ «ቀሚሱ ከበስተፊት ተቀድዶ እንደሆነ እውነት ተናገረች፡፡ እርሱም ከውሸታሞቹ ነው፡፡'),
('12:27', 87, '«ቀሚሱም ከበስተኋላ ተቀድዶ እንደሆነ ዋሸች፡፡ እርሱም ከእውነተኞቹ ነው፡፡»'),
('12:28', 87, 'ቀሚሱንም ከበስተኋላ ተቀድዶ ባየ ጊዜ «እርሱ (የተናገርሺው) ከተንኮላችሁ ነው (ሴቶች) ተንኮላችሁ በእርግጥ ብርቱ ነውና» አላት፡፡'),
('12:29', 87, '«ዩሱፍ ሆይ! ከዚህ (ወሬ) ተከልከል፡፡ ለኃጢአትሽም ማርታን ለምኚ፡፡ አንቺ ከስህተተኞቹ ሆነሻልና» (አለ)፡፡'),
('12:30', 87, 'በከተማው ያሉ ሴቶችም «የዐዚዝ ሚስት ብላቴናዋን ከነፍሱ ታባብለዋለች፡፡ በእውነቱ ፍቅሩ ልቧን መቷታል፡፡ እኛ በግልጽ ስህተት ውስጥ ሆና በእርግጥ እናያታለን» አሉ፡፡'),
('12:31', 87, 'ሀሜታቸውንም በሰማች ጊዜ ወደነሱ ላከችባቸው፡፡ ምግብንም ለእነርሱ አዘጋጀችላቸው፡፡ ከእነሱ ለያንዳንዳቸውም ቢላዋን ሰጠች፡፡ በእነሱም ላይ «ውጣ» አለችው፡፡ ባዩትም ጊዜ አደነቁት፡፡ እጆቻቸውንም ቆረጡ፡፡ አላህም ጥራት ይገባው፡፡ ይህ ሰው አይደለም፡፡ ይህ ያማረ መልአክ እንጅ ሌላ አይደለም አሉ፡፡'),
('12:32', 87, '«ታዲያ ይህ ያ በርሱ (ፍቅር) የዘለፋችሁኝ ነው፡፡ በእርግጥም ከነፍሱ አባበልኩት፡፡ እምቢ አለም፡፡ የማዘውንም ነገር ባይሠራ በእርግጥ ይታሰራል፡፡ ከወራዶቹም ይሆናል» አለች፡፡'),
('12:33', 87, '«ጌታዬ ሆይ! ወደርሱ ከሚጠሩኝ ነገር (ከዝሙት) ይልቅ መታሰር ለእኔ የተወደደ ነው፡፡ ተንኮላቸውንም ከእኔ ላይ ባትመልስልኝ ወደነሱ እዘነበላለሁ፡፡ ከስህተተኞቹም እሆናለሁ» አለ፡፡'),
('12:34', 87, 'ጌታውም ጸሎቱን ተቀበለው፡፡ ተንኮላቸውንም ከእርሱ መለሰለት፡፡ እነሆ! እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('12:35', 87, 'ከዚያም ማስረጃዎቹን ካዩ በኋላ እስከጊዜ ድረስ እንዲያስሩት ለነሱ ታያቸው፡፡'),
('12:36', 87, 'ከእሱም ጋር ሁለት ጎበዞች እስር ቤቱ ገቡ፡፡ አንደኛቸው «እኔ በህልሜ የወይን ጠጅን ስጠምቅ አየሁ» አለ፡፡ ሌላውም፡- «እኔ በራሴ ላይ እንጀራን ተሸክሜ ከእሱ በራሪ (አሞራ) ስትበላ አየሁ፡፡ ፍቹን ንገረን፡፡ እኛ ከአሳማሪዎች ሆነህ እናይሃለንና» አሉት፡፡'),
('12:37', 87, '(ዩሱፍም) አለ፡- «ማንኛውም የምትስሰጡት ምግብ ለናንተ ከመምጣቱ በፊት ፍቹን የምነግራችሁ ቢሆን እንጂ አይመጣላችሁም፡፡ ይኸ ጌታዬ ካሳወቀኝ ነገር ነው፤ እኔ በአላህ የማያምኑን እነርሱም መጨረሻይቱን ዓለም እነርሱ ከሓዲዎች የሆኑትን ሕዝቦች ሃይማኖት ትቻለሁ፡፡'),
('12:38', 87, '«የአባቶቼንም የኢብራሂምንና የኢስሐቅን፣ የያዕቆብንም ሃይማኖት ተከትያለሁ፡፡ ለእኛ በአላህ ምንንም ማጋራት አይገባንም ያ (አለማጋራት) በእኛ ላይና በሰዎቹ ላይ የአላህ ችሮታ ነው፡፡ ግን አብዛኞቹ ሰዎች አያመሰግኑም፡፡'),
('12:39', 87, '«የእስር ቤት ጓደኞቼ ሆይ! የተለያዩ አምላኮች ይሻላሉን ወይስ አሸናፊው አንዱ አላህ'),
('12:40', 87, '«ከእርሱ ሌላ እናንተና አባቶቻችሁ (አማልክት ብላችሁ) የጠራችኋቸውን ስሞች እንጅ አትገዝዙም፡፡ አላህ በእርሷ ምንም አስረጅ አላወረደም፡፡ ፍርዱ የአላህ እንጅ የሌላ አይደለም፡፡ እርሱን እንጅ ሌላን እንዳትገዙ አዟል፡፡ ይህ ትክክለኛው ሃይማኖት ነው፡፡ ግን አብዛኞቹ ሰዎች አያውቁም፡፡'),
('12:41', 87, '«የወህኒ ቤት ጓደኞቼ ሆይ! አንደኛችሁማ ጌታውን (ንጉሡን) ጠጅ ያጠጣል፡፡ ሌላውማ ይሰቀላል፡፡ ከራሱም በራሪ (አሞራ) ትበላለች፡፡ ያ ፍቹን የምትጠይቁት ነገር ተፈጸመ፤» (አላቸው)፡፡'),
('12:42', 87, 'ለዚያም ከሁለቱ እርሱ የሚድን መሆኑን ለተጠራጠረው እጌታህ ዘንድ አስታውሰኝ አለው፡፡ ጌታውንም ከማስታወስ ሰይጣን አስረሳው፡፡ ለጥቂት ዓመታትም በወህኒ ቤቱ ውስጥ ቆየ፡፡'),
('12:43', 87, 'ንጉሡም «እኔ ሰባትን የሰቡ ላሞች ሰባት ከሲታዎች ሲበሏቸው ሰባትንም ለምለም ዘለላዎች ሌሎችንም ደረቆችን (ሲጠመጠሙባቸው በሕልሜ) አያለሁ፡፡ እናንተ ታላላቅ ሰዎች ሆይ! ሕልምን የምትፈቱ እንደሆናችሁ ሕልሜን ፍቱልኝ» አላቸው፡፡'),
('12:44', 87, '«የሕልሞች ቅዠቶች ናቸው፡፡ እኛም የሕልሞችን ፍች ዐዋቂዎች አይደለንም» አሉት፡፡'),
('12:45', 87, 'ያም ከሁለቱ የዳነውና ከብዙ ጊዜ በኋላ (ዩሱፍን) ያስታወሰው ሰው «እኔ ፍቹን እነግራችኋለሁና ላኩኝ» አለ፤ (ወደ ዩሱፍ ሌደም)፡፡'),
('12:46', 87, '«አንተ እውነተኛው ዩሱፍ ሆይ! ሰባትን የሰቡ ላሞች ሰባት ከሲታዎች ላሞች ሲበሉዋቸው ሰባትን ለምለም ዘለላዎችም ሌሎችንም ደረቆች (በነሱ ላይ ሲጠመጠሙባቸው ያየን ሰው ሕልም ፍች) ተችልን፡፡ ያውቁ ዘንድ ወደ ሰዎቹ ልመለስ እከጅላለሁና» (አለው)፡፡'),
('12:47', 87, '(እርሱም) አለ፡- «ሰባትን የተከታተሉ ዓመታት ትዘራላችሁ፡፡ ያጨዳችሁትንም ሁሉ ከምትበሉት ጥቂት በስተቀር በዘለላው ውስጥ ተዉት፡፡'),
('12:48', 87, '«ከዚያም ከእነዚያ በኋላ ካደለባችሁት ጥቂት ሲቀር ለእነሱ ያደለባችሁትን ሁሉ የሚበሉ ሰባት የችግር ዓመታት ይመጣሉ፡፡'),
('12:49', 87, '«ከዚያም ከእነዚያ በኋላ ሰዎቹ በርሱ የሚዘነቡበት በርሱም (ወይንን) የሚጨምቁበት ዓመት ይመጣል፡፡»'),
('12:50', 87, 'ንጉሡም «እርሱን አምጡልኝ» አለ፡፡ መልክተኛውም (ዩሱፍን) በመጣው ጊዜ «ወደጌታህ ተመለስ፡፡ የዚያንም እጆቻቸውን የቆረጡትን ሴቶች ሁኔታ ጠይቀው፡፡ ጌታዬ ተንኮላቸውን ዐዋቂ ነውና» አለው፡፡'),
('12:51', 87, '(ንጉሡም)፡- «ዩሱፍን ከነፍሱ ባባበላችሁት ጊዜ ነገራችሁ ምንድን ነው» አላቸው፡፡ «ለአላህ ጥራት ይገባው፡፡ በእርሱ ላይ ምንም መጥፎን ነገር አላወቅንም» አሉት፡፡ የዐዚዝ ሚስት፡-«አሁን እውነቱ ተገለጸ፡፡ እኔ ከነፍሱ አባበልኩት፡፡ እርሱም ከእውነተኞቹ ነው» አለች፡፡'),
('12:52', 87, '(ዩሱፍ) «ይህ (ጌታዬ) ሩቅ ሆኖ ሳለ ያልከዳሁት መሆኔን አላህም የከዳተኞችን ተንኮል የማያቃና መሆኑን እንዲያውቅ ነው፤» (አለ)፡፡'),
('12:53', 87, '«ነፍሴንም (ከስሕተት) አላጠራም፡፡ ነፍስ ሁሉ ጌታዬ የጠበቃት ካልሆነች በስተቀር በመጥፎ ነገር በእርግጥ አዛዥ ናትና፡፡ ጌታዬ በጣም መሓሪ አዛኝ ነው» (አለ)፡፡'),
('12:54', 87, 'ንጉሡም «እርሱን አምጡልኝ ለራሴ ግለኛ አደርገዋለሁና» አለ፡፡ ባናገረውም ጊዜ «አንተ ዛሬ እኛ ዘንድ ባለሟል ታማኝ ነህ» አለው፡፡'),
('12:55', 87, '«በምድር ግምጃ ቤቶች ላይ (ሹም) አድርገኝ፡፡ እኔ ጠባቂ አዋቂ ነኝና» አለ፡፡'),
('12:56', 87, 'እንደዚሁም ለዩሱፍ በምድር ላይ ከእርሷ በፈለገው ስፍራ የሚሰፍር ሲሆን አስመቸነው፡፡ በችሮታችን የምንሻውን ሰው እንለያለን፡፡ የበጎ ሠሪዎችንም ዋጋ አናጠፋም፡፡'),
('12:57', 87, 'የመጨረሻይቱም ዓለም ምንዳ ለእነዚያ ላመኑትና ይጠነቀቁ ለነበሩት የበለጠ ነው፡፡'),
('12:58', 87, 'የዩሱፍ ወንድሞችም መጡ፡፡ በእርሱም ላይ ገቡ፡፡ እነሱም እርሱን የሳቱት ሲሆኑ ዐወቃቸው፡፡'),
('12:59', 87, '(ጉዳያቸውን ፈጽሞ) ስንቃቸውንም ባዘጋጀላቸው ጊዜ አለ፡- «ከአባታችሁ በኩል የሆነውን ወንድማችሁን አምጡልኝ፡፡ እኔ ከአስተናጋጆች ሁሉ በላጭ ስሆን፤ ስፍርን የምሞላ መሆኔን አታዩምን'),
('12:60', 87, 'እርሱንም ባታመጡልኝ እኔ ዘንድ ለእናንተ ስፍር የላችሁም፤ አትቀርቡኝምም፡፡»'),
('12:61', 87, '«ስለእርሱ አባቱን በጥብቅ እንጠይቃለን፡፡ እኛም (ይህንን) በእርግጥ ሠሪዎች ነን» አሉት፡፡'),
('12:62', 87, 'ለአሽከሮቹም «ሸቀጣቸውን ወደ ቤተሰቦቻቸው በተመለሱ ጊዜ ያውቋት ዘንድ በየጓዞቻቸው ውስጥ አድርጉላቸው፡፡ ሊመለሱ ይከጀላልና» አላቸው፡፡'),
('12:63', 87, 'ወደ አባታቸውም በተመሰሉ ጊዜ፡- «አባታችን ሆይ! (ወንድማችንን እስከምንወስድ) ስፍር ከእኛ ተከልክሏል፡፡ ስለዚህ ወንድማችንን ከእኛ ጋር ላከው፡፡ ይሰፍርልናልና እኛም ለርሱ ጠባቂዎች ነን» አሉ፡፡'),
('12:64', 87, '«ከአሁን በፊት በወንድሙ ላይ እንዳመንኳችሁ እንጂ በእርሱ ላይ አምናችኋለሁን አላህም በጠባቂነት (ከሁሉ) የበለጠ ነው፡፡ እርሱም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነው፤» አላቸው፡፡'),
('12:65', 87, 'ዕቃቸውንም በከፈቱ ጊዜ ሸቀጣቸው ወደእነርሱ ተመልሳ አገኙ፡፡ ፡-«አባታችን ሆይ! ምን እንፈልጋለን ይህቺ ሸቀጣችን ናት፡፡ ወደኛ ተመልሳልናለች፤ (እንረዳባታለን)፡፡ ለቤተሰቦቻችንም እንሸምታለን፡፡ ወንድማችንንም እንጠብቃለን፡፡ የግመልንም ጭነት እንጨምራለን፡፡ ይህ (በንጉሡ ላይ) ቀላል ስፍር ነው» አሉ፡፡'),
('12:66', 87, '«ካልተከበባችሁ በስተቀር እርሱን በእርግጥ የምታመጡልኝ ለመሆናችሁ ከአላህ የሆነን ቃል ኪዳን መተማመኛ እስከምትሰጡኝ ድረስ ከእናንተ ጋር ፈጽሞ አልልከውም» አላቸው፡፡ መተማመኛቸውንም በሰጡት ጊዜ «አላህ በምንለው ሁሉ ላይ ምስክር ነው» አላቸው፡፡'),
('12:67', 87, 'አለም «ልጆቼ ሆይ! በአንድ በር አትግቡ፡፡ ግን በተለዩ በሮች ግቡ፡፡ ከአላህም (ፍርድ) በምንም አልጠቅማችሁም፤ (አልመልስላችሁም)፡፡ ፍርዱ የአላህ እንጅ የሌላ አይደለም፡፡ በእርሱ ላይ ተመካሁ፡፡ ተመኪዎችም ሁሉ በእርሱ ብቻ ይመኩ፡፡»'),
('12:68', 87, 'አባታቸውም ካዘዛቸው ስፍራ በገቡ ጊዜ ከአላህ (ፍርድ) ምንም ነገር ከነርሱ የሚከለክልላቸው አልነበረም፡፡ ግን በያዕቆብም ነፍስ ውስጥ የነበረች ጉዳይ ናት፡፡ ፈጸማት፡፡ እርሱም ስላሳወቅነው የዕውቀት ባለቤት ነው፤ ግን አብዛኞቹ ሰዎች አያውቁም፡፡'),
('12:69', 87, 'በዩሱፍ ላይ በገቡ ጊዜም ወንድሙን ወደርሱ አስጠጋው፡፡ «እነሆ እኔ ወንድምህ ነኝ፡፡ ይሠሩት በነበሩትም ሁሉ አትቆላጭ» አለው፡፡'),
('12:70', 87, 'ዕቃቸውንም ባዘጋጀላቸው ጊዜ፤ ዋንጫይቱን በወንድሙ ዕቃ ውስጥ አደረገ፡፡ ከዚያም «እናንተ ባለ ግመሎች ሆይ! እናንተ በእርግጥ ሌቦች ናችሁ ሲል ጠሪ ተጣራ፡፡»'),
('12:71', 87, 'ወደነሱ ዞረውም «ምንድን ጠፋችሁ» አሉ፡፡'),
('12:72', 87, '«የንጉሡ መስፈሪያ ጠፍቶናል፡፡ እርሱንም ላመጣ ሰው የግመል ጭነት አለው፡፡ እኔም በእርሱ ተያዥ ነኝ» አለ፡፡'),
('12:73', 87, '«በአላህ እንምላለን በምድር ላይ ለማጥፋት እንዳልመጣን በእርግጥ ዐውቃችኋል፡፡ ሌቦችም አልነበርንም» አሉ፡፡'),
('12:74', 87, '«ውሸታሞች ብትሆኑ ቅጣቱ ምንድን ነው» አሏቸው፡፡'),
('12:75', 87, '«ቅጣቱ (በያዕቆብ ሕግ) ዕቃው በጓዙ ውስጥ የተገኘበት ሰው (ራሱ መወሰድ) ነው፡፡ እርሱም ቅጣቱ ነው፡፡ እንደዚሁ በደለኞችን እንቀጣለን» አሉ፡፡'),
('12:76', 87, '(ምርመራውን) ከወንድሙም ዕቃ በፊት በዕቃዎቻቸው ጀመረ፡፡ ከዚያም (ዋንጫይቱን) ከወንድሙ ዕቃ ውስጥ አወጣት፡፡ እንደዚሁ ለዩሱፍ ብልሃትን አስተማርነው፡፡ አላህ ባልሻ ኖሮ በንጉሡ ሕግ ወንድሙን ሊይዝ አይገባውም ነበር፡፡ የምንሻውን ሰው በደረጃዎች ከፍ እናደርጋለን፡፡ ከዕውቀት ባለቤቶች ሁሉ በላይም ዐዋቂ አልለ፡፡'),
('12:77', 87, '«ቢሰርቅ ከአሁን በፊት የርሱው ወንድም በእርግጥ ሰርቋል» አሉ፡፡ ዩሱፍም (ይህችን ንግግር) በነፍሱ ውስጥ ደበቃት፡፡ ለእነሱም አልገለጣትም፡፡ (በልቡ) «እናንተ ሥራችሁ የከፋ ነው፡፡ አላህም የምትሉትን ሁሉ ይበልጥ ዐዋቂ ነው» አለ፡፡'),
('12:78', 87, 'አንተ የተከበርከው ሆይ! «ለእርሱ በእርግጥ ታላቅ ሽማግሌ አባት አለው፡፡ ስለዚህ በእርሱ ስፍራ አንደኛችንን ያዝ፡፡ እኛ ከመልካም ሠሪዎች ሆነህ እናይሃለንና» አሉት፡፡'),
('12:79', 87, '«ዕቃችንን እርሱ ዘንድ ያገኘንበትን ሰው እንጂ ሌላን ከመያዝ በአላህ እንጠብቃለን፡፡ እኛ ያን ጊዜ በእርግጥ በዳዮች ነን» አለ፡፡'),
('12:80', 87, 'ከርሱም ተስፋን በቆረጡ ጊዜ የሚመካከሩ ሆነው ገለል አሉ፡፡ ታላቃቸው አለ «አባታቸሁ በናንተ ላይ ከአላህ የሆነን መታመኛ ኪዳን በእርግጥ የያዘባችሁ መሆኑን ከዚህም በፊት በዩሱፍ ላይ ግፍ የሠራችሁትን አታውቁምን ስለዚህ አባቴ ለእኔ እስከሚፈቅድልኝ ወይም አላህ ለኔ እስከሚፈርድልኝ ድረስ የምስርን ምድር አልለይም፡፡ እርሱም ከፈራጆች ሁሉ በላጭ ነው፡፡'),
('12:81', 87, '«ወደ አባታችሁ ተመለሱ በሉትም፡- አባታችን ሆይ! ልጅህ ሰረቀ፡፡ ባወቅነውም ነገር እንጂ አልመሰከርንም፡፡ ሩቁንም ነገር (ምስጢሩን) ዐዋቂዎች አልነበርንም፡፡'),
('12:82', 87, '«ያችንም በውስጧ የነበርንባትን ከተማ ያችንም በውስጧ የመጣነውን ባለ ግመል ጓድ ጠይቅ፡፡ እኛም በእርግጥ እውነተኞች ነን፡፡»'),
('12:83', 87, '(ያዕቆብ) «አይደለም ነፍሶቻችሁ አንዳች ነገርን ለእናንተ ሸለሙላችሁ፡፡ (ሠራችሁትም)፡፡ መልካምም ትእግስት (ማድረግ) አለብኝ፡፡ እነርሱን (ሦስቱንም) የተሰበሰቡ ሆነው አላህ ሊያመጣልኝ ይከጀላል፡፡ እነሆ እርሱ ዐዋቂ ጥበበኛ ነውና» አላቸው፡፡'),
('12:84', 87, 'ከእነሱም ዘወር አለናኣ«በዩሱፍ ላይ ዋ ሐዘኔ!» አለ፡፡ ዓይኖቹም ከሐዘን (ለቅሶ) የተነሳ ነጡ፡፡ እርሱም በትካዜ የተመላ ነው፡፡'),
('12:85', 87, '(እነርሱም) «በአላህ እንምላለን፡፡ ለጥፋት የቀረብክ እስከምትሆን ወይም ከጠፊዎቹ እስከምትሆን ድረስ ዩሱፍን ከማውሳት አትወገድም» አሉ፡፡'),
('12:86', 87, '«ጭንቀቴንና ሐዘኔንና የማሰሙተው ወደ አላህ ብቻ ነው፡፡ ከአላህም በኩል የማታውቁትን ነገር ዐውቃለሁ» አላቸው፡፡'),
('12:87', 87, '«ልጆቼ ሆይ! ሊዱ፤ ከዩሱፍና ከወንድሙም (ወሬ) ተመራመሩ፡፡ ከአላህም እዝነት ተስፋ አትቁረጡ፡፡ እነሆ ከአላህ እዝነት ከሓዲዎች ሕዝቦች እንጂ ተስፋ አይቆርጥም» (አለ)፡፡'),
('12:88', 87, 'በእርሱም ላይ በገቡ ጊዜ «አንተ የተከበርከው ሆይ! እኛንም ቤተሰቦቻችንንም ጉዳት ደረሰብን፡፡ ርካሽ ሸቀጥም ይዘን መጥተናል፡፡ ስፍርንም ለኛ ሙላልን፡፡ በኛም ላይ መጽውት አላህ መጽዋቾችን ይመነዳልና» አሉት፡፡'),
('12:89', 87, '«እናንተ የማታውቁ በነበራችሁ ጊዜ በዩሱፍና በወንድሙ ላይ የሰራችሁትን ግፍ ዐወቃችሁን» አላቸው፡፡'),
('12:90', 87, '«አንተ በእርግጥ አንተ ዩሱፍ ነህን» አሉት፡፡ «እኔ ዩሱፍ ነኝ፡፡ ይህም ወንድሜ ነው፡፡ አላህ በኛ ላይ በእርግጥ ለገሰልን፡፡ እነሆ! የሚጠነቀቅና የሚታገስ ሰው (አላህ ይክሰዋል)፡፡ አላህ የበጎ አድራጊዎችን ዋጋ አያጠፋምና» አለ፡፡'),
('12:91', 87, '«በአላህ እንምላለን፡፡ አላህ በኛ ላይ በእርግጥ አበለጠህ፡፡ እኛም በእርግጥ አጥፊዎች ነበርን» አሉ፡፡'),
('12:92', 87, '«ዛሬ በናንተ ላይ ወቀሳ የለባችሁም፡፡ አላህ ለእናንተ ይምራል፡፡ እርሱም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነው» አላቸው፡፤'),
('12:93', 87, '«ይህንን ቀሚሴን ይዛችሁ ሊዱ፡፡ በአባቴ ፊትም ጣሉት የሚያይ ሆኖ ይመጣልና፡፡ ቤተሰቦቻችሁንም ሰብስባችሁ አምጡልኝ» (አላቸው)፡፡'),
('12:94', 87, 'ግመል ጫኞቹም (ምስርን) በተለዩ ጊዜ አባታቸው «እኔ የዩሱፍን ሽታ በእርግጥ አገኛለሁ፡፡ ባታቄሉኝ ኖሮ (ታምኑኝ ነበር)» አለ፡፡'),
('12:95', 87, '«በአላህ እንምላለን፡፡ አንተ በእርግጥ በቀድሞው ስህተትህ ውስጥ ነህ» አሉት፡፡'),
('12:96', 87, 'አብሳሪውም በመጣ ጊዜ (ቀሚሱን) በፊቱ ላይ ጣለው፡፡ ወዲውም የሚያይ ኾነ፡፡ «እኔ ለእናንተ፡- ከአላህ በኩል የማታውቁትን ዐውቃለሁ አላልኳችሁምን» አላቸው፡፡'),
('12:97', 87, '«አባታችን ሆይ! ለኀጢአቶቻችን ምሕረትን ለምንልን እኛ ጥፋተኞች ነበርንና» አሉ፡፡'),
('12:98', 87, '«ወደፊት ለእናንተ ጌታዬን ምሕረትን እለምንላችኋለሁ፡፡ እነሆ! እርሱ መሓሪው አዛኙ ነውና» አላቸው፡፤'),
('12:99', 87, 'በዩሱፍ ላይም በገቡ ጊዜ ወላጆቹን ወደርሱ አስጠጋቸው፡፡ «በአላህም ፈቃድ ጥብቆች ስትኾኑ ምስርን ግቡ» አላቸው፡፡'),
('12:100', 87, 'ወላጆቹንም በዙፋኑ ላይ አወጣቸው፡፡ ለእርሱም ሰጋጆች ኾነው ወረዱለት፡፡ «አባቴም ሆይ! ይህ ፊት ያየኋት ሕልሜ ፍች ነው፡፡ ጌታ በእርግጥ እውነት አደረጋት፡፡ ከወህኒ ቤትም ባወጣኝና ሰይጣንም በእኔና በወንድሞቼ መካከል ከአበላሸ በኋላ እናንተን ከገጠር ባመጣችሁ ጊዜ በእርግጥ ለኔ መልካም ዋለልኝ፡፡ ጌታዬ ለሚሻው ነገር እዝነቱ ረቂቅ ነው፡፡ እነሆ እሱ ዐዋቂው ጥበበኛው ነው» አለ፡፡'),
('12:101', 87, '«ጌታዬ ሆይ! ከንግሥና በእርግጥ ሰጠኸኝ፡፡ ከሕልሞችም ፍች አስተማርከኝ፡፡ የሰማያትና የምድር ፈጣሪ ሆይ! አንተ በቅርቢቱና በመጨረሻይቱ ዓለም ረዳቴ ነህ፡፡ ሙስሊም ሆኘ ግደለኝ፡፡ በመልካሞቹም አስጠጋኝ» (አለ)፡፡'),
('12:102', 87, '(ሙሐመድ ሆይ) ይህ ወዳንተ የምናወርደው ሲኾን፤ ከሩቅ ወሬዎች ነው፡፡ አንተም እነርሱ (በዩሱፍ) የሚመክሩ ኾነው ነገራቸውን በቆረጡ ጊዜ እነሱ ዘንድ አልነበርክም፡፡'),
('12:103', 87, 'አብዛኛዎቹም ሰዎች (ለማመናቸው) ብትጓጓም የሚያምኑ አይደሉም፡፡'),
('12:104', 87, 'በእርሱም (በቁርአን) ላይ ምንም ዋጋ አትጠይቃቸውም፡፡ እርሱ ለዓለማት ግሳጼ እንጂ ሌላ አይደለም፡፡'),
('12:105', 87, 'በሰማያትና በምድርም ካለችው ምልክት ብዙይቱ እነሱ ከርሷ ዘንጊዎች ኾነው በርሷ ላይ ያልፋሉ፡፡'),
('12:106', 87, 'አብዛኞቻቸውም፤ እነሱ አጋሪዎች ኾነው እንጂ በአላህ አያምኑም፡፡'),
('12:107', 87, 'ከአላህ ቅጣት ሸፋኝ አደጋ የምትመጣባቸው ወይም ሰዓቲቱ እነሱ የማያውቁ ሲኾኑ በድንገት የምትመጣባቸው መኾኑዋን አይፈሩምን'),
('12:108', 87, '«ይህች መንገዴ ናት፡፡ ወደ አላህ እጠራለሁ፡፡ እኔም የተከተለኝም ሰው በግልጽ ማስረጃ ላይ ነን፡፡ ጥራትም ለአላህ ይገባው፡፡ እኔም ከአጋሪዎቹ አይደለሁም» በል፡፡'),
('12:109', 87, 'ካንተ በፊትም ከከተሞች ሰዎች ወደነርሱ ራእይ የምናወርድላቸው የኾኑን ወንዶችን እንጂ አልላክንም፡፡ በምድር ላይ አይኼዱምና የእነዚያን ከእነሱ በፊት የነበሩትን ሰዎች መጨረሻ አይመለከቱምን የመጨረሻይቱም አገር ለእነዚያ ለተጠነቀቁት በእርግጥ የተሻለች ናት፤ አታውቁምን'),
('12:110', 87, 'መልክተኞቹም ተስፋ በቆረጡና እነርሱ በእርግጥ የተዋሹ መኾናቸውን በተጠራጠሩ ጊዜ እርዳታችን መጣላቸው፡፡ (እኛ) የምንሻውም ሰው እንዲድን ተደረገ፡፡ ቅጣታችንም ከአጋሪዎቹ ሕዝቦች ላይ አይመለስም፡፡'),
('12:111', 87, 'በታሪካቸው ውስጥ ለአእምሮ ባለ ቤቶች በእርግጥ መገሰጫ ነበረ፡፡ (ይህ ቁርኣን) የሚቀጣጠፍ ወሬ አይደለም፡፡ ግን ያንን በስተፊቱ ያለውን አረጋጋጭ ለነገርም ሁሉ ገላጭ ለሚያምኑ ሕዝቦችም መሪና ችሮታ ነው፡፡'),
('13:1', 87, 'አ.ለ.መ.ረ (አሊፍ ላም ሚም ራ) ይህች (አናቅጽ) ከመጽሐፉ አንቀጾች ናት፡፡ ያም ከጌታህ ወዳንተ የተወረደው እውነት ነው፡፡ ግን አብዛኛዎቹ ሰዎች አያምኑም፡፡'),
('13:2', 87, 'አላህ ያ ሰማያትን የምታዩዋት አዕማድ ሳትኖር ያነሳት ከዚያም በዐርሹ (ዙፋኑ) ላይ (ለሱ ክብር በሚስማማ መልኩ) የተደላደለ ፀሐይንና ጨረቃንም የገራ ነው፡፡ ሁሉም ለተወሰነ ጊዜ ይሮጣሉ፡፡ ነገሩን ሁሉ ያስተናብራል፡፡ በጌታችሁ መገናኘት ታረጋግጡ ዘንድ ተዓምራቶችን ይዘረዝራል፡፡'),
('13:3', 87, 'እርሱም ያ ምድርን የዘረጋ በሷም ተራራዎችንና ወንዞችን ያደረገ በውስጧም ከፍሬዎች ሁሉ ሁለት ሁለት ዓይነቶችን ያደረገ ነው፡፡ ሌሊትን በቀን ይሸፍናል፡፡ በዚህም ውስጥ ለሚያስተነትኑ ሕዝቦች ምልክቶች አሉ፡፡'),
('13:4', 87, 'በምድርም የተጎራበቱ ቁርጥራጮች አልሉ፡፡ ከወይኖችም አትክልቶች አዝርዕቶችም መንታዎችና መንታዎች ያልኾኑ ዘንባባዎችም አልሉ፡፡ በአንድ ውሃ ይጠጣሉ፤ (በጣዕምም ይለያያሉ)፡፡ ከፊሉዋንም በከፊሉ ላይ በሚበላው ሰብል እናበልጣለን፡፡ በዚህም ውስጥ ለሚያውቁ ሕዝቦች ተዓምራት አለበት፡፡'),
('13:5', 87, 'ብትደነቅም ዐፈር በኾንን ጊዜ እና አዲስ ፍጥረት እንኾናለን ማለታቸው (ታላቅ) ድንቅ ነው፡፡ እነዚህ እነዚያ በጌታቸው የካዱት ናቸው፡፡ እነዚህም እንዛዝላዎች በአንገቶቻቸው ላይ ያሉባቸው ናቸው፡፡ እነዚሀም የእሳት ጓዶች ናቸው፡፡ እነሱ በውስጧ ዘውታሪዎች ናቸው፡፡'),
('13:6', 87, 'ከእነሱ በፊት የመሰሎቻቸው ቅጣቶች በእርግጥ ያለፉ ሲኾኑ ከመልካሙ በፊት በመጥፎው ያስቸኩሉሃል፡፡ ጌታህም ለሰዎች ከመበደላቸው ጋር በእርግጥ የምህረት ባለቤት ነው፡፡ ጌታህም በእርግጥ ቅጣተ ብርቱ ነው፡፡'),
('13:7', 87, 'እነዚያም የካዱት በእርሱ ላይ ከጌታው ተዓምር ለምን አልተወረደለትም ይላሉ፡፡ አንተ አስፈራሪ ብቻ ነህ፡፡ ለሕዝብም ሁሉ መሪ አላቸው፡፡'),
('13:8', 87, 'አላህ ሴት ሁሉ የምታረግዘውን ያውቃል፡፡ ማሕጸኖችም የሚያጎድሉትን የሚጨምሩትንም (ያውቃል)፡፡ ነገሩም ሁሉ እርሱ ዘንድ በልክ የተወሰነ ነው፡፤'),
('13:9', 87, 'ሩቁንና ቅርቡን ዐዋቂ ታላቅ የላቀ ነው፡፡'),
('13:10', 87, 'ከእናንተ ውስጥ ቃሉን ዝቅ ያደረገ ሰው በእርሱ የጮኸም ሰው እርሱ በሌሊት ተደባቂም በቀን (ተገልጾ) ኺያጅም የኾነ ሰው (እርሱ ዘንድ) እኩል ነው፡፡'),
('13:11', 87, 'ለእርሱ (ለሰው) ከስተፊቱም ከኋላውም በአላህ ትዕዛዝ (ከክፉ) የሚጠብቁት ተተካኪዎች (መላእክት) አሉት፡፡ አላህ በሕዝቦች ዘንድ ያለውን ጸጋ በነፍሶቻቸው ያለውን (ኹኔታ) እስከሚለውጡ ድረስ አይለውጥም፡፡ አላህም በሰዎች ላይ ክፉን በሻ ጊዜ ለእርሱ መመለስ የለውም፡፡ ለእነርሱም ከእርሱ ሌላ ምንም ተከላካይ የላቸውም፡፡'),
('13:12', 87, 'እርሱ ያ የምትፈሩና የምትከጅሉም ስትሆኑ ብልጭታን የሚያሳያችሁ ከባዶች ደመናዎችንም የሚያስገኝ ነው፡፡'),
('13:13', 87, 'ነጎድጓድም አላህን በማመስገን ያጠራል፡፡ መላእክትም እርሱን ለመፍራት (ያጠሩታል)፡፡ መብረቆችንም ይልካል፡፡ እነርሱም (ከሓዲዎች) በአላህ የሚከራከሩ ሲሆኑ በእርሷ የሚሻውን ሰው ይመታል፡፡ እርሱም ኀይለ ብርቱ ነው፡፡'),
('13:14', 87, 'ለእርሱ (ለአላህ) የእውነት መጥሪያ አለው፡፡ እነዚያም ከእርሱ ሌላ የሚገዙዋቸው (ጣዖታት) ወደ አፉ ይደርስ ዘንድ ወደ ውሃ መዳፎቹን (በሩቅ ሆኖ) እንደሚዘረጋ (ሰው መልስ) እንጂ ለነርሱ በምንም አይመልሱላቸውም፡፡ እርሱም ወደ አፉ ደራሽ አይደለም፡፡ የከሓዲዎችም ጥሪ በከንቱ እንጂ አይደለም፡፡'),
('13:15', 87, 'በሰማያትና በምድርም ያሉት ሁሉ በውድም ሆነ በግድ ለአላህ ይሰግዳሉ፡ ጥላዎቻቸውም በጧቶችና በሠርኮች ይሰግዳሉ፡፡'),
('13:16', 87, '«የሰማያትና የምድር ጌታ ማን ነው» በላቸው፡፡ «አላህ ነው» በል፡፡ «ለነፍሶቻቸው ጥቅምንም ጉዳትንም የማይችሉን ረዳቶች ከርሱ ሌላ ያዛችሁን» በላቸው፡፡ «ዕውርና የሚያይ ይስተካከላሉን ወይስ ጨለማዎችና ብርሃን ይስተካከላሉን ወይስ ለአላህ እንደርሱ አፈጣጠር የፈጠሩን ተጋሪዎች አደረጉለትና ፍጥረቱ በእነሱ ላይ ተመሳሰለባቸውን» በል፤ «አላህ ሁለመናውን ፈጣሪ ነው፡፡ እርሱም አንዱ አሸናፊው ነው» በል፡፡'),
('13:17', 87, 'ከሰማይ ውሃን አወረደ፡፡ ሸለቆዎቹም በመጠናቸው ፈሰሱ፡፡ ጎርፉም አሰፋፊውን ኮረፋት ተሸከመ፡፡ ለጌጥ ወይም ለዕቃ ፍላጎት በእርሱ ላይ እሳት የሚያነዱበትም (ማዕድን) ብጤው የኾነ ኮረፋት አልለው፡፡ እንደዚሁ አላህ ለእውነትና ለውሸት ምሳሌን ያደርጋል፡፡ ኮረፋቱማ ግብስብስ ኾኖ ይጠፋል፡፡ ለሰዎች የሚጠቅመውማ በምድር ላይ ይቆያል፡፡ እንደዚሁ አላህ ምሳሌዎችን ይገልፃል፡፡'),
('13:18', 87, 'ለእነዚያ ለጌታቸው ለታዘዙት መልካም ነገር (ገነት) አልላቸው፡፡ እነዚያም ለእርሱ ያልታዘዙት ለእነሱ በምድር ያለው ሁሉ ከእርሱም ጋር ብጤው ቢኖራቸው ኖሮ በእርሱ በተበዡበት ነበር፡፡ እነዚያ ለእነሱ ክፉ ምርመራ አለባቸው፡፡ መኖሪያቸውም ገሀነም ናት፡፡ ፍራሻቸውም ከፋች!'),
('13:19', 87, 'ከጌታህ ወዳንተ የተወረደው እውነት መኾኑን የሚያውቅ ሰው እንደዚያ እርሱ ዕውር እንደኾነው ሰው ነውን የሚገሠጹት የአእምሮ ባለቤቶች ብቻ ናቸው፡፡'),
('13:20', 87, 'እነዚያ በአላህ ቃል ኪዳን የሚሞሉ የጠበቀውንም ኪዳን የማያፈርሱ ናቸው፡፡'),
('13:21', 87, 'እነዚያም አላህ እንዲቀጠል በእርሱ ያዘዘውን ነገር የሚቀጥሉ ጌታቸውንም የሚያከብሩ መጥፎንም ቁጥጥር የሚፈሩ ናቸው፡፡'),
('13:22', 87, 'እነዚያም የጌታቸውን ውዴታ ለመፈለግ የታገሱ፣ ሶላትንም አዘውትረው የሰገዱ፣ እኛ ከሰጠናቸው ሲሳይም በምስጢርም ኾነ በግልጽ የመጸወቱ፣ ክፉውንም ነገር በበጎ የሚገፈትሩ ናቸው፡፡ እነዚያ ለእነሱ መጨረሻይቱ ምስጉን አገር አለቻቸው፡፡'),
('13:23', 87, '(እርሷም) የመኖሪያ ገነቶች ናት፡፡ ይገቡባታል፡፡ ከአባቶቻቸውም፣ ከሚስቶቻቸውም፣ ከዝርያቸውም መልካም የሠራ ሰው (ይገባታል)፡፡ መላእክትም በእነርሱ ላይ ከየደጃፉ ሁሉ ይገባሉ፡፡'),
('13:24', 87, '«ሰላም ለእናንተ ይኹን፡፡ (ይህ ምንዳ) በመታገሳችሁ ነው፡፡ የመጨረሻይቱም አገር ምን ታምር!» (ይሏቸዋል)፡፡'),
('13:25', 87, 'እነዚያም የአላህን ቃል ኪዳን ከጠበቀ በኋላ የሚያፈርሱ አላህም እንዲቀጠል በእርሱ ያዘዘውን ነገር የሚቆርጡ በምድርም ላይ የሚያበላሹ እነዚያ ለነሱ እርግማን አለባቸው፡፡ ለእነሱም መጥፎ አገር (ገሀነም) አላቸው፡፡'),
('13:26', 87, 'አላህ ለሚሻው ሰው ሲሳይን ያሰፋል፤ ያጠባልም፡፡ (ከሓዲዎች) በቅርቢቱም ሕይወት ተደሰቱ፡፡ የቅርቢቱም ሕይወት በመጨረሻይቱ አንጻር (ትንሽ) መጠቀሚያ እንጂ ምንም አይደለችም፡፡'),
('13:27', 87, 'እነዚያም የካዱት «በእርሱ ላይ ከጌታው ተዓምር ለምን አልተወረደም» ይላሉ፡፡ «አላህ የሚሻውን ያጠምማል፡፡ የተመለሰውንም ሰው ወደርሱ ይመራል» በላቸው፡፡'),
('13:28', 87, '(እነሱም) እነዚያ ያመኑ ልቦቻቸውም አላህን በማውሳት የሚረኩ ናቸው፡፡ ንቁ! አላህን በማውሳት ልቦች ይረካሉ፡፡'),
('13:29', 87, 'እነዚያ ያመኑትና መልካም ሥራዎችን የሠሩት ለእነሱ ደግ ኑሮ መልካም መመለሻም አላቸው፡፡'),
('13:30', 87, 'እንደዚሁ ከበፊትዋ ብዙ ሕዝቦች በእርግጥ ያለፉ ወደኾነችው ሕዝብ እነርሱ በአልረሕማን የሚክዱ ሲኾኑ ያንን ወደ አንተ ያወረድነውን ቁርኣን በእነርሱ ላይ ታነብላቸው ዘንድ ላክንህ፡፡ «እርሱ (አልረሕማን) ጌታዬ ነው፡፡ ከእርሱ ሌላ አምላክ የለም፡፡ በርሱ ላይ ተጠጋሁ፡፡ መመለሻየም ወደርሱ ብቻ ነው» በላቸው፡፡'),
('13:31', 87, 'ቁርኣንም በእርሱ ተራራዎች በተነዱበት ወይም በእርሱ ምድር በተቆራረጠችበት ወይም በእርሱ ሙታን እንዲናገሩ በተደረጉበት ኖሮ (የመካ ከሓዲዎች ባላመኑ ነበር)፡፡ በእውነቱ ነገሩ ሁሉ የአላህ ነው፡፡ እነዚያ ያመኑት ሰዎች እነሆ አላህ በሻ ኖሮ ሰዎችን በመላ በእርግጥ ይመራቸው እንደነበረ አያውቁምን እነዚያም የካዱት በሥራቸው ምክንያት (አጥፊ) ዐደጋ የምታገኛቸው ከመኾን ወይም የአላህ ቀጠሮ እስኪመጣ በአገራቸው አቅራቢያ (አንተ) የምትሰፍርባቸው ከመኾን አይወገዱም፡፡ አላህ ቀጠሮውን አያፈርስምና፡፡'),
('13:32', 87, 'ከአንተ በፊት በነበሩትም መልክተኞች በእርግጥ ተላግጦባቸዋል፡፡ ለእነዚያም ለካዱት ጊዜን ሰጠኋቸው፡፡ ከዚያም (በቅጣት) ያዝኩዋቸው፡፡ ቅጣቴም እንዴት ነበር!'),
('13:33', 87, 'እርሱ በነፍስ ሁሉ ላይ በሠራቸው ሥራ ተጠባባቂ የኾነው (አላህ እንደዚህ እንዳልኾነው ጣዖት ብጤ ነውን) ለአላህም ተጋሪዎችን አደረጉ፡፡ ጥሯቸው «አላህን በምድር ውስጥ የማያውቀው ኖሮ ትነግሩታላችሁን ወይስ ከቃል በግልጽ (ፍቺ በሌለው ከንቱ ቃል ተጋሪዎች በማለት ትጠሩዋቸዋላችሁን)» በላቸው፡፡ በእውነቱ ለእነዚያ ለካዱት ተንኮላቸው ተሸለመላቸው፡፡ ከእውነቱ መንገድም ታገዱ፡፡ አላህም ያጠመመው ሰው ለእርሱ ምንም አቅኚ የለውም፡፡'),
('13:34', 87, 'ለእነሱ በቅርቢቱ ሕይወት ቅጣት አላቸው፡፡ የመጨረሻይቱም (ዓለም) ቅጣት በጣም የበረታ ነው፡፡ ለእነሱም ከአላህ (ቅጣት) ምንም ጠባቂ የላቸውም፡፡'),
('13:35', 87, 'ያች ጥንቁቆቹ ተስፋ የተሰጧት ገነት ምጣኔዋ (እንደሚነገራችሁ ነው)፡፡ ከሥርዋ ወንዞች ይፈስሳሉ፡፡ ምግቧ (ሁልጊዜ) የማይቋረጥ፤ ነው፡፡ ጥላዋም (እንደዚሁ)፡፡ ይህች የእነዚያ የተጠነቀቁት መጨረሻ ናት፡፡ የከሃዲዎችም መጨረሻ እሳት ናት፡፡'),
('13:36', 87, 'እነዚያም መጽሐፉን የሰጠናቸው ወዳንተ በተወረደው ይደሰታሉ፡፡ ከአሕዛብም ከፊሉን የሚክዱ ሰዎች አልሉ፡፡ «እኔ የታዘዝኩት አላህን ብቻ እንድገዛ በእርሱም እንደዳላጋራ ነው፡፡ ወደእርሱ እጠራለሁ፤ መመለሻዬም ወደእርሱ ነው» በላቸው፡፡'),
('13:37', 87, 'እንደዚሁ በዐረብኛ የተነገረ ፍትሕ ሲኾን አወረድነው፡፡ ዕውቀቱ ከመጣልህም በኋላ ዝንባሌዎቻቸውን ብትከተል ከአላህ ቅጣት ምንም ረዳትም ጠባቂም የለህም፡፡'),
('13:38', 87, 'ከአንተ በፊትም መልክተኞችን በእርግጥ ልከናል፡፡ ለእነርሱም ሚስቶችንና ልጆችን አድርገናል፡፡ ለማንኛውም መልክተኛ በአላህ ፈቃድ እንጂ ተዓምር ሊያመጣ አይገባውም፡፡ ለጊዜው ሁሉ ጽሑፍ አለው፡፡'),
('13:39', 87, 'አላህ የሚሻውን ያብሳል፤ ያጸድቃልም፡፡ የመጽሐፉ መሠረትም እርሱ ዘንድ ነው፡፡'),
('13:40', 87, 'የዚያንም ያስፈራራናቸውን ከፊሉን ብናሳይህ (መልካም ነው)፡፡ ወይም ብንገድልህ (ወቀሳ የለብህም)፡፡ በአንተ ላይ ያለብህ ማድረስ ብቻ ነው፡፡ ምርመራውም በኛ ላይ ነው፡፤'),
('13:41', 87, 'እኛ ምድርን ከጫፎችዋ የምናጎድላት ኾነን የምንመጣባት መኾናችንን አላዩምን አላህም ይፈርዳል፡፡ ለፍርዱም ገልባጭ የለውም፡፡ እርሱም ምርመራው ፈጣን ነው፡፡'),
('13:42', 87, 'እነዚያም ከእነሱ በፊት የነበሩት በእርግጥ መከሩ፡፡ አዘንግቶም የመያዙ ዘዴ በሙሉ የአላህ ነው፡፡ ነፍስ ሁሉ የምትሠራውን ያውቃል፡፡ ከሓዲዎችም የመጨረሻይቱ አገር ለማን እንደምትኾን ወደፊት ያውቃሉ፡፡'),
('13:43', 87, 'እነዚያም የካዱት ሰዎች «መልክተኛ አይደለህም» ይላሉ፡፡ «በእኔና በእናንተ መካከል መስካሪ በአላህና እርሱ ዘንድ የመጽሐፉ ዕውቀት ባለው ሰው በቃ» በላቸው፡፡'),
('14:1', 87, 'አ.ለ.ረ (አሊፍ ላም ራ፤ ይህ ቁርአን) ሰዎችን በጌታቸው ፈቃድ ከጨለማዎች ወደ ብርሃን አሸናፊ ምስጉን ወደ ኾነው፡፡ ጌታ መንገድ ታወጣ ዘንድ ወዳንተ ያወረድነው መጽሐፍ ነው፡፡'),
('14:2', 87, 'አላህ ያ በሰማያት ያለው በምድርም ያለው ሁሉ የርሱ ብቻ የኾነ ነው፤ ለከሓዲዎችም ከብርቱ ቅጣት ወዮላቸው፡፡'),
('14:3', 87, 'እነዚያ የቅርቢቱን ሕይወት ከመጨረሻይቱ ሕይወት ይበልጥ የሚወዱ ከአላህም መንገድ የሚያግዱ መጥመሟንም የሚፈልጉዋት ናቸው፡፡ እነዚያ በሩቅ ስሕተት ውስጥ ናቸው፡፡'),
('14:4', 87, 'ከመልክተኛ ማንኛውንም ለእነርሱ ያብራራላቸው ዘንድ በወገኖቹ ቋንቋ እንጂ በሌላ አልላክንም፡፡ አላህም የሚሻውን ያጠማል፡፡ የሚሻውንም ያቀናል፡፡ እርሱም አሸናፊው ጥበበኛው ነው፡፡'),
('14:5', 87, 'ሙሳንም ወገኖችህን ከጨለማዎች ወደ ብርሃን አውጣ አላህንም ቀኖች አስገንዝባቸው በማለት በተዓምራታችን በእርግጥ ላክነው፡፡ በዚህ ውስጥ በብዙ ታጋሽና በብዙ አመስጋኝ ለኾኑት ሁሉ በእርግጥ ተዓምራቶች አሉ፡፡'),
('14:6', 87, 'ሙሳም ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፤ ከፈርዖን ቤተሰቦች መጥፎን ቅጣት የሚያቀምሱዋችሁ ወንዶች ልጆቻችሁንም የሚያርዱ ሴቶቻችሁንም የሚተዉ ሲኾኑ በአዳንናችሁ ጊዜ በእናንተ ላይ (የዋለላችሁን) የአላህን ጸጋ አስታውሱ፡፡ በዚህም ከጌታችሁ የኾነ ታላቅ ፈተና አለበት፡፡'),
('14:7', 87, 'ጌታችሁም «ብታመሰግኑ በእርግጥ እጨምርላችኋለሁ ብትክዱም (እቀጣችኋለሁ) ቅጣቴ በእርግጥ ብርቱ ነውና» በማለት ባስታወቀ ጊዜ (አስታውሱ)፡፡'),
('14:8', 87, 'ሙሳም አለ «እናንተም በምድር ያለውም ሁሉ በመላ ብትክዱ አላህ በእርግጥ ተብቃቂ ምስጉን ነው፡፡»'),
('14:9', 87, 'የእነዚያ ከናንተ በፊት የነበሩት የኑሕ ሕዝቦች የዓድም የሰሙድም የእነዚያም ከእነሱ በኋለ የነበሩት ከአላህ በስተቀር ሌላ የማያውቃቸው (ሕዝቦች) ወሬ አልመጣላችሁምን መልክተኞቻቸው በማስረጃዎች መጧቸው፡፡ እጆቻቸውንም (በቁጭት ሊነክሱ) ወደ አፎቻቸው መለሱ፡፡ አሉም «እኛ እናንተ በርሱ በተላካችሁበት ነገር ካድን እኛም ወደርሱ ከምትጠሩን ነገር አወላዋይ በኾነ ጥርጣሬ ውስጥ ነን፡፡»'),
('14:10', 87, 'መልክተኞቻቸው «ከኀጢአቶቻችሁ እንዲምራችሁ ወደ ተወሰነ ጊዜም (ያለ ቅጣት) እንዲያቆያችሁ የሚጠራችሁ ሲኾን ሰማያትንና ምድርን ፈጣሪ በኾነው አላህ (በመኖሩ) ጥርጣሬ አለን» አሏቸው፡፡ (ሕዝቦቹም) «እናንተ ብጤያችን ሰው እንጂ አይደላችሁም አባቶቻችን ይገዙት ከነበሩት ልትከለክሉን ትሻላችሁ፡፡ ግልጽንም አስረጅ (ካመጣችሁት ሌላ) አምጡልን» አሉ፡፡'),
('14:11', 87, 'መልክተኞቻቸው ለእነርሱ አሉ «እኛ ብጤያችሁ ሰው እንጂ ሌላ አይደለንም ግን አላህ ከባሮቹ በሚሻው ሰው ላይ ይለግሳል፡፡ ለእኛም በአላህ ፈቃድ እንጂ ማስረጃን ልናመጣላችሁ አይገባንም፡፡ በአላህም ላይ ምእምናኖች ይጠጉ፡፡'),
('14:12', 87, '«መንገዳችንንም በእርግጥ የመራን ሲኾን በአላህ ላይ የማንመካ ለእኛ ምን አለን በማሰቃየታችሁም ላይ በእርግጥ እንታገሳለን፡፡ በአላህም ላይ ተመኪዎች ሁሉ ይመኩ፡፡»'),
('14:13', 87, 'እነዚያም የካዱት ለመልክተኞቻቸው «ከምድራችን በእርግጥ እናወጣችኋለን፤ ወይም ወደ ሃይማኖታችን በእርግጥ ትመለሳላችሁ» አሉ፡፡ ወደእነርሱም ጌታቸው እንዲህ ሲል ላከ «ከሓዲዎችን በእርግጥ እናጠፋለን፡፡'),
('14:14', 87, '«ከእነሱም በኋላ ምድሪቱን በእርግጥ እናስቀምጣችኋለን፡፡ ይኸ በፊቴ መቆሙን ለሚፈራ ዛቻዬንም ለሚፈራ ሰው ነው፡፡»'),
('14:15', 87, 'እርዳታንም (ከአላህ) ፈለጉ፤ (ተረዱም)፡፡ ጨካኝ ሞገደኛ የኾነም ሁሉ አፈረ፡፡'),
('14:16', 87, 'ከስተፊቱ ገሀነም አለበት፡፡ እዥ ከኾነም ውሃ ይጋታል፡፡'),
('14:17', 87, 'ይጎነጨዋል፤ ሊውጠውም አይቀርብም፡፡ ሞትም ከየስፍራው ሁሉ ይመጣበታል፤ እርሱም የሚሞት አይደለም፡፡ ከስተፊቱም ከባድ ቅጣት አለ፡፡'),
('14:18', 87, 'የእነዚያ በጌታቸው የካዱት ሰዎች ምሳሌ (መልካም) ሥራዎቻቸው በነፋሻ ቀን ነፋስ በርሱ እንደ በረታችበት አመድ ነው፡፡ በሠሩት ሥራ በምንም ላይ (ሊጠቀሙ) አይችሉም፡፡ ይህ እርሱ ሩቅ ጥፋት ነው፡፡'),
('14:19', 87, 'አላህ ሰማያትንና ምድርን በእውነት የፈጠረ መኾኑን አታይምን ቢሻ ያጠፋችኋል፡፡ አዲስ ፍጡርንም ያመጣል፡፡'),
('14:20', 87, 'ይህም በአላህ ላይ አስቸጋሪ አይደለም፡፡'),
('14:21', 87, 'የተሰበሰቡም ኾነው ለአላህ ይገለጻሉ፡፡ (ሐሳበ) ደካማዎቹም (ተከታዮች) ለእነዚያ ለኮሩት «እኛ ለእናንተ ተከታዮች ነበርን፤ እናንተ ከአላህ ቅጣት ከኛ ላይ አንዳችን ነገር ተከላካዮች ናችሁን» ይላሉ፡፡ (አስከታዮቹም) «አላህ ባቀናን ኖሮ በእርግጥ በመራናችሁ ነበር» ይሏቸዋል፡፡ «ብንበሳጭ ወይም ብንታገስም በእኛ ላይ እኩል ነው፡፡ ለእኛ ምንም መጠጊያ የለንም» ይላሉ፡፡'),
('14:22', 87, 'ነገሩም በተፈጸመ ጊዜ ሰይጣን ይላቸዋል «አላህ እውነተኛውን ቃል ኪዳን ገባላችሁ፡፡ ቃል ኪዳንም ገባሁላችሁ፤ አፈረስኩባችሁም፡፡ ለእኔም በእናንተ ላይ ምንም ስልጣን አልበረኝም፡፡ ግን ጠራኋችሁ፡፡ ለእኔም ታዘዛችሁ፡፡ ስለዚህ አትውቀሱኝ፤ ነፍሶቻችሁንም ውቀሱ፡፡ እኔ የምረዳችሁ አይደለሁም፡፡ እናንተም የምትረዱኝ አይደላችሁም፡፡ እኔ ከአሁን በፊት ለአላህ ተጋሪ በአደረጋችሁት ነገር ካድኩ፡፡ በዳዮቹ ለእነርሱ በእርግጥ አሳማሚ ቅጣት አላቸው፡፡»'),
('14:23', 87, 'እነዚያም ያመኑና መልካም ሥራዎችን የሠሩ ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ በጌታቸው ፈቃድ እንዲገቡ ይደረጋሉ፡፡ በውስጣቸው መከባበሪያቸው ሰላም (ለእናንተ ይኹን መባባል) ነው፡፡'),
('14:24', 87, 'አላህ መልካምን ቃል ሥርዋ (በምድር ውስጥ) የተደላደለች ቅርንጫፍዋም ወደ ሰማይ (የረዘመች) እንደሆነች መልካም ዛፍ አድርጎ ምሳሌን እንዴት እንደገለጸ አላየኽምን'),
('14:25', 87, 'ምግቧን (ፍሬዋን) በጌታዋ ፈቃድ በየጊዜው ትሰጣለች፡፡ አላህም ለሰዎች ይገሰጹ ዘንድ ምሳሌዎችን ይገልጻል፡፡'),
('14:26', 87, 'የመጥፎም ቃል ምሳሌ ከምድር በላይ የተጎለሰሰች ለእርሷ ምንም መደላደል የሌላት እንደኾነች መጥፎ ዛፍ ነው፡፡'),
('14:27', 87, 'አላህ እነዚያን ያመኑትን በቅርቢቱም ሕይወት በመጨረሻይቱም (በመቃብር) በተረጋገጠው ቃል ላይ ያረጋቸዋል፡፡ ከሓዲዎችንም አላህ ያሳስታቸዋል፡፡ አላህም የሚሻውን ይሠራል፡፡'),
('14:28', 87, 'ወደእነዚያ የአላህን ጸጋ በክህደት ወደ ለወጡት ሕዝቦቻቸውንም በጥፋት አገር ወዳሰፈሩት (ወደ ቁረይሾች) አላየህምን'),
('14:29', 87, '(አገሪቱም) የሚገቧት ስትኾን ገሀነም ናት፡፡ ምን ትከፋም መርጊያ!'),
('14:30', 87, 'ለአላህም ከመንገዱ ያሳስቱ ዘንድ ባላንጣዎችን አደረጉለት፡፡ «(ጥቂትን) ተጠቀሙ መመለሻችሁም ወደ እሳት ነው» በላቸው፡፡'),
('14:31', 87, 'ለእነዚያ ላመኑት ባሮቼ በእርሱ ውስጥ ሽያጭና ወዳጂነት የሌለበት ቀን ከመምጣቱ በፊት ሶላትን በደንቡ ይሰግዳሉ፡፡ ከሰጠናቸውም ሲሳይ በምስጢርም በግልጽም ይለግሳሉ፡፡ (ስገዱ ለግሱም) በላቸው፡፡'),
('14:32', 87, 'አላህ ያ ሰማያትንና ምድርን የፈጠረ ከሰማይም ውሃን ያወረደ በእርሱም ከፍሬዎች ሲሳይን ለእናንተ ያወጣ መርከቦችንም በፈቃዱ በባሕር ላይ ይንሻለሉ ዘንድ ለናንተ የገራ ወንዞችንም ለናንተ የገራ ነው፡፡'),
('14:33', 87, 'ፀሐይንና ጨረቃንም ዘወትር ኼያጆች ሲኾኑ ለእናንተ የገራ ሌሊትንና ቀንንም ለእናንተ የገራላችሁ ነው፡፡'),
('14:34', 87, 'ከለመናችሁትም ሁሉ የሰጣችሁ ነው፡፡ የአላህንም ጻጋ ብትቆጥሩ አትዘልቋትም፡፡ ሰው በጣም በደለኛ ከሓዲ ነው፡፡'),
('14:35', 87, 'ኢብራሂምም ባለ ጊዜ (አስታውስ) «ጌታዬ ሆይ! ይህንን አገር (መካን) ጸጥተኛ አድርገው፡፡ እኔንም ልጆቼንም ጣዖታትን ከመገዛት አርቀን፡፡'),
('14:36', 87, '«ጌታዬ ሆይ! እነርሱ (ጣዖታት) ከሰዎች ብዙዎችን አሳስተዋልና፡፡ የተከተለኝም ሰው እርሱ ከኔ ነው፡፡ ትእዛዜንም የጣሰ ሰው አንተ መሓሪ አዛኝ ነህ፡፡'),
('14:37', 87, '«ጌታችን ሆይ! እኔ አዝመራ በሌለው ሸለቆ ውስጥ በተከበረው ቤት (በካዕባ) አጠገብ ከዘሮቼ አስቀመጥኩ፡፡ ጌታችን ሆይ! ሶላትን ያቋቁሙ ዘንድ (አስቀመጥኳቸው)፡፡ ከሰዎችም ልቦችን ወደእነሱ የሚናፍቁ አድርግ፡፡ ያመሰግኑህም ዘንድ ከፍሬዎች ስጣቸው፡፡'),
('14:38', 87, '«ጌታችን ሆይ! አንተ የምንደብቀውንም የምንገልጸውንም ሁሉ በእርግጥ ታውቃለህ፡፡ በአላህም ላይ በምድርም በሰማይም ምንም ነገር አይደበቅም፡፡'),
('14:39', 87, '«ለእዚያ ከሽምግልና በኋላ ኢስማዒልን ኢስሐቅንም ለእኔ ለሰጠኝ አላህ ምሰጋና ይገባው፡፡ ጌታዬ ልመናን በእርግጥ ሰሚ ነውና፡፡'),
('14:40', 87, '«ጌታዬ ሆይ! ሰላትን አዘውትሬ የምሰግድ አድርገኝ፡፡ ከዘሮቼም (አድርግ)፡፡ ጌታችን ሆይ! ጸሎቴንም ተቀበለኝ፤'),
('14:41', 87, '«ጌታችን ሆይ! ለእኔም ለወላቼም ለምእመናንም ሁሉ ምርመራ በሚደረግበት ቀን ማር፡፡»'),
('14:42', 87, 'አላህንም በደለኞች ከሚሠሩት ግፍ ዘንጊ አድርገህ አታስብ፡፡ የሚያቆያቸው ዓይኖች በእርሱ እስከሚፈጡበት ቀን ድረስ ብቻ ነው፡፡'),
('14:43', 87, '(ወደ ጠሪው መልአክ) ቸኳዮች ራሶቻቸውን አንጋጣጮች ኾነው (ዓይኖቻቸው ይፈጣሉ)፡፡ ዓይኖቻቸው ወደነርሱ አይመለሱም፡፡ ልቦቻቸውም ባዶዎች ናቸው፡፡'),
('14:44', 87, 'ሰዎችንም ቅጣቱ የሚመጣባቸውን ቀን አስፈራራቸው፡፡ እነዚያም የበደሉት «ጌታችን ሆይ! ወደ ቅርበ ጊዜ ድረስ አቆየን፡፡ ጥሪህን እንቀበላለንና መልክተኞቹንም እንከተላለንና» ይላሉ፡፡ «ከአሁን በፊት (በምድረ ዓለም) ለእናንተ ምንም መወገድ የላችሁም በማለት የማላችሁ አልነበራችሁምን» (ይባላሉ)፡፡'),
('14:45', 87, '«በእነዚያም ነፍሶቻቸውን በበደሉት ሰዎች መኖሪያ ውስጥ ተቀመጣችሁ፡፡ በእነሱም እንዴት እንደሠራንባቸው ለእናንተ ተገለጸላችሁ፡፡ ለእናንተም ምሳሌዎችን ገለጽንላችሁ፡፡»'),
('14:46', 87, '(በነቢዩ ላይ) ሴራቸውንም በእርግጥ አሴሩ፡፡ ሴራቸውም (ቅጣቱ) አላህ ዘንድ ነው፡፡ ሴራቸውም ኮረብታዎች (ሕግጋቶች) በእርሱ የሚወገዱበት አልነበረም፡፡'),
('14:47', 87, 'አላህንም መልክተኞቹን (የገባላቸውን) ቃል ኪዳኑን አፍራሽ አድርገህ አታስብ፡፡ አላህ አሸናፊ የመበቀል ባለቤት ነው፡፡'),
('14:48', 87, 'ምድር በሌላ ምድር የምትለወጥበትን ሰማያትም (እንደዚሁ) አንድ አሸናፊ ለኾነው አላህም (ፍጡራን ሁሉ) የሚገለጹበት ቀን (አስታውሱ)፡፡'),
('14:49', 87, 'አመጸኞችንም በዚያ ቀን በሰንሰለቶች ተቆራኝተው ታያቸዋለህ፡፡'),
('14:50', 87, 'ቀሚሶቻቸው ከካትራም ናቸው፡፡ ፊቶቻቸውንም እሳት ትሸፍናቸዋለች፡፡'),
('14:51', 87, 'አላህ ነፍስን ሁሉ የሠራችውን ይመነዳ ዘንድ (ይህንን አደረገ)፡፡ አላህ ምርመራው ፈጣን ነው፡፡'),
('14:52', 87, 'ይህ (ቁርኣን) ለሰዎች ገላጭ ነው፡፡ (ሊመከሩበት)፣ በእርሱም ሊስፈራሩበት፣ እርሱም አንድ አምላክ ብቻ መኾኑን ሊያውቁበት፣ የአእምሮ ባለቤቶችም ሊገሰፁበት (የተወረደ) ነው፡፡'),
('15:1', 87, 'አ.ለ.ረ (አሊፍ ላም ራ) ይህች (አናቅጽ) ከመጽሐፉ አንቀጾችና ገላጭ ከኾነው ቁርኣን ናት፡፡'),
('15:2', 87, 'እነዚያ የካዱት (በትንሣኤ ቀን) ሙስሊሞች በኾኑ ኖሩ በብዛት ይመኛሉ፡፡'),
('15:3', 87, 'ተዋቸው ይብሉ፤ ይጠቀሙም፡፡ ተስፋም ያዘናጋቸው፡፡ በእርግጥም (መጥፎ ፍጻሜያቸውን) ያውቃሉ፡፡'),
('15:4', 87, 'ማንኛይቱንም ከተማ ለእርሷ የተወሰነ መጽሐፍ (ጊዜያት) ያላት ኾና እንጂ አላጠፋንም፡፡'),
('15:5', 87, 'ማንኛይቱም ሕዝብ ጊዜዋን ምንም አትቀድምም፡፡ (ከእርሱ) አይቆዩምም፡፡'),
('15:6', 87, '«አንተ ያ በእርሱ ላይ ቁርኣን የተወረደለት ሆይ! አንተ በእርግጥ ዕብድ ነህ» አሉም፡፡'),
('15:7', 87, '«ከእውነተኞቹ እንደ ኾንክ በመላእክት (መስካሪ) ለምን አትመጣንም» (አሉ)፡፡'),
('15:8', 87, 'መላእክትን በእውነት (በቅጣት) እንጂ አናወርድም፡፡ ያን ጊዜም የሚቆዩ አይደሉም፡፡'),
('15:9', 87, 'እኛ ቁርኣንን እኛው አወረድነው፡፡ እኛም ለእርሱ ጠባቂዎቹ ነን፡፡'),
('15:10', 87, 'ከአንተም በፊት በነበሩት በመጀመሪያዎቹ ሕዝቦች ውስጥ (መልክተኞችን) በእርግጥ ልከናል፡፡'),
('15:11', 87, 'ማንኛውም መልእክተኛ በእርሱ የሚያላግጡበት ኾነው እንጅ አይመጣቸውም ነበር፡፡'),
('15:12', 87, 'እንደዚሁ (ማስተባበልን) በአመጸኞቹ ልቦች ውስጥ እናገባዋለን፡፡'),
('15:13', 87, 'በእርሱ አያምኑበትም፡፡ የቀድሞዎቹም ድርጊት በእርግጥ አልፋለች፤ (እንደጠፉ ይጠፋሉ)፡፡'),
('15:14', 87, 'በእነርሱም ላይ ከሰማይ ደጃፍን በከፈትንላቸውና በእርሱ ሲወጡ በዋሉ ኖሮ፤'),
('15:15', 87, '«የተዘጉት ዓይኖቻችን ናቸው፡፡ እንዲያውም እኛ የተደገመብን ሰዎች ነን» ባሉ ነበር፡፡'),
('15:16', 87, 'በሰማይም ላይ ቡርጆችን በእርግጥ አድርገናል፡፡ ለተመልካቾችም (በከዋክብት) አጊጠናታል፡፡'),
('15:17', 87, 'ከተባረረ ሰይጣንም ሁሉ ጠብቀናታል፡፡'),
('15:18', 87, 'ግን (ወሬ) መስማትን የሚሰርቅ ወዲየውኑ አብሪ ችቦ ይከተለዋል፡፡ (ያቃጥለዋል)፡፡'),
('15:19', 87, 'ምድርንም ዘረጋናት፡፡ በውስጧም ኮረብታዎችን ጣልናባት፡፡ በውስጧም (የተለካን) በቃይ ሁሉ አበቀልንባት፡፡'),
('15:20', 87, 'በእርሷም ውስጥ ለእናንተ መኖሪያዎችንና ለእርሱ መጋቢዎቹ ያልኾናችሁትንም (እንስሳትን) አደረግንላችሁ፡፡'),
('15:21', 87, 'መካዚኖቹም (መክፈቻቸው) እኛ ዘንድ ያልሆነ ምንም ነገር የለም፡፡ በተወሰነም ልክ እንጂ አናወርደውም፡፡'),
('15:22', 87, 'ነፋሶችንም (ደመናን) ተሸካሚዎች አድርገን ላክን፡፡ ከሰማይም (ከደመና) ዝናብን አወረድን፡፡ እርሱንም አጠጣናችሁ፡፡ እናንተም ለእርሱ አድላቢዎች አይደላችሁም፡፡'),
('15:23', 87, 'እኛም ሕያው የምናደርግና የምንገድል እኛው ብቻ ነን፡፡ እኛም (ፍጡርን ሁሉ ) የምንወርስ (ቀሪ) ነን፡፡'),
('15:24', 87, 'ከእናንተም ተቀዳሚዎቹን በእርግጥ ዐውቀናል፡፡ ወደ ኋላም ቀሪዎቹን በእርግጥ ዐውቀናል፡፡'),
('15:25', 87, 'ጌታህም እርሱ ይሰበስባችኋል፡፡ እርሱ ጥበበኛ ዐዋቂ ነውና፡፡'),
('15:26', 87, 'ሰውንም ከሚቅጨለጨል ሸክላ ከሚገማ ጥቁር ጭቃ በእርግጥ ፈጠርነው፡፡'),
('15:27', 87, 'ጃንንም (ከሰው) በፊት ከእሳት ነበልባል ፈጠርነው፡፡'),
('15:28', 87, 'ጌታህም ለመላእክት ባለጊዜ (አስታውስ)፡፡ እኔ ሰውን ከሚቅጨለጨል ሸክላ ከሚገማ ጭቃ እፈጥራለሁ፡፡'),
('15:29', 87, '(ፍጥረቱን) ባስተካከልኩትና በውስጡ ከመንፈሴ በነፋሁበትም ጊዜ ለእርሱ ሰጋጆች ኾናችሁ ውደቁ፡፡'),
('15:30', 87, 'መላእክትም መላውም ተሰብስበው ሰገዱ፡፡'),
('15:31', 87, 'ኢብሊስ (ዲያብሎስ) ብቻ ሲቀር፡፡ ከሰጋጆቹ ጋር ከመኾን እንቢ አለ፡፡'),
('15:32', 87, '(አላህም) «ኢብሊስ ሆይ! ከሰጋጆቹ ጋር የማትኾን ላንተ ምን ምክንያት አለህ» አለው፡፡'),
('15:33', 87, '«ከሚቅጨለጨል ሸክላ ከግም ጭቃ ለፈጠርከው ሰው ልሰግድ አይገባኝም» አለ፡፡'),
('15:34', 87, '(አላህ) አለው «ከርሷም ውጣ፡፡ አንተ የተባረርክ እርጉም ነህና፡፡»'),
('15:35', 87, '«ባንተ ላይም እስከ ፍርዱ ቀን ድረስ እርግማን አለብህ፡፡»'),
('15:36', 87, '«ጌታዬ ሆይ! እንግዲውያስ (ሰዎች) እስከሚቀሰቀሱበት ቀን ድረስ አቆየኝ» አለ፡፡'),
('15:37', 87, '(አላህም) አለ «አንተ ከሚቆዩት ነህ፡፡'),
('15:38', 87, '«እስከታወቀው ወቅት ቀን ድረስ፡፡»'),
('15:39', 87, '(ኢብሊስ) አለ «ጌታዬ ሆይ! እኔን በማጥመምህ ይኹንብኝ ለነርሱ በምድር ላይ (ኀጢአትን) እሸልምላቸዋለሁ፡፡ ሁሉንም አጠማቸዋለሁም፡፡»'),
('15:40', 87, '«ከነርሱ ፍጹሞቹ ባሮችህ ብቻ ሲቀሩ፡፡»'),
('15:41', 87, '(አላህም) አለ «ይህ በእኔ ላይ (መጠበቁ የተገባ) ቀጥተኛ መንገድ ነው፡፡»'),
('15:42', 87, '«እነሆ ባሮቼ በእነሱ ላይ ላንተ ስልጣን የለህም፡፡ ከጠማሞቹ የተከተለህ ሰው ብቻ ሲቀር፡፡»'),
('15:43', 87, '«ገሀነምም (ለርሱና ለተከተሉት) ለመላውም በእርግጥ ቀጠሯቸው ናት፡፡'),
('15:44', 87, '«ለእርሷ ሰባት ደጃፎች አሏት፡፡ ለየደጀፉም ሁሉ ከእነሱ የተከፈለ ፋንታ አለ፡፡'),
('15:45', 87, '«እነዚያ (ከኀጢአት) የተጠነቀቁት በአትክልቶችና በምንጮች ውስጥ ናቸው፡፡'),
('15:46', 87, '«ጸጥተኞች ኾናችሁ በሰላም ግቧት (ይባላሉ)፡፡'),
('15:47', 87, '«ባልጋዎችም ላይ ፊት ለፊት የሚቅጣጩ ወንድማማቾች ኾነው በደረቶቻቸው ውስጥ ከቂም ያለውን ሁሉ እናስወግዳለን፡፡'),
('15:48', 87, '«በእርሷም ውስጥ ድካም አይነካቸውም፡፡ እነሱም ከእርሷ የሚወጡ አይደሉም፡፡»'),
('15:49', 87, 'ባሮቼን እኔ መሓሪው አዛኙ እኔው ብቻ መኾኔን ንገራቸው፡፡'),
('15:50', 87, 'ቅጣቴም እርሱ አሳማሚ ቅጣት መኾኑን (ንገራቸው)፡፡'),
('15:51', 87, 'ከኢብራሂም እንግዶችም (ወሬ) ንገራቸው፡፡'),
('15:52', 87, 'በእርሱ ላይ በገቡና ሰላም ባሉት ጊዜ የኾነውን (አስታውስ)፡፡ (እርሱም) «እኛ ከእናንተ ፈሪዎች ነን» አላቸው፡፡'),
('15:53', 87, '«አትፍራ፤ እኛ ዐዋቂ በኾነ ወንድ ልጅ እናበስርሃለን» አሉት፡፡'),
('15:54', 87, '«እርጅና የደረሰብኝ ከመኾኔ ጋር አበሰራችሁኝን በምን ታበስሩኛላችሁ» አለ፡፡'),
('15:55', 87, '«በእውነት አበሰርንህ፡፡ ከተሰፋ ቆራጮችም አትኹን» አሉ፡፡'),
('15:56', 87, '«ከጠማማዎችም በስተቀር ከጌታው እዝነት ተስፋን የሚቆርጥ ማነው» አለ፡፡'),
('15:57', 87, '«እናንተ መልክተኞች ሆይ! ኧረ ለመኾኑ ነገራችሁ ምንድን ነው» አለ፡፡'),
('15:58', 87, '«እኛ አመጸኞች ወደ ኾኑ ሕዝቦች ተልከናል» አሉት፡፡'),
('15:59', 87, '«የሉጥ ቤተሰቦች ብቻ ሲቀሩ፡፡ (እነርሱን) እኛ ሁላቸውንም በእርግጥ የምናድናቸው ነን፡፡'),
('15:60', 87, '«ሚስቱ ብቻ ስትቀር፡፡ እርሷን (በቅጣቱ ውስጥ) ከሚቀሩት መኾኗን ወሰነናል» (አሉ)፡፡'),
('15:61', 87, 'መልክተኞቹም የሉጥን ቤተሰቦች በመጡባቸው ጊዜ፤'),
('15:62', 87, '(ሉጥ) «እናንተ የተሳታችሁ ሕዝቦች ናችሁ» አላቸው፡፡'),
('15:63', 87, '«አይደለም እኛ ሕዝቦችህ በርሱ ይጠራጠሩበት በነበሩት ቅጣት መጣንህ» አሉት፡፡'),
('15:64', 87, '«እውነትንም ይዘን መጣንህ፡፡ እኛም በእርግጥ እውነተኞች ነን፡፡'),
('15:65', 87, 'ከቤተሰብህም ጋር በሌሊቱ ከፊል ኺድ፡፡ ከኋላቸውም ተከተል፡፡ ከእናንተም አንድም ሰው ወደ ኋላው አይገላመጥ፡፡ ወደ ታዘዛችሁበትም ስፍራ እለፉ» (አሉት)፡፡'),
('15:66', 87, 'ወደርሱም ያንን ትእዛዝ አወረድን፡፡ (እርሱም) የእነዚህ (ሕዝቦች) መጨረሻ ያነጉ ሲኾኑ (ሥራቸው) መቆረጥ ነው፡፡'),
('15:67', 87, 'የከተማይቱም ሰዎች የሚበሳሰሩ ኾነው መጡ፡፡'),
('15:68', 87, '(ሉጥም) አለ «እነዚህ እንግዶቼ ናቸውና አታጋልጡኝ፡፡'),
('15:69', 87, '«አላህንም ፍሩ፤ አታሳፍሩኝም፡፡»'),
('15:70', 87, '«ከዓለማት (ማንንም እንዳታስተናግድ) አልከለከልንህምን» አሉት፡፡'),
('15:71', 87, '(ሉጥም) «እነኝህ ሴቶች ልጆቼ ናቸው፡፡ ሠሪዎች ብትኾኑ (አግቧቸው)» አለ፡፡'),
('15:72', 87, 'በዕድሜህ እንምላለን እነሱ በእርግጥ በስከራቸው ውስጥ ይዋልላሉ፡፡'),
('15:73', 87, 'ጩኸቲቱም ፀሐይ የወጣችባቸው ሲኾኑ ያዘቻቸው፡፡'),
('15:74', 87, 'ላይዋንም ከታችዋ አደረግን፡፡ በእነሱም ላይ የሸክላ ደንጊያዎችን አዘነብንባቸው፡፡'),
('15:75', 87, 'በዚህ ውስጥ ለተመልካቾች በእርግጥ መገምገሚያዎች አሉበት፡፡'),
('15:76', 87, 'እሷም (ከተማይቱ) በቀጥታ መንገድ ላይ ናት፡፡'),
('15:77', 87, 'በዚህ ውስጥ በእርግጥ ለምእምናን መገሰጫ አለ፡፡'),
('15:78', 87, 'እነሆ የአይከት ሰዎችም በእርግጥ በዳዮች ነበሩ፤'),
('15:79', 87, 'ከነሱም ተበቀልን ሁለቱም (የሉጥና የአይከት ሕዝቦች ከተሞች) በእርግጥ በግልጽ መንገድ ላይ ናቸው፡፡'),
('15:80', 87, 'የሒጅርም ሰዎች መልክተኞቹን በእርግጥ አስተባበሉ፡፡'),
('15:81', 87, 'ተዓምራታችንንም ሰጠናቸው፡፡ ከእርሷም ዘንጊዎች ነበሩ፡፡'),
('15:82', 87, 'ከኮረብታዎችም ቤቶችን ጸጥተኞች ኾነው ይጠርቡ ነበር፡፡'),
('15:83', 87, 'ያነጉም ሲኾኑ ጩኸት ያዘቻቸው፤ (ወደሙ)፡፡'),
('15:84', 87, 'ይሠሩትም የነበሩት ሕንጻ ምንም አልጠቀማቸውም፡፡'),
('15:85', 87, 'ሰማያትንና ምድርንም በመካከላቸው ያለውንም ሁሉ በእውነት እንጂ (በላግጣ) አልፈጠርንም፡፡ ሰዓቲቱም በእርግጥ መጪ ናት፡፡ መልካምንም ይቅርታ አድርግላቸው፡፡'),
('15:86', 87, 'ጌታህ እርሱ (ያልነበረን) ፈጣሪው ዐዋቂው ነው፡፡'),
('15:87', 87, 'ከሚደጋገሙ የኾኑን ሰባትንና ታላቁንም ቁርኣን (በሙሉ) በእርግጥ ሰጠንህ፡፡'),
('15:88', 87, 'ከእነርሱ (ከከሓዲዎች) ብዙዎችን ወገኖች በእርሱ ወደ አጣቀምንበት ጸጋ ዓይኖችህን አትዘርጋ፡፡ በእነሱም ላይ (ባያምኑ) አትዘን፡፡ ክንፍህንም ለምእምናን አለዝብ፡፡'),
('15:89', 87, 'በልም «እኔ ግልጽ አስፈራሪው እኔ ነኝ፡፡»'),
('15:90', 87, '(ሰዎችን ለማገድ የመካን በሮች) በተከፋፈሉት ላይ እንደ አወረድነው (በኾነ ቅጣት አሰፈራሪያችሁ ነኝ በል)፡፡'),
('15:91', 87, '(እነርሱም) እነዚያ ቁርኣንንን ክፍልፍሎች ያደረጉ ናቸው፡፡'),
('15:92', 87, 'በጌታህም እንምላለን፡፡ ሁላቸውንም እንጠይቃቸዋለን፤'),
('15:93', 87, 'ይሠሩት ከነበሩት ነገር ሁሉ፡፡'),
('15:94', 87, 'የታዘዝክበትንም ነገር በይፋ ግለጽ፡፡ አጋሪዎችንም ተዋቸው፡፡'),
('15:95', 87, 'ተሳላቂዎችን ሁሉ እኛ በቅተንሃል፡፡'),
('15:96', 87, '(እነሱም) እነዚያ ከአላህ ጋር ሌላ አምላክን ያደረጉ ናቸው፡፡ በእርግጥም (ፍጻሜያቸውን) ወደፊት ያውቃሉ፡፡'),
('15:97', 87, 'አንተም በሚሉት ነገር ልብህ የሚጠብ መኾኑን በእርግጥ እናውቃለን፡፡'),
('15:98', 87, 'ጌታህንም ከማመስገን ጋር አጥራው ከሰጋጆቹም ኹን፡፡'),
('15:99', 87, 'እውነቱም (ሞት) እስኪመጣህ ድረስ ጌታህን ተገዛ፡፡'),
('16:1', 87, 'የአላህ ትዕዛዝ መጣ፤ ስለዚህ አታስቸኩሉት፤ ከማይገባው ሁሉ ጠራ ከሚያጋሩትም ሁሉ ላቀ፤'),
('16:2', 87, 'ከባሮቹ በሚሻው ሰው ላይ መላእክትን ከራእይ ጋር በፈቃዱ ያወርዳል (ከሓዲዎችን በቅጣት) አስጠንቅቁ፤ እነሆ ከኔ በቀር ሌላ አምላክ የለም፤ ፍሩኝም ማለትን (አስታውቁ በማለት ያወርዳል)፡፡'),
('16:3', 87, 'ሰማያትንና ምድርን በእውነት ፈጠረ ከሚያጋሩት ሁሉ ጠራ፡፡'),
('16:4', 87, 'ሰውን ከፍትወት ጠብታ ፈጠረው፡፡ ከዚያም እርሱ ወዲያውኑ (ትንሣኤን በመካድ) ግልጽ ተከራካሪ ይኾናል፡፡'),
('16:5', 87, 'ግመልን፣ ከብትን፣ ፍየልንም በርሷ (ብርድ መከላከያ) ሙቀት ጥቅሞችም ያሉባት ስትኾን ለእናንተ ፈጠረላችሁ፡፡ ከርሷም ትበላላችሁ፡፡'),
('16:6', 87, 'ለእናንተም በእርሷ ወደ ማረፊያዋ በምትመልሷት ጊዜ በምታሰማሩዋትም ጊዜ ውበት አላችሁ፡፡'),
('16:7', 87, 'ጓዞቻችሁንም በነፍሶች ችግር እንጂ ወደማትደርሱበት አገር ትሸከማለች፡፡ ጌታችሁ በእርግጥ ሩኅሩኅ አዛኝ ነውና፡፡'),
('16:8', 87, 'ፈረሶችንም፣ በቅሎዎችንም፣ አህዮችንም ልትቀመጡዋቸውና ልታጌጡባቸው (ፈጠረላችሁ)፡፡ የማታውቁትንም ድንቅ ነገር ይፈጥራል፡፡'),
('16:9', 87, 'በአላህም ላይ (በችሮታው) ቀጥተኛውን መንገድ መግለጽ አለበት፡፡ ከእርሷም (ከመንገድ) ጠማማ አልለ፡፡ በሻም ኖሮ ሁላችሁንም በእርግጥ ባቀናችሁ ነበር፡፡'),
('16:10', 87, 'እርሱ ያ ከሰማይ ውሃን ያወረደ ነው፡፡ ከእርሱ ለእናንተ መጠጥ አላችሁ፡፡ ከእርሱም (እንስሳዎችን) በእርሱ የምታሰማሩበት ዛፍ (ይበቅልበታል)፡፡'),
('16:11', 87, 'በእርሱ ለእናንተ አዝመራን፣ (የዘይት) ወይራንም፣ ዘምባባዎችንም (ተምርን)፣ ወይኖችንም፣ ከፍሬዎችም ሁሉ ያበቅልላችኋል፡፡ በዚህ ውስጥ ለሚያስተነትኑ ሕዝቦች በእርግጥ ተዓምርአልለ፡፡'),
('16:12', 87, 'ለእናንተም ሌሊትንና ቀንን፣ ፀሐይንና ጨረቃንም ገራላችሁ፡፡ ከዋክብትም በፈቃዱ የተገሩ ናቸው፡፡ በዚህ ውስጥ ለሚያውቁ ሕዝቦች በእርግጥ ተዓምራቶች አልሉ፡፡'),
('16:13', 87, 'በምድርም ላይ መልኮቹ የተለያዩ ኾኖ ለእናንተ የፈጠረላችሁን ሁሉ (ገራላችሁ)፡፡ በዚህ ውስጥ ለሚገሰጹ ሕዝቦች በእርግጥ ተዓምር አልለ፡፡'),
('16:14', 87, 'እርሱም ያ ባሕርን ከእርሱ እርጥብ ስጋን ልትበሉና ከእርሱም የምትለብሱትን ጌጣጌጥ ታወጡ ዘንድ የገራ ነው፡፡ መርከቦችንም በውስጡ (ውሃውን) ቀዳጆች ኾነው (ሲንሻለሉ) ታያለህ፡፡ ከችሮታው ልትፈልጉና ልታመሰግኑም (ገራላችሁ)፡፡'),
('16:15', 87, 'በምድርም ውስጥ በእናንተ እንዳታረገርግ ተራራዎችን ጣለባት፡፡ ጂረቶችንም፣ መንገዶችንም ትመሩ ዘንድ (አደረገ)፡፡'),
('16:16', 87, 'ምልክቶችንም (አደረገ)፡፡ በከዋክብትም እነሱ ይምመራሉ፡፡'),
('16:17', 87, 'የሚፈጥር እንደማይፈጥር ነውን አትገሰጹምን'),
('16:18', 87, 'የአላህንም ጸጋ ብትቆጥሩ አትዘልቋትም፡፡ አላህ በእርግጥ መሓሪ አዛኝ ነውና፡፡'),
('16:19', 87, 'አላህም የምትደብቁትንና የምትገልጹትን ሁሉ ያውቃል፡፡'),
('16:20', 87, 'እነዚያም ከአላህ ሌላ የምትገዟቸው ምንንም አይፈጥሩም፡፡ እነርሱም ይፈጠራሉ፤'),
('16:21', 87, 'ሕያው ያልኾኑ ሙታን ናቸው፡፡ መቼ እንደሚቀሰቀሱም አያውቁም፡፡'),
('16:22', 87, 'አምላካችሁ አንድ አምላክ ብቻ ነው፡፡ እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ልቦቻቸው ከሓዲዎች ናቸው፡፡ እነሱም የኮሩ ናቸው፤ (አያምኑም)፡፡'),
('16:23', 87, 'አላህ የሚደብቁትንና የሚገልጹትን ሁሉ የሚያውቅ ለመኾኑ ጥርጣሬ የለበትም፡፡ እርሱ ኩሩዎችን አይወድም፡፡'),
('16:24', 87, 'ለእነርሱም «ጌታችሁ (በሙሐመድ ላይ) ምንን አወረደ» በተባሉ ጊዜ «(እርሱ) የመጀመሪያዎቹ ሕዝቦች ተረቶች ነው» ይላሉ፡፡'),
('16:25', 87, '(ይህንንም የሚሉት) በትንሣኤ ቀን ኀጢኣቶቻቸውን በሙሉ ከእነዚያም ያለ ዕውቀት ኾነው ከሚያጠሟቸው ሰዎች ኀጢአቶች ከፊሉን ሊሸከሙ ነው፡፡ ንቁ! የሚሸከሙት ኃጢኣት ምንኛ ከፋ!'),
('16:26', 87, 'እነዚያ ከእነሱ (ከቁረይሾች) በፊት የነበሩት በእርግጥ መከሩ፡፡ አላህም ሕንጻዎቻቸውን ከመሠረቶቻቸው አፈረሰ፡፡ ጣሪያውም በእነሱ ላይ ከበላያቸው ወደቀባቸው፡፡ ቅጣቱም ከማያውቁት ሥፍራ መጣባቸው፡፡'),
('16:27', 87, 'ከዚያም በትንሣኤ ቀን ያዋርዳቸዋል፡፡ እነዚያም «በእነሱ (ጉዳይ) ትከራከሩኝ የነበራችሁት ተጋሪዎቼ የት ናቸው» ይላቸዋል፡፡ «እነዚያ ዕውቀትን የተሰጡት ዛሬ ሐፍረቱና ቅጣቱ በእርግጥ በከሓዲዎች ላይ ነው» ይላሉ፡፡'),
('16:28', 87, '(እነርሱ) «እነዚያ ነፍሶቻቸውን በዳይ ኾነው መላእክት የሚገድሏቸው ናቸው፡፡ ከክፉ ሥራ ምንም ነገር የምንሠራም አልነበርን» (ሲሉ) ታዛዥነታቸውን ይገልጻሉ፡፡ «በእውነት አላህ ትሰሩት የነበራችሁትን ነገር ዐዋቂ ነው» (ይባላሉ)፡፡'),
('16:29', 87, '«የገሀነምንም ደጃፎች በውስጧ ዘውታሪዎች ስትኾኑ ግቡ» (ይባላሉ)፡፡ የኩሩዎችም መኖሪያ (ገሀነም) በእርግጥ ከፋች!'),
('16:30', 87, 'ለእነዚያም ለተጠነቀቁት «ጌታችሁ ምንን ነገር አወረደ» ተባሉ፡፡ «መልካምን ነገር» አሉ፡፡ ለእነዚያ ደግ ለሠሩት በዚሀች በቅርቢቱ ዓለም መልካም ኑሮ አላቸው፡፡ የመጨረሻይቱም አገር በእርግጥ በላጭ ናት፡፡ የጥንቁቆቹም አገር ምን ታምር!'),
('16:31', 87, '(እርሷም) የሚገቡዋትና በሥርዋ ወንዞች የሚፈሱባት ስትኾን የመኖሪያ አትክልቶች ናት፡፡ ለእነሱም በወስጧ የሚሹት ሁሉ አላቸው፡፡ እንደዚሁ አላህ ጥንቁቆችን ይመነዳል፡፡'),
('16:32', 87, 'እነዚያ በመልካም ኹኔታ ላይ ኾነው መላእክት «ሰላም በእናንተ ላይ» እያሉ የሚገድሏቸው ናቸው፡፡ «ትሠሩት በነበራችሁት ሥራ ገነትን ግቡ» (ይባላሉ)፡፡'),
('16:33', 87, '(ከሓዲዎች) መላእክት ወደ እነሱ መምጣትን ወይም የጌታህ ትእዛዝ መምጣቱን እንጂ አይጠባበቁም፡፡ ከእነሱ በፊት የነበሩት እንደዚህ ሠርተዋል፡፡ አላህም አልበደላቸውም፤ ግን ነፍሶቻቸውን የሚበድሉ ነበሩ፡፡'),
('16:34', 87, 'የሠሩዋቸውም ኀጢአቶች (ቅጣት) አገኛቸው፡፡ በእርሱም ይሳለቁበት የነበሩት ሁሉ በነሱ ላይ ወረደባቸው፡፡'),
('16:35', 87, 'እነዚያም (ጣዖታትን) ያጋሩት «አላህ በሻ ኖሮ ከእርሱ ሌላ እኛም አባቶቻችንም ምንንም ባልተገዛን ነበር፤ ያለእርሱም (ትእዛዝ) ምንንም እርም ባላደረግን ነበር አሉ፡፡» እነዚያም ከነሱ በፊት የነበሩት እነደዚሁ ሠሩ፡፡ በመልክተኞቹም ላይ ግልፅ ማድረስ ብቻ እንጂ ሌላ የለባቸውም፡፡'),
('16:36', 87, 'በየሕዝቡም ሁሉ ውስጥ «አላህን ተገዙ፤ ጣዖትንም ራቁ» በማለት መልክተኛን በእርግጥ ልከናል፡፡ ከእነሱም ውስጥ አላህ ያቀናው ሰው አልለ፡፡ ከእነሱም ውስጥ በእርሱ ላይ ጥመት የተረጋገጠበት ሰው አልለ፡፡ በምድርም ላይ ኺዱ፤ የአስተባባዮችም መጨረሻ እንዴት እንደ ነበረ ተመልከቱ፡፡'),
('16:37', 87, 'በመቅናታቸው ላይ ብትጓጓ (ምንም ልታደርግ አትችልም)፡፡ አላህ የሚጠመውን ሰው አያቀናውምና፡፡ ለእነሱም ከረዳቶች ምንም የላቸውም፡፡'),
('16:38', 87, 'መሓሎቻቸውምን አላህ የሚሞትን ሰው አያስነሳም ሲሉ በአላህ ስም ማሉ፡፡ ሐሰት ነው (ያስነሳቸዋል)፡፡ በእርሱ ላይ ቃል ኪዳን ገብቷል፡፡ አረጋግጧል፤ ግን አብዛኞቹ ሰዎች አያውቁም፡፡'),
('16:39', 87, '(የሚቀሰቅሳቸውም) ለእነሱ ያንን በእርሱ የሚለያዩበትን ሊገልጽላቸው፤ እነዚያ የካዱትም እነሱ ውሸታሞች የነበሩ መኾናቸውን እንዲያውቁ ነው፡፡'),
('16:40', 87, 'ለማንኛውም ነገር (መኾኑን) በሻነው ጊዜ ቃላችን ለእርሱ «ኹን» ማለት ብቻ ነው፤ ወዲውም ይኾናል፡፡'),
('16:41', 87, 'እነዚያም ከተበደሉ በኋላ በአላህ (መንገድ ላይ) የተሰደዱት በቅርቢቱ ዓለም መልካሚቱን አገር (መዲናን) በእርግጥ እናሰፍራቸዋለን፡፡ የመጨረሻይቱም ዓለም ምንዳ ታላቅ ነው፡፡ (ከሓዲዎች) ቢያውቁ ኖሮ (በተከተሏቸው ነበር)፡፡'),
('16:42', 87, '(እነርሱ) እነዚያ የታገሱት በጌታቸውም ላይ የሚጠጉት ናቸው፡፡'),
('16:43', 87, 'ከአንተም በፊት ወደእነሱ ወሕይን (ራእይን) የምናወርድላቸውን ሰዎችን እንጂ ሌላን አልላክንም፡፡ የማታውቁም ብትኾኑ የዕውቀትን ባለቤቶች ጠይቁ፡፡'),
('16:44', 87, 'በግልጽ ማስረጃዎችና በመጻሕፍት (ላክናቸው)፡፡ ወደ አንተም ለሰዎች ወደእነሱ የተወረደውን (ፍች) ልትገልጽላቸውና ያስተነትኑም ዘንድ ቁርኣንን አወረድን፡፡'),
('16:45', 87, 'እነዚያ መጥፎዎችን የዶለቱ አላህ በእነሱ ምድርን የሚገለብጥባቸው ወይም ከማያውቁት ስፍራ ቅጣት የሚመጣባቸው መኾኑን አይፈሩምን'),
('16:46', 87, 'ወይም (ካገር ወደ አገር) በሚዛወሩበት ጊዜ የሚይዛቸው መኾኑን (አይፈሩምን) እነሱም አሸናፊዎች አይደሉም፡፡'),
('16:47', 87, 'ወይም ቀስ በቀስ በማጉደል ላይ የሚይዛቸው መኾኑን (አይፈሩምን) ጌታችሁም በእርግጥ ርኅሩኅ አዛኝ ነው፡፡'),
('16:48', 87, 'ወደዚያ ከማንኛውም ነገር አላህ ወደ ፈጠረው ጥላዎቹ እነርሱ የተዋረዱ ሲኾኑ ለአላህ ሰጋጆች ኾነው ከቀኝና ከግራዎች ወደሚዛወሩት አላዩምን'),
('16:49', 87, 'ለአላህም በሰማያት ያለው ከተንቀሳቃሽም በምድር ያለው ሁሉ፣ መላእክትም ይሰግዳሉ፡፡ እነርሱም አይኮሩም፡፡'),
('16:50', 87, 'ጌታቸውን ከበላያቸው ሲኾን ይፈሩታል፡፡ የታዘዙትንም ሁሉ ይሠራሉ፡፡'),
('16:51', 87, 'አላህም አለ «ሁለት አማልክትን አትያዙ፡፡ እርሱ አንድ አምላክ ብቻ ነው፡፡ እኔንም ብቻ ፍሩ፡፡»'),
('16:52', 87, 'በሰማያትና በምድር ያለው ሁሉ የርሱ ብቻ ነው፡፡ መገዛትም ዘወትር ሲኾን ለርሱ ብቻ ነው፡፡ ከአላህም ሌላ ያለን ትፈራላችሁን'),
('16:53', 87, 'ማንኛውም በእናንተ ላይ ያለው ጸጋ ከአላህ ነው፡፡ ከዚያም ችግር በደረሰባችሁ ጊዜ ወደርሱ ብቻ ትጮሃላችሁ፡፡'),
('16:54', 87, 'ከዚያም ከእናንተ ላይ ችግርን ባነሳላችሁ ጊዜ ከእናንተው የኾኑ ጭፍሮች ወዲያውኑ በጌታቸው (ጣዖትን) ያጋራሉ፡፡'),
('16:55', 87, '(የሚያጋሩትም) በሰጠናቸው ሊክዱ ነው፡፡ ተጠቀሙም ወደ ፊትም (የሚደርስባችሁን) በእርግጥ ታውቃላችሁ፡፡'),
('16:56', 87, 'ለማያውቁትም (ጣዖታት) ከሰጠናቸው ሲሳይ ፈንታን ያደርጋሉ፡፡ በአላህ እምላለሁ፤ ትቀጣጥፉት ከነበራችሁት ሁሉ በእርግጥ ትጠየቃላችሁ፡፡'),
('16:57', 87, 'ለአላህም (ከመላእክት) ሴቶች ልጆችን ያደርጋሉ፡፡ ጥራት ተገባው፡፡ ለእነርሱም የሚፈልጉትን (ወንዶች ልጆችን) ያደርጋሉ፡፡'),
('16:58', 87, 'አንዳቸውም በሴት ልጅ በተበሰረ ጊዜ እርሱ የተቆጨ ኾኖ ፊቱ ጠቁሮ ይውላል፡፡'),
('16:59', 87, 'በእርሱ ከተበሰረበት ነገር መጥፎነት በውርደት ላይ ኾኖ ይያዘውን ወይስ በዐፈር ውስጥ ይደብቀውን (በማለት እያምታታ) ከሰዎች ይደበቃል፡፡ ንቁ! የሚፈርዱት (ፍርድ) ምንኛ ከፋ!'),
('16:60', 87, 'ለእነዚያ በመጨረሻይቱ ዓለም ለማያምኑት መጥፎ ጠባይ አላቸው፡፡ ለአላህም ታላቅ ባሕርይ አለው፡፡ እርሱም አሸናፊው ጥበበኛው ነው፡፡'),
('16:61', 87, 'አላህም ሰዎችን በበደላቸው በያዛቸው ኖሮ በርሷ (በምድር ላይ) ከተንቀሳቃሽ ምንንም ባልተወ ነበር፡፡ ግን እስከ ተወሰነ ጊዜ ድረስ ያቆያቸዋል፡፡ ጊዜያቸውም በመጣ ወቅት አንዲትን ሰዓት አይቆዩም፤ አይቀደሙምም፡፡'),
('16:62', 87, 'ለአላህም የሚጠሉትን ነገር ያደረጋሉ፡፡ ለእነሱም መልካሚቱ (አገር) አለቻቸው በማለት ምላሶቸቸው ውሸትን ይናገራሉ፡፡ ለእነሱ እሳት ያለቻቸው መኾናቸውና እነሱም (ወደርሷ) በቅድሚያ የሚነዱ መኾናቸው ጥርጥር የለበትም፡፡'),
('16:63', 87, 'በአላህ እንምላለን፤ ካንተ በፊት ወደ ነበሩት ሕዝቦች በእርግጥ (መልክተኞችን) ልከናል፡፡ ሰይጣንም ለእነርሱ ሥራዎቻቸውን ሸለመላቸው፡፡ እርሱም ዛሬ ረዳታቸው ነው፡፡ ለእነሱም (ኋላ) አሳማሚ ቅጣት አላቸው፡፡'),
('16:64', 87, 'ባንተም ላይ መጽሐፉን አላወረድንም፤ ያንን በርሱ የተለያዩበትን ለነርሱ ልታብራራላቸውና ለሚያምኑትም ሕዝቦች መሪና እዝነት ሊኾን እንጂ፡፡'),
('16:65', 87, 'አላህም ከሰማይ ውሃን አወረደ፡፡ በእርሱም ምድርን ከሞተች በኋላ ሕያው አደረገ፡፡ በዚህ ውስጥ ለሚሰሙ ሕዝቦች በእርግጥ ተዓምር አልለ፡፡'),
('16:66', 87, 'ለናንተም በግመል፣ በከብት፣ በፍየል በእርግጥ መገምገሚያ አልላችሁ፡፡ በሆዶቹ ውስጥ ካለው ከፈረስና ከደም መካከል ጥሩ ወተትን ለጠጪዎች ተዋጭ ሲሆን እናጠጣችኋለን፡፡'),
('16:67', 87, 'ከዘምባባዎችና ከወይኖችም ፍሬዎች (እንመግባችኋለን)፡፡ ከእርሱ ጠጅንና መልካም ምግብንም ትሠራላችሁ፡፡ በዚህም ውስጥ ለሚያስቡ ሕዝቦች በእርግጥ ተዓምር አልለ፡፡'),
('16:68', 87, 'ጌታህም ወደ ንብ እንዲህ ሲል አስታወቀ «ከተራራዎች፣ ከዛፍም፣ (ሰዎች) ከሚሠሩትም (ቀፎ) ቤቶችን ያዢ፡፡'),
('16:69', 87, '«ከዚያም ከፍሬዎች ሁሉ ብይ፡፡ የጌታሽንም መንገዶች (ላንቺ) የተገሩ ሲኾኑ ግቢ፡፡» ከሆዶችዋ መልኮቹ የተለያዩ መጠጥ ይወጣል፡፡ በእርሱ ውስጥ ለሰዎች መድኃኒት አለበት፡፡ በዚህ ውስጥ ለሚያስተነትኑ ሕዝቦች በእርግጥ ተዓምር አልለበት፡፡'),
('16:70', 87, 'አላህም ፈጠራችሁ፤ ከዚያም ይገድላችኋል፡፡ ከእናንተም ከዕወቅት በኋላ ምንንም ነገር እንዳያውቅ ወደ ወራዳ ዕድሜ የሚመለስ ሰው አልለ፡፡ አላህ ዐዋቂ ቻይ ነው፡፡'),
('16:71', 87, 'አላህም ከፊላችሁን በከፊሉ ላይ በሲሳይ አበለጠ፡፡ እነዚያም በላጭ የተደረጉት ሲሳያቸውን እጆቻቸው በያዙዋቸው (ባሮች) ላይ እነሱ በእርሱ ይተካከሉ ዘንድ መላሾች አይደሉም፡፡ ታዲያ በአላህ ጸጋ (ለእርሱ ተጋሪ በማድረግ) ይክዳሉን'),
('16:72', 87, 'አላህም ከነፍሶቻችሁ (ከጎሶቻችሁ) ለእናንተ ሚስቶችን አደረገ፡፡ ለእናንተም ከሚስቶቻችሁ ወንዶች ልጆችን፣ የልጅ ልጆችንም አደረገላችሁ፡፡ ከመልካሞችም ጸጋዎች ሰጣችሁ፡፡ ታድያ በውሸት (በጣኦት) ያምናሉን በአላህም ጸጋ እነሱ ይክዳሉን'),
('16:73', 87, 'ከአላህም ሌላ ከሰማያትም ከምድርም ምንንም ሲሳይ የማይሰጧቸውን (ምንንም) የማይችሉትንም ይግገዛሉ፡፡'),
('16:74', 87, 'ለአላህም አምሳያዎችን አታድርጉ፡፡ አላህ (መሳይ እንደሌለው) ያውቃል፡፡ እናንተ ግን አታውቁም፡፡'),
('16:75', 87, 'በምንም ላይ የማይችለውን በይዞታ ያለውን ባሪያና ከእኛ መልካም ሲሳይን የሰጠነውን እርሱም ከእርሱ (ከሰጠነው) በምስጢርና በግልጽ የሚለግሰውን (ነጻ) ሰው አላህ (ለጣዖትና ለርሱ) ምሳሌ አደረገ፡፡ (ሁለቱ) ይተካከላሉን ምስጋና ለአላህ ይኹን፡፡ በእውነቱ አብዛኞቻቸው አያውቁም፡፡'),
('16:76', 87, 'አላህም ሁለትን ወንዶች (ለከሓዲና ለምእመን) ምሳሌ አደረገ፡፡ አንደኛቸው በምንም ነገር ላይ የማይችል ዲዳ ነው፡፡ እርሱም በጌታው ላይ ሸክም ነው፡፡ ወደ የትም ቢያዞረው በደግ ነገር አይመጣም፡፡ እርሱና ያ እርሱ በቀጥተናው መንገድ ላይ ኾኖ በማስተካከል የሚያዘው ሰው ይስተካከላሉን'),
('16:77', 87, 'በሰማያትና በምድርም ያለው ሩቅ ምስጢር የአላህ ነው፡፡ የሰዓቲቱም ነገር (መምጣቷ) እንደዓይን ቅጽበት እንጂ አይደለም፡፡ ወይ እርሱ ይበልጥ የቀረበ ነው፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('16:78', 87, 'አላህም ከእናቶቻችሁ ሆዶች ምንም የማታውቁ ሆናችሁ አወጣችሁ፡፡ ታመሰግኑም ዘንድ ለእናንተ መስሚያን ማያዎችንም ልቦችንም አደረገላችሁ፡፡'),
('16:79', 87, 'ወደ በራሪዎች በሰማይ አየር ውስጥ (ለመብረር) የተገሩ ሲኾኑ (ከመውደቅ) አላህ እንጂ ሌላ የማይዛቸው ኾነው አይመለከቱምን በዚህ ውስጥ ለሚያምኑ ሕዝቦች በእርግጥ ተዓምራቶች አሉ፡፡'),
('16:80', 87, 'አላህም ከቤቶቻችሁ ለእናንተ መርጊያን አደረገላችሁ፡፡ ከእንስሳዎችም ቆዳዎች በጉዟችሁ ቀን በመቀመጫችሁም ቀን የምታቀልላቸውን ቤቶች ለናንተ አደረገላችሁ፡፡ ከበግዋ ሱፎች፣ ከግመልዋም ጠጉሮች፣ ከፍየልዋም ጠጉሮች የቤት ዕቃዎችን እስከ ጊዜም ድረስ መጠቃቀሚያን (አደረገላችሁ)፡፡'),
('16:81', 87, 'አላህም ከፈጠረው ነገር ለእናንተ ጥላዎችን አደረገላችሁ፡፡ ከጋራዎችም ለእናንተ መከለያዎችን አደረገላችሁ፡፡ ሐሩርንም (ብርድንም) የሚጠብቋችሁን ልብሶች የጦራችሁንም አደጋ የሚጠብቋችሁን ጥሩሮች ለእናንተ አደረገላችሁ፡፡ እንደዚሁ ትሰልሙ ዘንድ ጸጋውን በእናንተ ላይ ይሞላል፡፡'),
('16:82', 87, '(ከኢስላም) ቢሸሹም ባንተ ላይ ያለብህ ግልጽ ማድረስ ብቻ ነው፡፡'),
('16:83', 87, 'የአላህን ጸጋ ያውቃሉ፡፡ ከዚያም ይክዷታል፡፡ አብዛኞቻቸውም ከሓዲዎቹ ናቸው፡፡'),
('16:84', 87, 'ከየሕዝቡም ሁሉ መስካሪን የምንቀሰቅስበትን ቀን (አስታውስ)፡፡ ከዚያም ለእነዚያ ለካዱት (ንግግር) አይፈቀድላቸውም፡፡ እነሱም በወቀሳ አይታለፉም፡፡'),
('16:85', 87, 'እነዚያም የበደሉት ቅጣቱን ባዩ ጊዜ ከእነሱ (ቅጣቱ) አይቀለልላቸውም፡፡ እነሱም ጊዜ አይስሰጡም፡፡'),
('16:86', 87, 'እነዚያም ያጋሩት የሚያጋሩዋቸውን ባዩ ጊዜ «ጌታችን ሆይ! እነዚህ ከአንተ ሌላ እንገዛቸው የነበርነው ተጋሪዎቻችን ናቸው» ይላሉ፡፡ (አማልክቶች) «እናንተ በእርግጥ ውሸታሞች ናችሁ» የማለትንም ቃል ወደእነሱ ይጥላሉ፡፡'),
('16:87', 87, '(አጋሪዎቹ) በዚያ ቀንም ታዛዥነታቸውን ወደ አላህ ያቀርባሉ፡፡ ይቀጣጥፉት የነበሩትም ሁሉ ከእነርሱ ይጠፋቸዋል፡፡'),
('16:88', 87, 'እነዚያ የካዱ፣ ከአላህም መንገድ የከለከሉ ያጠፉ በነበሩት ምክንያት ቅጣትን በቅጣት ላይ ጨመርንባቸው፡፡'),
('16:89', 87, 'በየሕዝቡም ሁሉ ውስጥ ከጎሳቸው በእነሱ ላይ መስካሪን የምንቀሰቅስበትን አንተንም በእነዚህ (ሕዝቦች) ላይ መስካሪ አድርገን የምናመጣህን ቀን (አስታውስ)፡፡ መጽሐፉንም ለሁሉ ነገር አብራሪ፣ መሪም፣ እዝነትም፣ ለሙስሊሞችም አብሳሪ ኾኖ ባንተ ላይ አወረድነው፡፡'),
('16:90', 87, 'አላህ በማስተካከል፣ በማሳመርም፣ ለዝምድና ባለቤት በመስጠትም ያዛል፡፡ ከአስከፊም (ከማመንዘር)፣ ከሚጠላም ነገር ሁሉ፣ ከመበደልም ይከለክላል፡፡ ትገነዘቡ ዘንድ ይገስጻችኋል፡፡'),
('16:91', 87, 'ቃል ኪዳንም በገባችሁ ጊዜ በአላህ ቃል ኪዳን ሙሉ፡፡ መሓሎቻችሁንም ከአጠነከራችኋት በኋላ አላህን በእናንተ ላይ በእርግጥ መስካሪ ያደረጋችሁ ስትኾኑ አታፍርሱ፡፡ አላህ የምትሠሩትን ሁሉ ያውቃልና፡፡'),
('16:92', 87, '(ቃል ኪዳናችሁን በማፍረስ አንዲቱ) ሕዝብ እርሷ ከ(ሌላይቱ) ሕዝብ የበዛች ለመኾንዋ በመካከላችሁ መሓሎቻችሁን (ለክዳት) መግቢያ አድርጋችሁ የምትይዙ ስትኾኑ እንደዚያች ፈትልዋን ከጠነከረ በኋላ ትርትሮች አድርጋ እንዳፈረሰችው (ሴት) አትኹኑ፡፡ አላህ በእርሱ ይሞክራችኋል፤ በትንሣኤ ቀንም በእርሱ ትለያዩበት የነበራችሁትን ነገር ለእናንተ በእርግጥ ያብራራላችኋል፡፡'),
('16:93', 87, 'አላህም በሻ ኖሮ አንዲት ሕዝብ ባደረጋችሁ ነበር፡፡ ግን የሚሻውን ሰው ያጠማል፡፡ የሚሻውንም ሰው ያቀናል፡፡ ትሠሩት ከነበራችሁትም ሁሉ በእርግጥ ትጠየቃላችሁ፡፡'),
('16:94', 87, 'ጫማዎች ከተደላደሉ በኋላ እንዳይንዳለጡ ከአላህም መንገድ በመከልከላችሁ ምክንያት ቅጣትን እንዳትቀምሱ መሓሎቻችሁን በመካከላችሁ ለክዳት መግቢያ አድርጋችሁ አትያዙ፡፡ ለእናንተም (ያን ጊዜ) ታላቅ ቅጣት አላችሁ፡፡'),
('16:95', 87, 'በአላህም ቃል ኪዳን ጥቂትን ዋጋ አትግዙ፡፡ የምታውቁ ብትኾኑ አላህ ዘንድ ያለው ምንዳ እርሱ ለእናንተ በላጭ ነውና፡፡'),
('16:96', 87, 'እናንተ ዘንድ ያለው ሁሉ ያልቃል፡፡ አላህ ዘንድ ያለው ግን (ዘለዓለም) ቀሪ ነው፡፡ እነዚያንም የታገሱትን ይሠሩት በነበሩት በመልካሙ ምንዳቸውን እንመነዳቸዋለን፡፡'),
('16:97', 87, 'ከወንድ ወይም ከሴት እርሱ አማኝ ኾኖ በጎን የሰራ መልካም ኑሮን በእርግጥ እናኖረዋለን፡፡ ይሠሩትም ከነበሩት ነገር በመልካሙ ምንዳቸውን እንመነዳቸዋለን፡፡'),
('16:98', 87, 'ቁርኣንንም ባነበብህ ጊዜ እርጉም ከኾነው ሰይጣን በአላህ ተጠበቅ፡፡'),
('16:99', 87, 'እርሱ በእነዚያ ባመኑትና በጌታቸው ላይ በሚጠጉት ላይ ለእርሱ ስልጣን የለውምና፡፡'),
('16:100', 87, 'ስልጣኑ በእነዚያ በሚታዘዙት ላይና በእነዚያም እነርሱ በእርሱ (ምክንያት) አጋሪዎች በኾኑት ላይ ብቻ ነው፡፡'),
('16:101', 87, 'በአንቀጽም ስፍራ አንቀጽን በለወጥን ጊዜ አላህም የሚያወርደውን ነገር አዋቂ ነው፡፡ «አንተ ቀጣፊ እንጂ ሌላ አይደለህም» ይላሉ፡፡ በእውነቱ አብዛኞቻቸው አያውቁም፡፡'),
('16:102', 87, 'እነዚያን ያመኑትን ለማረጋጋት ሙስሊሞቹንም ለመምራትና ለማብሰር (ቁርኣንን) ቅዱሱ መንፈስ (ጂብሪል) እውነተኛ ሲኾን ከጌታህ አወረደው በላቸው፡፡'),
('16:103', 87, 'እነርሱም «እርሱን (ቁርኣንን) የሚያስተምረው ሰው ብቻ ነው» ማለታቸውን በእርግጥ እናውቃለን፡፡ የዚያ ወደርሱ የሚያስጠጉበት ሰው ቋንቋ ዐጀም ነው፡፡ ይህ (ቁርአን) ግን ግልጽ ዐረብኛ ቋንቋ ነው፡፡'),
('16:104', 87, 'እነዚያን በአላህ አንቀጾች የማያምኑትን አላህ አይመራቸውም፤ ለነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('16:105', 87, 'ውሸትን የሚቀጣጥፉት እነዚያ በአላህ አንቀጾች የማያምኑት ብቻ ናቸው፡፡ እነዚያም ውሸታሞቹ እነሱ ብቻ ናቸው፡፡'),
('16:106', 87, 'ከእምነቱ በኋላ በአላህ የካደ ሰው (ብርቱ ቅጣት አልለው)፡፡ ልቡ በእምነት የረጋ ኾኖ (በክህደት ቃል በመናገር) የተገደደ ሰው ብቻ ሲቀር፡፡ ግን ልባቸውን በክሕደት የከፈቱ ሰዎች በነሱ ላይ ከአላህ ቁጣ አለባቸው፡፡ ለእነሱም ታላቅ ቅጣት አልላቸው፡፡'),
('16:107', 87, 'ይህ (ቅጣት) እነሱ ቅርቢቱን ሕይወት ከመጨረሻይቱ በመምረጣቸው ምክንያትና አላህም ከሓዲዎችን ሕዝቦች የማያቀና በመኾኑ ነው፡፡'),
('16:108', 87, 'እነዚያ እነርሱ በልቦቻቸው፣ በዓይኖቻቸውም፣ በጆሮዎቻቸውም ላይ አላህ ያተመባቸው ናቸው፡፡ እነዚያም ዝንጉዎቹ እነሱ ናቸው፡፤'),
('16:109', 87, 'እነርሱ በመጨረሻይቱ ዓለም ከሳሪዎቹ እነሱ ለመኾናቸው ጥርጥር የለም፡፡'),
('16:110', 87, 'ከዚያም ጌታህ ለእነዚያ ከተፈተኑ በኋላ ለተሰደዱት ከዚያም ለታገሉትና ለታገሱት (መሓሪ አዛኝ ነው)፡፡ ጌታህ ከእርሷ (ከፈተናዋ) በኋላ በእርግጥ መሓሪ አዛኝ ነውና፡፡'),
('16:111', 87, 'ነፍስ ሁሉ ከራሷ ላይ የምትከራከር ኾና የምትመጣበትን ነፍስም ሁሉ የሠራችውን (ዋጋ) የምትቀበልበትን ቀን (አስታውስ)፡፡ እነርሱም አይበደሉም፡፡'),
('16:112', 87, 'አላህ ጸጥተኛ፣ የረካች፣ ሲሳይዋ ሰፊ ኾኖ ከየስፍራው ይመጣላት የነበረችውንና በአላህ ጸጋዎች የካደችውን አላህም ይሠሩት በነበሩት ኃጢኣት የረኃብንና የፍርሃትን ቅጣቶች ያቀመሳትን ከተማ (መካን) ምሳሌ አደረገ፡፡'),
('16:113', 87, 'ከእነርሱ ውስጥ የኾነ መልክተኛም በእርግጥ መጣላቸው፡፡ አስተባበሉትም፡፡ እነሱም በዳዮች ኾነው ቅጣቱ ያዛቸው፡፡'),
('16:114', 87, 'አላህም ከሰጣችሁ ሲሳይ የተፈቀደ ንጹሕ ሲኾን ብሉ፡፡ የአላህንም ጸጋ እርሱን የምትገዙት ብትሆኑ አመስግኑ፡፡'),
('16:115', 87, 'በእናንተ ላይ እርም ያደረገው በክትንና ደምን፣ የአሳማንም ስጋ፣ ያንንም (በመታረድ ጊዜ) በእርሱ ከአላህ ስም ሌላ የተነሳበትን ብቻ ነው፡፡ አመጸኛም ወሰን አላፊም ሳይኾን (ለመብላት) የተገደደ ሰው (ይፈቀድለታል)፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('16:116', 87, 'በአላህም ላይ ውሸትን ልትቀጣጥፉ ምላሶቻችሁ በሚመጥኑት ውሸት «ይህ የተፈቀደ ነው፤ ይህም እርም ነው» አትበሉ፡፡ እነዚያ በአላህ ላይ ውሸትን የሚቀጣጥፉ አይድኑም፡፡'),
('16:117', 87, 'ጥቂት መጣቀም አላቸው፡፡ ለእነሱም አሳማሚ ቅጣት አላቸው፡፡'),
('16:118', 87, 'በእነዚያም ይሁዳውያን በኾኑት ላይ ከአሁን በፊት በአንተ ላይ የተረክነውን ነገር እርም አድርገንባቸዋል፡፡ እኛም አልበደልናቸውም፡፡ ግን ነፍሶቻቸውን ይበድሉ ነበሩ፡፡'),
('16:119', 87, 'ከዚያም ጌታህ ለእነዚያ በስሕተት መጥፎን ለሠሩና ከዚያም ከዚህ በኋላ ለተጸጸቱ ሥራቸውንም ላበጁ ጌታህ ከእርሷ በኋላ በእርግጥ መሓሪ አዛኝ ነው፡፡'),
('16:120', 87, 'ኢብራሂም ለአላህ ታዛዥ ወደ ቀጥተኛ ሃይማኖት ተዘንባይ ሕዝብ ነበር፡፡ ከአጋሪዎቹም አልነበረም፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('16:121', 87, 'ለጸጋዎቹ አመስጋኝ ነበር፤ መረጠው፡፡ ወደ ቀጥተኛውም መንገድ መራው፡፡'),
('16:122', 87, 'በቅርቢቱም ዓለም በጎን ነገር ሰጠነው፡፡ እርሱም በመጨረሻይቱ ዓለም በእርግጥ ከመልካሞቹ ነው፡፡'),
('16:123', 87, 'ከዚያም ወደ አንተ የኢብራሂምን ሃይማኖት ቀጥተኛ ሲኾን ተከተል፤ ከአጋሪዎቹም አልነበረም ማለት አወረድን፡፡'),
('16:124', 87, 'ሰንበት (ክልክል) የተደረገው በእነዚያ በእርሱ በተለያዩበት ሰዎች ላይ ብቻ ነው፡፡ ጌታህም በትንሣኤ ቀን ይለያዩበት በነበሩት ነገር በመካከላቸው በእርግጥ ይፈርዳል፡፡'),
('16:125', 87, 'ወደ ጌታህ መንገድ በብልሃትና በመልካም ግሳጼ (በለዘብታ ቃል) ጥራ፡፡ በዚያችም እርሷ መልካም በኾነችው (ዘዴ) ተከራከራቸው፡፡ ጌታህ እርሱ ከመንገዱ የተሳሳተውን ሰው ዐዋቂ ነው፡፡ እርሱም ቅን የኾኑትን ሰዎች ዐዋቂ ነው፡፡'),
('16:126', 87, 'ብትበቀሉም በርሱ በተቀጣችሁበት ብጤ ተበቀሉ፡፡ ብትታገሱም እርሱ ለታጋሾች በእርግጥ በላጭ ነው፡፡'),
('16:127', 87, 'ታገስም፤ መታገስህም በአላህ (ማስቻል) እንጂ አይደለም፡፡ በእነርሱም ላይ (ባያምኑ) አትተክዝ፡፡ (ባንተ ላይ) ከሚመክሩትም ተንኮል በጭንቀት ውስጥ አትኹን፡፡'),
('16:128', 87, 'አላህ ከእነዚያ ከሚፈሩትና ከእነዚያም እነሱ መልካም ሠሪዎች ከኾኑት ጋር ነውና፡፡'),
('17:1', 87, 'ያ ባሪያውን ከተከበረው መስጊድ ወደዚያ ዙሪያውን ወደ ባረክነው ወደ ሩቁ መስጊድ በሌሊት ውስጥ ያስኼደው (ጌታ) ጥራት ይገባው፡፡ ከተዓምራቶቻችን ልናሳየው (አስኼድነው)፡፡ እነሆ እርሱ (አላህ) ሰሚው ተመልካቺው ነው፡፡'),
('17:2', 87, 'ሙሳንም መጽሐፉን ሰጠነው፡፡ ለእስራኤልም ልጆች መሪ አደረግነው፡፡ ከእኔ ሌላ መጠጊያን አትያዙ፤ (አልናቸውም)፡፡'),
('17:3', 87, 'እናንተ ከኑሕ ጋር (በመርከቢቱ) የጫናቸው ዘሮች ሆይ! (አላህን ተገዙ) እርሱ በብዙ አመስጋኝ ባሪያ ነበርና፡፡'),
('17:4', 87, 'ወደ እስራኤልም ልጆች በመጽሐፉ ውስጥ (እንዲህ በማለት) አወረድን፡፡ በምድር ላይ በእርግጥ ሁለት ጊዜ ታጠፋላችሁ፡፡ ትልቅንም ኩራት ትኮራላችሁ፡፡'),
('17:5', 87, 'ከሁለቱ (ጊዜያቶች) የመጀመሪያይቱ ቀጠሮ በመጣም ጊዜ ለእኛ የኾኑን ባሮች የብርቱ ኃይል ባለቤቶች የኾኑትን በእናንተ ላይ እንልካለን፡፡ በቤቶችም መካከል ይመላለሳሉ፤ (ይበረብሩታል፡፡) ይህ ተፈጻሚ ቀጠሮም ነበር፡፡'),
('17:6', 87, 'ከዚያም (በኋላ) ለእናንተ በእነሱ ላይ ድልን መለስንላችሁ፡፡ በገንዘቦችና በወንዶች ልጆችም ጨመርንላችሁ፡፡ በወገንም የበዛችሁ አደረግናችሁ፡፡'),
('17:7', 87, 'መልካም ብትሠሩ ለነፍሶቻችሁ መልካምን ሠራችሁ፡፡ መጥፎንም ብትሠሩ በነርሱ (በነፍሶቻችሁ) ላይ ነው፤ (አልን)፡፡ የኋለኛይቱም (ጊዜ) ቀጠሮ በመጣ ጊዜ ፊቶቻችሁን ሊያስከፉ፣ መስጊዱንም በመጀመሪያ ጊዜ እንደገቡት ሊገቡ፣ ያሸነፉትንም ሁሉ (ፈጽመው) ማጥፋትን እንዲያጠፉ (እንልካቸዋልን)፡፡'),
('17:8', 87, '(በመጽሐፉም አልን) «ብትጸጸቱ፡- ጌታችሁ ሊያዝንላችሁ ይከጀላል፡፡ (ወደ ማጥፋት) ብትመለሱም እንመለሳለን፡፡ ገሀነምንም ለከሓዲዎች ማሰሪያ አደርገናል፡፡'),
('17:9', 87, 'ይህ ቁርኣን ወደዚያች እርሷ ቀጥተኛ ወደ ኾነችው መንገድ ይመራል፡፡ እነዚያንም በጎ የሚሠሩትን ምእመናን ለእነሱ ታላቅ ምንዳ ያላቸው መኾኑን ያበስራል፡፡'),
('17:10', 87, 'እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ለእነሱ አሳማሚ ቅጣትን አዘጋጅተንላቸዋል፤'),
('17:11', 87, 'ሰው መልካምን ነገር እንደሚለምን ሁሉ፤ መጥፎንም ነገር ይለምናል፡፡ ሰውም ቸኳላ ነው፡፡'),
('17:12', 87, 'ሌሊትንና ቀንንም (ለችሎታችን) ምልክቶች አደረግን፡፡ የሌሊትን ምልክትም አበስን፡፡ የቀንን ምልክትም የምታሳይ አደረግን፡፡ (ይህም የኾነበት) ከጌታችሁ ትርፍን ልትፈልጉ የዓመታትንም ቁጥርና ሒሳብንም ታውቁ ዘንድ ነው፡፡ ነገሩንም ሁሉ ለያይተን ዘረዘርነው፡፡'),
('17:13', 87, 'ሰውንም ሁሉ በራሪውን (ሥራውን) በአንገቱ አስያዝነው፡፡ ለእርሱም በትንሣኤ ቀን የተዘረጋ ኾኖ የሚያገኘው የኾነን መጽሐፍ እናወጣለታለን፡፡'),
('17:14', 87, '«መጽሐፍህን አንብብ፡፡ ዛሬ ባንተ ላይ ተቆጣጣሪነት በነፍስህ በቃ» (ይባላል)፡፡'),
('17:15', 87, 'የተመራ ሰው የሚመራው ለራሱ ብቻ ነው፡፡ የተሳሳተም ሰው የሚሳሳተው (ጉዳቱ) በእርሷ ላይ ነው፡፡ ተሸካሚም (ነፍስ) የሌላይቱን ኃጢኣት አትሸከምም፡፡ መልዕክተኛንም እስከምንልክ ድረስ የምንቀጣ አይደለንም፡፡'),
('17:16', 87, 'ከተማንም ለማጥፋት በፈለግን ጊዜ ባለ ጸጋዎችዋን እናዛለን፡፡ በውስጧም ያምጻሉ፡፡ በእርሷም ላይ ቃሉ (ቅጣቱ) ይፈጸምባታል፡፡ ማጥፋትንም እናጠፋታለን፡፡'),
('17:17', 87, 'ከኑሕም በኋላ ከክፍለ ዘመናት ሰዎች ያጠፋናቸው ብዙዎች ናቸው፡፡ የባሮቹንም ኃጢኣቶች ውስጠ ዐዋቂ ተመልካች መኾን በጌታህ በቃ፡፡'),
('17:18', 87, 'ቸኳይቱን ዓለም (በሥራው) የሚፈልግ ሰው ለእርሱ በርሷ ውስጥ የሻነውን (ጸጋ) ለምንሻው ሰው እናስቸኩልለታለን፡፡ ከዚያም ለእርሱ ገሀነምን (መኖሪያ) አድርገንለታል፡፡ ተወቃሽ ብራሪ ኾኖ ይገባታል፡፡'),
('17:19', 87, 'መጨረሻይቱንም ዓለም የፈለገ ሰው እርሱ አማኝ ኾኖ ለርሷ (ተገቢ) ሥራዋን የሠራም ሰው እነዚህ ሥራቸው የተመሰገነ ይኾናል፡፡'),
('17:20', 87, 'ሁሉንም እነዚህንና እነዚያን ከጌታህ ስጦታ (በዚህ ዓለም) እንጨምርላቸዋለን፡፡ የጌታህም ስጦታ (በዚች ዓለም) ክልክል አይደለም፡፡'),
('17:21', 87, 'ከፊላቸውን በከፊሉ ላይ እንዴት እንዳበለጥን ተመልከት፡፡ የመጨረሻያቱም አገር በማዕረጎች በጣም የከበረችና በመብለጥም የተለቀች ናት፡፡'),
('17:22', 87, 'ከአላህ ጋር ሌላን አምላክ አታድርግ የተወቀስክ ረዳት የሌለህ ትኾናለህና፤'),
('17:23', 87, 'ጌታህም (እንዲህ ሲል) አዘዘ፡- እርሱን እንጂ ሌላን አትገዙ፡፡ በወላጆቻችሁም መልካምን ሥሩ፡፡ በአንተ ዘንድ ኾነው አንዳቸው ወይም ሁለታቸው እርጅናን ቢደርሱ ፎህ አትበላቸው፡፡ አትገላምጣቸውም፡፡ ለእነርሱም መልካምን ቃል ተናገራቸው፡፡'),
('17:24', 87, 'ለሁለቱም ከእዝነትህ የመዋረድን ክንፍ ዝቅ አድርግላቸው፡፡ «ጌታዬ ሆይ! በሕፃንነቴ (በርኅራኄ) እንዳሳደጉኝ እዘንልላቸውም» በል፡፡'),
('17:25', 87, 'ጌታችሁ በነፍሶቻችሁ ውስጥ ያለውን ሁሉ አዋቂ ነው፡፡ ታዛዦችም ብትኾኑ (በመሳሳትም ብታጠፉ) እርሱ ለተመላሾች መሓሪ ነው፡፡'),
('17:26', 87, 'ለዝምድና ባለቤትም መብቱን ስጥ፡፡ ለምስኪንና ለመንገደኛም (ስጥ)፡፡ ማባከንንም አታባክን፡፡'),
('17:27', 87, 'አባካኞች የሰይጣናት ወንድሞች ናቸውና፡፡ ሰይጣንም ለጌታው ብርቱ ከሓዲ ነው፡፡'),
('17:28', 87, 'ከጌታህም የምትከጅላትን ጸጋ ለማጣት ከእነርሱ ብትዞር ለእነሱ ልዝብን ቃል ተናገራቸው፡፡'),
('17:29', 87, 'እጅህንም ወደ አንገትህ የታሰረች አታድርግ፡፡ መዘርጋትንም ሁሉ አትዘርጋት፤ የተወቀስክ የተቆጨኽ ትኾናለህና፡፡'),
('17:30', 87, 'ጌታህ ሲሳይን ለሚሻው ሰው ያሰፋል፤ ያጠባልም፡፡ እርሱ በባሮቹ ኹኔታ ውስጠ ዐዋቂ ተመልካች ነውና፡፡'),
('17:31', 87, 'ልጆቻችሁንም ድኽነትን ለመፍራት አትግደሉ፡፡ እኛ እንመግባቸዋለን፡፡ እናንተንም (እንመግባለን)፡፡ እነርሱን መግደል ታላቅ ኃጢኣት ነውና፡፡'),
('17:32', 87, 'ዝሙትንም አትቅረቡ፡፡ እርሱ በእርግጥ መጥፎ ሥራ ነውና፡፡ መንገድነቱም ከፋ!'),
('17:33', 87, 'ያቺንም አላህ ያወገዛትን ነፍስ ያለ ሕግ አትግደሉ፡፡ የተበደለም ኾኖ የተገደለ ሰው ለዘመዱ (በገዳዩ ላይ) በእርግጥ ስልጣንን አድርገናል፡፡ በመግደልም ወሰንን አይለፍ፤ እርሱ የተረዳ ነውና፡፡'),
('17:34', 87, 'የየቲምንም ገንዘብ የብርታቱን ጊዜ እስኪደርስ ድረስ በዚያች እርሷ መልካም በኾነች ኹኔታ እንጂ አትቅረቡ፡፡ በኪዳናችሁም ሙሉ፡፡ ኪዳን የሚጠየቁበት ነውና፡፡'),
('17:35', 87, 'በሰፈራችሁም ጊዜ ስፍርን ሙሉ፡፡ በትክክለኛው ሚዛንም መዝኑ፡፡ ይህ መልካም ነገር ነው፡፡ መጨረሻውም ያማረ ነው፡፡'),
('17:36', 87, 'ለአንተም በርሱ ዕውቀት የሌለህን ነገር አትከተል፡፡ መስሚያ፣ ማያም፣ ልብም እነዚህ ሁሉ (ባለቤታቸው) ከእነሱ ተጠያቂ ነውና፡፡'),
('17:37', 87, 'በምድርም ላይ የተንበጣረረክ ሆነህ፤ አትሂድ፡፡ አንተ ፈጽሞ ምድርን አትሰረጉድምና በርዝመትም ፈጽሞ ጋራዎችን አትደርስምና፡፡'),
('17:38', 87, 'ይህ ሁሉ መጥፎው (አሥራ ሁለቱ ክልክሎች) እጌታህ ዘንድ የተጠላ ነው፡፡'),
('17:39', 87, 'ይህ ጌታህ ከጥበቡ ወደ አንተ ካወረደው ነገር ነው፡፡ ከአላህም ጋር ሌላን አምላክ አታድርግ የተወቀስክ የተባረርክ ኾነህ በገሀነም ውስጥ ትጣላለህና፡፡'),
('17:40', 87, 'ጌታችሁ በወንዶች ልጆች መረጣችሁና ከመላእክት ሴቶችን (ልጆች) ያዝን እናንተ ከባድን ቃል በእርግጥ ትናገራላችሁ፡፡'),
('17:41', 87, 'ይገሰጹም ዘንድ በዚህ ቁርኣን ውስጥ ደጋግመን በእርግጥ ገለጽን፡፡ መበርገግንም እንጂ ሌላን አይጨመርላቸውም፡፡'),
('17:42', 87, '(ሙሐመድ ሆይ) በላቸው «እንደምትሉት ከእርሱ ጋር አማልክት በነበሩ ኖሮ ያን ጊዜ ወደ ዐርሹ ባለቤት መንገድን በፈለጉ ነበር፡፡»'),
('17:43', 87, 'ጥራት ይገባው፡፡ ከሚሉትም ነገር ሁሉ ከፍ ያለን ልቅና ላቀ፡፡'),
('17:44', 87, 'ሰባቱ ሰማያትና ምድርም በውስጣቸውም ያለው ሁሉ ለእርሱ ያጠራሉ፡፡ ከነገርም ሁሉ ከማመስገን ጋር የሚያጠራው እንጂ አንድም የለም፡፡ ግን ማጥራታቸውን አታውቁትም፡፡ እርሱ ታጋሽ መሓሪ ነው፡፡'),
('17:45', 87, 'ቁርኣንንም ባነበብክ ጊዜ ባንተና በእነዚያ በመጨረሻይቱ ዓለም በማያምኑት ሰዎች መካከል የሚሸሸግን ግርዶሽ አድርገናል፡፡'),
('17:46', 87, 'እንዳያውቁትም በልቦቻቸው ላይ ሽፋንን በጆሮቻቸውም ውስጥ ድንቁርናን አደረግን፡፡ ጌታህንም ብቻውን ኾኖ በቁርኣን ባወሳኸው ጊዜ የሚሸሹ ኾነው በጀርባዎቻቸው ላይ ይዞራሉ፡፡'),
('17:47', 87, 'እኛ ወደ አንተ በሚያዳምጡ ጊዜ እነሱም በሚንሾካሾኩ ጊዜ በዳዮች (እርስ በርሳቸው) የተደገመበትን ስው እንጂ አትከተሉም በሚሉ ጌዜ በእርሱ የሚያዳምጡበትን ምክንያት ዐዋቂ ነን፡፡'),
('17:48', 87, 'ምሳሌዎችን ለአንተ እንዴት እንዳደረጉልህና እንደ ተሳሳቱ ተመልከት፡፡ (ወደ እውነቱ ለመድረስ) መንገድንም አይችሉም፡፡'),
('17:49', 87, 'አሉም «እንዴት አጥንቶችና ብስብሶች በኾን ጊዜ እኛ አዲስ ፍጥረት ኾነን በእርግጥ ተቀስቃሾች ነን»'),
('17:50', 87, 'በላቸው «ድንጋዮችን ወይም ብረትን ሁኑ»'),
('17:51', 87, '«ወይም በልቦቻችሁ ውስጥ የሚተልቅን ፍጥረት (ኹኑ መቀስቀሳችሁ አይቀርም)፡፡» «የሚመልሰንም ማነው» ይላሉ፡፡ ያ በመጀመሪያ ጊዜ የፈጠራችሁ ነው» በላቸው፡፡ ወደ አንተም ራሶቻቸውን ይነቀንቃሉ፡፡ «እርሱም መቼ ነው» ይላሉ፡፡ «(እርሱ) ቅርብ ሊኾነን ይቻላል በላቸው፡፡'),
('17:52', 87, '(እርሱም) የሚጠራችሁና (አላህን) አመስጋኞቹ ኾናችሁ ጥሪውን የምትቀበሉበት ጥቂትንም (ቀኖች) እንጂ ያልቆያችሁ መኾናችሁን የምትጠራጠሩበት ቀን ነው፤ (በላቸው)፡፡'),
('17:53', 87, 'ለባሮቼም በላቸው፡- ያችን እርሷ መልካም የኾነችውን (ቃል) ይናገሩ፡፡ ሰይጣን በመካከላቸው ያበላሻልና፡፡ ሰይጣን ለሰው ግልጽ ጠላት ነውና፡፡'),
('17:54', 87, 'ጌታችሁ በእናንተ (ኹኔታ) ዐዋቂ ነው፡፡ ቢሻ ያዝንላችኋል፤ ወይም ቢሻ ይቀጣችኋል፡፡ በእነሱም ላይ ኃላፊ ኾነህ አላክንህም፡፡ (አታስገድዳቸውም)፡፡'),
('17:55', 87, 'ጌታህም በሰማያትና በምድር ያለውን ሁሉ ዐዋቂ ነው፡፡ ከፊሉንም ነቢያት በከፊሉ ላይ በእርግጥ አብልጠናል፡፡ ዳውድንም ዘቡርን ሰጥተነዋል፡፡'),
('17:56', 87, '«እነዚያን ከእርሱ ሌላ (አማልክት) የምትሏቸውን ጥሩ፡፡ ከእናንተም ላይ ጉዳትን ማስወገድን (ወደ ሌላ) ማዞርንም አይችሉም» በላቸው፡፤'),
('17:57', 87, 'እነዚያ እነርሱ የሚግገዟቸው ማንኛቸውም (ወደ አላህ) በጣም ቀራቢያቸው ወደ ጌታቸው መቃረቢያን (ሥራ) ይፈልጋሉ፡፡ እዝነቱንም ይከጅላሉ፡፡ ቅጣቱንም ይፈራሉ፡፡ የጌታህ ቅጣት የሚፈራ ነውና፡፡'),
('17:58', 87, 'አንዲትም ከተማ የለችም እኛ ከትንሣኤ ቀን በፊት አጥፊዎችዋ ወይም ብርቱን ቅጣት ቀጭዎችዋ ብንኾን እንጂ፡፡ ይህ በመጽሐፉ የተጻፈ ነው፡፡'),
('17:59', 87, 'ታምራቶችንም ከመላክ የቀድሞዎቹ ሰዎች በእርሷ ማስተባበልና (መጥፋት) እንጂ ሌላ አልከለከለንም፡፡ ለሰሙድም ግመልን ግልጽ ተዓምር ኾና ሰጠናቸው፡፡ በእርሷም በደሉ፡፡ ተዓምራቶችንም ለማስፈራራት እንጂ አንንልክም፡፡'),
('17:60', 87, 'ላንተም ጌታህ (ዕውቀቱ) በሰዎቹ ከበበ ባልንህ ጊዜ (አስታውስ)፡፡ ያችንም (በሌሊቱ ጉዞ በዓይንህ) ያሳየንህን ትርዕይት ለሰዎች ፈተና እንጂ አላደረግናትም፡፡ በቁርኣንም የተረገመችውን ዛፍ (እንደዚሁ ፈተና እንጂ አላደረግንም)፡፡ እናስፈራራቸዋለንም፤ ታላቅንም ጥመት እንጂ አይጨምርላቸውም፡፡'),
('17:61', 87, 'ለመላእክትም ለአደም ስገዱ ባልናቸው ጊዜ (አስታውስ)፡፡ ወዲያውም ሰገዱ፤ ኢብሊስ ብቻ ሲቀር፡፡ «ከጭቃ ለፈጠርከው ሰው እሰግዳለሁን» አለ፡፡'),
('17:62', 87, '«ንገረኝ ይህ ያ በእኔ ላይ ያበለጥከው ነውን እስከ ትንሣኤ ቀን ድረስ ብታቆየኝ ዘሮቹን ጥቂቶች ሲቀሩ ወደ ስህተት በእርግጥ እስባቸዋለሁ» አለ፡፡'),
('17:63', 87, '(አላህም) አለው «ኺድ፤ ከእነሱም የተከተለህ ገሀነም የተሟላች ቅጣት ስትኾን ፍዳችሁ ናት፡፡'),
('17:64', 87, '«ከእነሱ የቻልከውንም ሰው በድምጽህ አታል፡፡ በእነሱም ላይ በፈረሰኞችህ፣ በእግረኞችህም ኾነህ ለልብ፡፡ በገንዘቦቻቸውም፣ በልጆቻቸውም ተጋራቸው፣ ተስፋ ቃልም ግባላቸው፡፡ ሰይጣንም ማታለልን እንጂ ተስፋ ቃልን አይገባላቸውም፡፡'),
('17:65', 87, '«ባሮቼ በእነሱ ላይ ፈጽሞ ላንተ ስልጣን የለህም፡፡ መጠጊያም በጌታህ በቃ፡፡»'),
('17:66', 87, 'ጌታችሁ ያ ከችሮታው ትፈልጉ ዘንድ መርከቦችን በባሕር ለይ ለእናንተ የሚነዳላችሁ ነው፡፡ እነሆ እርሱ ለናንተ አዛኝ ነውና፡፡'),
('17:67', 87, 'በባሕሩም ውስጥ ጉዳት ባገኛችሁ ጊዜ የምትጠሩዋቸው (አማልክት) ሁሉ ከእርሱ (ከአላህ) በቀር ይጠፋሉ፡፡ ወደ የብስም በማድረስ ባዳናችሁ ጊዜ (እምነትን) ትተዋላችሁ፡፡ ሰውም በጣም ከሓዲ ነው፡፡'),
('17:68', 87, 'የየብሱን በኩል (ምድርን) በእናንተ መገልበጡን ወይም ጠጠርን የያዘ ንፋስን በእናንተ ላይ መላኩን ከዚያም ለእናንተ ጠባቂ አለማግኘታችሁን አትፈሩምን'),
('17:69', 87, 'ወይስ ሌላ ጊዜ ወደ እርሱ (ወደ ባሕር) የሚመልሳችሁ ወዲያውም በእናንተ ላይ ብርቱን ነፋስ የሚልክ በክሕደታችሁም ምክንያት የሚያሰጥማችሁ መኾኑን ከዚያም በኛ ላይ በእርሱ ተከታይን (ረዳትን) ለእናንተ የማታገኙ መኾናችሁን አትፈሩምን'),
('17:70', 87, 'የአደምንም ልጆች በእርግጥ (ከሌላው ፍጡር) አከበርናቸው፡፡ በየብስና በባህርም አሳፈርናቸው፡፡ ከመልካሞችም (ሲሳዮች) ሰጠናቸው፡፡ ከፈጠርናቸውም ፍጡሮች በብዙዎቹ ላይ ማብለጥን አበለጥናቸው፡፡'),
('17:71', 87, 'ሰዎችን ሁሉ በመሪያቸው የምንጠራበትን ቀን (አስታውስ)፡፡ መጽሐፉንም በቀኙ የተሰጠ ሰው እነዚያ መጽሐፋቸውን ያነባሉ፡፡ በተምር ፍሬ ስንጥቅ ላይ ያለውን ክር ያክል እንኳ አይበደሉም፡፡'),
('17:72', 87, 'በዚህችም ዓለም (ልበ) ዕውር የኾነ ሰው እርሱ በመጨረሻይቱም (ዓለም) ይበልጥ ዕውር ነው፡፡ መንገድንም በጣም የተሳሳተ ነው፡፤'),
('17:73', 87, 'እነሆ ከዚያም ወደ አንተ ካወረድነው ሌላን በእኛ ላይ ትዋሽ ዘንድ ሊፈትኑህ በእርግጥ ተቃረቡ፡፡ ያን ጊዜም ወዳጅ አድርገው በያዙህ ነበር፡፡'),
('17:74', 87, 'ባላረጋንህም ኖሮ ወደነሱ ጥቂትን (ዝንባሌ) ልትዘነበል በእርግጥ በተቃረብክ ነበር፡፡'),
('17:75', 87, 'ያን ጊዜ የሕይወትን ድርብ (ቅጣት) የሞትንም ድርብ (ቅጣት) ባቀመስንህ ነበር፡፡ ከዚያም ላንተ በኛ ላይ ረዳትን አታገኝም ነበር፡፡'),
('17:76', 87, 'ከምድሪቱም (ከዓረብ ምድር) ከርሷ ያወጡህ ዘንድ ሊያሸብሩህ በእርግጥ ተቃረቡ፡፡ ያን ጊዜም ከአንተ በኋላ ጥቂትን ጊዜ እንጂ አይቆዩም ነበር፡፡'),
('17:77', 87, 'ከመልክተኞቻችን ካንተ በፊት በእርግጥ እንደላክናቸው ሰዎች ልማድ ብጤ (ይጠፉ ነበር)፡፡ ለልማዳችንም መለወጥን አታገኝም፡፡'),
('17:78', 87, 'ሶላትን ከፀሐይ መዘንበል እስከ ሌሊት ጨለማ ድረስ ስገድ፡፡ የጎህንም ሶላት ስገድ፡፡ የጎህ ሶላት (መላእክት) የሚጣዱት ነውና፡፡'),
('17:79', 87, 'ከሌሊትም ላንተ ተጨማሪ የኾነችን ሶላት በእርሱ (በቁርኣን) ስገድ፡፡ ጌታህ ምስጉን በኾነ ስፍራ በእርግጥ ያቆምሃል፡፡'),
('17:80', 87, 'በልም ጌታዬ ሆይ! የተወደደን ማግባት አግባኝ፡፡ የተወደደንም ማውጣት አውጣኝ፡፡ ለእኔም ከአንተ ዘንድ የተረዳን ስልጣን አድርግልኝ፡፡'),
('17:81', 87, 'በልም «እውነት መጣ ውሸትም ተወገደ፤ እነሆ ውሸት ተወጋጅ ነውና፡፡»'),
('17:82', 87, 'ከቁርኣንም ለምእመናን መድኀኒትና እዝነት የኾነን እናወርዳለን፡፡ በዳዮችንም ከሳራን እንጂ ሌላ አይጨምርላቸውም፡፡'),
('17:83', 87, 'በሰውም ላይ ጸጋችንን በለገስን ጊዜ (ከምስጋና) ይዞራል፡፡ ጎኑንም (ከእውነት) ያርቃል፡፡ ችግርም በነካው ጊዜ ተስፋ ቆራጭ ይኾናል፡፡'),
('17:84', 87, '«ሁሉም በሚመስለው መንገዱ ላይ ይሠራል፡፡ ጌታችሁም እርሱ መንገዱ ቀጥተኛ የኾነውን ሰው ዐዋቂ ነው በላቸው፡፡'),
('17:85', 87, 'ከሩሕም ይጠይቁሃል፡፡ «ሩሕ ከጌታዬ ነገር ነው ከዕውቀትም ጥቂትን እንጂ አልተሰጣችሁም» በላቸው፡፡'),
('17:86', 87, 'ብንሻም ያንን ወዳንተ ያወረድነውን በእርግጥ እናስወግዳለን፡፡ ከዚያም ላንተ በእኛ ላይ በርሱ (ለማስመለስ) ተያዢን አታገኝም፡፡'),
('17:87', 87, 'ግን ከጌታህ በኾነው እዝነት (ጠበቅነው)፡፡ ችሮታው ባንተ ላይ ታላቅ ነውና፡፤'),
('17:88', 87, '«ሰዎችም ጋኔኖችም የዚህን ቁርኣን ብጤ በማምጣት ላይ ቢሰበሰቡ ከፊላቸው ለከፊሉ ረዳት ቢሆንም እንኳ ብጤውን አያመጡም» በላቸው፡፡'),
('17:89', 87, 'በዚህም ቁርኣን ውስጥ ከምሳሌው ሁሉ ለሰዎች በእርግጥ መላለስን፡፡ አብዛኞቹም ሰዎች ክህደትን እንጂ ሌላን እምቢ አሉ፡፡'),
('17:90', 87, 'አሉም «ለኛ ከምድር ምንጭን እስከምታፈነዳን ለአንተ አናምንም፡፡»'),
('17:91', 87, '«ወይም ከዘምባባዎችና ከወይን የኾነች አትክልት ለአንተ እስከምትኖርህና በመካከልዋም ጂረቶችን በብዛት እስከምታንቧቧ፡፡'),
('17:92', 87, '«ወይም እንደምትለው ከሰማይ ቁራጮችን በኛ ላይ እስከምታወድቅ፤ ወይም አላህንና መላእክትን በግልጽ እስከምታመጣ፡፡'),
('17:93', 87, '«ወይም ከወርቅ የኾነ ቤት ላንተ እስከሚኖርህ፤ ወይም በሰማይ እስከምትወጣ፤ ለመውጣትህም በእኛ ላይ የምናነበው የኾነን መጽሐፍ እስከምታወርድልን ድረስ ፈጽሞ አናምንልህም» (አሉ)፡፡ «ጌታዬ ጥራት ይገባው፤ እኔ ሰው መልክተኛ እንጂ ሌላ አይደለሁም» በላቸው፡፡'),
('17:94', 87, 'ሰዎችንም መሪ (ቁርኣን) በመጣላቸው ጊዜ ከማመን «አላህ ሰውን መልክተኛ አድርጎ ላከን» ማለታቸው እንጂ ሌላ አልከለከላቸውም፡፡'),
('17:95', 87, '«በምድር ላይ ረግተው የሚኼዱ መላእክት በነበሩ ኖሮ በእነሱ ላይ (ከጎሳቸው) የመልአክን መልክተኛ ባወረድን ነበር» በላቸው፡፡'),
('17:96', 87, '«በእኔና በእናንተ መካከል መስካሪ በአላህ በቃ፡፡ እርሱ በባሮቹ (ነገር) ውስጥ ዐዋቂ ተመልካች ነውና» በላቸው፡፡'),
('17:97', 87, 'አላህም ያቀናው ሰው ቅኑ እርሱ ብቻ ነው፡፡ ያጠመማቸውም ሰዎች ከእርሱ ሌላ ለእነርሱ ፈጽሞ ረዳት አታገኝላቸውም፡፡ በትንሣኤ ቀንም ዕውሮች፣ ዲዳዎችም ደንቆሮዎችም ኾነው በፊቶቻቸው ላይ (እየተጎተቱ) እንሰበስባቸዋለን፡፡ መኖሪያቸው ገሀነም ናት፡፡ (ነዲድዋ) በደከመች ቁጥር መንቀልቀልን እንጨምርባቸዋለን፡፤'),
('17:98', 87, 'ይህ (ቅጣት)፤ እነርሱ በአንቀጾቻችን ስለ ካዱና «አጥንቶችና ብስብሶች በኾን ጊዜ እኛ አዲስ ፍጥረት ኾነን ተቀስቃሾች ነን» ስላሉም ፍዳቸው ነው፡፡'),
('17:99', 87, 'ያ ሰማያትንና ምድርን የፈጠረ አላህ ብጤያቸውን በመፍጠር ላይ ቻይ መኾኑን በእርሱ ጥርጣሬ የሌለበትም ጊዜ (ለሞትም ለትንሣኤም) ለእነርሱ የወሰነ መኾኑን አላወቁምን በደለኞችም ከክህደት በቀር እምቢ አሉ፡፡'),
('17:100', 87, '«እናንተ የጌታዬን የችሮታ መካዚኖች ብትይዙ ኖሮ ያን ጊዜ በማውጣታችሁ ማለቋን በመፍራት በጨበጣችሁ ነበር፡፡ ሰውም በጣም ቆጣቢ ነው፡፡»'),
('17:101', 87, 'ለሙሳም ግልጽ የኾኑን ዘጠኝ ተዓምራቶች በእርግጥ ሰጠነው፡፡ በመጣቸውም ጊዜ የእስራኤልን ልጆች (ከፈርዖን እንዲለቀቁ) ጠይቅ (አልነው)፡፡ ፈርዖንም «ሙሳ ሆይ! እኔ የተደገመብህ መኾንህን በእርግጥ እጠረጥራለሁ» አለው፡፡'),
('17:102', 87, '(ሙሳም) «እነዚህን (ተዓምራቶች) መገሰጫዎች ሲኾኑ የሰማያትና የምድር ጌታ እንጂ ሌላ እንዳላወረዳቸው በእርግጥ ዐውቀሃል፡፡ እኔም ፈርዖን ሆይ! የምትጠፋ መኾንህን በእርግጥ እጠረጥርሃለሁ» አለው፡፡'),
('17:103', 87, 'ከምድርም ሊቀሰቅሳቸው አሰበ፡፡ እርሱንና ከእርሱ ጋር የነበሩትንም ሰዎች ሁሉንም አሰጠምናቸው፡፡'),
('17:104', 87, 'ከእርሱም በኋላ ለእሰራኤል ልጆች «ምድሪቱን ተቀመጡባት የኋለኛይቱም (ሰዓት) ቀጠሮ በመጣ ጊዜ እናንተን የተከማቻችሁ ስትኾኑ እናመጣችኋለን» አልናቸው፡፡'),
('17:105', 87, '(ቁርኣንን) በውነትም አወረድነው፡፡ በእውነትም ወረደ፡፡ አንተንም አብሳሪና አስጠንቃቂ አድርገን እንጂ አልላክንህም፡፡'),
('17:106', 87, 'ቁርኣንንም በሰዎች ላይ በዝግታ ላይ ኾነህ ታነበው ዘንድ ከፋፈልነው፡፡ ቀስ በቀስ ማውረድንም አወረድነው፡፡'),
('17:107', 87, '«በእርሱ እመኑ ወይም አትመኑ» በላቸው፤ እነዚያ ከእርሱ በፊት ዕውቀትን የተሰጡት በእነሱ ላይ በተነበበ ጊዜ ሰጋጆች ኾነው በሸንጎበቶቻቸው ላይ ይወድቃሉ፤'),
('17:108', 87, 'ይላሉም «ጌታችን ጥራት ይገባው! እነሆ የጌታችን ተስፋ ተፈጻሚ ነው፡፡»'),
('17:109', 87, 'እያለቀሱም በሸንጎበቶቻቸው ላይ ይወድቃሉ (አላህን) መፍራትንም ይጨምራላቸዋል፡፡'),
('17:110', 87, '«አላህን ጥሩ፤ ወይም አልረሕማንን ጥሩ፤ (ከሁለቱ) ማንኛውንም ብትጠሩ (መልካም ነው)፡፡ ለእርሱ መልካም ስሞች አሉትና» በላቸው፡፡ በስግደትህም (ስታነብ) አትጩህ፡፡ በእርሷም ድምጽህን ዝቅ አታድርግ በዚህም መካከል መንገድን ፈልግ፡፡'),
('17:111', 87, '«ምስጋና ለአላህ ለዚያ ልጅን ላልያዘው፣ ለእርሱም በንግሥናው ተጋሪ ለሌለው፣ ለእርሱም ከውርደት ረዳት ለሌለው ይገባው በልም፡፡ ማክበርንም አክብረው፡፡»'),
('18:1', 87, 'ምስጋና ለአላህ ለዚያ መጽሐፉን በውስጡ መጣመምን ያላደረገበት ሲሆን በባሪያው ላይ ላወረደው ይገባው፡፡'),
('18:2', 87, 'ቀጥተኛ ሲሆን ከእርሱ ዘንድ የኾነን ብርቱን ቅጣት ሊያስፈራራበት፣ እነዚያንም በጎ ሥራዎችን የሚሠሩትን ምእመናን ለነሱ መልካም ምንዳ ያላቸው መኾኑን ሊያበስርበት፤ (አወረደው)፡፡'),
('18:3', 87, 'በእርሱ ውስጥ ዘለዓለም የሚቆዩበት ሲኾኑ (ያላቸው መኾኑን)፡፡'),
('18:4', 87, 'እነዚያንም «አላህ ልጅን ይዟል» ያሉትን ሊያስፈራራበት (አወረደው)፡፡'),
('18:5', 87, 'ለእነሱም ለአባቶቻቸውም በርሱ ምንም እውቀት የላቸውም፡፡ ከአፎቻቸው የምትወጣውን ቃል ምን አከበዳት! ውሸትን እንጂ አይናገሩም፡፡'),
('18:6', 87, 'በዚህም ንግግር (በቁርኣን) ባያምኑ በፈለጎቻቸው ላይ በቁጭት ነፍስህን አጥፊ ልትሆን ይፈራልሃል፡፡'),
('18:7', 87, 'እኛ ማንኛቸው ሥራው ያማረ መኾኑን ልንፈትናቸው በምድር ላይ ያለን ሁሉ ለእርሷ ጌጥ አደረግን፤'),
('18:8', 87, 'እኛም በእርሷ ላይ ያለውን (በመጨረሻ) በእርግጥ በቃይ የሌለበት ምልጥ ዐፈር አድራጊዎች ነን፡፡'),
('18:9', 87, 'የዋሻውና የሰሌዳው ባለቤቶች ከተዓምራቶቻችን ሲሆኑ ግሩም መሆናቸውን አሰብክን'),
('18:10', 87, 'ጎበዞቹ ወደ ዋሻው በተጠጉና «ጌታችን ሆይ! ከአንተ ዘንድ እዝነትን ስጠን፤ ለእኛም ከነገራችን ቅንን አዘጋጅልን» ባሉ ጊዜ (አስታውስ)፡፡'),
('18:11', 87, 'በዋሻውም ውስጥ የተቆጠሩን ዓመታት በጆሮዎቻቸው ላይ መታንባቸው፡፡'),
('18:12', 87, 'ከዚያም ከሁለቱ ክፍሎች ለቆዩት ጊዜ ልክ ያረጋገጠው ማንኛው መሆኑን ልናውቅ አስነሳናቸው፡፡'),
('18:13', 87, 'እኛ ወሬያቸውን በአንተ ላይ በእውነት እንተርካለን፡፡ እነሱ በጌታቸው ያመኑ ጎበዞች ናቸው፡፡ መመራትንም ጨመርንላቸው፡፡'),
('18:14', 87, '(በንጉሣቸው ፊት) በቆሙና «ጌታችን የሰማያትና የምድር ጌታ ነው፡፡ ከእርሱ ሌላ አምላክን አንገዛም፡፡ ያን ጊዜ (ሌላን ብናመልክ) ወሰን ያለፈን (ንግግር) በእርግጥ ተናገርን፡፡» ባሉ ጊዜ ልቦቻቸውን አጠነከርን፡፡'),
('18:15', 87, '«እነዚህ ሕዝቦቻችን ከእርሱ ሌላ አማልክትን ያዙ፤ (እውነተኞች ከኾኑ) በእነርሱ ላይ ግልጽ ማስረጃን ለምን አያመጡም በአላህም ላይ ውሸትን ከሚቀጣጥፍ ይበልጥ በዳይ ማነው» (አሉ)፡፡'),
('18:16', 87, '«እነርሱንና ያንን ከአላህ ሌላ የሚግገዙትን በተለያችሁ ጊዜ ወደ ዋሻው ተጠጉ፡፡ ጌታችሁ ለእናንተ ከችሮታው ይዘረጋላችኋልና፤ ከነገራችሁም ለእናንተ መጠቃቀሚያን ያዘጋጅላችኋል» (ተባባሉ)፡፡'),
('18:17', 87, 'ፀሐይንም በወጣች ጊዜ ከዋሻቸው ወደ ቀኝ ጎን ስታዘነብል ታያታለህ፡፡ በገባችም ጊዜ እነርሱ ከእርሱ በሰፊው ስፍራ ውስጥ ኾነው ሳሉ ወደ ግራ በኩል ትተዋቸዋለች፡፡ ይህ ከአላህ ተዓምራቶች ነው፡፡ አላህ የሚያቀናው ሰው ቅኑ እርሱ ብቻ ነው፡፡ የሚያጠመውም ሰው ለርሱ አቅኝን ረዳት አታገኝለትም፡፡'),
('18:18', 87, 'እነሱም የተኙ ሆነው ሳሉ (ዓይኖቻቸው በመከፈታቸው) ንቁዎች ናቸው ብለህ ታስባቸዋለህ፡፡ ወደ ቀኝ ጎንና ወደ ግራ ጎንም እናገላብጣቸዋለን፡፡ ውሻቸውም ሁለት ክንዶቹን በዋሻው በር ላይ ዘርግቷል፡፡ በእነሱ ላይ ዘልቀህ ብታይ ኖሮ የምትሸሽ ኾነህ በዞርክ ነበር፡፡ ከእነሱም በእርግጥ ፍርሃትን በተመላህ ነበር፡፡'),
('18:19', 87, 'እንዲሁም በመካከላቸው እንዲጠያየቁ ቀሰቀስናቸው፡፡ ከእነሱ አንድ ተናጋሪ «ምን ያክል ቆያችሁ» አለ፡፡ «አንድን ቀን ወይም የቀንን ከፊል ቆየን» አሉ፡፡ «ጌታችሁ የቆያችሁትን ጊዜ ልክ ዐዋቂ ነው፡፡ ከዚህችም ብራችሁ ጋር አንዳችሁን ወደ ከተማይቱ ላኩ፡፡ ከምግቦቿ የትኛዋ ንጹሕ መሆኗንም ይመልከት፡፡ ከእርሱም (ከንጹሑ) ምግብን ያምጣላችሁ፡፡ ቀስም ይበል፡፡ በእናንተም አንድንም ሰው አያሳውቅ» አሉ፡፡'),
('18:20', 87, '«እነሱ በእናንተ ላይ ቢዘልቁ ይቀጠቅጧችኋልና፡፡ ወይም ወደ ሃይማኖታቸው ይመልሷችኋል፡፡ ያንጊዜም በፍጹም ፍላጎታችሁን አታገኙም» (ተባባሉ)፡፡'),
('18:21', 87, 'እንደዚሁም የአላህ ቀጠሮ እርግጠኛ መሆኑን ሰዓቲቱም በርሷ ጥርጣሬ የሌለ መሆኑን ያውቁ ዘንድ በእነርሱ ላይ (ሰዎችን) አሳወቅን፡፡ (አማኞቹና ከሓዲዎቹ) ነገራቸውን በመካከላቸው ሲከራከሩ (የሆነውን አስታውስ፤ ከሓዲዎቹ)፡- «በእነሱ ላይም ግንብን ገንቡ» አሉ፡፡ ጌታቸው በእነሱ ይበልጥ ዐዋቂ ነው፡፡ እነዚያ በነገራቸው ላይ ያሸነፉት (ምእመናን) «በእነሱ ላይ በእርግጥ መስጊድን እንሠራለን» አሉ፡፡'),
('18:22', 87, 'በሩቅ ወርዋሪዎች ሆነው (በጥርጣሬ) «ሦስት ናቸው፤ አራተኛቸው ውሻቸው ነው» ይላሉ፡፡ «አምስት ናቸው፤ ስድስተኛቸው ውሻቸው ነውም» ይላሉ፡፡ «ሰባት ናቸው፤ ስምንተኛቸውም ውሻቸው ነው» ይላሉም፡፡ «ጌታዬ ቁጥራቸውን ዐዋቂ ነው፡፡ ጥቂት (ሰው) እንጂ አያውቃቸውም» በላቸው፡፡ በእነሱም ነገር ግልጽን ክርክር እንጂ (ጠልቀህ) አትከራከር፡፡ በእነሱም ጉዳይ ከነሱ (ከመጽሐፉ ሰዎች) አንድንም አትጠይቅ፡፡'),
('18:23', 87, 'ለማንኛውም ነገር «እኔ ይህንን ነገ ሠሪ ነኝም» አትበል፡፡'),
('18:24', 87, '«አላህ የሻ እንደ ሆነ (እሰራዋለሁ)» ብትል እንጂ፡፡ በረሳህም ጊዜ ጌታህን አውሳ፡፡ «ጌታዬም ከዚህ ይበልጥ ለቀጥታ የቀረበን ሊመራኝ ይከጀላል» በላቸው፡፡'),
('18:25', 87, 'በዋሻቸውም ውስጥ ሶስት መቶ ዓመታትን ቆዩ፡፡ ዘጠኝንም ጨመሩ፡፡'),
('18:26', 87, '«አላህ የቆዩትን ልክ ዐዋቂ ነው» በላቸው፡፡ የሰማያትና የምድር ምስጢር የእሱ ብቻ ነው፡፡ እርሱ ምን ያይ! ምን ይሰማም! ለእነርሱ ከእርሱ በቀር ምንም ረዳት የላቸውም፡፡ በፍርዱም አንድንም አያጋራም፡፡'),
('18:27', 87, 'ከጌታህም መጽሐፍ ወደ አንተ የተወረደውን አንብብ፡፡ ለቃላቶቹ ለዋጭ የላቸውም፡፡ ከእርሱም በቀር መጠጊያን በፍጹም አታገኝም፡፡'),
('18:28', 87, 'ነፍስህንም፤ ከእነዚያ ጌታቸውን ፊቱን (ውዴታውን) የሚሹ ኾነው በጧትና በማታ ከሚግገዙት ጋር አስታግስ፡፡ የቅርቢቱንም ሕይወት ሽልማት የምትሻ ሆነህ ዓይኖችህ ከእነሱ (ወደ ሌላ) አይለፉ፡፡ ልቡንም እኛን ከማስታወስ ያዘነጋነውን ፍላጎቱንም የተከተለውን ነገሩም ሁሉ ወሰን ማለፍ የሆነውን ሰው አትታዘዝ፡፡'),
('18:29', 87, '«እውነቱም ከጌታችሁ ነው፡፡ የሻም ሰው ይመን፤ የሻም ሰው ይካድ» በላቸው፡፡ እኛ ለበደለኞች አጥሯ በእነሱ የከበበ የኾነችውን እሳት አዘጋጅተናል፡፡ (ከጥም) እርዳታንም ቢፈልጉ እንደ ዘይት ዝቃጭ ባለ ፊቶችን በሚጠብስ ውሃ ይረዳሉ፡፡ መጠጡ ከፋ! መደገፊያይቱም ምንኛ አስከፋች!'),
('18:30', 87, 'እነዚያ ያመኑና መልካም ሥራዎችንም የሠሩ እኛ ሥራን ያሳመረን ሰው ምንዳ አናጠፋም፡፡'),
('18:31', 87, 'እነዚያ ለእነሱ የመኖሪያ ገነቶች ከሥሮቻቸው ወንዞች የሚፈሱባቸው አሏቸው፡፡ በእርሷ ውስጥ ከወርቅ የኾኑን አንባሮች ይሸለማሉ፡፡ ከቀጭን ሐርና ከወፍራም ሐርም አረንጓዴን ልብሶች ይለብሳሉ፡፡ በውስጧ በባለ አጎበር አልጋዎች ላይ የተደገፉ ኾነው (ይቀመጣሉ)፡፡ ምንዳቸው ምን ያምር! መደገፊያይቱም ምንኛ አማረች!'),
('18:32', 87, 'ለእነሱም የሁለትን ሰዎች ምሳሌ ግለጽላቸው፡፡ ለአንደኛቸው (ለከሓዲው) ከወይኖች የኾኑን ሁለት አትክልቶች አደረግንለት፡፡ በዘምባባም አከበብናቸው፡፡ በመካከላቸውም አዝመራን አደረግን፡፡'),
('18:33', 87, 'ሁለቱም አትክልቶች ሰብላቸውን ሰጡ፡፡ ከእርሱም ምንም አላጎደሉም፡፡ በመካከላቸውም ወንዝን አፈሰስን፡፡'),
('18:34', 87, 'ለእርሱም (ከአትክልቶቹ ሌላ ፍሬያማ) ሀብት ነበረው፡፡ ለጓደኛውም (ለአማኙ) እርሱ የሚወዳደረው ሲኾን «እኔ ካንተ በገንዘብ ይበልጥ የበዛሁ በወገንም ይበልጥ የበረታሁ ነኝ» አለው፡፡'),
('18:35', 87, 'እርሱም ነፍሱን በዳይ ኾኖ ወደ አትክልቱ ገባ፡፡ «ይህች ዘለዓለም ትጠፋለች ብዬ አልጠረጥርም» አለ፡፡'),
('18:36', 87, '«ሰዓቲቱንም ቋሚ (ኋኝ) ናት ብዬ አልጠረጥርም፡፡ (እንደምትለው) ወደ ጌታዬም ብመለስ ከእርሷ የበለጠን መመለሻ በእርግጥ አገኛለሁ» (አለው)፡፡'),
('18:37', 87, 'ጓደኛው (አማኙ) እርሱ ለእርሱ የሚመላለሰው ሲኾን «በዚያ ከዐፈር፣ ከዚያም ከፍትወት ጠብታ ከፈጠረህ፣ ከዚያም ሰው ባደረገህ (አምላክ) ካድክን» አለው፡፡'),
('18:38', 87, '«እኔ ግን እርሱ አላህ ጌታዬ ነው፤ (እላለሁ)፡፡ በጌታዬም አንድንም አላጋራም፡፡'),
('18:39', 87, '«አትክልትህንም በገባህ ጊዜ አላህ የሻው ይኾናል፤ በአላህ ቢኾን እንጂ ኀይል የለም፤ አትልም ኖሯልን እኔን በገንዘብም በልጅም ካንተ በጣም ያነስኩ ሆኜ ብታየኝ፡፡'),
('18:40', 87, '«ጌታዬ ከአትክልትህ የበለጠን ሊሰጠኝ በርሷም (በአትክልትህ) ላይ ከሰማይ መብረቆችን ሊልክባትና የምታንዳልጥ ምልጥ ምድር ልትኾን ይቻላል፡፡'),
('18:41', 87, 'ወይም ውሃው ሠራጊ ሊኾን (ይችላል)፡፡ ያን ጊዜ ለርሱ መፈለግን ፈጽሞ አትችልም» (አለው)፡፡'),
('18:42', 87, 'ሀብቱም ተጠፋ፡፡ እርሷ በዳሶቿ ላይ የወደቀች ኾና በእርሷ ባወጣው ገንዘብ ላይ (እየተጸጸተ) መዳፎቹን የሚያገላብጥና «ወይ ጸጸቴ! በጌታዬ አንድም ባላጋራሁ» የሚል ኾነ፡፡'),
('18:43', 87, 'ለእርሱም ከአላህ ሌላ የሚረዱት ጭፍሮች አልነበሩትም፡፡ ተረጂም አልነበረም፡፡'),
('18:44', 87, 'እዚያ ዘንድ (በትንሣኤ ቀን) ስልጣኑ እውነተኛ ለኾነው አላህ ብቻ ነው፡፡ እርሱ በመመንዳት የበለጠ ፍጻሜንም በማሳመር የበለጠ ነው፡፡'),
('18:45', 87, 'ለእነሱም የቅርቢቱን ሕይወት ምሳሌ አውሳላቸው፡፡ (እርሷ) ከሰማይ እንዳወረድነው ውሃ በእርሱም የምድር በቃይ እንደ ተቀላቀለበት (ከተዋበ በኋላ ደርቆ) ነፋሶችም የሚያበኑት ደቃቅ እንደ ኾነ ብጤ ናት፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('18:46', 87, 'ገንዘብና ወንዶች ልጆች የቅርቢቱ ሕይወት ጌጦች ናቸው፡፡ መልካሞቹም ቀሪዎች (ሥራዎች) እጌታህ ዘንድ በምንዳ በላጭ ናቸው፡፡ በተስፋም በላጭ ናቸው፡፤'),
('18:47', 87, 'ተራራዎችንም የምናስኼድበትን ቀን (አስታውስ)፡፡ ምድርንም ግልጽ ኾና ታያታለህ፡፡ እንሰበስባቸዋለንም፡፡ ከእነሱም አንድንም አንተውም፡፡'),
('18:48', 87, 'የተሰለፉም ኾነው በጌታህ ላይ ይቀረባሉ፡፡ (ይባላሉም) «በመጀመሪያ ጊዜ እንደ ፈጠርናችሁ (ራቁታችሁን) በእርግጥ መጣችሁን በእውነቱ ለእናንተ (ለመቀስቀሻ) ጊዜን አናደርግም መስሏችሁ ነበር፡፡»'),
('18:49', 87, '(ለሰው ሁሉ) መጽሐፉም ይቀርባል፡፡ ወዲያውም ከሓዲዎችን በውስጡ ካለው ነገር ፈሪዎች ኾነው ታያቸዋለህ፡፡ «ዋ ጥፋታችን! ለዚህ መጽሐፍ (ከሥራ) ትንሽንም ትልቅንም የቆጠራት ቢኾን እንጂ የማይተወው ምን አለው» ይላሉም፡፡ የሰሩትንም ነገር ሁሉ ቀራቢ ኾኖ ያገኙታል፡፡ ጌታህም አንድንም አይበድልም፡፡'),
('18:50', 87, 'ለመላእክትም ለአደም ስገዱ ባልናቸው ጊዜ (የኾነውን አስታውስ)፡፡ ወዲያውም ሰገዱ፤ ኢብሊስ ብቻ ሲቀር፡፡ ከጋኔን (ጎሳ) ነበር፡፡ ከጌታውም ትእዛዝ ወጣ፡፡ እርሱንና ዘሮቹን እነርሱ ለእናንተ ጠላቶች ሲኾኑ ከእኔ ላይ ረዳቶች አድርጋችሁ ትይዛላችሁን ለበዳዮች ልዋጭነቱ ከፋ!'),
('18:51', 87, 'የሰማያትንና የምድርን አፈጣጠር አላሳየኋቸውም፡፡ የነፍሶቻቸውንም አፈጣጠር (እንደዚሁ)፡፡ አሳሳቾችንም ረዳቶች አድርጌ የምይዝ አይደለሁም፡፡'),
('18:52', 87, '«እነዚያንም (አምላክ) የምትሏቸውን ተጋሪዎቼን ጥሩ» የሚልበትን ቀን (አስታውስ)፡፡ ይጠሯቸዋልም ግን አይመልሱላቸውም፡፡ በመካከላቸውም መጥፊያን ስፍራ (ገሀነምን) አደረግን፡፡'),
('18:53', 87, 'ከሓዲዎችም እሳትን ያያሉ፡፡ እነርሱም በውስጧ ወዳቂዎች መኾናቸውን ያረጋግጣሉ፡፡ ከእርሷም መሸሻን አያገኙም፡፡'),
('18:54', 87, 'በዚህም ቁርኣን ውስጥ ከየምሳሌው ሁሉ ለሰዎች መላልሰን ገለጽን፡፡ ሰውም ከነገሩ ሁሉ ይበልጥ ክርክረ ብዙ ነው፡፡'),
('18:55', 87, 'ሰዎችንም መምሪያ በመጣላቸው ጊዜ ከማመንና ጌታቸውንም ምሕረትን ከመለመን የመጀመሪዎቹ (ሕዝቦች) ልማድ (መጥፋት) ልትመጣባቸው ወይም ቅጣቱ በያይነቱ ሊመጣባቸው (መጠባበቅ) እንጂ ሌላ አልከለከላቸውም፡፡'),
('18:56', 87, 'መልክተኞችንም አብሳሪዎችና አስፈራሪዎች ኾነው እንጂ አንልክም፡፡ እነዚያ የካዱትም በውሸት እውነቱን በእሱ ሊያበላሹ ይከራከራሉ፡፡ አንቀጾቼንና በእርሱ የተስፈራሩበትንም ነገር ማላገጫ አድርገው ያዙ፡፡'),
('18:57', 87, 'በጌታውም አንቀጾች ከተገሰጸና ከእርሷ ከዞረ እጆቹም ያስቀደሙትን ነገር ከረሳ ሰው ይበልጥ በዳይ ማነው እኛ በልቦቻቸው ላይ እንዳያውቁት ሺፋኖችን በጆሮዎቻቸውም ውስጥ ድንቁርናን አደረግን፡፡ ወደ መመራትም ብትጠራቸው ያን ጊዜ ፈጽሞ አይምመሩም፡፡'),
('18:58', 87, 'ጌታህም በጣም መሃሪው የእዝነት ባለቤቱ ነው፡፡ በሠሩት ሥራ ቢይዛቸው ኖሮ ቅጣቱን ለእነሱ ባስቸኮለባቸው ነበር፡፡ ግን ለእነሱ ከእርሱ ሌላ መጠጊያን ፈጽሞ የማያገኙበት ቀጠሮ አላቸው፡፡'),
('18:59', 87, 'እነዚህ ከተሞችም በበደሉ ጊዜ አጠፋናቸው፡፡ ለመጥፊያቸውም የተወሰነ ጊዜን አደረግን፡፡'),
('18:60', 87, 'ሙሳም ለወጣቱ «የሁለቱን ባሕሮች መገናኛ እስከምደርስ ወይም ብዙን ጊዜ እስከምኼድ ድረስ (ከመጓዝ) አልወገድም» ያለውን (አስታውስ)፡፡'),
('18:61', 87, 'የሁለቱን መገናኛ በደረሱም ጊዜ ዐሣቸውን ረሱ፡፡ (ዐሣው) መንገዱንም በባህሩ ውስጥ ቀዳዳ አድርጎ ያዘ፡፡'),
('18:62', 87, 'ባለፉም ጊዜ ለወጣቱ «ምሳችንን ስጠን፡፡ ከዚህ ጉዟችን በእርግጥ ድካምን አግኝተናልና» አለ፡፡'),
('18:63', 87, '«አየህን ወደ ቋጥኝዋ በተጠጋን ጊዜ እኔ ዐሣውን ረሳሁ፡፡ ማስታወሱንም ሰይጣን እንጂ ሌላ አላስረሳኝም፡፡ በባሕሩም ውስጥ መንገዱን አስደናቂ (መንገድ) አድርጎ ያዘ» አለ፡፡'),
('18:64', 87, '(ሙሳም) ይህ እንፈልገው የነበርነው ነው አለው፡፡ በፈለጎቻቸውም ላይ እየተከተሉ ተመለሱ፡፡'),
('18:65', 87, 'ከባሮቻችንም ከእኛ ዘንድ ችሮታን የሰጠነውን ከእኛም ዘንድ ዕውቀትን ያስተማርነውን አንድን ባሪያ (ኸድርን) አገኙ፡፡'),
('18:66', 87, 'ሙሳ ለእርሱ «ከተማርከው ነገር ቀጥተኛን (ዕውቀት) ታስተምረኝ ዘንድ ልከተልህን» አለው፡፡'),
('18:67', 87, '(ባሪያውም) አለ «አንተ ከእኔ ጋር መታገስን በጭራሽ አትችልም፡፡'),
('18:68', 87, '«በዕውቀትም በእርሱ ባላዳረስከው ነገር ላይ እንዴት ትታገሳለህ»'),
('18:69', 87, '(ሙሳ) «አላህ የሻ እንደ ኾነ ታጋሽና ላንተ ትዕዛዝን የማልጥስ ኾኜ ታገኘኛለህ» አለው፡፡'),
('18:70', 87, '«ብትከተለኝም ለአንተ ከእርሱ ማውሳትን እስከምጀምርልህ ድረስ ከምንም ነገር አትጠይቀኝ» አለው፡፡'),
('18:71', 87, 'ኼዱም፡፡ በመርከቢቱም በተሳፈሩ ጊዜ ቀደዳት፡፡ «ባለ ቤቶቿን ልታሰጥም ቀደድካትን ትልቅ ነገርን በእርግጥ ሠራህ» አለው፡፡'),
('18:72', 87, '«አንተ ከኔ ጋር ትእግሥትን ፈጽሞ አትችልም አላልኩምን» አለ፡፡'),
('18:73', 87, '«በረሳሁት ነገር አትያዘኝ፡፡ ከነገሬም ችግርን አታሸክመኝ» አለው፡፡'),
('18:74', 87, '(ወርደው) ተጓዙም፡፡ ወጣትንም ልጅ ባገኙና በገደለው፤ «ጊዜ ያለ ነፍስ (መግደል) ንጹሕን ነፍስ ገደልክን በእርግጥ መጥፎን ነገር ሥራህ» አለው፡፡'),
('18:75', 87, '«አንተ ከኔ ጋር ትእግሥትን ፈጽሞ አትችልም አላልኩህምን» አለ፡፡'),
('18:76', 87, '«ከርሷ (ከአሁኒቱ ጊዜ) በኋላ ከምንም ነገር ብጠይቅህ አትጎዳኘኝ፡፡ ከእኔ የይቅርታን መጨረሻ በእርግጥ ደርሰሃል» አለው፡፡'),
('18:77', 87, 'ኼዱም፡፡ ወደ አንዲት ከተማ ሰዎች በመጡም ጊዜ ነዋሪዎቿን ምግብን ጠየቁ፡፡ ከማስተናገዳቸውም እምቢ አሉ፡፡ በእርሷም ውስጥ ለመውደቅ የተቃረበን ግድግዳ አገኙ፡፡ (ኸድር) አቆመውም፡፡ (ሙሳም) «በሻህ ኖሮ በእርሱ ላይ ዋጋን በተቀበልክ ነበር» አለው፡፡'),
('18:78', 87, '(ኸድር) አለ «ይህ በእኔና በአንተ መካከል መለያያ ነው፡፡ በእርሱ ላይ መታገስን ያልቻልክበትን ፍች እነግርሃለሁ፡፡'),
('18:79', 87, '«መርከቢቱማ በባሕር ለሚሠሩ ምስኪኖች ነበረች፡፡ ከኋላቸውም መርከብን ሁሉ በቅሚያ የሚይዝ ንጉሥ ነበረና፤ (እንዳይቀማቸው) ላነውራት ፈቀድኩ፡፡'),
('18:80', 87, '«ወጣቱም ልጅማ ወላጆቹ ምእመናን ነበሩ፡፡ (ቢያድግ) ትእቢትንና ክህደትንም የሚያስገድዳቸው መኾኑን ፈራን፡፡'),
('18:81', 87, '«ጌታቸውም በንጹሕነት ከእርሱ በላጭን በእዝነትም ከእርሱ በጣም ቀራቢን ልጅ ሊለውጥላቸው ፈለግን፡፡'),
('18:82', 87, '«ግድግዳውማ በከተማይቱ ውስጥ የነበሩ የሁለት የቲሞች ወጣቶች ነበር፡፡ በሥሩም ለእነርሱ የኾነ (የተቀበረ) ድልብ ነበረ፡፡ አባታቸውም መልካም ሰው ነበር፡፡ ጌታህም ለአካለ መጠን እንዲደርሱና ከጌታህ ችሮታ ድልባቸውን እንዲያወጡ ፈቀደ፡፡ በፈቃዴም አልሠራሁትም፡፡ ይህ በእርሱ ላይ መታገስን ያልቻልከው ነገር ፍች ነው» (አለው)፡፡'),
('18:83', 87, 'ከዙልቀርነይንም ይጠይቁሃል፡፡ «በእናንተ ላይ ከእርሱ ወሬን አነባለሁ፤» በላቸው፡፡'),
('18:84', 87, 'እኛ ለእርሱ በምድር አስመቸነው፡፡ ከነገሩም ሁሉ (መዳረሻ) መንገድን ሰጠነው፡፡'),
('18:85', 87, 'መንገድንም (ወደ ምዕራብ) ተከተለ፡፡'),
('18:86', 87, 'ወደ ፀሐይ መግቢያም በደረሰ ጊዜ ጥቁር ጭቃ ባላት ምንጭ ውስጥ ስትጠልቅ አገኛት፡፡ ባጠገቧም ሕዝቦችን አገኘ፡፡ «ዙልቀርነይን ሆይ! ወይም (በመግደል) ትቀጣለህ ወይም በእነርሱ መልካም ነገርን (መማረክን) ትሠራለህ» አልነው፡፤'),
('18:87', 87, '«የበደለውን ሰውማ ወደፊት እንቀጣዋለን፡፡ ከዚያም ወደ ጌታው ይመለሳል፡፡ ብርቱንም ቅጣት ይቀጣዋል» አለ፡፡'),
('18:88', 87, '«ያመነም ሰውማ መልካምንም ሥራ የሠራ ለእርሱ ከምንዳ በኩል መልካሚቱ (ገነት) አለችው፡፡ ለእርሱም ከትእዛዛችን ገርን ነገር እናዘዋለን» (አለ)፡፡'),
('18:89', 87, 'ከዚያም መንገድን (ወደ ምሥራቅ) ቀጠለ፡፡'),
('18:90', 87, 'ወደ ፀሐይ መውጫ በደረሰም ጊዜ ለእነሱ ከበታችዋ መከለያን ባላደረግንላቸው ሕዝቦች ላይ ስትወጣ አገኛት፡፡'),
('18:91', 87, '(ነገሩ) እንደዚሁ ነው፡፡ እርሱም ዘንድ ባለው ነገር ሁሉ በእርግጥ በዕውቀት ከበብን፡፡'),
('18:92', 87, 'ከዚያም (ወደ ሰሜን አቅጣጫ) መንገድን ቀጠለ፡፡'),
('18:93', 87, 'በሁለቱ ጋራዎችም መካከል በደረሰ ጊዜ በአቅራቢያቸው ንግግርን ለማወቅ የማይቃረቡ ሕዝቦችን አገኘ፡፡'),
('18:94', 87, '«ዙልቀርነይን ሆይ! የእጁጅና መእጁጅ በምድር ላይ አበላሺዎች ናቸውና በእኛና በእነሱ መካከል ግድብን ታደርግልን ዘንድ ግብርን እናድርግልህን» አሉ፡፡'),
('18:95', 87, 'አለ «ጌታዬ በእርሱ ያስመቸኝ ሀብት (ከናንተ ግብር) በላጭ ነው፡፡ ስለዚህ በጉልበት እገዙኝ፡፡ በእናንተና በእነሱ መካከል ብርቱን ግድብ አደርጋለሁና፡፡'),
('18:96', 87, '«የብረትን ታላላቅ ቁራጮች ስጡኝ» (አላቸው)፡፡ በሁለቱ ኮረብታዎች (ጫፍ) መካከልም ባስተካከለ ጊዜ አናፉ አላቸው፡፡ (ብረቱን) እሳትም ባደረገው ጊዜ «የቀለጠውን ነሐስ ስጡኝ፤ በርሱ ላይ አፈስበታለሁና» አላቸው፡፡'),
('18:97', 87, '(የእጁጅና መእጁጅ) ሊወጡትም አልቻሉም፡፡ ለእርሱ መሸንቆርንም አልቻሉም፡፡'),
('18:98', 87, '«ይህ (ግድብ) ከጌታዬ ችሮታ ነው፡፡ የጌታየም ቀጠሮ በመጣ ጊዜ ትክክል ምድር ያደርገዋል፡፡ የጌታዬም ቀጠሮ ተረጋገጠ ነው» አለ፡፡'),
('18:99', 87, 'በዚያም ቀን ከፊላቸውን በከፊሉ የሚቀላቀሉ አድርገን እንተዋቸዋለን፡፡ በቀንዱም ይነፋል መሰብሰብንም እንሰበስባቸዋለን፡፤'),
('18:100', 87, 'ገሀነምንም በዚያ ቀን ለከሓዲዎች በጣም ማቅረብን እናቀርባታለን፡፡'),
('18:101', 87, 'ለዚያ ዓይኖቻቸው ከግሳጼዬ በሺፋን ውስጥ ለነበሩትና መስማትንም የማይችሉ ለነበሩት (እናቀርባታለን)፡፡'),
('18:102', 87, 'እነዚያ የካዱት ባሮቼን ከእኔ ሌላ አማልክት አድርገው መያዛቸውን (የማያስቆጣኝ አድርገው) አሰቡን እኛ ገሀነምን ለከሓዲዎች መስተንግዶ አዘጋጅተናል፡፡'),
('18:103', 87, '«በሥራዎች በጣም ከሳሪዎቹን እንንገራችሁን» በላቸው፡፡'),
('18:104', 87, 'እነዚያ እነሱ ሥራን የሚያሳምሩ የሚመስላቸው ሲሆኑ በቅርቢቱ ሕይወት ሥራቸው የጠፋባቸው ናቸው፡፡'),
('18:105', 87, 'እነዚያ እነርሱ በጌታቸው ማስረጃዎችና በመገናኘቱ የካዱት ናቸው፡፡ ሥራዎቻቸውም ተበላሹ፡፡ ለእነሱም በትንሣኤ ቀን (ጠቃሚ) ሚዛንን አናቆምላቸውም፡፡'),
('18:106', 87, '(ነገሩ) ይህ ነው፡፡ በክህደታቸው አንቀጾቼንና መልክተኞቼንም መሳለቂያ አድርገው በመያዛቸው ፍዳቸው ገሀነም ነው፡፡'),
('18:107', 87, 'እነዚያ ያመኑና መልካም ሥራዎችን የሠሩ የፊርደውስ ገነቶች ለእነሱ መስፈሪያ ናቸው፡፡'),
('18:108', 87, 'በእርሷ ውስጥ ዘውታሪዎች ከእርሷ መዛወርን የማይፈልጉ ሲኾኑ፤ (መስፈሪያቸው ነው)፡፡'),
('18:109', 87, '«ባሕሩ ለጌታዬ ቃላት (መጻፊያ) ቀለሞችን በሆነ ኖሮ ብጤውን ጭማሪ ብናመጣም እንኳን የጌታዬ ቃላት ከማለቋ በፊት ባሕሩ ባለቀ ነበር» በላቸው፡፡'),
('18:110', 87, '«እኔ አምላካችሁ አንድ አምላክ ብቻ ነው ማለት ወደኔ የሚወረድልኝ ቢጤያችሁ ሰው ብቻ ነኝ፡፡ የጌታውንም መገናኘት የሚፈልግ ሰው፤ መልካም ሥራን ይሥራ፡፡ በጌታውም መገዛት አንድንም አያጋራ» በላቸው፡፡'),
('19:1', 87, 'ከ.ሀ.የ.ዐ.ጸ (ካፍ ሃ ያ ዓይን ሷድ)'),
('19:2', 87, '(ይህ) ጌታህ ባሪያውን ዘከሪያን በችሮታው ያወሳበት ነው፡፡'),
('19:3', 87, 'ጌታውን የምስጢርን ጥሪ በተጣራ ጊዜ (አስታውስ)፡፡'),
('19:4', 87, 'አለ «ጌታዬ ሆይ! እኔ አጥንቴ ደከመ፤ ራሴም በሺበት ተንቀለቀለ፤ አንተም በመለመኔ ጌታዬ ሆይ! (ምንጊዜም) ዕድለ ቢስ አልሆንኩም፡፡'),
('19:5', 87, '«እኔም ከበኋላዬ ዘመዶቼን በእርግጥ ፈራሁ፡፡ ሚስቴም መካን ነበረች ስለዚህ ከአንተ ዘንድ ለኔ ልጅን ስጠኝ፡፡'),
('19:6', 87, '«የሚወርሰኝ ከያዕቆብ ቤተሰቦችም የሚወርስ የሆነን (ልጅ)፡፡ ጌታዬ ሆይ! ተወዳጅም አድርገው፡፡»'),
('19:7', 87, '«ዘከሪያ ሆይ! እኛ በወንድ ልጅ ስሙ የሕያ በኾነ ከዚህ በፊት ሞክሼን ባላደረግንለት እናበስርሃለን» (አለው)፡፡'),
('19:8', 87, '«ጌታዬ ሆይ! ሚስቴ መካን የነበረች ስትኾን እኔም ከእርጅና ድርቀትን በእርግጥ የደረስኩ ስኾን እንዴት ልጅ ይኖረኛል!» አለ፡፡'),
('19:9', 87, '(ጅብሪል) አለ «(ነገሩ) እንደዚሁ ነው፡፡ ጌታህ፡- ከአሁን በፊት ምንም ያልነበርከውን የፈጠርኩህ ስኾን እርሱ በእኔ ላይ ቀላል ነው» አለ፡፡'),
('19:10', 87, '«ጌታዬ ሆይ! (እንግዲያውስ) ለእኔ ምልክትን አድርግልኝ አለ፡፡ ምልክትህ ጤናማ ሆነህ ሳለህ ሦስት ሌሊትን (ከነቀናቸው) ሰዎችን ለማነጋገር አለመቻልህ ነው» አለው፡፡'),
('19:11', 87, 'ከምኩራቡም በሕዝቦቹ ላይ ወጣ፡፡ በ×ትና በማታ (ጌታችሁን) አወድሱ በማለትም ወደነሱ ጠቀሰ፡፡'),
('19:12', 87, '«የሕያ ሆይ! መጽሐፉን በጥብቅ ያዝ!» (አልነው)፡፡ ጥበብንም በሕፃንነቱ ሰጠነው፡፡'),
('19:13', 87, 'ከእኛም የሆነን ርኅራኄ ንጽሕናንም (ሰጠነው)፡፡ ጥንቁቅም ነበር፡፡'),
('19:14', 87, 'ለወላጆቹም በጎ ሠሪ ነበር፡፡ ትዕቢተኛ አመጸኛም አልነበረም፡፡'),
('19:15', 87, 'በተወለደበት ቀንና በሚሞትበትም ቀን፣ ሕያው ሆኖ በሚነሳበትም ቀን ሰላም በእሱ ላይ ይሁን፡፡'),
('19:16', 87, 'በመጽሐፉ ውስጥ መርየምንም ከቤተሰቧ ወደ ምሥራቃዊ ስፍራ በተለይች ጊዜ (የሆነውን ታሪኳን) አውሳ፡፡'),
('19:17', 87, 'ከእነሱም መጋረጃን አደረገች፡፡ መንፈሳችንምም (ጂብሪልን) ወደርሷ ላክን፡፡ ለእርሷም ትክክለኛ ሰው ሆኖ ተመሰለላት፡፡'),
('19:18', 87, '«እኔ ከአንተ በአልረሕማን እጠበቃለሁ፡፡ ጌታህን ፈሪ እንደ ሆንክ (አትቅረበኝ)» አለች፡፡'),
('19:19', 87, '«እኔ ንጹሕን ልጅ ለአንቺ ልሰጥሽ የጌታሽ መልክተኛ ነኝ» አላት፡፡'),
('19:20', 87, '«(በጋብቻ) ሰው ያልነካኝ ሆኜ አመንዝራም ሳልሆን ለእኔ እንዴት ልጅ ይኖረኛል!» አለች፡፡'),
('19:21', 87, 'አላት «(ነገሩ) እንደዚህሽ ነው፡፡» ጌታሽ «እርሱ በእኔ ላይ ገር ነው፡፡ ለሰዎችም ታምር ከእኛም ችሮታ ልናደርገው (ይህንን ሠራን) የተፈረደም ነገር ነው» አለ፤ (ነፋባትም)፡፡'),
('19:22', 87, 'ወዲያውኑም አረገዘችው፡፡ በእርሱም (በሆዷ ይዛው) ወደ ሩቅ ስፍራ ገለል አለች፡፡'),
('19:23', 87, 'ምጡም ወደ ዘንባባይቱ ግንድ አስጠጋት፡፡ «ዋ ምኞቴ! ምነው ከዚህ በፊት በሞትኩ፡፡ ተረስቼም የቀረሁ በሆንኩ» አለች፡፡'),
('19:24', 87, 'ከበታቿም እንዲህ ሲል ጠራት «አትዘኝ፡፡ ጌታሽ ከበታችሽ ትንሽን ወንዝ በእርግጥ አድርጓል፡፡'),
('19:25', 87, '«የዘምባባይቱንም ግንድ ወዳንቺ ወዝውዣት ባንቺ ላይ የበሰለን የተምር እሸት ታረግፍልሻለችና፡፡'),
('19:26', 87, '«ብይም፣ ጠጭም፣ ተደሰችም፡፡ እኔ ለአልረሕማን ዝምታን ተስያለሁ፤ ዛሬም ሰውን በፍጹም አላነጋግርም» በይ፡፡'),
('19:27', 87, 'በእርሱም የተሸከመቺው ሆና ወደ ዘመዶቿ መጣች፡፡ «መርየም ሆይ! ከባድን ነገር በእርግጥ ሠራሽ» አሏት፡፡'),
('19:28', 87, '«የሃሩን እኅት ሆይ! አባትሽ መጥፎ ሰው አልነበረም፡፡ እናትሽም አመንዝራ አልነበረችም» አሏት፡፡'),
('19:29', 87, 'ወደርሱም ጠቀሰች፡፡ «በአንቀልባ ያለን ሕጻን እንዴት እናናግራለን!» አሉ፡፡'),
('19:30', 87, '(ሕፃኑም) አለ «እኔ የአላህ ባሪያ ነኝ፡፡ መጽሐፍን ሰጥቶኛል ነቢይም አድርጎኛል፡፡»'),
('19:31', 87, '«በየትም ስፍራ ብሆን ብሩክ አድርጎኛል፡፡ በሕይወትም እስካለሁ ሶላትን በመስገድ ዘካንም በመስጠት አዞኛል፡፡»'),
('19:32', 87, '«ለእናቴም ታዛዥ (አድርጎኛል)፡፡ ትዕቢተኛ እምቢተኛም አላደረገኝም፡፡'),
('19:33', 87, '«ሰላምም በእኔ ላይ ነው፡፡ በተወለድሁ ቀን፣ በምሞትበትም ቀን፣ ሕያው ኾኜ በምቀሰቀስበትም ቀን፡፡»'),
('19:34', 87, 'ይህ የመርየም ልጅ ዒሳ ነው፡፡ ያ በርሱ የሚጠራጠሩበት እውነተኛ ቃል ነው፡፡'),
('19:35', 87, 'ለአላህ ልጅን መያዝ አይገባውም፡፡ (ከጉድለት ሁሉ) ጠራ፡፡ ነገርን በሻ ጊዜ ለርሱ የሚለው «ኹን» ነው ወዲያውም ይኾናል፡፡'),
('19:36', 87, '(ዒሳ አለ) «አላህም ጌታዬ ጌታችሁም ነውና ተገዙት፡፡ ይህ ቀጥተኛ መንገድ ነው፡፡»'),
('19:37', 87, 'ከመካከላቸውም አሕዛቦቹ በእርሱ ነገር ተለያዩ፡፡ ለእነዚያም ለካዱት ሰዎች ከታላቁ ቀን መጋፈጥ ወዮላቸው፡፡'),
('19:38', 87, 'በሚመጡን ቀን ምን ሰሚ ምንስ ተመልካች አደረጋቸው! ግን አመጸኞች ዛሬ (በዚህ ዓለም) በግልጽ ስህተት ውስጥ ናቸው፡፤'),
('19:39', 87, 'እነሱም (አሁን) በዝንጋቴ ላይ ኾነው ሳሉ እነሱም የማያምኑ ሲኾኑ ነገሩ በሚፈረድበት ጊዜ የቁልጭቱን ቀን አስፈራራቸው፡፡'),
('19:40', 87, 'እኛ ምድርን በእርሷም ላይ ያለውን ሁሉ እኛ እንወርሳለን፡፡ ወደኛም ይመለሳሉ፡፡'),
('19:41', 87, 'በመጽሐፉ ውስጥ ኢብራሂምንም አውሳ፡፡ እርሱ በጣም እውነተኛ ነቢይ ነበርና፡፡'),
('19:42', 87, 'ለአባቱ ባለ ጊዜ (አስታውስ) «አባቴ ሆይ! የማይሰማንና የማያይን ከአንተም ምንንም የማይጠቅምህን (ጣዖት) ለምን ትግገዛለህ'),
('19:43', 87, '«አባቴ ሆይ! እኔ ከዕውቀት ያልመጣልህ ነገር በእርግጥ መጥቶልኛልና ተከተለኝ፡፡ ቀጥተኛውን መንገድ እመራሃለሁና፡፡'),
('19:44', 87, '«አባቴ ሆይ! ሰይጣንን አትግገዛ፡፡ ሰይጣን ለአልረሕማን አመጸኛ ነውና፡፡'),
('19:45', 87, '«አባቴ ሆይ! እኔ ከአልረሕማን ቅጣት ሊያገኝህ ለሰይጣንም ጓደኛ ልትኾን እፈራለሁ፡፡»'),
('19:46', 87, '(አባቱም) «ኢብራሂም ሆይ! አንተ አምላኮቼን ትተህ የምትዞር ነህን ባትከለከል በእርግጥ እወግርሃለሁ፡፡ ረዥም ጊዜንም ተወኝ» አለ፡፡'),
('19:47', 87, '«ደህና ኹን፡፡ ወደፊት ከጌታዬ ምሕረትን እለምንልሃለሁ፡፡ እርሱ ለኔ በጣም ርኅሩኅ ነውና» አለ፡፡'),
('19:48', 87, '«እናንተንም ከአላህ ሌላ የምትግገዙትንም እርቃለሁ፡፡ ጌታዬንም እግገዛለሁ፡፡ ጌታዬን በመገዛት የማፍር አለመኾኔን እከጅላለሁ፡፡»'),
('19:49', 87, 'እነርሱንም ከአላህ ሌላ የሚግገዙትንም በራቀ ጊዜ ለእርሱ ኢስሐቅንና ያዕቆብን ሰጠነው፡፡ ሁሉንም ነቢይ አደረግንም፡፡'),
('19:50', 87, 'ለእነሱም ከችሮታችን ሰጠናቸው፡፡ ለእነርሱም ከፍ ያለ ምስጉን ዝናን አደረግንላቸው፡፡'),
('19:51', 87, 'በመጽሐፉ ውስጥ ሙሳንም አውሳ፡፡ እርሱ ምርጥ ነበርና፡፡ መልክተኛ ነቢይም ነበር፡፡'),
('19:52', 87, 'ከጡር ቀኝ ጎን በኩልም ጠራነው፡፡ ያነጋገርነውም ሲኾን አቀረብነው፡፡'),
('19:53', 87, 'ከችሮታችንም ወንድሙን ሃሩንን ነቢይ አድርገን ሰጠነው፡፡'),
('19:54', 87, 'በመጽሐፉ ኢስማዒልንም አውሳ፡፡ እርሱ ቀጠሮን አክባሪ ነበረና፡፡ መልክተኛ ነቢይም ነበር፡፡'),
('19:55', 87, 'ቤተሰቦቹንም በሶላትና በዘካ ያዝ ነበር፡፡ እጌታውም ዘንድ ተወዳጅ ነበር፡፡'),
('19:56', 87, 'በመጽሐፉ ኢድሪስንም (ሄኖክን) አውሳ፡፡ እርሱ እውነተኛ ነቢይ ነበርና፡፡'),
('19:57', 87, 'ወደ ከፍተኛም ስፍራ አነሳነው፡፡'),
('19:58', 87, 'እነዚህ (ዐሥሩ) እነዚያ አላህ በእነሱ ላይ የለገሰላቸው ከነቢያት ከአዳም ዘር ከኑሕ ጋር (በመርከቢቱ ላይ) ከጫናቸውም (ዘሮች) ከኢብራሂምና ከእስራኤልም ዘሮች ከመራናቸውና ከመረጥናቸውም የኾኑት የአልረሕማን አንቀጾች በነሱ ላይ በተነበቡ ጊዜ ሰጋጆችና አልቃሾች ኾነው ይወድቃሉ፡፡'),
('19:59', 87, 'ከእነሱም በኋላ ሶላትን ያጓደሉ (የተዉ) ፍላጎቶችንም የተከተሉ መጥፎ ምትኮች ተተኩ! የገሀነምንም ሸለቆ በእርግጥ ያገኛሉ፡፡'),
('19:60', 87, 'ግን የተጸጸተና ያመነም በጎንም ሥራ የሠራ ሰው እነዚህ ገነትን ይገባሉ፡፡ አንዳችንም አይበደሉም፡፡'),
('19:61', 87, 'የመኖሪያን ገነቶች ያችን አልረሕማን ለባሮቹ በሩቅ ኾነው ሳሉ ተስፋ ቃል የገባላቸውን (ይገባሉ)፡፡ እርሱ ተስፋው ተፈጻሚ ነውና፤'),
('19:62', 87, 'በእርሷ ሰላምን እንጂ ውድቅን ነገር አይሰሙም፡፡ ለእነሱም በርሷ ውስጥ ጧትም ማታም ሲሳያቸው አላቸው፡፡'),
('19:63', 87, 'ይህች ያቺ ከባሮቻችን ጥንቁቆች ለኾኑት የምናወርሳት ገነት ናት፡፡'),
('19:64', 87, '(ጂብሪል አለ) «በጌታህም ትእዛዝ እንጅ አንወርድም፡፡ በፊታችን ያለው፣ በኋላችንም ያለው በዚህም መካከል ያለው ሁሉ የርሱ ነው፡፡ ጌታህም ረሺ አይደለም፡፡'),
('19:65', 87, '(እርሱ) የሰማያትና የምድር በሁለቱም መካከል ላለው ሁሉ ጌታ ነውና ተገዛው፡፡ እርሱን በመገዛትም ላይ ታገስ፡፡ ለእርሱ ሞክሼን ታውቃለህን'),
('19:66', 87, 'ሰውም «በሞትኩ ጊዜ ወደፊት ሕያው ኾኜ (ከመቃብር) እወጣለሁን» ይላል፡፡'),
('19:67', 87, 'ሰው ከአሁን በፊት ምንም ነገር ያልነበረ ሲኾን እኛ የፈጠርነው መኾኑን አያስታውስምን'),
('19:68', 87, 'በጌታህ እንምላለን ሰይጣናት ጋር በእርግጥ እንሰበስባቸዋለን፡፡ ከዚያም በገሀነም ዙሪያ የተንበረከኩ ኾነው፤ በእርግጥ እናቀርባቸዋለን፡፡'),
('19:69', 87, 'ከዚያም ከየጭፍሮቹ ሁሉ ከእነርሱ ያንን (እርሱ) በአልረሕማን ላይ በድፍረት በጣም ብርቱ የኾነውን እናወጣለን፡፡'),
('19:70', 87, 'ከዚያም እኛ እነዚያን እነርሱ በእርሷ ለመግባት ተገቢ የኾኑትን እናውቃለን፡፡'),
('19:71', 87, 'ከእናንተም ወደ እርሷ ወራጅ እንጂ አንድም የለም፡፡ (መውረዱም) ጌታህ የፈረደው ግዴታ ነው፡፡'),
('19:72', 87, 'ከዚያም እነዚያን የተጠነቀቁትን እናድናለን፡፡ አመጸኞቹንም የተንበረከኩ ኾነው በውስጧ እንተዋቸዋለን፡፡'),
('19:73', 87, 'በእነሱም ላይ አንቀጾቻችን ግልጽ መስረጃዎች ኾነው በተነበቡ ጊዜ እነዚያ የካዱት ለእነዚያ ላመኑት «ከሁለቱ ክፍሎች መኖሪያው የሚበልጠውና ሸንጎውም ይበልጥ የሚያምረው ማንኛው ነው» ይላሉ፡፡'),
('19:74', 87, 'ከእነሱም በፊት ከክፍለ ዘመናት ሕዝቦች እነሱ በቁሳቁስና በትርኢትም በጣም ያማሩትን ብዙዎችን አጥፍተናል፡፡'),
('19:75', 87, '«በስሕተት ውስጥ የኾነ ሰው አልረሕማን ለእርሱ ማዘግየትን ያዘገየዋል፡፡ የሚዛትባቸውንም ወይም ቅጣቱን ወይም ሰዓቲቱን ባዩ ጊዜ እርሱ ስፍራው መጥፎና ሰራዊቱ ደካማ የኾነው ሰው ማን እንደኾነ በእርግጥ ያውቃሉ» በላቸው፡፡'),
('19:76', 87, 'እነዚያንም የቀኑትን ሰዎች አላህ ቅንነትን ይጨምርላቸዋል፡፡ መልካሞቹ ቀሪዎች (ሥራዎች) እጌታህ ዘንድ በምንዳ በላጭ ናቸው፡፡ በመመለሻም የተሻሉ ናቸው፡፡'),
('19:77', 87, 'ያንንም በአንቀጾቻችን የካደውን «(በትንሣኤ ቀን) ገንዘብም ልጅም በእርግጥ እስሰጣለሁ ያለውንም አየህን»'),
('19:78', 87, 'ሩቁን ምስጢር ዐወቀን ወይስ አልረሕማን ዘንድ ቃል ኪዳንን ያዘ'),
('19:79', 87, 'ይከልከል (አይሰጠውም)፡፡ የሚለውን ሁሉ በእርግጥ እንጽፋለን፡፡ ለእርሱም ከቅጣት ጭማሬን እንጨምርለታለን፡፡'),
('19:80', 87, '(አልለኝ) የሚለውንም ሁሉ እንወርሰዋለን፡፡ ብቻውንም ኾኖ ይመጣናል፡፡'),
('19:81', 87, 'ከአላህም ሌላ አማልክትን ለእነሱ መከበሪያ (አማላጅ) እንዲኾኑዋቸው ያዙ፡፡'),
('19:82', 87, 'ይከልከሉ፤ መገዛታቸውን በእርግጥ ይክዷቸዋል፡፡ በእነሱም ላይ ተቃራኒ ይኾኑባቸዋል፡፡'),
('19:83', 87, 'እኛ ሰይጣናትን በከሓዲዎች ላይ (በመጥፎ ሥራ) ማወባራትን የሚያወባሩዋቸው ሲኾኑ የላክን መኾናችንን አለየህምን'),
('19:84', 87, 'በእነሱም (መቀጣት) ላይ አትቻኮል፡፡ ለእነሱ (ቀንን) መቁጠርን እንቆጥርላቸዋለንና፡፡'),
('19:85', 87, 'ምእምናንን የተከበሩ ጭፍሮች ኾነው ወደ አልረሕማን የምንሰበስብበትን ቀን (አስታውስ)፡፡'),
('19:86', 87, 'ከሓዲዎችንም የተጠሙ ኾነው ወደ ገሀነም የምንነዳበትን (ቀን አስታውስ)፡፡'),
('19:87', 87, 'አልረሕማን ዘንድ ቃል ኪዳንን የያዘ ሰው ቢኾን እንጂ ማማለድን አይችሉም፡፡'),
('19:88', 87, '«አልረሕማንም ልጅን ያዘ (ወለደ)» አሉ፡፡'),
('19:89', 87, 'ከባድ መጥፎን ነገር በእርግጥ አመጣችሁ፡፡'),
('19:90', 87, 'ከእርሱ (ከንግግራቸው) ሰማያት ሊቀደዱ፣ ምድርም ልትሰነጠቅ፣ ጋራዎችም ተንደው ሊወድቁ ይቃረባሉ፡፡'),
('19:91', 87, 'ለአልረሕማን ልጅ አልለው ስለአሉ፡፡'),
('19:92', 87, 'ለአልረሕማን ልጅን መያዝ አይገባውም፡፡'),
('19:93', 87, 'በሰማያትና በምድር ያለው ሁሉ (በትንሣኤ ቀን) ለአልራሕማን ባሪያ ኾነው የሚመጡ እንጂ ሌላ አይደሉም፡፡'),
('19:94', 87, 'በእርግጥ (በዕውቀቱ) ከቧቸዋል፡፡ መቁጠርንም ቆጥሯቸዋል፡፡'),
('19:95', 87, 'ሁሉም በትንሣኤ ቀን ለየብቻ ኾነው ወደርሱ መጪዎች ናቸው፡፡'),
('19:96', 87, 'እነዚያ ያመኑና በጎ ሥራዎችን የሠሩ አልረሕማን ለእነሱ ውዴታን ይሰጣቸዋል፡፡'),
('19:97', 87, 'በምላስህም (ቁርኣንን) ያገራነው በእርሱ ጥንቁቆቹን ልታበስርበት በእርሱም ተከራካሪዎችን ሕዝቦች ልታስፈራራበት ነው፡፡'),
('19:98', 87, 'ከእነሱም በፊት ከክፍለ ዘመናት ሕዝቦች ብዙዎችን አጥፍተናል፡፡ ከእነሱ አንድን እንኳ ታያለህን ወይስ ለእነሱ ሹክሹክታን ትሰማለህን'),
('20:1', 87, 'ጠ.ሀ. (ጣ ሃ)'),
('20:2', 87, 'ቁርኣንን ባንተ ላይ እንድትቸገር አላወረድንም፡፡'),
('20:3', 87, 'ግን አላህን ለሚፈራ ሰው መገሰጫ ይኾን ዘንድ (አወረድነው)፡፡'),
('20:4', 87, 'ምድርንና የላይኛዎቹን ሰማያት ከፈጠረ አምላክ ተወረደ፡፡'),
('20:5', 87, '(እርሱ) አልረሕማን ነው በዐርሹ ላይ (ለሱ ክብር በሚስማማ መልኩ) ተደላደለ፡፡'),
('20:6', 87, 'በሰማያት ያለው፣ በምድርም ያለው፣ በመካከላቸውም ያለው፣ ከዐፈር በታችም ያለው ሁሉ የርሱ ብቻ ነው፡፡'),
('20:7', 87, 'በንግግር ብትጮህ (አላህ ከጩኸቱ የተብቃቃ ነው)፡፡ እርሱ ምስጢርን በጣም የተደበቀንም ያውቃልና፡፡'),
('20:8', 87, 'አላህ ከእርሱ ሌላ አምላክ የለም፡፡ ለእርሱ መልካሞች የኾኑ ስሞች አልሉት፡፡'),
('20:9', 87, 'የሙሳም ወሬ በእርግጥ መጥቶሃል፡፡'),
('20:10', 87, 'እሳትን ባየና ለቤተሰቦቹ፡- (እዚህ) «ቆዩ፤ እኔ እሳትን አየሁ፡፡ ከእርሷ ችቦን ላመጣላችሁ፤ ወይም እሳቲቱ ዘንድ መሪን ላገኝ እከጅላለሁ» ባለጊዜ (አስታውስ)፡፡'),
('20:11', 87, 'በመጣትም ጊዜ «ሙሳ ሆይ» በማለት ተጠራ፡፡'),
('20:12', 87, '«እኔ ጌታህ እኔ ነኝ መጫሚያዎችህንም አውልቅ፡፡ አንተ በተቀደሰው ሸለቆ በጡዋ ነህና፡፡'),
('20:13', 87, '«እኔም መረጥኩህ፤ የሚወረድልህንም ነገር አዳምጥ፡፡'),
('20:14', 87, '«እኔ አላህ እኔ ነኝ ያለ እኔ አምላክ የለምና ተገዛኝ፡፡ ሶላትንም (በእርሷ) እኔን ለማውሳት ስገድ፡፡'),
('20:15', 87, '«ሰዓቲቱ በእርግጥ መጪናት፡፡ ልደብቃት እቃረባለሁ፡፡ ነፍስ ሁሉ በምትሠራው ነገር ትመነዳ ዘንድ (መጭ ናት)፡፡'),
('20:16', 87, '«በእርሷ የማያምነውና ዝንባሌውን የተከተለውም ሰው ከእርሷ አያግድህ ትጠፋለህና፡፤'),
('20:17', 87, '«ሙሳ ሆይ! ይህችም በቀኝ እጅህ ያለችው ምንድን ናት» (ተባለ)፡፡'),
('20:18', 87, '«እርሷ በትሬ ናት፡፡ በእርሷ ላይ እደገፍባታለሁ፣ በእርሷም ለፍየሎቼ ቅጠልን አረግፍባታለሁ፣ ለእኔም በእርሷ ሌሎች ጉዳዮች አሉኝ» አለ፡፡'),
('20:19', 87, '(አላህም) «ሙሳ ሆይ! ጣላት» አለው፡፡'),
('20:20', 87, 'ጣላትም፡፡ ወዲያውም እርሷ የምትሮጥ እባብ ኾነች፡፡'),
('20:21', 87, '«ያዛት፤ አትፍራም፡፡ ወደ መጀመሪያ ጠባይዋ እንመልሳታለን» አለው፡፡'),
('20:22', 87, '«እጅህንም ወደ ብብትህ አግባ፡፡ ሌላ ተዓምር ስትኾን ያለነውር ነጭ ኾና ትወጣለችና፡፡'),
('20:23', 87, '«ከተዓምራቶቻችን ታላቋን እናሳይህ ዘንድ (ይህን ሠራን)፡፡'),
('20:24', 87, '«ወደ ፈርዖን ኺድ፡፡ እርሱ ወሰን አልፏልና፡፡»'),
('20:25', 87, '(ሙሳም) አለ «ጌታዬ ሆይ! ልቤን አስፋልኝ፡፡'),
('20:26', 87, '«ነገሬንም ለእኔ አግራልኝ፡፡'),
('20:27', 87, '«ከምላሴም መኮላተፍን ፍታልኝ፡፡'),
('20:28', 87, '«ንግግሬን ያውቃሉና፡፡'),
('20:29', 87, '«ከቤተሰቦቼም ለእኔ ረዳትን አድርግልኝ፡፡'),
('20:30', 87, '«ሃሩንን ወንድሜን፡፡'),
('20:31', 87, '«ኅይሌን በእርሱ አበርታልኝ፡፡'),
('20:32', 87, '«በነገሬም አጋራው፡፡'),
('20:33', 87, '«በብዙ እናጠራህ ዘንድ፡፡'),
('20:34', 87, '«በብዙም እንድናወሳህ፡፡'),
('20:35', 87, '«አንተ በእኛ ነገር ዐዋቂ ነህና፡፡»'),
('20:36', 87, '(አላህም) አለ «ሙሳ ሆይ! ልመናህን በእርግጥ ተሰጠህ፡፡'),
('20:37', 87, '«በሌላም ጊዜ ባንተ ላይ በእርግጥ ለግሰናል፡፡'),
('20:38', 87, '«ወደናትህ በልብ የሚፈስን ነገር ባሳወቅን ጊዜ፡፡'),
('20:39', 87, '«(ሕፃኑን) በሳጥኑ ውስጥ ጣይው፡፡ እርሱንም (ሳጥኑን) በባሕር ላይ ጣይው፡፡ ባሕሩም በዳርቻው ይጣለው፡፡ ለእኔ ጠላት ለእርሱም ጠላት የኾነ ሰው ይይዘዋልና በማለት (ባሳወቅን ጊዜ ለገስንልህ)፡፡ ባንተ ላይም ከእኔ የኾነን መወደድ ጣልኩብህ፡፡ (ልትወደድና) በእኔም ጥበቃ ታድግ ዘንድ፡፡'),
('20:40', 87, '«እኅትህም በምትኼድና የሚያሳድገውን ሰው ላመላክታችሁን በምትል ጊዜ (መወደድን ጣልኩብህ)፡፡ ወደ እናትህም ዓይንዋ እንዲረጋ (እርሷ) እንዳታዝንም መለስንህ፡፡ ነፍስንም ገደልክ፡፡ ከጭንቅም አዳንንህ፡፡ ፈተናዎችንም ፈተንህ፡፡ በመድየን ቤተሰቦችም ውስጥ (ብዙ) ዓመታትን ተቀመጥክ፡፡ ከዚያም ሙሳ ሆይ! በተወሰነ ጊዜ ላይ መጣህ፡፡'),
('20:41', 87, '«ለነፍሴም (በመልእክቴ) መረጥኩህ፡፡'),
('20:42', 87, '«አንተም ወንድምህም በተዓምራቶቼ ኺዱ፡፡ እኔንም ከማውሳት አትቦዝኑ፡፡'),
('20:43', 87, '«ወደ ፈርዖን ኺዱ፡፡ እርሱ ወሰን አልፏልና፡፡'),
('20:44', 87, '«እርሱም ይገሰጽ ወይም ይፈራ ዘንድ፤ ለእርሱ ልዝብን ቃል ተናገሩት፡፡»'),
('20:45', 87, '«ጌታችን ሆይ! እኛ በእኛ ላይ ክፋት በመሥራት መቸኮሉን ወይም ኩራትን መጨመሩን እንፈራለን» አሉ፡፡'),
('20:46', 87, '(አላህም) አለ «አትፍሩ፡፡ እኔ በእርግጥ ከእናንተ ጋር ነኝና፡፡ እሰማለሁ፤ አያለሁም፡፡'),
('20:47', 87, '«ወደርሱም ኺዱ፤ በሉትም፡- ‹እኛ የጌታህ መልክተኞች ነን፡፡› የእስራኤልንም ልጆች ከኛ ጋር ልቀቅ፡፡ አታሰቃያቸውም፡፡ ከጌታህ በኾነው ተዓምር በእርግጥ መጥተንሃልና፡፡ ሰላምም ቀጥታን በተከተለ ሰው ላይ ይኹን፡፡'),
('20:48', 87, '«እኛ ቅጣቱ ባስተባበለና እምቢ ባለ ሰው ላይ ነው ማለት በእርግጥ ተወረደልን፡፡»'),
('20:49', 87, '(ፈርዖንም) «ሙሳ ሆይ! ጌታችሁ ማነው» አለ፡፡'),
('20:50', 87, '«ጌታችን ያ ለፍጥረቱ ነገርን ሁሉ (የሚያስፈልገውን) የሰጠ ከዚያም የመራው ነው» አለው፡፡'),
('20:51', 87, '(ፈርዖንም) «የመጀመሪያይቱ ዘመናት ሕዝቦች ኹኔታ ምንድን ነው» አለ፡፡'),
('20:52', 87, '(ሙሳም) «ዕውቀትዋ እጌታዬ ዘንድ በመጽሐፍ የተመዘገበ ነው፡፡ ጌታዬ አይሳሳትም አይረሳምም» አለው፡፡'),
('20:53', 87, '(እርሱ) ያ ምድርን ለእናንተ ምንጣፍ ያደረገላችሁ፣ በእርሷም ውስጥ ለእናንተ መንገድን ያገራላችሁ፣ ውሃንም ከሰማይ ያወረደ ነው (አለ)፡፡ በርሱም ከተለያየ በቃይ ዓይነቶችን አወጣንላችሁ፡፡'),
('20:54', 87, 'ብሉ እንስሳዎቻችሁንም አግጡ፤ (ባዮች ኾነን አወጣንላችሁ)፡፡ በዚህ ውስጥ ለአእምሮ ባለቤቶች በእርግጥ ተዓምራት አለበት፡፡'),
('20:55', 87, 'ከእርሷ (ከምድር) ፈጠርናችሁ፡፡ በእርሷም ውስጥ እንመልሳችኋለን፡፡ ከእርሷም በሌላ ጊዜ እናወጣችኋለን፡፡'),
('20:56', 87, 'ተዓምራቶቻችንንም ሁሏንም (ለፈርዖን) በእርግጥ አሳየነው፡፡ አስተባበለም፡፡ እምቢም አለ፡፡'),
('20:57', 87, '«ከምድራችን በድግምትህ ልታወጣን መጣህብን ሙሳ ሆይ!» አለ፡፡'),
('20:58', 87, '«መሰሉንም ድግምት እናመጣብሃለን፡፡ በእኛና ባንተም መካከል እኛም አንተም የማንጥሰው የኾነ ቀጠሮን በመካከለኛ ስፍራ አድርግልን» አለ፡፡'),
('20:59', 87, '«ቀጠሯችሁ በማጌጫው ቀን ሰዎቹም በረፋድ በሚሰበሰቡበት ነው» አለ፡፡'),
('20:60', 87, 'ፈርዖንም ዞረ፡፡ ተንኮሉንም ሰበሰበ፡፡ ከዚያም መጣ፡፡'),
('20:61', 87, 'ሙሳ ለእነሱ አላቸው «ወዮላችሁ በአላህ ላይ ውሸትን አትቅጠፉ፡፡ በቅጣት ያጠፋችኋልና፡፡ የቀጠፈም ሰው በእርግጥ አፈረ፡፡»'),
('20:62', 87, '(ድግምተኞቹ) በመካከላቸውም ነገራቸውን ተጨቃጨቁ፡፡ ውይይትንም ደበቁ፡፡'),
('20:63', 87, '«እነዚህ በእርግጥ ደጋሚዎች ናቸው፡፡ ከምድራችሁ በድግምታቸው ሊያወጧችሁ በላጪቱንም መንገዳችሁን ሊያስወግዱባችሁ ይሻሉ» አሉ፡፡'),
('20:64', 87, '«ተንኮላችሁንም አጠንክሩ፡፡ ከዚያም ተሰልፋችሁ ኑ፡፡ ዛሬ ያሸነፈም ሰው ምኞቱን አገኘ» (ተባባሉ)፡፡'),
('20:65', 87, '«ሙሳ ሆይ! ወይ ትጥላለህ ወይም በመጀመሪያ የምንጥል እንኾናለን» (ምረጥ) አሉ፡፡'),
('20:66', 87, '«አይደለም ጣሉ» አላቸው፡፡ ወዲያውም ገመዶቻቸውና ዘንጎቻቸው ከድግምታቸው የተነሳ እነርሱ የሚሮጡ (እባቦች) ኾነው ወደርሱ ተመለሱ፡፡'),
('20:67', 87, 'ሙሳም በነፍሱ ውስጥ ፍርሃትን አሳደረ፡፡'),
('20:68', 87, '«አትፍራ አንተ የበላዩ አንተ ነህና» አልነው፡፡'),
('20:69', 87, '«በቀኝ እጅህ ያለቸውንም በትር ጣል፡፡ ያንን የሠሩትን ትውጣለችና፡፡ ያ የሠሩት ሁሉ የድግምተኛ ተንኮል ነውና፡፡ ድግምተኛም በመጣበት ስፍራ ሁሉ አይቀናውም» (አልን)፡፡'),
('20:70', 87, 'ድግምተኞቹም ሰጋጆች ኾነው ወደቁ፡፡ «በሃሩንና በሙሳ ጌታ አመንን» አሉ፡፡'),
('20:71', 87, '(ፈርዖንም) «ለእናንተ ሳልፈቅድላችሁ በፊት ለእርሱ አመናችሁን እርሱ በእርግጥ ያ ድግምትን ያስተማራችሁ ትልቃችሁ ነው፡፡ እጆቻችሁንና እግሮቻችሁን በማናጋት (ግራናቀኝን በማፈራረቅ) እቆራርጣችኋለሁ፡፡ በዘምባባም ግንዶች ለይ እሰቅላችኋለሁ፡፡ ማንኛችንም ቅጣቱ በጣም ብርቱ የሚቆይም መኾኑን ታውቃላችሁ» አላቸው፡፡'),
('20:72', 87, 'ከመጡልን ታምራቶች ከዚያም ከፈጠረን(አምላክ) ፈጽሞ አንመርጥህም፤ አንተም የምትፈርደውን ፍረድ፤ የምትፈርደው በዚች በአነስተኛይቱ ሕይወት ብቻ ነው አሉ፡፡'),
('20:73', 87, '«ኃጢአቶቻችንንና ከድግምትም በእርሱ ላይ ያስገደድከንን ለእኛ ይምረን ዘንድ እኛ በጌታችን አምነናል፡፡ አላህም በጣም በላጭ ነው፤ (ቅጣቱም) በጣም የሚዘወትር ነው» አሉ፡፡'),
('20:74', 87, 'እነሆ ከሓዲ ኾኖ ወደ ጌታው የሚመጣ ሰው ለእርሱ ገሀነም አለችው፡፡ በውስጧም አይሞትም ሕያውም አይኾን፡፡'),
('20:75', 87, 'በጎ ሥራዎችን በእርግጥ የሠራ ምእመን ኾኖ የመጣውም ሰው እነዚያ ለእነሱ ከፍተኛ ደረጃዎች አሏቸው፡፡'),
('20:76', 87, 'ከሥሮቻቸው ወንዞች የሚፈሱባቸው የመኖሪያ ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ (አሏቸው)፡፡ ይህም የተጥራራ ሰው ምንዳ ነው፡፡'),
('20:77', 87, 'ወደ ሙሳም «ባሮቼን ይዘህ በሌሊት ኺድ፡፡ ለእነሱም በባሕር ውስጥ ደረቅ መንገድን አድርግላቸው፡፡ መገኘትን አትፍራ፡፡ (ከመስጠም) አትጨነቅም፡፡» ስንል በእርግጥ ላክንበት፡፡'),
('20:78', 87, 'ፈርዖንም ከሰራዊቱ ጋር ኾኖ ተከተላቸው፡፡ ከባህሩም የሚሸፍን ሸፈናቸው፡፡'),
('20:79', 87, 'ፈርዖንም ሕዝቦቹን አሳሳታቸው፡፡ ቅኑንም መንገድ አልመራቸውም፡፡'),
('20:80', 87, 'የእስራኤል ልጆች ሆይ! ከጠላታችሁ በእርግጥ አዳንናችሁ፡፡ በጡርም ቀኝ ጎን ቀጠሮ አደረግንላችሁ፡፡ በእናንተም ላይ መናንና ድርጭትን አወረድንላችሁ፡፡'),
('20:81', 87, 'ከሰጠናችሁ ሲሳይ፤ ከመልካሙ ብሉ፡፡ በእርሱም ወሰንን አትለፉ፡፡ ቁጣዬ በእናንተ ላይ ይወርድባችኋልና፡፡ በእርሱም ላይ ቁጣዬ የሚወርድበት ሰው በእርግጥ ይጠፋል፡፡'),
('20:82', 87, 'እኔም ለተጸጸተ፣ ላመነም፣ መልካምንም ለሠራ፣ ከዚያም ለተመራ ሰው በእርግጥ መሓሪ ነኝ፡፡'),
('20:83', 87, '«ሙሳ ሆይ! ከሕዝቦችህ ምን አስቸኮለህም» (ተባለ)፡፡'),
('20:84', 87, '«እነሱ እነዚህ፤ በዱካዬ ላይ ያሉ ናቸው፡፡ ጌታዬ ሆይ! ትወድልንም ዘንድ ወደ አንተ ቸኮልኩ» አለ፡፡'),
('20:85', 87, '(አላህ) «እኛም ከአንተ በኋላ ሰዎችህን በእርግጥ ፈትተን፡፡ ሳምራዊውም አሳሳታቸው» አለው፡፡'),
('20:86', 87, 'ሙሳም ወደ ሰዎቹ የተቆጣ ያዘነ ኾኖ ተመለሰ፡፡ «ሕዝቦቼ ሆይ! ጌታችሁ መልካም ተስፋን አልቀጠራችሁምን ቀጠሮው በእናንተ ላይ ረዘመባችሁን» ወይስ በእናንተ ላይ ከጌታችሁ ቅጣት ሊወርድባችሁ ፈለጋችሁና ቀጠሮየን አፈረሳችሁን አላቸው፡፡'),
('20:87', 87, '«ቀጠሮህን በፈቃዳችን አልጣስንም፡፡ ግን እኛ ከሕዝቦቹ ጌጥ ሸክሞችን ተጫን (በእሳት ላይ) ጣልናትም፡፡ ሳምራዊውም እንደዚሁ ጣለ» አሉት፡፡'),
('20:88', 87, 'ለእነሱም አካል የኾነ ጥጃን ለእርሱ መጓጎር ያለውን አወጣላቸው፡፡ (ተከታዮቹ) «ይህ አምላካችሁ የሙሳም አምላክ ነው ግን ረሳው» አሉም፡፡'),
('20:89', 87, 'ወደእነሱ ንግግርን የማይመልስ ለእነሱም ጉዳትንና ጥቅምን የማይችል መኾኑን አያዩምን'),
('20:90', 87, 'ሃሩንም ከዚህ በፊት በእርግጥ አላቸው፡- «ሕዝቦቼ ሆይ! (ይህ) በእርሱ የተሞከራችሁበት ብቻ ነው፡፡ ጌታችሁም አልረሕማን ነው፡፡ ተከተሉኝም፡፡ ትዕዛዜንም ስሙ፡፡»'),
('20:91', 87, '«ሙሳ ወደእኛ እስከሚመለስ በእርሱ (መገዛት) ላይ ከመቆየት ፈጽሞ አንወገድም» አሉ፡፡'),
('20:92', 87, '(ሙሳ) አለ፡- «ሃሩን ሆይ! ተሳስተው ባየሃቸው ጊዜ ምን ከለከልህ'),
('20:93', 87, '«እኔን ከመከተል ትዕዛዜን ጣስክን»'),
('20:94', 87, '«የእናቴ ልጅ ሆይ! ጢሜንም ራሴንም አትያዝ፡፡ እኔ በእስራኤል ልጆች መካከል ለያየህ፤ ቃሌንም አልጠበቅህም ማለትህን ፈራሁ» አለው፡፡'),
('20:95', 87, '(ሙሳ) «ሳምራዊው ሆይ! ነገርህም ምንድን ነው» አለ፡፡'),
('20:96', 87, 'ያላዩትን ነገር አየሁ፡፡ ከመልክተኛው (ከፈረሱ ኮቴ) ዱካም ጭብጥ አፈርን ዘገንኩ፡፡ (በቅርጹ ላይ) ጣልኳትም፡፡ እንደዚሁም ነፍሴ ሸለመችልኝ» አለ፡፡'),
('20:97', 87, 'አለው «ኺድ፤ ላንተም በሕይወትህ (ለአየኸው ሰው ሁሉ) መነካካት የለም ማለት አለህ፡፡ ለአንተም ፈጽሞ የማትጣሰው ቀጠሮ አለህ፡፡ ወደዚያም በእርሱ ላይ ተገዢው ኾነህ ወደ ቆየህበት አምላክህ ተመልከት፡፡ በእርግጥ እናቃጥለዋለን፡፡ ከዚያም በባሕሩ ውስጥ መበተንን እንበትነዋለን፡፡»'),
('20:98', 87, 'ጌታችሁ ያ ከእርሱ በቀር ሌላ አምላክ የሌለ የኾነው አላህ ብቻ ነው፡፡ እውቀቱ ነገርን ሁሉ አዳረሰ፡፡'),
('20:99', 87, 'እንደዚሁ በእርግጥ ካለፉት ወሬዎች ባንተ ላይ እንተርካለን፡፡ ከእኛም ዘንድ ቁረኣንን በእርግጥ ሰጠንህ፡፡'),
('20:100', 87, 'ከእርሱ ያፈገፈገ ሰው እርሱ በትንሣኤ ቀን ከባድን ቅጣት ይሸከማል፡፡'),
('20:101', 87, 'በእርሱ ውስጥ ዘውታሪዎች ኾነው (ይሸከማሉ)፡፡ በትንሣኤም ቀን ለእነሱ የኾነው ሸክም ከፋ!'),
('20:102', 87, 'በቀንዱ በሚነፋ ቀን (ሸክማቸው ከፋ)፤ ከሓዲዎችንም በዚያ ቀን (ዓይኖቻቸው) ሰማያዊዎች ሆነው እንሰበስባቸዋለን፡፡'),
('20:103', 87, '«ዐሥርን (ቀን) እንጂ አልቆያችሁም» በመባባል በመካከላቸው ይንሾካሾካሉ፡፡'),
('20:104', 87, 'በሐሳብ ቀጥተኛው «አንድን ቀን እንጅ አልቆያችሁም» በሚል ጊዜ የሚሉትን ነገር እኛ ዐዋቂዎች ነን፡፡'),
('20:105', 87, 'ከጋራዎችም ይጠይቁሃል፤ በላቸው «ጌታዬ መበተንን ይበትናቸዋል፡፡'),
('20:106', 87, '«ትክክል ሜዳም ኾና ይተዋታል፡፡'),
('20:107', 87, '«በርሷ ዝቅታና ከፍታን አታይም፡፡»'),
('20:108', 87, 'በዚያ ቀን (ለመሰብሰብ) ጠሪውን ለእርሱ መጣመም የሌለውን መከተል ይከተላሉ፡፡ ድምጾችም ለአልረሕማን ጸጥ ይላሉ፡፡ ስለዚህ ሹክሹክታን እንጂ አትሰማም፡፡'),
('20:109', 87, 'በዚያ ቀን ለእርሱ አልረሕማን የፈቀደለትንና ለእርሱም ቃልን የወደደለትን ሰው ቢኾን እንጅ ምልጃ (አንድንም) አትጠቅምም፡፡'),
('20:110', 87, 'በስተፊታቸው ያለውን በስተኋላቸውም ያለውን ሁሉ ያውቃል፡፡ በእርሱም ዕውቀትን አያካብቡም፤ (አያውቁም)፡፡'),
('20:111', 87, 'ፊቶችም ሁሉ ሕያው አስተናባሪ ለኾነው (አላህ) ተዋረዱ፡፡ በደልንም የተሸከመ ሰው በእርግጥ ከሰረ፡፡'),
('20:112', 87, 'እርሱ አማኝ ኾኖ ከመልካም ሥራዎችም የሠራ ሰው በደልንም መጉደልንም አይፈራም፡፡'),
('20:113', 87, 'እንደዚሁም ዐረብኛ ቁርኣን ኾኖ አወረድነው፡፡ አላህንም ይፈሩ ዘንድ ወይም ለእነሱ ግሣጼን ያድስላቸው ዘንድ ከዛቻ ደጋግመን በውስጡ ገለጽን፡፡'),
('20:114', 87, 'እውነተኛው ንጉስ አላህም (ከሓዲዎች ከሚሉት) ላቀ፡፡ ወደ አንተ መወረዱም ከመፈጸሙ በፊት በማንበብ አትቸኩል፡፡ «ጌታዬ ሆይ! ዕውቀትንም ጨምርልኝ» በል፡፡'),
('20:115', 87, 'ወደ አደምም ከዚህ በፊት ኪዳንን በእርግጥ አወረድን፡፡ ረሳም፡፡ ለእርሱም ቆራጥነትን አላገኘንለትም፡፡'),
('20:116', 87, 'ለመላእክትም ለአዳም ስገዱ ባልን ጊዜ (አስታውስ)፡፡ ሰገዱም፤ ኢብሊስ ብቻ ሲቀር እምቢ አለ፡፡'),
('20:117', 87, 'አልንም «አደም ሆይ! ይህ ላንተም ለሚስትህም በእርግጥ ጠላት ነው፡፡ ስለዚህ ከገነት አያውጣችሁ፤ ትለፋለህና፡፡'),
('20:118', 87, 'ለአንተ በእርሷ ውስጥ አለመራብና አለመታረዝ አለህ፡፡'),
('20:119', 87, 'አንተም በርሷ ውስጥ አትጠማም፤ ፀሐይም አትተኮስም፡፡'),
('20:120', 87, 'ሰይጣንም ወደርሱ ጎተጎተ «አደም ሆይ! በመዘውተሪያ ዛፍ በማይጠፋ ንግሥናም ላይ ላመላክትህን አለው፡፡'),
('20:121', 87, 'ከእርሷም በልሉ፡፡ ለእነርሱም ኀፍረተ ገላቸው ተገለጸች፡፡ ከገነትም ቅጠል በላያቸው ላይ ይለጥፉ ጀመር፡፡ አደምም የጌታውን ትእዛዝ (ረስቶ) ጣሰ፡፡ (ከፈለገው መዘውተር) ተሳሳተም፡፡'),
('20:122', 87, 'ከዚያም ጌታው መረጠው ከእርሱም ጸጸቱን ተቀበለው መራውም፡፡'),
('20:123', 87, 'አላቸው «ከፊላችሁም ለከፊሉ ጠላት ሲኾን ሁላችሁም ከእርሷ ውረዱ ከእኔም የኾነ መሪ ቢመጣላችሁ መሪየን የተከተለ አይሳሳትም አይቸገርምም፡፡'),
('20:124', 87, '«ከግሣጼዬም የዞረ ሰው ለእርሱ ጠባብ ኑሮ አለው፡፡ በትንሣኤም ቀን ዕውር ኾኖ እንቀሰቅሰዋለን፡፡'),
('20:125', 87, '«ጌታዬ ሆይ! ለምን ዕውር አድርገህ አስነሳኸኝ በእርግጥ የማይ የነበርኩ ስኾን» ይላል፡፡'),
('20:126', 87, '(ነገሩ) እንደዚሁ ነው፡፡ «ታምራታችን መጣችልህ፡፡ ተውካትም፡፡ እንደዚሁም ዛሬ ትተዋለህ» ይለዋል፡፡'),
('20:127', 87, 'እንደዚሁም ያጋራንና በጌታው አንቀጾች ያላመነን ሰው እንቀጣዋለን፡፡ የመጨረሻይቱም ዓለም ቅጣት በጣም ብርቱ ሁልጊዜ ዘውታሪም ነው፡፡'),
('20:128', 87, '(ቁረይሾች) ከእነሱ በፊት ከክፍለ ዘመናት ሕዝቦች ብዙዎችን ያጠፋን መኾናችን በመኖሪያዎቻቸው የሚኼዱ ኾነው ሳሉ ለእነርሱ አልተገለጸላቸውምን በዚህ ውስጥ ለአእምሮ ባለቤቶች በእርግጥ መልክቶች አሉበት፡፡'),
('20:129', 87, 'ከጌታህ ያለፈች ቃልና የተወሰነ ጊዜ ባልነበረ ኖሮ (ቅጣቱ አሁኑኑ) የሚይዛቸው ይኾን ነበር፡፡'),
('20:130', 87, 'በሚሉትም ላይ ታገስ፡፡ ጌታህንም ፀሐይ ከመውጣትዋ በፊት ከመግባትዋም በፊት የምታመሰግን ኾነህ አጥራው፤ (ስገድ)፡፡ ከሌሊት ሰዓቶችም በቀን ጫፎችም አጥራው፡፡ (በሚሰጥህ ምንዳ) ልትወድ ይከጀላልና፡፡'),
('20:131', 87, 'ዓይኖችህንም ከእነርሱ (ከሰዎቹ) ክፍሎችን በእርሱ ልንፈትናቸው ወደ አጣቀምንበት፤ ወደ ቅርቢቱ ሕይወት ጌጦች አትዘርጋ፡፡ የጌታህ ሲሳይም በጣም በላጭ ዘውታሪም ነው፡፡'),
('20:132', 87, 'ቤተሰብህንም በስግደት እዘዝ፡፡ በእርሷም ላይ ዘውትር፤(ጽና)፡፡ ሲሳይን አንጠይቅህም፡፡ እኛ እንሰጥሃለን፡፡ መልካሚቱ መጨረሻም ለጥንቁቆቹ ናት፡፡'),
('20:133', 87, '«ከጌታውም በኾነ ተዓምር አይመጣንምን» አሉ በመጀመሪያዎቹ ጽሑፎች ውስጥ ያለችው ማስረጃ አልመጣቻቸውምን'),
('20:134', 87, 'እኛም ከእርሱ (ከሙሐመድ መላክ) በፊት በቅጣት ባጠፋናቸው ኖሮ «ጌታችን ሆይ! ከመዋረዳችንና ከማፈራችን በፊት አንቀጾችህን እንከተል ዘንድ ወደኛ መልከተኛን አትልክም ነበርን» ባሉ ነበር፡፡'),
('20:135', 87, '«ሁሉም ተጠባባቂ ነው፡፡ ተጠባበቁም፡፡ የቀጥታውም መንገድ ባለቤቶች እነማን እንደሆኑ እነማንም እንደ ተመሩ ወደ ፊት ታውቃላችሁ» በላቸው፡፡'),
('21:1', 87, 'ለሰዎች እነርሱ በዝንጋቴ ውስጥ (መሰናዳትን) የተው ኾነው ሳሉ ምርመራቸው ቀረበ፡፡'),
('21:2', 87, 'ከጌታቸው አዲስ የተወረደ ቁርኣን አይመጣላቸውም፡፡ እነሱ የሚያላግጡ ሆነው የሚያደምጡት ቢሆኑ እንጂ፡፡'),
('21:3', 87, 'ልቦቻቸው ዝንጉዎች ኾነው (የሚያዳምጡት ቢኾኑ እንጅ)፡፡ እነዚያም የበደሉት ሰዎች መንሾካሾክን ደበቁ፡፡ «ይህ ብጤያችሁ ሰው እንጅ ሌላ ነውን እናንተም የምታዩ ስትኾኑ ድግምትን ለመቀበል ትመጣላችሁን» (አሉ)፡፡'),
('21:4', 87, '(ሙሐመድም) «ጌታዬ ቃልን ሁሉ በሰማይና በምድር ውስጥ ያለ ሲኾን ያውቃል እርሱም ሰሚው ዐዋቂው ነው» አለ፡፡'),
('21:5', 87, '«በእውነቱ (ቁርኣኑ) የሕልሞች ቅዠቶች ነው፡፡ ይልቁንም ቀጠፈው እንዲያውም እርሱ ቅኔን ገጣሚ ነው፡፡ የቀድሞዎቹም እንደተላኩ (መልክተኛ ከኾነ) በተዓምር ይምጣብን» አሉ፡፡'),
('21:6', 87, 'ከእነሱ በፊት ያጠፋናት ከተማ አላመነችም፡፡ ታዲያ እነሱ ያምናሉን'),
('21:7', 87, 'ከአንተም በፊት ወደእነሱ የምናወርድላቸው የኾነን ሰዎችን እንጂ ሌላን አላክንም፡፡ የማታውቁም ብትኾኑ የመጽሐፉን ባለቤቶች ጠይቁ፡፡'),
('21:8', 87, 'ምግብን የማይበሉ አካልም አላደረግናቸውም፡፡ ዘውታሪዎችም አልነበሩም፡፡'),
('21:9', 87, 'ከዚያም ቀጠሮን ሞላንላቸው፡፡ አዳንናቸውም፡፡ የምንሻውንም ሰው (አዳን)፡፡ ወሰን አላፊዎቹንም አጠፋን፡፡'),
('21:10', 87, 'ክብራችሁ በውስጡ ያለበትን መጽሐፍ ወደእናንተ በእርግጥ አወረድን፡፡ አታውቁምን'),
('21:11', 87, 'በዳይም ከነበረች ከተማ ያጠፋናትና ከኋላዋም ሌሎችን ሕዝቦች ያስገኘነው ብዙ ናት፡፡'),
('21:12', 87, 'ቅጣታችንም በተሰማቸው ጊዜ እነርሱ ወዲያውኑ ከእርሷ (ለመሸሽ) ይገሠግሣሉ፡፡'),
('21:13', 87, 'አትገሥግሡ፤ ትለመኑም ይኾናልና፡፡ በእርሱ ወደ ተቀማጠላችሁበት ጸጋ ወደ መኖሪያዎቻችሁም ተመለሱ (ይባላሉ)፡፡'),
('21:14', 87, '«ዋ ጥፋታችን! እኛ በእርግጥ በዳዮች ነበርን» ይላሉ፡፡'),
('21:15', 87, 'የታጨዱ ሬሳዎችም እስካደረግናቸው ድረስ ይህቺ ጠሪያቸው ከመኾን አልተወገደችም፡፡'),
('21:16', 87, 'ሰማይንና ምድርን በመካከላቸው ያለውንም ሁሉ ቀላጆች ኾነን አልፈጠርንም፡፡'),
('21:17', 87, 'መጫወቻን (ሚስትና ልጅን) ልንይዝ በሻን ኖሮ ከእኛ ዘንድ በያዝነው ነበር፡፡ (ግን) ሠሪዎች አይደለንም፡፡'),
('21:18', 87, 'በእርግጥ እውነትን በውሸት ላይ እንጥላለን፡፡ አንጎሉን ያፈርሰዋልም፡፡ ወዲያውም እርሱ ጠፊ ነው፡፡ ለእናንተም ከዚያ (ሚስትና ልጅ አለው በማለት) ከምትመጥኑት ነገር ብርቱ ቅጣት አላችሁ፤ (ወዮላችሁ)፡፡'),
('21:19', 87, 'በሰማያትና በምድር ያለው ሁሉም የእርሱ ነው፡፡ እርሱ ዘንድ ያሉትም (መላእክት) እርሱን ከመገዛት አይኮሩም፡፡ አይሰለቹምም፡፡'),
('21:20', 87, 'በሌሊትና በቀንም ያጠሩታል፤ አያርፉም፡፡'),
('21:21', 87, 'ይልቁንም ከምድር የኾኑን እነርሱ ሙታንን የሚያስነሱን አማልክት ያዙን (የለም)፡፡'),
('21:22', 87, 'በሁለቱ (በሰማያትና በምድር) ውስጥ ከአላህ ሌላ አማልክት በነበሩ ኖሮ በተበላሹ ነበር፡፡ የዐርሹ ጌታ አላህም ከሚሉት ሁሉ ጠራ፡፡'),
('21:23', 87, 'ከሚሠራው ሁሉ አይጠየቅም፡፡ እነርሱ (ፍጥረቶቹ) ግን ይጠየቃሉ፡፡'),
('21:24', 87, 'ይልቁንም ከእርሱ ሌላ አማልክትን ያዙን «አስረጃችሁን አምጡ፡፡ ይህ (ቁርኣን) እኔ ዘንድ ያለው ሕዝብ መገሰጫ ከእኔ በፊትም የነበሩት ሕዝቦች መገሰጫ ነው» በላቸው፡፡ በውነቱ አብዛኞቻቸው እውነቱን አያውቁም፡፡ ስለዚህ እነሱ እምቢተኞች ናቸው፡፡'),
('21:25', 87, 'ከአንተ በፊትም እነሆ ከእኔ ሌላ አምላክ የለምና ተገዙኝ በማለት ወደርሱ የምናወርድለት ቢኾን እንጅ ከመልክተኛ አንድንም አልላክንም፡፡'),
('21:26', 87, '«አልረሕማንም (ከመላእክት) ልጅን ያዘ» አሉ፡፡ ጥራት ተገባው፡፡ አይደለም (መላእክት) የተከበሩ ባሮች ናቸው፡፡'),
('21:27', 87, 'በንግግር አይቀድሙትም፤ (ያላለውን አይሉም)፡፡ እነርሱም በትእዛዙ ይሠራሉ፡፡'),
('21:28', 87, 'በፊታቸው ያለውንና በኋላቸው ያለውንም ሁሉ ያውቃል፡፡ ለወደደውም ሰው እንጅ ለሌላው አያማልዱም፡፡ እነርሱም እርሱን ከመፍራታቸው የተነሳ ተጨናቂዎች ናቸው፡፡'),
('21:29', 87, 'ከእነሱም «እኔ ከእርሱ ሌላ አምላክ ነኝ» የሚል ያንን ገሀነምን እንመነዳዋለን፡፡ እንደዚሁ በዳዮችን እንመነዳለን፡፡'),
('21:30', 87, 'እነዚያም የካዱት ሰማያትና ምድር የተጣበቁ የነበሩና የለያየናቸው መኾናችንን አያውቁምን ሕያው የኾነንም ነገር ሁሉ ከውሃ ፈጠርን፡፡ አያምኑምን'),
('21:31', 87, 'በምድርም ውስጥ በእነሱ እንዳታረገርግ ጋራዎችን አደረግን፡፡ ይመሩም ዘንድ በእርሷ ውስጥ ሰፋፊ መንገዶችን አደረግን፡፡'),
('21:32', 87, 'ሰማይንም (ከመውደቅ) የተጠበቀ ጣራ አደረግን፡፡ እነርሱም ከተዓምራቶቿ ዘንጊዎች ናቸው፡፡'),
('21:33', 87, 'እርሱም ሌሊትንና ቀንን፣ ፀሐይንና ጨረቃንም የፈጠረ ነው፡፡ ሁሉም በፈለካቸው ውስጥ ይዋኛሉ፡፡'),
('21:34', 87, '(ሙሐመድ ሆይ!) ካንተ በፊት ለማንም ሰው ዘለዓለም መኖርን አላደረግንም፡፡ ታዲያ ብትሞት እነሱ ዘውታሪዎች ናቸውን'),
('21:35', 87, 'ነፍስ ሁሉ ሞትን ቀማሽ ናት፡፡ ለመፈተንም በክፉም በበጎም እንሞክራችኋለን፡፡ ወደኛም ትመለሳላችሁ፡፡'),
('21:36', 87, 'እነዚያም የካዱት ሰዎች ባዩህ ጊዜ መሳለቂያ አድርገው እንጂ አይይዙህም፡፡ እነሱ በአልረሕማን መወሳት እነርሱ ከሓዲዎች ሲሆኑ «ያ አማልክቶቻችሁን (በክፉ) የሚያነሳው ይህ ነውን» (ይላሉ)፡፡'),
('21:37', 87, 'ሰው ቸኳይ ሆኖ ተፈጠረ፡፡ ተዓምራቶቼን በእርግጥ አሳያችኋለሁና አታቻኩሉኝ፡፡'),
('21:38', 87, '«ይህ ቀጠሮም መቼ ነው እውነተኞች ከኾናችሁ (አምጡት)» ይላሉ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('21:39', 87, 'እነዚያ የካዱት ከፊቶቻቸውና ከጀርባዎቻቸው ላይ እሳትን የማይከለክሉበትን እነሱም የማይረዳዱበትን ጊዜ ቢያውቁ ኖሮ (ይህንን አይሉም ነበር)፡፡'),
('21:40', 87, 'ይልቁንም (ሰዓቲቱ) በድንገት ትመጣቸዋለች፤ ታዋልላቸዋለችም፡፡ መመለሷንም አይችሉም፡፡ እነሱም አይቆዩም፡፡'),
('21:41', 87, 'ከአንተ በፊትም የነበሩት መልክተኞች በእርግጥ ተቀለደባቸው፡፡ በእነዚያም ከእነሱ ይቀልዱ በነበሩት በርሱ ይሳለቁበት የነበሩት (ቅጣት) ሰፈረባቸው፡፡'),
('21:42', 87, '«ከአልረሕማን (ቅጣት) በሌሊትና በቀን የሚጠብቃችሁ ማነው» በላቸው፡፡ በእውነቱ እነሱ ከጌታቸው ግሳጼ (ከቁርአን) ዘንጊዎች ናቸው፡፡'),
('21:43', 87, 'ለእነሱ ከእኛ ሌላ የምትከላከልላቸው አማልክት አለቻቸውን ነፍሶቻቸውን መርዳትን አይችሉም፡፡ እነርሱም (ከሓዲዎቹ) ከእኛ አይጠበቁም፡፡'),
('21:44', 87, 'በእውነት እነዚህንና አባቶቻቸውን በእነሱ ላይ ዕድሜ እስከ ረዘመባቸው ድረስ አጣቀምናቸው፡፡ (ተታለሉም)፡፡ እኛ ምድርን ከጫፎችዋ የምናጎላት ኾነን ስንመጣባት አያዩምን እነሱ አሸናፊዎች ናቸውን'),
('21:45', 87, '«የማስፈራራችሁ በተወረደልኝ ብቻ ነው፡፡ ግን ደንቆሮዎች በሚስፈራሩ ጊዜ ጥሪን አይሰሙም» በላቸው፡፡'),
('21:46', 87, 'ከጌታህ ቅጣትም ወላፈን ብትነካቸው «ዋ ጥፋታችን! እኛ በዳዮች ነበርን» ይላሉ፡፡'),
('21:47', 87, 'በትንሣኤም ቀን ትክክለኛ ሚዛኖችን እናቆማለን፡፡ ማንኛይቱም ነፍስ ምንንም አትበደልም፡፡ (ሥራው) የሰናፍጭ ቅንጣት ያክል ቢኾንም እርሷን እናመጣታለን፡፡ ተቆጣጣሪዎችም በኛ በቃ፡፡'),
('21:48', 87, 'ለሙሳና ለሃሩንም እውነትንና ውሸትን የሚለይን ብርሃንንም ለጥንቁቆችም መገሰጫን በእርግጥ ሰጠናቸው፡፡'),
('21:49', 87, 'ለእነዚያ ጌታቸውን በሩቅ ለሚፈሩት እነሱም ከሰዓቲቱ ተጨናቂዎች ለኾኑ (መገሰጫን ሰጠን)፡፡'),
('21:50', 87, 'ይህም (ቁርኣን) ያወረድነው የኾነ ብሩክ መገሰጫ ነው፡፡ ታዲያ እናንተ ለእርሱ ከሓዲዎች ናችሁን'),
('21:51', 87, 'ለኢብራሂምም ከዚያ በፊት ቅን መንገዱን በእርግጥ ሰጠነው፡፡ እኛም በእርሱ (ተገቢነት) ዐዋቂዎች ነበርን፡፡'),
('21:52', 87, 'ለአባቱና ለሕዝቦቹ «ይህቺ ቅርጻ ቅርጽ ያቺ እናንተ ለእርሷ ተገዢዎች የኾናችሁት ምንድን ናት» ባለ ጊዜ (መራነው)፡፡'),
('21:53', 87, '«አባቶቻችንን ለእርሷ ተገዢዎች ኾነው አገኘን» አሉት፡፡'),
('21:54', 87, '«እናንተም አባቶቻችሁም በእርግጥ በግልጽ ስህተት ውስጥ ነበራችሁ» አላቸው፡፡'),
('21:55', 87, '«በምሩ መጣህልን ወይንስ አንተ ከሚቀልዱት ነህ» አሉት፡፡'),
('21:56', 87, '«አይደለም ጌታችሁ የሰማያትና የምድር ጌታ ያ የፈጠራቸው ነው፡፡ እኔም በዚህ ላይ ከመስካሪዎቹ ነኝ» አለ፡፡'),
('21:57', 87, '«በአላህም እምላለሁ ዟሪዎች ኾናችሁ ከሄዳችሁ በኋላ ጣዖቶቻችሁን ተንኮል እሠራባቸዋለሁ» (አለ)፡፡'),
('21:58', 87, '(ዘወር ሲሉ) ስብርብሮችም አደረጋቸው፡፡ ለእነሱ የኾነ አንድ ታላቅ (ጣዖት) ብቻ ሲቀር ወደርሱ ይመለሱ ዘንድ (እርሱን ተወው)፡፡'),
('21:59', 87, '«በአማልክቶቻችን ይህንን የሠራ ማነው እርሱ በእርግጥ ከበደለኞች ነው» አሉ፡፡'),
('21:60', 87, '«ኢብራሂም የሚባል ጎበዝ (በመጥፎ) ሲያነሳቸው ሰምተናል» ተባባሉ፡፡'),
('21:61', 87, '«ይመሰክሩበት ዘንድ በሰዎቹ ዓይን (ፊት) ላይ አምጡት» አሉ፡፡'),
('21:62', 87, '«ኢብራሂም ሆይ! በአማልክቶቻችን ይህንን የሠራህ አንተ ነህን» አሉት፡፡'),
('21:63', 87, '«አይደለም ይህ ታላቃቸው ሠራው፡፡ ይናገሩም እንደ ኾነ ጠይቋቸው» አለ፡፡'),
('21:64', 87, 'ወደ ነፍሶቻቸውም ተመለሱ፡፡ «እናንተ (በመጠየቃችሁ) በዳዮቹ እናንተው ናችሁም» ተባባሉ፡፡'),
('21:65', 87, 'ከዚያም በራሶቻቸው ላይ ተገለበጡ፡፡ «እነዚህ የሚናገሩ አለመኾናቸውን በእርግጥ ዐውቀሃል፤» (አሉ)፡፡'),
('21:66', 87, '«ታዲያ ለእናንተ ምንም የማይጠቅማችሁንና የማይጎዳችሁን ነገር ከአላህ ሌላ ትገዛላችሁን» አላቸው፡፡'),
('21:67', 87, '«ፎህ! ለእናንተ ከአላህ ሌላ ለምትገዙትም ነገር፤ አታውቁምን» (አለ)፡፡'),
('21:68', 87, '«ሠሪዎች እንደ ኾናችሁ አቃጥሉት፡፡ አማልክቶቻችሁንም እርዱ» አሉ፡፡ (በእሳት ላይ ጣሉትም)፡፡'),
('21:69', 87, '«እሳት ሆይ! በኢብራሂም ላይ ቀዝቃዛ፤ ሰላምም ሁኚ» አልን፡፡'),
('21:70', 87, 'በእርሱም ተንኮልን አሰቡ፡፡ በጣም ከሳሪዎችም አደረግናቸው፡፡'),
('21:71', 87, 'እርሱንና ሉጥንም ወደዚያች፤ በውስጧ ለዓለማት በረከትን ወደ አደረግንባት ምድር (በመውሰድ) አዳን፡፡'),
('21:72', 87, 'ለእርሱም ኢስሐቅን ያዕቆብንም ተጨማሪ አድርገን ሰጠነው፡፡ ሁሉንም መልካሞች አደረግን፡፤'),
('21:73', 87, 'በትዕዛዛችንም ወደ በጎ ሥራ የሚመሩ መሪዎች አደረግናቸው፡፡ ወደእነሱም መልካም ሥራዎችን መሥራትን፣ ሶላትንም መስገድን፣ ዘካንም መስጠትን አወረድን፡፡ ለእኛ ተገዢዎችም ነበሩ፡፡'),
('21:74', 87, 'ሉጥንም ፍርድንና ዕውቀትን ሰጠነው፡፡ ከዚያችም መጥፎ ሥራዎችን ትሠራ ከነበረችው ከተማ አዳንነው፡፡ እነሱ ክፉ ሰዎች አመጸኞች ነበሩና፡፡'),
('21:75', 87, 'በችሮታችንም ውስጥ አገባነው፡፡ እርሱ ከመልካሞቹ ነውና፡፡'),
('21:76', 87, 'ኑሕንም ከዚያ በፊት (ጌታውን) በጠራ ጊዜ (አስታውስ)፡፡ ለእርሱም (ጥሪውን) ተቀበልነው፡፡ እርሱንም ቤተሰቦቹንም ከከባድ ጭንቅ አዳን፡፡'),
('21:77', 87, 'ከነዚያም በታምራቶቻችን ከአስተባበሉት ሕዝቦች (ተንኮል) ጠበቅነው፡፡ እነሱ ክፉ ሕዝቦች አመጸኞች ነበሩና፡፡ ሁሉንም አሰጠምናቸውም፡፡'),
('21:78', 87, 'ዳውድንና ሱለይማንንም በአዝመራው ነገር በሚፈርዱ ጊዜ የሕዝቦቹ ፍየሎች ሌሊት በርሱ ውስጥ በተሰማሩ ጊዜ (አስታውስ)፡፡ ፍርዳቸውንም ዐዋቂዎች ነበርን፡፡'),
('21:79', 87, 'ለሱለይማንም (ትክክለኛይቱን ፍርድ) አሳወቅናት፡፡ ለሁሉም ጥበብንና ዕውቀትን ሰጠን፡፡ ተራራዎችን ከዳውድ ጋር የሚያወድሱ ሲኾኑ ገራን፡፡ አእዋፍንም (እንደዚሁ ገራን)፡፡ ሠሪዎችም ነበርን፡፡'),
('21:80', 87, 'የብረት ልብስንም ሥራ ለእናንተ ከጦራችሁ ትጠብቃችሁ ዘንድ አስተማርነው፡፡ እናንተ አመስጋኞች ናችሁን'),
('21:81', 87, 'ለሱለይማንም ነፋስን በኀይል የምትነፍስ በትዕዛዙ ወደዚያች በእርሷ ውስጥ በረከትን ወደ አደረግንባት ምድር (ወደ ሻም) የምትፈስ ስትኾን (ገራንለት)፡፡ በነገሩ ሁሉም ዐዋቂዎች ነበርን፡፡'),
('21:82', 87, 'ከሰይጣናትም ለእርሱ (ሉልን ለማውጣት) የሚጠልሙንና ከዚያም ሌላ ያለን ሥራ የሚሠሩን (ገራንለት)፡፡ ለእነሱም ተጠባባቂዎች ነበርን፡፡'),
('21:83', 87, 'አዩብንም (ኢዮብን) ጌታውን «እኔ መከራ አገኘኝ አንተም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነህ» ሲል በተጣራ ጊዜ (አስታውስ)፡፡'),
('21:84', 87, 'ለእርሱም ጥሪውን ተቀበልነው፡፡ ከጉዳትም በእርሱ ላይ የነበረውን ሁሉ አስወገድን፡፡ ቤተሰቦቹንም ከእነሱም ጋር መሰላቸውን ከእኛ ዘንድ ለችሮታና ለተገዢዎች ለማስገንዘብ ሰጠነው፡፡'),
('21:85', 87, 'ኢስማዒልንም ኢድሪስንም ዙልኪፍልንም (አስታውስ)፡፡ ሁሉም ከታጋሾቹ ናቸው፡፡'),
('21:86', 87, 'ከችሮታችንም ውስጥ አገባናቸው፡፡ እነሱ ከመልካሞቹ ናቸውና፡፡'),
('21:87', 87, 'የዓሳውንም ባለቤት ተቆጥቶ በኼደ ጊዜ (አስታውስ)፡፡ በእርሱም ላይ ፈጽሞ የማንፈርድበት መኾናችንን ጠረጠረ፡፡ (ዓሳም ዋጠው)፡፡ በጨለማዎችም ውስጥ ኾኖ ከአንተ በቀር ሌላ አምላክ የለም፡፡ ጥራት ይገባህ፡፡ እኔ በእርግጥ ከበዳዮቹ ነበርኩ በማለት ተጣራ፡፡'),
('21:88', 87, 'ለርሱም ጥሪውን ተቀበልነው፡፡ ከጭንቅም አዳነው፡፡ እንደዚሁም ምእመናንን እናድናለን፡፡'),
('21:89', 87, 'ዘከሪያንም «ጌታዬ ሆይ! ብቻዬን አትተወኝ፡፡ አንተም ከወራሾች ሁሉ በላጭ ነህ ሲል» ጌታውን በተጣራ ጊዜ (አስታውስ)፡፡'),
('21:90', 87, 'ለእርሱም ጥሪውን ተቀበልነው፡፡ ለእርሱም የሕያን ሰጠነው፡፡ ለእርሱም ሚስቱን አበጀንለት፡፡ እነርሱ በበጎ ሥራዎች የሚቻኮሉ ከጃዮችና ፈሪዎች ኾነው የሚለምኑንም ነበሩ፡፡ ለእኛ ተዋራጆችም ነበሩ፡፡'),
('21:91', 87, 'ያችንም ብልቷን የጠበቀቺውን በርሷም ውስጥ ከመንፈሳችን የነፋንባትን እርሷንም ልጅዋንም (እንደዚሁ) ለዓለማት ተዓምር ያደረግናትን (መርየምን አስታውስ)፡፡'),
('21:92', 87, 'ይህች (ሕግጋት) አንዲት መንገድ ስትሆን በእርግጥ ሃይማኖታችሁ ናት፡፡ እኔም ጌታችሁ ነኝና ተገዙኝ፡፡'),
('21:93', 87, 'በሃይማኖታቸውም ነገር በመካከላቸው ተለያዩ፡፡ ሁሉም ወደኛ ተመላሾች ናቸው፡፡'),
('21:94', 87, 'እርሱ ያመነ ኾኖ ከበጎ ሥራዎች ማንኛውንም የሚሠራም ሰው፤ ምንዳውን አይነፈግም፡፡ እኛም ለእርሱ መዝጋቢዎች ነን፡፡'),
('21:95', 87, 'ባጠፋናትም ከተማ ላይ እነሱ (ወደኛ) የማይመለሱ መኾናቸው እብለት ነው፤ (ይመለሳሉ)፡፡'),
('21:96', 87, 'የእጁጅና መእጁጅም እነርሱ ከየተረተሩ የሚንደረደሩ ሲኾኑ (ግድባቸው) በተከፈተች ጊዜ፥'),
('21:97', 87, 'እውነተኛውም ቀጠሮ በቀረበ ጊዜ፥ ያን ጊዜ እነሆ የእነዚያ የካዱት ሰዎች ዓይኖች ይፈጥጣሉ፡፡ «ዋ ጥፋታችን! ከዚህ (ቀን) በእርግጥ በዝንጋቴ ላይ ነበርን፤ በእውነትም በዳዮች ነበርን» (ይላሉ)፡፡'),
('21:98', 87, 'እናንተ ከአላህ ሌላ የምትግገዟቸውም (ጣዖታት) የገሀነም ማገዶዎች ናችሁ፡፡ እናንተ ለእርሷ ወራጆች ናችሁ፡፡'),
('21:99', 87, 'እነዚህ (ጣዖታት) አማልክት በነበሩ ኖሮ አይገቧዋትም ነበር፡፡ ግን ሁሉም በእርሷ ውስጥ ዘውታሪዎች ናቸው፡፡'),
('21:100', 87, 'ለእነርሱ በእርሷ ውስጥ መንሰቅሰቅ አላቸው፡፡ እነርሱም በውስጧ (ምንንም) አይሰሙም፡፡'),
('21:101', 87, 'እነዚያ ከእኛ መልካሟ ቃል ለእነርሱ ያለፈችላቸው እነዚያ ከርሷ የተራቁ ናቸው፡፡'),
('21:102', 87, 'ድምጽዋን አይሰሙም፡፡ እነርሱም ነፍሶቻቸው በሚሹት ነገር ውስጥ ዘውታሪዎች ናቸው፡፡'),
('21:103', 87, 'ታላቁ ድንጋጤ አያስተክዛቸውም፡፡ መላእክትም ይህ ያ ትቀጠሩ የነበራችሁት ቀናችሁ ነው፤ እያሉ ይቀበሏቸዋል፡፡'),
('21:104', 87, 'ለመጽሐፎች የኾኑ ገጾች እንደሚጠቀለሉ ሰማይን የምንጠቀልልበትን ቀን (አስታውስ)፡፡ የመጀመሪያን ፍጥረት እንደ ጀመርን እንመልሰዋለን፡፡ (መፈጸሙ) በእኛ ላይ የኾነን ቀጠሮ ቀጠርን፡፡ እኛ (የቀጠርነውን) ሠሪዎች ነን፡፡'),
('21:105', 87, 'ምድንም መልካሞቹ ባሮቼ ይወርሷታል ማለትን ከመጽሐፉ (ከተጠበቀው ሰሌዳ) በኋላ በመጽሐፎቹ በእርግጥ ጽፈናል፡፡'),
('21:106', 87, 'በዚህ (ቁርኣን) ውስጥ ለተገዢዎች ሕዝቦች በቂነት አልለ፡፡'),
('21:107', 87, '(ሙሐመድ ሆይ!) ለዓለማትም እዝነት አድርገን እንጅ አልላክንህም፡፡'),
('21:108', 87, '«ያ ወደኔ የሚወረደው አምላካችሁ አንድ አምላክ ብቻ ነው ማለት ነው፤ ታዲያ እናንተ ፍጹም ታዛዦች ናችሁን» በላቸው፡፡'),
('21:109', 87, 'እምቢም ቢሉ (በማወቅ) በእኩልነት ላይ ኾነን (የታዘዝኩትን) አስታውቅኋችሁ፡፡ «የምትስፈራሩበትም ነገር ቅርብ ወይም ሩቅ መኾኑን አላውቅም፤» በላቸው፡፡'),
('21:110', 87, 'እርሱ ከንግግር ጩኸትን ያውቃል፡፡ የምትደብቁትንም ሁሉ ያውቃል፡፡'),
('21:111', 87, 'እርሱም (ቅጣትን ማቆየት) ምናልባት ለእናንተ ፈተናና እስከ ጊዜው መጠቃቀሚያ እንደሆነም አላውቅም፤ (በላቸው)፡፡'),
('21:112', 87, '«ጌታዬ ሆይ! በእውነት ፍረድ፤ ጌታችንም እጅግ በጣም ሩኅሩኅ በምትሉት ነገር ላይ መታገዣ ነው» አለ፡፡'),
('22:1', 87, 'እናንተ ሰዎች ሆይ! ጌታችሁን ፍሩ የሰዓቲቱ እንቅጥቃጤ በጣም ከባድ ነገር ነውና፡፡'),
('22:2', 87, 'በምታዩዋት ቀን አጥቢ ሁሉ ከአጠባችው ልጅ ትፈዝዛለች፡፡ የእርግዝና ባለቤት የኾነችም ሁሉ እርጉዟን ትጨነግፋለች፡፡ ሰዎቹንም (በድንጋጤ ብርታት) የሰከሩ ኾነው ታያለህ፡፡ እነርሱም (ከመጠጥ) የሰከሩ አይደሉም፡፡ ግን የአላህ ቅጣት ብርቱ ነው፡፡'),
('22:3', 87, 'ከሰዎቹም ያለ ዕውቀት በአላህ ነገር የሚከራከር፤ ሞገደኛ ሰይጣንንም ሁሉ የሚከተል ሰው አልለ፡፡'),
('22:4', 87, 'እነሆ! የተከተለውን ሰው እርሱ ያጠመዋል፡፡ ወደ ነዳጅ እሳት ስቃይም ይመራዋል ማለት በርሱ ላይ ተጽፏል፡፡'),
('22:5', 87, 'እናንተ ሰዎች ሆይ! ከመቀስቀስ በመጠራጠር ውስጥ እንደ ሆናችሁ (አፈጣጠራችሁን ተመልከቱ)፡፡ እኛም ከዐፈር ፈጠርናችሁ፣ ከዚያም ከፍትወት ጠብታ፣ ከዚያም ከረጋ ደም፣ ከዚያም ከቁራጭ ሥጋ፣ ፍጥረትዋ ሙሉ ከሆነችና ሙሉ ካልሆነች (ችሎታችንን) ለናንተ ልንገልጽላችሁ ፈጠርናችሁ፡፡ የምንሻውንም እስከ ተወሰነ ጊዜ ድረስ በማሕፀን ውስጥ እናረጋዋለን፡፡ ከዚያም ሕፃን ሆናችሁ እናወጣችኋለን፡፡ ከዚያም ሙሉ ጥንካሪያችሁን ትደርሱ ዘንድ (እናሳድጋችኋለን)፡፡ ከእናንተም የሚሞት ሰው አልለ፡፡ ከእናንተም ከዕውቀት በኋላ ምንንም እንዳያውቅ ወደ ወራዳ ዕድሜ የሚመለስ ሰው አልለ፡፡ ምድርንም ደረቅ ሆና ታያታለህ፡፡ በእርሷም ላይ ውሃን ባወረድን ጊዜ ትላወሳለች፡፡ ትነፋፋለችም፡፡ ውበት ካለው ጎሳ ሁሉ ታበቅላለችም፡፡'),
('22:6', 87, 'ይህ አላህ እርሱ መኖሩ የተረጋገጠ፣ እርሱም ሙታንን ሕያው የሚያደርግ፣ እርሱም በነገሩ ሁሉ ላይ ቻይ በመሆኑ ነው፡፡'),
('22:7', 87, 'ሰዓቲቱም መጪ ፣ በእርሷ ፈጽሞ ጥርጣሬ የሌለባት በመሆኗ፣ አላህም በመቃብሮች ውስጥ ያለን ሁሉ የሚቀሰቅስ በመሆኑ ነው፡፡'),
('22:8', 87, 'ከሰዎችም ውስጥ ያለ ዕውቀት፣ ያለ ማስረጃም፣ ያለ አብራሪ መጽሐፍም በአላህ ነገር የሚከራከር ሰው አልለ፡፡'),
('22:9', 87, 'ጎኑን ያጠፈ ሆኖ ከአላህ መንገድ ሊያሳስት (ይከራከራል)፡፡ በቅርቢቱ ዓለም ለእርሱ ውርደት አልለው፡፡ በትንሳኤ ቀንም አቃጣይን ቅጣት እናቀምሰዋለን፡፡'),
('22:10', 87, 'ይህ እጆችህ ባስቀደሙት ኀጢአት አላህም ለባሮቹ ፈጽሞ በዳይ ባለመሆኑ ነው (ይባላል)፡፡'),
('22:11', 87, 'ከሰዎችም (ከሃይማኖት) በጫፍ ላይ ሆኖ አላህን የሚግገዛ ሰው አልለ፡፡ ታዲያ መልካም ነገር ቢያገኘው በእርሱ ይረጋል፡፡ መከራም ብታገኘው በፊቱ ላይ ይገለበጣል፡፡ የቅርቢቱን ዓለምም የመጨረሻይቱንም ከሰረ፡፡ ይህ እርሱ ግልጽ ከሳራ ነው፡፡'),
('22:12', 87, 'ከአላህ ሌላ የማይጎዳውንና የማይጠቅመውን ይግገዛል፡፡ ይህ እርሱ (ከእውነት) የራቀ ስህተት ነው፡፡'),
('22:13', 87, 'ያንን ከጥቅሙ ይልቅ ጉዳቱ የሚቀርብን ይግገዛል፡፡ ረዳቱ ምንኛ ከፋ!'),
('22:14', 87, 'አላህ እነዚያን ያመኑትንና መልካም ሥራዎችን የሠሩትን በሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች ያገባቸዋል፡፡ አላህ የሚሻውን ነገር በእርግጥ ይሠራል፡፡'),
('22:15', 87, 'አላህ (መልክተኛውን) በቅርቢቱም በመጨረሻይቱም ዓለም አይረዳውም ብሎ የሚያስብ ሰው ገመድን ወደ ሰማይ ይዘርጋ፡፡ ከዚያም (ትንፋሹ እስኪቆረጥ) ይታነቅ፡፡ ተንኮሉ የሚያስቆጨውን ነገር ያስወግድለት እንደሆነም ይመልከት፡፡'),
('22:16', 87, 'እንደዚሁም (ቁርኣንን) የተብራሩ አንቀጾች አድርገን አወረድነው፡፡ አላህም የሚሻውን ሰው ይመራል፡፡'),
('22:17', 87, 'እነዚያ ያመኑት፣ እነዚያም ይሁዳውያን የሆኑ፣ ሳቢያኖችም፣ ክርስቲያኖችም፣ መጁሶችም እነዚያም (ጣዖታትን በአላህ) ያጋሩ አላህ በትንሣኤ ቀን በመካከላቸው በፍርድ ይለያል፡፡ አላህ በነገሩ ሁሉ ላይ በእርግጥ ዐዋቂ ነውና፡፡'),
('22:18', 87, 'አላህ በሰማያት ያለው ሁሉ፣ በምድርም ያለው ሁሉ፣ ፀሐይና ጨረቃም፣ ከዋክብትም፣ ተራራዎችም፣ ዛፎችም፣ ተንቀሳቃሾችም ከሰዎች ብዙዎችም፣ ለርሱ የሚሰግዱለት መሆኑን አታውቁምን ብዙውም በርሱ ላይ ቅጣት ተረጋገጠበት፡፡ አላህ የሚያዋርደውም ሰው ለእርሱ ምንም አክባሪ የለውም፡፡ አላህ የሻውን ይሠራልና፡፡'),
('22:19', 87, 'እነዚህ በጌታቸው የተከራከሩ ሁለት ባላጋራዎች ናቸው፡፡ እነዚያም የካዱት ለእነርሱ የእሳት ልብሶች ተለክተውላቸዋል፡፡ ከራሶቻቸው በላይ የፈላ ውሃ ይምቧቧቸዋል፡፡'),
('22:20', 87, 'በሆዶቻቸው ውስጥ ያሉ ቆዳዎቻቸውም በእርሱ ይቀለጣሉ፡፡'),
('22:21', 87, 'ለእነሱም (መቅጫ) ከብረት የሆኑ መዶሻዎች አልሉ፡፡'),
('22:22', 87, 'ከጭንቀት ብርታት የተነሳ ከእርሷ ለመውጣት በፈለጉ ቁጥር ከእርሷ ውስጥ እንዲመለሱ ይደረጋሉ፡፡ «በጣም የሚያቃጥልንም ቅጣት ቅመሱ» (ይባላሉ)፡፡'),
('22:23', 87, 'አላህ እነዚያን ያመኑትንና መልካም ሥራዎችን የሠሩትን ሰዎች በሥሮቻቸው ወንዞች የሚፈስሱባቸውን ገነቶች ያገባቸዋል፡፡ በእርሷ ውስጥ ከወርቅ የሆኑን አንባሮችና ሉልን ይሸለማሉ፡፡ በእርሷ ውስጥ ልብሶቻቸውም ሐር ናቸው፡፡'),
('22:24', 87, 'ከንግግርም ወደ መልካሙ ተመሩ፡፡ ወደ ምስጉንም መንገድ ተመሩ፡፡'),
('22:25', 87, 'እነዚያ የካዱ ከአላህም መንገድና ከዚያም ለሰዎች በውስጡ ነዋሪ ለሆኑትም፣ ከሩቅ ለሚመጡትም እኩል ካደረግነው ከተከበረው መስጊድ (ሰዎችን) የሚከለክሉ (አሳማሚን ቅጣት እናቀምሳቸዋለን)፡፡ በእርሱም ውስጥ (ከትክክለኛ መንገድ) በመዘንበል በዳይ ሆኖ (ማንኛውንም ነገር) የሚፈልግ ሰው ከአሳማሚ ቅጣት እናቀምሰዋለን፡፡'),
('22:26', 87, 'ለኢብራሂምም የቤቱን (የካዕባን) ስፍራ መመለሻ ባደረግንለት ጊዜ «በእኔ ምንንም አታጋራ፣ ቤቴንም ለሚዞሩትና ለሚቆሙበት ለሚያጎነብሱትና በግንባራቸውም ለሚደፉት ንጹሕ አድርግላቸው» (ባልነው ጊዜ አስታውስ)፡፡'),
('22:27', 87, '(አልነውም)፡- በሰዎችም ውስጥ በሐጅ ትዕዛዝ ጥራ፡፡ እግረኞች ከየሩቅ መንገድ በሚመጡ ከሲታ ግመሎችም ሁሉ ላይ ሆነው ይመጡሃልና፡፡'),
('22:28', 87, 'ለእነሱ የሆኑ ጥቅሞችን ይጣዱ ዘንድ በታወቁ ቀኖችም ውስጥ ከለማዳ እንስሳዎች በሰጣቸው ሲሳይ ላይ የአላህን ስም ያወሱ ዘንድ (ይመጡሃል)፡፡ ከርሷም ብሉ፡፡ ችግረኛ ድሃንም አብሉ፡፡'),
('22:29', 87, 'ከዚያም (እንደ ጠጉርና ጥፍር ያሉትን) ትርፍ አካላቸውንና ዕድፋቸውን ያስወግዱ፡፡ ስለቶቻቸውንም ይሙሉ፤ በጥንታዊውም ቤት ይዙሩ፡፡'),
('22:30', 87, '(ነገሩ) ይህ ነው፡፡ የአላህንም ሕግጋት የሚያከብር ሰው እርሱ ጌታው ዘንድ ለእርሱ በጣም የተሻለ ነው፡፡ የቤት እንስሳትም (ግመል ከብት በግና ፍየል) በናንተ ላይ (እርም መሆኑ) ከሚነበብላችሁ በስተቀር ለእናንተ ተፈቅዳላችኋለች፡፡ ከጣዖታትም ርክሰት ተጠንቀቁ፡፡ ሐሰትንም ቃል ራቁ፡፡'),
('22:31', 87, 'ለአላህ ታዛዦች በእርሱ የማታገሩ ሆናችሁ (ከሐሰት ራቁ)፡፡ በአላህም የሚያጋራ ሰው፤ ከሰማይ እንደ ወደቀና በራሪ እንደምትነጥቀው፣ ወይም ነፋስ እርሱን በሩቅ ስፍራ እንደምትጥለው ብጤ ነው፡፡'),
('22:32', 87, '(ነገሩ) ይህ ነው፡፡ የአላህንም የሃይማኖት ምልክቶች የሚያከብር ሰው እርሷ ከልቦች የኾነች ጥንቃቄ ናት፡፡'),
('22:33', 87, 'ለእናንተ በእርሷ እስከ ተወሰነ ጊዜ ድረስ ጥቅሞች አሏችሁ፡፡ ከዚያም (የማረጃ) ስፍራዋ እጥንታዊው ቤት አጠገብ ነው፡፡'),
('22:34', 87, 'ለሕዝብም ሁሉ (ወደ አላህ) መስዋዕት ማቅረብን ደነገግን፡፡ ከቤት እንስሳት በሰጣቸው ሲሳይ ላይ የአላህን ስም ብቻ ያወሱ ዘንድ (አዘዝናቸው)፡፡ አምላካችሁም አንድ አምላክ ብቻ ነው፡፡ ለእርሱም ብቻ ታዘዙ፡፡ ለአላህ ተዋራጆችንም አብስራቸው፡፡'),
('22:35', 87, 'እነዚያን አላህ በተወሳ ጊዜ ልቦቻቸው የሚጨነቁትን፣ በደረሰባቸውም (መከራ) ላይ ታጋሾችን፣ ሶላትንም አስተካክለው ሰጋጆችን፣ ከሰጠናቸውም ሲሳይ የሚለግሱትን (አብስር)፡፡'),
('22:36', 87, 'ግመሎችንም ለእናንተ ከአላህ ሃይማኖት ምልክቶች አደረግናቸው፡፡ በእርሷ ለእናንተ መልካም ጥቅም አላችሁ፡፡ በእርሷም ላይ (ስታርዷት) በሶስት እግሮችዋ ቆማ የተሰለፈች ሆና የአላህን ስም አውሱ፡፡ ጎኖቻቸውም በወደቁ ጊዜ ከእርሷ ብሉ፡፡ ለማኝንም ለልመና የሚያገዳድምንም አብሉ፡፡ እንደዚሁ ታመሰግኑ ዘንድ ለእናንተ ገራናት፡፡'),
('22:37', 87, 'አላህን ሥጋዎቿም ደሞቿም ፈጽሞ አይደርሰውም፡፡ ግን ከእናንተ የሆነው ፍራቻ ይደርሰዋል፡፡ እንደዚሁ አላህን በመራችሁ ላይ ልታከብሩት ለእናንተ ገራት፡፡ በጎ ሠሪዎችንም አብስር፡፡'),
('22:38', 87, 'አላህ ከእነዚያ ካመኑት ላይ ይከላከልላቸዋል፡፡ አላህ ከዳተኛን ውለታቢስን ሁሉ አይወድም፡፡'),
('22:39', 87, 'ለእነዚያ ለሚገደሉት (ምእመናን) እነርሱ የተበደሉ በመኾናቸው (መጋደል) ተፈቀደላቸው፡፡ አላህም እነርሱን በመርዳት ላይ በእርግጥ ቻይ ነው፡፡'),
('22:40', 87, 'ለእነዚያ «ጌታችን አላህ ነው» ከማለታቸው በስተቀር ያለ አግባብ ከአገራቸው የተባረሩ ለሆኑት (ተፈቀደ)፡፡ አላህ ሰዎችን ከፊላቸውን በከፊሉ መገፍተሩ ባልነበረ ኖሮ ገዳማት፣ ቤተክርስቲያኖችም፣ ምኩራቦችም በውስጣቸው የአላህ ስም በብዛት የሚወሳባቸው መስጊዶችም፤ በተፈረሱ ነበር፡፡ አላህም ሃይማኖቱን የሚረዳውን ሰው በእርግጥ ይረዳዋል፡፡ አላህ ብርቱ አሸናፊ ነውና፡፡'),
('22:41', 87, '(እነርሱም) እነዚያ በምድር ላይ ብናስመቻቸው ሶላትን እንደሚገባ የሚያስተካክሉ፣ ዘካንም የሚሰጡ፣ በደግ ነገርም የሚያዝዙ፣ ከመጥፎ ነገርም የሚከለክሉ ናቸው፡፡ የነገሮቹም ሁሉ መጨረሻ ወደ አላህ ነው፡፡'),
('22:42', 87, 'ቢያስተባብሉህም ከእነሱ በፊት የኑሕ ሕዝቦች ዓድና ሰሙድም በእርግጥ አስተባብለዋል፡፡'),
('22:43', 87, 'የኢብራሂምም ሕዝቦች የሉጥም ሕዝቦች (አስተባብለዋል)፡፡'),
('22:44', 87, 'የመድየንም ሰዎች (አስተባብለዋል)፡፡ ሙሳም ተስተባብሏል፡፡ ለከሓዲዎቹም ጊዜ ሰጠኋቸው፡፡ ከዚያም ያዝቸው፡፡ ጥላቻዬም እንዴት ነበረ!'),
('22:45', 87, 'ከከተማም እርሷ በደለኛ ሆና ያጠፋናትና እርሷ በጣሪያዎቿ ላይ ወዳቂ የሆነችው ብዙ ናት፡፡ ከተራቆተችም የውሃ ጉድጓድ ከተገነባም ሕንፃ (ያጠፋነው ብዙ ነው)፡፡'),
('22:46', 87, 'ለእነርሱም በእነርሱ የሚያውቁባቸው ልቦች ወይም በእነርሱ የሚሰሙባቸው ጆሮች ይኖሯቸው ዘንድ በምድር ላይ አይሄዱምን እነሆ ዓይኖች አይታወሩም ግን እነዚያ በደረቶች ውስጥ ያሉት ልቦች ይታወራሉ፡፡'),
('22:47', 87, 'አላህም ቀጠሮውን በፍጹም የማይጥስ ሲሆን በቅጣት ያቻኩሉሃል፡፡ እጌታህም ዘንድ አንዱ ቀን ከምትቆጥሩት (ቀን) እንደ ሺሕ ዓመት ነው፡፡'),
('22:48', 87, 'ከከተማ እርሷ በዳይ ሆና ለእርሷ ጊዜ የሰጠኋትና ከዚያም የያዝኳት ብዙ ናት፡፡ መመለሻም ወደኔ ብቻ ነው፡፡'),
('22:49', 87, '«እናንተ ሰዎች ሆይ! እኔ ለእናንተ ግልጽ አስጠንቃቂ ብቻ ነኝ» በላቸው፡፡'),
('22:50', 87, 'እነዚያም ያመኑ መልካም ሥራዎችንም የሠሩ ለእነርሱ ምህረትና ያማረ ሲሳይ አላቸው፡፡'),
('22:51', 87, 'እነዚያም የሚያመልጡ መስሏቸው ተዓምራቶቻችንን በመንቀፍ የተጉ እነሱ የእሳት ጓዶች ናቸው፡፡'),
('22:52', 87, 'ከመልክተኛና ከነቢይም ከአንተ በፊት አንድንም አላክንም ባነበበ (እና ዝም ባለ) ጊዜ ሰይጣን በንባቡ ላይ (ማጥመሚያን ቃል) የሚጥል ቢሆን እንጅ፡፡ ወዲያውም አላህ ሰይጣን የሚጥለውን ያስወግዳል፡፡ ከዚያም አላህ አንቀጾቹን ያጠነክራል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('22:53', 87, 'ሰይጣን የሚጥለውን ነገር ለእነዚያ በልቦቻቸው ውስጥ በሽታ ላለባቸው ልቦቻቸውም ደረቆች ለሆኑት ፈተና ሊያደርግ (ይጥላል)፡፡ በዳዮችም ከእውነት በራቀ ጭቅጭቅ ውስጥ ናቸው፡፡'),
('22:54', 87, 'እነዚያም ዕውቀትን የተሰጡት እርሱ (ቁርኣን) ከጌታህ የኾነ እውነት መኾኑን እንዲያውቁና በእርሱ እንዲያምኑ ልቦቻቸውም ለእርሱ እንዲረኩ (ያጠነክራል)፡፡ አላህም እነዚያን ያመኑትን ወደ ቀጥተኛው መንገድ በእርግጥ መሪ ነው፡፡'),
('22:55', 87, 'እነዚያ የካዱት ሰዎች ሰዓቲቱ በድንገት እስከምትመጣባቸው ወይም (ከደግ ነገር) መካን የሆነው ቀን ቅጣት እስከሚመጣባቸው ድረስ ከእርሱ (ከቁርኣን) በመጠራጠር ውስጥ ከመሆን አይወገዱም፡፡'),
('22:56', 87, 'በዚያ ቀን ንግሥናው የአላህ ብቻ ነው፡፡ በመካከላቸው ይፈርዳል፡፡ እነዚያም ያመኑት መልካም ሥራዎችንም የሠሩት በመደሰቻ ገነቶች ውስጥ ናቸው፡፡'),
('22:57', 87, 'እነዚያም የካዱት በአንቀጾቻችንም ያስተባበሉት እነዚያ ለእነርሱ አዋራጅ ቅጣት አላቸው፡፡'),
('22:58', 87, 'እነዚያም በአላህ ሃይማኖት የተሰደዱ ከዚያም የተገደሉ ወይም የሞቱ አላህ መልካምን ሲሳይ በእርግጥ ይሰጣቸዋል፡፡ አላህም እርሱ ከሰጪዎች ሁሉ በላጭ ነው፡፡'),
('22:59', 87, 'የሚወዱትን መግቢያ (ገነትን) በእርግጥ ያገባቸዋል፡፡ አላህም በእርግጥ ዐዋቂ ታጋሽ ነው፡፡'),
('22:60', 87, '(ነገሩ) ይህ ነው፡፡ በእሱ በተበደለበትም ብጤ የተበቀለ ሰው ከዚያም በእርሱ ላይ ግፍ የተዋለበት አላህ በእርግጥ ይረዳዋል፡፡ አላህ ይቅር ባይ መሓሪ ነውና፡፡'),
('22:61', 87, 'ይህ አላህ ሌሊትን በቀን ውስጥ የሚያስገባ ቀንንም በሌሊት ውስጥ የሚያስገባ (ቻይ) አላህም ሰሚ ተመልካች በመሆኑ ነው፡፡'),
('22:62', 87, 'ይህ አላህ እርሱ እውነት በመሆኑ ከእርሱም ሌላ የሚግገዙት ነገር እርሱ ፍጹም ውሸት በመሆኑ አላህም እርሱ የሁሉ በላይ ታላቅ በመኾኑ ነው፡፡'),
('22:63', 87, 'አላህ ከሰማይ ውሃን ማውረዱንና ምድር የምትለመልም መኾኗን አታይምን አላህ ሩኅሩኅ ውስጠ ዐዋቂ ነው፡፡'),
('22:64', 87, 'በሰማያት ውስጥ ያለውና በምድር ውስጥ ያለው ሁሉ የርሱ ብቻ ነው፡፡ አላህም እርሱ ተብቃቂው ምስጉኑ ነው፡፡'),
('22:65', 87, 'አላህ በምድር ውስጥ ያለን ሁሉ ለእናንተ የገራላችሁ፣ መርከቦችንም በባሕር ውስጥ በፈቃዱ የሚንሻለሉ ሲኾኑ (የገራላችሁ) መኾኑን፣ ሰማይንም በፈቃዱ ካልኾነ በምድር ላይ እንዳትወድቅ የሚይዛት መኾኑን አላየህምን አላህ ለሰዎች በእርግጥ ሩኅሩኅ አዛኝ ነው፡፡'),
('22:66', 87, 'እርሱም ያ ሕያው ያደረጋችሁ ነው፡፡ ከዚያም ይገድላችኋል፡፡ ከዚያም ሕያው ያደርጋችኋል፡፡ ሰው በእርግጥ በጣም ከሓዲ ነው፡፡'),
('22:67', 87, 'ለየሕዝቡ ሁሉ እነሱ የሚሠሩበት የኾነን ሥርዓተ ሃይማኖት አድርገናል፡፡ ስለዚህ በነገሩ አይከራከሩህ፡፡ ወደ ጌታህ መንገድም ጥራ፡፡ አንተ በእርግጥ በቅኑ መንገድ ላይ ነህና፡፡'),
('22:68', 87, 'ቢከራከሩህም «አላህ የምትሰሩትን ሁሉ ዐዋቂ ነው» በላቸው፡፡'),
('22:69', 87, 'አላህ በትንሣኤ ቀን በዚያ በእርሱ ትለያዩበት በነበራችሁት ሁሉ በመካከላችሁ ይፈርዳል፡፡'),
('22:70', 87, 'አላህ በሰማይና በምድር ውስጥ ያለን ሁሉ በእርግጥ የሚያውቅ መኾኑን አታውቅምን ይህ በመጽሐፍ ውስጥ (የተመዘገበ) ነው፡፡ ይህ በአላህ ላይ ገር ነው፡፡'),
('22:71', 87, 'ከአላህ ሌላም በእርሱ ማስረጃን ያላወረደበትን ለእነርሱም በእርሱ ዕውቀት የሌላቸውን ነገር ይግገዛሉ፡፡ ለባዳዮችም ምንም ረዳት የላቸውም፡፡'),
('22:72', 87, 'አንቀጾቻችንም የተብራሩ ኾነው በእነሱ ላይ በሚነበቡ ጊዜ በእነዚያ በካዱት ሰዎች ፊቶች ላይ ጥላቻን ታውቃለህ፡፡ በእነዚያ በእነሱ ላይ አንቀጾቻችንን በሚያነቡት ላይ በኃይል ሊዘልሉባቸው ይቃረባሉ፡፡ «ከዚህ ይልቅ የከፋን ነገር ልንገራችሁን» በላቸው፡፡ «(እርሱም) እሳት ናት፡፡ አላህ ለእነዚያ ለካዱት ሰዎች ቀጥሯታል፡፡ ምን ትከፋም መመለሻ!»'),
('22:73', 87, 'እናንተ ሰዎች ሆይ! አስደናቂ ምሳሌ ተገለጸላችሁ፡፡ ለእርሱም አድምጡት፡፡ እነዚያ ከአላህ ሌላ የምትግገዟቸው (ጣዖታት) ዝንብን ፈጽሞ አይፈጥሩም፡፡ እርሱን (ለመፍጠር) ቢሰበሰቡም እንኳን (አይችሉም)፡፡ አንዳችንም ነገር ዝንቡ ቢነጥቃቸው ከእርሱ አያስጥሉትም፡፡ ፈላጊውም ተፈላጊውም ደከሙ፡፡'),
('22:74', 87, 'አላህን ተገቢ ክብሩን አላከበሩትም፡፡ አላህ በጣም ኃያል አሸናፊ ነው፡፡'),
('22:75', 87, 'አላህ ከመላእክት ውስጥ መልክተኞችን ይመርጣል፡፡ ከሰዎችም (እንደዚሁ)፤ አላህ ሰሚ ተመልካች ነው፡፡'),
('22:76', 87, 'በስተፊታቸው ያለን በስተኋላቸውም ያለን ሁሉ ያውቃል፡፡ ወደ አላህም ነገሮች ሁሉ ይመለሳሉ፡፡'),
('22:77', 87, 'እናንተ ያመናችሁ ሰዎች ሆይ! (በስግደታችሁ) አጎንብሱ፣ በግንባራችሁም ተደፉ፣ ጌታችሁንም ተገዙ፣ በጎንም ነገር ሥሩ፣ ልትድኑ ይከጀልላችኋልና፡፡'),
('22:78', 87, 'በአላህም ሃይማኖት ተገቢውን ትግል ታገሉ፡፡ እርሱ መርጧችኋል፡፡ በናንተም ላይ በሃይማኖቱ ውስጥ ምንም ችግር አላደረገባችሁም፡፡ የአባታችሁን የኢብራሂምን ሃይማኖት ተከተሉ፡፡ እርሱ ከዚህ በፊት ሙስሊሞች ብሎ ሰይሟችኋል፡፡ በዚህም (ቁርኣን)፤ መልክተኛው በእናንተ ላይ መስካሪ እንዲሆን እናንተም በሰዎቹ ላይ መስካሪዎች እንድትኾኑ (ሙስሊሞች ብሎ ሰይሟችኋል)፡፡ ሶላትንም አስተካክላችሁ ስገዱ፣ ዘካንም ስጡ፣ በአላህም ተጠበቁ፣ እርሱ ረዳታችሁ ነው፡፡ (እርሱ) ምን ያምር ጠባቂ! ምን ያምርም ረዳት!'),
('23:1', 87, 'ምእምናን ፍላጎታቸውን ሁሉ በእርግጥ አገኙ (ዳኑ)፡፡'),
('23:2', 87, 'እነዚያ እነርሱ በስግደታቸው ውስጥ (አላህን) ፈሪዎች፡፡'),
('23:3', 87, 'እነዚያም እነርሱ ከውድቅ ንግግር ራቂዎች፡፡'),
('23:4', 87, 'እነዚያም እነርሱ ዘካን ሰጭዎች፡፡'),
('23:5', 87, 'እነዚያም እነርሱ ብልቶቻቸውን ጠባቂዎች የሆኑት (አገኙ)፡፡'),
('23:6', 87, 'በሚስቶቻቸው ወይም እጆቻቸው በያዟቸው (ባሪያዎች) ላይ ሲቀር፡፡ እነርሱ (በነዚህ) የማይወቀሱ ናቸውና፡፡'),
('23:7', 87, 'ከዚህም ወዲያ የፈለጉ ሰዎች እነዚያ እነርሱ ወሰን አላፊዎች ናቸው፡፡'),
('23:8', 87, 'እነዚያም እነርሱ ለአደራዎቻቸውና ለቃል ኪዳናቸው ጠባቂዎች፡፡'),
('23:9', 87, 'እነዚያም እነሱ በስግደቶቻቸው ላይ የሚጠባበቁ የኸኑት (አገኙ)፡፡'),
('23:10', 87, 'እነዚያ ወራሾቹ እነርሱ ናቸው፡፡'),
('23:11', 87, 'እነዚያ ፊርደውስን (ላዕላይ ገነትን)፤ የሚወርሱ ናቸው፡፡ እነርሱ በእርሷ ውስጥ ዘውታሪዎች ናቸው፡፡'),
('23:12', 87, 'በእርግጥም ሰውን ከነጠረ ጭቃ ፈጠርነው፡፡'),
('23:13', 87, 'ከዚያም በተጠበቀ መርጊያ ውስጥ የፍትወት ጠብታ አደረግነው፡፡'),
('23:14', 87, 'ከዚያም ጠብታዋን (በአርባ ቀን) የረጋ ደም አድርገን ፈጠርን፡፡ የረጋውንም ደም ቁራጭ ሥጋ አድርገን ፈጠርን፡፡ ቁራጯንም ሥጋ አጥንቶች አድርገን ፈጠርን፡፡ አጥንቶቹንም ሥጋን አለበስናቸው፡፡ ከዚያም (ነፍስን በመዝራት) ሌላ ፍጥረትን አድርገን አስገኘነው፡፡ ከሰዓሊዎችም ሁሉ በላጭ የሆነው አላህ ላቀ፡፡'),
('23:15', 87, 'ከዚያም እናንተ ከዚህ በኋላ በእርግጥ ሟቾች ናችሁ፡፡'),
('23:16', 87, 'ከዚያም እናንተ በትንሣኤ ቀን ትቀሰቀሳላችሁ፡፡'),
('23:17', 87, 'በእርግጥም ከበላያችሁ ሰባትን ሰማያት ፈጠርን፡፡ ከፍጥረቶቹም ዘንጊዎች አይደለንም፡፡'),
('23:18', 87, 'ከሰማይም ውሃን በልክ አወረድን፡፡ በምድርም ውስጥ አስቀመጥነው፡፡ እኛም እርሱን በማስወገድ ላይ በእርግጥ ቻዮች ነን፡፡'),
('23:19', 87, 'በእርሱም ከዘምባባዎችና ከወይኖች የኾኑን አትክልቶች ለእናንተ አስገኘንላችሁ፡፡ በውስጧ ለእናንተ ብዙ ፍራፍሬዎች አሏችሁ፡፡ ከእርሷም ትበላላችሁ፡፡'),
('23:20', 87, 'ከሲና ተራራም የምትወጣን ዛፍ በቅባትና ለበይዎችም መባያ በሚኾን (ዘይት) ተቀላቅላ የምትበቅልን (አስገኘንላችሁ)፡፡'),
('23:21', 87, 'ለእናንተም በግመል፣ በከብት፣ በፍየልና በበግ መገምገሚያ አልላችሁ፡፡ በሆዶችዋ ውስጥ ካለው (ወተት) እናጠጣችኋለን፡፡ ለእናንተም በእርሷ ብዙ ጥቅሞች አሏችሁ፡፡ ከእርሷም ትበላላችሁ፡፡'),
('23:22', 87, 'በእርሷም ላይ በመርከብም ላይ ትጫናላችሁ፡፡'),
('23:23', 87, 'ኑሕንም ወደ ሕዝቦቹ በእርግጥ ላክነው፡፡ ወዲያውም «ሕዝቦቼ ሆይ! አላህን ተገዙ፡፡ ከእርሱ ሌላ ምንም አምላክ የላችሁም፡፡ አትጠነቀቁምን» አላቸው፡፡'),
('23:24', 87, 'ከሕዝቦቹም እነዚያ ታላላቆቹ ሰዎች አሉ «ይህ ብጤያችሁ ሰው እንጅ ሌላ አይደለም፡፡ በእናንተ ላይ መብለጥን ይፈልጋል፡፡ አላህም በሻ ኖሮ መላእክትን ባወረደ ነበር፡፡ ይህንንም (የሚለውን) በመጀመሪያዎቹ አባቶቻችን አልሰማንም፡፡'),
('23:25', 87, '«እርሱ በእርሱ ዕብደት ያለበት ሰው እንጅ ሌላ አይደለም፡፡ በእርሱም እስከ ጊዜ (ሞቱ) ድረስ ተጠባበቁ» (አሉ)፡፡'),
('23:26', 87, '(ኑሕም) «ጌታዬ ሆይ! ባስተባበሉኝ ምክንያት እርዳኝ» አለ፡፡'),
('23:27', 87, 'ወደርሱም (እንዲህ ስንል) ላክን «በተመልካችነታችንና በትእዛዛችንም ታንኳን ሥራ በመጣና እቶኑ በፈለቀ ጊዜ በውስጧ ከሁሉም ሁለት ዓይነቶችን ቤተሰቦችህንም ከነሱ (ጠፊ በመኾን) ቃል ያለፈበት ብቻ ሲቀር፤ አግባ፡፡ በእነዚያም በበደሉት ሰዎች ነገር አታነጋግረኝ፡፡ እነሱ ተሰጣሚዎች ነቸውና፡፡'),
('23:28', 87, 'አንተም አብረውህ ካሉት ጋር በታንኳይቱ ላይ በተደላደልክ ጊዜ «ምስጋና ለዚያ ከበደለኞች ሕዝቦች ላዳነን አላህ ይገባው» በል፡፡'),
('23:29', 87, 'በልም «ጌታዬ ሆይ! ብሩክ የኾነን ማውረድ አውርደኝ፡፡ አንተም ከአውራጆች ሁሉ በላጭ ነህ፡፡»'),
('23:30', 87, 'በዚህ ውስጥ (ለከሃሊነታችን) ምልከቶች አልሉበት፡፡ እነሆ! (የኑሕን ሰዎች) በእርግጥም ፈትታኞች ነበርን፡፡'),
('23:31', 87, 'ከዚያም ከኋላቸው ሌሎችን የክፍለ ዘመን ሕዝቦች አስገኘን፡፡'),
('23:32', 87, 'በውስጣቸውም ከእነሱ የኾነን መልክተኛ አላህን ተገዙ ከእርሱ ሌላ አምላክ የላችሁም አትጠነቀቁምን በማለት ላክን፡፡'),
('23:33', 87, 'ከሕዝቦቹም እነዚያ የካዱት በመጨረሻይቱም ቀን መገናኘት ያስተባበሉት በቅርቢቱም ሕይወት ያቀማጠልናቸው ታላላቅ ሰዎች «ይህ ብጤያችሁ ሰው እንጂ ሌላ አይደለም፡፡ ከርሱ ከምትበሉት ምግብ ይበላል፡፡ ከምትጠጡትም ውሃ ይጠጣል» አሉ፡፡'),
('23:34', 87, '«ብጤያችሁም የኾነን ሰው ብትታዘዙ እናንተ ያን ጊዜ በእርግጥ የተሞኛችሁ ናቸሁ» (አሉ)፡፡'),
('23:35', 87, '«እናንተ በሞታችሁና ዐፈርና አጥንቶችም በኾናችሁ ጊዜ እናንተ (ከመቃብር) ትወጣላችሁ በማለት ያስፈራራችኋልን'),
('23:36', 87, '«ያ የምትስፈራሩበት ነገር ራቀ፤ በጣም ራቀ፡፡'),
('23:37', 87, '«እርሷ (ሕይወት) ቅርቢቱ ሕይወታችን እንጂ ሌላ አይደለችም፡፡ እንሞታለን፤ (ልጆቻችን ስለሚተኩ) ሕያውም እንኾናለን፡፡ እኛም ተቀስቃሾች አይደለንም፡፡'),
('23:38', 87, '«እርሱ በአላህ ላይ ውሸትን የቀጠፈ ሰው እንጂ ሌላ አይደለም፡፡ እኛም ለእርሱ አማኞች አይደለንም» (አሉ)፡፡'),
('23:39', 87, '(መልክተኛውም) «ጌታዬ ሆይ! ስላስተባበሉኝ እርዳኝ» አለ፡፡'),
('23:40', 87, '(አላህም) «ከጥቂት ጊዜ በኋላ (በጥፋታቸው) በእርግጥ ተጸጻቾች ይኾናሉ» አለው፡፡'),
('23:41', 87, 'ወዲያውም (የጥፋት) ጩኸቲቱ በእውነት ያዘቻቸው፡፡ እንደ ጎርፍ ግብስባሽም አደረግናቸው፡፡ ለበደለኞች ሕዝቦችም (ከእዝነት) መራቅ ተገባቸው፡፡'),
('23:42', 87, 'ከዚያም ከእነሱ በኋላ ሌሎችን የክፍለ ዘመናት ሕዝቦች አስገኘን፡፡'),
('23:43', 87, 'ማንኛይቱም ሕዝብ ጊዜያዋን አትቀድምም፤ አይቅቆዩምም፡፡'),
('23:44', 87, 'ከዚያም መልክተኞቻችንን የሚከታተሉ ኾነው ላክን፡፡ ማንኛይቱንም ሕዝብ መልክተኛዋ በመጣላት ቁጥር አስተባበሉት፡፡ ከፊላቸውንም በከፊሉ (በጥፋት) አስከታተለን፡፡ ወሬዎችም አደረግናቸው፡፡ ለማያምኑም ሕዝቦች (ከእዝነታችን) መራቅ ተገባቸው፡፡'),
('23:45', 87, 'ከዚያም ሙሳንና ወንድሙን ሃሩንን በተዓምራታችንና በግልጽ አስረጅ ላክን፡፡'),
('23:46', 87, 'ወደ ፈርዖንና ወደ ጭፍሮቹ (ላክናቸው)፡፡ ኮሩም፡፡ የተንበጣረሩ ሕዝቦችም ነበሩ፡፡'),
('23:47', 87, '«ብጤያችንም ለኾኑ ሁለት ሰዎች ሕዝቦቻቸው ለእኛ ተገዢዎች ኾነው ሳሉ እናምናለን» አሉ፡፡'),
('23:48', 87, 'አስተባበሉዋቸውም፡፡ ከጠፊዎቹም ኾኑ፡፡'),
('23:49', 87, 'ሙሳንም (ነገዶቹ) ይምመሩ ዘንድ መጽሐፍን በእርግጥ ሰጠነው፡፡'),
('23:50', 87, 'የመርየምን ልጅና እናቱንም ተዓምር አደረግናቸው፡፡ የመደላደልና የምንጭ ባለቤት ወደ ኾነች ከፍተኛ ስፍራም አስጠጋናቸው፡፡'),
('23:51', 87, 'እናንተ መልክተኞች ሆይ! ከተፈቀዱት ምግቦች ብሉ፡፡ በጎ ሥራንም ሥሩ፡፡ እኔ የምተሠሩትን ሁሉ ዐዋቂ ነኝ፡፡'),
('23:52', 87, 'ይህችም (በአንድ አምላክ የማመን ሕግጋት) አንድ መንገድ ስትኾን ሃይማኖታችሁ ናት፡፡ እኔም ጌታችሁ ነኝና ፍሩኝ፡፡'),
('23:53', 87, '(ከዚያ ተከታዮቻቸው) የሃይማኖት ነገራቸውንም በመካከላቸው ክፍልፍሎች አድርገው ቆራረጡ፡፡ ሕዝብ ሁሉ እነርሱ ዘንድ ባለው ሃይማኖት ተደሳቾች ናቸው፡፡'),
('23:54', 87, 'እስከ ጊዜያቸውም ድረስ በጥምመታቸው ውስጥ ተዋቸው፡፡'),
('23:55', 87, 'ከገንዘብና ከልጆች በእርሱ የምንጨምርላቸውን ያስባሉን'),
('23:56', 87, 'በበጎ ነገሮች የምንቻኮልላቸው መኾንን (ያስባሉን) አይደለም፤ (ለማዘንጋት መኾኑን) አያውቁም፡፡'),
('23:57', 87, 'እነዚያ እነርሱ ጌታቸውን ከመፍራት የተነሳ ተጨናቂዎች የኾኑት፡፡'),
('23:58', 87, 'እነዚያም እነርሱ በጌታቸው ተዓምራቶች ከሚያምኑት፡፡'),
('23:59', 87, 'እነዚያም እነርሱ በጌታቸው (ጣዖትን) የማያጋሩት፡፡'),
('23:60', 87, 'እነዚያም የሚሰጡትን ነገር እነርሱ ወደ ጌታቸው ተመላሾች መኾናቸውን ልቦቻቸው የሚፈሩ ኾነው የሚሰጡት፡፡'),
('23:61', 87, 'እነዚያ በመልካም ሥራዎች ይጣደፋሉ፡፡ እነሱም ለርሷ ቀዳሚዎች ናቸው፡፡'),
('23:62', 87, 'ማንኛይቱንም ነፍስ ችሎታዋን እንጂ አናስገድዳትም፡፡ እኛም ዘንድ በእውነት የሚናገር መጽሐፍ አልለ፡፡ እነርሱም አይበደሉም፡፡'),
('23:63', 87, 'በእውነቱ (ከሓዲዎች) ልቦቻቸው ከዚያ (መጽሐፍ) በዝንጋቴ ውስጥ ናቸው፡፡ ለእነሱም ከዚህ ሌላ እነሱ ለርሷ ሠሪዎችዋ የኾኑ (መጥፎ) ሥራዎች አሏቸው፡፡'),
('23:64', 87, 'ቅምጥሎቻቸውንም በቅጣት በያዝናቸው ጊዜ ወዲያውኑ እነርሱ ይወተውታሉ፡፡'),
('23:65', 87, 'ዛሬ አትወትውቱ፤ እናንተ ከእኛ ዘንድ አትረዱም፡፡'),
('23:66', 87, 'አንቀጾቹ በእናንተ ላይ በእርግጥ ይነበቡላችሁ ነበር፡፡ በተረከዞቻችሁም ላይ ወደ ኋላችሁ ትመለሱ ነበራችሁ፡፡'),
('23:67', 87, 'በእርሱ (በክልሉ ቤት) ኩሩዎች ሌሊት ተጫዋቾች (ቁርኣንንም) የምትተው ኾናችሁ (ትመለሱ ነበራችሁ ይባላሉ)፡፡'),
('23:68', 87, '(የቁርኣንን) ንግግሩንም አያስተነትኑምን ወይስ ለመጀመሪያዎቹ አባቶቻቸው ያልመጣ ነገር መጣባቸውን'),
('23:69', 87, 'ወይስ መልክተኛቸውን አላወቁምን ስለዚህ እነርሱ ለእርሱ ከሓዲዎች ናቸውን'),
('23:70', 87, 'ወይስ በእርሱ ዕብደት አለበት ይላሉን አይደለም፡፡ እውነትን ይዞ መጣላቸው፡፡ አብዛኞቻቸውም እውነትን ጠይዎች ናቸው፡፡'),
('23:71', 87, 'አላህም ዝንባሌዎቻቸውን በተከተለ ኖሮ ሰማያትና ምድር በውስጣቸውም ያለው ሁሉ በእርግጥ በተበላሸ ነበር፡፡ ይልቁንም ክብራቸው ያለበትን ቁርኣን አመጣንላቸው፡፡ እነርሱም ከክብራቸው ዘንጊዎች ናቸው፡፡'),
('23:72', 87, 'ወይስ ግብርን ትጠይቃቸዋለህን የጌታህም ችሮታ በላጭ ነው፡፡ እርሱም ከሰጪዎች ሁሉ በላጭ ነው፡፡'),
('23:73', 87, 'አንተም ወደ ቀጥተኛው መንገድ በእርግጥ ትጠራቸዋለህ፡፡'),
('23:74', 87, 'እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ከትክክለኛው መንገድ ተዘንባዮች ናቸው፡፡'),
('23:75', 87, 'ባዘንንላቸውና ከጉዳትም በእነርሱ ያለውን ባነሳንላቸው ኖሮ በጥመታቸው ውስጥ የሚዋልሉ ኾነው ይዘወትሩ ነበር፡፡'),
('23:76', 87, 'በእርግጥም በቅጣት ያዝናቸው፡፡ ታዲያ ለጌታቸው አልተናነሱም፡፡ አይዋደቁምም፡፡'),
('23:77', 87, 'በእነሱም ላይ የብርቱ ቅጣት ባለቤት የኾነ ደጃፍን በከፈትንባቸው ጊዜ እነርሱ ያን ጊዜ በእርሱ ተስፋ ቆራጮች ናቸው፡፡'),
('23:78', 87, 'እርሱም ያ መስሚያዎችንና ማያዎችን ልቦችንም ለእናንተ የፈጠረላችሁ ነው፡፡ ጥቂትን እንጅ አታመሰግኑም፡፡'),
('23:79', 87, 'እርሱም ያ በምድር ውስጥ የበተናችሁ ነው፡፡ ወደርሱም ትሰበሰባላችሁ፡፡'),
('23:80', 87, 'እርሱም ያ ሕያው የሚያደርግ የሚገድልም ነው፡፡ የሌሊትና የቀን መተካካትም የእርሱ ነው፡፡ አታውቁምን'),
('23:81', 87, 'ይልቁንም (የመካ ከሓዲዎች) የፊተኞቹ ሕዝቦች እንዳሉት ብጤ አሉ፡፡'),
('23:82', 87, '«በሞትንና ዐፈርና አጥንቶች በኾን ጊዜ እኛ ተቀስቃሾች ነን» አሉ፡፡'),
('23:83', 87, '«ይህንን እኛም ከእኛ በፊትም የነበሩት አባቶቻችን በእርግጥ ተቀጥረናል፡፡ ይህ የመጀመሪያዎቹ ሰዎች ተረቶች እንጂ ሌላ አይደለም» (አሉ)፡፡'),
('23:84', 87, '«ምድርና በውስጥዋ ያለው ሁሉ የማን ነው የምታውቁ ብትኾኑ (ንገሩኝ)» በላቸው፡፡'),
('23:85', 87, '«በእርግጥ የአላህ ነው» ይሉሃል፡፡ «ታዲያ አትገሰጹምን» በላቸው፡፡'),
('23:86', 87, '«የሰባቱ ሰማያት ጌታና የታላቁ ዐርሽ ጌታ ማን ነው» በላቸው፡፡'),
('23:87', 87, '«በእርግጥ አላህ ነው» ይሉሃል፡፡ «እንግዲያ አትፈሩትምን» በላቸው፡፡'),
('23:88', 87, '«የነገሩ ሁሉ ግዛት በእጁ የኾነ እርሱ የሚጠብቅ በእርሱ ላይ የማይጠበቅ ማን ነው የምታውቁ እንደኾናችሁ (መልሱልኝ)» በላቸው፡፡'),
('23:89', 87, '«በእርግጥ አላህ ነው» ይሉሃል፡፡ «ታዲያ እንዴት ትታለላላችሁ» በላቸው፡፡'),
('23:90', 87, 'ይልቁንም እውነትን አመጣንላቸው፡፡ እነርሱም (በመካዳቸው) ውሸታሞች ናቸው፡፡'),
('23:91', 87, 'አላህ ምንም ልጅን አልያዘም (አልወለደም)፡፡ ከእርሱም ጋር አንድም አምላክ የለም፡፡ ያን ጊዜ (ሌላ አምላክ በነበረ) አምላክ ሁሉ በፈጠረው ነገር በተለየ ነበር፡፡ ከፊላቸውም በከፊሉ ለይ በላቀ ነበር፡፡ አላህ ከሚመጥኑት ሁሉ ጠራ፡፡'),
('23:92', 87, 'ሩቁንና ቅርቡንም ሁሉ ዐዋቂ ነው፡፡ (በእርሱ) ከሚያጋሩትም ሁሉ ከፍ አለ፡፡'),
('23:93', 87, '(ሙሐመድ ሆይ!) በል «ጌታዬ ሆይ! የሚያስፈራሩበትን (ቅጣት) ብታሳየኝ፡፡'),
('23:94', 87, '«ጌታዬ ሆይ! በበደለኞች ሕዝቦች ውስጥ አታድርገኝ፡፡»'),
('23:95', 87, 'እኛም የምናስፈራራቸውን ነገር ልናሳይህ በእርግጥ ቻዮች ነን፡፡'),
('23:96', 87, 'በዚያች እርስዋ መልካም በኾነችው (ጠባይ) መጥፎይቱን ነገር ገፍትር፡፡ እኛ የሚሉትን ሁሉ ዐዋቂዎች ነን፡፡'),
('23:97', 87, 'በልም «ጌታዬ ሆ! ከሰይጣናት ጉትተጎታዎች በአንተ እጠበቃለሁ፡፡'),
('23:98', 87, '«ባንተም ጌታዬ ሆይ! (በነገሮቼ) ወደእኔ ከመጣዳቸው እጠበቃለሁ፡፡»'),
('23:99', 87, 'አንዳቸውንም ሞት በመጣበት ጊዜ እንዲህ ይላል «ጌታዬ ሆይ! (ወደ ምድረ ዓለም) መልሱኝ፡፡'),
('23:100', 87, '«በተውኩት ነገር በጎን ሥራ ልሠራ እከጅላለሁና፡፡» (ይህን ከማለት) ይከልከል፡፡ እርስዋ እርሱ ተናጋሪዋ የኾነች ከንቱ ቃል ናት፡፡ ከስተፊታቸውም እስከሚቀሰቀሱበት ቀን ድረስ ግርዶ አልለ፡፡'),
('23:101', 87, 'በቀንዱም በተነፋ ጊዜ በዚያ ቀን በመካከላቸው ዝምድና የለም፡፡ አይጠያየቁምም፡፡'),
('23:102', 87, 'ሚዛኖቹም የከበዱለት ሰው እነዚያ እነርሱ ፍላጎታቸውን ያገኙ ናቸው፡፡'),
('23:103', 87, 'ሚዛኖቹም የቀለሉበት ሰው እነዚያ እነርሱ ነፍሶቻቸውን ያከሰሩ ናቸው፡፡ በገሀነም ውስጥ ዘመውታሪዎች ናቸው፡፡'),
('23:104', 87, 'ፊቶቻቸውን እሳት ትገርፉቸዋለች፡፡ እነርሱም በእርሷ ውስጥ ከንፈሮቻቸው የተኮማተሩ ናቸው፡፡'),
('23:105', 87, '«አንቀጾቼ በእናንተ ላይ የሚነበቡላችሁና በእነርሱ የምታስተባብሉ አልነበራችሁምን» (ይባላሉ)፡፡'),
('23:106', 87, 'ይላሉ «ጌታችን ሆይ! በእኛ ላይ መናጢነታችን አሸነፈችን፡፡ ጠማማዎችም ሕዝቦች ነበርን፡፡'),
('23:107', 87, '«ጌታችን ሆይ! ከእርሷ አውጣን፡፡ (ወደ ክህደት) ብንመለስም እኛ በደዮች ነን፡፡»'),
('23:108', 87, '(አላህም) «ወራዶች ኾናችሁ በውስጥዋ እርጉ፡፡ አታናግሩኝም» ይላቸዋል፡፡'),
('23:109', 87, 'እነሆ ከባሮቼ «ጌታችን ሆይ! አምነናልና ማረን፡፡ እዘንልንም አንተም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነህ» የሚሉ ክፍሎች ነበሩ፡፡'),
('23:110', 87, 'እኔንም ማውሳትን እስካስረሷችሁ ድረስም ማላገጫ አድርጋችሁ ያዛችኋቸው፡፡ በእነርሱም የምትስቁ ነበራችሁ፡፡'),
('23:111', 87, 'እኔ ዛሬ በትዕግስታቸው ምክንያት እነሱ ፍላጎታቸውን የሚያገኙት እነርሱ ብቻ በመኾን መነዳኋቸው፤ (ይላቸዋል)፡፡'),
('23:112', 87, '«በምድር ውስጥ ከዓመታት ቁጥር ስንትን ቆያችሁ» ይላቸዋል፡፡'),
('23:113', 87, '«አንድ ቀንን ወይም ከፊል ቀንን ቆየን፡፡ ቆጣሪዎቹንም ጠይቅ» ይላሉ፡፡'),
('23:114', 87, '«እናንተ (የቆያችሁትን መጠን) የምታውቁ ብትኾኑ ኖሮ (በእሳት ውስጥ በምትቆዩት አንፃር) ጥቂትን ጊዜ እንጂ አልቆያችሁም» ይላቸዋል፡፡'),
('23:115', 87, '«የፈጠርናችሁ ለከንቱ መኾኑን እናንተም ወደኛ የማትመለሱ መኾናችሁን ጠረጠራችሁን» (ለከንቱ የፈጠርናችሁ መሰላችሁን)'),
('23:116', 87, 'የእውነቱም ንጉስ አላህ ከፍተኛነት ተገባው፡፡ ከእርሱ ሌላ አምላክ የለም፡፡ የሚያምረው ዐርሽ ጌታ ነው፡፡'),
('23:117', 87, 'ከአላህም ጋር ሌላን አምላክ ለእርሱ በእርሱ ማስረጃ የሌለውን የሚገዛ ሰው ምርመራው እጌታው ዘንድ ብቻ ነው፡፡ እነሆ ከሓዲዎች አይድኑም፡፡'),
('23:118', 87, 'በልም «ጌታዬ ሆይ ማር፤ እዘንም፡፡ አንተም ከአዛኞች ሁሉ በላጭ ነህ፡፡»'),
('24:1', 87, '(ይህች) ያወረድናትና የደነገግናት ምዕራፍ ናት፡፡ በእርሷም ውስጥ ትገሰፁ ዘንድ ግልጾችን አንቀጾች አውርደናል፡፡'),
('24:2', 87, 'ዝሙተኛይቱና ዝሙተኛው ከሁለቱ እያንዳንዳቸውን (ያላገቡ እንደኾኑ) መቶ ግርፋትን ግረፉዋቸው፤ በእነርሱም በአላህ ፍርድ ርኅራኄ አትያዛችሁ፡፡ በአላህና በመጨረሻው ቀን የምታምኑ እንደኾናችሁ (አትራሩ)፡፡ ቅጣታቸውንም ከምእምናን ጭፍሮች ይገኙበት፡፡'),
('24:3', 87, 'ዝሙተኛው ዝሙተኛይቱን ወይም አጋሪይቱን እንጂ አያገባም፡፡ ዝሙተኛይቱንም ዝሙተኛ ወይም አጋሪ እንጂ አያገባትም፡፡ ይህም በምእምናን ላይ ተከልክሏል፡፡'),
('24:4', 87, 'እነዚያም ጥብቆችን ሴቶች (በዝሙት) የሚሰድቡ ከዚያም አራትን ምስክሮች ያላመጡ ሰማኒያን ግርፋት ግረፏቸው፡፡ ከእነርሱም ምስክርነትን ሁልጊዜ አትቀበሉ እነዚያም እነሱ አመጸኞች ናቸው፡፡'),
('24:5', 87, 'እነዚያ ከዚህ በኋላ የተጸጸቱና ሥራቸውን ያሳመሩ ሲቀሩ፡፡ አላህ በጣም መሓሪ አዛኝ ነውና፡፡'),
('24:6', 87, 'እነዚያም ሚስቶቻቸውን (በዝሙት) የሚሰድቡ ለእነሱም ከነፍሶቻቸው በስተቀር ምስክሮች የሌሏቸው የኾኑ የአንዳቸው ምስክርነት እርሱ ከውነተኞች ለመኾኑ በአላህ ስም አራት ጊዜ ምሎ መመስከር ነው፡፡'),
('24:7', 87, 'አምስተኛይቱም ከውሸታሞች ቢኾን በእርሱ ላይ የአላህ እርግማን ይኑርበት (ብሎ መመስከር) ነው፡፡'),
('24:8', 87, 'እርሱም ከውሸታሞች ነው ብላ አራት ጊዜ መመስከሮችን በአላህ ስም መመስከርዋ ከእርስዋ ላይ ቅጣትን ይገፈትርላታል፡፡'),
('24:9', 87, 'አምስተኛይቱም እርሱ ከውነተኞች ቢኾን በእርስዋ ላይ የአላህ ቁጣ ይኑርባት (ብላ መመስከርዋ) ነው፡፡'),
('24:10', 87, 'በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ አላህም ጸጸትን ተቀባይ ጥበበኛ ባልኾነ ኖሮ (ውሸታሙን ይገልጸው ነበር)፡፡'),
('24:11', 87, 'እነዚያ መጥፎን ውሸት ያመጡ ከናንተው የኾኑ ጭፍሮች ናቸው፡፡ ለእናንተ ክፉ ነገር ነው'),
('24:12', 87, '(ውሸቱን) በሰማችሁት ጊዜ ምእምናንና ምእምናት በጎሶቻቸው ለምን ደግን ነገር አልጠረጠሩም ለምንስ ይህ ግልጽ ውሸት ነው አላሉም'),
('24:13', 87, 'በእርሱ ላይ ለምን አራትን ምስክሮች አላመጡም ምስክሮቹንም ካላመጡ እነዚያ አላህ ዘንድ ውሸታሞቹ እነሱ ናቸው፡፡'),
('24:14', 87, 'በቅርቢቱም በመጨረሻይቱም ዓለም በእናንተ ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ በውስጡ በገባችሁበት ወሬ ምክንያት ታላቅ ቅጣት በእርግጥ በደረሰባችሁ ነበር፡፡'),
('24:15', 87, 'በምላሶቻችሁ በምትቅበባሉት ጊዜ ለእናንተም በእርሱ ዕውቀት በሌላችሁ ነገር በአፎቻችሁ በተናገራችሁና እርሱ አላህ ዘንድ ከባድ ኀጢአት ኾኖ ሳለ ቀላል አድርጋችሁ ባሰባችሁት ጊዜ (ከባድ ቅጣት በነካችሁ ነበር)፡፡'),
('24:16', 87, 'በሰማችሁትም ጊዜ በዚህ ልንናገር ለእኛ አይገባንም፡፡ ጥራት ይገባህ፡፡ ይህ ከባድ ቅጥፈት ነው፤ አትሉም ነበርን'),
('24:17', 87, 'ምእመናን እንደኾናችሁ ወደ ብጤው በፍፁም እንዳትመለሱ አላህ ይገስጻችኋል፡፡'),
('24:18', 87, 'ለእናንተም አላህ አንቀጾችን ይገልጽላችኋል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('24:19', 87, 'እነዚያ በእነዚያ ባመኑት ሰዎች ውስጥ መጥፎ ወሬ እንድትስፋፋ የሚወዱ ለእነሱ በቅርቢቱም በመጨረሻይቱም ዓለም አሳማሚ ቅጣት አላቸው፡፡ አላህም ያውቃል እናንተ ግን አታውቁም፡፡'),
('24:20', 87, 'በእናንተም ላይ የአላህ ችሮታውና እዝነቱ ባልነበረ አላህም ሩኅሩኅና አዛኝ ባልኾነ ኖሮ (ቶሎ ባጠፋችሁ ነበር)፡፡'),
('24:21', 87, 'እናንተ ያመናችሁ ሆይ! የሰይጣንን እርምጃዎች አትከተሉ፡፡ የሰይጣንንም እርምጃዎች የሚከተል ሰው (ኀጢአትን ተሸከመ)፡፡ እርሱ በመጥፎና በሚጠላ ነገር ያዛልና፡፡ በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ ከናንተ አንድም ፈጽሞ ባልጠራ ነበር፡፡ ግን አላህ የሚሻውን ሰው ያጠራል፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('24:22', 87, 'ከእናንተም የችሮታና የክብረት ባለቤቶች የኾኑት ለቅርብ ዘመዶችና ለድኾች በአላህም መንገድ ለተሰደዱ ሰዎች ላይሰጡ አይማሉ፡፡ ይቅርታም ያድርጉ፡፡ (ጥፋተኞቹን) ይለፉም፡፡ አላህ ለእናንተ ሊምር አትወዱምን አላህም መሓሪ አዛኝ ነው፡፡'),
('24:23', 87, 'እነዚያ ጥብቆቹን ከዝሙት ዘንጊዎቹን ምእምናት የሚሰድቡ፤ በቅርቢቱም በመጨረሻይቱም'),
('24:24', 87, 'በእነሱ ላይ ምላሶቻቸው፣ እጆቻቸውና እግሮቻቸውም ይሠሩት በነበሩት ነገር በሚመሰክሩባቸው ቀን (ከባድ ቅጣት አላቸው)፡፡'),
('24:25', 87, 'በዚያ ቀን አላህ እውነተኛ ዋጋቸውን ይሞላላቸዋል፡፡ አላህም እርሱ መኖሩ የተረጋገጠ (ሁሉን ነገር) ገላጭ መኾኑን ያውቃሉ፡፡'),
('24:26', 87, 'መጥፎዎቹ ሴቶች ለመጥፎዎች ወንዶች መጥፎዎቹ ወንዶችም ለመጥፎዎቹ ሴቶች የተገቡ ናቸው፡፡ ጥሩዎቹ ሴቶችም ለጥሩዎቹ ወንዶች ጥሩዎቹ ወንዶችም ለጥሩዎቹ ሴቶች የሚገቡ ናቸው፡፡ እነዚያ (መጥፎዎቹ) ከሚሉት ነገር ንጹሕ የተደረጉ ናቸው፡፡ ለእነርሱ ምህረትና መልካም ሲሳይ አላቸው፡፡'),
('24:27', 87, 'እናንተ ያመናችሁ ሆይ! እስከምታስፈቅዱና በባለቤቶቿ ላይ ሰላምታን እስከምታቀርቡ ድረስ ከቤቶቻችሁ ሌላ የኾኑን ቤቶች አትግቡ፡፡ ይህ ለእናንተ መልካም ነው፡፡ እናንተ ትገነዘቡ ዘንድ (በዚህ ታዘዛችሁ)፡፡'),
('24:28', 87, 'በውስጧም አንድንም ሰው ባታገኙ ለእናንተ እስከሚፈቀድላችሁ ድረስ አትግቧት፡፡ ለእናንተ ተመለሱ ብትባሉም ተመለሱ፡፡ እርሱ ለእናንተ የተሻለ ነው፡፡ አላህም የምትሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('24:29', 87, 'መኖሪያ ያልኾኑን ቤቶች በውስጣቸው ለእናንተ ጥቅም ያላችሁን (ሳታስፈቅዱ) ብትገቡ በእናንተ ላይ ኀጢአት የለባችሁም፡፡ አላህም የምትገልጹትንና የምትደብቁትን ሁሉ ያውቃል፡፡'),
('24:30', 87, 'ለምእመናን ንገራቸው፡- ዓይኖቻቸውን (ያልተፈቀደን ከማየት) ይከልክሉ፤ ብልቶቻቸውንም ይጠብቁ፤ ይህ ለነሱ የተሻለ ነው፤ አላህ በሚሠሩት ሁሉ ውስጥ ዐዋቂ ነው፡፡'),
('24:31', 87, 'ለምእምናትም ንገራቸው፡- ዓይኖቻቸውን ይከልክሉ፡፡ ብልቶቻቸውንም ይጠብቁ፡፡ ጌጣቸውንም ከእርሷ ግልጽ ከኾነው በስተቀር አይግለጡ፡፡ ጉፍታዎቻቸውንም በአንገትጌዎቻቸው ላይ ያጣፉ፡፡ (የውስጥ) ጌጣቸውንም ለባሎቻቸው ወይም ለአባቶቻቸው ወይም ለባሎቻቸው አባቶች ወይም ለወንዶች ልጆቻቸው ወይም ለባሎቻቸው ወንዶች ልጆች ወይም ለወንድሞቻቸው ወይም ለወንድሞቻቸው ወንዶች ልጆች ወይም ለእህቶቻቸው ወንዶች ልጆች ወይም ለሴቶቻቸው ወይም እጆቻቸው ለያዙት (ባሪያ) ወይም ከወንዶች ለሴት ጉዳይ የሌላቸው ለኾኑ ተከታዮች ወይም ለነዚያ በሴቶች ሐፍረተ ገላ ላይ ላላወቁ ሕፃኖች ካልኾነ በስተቀር አይግለጹ፡፡ ከጌጣቸውም የሚሸፍኑት ይታወቅ ዘንድ በእግሮቻቸው አይምቱ፡፡ ምእመናኖች ሆይ! ትድኑ ዘንድ ሁላችሁም ወደ አላህ (በመመለስ) ተጸጸቱ፡፡'),
('24:32', 87, 'ከናንተም ትዳር የሌላቸውን አጋቡ፡፡ ከወንዶች ባሮቻችሁና ከሴቶች ባሮቻችሁም ለጋብቻ ብቁ የኾኑትን (አጋቡ)፡፡ ድኾች ቢኾኑ አላህ ከችሮታው ያከብራቸዋል፡፡ አላህም ስጦታው ሰፊ ዐዋቂ ነው፡፡'),
('24:33', 87, 'እነዚያም የማግቢያን ጣጣ የማያገኙ አላህ ከችሮታው እስከሚያከብራቸው ድረስ ይጠበቁ፡፡ እነዚያንም እጆቻችሁ ከጨበጧቸው አገልጋዮች (ገንዘብ ሰጥተው ነጻ ለመውጣት) መጻጻፍን የሚፈልጉትን ከእነሱ መልካምን ነገር ብታውቁ ተጻጻፉዋቸው፡፡ ከአላህም ገንዘብ ከዚያ ከሰጣችሁ ስጧቸው፡፡ ሴቶች ባሮቻችሁንም መጥጠበቅን ቢፈልጉ የቅርቢቱን ሕይወት ጥቅም ለመፈለግ ብላችሁ በዝሙት ላይ አታስገድዱዋቸው፡፡ የሚያስገድዳቸውም ሰው አላህ ከመገደዳቸው በኋላ (ለተገደዱት) መሓሪ አዛኝ ነው፡፡'),
('24:34', 87, 'ወደእናንተም አብራሪ የኾኑን አንቀጾች ከእነዚያ ከበፊታችሁ ካለፉትም (ምሳሌዎች ዓይነት) ምሳሌን ለጥንቁቆቹ መገሰጫንም በእርግጥ አወረድን፡፡'),
('24:35', 87, 'አላህ የሰማያትና የምድር አብሪ ነው፡፡ የብርሃኑ ምሳሌ በውስጧ መብራት እንዳለባት (ዝግ) መስኮት፣ መብራቱ በብርጭቆ ውስጥ የኾነ፣ ብርጭቆይቱ ፍፁም ሉላዊ ኮከብ የምትመሰል፣ ምሥራቃዊው ምዕራባዊም ካልኾነች ከተባረከች የወይራ ዛፍ ዘይቷ እሳት ባይነካውም እንኳ ሊያበራ የሚቀርብ ከኾነች (ዘይት) የሚቃጠል እንደ ሆነ (መብራት) ነው፡፡ (ይህ) በብርሃን ላይ የኾነ ብርሃን ነው፡፡ አላህ ወደ ብርሃኑ የሚሻውን ሰው ይመራል፡፡ አላህም ለሰዎች ምሳሌዎችን ያቀርባል፡፡ አላህም በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('24:36', 87, 'አላህ እንድትከበርና ስሙ በውስጧ እንዲወሳ ባዘዘው ቤቶች ውስጥ (አወድሱት)፡፡ በውስጧ በጧትና በማታ ለእርሱ ያጠራሉ፡፡'),
('24:37', 87, 'አላህን ከማውሳትና ሶላትን ከመስገድ ዘካንም ከመስጠት ንግድም ሽያጭም የማያታልላቸው ልቦችና ዓይኖች በእርሱ የሚገላበጡበትን ቀን የሚፈሩ የኾኑ ሰዎች (ያጠሩታል)፡፡'),
('24:38', 87, 'አላህ የሠሩትን ሥራ መልካሙን ሊመነዳቸው ከችሮታውም ሊጨመርላቸው (ያጠሩታል)፡፡ አላህም ለሚሻው ሰው ያለ ግምት ይሰጣል፡፡'),
('24:39', 87, 'እነዚያም የካዱት ሰዎች ሥራዎቻቸው (መልካሞቹ) በበረሃ ሜዳ እንዳለ ሲሪብዱ የጠማው ሰው ውሃ ነው ብሎ እንደሚያስበው በመጣውም ጊዜ ምንም ነገር ኾኖ እንደማያገኘው ነው፡፡ (ከሓዲው) አላህንም እሠራው ዘንድ ያገኘዋል፡፡ ምርመራውንም (ቅጣቱን) ይሞላለታል፡፡ አላህም ምርመራው ፈጣን ነው፡፡'),
('24:40', 87, 'ወይም (መጥፎ ሥራዎቻቸውን) ከበላዩ ደመና ያለበት ማዕበል በሚሸፈነው ጥልቅ ባህር ውስጥ እንዳሉ ጨለማዎች ነው፡፡ (እነዚያ) ከፊላቸው ከከፊሉ በላይ ድርብርብ የኾኑ ጨለማዎች ናቸው፡፡ (በዚህች) የተሞከረ (ሰው) እጁን ባወጣ ጊዜ ሊያያት አይቀርብም፡፡ አላህም ለእርሱ ብርሃንን ያላደረገለት ሰው ለእርሱ ምንም ብርሃን የለውም፡፡'),
('24:41', 87, 'አላህ በሰማያትና በምድር ያለ ሁሉ በራሪዎችም ክንፎቻቸውን (በአየር ላይ) ያንሳፈፉ ኾነው ለእርሱ የሚያጠሩ (የሚያወድሱ) መኾናቸውን አላወቅህምን ሁሉም ስግደቱንና ማጥራቱን በእርግጥ ዐወቀ፡፡ አላህም የሚሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('24:42', 87, 'የሰማያትና የምድርም ግዛት የአላህ ነው፡፡ መመለሻም ወደ አላህ ነው፡፡'),
('24:43', 87, 'አላህ ደመናን የሚነዳ መኾኑን አላየህምን ከዚያም ከፊሉን ከከፊሉ ያገናኛል፡፡ ከዚያም የተደራረበ ያደርገዋል፡፡ ዝናቡንም ከመካከሉ የሚወጣ ኾኖ ታየዋለህ፡፡ ከሰማይም (ከደመና) በውስጧ ካሉት ጋራዎች በረዶን ያወርዳል፡፡ በእርሱም የሚሻውን ሰው (በጉዳት) ይነካል፡፡ ከሚሻውም ሰው ላይ ይመልሰዋል፡፡ የብልጭታው ብርሃን ዓይኖችን ሊወስድ ይቀርባል፡፡'),
('24:44', 87, 'አላህ ሌሊትንና ቀንን ያገላብጣል፡፡ በዚህም ለባለ ውስጥ ዓይኖች በእርግጥ ማስረጃ አልለበት፡፡'),
('24:45', 87, 'አላህም ተንቀሳቃሽን ሁሉ ከውሃ ፈጠረ፡፡ ከእነሱም በሆዱ ላይ የሚኼድ አልለ፡፡ ከእነሱም በሁለት እግሮች ላይ የሚኼድ አልለ፡፡ አላህ የሚሻውን ሁሉ ይፈጥራል፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('24:46', 87, 'አብራሪን አንቀጾች በእርግጥ አወረድን፡፡ አላህም የሚሻውን ሰው ወደ ቀጥተኛ መንገድ ይመራዋል፡፡'),
('24:47', 87, 'በአላህና በመልክተኛውም አምነናል ታዘናልም ይላሉ፡፡ ከዚያም ከዚህ በኋላ ከእነሱ ከፊሉ ይሸሻል፡፡ እነዚያም ምእምናን አይደሉም፤'),
('24:48', 87, 'ወደ አላህና ወደ መልክተኛውም በመካከላቸው ሊፈርድ በተጠሩ ጊዜ ከእነሱ ከፊሉ ወዲያውኑ ይሸሻሉ፡፡'),
('24:49', 87, 'እውነቱም (ሐቁ) ለእነሱ ቢኾን ወደርሱ ታዛዦች ኾነው ይመጣሉ፡፡'),
('24:50', 87, 'በልቦቻቸው ውስጥ በሺታ አለን ወይስ (በነቢይነቱ) ተጠራጠሩን ወይስ አላህና መልክተኛው በእነሱ ላይ የሚበድሉ መኾንን ይፈራሉን ይልቁንም፤ እነዚያ እነሱ በዳዮቹ ናቸው፡፡'),
('24:51', 87, 'የምእምናን ቃል የነበረው ወደ አላህና ወደ መልክተኛው በመካከላቸው ሊፈርድ በተጠሩ ጊዜ ሰማን፤ ታዘዝንም ማለት ብቻ ነው፡፡ እነዚህም እነሱ የፈለጉትን የሚያገኙ ናቸው፡፡'),
('24:52', 87, 'አላህንና መልክተኛውን የሚታዘዝም ሰው፣ አላህንም የሚፈራና የሚጠነቀቀው ሰው፤ እነዚያ እነርሱ ፍለጎታቸውን የሚያገኙ ናቸው፡፡'),
('24:53', 87, '(ለዘመቻ) ብታዛቸውም በእርግጥ ሊወጡ የጠነከሩ መሓሎቻቸውን በአላህ ስም ይምላሉ፡፡ «አትማሉ፤ የታወቀች (የንፍቅና) መታዘዝ ናትና፡፡ አላህ በምትሠሩት ነገር ሁሉ ውስጥ ዐዋቂ'),
('24:54', 87, '«አላህን ተገዙ፡፡ መልክተኛውንም ታዘዙ፤ ብትሸሹም (አትጎዱትም)፡፡ በእርሱ ላይ ያለበት የተገደደውን ማድረስ ብቻ ነው፡፡ በእናንተም ላይ ያለባችሁ የተገደዳችሁት (መታዘዝ) ብቻ'),
('24:55', 87, 'አላህ እነዚያን ከእናንተ ያመኑትንና መልካም ሥራዎችን የሠሩትን እነዚያን ከእነሱ በፊት የነበሩትን እንደተካ በምድር ለይ በእርግጥ ሊተካቸው፣ ለእነሱም ያንን የወደደላቸውን ሃይማኖታቸውን ሊያደላድልላቸው፣ ከፍርሃታቸውም በኋላ ጸጥታን ሊለውጥላቸው ተስፋን ቃል ሰጥቷቸዋል፡፡ በእኔ ምንንም የማያጋሩ ኾነው ይግገዙኛል፡፡ ከዚያም በኋላ የካደ ሰው እነዚያ እነርሱ አመጸኞች ናቸው፡፡'),
('24:56', 87, 'ሶላትንም አስተካክላችሁ ስገዱ፡፡ ምጽዋትንም ስጡ፡፡ መልክተኛውንም ታዘዙ፡፡ ለእናንተ ሊታዘንላችሁ ይከጀላልና፡፡'),
('24:57', 87, 'እነዚያን የካዱትን በምድር ውስጥ የሚያቅቱ አድርገህ አታስብ፡፡ መኖሪያቸውም እሳት ናት፡፡ በእርግጥም የከፋች መመለሻ ናት፡፡'),
('24:58', 87, 'እናንተ ያመናችሁ ሆይ! እነዚያ እጆቻችሁ የጨበጧቸው (ባሮች) እነዚያም ከእናንተ ለአካላ መጠን ያልደረሱት ከጎህ ስግደት በፊት፣ በቀትርም ልብሶቻችሁን በምታወልቁ ጊዜ ከምሽት ስግደትም በኋላ ሦስት ጊዜያት (ለመግባት ሲፈልጉ) ያስፈቅዷችሁ፡፡ (እነዚህ) ለእናንተ የኾኑ ሦስት የሐፍረተ ገላ መገለጫ ጊዜያቶች ናቸውና፡፡ ከእነዚህ በኋላ በእናንተም በእነርሱም ላይ (ያለፈቃድ በመግባት) ኀጢአት የለም፡፡ በእናንተ ላይ (ለማገልገል) ዙዋሪዎች ናቸውና፡፡ ከፊላችሁ በከፊሉ ላይ ዙዋሪ ነው፡፡ እንደዚሁ አላህ ለእናንተ ሕግጋትን ይገልጽላችኋል፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('24:59', 87, 'ከእናንተም ሕፃናቶቹ አቅመ አዳምን በደረሱ ጊዜ እነዚያ ከእነሱ በፊት የነበሩት (ታላላቆቹ) እንዳስፈቀዱ ያስፈቅዱ፡፡ እንደዚሁ አላህ ለእናንተ አንቀጾቹን ያብራራል፤ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('24:60', 87, 'ከሴቶችም እነዚያ ጋብቻን የማይፈልጉት ተቀማጮች (ባልቴቶች)፤ በጌጥ የተገለፁ ሳይኾኑ የላይ ልብሶቻቸውን ቢጥሉ በእነሱ ላይ ኀጢአት የለባቸውም፡፡ ግን መጠበቃቸው ለእነርሱ የተሻለ ነው፡፡ አላህም ሰሚ ዐዋቂ ነው፡፡'),
('24:61', 87, '(ከሰዎች ጋር በመብላት) በዕውር ላይ ኀጢአት የለበትም፡፡ በአንካሳም ላይ ኀጢአት የለበትም፡፡ በበሽተኛም ላይ ኀጢአት የለበትም፡፡ በነፍሶቻችሁም ላይ ከቤቶቻችሁ ወይም ከአባቶቻችሁ ቤቶች ወይም ከእናቶቻችሁ ቤቶች ወይም ከወንድሞቻችሁ ቤቶች ወይም ከእኅቶቻችሁ ቤቶች ወይም ከአጎቶቻችሁ ቤቶች ወይም ከአክስቶቻችሁ ቤቶች ወይም ከየሹሞቻችሁ ቤቶች ወይም ከየሹሜዎቻችሁ ቤቶች ወይም መክፈቻዎቹን ከያዛችሁት ቤት ወይም ከወዳጃችሁ ቤት (ብትበሉ) ኀጢአት የለባችሁም፡፡ ተሰብስባችሁ ወይም ተለያይታችሁ ብትበሉ በእናንተ ላይ ኀጢአት የለባችሁም፡፡ ቤቶችንም በገባችሁ ጊዜ፤ ከአላህ ዘንድ የኾነችን የተባረከች መልካም ሰላምታ በነፍሶቻችሁ ላይ ሰላም በሉ፡፡ እንደዚሁ አላህ አንቀጾችን ለእናንተ ያብራራል፡፡ ልታውቁ ይከጀላልና፡፡'),
('24:62', 87, 'ምእመናን ማለት እነዚያ በአላህና በመልክተኛው ያመኑት፤ ከእርሱ ጋር በሚሰበሰብ ጉዳይ ላይ በኾኑ ጊዜ እስከሚያስፈቅዱ ድረስ የማይኼዱት ብቻ ናቸው፡፡ እነዚያ የሚያስፈቅዱህ እነርሱ እነዚያ በአላህና በመልክተኛው የሚያምኑት ናቸው፡፡ ለግል ጉዳያቸውም ፈቃድ በጠየቁህ ጊዜ ከእነሱ ለሻኸው ሰው ፍቀድለት፡፡ ለእነሱም አላህን ምሕረትን ለምንላቸው አላህ መሓሪ አዛኝ ነውና፡፡'),
('24:63', 87, 'በመካከላችሁ የመልክተኛውን ጥሪ ከፊላችሁ ከፊሉን እንደ መጥራት አታድርጉት፡፡ ከእናንተ ውስጥ እነዚያን እየተከለሉ በመስለክለክ የሚወጡትን አላህ በእርግጥ ያውቃቸዋል፡፡ እነዚያም ትዕዛዙን የሚጥሱ መከራ እንዳትደርስባቸው ወይም አሳማሚ ቅጣት እንዳያገኛቸው ይጠንቀቁ፡፡'),
('24:64', 87, 'ንቁ! በሰማያትና በምድር ያለው ሁሉ የአላህ ብቻ ነው፡፡ እናንተ በእርሱ ላይ ያላችሁበትን ኹኔታ በእርግጥ ያውቃል፡፡ ወደእርሱ የሚመለሱበትን ቀንም (ያውቃል)፡፡ የሠሩትንም ሁሉ ይነግራቸዋል፡፡ አላህም ነገሩን ሁሉ ዐዋቂ ነው፡፡'),
('25:1', 87, 'ያ ፉርቃንን በባሪያው ላይ ለዓለማት አስፈራሪ ይኾን ዘንድ ያወረደው (አምላክ) ክብርና ጥራት ተገባው፡፡'),
('25:2', 87, '(እርሱ) ያ የሰማያትና የምድር ንግሥና የእርሱ ብቻ የኾነ፣ ልጅንም ያልያዘ፣ በንግሥናውም'),
('25:3', 87, '(ከሓዲዎች) ከእርሱም ሌላ ምንንም የማይፈጥሩን፣ እነርሱም የሚፈጠሩን፣ ለነፍሶቻቸውም ጉዳትን ለመከላከል ጥቅምንም ለማምጣት የማይችሉን ሞትንና ሕይወትንም መቀስቀስንም የማይችሉን፣ አማልክት ያዙ፡፡'),
('25:4', 87, 'እነዚያም የካዱት ይህ (ቁርኣን ሙሐመድ) የቀጠፈው በእርሱም ላይ ሌሎች ሕዝቦች ያገዙት የኾነ ውሸት እንጂ ሌላ አይደለም አሉ፡፡ በእርግጥም በደልንና እብለትን ሠሩ፡፡'),
('25:5', 87, 'አሉም «የመጀመሪያዎቹ ሰዎች ተረቶች ናት፡፡ አስጻፋት፡፡ እርሷም በእርሱ ላይ ጧትና ማታ ትነበብለታለች፡፡»'),
('25:6', 87, '«ያ በሰማያትና በምድር ውስጥ ያለን ምስጢር የሚያውቀው አወረደው፡፡ እርሱ መሓሪ አዛኝ ነውና» በላቸው፡፡'),
('25:7', 87, 'ለዚህም መልክተኛ ምግብን የሚበላ፣ በገበያዎችም የሚኼድ ሲኾን ምን (መልክተኛነት) አለው ከርሱ ጋር አስፈራሪ ይኾን ዘንድ ወደርሱ መልአክ (ገሃድ) አይወረድም ኖሯልን አሉ፡፡'),
('25:8', 87, '«ወይም ወደእርሱ ድልብ አይጣልለትምን ወይም ከእርሷ የሚበላላት አትክልት ለእርሱ አትኖረውምን» (አሉ)፡፡ በዳዮቹም (ላመኑት) «የተደገመበትን ሰው እንጂ ሌላ አትከተሉም» አሉ፡፡'),
('25:9', 87, 'ላንተ ምሳሌዎችን እንዴት እንዳደረጉልህና እንደተሳሳቱ ተመልከት፡፡ (ወደ እውነት ለመድረስ) መንገድንም አይችሉም፡፡'),
('25:10', 87, 'ያ ቢሻ ከዚህ (ካሉት) የተሻለን ከሥሮቻቸው ወንዞች የሚፈሱባቸውን አትክልቶች ላንተ የሚያደርግልህ ሕንጻ ቤቶችንም ላንተ የሚያደርግልህ ጌታ ችሮታው በዛ፡፡'),
('25:11', 87, 'ይልቁንም በትንሣኤ አስተባበሉ፡፡ በትንሣኤ ላስተባበለም ሰው ሁሉ ነዳጅን እሳት አዘጋጅተናል፡፡'),
('25:12', 87, 'ከሩቅ ስፍራ ባየቻቸው ጊዜ ለእርሷ የቁጭት መገንፈልንና ማናፋትን ይሰማሉ፡፡'),
('25:13', 87, 'እጅ ከፍንጅ የታሠሩ ኾነውም ከእርሷ በጠባብ ስፍራ በተጣሉ ጊዜ በዚያ ስፍራ ጥፋትን ይጠራሉ፤ (ዋ ጥፋታችን ይላሉ)፡፡'),
('25:14', 87, '፡-ዛሬ አንድን ጥፋት ብቻ አትጥሩ ብዙንም ጥፋት ጥሩ (ይባላሉ)፡፡'),
('25:15', 87, '(እንዲህ) በላቸው «ይህ የተሻለ ነውን ወይስ ጥንቁቆቹ ተስፋ የተሰጧት የዘለዓለሟ ገነት» ለእነርሱ ምንዳና መመለሻ ኾነች፡፡'),
('25:16', 87, 'ለእነሱ በውስጧ ዘውታሪዎች ኾነው የሚፈልጉት ሁሉ አልላቸው፡፡ (ይህም) ተስፋ ከጌታህ ተለማኝ ተስፋ ነው፡፡'),
('25:17', 87, 'እነርሱንና ከአላህ ሌላ የሚግገዟቸውንም የሚሰበስብባቸውንና «እናንተ እነዚህን ባሮቼን አሳሳታችሁን ወይስ እነሱው መንገድን ሳቱ» የሚልበትን ቀን (አስታውስ)፡፡'),
('25:18', 87, '«ጥራት ይገባህ፤ ካንተ ሌላ ረዳቶችን ልንይዝ ለእኛ ተገቢያችን አልነበረም፡፡ ግን እነርሱንም አባቶቻቸውንም መገንዘብን እስከተዉ ድረስ አጣቀምካቸው፡፡ ጠፊ ሕዝቦችም ኾኑ» ይላሉ፡፡'),
('25:19', 87, 'በምትሉትም (አማልክቶቻችሁ) አስዋሹዋችሁ፡፡ ቅጣቴን መገፍተርንም መርዳትንም አትችሉም፡፡ ከእናንተም የሚበድለውን ታላቅን ቅጣት እናቀምሰዋለን፤ (ይባላሉ)፡፡'),
('25:20', 87, 'ከአንተ በፊትም ከመልክተኞች እነሱ በእርግጥ ምግብን የሚበሉ በገበያዎችም የሚኼዱ ኾነው በስተቀር አልላክንም፡፡ ከፊላችሁንም ለከፊሉ ፈተና አድርገናል፡፡ ትታገሳላችሁን ጌታህም ተመልካች ነው፡፡'),
('25:21', 87, 'እነዚያም መገናኘታችንን የማይፈሩት በእኛ ላይ ለምን መላእክት አልወረደም፡፡ ወይም ጌታችንን ለምን አናይም አሉ፡ በነፍሶቻቸው ውስጥ በእርግጥ ኮሩ፡፡ ታላቅንም አመጽ አመፁ፡፡'),
('25:22', 87, 'መላእክትን በሚያዩበት ቀን በዚያ ጊዜ ለአመጸኞች ምስራች የላቸውም፡፡ «የተከለከለ ክልክልም አድርገን» ይላሉ፡፡'),
('25:23', 87, 'ከሥራም ወደ ሠሩት እናስባለን፡፡ የተበተነ ትቢያም እናደርገዋለን፡፡'),
('25:24', 87, 'የገነት ሰዎች በዚያ ቀን በመርጊያ የተሻሉ በማረፊያም በጣም ያማሩ ናቸው፡፡'),
('25:25', 87, 'ሰማይም በደመና የምትቀደድበትንና መላእክትም መወረድን የሚወርድበትን ቀን (አስታውስ)፡፡'),
('25:26', 87, 'እውነተኛው ንግሥና በዚያ ቀን ለአልራሕማን ብቻ ነው፡፡ በከሓዲዎችም ላይ አስቸጋሪ ቀን ነው፡፡'),
('25:27', 87, 'በዳይም «ከመልክተኛው ጋር ቀጥተኛን መንገድ ይዤ በኾነ ዋ ምኞቴ!» እያለ (በጸጸት) ሁለት እጆቹን የሚነክስበትን ቀን (አስታውስ)፡፡'),
('25:28', 87, '«ዋ ጥፋቴ! እገሌን ወዳጅ ባልያዝኩ ኖሮ እመኛለሁ፡፡'),
('25:29', 87, '(የእምነት ቃልን) ከመጣልኝ በኋላ ከማስታወስ በእርግጥ አሳሳተኝ» (ይላል)፡፡ ሰይጣንም ለሰው አጋላጭ ነው፡፡'),
('25:30', 87, 'መልክተኛውም «ጌታዬ ሆይ! ሕዝቦቼ ይህንን ቁርኣን የተተወ ነገር አድርገው ያዙት» አለ፡፡'),
('25:31', 87, 'እንደዚሁም ለነቢዩ ሁሉ ከአመጸኞች የኾነ ጠላትን አድርገናል፡፡ መሪና ረዳትም በጌታህ በቃ፡፡'),
('25:32', 87, 'እነዚያ የካዱትም «ቁርኣን በእርሱ ላይ ለምን በጠቅላላ አንድ ጊዜ አልተወረደም» አሉ፡፡ እንደዚሁ በእርሱ ልብህን ልናረጋ (ከፋፍለን አወረድነው)፡፡ ቀስ በቀስ መለያየትንም ለየነው፡፡'),
('25:33', 87, 'በጥያቄም አይመጡብህም እውነተኛውን (መልስ) መልካምን ፍችም የምናመጣልህ ብንኾን እንጅ፡፡'),
('25:34', 87, 'እነዚያ በፊቶቻቸው ለይ (እየተጎተቱ) ወደ ገሀነም የሚሰበሰቡ ናቸው፡፡ እነዚያ ስፍራቸው የከፋ መንገዳቸውም የጠመመ ናቸው፡፡'),
('25:35', 87, 'በእርግጥም ለሙሳ መጽሐፍን ሰጠነው፡፡ ከእርሱም ጋር ወንድሙን ሃሩንን ረዳት አደረግንለት፡፡'),
('25:36', 87, '«ወደእነዚያም በተዓምራቶቻችን ወደ አስተባበሉት ሕዝቦች ኺዱ» አልናቸው፡፡ (አስዋሿቸውም) ማጥፋትንም አጠፋናቸው፡፡'),
('25:37', 87, 'የኑሕን ሰዎችም መልክተኞችን ባስተባበሉ ጊዜ አሰጠምናቸው፡፡ ለሰዎችም መገሰጫ አደረግናለቸው፡፡ ለበደለኞችም አሳማሚን ቅጣት አዘጋጅተናል፡፡'),
('25:38', 87, 'ዓድንም ሰሙድንም የረስን ሰዎችም በዚህ መካከል የነበሩትንም ብዙን የክፍለ ዘመናት ሕዝቦች (አጠፋን)፡፡'),
('25:39', 87, 'ሁሉንም (ገሠጽን) ለእነሱ ምሳሌዎችን ገለጽን፡፡ ሁሉንም ማጥፋትን አጠፋናቸውም፡፡'),
('25:40', 87, 'በዚያችም ክፉ ዝናምን በተዘነመችው ከተማ ላይ (የመካ ከሐዲዎች) በእርግጥ መጥተዋል፡፡ የሚያዩዋት አልነበሩምን በእውነቱ መቀስቀስን የማይፈሩ ነበሩ፡፡'),
('25:41', 87, 'ባዩህም ጊዜ ያ አላህ መልእክተኛ አድርጎ የላከው ይህ ነውን እያሉ መሳለቂያ እንጂ ሌላ አያደርጉህም፡፡'),
('25:42', 87, '«እነሆ በእርሷ ላይ መታገሳችን ባልነበረ ኖሮ ከአማልክቶቻችን ሊያሳስተን ቀርቦ ነበር» (ሲሉም ይሳለቃሉ)፡፡ ወደፊትም ቅጣቱን በሚያዩ ጊዜ መንገድን በጣም ተሰሳቹ ማን እንደኾነ በእርግጥ ያውቃሉ፡፡'),
('25:43', 87, 'ፍላጎቱን አምላኩ አድርጎ የያዘውን ሰው አየህን አንተ በእርሱ ላይ ጠባቂ ትኾናለህን'),
('25:44', 87, 'ይልቁንም አብዛኛዎቻቸው የሚሰሙ ወይም የሚያውቁ መኾናቸውን ታስባለህን እነርሱ እንደ እንስሳዎች እንጂ ሌላ አይደሉም፡፡ ከቶውንም እነሱ ይልቅ መንገድን የተሳሳቱ ናቸው፡፡'),
('25:45', 87, 'ወደ ጌታህ (ሥራ) ጥላን እንዴት እንደ ዘረጋ አላየህምን በሻም ኖሮ የረጋ ባደረገው ነበር፡፡ ከዚያም ፀሐይን በእርሱ ላይ ምልክት አደረግን፡፡'),
('25:46', 87, 'ከዚያም ቀስ በቀስ ወደእኛ ሰብሰብነው፡፡'),
('25:47', 87, 'እርሱም ያ ለእናንተ ሌሊትን ልብስ እንቅልፍንም ማረፊያ ያደረገ፤ ቀንንም መበተኛ ያደረገላችሁ ነው፡፡'),
('25:48', 87, 'እርሱም ያ ነፋሶችን አብሳሪዎች ሲኾኑ ከዝናሙ በስተፊት የላከ ነው፡፡ ከሰማይም አጥሪ ውሃን አወረድን፡፡'),
('25:49', 87, 'በእርሱ የሞተችን አገር ሕያው ልናደርግበት ከፈጠርነውም ፍጡር እንስሳዎችንና ብዙ ሰዎችንም ልናጠጣው (አወረድነው)፡፡'),
('25:50', 87, '(ጸጋችንን) ይገነዘቡም ዘንድ በመካከላቸው ከፋፈልነው፡፡ ግን አብዛኛዎቹ ሰዎች ክህደትን እንጂ እንቢ አሉ፡፡'),
('25:51', 87, 'በሻንም ኖሮ በየከተማይቱ አስፈራሪን በላክን ነበር፡፡'),
('25:52', 87, 'ከሓዲዎችንም አትታዘዛቸው፡፡ በእርሱም (በቁርኣን) ታላቅን ትግል ታገላቸው፡፡'),
('25:53', 87, 'እርሱም ያ ሁለቱን ባሕሮች አጎራብቶ የለቀቀ ነው፡፡ ይህ ጥምን የሚቆርጥ ጣፋጭ ነው፡፡ ይህም የሚመረግግ ጨው ነው፡፡ በመካከላቸውም (ከመቀላቀል) መለያንና የተከለለን ክልል ያደረገ ነው፡፡'),
('25:54', 87, 'እርሱም ያ ከውሃ ሰውን የፈጠረ፣ የዝምድናና የአማችም ባለቤት ያደረገው ነው፡፡ ጌታህም ቻይ ነው፡፡'),
('25:55', 87, 'ከአላህም ሌላ የማይጠቅማቸውንና የማይጎዳቸውን ይግገዛሉ፤ ከሓዲም በጌታው ላይ (በማመጽ ለሰይጣን) ረዳት ነው፡፡'),
('25:56', 87, 'አብሳሪና አስፈራሪም አድርገን እንጂ አልላክንህም፡፡'),
('25:57', 87, '«በእርሱ ላይ ዋጋን በፍጹም አልጠይቃችሁም፡፡ ግን ወደ ጌታው (መልካም) መንገድን ለመያዝ የሻ ሰው (ይሥራ)» በላቸው፡፡'),
('25:58', 87, 'በዚያም በማይሞተው ሕያው አምላክ ላይ ተመካ፡፡ ከማመስገንም ጋር አጥራው፡፡ በባሮቹ ኀጢኣቶችም ውስጠ ዐዋቂ በእርሱ በቃ፡፡'),
('25:59', 87, 'ያ ሰማያትና ምድርን በመካከላቸው ያለውንም ሁሉ በስድስት ቀኖች ውስጥ የፈጠረ፣ ከዚያም በዐርሹ ላይ (ለሱ ክብር በምስማማ መልኩ) የተደላደለ አልረሕማን ነው፡፡ ከእርሱም ዐዋቂን ጠይቅ፡፡'),
('25:60', 87, 'ለእነርሱም ለአልረሕማን ስገዱ በተባሉ ጊዜ አልረሕማን ማነው ለምታዘን (እና ለማናውቀው) እንሰግዳለን ይላሉ፡፡ (ይህ) መራቅንም ጨመራቸው፡፡'),
('25:61', 87, 'ያ በሰማይ ቡሩጆችን ያደረገና በእርሷም አንጸባራቂን (ፀሐይ) አብሪ ጨረቃንም ያደረገ ጌታ ክብሩ በጣም ላቀ፡፡'),
('25:62', 87, 'እርሱም ያ (ያመለጠውን ሥራ) ማስታወስን ለሚፈልግ ወይም ማመስገንን ለሚፈልግ ሰው ሌሊትንና ቀንን ተተካኪ ያደረገ ነው፡፡'),
('25:63', 87, 'የአልረሕማንም ባሮች እነዚያ በምድር ላይ በዝግታ የሚኼዱት፣ ባለጌዎችም (በክፉ) ባነጋገሩዋቸው ጊዜ ሰላም የሚሉት ናቸው፡፡'),
('25:64', 87, 'እነዚያም ለጌታቸው በግንባራቸው ተደፊዎችና ቋሚዎች ኾነው የሚያድሩት ናቸው፡፡'),
('25:65', 87, 'እነዚያም «ጌታችን ሆይ! የገሀነምን ቅጣት ከእኛ ላይ መልስልን ቅጣቷ የማይለቅ ነውና» የሚሉት ናቸው፡፡'),
('25:66', 87, 'እርሷ መርጊያና መቀመጫ በመኾን ከፋች! (ይላሉ)፡፡'),
('25:67', 87, 'እነዚያም በለገሱ ጊዜ የማያባክኑ የማይቆጥቡትም ናቸው፡፡ በዚህም መካከል (ልግስናቸው) ትክክለኛ የኾነ ነው፡፡'),
('25:68', 87, 'እነዚያም ከአላህ ጋር ሌላን አምላክ የማይገዙት፣ ያችንም አላህ እርም ያደረጋትን ነፍስ ያለ ሕግ የማይገድሉት፣ የማያመነዝሩትም ናቸው፡፡ ይህንንም የሚሠራ ሰው ቅጣትን ያገኛል፡፡'),
('25:69', 87, 'በትንሣኤ ቀን ቅጣቱ ለእርሱ ይደራረባል፡፡ በእርሱም ውስጥ የተዋረደ ኾኖ ይኖራል፡፡'),
('25:70', 87, 'ተጸጽቶ የተመለሰና ያመነ መልካምንም ሥራ የሠራ ሰው ብቻ ሲቀር፡፡ እነዚያም አላህ መጥፎ ሥራዎቻቸውን በመልካም ሥራዎች ይለውጣል፡፡ አላህም እጅግ መሓሪ አዛኝ ነው፡፡'),
('25:71', 87, 'ተጸጽቶ የተመለሰም ሰው መልካምንም የሠራ እርሱ የተወደደን መመለስ ወደ አላህ ይመለሳል፡፡'),
('25:72', 87, 'እነዚያም እብለትን የማይመሰክሩ፤ በውድቅ ቃልም (ተናጋሪ አጠገብ) ባለፉ ጊዜ የከበሩ ኾነው የሚያልፉት ናቸው፡፡'),
('25:73', 87, 'እነዚያም በጌታቸው አንቀጾች በተገሰጹ ጊዜ (የተረዱ ተቀባዮች ኾነው እንጂ) ደንቆሮዎችና ዕውሮች ኾነው በእርሷ ላይ የማይደፉት ናቸው፡፡'),
('25:74', 87, 'እነዚያም «ጌታችን ሆይ! ከሚስቶቻችንና ከዘሮቻችን ለዓይኖች መርጊያን ለእኛ ስጠን፡፡ አላህን ለሚፈሩትም መሪ አድርገን» የሚሉት ናቸው፡፡'),
('25:75', 87, 'እነዚያ በመታገሳቸው የገነትን ሰገነቶች ይምመነዳሉ፡፡ በእርሷም ውስጥ ውዳሴንና ሰላምታን ይስሰጣሉ፡፡'),
('25:76', 87, 'በእርሷ ውስጥ ዘውታሪዎች ኾነው (ይስሰጣሉ)፡፡ መርጊያና መኖሪያይቱ አማረች፡፡'),
('25:77', 87, '«ጸሎታችሁ ባልነበረ ኖሮ ጌታዬ እናንተን ከምንም አይቆጥራችሁም ነበር፡፡ በእርግጥም አስተባበላችሁ፤ ወደ ፊትም (ቅጣቱ) ያዣችሁ ይኾናል» በላቸው፡፡'),
('26:1', 87, 'ጠ.ሰ.መ. (ጧ ሲን ሚም)፡፡'),
('26:2', 87, 'ይህች ግልጽ ከኾነው መጽሐፍ አንቀጾች ናት፡፡'),
('26:3', 87, 'አማኞች ባለመኾናቸው፤ (በቁጭት) ነፍስህን ገዳይ መኾን ይፈራልሃል፡፡'),
('26:4', 87, 'ብንሻ በእነሱ ላይ ከሰማይ ተዓምረን እናወርድና አንገቶቻቸው (መሪዎቻቸው) ለእርሷ ተዋራጆች ይኾናሉ፡፡'),
('26:5', 87, 'ከአልረሕማንም ዘንድ ኣዲስ የተወረደ ቁርኣን አይመጣላቸውም፤ ከእርሱ የሚሸሹ ቢኾኑ እንጂ፡፡'),
('26:6', 87, 'በእርግጥም አስተባበሉ፡፡ የዚያም በእርሱ ይሳለቁበት የነበሩት ወሬዎች (ፍጻሜ) ይመጣባቸዋል፡፡'),
('26:7', 87, 'ወደ ምድርም በውስጧ ከመልካም (በቃይ) ጎሳ ሁሉ ብዙን እንዳበቀልን አላዩምን፡፡'),
('26:8', 87, 'በዚህ አስደናቂ ምልክት አልለበት፡፡ አብዛኞቻቸውም አማኞች አልነበሩም፡፡'),
('26:9', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊ አዛኝ ነው፡፡'),
('26:10', 87, 'ጌታህም ሙሳን «ወደ በደለኞቹ ሕዝቦች ኺድ» በማለት በጠራው ጊዜ (አስታውስ)፡፡'),
('26:11', 87, '«ወደ ፈርዖን ሕዝቦች (ኺድ) አላህን አይፈሩምን» (አለው)፡፡'),
('26:12', 87, '(ሙሳም) አለ «ጌታዬ ሆይ! እኔ ሊያስተባብሉኝ እፈራለሁ፡፡'),
('26:13', 87, '«ልቤም ይጠብባል፡፡ ምላሴም አይፈታም፡፡ ስለዚህ ወደ ሃሩን ላክ፡፡'),
('26:14', 87, '«ለእነርሱም በእኔ ላይ (የደም) ወንጀል አልለ፡፡ ስለዚህ እንዳይገድሉኝ እፈራለሁ፡፡»'),
('26:15', 87, '(አላህ) አለ «ተው! (አይነኩህም)፡፡ በተዓምራቶቻችንም ኺዱ፡፡ እኛ ከእናንተ ጋር ሰሚዎች ነንና፡፡'),
('26:16', 87, '«ወደ ፈርዖንም ኺዱ፡፡ በሉትም፡- እኛ የዓለማት ጌታ መልክተኞች ነን፡፡'),
('26:17', 87, '«የእስራኤልን ልጆች ከእኛ ጋር ልቀቅ፡፡»'),
('26:18', 87, '(ፈርዖንም) አለ «ልጅ ኾነህ በእኛ ውስጥ አላሳደግንህምን በእኛ ውስጥም ከዕድሜህ ብዙ ዓመታትን አልተቀመጥክምን'),
('26:19', 87, '«ያችንም የሠራሃትን ሥራህን አልሠራህምን አንተም ከውለታ ቢሶቹ ነህ» (አለ)፡፡'),
('26:20', 87, '(ሙሳም) አለ «ያን ጊዜ እኔም ከተሳሳቱት ኾኜ ሠራኋት፡፡'),
('26:21', 87, '«በፈራኋችሁም ጊዜ ከእንናተ ሸሸሁ፡፡ ጌታየም ለእኔ ጥበብን ሰጠኝ፡፡ ከመልክተኞቹም አደረገኝ፡፡'),
('26:22', 87, '«ይህችም የእስራኤልን ልጆች ባሪያ በማድረግህ በእኔ ላይ የምትመጻደቅባት ጸጋ ነት፡፡»'),
('26:23', 87, 'ፈርዖን አለ «(ላከኝ የምትለው) የዓለማትም ጌታ ምንድነው»'),
('26:24', 87, '(ሙሳ) «የሰማያትና የምድር በመካከላቸውም ያለው ሁሉ ጌታ ነው፡፡ የምታረጋግጡ ብትኾኑ (ነገሩ ይህ ነው)፤» አለው፡፡'),
('26:25', 87, '(ፈርዖንም) በዙሪያው ላሉት ሰዎች «አትሰሙምን» አለ፡፡'),
('26:26', 87, '(ሙሳ) «ጌታችሁና የመጀመሪያዎቹ አባቶቻችሁም ጌታ ነው» አለው፡፡'),
('26:27', 87, '(ፈርዖን)'),
('26:28', 87, '(ሙሳ) «የምሥራቅና የምዕራብ በመካከላቸውም ያለው ነገር ሁሉ ጌታ ነው፡፡ ታውቁ እንደኾናችሁ (እመኑበት)» አለው፡፡'),
('26:29', 87, '(ፈርዖን) «ከእኔ ሌላ አምላክን ብትይዝ በውነቱ ከእስረኞቹ አደርግሃለሁ» አለ፡፡'),
('26:30', 87, '(ሙሳ) «በግልጽ አስረጅ ብመጣህም እንኳ» አለው፡፡'),
('26:31', 87, '«እንግዲያውስ ከእውነተኞች እንደኾንክ (አስረጁን) አምጣው» አለ፡፡'),
('26:32', 87, 'በትሩንም ጣለ፡፡ እርሷም ወዲያውኑ ግልጽ እባብ ኾነች፡፡'),
('26:33', 87, 'እጁንም አወጣ፡፡ ወዲያውም እርሷ ለተመልካቾች (የምታበራ) ነጭ ኾነች፡፡'),
('26:34', 87, '(ፈርዖን) በዙሪያው ላሉት መማክርት «ይህ በእርግጥ ዐዋቂ ድግምተኛ ነው» አለ፡፡'),
('26:35', 87, '«ከምድራችሁ በድግምቱ ሊያወጣችሁ ይፈልጋልና ምንን ታዛላችሁ» (አላቸው)፡፡'),
('26:36', 87, 'አሉት «እርሱን ወንድሙንም አቆይና በየከተሞቹ ሰብሳቢዎችን ላክ፡፡'),
('26:37', 87, '«በጣም ዐዋቂ ድግምተኞችን ሁሉ ያመጡልሃልና፡፡»'),
('26:38', 87, 'ድግምተኞቹም በታወቀ ቀን ቀጠሮ ተሰበሰቡ፡፡'),
('26:39', 87, 'ለሰዎቹም «እናንተ ተሰብስባችኋልን» ተባለ፡፡'),
('26:40', 87, '«ድግምተኞቹን እነሱ አሸናፊዎች ቢኾኑ እንከተል ዘንድ» (ተባለ)፡፡'),
('26:41', 87, '«ድግምተኞቹም በመጡ ጊዜ ለፈርዖን እኛ አሸናፊዎች ብንሆን ለእኛ በእርግጥ ዋጋ አለን» አሉት፡፡'),
('26:42', 87, '«አዎን፤ እናንተም ያን ጊዜ ከባለሟሎቹ ትኾናላችሁ» አላቸው፡፡'),
('26:43', 87, 'ሙሳ «ለእነርሱ እናንተ የምትጥሉትን ጣሉ» አላቸው፡፡'),
('26:44', 87, 'ገመዶቻቸውንና በትሮቻቸውንም ጣሉ፡፡ «በፈርዖንም ክብር ይኹንብን፡፡ እኛ በእርግጥ አሸናፊዎቹ እኛ ነን» አሉ፡፡'),
('26:45', 87, 'ሙሳም በትሩን ጣለ፡፡ ወዲያውም እርሷ የሚያስመስሉትን ሁሉ ትውጣለች፡፡'),
('26:46', 87, 'ድግምተኞቹም ሰጋጆች ኾነው ወደቁ፡፡'),
('26:47', 87, '(እነሱም) አሉ «በዓለማት ጌታ አመንን፡፡'),
('26:48', 87, '«በሙሳና በሃሩን ጌታ፡፡»'),
('26:49', 87, '(ፈርዖንም) «ለእናንተ ሳልፈቅድላችሁ በፊት ለእርሱ አመናችሁን እርሱ ያ ድግምትን ያስተማራችሁ ታላቃችሁ ነው፡፡ ወደፊትም (የሚያገኛችሁን) በእርግጥ ታውቃላችሁ፡፡ እጆቻችሁንና እግሮቻችሁን (ቀኝና ግራን) በማናጋት እቆረርጣለሁ፡፡ ሁላችሁንም እሰቅላችኋለሁም» አለ፡፡'),
('26:50', 87, '(እነርሱም) አሉ «ጉዳት የለብንም፡፡ እኛ ወደ ጌታችን ተመላሾች ነን፡፡'),
('26:51', 87, '«እኛ የምእምናን መጀመሪያ በመኾናችን ጌታችን ኀጢአቶቻችንን ለእኛ ሊምር እንከጅላለን፡፡»'),
('26:52', 87, 'ወደ ሙሳም «ባሮቼን ይዘህ ሌሊት ኺድ፡፡ እናንተ የሚከተሉዋችሁ ናችሁና» ስንል ላክን፡፡'),
('26:53', 87, 'ፈርዖንም በየከተሞቹ ሰብሳቢዎችን (እንዲህ ሲል) ላከ፡፡'),
('26:54', 87, '«እነዚህ ጥቂቶች ጭፈሮች ናቸው፡፡'),
('26:55', 87, '«እነርሱም ለእኛ አስቆጪዎች ናቸው፡፡'),
('26:56', 87, '«እኛም ብዙዎች ጥንቁቆች ነን፤» (አለ)፡፡'),
('26:57', 87, 'አወጣናቸውም፡፡ ከአትክልቶችና ከምንጮች፡፡'),
('26:58', 87, 'ከድልቦችም ከመልካም መቀመጫዎችም፡፡'),
('26:59', 87, 'እንደዚሁ ለእስራኤል ልጆች አወረስናትም፡፡'),
('26:60', 87, 'ፀሐይዋ ስትወጣም ተከተሉዋቸው፡፡'),
('26:61', 87, 'ሁለቱ ጭፍሮችም በተያዩ ጊዜ የሙሳ ጓዶች «እኛ(የፈርዖን ሰዎች) የሚደርሱብን ነን» አሉ፡፡'),
('26:62', 87, '(ሙሳ) «ተዉዉ! ጌታዬ ከእኔ ጋር ነው፡፡ በእርግጥ ይመራኛል» አለ፡፡'),
('26:63', 87, 'ወደ ሙሳም «ባሕሩን በበትርህ ምታው» ስንል ላክንበት፡፡ (መታውና) ተከፈለም፡፡ ክፍሉም ሁሉ እንደ ታላቅ ጋራ ኾነ፡፡'),
('26:64', 87, 'እዚያም ዘንድ ሌሎችን አቀረብን፡፡'),
('26:65', 87, 'ሙሳንም ከእርሱ ገር ያሉትንም ሰዎች ሁሉንም አዳን፡፡'),
('26:66', 87, 'ከዚያም ሌሎቹን አሰጠምን፡፡'),
('26:67', 87, 'በዚህ ውስጥ ታላቅ ታምር አለበት፡፡ አብዛኞቻቸውም አማኞች አልነበሩም፡፡'),
('26:68', 87, 'ጌታህም እርሱ አሸናፊው አዛኙ ነው፡፡'),
('26:69', 87, 'በእነሱም (በሕዝቦችህ) ላይ የኢብራሂምን ወሬ አንብብላቸው፡፡'),
('26:70', 87, 'ለአባቱና ለሕዝቦቹ «ምንን ትግገዛላችሁ» ባለ ጊዜ፡፡'),
('26:71', 87, '«ጣዖታትን እንገዛለን፤ እርሷንም በመገዛት ላይ እንቆያለን» አሉ፡፡'),
('26:72', 87, '(እርሱም) አለ «በጠራችኋቸው ጊዜ ይሰሟችኋልን'),
('26:73', 87, '«ወይስ ይጠቅሟችኋልን ወይስ ይጎዷችኋልን»'),
('26:74', 87, '«የለም! አባቶቻችን እንደዚሁ ሲሠሩ አገኘን» አሉት፡፡'),
('26:75', 87, '«ትግገዙት የነበራችሁትን አስተዋላችሁን'),
('26:76', 87, '«እናንተም የቀድሞዎቹ አባቶቻችሁም (የተግገዛችሁትን)፡፡»'),
('26:77', 87, '«እነሱም (ጣዖቶቹ) ለእኔ ጠላቶች ናቸው፡፡ ግን የዓለማት ጌታ ሲቀር (እርሱ ወዳጄ ነው)፡፡'),
('26:78', 87, '«(እርሱ) ያ የፈጠረኝ ነው፡፡ እርሱም ይመራኛል፡፡'),
('26:79', 87, '«ያም እርሱ የሚያበላኝና የሚያጠጣኝ ነው፡፡'),
('26:80', 87, '«በታመምኩም ጊዜ እርሱ ያሽረኛል፡፡'),
('26:81', 87, '«ያም የሚገድለኝ ከዚያም ሕያው የሚያደርገኝ ነው፡፡'),
('26:82', 87, 'ያም በፍርዱ ቀን ኀጢአቴን ለእኔ ሊምር የምከጅለው ነው፡፡'),
('26:83', 87, 'ጌታዬ ሆይ! ዕውቀትን ስጠኝ! በደጋጎቹም ሰዎች አስጠጋኝ፡፡'),
('26:84', 87, 'በኋለኞቹም ሕዝቦች ውስጥ ለእኔ መልካም ዝናን አድርግልኝ፡፡'),
('26:85', 87, 'የጸጋይቱን ገነት ከሚወርሱትም አድርገኝ፡፡'),
('26:86', 87, 'ለአባቴም ማር፡፡ እርሱ ከተሳሳቱት ነበረና፡፡'),
('26:87', 87, 'በሚቀሰቀሱበት ቀንም አታዋርደኝ፡፡'),
('26:88', 87, 'ገንዘብም ልጆችም በማይጠቅሙበት ቀን፡፡'),
('26:89', 87, 'ወደ አላህ በንጹህ ልብ የመጣ ሰው ቢኾን እንጅ፡፡»');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('26:90', 87, 'ገነትም ለፈሪዎች በምትቀረብበት (ቀን)፡፡'),
('26:91', 87, 'ገሀነምም ለጠመሞች በምትገለጽበት (ቀን)፡፡'),
('26:92', 87, 'ለእነሱም በሚባል ቀን «ትግገዟቸው የነበራችሁት የት ናቸው»'),
('26:93', 87, '«ከአላህ ሌላ ሲኾኑ ይረዱዋችኋልን ወይስ (ለራሳቸው) ይርረዳሉን»'),
('26:94', 87, 'በውስጧም እነሱና ጠማሞቹ በፊቶቻቸው ተጥለው ይንከባለላሉ፡፡'),
('26:95', 87, 'የሰይጣንም ሰራዊቶች መላውም (ይጣላሉ)፡፡'),
('26:96', 87, 'እነርሱም በእርሷ ውስጥ የሚከራከሩ ኾነው ይላሉ፡-'),
('26:97', 87, 'በአላህ እንምላለን፤ እኛ በግልጽ መሳሳት ውስጥ ነበርን፡፡'),
('26:98', 87, '(ጣዖቶቹን) በዓለማት ጌታ ባስተካከልናችሁ ጊዜ፡፡'),
('26:99', 87, 'አመጸኞቹም እንጅ ሌላ አላሳሳተንም፡፡'),
('26:100', 87, 'ከአማላጆችም ለእኛ ምንም የለንም፡፡'),
('26:101', 87, 'አዛኝ ወዳጂም (የለንም)፡፡'),
('26:102', 87, 'ለእኛም አንዲት ጊዜ መመለስ በኖረችንና ከአማኞቹ በኾን እንመኛለን (ይላሉ)፡፡'),
('26:103', 87, 'በዚህ ውስጥ አስደናቂ ግሳጼ አልለበት፡፡ አብዛኞቻቸውም አማኞች አልነበሩም፡፡'),
('26:104', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:105', 87, 'የኑሕ ሕዝቦች መልክተኞችን አስተባበሉ፡፡'),
('26:106', 87, 'ወንድማቸው ኑሕ ለእነሱ ባላቸው ጊዜ «አትጠነቀቁምን'),
('26:107', 87, '«እኔ ለእናንተ ታማኝ መልክተኛ ነኝ፡፡'),
('26:108', 87, '«አላህንም ፍሩ ታዘዙኝም፡፡'),
('26:109', 87, '«በእርሱም ላይ ምንም ዋጋ አልጠይቃችሁም፡፡ ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም፡፡'),
('26:110', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡»'),
('26:111', 87, '(እነርሱም) «ወራዶቹ የተከተሉህ ኾነህ ለአንተ እናምናለን» አሉት፡፡'),
('26:112', 87, '(እርሱም) አላቸው «ይሠሩት በነበሩት ነገር ምን ዕውቀት አለኝ፡፡'),
('26:113', 87, '«ምርመራቸው በጌታዬ ላይ እንጅ በሌላ ላይ አይደለም፡፡ ብታውቁ ኖሮ (ይህንን ትርረዱ ነበር)፡፡'),
('26:114', 87, '«እኔም አማኞችን አባራሪ አይደለሁም፡፡'),
('26:115', 87, '«እኔ ግልጽ አስፈራሪ እንጅ ሌላ አይደለሁም፡፡»'),
('26:116', 87, '«ኑሕ ሆይ! (ከምትለው) ባትከለከል በእርግጥ ከሚወገሩት ትኾናለህ» አሉት፡፡'),
('26:117', 87, '(እርሱም) አለ «ጌታዬ ሆይ! ሕዝቦቼ አስተባበሉኝ፡፡'),
('26:118', 87, '«በእኔና በእነርሱም መካከል (ተገቢ) ፍርድን ፍረድ፡፡ አድነኝም፡፡ ከእኔ ጋር ያሉትንም ምእምናን፡፡»'),
('26:119', 87, 'እርሱንም ከእርሱ ጋር ያለውንም ሁሉ በተመላው መርከብ ውስጥ አዳን፡፡'),
('26:120', 87, 'ከዚያም በኋላ ቀሪዎቹን አሰጠምን፡፡'),
('26:121', 87, 'በዚህ ውስጥ ታላቅ ግሳጼ አለበት፡፡ አብዛኞቻቸውም አማኞች አልነበሩም፡፡'),
('26:122', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:123', 87, 'ዓድ መልክተኞችን አስተባበለች፡፡'),
('26:124', 87, 'ወንድማቸው ሁድ ለነርሱ ባላቸው ጊዜ «አትጠነቀቁምን'),
('26:125', 87, '«እኔ ለናንተ ታማኝ መልክተኛ ነኝ፡፡'),
('26:126', 87, '«አላህንም ፍሩ ታዘዙኝም፡፡'),
('26:127', 87, '«በእርሱም ላይ ምንም ዋጋ አለምናችሁም፡፡ ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም፡፡'),
('26:128', 87, '«የምትጫወቱ ኾናችሁ በከፍተኛ ስፍራ ሁሉ ላይ ምልክትን ትገነባላችሁን'),
('26:129', 87, '«የውሃ ማጠራቀሚያዎችንና ሕንፃዎችንም ዘላለም መኖርን የምትከጅሉ ኾናችሁ ትሠራላችሁን'),
('26:130', 87, '«በቀጣችሁም ጊዜ ጨካኞች ኾናችሁ ትቀጣላችሁን'),
('26:131', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡'),
('26:132', 87, '«ያንንም በምታውቁት (ጸጋ) ያጣቀማችሁን ፍሩ፡፡'),
('26:133', 87, '«በእንስሳዎችና በልጆች ያጣቀማችሁን፡፡'),
('26:134', 87, '«በአትክልቶችና በምንጮችም፡፡'),
('26:135', 87, '«እኔ በእናንተ ላይ የታላቅን ቀን ቅጣት እፈራለሁና፡፡»'),
('26:136', 87, '(እነርሱም) አሉ «ብትገስጽም ወይም ከገሳጮቹ ባትኾንም በእኛ ላይ እኩል ነው፤ (ያለንበትን አንለቅም)፡፡'),
('26:137', 87, '«ይህ የፊተኞቹ ሰዎች ፀባይ እንጅ ሌላ አይደለም፡፡'),
('26:138', 87, '«እኛም የምንቅቀጣ አይደለንም» (አሉ)፡፡'),
('26:139', 87, 'አስተባበሉትም፡፡ አጠፋናቸውም፡፡ በዚህም ውስጥ እርግጠኛ ግሳጼ አለበት፡፡ አብዛኞቻቸውም ምእመናን አልነበሩም፡፡'),
('26:140', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:141', 87, 'ሰሙድ መልክተኞችን አስተባበለች፡፡'),
('26:142', 87, 'ወንድማቸው ሷሊህ ለእነርሱ ባላቸው ጊዜ «አትጠነቀቁምን'),
('26:143', 87, '«እኔ ለእናንተ ታማኝ መልክተኛ ነኝ፡፡'),
('26:144', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡'),
('26:145', 87, '«በእርሱም ላይ ምንም ዋጋ አልለምናችሁም፡፡ ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም፡፡'),
('26:146', 87, '«በዚያ እዚህ ባለው (ጸጋ) ውስጥ የረካችሁ ኾናችሁ ትተዋላችሁን'),
('26:147', 87, '«በአትክልቶችና በምንጮች ውስጥ፡፡'),
('26:148', 87, '«በአዝመራዎችም ፍሬዋ የበሰለ በኾነች ዘንባባም፤ (ውስጥ ትተዋላችሁን)'),
('26:149', 87, '«ብልሆች ኾናችሁ ከጋራዎች ቤቶችንም ትጠርባላችሁ፡፡'),
('26:150', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡'),
('26:151', 87, '«የወሰን አላፊዎችንም ትዕዛዝ አትከተሉ፡፡'),
('26:152', 87, '«የእነዚያን በምድር ላይ የሚያጠፉትንና የማያበጁትን፡፡»'),
('26:153', 87, '(እነሱም) አሉ «አንተ በብዙ ከተደገመባቸው ሰዎች ብቻ ነህ፡፡'),
('26:154', 87, '«አንተ ብጤያችን ሰው እንጅ ሌላ አይደለህም፡፡ ከእውነተኞቹም እንደኾንክ ተዓምርን አምጣ፡፡»'),
('26:155', 87, '(እርሱም) አለ «ይህች ግመል ናት፡፡ ለእርሷ የመጠጥ ፋንታ አላት፡፡ ለእናንተም የታወቀ ቀን ፋንታ አላችሁ፡፡'),
('26:156', 87, '«በክፉም አትንኳት፡፡ የታላቅ ቀን ቅጣት ይይዛችኋልና፡፡»'),
('26:157', 87, 'ወጓትም፡፡ ወዲያውም ተጸጻቾች ኾነው አነጉ፡፡'),
('26:158', 87, 'ቅጣቱም ያዛቸው፡፡ በዚህም ውስጥ ግሳፄ አልለበት፡፡ አብዛኞቻቸውም ምእመናን አልነበሩም፡፡'),
('26:159', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:160', 87, 'የሉጥ ሕዝቦች መልክተኞችን አስተባባሉ፡፡'),
('26:161', 87, 'ወንድማቸው ሉጥ ለእነርሱ ባለ ጊዜ «አትጠነቀቁምን'),
('26:162', 87, '«እኔ ለእናንተ ታማኝ መልክተኛ ነኝ፡፡'),
('26:163', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡'),
('26:164', 87, '«በእርሱም ላይ ምንም ዋጋ አልለምናችሁም፡፡ ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም፡፡'),
('26:165', 87, '«ከዓለማት ሰዎች ወንዶችን ትመጣላችሁን'),
('26:166', 87, '«ከሚስቶቻችሁም ጌታችሁ ለናንተ የፈጠረላችሁን ትተዋላችሁን በእውነቱ እናንተ ወሰን አላፊዎች ሕዝቦ ናችሁ፡፡»'),
('26:167', 87, '(እነርሱም) አሉ «ሉጥ ሆይ! ባትከለከል በእርግጥ (ከአገር) ከሚወጡት ትኾናለህ፡፡»'),
('26:168', 87, '(እርሱም) አለ «እኔ ሥራችሁን ከሚጠሉት ሰዎች ነኝ፡፡'),
('26:169', 87, '«ጌታዬ ሆይ! እኔንም ቤተሰቦቼንም ከሚሠሩት ሥራ (ቅጣት) አድነን፡፡»'),
('26:170', 87, 'እርሱንም ቤተሰቦቹንም በጠቅላላ አዳንናቸው፡፡'),
('26:171', 87, 'በቀሪዎቹ ውስጥ የኾነች አሮጊት ብቻ ስትቀር (እርሷ ጠፋች)፡፡'),
('26:172', 87, 'ከዚያም ሌሎቹን አጠፋን፡፡'),
('26:173', 87, 'በእነሱም ላይ (የድንጋይን) ዝናምን አዘነምንባቸው፡፡ የተስፈራሪዎቹም ዝናም (ምንኛ) ከፋ፡፡'),
('26:174', 87, 'በዚህ ውስጥ አስደናቂ ተዓምር አልለበት፡፡ አብዛኞቻቸውም ምእመናን አልነበሩም፡፡'),
('26:175', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:176', 87, 'የአይከት ሰዎች መልክተኞችን አስተባበሉ፤'),
('26:177', 87, 'ሹዕይብ ለእነርሱ ባላቸው ጊዜ «አትጠነቀቁምን'),
('26:178', 87, '«እኔ ለእናንተ ታማኝ መልክተኛ ነኝ፡፡'),
('26:179', 87, '«አላህንም ፍሩ፤ ታዘዙኝም፡፡'),
('26:180', 87, '«በርሱም ላይ ምንም ዋጋ አልጠይቃችሁም፡፡ ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም፡፡'),
('26:181', 87, '«ስፍርን ሙሉ፡፡ ከአጉዳዮቹም አትኹኑ፡፡'),
('26:182', 87, '«በትክክለኛ ሚዛንም መዝኑ፡፡'),
('26:183', 87, '«ሰዎችንም ነገሮቻቸውን አታጉድሉባቸው፡፡ በምድርም ላይ አጥፊዎች ኾናችሁ አታበላሹ፡፡'),
('26:184', 87, '«ያንንም የፈጠራችሁን የቀድሞዎቹንም ፍጡሮች (የፈጠረውን) ፍሩ፡፡»'),
('26:185', 87, 'አሉ «አንተ በብዛት ከተደገመባቸው ሰዎች ነህ፡፡'),
('26:186', 87, '«አንተም ብጤያችን ሰው እንጅ ሌላ አይደለህም፡፡ እነሆ ከውሸታሞች ነህ ብለን እንጠረጥርሃለን፡፡'),
('26:187', 87, '«ከእውነተኞቹም እንደኾንክ በእኛ ላይ ከሰማይ ቁራጭን ጣልብን፡፡»'),
('26:188', 87, '«ጌታዬ የምትሠሩትን ሁሉ ዐዋቂ ነው፤» አላቸው፡፡'),
('26:189', 87, 'አስተባበሉትም፡፡ የጥላይቷ ቀን ቅጣትም ያዛቸው፡፡ እርሱ የከባድ ቀን ቅጣት ነበርና፡፡'),
('26:190', 87, 'በዚህ ውስጥ አስደናቂ ተዓምር አልለበት፡፡ አብዛኞቻቸውም ምእምናን አልነበሩም፡፡'),
('26:191', 87, 'ጌታህም እርሱ በእርግጥ አሸናፊው አዛኙ ነው፡፡'),
('26:192', 87, 'እርሱም (ቁርኣን) በእርግጥ ከዓለማት ጌታ የተወረደ ነው፡፡'),
('26:193', 87, 'እርሱን ታማኙ መንፈስ (ጂብሪል) አወረደው፤'),
('26:194', 87, 'ከአስፈራሪዎቹ (ነቢያት) ትኾን ዘንድ በልብህ ላይ (አወረደው)፡፡'),
('26:195', 87, 'ግልጽ በኾነ ዐረብኛ ቋንቋ፡፡'),
('26:196', 87, 'እርሱም (ቁርኣን) በቀድሞዎቹ መጻሐፍት ውስጥ (የተወሳ ነው)፡፡'),
('26:197', 87, 'የእስራኤል ልጆች ሊቃውንት የሚያውቁት መኾኑ ለእነርሱ (ለመካ ከሓዲዎች) ምልክት አይኾናቸውምን'),
('26:198', 87, 'ከአዕጀሞች ባንዱ ላይ ባወረድነውም ኖሮ፤'),
('26:199', 87, 'በእነርሱ ላይ ባነበበውም በእርሱ አማኞች አይኾኑም ነበር፡፡'),
('26:200', 87, 'እንደዚሁ (ማስተባበልን) በተንኮለኞች ልቦች ውስጥ አስገባነው፡፡'),
('26:201', 87, 'አሳማሚ ቅጣትን እስከሚያዩ ድረስ በእርሱ አያምኑም፡፡'),
('26:202', 87, 'እነርሱ የማያውቁ ሲኾኑ (ቅጣቱ) ድንገት እስከሚመጣባቸውም ድረስ (አያምኑም)፡፡'),
('26:203', 87, '(በመጣባቸው ጊዜ) «እኛ የምንቆይ ነን» እስከሚሉም (አያምኑም)፡፡'),
('26:204', 87, 'በቅጣታችን ያቻኩላሉን'),
('26:205', 87, 'አየህን ብዙ ዓመታትን ብናጣቅማቸው፤'),
('26:206', 87, 'ከዚያም ያ ይስፈራሩበት የነበሩት ቢመጣባቸው፤'),
('26:207', 87, 'ይጣቀሙበት የነበሩት ሁሉ ከእነሱ ምንም አያብቃቃቸውም፡፡'),
('26:208', 87, 'አንዲትንም ከተማ ለእርሷ አስፈራሪዎች ያሏት (እና ያስተባበለች) ኾና እንጅ አላጠፋንም፡፡'),
('26:209', 87, '(ይህች) ግሳፄ ናት፡፡ በዳዮችም አልነበርንም፡፡'),
('26:210', 87, 'ሰይጣናትም እርሱን (ቁርኣንን) አላወረዱትም፡፡'),
('26:211', 87, 'ለእነርሱም አይገባቸውም፤ አይችሉምም፡፡'),
('26:212', 87, 'እነርሱ (የመላእክትን ንግግር) ከመስማት ተከለከሉ ናቸው፡፡'),
('26:213', 87, 'ከአላህም ጋር ሌላን አምላክ አትግገዛ፤ ከሚቀጡት ትኾናለህና፡፡'),
('26:214', 87, 'ቅርቦች ዘመዶችህንም አስጠንቅቅ፡፡'),
('26:215', 87, 'ከምእምናንም ለተከተሉህ ሰዎች ክንፍህን ዝቅ አድርግ፤ (ልዝብ ኹን)፡፡'),
('26:216', 87, '«እንቢ» ቢሉህም «እኔ ከምትሠሩት ንጹሕ ነኝ» በላቸው፡፡'),
('26:217', 87, 'አሸናፊ አዛኝ በኾነው (ጌታህ) ላይም ተጠጋ፡፡'),
('26:218', 87, 'በዚያ ለሶላት በምትቆም ጊዜ በሚያይህ፡፡'),
('26:219', 87, 'በሰጋጆች ውስጥ መዘዋወርህንም (በሚያየው ጌታህ ላይ ተጠጋ)፡፡'),
('26:220', 87, 'እነሆ እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('26:221', 87, 'ሰይጣናት በማን ላይ እንደሚወርዱ ልንገራችሁን'),
('26:222', 87, 'በውሸታም ኀጢአተኛ ሁሉ ላይ ይወርዳሉ፡፡'),
('26:223', 87, 'የሰሙትን (ወደ ጠንቋዮች) ይጥላሉ፡፡ አብዛኞቻቸውም ውሸታሞች ናቸው፡፡'),
('26:224', 87, 'ባለ ቅኔዎችንም ጠማማዎቹ ይከተሉዋቸዋል፡፡'),
('26:225', 87, 'እነርሱ በ(ንግግር) ሸለቆ ሁሉ የሚዋልሉ መኾናቸውን አታይምን'),
('26:226', 87, 'እነሱም የማይሠሩትን ነገር የሚናገሩ መኾናቸውን (አታይምን)፤'),
('26:227', 87, 'እነዚያ ያመኑና መልካም ሥራዎችን የሠሩ አላህንም በብዛት ያወሱ ከተበደሉም በኋላ (በቅኔ) የተከላከሉ ሲቀሩ፤ (እነርሱ አይወቀሱም)፡፡ እነዚያም የበደሉ (ከሞቱ በኋላ) እንዴት ያለን መመለስ እንደሚመለሱ በእርግጥ ያውቃሉ፡፡'),
('27:1', 87, 'ጠ.ሰ (ጣ ሲን) ይህቺ ከቁርኣኑና ከገላጩ መጽሐፍ አንቀጾች ናት፡፡'),
('27:2', 87, 'ለምእምናን መሪና ብስራት ናት፡፡'),
('27:3', 87, 'ለእነዚያ ሶላትን ለሚሰግዱት ዘካንም ለሚሰጡት እነሱም በመጨረሻይቱ ሕይወት እነሱ የሚያረጋግጡ ለኾኑት፡፡'),
('27:4', 87, 'እነዚያ በመጨረሻይቱ ዓለም የማያምኑት ለእነሱ (ክፉ) ሥራዎቻቸውን ሸለምንላቸው፡፡ ስለዚህ እነርሱ ይዋልላሉ፡፡'),
('27:5', 87, 'እነርሱ እነዚያ ክፉ ቅጣት ለእነርሱ ያላቸው ናቸው፡፡ እነርሱም በመጨረሻይቱ ዓለም እነርሱ በጣም ከሳሪዎቹ ናቸው፡፡'),
('27:6', 87, 'አንተም ቁርኣንን ጥበበኛና ዐዋቂ ከኾነው (ጌታህ) ዘንድ በእርግጥ ትስሰጣለህ፡፡'),
('27:7', 87, 'ሙሳ ለቤተሰቦቹ «እኔ እሳትን አየሁ፡፡ ከእርሷ ወሬን አመጣላችኋለሁ፡፡ ወይም ትሞቁ ዘንድ የተለኮሰ ችቦን አመጣላችኋለሁ» ባለ ጊዜ (የኾነውን አውሳላቸው)፡፡'),
('27:8', 87, 'በመጣትም ጊዜ እንዲህ በማለት ተጠራ፤ «በእሳቲቱ ያለው ሰውና በዙሪያዋ ያሉም ሁሉ ተባረኩ፡፡ የዐለማትም ጌታ አላህ ጥራት ይገባው፡፡»'),
('27:9', 87, '«ሙሳ ሆይ! እነሆ እኔ አሸናፊው ጥበበኛው አላህ ነኝ፡፡'),
('27:10', 87, '«በትርህንም ጣል» (ተባለ ጣለም)፡፡ እርሷ እንደ ትንሽ እባብ በፍጥነት ስትስለከለክ ባያትም ጊዜ፤ ወደ ኋላ ዞሮ ሸሸ፡፡ አልተመለሰምም፡፡ «ሙሳ ሆይ! አትፈራ፤ እኔ መልክተኞቹ እኔ ዘንድ አይፈሩምና፡፡'),
('27:11', 87, '«ግን የበደለ ሰው ከዚያም ከመጥፎ ሥራው በኋላ መልካምን የለወጠ እኔ መሓሪ አዛኝ ነኝ፡፡'),
('27:12', 87, '«እጅህንም በአንገትጌህ ውስጥ አግባ፡፡ ያለነውር (ያለ ለምጽ) ነጭ ኾና ትወጣለችና፡፡ በዘጠኝ ተዓምራት ወደ ፈርዖንና ወደ ሕዝቦቹ (ኺድ)፡፡ እነርሱ አመጸኞች ሕዝቦች ናቸውና፡፡'),
('27:13', 87, 'ተዓምራታችንም ግልጽ ኾና በመጣቻቸው ጊዜ «ይህ ግልጽ ድግምት ነው» አሉ፡፡'),
('27:14', 87, 'ነፍሶቻቸውም ያረጋገጧት ሲኾኑ ለበደልና ለኩራት በእርሷ ካዱ፡፡ የአመጸኞችም ፍጻሜ እንዴት እንደ ነበረ ተመልከት፡፡'),
('27:15', 87, 'ለዳውድና ለሱለይማንም ዕውቀትን በእርግጥ ሰጠናቸው፡፡ አሉም፡- «ምስጋና ለአላህ ለእዚያ ከምእምናን ባሮቹ በብዙዎቹ ላይ ላበለጠን ይገባው፡፡»'),
('27:16', 87, 'ሱለይማንም ዳውድን ወረሰ፡፡ አለም «ሰዎች ሆይ! የበራሪን ንግግር (የወፍን ቋንቋ) ተስተማርን፡፡ ከነገሩም ሁሉ ተሰጠን፡፡ ይህ እርሱ በእርግጥ ግልጽ የኾነ ችሮታ ነው፡፡»'),
('27:17', 87, 'ለሱለይማንም ሰራዊቶቹ ከጋኔን፣ ከሰውም፣ ከበራሪም የኾኑት ተሰበሰቡ፡፡ እነሱም ይከመከማሉ፡፡'),
('27:18', 87, 'በጉንዳንም ሸለቆ በመጡ ጊዜ አንዲት ጉንዳን «እናንተ ጉንዳኖች ሆይ! ወደ መኖሪያዎቻችሁ'),
('27:19', 87, 'ከንግግርዋም እየሳቀ ጥርሱን ፈገግ አደረገ፡፡ «ጌታዬ ሆይ! ያቺን በእኔና በወላጆቼ ላይ የለገስካትን ጸጋህን እንዳመሰግን የምትወደውንም በጎ ሥራ እንድሠራ ምራኝ፡፡ በችሮታህም በመልካሞቹ ባሮችህ ውስጥ አግባኝ» አለ፡፡'),
('27:20', 87, 'በራሪዎቹንም ተመለከተ፤ አለም «ሁድሁድን ለምን አላየውም! በእውነቱ ከራቁት ነበርን፡፡'),
('27:21', 87, '«ብርቱን ቅጣት በእርግጥ እቀጣዋለሁ፡፡ ወይም በእርግጥ ዐርደዋለሁ፤ ወይም ግልጽ በኾነ አስረጅ ይመጣኛል» (አለ)'),
('27:22', 87, '(ወፉ) ዕሩቅ ያልኾነንም ጊዜ ቆዬ፡፡ አለም «ያላወቅከውን ነገር አወቅኩ፡፡ ከሰበእም እርግጠኛን ወሬ አመጣሁልህ፡፡'),
('27:23', 87, '«እኔ የምትገዛቸው የኾኑችን ሴት ከነገሩም ሁሉ የተሰጠችኝ አገኘሁ፡፡ ለእርሷም ታላቅ ዙፋን አልላት፡፡'),
('27:24', 87, '«እርስዋንም ሕዝቦችዋንም ከአላህ ሌላ ለፀሐይ ሲሰግዱ አገኘኋቸው፡፡ ሰይጣንም ለእነሱ ሥራዎቻቸውን ሸልሞላቸዋል፡፡ ከእውነተኛውም መንገድ አግዷቸዋል፡፡ ስለዚህ እነሱ (ወደ እውነት) አይምመሩም፡፡»'),
('27:25', 87, 'ለዚያ በሰማያትና በምድር የተደበቀውን ለሚያወጣው፣ የምትሸሽጉትንና የምትገ ልጹትንም ሁሉ ለሚያውቀው አላህ እንዳይሰግዱ (ሰይጣን አግዷቸዋል)፡፡'),
('27:26', 87, 'አላህ ከርሱ ሌላ አምላክ የለም፡፡ የታላቁ ዐርሽ (ዙፋን) ጌታ ነው፡፡'),
('27:27', 87, '(ሱለይማንም) አለ «እውነት እንደ ተናገርክ ወይም ከውሸታሞቹ እንደ ኾንክ ወደፊት እናያለን፡፡'),
('27:28', 87, '«ይህንን ደብዳቤዬን ይዘህ ኺድ፡፡ ወደእነርሱም ጣለው፡፡ ከዚያም ከእነሱ ዘወር በል፡፡ ምን አንደሚመልሱም ተመልከት፡፡»'),
('27:29', 87, '(እርሷም በደረሳት ጊዜ) አለች «እናንተ መማክርቶች ሆይ! እኔ ክብር ያለው ጽሑፍ ወደኔ ተጣለ፡፡'),
('27:30', 87, '«እርሱ ከሱለይማን ነው፡፡ እርሱም በአላህ ስም እጅግ በጣም ሩኅሩኅ በጣም አዛኝ በኾነው፡፡'),
('27:31', 87, '«በእኔ ላይ አትኩሩ፡፡ ታዛዦችም ኾናችሁ ወደኔ ኑ፤ (የሚል ነው)፡፡'),
('27:32', 87, '«እናንተ መማክርቶች ሆይ! በነገሬ (የሚበጀውን) ንገሩኝ፡፡ እስከምትገኙልኝ ድረስ አንድንም ነገር ቆራጭ አይደለሁምና» አለች፡፡'),
('27:33', 87, '«እኛ የኀይል ባለቤቶች የብርቱ ጦርም ባለቤቶች ነን፡፡ ግን ትዕዛዙ ወደ አንቺ ነው፡፡ ምን እንደምታዢም አስተውዪ፤» አሏት፡፡'),
('27:34', 87, '(እርሷም) አለች «ንጉሦች ከተማን (በኀይል) በገቡባት ጊዜ ያበላሹዋታል፡፡ የተከበሩ ሰዎችዋንም ወራዶች ያደርጋሉ፡፡ እንደዚሁም (እነዚህ) ይሠራሉ፡፡'),
('27:35', 87, '«እኔም ወደእነርሱ ገጸ በረከትን የምልክና መልክተኞቹ በምን እንደሚመለሱ የምጠባበቅ ነኝ፡፡»'),
('27:36', 87, '(መልክተኛው) ሱለይማንንም በመጣው ጊዜ አለ «በገንዘብ ትረዱኛላችሁን አላህም የሰጠኝ ከሰጣችሁ የበለጠ ነው፡፡ ይልቁንም እናንተ በገጸ በረከታችሁ ትደሰታላችሁ፡፡»'),
('27:37', 87, '«ወደእነሱ ተመለስ፡፡ ለእነርሱም በእርሷ ችሎታ በሌላቸው ሰራዊት እንመጣባቸዋለን፡፡ ከእርሷም እነርሱ የተዋረዱ ኾነው በእርግጥ እናወጣቸዋለን» (አለ)፡፡'),
('27:38', 87, '«እናንተ መኳንንቶች ሆይ! ሙስሊሞች ኾነው ሳይመጡኝ በፊት ዙፋንዋን የሚያመጣልኝ ማንኛችሁ ነው» አለ፡፡'),
('27:39', 87, 'ከጋኔን ኀይለኛው «ከችሎትህ ከመነሳትህ በፊት እኔ እርሱን አመጣልሃለሁ፡፡ እኔም በእርሱ ላይ ብርቱ ታማኝ ነኝ» አለ፡፡'),
('27:40', 87, 'ያ እርሱ ዘንድ ከመጽሐፉ ዕውቀት ያለው ሰው (የተገለጸው) «ዓይንህ ወደ አንተ ከመመለሱ በፊት እኔ እርሱን አመጣልሃለሁ» አለ፤ (እንደዚሁም አደረገ)፡፡ እርሱ ዘንድ ረግቶ ባየውም ጊዜ «ይህ ከጌታዬ ችሮታ ነው፡፡ የማመሰግን ወይም የምክድ መኾኔን ሊሞክረኝ (ቸረልኝ)፡፡ ያመሰገነም ሰው የሚያመሰግነው ለራሱ ነው፡፡ የካደም ሰው ጌታዬ ከእርሱ ተብቃቂ ቸር ነው» አለ፡፡'),
('27:41', 87, '«ዙፋንዋን ለእርሷ አሳስቱ፡፡ ታውቀው እንደኾነ ወይም ከእነዚያ ከማያወቁት ትኾን እንደሆነ፤ እናያለን፤» አላቸው፡፡'),
('27:42', 87, 'በመጣች ጊዜ፡- «ዙፋንሽ እንደዚህ ነውን» ተባለች፡፡ «እርሱ ልክ እርሱ ነው መሰለኝ» አለች፡፡ (ሱለይማን) «ከእርሷ በፊትም ዕውቀትን ተሰጠን ሙስሊሞችም ነበርን፤» (አለ)፡፡'),
('27:43', 87, 'ከአላህ ሌላ ትግገዛው የነበረችውንም ከለከላት፡፡ እርሷ ከከሓዲዎች ሕዝቦች ነበረችና፡፡'),
('27:44', 87, 'ሕንጻውን ግቢ ተባለች፡፡ ባየቺውም ጊዜ ባሕር ነው ብላ ጠረጠረችው፡፡ ከባቶችዋም ገለጠች፡፡ «እርሱ ከመስተዋት የተለሰለሰ ሕንጻ ነው» አላት፡፡ «ጌታዬ ሆይ! እኔ ነፍሴን በደልኩ፡፡ ከሱለይማንም ጋር ሆኜ ለዓለማት ጌታ ለአላህ ታዘዝኩ» አለች፡፡'),
('27:45', 87, 'ወደ ሰሙድም ወንድማቸውን ሷሊሕን አላህን ተገዙ በማለት በእርግጥ ላክነው፡፡ ወዲያውም እነሱ የሚነታረኩ ሁለት ጭፍሮች ኾኑ፡፡'),
('27:46', 87, '«ሕዝቦቼ ሆይ! ከመልካሙ በፊት በክፉው (ቅጣትን አምጣብን በማለት) ለምን ታስቸኩላላችሀ ይታዘንላችሁ ዘንድ አላህን ምሕረትን አትለምኑምን» አላቸው፡፡'),
('27:47', 87, '«ባንተና ከአንተም ጋር ባሉት ሰዎች ምክንያት ገደቢሶች ኾን» አሉት፡፡ «ገደቢስነታችሁ አላህ ዘንድ ነው፤ ይልቁንም እናንተ የምትፈተኑ ሕዝቦች ናችሁ» አላቸው፡፡'),
('27:48', 87, 'በከተማይቱም ውስጥ በምድር ውስጥ የሚያበላሹና የማያሳምሩ ዘጠኝ ሰዎች ነበሩ፡፡'),
('27:49', 87, '«እርሱንና ቤተሰቦቹን ሌሊት ልንገድል ከዚያም ለዘመዱ የቤተሰቦቹን ጥፋት (መገደላቸውን) አላየንም፤ እኛም እውነተኞች ነን ልንል በአላህ ተማማሉ» አሉ፡፡'),
('27:50', 87, 'ተንኮልንም መከሩ፡፡ እነርሱም የማያወቁ ሲኾኑ በተንኮላቸው አጠፋናቸው፡፡'),
('27:51', 87, 'የተንኮላቸውም መጨረሻ እንዴት እንደነበረ እኛ እነርሱንም ሕዝቦቻቸውንም በሙሉ እንዴት እንዳጠፋናቸው ተመልከት፡፡'),
('27:52', 87, 'እኚህም በበደላቸው ምክንያት ባዶዎች ሲሆኑ ቤቶቻቸው ናቸው፡፡ በዚህም ውስጥ ለሚያወቁ ሕዝቦች አስደናቂ ተዓምር አለበት፡፡'),
('27:53', 87, 'እነዚያንም ያመኑትንና ከክሕደት ይጠነቀቁ የነበሩትን አዳን፡፡'),
('27:54', 87, 'ሉጥንም ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፤ «እናንተ የምታዩ ስትኾኑ ፀያፍን ነገር ትሠራላችሁን'),
('27:55', 87, '«እናንተ ከሴቶች አልፋችሁ ወንዶችን ለመከጀል ትመጣላችሁን በእውነቱ እናንተ የምትሳሳቱ ሕዝቦች ናቸሁ፡፡»'),
('27:56', 87, 'የሕዝቦቹም መልስ የሉጥን ቤተሰቦች «ከከተማችሁ አውጡ፡፡ እነርሱ የሚጥራሩ ሰዎች ናቸውና» ማለት እንጅ ሌላ አልነበረም፡፡'),
('27:57', 87, 'እርሱንና ቤተሰቦቹንም አዳን፡፡ ሚስቱ፤ ብቻ ስትቀር፡፡ (በጥፋቱ ውስጥ) ከቀሪዎቹ አደረግናት፡፡'),
('27:58', 87, 'በእነርሱም ላይ (የድንጋይ) ዝናብን አዘነብንባቸው፡፡ የተስፈራሪዎቹም ዝናብ ከፋ፡፡'),
('27:59', 87, '(ሙሐመድ ሆይ) በል «ምስጋና ለአላህ ይግባው፡፡ በእነዚያም በመረጣቸው ባሮቹ ላይ ሰላም ይውረድ፡፡ አላህ በላጭ ነውን ወይስ ያ የሚያጋሩት (ጣዖት)፡፡'),
('27:60', 87, 'ወይም ያ ሰማያትንና ምድርን የፈጠረና ከሰማይም ለእናንተ ውሃን ያወረደው (ይበልጣል ወይስ የሚያጋሩት) በእርሱም ባለውበት የኾኑትን የታጠሩ አትክልቶችን ዛፍዋን ልታበቅሉ ለናንተ ችሎታ ያልነበራችሁን አበቀልን፡፡ ከአላህ ጋር ሌላ አምላክ አለን (የለም)፡፡ ግን እነርሱ (ከእውነት) የሚያዘነብሉ ሕዝቦች ናቸው፡፡'),
('27:61', 87, 'ወይም ያ ምድርን መርጊያ ያደረገና በመካከሏም ወንዞችን ያደረገ፣ ለእርሷም ጋራዎችን ያደረገ፣ በሁለቱ ባሕሮችም (በጣፋጩና በጨው ባሕር) መካከል ግርዶን ያደረገ (ይበልጣልን ወይስ የሚያጋሩት) ከአላህ ጋር ሌላ አምላክ አለን ግን አብዛኞቻቸው አያውቁም፡፡'),
('27:62', 87, 'ወይም ያ ችግረኛን በለመነው ጊዜ የሚቀበል፣ መከራንም የሚያስወግድ፣ በምድርም ላይ ምትኮች የሚያደረጋችሁ፤ (ይበልጣልን ወይስ የሚያጋሩት) ከአላህ ጋር ሌላ አምላክ አለን ጥቂትንም አትገሠጹም፡፡'),
('27:63', 87, 'ወይም ያ በየብስና በባሕር ጨለማዎች ውስጥ የሚመራችሁ ነፋሶችንም ከዝናሙ በፊት አብሳሪ ኾነው የሚልክ (ይበልጣልን ወይስ የሚያጋሩት) ከአላህ ጋር ሌላ አምላክ አለን አላህ (በእርሱ) ከሚያጋሩዋቸው ሁሉ ላቀ፡፡'),
('27:64', 87, 'ወይም ያ መፍጠርን የሚጀምር ከዚያም የሚመልሰው ከሰማይና ከምድርም ሲሳይን የሚሰጣችሁ አምላክ (ይበልጣልን ወይስ የሚያጋሩት) ከአላህ ጋር ሌላ አምላክ አለን «እውነተኞች እንደኾናችሁ፤ አስረጃችሁን አምጡ» በላቸው፡፡'),
('27:65', 87, '«በሰማያትና በምድር ያለው ሁሉ ሩቅን ምስጢር አያውቅም፡፡ ግን አላህ (ያውቀዋል)፡፡ መቼ እንደሚቀሰቀሱም አያውቁም» በላቸው፡፡'),
('27:66', 87, 'በእውነት የመጨረሻይቱን ዓለም (ኹኔታ) ማወቃቸው ተሟላን አይደለም እነርሱ ከእርሷ በመጠራጠር ውስጥ ናቸው፡፡ በእውነትም እነርሱ ከእርሷ ዕውሮች ናቸው፡፡'),
('27:67', 87, 'እነዚያም የካዱት አሉ «እኛም አባቶቻችንም ዐፈር በኾን ጊዜ እኛ (ከመቃብር) የምንወጣ ነን'),
('27:68', 87, '«ይህንን እኛም ከፊት የነበሩት አባቶቻችንም በእርግጥ ተቀጥረንበታል፡፡ ይህ የመጀመሪያዎቹ ሰዎች ተረቶች እንጅ ሌላ አይደለም» (አሉ)፡፡'),
('27:69', 87, '«በምድር ላይ ኺዱ፡፡ የአመጸኞችም መጨረሻ እንዴት እንደ ነበረ ተመልከቱ» በላቸው፡፡'),
('27:70', 87, 'በእነሱም ላይ አትዘን፡፡ ከሚመክሩብህም ነገር በጭንቀት ውስጥ አትኹን፡፡'),
('27:71', 87, '«እውነተኞችም እንደ ኾናችሁ ይህ ቀጠሮ መቼ ነው» ይላሉ፡፡'),
('27:72', 87, '«የዚያ የምትቻኮሉበት ከፊሉ ለእናንተ የቀረበ መኾኑ ተረጋግጧል» በላቸው፡፡'),
('27:73', 87, 'ጌታህም በሰዎች ላይ በእርግጥ የችሮታ ባለቤት ነው፡፡ ግን አብዛኛዎቻቸው አያመሰግኑም፡፡'),
('27:74', 87, 'ጌታህም ልቦቻቸው የሚደብቁትንና የሚገልጹትን ያውቃል፡፡'),
('27:75', 87, 'በሰማይና በምድር ውስጥ ምንም የተደበቀ ነገር የለም ገላጭ በኾነው መጽሐፍ ውስጥ ያለ ቢኾን እንጅ፡፡'),
('27:76', 87, 'ይህ ቁርኣን በእስራኤል ልጆች ላይ የእነዚያን እነርሱ በእርሱ የሚለያዩበትን አብዛኛውን ይነግራል፡፡'),
('27:77', 87, 'እርሱም ለምእምናን መምሪያና እዝነት ነው፡፡'),
('27:78', 87, 'ጌታህ በመካከላቸው በትክክል ፍርዱ ይፈርዳል፡፡ እርሱም አሸናፊው ዐዋቂው ነው፡፡'),
('27:79', 87, 'በአላህም ላይ ተጠጋ፡፡ አንተ ግልጽ በኾነው እውነት ላይ ነህና፡፡'),
('27:80', 87, 'አንተ ሙታንን አታሰማም፡፡ ደንቆሮዎችንም የሚተው ኾነው በዞሩ ጊዜ ጥሪን አታሰማም፡፡'),
('27:81', 87, 'አንተም (ልበ) ዕውሮችን ከጥመታቸው አቅኚ አይደለህም፡፡ በአንቀጾቻችን የሚያምኑትን በስተቀር አታሰማም፡፡ እነርሱ ፍጹም ታዛዦች ናቸውና፡፡'),
('27:82', 87, 'በእነርሱም ላይ (የቅጣት) ቃሉ በተረጋገጠ ጊዜ ሰዎቹ በአንቀጾቻችን የማያረጋግጡ እንደነበሩ የምትነግራቸውን እንስሳ ለእነርሱ ከምድር እናወጣለን፡፡'),
('27:83', 87, 'ከሕዝቦቹም ሁሉ ባንቀፆቻችን የሚያስተባብሉትን ጭፍሮች የምንሰበስብበትን ቀን (አስታውስ)፡፡ እነሱም ይከመከማሉ፡፡'),
('27:84', 87, 'በመጡም ጊዜ (አላህ) ይላቸዋል «በአንቀጾቼ እርሷን በማወቅ ያላዳረሳችሁ ስትሆኑ አስተባበላችሁን ወይስ ምንን ትሠሩ ነበራችሁ»'),
('27:85', 87, 'በመበደላቸውም በእነርሱ ላይ ቃሉ ይፈጸምባቸዋል፡፡ እነርሱም አይናገሩም፡፡'),
('27:86', 87, 'እኛ ሌሊትን በእርሱ ውስጥ እንዲያርፉበት ቀንንም የሚያሳይ እንዳደረግን አያዩምን ለሚያምኑ ሕዝቦች በዚህ ውስጥ ተዓምራቶች አሉበት፡፡'),
('27:87', 87, 'በቀንዱም በሚነፋ ቀን በሰማያት ውስጥ ያሉትና በምድርም ውስጥ ያሉት ሁሉ አላህ የሻው ነገር ብቻ ሲቀር በሚደነግጡ ጊዜ (የሚኾነውን አስታውስ)፡፡ ሁሉም የተናነሱ ኾነውም ወደርሱ ይመጣሉ፡፡'),
('27:88', 87, 'ጋራዎችንም እርሷ እንደ ደመና አስተላለፍ የምታልፍ ስትኾን የቆመች ናት ብለህ የምታስባት ሆና ታያታለህ፡፡ የዚያን ነገሩን ሁሉ ያጠነከረውን የአላህን ጥበብ (ተመልከት)፡፡ እርሱ በምትሠሩት ሁሉ ውስጥ ዐዋቂ ነው፡፡'),
('27:89', 87, 'በመልካም ሥራ የመጣ ሰው ለእርሱ ከእርስዋ የበለጠ ምንዳ አልለው፡፡ እነርሱም በዚያ ቀን ከድንጋጤ ጸጥተኞች ናቸው፡፡'),
('27:90', 87, 'በመጥፎም የመጡ ሰዎች ፊቶቻቸው በእሳት ውስጥ ይደፋሉ፡፡ «ትሠሩት የነበራችሁትን እንጅ አትመነዱም» (ይባላሉ)፡፡'),
('27:91', 87, 'የታዘዝኩት የዚህችን አገር ጌታ ያንን ክልል ያደረጋትን እንድግገዛ ብቻ ነው፡፡ ነገሩንም ሁሉ የእርሱ ነው፡፡ ከሙስሊሞችም እንድኾን ታዝዣለሁ (በላቸው)፡፡'),
('27:92', 87, 'ቁርኣንንም እንዳነብ (ታዝዣለሁ)፡፡ የተመራም ሰው የሚመራው ለእራሱ ብቻ ነው፡፡ የተሳሳተም ሰው «እኔ ከአስጠንቃቂዎች ነኝ እንጅ ሌላ አይደለሁም» በለው፡፡'),
('27:93', 87, 'ምስጋናም ለአላህ ነው፡፡ ተዓምራቶቹን ወደፊት ያሳያችኋል፡፡ «ታውቋትምአላችሁ» በላቸው፡፡ ጌታህም ከምትሠሩት ሁሉ ዘንጊ አይደለም፡፡'),
('28:1', 87, 'ጠ.ሰ.መ (ጣ ሲን ሚም)፡፡'),
('28:2', 87, 'ይህቺ ገላጭ ከሆነው መጽሐፍ አንቀጾች ናት፡፡'),
('28:3', 87, 'ከሙሳና ከፈርዖን ዜና እውነተኞች ስንኾን ለሚያምኑ ሕዝቦች ባንተ ላይ እናነባለን፡፡'),
('28:4', 87, 'ፈርዖን በምድር ላይ ተንበጣረረ፡፡ ነዋሪዎቿንም የተከፋፈሉ ጓዶች አደረጋቸው፡፡ ከእነርሱ ጭፍሮችን ያዳክማል፡፡ ወንዶች ልጆቻቸውን በብዛት ያርዳል፡፡ ሴቶቻቸውንም ይተዋል፤ እርሱ ከሚያበላሹት ሰዎች ነበርና፡፡'),
('28:5', 87, 'በእነዚያም በምድር ውስጥ በተጨቆኑ ላይ ልንለግስ፣ መሪዎችም ልናደርጋቸው ወራሾችም ልናደርጋቸው እንሻለን፡፡'),
('28:6', 87, 'ለእነርሱም በምድር ላይ ልናስመች ፈርዖንንና ሃማንንም ሰራዊቶቻቸውንም ከእነሱ ይፈሩት የነበሩትን ነገር ልናሳያቸው (እንሻለን)፡፡'),
('28:7', 87, 'ወደ ሙሳም እናት «አጥቢው፣ በርሱም ላይ በፈራሽ ጊዜ በባሕሩ ውስጥ ጣይው አትፈሪም፣ አትዘኝም፣ እኛ ወዳንቺ መላሾቹና ከመልክተኞቹም አድራጊዎቹ ነንና» ማለትን አመለከትን፡፡'),
('28:8', 87, 'የፈርዖን ቤተሰቦችም (መጨረሻው) ለእነርሱ ጠላት ሐዘንም ይሆን ዘንድ አነሱት፡፡ ፈርዖንና ሃማንም ሰራዊቶቻቸውም ሀጢአተኞች ነበሩ፡፡'),
('28:9', 87, 'የፈርዖንም ሚስት «ለእኔ የዓይኔ መርጊያ ነው፡፡ ለአንተም፡፡ አትግደሉት፡፡ ሊጠቅመን ወይም ልጅ አድርገን ልንይዘው ይከጀላልና» አለች፡፡ እነርሱም (ፍጻሜውን) የማያውቁ ሆነው (አነሱት)፡፡'),
('28:10', 87, 'የሙሳም እናት ልብ ባዶ ሆነ፡፡ ከምእምናን ትሆን ዘንድ በልቧ ላይ ባላጠነከርን ኖሮ ልትገልጸው ቀርባ ነበር፡፡'),
('28:11', 87, 'ለእኅቱም ተከታተይው አለቻት፡፡ እርሱንም እነሱ የማያውቁ ሲሆኑ በሩቅ ሆና አየችው፡፡'),
('28:12', 87, '(ወደናቱ ከመመለሱ) በፊትም አጥቢዎችን (መጥባትን) በእርሱ ላይ እርም አደረግን፡፡ (እኅቱ) «ለእናንተ የሚያሳድጉላችሁን እነርሱም ለእርሱ ቅን አገልጋዮች የሆኑን ቤተሰቦች ላመልክታችሁን» አለችም፡፡'),
('28:13', 87, 'ወደእናቱም ዓይንዋ እንድትረጋ፣ እንዳታዝንም፣ የአላህም የተስፋ ቃል እርግጥ መሆኑን እንድታውቅ መለስነው፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('28:14', 87, 'ብርታቱንም በደረሰና በተስተካከለ ጊዜ ጥበብንና ዕውቀትን ሰጠነው፡፡ እንዲሁም መልካም ሠሪዎችን እንመነዳለን፡፡'),
('28:15', 87, 'ከተማይቱንም ሰዎቿ በዝንጋቴ ጊዜ ላይ ሆነው ሳሉ ገባ፡፡ በእርሷም ውስጥ የሚጋደሉን ሁለት ሰዎችን አገኘ፡፡ ይህ ከወገኑ ነው፤ ይህም ከጠላቱ ነው፡፡ ያም ከወገኑ የሆነው ሰው በዚያ ከጠላቱ በሆነው ሰው ላይ እርዳታን ጠየቀው፡፡ ሙሳም በጡጫ መታው፡፡ ገደለውም፡፡ ይህ ከሰይጣን ሥራ ነው፡፡ እርሱ ግልጽ አሳሳች ጠላት ነውና አለ፡፡'),
('28:16', 87, '«ጌታዬ ሆይ! እኔ ነፍሴን በደልኩ፡፡ ለእኔም ማር አለ፡፡» ለእርሱም ምሕረት አደረገለት እርሱ መሓሪ አዛኝ ነውና፡፡'),
('28:17', 87, '«ጌታዬ ሆይ! በእኔ ላይ በመለገስህ ይሁንብኝ (ከስህተቴ እጸጸታለሁ)፤ ለአመጸኞችም ፈጽሞ ረዳት አልሆንም አለ፡፡'),
('28:18', 87, 'በከተማይቱም ውስጥ ፈሪ የሚጠባበቅ ሆኖ አደረ፡፡ በድንገትም ያ ትላንት እርዳታን የጠየቀው ሰው በጩኸት እርዳታን ይጠይቀዋል፡፡ ሙሳ ለርሱ «አንተ በእርግጥ ግልጽ ጠማማ ነህ» አለው፡፡'),
('28:19', 87, '(ሙሳ) ያንን እርሱ ለሁለቱም ጠላት የሆነውን ሰው በኃይል ሊይዘው በፈለገም ጊዜ «ሙሳ'),
('28:20', 87, 'ከከተማይቱም ዳርቻ አንድ ሰው እየሮጠ መጣ፡፡ «ሙሳ ሆይ! ሹማምንቶቹ ሊገድሉህ ባንተ ይመካከራሉና ውጣ፡፡ እኔ ላንተ ከመካሪዎች ነኝና» አለው፡፡'),
('28:21', 87, 'የፈራና የሚጠባበቅ ሆኖም ከእርሷ ወጣ፡፡ «ጌታዬ ሆይ! ከበደለኞቹ ሕዝቦች አድነኝ» አለ፡፡'),
('28:22', 87, 'ወደ መድየን አቅጣጫ ፊቱን ባዞረ ጊዜም «ጌታዬ ቀጥተኛውን መንገድ ሊመራኝ እከጅላለሁ» አለ፡፡'),
('28:23', 87, 'ወደ መድየንም ውሃ በመጣ ጊዜ በእርሱ ላይ ከሰዎች ጭፍሮችን (መንጋዎቻቸውን) የሚያጠጡ ሆነው አገኘ፡፡ ከእነርሱ በታችም (ከውሃው መንጎቻቸውን) የሚከለክሉን ሁለት ሴቶች አገኘ፡፡ «ነገራችሁ ምንድን ነው» አላቸው፡፡ «እረኞቹ ሁሉ (መንጋዎቻቸውን) እስከሚመልሱ አናጠጣም፡፡ አባታችንም ትልቅ ሽማግሌ ነው» አሉት፡፡'),
('28:24', 87, 'ለሁለቱም አጠጣላቸው፡፡ ከዚያም ወደ ጥላው ዘወር አለ፡፡ «ጌታዬ ሆይ! እኔ ከመልካም ነገር ወደኔ ለምታወርደው ፈላጊ ነኝ» አለ፡፡'),
('28:25', 87, 'ከሁለቱ አንደኛይቱም ከሐፍረት ጋር የምትኼድ ሆና መጣችው፡፡ «አባቴ ለእኛ ያጠጣህልንን ዋጋ ሊሰጥህ ይጠራሃል» አለችው፡፡ ወደእርሱ በመጣና ወሬውን በእርሱ ላይ በተረከለትም ጊዜ «አትፍራ ከበደለኞቹ ሕዝቦች ድነሃል» አለው፡፡'),
('28:26', 87, 'ከሁለቱ አንደኛይቱም «አባቴ ሆይ ቅጠረው፡፡ ከቀጠርከው ሰው ሁሉ በላጩ ብርቱው ታማኙ ነውና» አለችው፡፡'),
('28:27', 87, '«ስምንትን ዓመታት ልታገለግለኝ እኔ ከእነዚህ ሁለት ሴቶቸ ልጆቼ አንዲቱን ላጋባህ እሻለሁ፡፡ ዐስርን ብትሞላም ከአንተ ነው፡፡ ባንተ ላይ ማስቸገርንም አልሻም፡፡ አላህ የሻ እንደ ኾነ ከመልካሞቹ ሰዎች ኾኜ ታገኘኛለህ» አለው፡፡'),
('28:28', 87, '(ሙሳም) «ይህ (ውለታ) በእኔና ባንተ መካከል (ረጊ) ነው፡፡ ከሁለቱ ጊዜያቶች ማንኛውንም ብፈጽም በእኔ ላይ ወሰን ማለፍ የለም፡፡ አላህም በምንለነው ላይ ምስክር» ነው አለ፡፡'),
('28:29', 87, 'ሙሳም ጊዜውን በጨረሰና ከቤተሰቦቹ ጋር በኼደ ጊዜ ከጡር ተራራ ጎን እሳትን አየ፡፡ ለቤተሰቡ (እዚህ) «ቆዩ፡፡ እኔ እሳትን አየሁ፡፡ ከእርሷ ወሬን ወይም ትሞቁ ዘንድ ከእሳት ትንታግን አመጣላችኋለሁ» አለ፡፡'),
('28:30', 87, 'በመጣትም ጊዜ ከሸለቆው ቀኝ ዳርቻ ከዛፊቱ በኩል በተባረከችው ስፍራ ውስጥ «ሙሳ ሆይ! እኔ የዓለማት ጌታ አላህ እኔ ነኝ» በማለት ተጠራ፡፡'),
('28:31', 87, '«በትርህንም ጣል» (ተባለ)፡፡ እንደ ትንሽ እባብ ስትስለከለክ ባያትም ጊዜ ወደ ኋላ ዞሮ ሸሸ፤ አልተመለሰምም፡፡ «ሙሳ ሆይ! ተመለስ አትፍራም፤ አንተ ከጥብቆቹ ነህና» (ተባለም)፡፡'),
('28:32', 87, '«እጅህን በአንገትጌህ ውስጥ አግባ፡፡ ያለ ነውር ነጭ ሆና ትወጣለችና፡፡ ክንፍህንም ከፍርሃት (ለመዳን) ወዳንተ አጣብቅ፡፡ እነዚህም ከጌታህ የሆኑ ወደ ፈርዖንና ወደ መኳንንቶቹ የሚደርሱ ሁለት አስረጅዎች ናቸው፡፡ እነርሱ አመጸኞች ሕዝቦች ነበሩና፡፡»'),
('28:33', 87, '(ሙሳ) አለ «ጌታዬ ሆይ! እኔ ከእነርሱ ነፍስን ገድያለሁ፡፡ ስለዚህ እንዳይገድሉኝ እፈራለሁ፡፡'),
('28:34', 87, '«ወንድሜም ሃሩን እርሱ ምላሱ ከእኔ የተባ ነው፡፡ እውነተኛነቴንም የሚያረጋግጥልኝ ረዳት ኾኖ ከእኔ ጋር ላከው፡፡ እኔ ሊያስተባብሉኝ እፈራለሁና፡፡»'),
('28:35', 87, '(አላህም) «ጡንቻህን በወንድምህ በእርግጥ እናበረታለን፡፡ ለሁለታችሁም ስልጣንን እናደርጋለን፡፡ ወደእናንተም (በመጥፎ) አይደርሱም፡፡ በተዓምራቶቻችን (ኺዱ)፡፡ እናንተና የተከተላችሁም ሁሉ አሸናፊዎች ናችሁ» አላቸው፡፡'),
('28:36', 87, 'ሙሳም በታምራቶቻችን ግልጽ ኾነው በመጣባቸው ጊዜ «ይህ የተቀጠፈ ድግምት እንጅ ሌላ አይደለም፡፡ ይህንንም በመጀመሪያዎቹ አባቶቻችን ውስጥ አልሰማንም» አሉ፡፡'),
('28:37', 87, 'ሙሳም «ጌታዬ ከእርሱ ዘንድ በቀጥታው መንገድ የመጣውን ሰው ምስጉኒቱም አገር ለእርሱ የምትኾንለትን ሰው ዐዋቂ ነው፡፡ እነሆ በደለኞቹ አይድኑም» አለ፡፡'),
('28:38', 87, 'ፈርዖንም «እናንተ ጭፍሮች ሆይ! ከእኔ ሌላ ለእናንተ አምላክን ምንም አላወቅሁም፡፡ ሃማንም ሆይ! ጭቃን ለእኔ አቃጥልልኝ፤ (ጡብ ሥራልኝ)፡፡ ለእኔም ከፍተኛ ሕንጻን ሥራልኝ፡፡ ወደ ሙሳ አምላክ ልወጣ እከጅላለሁና፡፡ እኔም ከውሸታሞቹ መኾኑን እጠረጥረዋለሁ» አለ፡፡'),
('28:39', 87, 'እርሱም ሰራዊቶቹም በምድር ላይ ያለ አግባብ ኮሩ፡፡ እነርሱም ወደእኛ የማይመለሱ መኾናቸውን ጠረጠሩ፡፡'),
('28:40', 87, 'እርሱንም ሰራዊቱንም በጥብቅ ያዝናቸው፡፡ በባሕርም ውስጥ ጣልናቸው፡፡ የበደለኞች መጨረሻም፤ እንዴት እንደ ነበረ ተመልከት፡፡'),
('28:41', 87, 'ወደ እሳት የሚጠሩ መሪዎችም አደረግናቸው፡፡ በትንሣኤም ቀን አይርረዱም፡፡'),
('28:42', 87, 'በይህችም በቅርቢቱም ዓለም ውስጥ እርግማንን አስከተልናቸው፡፡ በትንሣኤም ቀን እነሱ ከሚባረሩት ናቸው፡፡'),
('28:43', 87, 'የፊተኞቹን የክፍለ ዘመናት ሕዝቦችም ከአጠፋን በኋላ ለሰዎች የልብ ብርሃን መሪም እዝነትም ሲኾን ይገሰጹ ዘንድ ለሙሳ መጽሐፉን በእርግጥ ሰጠነው፡፡'),
('28:44', 87, 'ወደ ሙሳም ትዕዛዝን ባወረድንለት ጊዜ (ከተራራው) በምዕራባዊው ጎን አልነበርክም ከተጣዱትም አልነበርክም፡፡'),
('28:45', 87, 'ግን እኛ (ከእርሱ በኋላ) የክፍለ ዘመናትን ሰዎች አስገኘን፡፡ በእነሱም ላይ ዕድሜዎች ተራዘሙ፡፡ በመድየንም ሰዎች ውስጥ ተቀማጭ በእነሱ ላይ አንቀጾቻችን የምታነብ አልነበርክም፡፡ ግን እኛ ላኪዎችህ ኾንን፡፡'),
('28:46', 87, 'በጠራነውም ጊዜ በጡር ጎን አልነበርክም፡፡ ግን ከአንተ በፊት ምንም አስፈራሪ ያልመጣቸውን ሕዝቦች ታስፈራራ ዘንድ ከጌታህ በኾነ ችሮታ (ላክንህ) ሊገሰጹ ይከጀላልና፡፡'),
('28:47', 87, 'እጆቻቸውም ባሳለፉት ምክንያት መከራ የምትነካቸውና «ጌታችን ሆይ! አንቀጾችህን እንድንከተል ከምእምናንም እንድንኾን ወደኛ መልክተኛን አትልክም ኖሯልን» የሚሉ ባልኾኑ ኖሮ (አንልክም ነበር)፡፡'),
('28:48', 87, 'እውነቱም ከእኛ ዘንድ በመጣላቸው ጊዜ «ለሙሳ የተሰጠው ብጤ አይስሰጠውም ኖሯልን» አሉ፡፡ «ከዚህ በፊት ሙሳ በተሰጠው አልካዱምን የተረዳዱ ሁለት ድግምቶች ናቸው» አሉ፡፡'),
('28:49', 87, '«ከአላህ ዘንድ የኾነን መጽሐፍ እርሱ ከሁለቱም ይበልጥ ቅን የኾነን አምጡ፡፡ እውነተኞች እንደ ኾናችሁ (ብታመጡት) እከተለዋለሁ» በላቸው፡፡'),
('28:50', 87, 'እሺ ባይሉህም፤ የሚከተሉት፤ ዝንባሌዎቻቸውን ብቻ መኾኑን ዕወቅ፡፡ ከአላህም የኾነ መመሪያ ሳይኖረው ዝንባሌውን ከተከተለ ሰው ይበልጥ የጠመመ አንድም የለም፡፡ አላህ በደለኞች ሕዝቦችን አይመራምና፡፡'),
('28:51', 87, 'ይገሰጹም ዘንድ ቃልን (ቁርኣንን በያይነቱ) ለእነርሱ በእርግጥ አስከታተልን፡፡'),
('28:52', 87, 'እነዚያ ከእርሱ በፊት መጽሐፍን የሰጠናቸው እነርሱ በእርሱ ያምናሉ፡፡'),
('28:53', 87, 'በእነሱ ላይ በሚነበብላቸውም ጊዜ «በእርሱ አምነናል፡፡ እርሱ ከጌታችን የኾነ እውነት ነው፡፡ እኛ ከርሱ በፊት ሙስሊሞች ነበርን» ይላሉ፡፡'),
('28:54', 87, 'እነዚያ በመታገሳቸው ዋጋቸውን ሁለት ጊዜ ይስሰጣሉ፡፡ ክፉውንም ነገር በበጎ ምግባር ይገፈትራሉ፡፡ ከሰጠናቸውም ሲሳይ ይለግሳሉ፡፡'),
('28:55', 87, 'ውድቅንም ቃል በሰሙ ጊዜ ከእርሱ ይርቃሉ፡፡ «ለእኛ ሥራዎቻችን አሉን፡፡ ለናንተም ሥራዎቻችሁ አሏችሁ፡፡ ሰላም በእናንተ ላይ (ይኹን) ባለጌዎችን አንፈልግም» ይላሉ፡፡'),
('28:56', 87, 'አንተ የወደድከውን ሰው ፈጽሞ አታቀናም፡፡ ግን አላህ የሚሻውን ሰው ያቀናል እርሱም ቅኖቹን ዐዋቂ ነው፡፡'),
('28:57', 87, '«ከአንተ ጋር ቅንን መንገድ ብንከተል ከምድራችን እንባረራለን» አሉም፡፡ ከእኛ ዘንድ (የተሰጠ) ሲሳይ ሲሆን የነገሩ ሁሉ ፍሬዎች ወደእርሱ የሚነዱበትን ጸጥተኛ ክልል (መካን) ለእነሱ አላስመቸናቸውምን ግን አብዛኞቻቸው አያውቁም፡፡'),
('28:58', 87, 'ከከተማም ኑሮዋን (ምቾቷን) የካደችን (ከተማ) ያጠፋናት ብዙ ናት፡፡ እነዚህም ከእነሱ በኋላ ጥቂት ጊዜ እንጅ ያልተኖረባቸው ሲኾኑ መኖሪያዎቻቸው ናቸው፡፡ እኛም (ከእነርሱ) ወራሾች ነበርን፡፡'),
('28:59', 87, 'ጌታህም ከተሞችን በዋናዋ (ከተማ) ውስጥ አንቀጾቻችንን በእነሱ ላይ የሚያነብ መልክተኛን እስከሚልክ ድረስ አጥፊ አልነበረም፡፡ ከተሞችንም ባለቤቶቿ በዳዮች ሆነው እንጅ አጥፊዎች አልነበርንም፡፡'),
('28:60', 87, 'ከማንኛውም ነገር የተሰጣችሁት፤ የቅርቢቱ ሕይወት ጥቅምና ጌጧ ነው፡፡ አላህ ዘንድ ያለውም (ምንዳ) በጣም በላጭና ዘውታሪ ነው አታውቁምን'),
('28:61', 87, 'መልካምን ተስፋ ቃል የገባንለትና እርሱም አግኚው የሆነ ሰው የቅርቢቱን ሕይወት ጥቅም እንዳስመቸነውና ከዚያም እርሱ በትንሣኤ ቀን (ለእሳት) ከሚቀረቡት እንደ ኾነው ሰው ነውን'),
('28:62', 87, '(አላህ) የሚጠራባቸውንና እነዚያ ተጋሪዎቼ ትሏቸው የነበራችሁት የት ናቸው የሚልበትን ቀን (አስታውስ)፡፡'),
('28:63', 87, 'እነዚያ በእነርሱ ላይ ቃሉ የተረጋገጠባቸው ይላሉ «ጌታችን ሆይ! እነዚህ እነዚያ ያጠመምናቸው ናቸው፡፡ እንደጠመምን አጠመምናቸው፡፡ (ከእነሱ) ወዳንተ ተጥራራን፡፡ እኛን ይግገዙ አልነበሩም፡፡'),
('28:64', 87, '«(ለአላህ) የምታጋሯቸውንም ጥሩ» ይባላሉ፤ ይጠሯቸዋልም፡፡ ግን ለእነርሱ አይመልሱላቸውም፡፡ ቅጣቱንም ያያሉ፡፡ እነርሱ ይመሩ በነበሩ ኖሮ (አያዩትም ነበር)፡፡'),
('28:65', 87, '«የሚጠራባቸውንና ለመልክተኞቹም ምንን መለሳችሁ» የሚልበትን ቀን (አስታውስ)፡፡'),
('28:66', 87, 'በዚያም ቀን ወሬዎቹ ሁሉ በእነርሱ ላይ ይሰውሩባቸዋል፡፡ እነርሱም አይጠያየቁም፡፡'),
('28:67', 87, 'የተጸጸተና ያመነ ሰውማ መልካምንም የሠራ ከሚድኑት ሊኾን ይከጀላል፡፡'),
('28:68', 87, 'ጌታህም የሚሻውን ይፈጥራል፤ ይመርጣልም፡፡ ለእነርሱ (ለሰዎቹ) ምርጫ የላቸውም፡፡ አላህ ከማይግገባው ሁሉ ጠራ፡፡ ከሚያጋሯቸውም ላቀ፡፡'),
('28:69', 87, 'ጌታህም ልቦቻቸው የሚደብቁትንና የሚገልጹትን ሁሉ ያውቃል፡፡'),
('28:70', 87, 'እርሱም አላህ ነው፡፡ ከእርሱ ሌላ አምላክ የለም፡፡ ምስጋና በመጀመሪያይቱም በመጨረሻይቱም ዓለም ለእርሱ ብቻ ነው፡፡ ፍርዱም የእርሱ ብቻ ነው፡፡ ወደእርሱም ትመለሳላችሁ፡፡'),
('28:71', 87, 'አያችሁን (ንገሩኝ) «አላህ በእናንተ ላይ ሌሊትን እስከ ትንሣኤ ቀን ድረስ ዘውታሪ ቢያደርገው ከአላህ ሌላ ብርሃንን የሚያመጣላችሁ አምላክ ማነው አትሰሙምን» በላቸው፡፡'),
('28:72', 87, 'አያችሁን «አላህ በእናንተ ላይ ቀንን እስከ ትንሣኤ ቀን ድረስ ዘውታሪ ቢያደርገው ከአላህ ሌላ በውስጡ የምታርፉበትን ሌሊት የሚያመጣላችሁ አምላክ ማን ነው (ንገሩኝ) አታስተውሉምን» በላቸው፡፡'),
('28:73', 87, 'ከችሮታውም ለእናንተ ሌሊትንና ቀንን በውስጡ ልታርፉበት፣ ከትሩፋቱም ልትፈልጉበት፣ አመስገኞችም ልትኾኑ አደረገላችሁ፡፡'),
('28:74', 87, 'የሚጠራባቸውንም ቀንና «እነዚያ ተጋሪዎቼ ትሏቸው የነበራችሁት የት ናቸው» የሚልበትን (አስታውስ)፡፡'),
('28:75', 87, 'ከሕዝቦችም ሁሉ መስካሪን እናወጣለን፡፡ (ያን ጊዜ) እውነተኛውም አምላክነት ለአላህ ብቻ መኾኑን ያውቃሉ፡፡ ይቀጣጥፉት የነበሩትም ከእነርሱ ይጠፋቸዋል፡፡'),
('28:76', 87, 'ቃሩን ከሙሳ ነገዶች ነበር፡፡ በእነርሱም ላይ አመጸ፡፡ ከድልቦችም ያንን መከፈቻዎቹ ብቻ የኃይል ባለቤቶች የኾኑ ጭፍሮችን (ሸክሙ) የሚከብድን ሰጠነው፡፡ ወገኖቹ ለእርሱ አትኩራ፤ አላህ ኩራተኞችን አይወድምና ባሉት ጊዜ (አስታውስ)፡፡'),
('28:77', 87, '«አላህም በሰጠህ ሀብት የመጨረሻይቱን አገር ፈልግ፡፡ ከቅርቢቱም ዓለም ፋንታህን አትርሳ፡፡ አላህም ወደ አንተ መልካምን እንዳደረገልህ (ለሰዎች) መልካምን አድርግ፡፡ በምድርም ውስጥ ማጥፋትን አትፈልግ፡፡ አላህ አጥፊዎችን አይወድምና» (አሉት)፡፡'),
('28:78', 87, '(ሀብቱን) «የተሰጠሁት እኔ ዘንድ ባለው እውቀት ብቻ ነው አለ፡፡ አላህ ከእርሱ በፊት ከክፍለ ዘመናት ሰዎች በኀይል ከእርሱ ይበልጥ የበረቱትን (ሀብትን) በመሰብሰብም ይበልጥ የበዙትን በእርግጥ ያጠፋ መኾኑን አያውቅምን አመጸኞችም ከኀጢኣቶቻቸው (ምሕረት የሚከተለውን ጥያቄ) አይጠየቁም፡፡'),
('28:79', 87, 'በሕዝቦቹም ላይ በጌጡ ውስጥ ኾኖ ወጣ፡፡ እነዚያ ቅርቢቱን ሕይወት የሚፈልጉት «ወይ ምኞታችን! ቃሩን የተሰጠው ብጤ ምነው ለእኛ በኖረን፤ እርሱ የታላቅ ዕድል ባለቤት ነውና» አሉ፡፡'),
('28:80', 87, 'እነዚያም ዕውቀትን የተሰጡት «ወዮላችሁ! የአላህ ምንዳ ለአመነ ሰው መልካምንም ለሠራ በላጭ ነው፡፡ ታጋሾችም እንጅ ሌላው አያገኛትም» አሉ፡፡'),
('28:81', 87, 'በእርሱም በቤቱም ምድርን ደረባን፡፡ ለእርሱም ከአላህ ሌላ የሚረዱት ጭፍሮች ምንም አልነበሩትም፡፡ ከሚርረዱትም አልነበረም፡፡'),
('28:82', 87, 'እነዚያም በትላንትናው ቀን ስፍራውን ይመኙ የነበሩት «ወይ ጉድ! ለካ አላህ ከባሮቹ ለሚሻው ሰው ሲሳይን ያሰፋል፤ ያጠባልም፡፡ አላህ በእኛ ላይ (በእምነት) ባልለገሰልን ኖሮ ምድርን በእኛ ላይ በገለበጠብን ነበር፡፡ ወይ ጉድ! ከሓዲዎች አይድኑም» የሚሉ ኾነው አነጉ፡፡'),
('28:83', 87, 'ይህች የመጨረሻይቱ አገር ለእነዚያ በምድር ውስጥ ኩራትንና ማመፅን ለማይፈልጉት እናደርጋታለን፡፡ ምስጉኒቱም መጨረሻ ለጥንቁቆቹ ናት፡፡'),
('28:84', 87, 'በደግ ሥራ የመጣ ሰው ለእርሱ ከእርሷ በላጭ ምንዳ አልለው፡፡ በክፉም ሥራ የመጡ ሰዎች እነዚህ መጥፎዎችን የሠሩ ይሠሩት የነበሩትን እንጅ አይመነዱም፡፡'),
('28:85', 87, 'ያ ቁርኣንን የተከፋፈለ ኾኖ ባንተ ላይ ያወረደው (አምላክ) ወደ መመለሻ (ወደመካ) በእርግጥ መላሽህ ነው፡፡ «ጌታዬ በቅን መንገድ የመጣውን ሰውና እርሱም በግልጽ ስሕተት ውስጥ የኾነውን ሰው ዐዋቂ ነው» በላቸው፡፡'),
('28:86', 87, 'መጽሐፉ ወዳንተ መወረዱን ተስፋ የምታደርግ አልነበርክም፡፡ ግን ከጌታህ ችሮታ (ተወረደልህ)፡፡ ለከሓዲዎችም በፍጹም ረዳት አትኹን፡፡'),
('28:87', 87, 'ከአላህም አንቀጾች ወዳንተ ከተወረዱ ጊዜ በኋላ አያግዱህ፡፡ ወደ ጌታህም (ሰዎችን) ጥራ፡፡ ከአጋሪዎቹም አትኹን፤'),
('28:88', 87, 'ከአላህም ጋር ሌላን አምላክ አትግገዛ፡፡ ከእርሱ በቀር አምላክ የለም፡፡ ነገሩ ሁሉ ከአላህ በቀር ጠፊ ነው፡፡ ፍርዱ የርሱ፤ ብቻ ነው፡፡ ወደእርሱም ትመለሳላችሁ፡፡'),
('29:1', 87, 'አ.ለ.መ (አሊፍ ላም ሚም)'),
('29:2', 87, 'ሰዎቹ አምነናል በማለታቸው ብቻ እነሱ ሳይፈተኑ የሚተው መኾናቸውን ጠረጠሩን'),
('29:3', 87, 'እነዚያንም ከእነሱ በፊት የነበሩትን በእርግጥ ፈትነናል፡፡ እነዚያንም እውነት የተናገሩትን አላህ በእርግጥ ያውቃል፡፡ ውሸታሞቹንም ያውቃል፡፡'),
('29:4', 87, 'ይልቁንም እነዚያ መጥፎዎችን ሥራዎች የሚሠሩት ሊያመልጡን ይጠረጥራሉን ያ የሚፈርዱት (ፍርድ) ከፋ፡፡'),
('29:5', 87, 'የአላህን መገናኘት ተስፋ የሚያደርግ ሰው (ይዘጋጅ)፡፡ የአላህ ቀጠሮ በእርግጥ መጪ ነውና፡፡ እርሱም ሰሚው ዐዋቂው ነው፡፡'),
('29:6', 87, 'የታገለ ሰውም የሚታገለው ለነፍሱ ነው፡፡ አላህ ከዓለማት በእርግጥ ተብቃቂ ነውና፡፡'),
('29:7', 87, 'እነዚያም ያመኑ፤ መልካሞችንም የሠሩ መጥፎዎቹን ሥራዎቻቸውን ከእነሱ ላይ እናብስላቸዋለን፡፡ በዚያም ይሠሩት በነበሩት መልካም ሥራ በእርግጥ እንመነዳቸዋለን፡፡'),
('29:8', 87, 'ሰውንም በወላጆቹ መልካም አድራጎትን አዘዝነው፡፡ ላንተም በእርሱ ዕውቀት የሌለህን (ጣዖት) በእኔ እንድታጋራ ቢታገሉህ አትታዘዛቸው፡፡ መመለሻችሁ ወደኔ ነው፡፡ ትሠሩት የነበራችሁትንም ሁሉ እነግራችኋለሁ፡፡'),
('29:9', 87, 'እነዚያንም ያመኑ፤ መልካም ሥራዎችንም የሠሩ በደጋጎቹ ውስጥ በእርግጥ እናገባቸዋለን፡፡'),
('29:10', 87, 'ከሰዎችም በአላህ አመንን የሚል ሰው አልለ፡፡ በአላህም (በማመኑ) በተሰቃየ ጊዜ የሰዎችን ማሰቃየት እንደ አላህ ቅጣት ያደርጋል፡፡ ከጌታህም እርዳታ ቢመጣ እኛ በእርግጥ ከእናንተ ጋር ነበርን ይላሉ፡፡ አላህ በዓለማት ሕዝብ ልቦች ውስጥ ያለውን ሁሉ ዐዋቂ አይደለምን'),
('29:11', 87, 'አላህም እነዚያን ያመኑትን በእርግጥ ያውቃል፡፡ መናፍቆቹንም ያውቃል፡፡'),
('29:12', 87, 'እነዚያም የካዱት ሰዎች ለእነዚያ ላመኑት «መንገዳችንን ተከተሉ፤ ኀጢአቶቻችሁንም እንሸከማለን» አሉ፡፡ እነርሱም ከኀጢአቶቻቸው ምንንም ተሸካሚዎች አይደሉም፡፡ እነርሱ በእርግጥ ውሸታሞች ናቸው፡፡'),
('29:13', 87, 'ሸክሞቻቸውንና ከሸክሞቻቸው ጋር (ሌሎች) ሸክሞችንም በእርግጥ ይሸከማሉ፡፡ በትንሣኤም ቀን ይቀጥፉት ከነበሩት በእርግጥ ይጠየቃሉ፡፡'),
('29:14', 87, 'ኑሕንም ወደ ሕዝቦቹ በእርግጥ ላክነው፡፡ በውስጣቸውም ሺህ ዓመትን አምሳ ዓመት ሲቀር ተቀመጠ፡፡ እነርሱ በዳዮች ኾነውም የውሃው ማጥለቅለቅ ያዛቸው፡፡'),
('29:15', 87, 'ኑሕንና የመርከቢቱንም ጓዶች አዳናቸው፡፡ እርሷንም ለዓለማት ተዓምር አደረግናት፡፡'),
('29:16', 87, 'ኢብራሂምንም ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፡፡ «አላህን ተገዙ ፍሩትም፡፡ ይህ የምታውቁ ብትሆኑ ለእናንተ በላጭ ነው፡፡'),
('29:17', 87, '«ከአላህ ሌላ የምትገዝዙት ጣዖታትን ብቻ ነው፡፡ ውሸትንም ትቀጣጥፋላችሁ፡፡ እነዚያ ከአላህ ሌላ የምትግገዙዋቸው ለእናንተ ሲሳይን ሊሰጧችሁ አይችሉም፡፡ ስለዚህ ሲሳይን ከአላህ ዘንድ ብቻ ፈልጉ፡፡ ተገዙትም፡፡ ለእርሱም አመሰግኑ፡፡ ወደእርሱ ትመለሳላችሁ፡፡'),
('29:18', 87, '«ብታስተባብሉም ከፊታችሁ የነበሩት ሕዝቦች በእርግጥ አስተባብለዋል፡፡ በመልክተኛውም ላይ ግልጽ ማድረስ እንጂ ሌላ የለበትም፡፡»'),
('29:19', 87, 'አላህ መፍጠርን እንዴት እንደሚጀመር ከዚያም እንዴት እንደሚመልሰው አይመለከቱምን ይህ በአላህ ላይ ቀላል ነው፡፡'),
('29:20', 87, '«፡--በምድር ላይ ኺዱ፤ መፍጠርንም እንዴት እንደ ጀመረ ተመልከቱ፡፡ ከዚያም፤ አላህ የመጨረሻይቱን መነሳት ያስነሳል፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነውና» በላቸው፡፡'),
('29:21', 87, 'የሚሻውን ሰው ይቀጣል፡፡ የሚሻውንም ሰው ያዝንለታል፡፡ ወደእርሱም ትመለሳላችሁ፡፡'),
('29:22', 87, 'እናንተም በምድርም ኾነ በሰማይ የምታቅቱ አይደላችሁም፡፡ ከአላህም ሌላ ረዳትም ተከላካይም ምንም የላችሁም፡፡'),
('29:23', 87, 'እነዚያም በአላህ አንቀጾችና በመገናኘቱ የካዱ እነዚያ ከእዝነቴ ተስፋን ቆረጡ፡፡ እነዚያም ለእነሱ አሳማሚ ቅጣት አላቸው፡፡'),
('29:24', 87, 'የሕዝቦቹም መልስ፡- «ግደሉት፤ ወይም አቃጥሉት» ማለት እንጂ ሌላ አልነበረም፡፡ ከእሳቲቱም አላህ አዳነው፡፡ በዚህ ውስጥ ለሚያምኑ ሕዝቦች ተዓምራቶች አሉበት፡፡'),
('29:25', 87, '(ኢብራሂም) አለም «ከአላህ ሌላ ጣዖታትን (አማልክት) የያዛችሁት በቅርቢቱ ሕይወት በመካከላችሁ ለመዋደድ ብቻ ነው፡፡ ከዚያም በትንሣኤ ቀን ከፊላቸሁ በከፊሉ ይክዳል፡፡ ከፊላችሁም ከፊሉን ይረግማል፡፡ መኖሪያችሁም እሳት ናት፡፡ ለእናንተም ከረዳቶች ምንም የላችሁም፡፡»'),
('29:26', 87, 'ሉጥም ለእርሱ አመነ፤ (ኢብራሂም) «እኔ ወደ ጌታዬ ተሰዳጅ ነኝ፡፡ እነሆ እርሱ አሸናፊው ጥበበኛው ነውና» አለም፡፡'),
('29:27', 87, 'ለእርሱም ኢስሐቅንና ያዕቆብን ሰጠነው፡፡ በዘሩም ውስጥ ነብይነትንና መጽሐፍን አደረግን፡፡ ምንዳውንም በቅርቢቱ ዓለም ሰጠነው፡፡ እርሱም በመጨረሻይቱ ዓለም ከደጋጎቹ ነው፡፡'),
('29:28', 87, 'ሉጥንም ለሕዝቦቹ ባለ ጊዜ (አስታውስ) «እናንተ ጠያፍን ስራ ትሠራላችሁን በእርሷ ከዓለማት አንድም አልቀደማችሁም፡፡'),
('29:29', 87, '«እናንተ በእርግጥ ወንዶችን ትመጣላችሁን መንገድንም ትቆርጣላችሁን በሸንጓችሁም የሚነወርን ነገር ትሠራላችሁን» (አላቸው)፡፡ የሕዝቦቹም መልስ «ከእውነተኞቹ እንደ ሆንክ የአላህን ቅጣት አምጣብን» ማለት እንጂ ሌላ አልነበረም፡፡'),
('29:30', 87, '«ጌታዬ ሆይ! በአመጸኞች ሕዝቦች ላይ እርዳኝ» አለ፡፡'),
('29:31', 87, 'መልክተኞቻችንም ኢብራሂምን በብስራት በመጡት ጊዜ «እኛ የዚህችን ከተማ ሰዎች አጥፊዎች ነን፡፡ ሰዎቿ በዳዮች ነበሩና» አሉት፡፡'),
('29:32', 87, '«በእርሷ ውስጥ ሉጥ አለ እኮ» አላቸው፡፡ «እኛ በውስጧ ያለውን ይበልጥ ዐዋቂ ነን፡፡ (እርሱን) በእርግጥ እናድነዋለን፡፡ ቤተሰቦቹንም ጭምር፡፡ ሚስቱ ብቻ ስትቀር፡፡ እርሷ በጥፋቱ ውስጥ ከሚቀሩት ናት» አሉት፡፡'),
('29:33', 87, 'መልክተኞቻችንም ሉጥን በመጡት ጊዜ በእነሱ ምክንያት አዘነ፡፡ በእነርሱም ልቡ ተጨነቀ፡፡ «አትፍራ፤ አትዘንም፡፡ እኛ አዳኞችህ ነን፡፡ ቤተሰቦችህንም፤ ሚስትህ ብቻ ስትቀር፡፡ እርሷ በጥፋቱ ውስጥ ከቀሪዎቹ ናት» አሉትም፡፡'),
('29:34', 87, '«እኛ በዚህች ከተማ ሰዎች ላይ ያምጹ በነበሩት ምክንያት ከሰማይ ቅጣትን አውራጆች ነን፡፡»'),
('29:35', 87, 'በእርግጥም ለሚያስቡ ሰዎች ከእርሷ ግልጽ ምልክትን ተውን (አስቀረን)፡፡'),
('29:36', 87, 'ወደ መድየንም ወንድማቸውን ሹዐይብን (ላክን)፡፡ «ሕዝቦቼ ሆይ! አላህን ተገዙ፣ የመጨረሻውንም ቀን ፍሩ፣ በምድርም ውስጥ የምታጠፉ ሆናችሁ አታበላሹ አላቸውም፡፡'),
('29:37', 87, 'አስተባባሉትም፡፡ የምድር መንቀጥቀጥ ያዘቻቸው፡፡ በሃገራቸውም ውስጥ ተንከፍርረው አነጉ፡፡'),
('29:38', 87, 'ዓድንና ሰሙድንም (አጠፋን)፡፡ ከመኖሪያዎቻቸውም (ፍርስራሾች በኩል መጥፋታቸው) ለእናንተ በእውነት ተገለጠላችሁ፡፡ ሰይጣንም ሥራዎቻቸውን ለእነርሱ ሸለመላቸው፡፡ ከመንገድም አገዳቸው፡፡ የማስተዋልም ባለቤቶች ነበሩ፤ (ግን አላስተዋሉም)፡፡'),
('29:39', 87, 'ቃሩንንም ፈርዖንንም ሃማንንም (አጠፋን)፡፡ ሙሳም በተዓምራቶች በእርግጥ መጣባቸው፡፡ በምድርም ላይ ኮሩ፡፡ አምላጪዎችም አልነበሩም፡፡'),
('29:40', 87, 'ሁሉንም በኅጢኣቱ ያዝነው፡፡ ከእነሱም ውስጥ ጠጠርን ያዘለ ነፋስን የላክንበት አልለ፡፡ ከእነሱም ውስጥ ጩኸት የያዘችው አልለ፡፡ ከእነርሱም ውስጥ በእርሱ ምድርን የደረባንበት አልለ፡፡ ከእነሱም ውስጥ ያሰጠምንው አልለ፡፡ አላህም የሚበድላቸው አልነበረም፡፡ ግን ነፍሶቻቸውን የሚበድሉ ነበሩ፡፡'),
('29:41', 87, 'የእነዚያ ከአላህ ሌላ ረዳቶችን (ጣዖታትን) የያዙ ሰዎች ምሳሌ ቤትን እንደ ሠራች ሸረሪት ብጤ ነው፡፡ ከቤቶችም ሁሉ በጣም ደካማው የሸረሪት ቤት ነው፡፡ ቢያውቁ ኖሮ (አማልክት አድርገው አይግገዟቸውም ነበር)፡፡'),
('29:42', 87, 'አላህ ያንን ከእርሱ ሌላ የሚግገዙትን ማንኛውንም ያውቃል፡፡ እርሱም አሸናፊው ጥበበኛው ነው፡፡'),
('29:43', 87, 'እነዚህንም ምሳሌዎች ለሰዎች እንገልጻቸዋለን፡፡ ከሊቃውንቶቹም በስተቀር ሌሎቹ አያውቋትም፡፡'),
('29:44', 87, '«አላህ ሰማያትንና ምድርን እውነተኛ ሆኖ ፈጠረ፡፡» በዚህ ውስጥ ለምእምናን ተዓምር አለበት፡፡'),
('29:45', 87, 'ከመጽሐፍ ወደ አንተ የተወረደውን አንብብ፡፡ ሶላትንም ደንቡን ጠብቀህ ስገድ፡፡ ሶላት ከመጥፎና ከሚጠላ ነገር ሁሉ ትከለክላለችና፡፡ አላህንም ማውሳት ከሁሉ ነገር በላጭ ነው፤ አላህም የምትሠሩትን ሁሉ ያውቃል፡፡'),
('29:46', 87, 'የመጽሐፉን ባለቤቶችም በዚያች እርሷ መልካም በኾነችው ክርክር እንጂ አትከራከሩ፡፡ ከእነርሱ እነዚያን የበደሉትን ሲቀር፡፡ በሉም «በዚያ ወደኛ በተወረደው ወደናንተም በተወረደው አመንን፡፡ አምላካችንም አምላካችሁም አንድ ነው፡፡ እኛም ለእርሱ ታዛዦች ነን፡፡»'),
('29:47', 87, 'እንደዚሁም ወዳንተ መጽሐፍን አወረድን፡፡ እነዚያም መጽሐፍን የሰጠናቸው፤ በእርሱ ያምናሉ፡፡ ከእነዚህም (ከመካ ሰዎች) በእርሱ የሚያምኑ አልሉ፡፡ በተዓምራቶቻችንም ከሓዲዎቹ እንጂ ማንም አይክድም፡፡'),
('29:48', 87, 'ከእርሱ በፊትም መጽሐፍን የምታነብ በቀኝህም የምትጽፈው አልነበርክም፡፡ ያን ጊዜ አጥፊዎቹ በእርግጥ በተጠራጠሩ ነበር፡፡'),
('29:49', 87, 'አይደለም እርሱ (ቁርኣን) በእነዚያ ዕውቀትን በተሰጡት ሰዎች ልቦች ውስጥ (የጠለቀ) ግልጾች አንቀጾች ነው፡፡ በአንቀጾቻችንም በዳዮቹ እንጂ ሌላው አይክድም፡፡'),
('29:50', 87, '«በእርሱ ላይም ከጌታህ ዘንድ ተዓምራቶች ለምን አልተወረዱም» አሉ፡፡ «ተዓምራቶች አላህ ዘንድ ብቻ ናቸው፡፡ እኔም ግልጽ አስፈራሪ ብቻ ነኝ» በላቸው፡፡'),
('29:51', 87, 'እኛ መጽሐፉን በእነሱ ላይ የሚነበብ ኾኖ ባንተ ላይ ማውረዳችን አይበቃቸውምን በዚህ ውስጥ ለሚያምኑ ሕዝቦች ችሮታና ግሳጼ አለበት፡፡'),
('29:52', 87, '«በእኔና በእናንተ መካከል መስካሪ በአላህ በቃ፡፡ በሰማያትና በምድርም ያለውን ሁሉ ያውቃል» በላቸው፡፡ እነዚያም በብላሽ ነገር ያመኑ በአላህም የካዱ እነዚያ እነሱ ከሳሪዎች ናቸው፡፡'),
('29:53', 87, 'በቅጣትም ያስቸኩሉሃል፡፡ የተወሰነም ጊዜ ባልነበረ ኖሮ ቅጣቱ በመጣባቸው ነበር፡፡ እነርሱ የማያውቁ ሲኾኑም በድንገት በእርግጥ ይመጣባቸዋል፡፡'),
('29:54', 87, 'በቅጣት ያስቸኩሉሃል፡፡ ገሀነምም ከሓዲዎችን በእርግጥ ከባቢ ናት፡፡'),
('29:55', 87, 'ቅጣቱ ከበላያቸው፣ ከእግሮቻቸውም ሥር በሚሸፍናቸው ቀን ትሠሩት የነበራችሁትን ቅመሱ በሚላቸውም (ቀን ትከባቸዋለች)፡፡'),
('29:56', 87, 'እናንተ ያመናችሁ ባሮቼ ሆይ! ምድሬ በእርግጥ ሰፊ ናት፤ (ብትቸገሩ ተሰደዱ)፡፡ እኔንም ብቻ ተገዙኝ፡፡'),
('29:57', 87, 'ነፍስ ሁሉ ሞትን ቀማሽ ናት፡፡ ከዚያም ወደኛ ትመለሳላችሁ፡፡'),
('29:58', 87, 'እነዚያም ያመኑና መልካም ሥራዎችን የሠሩ ከገነት በሥሮቻቸው ወንዞች የሚፈሱባቸውን ሰገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ በእርግጥ እናሰፍራቸዋለን፡፡ የሠራተኞች ምንዳ ምንኛ አማረ!'),
('29:59', 87, '(እነሱ) እነዚያ የታገሱ በጌታቸውም ላይ የሚመኩ ናቸው፡፡'),
('29:60', 87, 'ከተንቀሳቃሽም ምግቧን ለመሸከም የማትችለው ብዙ ናት፡፡ አላህ ይመግባታል፡፡ እናንተንም (ይመግባል)፡፡ እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('29:61', 87, 'ሰማያትንና ምድርን የፈጠረ ፀሐይንና ጨረቃንም የገራ ማን እንደኾነ ብትጠይቃቸው «በእርግጥ አላህ ነው» ይሉሃል፡፡ ታድያ እንዴት ይመለሳሉ፡፡'),
('29:62', 87, 'አላህ ከባሮቹ ለሚሻው ሲሳይን ያሰፋል፡፡ ለእርሱም ያጠብባል፡፡ አላህ በነገሩ ሁሉ ዐዋቂ ነውና፡፡'),
('29:63', 87, 'ከሰማይም ውሃን ያወረደና በእርሱም ምድርን ከሞተች በኋላ ሕያው ያደረጋት ማን እንደኾነ ብትጠይቃቸው «አላህ ነው» ይሉሃል፡፡ «ምስጋና ለአላህ ነው» በላቸው፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('29:64', 87, 'ይህችም የቅርቢቱ ሕይወት መታለያና ጨዋታ እንጂ ሌላ አይደለችም፡፡ የመጨረሻይቱም አገር እርሷ በእርግጥ የዘላለም ሕይወት አገር ናት፡፡ የሚያውቁ ቢኾኑ ኖሮ፤ (ጠፊይቱን ሕይወት አይመርጡም ነበር)፡፡'),
('29:65', 87, 'በመርከቦች ውስጥ በተሳፈሩ ጊዜም አላህን መገዛትን ለእርሱ ብቻ ያጠሩ ኾነው ይጠሩታል፡፡ ወደ የብስ (በማውጣት) ባዳናቸው ጊዜም ወዲያውኑ እነርሱ (ጣዖትን) ያጋራሉ፡፡'),
('29:66', 87, 'በሰጠናቸው ጸጋ ሊክዱና ሊጠቃቀሙ (ያጋራሉ)፡፡ ወደፊትም (የሚጠብቃቸውን) ያውቃሉ፡፡'),
('29:67', 87, 'ሰዎቹ ከዙሪያቸው ሲነጠቁ እኛ (አገራቸውን ) ጸጥተኛ ክልል ማድረጋችንን አያዩምን በውድቅ ነገር ያምናሉን በአላህም ጸጋ ይክዳሉን'),
('29:68', 87, 'በአላህ ላይም ውሸትን ከቀጣጠፈ ሰው ወይም እውነቱ በመጣለት ጊዜ ከአስዋሸ ይበልጥ በዳይ ማነው በገሀነም ውስጥ ለከሓዲዎች መኖሪያ የለምን'),
('29:69', 87, 'እነዚያም በእኛ መንገድ የታገሉ መንገዳችንን በእርግጥ እንመራቸዋለን፡፡ አላህም በእርግጥ ከበጎ ሠሪዎች ጋር ነው፡፡'),
('30:1', 87, 'አ.ለ.መ (አሊፍ ላም ሚም)፡፡'),
('30:2', 87, 'ሩም ተሸነፈች፡፡'),
('30:3', 87, 'በጣም ቅርብ በሆነችው ምድር፡፡ እነርሱም ከመሸነፋቸው በኋላ በእርግጥ ያሸንፋሉ፡፡'),
('30:4', 87, 'በጥቂት ዓመታት ውስጥ (ያሸንፋሉ)፡፡ ትዕዛዙ በፊትም በኋላም የአላህ ነው፡፡ በዚያ ቀንም ምእመናን ይደሰታሉ፡፡'),
('30:5', 87, 'በአላህ እርዳታ (ይደሰታሉ)፡፡ የሚሻውን ሰው ይረዳል፤ እርሱም አሸናፊው አዛኙ ነው፡፡'),
('30:6', 87, 'አላህ እርዳታን ቀጠረ፡፡ አላህ ቀጠሮውን አያፈርስም፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም፡፡'),
('30:7', 87, 'ከቅርቢቱ ህይወት ግልጹን ብቻ ያውቃሉ፡፡ እነርሱም ከኋለኛይቱ ዓለም እነርሱ ዘንጊዎች ናቸው፡፡'),
('30:8', 87, 'በነፍሶቻቸው (ሁኔታ) አያስተውሉምን? ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ አላህ በእውነትና በተወሰነ ጊዜ እንጂ አልፈጠራቸውም፡፡ ከሰዎቹም ብዙዎቹ በጌታቸው መገናኘት ከሓዲዎች ናቸው፡፡'),
('30:9', 87, 'በምድር ላይ አይኼዱምና የእነዚያን ከበፊታቸው የነበሩትን ሰዎች ፍጻሜ እንዴት እንደነበረ አይመለከቱምን? በኀይል ከእነርሱም ይበልጥ የጠነከሩ ነበሩ፡፡ ምድርንም አረሱ፡፡ (እነዚህ) ከአለሟትም የበዛ አለሟት፡፡ መልዕክተ ኞቻቸውም በተዓምራቶች መጡባቸው፤ (አስተባበሉምና ጠፉ)፡፡ አላህም የሚበድላቸው አልነበረም፤ ግን ነፍሶቻቸውን ይበድሉ ነበሩ፡፡'),
('30:10', 87, 'ከዚያም የእነዚያ ያጠፉት ሰዎች መጨረሻ በአላህ አንቀጾች በማስተባበላቸውና በእርሷ የሚሳለቁ በመኾናቸው ምክንያት መጥፎ ቅጣት ሆነች፡፡'),
('30:11', 87, 'አላህ መፍጠርን ይጀምራል፡፡ ከዚያም ይመልሰዋል፤ ከዚያም ወደርሱ ትመለሳላችሁ፡፡'),
('30:12', 87, 'ሰዓቲቱም በምትቆምበት ቀን አመጸኞች ጭጭ ይላሉ፡፡'),
('30:13', 87, 'ለእነርሱም ከሚያጋሩዋቸው (ጣዖታት) አማላጆች አይኖሯቸውም፤ በሚያጋሯቸውም (ጣዖታት) ከሓዲዎች ይኾናሉ፡፡'),
('30:14', 87, 'ሰዓቲቱ በምትቆምበት ቀንም በዚያ ቀን ይለያያሉ፡፡'),
('30:15', 87, 'እነዚያ ያመኑትና መልካሞችን ሥራዎች የሠሩትማ እነርሱ በገነት ጨፌ ውስጥ ይደሰታሉ፡፡'),
('30:16', 87, 'እነዚያም የካዱትማ በአንቀጾቻችንና በኋለኛይቱም ዓለም መገናኘት ያስተባበሉት እነዚያ በቅጣቱ ውስጥ የሚጣዱ ናቸው፡፡'),
('30:17', 87, 'አላህንም በምታመሹ ጊዜ በምታነጉም ጊዜ አጥሩት፤ (ስገዱለት)፡፡'),
('30:18', 87, 'ምስጋናም በሰማያትና በምድር ውስጥ ለርሱ ብቻ (የተገባው) ነው፡፡ በሰርክም፤ በቀትር ውስጥ በምትገቡም ጊዜ፤ (አጥሩት)፡፡'),
('30:19', 87, 'ሕያውን ከሙት ያወጣል፡፡ ሙታንም ከሕያው ያወጣል፡፡ ምድርንም ከሞተች በኋላ ህያው ያደርጋታል፡፡ እንደዚሁም (ከመቃብር) ትወጣላችሁ፡፡'),
('30:20', 87, 'እናንተንም ከዐፈር መፍጠሩ ከዚያም እናንተ ወዲያውኑ የምትበታተኑ ሰዎች መኾናችሁ ከአስደናቂ ምልክቶቹ ነው፡፡'),
('30:21', 87, 'ለእናንተም ከነፍሶቻችሁ (ከጎሶቻችሁ) ሚስቶችን ወደእነርሱ ትረኩ ዘንድ መፍጠሩ፣ በመካከላችሁም ፍቅርንና እዝነትን ማድረጉ ከአስደናቂ ምልክቶቹ ነው፡፡ በዚህ ውስጥ ለሚያስተውሉ ሕዝቦች ተዓምራቶች አልሉ፡፡'),
('30:22', 87, 'ሰማያትንና ምድርንም መፍጠሩ፣ የቋንቋዎቻችሁና የመልኮቻችሁም መለያየት፣ ከአስደናቂ ምልክቶቹ ነው፡፡ በዚህ ውስጥ ለዐዋቂዎች ተዓምራቶች አልሉበት፡፡'),
('30:23', 87, 'በሌሊትና በቀንም መተኛታችሁ፣ ከችሮታውም መፈለጋችሁ ከምልክቶቹ ነው፡፡ በዚህ ውስጥ ለሚሰሙ ሕዝቦች ተዓምራቶች አልሉበት፡፡'),
('30:24', 87, 'ብልጭታንም ፈሪዎችና ከጃዮች ስትሆኑ ለእናንተ ማሳየቱ፣ ከሰማይም ውሃን ማውረዱ፣ በእርሱም ምድርን ከሞተች በኋላ ሕያው ማድረጉ ከአስደናቂ ምልክቶቹ ነው፡፡ በዚህ ውስጥ ለሚያስቡ ሕዝቦች ተዓምራቶች አልሉበት፡፡'),
('30:25', 87, 'ሰማይና ምድርም (ያለምሰሶ) በትዕዛዙ መቆማቸው፣ ከዚያም (መልአኩ ለትንሣኤ) ከምድር ጥሪን በጠራችሁ ጊዜ እናንተ ወዲያውኑ የምትወጡ መሆናችሁ ከአስደናቂ ምልክቶቹ ነው፡፡'),
('30:26', 87, 'በሰማያትና በምድር ያለው ሁሉ የእርሱ ብቻ ነው፡፡ ሁሉም ለእርሱ ታዛዦች ናቸው፡፡'),
('30:27', 87, 'እርሱም ያ መፍጠርን የሚጀምር ከዚያም የሚመልሰው ነው፡፡ እርሱም (መመለሱ) በእርሱ ላይ በጣም ገር ነው፡፡ ለእርሱም በሰማያትም በምድርም ከፍተኛ ባሕርይ (አንድነትና ለእርሱ ብጤ የሌለው መኾን) አልለው፡፡ እርሱም አሸናፊ ጥበበኛ ነው፡፡'),
('30:28', 87, 'ለእናንተ ከነፍሶቻችሁ የሆነን ምሳሌ አደረገላችሁ፡፡ (እርሱም) እጆቻችሁ ከያዟቸው (ባሮች) ውስጥ በሰጠናችሁ ጸጋ ለእናንተ ተጋሪዎች አሏችሁን? ታዲያ እናንተና እነርሱ በእርሱ ትክክል ናችሁን? ነፍሶቻችሁን (ብጤዎቻችሁን) እንደምትፈሩ ትፈሯቸዋላችሁን? እንደዚሁ ለሚያስተውሉ ሕዝቦች፤ አንቀጾችን እንገልጻለን፡፡'),
('30:29', 87, 'ይልቁንም እነዚያ የበደሉ ሰዎች ያለ ዕውቀት ዝንባሌዎቻቸውን ተከተሉ፡፡ አላህም ያጠመመውን ሰው የሚያቀናው ማነው? ለእነርሱም ከረዳቶች ምንም የላቸውም፡፡'),
('30:30', 87, 'ወደ እውነት ተዘንባይ ኾነህም ፊትህን ለሃይማኖት ቀጥ አድርግ፡፡ የአላህን ፍጥረት ያችን አላህ ሰዎችን በእርስዋ ላይ የፈጠረባትን (ሃይማኖት ያዟት)፡፡ የአላህን ፍጥረት መለወጥ የለም፡፡ ይህ ቀጥተኛ ሃይማኖት ነው፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም፡፡'),
('30:31', 87, 'ወደእርሱ ተመላሾች ሆናቸሁ (የአላህን ሃይማኖት ያዙ)፡፡ ፍሩትም፡፡ ሶላትንም አስተካክላችሁ ስገዱ፡፡ ከአጋሪዎቹም አትሁኑ፡፡'),
('30:32', 87, 'ከእነዚያ ሃይማኖታቸውን ከለያዩትና ክፍልፍሎችም ከሆኑት (አትሁኑ)፡፡ ሕዝብ ሁሉ እነሱ ዘንድ ባለው ነገር ተደሳቾች ናቸው፡፡'),
('30:33', 87, 'ሰዎችንም ችግር ባገኛቸው ጊዜ ጌታቸውን ወደርሱ ተመላሾች ሆነው ይጠሩታል፡፡ ከዚያም ከእርሱ ችሮታን ባቀመሳቸው ጊዜ ከእነርሱ ከፊሎቹ ወዲያውኑ በጌታቸው (ጣዖትን) ያጋራሉ፡፡'),
('30:34', 87, 'በሰጠናቸው ጸጋ ሊክዱ (ያጋራሉ)፡፡ ተጣቀሙም፤ በእርግጥም (መጨረሻችሁን) ወደፊት ታውቃላችሁ፡፡'),
('30:35', 87, 'በእነርሱ ላይ አስረጅ አወረድን? ታዲያ እርሱ በዚያ በእርሱ ያጋሩ በነበሩት ነገር ይናገራልን;(የለም)፡፡'),
('30:36', 87, 'ሰዎችንም ችሮታን ባቀመስናቸው ገዜ በእርሷ ይደሰታሉ፡፡ እጆቻቸውም ባሳለፉት ምክንያት መከራ ብታገኛቸው ወዲያውኑ እነርሱ ተስፋ ይቆርጣሉ፡፡'),
('30:37', 87, 'አላህ ለሚሻው ሰው ሲሳይን የሚያሰፋ የሚያጠብም መሆኑን አያዩምን በዚህ ውስጥ ለሚያምኑ ሕዝቦች አስደናቂ ምልክቶች አልሉበት፡፡'),
('30:38', 87, 'የዝምድናን ባለቤት ተገቢውን ስጠው፡፡ ለድኻም ለመንገደኛም (እርዳ)፡፡ ይህ ለእነዚያ የአላህን ፊት (ውዴታውን) ለሚሹ መልካም ነው፡፡ እነዚያም እነርሱ የፈለጉትን የሚያገኙ ናቸው፡፡'),
('30:39', 87, 'ከበረከትም በሰዎች ገንዘቦች ውስጥ ይጨመር ዘንድ የምትሰጡት አላህ ዘንድ አይጨምርም፡፡ ከምጽዋትም የአላህን ፊት የምትሹ ሆናችሁ የምትሰጡት እነዚያ (ሰጪዎች) አበርካቾች እነርሱ ናቸው፡፡'),
('30:40', 87, 'አላህ ያ የፈጠራችሁ፣ ከዚያም ሲሳይን የሰጣችሁ፣ ከዚያም የሚገድላችሁ ከዚያም ሕያው የሚያደርጋችሁ ነው፡፡ ከምታጋሯቸው (ጣዖታት) ውስጥ ከዚህ ነገር አንዳችን የሚሠራ አለን ለአላህ ጥራት ይገባው፡፡ (በእርሱ) ከሚያጋሩትም ሁሉ ላቀ፡፡'),
('30:41', 87, 'የሰዎች እጆች በሠሩት ኃጢኣት ምክንያት የዚያን የሠሩትን ከፊሉን ያቀምሳቸው ዘንድ መከራው በየብስና በባሕር ተገለጠ፤ (ተሰራጨ)፡፡ እነርሱ ሊመለሱ ይከጀላልና፡፡'),
('30:42', 87, '«በምድር ላይ ኺዱ የእነዚያንም በፊት የነበሩትን ሰዎች መጨረሻ እንዴት እንደነበረ ተመልከቱ» በላቸው፡፡ አብዛኞቻቸው አጋሪዎች ነበሩ፡፡'),
('30:43', 87, 'ለርሱ መመለስ የሌለው ቀን (የትንሣኤ ቀን) ከአላህ ሳይመጣ በፊት ፊትህን ወደ ቀጥተኛው'),
('30:44', 87, 'የካደ ሰው ክህደቱ (ጠንቁ) በእርሱው ላይ ነው፡፡ መልካምም የሠሩ ለነፍሶቻቸው (ማረፊያዎችን) ያዘጋጃሉ፡፡'),
('30:45', 87, 'እነዚያን ያመኑትንና መልካሞችንም የሠሩትን ከችሮታው ይመነዳ ዘንድ (ይለያያሉ)፡፡ እርሱ ከሓዲዎችን አይወድምና፡፡'),
('30:46', 87, 'ነፋሶችንም (በዝናብ) ልታበስራችሁ፣ ከችሮታውም (በእርሷ) ሊያቀምሳችሁ፣ መርከቦችም በትዕዛዙ እንዲንሻለሉ፣ ከችሮታውም እንድትፈልጉ፣ ታመሰግኑትም ዘንድ መላኩ ከአስደናቂ ምልክቶቹ ነው፡፡'),
('30:47', 87, 'ከአንተ በፊትም መልክተኞችን ወደየሕዝቦቻቸው በእርግጥ ላክን፡፡ በግልጽ ማስረጃዎችም መጡባቸው፡፡ ከእነዚያ ካመጹትም ተበቀልን፡፡ ምእመኖቹንም መርዳት በእኛ ላይ ተገቢ ሆነ፡፡'),
('30:48', 87, 'አላህ ያ ነፋሶችን የሚልክ ነው፡፡ ደመናንም ይቀሰቅሳሉ፡፡ በሰማይ ላይም እንደሚሻ ይዘረጋዋል፡፡ ቁርጥራጮችም ያደርገዋል፡፡ ዝናቡንም ከደመናው መካከል ሲወጣ ታያለህ፡፡ በእርሱም ከባሮቹ የሚሻውን በለየ ጊዜ ወዲያውኑ እነሱ ይደሰታሉ፡፡'),
('30:49', 87, 'በእነርሱም ላይ ከመወረዱ በፊት ከእርሱ በፊት በእርግጥ ተስፋ ቆራጮች ነበሩ፡፡'),
('30:50', 87, 'ምድርንም ከሞተች በኋላ እንዴት ሕያው እንደሚያደርጋት ወደ አላህ ችሮታ ፈለጎች ተመልከት፡፡ ይህ (አድራጊ) ሙታንንም በእርግጥ ሕያው አድራጊ ነው፡፡ እርሱም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('30:51', 87, 'ነፋስንም (በአዝመራዎች ላይ) ብንልክና ገርጥቶ ቢያዩት ከእርሱ በኋላ በእርግጥ (ችሮታውን) የሚክዱ ይሆናሉ፡፡'),
('30:52', 87, 'አንተም ሙታንን አታሰማም፡፡ ደንቆሮዎችንም ዟሪዎች ሆነው በሸሹ ጊዜ ጥሪን አታሰማም፡፡'),
('30:53', 87, 'አንተ ዕውሮችንም ከጥመታቸው የምታቀና አይደለህም፡፡ በአንቀጾቻችን የሚያምኑትን ሰዎች እንጂ ሌላን አታሰማም፡፡ እነርሱም ታዛዦች ናቸው፡፡'),
('30:54', 87, 'አላህ ያ ከደካማ (ፍትወት ጠብታ) የፈጠራችሁ ነው፡፡ ከዚያም ከደካማነት በኋላ ኀይልን አደረገ፡፡ ከዚያም ከብርቱነት በኋላ ደካማነትንና ሽበትን አደረገ፡፡ የሚሻውን ይፈጥራል፡፡ እርሱም ዐዋቂው ቻዩ ነው፡፡'),
('30:55', 87, 'ሰዓቲቱ በምትሆንበት ቀን ከሓዲዎች «ከአንዲት ሰዓት በስተቀር (በመቃብር) አልቆየንም» ብለው ይምላሉ፡፡ እንደዚሁ (ከእውነት) ይመለሱ ነበሩ፡፡'),
('30:56', 87, 'እነዚያንም ዕውቀትንና እምነትን የተሰጡት «በአላህ መጽሐፍ (ፍርድ) እስከ ትንሣኤ ቀን በእርግጥ ቆያችሁ፡፡ ይህም (የካዳችሁት) የትንሣኤ ቀን ነው፡፡ ግን እናንተ የማታውቁ ነበራችሁ» ይሏቸዋል፡፡'),
('30:57', 87, 'በዚያም ቀን እነዚያን የበደሉትን ማመካኘታቸው አይጠቅማቸውም፡፡ እነርሱም በወቀሳ አይታለፉም፡፡'),
('30:58', 87, 'በዚያም ቁርኣን ውስጥ ከምሳሌ ሁሉ ለሰዎች በእርግጥ ገለጽን፡፡ በተዓምርም ብትመጣባቸው እነዚያ የካዱት ሰዎች «እናንተ አበላሺዎች እንጂ ሌላ አይደላችሁም» ይላሉ፡፡'),
('30:59', 87, 'እንደዚሁ አላህ በእነዚያ በማያውቁት ሰዎች ልቦች ላይ ያትማል፡፡'),
('30:60', 87, 'ስለዚህ ታገስ፡፡ የአላህ ቀጠሮ እውነት ነውና፡፡ እነዚያም በትንሣኤ የሚያረጋግጡት አያቅልሉህ፡፡'),
('31:1', 87, 'አ.ለ.መ. (አሊፍ ላም ሚም)፡፡'),
('31:2', 87, 'ይህች ጥበብ ከተመላው መጽሐፍ አንቀጾች ናት፡፡'),
('31:3', 87, 'ለበጎ አድራጊዎች መሪና እዝነት ስትኾን፡፡'),
('31:4', 87, 'ለእነዚያ ሶላትን አስተካክለው ለሚያደርሱት፣ ዘካንም ለሚሰጡት፣ እነርሱም በመጨረሻይቱ ዓለም እነርሱ የሚያረጋግጡ ለሆኑት፡፡'),
('31:5', 87, 'እነዚያ ከጌታቸው በሆነ ቅን መንገድ ላይ ናቸው፡፡ እነዚያም እነርሱ ምኞታቸውን ያገኙ ናቸው፡፡'),
('31:6', 87, 'ከሰዎችም ያለ ዕውቀት ሆኖ ከአላህ መንገድ ሊያሳስትና ማላገጫ አድርጎ ሊይዛት አታላይ ወሬን የሚገዛ አልለ፡፡ እነዚያ ለእነርሱ አዋራጅ ቅጣት አላቸው፡፡'),
('31:7', 87, 'አንቀጾቻችንም በእርሱ ላይ በሚነበቡ ጊዜ እንዳልሰማትና በጆሮቹ ድንቁርና እንዳለበት የኮራ ሆኖ ይዞራል፡፡ በአሳማሚ ቅጣትም አብስረው፡፡'),
('31:8', 87, 'እነዚያ ያመኑና መልካሞችንም የሠሩ ለእነርሱ የጸጋ ገነቶች አሏቸው፡፡'),
('31:9', 87, 'በእርሷ ውስጥ ዘውታሪዎች ሲሆኑ፤ አላህም እውነተኛን ተስፋ ቃል ገባላቸው፡፡ እርሱም አሸናፊው ጥበበኛው ነው፡፡'),
('31:10', 87, 'ሰማያትን ያለምታዩዋት አዕማድ (ምሰሶዎች) ፈጠረ፡፡ በምድርም ውስጥ በእናንተ እንዳታረገርግ ተራራዎችን ጣለ፡፡ በእርሷም ላይ ከተንቀሳቃሽ ሁሉ በተነ፡፡ ከሰማይም ውሃን አወረድን፡፡ በእርሷም ውስጥ ከመልካም ዓይነት ሁሉ አበቀልን፡፡'),
('31:11', 87, 'ይህ የአላህ ፍጡር ነው፡፡ እነዚያ ከእርሱ ሌላ ያሉት ምንን እንደፈጠሩ እስኪ አሳዩኝ፡፡ በእውነቱ በዳዮቹ በግልጽ ጥመት ውስጥ ናቸው፡፡'),
('31:12', 87, 'ለሉቅማንም ጥበብን በእርግጥ ሰጠነው፡፡ (አልነውም)፡- «አላህን አመስግን፡፡» ያመሰገነም ሰው የሚያመሰግነው ለራሱ ብቻ ነው፡፡ የካደም ሰው (በራሱ ላይ ነው)፡፡ አላህ ተብቃቂ ምስጉን ነውና፡፡'),
('31:13', 87, 'ሉቅማንም ለልጁ እርሱ የሚገሥጸው ሲኾን «ልጄ ሆይ! በአላህ (ጣዖትን) አታጋራ፡፡ ማጋራት ታላቅ በደል ነውና» ያለውን (አስታውስ)፡፡'),
('31:14', 87, 'ሰውንም በወላጆቹ (በጎ እንዲያደርግ) በጥብቅ አዘዝነው፡፡ እናቱ ከድካም በላይ በሆነ ድካም'),
('31:15', 87, 'ለአንተ በእርሱ ዕውቀት የሌለህን ነገር በእኔ እንድታጋራ ቢታገሉህም አትታዘዛቸው፡፡ በቅርቢቱም ዓለም፤ በመልካም ሥራ ተወዳጃቸው፡፡ ወደእኔም የተመለሰን ሰው መንገድ ተከተል፡፡ ከዚያም መመለሻችሁ ወደእኔ ነው፡፡ ትሠሩት የነበራችሁትንም ሁሉ እነግራችኋለሁ፤ (አልነው)፡፡'),
('31:16', 87, '(ሉቅማንም አለ) «ልጄ ሆይ! እርሷ የሰናፍጭ ቅንጣት ክብደት ያህል ብትሆንና በቋጥኝ ውስጥ ወይም በሰማያት ውስጥ ወይም በምድር ውስጥ ብትሆን አላህ ያመጣታል፡፡ አላህ ሩኅሩኅ ውስጥ ዐዋቂ ነውና፡፡'),
('31:17', 87, '«ልጄ ሆይ! ሶላትን አስተካክለህ ስገድ፡፡ በበጎ ነገርም እዘዝ፡፡ ከሚጠላም ሁሉ ከልክል፡፡ በሚያገኝህም መከራ ላይ ታገስ፡፡ ይህ በምር ከሚያዙ ነገሮች ነው፡፡'),
('31:18', 87, '«ጉንጭህንም (በኩራት) ከሰዎች አታዙር፡፡ በምድርም ላይ ተንበጥርረህ አትሂድ፡፡ አላህ ተንበጥራሪን ጉረኛን ሁሉ አይወድምና፡፡'),
('31:19', 87, '«በአካኼድህም መካከለኛ ኹን፡፡ ከድምጽህም ዝቅ አድርግ፡፡ ከድምጾች ሁሉ አስከፊው የአህዮች ድምጽ ነውና፡፡»'),
('31:20', 87, 'አላህ በሰማያት ያለውንና በምድርም ያለውን ሁሉ ለእናንተ ያገራላችሁ ጸጋዎቹንም ግልጽም ድብቅም ሲኾኑ የሞላላችሁ መኾኑን አታዩምን? ከሰዎችም ያለ ዕውቀትና ያለ መሪ፣ ያለግልጽ መጽሐፍም በአላህ የሚከራከር አልለ፡፡'),
('31:21', 87, 'ለእነርሱም አላህ ያወረደውን ተከተሉ በተባሉ ጊዜ አይደለም በእርሱ ላይ አባቶቻችንን ያገኘንበትን እንከተላለን ይላሉ፡፡ ሰይጣን ወደ እሳት ቅጣት የሚጠራቸው ቢሆንም (ይከተሉዋቸዋልን?)'),
('31:22', 87, 'እርሱ መልካም ሠሪ ሆኖ ፊቱን ወደ አላህ የሚሰጥም ሰው ጠንካራን ገመድ በእርግጥ ጨበጠ፡፡ የነገሩም ሁሉ ፍጻሜ ወደ አላህ ነው፡፡'),
('31:23', 87, 'የካደም ሰው ክህደቱ አያሳዝንህ፡፡ መመለሻቸው ወደኛ ነው፤ የሠሩትንም ሁሉ እንነግራቸዋለን፡፡ አላህ በልቦች ውስጥ ያለን ሁሉ ያውቃልና፡፡'),
('31:24', 87, 'ጥቂትን እናጣቅማቸዋለን፡፡ ከዚያም ወደ ብርቱ ቅጣት እናስገድዳቸዋለን፡፡'),
('31:25', 87, 'ሰማያትንና ምድርንም የፈጠረ ማን እንደሆነ ብትጠይቃቸው በእርግጥ አላህ ነው ይላሉ፡፡ ምስጋና ለአላህ ይገባው በላቸው፡፡ ይልቁንም አብዛኛዎቹ አያውቁም፡፡'),
('31:26', 87, 'በሰማያትና በምድር ያለው ሁሉ የአላህ ነው፡፡ አላህ እርሱ ተብቃቂ ምስጉን ነው፡፡'),
('31:27', 87, 'ከዛፍም በምድር ያለው ሁሉ ብእሮች ቢሆኑ ኖሮ ባሕሩም ከእርሱ (ማለቅ) በኋላ ሰባት ባህሮች የሚጨመሩለት ሆኖ (ቀለም ቢሆንና ቢጻፍባቸው) የአላህ ቃላት ባላለቀች ነበር፡፡ አላህ አሸናፊ ጥበበኛ ነውና፡፡'),
('31:28', 87, 'እናንተን መፍጠርና እናንተን መቀስቀስ እንደ አንዲት ነፍስ እንጂ ሌላ አይደለም፡፡ አላህ ሰሚ ተመልካች ነውና፡፡'),
('31:29', 87, 'አላህ ሌሊትን በቀን ውስጥ የሚያስገባ፣ ቀንንም በሌሊት ውስጥ የሚያስገባ፣ ፀሐይንና ጨረቃንም የገራ መሆኑን አታይምን? ሁሉም እስከ ተወሰነ ጊዜ ድረስ ይሮጣሉ፡፡ አላህም በምትሠሩት ሁሉ ውስጠ ዐዋቂ ነው፡፡'),
('31:30', 87, 'ይህ አላህ እርሱ እውነት ከእርሱም ሌላ የሚግገዙት (ጣዖት) ውሸት በመሆኑና አላህም እርሱ የበላይ ታላቅ በመሆኑ ነው፡፡'),
('31:31', 87, 'ከአስደናቂ ምልክቶቹ ሊያሳያችሁ መርከቦች በአላህ ችሮታ በባህር ውስጥ የሚንሻለሉ መሆናቸውን አታይምን? በዚህ ውስጥ በጣም ታጋሽ አመስጋኝ ለሆኑ ሁሉ ተዓምራቶች አሉበት፡፡'),
('31:32', 87, 'እንደ ጥላዎችም የሆነ ማዕበል በሸፈናቸው ጊዜ አላህን ሃይማኖትን ለእርሱ ብቻ ያጠሩ ሆነው ይጠሩታል፡፡ ወደ የብስም ባዳናቸው ጊዜ ከእነሱ ትክክለኛም አልለ፡፡ (ከእነርሱም የሚክድ አለ)፡፡ በአንቀጾቻችንም አታላይ ከዳተኛ ሁሉ እንጂ ሌላው አይክድም፡፡'),
('31:33', 87, 'እናንተ ሰዎች ሆይ! ጌታችሁን ፍሩ፡፡ ወላጅም ከልጁ (በምንም) የማይጠቅምበትን፤ ተወላጅም እርሱ ወላጅን በምንም ጠቃሚ የማይሆንበትን ቀን ፍሩ፡፡ የአላህ ቀጠሮ እውነት ነውና፡፡ ቅርቢቱም ሕይወት አትሸንግላችሁ፡፡ በአላህም (መታገስ) አታላዩ (ሰይጣን) አያታልላችሁ፡፡'),
('31:34', 87, 'አላህ የሰዓቲቱ ዕውቀት እርሱ ዘንድ ብቻ ነው፡፡ ዝናብንም ያወርዳል፡፡ በማሕፀኖችም ውስጥ ያለን ሁሉ ያውቃል፡፡ ማንኛይቱ ነፍስም ነገ የምትሠራውን አታውቅም፡፡ ማንኛይቱ ነፍስም በየትኛው ምድር እንደምትሞት አታውቅም፡፡ አላህ ዐዋቂ ውስጠ ዐዋቂ ነው፡፡'),
('32:1', 87, 'አ.ለ.መ (አሊፍ ላም ሚም)፡፡'),
('32:2', 87, 'የመጽሐፉ መወረድ ጥርጥር የለበትም፡፡ ከዓለማት ጌታ ነው፡፡'),
('32:3', 87, 'ይልቁንም «ቀጠፈው» ይላሉን? አይደለም፡፡ እርሱ ከጌታህ ዘንድ የሆነ እውነት ነው፡፡ በእርሱ ከአንተ በፊት ከአስፈራሪ (ነቢይ) ያልመጣባቸውን ሕዝቦች ልታስፈራራበት (ያወረደልህ ነው)፡፡ እነርሱ ሊምመሩ ይከጀላልና፡፡'),
('32:4', 87, 'አላህ ያ ሰማያትንና ምድርን በመካከላቸውም ያለውን ሁሉ በስድስት ቀኖች ውስጥ የፈጠረ ከዚያም በዐርሹ ላይ (ለሱ ክብር በሚስማማ መልኩ) የተደላደለ ነው፡፡ ከእርሱ ሌላ ለእናንተ ረዳትም አማላጅም ምንም የላችሁም፤ አትገሰጹምን?'),
('32:5', 87, 'ነገሩን ሁሉ ከሰማይ ወደ ምድር ያዘጋጃል፡፡ ከዚያም ከምትቆጥሩት (ዘመን) ልኩ ሺህ ዓመት በሆነ ቀን ውስጥ ወደርሱ ይወጣል (ይመለሳል)፡፡'),
('32:6', 87, 'ይህ (ይህንን የሠራው) ሩቁንም ቅርቡንም ሁሉ ዐዋቂው አሸናፊው፣ አዛኙ (ጌታ) ነው፡፡'),
('32:7', 87, 'ያ የፈጠረውን ነገር ሁሉ ያሳመረው የሰውንም ፍጥረት ከጭቃ የጀመረው ነው፡፡'),
('32:8', 87, 'ከዚያም ዘሮቹን ከተንጣለለ፣ ከደካማ ውሃ ያደረገ ነው፡፡'),
('32:9', 87, 'ከዚያም (ቅርጹን) አስተካከለው፡፡ በእርሱ ውስጥም ከመንፈሱ ነፋበት፤ (ነፍስ ዘራበት)፡፡ ለእናንተም ጆሮዎችን፣ ዓይኖችንና ልቦችንም አደረገላችሁ፡፡ በጣም ጥቂትን ብቻ ታመሰግናላችሁ፡፡'),
('32:10', 87, '«በምድርም ውስጥ (በስብሰን) በጠፋን ጊዜ እኛ በአዲስ መፈጠር ውስጥ እንሆናለን?» አሉ፡፡ በእውነቱ እነርሱ በጌታቸው መገናኘት ከሓዲዎች ናቸው፡፡'),
('32:11', 87, '«በእናንተ የተወከለው መልአከ ሞት ይገድላችኋል፡፡ ከዚያም ወደ ጌታችሁ ትመለሳላችሁ» በላቸው፡፡'),
('32:12', 87, 'አመጸኞችም በጌታቸው ዘንድ ራሶቻቸውን ያቀረቀሩ ሆነው «ጌታችን ሆይ! አየን፣ ሰማንም፡፡ መልካምን እንሠራለንና (ወደ ምድረ ዓለም) መልሰን፡፡ እኛ አረጋጋጮች ነን፡፡» (የሚሉ ሲሆኑ) ብታይ ኖሮ (አስደንጋጭን ነገር ታይ ነበር)፡፡'),
('32:13', 87, 'በሻንም ኖሮ ነፍስን ሁሉ ቅንነቷን (እምነቷን) በሰጠናት ነበር፡፡ ግን ገሀነምን ከአጋንንትና ከሰዎች የተሰበሰቡ ሆነው በእርግጥ እሞላለሁ ማለት ቃሉ ከእኔ ተረጋግጧል፡፡'),
('32:14', 87, 'ይህንንም ቀናችሁን መገናኘትን በመርሳታችሁ ምክንያት (ቅጣትን) ቅመሱ! እኛ ተውናችሁ፡፡ ትሠሩት በነበራችሁትም ጥፋት ዘውታሪን ቅጣት ቅመሱ (ይባላሉ)፡፡'),
('32:15', 87, 'በአንቀጾቻችን የሚያምኑት እነዚያ በእርሷ በተገሰጹ ጊዜ ሰጋጆች ሆነው የሚወድቁትና እነርሱም የማይኮሩ ሆነው በጌታቸው ምስጋና (ተጎናጽፈው) የሚያወድሱት ብቻ ናቸው፡፡'),
('32:16', 87, 'ጌታቸውን ለመፍራትና ለመከጀል የሚጠሩት ሆነው ጎኖቻቸው ከመጋደሚያ ስፍራዎች ይራራቃሉ፡፡ ከሰጠናቸውም (ጸጋ) ይለገሳሉ፡፡'),
('32:17', 87, 'ይሠሩትም በነበሩት ለመመንዳት ከዓይኖች መርጊያ ለእነርሱ የተደበቀላቸውን (ጸጋ) ማንኛይቱም ነፍስ አታውቅም፡፡'),
('32:18', 87, 'አማኝ የሆነ ሰው አመጸኛ እንደ ሆነ ሰው ነውን? አይስተካከሉም፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('32:19', 87, 'እነዚያ ያመኑና መልካሞችን የሰሩማ ለእነርሱ ይሠሩት በነበሩት ምክንያት መስተንግዶ ሲሆኑ መኖሪያ ገነቶች አሏቸው፡፡'),
('32:20', 87, 'እነዚያ ያመጹትማ፤ መኖሪያቸው እሳት ናት፡፡ ከእርሷ መውጣትን በፈለጉ ቁጥር በእርሷ ውስጥ ይመለሳሉ፡፡ ለእነርሱም «ያንን በእርሱ ታስተባብሉበት የነበራችሁትን የእሳት ቅጣት ቅመሱ» ይባላሉ፡፡'),
('32:21', 87, 'ይመለሱ ዘንድም ከትልቁ ቅጣት በፊት (በዚህ ዓለም) ከትንሹ ቅጣት በእርግጥ እናቀምሳቸዋለን፡፡'),
('32:22', 87, 'በጌታውም አንቀጾች ከተገሰጸና ከዚያም ከተዋት ሰው ይበልጥ በደለኛ ማነው? (የለም)፤ እኛ ከተንኮለኞቹ ተበቃዮች ነን፡፡'),
('32:23', 87, 'ሙሳንም መጽሐፍን በእርግጥ ሰጠነው፡፡ እርሱን ከመገናኘትህም በመጠራጠር ውስጥ አትሁን፡፡ ለእስራኤል ልጆችም መሪ አደረግነው፡፡'),
('32:24', 87, 'በታገሱና በተዓምራቶቻችን የሚያረጋግጡ በሆኑም ጊዜ ከእነርሱ በትዕዛዛችን የሚመሩ መሪዎች አደረግን፡፡'),
('32:25', 87, 'ጌታህ እርሱ በዚያ በእርሱ ይለያዩበት በነበሩት ነገር በትንሣኤ ቀን በመካከላቸው (በፍርድ) ይለያል፡፡'),
('32:26', 87, 'ከክፍለ ዘመናት ሰዎች ብዙዎችን ያጠፋን መሆናችን በመኖሪያዎቻቸው የሚሄዱ ሲሆኑ'),
('32:27', 87, 'እኛ ውሃን ወደ ደረቅ ምድር የምንነዳ እንስሶቻቸውና ነፍሶቻቸው ከእርሱ የሚበሉለትንም አዝመራ በእርሱ የምናወጣ መኾናችንን አያዩምን? አይመለከቱምን?'),
('32:28', 87, '«ከእውነተኞችም እንደሆናችሁ ይህ ፍርድ መቼ ነው?» ይላሉ፡፡'),
('32:29', 87, '«በፍርድ ቀን እነዚያን የካዱትን ሰዎች እምነታቸው አይጠቅማቸውም፡፡ እነርሱም ጊዜን አይሰጡም፤» በላቸው፡፡'),
('32:30', 87, 'እነርሱንም ተዋቸው፡፡ ተጠባበቅም፤ እነርሱ ተጠባባቂዎች ናቸውና፡፡'),
('33:1', 87, 'አንተ ነቢዩ ሆይ! አላህን ፍራ፡፡ ከሓዲዎችንና መናፍቃንንም አትታዘዝ፡፡ አላህ ዐዋቂ ጥበበኛ ነውና፡፡'),
('33:2', 87, 'ከጌታህም ወደ አንተ የሚወረደውን ተከተል፡፡ አላህ በምትሠሩት ሁሉ ውሰጠ አዋቂ ነውና፡፡'),
('33:3', 87, 'በአላህም ላይ ተመካ፡፡ መመኪያም በአላህ በቃ፡፡'),
('33:4', 87, 'አላህ ለአንድ ሰው በሆዱ ውስጥ ሁለትን ልቦች አላደረገም፡፡ ሚስቶቻችሁንም እነዚያን ከእነርሱ እንደናቶቻችሁ ጀርባዎች ይሁኑብን የምትሏቸውን እናቶቻችሁ አላደረገም፡፡ ልጅ በማድረግ የምታስጠጓቸውንም ልጆቻችሁ አላደረገም፡፡ ይህ በአፎቻችሁ የምትሉት ነው፡፡ አላህም እውነቱን ይናገራል፡፡ እርሱም ትክክለኛውን መንገድ ይመራል፡፡'),
('33:5', 87, 'ለአባቶቻቸው (በማስጠጋት) ጥሯቸው፡፡ እርሱ አላህ ዘንድ ትክክለኛ ነው፡፡ አባቶቻቸውንም ባታውቁ በሃይማኖት ወንድሞቻችሁና ዘመዶቻችሁ ናቸው፡፡ በእርሱ በተሳሳታችሁበት ነገርም በእናንተ ላይ ኀጢአት የለባችሁም፡፡ ግን ልቦቻችሁ ዐውቀው በሠሩት (ኀጢአት'),
('33:6', 87, 'ነቢዩ በምእምናን ከነፍሶቻቸው ይበልጥ ተገቢ ነው፡፡ ሚስቶቹም እናቶቻቸው ናቸው፡፡ የዝምድና ባለቤቶችም ከፊላቸው በከፊሉ (ውርስ) በአላህ መጽሐፍ ውስጥ ከምእምናንና ከስደተኞቹ ይልቅ የተገባቸው ናቸው፡፡ግን ወደ ወዳጆቻችሁ (በኑዛዜ) መልካምን ብትሰሩ (ይፈቀዳል)፡፡ ይህ በመጽሐፉ ውሰጥ የተመዘገበ ነው፡፡'),
('33:7', 87, 'ከነቢዮችም የጠበቀ ኪዳናቸውን ከአንተም፣ ከኑሕም፣ ከኢብራሒምም፣ ከሙሳም ከመርየም ልጅ ዒሳም በያዝን ጊዜ (አስታወስ)፡፡ ከእነርሱም የከበደን ቃል ኪዳን ያዝን፡፡'),
('33:8', 87, '(አላህ) እውነተኞችን ከውነታቸው ሊጠይቅ (ይህንን ሠራ)፡፡ ለከሓዲዎችም አሳማሚን ቅጣት አዘጋጀ፡፡'),
('33:9', 87, 'እናንተ ያመናችሁ ሆይ! ብዙ ሰራዊት በመጣችባችሁና በእነርሱ ላይ ነፋስንና ያላያችኋትን ሰራዊት በላክን ጊዜ በእናንተ ላይ (ያደረገላችሁን) የአላህን ጸጋ አስታውሱ፡፡ አላህም የምትሠሩትን ሁሉ ተመልካች ነው፡፡'),
('33:10', 87, 'ከበላያችሁም ከናንተ በታችም በመጡባችሁ ጊዜ፣ ዓይኖችም በቃበዙ፣ ልቦችም ላንቃዎች በደረሱና በአላህም ጥርጣሬዎችን በጠረጠራችሁ ጊዜ (ያደረገላችሁን አስታውሱ)፡፡'),
('33:11', 87, 'እዚያ ዘንድ ምእምናን ተሞከሩ፡፡ ብርቱን መንቀጥቀጥም ተንቀጠቀጡ፡፡'),
('33:12', 87, 'መናፍቆችና እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸውም «አላህና መልክተኛው ማታለልን እንጂ ሌላን አልቀጠሩንም» በሚሉ ጊዜ (ያደረገላችሁን አስታውሱ)፡፡'),
('33:13', 87, 'ከእነርሱም የሆኑ ጭፍሮች «የየስሪብ ሰዎች ሆይ! ለእናንተ ስፍራ የላችሁምና ተመለሱ» ባሉ ጊዜ (አስታውሱ)፡፡ ከእነርሱም «ከፊሎቹ እርሷ ነውረኛ ሳትሆን ቤቶቻችን ነውረኛ ናቸው» የሚሉ ሆነው ነቢዩን (ከጦሩ ለመመለስ) ፈቃድን ይጠይቃሉ፡፡ መሸሽን እንጂ ሌላ አይፈልጉም፡፡'),
('33:14', 87, 'በእነርሱም ላይ (ቤቶቻቸው) ከየቀበሌዋ በተገባባት ከዚያም ከኢስላም መመለስን በተጠየቁ ኖሮ በሠሯት ነበር፡፡ በእርሷም ጥቂትን ጊዜ እንጂ አይቆዩም ነበር፡፡'),
('33:15', 87, 'ጀርባዎችንም ላያዞሩ ከዚያ በፊት በእርግጥ አላህን ቃል ኪዳን የተጋቡ ነበሩ፡፡ የአላህም ቃል ኪዳን የሚጠየቁበት ነው፡፡'),
('33:16', 87, 'ከሞት ወይም ከመገደል ብትሸሹ መሸሻችሁ ፈጽሞ አይጠቅማችሁም፡፡ ያን ጊዜም ጥቂትን እንጂ የምትጣቀሙ አትደረጉም በላቸው፡፡'),
('33:17', 87, '«(አላህ) በእናንተ ክፉን ነገር ቢሻ ያ ከአላህ የሚጠብቃችሁ ማነው? ወይም ለእናንተ ችሮታን ቢሻ፤ (በክፉ የሚነካችሁ ማነው?)» በላቸው፤ ከአላህም ሌላ ለእነርሱ ወዳጅም ረዳትም አያገኙም፡፡'),
('33:18', 87, 'ከእናንተ ውስጥ የሚያሳንፉትን፣ ለወንድሞቻቸውም «ወደኛ ኑ» የሚሉትን፣ ውጊያንም ጥቂትን እንጂ የማይመጡትን በእርግጥ አላህ ያውቃቸዋል፡፡'),
('33:19', 87, 'በእናንተ ላይ (እርዳታን) የነፈጉ ሆነው እንጅ (የማይመጡትን)፣ ሽብሩም በመጣ ጊዜ እንደዚያ ከሞት (መከራ) በርሱ ላይ የሚሸፍን ዐደጋ እንደወደቀበት ዓይኖቻቸው ወዲያና ወዲህ የምትዞር ኾና ወዳንተ ሲመለከቱ ታያቸዋለህ፡፡ ሽብሩም በኼደ ጊዜ በገንዘብ ላይ የሚሳሱ ኾነው በተቡ ምላሶች ይነድፏችኋል፡፡ እነዚያ አላመኑም፡፡ ስለዚህ አላህ ሥራዎቻቸውን አበላሸ፡፡ ይህም በአላህ ላይ ገርነው፡፡'),
('33:20', 87, '(መናፍቆች) አሕዛብን አልኼዱም ብለው ያስባሉ፡፡ አሕዛቦቹም ቢመጡ እነርሱ በዘላኖች ውስጥ በገጠር (የራቁ) ሊሆኑ ይመኛሉ፡፡ ከወሬዎቻችሁ ይጠይቃሉ፡፡ በእናንተ ውስጥ በነበሩም ኖሮ ጥቂትን እንጂ አይዋጉም ነበር፡'),
('33:21', 87, 'ለእናንተ አላህንና የመጨረሻውን ቀን የሚከጅል ለሆነ ሰው፣ አላህንም በብዙ ለሚያወሳ በአላህ መልዕክተኛ መልካም መከተል አልላችሁ፡፡'),
('33:22', 87, 'አማኞቹም አሕዛብን ባዩ ጊዜ «ይህ አላህና መልክተኛው የቀጠሩን ነው፡፡ አላህና መልክተኛውም እውነትን ተናገሩ» አሉ፡፡ (ይህ) እምነትንና መታዘዝንም እንጂ ሌላን አልጨመረላቸውም፡፡'),
('33:23', 87, 'ከአማኞቹ በእርሱ ላይ ለአላህ ቃል ኪዳን የገቡበትን በእውነት የፈጸሙ ወንዶች አልሉ፡፡ ከነርሱም ስለቱን የፈጸመ (ለሃይማኖቱ የተገደለ) አልለ፤ ከነርሱም ገና የሚጠባበቅ አልለ፡፡ (የገቡበትን ቃል) መለወጥንም አልለወጡም፡፡'),
('33:24', 87, 'አላህ እውነተኞችን በውነተኛነታቸው ሊመነዳ መናፍቃንንም ቢሻ ሊቀጣ ወይም (ቢመለሱ) በእነርሱ ላይ ጸጸታቸውን ሊቀበል (ይህን አደረገ)፡፡ አላህ መሓሪ አዛኝ ነውና፡፡'),
('33:25', 87, 'እነዚያንም የካዱትን በቁጭታቸው የተመሉ መልካምን ነገር ያላገኙ ሆነው አላህ'),
('33:26', 87, 'እነዚያንም ከመጽሐፉ ባለቤቶች (አሕዛቦችን) የረዷቸውን (ቁረይዟን) ከምሽጎቻቸው አወረዳቸው፡፡ በልቦቻቸውም ውስጥ መባባትን ጣለባቸው፡፡ ከፊሉን ትገድላላችሁ፡፡ ከፊሉንም ትማርካላችሁ፡፡'),
('33:27', 87, 'ምድራቸውንም፣ ቤቶቻቸውንም፣ ገንዘቦቻቸውንም ገና ያልረገጣችኋትንም ምድር አወረሳችሁ፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('33:28', 87, 'አንተ ነቢይ ሆይ! ለሚስቶችህ (እንዲህ) በላቸው «ቅርቢቱን ሕይወትና ጌጧን የምትፈልጉ እንደ ሆናችሁ ኑ፤ አጣቅማችኋለሁና፡፡ መልካምንም ማሰማራት (በመፍታት) አሰማራችኋለሁና፡፡'),
('33:29', 87, '«አላህንና መልክተኛውን የመጨረሻይቱን አገርም የምትፈልጉ ብትሆኑም፤ እነሆ አላህ ከእናንተ ለመልካም ሠሪዎቹ ትልቅን ምንዳ አዘጋጅቷል፡፡»'),
('33:30', 87, 'የነቢዩ ሴቶች ሆይ! ከእናንተ ውስጥ ግልጽ የሆነን መጥፎ ሥራ የምትሠራ ለእርሷ ቅጣቱ ሁለት እጥፍ ሆኖ ይነባበርባታል፡፡ ይህም በአላህ ላይ ገር ነው፡፡'),
('33:31', 87, 'ከእናንተም ለአላህና ለመልክተኛው የምትታዘዝ መልካም ሥራንም የምትሠራ ምንዳዋን ሁለት ጊዜ እንሰጣታለን፡፡ ለእርሷም የከበረን ሲሳይ አዘጋጅተንላታል፡፡'),
('33:32', 87, 'የነቢዩ ሴቶች ሆይ! ከሴቶች እንደማናቸው አይደላችሁም፡፡ አላህን ብትፈሩ (ትበልጣላችሁ)፡፡ ያ በልቡ ውስጥ በሽታ ያለበት እንዳይከጅል በንግግር አትለስልሱም፡፡ መልካምንም ንግግር ተናገሩ፡፡'),
('33:33', 87, 'በቤቶቻችሁም ውስጥ እርጉ፡፡ እንደ ፊተኛይቱ መሃይምነት ጊዜ መገለጥም በማጌጥ አትገለጡ፡፡ ሶላትንም በደንቡ ስገዱ፡፡ ዘካንም ስጡ፡፡ አላህንና መልክተኛውንም ታዘዙ፡፡ የነቢዩ ቤተሰቦች ሆይ! አላህ የሚሻው ከእናንተ ላይ እርክሰትን ሊያስወግድና ማጥራትንም ሊያጠራችሁ ብቻ ነው፡፡'),
('33:34', 87, 'ከአላህ አንቀጾችና ከጥበቡም በቤቶቻችሁ የሚነበበውን አስታውሱ፡፡ አላህ እዝነቱ ረቂቅ ውስጠ ዐዋቂ ነውና፡፡'),
('33:35', 87, 'ሙስሊሞች ወንዶችና ሙስሊሞች ሴቶች፣ ምእምናንና ምእምናትም፣ ታዛዦች ወንዶችና ታዛዦች ሴቶችም፣ እውነተኞች ወንዶችና እውነተኞች ሴቶችም፣ ታጋሾች ወንዶችና ታጋሾች ሴቶችም፣ አላህን ፈሪዎች ወንዶችና አላህን ፈሪዎች ሴቶችም፣ መጽዋቾች ወንዶችና መጽዋቾች ሴቶችም፣ ጿሚዎች ወንዶችና ጿሚዎች ሴቶችም፣ (ካልተፈቀደ ሥራ) ብልቶቻቸውን ጠባቂዎች ወንዶችና ጠባቂ ሴቶችም፣ አላህን በብዙ አውሺዎች ወንዶችና አውሺዎች ሴቶችም፣ አላህ ለእነርሱ ምሕረትንና ታላቅን ምንዳ አዘጋጅቶላቸዋል፡፡'),
('33:36', 87, 'አላህና መልክተኛውም ነገርን በፈረዱ ጊዜ ለምእምናንና ለምእምናት ከነገራቸው ለእነርሱ ምርጫ ሊኖራቸው አይገባም! የአላህንና የመልክተኛውንም ትእዛዝ የጣሰ ሰው ግልጽ የሆነን መሳሳት በእርግጥ ተሳሳተ፡፡'),
('33:37', 87, 'ለእዚያም አላህ በእርሱ ላይ ለለገሰለትና (አንተም ነጻ በማውጣት) በእርሱ ላይ ለለገስክለት ሰው (ለዘይድ) አላህ ገላጩ የሆነን ነገር በነፍስህ ውስጥ የምትደብቅና አላህ ልትፈራው ይልቅ የተገባው ሲሆን ሰዎችን የምትፈራ ሆነህ «ሚስትህን ባንተ ዘንድ ያዝ፤ (ከመፍታት) አላህንም ፍራ» በምትል ጊዜ (አስታውስ)፡፡ ዘይድም ከእርሷ ጉዳይን በፈጸመ ጊዜ በምእምናኖች ላይ ልጅ አድርገው ባስጠጉዋቸው (ሰዎች) ሚስቶች ከእነርሱ ጉዳይን በፈጸሙ ጊዜ (በማግባት) ችግር እንዳይኖርባቸው እርሷን አጋባንህ፡፡ የአላህም ትእዛዝ ተፈጻሚ ነው፡፡'),
('33:38', 87, 'በነቢዩ ላይ አላህ ለእርሱ በፈረደው ነገር ምንም ችግር ሊኖርበት አይገባም፡፡ በእነዚያ ከዚያ በፊት ባለፉት (ነቢያት) አላህ ደነገገው፡፡ የአላህም ትእዛዝ የተፈረደ ፍርድ ነው፡፡'),
('33:39', 87, 'ለእነዚያ የአላህን መልእክቶች ለሚያደርሱና ለሚፈሩት ከአላህ በስተቀርም አንድንም ለማይፈሩት (ተደነገገ)፡፡ ተቆጣጣሪም በአላህ በቃ፡፡'),
('33:40', 87, 'ሙሐመድ ከወንዶቻችሁ የአንድም ሰው አባት አይደለም፡፡ ግን የአላህ መልክተኛና የነቢዮች መደምደሚያ ነው፡፡ አላህም በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('33:41', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ብዙ ማውሳትን አውሱት፡፡'),
('33:42', 87, 'በቀኑ መጀመሪያና መጨረሻም አጥሩት፡፡'),
('33:43', 87, 'እርሱ ያ በእናንተ ላይ እዝነትን የሚያወርድ ነው፡፡ መላእክቶቹም (እንደዚሁ ምሕረትን የሚለምኑላችሁ ናቸው)፡፡ ከጨለማዎች ወደ ብርሃን ያወጣችሁ ዘንድ (ያዝንላችኋል)፡፡ ለአማኞችም በጣም አዛኝ ነው፡፡'),
('33:44', 87, 'በሚገናኙት ቀን መከባበሪያቸው ሰላም መባባል ነው፡፡ ለእነርሱም የከበረን ምንዳ አዘጋጅቶላቸዋል፡፡'),
('33:45', 87, 'አንተ ነቢዩ ሆይ! እኛ መስካሪ፣ አብሳሪና አስፈራሪም አድርገን ላክንህ፡፡'),
('33:46', 87, 'ወደ አላህም በፈቃዱ ጠሪ፣ አብሪ ብርሃንም (አድርገን ላክንህ)፡፡'),
('33:47', 87, 'አማኞችንም ከአላህ ዘንድ ለእነርሱ ታላቅ ችሮታ ያላቸው መኾኑን አብስራቸው፡፡'),
('33:48', 87, 'ከሓዲዎችንና መናፍቃንንም አትታዘዛቸው፡፡ ማሰቃየታቸውንም (ለአላህ) ተው፡፡ በአላህም ላይ ተጠጋ፡፡ መጠጊያም በአላህ በቃ፡፡'),
('33:49', 87, 'እናንተ ያመናችሁ ሆይ! ምእምናትን ባገባችሁና ከዚያም ሳትነኩዋቸው በፊት በፈታችኋቸው ጊዜ ለእናንተ በእነርሱ ላይ የምትቆጥሩዋት ዒዳ ምንም የላችሁም፡፡ አጣቅሟቸውም፤ (ጉርሻ ስጧቸው)፡፡ መልካም ማሰናበትንም አሰናብቷቸው፡፡'),
('33:50', 87, 'አንተ ነቢዩ ሆይ! እኛ እነዚያን መህሮቻቸውን የሰጠሃቸውን ሚስቶችህን፣ አላህ ባንተ ላይ ከመለሰልህም እነዚያን እጅህ የጨበጠቻቸውን ምርኮኞች፣ እነዚያንም ከአንተ ጋር የተሰደዱትን የአጎትህን ሴቶች ልጆች፣ የአክስቶችህንም ሴቶች ልጆች፣ የየሹማህንም ሴቶች ልጆች፣ የየሹሜዎችህንም ሴቶች ልጆች (ማግባትን) ለአንተ ፈቅደንልሃል፡፡ የአመነችንም ሴት ነፍሷን (ራሷን) ለነቢዩ ብትሰጥ ነቢዩ ሊያገባት የፈለገ እንደ ኾነ ከምእምናን ሌላ ላንተ ብቻ የጠራች ስትኾን (ፈቀድንልህ)፡፡ በእነርሱ (በምእምናን) ላይ በሚስቶቻቸውና እጆቻቸው በጨበጧቸው (ባሮች ነገር) ግዴታ ያደረግንባቸውን በእርግጥ ዐውቀናል፡፡ ባንተ ላይ ችግር እንዳይኖር (ያለፉትን ፈቀድንልህ)፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('33:51', 87, 'ከእነርሱ የምትሻትን ታቆያለህ፡፡ የምትሻውንም ወደ አንተ ታስጠጋለህ፡፡ (በመፍታት) ከአራቅሃትም የፈለግሃትን (በመመለስ ብታስጠጋ) በአንተ ላይ ኀጢአት የለብህም፡፡ ይህ ዓይኖቻቸው ወደ መርጋት፣ ወደ አለማዘናቸውም፣ ለሁሉም በሰጠሃቸው ነገር ወደ መውደዳቸውም በጣም የቀረበ ነው፡፡ አላህም በልቦቻችሁ ውስጥ ያለውን ሁሉ ያውቃል፡፡ አላህም ዐዋቂ ታጋሽ ነው፡፡'),
('33:52', 87, 'ከእነዚህ በኋላ እጅህ ከጨበጠቻቸው (ባሮች) በስተቀር ሴቶች ለአንተ አይፈቀዱልህም፡፡ ከሚስቶችም መልካቸው ቢደንቅህም እንኳ በእነርሱ ልታላውጥ (አይፈቀደልህም)፡፡ አላህም በነገሩ ሁሉ ላይ ተጠባባቂ ነው፡፡'),
('33:53', 87, 'እናንተ ያመናችሁ ሆይ! መድረሱን የማትጠባበቁ ስትኾኑ ወደ ምግብ ካልተፈቀደላችሁ በስተቀር የነቢዩን ቤቶች (በምንም ጊዜ) አትግቡ፡፡ ግን በተጠራችሁ ጊዜ ግቡ፡፡ በተመገባችሁም ጊዜ ወዲያውኑ ተበተኑ፡፡ ለወግ የምትጫወቱ ኾናችሁም (አትቆዩ)፡፡ ይህ ነቢዩን በእርግጥ ያስቸግራል፡፡ ከእናንተም ያፍራል፡፡ ግን አላህ ከእውነት አያፍርም፡፡ ዕቃንም (ለመዋስ) በጠየቃችኋቸው ጊዜ ከመጋረጃ ኋላ ኾናችሁ ጠይቋቸው፡፡ ይህ ለልቦቻችሁ፤ ለልቦቻቸውም የበለጠ ንጽሕና ነው፡፡ የአላህንም መልክተኛ ልታስቸግሩ ሚስቶቹንም ከእርሱ በኋላ ምንጊዜም ልታገቡ ለእናንተ አይገባችሁም፡፡ ይህ አላህ ዘንድ ከባድ (ኀጢአት) ነው፡፡'),
('33:54', 87, 'ማንኛውንም ነገር ብትገልጹ ወይም ብትደብቁት (በርሱ ይመነዳችኋል)፡፡ አላህ ነገሩን ሁሉ ዐዋቂ ነውና፡፡'),
('33:55', 87, '(የነቢዩ ሚስቶች) በአባቶቻቸው፣ በወንዶች ልጆቻቸውም፣ በወንድሞቻቸውም፣ ወንድሞቻቸው ወንዶች ልጆችም፣ በእኅቶቻቸው ወንዶች ልጆችም፣ (ምእምናት በኾኑት) በሴቶቻቸውም፣ እጆቻቸው በጨበጧቸውም ባሮች (አጠገብ በመገለጥ) በእነርሱ ላይ ኃጢአት የለባቸውም፡፡ (ሴቶች ሆይ! ታዘዙ) አላህንም ፍሩ፡፡ አላህ በነገሩ ሁሉ ላይ መስካሪ ነውና፡፡'),
('33:56', 87, 'አላህና መላእክቱ በነቢዩ ላይ የአክብሮት እዝነትን ያወርዳሉ፡፡ እናንተ ያመናችሁ ሆይ! በእርሱ ላይ የአክብሮት እዝነትን አውርዱ፡፡ የማክበርንም ሰላምታ ሰላም በሉ፡፡'),
('33:57', 87, 'እነዚያ አላህንና መልክተኛውን የሚያስከፉ በቅርቢቱ ዓለም በመጨረሻይቱም አላህ ረግሟቸዋል፡፡ ለእነርሱም አዋራጅን ቅጣት ደግሶላቸዋል፡፡'),
('33:58', 87, 'እነዚያንም ምእምናንንና ምእምናነትን ባልሰሩት ነገር (በመዝለፍ) የሚያሰቃዩ ዕብለትንና ግልጽ ኃጢአትን በእርግጥ ተሸከሙ፡፡'),
('33:59', 87, 'አንተ ነቢዩ ሆይ! ለሚስቶቸህ፣ ለሴቶች ልጆችህም፣ ለምእምናን ሚስቶችም ከመከናነቢያዎቻቸው በላያቸው ላይ እንዲለቁ ንገራቸው፡፡ ይህ እንዲታወቁና (በባለጌዎች) እንዳይደፈሩ ለመኾን በጣም የቀረበ ነው፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('33:60', 87, 'መናፍቃንና እነዚያ በልቦቻቸው ውስጥ (የአመንዝራነት) በሽታ ያለባቸው በመዲናም ውሰጥ (በወሬ) አሸባሪዎቹ (ከዚህ ሥራቸው) ባይከለከሉ በእነርሱ ላይ በእርግጥ እንቀሰቅስሃለን፡፡ ከዚያም በእርሷ ውስጥ ጥቂትን እንጂ አይጎራበቱህም፡፡'),
('33:61', 87, 'የተረገሙ ኾነው እንጂ (አይጎራበቱህም)፡፡ በየትም ስፍራ ቢገኙ ይያዛሉ፡፡ መገደልንም ይገደላሉ፡፡'),
('33:62', 87, '(ይህቺ) በእነዚያ በፊት ባለፉት (ላይ የደነገጋት) የአላህ ድንጋጌ ናት፡፡ ለአላህም ድንጋጌ ፈጽሞ መለወጥን አታገኝም፡፡'),
('33:63', 87, 'ሰዎች ከሰዓቲቱ ይጠይቁሃል፡፡ «ዕውቀትዋ አላህ ዘንደ ብቻ ነው፤» በላቸው፡፡ የሚያሳወቅህም ምንድን ነው! ሰዓቲቱ በቅርብ ጊዜ ልትኾን ይከጀላል፡፡'),
('33:64', 87, 'አላህ ከሓዲዎችን በእርግጥ ረግሟቸዋል፡፡ ለእነርሱም የተጋጋመችን እሳት አዘጋጅቷል፡፡'),
('33:65', 87, 'በእርሷ ውስጥ ዘለዓለም ዘውታሪዎች ሲኾኑ፤ ወዳጅም ረዳትም አያገኙም፡፡'),
('33:66', 87, 'ፊቶቻቸው በእሳት ውሰጥ በሚገለባበጡ ቀን «ዋ ምኞታችን! አላህን በተገዛን መልክተኛውንም በታዘዝን ኖሮ» እያሉ ይጸጸታሉ፡፡'),
('33:67', 87, 'ይላሉም «ጌታችን ሆይ! እኛ ጌቶቻችንንና ታላላቆቻችንን ታዘዝን፡፡ መንገዱንም አሳሳቱን፡፡'),
('33:68', 87, '«ጌታችን ሆይ! ከቅጣቱ እጥፍን ስጣቸው፡፡ ታላቅን እርግማንም እርገማቸው፡፡»'),
('33:69', 87, 'እናንተ ያመናችሁ ሆይ! እንደእነዚያ ሙሳን እንዳሰቃዩት ሰዎች አትኹኑ፡፡ ካሉትም ነገር ሁሉ አላህ አጠራው፡፡ አላህም ዘንድ ባለሞገስ ነበር፡፡'),
('33:70', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ፍሩ፡፡ ትክክለኛንም ንግግር ተናገሩ፡፡'),
('33:71', 87, 'ሥራዎቻችሁን ለእናንተ ያበጅላችኋልና፡፡ ኀጢአቶቻችሁንም ለእናንተ ይምርላችኋል፡፡ አላህንና መልክተኛውን የሚታዘዝም ሰው በእርግጥ ታላቅን እድል አገኘ፡፡'),
('33:72', 87, 'እኛ አደራን በሰማያትና በምድር፣ በተራራዎችም ላይ አቀረብናት፡፡ መሸከሟንም እንቢ አሉ፡፡ ከእርሷም ፈሩ፡፡ ሰውም ተሸከማት፡፡ እርሱ በጣም በደለኛ ተሳሳች ነውና፡፡'),
('33:73', 87, 'መናፍቃንንና መናፍቃትን፣ ወንዶች አጋሪዎችንና ሴቶች አጋሪዎችንም አላህ ሊቀጣና በምእምናንና በምእምናትም ላይ አላህ ንስሓን ሊቀበል (አደራዋን ሰው ተሸከማት)፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('34:1', 87, 'ምስጋና ለዚያ በሰማያትም ያለ በምድርም ያለ ሁሉ የርሱ ለኾነው ለአላህ ይገባው፡፡ በመጨረሻይቱም ዓለም ምስጋና ለእርሱ ብቻ ነው፡፡ እርሱም ብልሃተኛው ውስጠ ዐዋቂው ነው፡፡'),
('34:2', 87, 'በምድር ውስጥ የሚገባውን ሁሉ ከእርሷም የሚወጣውን ከሰማይም የሚወርደውን በእርሷም ውስጥ የሚያርገውን ሁሉ ያውቃል፡፡ እርሱም አዛኙ መሓሪው ነው፡፡'),
('34:3', 87, 'እነዚያ የካዱትም «ሰዓቲቱ አትመጣብንም» አሉ፡፡ በላቸው «አይደለም፤ ሩቁን ሁሉ ዐዋቂ በኾነው ጌታዬ እምላለሁ፡፡ በእርግጥ ትመጣባችኋለች፡፡ የብናኝ ክብደት ያክል እንኳ በሰማያትና በምድር ውስጥ ከእርሱ አይርቅም፡፡ ከዚህ ያነሰም ኾነ የበለጠ የለም በግልጹ መጽሐፍ ውስጥ የተመዘገበ ቢኾን እንጅ፡፡»'),
('34:4', 87, 'እነዚያን ያመኑትንና መልካሞችን የሠሩትን ሊመነዳ (ሰዓቲቱ ትመጣባችኋለች)፤ እነዚያ ለእነርሱ ምህረትና የከበረ ሲሳይ አላቸው፡፡'),
('34:5', 87, 'እነዚያም የሚያመልጡ መስሏቸው አንቀጾቻችንን ለማፍረስ የጣሩ እነዚያ ለእነርሱ ከመጥፎ ቅጣት የኾነ አሳማሚ ስቃይ አላቸው፡፡'),
('34:6', 87, 'እነዚያም ዕውቀትን የተሰጡት ያንን ከጌታህ ወዳንተ የተወረደውን እርሱ እውነትና አሸናፊ ምስጉን ወደ ኾነው አላህ መንገድ የሚመራ መኾኑን ያውቃሉ፡፡'),
('34:7', 87, 'እነዚያም የካዱት «(ሙታችሁ) መበጣጠስን ሁሉ በተበጣጠሳችሁ ጊዜ እናንተ በአዲስ መፈጠር ውስጥ ትኾናላችሁ ብሎ የሚነግራችሁን ሰው እናሳያችሁን?» አሉ፡፡'),
('34:8', 87, 'በአላህ ላይ ውሸትን ቀጠፈን? ወይስ በእርሱ ዕብደት አለበትን? (አሉ)፡፡ እንዳሉት አይደለም፡፡ እነዚያ በመጨረሻይቱ (ዓለም) የሚያምኑት (በእርሷ) በቅጣት ውስጥ (አሁን) በራቀ ስህተትም ውስጥ ናቸው፡፡'),
('34:9', 87, 'ከሰማይና ከምድር በፊታቸውና በኋላቸው ወዳለው ሁሉ አይመለከቱምን? ብንሻ በእነርሱ ምድርን እንደረባባቸዋለን፡፡ ወይም በእነርሱ ላይ ከሰማይ ቁራጭን እንጥልባቸዋለን፤ በዚህ ውስጥ (ወደ ጌታው) ተመላሽ ለኾነ ባሪያ ሁሉ ምልክት አለበት፡፡'),
('34:10', 87, 'ለዳውድም ከእኛ የኾነን ችሮታ በእርግጥ ሰጠነው፡፡ (አልንም)፡-«ተራራዎች ሆይ! ከእርሱ ጋር ውዳሴን መላልሱ፡፡ በራሪዎችንም (ገራንለት)፡፡ ብረትንም ለእርሱ አለዘብንለት፡፡»'),
('34:11', 87, 'ሰፋፊዎችን ጥሩሮች ሥራ፡፡ በአሠራርዋም መጥን፡፡ መልካምንም ሥራ ሥሩ፡፡ እኔ የምትሠሩትን ነገር ሁሉ ተመልካች ነኝና (አልነው)፡፡'),
('34:12', 87, 'ለሱለይማንም ነፋስን የቀትር በፊት ጉዞዋ የወር መንገድ የቀትር በኋላ ጉዞዋም የወር መንገድ ሲኾን ገራንለት፡፡ የነሐስንም ምንጭ ለእርሱ አፈሰስንለት፡፡ ከጋኔኖችም በጌታው ፈቃድ በፊቱ የሚሠሩን (አደረግንለት)፡፡ ከነርሱም ውስጥ ከትእዛዛችን ዝንፍ የሚል ከነዲድ እሳት ቅጣት እናቀምሰዋለን፡፡'),
('34:13', 87, 'ከምኩራቦች፣ ከምስሎችም እንደ ገንዳ ከኾኑ ገበታዎችም፣ ከተደላደሉ ታላላቅ ድስቶችም የሚሻውን ሁሉ ይሠሩለታል፡፡ (አልናቸውም) «የዳውድ ቤተሰቦች ሆይ! አመስጋኞች ኾናችሁ (ለጌታችሁ) ሥሩ፡፡» ከባሮቼ በጣም አመስጋኞቹም ጥቂቶች ናቸው፡፡'),
('34:14', 87, 'በእርሱም ላይ ሞትን በፈጸምንበት ጊዜ መሞቱን በትሩን የምትበላ ተንቀሳቃሽ ምስጥ እንጂ ሌላ አላመለከታቸውም፡፡ በወደቀ ጊዜም ጋኔኖች ሩቅን ምስጢር የሚያወቁ በኾኑ ኖሮ በአዋራጅ ስቃይ ውስጥ የማይቆይ እንደነበሩ ተረዱ፡፡'),
('34:15', 87, 'ለሰበእ በመኖሪያቸው በእውነት አስደናቂ ምልክት ነበራቸው፡፡ ከግራና ከቀኝ ሁለት አትክልቶች (ነበሯቸው)፡፡ «ከጌታችሁ ሲሳይ ብሉ፡፡ ለእርሱም አመስግኑ፡፡ (አገራችሁ) ውብ አገር ናት፡፡ (ጌታችሁ) መሓሪ ጌታም ነው» (ተባሉ)፡፡'),
('34:16', 87, '(ከማመስገን) ዞሩም፡፡ በእነርሱም ላይ የግድቡን ጎርፍ ለቀቅንባቸው፡፡ በአትክልቶቻቸውም ሁለት አትክልቶች፣ ባለመርጋጋ ፍሬዎችን፣ ባለጠደቻና ከቁርቁራም ባለጥቂት ዛፎችን ለወጥናቸው፡፡'),
('34:17', 87, 'በመካዳቸው ይህንን መነዳናቸው፤ (እንዲህ ያለውን ቅጣት) በጣም ከሓዲን እንጂ ሌላውን እንቀጣለን?'),
('34:18', 87, 'በእነርሱና በዚያች በውስጧ በረከትን ባደረግንባት አገር (በሻም) መካከልም ቅጥልጥል ከተሞችን አደረግን፡፡ በእርሷም ጉዞን ወሰንን፡፡ «ጸጥተኞች ኾናችሁ በሌሊቶችም በቀኖችም ተጓዙ፤» (አልን)፡፡'),
('34:19', 87, '«ጌታችን ሆይ! በጉዞዎቻችን መካከል አራርቅልን» አሉም፡፡ ነፍሶቻቸውንም በደሉ፡፡ (መገረሚያ) ወሬዎችም አደረግናቸው፡፡ መበታተንንም ሁሉ በታተንናቸው፡፡ በዚህ ውስጥ በጣም ታጋሽና አመስጋኝ ለሆነ ሁሉ መገሰጫዎች አሉበት፡፡'),
('34:20', 87, 'ኢብሊስም በእነርሱ ላይ ምኞቱን በእርግጥ ፈጸመ፤ ከአመኑትም የሆኑት ጭፍሮች በስተቀር ተከተሉት፡፡'),
('34:21', 87, 'በመጨረሻይቱም ዓለም የሚያምነውን ከዚያ እርሱ ከእርሷ በመጠራጠር ውስጥ ከሆነው ሰው ለይተን እንድናውቅ እንጅ በእነርሱ ላይ ለእርሱ ምንም ስልጣን አልነበረውም፡፡ ጌታህም በነገሩ ሁሉ ላይ ተጠባባቂ ነው፡፡'),
('34:22', 87, '«እነዚያን ከአላህ ሌላ (አማልክት ብላችሁ) የምታስቧቸውን ጥሩ፡፡ በሰማያትም በምድርም ውስጥ የብናኝ ክብደት ያክል ምንንም አይችሉም፡፡ ለእነርሱም በሁለቱም ውስጥ ምንም ሽርክና የላቸውም፡፡ ከእነርሱም ለእርሱ ምንም አጋዥ የለውም፤» በላቸው፡፡'),
('34:23', 87, 'ምልጃም እርሱ ለፈቀደለት ሰው ብቻ ቢሆን እንጂ እርሱ ዘንድ ምንም አትጠቅምም፡፡ ከልቦቻቸው ላይ ድንጋጤው በተገለጸም ጊዜ (ተማላጆቹ) «ጌታችሁ ምን አለ?» ይላሉ፡፡ (አማላጆቹ) «እውነትን አለ፤ እርሱም ከፍተኛው ታላቁ ጌታ ነው» ይላሉ፡፡'),
('34:24', 87, '«ከሰማያትና ከምድር (ዝናብንና በቃይን) የሚሰጣችሁ ማነው?» በላቸው፡፡ «አላህ ነው፡፡ እኛ ወይም እናንተ በትክክለኛው መንገድ ላይ ወይም በግልጽ መሳሳት ውስጥ ነን» በላቸው፡፡'),
('34:25', 87, '«ከአጠፋነው ጥፋት አትጠየቁም፡፡ ከምትሠሩትም ሥራ አንጠየቅም» በላቸው፡፡'),
('34:26', 87, '«ጌታችን በመካከላችን ይሰበስባል፡፡ ከዚያም በመካከላችን በእውነት ይፈርዳል፡፡ እርሱም በትክክል ፈራጁ ዐዋቂው ነው» በላቸው፡፡'),
('34:27', 87, '«እነዚያን ተጋሪዎች አድርጋችሁ በእርሱ ያስጠጋችኋቸውን (ጣዖታት) አሳዩኝ፡፡ ተዉ (አታጋሩ)፤ በእውነቱ እርሱ አሸናፊው ብልሃተኛው አላህ ነው» በላቸው፡፡'),
('34:28', 87, 'አንተንም ለሰዎች ሁሉ በመላ አብሳሪና አስፈራሪ አድርገን ቢሆን እንጂ አላክንህም፡፡ ግን አብዛኞቹ ሰዎች አያውቁም፡፡'),
('34:29', 87, '«እውነተኞችም እንደ ሆናችሁ ይህ ቀጠሮ መቼ ነው?» ይላሉ፡፡'),
('34:30', 87, '«ለእናንተ ከእርሱ አንዲትንም ሰዓት የማትዘገዩበት የማትቀድሙበትም የቀጠሮ ቀን አላችሁ» በላቸው፡፡'),
('34:31', 87, 'እነዚያ የካዱትም በዚህ ቁርኣን በዚያ ከበፊቱ ባለውም (መጽሐፍ) በጭራሽ አናምንም አሉ፡፡'),
('34:32', 87, 'እነዚያ የኮሩት ለእነዚያ ለተዋረዱት «ከትክክለኛው እምነት ከመጣላችሁ በኋላ እኛ ከለከልናችሁን? አይደለም (እናንተው) ከሓዲዎች ነበራችሁ» ይሏቸዋል፡፡'),
('34:33', 87, 'እነዚያም የተዋረዱት ለእነዚያ ለኮሩት «አይደለም፤ በአላህ እንድንክድና ለእርሱ ባላንጣዎችን እንድናደርግ ስታዙን (የከለከለን) የሌሊትና የቀን ዱለታችሁ ነው» ይላሉ፡፡ ቅጣቱንም ባዩ ጊዜ ጸጸትን ይገልጻሉ፡፡ በእነዚያም በካዱት አንገቶች ላይ እንዛዝሎችን እናደርጋለን፡፡ ይሠሩት የነበሩትን እንጂ ሌላን ይመነዳሉን?'),
('34:34', 87, 'በከተማም አስፈራሪን አልላክንም፡፡ ነዋሪዎችዋ «እኛ በዚያ በርሱ በተላካችሁበት ከሓዲዎች ነን» ያሉ ቢኾኑ እንጂ፡፡'),
('34:35', 87, '«እኛም በገንዘቦችና በልጆች ይበልጥ የበዛን ነን፡፡ እኛም የምንቀጣ አይደለንም» አሉ፡፡'),
('34:36', 87, 'በላቸው «ጌታዬ ሲሳይን ለሚሻው ሰው ያሰፋል፤ ያጠባልም፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም፡፡»'),
('34:37', 87, 'ገንዘቦቻችሁና ልጆቻችሁም ያች እኛ ዘንድ መቅረብን የምታቀርባችሁ አይደለችም፡፡ ያመነና መልካምን የሠራ ብቻ ሲቀር፡፡ እነዚያ ለእነርሱ በሠሩት መልካም ሥራ እጥፍ ምንዳ አልላቸው፡፡ እነርሱም በገነት ሰገነቶች ውስጥ ጸጥተኞች ናቸው፡፡'),
('34:38', 87, 'እነዚያም የሚያቅቱ መስሏቸው አንቀጾቻችንን ለማበላሸት የሚጥሩት እነዚያ በቅጣቱ ውስጥ የሚጣዱ ናቸው፡፡'),
('34:39', 87, '«ጌታዬ ሲሳይን ከባሮቹ ለሚሻው ሰው ያሰፋል፡፡ ለእርሱም ያጠብባል፡፡ ከማንኛውም ነገር የምትለግሱትን እርሱ ይተካዋል፡፡ እርሱም ከሲሳይ ሰጪዎች ሁሉ በላጭ ነው» በላቸው፡፡'),
('34:40', 87, 'ሁሉንም በሚሰበስባቸውና ከዚያም ለመላእክቶቹ «እነዚህ እናንተን ይግገዙ ነበሩን?» በሚላቸው ቀን (የሚኾነውን አስታውስ)፡፡'),
('34:41', 87, '(መላእክቶቹም) «ጥራት ይገባህ ከእነርሱ ሌላ ረዳታችን አንተ ብቻ ነህ፡፡ (እንደሚሉት) አይደለም ይልቁንም ጋኔንን ይግገዙ ነበሩ፡፡ አብዛኞቻቸው በእነርሱ አማኞች ናቸው» ይላሉ፡፡'),
('34:42', 87, 'ዛሬም ከፊላችሁ ለከፊሉ መጥቀምንም ኾነ መጉዳትን አይችሉም፡፡ ለእነዚያም ለበደሉት «ያችን በእርሷ ታስተባብሉባት የነበራችሁትን የእሳት ቅጣት ቅመሱ» እንላቸዋለን፡፡'),
('34:43', 87, 'በእነርሱም ላይ አንቀጾቻችን ግልጽ ኾነው በተነበቡላቸው ጊዜ «ይህ አባቶቻችሁ ይግገዙት ከነበሩት ነገር ሊከለክላችሁ የሚፈልግ ሰው እንጂ ሌላ አይደለም» አሉ፡፡ «ይህም (ቁርኣን) የተቀጣጠፈ ውሸት ነው እንጂ ሌላ አይደለም» አሉ፡፡ እነዚያም የካዱት እውነቱ በመጣላቸው ጊዜ «ይህ ግልጽ ድግምት ነው እንጂ ሌላ አይደለም» አሉ፡፡'),
('34:44', 87, 'የሚያጠኑዋቸው የኾኑ መጽሐፍቶችንም ምንም አልሰጠናቸውም፡፡ ከአንተ በፊትም አስፈራሪ ነቢይን ወደእነርሱ አልላክንም፡፡'),
('34:45', 87, 'እነዚያም ከእነርሱ በፊት የነበሩት አስተባብለዋል፡፡ የሰጠናቸውንም ከዐስር አንዱን (እነዚህ) አልደረሱም፡፡ መልክተኞቼንም አስተባበሉ፤ (ነቀፍኳቸውም)፡፡ መንቀፌም እንዴት ነበር!'),
('34:46', 87, '«የምገስጻችሁ ባንዲት ነገር ብቻ ነው፡፡ (እርሷም) ሁለት ሁለት አንድ አንድም ኾናችሁ ለአላህ እንድትነሱ ከዚያም በጓደኛችሁ (በሙሐመድ) ምንም ዕብደት የሌለበት መኾኑን መርምራችሁ እንድትርረዱ ነው፡፡ እርሱ ለእናንተ ከብርቱ ቅጣት በስተፊት አስጠንቃቂ ነው እንጂ ሌላ አይደለም» በላቸው፡፡'),
('34:47', 87, '«ከዋጋ ማንኛውም የጠየቅኋችሁ ቢኖር እርሱ ለእናንተው ነው፤ ዋጋዬ በአላህ ላይ እንጂ በሌላ ላይ አይደለም፡፡ እርሱም በነገሩ ሁሉ ላይ ዐዋቂ ነው» በላቸው፡፡'),
('34:48', 87, '«ጌታዬ እውነትን ያወርዳል፡፡ ሩቅ የኾኑትን ምስጢሮች ሁሉ ዐዋቂ ነው» በላቸው፡፡'),
('34:49', 87, '«እውነቱ መጣ፡፡ ውሸትም መነሻም መድረሻም የለውም (ተወገደ)» በላቸው፡፡'),
('34:50', 87, '«ብሳሳት የምሳሳተው በራሴ ላይ ብቻ ነው፡፡ ብመራም ጌታዬ ወደኔ በሚያወርደው ነው፡፡ እርሱ ሰሚ ቅርብ ነውና» በላቸው፡፡'),
('34:51', 87, 'በደነገጡና ማምለጫ በሌላቸው ጊዜ ከቅርብ ስፍራም በተያዙ ጊዜ (ኹኔታቸውን) ብታይ ኖሮ (አስደናቂን ነገር ባየህ ነበር)፡፡'),
('34:52', 87, '«በእርሱም (አሁን) አመንን» ይላሉ፡፡ ለእነርሱም ከሩቅ ስፍራ (እምነትን) በቀላል ማግኘት ከየታቸው?'),
('34:53', 87, 'በፊትም በእርሱ በእርግጥ ክደዋል፡፡ ከሩቅ ስፍራም በግምት ንግግርን ይጥላሉ፡፡'),
('34:54', 87, 'ከዚህ ቀደም በመሰሎቻቸው እንደ ተሠራውም ብጤ በእነርሱና በሚፈልጉት መካከል ተጋረደ፡፡ እነርሱ በእርግጥ በአወላዋይ ጥርጣሬ ውስጥ ነበሩና፡፡'),
('35:1', 87, 'ምስጋና ሰማያትንና ምድርን ፈጣሪ፣ መላእክትን ባለ ሁለት ሁለት፣ ባለ ሶስት ሶስትም፣ ባለ አራት አራትም ክንፎች የኾኑ መልክተኞች አድራጊ ለኾነው አላህ ይገባው፡፡ በፍጥረቱ ውስጥ የሚሻውን ይጨምራል፡፡ አላህ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('35:2', 87, 'አላህ ለሰዎች ከችሮታ የሚከፍታት ለእርሷ ምንም አጋጅ የላትም፡፡ የሚያግደውም ከእርሱ በኋላ ለእርሱ ምንም ለቃቂ የለውም፡፡ እርሱም አሸነፊው ጥበበኛው ነው፡፡'),
('35:3', 87, 'እናንተ ሰዎች ሆይ! በእናንተ ላይ (ያለውን) የአላህን ጸጋ አስታውሱ፡፡ ከአላህ ሌላ ፈጣሪ አለን? ከሰማይና ከምድርም ሲሳይን የሚሰጣችሁ አለን? ከእርሱ በስተቀር አምላክ (ሰጪም) የለም፡፡ ታዲያ ወዴት ትዞራላችሁ፡፡'),
('35:4', 87, 'ቢያስተባብሉህም ከአንተ በፊት የነበሩ መልክተኞች በእርግጥ ተስተባብለዋል፡፡ ወደ አላህም ነገሮች ሁሉ ይመለሳሉ፡፡'),
('35:5', 87, 'እናንተ ሰዎች ሆይ! የአላህ ቀጠሮ እውነት ነው፡፡ የቅርቢቱም ሕይወት አታታላችሁ፡፡ አታላዩም (ሰይጣን) በአላህ (መታገስ) አያታላችሁ፡፡'),
('35:6', 87, 'ሰይጣን ለናንተ ጠላት ነው፡፡ ስለዚህ ጠላት አድርጋችሁ ያዙት፡፡ ተከታዮቹን የሚጠራው ከእሳት ጓዶች እንዲኾኑ ብቻ ነው፡፡'),
('35:7', 87, 'እነዚያ የካዱት ለእነርሱ ብርቱ ቅጣት አልላቸው፡፡ እነዚያም ያመኑትና በጎ ስራዎችን የሠሩት ለእነርሱ ምሕረትና ታላቅ ምንዳ አልላቸው፡፡'),
('35:8', 87, 'መጥፎ ሥራው የተሸለመለትና መልካም አድርጎ ያየው ሰው (አላህ እንዳቀናው ሰው ነውን?) አላህም የሚሻውን ሰው ያጠምማል፡፡ የሚሻውንም ያቀናል፡፡ ስለዚህ በእነርሱ ላይ (ባለመቅናታቸው) ስለመቆላጨት ነፍስህ አትጥፋ፡፡ አላህ የሚሠሩትን ሁሉ ዐዋቂ ነውና፡፡'),
('35:9', 87, 'አላህም ያ ነፋሶችን የላከ ነው፡፡ ደመናዎችንም ትቀሰቅሳለች፤ ወደ ሙት (ድርቅ) አገርም እንነዳዋለን፡፡ በእርሱም ምድርን ከሞተች በኋላ ሕያው እናደርጋታለን፡፡ ሙታንንም'),
('35:10', 87, 'ማሸነፍን የሚፈልግ የኾነ ሰው አሸናፊነት ለአላህ ብቻ ነው፤ (እርሱን በመግገዛት ይፈልገው)፡፡ መልካም ንግግር ወደርሱ ይወጣል፡፡ በጎ ሥራም ከፍ ያደርገዋል፡፡ እነዚያም መጥፎ ሥራዎችን የሚዶልቱ ለእነሱ ብርቱ ቅጣት አልላቸው፡፡ የእነዚያም ተንኮል እርሱ ይጠፋል፡፡'),
('35:11', 87, 'አላህም ከዐፈር፣ ከዚያም ከፍትወት ጠብታ ፈጠራችሁ፡፡ ከዚያም ጎሳዎች አደረጋችሁ፡፡ ሴትም አታረግዝም አትወልድምም በዕውቀቱ ቢኾን እንጂ፡፡ ዕድሜው ከሚረዘምም አንድም አይረዘምም ከዕድሜውም አይጎደልም በመጽሐፉ ውስጥ ያለ ቢኾን እንጂ፡፡ ይህ በአላህ ላይ ገር ነው፡፡'),
('35:12', 87, 'ሁለቱ ባሕሮችም አይተካከሉም! ይህ ጣፋጭ፣ ጥምን ቆራጭ፣ መጠጡ በገር ተዋጭ ነው፡፡ ይህኛውም ጨው መርጋጋ ነው፡፡ እርጥብ ስጋንም ከሁሉም ትበላላችሁ፡፡ (ከጨው ባሕር) የምትለብሷትንም ጌጥ ታወጣላችሁ፡፡ ከችሮታው ልትፈልጉና ልታመሰግኑም መርከቦችን በእርሱ ውስጥ ውሃውን ቀዳጆች ኾነው (ሲንሻለሉ) ታያለህ፡፡'),
('35:13', 87, 'ሌሊትን በቀን ውስጥ ያስገባል፡፡ ቀንንም በሌሊት ውሰጥ ያስገባል፤ ፀሐይንና ጨረቃንም ገራ፡፡ ሁሉም እተወሰነ ጊዜ ድረስ ይሮጣሉ፡፡ ይህ ጌታችሁ አላህ ነው፡፡ ንግሥናው የእርሱ ብቻ ነው፡፡ እነዚያም ከእርሱ ሌላ የምትግገዟቸው የተምር ፍሬ ሽፋን እንኳ አይኖራቸውም፡፡'),
('35:14', 87, 'ብትጠሩዋቸው ጥሪያችሁን አይሰሙም፡፡ ቢሰሙም ኖሮ ለእናንተ አይመልሱላችሁም፡፡ በትንሣኤም ቀን (እነርሱን በአላህ) ማጋራታችሁን ይክዳሉ፡፡ እንደ ውስጠ ዐዋቂው ማንም አይነግርህም፡፡'),
('35:15', 87, 'እናንተ ሰዎች ሆይ! እናንተ (ሁል ጊዜ) ወደ አላህ ከጃዮች ናችሁ፡፡ አላህም እርሱ ተብቃቂው ምስጉኑ ነው፡፡'),
('35:16', 87, 'ቢሻ ያስወግዳችኋል፡፡ አዲስንም ፍጡር ያመጣል፡፡'),
('35:17', 87, 'ይህም በአላህ ላይ ምንም አስቸጋሪ አይደለም፡፡'),
('35:18', 87, 'ኀጢአትን ተሸካሚም (ነፍስ) የሌላዋን ሸክም አትሸከምም፡፡ የተከበደችም (ነፍስ) ወደ ሸክሟ ብትጣራ (ተጠሪው) የቅርብ ዝምድና ባለቤት ቢኾንም እንኳ ከእርሷ አንዳችን የሚሸከምላት አታገኝም፡፡ የምታስጠነቅቀው እነዚያን ጌታቸውን በሩቅ የሚፈሩትን፣ ሶላትንም አስተካክለው ያደረሱትን ብቻ ነው፡፡ የተጥራራም ሰው የሚጥራራው ለራሱ ብቻ ነው፡፡ መመለሻም ወደ አላህ ብቻ ነው፡፡'),
('35:19', 87, 'ዕውሩና የሚያየውም አይስተካከሉም፡፡'),
('35:20', 87, 'ጨለማዎችና ብርሃንም፤ (እንደዚሁ)፡፡'),
('35:21', 87, 'ጥላና ሐሩርም፡፡'),
('35:22', 87, 'ሕያዋንና ሙታንም አይስተካከሉም፡፡ አላህ የሚሻውን ሰው ያሰማል፡፡ አንተም በመቃብር ውስጥ ያሉትን አሰሚ አይደለህም፡፡'),
('35:23', 87, 'አንተ አስጠንቃቂ እንጂ ሌላ አይደለህም፡፡'),
('35:24', 87, 'እኛ አብሳሪና አስፈራሪ አድርገን በእውነቱ (መምሪያ) ላክንህ፡፡ ማንኛይቱም ሕዝብ በውስጧ አስፈራሪ ያላለፈባት የለችም፡፡'),
('35:25', 87, 'ቢያስተባብሉህም እነዚያ ከበፊታቸው የነበሩት በእርግጥ አስተባብለዋል፡፡ መልክተኞቻቸው'),
('35:26', 87, 'ከዚያም እነዚያን የካዱትን ያዝኳቸው፡፡ ቅጣቴም እንዴት ነበር! (በስፍራው ነው)፡፡'),
('35:27', 87, 'አላህ ከሰማይ ውሃን ማውረዱን አላየህምን? በእርሱም ዓይነቶቻቸው የተለያዩ ፍሬዎችን አወጣን፡፡ ከጋራዎችም መልኮቻቸው የተለያዩ ነጮች፣ ቀዮችም፣ በጣም ጥቁሮችም የኾኑ መንገዶች አልሉ፡፡'),
('35:28', 87, 'ከሰዎችም፣ ከተንቀሳቃሾችም፣ ከቤት እንሰሳዎችም እንደዚሁ መልኮቻቸው የተለያዩ አልሉ፡፡ አላህን ከባሮቹ ውስጥ የሚፈሩት ዐዋቂዎቹ ብቻ ናቸው፡፡ አላህ አሸናፊ መሓሪ ነው፡፡'),
('35:29', 87, 'እነዚያ የአላህን መጽሐፍ የሚያነቡ፣ ሶላትንም አስተካክለው ያደረሱ፣ ከሰጠናቸውም ሲሳይ በምስጢርም ኾነ በግልጽ የለገሱ፣ በፍጹም የማትከስርን ንግድ ተስፋ ያደርጋሉ፡፡'),
('35:30', 87, 'ምንዳዎቻቸውን ሊሞላላቸው፣ ከችሮታውም ሊጨምርላቸው (ተስፋ ያደርጋሉ)፡፡ እርሱ በጣም መሓሪ አመስጋኝ ነውና፡፡'),
('35:31', 87, 'ያም ከመጽሐፉ ወዳንተ ያወረድንልህ ከበፊቱ ላለው አረጋጋጭ ሲኾን እርሱ እውነት ነው፡፡ አላህ በርግጥ በባሮቹ ውስጥ ዐዋቂ ተመልካች ነው፡፡'),
('35:32', 87, 'ከዚያም እነዚያን ከባሮቻችን የመረጥናቸውን መጽሐፉን አወረስናቸው፡፡ ከእነርሱም ነፍሱን በዳይ አልለ፡፡ ከእነርሱም መካከለኛ አልለ፡፡ ከእነሱም በአላህ ፈቃድ በበጎ ሥራዎች ቀዳሚ አልለ፡፡ ያ (ማውረስ)፤ እርሱ ታላቅ ችሮታ ነው፡፡'),
('35:33', 87, 'የመኖሪያ ገነቶችን በውስጧ የወርቅ አንባሮችን፣ ሉልንም የሚሸለሙ ኾነው ይገቡባታል፡፡ በእርሷ ውስጥ አልባሳታቸውም ሐር ነው፡፡'),
('35:34', 87, 'ይላሉም «ምስጋና ለእዚያ ከእኛ ላይ ሐዘንን ላስወገደልን አላህ ይገባው፡፡ ጌታችን በጣም መሓሪ አመስጋኝ ነውና፡፡'),
('35:35', 87, '(እርሱም) ያ ከችሮታው የዘላለም መኖሪያን አገር ያሰፈረን ነው፡፡ በእርሷ ውስጥ መከራ አይነካንም፡፡ በእርሷም ውስጥ ድካም አይነካንም፡፡»'),
('35:36', 87, 'እነዚያ የካዱትም ለእነርሱ የገሀነም እሳት አልላቸው፡፡ ይሞቱ ዘንድ በእነርሱ ላይ (በሞት) አይፈረድም፡፡ ከቅጣቷም ከእነርሱ አይቀለልላቸውም፡፡ እንደዚሁ ከሓዲን ሁሉ እንመነዳለን፡፡'),
('35:37', 87, 'እነርሱም በርሷ ውስጥ እርዳታን በመፈለግ በኀይል ይጮሃሉ፡፡ «ጌታችን ሆይ! ከእዚያ እንሠራው ከነበርነው ሌላ በጎ ሥራን እንሠራ ዘንድ አውጣን» (ይላሉ)፡፡ «በእርሱ ውስጥ ያስታወሰ ሰው የሚገሰጽበትን ዕድሜ አላቆየናችሁምን? አስጠንቃቂውም መጥቶላችኋል (አስተባብላችኋልም)፡፡ ስለዚህ ቅመሱ፡፡ ለበደለኞችም ምንም ረዳት የላቸውም» (ይባላሉ)፡፡'),
('35:38', 87, 'አላህ የሰማያትንና የምድርን ምስጢር በእርግጥ ዐዋቂ ነው፡፡ እርሱ በልቦች ውስጥ ያለን ሁሉ ዐዋቂ ነውና፡፡'),
('35:39', 87, 'እርሱ ያ በምድር ውስጥ ምትኮች ያደረጋችሁ ነው፡፡ የካደም ሰው ክህደቱ በእርሱው ላይ ብቻ ነው፡፡ ከሓዲዎችንም ክሕደታቸው ከጌታቸው ዘንድ መጠላትን እንጂ ሌላ አይጨመርላቸውም፡፡ ከሓዲዎችንም ክሕደታቸው ከሳራን እንጂ አይጨምርላቸውም፡፡'),
('35:40', 87, 'በላቸው «እነዚያን ከአላህ ሌላ የምትግገዟቸውን ተጋሪዎቻችሁን አያችሁን? ከምድር ምንን እንደ ፈጠሩ አሳዩኝ፡፡ ወይስ ለእነርሱ በሰማያት ውስጥ ሽርክና አላቸውን? ወይስ መጽሐፍን ሰጠናቸውና እነርሱ ከርሱ በግልጽ አስረጅ ላይ ናቸውን? አይደለም በደለኞች ከፊላቸው ከፊሉን ማታለልን እንጂ አይቀጥሩም፡፡»'),
('35:41', 87, 'አላህ ሰማያትንና ምድርን እንዳይወገዱ ይይዛቸዋል፡፡ ቢወገዱም ከእርሱ ሌላ አንድም የሚይዛቸው የለም፡፡ እነሆ እርሱ ታጋሽ መሓሪ ነውና፡፡'),
('35:42', 87, 'አስፈራሪም ቢመጣላቸው ከሕዝቦቹ ሁሉ ከአንደኛዋ ይበልጥ የተመሩ ሊኾኑ የመሓላቸውን ድካ አድርሰው በአላህ ማሉ፡፡ አስፈራሪም በመጣላቸው ጊዜ መበርገግን እንጂ ሌላ አልጨመረላቸውም፡፡'),
('35:43', 87, 'በምድር ላይ ኩራትንና በክፉ (ተንኮል) መዶለትንም (እንጂ አልጨመረላቸውም፡፡ ክፉ ተንኮልም በባለቤቱ ላይ እንጂ በሌላ ላይ አይሰፍርም፡፡ የቀድሞዎቹን ደንብ እንጂ ይጠባበቃሉን? ለአላህ ደንብም መልለወጥን አታገኝም፡፡ ለአላህ ደንብም መዛወርን አታገኝም፡፡'),
('35:44', 87, 'በምድር ላይ አይኼዱምና የእነዚያን ከእነርሱ በፊት የነበሩትን ሰዎች መጨረሻ እንዴት እንደ ነበረ አይመለከቱምን? ከእነርሱም በኀይል የበረቱ ነበሩ፡፡ አላህም በሰማያትም ኾነ በምድር ውስጥ ምንም ነገር የሚያቅተው አይደለም፡፡ እርሱ ዐዋቂ ቻይ ነውና፡፡'),
('35:45', 87, 'አላህም ሰዎችን በሠሩት ኀጢአት ቢይዝ ኖሮ በወለሏ (በምድር) ላይ ምንም ተንቀሳቃሽ'),
('36:1', 87, 'የ.ሰ.(ያ ሲን)'),
('36:2', 87, 'ጥበብ በተመላበት ቁርኣን እምላለሁ፡፡'),
('36:3', 87, 'አንተ በእርግጥ ከመልክተኞቹ ነህ፡፡'),
('36:4', 87, 'በቀጥታም መንገድ ላይ ነህ፡፡'),
('36:5', 87, 'አሸናፊ አዛኝ ከሆነው አምላክ መወረድን ተወረደ፡፡'),
('36:6', 87, 'አባቶቻቸው ያልተስፈራሩትን ሕዝቦች ልታስጠነቅቅበት (ተወረደ)፡፡ እነርሱ ዘንጊዎች ናቸውና፡፡'),
('36:7', 87, 'በአብዛኞቻቸው ላይ ቃሉ በእውነት ተረጋገጠ፡፡ ስለዚህ እነርሱ አያምኑም፡፡'),
('36:8', 87, 'እኛ በአንገቶቻቸው ላይ እንዛዝላዎችን አደረግን፡፡ እርሷም (እንዛዝላይቱ) ወደ አገጮቻቸው ደራሽ ናት፡፡ እነርሱም ራሶቻቸውን ያንጋጠጡ ናቸው፡፡'),
('36:9', 87, 'ከስተፊታቸውም ግርዶን ከስተኋላቸውም ግርዶን አደረግን፡፡ ሸፈንናቸውም፡፡ ስለዚህ እነሱ አያዩም፡፡'),
('36:10', 87, 'ብታሰጠነቅቃቸውም ባታስጠነቅቃቸውም በእነርሱ ላይ እኩል ነው፡፡ አያምኑም፡፡'),
('36:11', 87, 'የምታስጠነቅቀው ግሳጼን የተከተለንና አልረሕማንን በሩቅ የፈራን ሰው ብቻ ነው፡፡ በምሕረትና በመልካም ምንዳም አብስረው፡፡'),
('36:12', 87, 'እኛ ሙታንን እኛ በእርግጥ ሕያው እናደርጋለን፡፡ ያስቀደሙትንም ሥራ ፈለጎቻቸውንም እንጽፋለን፡፡ ነገሩንም ሁሉ ገላጭ መሪ በኾነ መጽሐፍ ውስጥ አጠቃለልነው፡፡'),
('36:13', 87, 'ለእነርሱም የከተማይቱን (የአንጾኪያን) ሰዎች ምሳሌ መልክተኞቹ በመጧት ጊዜ (የኾነውን) ግለጽላቸው፡፡'),
('36:14', 87, 'ወደእነርሱ ሁለትን ሰዎች በላክንና ባስተባበሉዋቸው ጊዜ በሶስተኛም በአበረታንና እኛ ወደ እናንተ መልክተኞች ነን ባሏቸው ጊዜ (የኾነውን ምሳሌ ግለጽላቸው)፡፡'),
('36:15', 87, 'እናንተ መሰላችን ሰዎች እንጂ ሌላ አይደላችሁም፡፡ አልረሕማንም ምንም ነገር አላወረደም፡፡ እናንተ የምትዋሹ እንጂ ሌላ አይደላችሁም አሉዋቸው፡፡'),
('36:16', 87, '(መልክተኞቹም) አሉ «ጌታችን ያውቃል፡፡ እኛ ወደእናንተ በእርግጥ መልክተኞች ነን፡፡'),
('36:17', 87, '«በእኛ ላይም ግልጽ የኾነ ማድረስ እንጂ ሌላ የለብንም፡፡»'),
('36:18', 87, '(ሕዝቦቹም) «እኛ በእናንተ ገደ ቢሶች ኾን፡፡ ባትከለከሉ በእርግጥ እንወግራችኋለን፡፡ ከእኛም አሳማሚ ቅጣት በእርግጥ ያገኛችኋል» አሉ፡፡'),
('36:19', 87, '«ገደ ቢስነታችሁ ከእናንተው ጋር ነው፡፡ ብትገሰጹ (ትዝታላችሁን?) በእውነቱ እናንተ ወሰን አላፊዎች ሕዝቦች ናችሁ» አሏቸው፡፡'),
('36:20', 87, 'ከከተማይቱም ሩቅ ዳርቻ የሚሮጥ ሰው መጣ፡፡ «ወገኖቼ ሆይ! መልክተኞቹን ተከተሉ» አለ፡፡'),
('36:21', 87, '«እነርሱ ቅኑን መንገድ የተመሩ ሲኾኑ ዋጋን የማየጠይቁዋችሁን ሰዎች ተከተሉ» (አላቸው)፡፡'),
('36:22', 87, '«ያንንም የፈጠረኝን፤ ወደርሱም የምትመለሱበትን (ጌታ) የማልገዛ ለእኔ ምን አለኝ?» (አለ)፡፡'),
('36:23', 87, '«ከእርሱ ሌላ አማልክትን እይዛለሁን? አልረህማን በጉዳት ቢሻኝ ምልጃቸው ከእኔ (ለመመለስ) ምንም አትጠቅመኝም፤ አያድኑኝምም፡፡'),
('36:24', 87, '«እኔ ያን ጊዜ በግልጽ ስህተት ውስጥ ነኝ፡፡'),
('36:25', 87, '«እኔ በጌታችሁ አመንኩ፤ ስሙኝም፤» (አለ)፡፡'),
('36:26', 87, '«ገነትን ግባ» ተባለ፡፡ (እርሱም) አለ፡- «ወገኖቼ ቢያውቁ እመኛለሁ፡፡'),
('36:27', 87, '«ጌታዬ ለእኔ ምሕረት ያደረገልኝና ከተከበሩትም ያደረገኝ መኾኑን፡፡»'),
('36:28', 87, 'ከእርሱም በኋላ በሕዝቦቹ ላይ (ልናጠፋቸው) ሰራዊትን ከሰማይ አላወረድንም፡፡ (በማንም ላይ) አወራጆችም አልነበርንም፡፡'),
('36:29', 87, '(ቅጣታቸው) አንዲት ጩኸት እንጂ ሌላ አልነበረችም፡፡ ወዲያውኑም እነርሱ ጠፊዎች ኾኑ፡፡'),
('36:30', 87, 'በባሮቹ ላይ ዋ ቁልጭት! ከመልክተኛ አንድም አይመጣቸውም በእርሱ የሚሳለቁበት ቢኾኑ እንጅ፡፡'),
('36:31', 87, 'ከእነርሱ በፊት ከክፍለ ዘመናት ሕዝቦች ብዙዎችን ማጥፋታችንንና እነርሱ ወደነርሱ የማይመለሱ መኾናቸውን አላወቁምን?'),
('36:32', 87, 'ሁሉም እኛ ዘንድ የሚሰበሰቡ የሚቀረቡ እንጂ ሌላ አይደሉም፡፡'),
('36:33', 87, 'የሞተችውም ምድር ለእነርሱ ምልክት ናት! ሕያው አደረግናት፡፡ ከእርሷም ፍሬን አወጣን፤ ከርሱም ይበላሉ፡፡'),
('36:34', 87, 'በእርሷም ውሰጥ ከዘምበባዎችና ከወይኖች የኾኑ አትክልቶችን አደረግን፡፡ በእርሷም ውስጥ ምንጮችን አፈለቅን፡፡'),
('36:35', 87, 'ከፍሬውና እጆቻቸው ከሠሩትም ይበሉ ዘንድ (ይህን አደረግን)፤ አያመሰግኑምን?'),
('36:36', 87, 'ያ ምድር ከምታበቅለው ከነፍሶቻቸውም ከማያውቁትም ነገር ዓይነቶችን ሁሏንም የፈጠረ (አምላክ) ጥራት ይገባው፡፡'),
('36:37', 87, 'ሌሊቱም ለእነርሱ ምልክት ነው፡፡ ከእርሱ ላይ ቀንን እንገፍፋለን፡፡ ወዲያውኑም እነርሱ በጨለማ ውስጥ ይገባሉ፡፡'),
('36:38', 87, 'ፀሐይም ለእርሷ ወደ ሆነው መርጊያ ትሮጣለች፡፡ ይህ የአሸናፊው የዐዋቂው አምላክ ውሳኔ ነው፡፡'),
('36:39', 87, 'ጨረቃንም የመስፈሪያዎች ባለቤት ሲኾን እንደ ዘንባባ አሮጌ ቀንዘል እስኪኾን ድረስ (መኼዱን) ለካነው፡፡'),
('36:40', 87, 'ፀሐይ ጨረቃን ልትደርስበት አይገባትም፡፡ ሌሊትም ቀንን (ያለ ጊዜው) ቀዳሚ አይኾንም፡፡ ሁሉም በመዞሪያቸው ውስጥ ይዋኛሉ፡፡'),
('36:41', 87, 'እኛም (የቀድሞ) ትውልዳቸውን በተሞላች መርከብ ውስጥ የጫን መኾናችን ለእነርሱ ምልክት ነው፡፡'),
('36:42', 87, 'ከመሰሉም በእርሱ የሚሳፈሩበትን ለእነርሱ ፈጠርንላቸው፡፡'),
('36:43', 87, 'ብንሻም እናሰጥማቸዋለን፡፡ ለእነርሱም ረዳት የላቸውም፡፡ እነርሱም የሚድዳኑ አይደሉም፡፡'),
('36:44', 87, 'ግን ከእኛ ለኾነው ችሮታና እስከ ጊዜ ሞታቸው ለማጣቀም (አዳንናቸው)፡፡'),
('36:45', 87, 'ለእነርሱም «በስተፊታችሁና በኋለችሁ ያለውን ነገር ተጠንቀቁ ይታዘንላችኋልና» በተባሉ ጊዜ (ፊታቸውን ያዞራሉ)፡፡'),
('36:46', 87, 'ከጌታቸውም ተዓምራት ማንኛይቱም ተዓምር አትመጣላቸውም፤ ከእርሷ የሚሸሹ ቢኾኑ እንጅ፡፡'),
('36:47', 87, 'ለእነርሱም «አላህ ከሰጣችሁ ሲሳይ ለግሱ» በተባሉ ጊዜ እነዚያ የካዱት ለእነዚያ ላመኑት «አላህ ቢሻ ኖሮ የሚያበላውን ሰው እናበላለን? እናንተ በግልጽ ስህተት ውስጥ እንጂ በሌላ ላይ አይደላችሁም» ይላሉ፡፡'),
('36:48', 87, '«እውነተኞችም እንደኾናችሁ ይህ ቀጠሮ መቼ ነው?» ይላሉ፡፡'),
('36:49', 87, 'እነርሱ የሚከራከሩ ሲኾኑ በድንገት የምትይዛቸው የኾነችን አንዲትን ጩኸት እንጂ ሌላን አይጠባበቁም፡፡'),
('36:50', 87, '(ያን ጊዜ) መናዘዝንም አይችሉም፡፡ ወደ ቤተሰቦቻቸወም አይመለሱም፡፡'),
('36:51', 87, 'በቀንዱም ይነፋል፡፡ ወዲያውኑም እነርሱ ከመቃብሮቻቸው ወደ ጌታቸው በፍጥነት ይገሰግሳሉ፡፡'),
('36:52', 87, '«ወይ ጥፋታችን! ከመኝታችን ማን ቀሰቀሰን? ይህ ያ አዛኙ ጌታ (በእርሱ) የቀጠረን መልክተኞቹም እውነትን የነገሩን ነው» ይላሉ፡፡'),
('36:53', 87, '(እርሷ) አንዲት ጩኸት እንጂ አይደለችም፡፡ ወዲያውኑም እነርሱ እኛ ዘንድ የሚሰበሰቡ የሚቀርቡ ናቸው፡፡'),
('36:54', 87, '«ዛሬም ማንኛይቱም ነፍስ ምንም አትበደልም፡፡ ትሠሩትም የነበራችሁትን እንጂ ሌላን አትመነዱም» (ይባላሉ)፡፡'),
('36:55', 87, 'የገነት ሰዎች ዛሬ በእርግጥ በሥራዎች ውስጥ ተደሳቾች ናቸው፡፡'),
('36:56', 87, 'እነርሱም ሚስቶቻቸውም በጥላዎች ውስጥ ናቸው፡፡ ባለ አጎበር አልጋዎች ላይ ተደጋፊዎች ናቸው፡፡'),
('36:57', 87, 'በውስጧ ለእነርሱ ፍራፍሬዎች አሏቸው፡፡ ለእነርሱም የሚፈልጉት ሁሉ አልላቸው፡፡'),
('36:58', 87, '(ለእነርሱም) አዛኝ ከሆነው ጌታ በቃል ሰላምታ አላቸው።'),
('36:59', 87, '(ይላልም) «እናንተ አመጸኞች ሆይ! ዛሬ (ከምእምናን) ተለዩ፡፡»'),
('36:60', 87, 'የአደም ልጆች ሆይ! ሰይጣንን አትገዙ፤ እርሱ ለእናንተ ግልጽ ጠላት ነውና በማለት ወደእናንተ አላዘዝኩምን?'),
('36:61', 87, 'ተገዙኝም፤ ይህ ቀጥተኘ መንገድ ነው፤ (በማለትም)፡፡'),
('36:62', 87, 'ከእናንተም ብዙን ፍጡር በእርግጥ አሳስቷል፡፡ የምታውቁም አልነበራችሁምን?'),
('36:63', 87, 'ይህቺ ያቺ ትቀጠሩዋት የነበረችው ገሀነም ናት፡፡'),
('36:64', 87, 'ትክዱ በነበራችሁት ምክንያት ዛሬ ግቧት (ይባላሉ)፡፡'),
('36:65', 87, 'ዛሬ በአፎቻቸው ላይ እናትምና እጆቻቸው ያነጋግሩናል፡፡ እግሮቻቸውም ይሠሩት በነበሩት ሁሉ ይመሰክራሉ፡፡'),
('36:66', 87, 'ብንሻም ኖሮ በዐይኖቻቸው ላይ በአበስን ነበር፡፡ መንገድንም (እንደ ልመዳቸው) በተሽቀዳደሙ ነበር፡፡ እንዴትም ያያሉ?'),
('36:67', 87, 'ብንሻም ኖሮ በስፍራቸው ላይ እንዳሉ ወደ ሌላ ፍጥረት በለወጠናቸው ነበር፡፡ መኼድንም መመለስንም ባልቻሉም ነበር፡፡'),
('36:68', 87, 'ዕድሜውንም የምናረዝመውን ሰው በፍጥረቱ (ወደ ደካማነት) እንመልሰዋለን፤ አያውቁምን?'),
('36:69', 87, '(ሙሐመድን) ቅኔንም አላስተማርነውም፡፡ ለእርሱም አይግገባውም፡፡ እርሱ (መጽሐፉ) መገሰጫና ገላጭ ቁርኣን እንጅ (ቅኔ) አይደለም፡፡'),
('36:70', 87, '(ግሣጼነቱም ልቡ) ሕያው የኾነን ሰው ሊያስፈራራበትና ቃሉም በከሓዲዎች ላይ ይፈጸም ዘንድ ነው፡፡'),
('36:71', 87, 'እኛ እጆቻችን (ኃይሎቻችን) ከሠሩት ለእነርሱ እንስሳዎችን መፍጠራችንን አያውቁምን? እነርሱም ለእርሷ ባለ መብቶች ናቸው፡፡'),
('36:72', 87, 'ለእነርሱም ገራናት፡፡ ስለዚህ ከእርሷ ውስጥ የሚጋልቡት አልለ፡፡ ከእርሷም ይበላሉ፡፡'),
('36:73', 87, 'ለእነርሱም በእርሷ ውስጥ (ሌሎች) ጥቅሞች መጠጦችም አሉዋቸው፡፡ ታዲያ አያመሰግኑምን;'),
('36:74', 87, 'መረዳትንም በመከጀል ከአላህ ሌላ አማልክትን ያዙ፡፡'),
('36:75', 87, 'መርዳታቸውን አይችሉም፡፡ እነርሱም ለእርሳቸው (ወደ እሳት) የተቀረቡ ሰራዊት ናቸው፡፡'),
('36:76', 87, 'ንግግራቸውም አያሳዝንህ፡፡ እኛ የሚደብቁትንም የሚገልጹትንም እናውቃለንና፡፡'),
('36:77', 87, 'ሰውየው እኛ ከፍቶት ጠብታ የፈጠርነው መኾናችን አላወቀምን? ወዲያውም እርሱ (ትንሣኤን በመካድ) ግልጽ ተከራካሪ ይኾናልን?'),
('36:78', 87, 'ለእኛም ምሳሌን አደረገልን፡፡ መፈጠሩንም ረሳ፡፡ «አጥንቶችን እነርሱ የበሰበሱ ሲኾኑ ሕያው የሚያደርጋቸው ማነው?» አለ፡፡'),
('36:79', 87, '«ያ በመጀመሪያ ጊዜ (ከኢምንት) ያስገኛት ሕያው ያደርጋታል፡፡ እርሱም በፍጡሩ ሁሉ (ኹኔታ) ዐዋቂ ነው» በለው፡፡'),
('36:80', 87, 'ያ ለእናንተ በእርጥብ ዛፍ እሳትን ያደረገላችሁ ነው፡፡ ወዲያውኑም እናንተ ከእርሱ ታቀጣጥላላችሁ፡፡'),
('36:81', 87, 'ያ ሰማያትንና ምድርን የፈጠረ ብጤያቸውን በመፍጠር ላይ ቻይ አይደለምን? ነው እንጅ፡፡ እርሱም በብዙ ፈጣሪው ዐዋቂው ነው፡፡'),
('36:82', 87, 'ነገሩም አንዳችን በሻ ጊዜ ኹን ማለት ነው፡፡ ወዲያው ይኾናልም፡፡'),
('36:83', 87, 'ያ የነገሩ ሁሉ ስልጣን በእጁ የኾነው ጌታ ጥራት ይገባው፡፡ ወደእርሱም ትመለሳላችሁ፡፡'),
('37:1', 87, 'መሰለፍን በሚሰለፉት፡፡'),
('37:2', 87, 'መገሠጽንም በሚገሥጹት፤'),
('37:3', 87, 'ቁርኣንንም በሚያነቡት እምላለሁ፡፡'),
('37:4', 87, 'አምላካችሁ በእርግጥ አንድ ነው፡፡'),
('37:5', 87, 'የሰማያትና የምድር በመካከላቸው ያለውም ፍጡር ሁሉ ጌታ ነው፡፡ የምሥራቆችም ጌታ ነው፡፡'),
('37:6', 87, 'እኛ ቅርቢቱን ሰማይ በከዋክብት ጌጥ አጌጥናት፡፡'),
('37:7', 87, 'አመጸኛም ከሆነ ሰይጣን ሁሉ መጠበቅን ጠበቅናት፡፡'),
('37:8', 87, 'ወደላይኛው ሰራዊት አያዳምጡም፡፡ ከየወገኑም ሁሉ ችቦ ይጣልባቸዋል፡፡'),
('37:9', 87, 'የሚባረሩ ሲሆኑ (ይጣልባቸዋል)፡፡ ለእነሱም ዘውታሪ ቅጣት አላቸው፡፡'),
('37:10', 87, 'ንጥቂያን የነጠቀ ወዲያውም አብሪ ኮከብ የተከተለው ሲቀር፤ (እርሱ ይሰማዋል)፡፡'),
('37:11', 87, 'ጠይቃቸውም፤ እነርሱ በአፈጣጠር ይበልጥ የበረቱ ናቸውን? ወይስ እኛ (ከእነርሱ በፊት) የፈጠርነው? (ፍጡር) እኛ ከሚጣበቅ ጭቃ ፈጠርናቸው፡፡'),
('37:12', 87, 'ይልቁንም (በማስተባበላቸው) ተደነቅህ፤(ከመደነቅህ) ይሳለቃሉም፡፡'),
('37:13', 87, 'በተገሠጹም ጊዜ አይመለሱም፡፡'),
('37:14', 87, 'ተዓምርን ባዩም ጊዜ ለመሳለቅ ይጠራራሉ፡፡'),
('37:15', 87, 'ይላሉም «ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም፡፡'),
('37:16', 87, '«በሞትንና ዐፈርና አጥንቶችም በኾን ጊዜ እኛ የምንቀሰቀስ ነን?'),
('37:17', 87, '«የቀድሞዎቹ አባቶችንም? (ይላሉ)፡፡'),
('37:18', 87, '«አዎን እናንተ ወራዶች ሆናችሁ (ትነሳላችሁ)» በላቸው፡፡'),
('37:19', 87, 'እርሷም አንዲት ጩኸት ብቻ ናት፡፡ እነርሱም ወዲያውኑ (ምን እንደሚፈጸምባቸው) ያያሉ፡፡'),
('37:20', 87, '«ዋ ጥፋታችን! ይህ የፍርዱ ቀን ነው» ይላሉም፡፡'),
('37:21', 87, '«ይህ ያ በእርሱ ታስተባብሉ የነበራችሁት መለያው ቀን ነው» (ይባላሉ)፡፡'),
('37:22', 87, '(ለመላእክቶችም) «እነዚያን ነፍሶቻቸውን የበደሉትን ሰዎች ጓደኞቻቸውንም ይግገዟቸው የነበሩትንም (ጣዖታት) ሰብስቡ፡፡'),
('37:23', 87, '«ከአላህ ሌላ (የሚገዙዋቸውን ሰብስቧቸው) ወደ እሳት መንገድም ምሩዋቸው፡፡'),
('37:24', 87, '«አቁሟቸውም፡፡ እነርሱ ተጠያቂዎች ናቸውና» (ይባላል)፡፡'),
('37:25', 87, '(ለእነርሱም) «የማትረዳዱት ለእናንተ ምን አላችሁ? (ይባላሉ)፡፡'),
('37:26', 87, 'በእርግጥ እነርሱ ዛሬ እጃቸውን የሰጡ ወራዳዎች ናቸው፡፡'),
('37:27', 87, 'የሚወቃቀሱም ሆነው ከፊላቸው በከፊሉ ላይ ይመጣሉ፡፡'),
('37:28', 87, '(ለአስከታዮቹ) እናንተ ከስተቀኝ ትመጡብን ነበር ይላሉ፡፡'),
('37:29', 87, '(አስከታዮቹም) ይላሉ «አይደለም ፈጽሞ ምእምናን አልነበራችሁም፡፡'),
('37:30', 87, '«ለእኛም በእናንተ ላይ ምንም ስልጣን አልነበረንም፡፡ በእርግጥ እናንተ ጠማሞች ሕዝቦች ነበራችሁ፡፡'),
('37:31', 87, '«በእኛም ላይ የጌታችን ቃል ተረጋገጠብን፤ እኛ (ሁላችንም ቅጣቱን) ቀማሾች ነን፡፡'),
('37:32', 87, '«ወደ ጥምመት ጠራናችሁም፡፡ እኛ ጠማሞች ነበርንና» (ይላሉ)፡፡'),
('37:33', 87, 'ስለዚህ እነርሱ በዚያ ቀን በቅጣቱ ነጋሪዎች ናቸው፡፡'),
('37:34', 87, 'እኛ በአመጸኞች ሁሉ እንደዚሁ እንሠራለን፡፡'),
('37:35', 87, 'እነርሱ ከአላህ ሌላ አምላክ የለም በተባሉ ጊዜ ይኮሩ ነበሩ፡፡'),
('37:36', 87, 'እኛ ለዕብድ ባለቅኔ ብለን አማልክቶቻችንን የምንተው ነን? ይሉም ነበር፡፡'),
('37:37', 87, 'አይደለም እውነቱን (ሃይማኖት) አመጣ፡፡ መልክተኞቹንም እውነተኛነታቸውን አረጋገጠ፡፡'),
('37:38', 87, 'እናንተ አሳማሚውን ቅጣት በእርግጥ ቀማሾች ናችሁ፡፡'),
('37:39', 87, 'ትሠሩትም የነበራችሁትን እንጂ ሌላን አትመነዱም፡፡'),
('37:40', 87, 'ግን ምርጥ የሆኑት የአላህ ባሮች (ቅጣትን አይቀምሱም)፡፡'),
('37:41', 87, 'እነዚያ ለእነርሱ የታወቀ ሲሳይ አላቸው፡፡'),
('37:42', 87, 'ፍራፍሬዎች (አሏቸው) እነርሱም የተከበሩ ናቸው፤'),
('37:43', 87, 'በድሎት ገነቶች ውስጥ፡፡'),
('37:44', 87, 'ፊት ለፊት የሚታያዩ ሲሆኑ በአልጋዎች ላይ (ይንፈላሰሳሉ)፡፡'),
('37:45', 87, 'ከሚመነጭ ወይን ጠጅ በያዘ ብርጭቆ በእነርሱ ላይ ይዞርባቸዋል፡፡'),
('37:46', 87, 'ነጭ ለጠጪዎች ጣፋጭ ከኾነች፡፡'),
('37:47', 87, 'በእርሷ ውስጥም ምታት የለባትም፡፡ እነርሱም ከእርሷ የሚሰክሩ አይደሉም፡፡'),
('37:48', 87, 'እነርሱም ዘንድ ዓይናቸውን (በባሎቻቸው ላይ) አሳጣሪዎች የኾኑ ዓይናማዎች አልሉ፡፡'),
('37:49', 87, 'እነርሱ ልክ የተሸፈነ (የሰጎን) ዕንቁላል ይመስላሉ፡፡'),
('37:50', 87, 'የሚጠያየቁም ሆነው ከፊላቸው ወደ ከፊሉ ይመጣሉ፡፡'),
('37:51', 87, 'ከእነርሱ የሆነ ተናጋሪ ይላል «እኔ ጓደኛ ነበረኝ፡፡'),
('37:52', 87, '«በእርግጥ አንተ ከሚያምኑት ነህን? የሚል፡፡'),
('37:53', 87, '«በሞትንና ዐፈር አጥንቶችም በሆን ጊዜ እኛ በእርግጥ እንመረመራለን?» (የሚል)፡፡'),
('37:54', 87, 'እናንተ ተመልካቾች ናችሁን? ይላል፡፡'),
('37:55', 87, 'ይመለከታልም፤ በገሀነም መካከልም (ጓደኛውን) ያየዋል፡፡'),
('37:56', 87, 'ይላል «በአላህ እምላለሁ፤ በእርግጥ ልታጠፋኝ ቀርበህ ነበር፡፡'),
('37:57', 87, '«የጌታየም ጸጋ ባልነበረ ኖሮ ወደ እሳት ከሚቀርቡት እሆን ነበር፡፡»'),
('37:58', 87, '(የገነት ሰዎች ይላሉ) «እኛ የምንሞት አይደለንምን?'),
('37:59', 87, '«የመጀመሪያይቱ መሞታችን ብቻ ስትቀር፡፡ እኛም የምንቅቀጣ አይደለንምን?» (ይላሉ)፡፡'),
('37:60', 87, 'ይህ (ለገነት ሰዎች የተወሳው) እርሱ በእርግጥ ታላቅ ዕድል ነው፡፡'),
('37:61', 87, 'ለዚህ ብጤ ሠሪዎች ይሥሩ፡፡'),
('37:62', 87, 'በመስተንግዶነት ይህ ይበልጣልን? ወይስ የዘቁም ዛፍ?'),
('37:63', 87, 'እኛ ለበዳዮች ፈተና አድርገናታል፡፡'),
('37:64', 87, 'እርሷ በገሀነም አዘቅት ውስጥ የምትወጣ ዛፍ ናት፡፡'),
('37:65', 87, 'እንቡጧ ልክ የሰይጣናት ራሶች ይመስላል፡፡'),
('37:66', 87, 'እነርሱም ከእርሷ በይዎች ናቸው፤ ሆዶችንም ከእርሷ ሞይዎች ናቸው፡፡'),
('37:67', 87, 'ከዚያም ለእነርሱ በእርሷ ላይ ከተኳሳ ውሃ ቅልቅል (መጠጥ) አልላቸው፡፡'),
('37:68', 87, 'ከዚያም መመለሻቸው ወደ ተጋጋመች እሳት ነው፡፡'),
('37:69', 87, 'እነሱ አባቶቻቸውን የተሳሳቱ ሆነው አግኝተዋልና፡፡'),
('37:70', 87, 'እነሱም በፈለጎቻቸው ላይ ይገሰግሳሉና፡፡'),
('37:71', 87, 'ከእነርሱ በፊትም የቀድሞዎቹ (ሕዝቦች) አብዛኞቻቸው በእርግጥ ተሳስተዋል፡፡'),
('37:72', 87, 'በውስጣቸውም አስፈራሪዎችን በእርግጥ ልከናል፡፡'),
('37:73', 87, 'የተስፈራሪዎቹም መጨረሻ እንዴት እንደነበረ ተመልከት፡፡'),
('37:74', 87, 'ምርጥ የሆኑት የአላህ ባሮች ብቻ ሲቀሩ፡፡'),
('37:75', 87, 'ኑሕም በእርግጥ ጠራን፡፡ ጥሪውን ተቀባዮቹም ምንኛ አማርን!'),
('37:76', 87, 'እርሱንም ቤተሰቦቹንም ከከባድ ጭንቅ አዳንን፡፡'),
('37:77', 87, 'ዘሮቹንም እነርሱን ብቻ ቀሪዎች አደረግን፤'),
('37:78', 87, 'በርሱም ላይ በኋለኞቹ ሕዝቦች ውስጥ (መልካም ዝናን) ተውን፡፡'),
('37:79', 87, '«በዓለማት ውስጥ ሰላም በኑሕ ላይ ይኹን፡፡»'),
('37:80', 87, 'እኛ እንደዚሁ መልካም ሠሪዎችን እንመነዳለን፡፡'),
('37:81', 87, 'እርሱ ከምእምናን ባሮቻችን ነውና፡፡'),
('37:82', 87, 'ከዚያም ሌሎቹን አሰጠምን፡፡'),
('37:83', 87, 'ኢብራሂምም በእርግጥ ከተከታዮቹ ነው፡፡'),
('37:84', 87, 'ወደ ጌታው በቅን ልብ በመጣ ጊዜ (የኾነውን አስታውስ)፡፡፡'),
('37:85', 87, '«ለአባቱና ለሕዝቦቹ ምንን ትግገዛላችሁ?» ባለ ጊዜ፡፡'),
('37:86', 87, '«ለቅጥፈት ብላችሁ ከአላህ ሌላ አማልክትን ትሻላችሁን?'),
('37:87', 87, '«በዓለማትም ጌታ ሃሳባችሁ ምንድን ነው?» አለ፡፡'),
('37:88', 87, 'በከዋክብትም መመልከትን ተመለከተ፡፡'),
('37:89', 87, '«እኔ በሽተኛ ነኝም» አለ፡፡'),
('37:90', 87, 'ከእርሱም የሸሹ ሆነው ኼዱ፡፡'),
('37:91', 87, 'ወደ አማልክቶቻቸውም ተዘነበለ፡፡ አለም፡- «አትበሉምን?»'),
('37:92', 87, '«የማትናገሩት ለናንተ ምን አላችሁ?»'),
('37:93', 87, 'በኀይል የሚመታቸውም ሆኖ በእነርሱ ላይ በድብቅ ተዘነበለ፡፡'),
('37:94', 87, 'ወደእርሱም (ሰዎቹ) እየሮጡ መጡ፡፡'),
('37:95', 87, 'አላቸው «የምትጠርቡትን ትግገዛላችሁን?»'),
('37:96', 87, '«አላህ እናንተንም የምትሠሩትንም የፈጠረ ሲኾን፡፡»'),
('37:97', 87, '«ለእርሱም ግንብን ገንቡ በእሳት ነበልባል ውስጥ ጣሉትም» አሉ፡፡'),
('37:98', 87, 'በእርሱም ተንኮልን አሰቡ፡፡ ዝቅተኞችም አደረግናቸው፡፡'),
('37:99', 87, 'አለም «እኔ ወደ ጌታዬ ኼያጅ ነኝ፡፡ በእርግጥ ይመራኛልና፡፡»'),
('37:100', 87, 'ጌታዬ ሆይ! ከመልካሞቹ የሆነን (ልጅ) ስጠኝ፡፡'),
('37:101', 87, 'ታጋሽ በሆነ ወጣት ልጅም አበሰርነው፡፡'),
('37:102', 87, 'ከእርሱ ጋርም ለሥራ በደረሰ ጊዜ «ልጄ ሆይ! እኔ በሕልሜ እኔ የማርድህ ሆኜ አያለሁ፡፡ ተመልከትም፤ ምን ታያለህ?» አለው፡፡ «አባቴ ሆይ! የታዘዝከውን ሥራ፡፡ አላህ ቢሻ ከታጋሾቹ ሆኜ ታገኘኛለህ» አለ፡፡'),
('37:103', 87, 'ሁለቱም ትዕዛዙን በተቀበሉና በግንባሩም ጎን ላይ በጣለው ጊዜ (የሆነው ሆነ)፡፡'),
('37:104', 87, 'ጠራነውም፤ (አልነው) «ኢብራሂም ሆይ!'),
('37:105', 87, 'ራእይቱን በእውነት አረጋገጥክ፡፡» እኛ እንደዚሁ መልካም ሠሪዎችን እንመነዳለን፡፡'),
('37:106', 87, 'ይህ እርሱ በእውነት ግልጽ ፈተና ነው፡፡'),
('37:107', 87, 'በታላቅ ዕርድም (መስዋዕት) ተቤዠነው፡፡'),
('37:108', 87, 'በእርሱም ላይ በኋለኞቹ ሕዝቦች ውስጥ መልካም ዝናን አስቀረንለት፡፡'),
('37:109', 87, 'ሰላም በኢብራሂም ላይ ይሁን፡፡'),
('37:110', 87, 'እንደዚሁ መልካም ሠሪዎችን ሁሉ እንመነዳለን፡፡'),
('37:111', 87, 'እርሱ በእርግጥ ካመኑት ባሮቻችን ነው፡፡'),
('37:112', 87, 'በኢስሐቅም አበሰርነው፡፡ ከመልካሞቹ የሆነ ነቢይ ሲሆን፡፡'),
('37:113', 87, 'በእርሱና በኢስሐቅ ላይም ባረክን፡፡ ከሁለቱም ዘሮች በጎ ሠሪ አልለ፡፡ ለነፍሱ ግልጽ በዳይም አለ፡፡'),
('37:114', 87, 'በሙሳና በሃሩን ላይም በእርግጥ ለገስን፡፡'),
('37:115', 87, 'እነርሱንም ሕዝቦቻቸውንም ከታላቅ ጭንቅ አዳንን፡፡'),
('37:116', 87, 'ረዳናቸውም፡፡ እነርሱም አሸናፊዎች ነበሩ፡፡'),
('37:117', 87, 'በጣም የተብራራውንም መጽሐፍ ሰጠናቸው፡፡'),
('37:118', 87, 'ቀጥተኛውንም መንገድ መራናቸው፡፡'),
('37:119', 87, 'በሁለቱም ላይ በኋለኞቹ ሕዝቦች ውስጥ መልካም ዝናን ተውንላቸው፡፡'),
('37:120', 87, 'ሰላም በሙሳና በሃሩን ላይ ይሁን፡፡'),
('37:121', 87, 'እኛ እንደዚሁ በጎ አድራጊዎችን ሁሉ እንመነዳለን፡፡'),
('37:122', 87, 'ሁለቱም በእርግጥ ከአመኑት ባሮቻችን ናቸው፡፡'),
('37:123', 87, 'ኢልያስም በእርግጥ ከመልክተኞቹ ነው፡፡'),
('37:124', 87, 'ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፤ አላህን አትፈሩምን?'),
('37:125', 87, 'በዕልን ትገዛላችሁን? ከሰዓሊዎቹ ሁሉ ይበልጥ በጣም አሳማሪ የሆነውንም አምላክ ትተዋላችሁን?'),
('37:126', 87, 'አላህን ጌታችሁንና የቀድሞዎቹ አባቶቻችሁን ጌታ (ትተዋላችሁን)?'),
('37:127', 87, 'አስተባበሉትም፡፡ ስለዚህ እነርሱ (ለቅጣት) የሚጣዱ ናቸው፡፡'),
('37:128', 87, 'ንጹሕ የተደረጉት የአላህ ባሮች ብቻ ሲቀሩ፡፡'),
('37:129', 87, 'በእርሱ ላይም በኋለኞቹ ሕዝቦች ውስጥ መልካም ዝናን ተውንለት፡፡'),
('37:130', 87, 'ሰላም በኢልያሲን ላይ ይሁን፡፡'),
('37:131', 87, 'እኛ እንደዚሁ መልካም ሠሪዎችን እንመነዳለን፡፡'),
('37:132', 87, 'እርሱ በእርግጥ ከምእመናን ባሮቻችን ነው፡፡'),
('37:133', 87, 'ሉጥም በእርግጥ ከመልክተኞቹ ነው፡፡'),
('37:134', 87, 'እርሱንና ቤተሰቦቹን ሁሉንም በአዳንናቸው ጊዜ (አስታውስ)፡፡'),
('37:135', 87, '(በቅጣቱ ውስጥ) ከቀሪዎቹ የሆነችው አሮጊት ብቻ ስትቀር፡፡'),
('37:136', 87, 'ከዚያም ሌሎቹን አጠፋን፡፡'),
('37:137', 87, 'እናንተም ያነጋችሁ ስትሆኑ በእነርሱ (መኖሪያዎች) ላይ (በቀን) ታልፋላችሁ፡፡'),
('37:138', 87, 'በሌሊትም (ታልፋላችሁ)፤ ልብም አታደርጉምን?'),
('37:139', 87, 'ዩኑስም በእርግጥ ከመልክተኞቹ ነው፡፡'),
('37:140', 87, 'ወደ ተመላው መርከብ በኮበለለ ጊዜ (አስታውስ)፡፡'),
('37:141', 87, 'ዕጣም ተጣጣለ፡፡ ከተሸነፉትም ሆነ፡፡'),
('37:142', 87, 'እርሱም ተወቃሽ ሲሆን ዐሳው ዋጠው፡፡'),
('37:143', 87, 'እርሱ ለጌታው ከአወዳሾቹ ባልሆነም ኖሮ፤'),
('37:144', 87, 'እስከሚቀሰቀሱበት ቀን ድረስ በሆዱ ውስጥ በቆየ ነበር፡፡'),
('37:145', 87, 'እርሱ በሽተኛ ሆኖ በቃይ በሌለው (በባሕር) ዳርቻ ላይ ጣልነውም፡፡'),
('37:146', 87, 'በእርሱም ላይ (በአጠገቡ) ከቅል የሆነችን ዛፍ አበቀልን፡፡'),
('37:147', 87, 'ወደ መቶ ሺሕ ሰዎችም (ዳግመኛ) ላክነው፡፡ ከቶውንም ይጨምራሉ፡፡'),
('37:148', 87, 'አመኑም፡፡ እስከ ጊዜ ድረስም አጣቀምናቸው፡፡'),
('37:149', 87, '(የመካን ሰዎች) ጠይቃቸውም፡፡ «ለጌታህ ሴቶች ልጆች ለእነርሱም ወንዶች ልጆች ይኖራልን?»'),
('37:150', 87, 'ወይስ እኛ እነርሱ የተጣዱ ሆነው መላእክትን ሴቶች አድርገን ፈጠርን?'),
('37:151', 87, 'ንቁ! እነርሱ ከቅጥፈታቸው (የተነሳ) ይላሉ፡-'),
('37:152', 87, '«አላህ (መላእክትን) ወለደ፡፡» እነርሱም በእርግጥ ውሸታሞች ናቸው፡፡'),
('37:153', 87, 'በወንዶች ልጆች ላይ ይልቅ ሴቶችን ልጆች መረጥን?'),
('37:154', 87, 'ለእናንተ ምን (አስረጅ) አላችሁ? እንዴት ትፈርዳላችሁ!'),
('37:155', 87, 'አትገነዘቡምን?'),
('37:156', 87, 'ወይስ ለእናንተ ግልጽ አስረጅ አላችሁን?'),
('37:157', 87, '«እውነተኞች እንደ ሆናችሁ መጽሐፋችሁን አምጡ» (በላቸው)፡፡'),
('37:158', 87, 'በአላህና በአጋንንት መካከልም ዝምድናን አደረጉ፡፡ አጋንንትም እነርሱ (ይህን ባዮች በእሳት) የሚጣዱ መሆናቸውን በእርግጥ ዐውቀዋል፡፡'),
('37:159', 87, 'አላህ ከሚመጥኑት ሁሉ ጠራ፡፡'),
('37:160', 87, 'ግን የተመረጡት የአላህ ባሮች (በአላህ ላይ አይዋሹም)፡፡'),
('37:161', 87, 'እናንተም የምትገዟቸውም ሁሉ፤'),
('37:162', 87, 'በእርሱ (በአላህ) ላይ አንድንም አጥማሚዎች አይደላችሁም፡፡'),
('37:163', 87, 'ያንን እርሱ ገሀነምን ገቢ የሆነውን ሰው ቢሆን እንጅ፡፡'),
('37:164', 87, '(ጂብሪል አለ) ከእኛም አንድም የለም፤ ለእርሱ የታወቀ ደረጃ ያለው ቢሆን እንጅ፡፡'),
('37:165', 87, 'እኛም (ጌታን ለመግገዛት) ተሰላፊዎቹ እኛ ነን፡፡'),
('37:166', 87, 'እኛም (አላህን) አጥሪዎቹ እኛ ነን፡፡'),
('37:167', 87, 'እነርሱም (ከሓዲዎቹ) በእርግጥ ይሉ ነበሩ፡-'),
('37:168', 87, '«ከቀድሞዎቹ (መጻሕፍት) ገሳጭ መጽሐፍ እኛ ዘንድ በነበረን ኖሮ፤'),
('37:169', 87, '«የአላህ ምርጦች ባሮች በሆን ነበር፡፡»'),
('37:170', 87, 'ግን (ቁርኣኑ በመጣላቸው ጊዜ) በእርሱ ካዱ፡፡ ወደፊትም በእርግጥ ያውቃሉ፡፡'),
('37:171', 87, '(የእርዳታ) ቃላችንም መልክተኞች ለሆኑት ባሮቻችን በእውነት አልፋለች፡፡'),
('37:172', 87, 'እነርሱ ተረጂዎቹ እነርሱ ናቸው፡፡'),
('37:173', 87, 'ሰራዊቶቻችንም በእርግጥ አሸናፊዎቹ እነርሱ ናቸው፡፡'),
('37:174', 87, 'ከእነርሱም (ከመካ ከሓዲዎች) እስከ ጥቂት ጊዜ ድረስ ዙር (ተዋቸው)፡፡'),
('37:175', 87, 'እያቸውም ወደፊትም (የሚደርስባቸውን) ያያሉ፡፡'),
('37:176', 87, 'በቅጣታችንም ያቻኩላሉን?'),
('37:177', 87, 'በቀያቸውም በወረደ ጊዜ የተስፈራሪዎቹ ንጋት ከፋ!'),
('37:178', 87, 'እነርሱንም እስከ (ጥቂት) ጊዜ ድረስ ተዋቸው፡፡'),
('37:179', 87, 'ተመልከትም በእርግጥም ያያሉ፡፡'),
('37:180', 87, 'የማሸነፍ ጌታ የሆነው ጌታህ ከሚሉት ሁሉ ጠራ፡፡'),
('37:181', 87, 'በመልክተኞቹም ላይ ሰላም ይኹኑ፤'),
('37:182', 87, 'ምስጋናም ለዓለማት ጌታ ለአላህ ይሁን፡፡'),
('38:1', 87, 'ጸ. (ሷድ) የክብር ባለቤት በሆነው ቁርኣን እምላለሁ (ብዙ አማልክት አሉ እንደሚሉት አይደለም)፡፡'),
('38:2', 87, 'ይልቁንም እነዚያ የካዱት ሰዎች በትዕቢትና በክርክር ውስጥ ናቸው፡፡'),
('38:3', 87, 'ከእነርሱ በፊት ከክፍለ ዘመናት ሕዝቦች ብዙን አጥፍተናል፡፡ (ጊዜው) የመሸሻና የማምለጫ ጊዜ ሳይሆንም (ለእርዳታ) ተጣሩ፡፡'),
('38:4', 87, 'ከእነርሱ የሆነ አስፈራሪም ስለ መጣላቸው ተደነቁ፡፡ ከሓዲዎቹም «ይህ ድግምተኛ (ጠንቋይ) ውሸታም ነው» አሉ፡፡'),
('38:5', 87, '«አማልክቶቹን አንድ አምላክ አደረጋቸውን? ይህ አስደናቂ ነገር ነው» (አሉ)፡፡'),
('38:6', 87, 'ከእነርሱም መኳንንቶቹ «ሂዱ፤ በአማልክቶቻችሁም (መግገዛት) ላይ ታገሱ፡፡ ይህ (ከእኛ) የሚፈለግ ነገር ነውና» እያሉ አዘገሙ፡፡'),
('38:7', 87, '«ይህንንም በኋለኛይቱ ሃይማኖት አልሰማንም፡፡ ይህ ውሸትን መፍጠር እንጅ ሌላ አይደለም» (እያሉም)፡፡'),
('38:8', 87, '«ከመካከላችን በእርሱ ላይ ቁርኣን ተወረደን?» (አሉ)፡፡ በእውነት እነርሱ ከግሳጼዬ (ከቁርኣን) በመጠራጠር ውስጥ ናቸው፡፡ በእርግጥም ቅጣቴን ገና አልቀመሱም፡፡'),
('38:9', 87, 'ይልቁንም የአሸናፊውና የለጋሱ ጌታህ የችሮታው መጋዘኖች እነርሱ ዘንድ ናቸውን?'),
('38:10', 87, 'ወይስ የሰማያትና የምድር የመካከላቸውም ንግሥና የእነርሱ ነውን? (ነው ቢሉ) በመሰላሎችም ይውጡ፡፡'),
('38:11', 87, 'እዚያ ዘንድ ከአሕዛብ የሆኑ ተሸናፊ ሰራዊት ናቸው፡፡'),
('38:12', 87, 'ከእነርሱ በፊት የኑሕ ሕዝቦች፣ ዓድም፣ የችካሎች ባለቤት የሆነው ፈርዖንም አስተባበሉ፡፡'),
('38:13', 87, 'ሰሙድም፣ የሉጥ ሰዎችም፣ የአይከት ሰዎችም (አስተባበሉ)፡፡ እነዚህ አሕዛቦቹ ናቸው፡፡'),
('38:14', 87, 'ሁሉም መልክተኞቹን ያስዋሹ እንጅ ሌላ አይደሉም፡፡ ቅጣቴም ተረጋገጠባቸው፡፡'),
('38:15', 87, 'እነዚህም ለእርሷ መመለስ የሌላትን አንዲትን ጩኸት እንጅ ሌላን አይጠባበቁም፡፡'),
('38:16', 87, '«ጌታችን ሆይ! ከምርመራው ቀን በፊት መጽሐፋችንን አስቸኩልልን» አሉም፡፡'),
('38:17', 87, 'በሚሉት ነገር ላይ ታገስ፡፡ የኀይል ባለቤት የሆነውን ባሪያችንንም ዳውድን አውሳላቸው፡፡ እርሱ በጣም መላሳ ነውና፡፡'),
('38:18', 87, 'እኛ ተራራዎችን ከቀትር በኋላና በረፋድም ከእርሱ ጋር የሚያወድሱ ሲሆኑ ገራንለት፡፡'),
('38:19', 87, 'በራሪዎችንም (አእዋፍን) የሚሰበሰቡ ሆነው (ገራንለት)፡፡ ሁሉም ለእርሱ (ማወደስ) የሚመላለስ ነው፡፡'),
('38:20', 87, 'መንግሥቱንም አበረታንለት፡፡ ጥበብንም ንግግርን መለየትንም ሰጠነው፡፡'),
('38:21', 87, 'የተከራካሪዎቹም ወሬ መጥቶልሃልን? ምኩራቡን በተንጠላጠሉ ጊዜ፡፡'),
('38:22', 87, 'በዳውድ ላይም በገቡ ጊዜ ከእነርሱም በደነገጠ ጊዜ «አትፍራ፤ (እኛ) ከፊላችን በከፊሉ ላይ ወሰን ያለፈ ሁለት ተከራካሪዎች ነን፡፡ በመካከላችንም በእውነት ፍረድ፡፡ አታዳላም፡፡ ወደ'),
('38:23', 87, '«ይህ ወንድሜ ነው፤ ለእርሱ ዘጠና ዘጠኝ ሴቶች በጎች አሉት፡፡ ለኔም አንዲት ሴት በግ'),
('38:24', 87, '«ሴት በግህን ወደ በጎቹ (ለመቀላቀል) በመጠየቁ በእርግጥ በደለህ፡፡ ከተጋሪዎችም ብዙዎቹ ከፊላቸው በከፊሉ ላይ ወሰን ያልፋሉ፡፡ እነዚያ ያመኑትና መልካሞችን የሠሩት ብቻ ሲቀሩ፡፡ እነርሱም በጣም ጥቂቶች ናቸው» አለ፡፡ ዳውድም የፈተንነው መኾኑን ዐወቀ፡፡ ጌታውንም ምሕረትን ለመነ፡፡ ሰጋጅ ኾኖ ወደቀም፡፡ በመጸጸት ተመለሰም፡፡'),
('38:25', 87, 'ለእርሱም እኛ ዘንድ መቅረብ (ክብር) መልካም መመለሻም አለው፡፡'),
('38:26', 87, 'ዳውድ ሆይ! እኛ በምድር ላይ ምትክ አድርገንሃልና በሰዎች መካከል በእውነት ፍረድ፡፡ ዝንባሌሀንም አትከተል፤ከአላህ መንገድ ያሳሳትሃልና፡፡ እነዚያ ከአላህ መንገድ የሚሳሳቱ የምርመራውን ቀን በመርሳታቸው ለእነርሱ ብርቱ ቅጣት አላቸው፡፡'),
('38:27', 87, 'ሰማይንና ምድርን በመካከላቸውም ያለውን ሁሉ ለከንቱ አልፈጠርንም፡፡ ይህ የእነዚያ የካዱት ሰዎች ጥርጣሬ ነው፡፡ ለእነዚያም ለካዱት ሰዎች ከእሳት ወዮላቸው!'),
('38:28', 87, 'በእውነቱ እነዚያን ያመኑትንና መልካሞችን የሠሩትን በምድር ውስጥ እንደሚያጠፉት እናደርጋለን? ወይስ አላህን ፊረዎቹን እንደ ከሓዲዎቹ እናደርጋለን?'),
('38:29', 87, '(ይህ) ወዳንተ ያወረድነው ብሩክ መጽሐፍ ነው፡፡ አንቀጾቹን እንዲያስተነትኑና የአእምሮዎች ባለቤቶችም እንዲገሰጹ (አወረድነው)፡፡'),
('38:30', 87, 'ለዳውድም ሱለይማንን ሰጠነው፡፡ ምን ያምር ባሪያ! (ሱለይማን)፣ እርሱ መላሳ ነው፡፡'),
('38:31', 87, 'በእርሱ ላይ ከቀትር በኋላ በሦስት እግሮችና በአራተኛዋ ኮቴ ጫፍ የሚቆሙ ጮሌዎች ፈረሶች በተቀረቡለት ጊዜ (አስታውስ)፡፡'),
('38:32', 87, 'አለም «እኔ (ፀሐይ) በግርዶ እስከ ተደበቀች ድረስ ከጌታዬ ማስታወስ ፋንታ ፈረስን መውደድን መረጥኩ፡፡»'),
('38:33', 87, '«በእኔ ላይ መልሷት» (አለ) አጋዶችዋንና አንገቶችዋንም ማበስ ያዘ፡፡'),
('38:34', 87, 'ሱለይማንንም በእርግጥ ፈተንነው፡፡ በመንበሩም ላይ አካልን ጣልን፡፡ ከዚያም በመጸጸት ተመለሰ፡፡'),
('38:35', 87, '«ጌታዬ ሆይ! ለእኔ ማር፡፡ ከእኔ በኋላ ለአንድም የማይገባንም ንግሥና ስጠኝ፡፡ አንተ ለጋሱ አንተ ብቻ ነህና» አለ፡፡'),
('38:36', 87, 'ነፋስንም በትእዛዙ ወደፈለገበት ስፍራ ልዝብ ኾና የምትፈስ ስትኾን ገራንለት፡፡'),
('38:37', 87, 'ሰይጣናትንም ገንቢዎችንና ሰጣሚዎችን ሁሉ (ገራንለት)፡፡'),
('38:38', 87, 'ሌሎችንም በፍንጆች ተቆራኞችን (ገራንለት)፡፡'),
('38:39', 87, '«ይህ ስጦታችን ነው፡፡ ያለግምት ለግስ፤ ወይም ጨብጥ» (አልነው)፡፡'),
('38:40', 87, 'ለእርሱም እኛ ዘንድ መቅረብ፤ መልካም መመለሻም በእርግጥ አልለው፡፡'),
('38:41', 87, 'ባሪያችንን አዩብንም አውሳላቸው፡፡ «እኔ ሰይጣን በጉዳትና በስቃይ ነካኝ» ሲል ጌታውን በተጣራ ጊዜ፡፡'),
('38:42', 87, '«በእግርህ (ምድርን) ምታ፡፡ ይህ ቀዝቃዛ መታጠቢያ መጠጥም ነው» (ተባለ)፡፡'),
('38:43', 87, 'ለእርሱም ከእኛ ዘንድ ለችሮታ ባለአእምሮዎችንም ለመገሠጽ ቤተሰቦቹን ከእነርሱም ጋር መሰላቸውን ሰጠነው፡፡'),
('38:44', 87, '«በእጅህም ጭብጥ አርጩሜን ያዝ፡፡ በእርሱም (ሚስትህን) ምታ፡፡ ማላህንም አታፍርስ» (አልነው)፡፡ እኛ ታጋሸ ኾኖ አገኘነው፡፡ ምን ያምር ባሪያ እርሱ በጣም መላሳ ነው፡፡'),
('38:45', 87, 'ባሮቻችንንም ኢብራሂምን፣ ኢስሐቅንና ያዕቆበንም፣ የኅይልና የማስተዋል ባለቤቶች የኾኑን አውሳላቸው፡፡'),
('38:46', 87, 'እኛ ጥሩ በኾነች ጠባይ መረጥናቸው፡፡ (እርሷም) የመጨረሻይቱን አገር ማስታወስ ናት፡፡'),
('38:47', 87, 'እነርሱም እኛ ዘንድ ከመልካሞቹ ምርጦች ናቸው፡፡'),
('38:48', 87, 'ኢስማዒልንም፣ አልየሰዕንም፣ ዙልኪፍልንም አውሳ፡፡ ሁሉም ከበላጮቹ ናቸው፡፡'),
('38:49', 87, 'ይህ መልካም ዝና ነው፡፡ ለአላህ ፈሪዎችም በእርግጥ ውብ የኾነ መመለሻ አላቸው፡፡'),
('38:50', 87, 'በሮቻቸው ለእነርሱ የተከፈቱ ሲኾኑ የመኖሪያ ገነቶች አሏቸው፡፡'),
('38:51', 87, 'በእርሷ ውስጥ የተደገፉ ኾነው በውስጧ በብዙ እሸቶችና በመጠጥም ያዝዛሉ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('38:52', 87, 'እነርሱ ዘንድም ዓይኖቻቸውን (በባሎቻቸው ላይ) አሳጣሪዎች እኩያዎች (ሴቶች) አልሉ፡፡'),
('38:53', 87, 'ይህ ለምርመራው ቀን የምትቀጠሩት ተሰፋ ነው፡፡'),
('38:54', 87, 'ይህ ሲሳያችን ነው፡፡ ለእርሱ ምንም ማለቅ የለውም፡፡'),
('38:55', 87, 'ይህ (ለአማኞች ነው)፡፡ ለጠማሞችም በጣም የከፋ መመለሻ አላቸው፡፡'),
('38:56', 87, 'የሚገቧት ስትኾን ገሀነም (አለቻቸው)፡፡ ምንጣፊቱም ምንኛ ከፋች፡፡'),
('38:57', 87, 'ይህ (ለከሓዲዎች ነው)፡፡ ይቅመሱትም፡፡ የፈላ ውሃና እዥ ነው፡፡'),
('38:58', 87, 'ሌላም ከመሰሉ ዓይነቶች አልሉ፡፡'),
('38:59', 87, 'ይህ ከእናንተ ጋር በመጋፈጥ ገቢ ጭፍራ ነው፤ (ይባላሉ)፡፡ ለእነርሱ አይስፋቸው፡፡ እነርሱ እሳትን ገቢዎች ናቸውና (ይላሉ)፡፡'),
('38:60', 87, '(ተከታዮቹ) ይላሉ «ይልቁን እናንተ አይስፋችሁ፡፡ እናንተ (ክህደቱን) ለእኛ አቀረባችሁት፡፡ መርጊያይቱም (ገሀነም) ከፋች፡፡»'),
('38:61', 87, '«ጌታችን ሆይ! ይህንን ያቀረበልንን ሰው በእሳት ውስጥ እጥፍን ቅጣት ጨምርለት» ይላሉ፡፡'),
('38:62', 87, 'ይላሉም «ለእኛ ምን አለን? ከመጥፎዎች እንቆጥራቸው የነበሩትን ሰዎች (እዚህ) አናይምሳ፡፡»'),
('38:63', 87, '«መቀለጃ አድርገን ያዝናቸውን? ወይስ ዓይኖቻችን ከእነሱ ዋለሉ?»'),
('38:64', 87, 'ይህ በእርግጥ እምነት ነው፡፡ (እርሱም) የእሳት ሰዎች (የእርስ በእርስ) መካሰስ ነው፡፡'),
('38:65', 87, '«እኔ አስፈራሪ ብቻ ነኝ፡፡ ኀያል አንድ ከኾነው አላህ በቀር ምንም አምላክ የለም» በላቸው፡፡'),
('38:66', 87, '«የሰማያትና የምድር በመካከላቸውም ያለው ሁሉ ጌታ አሸናፊው መሓሪው ነው፡፡»'),
('38:67', 87, 'በላቸው «እርሱ (ቁርኣን) ታላቅ ዜና ነው፡፡'),
('38:68', 87, '«እናንተ ከእርሱ ዘንጊዎች ናችሁ፡፡'),
('38:69', 87, '(በአደም ነገር) «በሚከራከሩ ጊዜ በላይኛው ሰራዊት ለእኔ ምንም ዕውቀት አልነበረኝም፡፡'),
('38:70', 87, '«ወደእኔም አስፈራሪ ገላጭ መኾኔ እንጂ ሌላ አይወረድልኝም» (በል)፡፡'),
('38:71', 87, 'ጌታህ «ለመላእክት እኔ ሰውን ከጭቃ ፈጣሪ ነኝ ባለ ጊዜ» (አስታውስ)፡፡'),
('38:72', 87, '«ፍጥረቱንም ባስተካከልኩና ከመንፈሴ በነፋሁበት ጊዜ ለእርሱ ሰጋጆች ኾናችሁ ውደቁ» (አልኩ)፡፡'),
('38:73', 87, 'መላእክትም መላውም ባንድነት ሰገዱ፡፡'),
('38:74', 87, 'ኢብሊስ ብቻ ሲቀር፡፡ ኮራ፤ ከከሓዲዎቹም ነበር፡፡'),
('38:75', 87, '(አላህም) «ኢብሊስ ሆይ! በሁለት እጆቼ (በኃይሌ) ለፈጠርኩት ከመስገድ ምን ከለከለህ? (አሁን) ኮራህን? ወይስ (ፊቱኑ) ከትዕቢተኞቹ ነበርክ?» አለው፡፡'),
('38:76', 87, '«እኔ ከእርሱ በላጭ ነኝ፡፡ ከእሳት ፈጠርከኝ፤ ከጭቃም ፈጠርከው» አለ፡፡'),
('38:77', 87, '(አላህ) አለው «ከእርሷ ውጣ፤ አንተ የተባረርክ ነህና፡፡»'),
('38:78', 87, '«እርግማኔም እስከ ፍርዱ ቀን ድረስ ባንተ ላይ ይኹን፡፡»'),
('38:79', 87, '«ጌታዬ ሆይ! እስከሚቀሰቀሱበት ቀን ድረስ አቆየኝም» አለ፡፡'),
('38:80', 87, '(አላህም) አለው «አንተ ከሚቆዩት ነህ፡፡»'),
('38:81', 87, '«እስከ ታወቀው ወቅት ቀን ድረስ፡፡»'),
('38:82', 87, '(እርሱም) አለ «በአሸናፊነትህ ይኹንብኝ፤ በመላ አሳስታቸዋለሁ፡፡»'),
('38:83', 87, '«ከእነርሱ ምርጥ የኾኑት ባሮችህ ብቻ ሲቀሩ፡፡»'),
('38:84', 87, '(አላህ) አለው «እውነቱም (ከኔ ነው)፡፡ እውነትንም እላለሁ፡፡'),
('38:85', 87, 'ከአንተና ከእነርሱ ውስጥ ከተከተሉህ ባንድ ላይ ገሀነምን በእርግጥ እሞላታለሁ፡፡»'),
('38:86', 87, 'በላቸው «በእርሱ ላይ ምንም ዋጋ አልጠይቃችሁም፤ እኔም ከተግደርዳሪዎቹ አይደለሁም፡፡'),
('38:87', 87, '«እርሱ (ቁርኣን) ለዓለማት መገሠጫ እንጂ ሌላ አይደለም፡፡'),
('38:88', 87, '«ትንቢቱንም (እውነት መኾኑን) ከጊዜ በኋላ በእርግጥ ታውቁታላችሁ፡፡»'),
('39:1', 87, 'የመጽሐፉ መወረድ አሸናፊው ጥበበኛው ከኾነው አላህ ነው፡፡'),
('39:2', 87, 'እኛ ወደ አንተ መጽሐፉን በእውነት (የተመላ) ሲኾን አወረድነው፡፡ አላህንም ሃይማኖትን ለእርሱ ብቻ ያጠራህ ኾነህ ተገዛው፡፡'),
('39:3', 87, 'ንቁ! ፍጹም ጥሩ የኾነው ሃይማኖት የአላህ ብቻ ነው፡፡ እነዚያም ከእርሱ ሌላ (ጣዖታትን) ረዳቶች የያዙት «ወደ አላህ ማቃረብን እንዲያቀርቡን እንጅ ለሌላ አንገዛቸውም» (ይላሉ)፡፡ አላህ በዚያ እነርሱ በእርሱ በሚለያዩበት ነገር በመካከላቸው ይፈርዳል፡፡ አላህ እርሱ ውሸታም ከሓዲ የኾነን ሰው አያቀናም፡፡'),
('39:4', 87, 'አላህ ልጅን መያዝ በፈለገ ኖሮ ከሚፈጥረው ውስጥ የሚሻውን ይመርጥ ነበር፡፡ ጥራት ተገባው፡፡ እርሱ አሸናፊው አንዱ አላህ ነው፡፡'),
('39:5', 87, 'ሰማያትንና ምድርን በእወነት ፈጠረ፡፡ ሌሊትን በቀን ላይ ይጠቀልላል፡፡ ቀንንም በሌሊት ላይ ይጠቀልላል፤ ፀሐይንና ጨረቃንም ገራ፡፡ ሁሉም ለተወሰነ ጊዜ ይሮጣሉ፡፡ ንቁ! እርሱ አሸናፊው መሓሪው ነው፡፡'),
('39:6', 87, 'ከአንዲት ነፍስ ፈጠራችሁ፡፡ ከዚያም ከእርሷ መቀናጆዋን አደረገ፡፡ ለእናንተም ከግመልና ከከብት፣ ከፍየል፣ ከበግ ስምንት ዓይነቶችን (ወንድና ሴት) አወረደ፡፡ በእናቶቻችሁ ሆዶች ውስጥ በሦስት ጨለማዎች ውስጥ ከመፍጠር በኋላ (ሙሉ) መፍጠርን ይፈጠራችኋል፡፡ ይህ ጌታችሁ አላህ ነው፡፡ ስልጣኑ የርሱ ብቻ ነው፡፡ ከእርሱ ሌላ አምላክ የለም፡፡ ታዲያ ወዴት ትዞራላችሁ፡፡'),
('39:7', 87, 'ብትክዱ አላህ ከእናንተ የተብቃቃ ነው፡፡ ለባሪያዎቹም ከህደትን አይወድም፡፡ ብታመሰግኑም፤ እርሱን ይወድላችኋል፡፡ ማንኛይቱም ኃጢኣትን ተሸካሚ ነፍስ የሌላይቱን ኃጢኣት አትሸከምም፡፡ ከዚያም መመለሻችሁ ወደ ጌታችሁ ነው፡፡ ትሠሩት የነበራችሁትንም ይነግራችኋል፡፡ እርሱ በልቦች ውስጥ ያሉትን ዐዋቂ ነውና፡፡'),
('39:8', 87, 'ሰውንም ጉዳት ባገኘው ጊዜ ጌታውን ወደርሱ ተመላሽ ኾኖ ይጠራል፡፡ ከዚያም ከእርሱ ዘንድ ጸጋን በሰጠው ጊዜ ያንን ከዚያ በፊት ወደርሱ ይጸልይበት የነበረውን (መከራ) ይረሳል፡፡ ከመንገዱ ለማሳሳትም ለአላህ ባላንጣዎችን ያደርጋል፡፡ «በክህደትህ ጥቂትን ተጣቀም፡፡ አንተ በእርግጥ ከእሳት ጓዶች ነህ» በለው፡፡'),
('39:9', 87, 'እርሱ የመጨረሻይቱን ዓለም (ቅጣት) የሚፈራ የጌታውንም ችሮታ የሚከጅል ሲኾን በሌሊት ሰዓቶች ሰጋጅና ቋሚ ኾኖ ለጌታው የሚግገዛ ሰው (እንደ ተስፋ ቢሱ ከሓዲ ነውን? በለው)፡፡ «እነዚያ የሚያውቁና እነዚያ የማያውቁ ይስተካከላሉን?» በላቸው፡፡ የሚገነዘቡት ባለ አእምሮዎቹ ብቻ ናቸው፡፡'),
('39:10', 87, '(ጌታችሁ) «እናንተ ያመናችሁ ባሮቼ ሆይ! ጌታችሁን ፍሩ፡፡ ለነዚያ በዚህች በቅርቢቱ ዓለም መልካም ለሠሩት መልካም ምንዳ አላቸው፡፡ የአላህ ምድርም ሰፊ ናት፤ (ብትቸገሩ ተሰደዱ)፡፡ ታጋሾቹ ምንዳቸውን የሚሰጡት ያለግምት ነው» (ይላል) በላቸው፡፡'),
('39:11', 87, 'በል «እኔ አላህን ሃይማኖትን ለርሱ ያጠራሁ ኾኜ እንድግገዛው ታዘዝኩ፡፡'),
('39:12', 87, '«የሙስሊሞችም መጀመሪያ እንድኾን ታዘዝኩ፡፡»'),
('39:13', 87, '«እኔ ከጌታዬ ባምጽ የታላቁን ቀን ቅጣት እፈራለሁ» በል፡፡'),
('39:14', 87, 'አላህን «ሃይማኖቴን ለእርሱ ያጠራሁ ኾኜ እግገዛዋለሁ» በል፡፡'),
('39:15', 87, '«ከእርሱ ሌላ የሻችሁትን ተገዙ፡፡ ከሳሪዎች ማለት እነዚያ በትንሣኤ ቀን ነፍሶቻቸውንና ቤተሰቦቻቸውን ያከሰሩ ናቸው፡፡ ንቁ! ይህ እርሱ ግልጽ ከሳራ ነው» በላቸው፡፡'),
('39:16', 87, 'ለእነርሱ ከበላያቸው ከእሳት የኾኑ (ድርብርብ) ጥላዎች አልሏቸው፡፡ ከበታቻቸውም ጥላዎች አልሏቸው። ይህ አላህ ባሮቹን (እንዲጠነቀቁ) በእርሱ ያስፈራራበታል፡፡ «ባሮቼ ሆይ! ስለዚህ ፍሩኝ፡፡»'),
('39:17', 87, 'እነዚያም ጣዖታትን የሚግገዟት ከመኾን የራቁ ወደ አላህም የዞሩ ለእነርሱ ብስራት አልላቸው፡፡ ስለዚህ ባሮቼን አብስር፡፡'),
('39:18', 87, 'እነዚያን ንግግርን የሚያዳምጡትንና መልካሙን የሚከተሉትን (አብስር)፡፡ እነዚያ እነርሱ አላህ የመራቸው ናቸው፡፡ እነዚያም እነርሱ ባለአእምሮዎቹ ናቸው፡፡'),
('39:19', 87, 'በእርሱ ላይ የቅጣት ቃል የተረጋገጠችበትን ሰው (ትመራዋለህን?) አንተ በእሳት ውስጥ ያለን ሰው ታድናለህን?'),
('39:20', 87, 'ግን እነዚያ ጌታቸውን የፈሩ ለእነርሱ ከበላያቸው የታነጹ ሰገነቶች ያሏቸው ሰገነቶች ከስሮቻቸው ወንዞች የሚፈሱባቸው የኾኑ አልሏቸው፡፡ (ይህንን) አላህ ቃል ገባላቸው፡፡ አላህ ቃሉን አያፈርስም፡፡'),
('39:21', 87, 'አላህ ከሰማይ ውሃን እንዳወረደና በምድርም ውስጥ ምንጮች አድርጎ እንዳስገባው አላየህምን? ከዚያም በእርሱ ዓይነቶቹ የተለያዩን አዝመራ ያወጣል፡፡ ከዚያም ይደርቃል፡፡ ገርጥቶም ታየዋለህ፡፡ ከዚያም ስብርብር ያደርገዋል፡፡ በዚህ ውስጥ ለባለ አእምሮዎች ግሣጼ አለበት፡፡'),
('39:22', 87, 'አላህ ደረቱን ለእስልምና ያስፋለትና እርሱም ከጌታው ዘንድ በብርሃን ላይ የኾነ ሰው (ልቡ እንደ ደረቀ ሰው ነውን?) ልቦቻቸውም ከአላህ መወሳት ለደረቁ ሰዎች ወዮላቸው፡፡ እነዚያ በግልጽ መሳሳት ውስጥ ናቸው፡፡'),
('39:23', 87, 'አላህ ከዜና ሁሉ መልካምን፣ ተመሳሳይ፣ ተደጋጋሚ የኾነን መጽሐፍ አወረደ፡፡ ከእርሱ (ግሣጼ) የእነዚያ ጌታቸውን የሚፈሩት ሰዎች ቆዳዎች ይኮማተራሉ፡፡ ከዚያም ቆዳዎቻቸውና ልቦቻቸው ወደ አላህ (ተስፋ) ማስታወስ ይለዝባሉ፡፡ ይህ የአላህ መምሪያ ነው፡፡ በእርሱ የሚሻውን ሰው ይመራበታል፡፡ አላህም የሚያጠመው ሰው ለእርሱ ምንም አቅኚ የለውም፡፡'),
('39:24', 87, 'በትንሣኤ ቀን ክፉን ቅጣት በፊቱ የሚመክት ሰው (ከቅጣት እንደሚድን ነውን?) ለበዳዮችም «ትሠሩት የነበራችሁትን (ቅጣቱን) ቅመሱ» ይባላሉ፡፡'),
('39:25', 87, 'ከእነሱ በፊት የነበሩት አስተባበሉ፡፡ ቅጣቱም ከማያውቁት በኩል መጣባቸው፡፡'),
('39:26', 87, 'አላህም በቅርቢቱ ሕይወት ውርደትን አቀመሳቸው፡፡ የመጨረሻይቱም ዓለም ቅጣት በጣም ትልቅ ነው፡፡ የሚያውቁ ቢኾኑ ኖሮ (አያስተባብሉም ነበር)፡፡'),
('39:27', 87, 'በዚህም ቁርኣን ውስጥ ለሰዎች ይገሠጹ ዘንድ ከየምሳሌው ሁሉ በእርግጥ አብራራን፡፡'),
('39:28', 87, 'መዛባት የሌለበት ዐረብኛ ቁርኣን ሲኾን (አብራራነው)፡፡ ሊጠነቀቁ ይከጀላልና፡፡'),
('39:29', 87, 'አላህ በእርሱ ተጨቃጫቂዎች የኾኑ ተጋሪዎች ያሉትን ባሪያና ለአንድ ሰው ብቻ ንጹሕ የኾነን ባሪያ (ለሚያጋራና ባንድነቱ ለሚያምን ሰው) ምሳሌ አደረገ፡፡ በምሳሌ ይስተካከላሉን? ምስጋና ለአላህ ይገባው፡፡ በእውነቱ አብዛኞቻቸው አያውቁም፡፡'),
('39:30', 87, 'አንተ ሟች ነህ፤ እነርሱም ሟቾች ናቸው፡፡'),
('39:31', 87, 'ከዚያም እናንተ በትንሣኤ ቀን እጌታችሁ ዘንድ ትከራከራላችሁ፡፡'),
('39:32', 87, 'በአላህም ላይ ከዋሸ እውነቱንም በመጣለት ጊዜ ከአስተባበለ ሰው ይበልጥ በዳይ ማን ነው?'),
('39:33', 87, 'ያም በእውነት የመጣው በእርሱ ያመነውም እነዚያ እነርሱ አላህን ፊሪዎች ናቸው፡፡'),
('39:34', 87, 'ለእነርሱ በጌታቸው ዘንድ የሚሹት ሁሉ አልላቸው፡፡ ይህ የበጎ አድራጊዎች ምንዳ ነው፡፡'),
('39:35', 87, 'አላህ ያንን (በስሕተት) የሠሩትን መጥፎ ሥራ ከእነርሱ ሊሰርይላቸው በዚያም ይሠሩት በነበሩት በመልካሙ ሥራ ምንዳቸውን ሊመነዳቸው (ይህንን አደረገ)፡፡'),
('39:36', 87, 'አላህ ባሪያውን በቂ አይደለምን? በእነዚያ ከእርሱ ሌላ በኾኑትም (ጣዖታት) ያስፈራሩሃል፡፡ አላህ የሚያጠመውም ሰው ለርሱ ምንም አቅኚ የለውም፡፡'),
('39:37', 87, 'አላህ የሚያቀናውም ሰው ለእርሱ ምንም አጥማሚ የለውም፡፡ አላህ አሸናፊ የመበቀል ባለቤት አይደለምን?'),
('39:38', 87, 'ሰማያትንና ምድርን የፈጠረ ማን እንደ ኾነ ብትጠይቃቸው «አላህ ነው» ይሉሃል፡፡ «ከአላህ ሌላ የምትግገዟቸውን (ጣዖታት) አያችሁን? (ንገሩኝ) አላህ በጉዳት ቢፈልገኝ እነርሱ ጉዳቱን ገላጮች ናቸውን? ወይስ በችሮታው ቢፈቅደኝ እነርሱ ችሮታውን አጋጆች ናቸውን?» በላቸው፡፡ «አላህ በቂዬ ነው፡፡ በእርሱ ላይ ተመኪዎች ይመካሉ» በል፡፡'),
('39:39', 87, '(ሙሐመድ ሆይ!) በላቸው «ሕዝቦቼ ሆይ! ባላችሁበት ኹኔታ ላይ ሥሩ፡፡ እኔ ሠሪ ነኝና፡፡ ወደፊትም ታውቃላችሁ፡፡»'),
('39:40', 87, 'ያንን የሚያሳፍረው ቅጣት የሚመጠበትንና በእርሱ ላይ ዘውታሪ ቅጣት የሚሰፍርበትን (ታውቃላችሁ)'),
('39:41', 87, 'እኛ መጽሐፉን ባንተ ላይ ለሰዎች (ጥቅም) በእውነት አወረድነው፡፡ የተመራም ሰው ለነፍሱ ነው፡፡ የጠመመም ሰው የሚጠምመው (ጉዳቱ) በእርሷ ላይ ነው፡፡ አንተም (ታስገድዳቸው ዘንድ) በእነርሱ ላይ ጠባቂ አይደለህም፡፡'),
('39:42', 87, 'አላህ ነፍሶችን በሞታቸው ጊዜ ይወስዳል፡፡ ያችንም ያልሞተችውን በእንቅልፏ ጊዜ (ይወስዳታል)፡፡ ታዲያ ያችን ሞትን የፈረደባትን ይይዛታል፡፡ ሌላይቱንም እስከ ተወሰነ ጊዜ ድረስ ይለቅቃታል፡፡ በዚህ ውስጥ ለሚያስተነትኑ ሕዝቦች ምልክቶች አልሉበት፡፡'),
('39:43', 87, 'ይልቁንም (ቁረይሾች) ከአላህ ሌላ አማላጆችን ያዙ፡፡ «እነርሱ ምንንም የማይችሉና የማያውቁ ቢኾኑም?» በላቸው፡፡'),
('39:44', 87, '«ምልጃ መላውም የአላህ ብቻ ነው፡፡ የሰማያትና የምድር ሥልጣን የእርሱ ብቻ ነው፡፡ ከዚያም ወደእርሱ ትመለሳላችሁ» በላቸው፡፡'),
('39:45', 87, 'አላህም ብቻውን በተወሳ ጊዜ የእነዚያ በመጨረሻይቱ ዓለም የማያምኑት ሰዎች ልቦች ይሸማቀቃሉ፤ (ይደነብራሉ)፡፡ እነዚያም ከእርሱ ሌላ የኾኑት (ጣዖታት) በተወሱ ጊዜ እነርሱ ወዲያውኑ ይደሰታሉ፡፡'),
('39:46', 87, '«ሰማያትንና ምድርን የፈጠርክ ሩቁንም ቅርቡንም ዐዋቂ የኾንክ አላህ ሆይ! አንተ በባሮችህ መካከል በእዚያ በእርሱ ይለያዩበት በነበሩት ነገር ትፈርዳለህ» በል፡፡'),
('39:47', 87, 'ለእነዚያም ለበደሉት በምድር ያለው ሁሉ መላውም ከእርሱ ጋር መሰሉም ቢኖራቸው ኖሮ በትንሣኤ ቀን ከቅጣቱ ክፋት የተነሳ በእርሱ ነፍሶቻቸውን በተበዡበት ነበር፡፡ ለእነርሱም ከአላህ ዘንድ ያስቡት ያልነበሩት ሁሉ ይገለጽላቸዋል፡፡'),
('39:48', 87, 'ለእነርሱም የሠሩዋቸው መጥፎዎቹ ይገለጹላቸዋል፡፡ በእነርሱም ላይ በእርሱ ያላግጡበት የነበሩት ቅጣት ይሰፍርባቸዋል፡፡'),
('39:49', 87, 'ሰውም ጉዳት ባገኘው ጊዜ ይጠራናል፡፡ ከዚያም ከእኛ የኾነውን ጸጋ በሰጠነው ጊዜ «እርሱን የተሰጠሁት፤ በዕውቀት ብቻ ነው» ይላል፡፡ ይልቁንም እርሷ (ጸጋይቱ) መፈተኛ ናት፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('39:50', 87, 'እነዚያ ከእነርሱ በፊት የነበሩት ሕዝቦች በእርግጥ ብለዋታል፡፡ ይሠሩት የነበሩትም ነገር ከእነርሱ አልጠቀማቸውም፡፡'),
('39:51', 87, 'የሠሩዋቸውም መጥፎዎች (ቅጣት) አገኛቸው፡፡ ከእነዚህም እነዚያ የበደሉት የሠሩዋቸው መጥፎዎች (ፍዳ) በእርግጥ ይነካቸዋል፡፡ እነርሱም አምላጮች አይደሉም፡፡'),
('39:52', 87, 'አላህ ሲሳዩን ለሚሻው ሰው የሚያሰፋ የሚያጠብም መኾኑን አያውቁምን? በዚህ ውስጥ ለሚያምኑት ሕዝቦች ግሣጼዎች አሉበት፡፡'),
('39:53', 87, 'በላቸው «እናንተ በነፍሶቻችሁ ላይ ድንበር ያለፋችሁ ባሮቼ ሆይ! ከአላህ እዝነት ተስፋ አትቁረጡ፡፡ አላህ ኃጢኣቶችን በመላ ይምራልና፡፡ እነሆ እርሱ መሓሪው አዛኙ ነውና፡፡'),
('39:54', 87, '«ቅጣቱም ወደእናንተ ከመምጣቱና ከዚያም የማትርረዱ ከመኾናችሁ በፊት ወደ ጌታችሁ (በመጸጸት) ተመለሱ፡፡ ለእርሱም ታዘዙ፡፡'),
('39:55', 87, '«እናንተ የማታውቁ ስትኾኑም ቅጣቱ በድንገት ሳይመጣባችሁ በፊት ከጌታችሁ ወደናንተ የተወረደውን መልካሙን (መጽሐፍ) ተከተሉ፡፡»'),
('39:56', 87, '(የካደች) ነፍስ «እኔ ከሚሳለቁት የነበርኩ ስኾን በአላህ በኩል ባጓደልኩት ዋ ጸጸቴ» ማለቷን (ለመፍራት)፤'),
('39:57', 87, 'ወይም «አላህ በመራኝ ኖሮ ከሚጠነቀቁት እኾን ነበር» ማለቷን (ለመፍራት)፡፡'),
('39:58', 87, 'ወይም ቅጣቱን በምታይ ጊዜ «ለእኔ (ወደ ምድረ ዓለም) አንድ ጊዜ መመለስ በኖረኝና ከበጎ አድራጊዎቹ በኾንኩ» ማለቷን (ለመፍራት መልካሙን ተከተሉ)፡፡'),
('39:59', 87, 'የለም ተመርተሃል፡፡ አንቀጾቼ በእርግጥ መጥተውልሃል፡፡ በእነርሱም አስተባብለሃል፡፡ ኮርተሃልም፡፡ ከከሓዲዎቹም ኾነሃል፤ (ይባላል)፡፡'),
('39:60', 87, 'በትንሣኤ ቀንም እነዚያን በአላህ ላይ የዋሹትን ፊቶቻቸው የጠቆሩ ኾነው ታያቸዋለህ፡፡ በገሀነም ውስጥ ለትዕቢተኞች መኖሪያ የለምን?'),
('39:61', 87, 'እነዚያንም የተጠነቀቁትን በማግኛቸው ስፍራ ኾነው አላህ ያድናቸዋል፡፡ ክፉ ነገር አይነካቸውም፡፡ እነርሱም አያዝኑም፡፡'),
('39:62', 87, 'አላህ የነገሩ ሁሉ ፈጣሪ ነው፡፡ እርሱም በነገሩ ሁሉ ላይ አስተናባሪ ነው፡፡'),
('39:63', 87, 'የሰማያትና የምድር (ድልብ) መክፈቻዎች የእርሱ ብቻ ናቸው፡፡ እነዚያም በአላህ አንቀጾች የካዱት እነዚያ እነሱ ከሳሪዎቹ ናቸው፡፡'),
('39:64', 87, '«እናንተ መሃይማን ሆይ! ከአላህ ሌላን እንድግገዛ ታዙኛላችሁን?» በላቸው፡፡'),
('39:65', 87, 'ብታጋራ ሥራህ በእርግጥ ይታበሳል፡፡ በእርግጥም ከከሓዲዎቹ ትኾናለህ ማለት ወደ አንተም ወደእነዚያም ካንተ በፊት ወደነበሩት በእርግጥ ተወርዷል፡፡'),
('39:66', 87, 'ይልቅ አላህን ብቻ ተገዛም፡፡ ከአመስጋኞቹም ኹን፡፡'),
('39:67', 87, 'አላህንም በትንሣኤ ቀን ምድር በመላ ጭብጡ ስትኾን፤ ሰማያትም በኀይሉ የሚጠቀለሉ ሲኾኑ (ከርሱ ጋር ሌላን በማጋራታቸው) ተገቢ ክብሩን አላከበሩትም፡፡ ከሚያጋሩት ጠራ፤ ላቀም፡፡'),
('39:68', 87, 'በቀንዱም ይንነፋል፡፡ በሰማያት ውስጥ ያለው ፍጡርና በምድርም ውስጥ ያለው ፍጡር ሁሉ አላህ የሻው ሲቀር በድንጋጤ ይሞታል፡፡ ከዚያም በእርሱ ሌላ (መንነፋት) ይንነፋል፡፡ ወዲያውም እነርሱ (የሚሠራባቸውን) የሚጠባበቁ ኾነው ቋሚዎች ይኾናሉ፡፡'),
('39:69', 87, 'ምድርም በጌታዋ ብርሃን ታበራለች፡፡ መጽሐፉም ይቅቀረባል፡፡ ነቢያቱና ምስክሮቹም ይመጣሉ፡፡ በመካከላቸውም በእውነት ይፈረዳል፡፡ እነርሱም አይበደሉም፡፡'),
('39:70', 87, 'ነፍስም ሁሉ የሠራችውን ሥራ ትሞላለች፤ (ትሰፈራለች)፡፡ እርሱም የሚሠሩትን ሁሉ ዐዋቂ ነው፡፡'),
('39:71', 87, 'እነዚያ የካዱትም የተከፋፈሉ ጭፍሮች ኾነው ወደ ገሀነም ይንነዳሉ፡፡ በመጧትም ጊዜ ደጃፎችዋ ይከፈታሉ፡፡ ዘበኞችዋም «ከእናንተ የኾኑ መልክተኞች የጌታችሁን አንቀጾች'),
('39:72', 87, '«የገሀነምን ደጃፎች በውስጧ ዘውታሪዎች ስትኾኑ ግቡ፡፡ የትዕቢተኞችም መኖሪያ ምን ትከፋ!» ይባላሉ፡፡'),
('39:73', 87, 'እነዚያም ጌታቸውን የፈሩት የተከፋፈሉ ጭፍሮች ኾነው ወደ ገነት ይንነዳሉ፡፡ በመጧትም ጊዜ ደጃፎችዋ የተከፈቱ ሲኾኑ ዘበኞችዋም ለእነርሱ «ሰላም በናንተ ላይ ይኹን፡፡ ተዋባችሁ፡፡ ዘውታሪዎች ኾናችሁ ግቧት» በሏቸው ጊዜ (ይገቧታል)፡፡'),
('39:74', 87, '«ምስጋና ለአላህ ለዚያ ተስፋ ቃሉን ለሞላልን፡፡ የገነትን ምድር በምንሻው ስፍራ የምንሰፍር ስንኾን ላወረሰን ይገባው» ይላሉም፡፡ የሠሪዎችም ምንዳ ምን ያምር!'),
('39:75', 87, 'መላእክትንም በጌታቸው ምስጋና ቀላቅለው የሚያጠሩ ሲኾኑ በዐርሹ ዙሪያ ከባቢዎች ኾነው ታያለህ፡፡ በመካከላቸው በእውነት ይፈረዳል፡፡ ይባላልም፤ «ምስጋና ለአላህ ለዓለማት ጌታ ይገባው፡፡»'),
('40:1', 87, 'ሐ.መ (ሓ.ሚም)፤'),
('40:2', 87, 'የመጽሐፉ መወረድ አሸናፊ ዐዋቂ ከሆነው አላህ ነው፡፡'),
('40:3', 87, 'ኀጢአትን መሓሪ፣ ጸጸትንም ተቀባይ፣ ቅጣተ ብርቱ፣ የልግስና ባለቤት ከኾነው (አላህ የወረደ ነው)፡፡ ከእርሱ በቀር አምላክ የለም፡፡ መመለሻው ወደርሱ ብቻ ነው፡፡'),
('40:4', 87, 'በአላህ አንቀጾች እነዚያ የካዱት ቢኾኑ እንጅ ማንም (በመዝለፍ) አይከራከርም፡፡ በያገሮችም ውስጥ መዘዋወራቸው አይሸንግልህ፡፡'),
('40:5', 87, 'ከእነርሱ በፊት የኑሕ ሕዝቦች ከኋላቸውም አሕዛቦቹ አስተባባሉ፡፡ ሕዝቦችም ሁሉ መልክተኛቸውን ሊይዙ አሰቡ፡፡ በውሸትም በእርሱ እውነትን ሊያጠፉበት ተከራከሩ፡፡ ያዝኳቸውም፡፡ ታዲያ ቅጣቴ እንዴት ነበር?'),
('40:6', 87, 'እንደዚሁም የጌታህ ቃል በእነዚያ በካዱት ላይ እነርሱ የእሳት ጓዶች ናቸው ማለት ተረጋገጠች፡፡'),
('40:7', 87, 'እነዚያ ዐርሹን የሚሸከሙት እነዚያም በዙሪያው ያሉት በጌታቸው ምስጋና ያወድሳሉ፡፡ በእርሱም ያምናሉ፡፡ «ጌታችን ሆይ! ነገሩን ሁሉ በእዝነትና በዕውቀት ከበሃል፡፡ ስለዚህ ለእነዚያ ለተጸጸቱት መንገድህንም ለተከተሉት ምሕረት አድርግላቸው፡፡ የእሳትንም ቅጣት ጠብቃቸው፡፡» እያሉ ለእነዚያ ላመኑት ምሕረትን ይለምናሉ፡፡'),
('40:8', 87, '«ጌታችን ሆይ! እነርሱንም፣ ከአባቶቻቸውና ከሚስቶቻቸውም፣ ከዝርዮቻቸውም፣ የበጀውን ሁሉ እነዚያን ቃል የገባህላቸውን የመኖሪያ ገነቶች አግባቸው፡፡ አንተ አሸናፊው ጥበበኛው አንተ ነህና፡፡'),
('40:9', 87, '«ከቅጣቶችም ጠብቃቸው፡፡ በዚያ ቀንም የምትጠብቃውን ሰው በእርግጥ አዘንክለት፡፡» ይህም እርሱ ታላቅ ማግኘት ነው፡፡'),
('40:10', 87, 'እነዚያ የካዱት ሰዎች «ወደ እምነት በምትጠሩና በምትክዱ ጊዜ አላህ (እናንተን) መጥላቱ ነፍሶቻችሁን (ዛሬ) ከመጥላታችሁ የበለጠ ነው» በማለት ይጥጠራሉ፡፡'),
('40:11', 87, '«ጌታችን ሆይ! ሁለትን ሞት አሞትከን፡፡ ሁለትንም ሕይወት ሕያው አደረግከን፡፡ በኃጢኣቶቻችንም መሰከርን፡፡ ታዲያ (ከእሳት) ወደ መውጣት መንገድ አለን?» ይላሉ፡፡'),
('40:12', 87, '«ይህ እነሆ አላህ ብቻውን በተጠራ ጊዜ ስለ ካዳችሁ በእርሱም ተጋሪ ቢደረግ የምታምኑ ስለ ኾናችሁ ነው፡፡ ስለዚህ ፍርዱ ከፍተኛ ታላቅ ለኾነው አላህ ብቻ ነው፡፡»'),
('40:13', 87, 'እርሱ ያ (ለአምላክነቱ) ምልክቶቹን የሚያሳያችሁ ለእናንተም ከሰማይ ሲሳይን የሚያወርድላችሁ ነው፡፡ ወደእርሱም የሚመለስ ሰው ቢኾን እንጂ ሌላው አይገሰጽም፡፡'),
('40:14', 87, 'አላህንም ከሓዲዎች ቢጠሉም ሃይማኖትን ለእርሱ አጥሪዎች ኾናችሁ ተገዙት፡፡'),
('40:15', 87, '(እርሱ) ደረጃዎችን ከፍ አድራጊ የዐርሹ ባለቤት ነው፡፡ የመገናኛውን ቀን ያስፈራራ ዘንድ ከባሮቹ በሚሻው ሰው ላይ ከትዕዛዙ መንፈስን (ራእይን) ያወርዳል፡፡'),
('40:16', 87, 'እነርሱ (ከመቃብር) በሚወጡበት ቀን በአላህ ላይ ከእነርሱ ምንም ነገር አይደበቅም፡፡ «ንግሥናው ዛሬ ለማን ነው?» (ይባላል፤)፡፡ «ለአሸናፊው ለአንዱ አላህ ብቻ ነው» (ይባላል)፡፡'),
('40:17', 87, '«ዛሬ ነፍስ ሁሉ በሠራችው ሥራ ትምመነዳለች፡፡ ዛሬ በደል የለም፡፡ አላህ በእርግጥ ምርመራው ፈጣን ነው» (ይባላል)፡፡'),
('40:18', 87, 'ቅርቢቱንም (የትንሣኤን) ቀን ልቦች ጭንቀትን የተመሉ ኾነው ላንቃዎች ዘንድ የሚደርሱበትን ጊዜ አስጠንቅቃቸው፡፡ ለበዳዮች ምንም ወዳጅና ተሰሚ አማላጅ የላቸውም፡፡'),
('40:19', 87, '(አላህ) የዓይኖችን ክዳት ልቦችም የሚደብቁትን ሁሉ ያውቃል፡፡'),
('40:20', 87, 'አላህም በእውነት ይፈርዳል፡፡ እነዚያም ከእርሱ ሌላ የሚግገዟቸው በምንም አይፈርዱም፡፡ አላህ እርሱ ሰሚው ተመልካቹ ነው፡፡'),
('40:21', 87, 'የእነዚያን ከእነርሱ በፊት የነበሩትን ሕዝቦች ፍጻሜ እንዴት እንደነበረ ይመለከቱ ዘንድ በምድር ላይ አይኼዱምን? በኀይልና በምድር ላይ በተዋቸው ምልክቶች፤ ከእነርሱ ይበልጥ የበረቱ ነበሩ፡፡ አላህም በኀጢአቶቻቸው ያዛቸው፡፡ ለእነርሱም ከአላህ (ቅጣት) ምንም ጠባቂ አልነበራቸውም፡፡'),
('40:22', 87, 'ይህ (መያዝ) እነርሱ መልክተኞቻቸው በተዓምራቶች ይመጡባቸው ስለነበሩና ስለ ካዱ ነው፡፡ አላህም ያዛቸው፡፡ እርሱ ኀያል ቅጣተ ብርቱ ነውና፡፡'),
('40:23', 87, 'ሙሳንም በተዓምራቶቻችንና በግልጽ ማስረጃ በእርግጥ ላክነው፡፡'),
('40:24', 87, 'ወደ ፈርዖንና ወደ ሃማን፤ ወደ ቃሩንም (ላክነው)፡፡ «ድግምተኛ ውሸታም ነው» አሉም፡፡'),
('40:25', 87, 'ከእኛ ዘንድ እውነትን ይዞ በመጣላቸውም ጊዜ «የእነዚያን ከእርሱ ጋር ያመኑትን ሰዎች ወንዶች ልጆች ግደሉ፤ ሴቶቻቸውንም አስቀሩ» አሉ፡፡ የከሓዲዎችም ተንኮል በጥፋት ውስጥ እንጅ አይደለም፡፡'),
('40:26', 87, 'ፈርዖንም «ተዉኝ፤ ሙሳን ልግደል፡፡ ጌታውንም ይጥራ፡፡ ያድነው እንደኾነ፡፡ እኔ ሃይማኖታችሁን ሊለውጥ፤ ወይም በምድር ውስጥ ጥፋትን ሊያሰራጭ እፈራለሁና» አለ፡፡'),
('40:27', 87, 'ሙሳም «እኔ በምርመራው ቀን ከማያምን ትዕቢተኛ ሁሉ በጌታዬና በጌታችሁ ተጠበቅሁ» አለ፡፡'),
('40:28', 87, 'ከፈርዖንም ቤተሰቦች አንድ እምነቱን የሚደብቅ ምእመን ሰው አለ፡- «ሰውየውን ከጌታችሁ በተዓምራቶች በእርግጥ የመጣለችሁ ሲኾን ‹ጌታዬ አላህ ነው› ስለሚል ትገድላላችሁን? ውሸታምም ቢኾን ውሸቱ በርሱው ላይ ነው፡፡ እውነተኛ ቢኾን ግን የዚያ የሚያሰፈራራችሁ ከፊሉ ያገኛችኋል፡፡ አላህ ያንን እርሱ ድንበር አላፊ ውሸታም የኾነውን አይመራምና፡፡'),
('40:29', 87, '«ወገኖቼ ሆይ! በምድር ላይ አሸናፊዎች ስትኾኑ ዛሬ መንግስቱ የእናንተ ነው፡፡ ታዲያ ከአላህ ቅጣት ቢመጣብን የሚያድነን ማን ነው?» (አለ)፡፡ ፈርዖን «የማየውን ነገር እንጅ፤ አላመለክታችሁም፡፡ ቅኑንም መንገድ እንጅ አልመራችሁም» አላቸው፡፡'),
('40:30', 87, 'ያም ያመነው ሰው አለ «እኔ በናንተ ላይ የአሕዛቦቹን ቀን ብጤ እፈራላችኋለሁ፡፡'),
('40:31', 87, '«የኑሕን ሕዝቦች፣ የዓድንና የሰሙድንም፣ የእነዚያንም ከኋላቸው የነበሩትን ልማድ ብጤ (እፈራላችኋለሁ)፡፡ አላህም ለባሮቹ መበደልን የሚሻ አይደለም፡፡'),
('40:32', 87, '«ወገኖቼ ሆይ! እኔ በእናንተ ላይ የመጠራሪያን ቀን እፈራለሁ፡፡»'),
('40:33', 87, 'ወደ ኋላ ዞራችሁ በምትሸሹበት ቀን፤ ለናንተ ከአላህ (ቅጣት) ምንም ጠባቂ የላችሁም፡፡ አላህም የሚያጠመው ሰው ለርሱ ምንም አቅኚ የለውም፡፡'),
('40:34', 87, 'ዩሱፍም ከዚህ በፊት ግልጽ ማስረጃዎችን በእርግጥ አመጣላቸሁ፡፡ ከዚያም እርሱ ካመጣላችሁ ነገር ከመጠራጠር አልተወገዳችሁም፡፡ በጠፋም ጊዜ «አላህ ከእርሱ ኋላ መልክተኛን በጭራሽ አይልክም» አላችሁ፡፡ አላህ እንደዚሁ ድንበር አላፊ ተጠራጣሪ የኾነን ሰው ያሳስታል፡፡'),
('40:35', 87, 'እነዚያ፤ የመጣላቸው አስረጅ ሳይኖር በአላህ ተዓምራቶች የሚከራከሩ (ክርክራቸው) አላህ ዘንድና እነዚያም አመኑት ዘንድ መጠላቱ በጣም ተለቀ፡፡ እንደዚሁ አላህ በኩሩ ጨካኝ (ሰው) ልብ ሁሉ ላይ ያትማል፡፡'),
('40:36', 87, 'ፈርዖንም አለ «ሃማን ሆይ! መንገዶችን እደርስ ዘንድ ረዢም ሕንጻን ለእኔ ካብልኝ፡፡'),
('40:37', 87, '«የሰማያትን መንገዶች (እደርስ ዘንድ)፣ ወደ ሙሳም አምላክ እመለከት ዘንድ፡፡ እኔም ውሸታም ነው ብዬ በእርግጥ እጠረጥረዋለሁ» (አለ)፡፡ እንደዚሁም ለፈርዖን መጥፎ ሥራው ተሸለመለት፡፡ ከቅን መንገድም ታገደ፡፡ የፈርዖንም ተንኮል በከሳራ ውስጥ እንጅ አይደለም፡፡'),
('40:38', 87, 'ያም ያመነው አለ «ወገኖቼ ሆይ! ተከተሉኝ፡፡ ቀጥታውን መንገድ እመራችኋለሁና፡፡'),
('40:39', 87, '«ወገኖቼ ሆይ! ይህቺ ቅርቢቱ ሕይወት (ጥቂት) መጣቀሚያ ብቻ ናት፡፡ መጨረሻይቱም ዓለም እርሷ መርጊያ አገር ናት፡፡»'),
('40:40', 87, '«መጥፎን የሠራ ሰው ብጤዋን እንጅ አይምመነዳም፡፡ እርሱ ምእመን ኾኖ ከወንድ ወይም ከሴት በጎን የሠራም ሰው እነዚያ ገነትን ይገባሉ፡፡ በእርሷ ውስጥ ያለ ቁጥጥር ይመገባሉ፡፡'),
('40:41', 87, '«ወገኖቼም ሆይ! ወደ መዳን የምጠራችሁ ስኾን ወደ እሳትም የምትጠሩኝ ስትኾኑ ለኔ ምን አለኝ!'),
('40:42', 87, '«በአላህ ልክድና በእርሱም ለእኔ ዕውቀት የሌለኝን ነገር በእርሱ እንዳጋራ ትጠሩኛላችሁ፡፡ እኔም ወደ አሸናፊው፤ መሓሪው (አላህ) እጠራችኋለሁ፡፡'),
('40:43', 87, '«በእርግጥ ወደእርሱ የምትጠሩብኝ (ጣዖት) ለእርሱ በቅርቢቱም ኾነ በመጨረሻይቱ ዓለም (ተሰሚ) ጥሪ የለውም፡፡ መመለሻችንም በእርግጥ ወደ አላህ ነው፡፡ ወሰን አላፊዎቹም እነሱ የእሳት ጓዶች ናቸው፡፡'),
('40:44', 87, '«ወደ ፊትም ለእናንተ የምላችሁን ምክር (ቅጣትን በምታዩ ጊዜ) ታስታውሳላችሁ፡፡ ነገሬንም ሁሉ ወደ አላህ አስጠጋለሁ፡፡ አላህ ባሮቹን ተመልካች ነውና፡፡»'),
('40:45', 87, 'ከመከሩዋቸውም መጥፎዎች አላህ ጠበቀው፡፡ በፈርዖን ቤተሰቦችም ላይ ክፉ ቅጣት ሰፈረባቸው፡፡'),
('40:46', 87, 'እሳት በጧትና በማታ በእርሷ ላይ ይቀርባሉ፡፡ ሰዓቲቱም በምትኾንበት ቀን «የፈርዖንን ቤተሰቦች ብርቱን ቅጣት (ገሀነምን) አግቡዋቸው» (ይባላል)፡፡'),
('40:47', 87, 'በእሳትም ውስጥ የሚከራከሩበትን ጊዜ (አስታውስ)፡፡ ደካማዎቹም ለእነዚያ ለኮሩት «እኛ ለእናንተ ተከታዮች ነበርንና እናንተ (አሁን) ከእሳት ከፊሉን ከእኛ ላይ ገፍታሪዎች ናችሁን?» ይላሉ፡፡'),
('40:48', 87, 'እነዚያም የኮሩት «እኛ ሁላችንም በውስጧ ነን፡፡ አላህ በባሮቹ መካከል በእርግጥ ፈረደ» ይላሉ፡፡'),
('40:49', 87, 'እነዚያም በእሳት ውሰጥ ያሉት ለገሀነም ዘበኞች «ጌታችሁን ለምኑልን፤ ከእኛ ላይ ከቅጣቱ አንድን ቀን ያቃልልን» ይላሉ፡፡'),
('40:50', 87, '(ዘበኞቹም) «መልእክተኞቻችሁ በተዓምራቶች ይመጡላችሁ አልነበሩምን?» ይላሉ፡፡ (ከሓዲዎቹም) «እንዴታ መጥተውናል እንጅ፤ (ግን አስተባበልናቸው)» ይላሉ፡፡'),
('40:51', 87, 'እኛ መልክተኞቻችንን፣ እነዚያንም ያመኑትን በቅርቢቱ ሕይወት ምስክሮችም በሚቆሙበት ቀን በእርግጥ እንረዳለን፡፡'),
('40:52', 87, 'በደለኞችን ምክንያታቸው በማይጠቅማቸው ቀን (እንረዳለን)፡፡ ለእነርሱም ርግማን አልላቸው፡፡ ለእነርሱም መጥፎ አገር አልላቸው፡፡'),
('40:53', 87, 'ሙሳንም መምሪያን በእርግጥ ሰጠነው፡፡ የእስራኤልንም ልጆች መጽሐፉን አወረስናቸው፡፡'),
('40:54', 87, 'ለባለ አእምሮዎች መሪና ገሳጭ ሲኾን፡፡'),
('40:55', 87, '(ሙሐመድ ሆይ!) ታገስም የአላህ ተስፋ እውነት ነውና፡፡ ለስህተትህም ምሕረትን ለምን፡፡ ከቀትር በኋላም በማለዳም ጌታሀን ከማመስገን ጋር አጥራው፡፡'),
('40:56', 87, 'እነዚያ የመጣላቸው አስረጅ ሳይኖር በአላህ አንቀጾች የሚከራከሩ በልቦቻቸው ውስጥ እነርሱ ደራሾቹ ያልኾኑት ኩራት ብቻ እንጅ ምንም የለም፡፡ በአላህም ተጠበቅ፡፡ እነሆ እርሱ ሰሚው ተመልካቹ ነውና፡፡'),
('40:57', 87, 'ሰማያትንና ምድርን መፍጠር ሰዎችን ከመፍጠር ይልቅ ታላቅ ነው፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም፡፡'),
('40:58', 87, 'ዕውርና የሚያይ እነዚያም አምነው መልካሞችን የሠሩና መጥፎ ሠሪው አይስተካከሉም፡፡ በጣም ጥቂትን ብቻ ትገሰጻላችሁ፡፡'),
('40:59', 87, 'ሰዓቲቱ በእርግጥ መጪ ናት፡፡ በእርሷ ጥርጥር የለም፡፡ ግን አብዛኞቹ ሰዎች አያምኑም፡፡'),
('40:60', 87, 'ጌታችሁም አለ «ለምኑኝ፤ እቀበላችኋለሁና፡፡ እነዚያ እኔን ከመግገዛት የሚኮሩት ተዋራጆች ኾነው ገሀነምን በእርግጥ ይገባሉ፡፡'),
('40:61', 87, 'አላህ ያ ለእናንተ ሌሊትን በውስጡ ልታርፉበት (ጨለማ) ቀንንም (ልትሠሩበት) የሚያሳይ ያደረገላችሁ ነው፡፡ አላህ በሰዎች ላይ በእርግጥ የችሮታ ባለቤት ነውና፡፡ ግን አብዛኛዎቹ ሰዎች አያመሰግኑም፡፡'),
('40:62', 87, 'ይሃችሁ ጌታችሁ አላህ ነው፤ የነገሩ ሁሉ ፈጣሪ ነው፤ ከርሱ ሌላ አምላክ የለም፤ ታዲያ (ከእምነት) ወዴት ትመለሳላችሁ፡፡'),
('40:63', 87, 'እንደዚሁ እነዚያ በአላህ አንቀጾች ይክዱ የነበሩት (ከእምነት) ይመለሳሉ፡፡'),
('40:64', 87, 'አላህ ያ ምድርን መርጊያ ሰማይንም ጣሪያ ያደረገላችሁ ነው፡፡ የቀረጻችኁም ቅርጻችሁንም ያሳመረ ከጣፋጮችም ሲሳዮች የሰጣችሁ ነው፡፡ ይሃችሁ ጌታችሁ አላህ ነው፡፡ የዓለማትም ጌታ አላህ ላቀ፡፡'),
('40:65', 87, 'እርሱ ብቻ (ሁል ጊዜ) ሕያው ነው፤ ከርሱ ሌላ አምላክ የለም፤ ሃይማኖትንም ለእርሱ ያጠራችሁ ስትኾኑ «ምስጋና ለዓለማት ጌታ ለአላህ ይኹን» የምትሉ ኾናችሁ ተገዙት፡፡'),
('40:66', 87, '«እኔ ከጌታዬ አስረጂዎች በመጡልኝ ጊዜ እነዚያን ከአላህ ሌላ የምትገዙዋቸውን እንዳልገዛ ተከልክያለሁ፡፡ ለዓለማት ጌታም እንድገዛ ታዝዣለሁ» በላቸው፡፡'),
('40:67', 87, 'እርሱ ያ ከዐፈር ከዚያም ከፍትወት ጠብታ ከዚያም ከረጋ ደም የፈጠራችሁ ነው፡፡ ከዚያም ሕጻናት አድርጎ ያወጣችኋል፡፡ ከዚያም ጥንካሬያችሁን ትደርሱ ዘንድ፤ ከዚያም ሽማግሌዎች ትኾኑ ዘንድ (ያቆያችኋል)፡፡ ከእናንተም ውስጥ ከዚህ በፊት የሚሞት አልለ፡፡ (ይህንንም ያደረገው ልትኖሩና) የተወሰነ ጊዜንም ልትደርሱ ታውቁም ዘንድ ነው፡፡'),
('40:68', 87, 'እርሱ ያ ሕያው የሚያደርግ የሚገድልም ነው፡፡ አንዳችን ነገር በሻም ጊዜ ለእርሱ የሚለውን «ኹን» ነው፤ ወዲያውም ይኾናል፡፡'),
('40:69', 87, 'ወደእነዚያ በአላህ አንቀጾች ወደሚከራከሩት (ከእምነት) እንዴት እንደሚመለሱ አታይምን?'),
('40:70', 87, 'ወደእነዚያ በመጽሐፉ በዚያም መልክተኞቻችንን በእርሱ በላክንበት ወዳስተባበሉት (አታይምን?) ወደፊትም ያውቃሉ፡፡'),
('40:71', 87, 'እንዛዝላዎቹና ሰንሰለቶቹ በአንገቶቻቸው ላይ በተደረጉ ጊዜ (በእርሷ) ይጎተታሉ፡፡'),
('40:72', 87, 'በገሀነም ውስጥ (ይጎተታሉ)፤ ከዚያም በእሳት ውስጥ ይማገዳሉ፡፡'),
('40:73', 87, 'ከዚያም ለእነርሱ ይባላሉ (በአላህ) «ታጋሯቸው የነበራችሁት የታሉ?»'),
('40:74', 87, '«ከአላህ ሌላ (የምታጋሩዋቸው)፤ ከኛ ተሰወሩን?» «ከቶ ከዚህ በፊት ምንንም የምንገዛ አልነበርንም» ይላሉ፤ እንደዚሁ አላህ ከሓዲዎችን ያሳስታል፡፡'),
('40:75', 87, 'ይህ (ቅጣት) ያላግባብ በምድር ውሰጥ ትደሰቱ በነበራችሁትና ትንበጣረሩ በነበራችሁት ነው (ይባላሉ)፡፡'),
('40:76', 87, 'የገሀነምን በሮች በውስጧ ዘውታሪዎች ስትኾኑ ግቡ (ይባላሉ)፡፡ የትዕቢተኞችም መኖሪያ (ገሀነም) ምን ትከፋ!'),
('40:77', 87, 'ታገስም የአላህ ቀጠሮ እውነት ነውና፡፡ የዚያንም የምናስፈራራቸውን ከፊሉን (በሕይወትህ) ብናሳይህ (መልካም ነው)፡፡ ወይም ብንገድልህ ወደኛ ይመለሳሉ፡፡'),
('40:78', 87, 'ካንተ በፊትም መልክተኞችን በእርግጥ ልከናል፡፡ ከእነርሱ ባንተ ላይ የተረክንልህ አልለ፡፡ ከእነርሱም ባንተ ላይ ያልተረክነው አልለ፡፡ ለማንኛውም መልክተኛ በአላህ ፈቃድ ካልኾነ ተዓምርን ሊያመጣ አይገባውም፡፡ የአላህም ትእዛዝ በመጣ ጊዜ በእውነት ይፈረዳል፡፡ እዚያ ዘንድም አጥፊዎቹ ይከስራሉ፡፡'),
('40:79', 87, 'አላህ ያ ለእናንተ ግመልን ከብትንና ፍየልን ከእርሷ (ከፊሏን) ልትጋልቡ የፈጠረላችሁ ነው፡፡ ከእርሷም ትበላላችሁ፡፡'),
('40:80', 87, 'ለእናንተም በእርሷ ውስጥ ጥቅሞች አልሏችሁ፡፡ በእርሷም ላይ (እቃን በመጫን) በልቦቻችሁ ያሰባችሁትን ጉዳይ ትደርሱ ዘንድ (ፈጠረላችሁ)፡፡ በእርሷም ላይ በመርከቦችም ላይ ትሳፈራላችሁ፡፡'),
('40:81', 87, 'ተዓምራቱንም ያሳያችኋል፡፡ ታዲያ ከአላህ ተዓምራት የትኛውን ትክዳላችሁ?'),
('40:82', 87, 'የእነዚያን ከእነርሱ በፊት የነበሩትን ሕዝቦች ፍጻሜ እንዴት እንደነበረ ይመለከቱ ዘንድ በምድር ላይ አይኼዱምን? ከእነርሱ ይበልጥ ብዙዎች በኀይልና በምድር ላይ በተዋቸው ምልክቶችም በጣም ብርቱዎች ነበሩ፡፡ ያም ይሠሩት የነበሩት ከእነርሱ ምንም አልጠቀማቸውም፡፡'),
('40:83', 87, 'መልክተኞቻቸውም ተዓምራቶችን ባመጡላቸው ጊዜ እነርሱ ዘንድ ባለው ዕውቀት ተደሰቱ፡፡ በእርሱ ይሳለቁበት የነበሩት ቅጣትም በእነርሱ ላይ ሰፈረባቸው፡፡'),
('40:84', 87, 'ብርቱ ቅጣታችንንም ባዩ ጊዜ «በአላህ አንድ ሲኾን አምነናል፤ በእርሱም እናጋራ በነበርነው (ጣዖታት) ክደናል» አሉ፡፡'),
('40:85', 87, 'ብርቱ ቅጣታችንን ባዩ ጊዜ ማመናቸውም የሚጠቅማቸው አልነበረም፡፡ የአላህን ደንብ ያችን በባሮቹ ውስጥ ያለፈችውን (ተጠንቀቁ) በዚያ ጊዜም ከሓዲዎች ከሰሩ፡፡'),
('41:1', 87, 'ሐ.መ.(ሓ ሚም)፡፡'),
('41:2', 87, '(ይህ ቁርኣን) እጅግ በጣም ሩኅሩህ በጣም አዛኝ ከሆነው (አላህ) የተወረደ ነው፡፡'),
('41:3', 87, 'አንቀጾቹ የተብራሩ የኾነ መጽሐፍ ነው፡፡ ዐረብኛ ቁርኣን ሲኾን ለሚያውቁ ሕዝቦች (የተብራራ) ነው፡፡'),
('41:4', 87, 'አብሳሪና አስፈራሪ ሲኾን (ተወረደ)፡፡ አብዛኛዎቻቸውም ተዉት፡፡ እነርሱም አይሰሙም፡፡'),
('41:5', 87, 'አሉም «ልቦቻችን ከእዚያ ወደእርሱ ከምትጠራን እምነት በመሸፈኛዎች ውስጥ ናቸው፡፡ በጆሮዎቻችንም ላይ ድንቁርና አልለ፤ በእኛና ባንተም መካከል ግርዶሽ አልለ፡፡ (በሃይማኖትህ) ሥስራም፤ እኛ ሠሪዎች ነንና፡፡»'),
('41:6', 87, '(እንዲህ) በላቸው «እኔ መሰላችሁ ሰው ብቻ ነኝ፡፡ አምላካችሁ አንድ አምላክ ብቻ ነው ወደእርሱም ቀጥ በሉ ምሕረትንም ለምኑት ማለት ወደእኔ ይወረድልኛል፡፡ ለአጋሪዎቹም ወዮላቸው፡፡'),
('41:7', 87, 'ለእነዚያ ዘካን ለማይሰጡት እነርሱም በመጨረሻይቱ ዓለም እነርሱ ከሓዲዎች ለኾኑት (ወዮላቸው)፡፡'),
('41:8', 87, 'እነዚያ ያመኑትና በጎ ሥራዎችን የሠሩት ለእነርሱ የማይቆረጥ ምንዳ አልላቸው፡፡'),
('41:9', 87, 'በላቸው «እናንተ በዚያ ምድርን በሁለት ቀኖች ውስጥ በፈጠረው አምላክ በእርግጥ ትክዳላችሁን? ለእርሱም ባለንጣዎችን ታደርጋላችሁን? ያ (ይህንን የሠራው) የዓለማት ጌታ ነው፡፡'),
('41:10', 87, 'በእርሷም ከበላይዋ የረጉ ጋራዎችን አደረገ፡፡ በእርሷም በረከትን አደረገ፡፡ በውስጧም ምግቦችዋን (ካለፉት ሁለት ቀኖች ጋር) በአራት ቀናት ውሰጥ ለጠያቂዎች ትክክል ሲኾኑ ወሰነ፡፡'),
('41:11', 87, 'ከዚያም ወደ ሰማይ እርሷ ጭስ ኾና ሳለች አሰበ፡፡ ለእርሷም ለምድርም «ወዳችሁም ኾነ ወይም ጠልታችሁ ኑ» አላቸው፡፡ «ታዛዦች ኾነን መጣን» አሉ፡፡'),
('41:12', 87, 'በሁለት ቀኖችም ውስጥ ሰባት ሰማያት አደረጋቸው፡፡ በሰማይቱም ሁሉ ነገሯን አዘጋጀ፡፡ ቅርቢቱንም ሰማይ በመብራቶች አጌጥን፡፡ (ከሰይጣናት) መጠበቅንም ጠበቅናት፡፡ ይህ የአሸናፊው የዐዋቂው (ጌታ) ውሳኔ ነው፡፡'),
('41:13', 87, '(ከእምነት) እንቢ «ቢሉም እንደ ዓድና ሰሙድ መቅሰፍት ብጤ የኾነን መቅሰፍት አስጠነቅቃችኋለሁ» በላቸው፡፡'),
('41:14', 87, 'መልክተኞቹ አላህን እንጅ ሌላን አትግገዙ በማለት ከስተፊታቸውም ከስተኋለቸውም በመጡባቸው ጊዜ «ጌታችን በሻ ኖሮ መላእክትን ባወረደ ነበር፡፡ ስለዚህ እኛ በዚያ በእርሱ በተላካችሁበት ከሓዲዎች ነን» አሉ፡፡'),
('41:15', 87, 'ዓድም በምድር ላይ ያለ አግባብ ኮሩ፡፡ «ከእኛ ይበልጥ በኀይል ብርቱ ማን ነው?» አሉም፡፡ ያ የፈጠራቸው አላህ እርሱ በኀይል ከእነርሱ ይበልጥ የበረታ መኾኑን አያዩምን? በተዓምራታችንም ይክዱ ነበሩ፡፡'),
('41:16', 87, 'በቅርቢቱ ሕይወት የውርደትን ቅጣት ልናቀምሳቸውም በእነርሱ ላይ የሚንሻሻን ብርቱ ነፋስ መናጢዎች በኾኑ ቀናት ውስጥ ላክንባቸው፡፡ የመጨረሻይቱም (ዓለም) ስቃይ በጣም አዋራጅ ነው፡፡ እነርሱም አይረዱም፡፡'),
('41:17', 87, 'ሰሙዶችማ መራናቸው ዕውርነትንም በቅንነት ላይ መረጡ፡፡ ይሠሩትም በነበሩት ኃጢኣት አሳናሽ የኾነችው የመብረቅ ቅጣት ያዘቻቸው፡፡'),
('41:18', 87, 'እነዚያንም ያመኑትንና ይጠነቀቁ የነበሩትን አዳንናቸው፡፡'),
('41:19', 87, 'የአላህም ጠላቶች ወደ እሳት የሚሰበሰቡበትን ቀን (አስታውስ)፡፡ እነርሱም የሚከመከሙ ኾነው ይነዳሉ፡፡'),
('41:20', 87, 'በመጧትም ጊዜ ጆሮዎቻቸው፣ ዓይኖቻቸውና ቆዳዎቻቸውም ይሠሩት በነበሩት ነገር በእነርሱ ላይ ይመሰክሩባቸዋል፡፡'),
('41:21', 87, 'ለቆዳዎቻቸውም «በእኛ ላይ ለምን መሰከራችሁብን?» ይላሉ፡፡ «ያ አንዳቹን ነገር ሁሉ ያናገረው አላህ አናገረን፡፡ እርሱም በመጀመሪያ ጊዜ ፈጠራችሁ፡፡ ወደእርሱም ትመለሳላችሁ» ይሏቸዋል፡፡'),
('41:22', 87, 'ጆሮዎቻችሁ ዓይኖቻችሁና ቆዳዎቻችሁም በእናንተ ላይ ከመመስከራቸው የምትደበቁ አልነበራችሁም፡፡ ግን አላህ ከምትሠሩት ብዙውን አያውቅም ብላችሁ ጠረጠራችሁ፡፡'),
('41:23', 87, 'ይህም ያ በጌታችሁ የጠረጠራችሁት ጥርጣሪያችሁ አጠፋችሁ፡፡ ከከሳሪዎቹም ኾናችሁ (ይባላሉ)፡፡'),
('41:24', 87, 'ቢታገሱም እሳት ለእነርሱ መኖሪያቸው ናት፡፡ ወደሚወዱት መመለስንም ቢጠይቁ እነርሱ ተቀባይ የሚያገኙ አይደሉም፡፡'),
('41:25', 87, 'ለእነርሱም ቁራኛዎችን አዘጋጀንላቸው፡፡ በፊታቸው ያለውንና በኋላቸው ያለውንም ሁሉ ለእነርሱ ሸለሙላቸው፡፡ ከጋኔንና ከሰውም ከእነርሱ በፊት በእርግጥ ካለፉት ሕዝቦች ጋር ኾነው ቃሉ በእነርሱ ላይ ተረጋገጠባቸው፡፡ እነርሱ በእርግጥ ከሳሪዎች ነበሩና፡፡'),
('41:26', 87, 'እነዚያም የካዱት «ይህንን ቁርኣን አታዳምጡ፡፡ ታሸንፉም ዘንድ (ሲነበብ) በእርሱ ውሰጥ ተንጫጩ» አሉ፡፡'),
('41:27', 87, 'እነዚያንም የካዱትን ብርቱን ቅጣት እናቀምሳቸዋለን፡፡ የእዚያነም ይሠሩት የነበሩትን መጥፎውን (ፍዳ) በእርግጥ እንመነዳቸዋለን፡፡'),
('41:28', 87, 'ይህ የአላህ ጠላቶች ፍዳ ነው፡፡ እሳት በውስጧ ለእነርሱ የዘላለም መኖሪያ አገር አልላቸው፡፡ ከአንቀጾቻችን ይክዱ በነበሩት ምንዳን (ይምመነዳሉ)፡፡'),
('41:29', 87, 'እነዚያም የካዱት (በእሳት ውስጥ ኾነው) «ጌታችን ሆይ! እነዚያን ከጋኔንና ከሰው ያሳሳቱንን አሳየን፡፡ ከታችኞቹ ይኾኑ ዘንድ ከጫማዎቻችን ሥር እናደርጋቸዋለንና» ይላሉ፡፡'),
('41:30', 87, 'እነዚያ «ጌታችን አላህ ነው» ያሉ ከዚያም ቀጥ ያሉ «አትፍሩ፤ አትዘኑም፤ በዚያችም ተስፋ ቃል ትደረግላችሁ በነበራችሁት ገነት ተበሰሩ» በማለት በነሱ ላይ መላእክት ይወርዳሉ፡፡'),
('41:31', 87, '«እኛ በቅርቢቱም ሕይወት በመጨረሻይቱም ረዳቶቻችሁ ነን! ለእናንተም በእርሷ ውስጥ ነፍሶቻችሁ የሚሹት ሁሉ አልላችሁ፡፡ ለእናንተም በእርሷ ውስጥ የምትፈልጉት ሁሉ አልላችሁ፡፡'),
('41:32', 87, '«መሓሪ አዛኝ ከኾነው አላህ መስተንግዶ ሲኾን» (ይባላሉ)፡፡'),
('41:33', 87, 'ወደ አላህ ከጠራና መልካምንም ከሠራ፣ «እኔ ከሙስሊሞች ነኝ» ካለም ሰው ይበልጥ ቃሉ ያማረ ማን ነው?'),
('41:34', 87, 'መልካሚቱና ክፉይቱም (ጸባይ) አይተካከሉም፡፡ በዚያች እርሷ መልካም በኾነችው ጸባይ (መጥፎይቱን) ገፍትር፡፡ ያን ጊዜ ያ ባንተና በእርሱ መካከል ጠብ ያለው ሰው እርሱ ልክ እንደ አዛኝ ዘመድ ይኾናል፡፡'),
('41:35', 87, '(ይህችንም ጠባይ) እነዚያ የታገሱት እንጅ ሌላው አያገኛትም፡፡ የትልቅም ዕድል ባለቤት እንጅ ማንም አይገጠማትም፡፡'),
('41:36', 87, 'ከሰይጣንም ጉትጎታ ቢያገኝህ (ከመልካም ጠባይም ቢመልስህ) በአላህ ተጠበቅ፡፡ እነሆ እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('41:37', 87, 'ሌሊትና ቀንም ፀሐይና ጨረቃም ከምልክቶቹ ናቸው፡፡ ለፀሐይና ለጨረቃ አትስገዱ፡፡ ለእዚያም ለፈጠራቸው አላህ ስገዱ፡፡ እርሱን ብቻ የምትግገዙ እንደ ኾናችሁ (ለሌላ አትስገዱ)፡፡'),
('41:38', 87, 'ቢኮሩም እነዚያ በጌታህ ዘንድ ያሉት (መላእክት) በቀንም በሌሊትም ለእርሱ ያወድሳሉ፡፡ እነርሱም አይሰለቹም፡፡'),
('41:39', 87, 'አንተ ምድርን ደረቅ ኾና ማየትህም ከምልክቶቹ ነው፡፡ በእርሷም ላይ ውሃን ባወረድን ጊዜ (በቡቃያዎችዋ) ትላወሳለች፡፡ ትነፋለችም፡፡ ያ ሕያው ያደረጋት ጌታ በእርግጥ ሙታንን ሕያው አድራጊ ነው፡፡ እነርሱ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('41:40', 87, 'እነዚያ አንቀጾቻችንን የሚያጣምሙ በእኛ ላይ አይደበቁም፡፡ (የሚያጣምምና) በእሳት ውስጥ የሚጣለው ሰው ይበልጣልን? ወይስ በትንሣኤ ቀን ጸጥተኛ ኾኖ የሚመጣው ሰው? የሻችሁትን ሥሩ (ዋጋችሁን ታገኛላችሁ)፡፡ እርሱ የምትሠሩትን ሁሉ ተመልካች ነውና፡፡'),
('41:41', 87, 'እነዚያ በቁርኣን እርሱ አሸናፊ መጽሐፍ ሲኾን በመጣላቸው ጊዜ የካዱት (ጠፊዎች ናቸው)፡፡'),
('41:42', 87, 'ከኋላውም ከፊቱም ውሸት አይመጣበትም፡፡ ጥበበኛ ምስጉን ከኾነው ጌታ የተወረደ ው፡፡'),
('41:43', 87, 'ካንተ በፊት ለነበሩት መልክተኞች የተባለው ብጤ እንጅ ለአንተ ሌላ አይባልም፡፡ ጌታህ የምህረት ባለቤትና የአሳማሚ ቅጣት ባለቤት ነው፡፡'),
('41:44', 87, 'በአጀምኛ የኾነ ቁርኣን ባደረግነው ኖሮ አንቀጾቹ «(በምናውቀው ቋንቋ) አይብራሩም ኖሯልን? (ቁርኣኑ) አጀምኛና (መልክተኛው) ዐረባዊ ይኾናልን?» ባሉ ነበር እርሱ ለእነዚያ ለአመኑት መምሪያና መፈወሻ ነው፡፡ እነዚያም የማያምኑት በጆሮዎቻቸው ውስጥ ድንቁርና ነው፡፡ (አይሰሙትም)፡፡ እነርሱም በእነርሱ ላይ እውርነት ነው፡፡ እነዚያ ከሩቅ ስፍራ እንደሚጥጠሩ ናቸው፡፡'),
('41:45', 87, 'ሙሳንም መጽሐፉን በእርግጥ ሰጠነው፡፡ በእርሱም ተለያዩበት፡፡ ከጌታህም ያለፈች ቃል ባልነበረች ኖሮ በመካከላቸው በተፈረደ ነበር፡፡ እነርሱም ከእርሱ አወላዋይ በኾነ ጥርጣሬ ውስጥ ናቸው፡፡'),
('41:46', 87, 'መልካም የሠራ ሰው ለነፍሱ ነው፡፡ ያጠፋም ሰው በእርሷ ላይ ነው፡፡ ጌታህም ለባሮቹ በዳይ አይደለም፡፡'),
('41:47', 87, 'ጊዜይቱን ማወቅ ወደእርሱ ይመለሳል ከፍሬዎችም ከሽፋኖቻቸው አይወጡም፡፡ ከሴትም አንዲትም አታረግዝም፣ አትወልድምም በዕውቀቱ ቢኾን እንጅ፡፡ «ተጋሪዎቼ የት ናቸው?» በማለት በሚጠራቸው ቀንም «ከእኛ ውስጥ (ባላንጣ አልለ ብሎ) ምንም መስካሪ አለመኖሩን አስታወቅንህ» ይላሉ፡፡'),
('41:48', 87, 'ያም በፊት ይግገዙት የነበሩት (ጣዖት) ከእነርሱ ይጠፋቸዋል፡፡ ለእነርሱም ምንም መሸሻ የሌላቸው መኾኑን ያረጋግጣሉ፡፡'),
('41:49', 87, 'ሰው በጎ ነገርን ከመለመን አይሰለችም፡፡ ክፉም ቢያገኘው ወዲያውኑ በጣም ተስፋ ቆራጭ ተበሳጭ ይኾናል፡፡'),
('41:50', 87, 'ካገኘችውም መከራ በኋላ ከእኛ የኾነን እዝነት ብናቀምሰው «ይህ ለእኔ (በሥራዬ የተገባኝ)'),
('41:51', 87, 'በሰውም ላይ ጸጋችንን በለገስን ጊዜ (ከማመስገን) ይዞራል፡፡ በጎኑም ይርቃል፡፡ መከራም ባገኘው ጊዜ የብዙ ልመና ባለቤት ይኾናል፡፡'),
('41:52', 87, 'በላቸው «ንገሩኝ (ቁርኣኑ) ከአላህ ዘንድ ቢኾን ከዚያም በእርሱ ብትክዱ (ከውነት) በራቀ ጭቅጭቅ ላይ ከኾነ ሰው ይበልጥ የተሳሳተ ማን ነው?»'),
('41:53', 87, 'እርሱም (ቁርኣን) እውነት መኾኑ ለእነርሱ እስከሚገለፅላቸው ድረስ በአጽናፎቹ ውስጥና በነፍሶቻቸውም ውስጥ ያሉትን ተዓምራቶቻችንን በእርግጥ እናሳያቸዋለን፡፡ ጌታህም እርሱ በነገሩ ሁሉ ላይ ዐዋቂ መኾኑ አይበቃቸውምን?'),
('41:54', 87, 'ንቁ! እነርሱ ከጌታቸው መገናኘት በመጠራጠር ውስጥ ናቸው፡፡ ንቁ! እርሱ በነገሩ ሁሉ (ዕውቀቱ) ከባቢ ነው፡፡'),
('42:1', 87, 'ሐ.መ (ሐ፡ ሚም)፡፡'),
('42:2', 87, 'ዐ.ሰ.ቀ (ዓይን ሲን ቃፍ)፤'),
('42:3', 87, 'እንደዚሁ (በዚህች ሱራ ውስጥ እንዳለው) አሸናፊው ጥበበኛው አላህ ወዳንተ ያወርዳል፡፡ ወደእነዚያም ከአንተ በፊት ወደ ነበሩት ሕዝቦች (አውርዷል)፡፡'),
('42:4', 87, 'በሰማያትና በምድር ያለው ሁሉ የእርሱ ነው፡፡ እርሱም የበላዩ ታላቁ ነው፡፡'),
('42:5', 87, '(ከአላህ ፍራቻ) ሰማያት ከበላያቸው ሊቀደዱ ይቀርባሉ፡፡ መላእክትም ጌታቸውን እያመሰገኑ ያወድሳሉ፡፡ በምድርም ላለው ፍጡር ምሕረትን ይለምናሉ፡፡ ንቁ! አላህ እርሱ መሓሪው አዛኙ ነው፡፡'),
('42:6', 87, 'እነዚያም ከእርሱ ሌላ (የጣዖታት) ረዳቶችን የያዙ፤ አላህ በእነርሱ ላይ ተጠባባቂ ነው፡፡ አንተም በእነርሱ ላይ ኀላፊ አይደለህም፡፡'),
('42:7', 87, 'እንደዚሁም የከተሞች እናት የኾነችውን (የመካን ሰዎች) በአካባቢዋ ያሉትንም ልታስፈራራ የመሰብሰቢያውንም ቀን በእርሱ ጥርጣሬ የሌለበት ሲኾን ልታስጠነቅቅ ዐረብኛ የኾነን ቁርኣን ወደ አንተ አወረድን፡፡ (ከእነርሱም) ከፊሉ በገነት ውሰጥ ከፊሉም በእሳት ውስጥ ነው፡፡'),
('42:8', 87, 'አላህም በሻ ኖሮ (ባንድ ሃይማኖት ላይ) አንድ ሕዝብ ባደረጋቸው ነበር፡፡ ግን የሚሻውን ሰው በእዝነቱ ውስጥ ያስገባል፡፡ በዳዮችም ለእነርሱ ወዳጅና ረዳት ምንም የላቸውም፡፡'),
('42:9', 87, 'ከእርሱ ሌላ ረዳቶችን ያዙን? (ረዳቶች አይደሉም)፡፡ አላህም ረዳት እርሱ ብቻ ነው፡፡ እርሱም ሙታንን ሕያው ያደርጋል፡፡ እርሱም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('42:10', 87, 'ከምንም ነገር ያ በእርሱ የተለያዩበት ፍርዱ ወደ አላህ ነው፡፡ «እርሱ አላህ ጌታዬ ነው፡፡ በእርሱ ላይ ተጠጋሁ፣ ወደርሱም እመለሳለሁ» (በላቸው)፡፡'),
('42:11', 87, 'ሰማያትንና ምድርን ፈጣሪ ነው፡፡ ከነፍሶቻችሁ ሴቶችን ከቤት እንስሳዎችም ዓይነቶችን (ወንዶችና ሴቶችን) ለእናንተ አደረገላችሁ፡፡ በእርሱ ያበዛችኋል፡፡ የሚመስለው ምንም ነገር የለም፡፡ እርሱም ሰሚው ተመልካቹ ነው፡፡'),
('42:12', 87, 'የሰማያትና የምድር (ድልቦች) መከፈቻዎች የእርሱ ናቸው፡፡ ሲሳይን ለሚሻው ሰው ያሰፋል፤ ያጠባልም፡፡ እርሱ ነገሩን ሁሉ ዐዋቂ ነውና፡፡'),
('42:13', 87, 'ለእናንተ ከሃይማኖት ያንን በእርሱ ኑሕን ያዘዘበትን ደነገገላችሁ፡፡ ያንንም ወዳንተ ያወረድነውን ያንንም በእርሱ ኢብራሂምን ሙሳንና ዒሳንም ያዘዝንበትን ሃይማኖትን በትክክል አቋቁሙ በእርሱም አትለያዩ ማለትን (ደነገግን)፡፡ በአጋሪዎቹ ላይ ያ ወደርሱ የምትጠራቸው ነገር ከበዳቸው፡፡ አላህ የሚሻውን ሰው ወደእርሱ (እምነት) ይመርጣል፡፡ የሚመለስንም ሰው ወደርሱ ይመራል፡፡'),
('42:14', 87, '(የሃይማኖት ሰዎች) ዕውቀቱም ከመጣላቸው በኋላ በመካከላቸው ለምቀኝነት እንጅ ለሌላ አልተለያዩም፡፡ እስከ ተወሰነም ጊዜ (በማቆየት) ከጌታህ ያለፈች ቃል ባልነበረች ኖሮ በእነርሱ መካከል (አሁን) በተፈረደ ነበር፡፡ እነዚያም ከኋላቸው መጽሐፉን እንዲወርሱ የተደረጉት ከእርሱ በእርግጥ በአወላዋይ ጥርጣሬ ውስጥ ናቸው፡፡'),
('42:15', 87, 'ለዚህም (ድንጋጌ ሰዎችን) ጥራ፡፡ እንደታዘዝከውም ቀጥ በል፡፡ ዝንባሌዎቻቸውንም አትከተል፡፡ «በላቸውም ከመጽሐፍ አላህ ባወረደው ሁሉ አመንኩ፡፡ በመካከላችሁም ላስተካክል ታዘዝኩ፡፡ አላህ ጌታችን ጌታችሁም ነው፡፡ ለእኛ ሥራዎቻችን አልሉን፡፡ ለእናንተም ሥራዎቻችሁ አልሏችሁ፡፡ በእኛና በእናንተ መካከል ክርክር የለም፡፡ አላህ በመካከላችን ይሰበስባል፡፡ መመለሻም ወደእርሱ ብቻ ነው፡፡»'),
('42:16', 87, 'እነዚያም በአላህ (ሃይማኖት) ለእርሱ ተቀባይ ካገኘ በኋላ የሚከራከሩት ማስረጃቸው በጌታቸው ዘንድ ብልሹ ናት፡፡ በእነርሱም ላይ ቁጣ አልለባቸው፡፡ ለእነርሱም ብርቱ ቅጣት አልላቸው፡፡'),
('42:17', 87, 'አላህ ያ መጽሐፉን በእውነት ያወረደ ነው፡፡ ሚዛንንም (እንደዚሁ)፡፡ ሰዓቲቱ ምንአልባት ቅርብ መኾንዋን ምን ያሳውቅሃል?'),
('42:18', 87, 'እነዚያ በእርሷ የማያምኑት በእርሷ ያቻኩላሉ፡፡ እነዚያም ያመኑት ከእርሷ ፈሪዎች ናቸው፡፡ እርሷም እውነት መኾንዋን ያውቃሉ፡፡ ንቁ! እነዚያ በሰዓቲቱ የሚከራከሩት በእርግጥ (ከእውነት) በራቀ ስሕተት ውስጥ ናቸው፡፡'),
('42:19', 87, 'አላህ በባሮቹ ሩህሩህ ነው፡፡ ለሚሻው ሰው (በሰፊው) ሲሳይን ይሰጣል፡፡ እርሱም ብርቱው አሸናፊው ነው፡፡'),
('42:20', 87, '(በሥራው) የኋለኛይቱን ዓለም አዝመራ የሚፈልግ የኾነ ሰው ለእርሱ በአዝመራው ላይ እንጨምርለታለን፡፡ የቅርቢቱንም ዓለም አዝመራ የሚፈልግ የኾነ ሰው ከእርሷ (የተወሰነለትን ብቻ) እንሰጠዋለን፡፡ ለእርሱም በኋለኛይቱ ዓለም ምንም ፋንታ የለውም፡፡'),
('42:21', 87, 'ከሃይማኖት አላህ በእርሱ ያልፈቀደውን ለእነርሱ የደነገጉ ተጋሪዎች ለእነርሱ አልሏቸውን? የፍርዱ ቃል ባልነበረ ኖሮ በመካከላቸው (አሁን) በተፈረደ ነበር፡፡ በደለኞችም ለእነርሱ አሳማሚ ቅጣት በእርግጥ አልላቸው፡፡'),
('42:22', 87, 'በደለኞችን ከሠሩት ሥራ (ዋጋ በትንሣኤ ቀን) ፈሪዎች ኾነው ታያቸዋለህ፡፡ እርሱም በእነርሱ ላይ ወዳቂ ነው፡፡ እነዚያም ያመኑት መልካሞችንም የሠሩት በገነቶች ጨፌዎች ውስጥ ናቸው፡፡ ለእነርሱ በጌታቸው ዘንድ የሚሹት ሁሉ አልላቸው፡፡ ይህ እርሱ ታላቅ ችሮታ ነው፡፡'),
('42:23', 87, 'ይህ (ታላቅ ችሮታ) ያ አላህ እነዚያን ያመኑትንና መልካሞችን የሠሩትን ባሮቹን የሚያበስርበት ነው፡፡ «በእርሱ (መልክቴን በማድረሴ) ላይ በዝምድና ውዴታን እንጅ ዋጋን አልጠይቃችሁም» በላቸው፡፡ መልካሚቱንም ሥራ የሚሠራ ሰው ለእርሱ በእርሷ መልካምን ነገር እንጨምርለታለን፡፡ አላህ መሓሪ አመስጋኝ ነውና፡፡'),
('42:24', 87, 'ይልቁንም «በአላህ ላይ ውሸትን ቀጠፈ» ይላሉን? አላህም ቢሻ በልብህ ላይ ያትማል፡፡ አላህም ውሸቱን ያብብሳል፡፡ እውነቱንም በቃላቱ ያረጋግጣል፡፡ እርሱ በልቦች ውስጥ ያለን ሁሉ ዐዋቂ ነውና፡፡'),
('42:25', 87, 'እርሱም ያ ከባሮቹ ንስሓን የሚቀበል፣ ከኃጢአቶችም ይቅር የሚል፣ የምትሠሩትንም ሁሉ የሚያውቅ ነው፡፡'),
('42:26', 87, 'እነዚያንም ያመኑትንና መልካሞችን የሠሩትን ልመናቸውን ይቀበላል፡፡ ከችሮታውም ይጨምርላቸዋል፡፡ ከሓዲዎቹም ለእነርሱ ብርቱ ቅጣት አልላቸው፡፡'),
('42:27', 87, 'አላህም ለባሮቹ (ሁሉ) ሲሳይን በዘረጋ ኖሮ በምድር ውስጥ (ሁሉም) ወሰን ባለፉ ነበር፡፡ ግን የሚሻውን በልክ ያወርዳል፡፡ እርሱ በባሮቹ ውስጥ ዐዋቂ ተመልካች ነውና፡፡'),
('42:28', 87, 'እርሱም ያ ተስፋ ከቆረጡ በኋላ ዝናምን የሚያወርድ ችሮታውንም የሚዘረጋ ነው፡፡ እርሱም ረዳቱ ምስጉኑ ነው፡፡'),
('42:29', 87, 'ሰማያትንና ምድርንም መፍጠሩ፣ ከተንቀሳቃሽም በሁለቱ ውስጥ የበተነውን (መፍጠሩ) ከአስደናቂ ምልክቶቹ ነው፡፡ እርሱም በሚሻ ጊዜ እነርሱን በመሰብሰብ ላይ ቻይ ነው፡፡'),
('42:30', 87, 'ከመከራም ማንኛውም ያገኛችሁ ነገር እጆቻችሁ በሠሩት (ኃጢኣት) ምክንያት ነው፡፡ ከብዙውም ይቅር ይላል፡፡'),
('42:31', 87, 'እናንተም በምድር ውስጥ የምታቅቱ አይደላችሁም፡፡ ለእናንተም ከአላህ ሌላ ከዘመድም ከረዳትም ምንም የላችሁም፡፡'),
('42:32', 87, 'በባሕር ላይ እንደ ጋራዎች ኾነው ተንሻላዮቹም (መርከቦች) ከአስደናቂ ምልክቶቹ ናቸው፡፡'),
('42:33', 87, 'ቢሻ ነፋሱን የረጋ ያደርገዋል፡፡ በባሕሩም ጀርባ ላይ ረጊዎች ይኾናሉ፡፡ በዚህ ውሰጥ በጣም ታጋሽና አመስጋኝ ለኾነ ሁሉ በእርግጥ ምልክቶች አልሉ፡፡'),
('42:34', 87, 'ወይም በሠሩት ኃጢኣት ምክንያት (በማስጠም) ያጠፋቸዋል፡፡ ከብዙም ይቅርታ ያደርጋል፡፡'),
('42:35', 87, '(ከእነርሱ ለመበቀል)፤ እነዚያንም በአንቀጾቻችን የሚከራከሩትን ለማወቅ (ያጠፋቸዋል)፡፡ ለእነርሱ ምንም መሸሻ የላቸውም፡፡'),
('42:36', 87, 'ከምንም ነገር የተሰጣችሁት የቅርቢቱ ሕይወት መጠቀሚያ ነው፡፡ አላህ ዘንድ ያለውም ምንዳ ለእነዚያ ለአመኑትና በጌታቸው ላይ ለሚጠጉት በላጭና ሁል ጊዜ ነዋሪ ነው፡፡'),
('42:37', 87, 'ለእነዚያም የኀጢኣትን ታላላቆችና ጠያፎችን የሚርቁ በተቆጡም ጊዜ እነሱ የሚምሩት ለኾኑት፡፡'),
('42:38', 87, 'ለእነዚያም የጌታቸውን ጥሪ ለተቀበሉት፣ ሶላትንም ላዘወተሩት፣ ነገራቸውም በመካከላቸው መመካከር ለኾነው ከሰጠናቸውም ሲሳይ ለሚለግሱት፡፡'),
('42:39', 87, 'ለእነዚያም በደል በደረሰባቸው ጊዜ እነርሱ (በመሰሉ) የሚመልሱ ለኾኑት (በላጭና ኗሪ ነው)፡፡'),
('42:40', 87, 'የመጥፎም ነገረ ዋጋ ብጤዋ መጥፎ ናት፡፡ ይቅርም ያለና ያሳመረ ሰው ምንዳው በአላህ ላይ ነው፡፡ እርሱ በደለኞችን አይወድም፡፡'),
('42:41', 87, 'ከተበደሉም በኋላ (በመሰሉ) የተበቀሉ እነዚያ በነርሱ ላይ ምንም (የወቀሳ) መንገድ የለባቸውም፡፡'),
('42:42', 87, '(የወቀሳ) መንገዱ በእነዚያ ሰዎችን በሚበድሉት፣ በምድርም ውስጥ ያለ ሕግ ወሰን በሚያልፉት፣ ላይ ብቻ ነው፡፡ እነዚያ ለእነርሱ አሳማሚ ቅጣት አልላቸው፡፡'),
('42:43', 87, 'የታገስና ምሕረት ያደረገም ሰው ይህ ከምርሮቹ (ከተፈላጊዎቹ) ነገሮች ነው፡፡'),
('42:44', 87, 'አላህ የሚያጠመውም ሰው ከእርሱ በኋለ ለእርሱ ምንም ረዳት የለውም፡፡ በደለኞችንም ቅጣቱን ባዩ ጊዜ ወደ መመለስ መንገድ አልለን? የሚሉ ሲኾኑ ታያቸዋለህ፡፡'),
('42:45', 87, 'ከውርደት የተነሳ ፈሪዎች ኾነው በዓይን ስርቆት ወደእርሷ (ወደ እሳት) እያስተዋሉ በእርሷ ላይ የሚቀረቡ ሲኾኑ ታያቸዋለህ፡፡ እነዚያም ያመኑት፡- «በእርግጥ ከሳሪዎቹ እነዚያ ነፍሶቻቸውንና ቤተሰቦቻቸውን በትንሣኤ ቀን ያከሰሩት ናቸው» ይላሉ፡፡'),
('42:46', 87, 'ንቁ! በደለኞች በእርግጥ በዘውታሪ ስቃይ ውስጥ ናቸው፡፡ ለእነርሱም ከአላህ ሌላ የሚረዷቸው ዘመዶች ምንም አልነበሩዋቸውም፡፡ አላህም የሚያጠመው ሰው ለእርሱ (ወደ እውነት) ምንም መንገድ የለውም፡፡'),
('42:47', 87, 'ለእርሱ መመለስ የሌለው ቀን ከአላህ ከመምጣቱ በፊት ለጌታችሁ ታዘዙ፡፡ በዚያ ቀን ለእናንተ ምንም መጠጊያ የላችሁም፡፡ ለእናንተም ምንም መካድ የላችሁም፡፡'),
('42:48', 87, 'ቢዞሩም (ወቀሳ የለብህም)፡፡ በእነርሱ ላይ ጠባቂ አድርገን አልላክንህምና፡፡ ባንተ ላይ ማድረስ እንጅ ሌላ የለብህም፡፡ እኛም ሰውን ከእኛ የኾነን ጸጋ ባቀመስነው ጊዜ በርሷ ይደሰታል፡፡ እጆቻቸው ባስቀደሙትም ኀጢአት ምክንያት መከራ ብትደርስባቸው (ተስፋ ይቆርጣሉ)፡፡ ሰው (ውለታን) በጣም ከሐዲ ነውና፡፡'),
('42:49', 87, 'የሰማያትና የምድር ንግሥና የአላህ ነው፡፡ የሚሻውን ይፈጥራል፡፡ ለሚሻው ሰው ሴቶችን (ልጆች) ይሰጣል፡፡ ለሚሻውም ሰው ወንዶችን ይሰጣል፡፡'),
('42:50', 87, 'ወይም ወንዶችና ሴቶች አድርጎ ያጠናዳቸዋል፡፡ የሚሻውንም ሰው መካን ያደርገዋል፡፡ እርሱ ዐዋቂ ቻይ ነውና፡፡'),
('42:51', 87, 'ለሰውም አላህ በራእይ፣ ወይም ከግርዶ ወዲያ፣ ወይም መልክተኛን (መልአክን) የሚልክና በፈቃዱ የሚሻውን ነገር የሚያወርድለት ቢኾን እንጅ (በገሃድ) ሊያናግረው ተገቢው አይደለም፡፡ እርሱ የበላይ ጥበበኛ ነውና፡፡'),
('42:52', 87, 'እንደዚሁም ወደ አንተ ከትእዛዛችን ሲኾን መንፈስን (ቁርኣንን) አወረድን፡፡ መጽሐፉም እምነቱም ምን እንደኾነ የምታውቅ አልነበርክም፡፡ ግን (መንፈሱን) ከባሮቻችን የምንሻውን ሰው በእርሱ የምንመራበት ብርሃን አደረግነው፡፡ አንተም ወደ ቀጥተኛው መንገድ በእርግጥ ትመራለህ፡፡'),
('42:53', 87, 'ወደዚያ በሰማያትና በምድር ያለው ሁሉ የእርሱ ወደ ኾነው አላህ መንገድ (ትመራለህ)፡፡ ንቁ! ነገሮቹ ሁሉ ወደ አላህ ይመለሳሉ፡፡'),
('43:1', 87, 'ሐ.መ (ሓ ሚም)፡፡'),
('43:2', 87, 'ገላጭ በኾነው መጽሐፍ እምላለሁ፡፡'),
('43:3', 87, 'እኛ ታውቁ ዘንድ ዐረብኛ ቁርኣን አደረግነው፡፡'),
('43:4', 87, 'እርሱም በመጽሐፎቹ እናት ውስጥ እኛ ዘንድ በእርግጥ ከፍተኛ ጥበብ የተመላ ነው፡፡'),
('43:5', 87, 'ድንበር አላፊዎች ሕዝቦች ለመኾናችሁ ቁርኣኑን ከእናንተ ማገድን እናግዳለን?'),
('43:6', 87, 'በፊተኞቹም ሕዝቦች ውስጥ ከነቢይ ብዙን ልከናል፡፡'),
('43:7', 87, 'ከነቢይም አንድም የሚመጣላቸው አልነበረም በእርሱ ይሳለቁበት የነበሩ ቢኾኑ እንጅ፡፡'),
('43:8', 87, 'ከእነርሱም በኀይል ይበልጥ የበረቱትን አጥፍተናል፡፡ የፊተኞቹም (አጠፋፍ) ምሳሌ አልፏል፡፡'),
('43:9', 87, '«ሰማያትንና ምድርንም ማን ፈጠራቸው» ብለህ ብትጠይቃቸው «አሸናፊው ዐዋቂው (አላህ) በእርግጥ ፈጠራቸው» ይላሉ፡፡'),
('43:10', 87, '(እርሱ) ያ ምድርን ለእናንተ ምንጣፍ ያደረገላችሁ በርሷም ውስጥ ትምመሩ ዘንድ ለእናንተ መንገዶችን ያደረገላችሁ ነው፡፡'),
('43:11', 87, 'ያም ከሰማያ ውሃን በልክ ያወረደላችሁ ነው፡፡ በእርሱም የሞተችውን አገር ሕያው አደረግን፡፡ እንደዚሁ (ከመቃብራችሁ) ትውወጣላችሁ፡፡'),
('43:12', 87, 'ያም ዓይነቶችን ሁሉ የፈጠረ ለእናንተም ከመርከቦችና ከቤት እንስሳዎች የምትጋልቧቸውን ያደረገላችሁ ነው፡፡'),
('43:13', 87, 'በጀርባዎቹ ላይ እንድትደላደሉ ከዚያም በርሱ ላይ የተደላደላችሁ ጊዜ የጌታችሁን ጸጋ እንድታስታውሱ፤ እንድትሉም፡- «ያ ይህንን የማንችለው ስንኾን ለእኛ ያገራለን ጌታ ጥራት ይገባው፡፡'),
('43:14', 87, 'እኛም በእርግጥ ወደ ጌታችን ተመላሾች፤ነን» (እንድትሉ)፡፡'),
('43:15', 87, 'ከባሮቹም ለእርሱ ቁራጭን (ልጅን) አደረጉለት፡፡ ሰው በእርግጥ ግልጽ ከሓዲ ነው፡፡'),
('43:16', 87, 'ከሚፈጥረው ውስጥ ሴቶች ልጆችን ያዘን? በወንዶች ልጆችም (እናንተን) መረጣችሁን?'),
('43:17', 87, 'አንዳቸውም ለአልረሕማን ምሳሌ ባደረገው ነገር (በሴት ልጅ) በተበሰረ ጊዜ እርሱ በቁጭት የተመላ ኾኖ ፊቱ የጠቆረ ይኾናል፡፡'),
('43:18', 87, 'በጌጥ (ተከልሶ) እንዲያድግ የሚደረገውን? እርሱም (ለደካማነቱ) በክርክር የሚያብራራውን ፍጡር (ሴትን) ለአላህ ያደርጋሉን?'),
('43:19', 87, 'መላእክትንም እነርሱ የአልረሕማን ባሮች የኾኑትን ሴቶች አደረጉ፡፡ ሲፈጠሩ ነበሩን? መመስከራቸው በእርግጥ ትጻፋለች፡፡ ይጠየቃሉም፡፡'),
('43:20', 87, '«አልረሕማንም በሻ ኖሮ ባልተገዛናቸው ነበር» አሉ፡፡ ለእነርሱ በዚህ ምንም ዕውቀት የላቸውም፡፡ እነርሱ የሚዋሹ እንጅ ሌላ አይደሉም፡፡'),
('43:21', 87, 'ከእርሱ (ከቁርኣን) በፊት መጽሐፍን ሰጠናቸውን? ስለዚህ እነርሱ እርሱን የጨበጡ ናቸውን?'),
('43:22', 87, 'ከቶውንም «እኛ አባቶቻችንን በሃይማኖት ላይ አገኘናቸው፡፡ እኛም በፈለጎቻቸው ላይ ተመሪዎች ነን» አሉ፡፡'),
('43:23', 87, '(ነገሩ) እንደዚሁም ነው፡፡ ከበፊትህ በማንኛይቱም ከተማ ውስጥ አስፈራሪን አልላክንም፤ ቅምጥሎችዋ እኛ አባቶቻችንን በሃይማኖት ላይ አገኘን፤ እኛም በፈለጎቻቸው ላይ ተከታዮች ነን ያሉ ቢኾኑ እንጅ፡፡'),
('43:24', 87, '(አስፈራሪው) «አባቶቻችሁን በእርሱ ላይ ከአገኛችሁበት ይበልጥ ቀጥተኛን (ሃይማኖት) ባመጣላችሁም?» አላቸው፡፡ «እኛ በእርሱ በተላካችሁበት ነገር ከሓዲዎች ነን» አሉ፡፡'),
('43:25', 87, 'ከእነርሱም ተበቀልን፡፡ ያስተባባዮቹም መጨረሻ እንዴት እንደ ነበረ ተመልከት፡፡'),
('43:26', 87, 'ኢብራሂምም ለአባቱና ለሕዝቦቹ ባለ ጊዜ (አስታውስ)፡፡ «እኔ ከምትግገዙት ሁሉ ንጹሕ ነኝ፡፡»'),
('43:27', 87, '«ከዚያ ከፈጠረኝ በስተቀር (አልግገዛም)፡፡ እርሱ በእርግጥ ይመራኛልና፡፡»'),
('43:28', 87, 'በዝርዮቹም ውስጥ ይመለሱ ዘንድ (ባንድ አምላክ ማመንን) ቀሪ ቃል አደረጋት፡፡'),
('43:29', 87, 'ይልቅ እነዚህን (ቁረይሾችን)፣ አባቶቻቸውንም ቁርኣንና ገላጭ መልክተኛ እስከመጣላቸው ድረስ አጣቀምኳቸው፡፡'),
('43:30', 87, 'እውነቱም በመጣላቸው ጊዜ «ይህ ድግምት ነው፡፡ እኛም በእርሱ ከሓዲዎች ነን» አሉ፡፡'),
('43:31', 87, '«ይህም ቁርኣን ከሁለቱ ከተሞች በታላቅ ሰው ላይ አይወረድም ኖሯልን?» አሉ፡፡'),
('43:32', 87, 'እነርሱ የጌታህን ችሮታ ያከፈፍላሉን? እኛ በቅርቢቱ ሕይወት ኑሯቸውን በመካከላቸው አከፋፍለናል፡፡ ከፊላቸውም ከፊሉን ሠራተኛ አድርጎ ይይዝ ዘንድ ከፊላቸውን ከከፊሉ በላይ በደረጃዎች (በሀብት) አበለጥን፡፡ የጌታህም ጸጋ (ገነት) ከሚሰበስቡት (ሃብት) በላጨ ናት፡፡'),
('43:33', 87, 'ሰዎችም (በክሕደት) አንድ ሕዝብ የሚኾኑ ባልነበሩ ኖሮ በአልረሕማን ፤ለሚክዱት ሰዎች (በዚህች ዓለም) ለቤቶቻቸው ከብር የኾኑን ጣራዎች በእነርሱ ላይ የሚወጡባቸውንም (የብር) መሰላሎች ባደረግንላቸው ነበር፡፡'),
('43:34', 87, 'ለቤቶቻቸውም ደጃፎችን በእነርሱ ላይ የሚደገፉባቸውንም አልጋዎች (ከብር ባደረግንላቸው ነበር)፡፡'),
('43:35', 87, 'የወርቅ ጌጥንም (ባደረግንላቸው ነበር)፡፡ ይህም ሁሉ የቅርቢቱ ሕይወት መጣቀሚያ እንጅ ሌላ አይደለም፤ (ጠፊ ነው)፡፡ መጨረሻይቱም አገር በጌታህ ዘንድ ለጥንቁቆቹ ናት፡፡'),
('43:36', 87, 'ከአልረሕማን ግሣጼ (ከቁርኣን) የሚደናበርም ሰው ለእርሱ ሰይጣንን እናስጠጋለን፡፡ ስለዚህ እርሱ ለእርሱ ቁራኛ ነው፡፡'),
('43:37', 87, 'እነርሱም (ተደናባሪዎቹ) ተመሪዎች መኾናቸውን የሚያስቡ ሲኾኑ እነርሱ (ሰይጣናት) ከቀጥተኛው መንገድ በእርግጥ ያግዷቸዋል፡፡'),
('43:38', 87, '(በትንሣኤ) ወደኛ በመጣም ጊዜ (ቁራኛዬ ሆይ!) «በእኔና ባንተ መካከል የምሥራቅና የምዕራብ ርቀት በኖረ ወይ ምኞቴ! ምን የከፋህ ቁራኛ ነህ» ይላል፡፡'),
('43:39', 87, 'ስለ በደላችሁም ዛሬ እናንተ በቅጣት ተጋሪዎች መኾናችሁ አይጠቅማችሁም፤ (ይባላሉ)፡፡'),
('43:40', 87, 'አንተ ደንቆሮዎችን ታሰማለህን? ወይስ ዕውሮችንና በግልጽ ጥመት ውስጥ የኾኑን ሰዎች ትመራለህን?'),
('43:41', 87, 'አንተንም (ቅጣታቸውን ስታይ) ብንወስድህ እኛ ከእነርሱ ተበቃዮች ነን፡፡'),
('43:42', 87, 'ወይም ያንን የቀጠርናቸውን ብናሳይህ እኛ በእነርሱ (ቅጣት) ላይ ቻይዎች ነን፡፡'),
('43:43', 87, 'ያንንም ወደ አንተ የተወረደልህን አጥብቀህ ያዝ፡፡ አንተ በቀጥተኛው መንገድ ላይ ነህና፡፡'),
('43:44', 87, 'እርሱም (ቁርኣን) ለአንተ፣ ለሕዘቦችህም ታላቅ ክብር ነው፡፡ ወደ ፊትም (ከርሱ) ትጠየቃላችሁ፡፡'),
('43:45', 87, 'ከመልእክተኞቻችንም ካንተ በፊት የላክናቸውን (ተከታዮቻቸውን) ከአልረሕማን ሌላ የሚገዙዋቸው የኾኑን አማልክት አድርገን እንደ ኾነ ጠይቃቸው፡፡'),
('43:46', 87, 'ሙሳንም በተዓምራቶቻችን ወደ ፈርዖንና ወደ ሹማምንቶቹ በእርግጥ ላክን፡፡ «እኔ የዓለማት ጌታ መልክተኛ ነኝ» አላቸውም፡፡'),
('43:47', 87, 'በተዓምራታችንም በመጣባቸው ጊዜ ወዲያውኑ እነርሱ በእርሷ ይስቃሉ፡፡'),
('43:48', 87, 'ከተዓምርም አንዲትንም አናሳያቸውም እርሷ ከብጤዋ በጣም የበለጠች ብትኾን እንጅ፡፡ (ከክህደታቸው) ይመለሱም ዘንድ በቅጣት ያዝናቸው፡፡'),
('43:49', 87, '«አንተ ድግምተኛ (ዐዋቂ) ሆይ! ጌታህን አንተ ዘንድ ቃል በገባልህ ለእኛ ለምንልን፡፡ እኛ (ቅጣቱን ቢያነሳልን) ተመሪዎች ነን» አሉም፡፡'),
('43:50', 87, 'ስቃዩን ከእነርሱ ላይ በገለጥንም ጊዜ ወዲያውኑ ኪዳናቸውን ያፈርሳሉ፡፡'),
('43:51', 87, 'ፈርዖንም በሕዝቦቹ ውስጥ ተጣራ፡፡ አለም፤ «ሕዝቦቼ ሆይ! የምስር ግዛት የኔ አይደለምን? እነዚህም ጅረቶች ከስሬ የሚፈሱ ሲኾኑ (የኔ አይደሉምን?) አትመለከቱምን?'),
('43:52', 87, '«በውነቱ እኔ ከዚህ ያ እርሱ ወራዳ ንግግሩንም ሊገልጽ የማይቀርብ ከኾነው በላጭ ነኝ፡፡'),
('43:53', 87, '«በእርሱም ላይ የወርቅ አንባሮች ለምን አልተጣሉበትም ወይም መላእክት ከእርሱ ጋር ተቆራኝተው ለምን አልመጡም» (አለ)፡፡'),
('43:54', 87, 'ሕዝቦቹንም አቄላቸው፡፡ ታዘዙትም፡፡ እነርሱ አመጸኞች ሕዝቦች ነበሩና፡፡'),
('43:55', 87, 'ባስቆጡንም ጊዜ ከእነርሱ በተበቀለን፡፡ ሁሉንም አሰጠምናቸውም፡፡'),
('43:56', 87, '(በጥፋት) ቀዳሚዎችና ለኋለኞቹ (መቀጣጫ) ምሳሌም አደረግናቸው፡፡'),
('43:57', 87, 'የመርየም ልጅም ምሳሌ በተደረገ ጊዜ ሕዝቦችህ (ከሓዲዎቹ) ወዲያውኑ ከእርሱ ይስቃሉ፡፡'),
('43:58', 87, '«አማልክቶቻችን ይበልጣሉን ወይስ እርሱ?» አሉም፡፡ ለክርክርም እንጅ ላንተ እርሱን ምሳሌ አላደረጉትም፡፡ በእውነት እነርሱ ክርክረ ብርቱ ሕዝቦች ናቸው፡፡'),
('43:59', 87, 'እርሱ በርሱ ላይ የለገስንለት ለእስራኤለም ልጆች ተዓምር ያደረግነው የኾነ ባሪያ እንጅ ሌላ አይደለም፡፡'),
('43:60', 87, 'ብንሻም ኖሮ በምድር ላይ ከእናነተ ምትክ መላእክትን ባደረግን ነበር፡፡'),
('43:61', 87, 'እርሱም (ዒሳ) ለሰዓቲቱ (ማወቂያ) በእርግጥ ምልክት ነው፡፡ «በእርሷም አትጠራጠሩ፡፡ ተከተሉኝም፤ ይህ ቀጥተኛ መንገድ ነው» (በላቸው)፡፡'),
('43:62', 87, 'ሰይጣንም አያግዳችሁ፡፡ እርሱ ለእናንተ ግልጽ ጠላት ነውና፡፡'),
('43:63', 87, 'ዒሳ በታምራቶች በመጣ ጊዜም አላቸው «በእርግጥ በጥበብ መጣኋችሁ፡፡ የዚያንም በርሱ የምትለያዩበትን ከፊሉን ለናንተ ላብራራላችሁ (መጣሁ)፡፡ አላህንም ፍሩ፡፡ ታዘዙኝም፡፡'),
('43:64', 87, '«አላህ ጌታዬ ጌታችሁም ነውና ተገዙት፡፡ ይህ ቀጥተኛ መንገድ ነው፡፡»'),
('43:65', 87, 'ከመካከላቸውም አሕዛቦቹ ተለያዩ፡፡ ለእነዚያም ለበደሉት ከአሳማሚ ቀን ቅጣት ወዮላቸው፡፡'),
('43:66', 87, 'ሰዓቲቱን እነርሱ የማያውቁ ኾነው በድንገት ልትመጣባቸው እንጅ ይጠባበቃሉን?'),
('43:67', 87, 'ወዳጆች በዚያ ቀን ከፊላቸው ለከፊሉ ጠላት ነው፡፡ አላህን ፈሪዎች ብቻ ሲቀሩ፡፡'),
('43:68', 87, '(ለነርሱስ) «ባሮቼ ሆይ! ዛሬ ቀን በእናንተ ላይ ፍርሃት የለባችሁም እናንተም የምታዝኑ አይደላችሁም» (ይባላሉ)፡፡'),
('43:69', 87, 'እነዚያ በአንቀጾቻችን ያመኑና ፍጹም ታዛዦች የነበሩ (ባሮቼ ሆይ!)'),
('43:70', 87, '«ገነትን ግቡ እናንተም ሚስቶቻችሁም ትደሰታላችሁ ትከበሩም አላችሁ» (ይባላሉ)፡፡'),
('43:71', 87, 'ከወርቅ የኾኑ ሰፋፊ ዝርግ ሳሕኖችና ኩባያዎች በእነርሱ ላይ ይዝዞራሉ፡፡ በእርሷም ውስጥ ነፍሶች የሚከጅሉት፣ ዓይኖችም የሚደሰቱበት ሁሉ አልለ፡፡ እናንተም በውስጧ ዘላለም ዘውታሪዎች ናችሁ፡፡'),
('43:72', 87, 'ይህችም ያቺ ትሠሩት በነበራችሁት ዋጋ የተሰጣችኋት ገነት ናት፡፡'),
('43:73', 87, 'ለእናንተ በውስጧ ብዙ ፍረፍሬዎች በእርግጥ ዘውታሪዎች ናቸው፡፡'),
('43:74', 87, 'አመጸኞች በገሀነም ስቃይ ውስጥ በእርግጥ ዘውታሪዎች ናቸው፡፡'),
('43:75', 87, 'ከእነርሱ (ቅጣቱ) አይቀለልላቸውም፡፡ እነርሱም በእርሱ ውስጥ ተሰፋ ቆራጮች ናቸው፡፡'),
('43:76', 87, 'አልበደልናቸውምም፤ ግን በዳዮቹ እነርሱው ነበሩ፡፡'),
('43:77', 87, '«ማሊክ ሆይ! ጌታህ በኛ ላይ (በሞት) ይፍረድ፡፡» እያሉ ይጣራሉም፡፡ «እናንተ (በቅጣቱ ውስጥ) ዘላለም ነዋሪዎች ናችሁ» ይላቸዋል፡፡'),
('43:78', 87, 'እውነተኛውን መንገድ በእርግጥ አመጣንላችሁ፡፡ ግን አብዛኞቻችሁ እውነቱን ጠይዎች ናችሁ፡፡'),
('43:79', 87, 'ይልቁንም (በነቢዩ ላይ በማደም) ነገርን አጠነከሩን? እኛም (ተንኮላቸውን ወደእነርሱ በመመለስ) አጠንካሪዎች ነን፡፡'),
('43:80', 87, 'ወይም እኛ ምስጢራቸውንና ውይይታቸውን የማንሰማ መኾናችንን ያስባሉን? አይደለም፤ መልክተኞቻችንም እነርሱ ዘንድ ይጽፋሉ፡፡'),
('43:81', 87, '«ለአልረሕማን ልጅ (የለውም እንጅ) ቢኖረው እኔ (ለልጁ) የተገዢዎቹ መጀመሪያ ነኝ» በላቸው፡፡'),
('43:82', 87, 'የሰማያትና የምድር ጌታ የዙፋኑ ጌታ ከሚሉት ነገር ሁሉ ጠራ፡፡'),
('43:83', 87, 'ተዋቸውም፡፡ ያንን ይስፈራሩበት የነበሩትን ቀናቸውን እስከሚገናኙ ድረስ (በስሕተታቸው ውስጥ) ይዋኙ ይጫዎቱም፡፡'),
('43:84', 87, 'እርሱም ያ በሰማይ ውስጥ ሊግገዙት የሚገባው በምድርም ውስጥ ሊግገዙት የሚገባው አምላክ ነው፡፡ እርሱም ብልሃተኛው ዐዋቂው ነው፡፡'),
('43:85', 87, 'ያም የሰማያትና የምድር በመካከላቸውም ያለው ሁሉ ንግሥና የእርሱ ብቻ የኾነው አምላክ ላቀ፡፡ የሰዓቲቱም (የመምጫዋ ዘመን) ዕውቀት እርሱ ዘንድ ብቻ ነው፡፡ ወደእርሱም ትመለሳላችሁ፡፡'),
('43:86', 87, 'እነዚያም ከአላህ ሌላ የሚግገዟቸው እነርሱ የሚያውቁ ኾነው በእውነት ከመሰከሩት በስተቀር ምልጃን አይችሉም፡፡'),
('43:87', 87, 'ማን እንደፈጠራቸውም ብትጠይቃቸው «በእርግጥ አላህ ነው» ይላሉ፡፡ ታዲያ (ከእምነት) ወዴት ይዞራሉ፡፡'),
('43:88', 87, '(ነቢዩ) ጌታዬ ሆይ! እነዚህ የማያምኑ ሕዝቦች ናቸው፤ የማለቱም (ዕውቀት አላህ ዘንድ ነው)፡፡'),
('43:89', 87, 'እነርሱንም ተዋቸው፡፡ ነገሬ ሰላም ነው በልም፡፡ ወደፊትም (የሚመጣባቸውን) ያውቃሉ፡፡'),
('44:1', 87, 'ሐ.መ (ሓ ሚም)፡፡'),
('44:2', 87, 'አብራሪ በኾነው መጽሐፍ እንምላለን፡፡'),
('44:3', 87, 'እኛ (ቁርኣኑን) በተባረከች ሌሊት ውስጥ አወረድነው፡፡ እኛ አስፈራሪዎች ነበርንና፡፡'),
('44:4', 87, 'በውስጧ የተወሰነው ነገር ሁሉ ይልለያል፡፡'),
('44:5', 87, 'ከእኛ ዘንድ የኾነ ትእዛዝ ሲኾን (አወረድነው)፡፡ እኛ (መልክተኞችን) ላኪዎች ነበርን፡፡'),
('44:6', 87, 'ከጌታህ በኾነው ችሮታ (ተላኩ)፡፡ እነሆ እርሱ ሰሚው ዐዋቂው ነውና፡፡'),
('44:7', 87, 'የሰማያትና የምድር በመካከላቸውም ያለው ነገር ሁሉ ጌታ ከኾነው (ተላኩ)፡፡ የምታረጋግጡ እንደኾናችሁ (ነገሩ እንዳልነው መኾኑን እወቁ)፡፡'),
('44:8', 87, 'ከእርሱ ሌላ አምላክ የለም፡፡ ሕያው ያደርጋል፡፡ ይገድላልም፡፡ ጌታችሁ የመጀመሪያዎቹ አባቶቻችሁም ጌታ ነው፡፡'),
('44:9', 87, 'በእውነቱ እነርሱ የሚጫወቱ ሲኾኑ በመጠራጠር ውስጥ ናቸው፡፡'),
('44:10', 87, 'ሰማይም በግልጽ ጭስ የምትመጣበትን ቀን ተጠባበቅ፡፡'),
('44:11', 87, 'ሰዎችን የሚሸፍን (በኾነ ጭስ) ይህ አሳማሚ ቅጣት ነው፡፡'),
('44:12', 87, '«ጌታችን ሆይ! ከእኛ ላይ ቅጣቱን ግለጥልን፡፡ እኛ አማኞች እንኾናለንና» (ይላሉም)፡፡'),
('44:13', 87, '(ቅጣቱ በወረደ ጊዜ) ለእነርሱ መግገሰጽ እንዴት ይኖራቸዋል? አስረጅ መልክተኛ የመጣቸው ሲኾን (የካዱም ሲኾኑ)፡፡'),
('44:14', 87, 'ከዚያም ከእርሱ የዞሩ፤ (ከሰው) «የተሰተማረ ዕብድ ነው» ያሉም ሲኾኑ፡፡'),
('44:15', 87, 'እኛ ቅጣቱን ለጥቂት ጊዜ ገላጮች ነን፡፡ እናንተ (ወደ ክህደታችሁ) በእርግጥ ተመላሾች ናችሁ፡፡'),
('44:16', 87, 'ታላቂቱን ብርቱ አያያዝ በምንይዝበት ቀን፤ እኛ ተበቃዮች ነን፡፡'),
('44:17', 87, 'ከእነርሱም በፊት የፈርዖንን ሕዝቦች በእርግጥ ሞከርን፡፡ ክቡር መልእክተኛም መጣላቸው፡፡'),
('44:18', 87, '«የአላህን ባሮች ወደኔ አድርሱ፡፡ እኔ ለእናንተ ታማኝ መልክተኛ ነኝና፡፡'),
('44:19', 87, '«በአላህም ላይ አትኩሩ፡፡ እኔ ግልጽ የኾነን አስረጅ ያመጣሁላችሁ ነኝና (በማለት መጣላቸው)፡፡'),
('44:20', 87, '«እኔም እንዳትወግሩኝ በጌታየና በጌታችሁ ተጠብቂያለሁ፡፡'),
('44:21', 87, '«በእኔም ባታምኑ ራቁኝ» (ተዉኝ አለ)፡፡'),
('44:22', 87, 'ቀጥሎም (ስለ ዛቱበት) «እነዚህ አመጸኞች ሕዝቦች ናቸው» (አጥፋቸው) ሲል ጌታውን ለመነ፡፡'),
('44:23', 87, '(ጌታው) «ባሮቼንም ይዘህ በሌሊት ኺድ፡፡ እናንተ የሚከተሉዋችሁ ናችሁና፡፡'),
('44:24', 87, '«ባሕሩንም የተከፈተ ኾኖ ተወው፡፡ እነርሱ የሚሰጥጠሙ ሰራዊት ናቸውና» (አለው)፡፡'),
('44:25', 87, 'ከአትክልቶችና ከምንጮችም ብዙ ነገሮችን ተዉ፡፡'),
('44:26', 87, 'ከአዝመራዎችም ከመልካም መቀመጫም፡፡'),
('44:27', 87, 'በእርሷ ተደሳቾች ከነበሩባትም ድሎት (ብዙን ነገር ተዉ)፡፡'),
('44:28', 87, '(ነገሩ) እንደዚሁ ኾነ፡፡ ሌሎችንም ሕዝቦች አወረስናት፡፡'),
('44:29', 87, 'ሰማይና ምድርም በእነርሱ ላይ አላለቀሱም፡፡ የሚቆዩም አልነበሩም፡፡'),
('44:30', 87, 'የእስራኤልንም ልጆች አዋራጅ ከኾነ ስቃይ በእርግጥ አዳንናቸው፡፡'),
('44:31', 87, 'ከፈርዖን፤ እርሱ የኮራ ከወሰን አላፊዎቹ ነበርና፡፡'),
('44:32', 87, 'ከማወቅም ጋር በዓለማት ላይ በእርግጥ መረጥናቸው፡፡'),
('44:33', 87, 'ከታምራቶችም በውስጡ ግልጽ የኾነ ፈተና ያለበትን ሰጠናቸው፡፡'),
('44:34', 87, 'እነዚህ (የመካ ከሓዲዎች) በእርግጥ ይላሉ፡-'),
('44:35', 87, 'እርሷ የፊተኛይቱ ሞታችን እንጅ አይደለችም፡፡ እኛም የምንቀሰቀስ አይደለንም፡፡'),
('44:36', 87, 'እውነተኞችም እንደ ኾናችሁ አባቶቻችንን አምጡልን፡፡'),
('44:37', 87, 'እነርሱ በላጮች ናቸውን ወይስ የቱብበዕ ሕዝቦችና እነዚያ ከእነርሱ በፊት የነበሩት? አጠፋናቸው፡፡ እነርሱ አመጸኞች ነበሩና፡፡'),
('44:38', 87, 'ሰማያትንና ምድርንም በሁለቱ መካከል ያለውንም ሁሉ ቀላጆች ኾነን አልፈጠርንም፡፡'),
('44:39', 87, 'ሁለቱንም በምር እንጅ አልፈጠርናቸውም፡፡ ግን አብዛኞቻቸው አያውቁም፡፡'),
('44:40', 87, 'የመለያው ቀን ለሁሉም ቀጠሯቸው ነው፡፡'),
('44:41', 87, 'ዘመድ ከዘመዱ ምንንም የማይጠቅምበት እነርሱም የማይርረዱበት ቀን ነው፡፡'),
('44:42', 87, 'አላህ ያዘነለት ሰውና ያመነ ብቻ ሲቀር፡፡ (እርሱስ ይርረዳል)፡፡ እርሱ አሸናፊው አዛኙ ነውና፡፡'),
('44:43', 87, 'የዘቁመ ዛፍ'),
('44:44', 87, 'የኀጢኣተኛው ምግብ ነው፡፡'),
('44:45', 87, 'እንደ ዘይት አተላ ነው፡፡ በሆዶች ውስጥ የሚፈላ ሲኾን፡፡'),
('44:46', 87, 'እንደ ገነፈለ ውሃ አፈላል (የሚፈላ ሲኾን)፡፡'),
('44:47', 87, 'ያዙት፤ ወደ ገሀነም መካከልም በኀይል ጎትቱት፡፡'),
('44:48', 87, 'ከዚያም «ከራሱ በላይ ከፈላ ውሃ ስቃይ አንቧቡበት፡፡»'),
('44:49', 87, '«ቅመስ፤ አንተ አሸናፊው ክብሩ ነህና» (ይባላል)፡፡'),
('44:50', 87, '«ይህ ያ በእርሱ ትጠራጠሩበት የነበራችሁት ነው» (ይባላሉ)፡፡'),
('44:51', 87, 'ጥንቁቆቹ በእርግጥ በጸጥተኛ መኖሪያ ውስጥ ናቸው፡፡'),
('44:52', 87, 'በአትክልቶችና በምንጮች ውስጥ ናቸው፡፡'),
('44:53', 87, 'ፊት ለፊት የተቅጣጩ ኾነው ከስስ ሐርና ከወፍራም ሐር ይለብሳሉ፡፡'),
('44:54', 87, '(ነገሩ) እንደዚሁ ነው፤ ዓይናማዎች የኾኑን ነጫጭ ሴቶችም እናጠናዳቸዋለን፡፡'),
('44:55', 87, 'በእርሷም ውስጥ የተማመኑ ኾነው፤ ከፍራፍሬ ሁሉ ያዝዛሉ፡፡'),
('44:56', 87, 'የፊተኛይቱን ሞት እንጅ (ዳግመኛ) በእርሷ ውስጥ ሞትን አይቀምሱም፡፡ የገሀነምንም ቅጣት (አላህ) ጠበቃቸው፡፡'),
('44:57', 87, 'ከጌታህ በኾነ ችሮታ (ጠበቃቸው)፡፡ ይህ እርሱ ታላቅ ዕድል ነው፡፡'),
('44:58', 87, '(ቁርኣኑን) በቋንቋህም ያገራነው (ሕዝቦችህ) ይገነዘቡ ዘንድ ብቻ ነው፡፡'),
('44:59', 87, 'ተጠባበቅም እነርሱ ተጠባባቂዎች ናቸውና፡፡'),
('45:1', 87, 'ሐ.መ (ሓ ሚም)፡፡'),
('45:2', 87, 'የመጽሐፉ መወረድ አሸናፊ ጥበበኛ ከኾነው አላህ ነው፡፡'),
('45:3', 87, 'በሰማያትና በምድር ውስጥ ለምእምናን ሁሉ (ለችሎታው) እርገጠኛ ምልክቶች አልሉ፡፡'),
('45:4', 87, 'እናንተንም በመፍጠር ከተንቀሳቃሽም (በምድር ላይ) የሚበትነውን ሁሉ (በመፍጠሩ) ለሚያረጋግጡ ሕዝቦች ተዓምራቶች አልሉ፡፡'),
('45:5', 87, 'በሌሊትና መዓልት መተካካትም፣ ከሲሳይም (ከዝናም) አላህ ከሰማይ ባወረደው በርሱም ምድርን ከሞተች በኋላ ሕያው በማድረጉ፣ ነፋሶችንም (በያቅጣጫቸው) በማዘዋወሩ ለሚያውቁ ሕዝቦች ማስረጃዎች አልሉ፡፡'),
('45:6', 87, 'እነዚህ ባንተ ላይ በውነት የምናነባቸው ሲኾኑ የአላህ ማስረጃዎች ናቸው፡፡ ከአላህና ከማስረጃዎቹም ወዲያ በየትኛው ንግግር ያምናሉ?'),
('45:7', 87, 'ውሸታም ኀጢአተኛ ለኾነ ሁሉ ወዮለት፡፡ (ጥፋት ተገባው)፡፡'),
('45:8', 87, 'የአላህን አንቀጾች በእርሱ ላይ የሚነበቡለት ሲኾኑ ይሰማል፡፡ ከዚያም የኮራ ሲኾን እንዳልሰማት ኾኖ (በክሕደቱ ላይ) ይዘወትራል፡፡ በአሳማሚም ቅጣት አብስረው፡፡'),
('45:9', 87, 'ከአንቀጾቻችንም አንዳችን ባወቀ ጊዜ መሳለቂያ አድርጎ ይይዛታል፡፡ እነዚያ ለእነርሱ አዋራጅ ቅጣት አልላቸው፡፡'),
('45:10', 87, 'ከፊታቸውም ገሀነም አልለች፡፡ የሰበሰቡትም ሀብት ከእነርሱ ላይ ምንንም አይመልስላቸውም፡፡ ከአላህ ሌላም ረዳቶች አድርገው የያዙዋቸው (አይጠቅሟቸውም)፡፡ ለእነርሱም ታላቅ ቅጣት አልላቸው፡፡'),
('45:11', 87, 'ይህ (ቁርኣን) መሪ ነው፡፡ እነዚያም በጌታቸው አንቀጾች የካዱት ለእነርሱ ከብርቱ ቅጣት የኾነ አሳማሚ ስቃይ አልላቸው፡፡'),
('45:12', 87, 'አላህ ያ ባሕርን በውስጡ ታንኳዎች በፈቃዱ እንዲንሻለሉበት ከችሮታውም እንድትፈልጉበት እንድታመሰግኑትም ለእናነተ የገራላችሁ ነው፡፡'),
('45:13', 87, 'ለናንተም በሰማያት ያለውንና በምድርም ያለውን ሁሉ በመላ ከእርሱ ሲኾን የገራላችሁ ነው፡፡ በዚህ ለሚያስተነትኑ ሕዝቦች ተዓምራት አልለበት፡፡'),
('45:14', 87, 'ለእነዚያ ለአመኑት ሰዎች (ምሕረት አድርጉ) በላቸው፡፡ ለእነዚያ የአላህን ቀኖች ለማይፈሩት ይምራሉና፡፡ ሕዝቦችን ይሠሩት በነበሩት ነገር ይመነዳ ዘንድ (ምሕረት አድርጉ በላቸው)፡፡'),
('45:15', 87, 'መልካምን የሠራ ሰው ለነፍሱ ነው፡፡ ያከፋም ሰው በእርሷ ላይ ነው፡፡ ከዚያም ወደ ጌታችሁ'),
('45:16', 87, 'ለእስራኤል ልጆችም መጽሐፍንና ሕግን፣ ነቢይነትንም በእርግጥ ሰጠናቸው፡፡ ከመልካም ሲሳዮችም ለገስንላቸው፡፡ በዓለማት ላይም አበለጥናቸው፡፡'),
('45:17', 87, 'ከትዕዛዝም ግልጾችን ሰጠናቸው፡፡ ዕውቀቱም ከመጣላቸው በኋላ በመካከላቸው ለምቀኝነት እንጅ ለሌላ አልተለያዩም፡፡ ጌታህ በትንሣኤ ቀን በዚያ በእርሱ ይለያዩበት በነበሩት ነገር በመካከላቸው በእርግጥ ይፈርዳል፡፡'),
('45:18', 87, 'ከዚያም ከነገሩ (ከሃይማኖት) በትክክለኛይቱ ሕግ ላይ አደረግንህ፡፡ ስለዚህ ተከተላት፡፡ የእነዚያንም የማያውቁትን ሕዝቦች ዝንባሌዎች አትከተል፡፡'),
('45:19', 87, 'እነርሱ ከአላህ (ቅጣት) ምንንም ከአንተ አይገፈትሩልህምና፡፡ በደለኞም ከፊላቸው የከፊሉ ረዳቶች ናቸው፡፡ አላህም የጥንቁቆቹ ረዳት ነው፡፡'),
('45:20', 87, 'ይሀ (ቁርኣን) ለሰዎች የልብ ብርሃኖች ነው፡፡ ለሚያረጋግጡም ሕዝቦች መሪና እዝነት ነው፡፡'),
('45:21', 87, 'እነዚያ ኀጢአቶችን የሠሩ ሕይወታቸውም ሞታቸውም ትክክል ሲኾን እንደእነዚያ እንደ አመኑትና መልካሞችን እንደሠሩት ልናደርጋቸው ይጠረጥራሉን? (አይጠርጥሩ)፡፡ የሚፈርዱት ምንኛ ከፋ!'),
('45:22', 87, 'አላህም ሰማያትንና ምድርን (ለችሎታው እንደሚያመለክትባቸውና) ነፍስም ሁሉ በሠራችው ሥራ ትምመነዳ ዘንድ በትክክል ፈጠረ፡፡ እነርሱም አይበደሉም፡፡'),
('45:23', 87, 'ዝንባሌውን አምላኩ አድርጎ የያዘውን፣ አላህም ከዕውቀት ጋር ያጠመመውን፣ በጆሮውና በልቡ ላይም ያተመበትን፣ በዓይኑም ላይ ሺፋን ያደረገበትን ሰው አየህን! ታዲያ ከአላህ በኋላ የሚያቀናው ማነው? አትገሠጹምን?'),
('45:24', 87, 'እርሷም (ሕይወት) የቅርቢቱ ሕይወታችን እንጅ ሌላ አይደለችም፡፡ «እንሞታለን፤ ሕያውም እንኾናለን፡፡ ከጊዜም (ማለፍ) በስተቀር ሌላ አያጠፋንም» አሉ፡፡ ለእነርሱም በዚህ (በሚሉት) ምንም ዕውቀት የላቸውም፡፡ እነርሱ የሚጠራጠሩ እንጅ ሌላ አይደሉም፡፡'),
('45:25', 87, 'አንቀጾቻችንም ግልጾች ኾነው በእነርሱ ላይ በተነበቡላቸው ጊዜ ክርክራቸው «እውነተኞች እንደ ኾናችሁ አባቶቻችንን አምጡ» ማለት እንጅ ሌላ አልነበረም፡፡'),
('45:26', 87, '«አላህ ሕያው ያደርጋችኋል፤ ከዚያም ይገድላችኋል፣ ከዚያም ወደ ትንሣኤ ቀን ይሰበስባችኋል፡፡ በእርሱ ጥርጥር የለበትም፡፡ ግን አብዛኛዎቹ ሰዎች አያውቁም» በላቸው፡፡'),
('45:27', 87, 'የሰማያትና የምድር ግዛት የአላህ ብቻ ነው፡፡ ሰዓቲቱም በምትቆምበት ቀን ያን ጊዜ አጥፊዎች ሁሉ ይከስራሉ፡፡'),
('45:28', 87, 'ሕዝብንም ሁሉ ተንበርካኪ ኾና ታያታለህ፡፡ ሕዝብ ሁሉ ወደ መጽሐፏ ትጥጠራለች፡፡ «ዛሬ ትሠሩት የነበራችሁትን ነገር ትመነዳላችሁ» (ይባላሉ)፡፡'),
('45:29', 87, 'ይህ መጽሐፋችን ነው፡፡ በእናንተ ላይ በእውነት ይናገራል፡፡ እኛ ያንን ትሠሩት የነበራችሁትን እናስገለብጥ ነበርን (ይባላሉ)፡፡'),
('45:30', 87, 'እነዚያ ያመኑትና መልካሞችን የሠሩትማ ጌታቸው በእዝነቱ ውስጥ ያገባቸዋል፡፡ ይህ እርሱ ግልጽ የኾነ ማግኘት ነው፡፡'),
('45:31', 87, 'እነዚያም የካዱትማ (ለእነርሱ ይባላሉ) «አንቀጾቼ በእናንተ ላይ ይነበቡ አልነበሩምን? ኮራችሁም፡፡ ከሓዲዎች ሕዝቦችም ነበራችሁ፡፡»'),
('45:32', 87, '«የአላህ ቀጠሮ እውነት ነው፡፡ ሰዓቲቱም በእርሷ (መምጣት) ጥርጥር የለም፡፡» በተባለ ጊዜም «ሰዓቲቱ ምን እንደ ኾነች አናውቅም፡፡ መጠራጠርን የምንጠራጠር እንጅ ሌላ አይደለንም፡፡ እኛም አረጋጋጮች አይደለንም» አላችሁ፡፡'),
('45:33', 87, 'የሠሩዋቸውም ኀጢአቶች ለእነርሱ ይገለጹላቸዋል፡፡ ያም በእርሱ ይሳለቁበት የነበሩት ቅጣት በእነርሱ ላይ ይወርድባቸዋል፡፡'),
('45:34', 87, '«ይህንንም ቀናችሁን መገናኘትን እንደ ረሳችሁ ዛሬ እንረሳችኋለን፡፡ (እንተዋችኋለን)፡፡ መኖሪያችሁም እሳት ናት፡፡ ለእናንተም ከረዳቶች ምንም የላችሁም» ይባላል፡፡'),
('45:35', 87, 'ይህ እናንተ የአላህን አንቀጾች መቀለጃ አድርጋችሁ በመያዛችሁና ቅርቢቱም ሕይወት ስለአታለለቻችሁ ነው፤ (ይባላሉ)፡፡ ዛሬ ከእርሷ አይወጥጡም፤ እነርሱም በወቀሳ አይታለፉም፡፡'),
('45:36', 87, 'ምስጋናም ለአላህ ለሰማያት ጌታ ለምድርም ጌታ ለዓለማት ጌታ የተገባው ነው፡፡'),
('45:37', 87, 'ኩራትም በሰማያትም በምድርም ለእርሱ ብቻ ነው፡፡ እርሱም አሸነፊው ጥበበኛው ነው፡፡'),
('46:1', 87, 'ሐ.መ (ሓ ሚም)፡፡'),
('46:2', 87, 'የመጽሐፉ መወረድ አሸናፊ ጥበበኛ ከኾነው አላህ ነው፡፡'),
('46:3', 87, 'ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ በምርና የተወሰነ ጊዜንም በመለካት እንጅ (ለቀልድ) አልፈጠርናቸውም፡፡ እነዚያ የካዱትም ከተስፈራሩት ነገር (ትተው) ዘዋሪዎች ናቸው፡፡'),
('46:4', 87, '«ከአላህ ሌላ የምትግገዟቸውን አያችሁን? ከምድር ምንን እንደ ፈጠሩ አሳዩኝ፡፡ ወይም በሰማያት ለእነርሱ (ከአላህ ጋር) መጋራት አላቸውን? (ያማልዱናል በማለታችሁ) እውነተኞች እንደ ኾናችሁ ከዚህ (ቁርኣን) በፊት የኾነን መጽሐፍ ወይም ከዕውቀት የኾነ ቅርስን አምጡልኝ» በላቸው፡፡'),
('46:5', 87, 'እስከ ትንሣኤ ቀን ድረስም ለእርሱ የማይመልስለትን (ጣዖት) ከአላህ ሌላ ከሚጠራ ሰው ይበልጥ የተሳሳተ ማነው? እነርሱም ከጥሪያቸው ዘንጊዎች ናቸው፡፡'),
('46:6', 87, 'ሰዎችም በተሰበሰቡ ጊዜ (ጣዖቶቹ) ለእነርሱ ጠላቶች ይኾናሉ፡፡ (እነሱን) መገዛታቸውንም ከሓዲዎች ይኾናሉ፡፡'),
('46:7', 87, 'በእነርሱም ላይ አንቀጾቻችን ግልጾች ኾነው በተነበቡ ጊዜ እነዚያ እውነቱን በመጣላቸው ጊዜ የካዱትን «ይህ ግልጽ ድግምት ነው» አሉ፡፡'),
('46:8', 87, 'ይልቁንም ቀጠፈው ይላሉን? «ብቀጥፈው ለእኔ ከአላህ (ቅጣት ለማዳን) ምንንም አትችሉም፡፡ እርሱ ያንን በእርሱ የምትቀባዥሩበትን ዐዋቂ ነው፡፡ በእኔና በእናንተ መካከል መስካሪ በእርሱ በቃ፡፡ እርሱም መሓሪው አዛኙ ነው» በላቸው፡፡'),
('46:9', 87, '«ከመልክተኞች ብጤ የሌለኝ አይደለሁም፡፡ በእኔም በእናንተም ምን እንደሚሥሠራም አላውቅም፡፡ ወደእኔ የሚወረደውን እንጅ ሌላን አልከተልም፡፡ እኔም ግልጽ አስፈራሪ እንጅ ሌላ አይደለሁም» በላቸው፡፡'),
('46:10', 87, '(ሙሐመድ ሆይ!) በላቸው «እስቲ ንገሩኝ፤ (ቁርኣኑ) ከአላህ ዘንድ ቢኾን፡፡ በእርሱም ብትክዱ፣ ከእስራኤል ልጆችም መስካሪ በብጤው (በእርሱ) ላይ ቢመሰክር፣ ቢያምንም፣ (ከእምነት) ብትኮሩም፣ (በዳይ አትኾኑምን?)» አላህ በእርግጥ በደለኞችን ሕዝቦች አያቀናም፡፡'),
('46:11', 87, 'እነዚያንም የካዱት ሰዎች ስለእነዚያ ስለ አመኑት ሰዎች (እምነቱ) «መልካም ነገር በኾነ ኖሮ ወደርሱ ባልቀደሙን ነበር» አሉ፡፡ በእርሱም ባልተመሩ ጊዜ «ይህ (ቁርኣን) ጥንታዊ ቅጥፈት ነው» ይላሉ፡፡');
INSERT INTO `ayah_translations` (`verse_key`, `translation_id`, `text`) VALUES
('46:12', 87, 'ከበፊቱም የሙሳ መጽሐፍ መሪና ጸጋ ሲኾን አልለ፡፡ ይህም እነዚያን የበደሉትን ሊያስፈራራ በዐረብኛ ቋንቋ ሲኾን (የፊቶቹን መጻሕፍት) አረጋጋጭ መጽሐፍ ነው፡፡ ለበጎ አድራጊዎችም ብስራት ነው፡፡'),
('46:13', 87, 'እነዚያ «ጌታችን አላህ ነው» ያሉ፣ ከዚያም ቀጥ ያሉ በነርሱ ላይ ፍርሃት የለባቸውም፡፡ እነርሱም አያዝኑም፡፡'),
('46:14', 87, 'እነዚያ የገነት ጓዶች ናቸው፡፡ በእርሷ ውስጥ ዘውታሪዎች ሲኾኑ፡፡ በዚያ ይሠሩት በነበሩት ምክንያት ታላቅን ምንዳ (ይምመነዳሉ)፡፡'),
('46:15', 87, 'ሰውንም በወላጆቹ በጎ መዋልን በጥብቅ አዘዝነው፡፡ እናቱ በችግር ላይ ኾና አረገዘችው፡፡ በችግርም ወለደችው፡፡ እርግዝናውና ከጡት መለያውም ሰላሳ ወር ነው፡፡ ጥንካሬውንም ወቅት በደረሰ ጊዜ (ከዚያ አልፎ) አርባ ዓመትንም በደረሰ ጊዜ «ጌታዬ ሆይ! ያችን በእኔ ላይና በወላጆቼ ላይ የለገስካትን ጸጋህን እንዳመሰግን የምትወደውንም መልካም ሥራ እንድሠራ ምራኝ፡፡ ዘሮቼንም ለእኔ አብጅልኝ፡፡ እኔ ወዳንተ ተመለስኩ፡፡ እኔም ከሙስሊሞ ነኝ» አለ፡፡'),
('46:16', 87, 'እነዚህ (ይህንን ባዮች) በገነት ጓዶች ውስጥ ሲኾኑ እነዚያ ከሠሩት ሥራ መልካሙን ከነሱ የምንቀበላቸውና ከኀጢአቶቻቸውም የምናልፋቸው ናቸው፡፡ ያንን ተስፋ ይስሰጡት የነበሩትን እውነተኛ ቀጠሮ (እንሞላላቸዋለን)፡፡'),
('46:17', 87, 'ያንንም ለወላጆቹ «ፎህ ለእናንተ ከእኔ በፊት የክፍል ዘመናት ሰዎች (ሳይወጡ) በእርግጥ ያለፉ ሲኾኑ (ከመቃብር) እንድወጥጣ ታስፈራሩኛላችሁን?» ያለውን ሁለቱም (ወላጆቹ) አላህን የሚለምኑ ሲኾኑ (ባታምን) «ወዮልህ፡፡ እመን፡፡ የአላህ ቀጠሮ እርግጠኛ ነው፡፡»'),
('46:18', 87, 'እነዚህ እነዚያ ከጋኔንም ከሰውም ከእነርሱ በፊት ካለፉት ሕዝቦች ጋር ቃሉ በእነርሱ ላይ የተረጋገጠባቸው ናቸው፡፡ እነርሱ ከሳሪዎች ነበሩና፡፡'),
('46:19', 87, 'ለሁሉም ከሠሩት ሥራ ደረጃዎች አልሏቸው፡፡ ሥራዎቻቸውንም ይሞላላቸው ዘንድ (ይህንን መነዳቸው) እነርሱም አይበደሉም፡፡'),
('46:20', 87, 'እነዚያም የካዱት በእሳት ላይ በሚጋፈጡ ቀን «ጣፋጮቻችሁን በአነስተኛይቱ ሕይወታችሁ አሳለፋችሁ፡፡ በእርሷም ተጣቀማችሁ፡፡ ስለዚህ በምድር ላይ ያለ አግባብ ትኮሩ በነበራችሁትና ታምጹ በነበራችሁት ዛሬ የውርደትን ቅጣት ትምመነዳላችሁ» (ይባላሉ)፡፡'),
('46:21', 87, 'የዓድንም ወንድም (ሁድን) ሕዝቦቹን በአሕቃፍ ባስጠነቀቀ ጊዜ አውሳለቸው፡፡ በስተፊቱና በስተኋላውም ብዙ አስፈራሪዎች በእርግጥ አልፈዋል፡፡ «ከአላህ በስተቀር አትግገዙ እኔ በእናነተ ላይ የከባድ ቀንን ቅጣት እፈራላችኋለሁና» በማለት (ባሰጠነቀቀ ጊዜ)፡፡'),
('46:22', 87, '«ከአማልክቶቻችን ልታዞረን መጣህብን? ከውነተኞቹም እንደኾንክ የምትዝትብንን (ቅጣት) አምጣው» አሉ፡፡'),
('46:23', 87, '«ዕውቀቱ አላህ ዘንድ ብቻ ነው፡፡ ያን በእርሱ የተላክሁበትንም አደርስላችኋለሁ፡፡ ግን እኔ የምትሳሳቱ ሕዝቦች ኾናችሁ አያችኋለሁ» አላቸው፡፡'),
('46:24', 87, 'ሸለቆዎቻቸውን ተቅጣጪ አግዳሚ ደመና ኾኖ ባዩትም ጊዜ «ይህ አዝናቢያችን የኾነ ደመና ነው» አሉ፡፡ (ሁድም) «አይደለም፤ እርሱ ያ በእርሱ የተቻኮላችሁበት መዐት ነው፡፡ በውስጧ አሳማሚ ስቃይ ያለባት ነፋስ ናት፡፡'),
('46:25', 87, 'በጌታዋ ትዕዛዝ አንዳቹን ሁሉ ታጠፋለች» (አላቸው)፡፡ ከመኖሪያዎቻቸውም በስተቀር ምንም የማይታዩ ኾኑ፡፡ እንደዚሁ አመጸኞችን ሕዝቦች ሁሉ እንቀጣለን፡፡'),
('46:26', 87, 'በዚያም እናንተን በእርሱ ባላስመቸንበት (ድሎት) በእርግጥ አስመቸናቸው፡፡ ለእነርሱም መስሚያንና ማያዎችን፣ ልቦችንም አደረግንላቸው፡፡ ግን መስሚያቸውና ማያዎቻቸው፣ ልቦቻቸውም ከእነሱ ምንም አልጠቀሟቸውም፡፡ በአላህ አንቀጾች ይክዱ ነበሩና፡፡ በእነርሱም ላይ ያ በእርሱ ይሳለቁበት የነበሩት ቅጣት ወረደባቸው፡፡'),
('46:27', 87, 'ከከተሞችም እነዚያን በአካባቢያችሁ የነበሩትን በእርግጥ አጠፋን (ከክሕደታቸው) ይመለሱም ዘንድ አስረጂዎችን መላለስን፡፡'),
('46:28', 87, 'እነዚያም መቃረቢያ ይኾኑ ዘንድ ከአላህ ሌላ አማልክት አድርገው የያዙዋቸው አይረዷቸውም ኖሯልን? በእርግጥ ከነሱ ራቁ፡፡ ይህም ውሸታቸውና (በልማድ) ይቀጥፉት የነበሩት ነው፡፡'),
('46:29', 87, 'ከጋኔን የኾኑን ጭፍሮች ቁርኣንን የሚያዳምጡ ሲኾኑ ወዳንተ ባዞርን ጊዜም (አስታውስ)፡፡ በተጣዱትም ጊዜ ዝም ብላችሁ አዳምጡ ተባባሉ፡፡ በተጨረሰም ጊዜ አስጠንቃቂዎች ኾነው ወደ ሕዝቦቻቸው ተመለሱ፡፡'),
('46:30', 87, 'አሉም «ሕዝቦቻችን ሆይ! እኛ ከሙሳ በኋላ የተወረደን መጽሐፍ በፊቱ ያለውን (መጽሐፍ) የሚያረጋግጥ ወደ እውነትና ወደ ቀጥተኛ መንገድ የሚመራ የኾነን ሰማን፡፡'),
('46:31', 87, 'ወገኖቻችን ሆይ! የአላህን ጠሪ ተቀበሉ፡፡ በእርሱም እመኑ፡፡ (አላህ) ከኀጢአቶቻችሁ ለእናንተ ይምራልና፡፡ ከአሳማሚ ቅጣትም ያድናችኋልና፡፡'),
('46:32', 87, 'የአላህንም ጠሪ የማይቀበል ሰው በምድር ውስጥ የሚያመልጥ አይደለም፡፡ ከእርሱም ሌላ ለእርሱ ረዳቶች የሉትም፡፡ እነዚያ በግልጽ ስሕተት ውስጥ ናቸው» (አሉ)፡፡'),
('46:33', 87, 'ያ ሰማያትንና ምድርን የፈጠረ እነርሱንም በመፍጠሩ ያልደከመው አላህ ሙታንን ሕያው በማድረግ ላይ ቻይ መኾኑን አላስተዋሉምን? (በማስነሳት) ቻይ ነው፡፡ እርሱ በነገሩ ሁሉ ላይ ቻይ ነውና፡፡'),
('46:34', 87, 'እነዚያም የካዱት ሰዎች በእሳት ላይ በሚቀረቡ ቀን «ይህ እውነት አይደለምን?» (ይባላሉ)፡፡ «እውነት ነው፤ በጌታችን ይኹንብን» ይላሉ፡፡ (አላህም) «ትክዱ በነበራችሁት ምክንያት ቅጣቱን ቅመሱ» ይላቸዋል፡፡'),
('46:35', 87, 'ከመልክተኞችም የቆራጥነት ባለቤቶች የኾኑት እንደ ታገሱ ሁሉ ታገስ፡፡ ለእነርሱም (ለሕዝቦችህ ቅጣት) አትቻኮል፡፡ ያንን የሚስፈራሩበትን ቅጣት በሚያዩ ቀን እነርሱ ከቀን አንዲትን ሰዓት አንጅ እንዳልቆዩ ይኾናሉ፡፡ (ይህ ቁርኣን) በቂ ግሳጼ ነው አመጸኞችም ሕዝቦች እንጅ (ሌሎች) ይጥጠፋሉን?'),
('47:1', 87, 'እነዚያ የካዱ ከአላህ መንገድም የከለከሉ (አላህ) ሥራዎቻቸውን አጠፋባቸው፡፡'),
('47:2', 87, 'እነዚያም ያመኑ፣ በጎዎችንም የሠሩ፣ በሙሐመድ ላይም የወረደው እርሱ ከጌታቸው ሲኾን እውነት ስለ ኾነ ያመኑ ከእነርሱ ላይ ኃጢአቶቻቸውን ያባብሳል፡፡ ኹኔታቸውንም ሁሉ ያበጃል፡፡'),
('47:3', 87, 'ይህ እነዚያ የካዱት ውሸትን የተከተሉ በመኾናቸውና እነዚያም ያመኑት ከጌታቸው የኾነን እውነት ስለተከተሉ ነው፡፡ እንደዚሁ አላህ ለሰዎች ምሳሌዎቻቸውን ያብራራል፡፡'),
('47:4', 87, 'እነዚያንም የካዱትን (በጦር ላይ) ባገኛችሁ ጊዜ ጫንቃዎችን በኀይል ምቱ፡፡ ባደካማችኋቸውም ጊዜ (አትግደሏቸው ማርኳቸው)፡፡ ማሰሪያውንም አጥብቁ፡፡ በኋላም ወይም በነጻ ትለቋቸዋላችሁ፤ ወይም ትበዧቸዋላችሁ፡፡ (ይህም) ጦሪቱ መሳሪያዋን እስከምትጥል ድረስ ነው፡፡ (ነገሩ) ይህ ነው፡፡ አላህም ቢሻ ከእነርሱ (ያለጦር) በተበቀለ ነበር፡፡ ግን ከፊላችሁን በከፊሉ ሊሞክር (በዚህ አዘዛችሁ)፡፡ እነዚያንም በአላህ መንገድ ላይ የተገደሉትን ሥራዎቻቸውን ፈጽሞ አያጠፋባቸውም፡፡'),
('47:5', 87, 'በእርግጥ ይመራቸዋል፡፡ ኹኔታቸውንም ሁሉ ያበጃል፡፡'),
('47:6', 87, 'ገነትንም ያገባቸዋል፡፡ ለእነርሱ አስታውቋታል፡፡'),
('47:7', 87, 'እናንተ ያመናችሁ ሆይ! አላህን (ሃይማኖቱን) ብትረዱ፤ ይረዳችኋል፡፡ ጫማዎቻችሁንም ያደላድላል፡፡'),
('47:8', 87, 'እነዚያም የካዱት ለእነርሱ ጥፋት ተገባቸው፡፡ ሥራዎቻቸውንም አጠፋባቸው፡፡'),
('47:9', 87, 'ይህ እነርሱ አላህ ያወረደውን ስለጠሉ ነው፡፡ ስለዚህ ሥራዎቻቸውን አበላሸባቸው፡፡'),
('47:10', 87, 'የእነዚያ ከእነርሱ በፊት የነበሩት (ከሓዲዎች) መጨረሻ እንዴት እንደ ነበረ ያዩ ዘንድ በምድር ለይ አልኼዱምን? አላህ በእነርሱ ላይ (ያላቸውን ሁሉ) አጠፋባቸው፡፡ ለከሐዲዎችም ሁሉ ብጤዎችዋ አልሏቸው፡፡'),
('47:11', 87, 'ይህ አላህ የእነዚያ ያመኑት ሰዎች ረዳት ስለኾነና ከሓዲዎችም ለእነርሱ ረዳት ስለሌላቸው ነው፡፡'),
('47:12', 87, 'አላህ እነዚያን ያመኑትንና መልካሞችን የሠሩትን ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች ያገባቸዋል፡፡ እነዚያም የካዱት (በቅርቢቱ ዓለም) ይጣቀማሉ፡፡ እንስሳዎችም እንደሚበሉ ይበላሉ፡፡ እሳትም ለእነርሱ መኖሪያቸው ናት፡፡'),
('47:13', 87, 'ከከተማም እርሷ ከዚያች ካወጣችህ ከተማህ ይበልጥ በኀይል ጠንካራ የኾነች (ባለቤቶችዋን) ያጠፋናቸው ብዙ ናት፡፡ ለእነርሱም ረዳት አልነበራቸውም፡፡'),
('47:14', 87, 'ከጌታው በኾነች አስረጅ ላይ የኾነ ምእመን ክፉ ሥራቸው ለእነርሱ እንደ ተሸለመላቸውና ዝንባሌዎቻቸውን እንደ ተከተሉት ነውን?'),
('47:15', 87, 'የዚያች ጥንቁቆቹ ተስፋ የተሰጧት ገነት ምስል በውስጧ ሺታው ከማይለውጥ ውሃ ወንዞች፣ ጣዕሙ ከማይለወጥ ወተትም ወንዞች፣ ለጠጪዎች ሁሉ ጣፋጭ ከኾነች የወይን ጠጅም ወንዞች ከተነጠረ ማርም ወንዞች አልሉባት፡፡ ለእነርሱም በውስጧ ከፍሬዎች ሁሉ (በያይነቱ) ከጌታቸው ምሕረትም አልላቸው፡፡ (በዚች ገነት ውስጥ ዘውታሪ የኾነ ሰው) እርሱ በእሳት ውስጥ ዘውታሪ እንደኾነ ሰው፣ ሞቃትንም ውሃ እንደተጋቱ፣ አንጀቶቻቸውንም ወዲያውኑ እንደቆራረጠው ነውን? (አይደለም)፡፡'),
('47:16', 87, 'ከእነርሱም ወዳንተ የሚያዳምጡ አልሉ፡፡ ከአንተም ዘንድ በወጡ ጊዜ ለእነዚያ ዕውቀት ለተሰጡት «አሁን ምን አለ?» ይላሉ፡፡ እነዚህ እነዚያ በልቦቻቸው ላይ አላህ ያተመባቸው ዝንባሌዎቻቸውንም የተከተሉ ናቸው፡፡'),
('47:17', 87, 'እነዚያም የተመሩት (አላህ) መመራትን ጨመረላቸው፡፡ (ከእሳት) መጥጠበቂያቸውንም ሰጣቸው፡፡'),
('47:18', 87, 'ሰዓቲቱንም ድንገት የምትመጣባቸው መኾንዋን እንጅ ይጠባበቃሉን? ምልክቶችዋም በእርግጥ መጥተወል፡፡ በመጣቻቸውም ጊዜ ማስታወሳቸው ለእነርሱ እንዴት ይጠቅማቸዋል?'),
('47:19', 87, 'እነሆ ከአላህ ሌላ አምላክ አለመኖሩንም ዕወቅ፡፡ ስለ ስህተትህም ለምእመናንም ምሕረትን ለምን፡፡ አላህም መዘዋወሪያችሁን፣ መርጊያችሁንም ያውቃል፡፡'),
('47:20', 87, 'እነዚያም ያመኑት ሰዎች (መታገል ያለባት) «ሱራ አትወርድም ኖሮአልን?» ይላሉ፡፡ የጠነከረችም ሱራ በተወረደችና በውስጧም መጋደል በተወሳ ጊዜ እነዚያን በልቦቻቸው ውስጥ (የንፍቅና) በሺታ ያለባቸውን ሰዎች ከሞት የኾነ መከራ በርሱ ላይ እንደ ወደቀበት ሰው አስተያየት ወዳንተ ሲመለከቱ ታያቸዋለህ፡፡ ለእነሱም ወዮላቸው፡፡'),
('47:21', 87, 'ታዛዥነትና መልካም ንግግር (ይሻላቸዋል) ትዕዛዙም ቁርጥ በኾነ ጊዜ ለአላህ (ትዕዛዝ) እውነተኞች በኾኑ ኖሮ ለእነርሱ የተሻለ በኾነ ነበር፡፡'),
('47:22', 87, 'ብትሽሾሙም በምድር ላይ ማበላሸትን ዝምድናችሁንም መቁረጥን ከጀላችሁን?'),
('47:23', 87, 'እነዚህ እነዚያ አላህ የረገማቸው፣ ያደነቆራቸውም፣ ዓይኖቻቸውንም ያወራቸው ናቸው፡፡'),
('47:24', 87, 'ቁርኣንንም አያስተነትኑምን? በእውነቱ በልቦቻቸው ላይ ቁልፎቿ አልሉባትን?'),
('47:25', 87, 'እነዚያ ለእነርሱ ቅኑ መንገድ ከተብራራላቸው በኋላ ወደ ኋላቸው የተመለሱት ሰይጣን ለእነርሱ መመለሳቸውን ሸለመላቸው፡፡ ለእነርሱም አዝዘናጋቸው፡፡'),
('47:26', 87, 'ይህ እነርሱ ለእነዚያ አላህ ያወረደውን ለጠሉት «በነገሩ ከፊል እንታዘዛችኋለን» ያሉ በመኾናቸው ነው፡፡ አላህም መደበቃቸውን ያውቃል፡፡'),
('47:27', 87, 'መላእክትም ፊቶቻቸውንና ጀርባዎቻቸውን የሚመቱ ሲኾኑ በገደሉዋቸው ጊዜ (ኹኔታቸው) እንዴት ይኾናል?'),
('47:28', 87, 'ይህ እነርሱ አላህን ያስቆጣውን ነገር ስለ ተከተሉ ውዴታውንም ስለ ጠሉ ነው፡፡ ስለዚህ ሥራዎቻቸውን አበላሸባቸው፡፡'),
('47:29', 87, 'እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው አላህ ቂሞቻቸውን አለማውጣቱን ጠረጠሩን?'),
('47:30', 87, 'በሻንም ኖሮ እነርሱን ባሳየንህና በምልክታቸውም በእርግጥ ባወቅሃቸው ነበር፡፡ ንግግርንም በማሸሞራቸው በእርግጥ ታውቃቸዋለህ፡፡ አላህም ሥራዎቻችሁን ያውቃል፡፡'),
('47:31', 87, 'ከእናንተም ታጋዮቹንና ታጋሾቹን እስከምናውቅ፣ ወሬዎቻችሁንም እስከምንገልጽ ድረስ በእርግጥ እንሞክራችኋለን፡፡'),
('47:32', 87, 'እነዚያ የካዱና ከአላህም መንገድ ያገዱ ለእነርሱም ቅኑ መንገድ ከተገለጸላቸው በኋላ መልክተኛውን የተከራከሩ አላህን በምንም አይጎዱትም፡፡ ሥራዎቻቸውንም በእርግጥ ያበላሻል፡፡'),
('47:33', 87, 'እናንተ ያመናችሁ ሆይ! አላህን ተገዙ፡፡ መልክተኛውንም ታዘዙ፡፡ ሥራዎቻችሁንም አታበላሹ፡፡'),
('47:34', 87, 'እነዚያ የካዱ፣ ከአላህም መንገድ ያገዱ፣ ከዚያም እነርሱ ከሓዲዎች ኾነው የሞቱ አላህ ለእነርሱ በፍጹም አይምርም፡፡'),
('47:35', 87, 'እናንተም አሸናፊዎቹ ስትኾኑ አላህ ከእናንተ ጋር ሲሆን አትድከሙ፡፡ ወደ ዕርቅም አትጥሩ፡፡ ሥራዎቻችሁንም ፈጽሞ አያጎድልባችሁም፡፡'),
('47:36', 87, 'ቅርቢቱ ሕይወት ጫወታና ዛዛታ ብቻ ናት፡፡ ብታምኑም ብትጠነቀቁም ምንዳዎቻችሁን ይሰጣችኋል፡፡ ገንዘቦቻችሁንም (ሁሉ) አይጠይቃችሁም፡፡'),
('47:37', 87, 'እርሷን ቢጠይቃችሁና ችክ ቢልባችሁ ትሰስታላችሁ፡፡ ቂሞቻችሁንም ያወጣል፡፡'),
('47:38', 87, 'ንቁ! እናንተ እነዚያ በአላህ መንገድ ትለግሱ ዘንድ የምትጥጠሩ ናችሁ፡፡ ከእናንተም ውስጥ የሚሰስት ሰው አልለ፡፡ የሚሰስትም ሰው የሚሰስተው በራሱ ላይ ብቻ ነው፡፡ አላህም ከበርቴ ነው፡፡ እናንተም ድኾች ናችሁ፡፡ ብትሸሹም ሌሎችን ሕዝቦች ይለውጣል፡፡ ከዚያም (ባለመታዘዝ) ብጤዎቻችሁ አይኾኑም፡፡'),
('48:1', 87, 'እኛ ላንተ ግልጽ የኾነን መክፈት ከፈትንልህ፡፡'),
('48:2', 87, 'አላህ ከኃጢአትህ ያለፈውንና የሚመጣውን ላንተ ሊምር ጸጋውንም ባንተ ላይ ሊሞላ ቀጥተኛውንም መንገድ ሊመራህ (ከፈተልህ)፡፡'),
('48:3', 87, 'አላህ ብርቱን እርዳታ ሊረዳህም (ከፈተልህ)፡፡'),
('48:4', 87, 'እርሱ ያ በምእምናን ልቦች ውስጥ ከእምነታቸው ጋር እምነትን ይጨምሩ ዘንድ እርጋታን ያወረደ ነው፡፡ ለአላህም የሰማያትና የምድር ሰራዊቶች አልሉት፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('48:5', 87, 'ምእምናንንና ምእምናትን ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲኾኑ ሊያገባቸው ከነርሱም ኃጢአቶቻቸውን ሊያብስላቸው (በትግል አዘዛቸው)፡፡ ይህም ከአላህ ዘንድ የኾነ ታላቅ ማግኘት ነው፡፡'),
('48:6', 87, 'በአላህም ክፉ ጥርጣሬን ተጠራጣሪዎቹን መናፍቃንና መናፍቃትን፣ ወንዶች አጋሪዎቻችንና ሴቶች አጋሪዎችንም ያሰቃይ ዘንድ (በትግል አዘዘ)፡፡ በእነርሱ ላይ ክፉ ከባቢ አለባቸው፡፡ በእነርሱም ላይ አላህ ተቆጣባቸው፡፡ ረገማቸውም፡፡ ለእነርሱም ገሀነምን አዘጋጀላቸው፡፡ መመለሻነትዋም ከፋች፡፡'),
('48:7', 87, 'ለአላህም የሰማያትና የምድር ሰራዊቶች አልሉት፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('48:8', 87, 'እኛ መስካሪ አብሳሪና አስፈራሪም አድርገን በእርግጥ ላክንህ፡፡'),
('48:9', 87, 'በአላህ ልታምኑ፣ በመልክተኛውም (ልታምኑ)፣ ልትረዱትም፣ ልታከብሩትም፣ (አላህን) በጧትና ከቀትር በኋላ ልታወድሱትም (ላክነው)፡፡'),
('48:10', 87, 'እነዚያ ቃል ኪዳን የሚጋቡህ ቃል ኪዳን የሚጋቡት አላህን ብቻ ነው፡፡ የአላህ እጅ (ኀይሉ) ከእጆቻቸው በላይ ነው፡፡ ያፈረሰም ሰው የሚያፈርሰው በነፍሱ ላይ ብቻ ነው፡፡ በእርሱ ላይ አላህን ቃል ኪዳን የተጋባበትን የሞላም ሰው ታላቅ ምንዳን በእርግጥ ይሰጠዋል፡፡'),
('48:11', 87, 'ከአዕራብ ሰዎች እነዚያ (ከዘመቻ) ወደ ኋላ የቀሩት ለአንተ «ገንዘቦቻችንና ቤተሰቦቻችን አስቸገሩን፤ ስለዚህ ምሕረትን ለምንልን፤» ይሉሃል፡፡ በልቦቻቸው ውስጥ የሌለውን ነገር በምላሶቻቸው ይናገራሉ፡፡ (አላህ) «በእናንተ ላይ ጉዳትን ቢሻ ወይም በእናንተ መጥቀምን ቢሻ ከአላህ (ለማገድ) ለእናንተ አንዳችን የሚችል ማነው? በእውነቱ አላህ፤በምትሠሰሩት ሁሉ ውስጥ ዐዋቂ ነው» በላቸው፡፡'),
('48:12', 87, 'ይልቁንም መልክተኛውና ምእመናኖቹ ወደ ቤተሰቦቻቸው ፈጽሞ አለመመለሳቸውን ጠረጠራችሁ፡፡ ይህም በልቦቻችሁ ውስጥ ተሸለመላችሁ፡፡ መጥፎንም መጠርጠር ጠረጠራችሁ፡፡ ጠፊዎች ሕዝቦችም ኾናችሁ፡፡'),
('48:13', 87, 'በአላህና በመልክተኛው ያላመነም ሰው እኛ ላከሓዲዎች እሳትን አዘጋጅተናል፡፡'),
('48:14', 87, 'የሰማያትና የምድር ንግሥናም የአላህ ነው፡፡ ለሚሻው ሰው ይምራል፤ የሚሻውንም ይቀጣል፡፡ አላህም መሓሪ አዛኝ ነው፡፡'),
('48:15', 87, 'ወደ ዘረፋዎች ልትይዟት በኼዳችሁ ጊዜ እነዚያ ወደ ኋላ የቀሩት ሰዎች «ተዉን እንከተላችሁ» ይሏችኋል፡፡ (በዚህም) የአላህን ቃል ሊለውጡ ይፈልጋሉ፡፡ «ፈጽሞ አትከተሉንም፡፡ ይህን (ቃል) ከዚህ በፊት አላህ ብሏል» በላቸው፡፡ ይልቁንም «ትመቀኙናላችሁ» ይላሉም፡፡ በእውነት እነርሱ ጥቂትን እንጅ የማያውቁ ነበሩ፡፡'),
('48:16', 87, 'ከአዕራቦች ወደ ኋላ ለቀሩት በላቸው፡- «የብርቱ ጭካኔ ባለቤት ወደ ኾኑ ሕዝቦች (ውጊያ) ወደ ፊት ትጥጠራላችሁ፡፡ ትጋደሏቸዋላችሁ፤ ወይም ይሰልማሉ፡፡ ብትታዘዙም አላህ መልካም ምንዳን ይሰጣችኋል፡፡ ከአሁን በፊት እንደ ሸሻችሁ ብትሸሹም አሳማሚን ቅጣት ይቀጣችኋል፡፡»'),
('48:17', 87, 'በዕውር ላይ (ከዘመቻ በመቅቱ) ኃጢአት የለበትም፡፡ በአንካሳም ላይ ኃጢአት የለበትም፡፡ በበሽተኛም ላይ ኃጢአት የለበትም፡፡ አላህንና መልክተኛውንም የሚታዘዝ ሰው ከሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች ያገባዋል፡፡ የሚሸሸውንም ሰው አሳማሚውን ቅጣት ይቀጣዋል፡፡'),
('48:18', 87, 'ከምእምናኖቹ በዛፊቱ ሥር ቃል ኪዳን በሚጋቡህ ጊዜ አላህ በእርግጥ ወደደ፡፡ በልቦቻቸውም ውስጥ ያለውን ዐወቀ፡፡ በእነርሱም ላይ እርጋታን አወረደ፡፡ ቅርብ የኾነንም መክፈት መነዳቸው፡፡'),
('48:19', 87, 'ብዙዎች ዘረፋዎችንም የሚወስዷቸው የኾኑን (መነዳቸው)፡፡ አላህም አሸናፊ ጥበበኛ ነው፡፡'),
('48:20', 87, 'አላህ ብዙዎችን ዘረፋዎች የምትወስዷቸው የኾኑን ተስፋ አደረገላችሁ፡፡ ይህችንም ለእናንተ አስቸኮለላችሁ፡፡ ከእናንተም የሰዎችን እጆች ከለከለላችሁ፡፡ (ልታመሰግኑትና) ለምእምናንም ምልክት እንድትኾን ቀጥተኛውን መንገድ ይመራችሁም ዘንድ (ይህንን ሠራላችሁ)፡፡'),
('48:21', 87, 'ሌላይቱንም በእርሷ ላይ ገና ያልቻላችኋትን አላህ ያወቃትን (ለእናንተ አዘጋጃት)፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡'),
('48:22', 87, 'እነዚያም የካዱት (የመካ ሰዎች በሑደይቢያ) በተወጉወችሁ ኖሮ ( ለሺሺት) ጀርባዎችን ባዞሩ ነበር፡፡ ከዚያም ዘመድም ረዳትም አያገኙም፡፡'),
('48:23', 87, 'አላህ ያችን ከዚህ በፊት በእርግጥ ያለፈችውን ልማድ ደነገገ፡፡ ለአላህም ልማድ ለውጥን አታገኝም፡፡'),
('48:24', 87, 'እርሱም ያ በመካ ውስጥ በእነርሱ ላይ ካስቻለችሁ በኋላ እጆቻቸውን ከእናንተ ላይ እጆቻችሁንም ከእነርሱ ላይ የከለከለ ነው፡፡ አላህም የምትሠሩትን ሁሉ ተመልካች ነው፡፡'),
('48:25', 87, 'እነርሱ እነዚያ የካዱ፣ ከተከበረው መስጊድም የከለከሏችሁ፣ መስዋእቱንም የታሰረ ሲኾን በስፍራው እንዳይደርስ (የከለከሉ) ናቸው፡፡ የማታውቋቸው የኾኑ ምእመናን ወንዶችና ምእምናት ሴቶች (ከከሓዲዎቹ ጋር) ባልነበሩ ያለ ዕውቀት እነርሱን መርገጣችሁና ከእነረሱ (በኩል) መከፋት የሚነካችሁ ባልኾነ ኖሮ (እጆቻችሁን ባላገድን ነበር) አላህ የሚሻውን ሰው በእዝነቱ ውስጥ ያገባ ዝንድ (እጆቻችሁን አገደ)፡፡ በተለዩ ኖሮ እነዚያን ከእነርሱ ውስጥ የካዱትን አሳማሚን ቅጣት በቀጣናቸው ነበር፡፡'),
('48:26', 87, 'እነዚያ የካዱት ደራይቱን የመሀይምነቲቱን ደራ በልቦቻቸው ውስጥ ባደረጉ ጊዜ (በቀጣናቸው ነበር)፡፡ አላህም በመልክተኛው ላይና በምእምናኖቹ ላይ እርጋታውን አወረደ፡፡ መጥጠበቂያይቱንም ቃል አስያዛቸው፡፡ በእርሷም ተገቢዎች ባለቤቶችዋም ነበሩ፡፡ አላህም በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('48:27', 87, 'አላህ ለመልክተኛው ሕልሙን እውነተኛ ሲኾን አላህ የሻ እንደ ኾነ ጸጥተኞች ኾናችሁ ራሶቻችሁን ላጭታችሁ፣ አሳጥራችሁም የማትፈሩ ስትኾኑ የተከበረውን መስጊድ በእርግጥ ትገባላችሁ፤ ያለውን በእርግጥ እውነት አደረገለት፡፡ (ከእርቁ) ያላወቃችሁትንም ነገር ዐወቀ፡፡ ከዚህም በፊት ቅርብን መክፈት አደረገ፡፡'),
('48:28', 87, 'እርሱ ያ መልክተኛውን በመሪ መጽሐፍና በእውነተኛ ሃይማኖት በሃይማኖት ሁሉ ላይ ሊያልቀው የላከ ነው፡፡ መስካሪም በአላህ በቃ፡፡'),
('48:29', 87, 'የአላህ መልክተኛ ሙሐመድ እነዚያም ከእርሱ ጋር ያሉት (ወዳጆቹ) በከሓዲዎቹ ላይ ብርቱዎች በመካከላቸው አዛኞች ናቸው፡፡ አጎንባሾች፣ ሰጋጆች ኾነው ታያቸዋለህ፡፡ ከአላህ ችሮታንና ውዴታን ይፈልጋሉ፡፡ ምልክታቸው ከስግደታቸው ፈለግ ስትኾን በፊቶቻቸው ላይ ናት፡፡ ይህ በተውራት (የተነገረው) ጠባያቸው ነው፡፡ በኢንጂልም ውስጥ ምሳሌያቸው ቀንዘሉን አንደአወጣ አዝመራና፣ (ቀንዘሉ) እንዳበረታው፣ እንደወፈረምና፣ ገበሬዎቹን የሚያስደንቅ ኾኖ በአገዳዎቹ ላይ ተስተካክሎ እንደ ቆመ (አዝመራ) ነው፡፡ (ያበረታቸውና ያበዛቸው) ከሓዲዎችን በእነርሱ ሊያስቆጭ ነው፡፡ አላህም እነዚያን ያመኑትንና ከእነርሱ በጎዎችን የሠሩትን ምሕረትንና ታላቅ ምንዳን ተስፋ አድርጎላቸዋል፡፡'),
('49:1', 87, 'እናንተ ያመናችሁ ሆይ! በአላህና በመልክተኛው ፊት (ነፍሶቻችሁን) አታስቀድሙ፡፡ አላህንም ፍሩ፡፡ አላህ ሰሚ ዐዋቂ ነውና፡፡'),
('49:2', 87, 'እናንተ ያመናችሁ ሆይ! ድምጾቻችሁን ከነቢዩ ድምጽ በላይ ከፍ አታድርጉ፡፡ ከፊላችሁም ለከፊሉ እንደሚጮህ በንግግር ለርሱ አትጩሁ፡፡ እናንተ የማታውቁ ስትኾኑ ሥራዎቻችሁ እንዳይበላሹ (ተከልከሉ)፡፡'),
('49:3', 87, 'እነዚያ በአላህ መልክተኛ ዘንድ ድምጾቻቸውን ዝቅ የሚያደርጉ እነዚህ እነዚያ አላህ ልቦቻቸውን ለፍርሃት የፈተናቸው ናቸው፡፡ ለእነርሱም ምሕረትና ታላቅ ምንዳ አላቸው፡፡'),
('49:4', 87, 'እነዚያ ከክፍሎቹ ውጭ ኾነው የሚጠሩህ አብዛኞቻቸው አያውቁም፡፡'),
('49:5', 87, 'ወደእነርሱም እስክትወጣ ድረስ እነርሱ በታገሱ ኖሮ ለእነርሱ በላጭ በኾነ ነበር፡፡ አላህም እጅግ መሓሪ አዛኝ ነው፡፡'),
('49:6', 87, 'እላንተ ያመናችሁ ሆይ! ነገረኛ ወሬን ቢያመጣላችሁ በስህተት ላይ ኾናችሁ ሕዝቦችን እንዳትጎዱና በሠራችሁት ነገር ላይ ተጸጸቾች እንዳትኾኑ አረጋግጡ፡፡'),
('49:7', 87, 'በውስጣችሁም የአላህ መልክተኛ መኖሩን ዕወቁ፡፡ ከነገሩ በብዙው ቢከተላችሁ ኖሮ በእርግጥ በተቸገራችሁ ነበር፡፡ ግን አላህ አምነትን ወደናንተ አስወደደ፡፡ በልቦቻችሁም ውሰጥ አጌጠው፡፡ ክህደትንና አመጽንም እንቢተኛነትንም ወደናንተ የተጠላ አደረገ፡፡ እነዚያ (እምነትን የወደዱና ክሕደተን የጠሉ) እነርሱ ቅኖቹ ናቸው፡፡'),
('49:8', 87, 'ከአላህ በኾነው ችሮታና ጸጋ (ቅኖች ናቸው)፡፡ አላህም ዐዋቂ ጥበበኛ ነው፡፡'),
('49:9', 87, 'ከምዕምናንም የኾኑ ሁለት ጭፍሮች ቢጋደሉ በመካከላቸው አስታርቁ፡፡ ከሁለቱ አንደኛይቱም በሌላይቱ ላይ ወሰን ብታልፍ ያችን ወሰን የምታልፈውን ወደ አላህ ትዕዛዝ እስከምትመለስ ድረስ ተጋደሉ፡፡ ብትመለስም በመካከላቸው በትክክል አስታርቁ፡፡ በነገሩ ሁሉ አስተካክሉም፡፡ አላህ አስተካካዮችን ይወዳልና፡፡'),
('49:10', 87, 'ምእመናኖች ወንድማመቾች ናቸው፡፡ በሁለት ወንድሞቻችሁም መካከል አስታርቁ፡፡ ይታዘንላችሁም ዘንድ አላህን ፍሩ፡፡'),
('49:11', 87, 'እናንተ ያመናችሁ ሆይ! ወንዶች ከወንዶች አይቀልዱ፡፡ ከእነርሱ የበለጡ ሊኾኑ ይከጀላልና፡፡ ሴቶችም ከሴቶች (አይሳለቁ)፡፡ ከእነርሱ የበለጡ ሊኾኑ ይከጀላልና፡፡ ነፍሶቻችሁንም አታነውሩ፡፡ በመጥፎ ስሞችም አትጠራሩ፡፡ ከእምነት በኋላ የማመጽ ስም ከፋ፡፡ ያልተጸጸተም ሰው እነዚያ እነርሱ በዳዮቹ ናቸው፡፡'),
('49:12', 87, 'እናንተ ያመናችሁ ሆይ! ከጥርጣሬ ብዙውን ራቁ፤ ከጥርጣሬ ከፊሉ ኃጢአት ነውና፡፡ ነውርንም አትከታተሉ፡፡ ከፊላችሁም ከፊሉን አይማ፡፡ አንደኛችሁ የወንድሙን ስጋ የሞተ ኾኖ ሊበላው ይወዳልን? (መብላቱን) ጠላችሁትም፤ (ሐሜቱንም ጥሉት)፡፡ አላህንም ፍሩ፡፡ አላህ ጸጸትን ተቀባይ አዛኝ ነውና፡፡'),
('49:13', 87, 'እናንተ ሰዎች ሆይ! እኛ ከወንድና ከሴት ፈጠርናችሁ፡፡ እንድትተዋወቁም ጎሳዎችና ነገዶች አደረግናችሁ፡፡ አላህ ዘንድ በላጫችሁ በጣም አላህን ፈሪያችሁ ነው፡፡ አላህ ግልጽን ዐዋቂ ውስጥንም ዐዋቂ ነው፡፡'),
('49:14', 87, 'የዐረብ ዘላኖች «አምነናል» አሉ፡፡ «አላመናችሁም፤ ግን ሰልመናል በሉ፡፡ «እምነቱም በልቦቻችሁ ውስጥ ገና (ጠልቆ) አልገባም፡፡ አላህንና መልክተኛውንም ብትታዘዙ ከሥራዎቻችሁ ምንንም አያጎድልባችሁም፡፡ አላህ መሓሪ አዛኝ ነውና» በላቸው፡፡'),
('49:15', 87, '(እውነተኛዎቹ) ምእምናን እነዚያ በአላህና በመልእከተኛው ያመኑት ከዚያም ያልተጠራጠሩት በገንዘቦቻቸውና በነፍሶ ቻቸውም በአላህ መንገድ የታገሉት ብቻ ናቸው፡፡ እነዚያ እነሱ እውነተኞቹ ናቸው፡፡'),
('49:16', 87, '«አላህ በሰማያት ውስጥ ያለውንና በምድር ውስጥ ያለውን ሁሉ የሚያውቅ ሲኾን አላህን በሃይማኖታችሁ ታስታውቁ ታላችሁን?» በላቸው፡፡ አላህም በነገሩ ሁሉ ዐዋቂ ነው፡፡'),
('49:17', 87, 'በመስለማቸው በአንተ ላይ ይመጻደቃሉ «በስልምናችሁ በኔ ላይ አትመጻደቁ፤ ይልቁንም አላህ ወደ እምነት ስለ መራችሁ ይመጸደቅባችኋል፤ እውነተኞች ብትኾኑ» (መመጻደቅ ለአላህ ነው) በላቸው፡፡'),
('49:18', 87, 'አላህ የሰማያትንና የምድርን ሩቅ ምሰጢር ያውቃል፤ አላህም የምትሰሩትን ሁሉ ተመልካች ነው፡፡'),
('50:1', 87, 'ቀ (ቃፍ) በተከበረው ቁርኣን እምላለሁ (በሙሐመድ አላመኑም)፡፡'),
('50:2', 87, 'ይልቁንም ከነሱ ጎሳ የኾነ አስፈራሪ ስለ መጣላቸው ተደነቁ፡፡ ከሓዲዎቹም «ይህ አስደናቂ ነገር ነው» አሉ፡፡'),
('50:3', 87, '«በሞትንና ዐፈር በኾን ጊዜ (እንመለሳለን?) ይህ ሩቅ የኾነ መመለስ ነው፤» (አሉ)፡፡'),
('50:4', 87, 'ከእነርሱ (አካል) ምድር የምታጎድለውን በእርግጥ ዐውቀናል፡፡ እኛም ዘንድ ጠባቂ መጽሐፍ አልለ፡፡'),
('50:5', 87, '(አልተመለከቱም)፡፡ ይልቁንም በቁርኣን በመጣላቸው ጊዜ አስተባበሉ፡፡ እነርሱም በተማታ ነገር ውሰጥ ናቸው፡፡'),
('50:6', 87, 'ወደ ሰማይም ከበላያቸው ስትኾን ለእርሷ ምንም ቀዳዳዎች የሌሏት ኾና እንዴት እንደ ገነባናትና (በከዋክብት) እንዳጌጥናት አልተመለከቱምን?'),
('50:7', 87, 'ምድርንም ዘረጋናት፡፡ በእርሷም ውስጥ ጋራዎችን ጣልንባት፡፡ በውስጧም ከሚያስደስት ዓይነት ሁሉ አበቀልን፡፡'),
('50:8', 87, '(ይህንን ያደረግነው) ተመላሽ ለኾነ ባሪያ ሁሉ ለማሳየትና ለማስገንዘብ ነው፡፡'),
('50:9', 87, 'ከሰማይም ብሩክን ውሃ አወረድን፡፡ በእርሱም አትክልቶችንና የሚታጨድን (አዝመራ) ፍሬ አበቀልን፡፡'),
('50:10', 87, 'ዘምባባንም ረዣዢም ለእርሷ የተደራረበ እንቡጥ ያላት ስትኾን (አበቀልን)፡፡'),
('50:11', 87, 'ለባሮቹ ሲሳይ ትኾን ዘንድ (አዘጋጀናት)፡፡ በእርሱም የሞተችን አገር ሕያው አደረግንበት፡፡ (ከመቃብር) መውጣትም እንደዚሁ ነው፡፡'),
('50:12', 87, 'ከእነርሱ በፊት የኑሕ ሕዝቦችና የረሰስ ሰዎች፤ ሰሙድም አስተባበሉ፡፡'),
('50:13', 87, 'ዓድም ፈርዖንም፤ የሉጥ ወንድሞችም፤'),
('50:14', 87, 'የአይከት ሰዎችም የቱብበዕ ሕዝቦችም ሁሉም መልከተኞቹን አስተባበሉ፡፡ ዛቻዬም ተረጋገጠባቸው፡፡'),
('50:15', 87, 'በፊተኛው መፍጠር ደከምን? በእውነቱ እነርሱ ከአዲስ መፍጠር በመጠራጠር ውስጥ ናቸው፡፡'),
('50:16', 87, 'ሰውንም ነፍሱ (በሐሳቡ) የምታጫውተውን የምናውቅ ስንኾን በእርግጥ ፈጠርነው፤ እኛም ከደም ጋኑ ጅማት ይበልጥ ወደርሱ ቅርብ ነን፡፡'),
('50:17', 87, 'ሁለቱ ቃል ተቀባዮች (መላእክት) ከቀኝና ከግራ ተቀማጮች ኾነው በሚቀበሉ ጊዜ (አስታውስ)፡፡'),
('50:18', 87, 'ከቃል ምንም አይናገርም በአጠገቡ ተጠባባቂና ዝግጁ የኾኑ (መላእክት) ያሉበት ቢኾን እንጅ፡፡'),
('50:19', 87, 'የሞትም መከራ እውነቱን ነገር ታመጣለች፡፡ (ሰው ሆይ)፡- «ይህ ያ ከርሱ ትሸሸው የነበርከው ነው» (ይባላል)፡፡'),
('50:20', 87, 'በቀንዱም ውስጥ ይንነፋል፡፡ ያ (ቀን) የዛቻው (መፈጸሚያ) ቀን ነው፡፡'),
('50:21', 87, 'ነፍስም ሁሉ ከእርሷ ጋር ነጂና መስካሪ ያለባት ኾና ትመጣለች፡፡'),
('50:22', 87, '«ከዚህ ነገር በእርግጥ በዝንጋቴ ውስጥ ነበርክ፡፡ ሺፋንህንም ካንተ ላይ ገለጥንልህ፡፡ ስለዚህ ዛሬ ዓይንህ ስለታም ነው» (ይባላል)፡፡'),
('50:23', 87, 'ቁራኛውም (መልአክ) «ይህ ያ እኔ ዘንድ ያለው ቀራቢ ነው» ይላል፡፡'),
('50:24', 87, '«ሞገደኛ ከሓዲን ሁሉ በገሀነም ውስጥ ጣሉ፡፡»'),
('50:25', 87, '«ለበጎ ሥራ ከልካይ፣ በዳይ፣ ተጠራጣሪ የኾነን ሁሉ፤» (ጣሉ)፡፡'),
('50:26', 87, '«ያንን ከአላህ ጋር ሌላን አምላክ ያደረገውን በብርቱ ቅጣት ውስጥ ጣሉት፤» (ይባላል)፡፡'),
('50:27', 87, 'ቁራኛው (ሰይጣን) «ጌታችን ሆይ! እኔ አላሳሳትኩትም፡፡ ግን (ራሱ) በሩቅ ስሕተት ውስጥ ነበር» ይላል፡፡'),
('50:28', 87, '(አላህ) «ወደእናንተ ዛቻን በእርግጥ ያስቀደምኩ ስኾን እኔ ዘንድ አትጨቃጨቁ» ይላቸዋል፡፡'),
('50:29', 87, '«ቃሉ እኔ ዘንድ አይለወጥም፡፡ እኔም ለባሮቼ ፈጽሞ በዳይ አይደለሁም» (ይላቸዋል)፡፡'),
('50:30', 87, 'ለገሀነም «ሞላሽን? የምንልበትንና ጭማሪ አለን? የምትልበትን ቀን» (አስጠንቅቃቸው)፡፡'),
('50:31', 87, 'ገነትም አላህን ለፈሩት እሩቅ ባልኾነ ስፍራ ትቅቀረባለች፡፡'),
('50:32', 87, '«ይህ ወደ አላህ ተመላሽና (ሕግጋቱን) ጠባቂ ለኾነ ሁሉ የተቀጠራችሁት ነው» (ይባላሉ)፡፡'),
('50:33', 87, '«አልረሕማንን በሩቁ ኾኖ ለፈራና በንጹሕ ልብ ለመጣ» (ትቅቀረባለች)፡፡'),
('50:34', 87, '«በሰላም ግቧት ይህ የመዘውተሪያ ቀን ነው» (ይባላሉ)፡፡'),
('50:35', 87, 'ለነርሱ በውስጧ ሲኾኑ የሚሹት ሁሉ አልላቸው፡፡ እኛም ዘንድ ጭማሪ አልለ፡፡'),
('50:36', 87, 'ከእነርሱም (ከቁረይሾች) በፊት ከክፍለ ዘመናት ሕዝቦች ብዙዎችን እነርሱ በኀያልነት ከእነርሱ ይበልጥ የበረቱ የኾኑትን (ማምለጫ ፍለጋ) በየአገሮቹም የመረመሩትን አጥፍተናል፡፡ ማምለጫ አለን?'),
('50:37', 87, 'በዚህ ውሰጥ ለእርሱ ልብ ላለው ወይም እርሱ (በልቡ) የተጣደ ኾኖ (ወደሚነበብለት) ጆሮውን ለጣለ ሰው ግሳጼ አለበት፡፡'),
('50:38', 87, 'ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ በስድስት ቀናት ውስጥ በእርግጥ ፈጠርን፡፡ ድካምም ምንም አልነካንም፡፡'),
('50:39', 87, 'በሚሉትም ላይ ታገሥ፤ ጌታህንም ከማመስገን ጋር ፀሐይ ከመውጣቷ በፊት ከመግባቷም በፊት አወድሰው፡፡'),
('50:40', 87, 'ከሌሊቱም አወድሰው ከስግደቶችም በኋላዎች (አወድሰው)፡፡'),
('50:41', 87, '(የሚነገርህን) አዳምጥም፡፡ ጠሪው ከቅርብ ስፍራ በሚጠራበት ቀን (ከመቃብራቸው ይወጣሉ)፡፡'),
('50:42', 87, 'ጩኸቲቱን በእውነት የሚሰሙበት ቀን ያ (ከመቃብር) የመውጫው ቀን ነው፡፡'),
('50:43', 87, 'እኛ እኛው ሕያው እናደርጋለን፡፡ እንገድላለንም፡፡ መመለሻም ወደእኛ ብቻ ነው፡፡'),
('50:44', 87, 'የሚፈጥኑ ኾነው ምድር ከእነርሱ ላይ የምትሰነጣጠቅበት ቀን (የመውጫው ቀን ነው)፡፡ ይህ በእኛ ላይ ገር የኾነ መሰብሰብ ነው፡፡'),
('50:45', 87, 'እኛ የሚሉትን ሁሉ ዐዋቂ ነን፡፡ አንተም በእነርሱ ላይ አስገዳጅ አይደለህም፡፡ ስለዚህ ዛቻየን የሚፈራን ሰው በቁርኣን አስታውስ፡፡'),
('51:1', 87, 'መበተንን በታኞች በኾኑት (ነፋሶች)፡፡'),
('51:2', 87, 'ከባድ (ዝናምን) ተሸካሚዎች በኾኑትም (ደመናዎች)፡፡'),
('51:3', 87, 'ገር (መንሻለልን) ተንሻላዮች በኾኑትም (መርከቦች)፡፡'),
('51:4', 87, 'ነገርን ሁሉ አከፋፋዮች በኾኑትም (መላእክት) እምላለሁ፡፡'),
('51:5', 87, 'የምትቀጠሩት (ትንሣኤ) እውነት ነው፡፡'),
('51:6', 87, '(እንደየሥራው) ዋጋን ማግኘትም፤ ኋኝ ነው፤ (የማይቀር ነው)፡፡'),
('51:7', 87, 'የ(ከዋክብት) መንገዶች ባለቤት በኾነችው ሰማይ እምላለሁ፡፡'),
('51:8', 87, 'እናንተ (የመካ ሰዎች) በተለያየ ቃል ውስጥ ናችሁ፡፡'),
('51:9', 87, 'ከርሱ የሚዝዞር ሰው ይዝዞራል፡፡'),
('51:10', 87, 'በግምት የሚናገሩ ውሸታሞች ተረገሙ፡፡'),
('51:11', 87, 'እነዚያ እነርሱ በሚሸፍን ስሕተተ ውስጥ ዘንጊዎች የኾኑት፡፡'),
('51:12', 87, 'የዋጋ መስጫው ቀን መቼ እንደ ኾነ ይጠይቃሉ፡፡'),
('51:13', 87, '(እነርሱ) በእሳት ላይ በሚፈተኑበት ቀን ነው፡፡'),
('51:14', 87, '«መከራችሁን ቅመሱ፤ ይህ ያ በእርሱ ትቻኮሉበት የነበራችሁት ነው» (ይባላሉ)፡፡'),
('51:15', 87, 'አላህን ፈሪዎቹ በአትክልቶችና በምንጮች ውስጥ ናቸው፡፡'),
('51:16', 87, 'ያንን ጌታቸው የሰጣቸውን ተቀባዮች ኾነው፤ (በገነት ውስጥ ይኾናሉ)፡፡ እነርሱ ከዚህ በፊት መልካም ሰሪዎች ነበሩና፡፡'),
('51:17', 87, 'ከሌሊቱ ጥቂትን ብቻ ይተኙ ነበሩ፡፡'),
('51:18', 87, 'በሌሊቱ መጨረሻዎችም እነርሱ ምሕረትን ይለምናሉ፡፡'),
('51:19', 87, 'በገንዘቦቻቸውም ውስጥ ለለማኝና (ከልመና) ለተከለከለም (በችሮታቸው) መብት አልለ፡፡'),
('51:20', 87, 'በምድርም ውስጥ ለሚያረጋግጡ ሰዎች ምልክቶች አልሉ፡፡'),
('51:21', 87, 'በነፍሶቻችሁም ውስጥ (ምልክቶች አልሉ)፤ ታዲያ አትመለከቱምን?›'),
('51:22', 87, 'ሲሳያችሁም የምትቀጠሩትም (ፍዳና ምንዳ) በሰማይ ውስጥ ነው፡፡'),
('51:23', 87, 'በሰማይና በምድር ጌታም እምላለሁ፡፡ እርሱ እናንተ እንደምትናገሩት ብጤ እርግጠኛ ነው፡፡'),
('51:24', 87, 'የተከበሩት የኢብራሂም እንግዶች ወሬ መጥቶሃልን?'),
('51:25', 87, 'በእርሱ ላይ በገቡና «ሰለም» ባሉ ጊዜ (አስታውስ)፡፡ «ሰላም ያልታወቃችሁ ሕዝቦች ናችሁ፤» አላቸው፡፡'),
('51:26', 87, 'ወደ ቤተሰቡም ተዘነበለ፤» ወዲያውም የሰባ ወይፈንን አመጣ፡፡'),
('51:27', 87, 'ወደእነርሱም (አርዶና ጠብሶ) አቀረበው፡፡ «አትበሉም ወይ?» አላቸው፡፡'),
('51:28', 87, 'ከእነርሱ መፍራትንም በልቡ አሳደረ፡፡ «አትፍራ» አሉት፡፡ በዐዋቂ ወጣት ልጅም አበሰሩት፡፡'),
('51:29', 87, 'ሚስቱም እየጮኸች መጣች፡፡ ፊቷንም መታች፡፡ «መካን አሮጊት ነኝ» አለችም፡፡'),
('51:30', 87, 'እንደዚህ ጌታሽ ብሏል፡፡ «እነሆ እርሱ ጥበባ ዐዋቂ ነውና» አሏት፡፡'),
('51:31', 87, '«እናንተ መልክተኞች ሆይ! ታዲያ ነገራችሁ ምንድን ነው?» አላቸው፡፡'),
('51:32', 87, '(እነርሱም) አሉ፡- «እኛ ወደ አመጸኞች ሕዝቦች ተልከናል፡፡»'),
('51:33', 87, 'በእነርሱ ላይ ከጭቃ የኾኑን ድንጋዮች ልንለቅባቸው (ተላክን)፡፡'),
('51:34', 87, 'በጌታህ ዘንድ ለድንበር አላፊዎቹ (በየስማቸው) ምልክት የተደረገባት ስትኾን፡፡'),
('51:35', 87, 'ከምእምናንም፤ በእርሷ (በከተማቸው) ውስጥ የነበሩትን አወጣን፡፡'),
('51:36', 87, 'በውስጧም ከሙስሊሞች ከአንድ ቤት (ቤተሰቦች) በስተቀር አላገኘንም፡፡'),
('51:37', 87, 'በውስጧም ለእነዚያ አሳማሚውን ቅጣት ለሚፈሩት ምልክትን አስቀረን፡፡'),
('51:38', 87, 'በሙሳም (ወሬ) ውስጥ ወደ ፈርዖን በግልጽ ማስረጃ በላክነው ጊዜ (ምልክትን አደረግን)፡፡'),
('51:39', 87, 'ከድጋፉ (ከሰራዊቱ) ጋርም (ከእምነት) ዞረ፡፡ (እርሱ) «ድግምተኛ ወይም ዕብድ ነው» አለም፡፡'),
('51:40', 87, 'እርሱንም ሰራዊቱንም ያዝናቸው፡፡ እርሱ ተወቃሽ ሲኾን በባሕር ውስጥም ጣልናቸው፡፡'),
('51:41', 87, 'በዓድም በእነርሱ ላይ መካንን ነፋስ በላክን ጊዜ (ምልክት አልለ)፡፡'),
('51:42', 87, 'በላዩ ላይ የመጣችበትን ማንኛውንም ነገር እንደ በሰበሰ አጥንት ያደረገችው ብትኾን እንጂ አትተወውም፡፡'),
('51:43', 87, 'በሰሙድም ለእነርሱ «እስከ ጊዜ (ሞታችሁ) ድረስ ተጣቀሙ» በተባሉ ጊዜ (ምልክት አልለ)፡፡'),
('51:44', 87, 'ከጌታቸው ትዕዛዝም ኮሩ፡፡ እነርሱም እያዩ ጩኸት ያዘቻቸው፡፡'),
('51:45', 87, 'መቆምንም ምንም አልቻሉም፡፡ የሚርረዱም አልነበሩም፡፡'),
('51:46', 87, 'የኑሕንም ሕዝቦች ከዚህ በፊት (አጠፋን)፡፡ እነርሱ አመጸኞች ሕዝቦች ነበሩና፡፡'),
('51:47', 87, 'ሰማይንም በኀይል ገነባናት፡፡ እኛም በእርግጥ ቻዮች ነን፡፡'),
('51:48', 87, 'ምድርንም ዘረጋናት፡፡ ምን ያማርንም ዘርጊዎች (ነን!)'),
('51:49', 87, 'ትገነዘቡም ዘንድ ከነገሩ ሁሉ ሁለት (ተቃራኒ) ዓይነትን ፈጠርን፡፡'),
('51:50', 87, '«ወደ አላህም ሽሹ፤ እኔ ለእናንተ ከርሱ ግልጽ አስጠንቃቂ ነኝና» (በላቸው)፡፡'),
('51:51', 87, 'ከአላህም ጋር ሌላን አምላክ አታድርጉ፡፡ እኔ ለእናንተ ከእርሱ (የተላክሁ) ግልጽ አስፈራሪ ነኝና፡፡'),
('51:52', 87, '(ነገሩ) እንደዚሁ ነው፡፡ እነዚያን ከእነርሱ በፊት የነበሩትን ከመልክተኛ ማንም አልመጣቸውም፡፡ (እርሱ) «ድግምተኛ ወይም ዕብድ ነው» ያሉ ቢኾኑ እንጂ፡፡'),
('51:53', 87, 'በእርሱ (በዚህ ቃል) አደራ ተባብለዋልን? አይደለም፤ እነርሱ ጥጋበኞች ሕዝቦች ናቸው፡፡'),
('51:54', 87, 'ከእነርሱም (ክርክር) ዘወር በል፤ (ተዋቸው)፡፡ አንተ ምንም ተወቃሽ አይደለህምና፡፡'),
('51:55', 87, 'ገሥጽም፤ ግሣጼ ምእመናንን ትጠቅማለችና፡፡'),
('51:56', 87, 'ጋኔንንና ሰውንም ሊግገዙኝ እንጅ ለሌላ አልፈጠርኳቸውም፡፡'),
('51:57', 87, 'ከነርሱም ምንም ሲሳይ አልፈልግም፡፡ ሊመግቡኝም አልሻም፡፡'),
('51:58', 87, 'አላህ እርሱ ሲሳይን ሰጪ የብርቱ ኀይል ባለቤት ነው፡፡'),
('51:59', 87, 'ለእነዚያም ለበደሉት እንደ ጓደኞቻቸው ፋንታ ብጤ (የቅጣት) ፋንታ አልላቸው፡፡ ስለዚህ አያስቸኩሉኝ፡፡'),
('51:60', 87, 'ለነዚያም ለካዱት ከዚያ ከሚቀጠሩት ቀናቸው ወዮላቸው፡'),
('52:1', 87, 'በጡር (ጋራ) እምላለሁ፡፡'),
('52:2', 87, 'በተጻፈው መጽሐፍም፡፡'),
('52:3', 87, 'በተዘረጋ ብራና ላይ፤ (በተጻፈው)፡፡'),
('52:4', 87, 'በደመቀው ቤትም፡፡'),
('52:5', 87, 'ከፍ በተደረገው ጣራም፡፡'),
('52:6', 87, 'በተመላው ባሕርም እምላለሁ፡፡'),
('52:7', 87, 'የጌታህ ቅጣት በእርግጥ ወዳቂ ነው፤ (የማይቀር ነው)፡፡'),
('52:8', 87, 'ለእርሱ ምንም ገፍታሪ የለውም፡፡'),
('52:9', 87, 'ሰማይ ብርቱ መዞርን በምትዞርበት ቀን (ይኾናል)፡፡'),
('52:10', 87, 'ተራራዎችም መኼድን በሚኼዱበት (ቀን)፡፡'),
('52:11', 87, 'ለአስተባባዮችም ያን ጊዜ ወዮላቸው፡፡'),
('52:12', 87, 'ለእነዚያ እነርሱ በውሸት ውስጥ የሚጫወቱ ለኾኑት፡፡'),
('52:13', 87, 'ወደ ገሀነም እሳት በኀይል መግገፍተርን በሚግገፈተሩበት ቀን፡፡'),
('52:14', 87, 'ይህቺ ያቺ በእርሷ ታስተባብሉባት የነበራችሁት እሳት ናት፡፡'),
('52:15', 87, 'ይህ (ፊት ትሉ እንደነበራችሁት) ድግምት ነውን? ወይስ እናንተ አታዩምን?'),
('52:16', 87, 'ግቧት ታገሱም ወይም አትታገሡ በእናንተ ላይ እኩል ነው፡፡ የምትምመነዱት ትሠሩት የነበራችሁትን (ፍዳ) ብቻ ነው (ይባላሉ)፡፡'),
('52:17', 87, 'አላህን ፈሪዎቹ በእርግጥ በገነቶችና በጸጋ ውስጥ ናቸው፡፡'),
('52:18', 87, 'ጌታቸው በሰጣቸው ጸጋ ተደሳቾች ኾነው (በገነት ውስጥ ናቸው)፡፡ የገሀነምንም ስቃይ ጌታቸው ጠበቃቸው፡፡'),
('52:19', 87, '«ትሠሩት በነበራችሁት ምክንያት ተደሳቾች ኾናችሁ ብሉ፤ ጠጡም፤» (ይባላሉ)፡፡'),
('52:20', 87, 'በተደረደሩ አልጋዎች ላይ ተደጋፊዎች ኾነው (በገነት ይኖራሉ)፡፡ ዓይናማዎች በኾኑ ነጫጭ ሴቶችም እናጠናዳቸዋለን፡፡'),
('52:21', 87, 'እነዚያም ያመኑትና ዝርያቸውም በእምነት የተከተለቻቸው ዝርያቸውን በእነርሱ እናስጠጋለን፡፡ ከሥራቸውም ምንም አናጎድልባቸውም፡፡ ሰው ሁሉ በሠራው ሥራ ተያዢ ነው፡፡'),
('52:22', 87, 'ከሚሹትም ሁሉ እሸትንና ስጋን እንጨምርላቸዋለን፡፡'),
('52:23', 87, 'በውስጧ መጠጥን ይሰጣጣሉ፡፡ በውስጧ ውድቅ ንግግርና መውወንጀልም የለም፡፡'),
('52:24', 87, 'ለነርሱም የኾኑ ወጣቶች ልክ የተሸፈነ ሉል መስለው በእነርሱ ላይ (ለማሳለፍ) ይዘዋወራሉ፡፡'),
('52:25', 87, 'የሚጠያየቁ ኾነውም ከፊላቸው በከፊሉ ላይ ይዞራል፡፡'),
('52:26', 87, '«እኛ ፊት በቤተሰቦቻችን ውስጥ (ከቅጣት) ፈሪዎች ነበርን» ይላሉ፡፡'),
('52:27', 87, '«አላህም በእኛ ላይ ለገሰ፡፡ የመርዛም እሳት ቅጣትንም ጠበቀን፡፡'),
('52:28', 87, '«እኛ ከዚህ በፊት እንለምነው ነበርን፡፡ እነሆ እርሱ በጎ ዋይ አዛኝ ነውና» (ይላሉ)፡፡'),
('52:29', 87, '(ሰዎችን) አስታውስም፡፡ አንተም በጌታህ ጸጋ ምክንያት ጠንቋይም ዕብድም አይደለህም፡፡'),
('52:30', 87, 'ይልቁንም የሞትን አደጋ በእርሱ የምንጠባበቅበት የኾነ ባለ ቅኔ ነው ይላሉን?'),
('52:31', 87, '«ተጠባበቁ፤ እኔም ከእናንተ ጋር ከሚጠባበቁት ነኝ» በላቸው፡፡'),
('52:32', 87, 'አእምሮዎቻቸው በዚህ ያዟቸዋልን? አይደለም በእውነቱ እነርሱ ወሰን አላፊዎች ሕዝቦች ናቸው፡፡'),
('52:33', 87, 'ወይም «ቀጠፈው ይላሉን?» አይደለም፤ በእውነቱ አያምኑም፡፡'),
('52:34', 87, 'እውነተኞችም ቢኾኑ መሰሉ የኾነን ንግግር ያምጡ፡፡'),
('52:35', 87, 'ወይስ ያለ አንዳች (ፈጣሪ) ተፈጠሩን? ወይስ እነርሱ ፈጣሪዎች ናቸውን?'),
('52:36', 87, 'ወይስ ሰማያትንና ምድርን ፈጠሩን? አይደለም አያረጋግጡም፡፡'),
('52:37', 87, 'ወይስ የጌታህ ግምጃ ቤቶች እነርሱ ዘንድ ናቸውን? ወይስ እነርሱ አሸናፊዎች ናቸውን?'),
('52:38', 87, 'ወይስ ለእነርሱ በእርሱ ላይ (ከሰማይ) የሚያዳምጡበት መሰላል አላቸውን? አድማጫቸውም (ሰማሁ ቢል) ግልጽን አስረጅ ያምጣ፡፡'),
('52:39', 87, 'ወይስ ለእርሱ ሴቶች ልጆች አሉትን? ለእናንተም ወንዶች ልጆች አሏችሁን?'),
('52:40', 87, 'ወይስ ዋጋን ትጠይቃቸዋለህን? ስለዚህ እነርሱ ከዕዳው የተከበዱ ናቸውን?'),
('52:41', 87, 'ወይስ ሩቁ ምስጢር እነርሱ ዘንድ ነውን? ስለዚህ እነርሱ ይጽፋሉን?'),
('52:42', 87, 'ወይስ ተንኮልን (ባንተ) ይሻሉን? እነዚያም የካዱት እነርሱ በተንኮል ተሸናፊዎች ናቸው፡፡'),
('52:43', 87, 'ወይስ ለእነርሱ ከአላህ ሌላ አምላክ አላቸውን? አላህ ከሚያጋሩት ሁሉ ጠራ፡፡'),
('52:44', 87, 'ከሰማይም ቁራጭን (በእነርሱ ላይ) ወዳቂ ኾኖ ቢያዩ ኖሮ «ይህ የተደራረበ ደመና ነው» ይሉ ነበር፡፡'),
('52:45', 87, 'ያንንም በእርሱ የሚግገደሉበትን ቀናቸውን እስከሚገናኙ ድረስ ተዋቸው፡፡'),
('52:46', 87, 'ተንኮላቸው ከእነርሱ ምንንም የማይጠቅማቸውንና እነርሱም የማይርረዱበትን ቀን (እስከ ሚገናኙ ተዋቸው)፡፡'),
('52:47', 87, 'ለእነዚያ ለበደሉትም ከዚህ ሌላ ቅርብ ቅጣት አልላቸው፡፡ ግን አብዛኛዎቻቸው አያውቁም፡፡'),
('52:48', 87, 'ለጌታህ ፍርድም ታገሥ፡፡ አንተ በጥበቃችን ውስጥ ነህና፡፡ ጌታህንም በምትነሳ ጊዜ ከማመስገን ጋር አወድሰው፡፡'),
('52:49', 87, 'ከሌሊቱም አወድሰው፡፡ በከዋክብት መዳበቂያ ጊዜም (ንጋት ላይ አወድሰው)፡፡'),
('53:1', 87, 'በኮከብ እምላለሁ በወደቀ (በገባ) ጊዜ፡፡'),
('53:2', 87, 'ነቢያችሁ (ሙሐመድ) አልተሳሳተም፤ አልጠመመምም፡፡'),
('53:3', 87, 'ከልብ ወለድም አይናገርም፡፡'),
('53:4', 87, 'እርሱ (ንግግሩ) የሚወርረድ ራእይ እንጅ ሌላ አይደለም፡፡'),
('53:5', 87, 'ኀይሎቹ ብርቱው (መልአክ) አስተማረው፡፡'),
('53:6', 87, 'የዕውቀት ባለቤት የኾነው (አስተማረው፤ በተፈጥሮ ቅርጹ ኾኖ በአየር ላይ) ተደላደለም፡፡'),
('53:7', 87, 'እርሱ በላይኛው አድማስ ኾኖ፡፡'),
('53:8', 87, 'ከዚያም ቀረበ፤ ወረደም፡፡'),
('53:9', 87, '(ከእርሱ) የሁለት ደጋኖች ጫፍ ያህል ወይም (ከዚህ) ይበልጥ የቀረበ ኾነም፡፡'),
('53:10', 87, 'ወደ ባሪያውም (አላህ) ያወረደውን አወረደ፡፡'),
('53:11', 87, '(ነቢዩም በዓይኑ) ያየውን ልቡ አልዋሸም፡፡'),
('53:12', 87, 'ታዲያ በሚያየው ላይ ትከራከሩታላችሁን?'),
('53:13', 87, 'በሌላይቱም መውረድ ጊዜ በእርግጥ አይቶታል፡፡'),
('53:14', 87, 'በመጨረሻይቱ ቁርቁራ አጠገብ፤'),
('53:15', 87, 'እርሷ ዘንድ መኖሪያይቱ ገነት ያለች ስትኾን፡፡'),
('53:16', 87, 'ቁርቁራይቱን የሚሸፍን ነገር በሚሸፍናት ጊዜ (አየው)፡፡'),
('53:17', 87, 'ዓይኑ (ካየው) አልተዘነበለም፡፡ ወሰንም አላለፈም፡፡'),
('53:18', 87, 'ከጌታው ታምራቶች ታላላቆቹን በእርግጥ አየ፡፡'),
('53:19', 87, 'አል-ላትንና አል-ዑዛን አያችሁን?'),
('53:20', 87, 'ሦስተኛይቱንም አነስተኛዋን መናትን (አያችሁን? የምትግገዟቸው ኃይል አላቸውን?)'),
('53:21', 87, 'ለእናንተ ወንድ ለእርሱም ሴት (ልጅ) ይኖራልን?'),
('53:22', 87, 'ይህቺ ያን ጊዜ አድላዊ ክፍያ ናት፡፡'),
('53:23', 87, 'እነርሱ እናንተና አባቶቻችሁ (አማልክት ብላችሁ) የጠራችኋቸው ስሞች ብቻ እንጅ ምንም አይደሉም፡፡ አላህ በእርሷ (መግገዛት) ምንም ማስረጃ አላወረደም፡፡ ከጌታቸውም መምሪያ የመጣላቸው ሲኾኑ ጥርጣሬንና ነፍሶች የሚዘነበሉበትን እንጅ ሌላ አይከተሉም፡፡'),
('53:24', 87, 'ለሰው የተመኘው ሁሉ አለውን?'),
('53:25', 87, 'መጨረሻይቱም መጀመሪያይቱም (ዓለም) የአላህ ብቻ ናቸው፡፡'),
('53:26', 87, 'በሰማያት ውስጥ ካለ መልአክም ብዙዎች (ሊማለዱለት) ለሚሻውና ለሚወደው ሰው ከፈቀደ በኋላ ቢኾን እንጅ ምልጃቸው ምንም አትጠቅምም፡፡'),
('53:27', 87, 'እነዚያ በመጨረሻይቱ ዓለም የማያምኑት መላእክትን በሴት አጠራር ይጠራሉ፡፡'),
('53:28', 87, 'ለእነርሱም በእርሱ ምንም ዕውቀት የላቸውም፡፡ ጥርጣሬን እንጅ ሌላን አይከተሉም፡፡ ጥርጣሬም ከእውነት ምንም አያብቃቃም፡፡'),
('53:29', 87, 'ከግሣጼያችንም (ከቁርኣን) ከሸሸና አነስተኛይቱን ሕይወት እንጅ ሌላን ከማይሻ ሰው ዙር (ተወው)፡፡'),
('53:30', 87, 'ይህ (አነስተኛይቱን ሕይወት መምረጥ) ከዕውቀት ድካቸው ነው፡፡ ጌታህ እርሱ ከመንገዱ የተሳሳተውን በእርግጥ ዐዋቂ ነው፡፡ እርሱም የቀናውን ሰው ዐዋቂ ነው፡፡'),
('53:31', 87, 'በሰማያት ያለውና በምድር ያለው ሁሉ የአላህ ነው፡፡ እነዚያን ያጠፉትን በሠሩት ሊቀጣ እነዚያን ያሳመሩትንም በመልካሚቱ (ገነት) ሊመነዳ (የጠመመውንና የቀናውን ያውቃል)፡፡'),
('53:32', 87, '(እነርሱ) እነዚያ የኃጢኣትን ታላለቆችና አስጸያፊዎቹን የሚርቁ ናቸው፡፡ ግን ትናንሾቹ የሚማሩ ናቸው፡፡ ጌታህ ምሕረተ ሰፊ ነውና፡፡ ከምድር በፈጠራችሁ ጊዜ እናንተም በእናቶቻችሁ ሆዶች ውስጥ ሽሎች በኾናችሁ ጊዜ እርሱ በናንተ (ኹነታ) ዐዋቂ ነው፡፡ ነፍሶቻችሁንም አታወድሱ እርሱ የሚፈራውን ሰው ዐዋቂ ነው፡፡'),
('53:33', 87, 'ያንን (ከእምነት) የዞረውን አየህን?'),
('53:34', 87, 'ጥቂትን የሰጠውንና ያቋረጠውንም (አየህን?)'),
('53:35', 87, 'የሩቁ ምስጢር ዕውቀት እርሱ ዘንድ አልለን? ስለዚህ እርሱ ያያልን?'),
('53:36', 87, 'ይልቁንም በዚያ በሙሳ ጽሑፎች ውስጥ ባለው ነገር አልተነገረምን?'),
('53:37', 87, 'በዚያም (የታዘዘውን) በፈጸመው በኢብራሂም (ጽሑፎች ውስጥ ባለው አልተነገረምን?)'),
('53:38', 87, '(እርሱም ኃጢያት) ተሸካሚ ነፍስ የሌላይቱን ነፍስ ኃጢኣት አትሸከምም፡፡'),
('53:39', 87, 'ለሰውም ሁሉ የሠራው እንጅ ሌላ የለውም፡፡'),
('53:40', 87, 'ሥራውም ሁሉ ወደ ፊት ይታያል፡፡'),
('53:41', 87, 'ከዚያም ሙሉውን ምንዳ ይመነዳዋል፡፡'),
('53:42', 87, 'መጨረሻውም ወደ ጌታህ ብቻ ነው፡፡'),
('53:43', 87, 'እነሆ እርሱም አስሳቀ፣ አስለቀሰም፡፡'),
('53:44', 87, 'እነሆ እርሱም ገደለ፣ አስነሳም፡፡'),
('53:45', 87, 'እርሱም ሁለቱን ዓይነቶች ወንድንና ሴትን ፈጠረ፡፡'),
('53:46', 87, 'ከፍትወት ጠብታ (በማህጸን ውስጥ) በምትፈሰስ ጊዜ፡፡'),
('53:47', 87, 'የኋለኛይቱም ማስነሳት በእርሱ ላይ ነው፡፡'),
('53:48', 87, 'እነሆ እርሱም አከበረ፣ ጥሪተኛም አደረገ፡፡'),
('53:49', 87, 'እነሆ እርሱም የሺዕራ ጌታ ነው፡፡'),
('53:50', 87, 'እነሆ እርሱም የፊተኛይቱን ዓድ አጥፍቷል፡፡'),
('53:51', 87, 'ሰሙድንም (አጥፍቷል)፤ አላስቀረምም፡፡'),
('53:52', 87, 'በፊትም የኑሕን ሕዝቦች (አጥፍቷል)፡፡ እነርሱ በጣም በደለኞችና እጅግ የጠመሙ እነርሱ ነበሩና፡፡'),
('53:53', 87, 'የተገለበጠችውንም ከተማ ደፋ፡፡'),
('53:54', 87, 'ያለበሳትንም አለበሳት፡፡'),
('53:55', 87, 'ከጌታህም ጸጋዎች በየትኛው ትጠራጠራለህ?'),
('53:56', 87, 'ይህ ከፊተኞቹ አስፈራሪዎች (ጎሳ) የኾነ አስፈራሪ ነው፡፡'),
('53:57', 87, 'ቀራቢይቱ (ኅልፈተ ዓለም) ቀረበች፡፡'),
('53:58', 87, 'ለእርሷ ከአላህ ሌላ ገላጭ የላትም፡፡'),
('53:59', 87, 'ከዚህ ንግግር ትደነቃላችሁን?'),
('53:60', 87, 'ትስቃላችሁምን? አታለቅሱምን?'),
('53:61', 87, 'እናንተም ዘንጊዎች ናችሁ፡፡'),
('53:62', 87, 'ለአላህም ስገዱ ተገዙትም፡፡'),
('54:1', 87, 'ሰዓቲቱ (የትንሣኤ ቀን) ተቃረበች፤ ጨረቃም ተገመሰ፡፡'),
('54:2', 87, 'ተዓምርንም ቢያዩ (ከእምነት) ይዞራሉ፡፡ (ይህ) «ዘውታሪ ድግምት ነውም» ይላሉ፡፡'),
('54:3', 87, 'አስተባበሉም፡፡ ዝንባሌዎቻቸውንም ተከተሉ፡፡ ነገርም ሁሉ (ወሰን አለው)፤ ረጊ ነው፡፡'),
('54:4', 87, 'ከዜናዎችም በእርሱ ውስጥ መገሰጥ ያለበት ነገር በእርግጥ መጣላቸው፡፡'),
('54:5', 87, 'ሙሉ የኾነች ጥበብ (መጣቻቸው) ግን አስፈራሪዎቹ አያብቃቁም፡፡'),
('54:6', 87, 'ከነርሱም ዙር፡፡ ጠሪው (መልአክ) ወደ አስደንጋጭ ነገር የሚጠራበትን ቀን (አስታውስ)፡፡'),
('54:7', 87, 'ዓይኖቻቸው ያቀረቀሩ ኾነው፤ ፍጹም የተበተነ አንበጣ መስለው ከመቃብሮቹ ይወጣሉ፡፡'),
('54:8', 87, 'ወደ ጠሪው አንገቶቻቸውን ሳቢዎች ቸኳዮች ኾነው (ይወጣሉ)፡፡ ከሓዲዎቹ (ያን ጊዜ ምን ይላሉ?) «ይህ ብርቱ ቀን ነው» ይላሉ፡፡'),
('54:9', 87, 'ከእነርሱ በፊት የኑሕ ነገድ አስተባበለች፡፡ ባሪያችንንም (ኑሕን) አስተባበሉ፡፡ «ዕብድ ነውም» አሉ፡፡ ተገላመጠም፡፡'),
('54:10', 87, 'ጌታውንም «እኔ የተሸነፍኩ ነኝና እርዳኝ» ሲል ጠራ፡፡'),
('54:11', 87, 'ወዲያውም የሰማይን ደጃፎች በሚንቧቧ ውሃ ከፈትን፡፡'),
('54:12', 87, 'የምድርንም ምንጮች አፈነዳን፡፡ ውሃውም (የሰማዩና የምድሩ) በእርግጥ በተወሰነ ኹነታ ላይ ተገናኘ፡፡'),
('54:13', 87, 'ባለ ሳንቃዎችና ባለሚስማሮች በኾነችም ታንኳ ላይ ጫንነው፡፡'),
('54:14', 87, 'በጥበቃችን ስር ኾና ትንሻለላለች፡፡ ተክዶ ለነበረው ሰው ምንዳ (ይህንን ሠራን)፡፡'),
('54:15', 87, 'ተዓምር አድርገንም በእርግጥ ተውናት፡፡ ከተገሳጭም አልለን?'),
('54:16', 87, 'ቅጣቴና ማስጠንቀቂያዎቼም እንዴት ነበሩ?'),
('54:17', 87, 'ቁርኣንንም ለመገንዘብ በእርግጥ አገራነው፡፡ ተገንዛቢም አልለን?'),
('54:18', 87, 'ዓድ አስተባበለች፡፡ ቅጣቴና ማስጠንቀቂያዎቼም እንዴት ነበሩ!'),
('54:19', 87, 'እኛ በእነርሱ ላይ ዘወትር መናጢ በኾነ ቀን በኀይል የምትንሻሻ ነፋስን ላክንባቸው፡፡'),
('54:20', 87, 'ሰዎቹን ልክ ከሥሮቻቸው የተጎለሰሱ የዘንባባ ግንዶች መስለው (ከተደበቁበት) ትነቅላቸዋለች፡፡'),
('54:21', 87, 'ቅጣቴና ማስጠንቀቂያዎቼም እንዴት ነበሩ?'),
('54:22', 87, 'ቁርኣንንም ለማስታወስ በእርግጥ አገራነው፡፡ ተገሳጭም አልለን?'),
('54:23', 87, 'ሰሙድ በአስፈራሪዎቹ አስተባበለች፡፡'),
('54:24', 87, '«ከእኛ የኾነን አንድን ሰው እንከተለዋለን? እኛ ያን ጊዜ በስህተትና በዕብደት ውስጥ ነን» አሉ፡፡'),
('54:25', 87, '«ከኛ መካከል በእርሱ ላይ (ብቻ) ማስገንዘቢያ (ራእይ) ተጣለለትን? አይደለም እርሱ ውሸታም ኩሩ ነው» (አሉ)፡፡'),
('54:26', 87, 'ውሸታሙ ኩሩው ማን እንደኾነ ነገ በእርግጥ ያውቃሉ፡፡'),
('54:27', 87, 'እኛ ሴት ግመልን ለእነርሱ መፈተኛ ትኾን ዘንድ ላኪዎች ነን፡፡ ተጠባበቃቸውም፡፡ ታገስም፡፡'),
('54:28', 87, 'ውሃውንም በመካከላቸው የተከፈለ መኾኑን ንገራቸው፡፡ ከውሃ የኾነ ፋንታ ሁሉ (ተረኞቹ) የሚጣዱት ነው፡፡'),
('54:29', 87, 'ጓደኛቸውንም ጠሩ፡፡ ወዲያውም (ሰይፍን) ተቀበለ፡፡ ወጋትም፡፡'),
('54:30', 87, 'ቅጣቴና ማስጠንቀቂያዎቼም እንዴት ነበሩ?'),
('54:31', 87, 'እኛ በእነርሱ ላይ አንዲትን ጩኸት ላክንባቸው፡፡ ወዲያውም ከበረት አጣሪ (አጥር) እንደ ተሰባበረ ርግጋፊ ኾኑ፡፡'),
('54:32', 87, 'ቁርኣንንም ለመገንዘብ አገራነው፡፡ ተገሳጭም አልለን?'),
('54:33', 87, 'የሉጥ ሕዝብ በአስፈራሪዎቹ አስተባበለች፡፡'),
('54:34', 87, 'እኛ በእነርሱ ላይ ጠጠርን ያዘለች ነፋስን ላክን፡፡ የሉጥ ቤተሰቦች ብቻ ሲቀሩ (እነርሱንስ) በሌሊት መጨረሻ ላይ አዳንናቸው፡፡'),
('54:35', 87, 'ከእኛ በኾነ ጸጋ (አዳንናቸው)፡፡ እንደዚሁ ያመሰገነን ሰው እንመነዳለን፡፡'),
('54:36', 87, 'ብርቱይቱን አያያዛችንንም በእርግጥ አስጠነቀቃቸው፡፡ በማስጠንቀቂያዎቹም ተከራከሩ፡፡'),
('54:37', 87, 'ከእንግዶቹም እንዲያስመቻቸው ደጋግመው ፈለጉት፡፡ ወዲያውም ዓይኖቻቸውን አበስን፡፡ «ቅጣቴንና ማስጠንቀቂያዎቼንም ቅመሱ» (አልናቸው)፡፡'),
('54:38', 87, 'በማለዳም ዘውታሪ የኾነ ቅጣት በእርግጥ ማለደባቸው፡፡'),
('54:39', 87, '«ቅጣቴንና ማስጠንቀቂያዎቼንም ቅመሱ» (ተባሉ)፡፡'),
('54:40', 87, 'ቁርኣንንም ለመገንዘብ በእርግጥ አገራነው፡፡ ተገሳጭም አልለን?'),
('54:41', 87, 'የፈርዖንንም ቤተሰቦች ማስጠንቀቂያዎች በእርግጥ መጡዋቸው፡፡'),
('54:42', 87, 'በተዓምራቶቻችን በሁሏም አስተባበሉ፡፡ የብርቱ ቻይንም አያያዝ ያዝናቸው፡፡'),
('54:43', 87, 'ከሓዲዎቻችሁ ከእነዚህ በላጮች ናቸውን? ወይስ ለናንተ በመጽሐፎች ውስጥ (የተነገረ) ነፃነት አላችሁን?'),
('54:44', 87, 'ወይስ «እኛ የተረዳን ክምቹዎች ነን» ይላሉን?'),
('54:45', 87, 'ክምቹዎቹ በእርግጥ ድል ይምመታሉ፡፡ ጀርባዎችንም ያዞራሉ፡፡'),
('54:46', 87, 'ይልቁንም ሰዓቲቱ (ትንሣኤ) ቀጠሮዋቸው ናት፡፡ ሰዓቲቱም በጣም የከበደችና የመረረች ናት፡፡'),
('54:47', 87, 'አመጸኞች በስህተትና በእሳቶች ውስጥ ናቸው፡፡'),
('54:48', 87, 'በእሳት ውስጥ በፊቶቻቸው በሚጎተቱበት ቀን «የሰቀርን መንካት ቅመሱ» (ይባላሉ)፡፡'),
('54:49', 87, 'እኛ ሁሉን ነገር በልክ ፈጠርነው፡፡'),
('54:50', 87, 'ትእዛዛችንም እንደ ዓይን ቅጽበት አንዲት (ቃል) እንጅ ሌላ አይደለም፡፡'),
('54:51', 87, 'ብጤዎቻችሁንም በእርግጥ አጠፋን፡፡ ተገሳጭም አልለን?'),
('54:52', 87, 'የሠሩትም ነገር ሁሉ በመጽሐፎች ውስጥ ነው፡፡'),
('54:53', 87, 'ትንሹም ትልቁም ሁሉ የተጻፈ ነው፡፡'),
('54:54', 87, 'አላህን ፈሪዎቹ በአትክልቶችና በወንዞች ውስጥ ናቸው፡፡'),
('54:55', 87, '(እነርሱም ውድቅ ቃልና መውወንጀል በሌለበት) በእውነት መቀመጫ ውስጥ ቻይ የሆነው ንጉሥ ዘንድ ናቸው፡፡'),
('55:1', 87, 'አል-ረሕማን፤'),
('55:2', 87, 'ቁርኣንን አስተማረ፡፡'),
('55:3', 87, 'ሰውን ፈጠረ፡፡'),
('55:4', 87, 'መናገርን አስተማረው፡፡'),
('55:5', 87, 'ፀሐይና ጨረቃ በተወሰነ ልክ (ይኼዳሉ)፡፡'),
('55:6', 87, 'ሐረግና ዛፍም (ለእርሱ) ይሰግዳሉ፡፡'),
('55:7', 87, 'ሰማይንም አጓናት፡፡ ትክክለኛነትንም ደነገገ፡፡'),
('55:8', 87, 'በሚዛን (ስትመዝኑ) እንዳትበድሉ፡፡'),
('55:9', 87, 'መመዘንንም በትክክል መዝኑ፡፡ ተመዛኙንም አታጉድሉ፡፡'),
('55:10', 87, 'ምድርንም ለፍጡሩ አደላደላት፡፡'),
('55:11', 87, 'በውስጧ እሸት ባለ ሺፋኖች የኾኑ ዘንባባዎችም ያሉባት ስትኾን፡፡'),
('55:12', 87, 'የገለባ ባለቤት የኾነ ቅንጣትም፡፡ ባለ መልካም መዐዛ ቅጠሎችም (ያሉባት ስትኾን)፡፡'),
('55:13', 87, '(ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁም ጸጋዎች በየትኛው ታስተባብላላችሁ?'),
